    ["person:elder-runetotem"] = {title="Ancestro Tótem de Runa",kind="Personaje",aliases={"Ancestro Tótem de Runa"},body="Ancestro Tótem de Runa recibe homenajes durante el Festival Lunar en Durotar. Reconoce la vitalidad espiritual de los jóvenes que se acercan y corresponde a su respeto con una muestra del vínculo entre las generaciones.",aliasQuestIDs={},en={title="Elder Runetotem",aliases={"Elder Runetotem","Runetotem"},body="Elder Runetotem receives homage during the Lunar Festival in Durotar. This elder recognizes the spiritual vitality of young visitors and responds to their respect with a token of the bond between generations.",aliasQuestIDs={}},fr={title="Elder Runetotem",body="Elder Runetotem reçoit un hommage lors de la Lunar Festival dans Durotar. Cet ancien reconnaît la vitalité spirituelle des jeunes visiteurs et répond à leur respect par un signe du lien entre les générations."},de={title="Elder Runetotem",body="Elder Runetotem erhält Ehrung während des Lunar Festival in Durotar. Dieser Älteste erkennt die spirituelle Vitalität der jungen Besucher und reagiert auf ihren Respekt mit einem Zeichen der Verbundenheit zwischen den Generationen."},pt={title="Elder Runetotem",body="Elder Runetotem recebe homenagem durante o Lunar Festival em Durotar. Este ancião reconhece a vitalidade espiritual dos jovens visitantes e responde ao seu respeito com um símbolo do vínculo entre gerações."},pl={title="Elder Runetotem",body="Elder Runetotem przyjmuje hołd podczas Lunar Festival w Durotar. Dostrzega duchową żywotność młodych przybyszów i odpowiada na ich szacunek pamiątką więzi między pokoleniami."},ru={title="Elder Runetotem",body="Elder Runetotem получает дань уважения во время Lunar Festival в Durotar. Этот старейшина признает духовную жизненную силу молодых гостей и в ответ на их уважение дает знак связи между поколениями."},references={["event:lunar-festival"]=true,["place:durotar"]=true},questIDs={[8670]=true}},
    ["person:elder-skygleam"] = {title="Ancestro Relucielo",kind="Personaje",aliases={"Ancestro Relucielo"},body="Ancestro Relucielo recibe el homenaje de los visitantes del Festival Lunar en Azshara. Su enseñanza recuerda que los cielos y sus innumerables estrellas pueden ofrecer respuestas a los misterios del mundo a quienes saben buscar la verdad.",aliasQuestIDs={},en={title="Elder Skygleam",aliases={"Elder Skygleam","Skygleam"},body="Elder Skygleam receives visitors’ homage during the Lunar Festival in Azshara. This elder teaches that the heavens and their countless stars may offer answers to earthly mysteries for those seeking truth.",aliasQuestIDs={}},fr={title="Elder Skygleam",body="Elder Skygleam reçoit les hommages des visiteurs lors de la Lunar Festival en Azshara. Cet ancien enseigne que les cieux et leurs innombrables étoiles peuvent offrir des réponses aux mystères terrestres pour ceux qui cherchent la vérité."},de={title="Elder Skygleam",body="Elder Skygleam erhält die Ehrung der Besucher während des Lunar Festival in Azshara. Dieser Älteste lehrt, dass der Himmel und seine zahllosen Sterne den Wahrheitssuchenden Menschen Antworten auf irdische Geheimnisse bieten können."},pt={title="Elder Skygleam",body="Elder Skygleam recebe homenagem dos visitantes durante o Lunar Festival em Azshara. Este ancião ensina que os céus e suas incontáveis estrelas podem oferecer respostas aos mistérios terrenos para aqueles que buscam a verdade."},pl={title="Elder Skygleam",body="Elder Skygleam przyjmuje hołd odwiedzających podczas Lunar Festival w regionie Azshara. Naucza, że niebo i jego niezliczone gwiazdy mogą przynieść poszukującym prawdy odpowiedzi na ziemskie tajemnice."},ru={title="Elder Skygleam",body="Elder Skygleam принимает посетителей во время Lunar Festival в Azshara. Этот старейшина учит, что небеса и их бесчисленные звезды могут дать ответы на земные тайны для тех, кто ищет истину."},references={["event:lunar-festival"]=true},questIDs={[8720]=true}},
    ["person:elder-skyseer"] = {title="Ancestro Vidente del Cielo",kind="Personaje",aliases={"Ancestro Vidente del Cielo"},body="Ancestro Vidente del Cielo recibe homenajes durante el Festival Lunar en Las Mil Agujas. Reconoce la vitalidad espiritual de los jóvenes que se acercan y corresponde a su respeto con una muestra del vínculo entre las generaciones.",aliasQuestIDs={},en={title="Elder Skyseer",aliases={"Elder Skyseer","Skyseer"},body="Elder Skyseer receives homage during the Lunar Festival in Thousand Needles. This elder recognizes the spiritual vitality of young visitors and responds to their respect with a token of the bond between generations.",aliasQuestIDs={}},fr={title="Elder Skyseer",body="Elder Skyseer reçoit un hommage lors de la Lunar Festival dans Thousand Needles. Cet ancien reconnaît la vitalité spirituelle des jeunes visiteurs et répond à leur respect par un signe du lien entre les générations."},de={title="Elder Skyseer",body="Elder Skyseer erhält Ehrung während des Lunar Festival in Thousand Needles. Dieser Älteste erkennt die spirituelle Vitalität der jungen Besucher und reagiert auf ihren Respekt mit einem Zeichen der Verbundenheit zwischen den Generationen."},pt={title="Elder Skyseer",body="Elder Skyseer recebe homenagem durante o Lunar Festival em Thousand Needles. Este ancião reconhece a vitalidade espiritual dos jovens visitantes e responde ao seu respeito com um símbolo do vínculo entre gerações."},pl={title="Elder Skyseer",body="Elder Skyseer przyjmuje hołd podczas Lunar Festival w Thousand Needles. Dostrzega duchową żywotność młodych przybyszów i odpowiada na ich szacunek pamiątką więzi między pokoleniami."},ru={title="Elder Skyseer",body="Elder Skyseer получает дань уважения во время Lunar Festival в Thousand Needles. Этот старейшина признает духовную жизненную силу молодых гостей и в ответ на их уважение дает знак связи между поколениями."},references={["event:lunar-festival"]=true,["place:thousand-needles"]=true},questIDs={[8682]=t