    ["person:elder-wildmane"] = {title="Ancestro Ferocrín",kind="Personaje",aliases={"Ancestro Ferocrín"},body="Ancestro Ferocrín recibe homenajes durante el Festival Lunar en Zul'Farrak. Reconoce la vitalidad espiritual de los jóvenes que se acercan y corresponde a su respeto con una muestra del vínculo entre las generaciones.",aliasQuestIDs={},en={title="Elder Wildmane",aliases={"Elder Wildmane","Wildmane"},body="Elder Wildmane receives homage during the Lunar Festival in Zul'Farrak. This elder recognizes the spiritual vitality of young visitors and responds to their respect with a token of the bond between generations.",aliasQuestIDs={}},fr={title="Elder Wildmane",body="Elder Wildmane reçoit un hommage lors de la Lunar Festival dans Zul'Farrak. Cet ancien reconnaît la vitalité spirituelle des jeunes visiteurs et répond à leur respect par un signe du lien entre les générations."},de={title="Elder Wildmane",body="Elder Wildmane erhält Ehrung während des Lunar Festival in Zul'Farrak. Dieser Älteste erkennt die spirituelle Vitalität der jungen Besucher und reagiert auf ihren Respekt mit einem Zeichen der Verbundenheit zwischen den Generationen."},pt={title="Elder Wildmane",body="Elder Wildmane recebe homenagem durante o Lunar Festival em Zul'Farrak. Este ancião reconhece a vitalidade espiritual dos jovens visitantes e responde ao seu respeito com um símbolo do vínculo entre gerações."},pl={title="Elder Wildmane",body="Elder Wildmane przyjmuje hołd podczas Lunar Festival w Zul'Farrak. Dostrzega duchową żywotność młodych przybyszów i odpowiada na ich szacunek pamiątką więzi między pokoleniami."},ru={title="Elder Wildmane",body="Elder Wildmane получает дань уважения во время Lunar Festival в Zul'Farrak. Этот старейшина признает духовную жизненную силу молодых гостей и в ответ на их уважение дает знак связи между поколениями."},references={["event:lunar-festival"]=true,["place:zulfarrak"]=true},questIDs={[8676]=true}},
    ["person:elder-windtotem"] = {title="Ancestro Tótem de Viento",kind="Personaje",aliases={"Ancestro Tótem de Viento"},body="Ancestro Tótem de Viento recibe homenajes durante el Festival Lunar en Los Baldíos. Reconoce la vitalidad espiritual de los jóvenes que se acercan y corresponde a su respeto con una muestra del vínculo entre las generaciones.",aliasQuestIDs={},en={title="Elder Windtotem",aliases={"Elder Windtotem","Windtotem"},body="Elder Windtotem receives homage during the Lunar Festival in The Barrens. This elder recognizes the spiritual vitality of young visitors and responds to their respect with a token of the bond between generations.",aliasQuestIDs={}},fr={title="Elder Windtotem",body="Elder Windtotem reçoit un hommage lors de la Lunar Festival dans The Barrens. Cet ancien reconnaît la vitalité spirituelle des jeunes visiteurs et répond à leur respect par un signe du lien entre les générations."},de={title="Elder Windtotem",body="Elder Windtotem erhält Ehrung während des Lunar Festival in The Barrens. Dieser Älteste erkennt die spirituelle Vitalität der jungen Besucher und reagiert auf ihren Respekt mit einem Zeichen der Verbundenheit zwischen den Generationen."},pt={title="Elder Windtotem",body="Elder Windtotem recebe homenagem durante o Lunar Festival em The Barrens. Este ancião reconhece a vitalidade espiritual dos jovens visitantes e responde ao seu respeito com um símbolo do vínculo entre gerações."},pl={title="Elder Windtotem",body="Elder Windtotem przyjmuje hołd podczas Lunar Festival w The Barrens. Dostrzega duchową żywotność młodych przybyszów i odpowiada na ich szacunek pamiątką więzi między pokoleniami."},ru={title="Elder Windtotem",body="Elder Windtotem получает дань уважения во время Lunar Festival в The Barrens. Этот старейшина признает духовную жизненную силу молодых гостей и в ответ на их уважение дает знак связи между поколениями."},references={["event:lunar-festival"]=true,["place:the-barrens"]=true},questIDs={[8680]=true}},
    ["person:elegael-thornpaw"] = {title="Elegael Zarzaspina",kind="Personaje",aliases={"Elegael","Elegael Zarzaspina"},body="Elegael Zarzaspina es un druida del Bosque Ventarrosombra relacionado con un cónclave de la Guarida Garra Nocturna. Su conocimiento de los recursos del bosque incluye el uso de mohos y preparados para atender heridas.",aliasQuestIDs={},en={title="Elegael Thornpaw",aliases={"Elegael","Elegael Thornpaw"},body="Elegael Thornpaw is a druid in Shadowgale Forest associated with a conclave in Nightclaw Den. His knowledge of forest resources includes using molds and preparations to treat wounds.",aliasQuestIDs={}},fr={title="Elegael Thornpaw",body="Elegael Thornpaw est un druide dans la forêt Shadowgale associé à un conclave dans Nightclaw Den. Sa connaissance des ressources forestières comprend l’utilisation de moisissures et de préparations pour traiter les plaies."},de={title="Elegael Thornpaw",body="Elegael Thornpaw ist Druide in Shadowgale Forest, verbunden mit einem Konklave in Nightclaw Den. Zu seinen Kenntnissen der Waldressourcen gehört der Einsatz von Schimmelpilzen und Präparaten zur Wundbehandlung."},pt={title="Elegael Thornpaw",body="Elegael Thornpaw é um druida na Floresta Shadowgale associado a um conclave no Nightclaw Den. Seu conhecimento dos recursos florestais inclui o uso de moldes e preparações para tratar feridas."},pl={title="Elegael Thornpaw",body="Elegael Thornpaw jest druidem w lesie Shadowgale związanym z konklawe w legowisku Nightclaw. Jego wiedza o zasobach lasu obejmuje stosowanie pleśni i preparatów do leczenia ran."},ru={title="Elegael Thornpaw",body="Elegael Thornpaw - друид в лесу Shadowgale, связанный с конклавом в зоне Nightclaw. Его знания лесных ресурсов включают использование форм и препаратов для лечения ран."},references={}},
    ["person:emberstrife"] = {title="Brasaliza",kind="Personaje",aliases={"Brasaliza"},body="Brasaliza es un draco antiguo del Marjal Revolcafango al servicio de Nefarian. Su responsabilidad consiste en someter a prueba a los dragauros que aspiran a ocupar un puesto entre los guardias de élite de Onyxia.",aliasQuestIDs={},en={title="Emberstrife",aliases={"Emberstrife"},body="Emberstrife is an ancient drake in Dustwallow Marsh serving Nefarian. His responsibility is to test dragonspawn aspiring to a place among Onyxia’s elite guards.",aliasQuestIDs={}},fr={title="Emberstrife",body="Emberstrife est un ancien drake en Dustwallow Marsh desservant Nefarian. Sa responsabilité est de tester Dragonspawn aspirant à une place parmi les gardes d'élite de Onyxia."},de={title="Emberstrife",body="Emberstrife ist ein uralter Erpel in Dustwallow Marsh, der Nefarian dient. Seine Aufgabe ist es, den Drachenspawn zu testen, der sich um einen Platz in der Elitegarde von Onyxia 's anstrebt."},pt={title="Emberstrife",body="Emberstrife é um drake antigo em Dustwallow Marsh servindo Nefarian. Sua responsabilidade é testar a dragonspawn aspirando a um lugar entre os guardas de elite da Onyxia."},pl={title="Emberstrife",body="Emberstrife jest pradawnym smokiem w Dustwallow Marsh służącym postaci Nefarian. Odpowiada za sprawdzanie smokowców aspirujących do miejsca wśród elitarnych strażników smoczycy Onyxia."},ru={title="Emberstrife",body="Emberstrife - древний драки в Dustwallow Marsh, обслуживающий Nefarian. Его обязанность - испытать потомство драконов, стремящихся к месту среди элитных охранников Onyxia."},references={["npc:nefarian"]=true,["npc:onyxia"]=true,["place:dustwallow-marsh"]=true}},
    ["person:eralya-leafshadow"] = {title="Eralya Sombra de Hoja",kind="Personaje",aliases={"Eralya","Eralya Sombra de Hoja"},body="Eralya Sombra de Hoja es una centinela en formación de Teldrassil. Forma parte de la red de corredores encargados de llevar los mensajes del Árbol del Oráculo a los ancianos de su pueblo.",aliasQuestIDs={},en={title="Eralya Leafshadow",aliases={"Eralya","Eralya Leafshadow"},body="Eralya Leafshadow is a sentinel in training in Teldrassil. She belongs to the network of runners charged with carrying the Oracle Tree’s messages to her people’s elders.",aliasQuestIDs={}},fr={title="Eralya Leafshadow",body="Eralya Leafshadow est une sentinelle en formation en Teldrassil. Elle appartient au réseau des coureurs chargés de porter les messages de la Oracle Tree aux aînés de son peuple."},de={title="Eralya Leafshadow",body="Eralya Leafshadow ist Wache in der Ausbildung bei Teldrassil. Sie gehört zu dem Netzwerk von Läufern, die beauftragt sind, die Botschaften der Oracle Tree zu den Ältesten ihres Volkes zu tragen."},pt={title="Eralya Leafshadow",body="Eralya Leafshadow é uma sentinela em treinamento em Teldrassil. Ela pertence à rede de corredores encarregados de levar as mensagens do Oracle Tree aos anciãos de seu povo."},pl={title="Eralya Leafshadow",body="Eralya Leafshadow jest szkolącą się strażniczką w Teldrassil. Należy do sieci gończyń odpowiedzialnych za dostarczanie wiadomości Oracle Tree starszyźnie swojego ludu."},ru={title="Eralya Leafshadow",body="Eralya Leafshadow - это страж, который тренируется в Teldrassil. Она принадлежит к сети бегунов, отвечающих за передачу сообщений Oracle Tree  старшим ее народа."},references={["place:oracle-tree"]=true,["place:teldrassil"]=true}},
    ["person:eranikus"] = {title="Eranikus",kind="Personaje",aliases={"Eranikus"},body="Eranikus es un dragón del Vuelo Verde vinculado al Sueño y a la vigilancia del Templo de Atal'Hakkar. Su cometido es impedir que los trols vuelvan a invocar a su dios, una responsabilidad que lo enfrenta a poderes capaces de amenazar incluso a los guardianes del Sueño.",aliasQuestIDs={},en={title="Eranikus",aliases={"Eranikus"},body="Eranikus is a Green Dragonflight dragon tied to the Dream and the watch over the Temple of Atal'Hakkar. His charge is to prevent the trolls from summoning their god again, a responsibility pitting him against powers capable of threatening even the Dream’s guardians.",aliasQuestIDs={}},fr={title="Eranikus",body="Eranikus est un dragon Green Dragonflight attaché au Rêve et à la veille sur le Temple of Atal'Hakkar. Sa charge est d'empêcher les trolls d'invoquer à nouveau leur dieu, une responsabilité qui l'oppose à des pouvoirs capables de menacer même les gardiens du Rêve."},de={title="Eranikus",body="Eranikus ist ein Green Dragonflight-Drache, der an den Traum und die Wache über den Temple of Atal'Hakkar gebunden ist. Seine Aufgabe besteht darin, die Trolle daran zu hindern, ihren Gott erneut zu rufen, eine Verantwortung zu übernehmen, die ihn gegen Mächte auszuspielen, die sogar die sogar die Hüter des Traums bedrohen können."},pt={title="Eranikus",body="Eranikus é um dragão Green Dragonflight amarrado ao sonho e o relógio sobre o Temple of Atal'Hakkar. Sua acusação é evitar que os trolls invoquem seu deus novamente, uma responsabilidade que o coloca contra poderes capazes de ameaçar até mesmo os guardiões do Sonho."},pl={title="Eranikus",body="Eranikus jest smokiem Green Dragonflight związanym ze Snem i strażą nad Temple of Atal'Hakkar. Ma uniemożliwiać trollom ponowne przywołanie boga, co stawia go przeciw potęgom zdolnym zagrozić nawet strażnikom Snu."},ru={title="Eranikus",body="Eranikus - это Green Dragonflight дракон, связанный с Мечтой и наблюдающий за Temple of Atal'Hakkar. Его задача - помешать троллям снова призвать своего бога, ответственность ставит его против сил, способных угрожать даже стражам Сновидения."},references={["organization:green-dragonflight"]=true,["place:temple-of-atal-hakkar"]=true}},
    ["person:erelas-ambersky"] = {title="Erelas Cieloámbar",kind="Personaje",aliases={"Erelas","Erelas Cieloámbar"},body="Erelas Cieloámbar estudia criaturas y tradiciones religiosas desde la Aldea Rut'theran. Sus investigaciones sobre los lechúcicos salvajes buscan comprender tanto su naturaleza como su posible relación con Elune.",aliasQuestIDs={},en={title="Erelas Ambersky",aliases={"Erelas","Erelas Ambersky"},body="Erelas Ambersky studies creatures and religious traditions from Rut'theran Village. His research on wildkin seeks to understand both their nature and their possible relationship with Elune.",aliasQuestIDs={}},fr={title="Erelas Ambersky",body="Erelas Ambersky étudie les créatures et les traditions religieuses de Rut'theran Village. Ses recherches sur le wildkin cherchent à comprendre à la fois leur nature et leur relation possible avec Elune."},de={title="Erelas Ambersky",body="Erelas Ambersky studiert Lebewesen und religiöse Traditionen von Rut'theran Village. Seine Forschungen über Wildkin versuchen, sowohl ihr Wesen als auch ihre mögliche Beziehung zu Elune zu verstehen."},pt={title="Erelas Ambersky",body="Erelas Ambersky estuda criaturas e tradições religiosas de Rut'theran Village. Sua pesquisa sobre wildkin busca entender tanto sua natureza quanto sua possível relação com o Elune."},pl={title="Erelas Ambersky",body="Erelas Ambersky bada stworzenia i tradycje religijne, działając z Rut'theran Village. Badania stworzeń wildkin służą zrozumieniu zarówno ich natury, jak i możliwego związku z boginią Elune."},ru={title="Erelas Ambersky",body="Erelas Ambersky изучает существ и религиозные традиции из Rut'theran Village. Его исследования диких людей направлены на понимание их природы и возможной связи с Elune."},references={["npc:elune"]=true,["place:ruttheran-village"]=true}},
    ["person:eridan-bluewind"] = {title="Eridan Vientoazul",kind="Personaje",aliases={"Eridan","Eridan Vientoazul"},body="Eridan Vientoazul vive en Frondavil y posee conocimientos de magia capaces de responder a poderes elementales. Su experiencia vincula los recursos del bosque con la preparación de objetos de gran fuerza.",aliasQuestIDs={},en={title="Eridan Bluewind",aliases={"Eridan","Eridan Bluewind"},body="Eridan Bluewind lives in Felwood and possesses magical knowledge capable of answering elemental powers. Her expertise connects the forest’s resources with the preparation of powerful objects.",aliasQuestIDs={}},fr={title="Eridan Bluewind",body="Eridan Bluewind vit dans Felwood et possède des connaissances magiques capables de répondre aux pouvoirs élémentaires. Son expertise relie les ressources de la forêt à la préparation d’objets puissants."},de={title="Eridan Bluewind",body="Eridan Bluewind lebt in Felwood und besitzt magisches Wissen, das in der Lage ist, elementare Kräfte zu beantworten. Ihre Expertise verbindet die Ressourcen des Waldes Waldes mit der Vorbereitung mächtiger Objekte."},pt={title="Eridan Bluewind",body="Eridan Bluewind vive em Felwood e possui conhecimento mágico capaz de responder a poderes elementares. Sua experiência conecta os recursos da floresta com a preparação de objetos poderosos."},pl={title="Eridan Bluewind",body="Eridan Bluewind mieszka w Felwood i posiada wiedzę magiczną pozwalającą odpowiadać na moce żywiołów. Jej umiejętności łączą zasoby lasu z przygotowaniem potężnych przedmiotów."},ru={title="Eridan Bluewind",body="Eridan Bluewind живет в Felwood и обладает магическими знаниями, способными отвечать на элементарные силы. Ее опыт связывает ресурсы леса с изготовлением мощных объектов."},references={["place:felwood"]=true}},
    ["person:erion-shadewhisper"] = {title="Erion Sombrusurro",kind="Personaje",aliases={"Erion","Erion Sombrusurro"},body="Erion actúa en el Enclave Cenarion y mantiene vínculos con los servicios de inteligencia de Ventormenta. Orienta a los pícaros que están preparados para ampliar su formación y conocer oportunidades más allá de su tierra natal.",aliasQuestIDs={},en={title="Erion Shadewhisper",aliases={"Erion","Erion Shadewhisper"},body="Erion operates in the Cenarion Enclave and maintains links with Stormwind’s intelligence services. He guides rogues ready to broaden their training and discover opportunities beyond their homeland.",aliasQuestIDs={}},fr={title="Erion Shadewhisper",body="Erion opère dans le Cenarion Enclave et entretient des liens avec les services de renseignement de Stormwind. Il guide des voyous prêts à élargir leur formation et à découvrir des opportunités au-delà de leur patrie."},de={title="Erion Shadewhisper",body="Erion arbeitet im Cenarion Enclave und unterhält Verbindungen zu Stormwind \"Nachrichtendiensten. Er leitet Schurken an, die bereit sind, ihre Ausbildung zu erweitern und Chancen jenseits ihrer Heimat zu entdecken."},pt={title="Erion Shadewhisper",body="A Erion opera no Cenarion Enclave e mantém ligações com os serviços de inteligência da Stormwind. Ele guia bandidos prontos para ampliar seu treinamento e descobrir oportunidades além de sua terra natal."},pl={title="Erion Shadewhisper",body="Erion działa w Cenarion Enclave i utrzymuje więzi ze służbami wywiadowczymi Stormwind. Prowadzi łotrzyków gotowych poszerzyć szkolenie i odkrywać możliwości poza ojczyzną."},ru={title="Erion Shadewhisper",body="Erion работает в Cenarion Enclave и поддерживает связи с разведывательными службами Stormwind. Он направляет негодяев, готовых расширить свое обучение и открыть возможности за пределами своей родины."},references={["place:stormwind"]=true}},
    ["person:eyahn-eagletalon"] = {title="Eyahn Garra de Águila",kind="Personaje",aliases={"Eyahn","Eyahn Garra de Águila"},body="Eyahn Garra de Águila prepara un penacho para la ceremonia en la que su hermano se presentará ante el jefe Pezuña de Sangre. Su trabajo con cuero y plumas expresa el deber familiar y el orgullo que acompañan ese momento de la vida tauren.",aliasQuestIDs={},en={title="Eyahn Eagletalon",aliases={"Eyahn","Eyahn Eagletalon"},body="Eyahn Eagletalon prepares a headdress for the ceremony in which his brother will stand before Chief Bloodhoof. His leatherwork and featherwork express the family duty and pride accompanying that moment in tauren life.",aliasQuestIDs={}},fr={title="Eyahn Eagletalon",body="Eyahn Eagletalon prépare une coiffe pour la cérémonie au cours de laquelle son frère se tiendra devant le chef Bloodhoof. Sa maroquinerie et ses plumes expriment le devoir familial et la fierté qui accompagnent ce moment de la vie tauren."},de={title="Eyahn Eagletalon",body="Eyahn Eagletalon bereitet einen Kopfschmuck für die Zeremonie vor, bei der sein Bruder vor Häuptling Bloodhoof stehen wird. Seine Leder- und Federarbeiten sind Ausdruck der familiären Pflicht und des Stolzes, die diesen Moment im Taurenleben begleiten."},pt={title="Eyahn Eagletalon",body="Eyahn Eagletalon prepara um cocar para a cerimônia em que seu irmão estará diante do Chefe Bloodhoof. Seu trabalho de couro e penas expressam o dever e o orgulho da família que acompanham esse momento na vida tauren."},pl={title="Eyahn Eagletalon",body="Eyahn Eagletalon przygotowuje nakrycie głowy na ceremonię, podczas której brat stanie przed wodzem Bloodhoof. Obróbka skóry i piór wyraża rodzinny obowiązek oraz dumę towarzyszące tej chwili taurenskiego życia."},ru={title="Eyahn Eagletalon",body="Eyahn Eagletalon готовит головной убор для церемонии, в которой его брат предстанет перед начальником Bloodhoof. Его кожаные и перьевые работы выражают семейный долг и гордость, сопровождающие этот момент в жизни быка."},references={}},
    ["person:falfindel-waywarder"] = {title="Díscolo Falfindel",kind="Personaje",aliases={"Díscolo Falfindel","Falfindel"},body="El Díscolo Falfindel es un druida que vive donde Las Mil Agujas se encuentran con los bosques de Feralas. Su sabiduría le permite invocar espíritus del bosque para ayudar a restaurar lugares dañados como La Vega Carbonizada.",aliasQuestIDs={},en={title="Falfindel Waywarder",aliases={"Falfindel","Falfindel Waywarder"},body="Falfindel Waywarder is a druid living where Thousand Needles meets the forests of Feralas. His wisdom allows him to call upon forest spirits to help restore damaged places such as the Charred Vale.",aliasQuestIDs={}},fr={title="Falfindel Waywarder",body="Falfindel Waywarder est un druide vivant où Thousand Needles rencontre les forêts de Feralas. Sa sagesse lui permet de faire appel aux esprits de la forêt pour aider à restaurer des endroits endommagés tels que le Charred Vale."},de={title="Falfindel Waywarder",body="Falfindel Waywarder ist ein Druide, der dort lebt, wo Thousand Needles die Wälder Feralas \"trifft. Seine Weisheit erlaubt es ihm, Waldgeister zu rufen, um bei der Wiederherstellung beschädigter Orte wie der Charred Vale zu helfen."},pt={title="Falfindel Waywarder",body="Falfindel Waywarder é um druida que vive onde Thousand Needles encontra as florestas de Feralas. Sua sabedoria lhe permite invocar espíritos da floresta para ajudar a restaurar lugares danificados, como o Charred Vale."},pl={title="Falfindel Waywarder",body="Falfindel Waywarder jest druidem mieszkającym tam, gdzie Thousand Needles spotyka lasy Feralas. Mądrość pozwala mu wzywać leśne duchy pomagające odnawiać zniszczone miejsca takie jak Charred Vale."},ru={title="Falfindel Waywarder",body="Falfindel Waywarder - это друид, живущий там, где Thousand Needles встречается с лесами Feralas. Его мудрость позволяет ему призвать лесных духов, чтобы помочь восстановить поврежденные места, такие как Charred Vale."},references={["place:charred-vale"]=true,["place:feralas"]=true,["place:thousand-needles"]=true}},
    ["person:falrin-treeshaper"] = {title="Falrin Tallarbol",kind="Personaje",aliases={"Falrin","Falrin Tallarbol"},body="Falrin Tallarbol se encuentra en la biblioteca de La Masacre y conoce encantamientos capaces de provocar a una persona mediante un estandarte. Mantiene una profunda hostilidad hacia los ogros, tanto los seguidores de Omokk como los del rey Gordok.",aliasQuestIDs={},en={title="Falrin Treeshaper",aliases={"Falrin","Falrin Treeshaper"},body="Falrin Treeshaper is found in Dire Maul’s library and knows enchantments capable of provoking someone through a banner. He holds a deep hostility toward ogres, both Omokk’s followers and those serving King Gordok.",aliasQuestIDs={}},fr={title="Falrin Treeshaper",body="Falrin Treeshaper se trouve dans la bibliothèque de Dire Maul et connaît des enchantements capables de provoquer quelqu'un à travers une bannière. Il est profondément hostile aux ogres, à la fois aux partisans de Omokk et à ceux qui servent le roi Gordok."},de={title="Falrin Treeshaper",body="Falrin Treeshaper befindet sich in der Bibliothek von Dire Maul und kennt Verzauberungen, die jemanden durch ein Banner provozieren können. Er hegt eine tiefe Feindseligkeit gegenüber den Ogläubigen, sowohl den Anhängern von Omokk als auch denen von König Gordok."},pt={title="Falrin Treeshaper",body="O Falrin Treeshaper é encontrado na biblioteca do Dire Maul e conhece encantamentos capazes de provocar alguém através de um banner. Ele mantém uma profunda hostilidade contra ogros, tanto os seguidores de Omokk e aqueles que servem o rei Gordok."},pl={title="Falrin Treeshaper",body="Falrin Treeshaper przebywa w bibliotece Dire Maul i zna zaklęcia pozwalające sprowokować kogoś za pomocą sztandaru. Żywi głęboką wrogość wobec ogrów, zarówno zwolenników Omokk, jak i tych służących królowi Gordok."},ru={title="Falrin Treeshaper",body="Falrin Treeshaper находится в библиотеке Dire Maul  и знает заклинания, способные спровоцировать кого-то через баннер. Он питает глубокую враждебность к великанам, как последователям Omokk, так и тем, кто служит королю Gordok."},references={["organization:gordok"]=true,["place:dire-maul"]=true}},
    ["person:fandral-staghelm"] = {title="Fandral Corzocelada",kind="Personaje",aliases={"Fandral","Fandral Corzocelada"},body="Fandral Corzocelada es un archidruida de Darnassus. Su posición en el Enclave Cenarion lo vincula a la formación de druidas y a la investigación de los problemas que afectan a Teldrassil.",aliasQuestIDs={},en={title="Fandral Staghelm",aliases={"Fandral","Fandral Staghelm"},body="Fandral Staghelm is an archdruid in Darnassus. His position in the Cenarion Enclave connects him to druid training and investigation of the problems affecting Teldrassil.",aliasQuestIDs={}},fr={title="Fandral Staghelm",body="Fandral Staghelm est un archidruide dans Darnassus. Sa position dans le Cenarion Enclave le relie à la formation et à l'investigation druides des problèmes affectant Teldrassil."},de={title="Fandral Staghelm",body="Fandral Staghelm ist ein Erzdruide in Darnassus. Seine Position im Cenarion Enclave verbindet ihn mit dem Druidentraining und der Untersuchung der Probleme, die Teldrassil betreffen."},pt={title="Fandral Staghelm",body="Fandral Staghelm é um archdruid em Darnassus. Sua posição no Cenarion Enclave o conecta ao treinamento de druidas e à investigação dos problemas que afetam o Teldrassil."},pl={title="Fandral Staghelm",body="Fandral Staghelm jest arcydruidem w Darnassus. Pozycja w Cenarion Enclave wiąże go ze szkoleniem druidów oraz badaniem problemów dotykających Teldrassil."},ru={title="Fandral Staghelm",body="Fandral Staghelm - это архдруид в Darnassus. Его должность в Cenarion Enclave связывает его с тренировкой друидов и расследованием проблем, затрагивающих Teldrassil."},references={["place:darnassus"]=true,["place:teldrassil"]=true}},
    ["person:fariel-starsong"] = {title="Fariel Cantostelar",kind="Personaje",aliases={"Fariel","Fariel Cantostelar"},body="Fariel Cantostelar recibe a los visitantes del Festival Lunar en el Amparo de la Noche junto con su hermano Valadar. Reúne monedas de linaje y participa en los premios de una celebración que abre el poblado a viajeros de todo Azeroth.",aliasQuestIDs={},en={title="Fariel Starsong",aliases={"Fariel","Fariel Starsong"},body="Fariel Starsong welcomes Lunar Festival visitors to Nighthaven alongside her brother Valadar. She collects Coins of Ancestry and takes part in the rewards of a celebration opening the village to travelers from across Azeroth.",aliasQuestIDs={}},fr={title="Fariel Starsong",body="Fariel Starsong accueille les visiteurs Lunar Festival à Nighthaven aux côtés de son frère Valadar. Elle collecte Coins of Ancestry et participe aux récompenses d'une célébration ouvrant le village aux voyageurs de Azeroth."},de={title="Fariel Starsong",body="Fariel Starsong begrüßt Lunar Festival zusammen mit ihrem Bruder Valadar zu Nighthaven. Sie sammelt Coins of Ancestry ein und nimmt an einer Feier teil, die das Dorf für Reisende aus ganz Azeroth öffnet."},pt={title="Fariel Starsong",body="Fariel Starsong recebe visitantes do Lunar Festival em Nighthaven, ao lado de seu irmão Valadar. Ela coleta Coins of Ancestry e participa da premiação de uma celebração que abre o vilarejo a viajantes de toda Azeroth."},pl={title="Fariel Starsong",body="Fariel Starsong wraz z bratem Valadar wita gości Lunar Festival w Nighthaven. Zbiera Coins of Ancestry i uczestniczy w rozdawaniu nagród podczas święta otwierającego wioskę dla podróżnych z całego Azeroth."},ru={title="Fariel Starsong",body="Fariel Starsong приветствует посетителей Lunar Festival в Nighthaven вместе со своим братом Valadar. Она собирает Coins of Ancestry и принимает участие в наградах празднования открытия деревни для путешественников со всех концов Azeroth."},references={["event:lunar-festival"]=true,["npc:valadar-starsong"]=true,["object:coins-of-ancestry"]=true,["place:azeroth"]=true,["place:nighthaven"]=true}},
    ["person:feegly-the-exiled"] = {title="Feegly el Exiliado",kind="Personaje",aliases={"Feegly","Feegly el Exiliado"},body="Feegly el Exiliado participó en las excavaciones de Bael Modan. Su obsesión con el poder de la Lágrima de las Lunas lo enfrenta al general Trenzado, que considera maldito el hallazgo y lo mantiene bajo custodia.",aliasQuestIDs={},en={title="Feegly the Exiled",aliases={"Feegly","Feegly the Exiled"},body="Feegly the Exiled took part in the Bael Modan excavations. His obsession with the Tear of the Moons’ power sets him against General Twinbraid, who considers the discovery cursed and keeps it under guard.",aliasQuestIDs={}},fr={title="Feegly the Exiled",body="Feegly the Exiled a participé aux fouilles Bael Modan. Son obsession pour le pouvoir de la larme des lunes le place contre le général Twinbraid, qui considère la découverte comme maudite et la garde sous surveillance."},de={title="Feegly the Exiled",body="Feegly the Exiled war an den Ausgrabungen von Bael Modan beteiligt. Seine Besessenheit mit der Macht der Monde bringt ihn gegen General Twinbraid auf, der die Waage, der diese Entdeckung, der sie für verflucht hält und bewacht."},pt={title="Feegly the Exiled",body="Feegly the Exiled participou das escavações Bael Modan. Sua obsessão com o poder da Lágrima das Luas o coloca contra o General Twinbraid, que considera a descoberta amaldiçoada e a mantém sob guarda."},pl={title="Feegly the Exiled",body="Feegly the Exiled uczestniczył w wykopaliskach Bael Modan. Obsesja na punkcie mocy łzy księżyców stawia go przeciw generałowi Twinbraid, który uważa odkrycie za przeklęte i trzyma je pod strażą."},ru={title="Feegly the Exiled",body="Feegly the Exiled участвовал в раскопках Bael Modan. Его одержимость силой \"Слёзы Луны\" ставит его против генерала Twinbraid, который считает открытие проклятым и держит его под охраной."},references={}},
    ["person:feero"] = {title="Feero",kind="Personaje",aliases={"Feero"},body="Feero es un mensajero que transporta información y suministros entre Vallefresno y Auberdine. La seguridad de su carga depende de atravesar un bosque en el que grupos hostiles acechan los caminos.",aliasQuestIDs={},en={title="Feero",aliases={"Feero"},body="Feero is a messenger carrying information and supplies between Ashenvale and Auberdine. The safety of his cargo depends on crossing a forest where hostile groups watch the roads.",aliasQuestIDs={}},fr={title="Feero",body="Feero est un messager transportant des informations et des fournitures entre Ashenvale et Auberdine. La sécurité de sa cargaison dépend de la traversée d'une forêt où des groupes hostiles surveillent les routes."},de={title="Feero",body="Feero ist ein Bote, der Informationen und Vorräte zwischen Ashenvale und Auberdine transportiert. Die Sicherheit seiner Ladung hängt davon ab, einen Wald zu überqueren, wo feindliche Gruppen die Straßen überwachen."},pt={title="Feero",body="Feero é um mensageiro que transporta informações e suprimentos entre Ashenvale e Auberdine. A segurança de sua carga depende da travessia de uma floresta onde grupos hostis vigiam as estradas."},pl={title="Feero",body="Feero jest posłańcem przewożącym informacje i zapasy między Ashenvale a Auberdine. Bezpieczeństwo ładunku zależy od pokonania lasu, w którym wrogie grupy obserwują drogi."},ru={title="Feero",body="Feero - это посланник, который несет информацию и припасы между Ashenvale и Auberdine. Безопасность его груза зависит от пересечения леса, где враждебные группы наблюдают за дорогами."},references={["place:ashenvale"]=true,["place:auberdine"]=true}},
    ["person:felgur-twocuts"] = {title="Felgur Doscortes",kind="Personaje",aliases={"Felgur","Felgur Doscortes"},body="Felgur Doscortes reúne información sobre los centauros desde el Campamento del Espíritu Errante en Desolace. Sus observaciones ayudan a la Horda a comprender cómo los conflictos de los clanes se extienden a otras regiones.",aliasQuestIDs={},en={title="Felgur Twocuts",aliases={"Felgur","Felgur Twocuts"},body="Felgur Twocuts gathers information on centaurs from Ghost Walker Post in Desolace. His observations help the Horde understand how clan conflicts spread into other regions.",aliasQuestIDs={}},fr={title="Felgur Twocuts",body="Felgur Twocuts rassemble des informations sur les centaures à partir de Ghost Walker Post dans Desolace. Ses observations aident le Horde à comprendre comment les conflits claniques se propagent dans d'autres régions."},de={title="Felgur Twocuts",body="Felgur Twocuts sammelt Informationen über Zentauren bei der Ghost Walker Post in Desolace. Seine Beobachtungen helfen den Horde zu verstehen, wie sich Clankonflikte in anderen Regionen ausbreiten."},pt={title="Felgur Twocuts",body="Felgur Twocuts reúne informações sobre centauros de Ghost Walker Post em Desolace. Suas observações ajudam o Horde a entender como os conflitos de clãs se espalharam para outras regiões."},pl={title="Felgur Twocuts",body="Felgur Twocuts zbiera informacje o centaurach z Ghost Walker Post w Desolace. Obserwacje pomagają frakcji Horde zrozumieć, jak konflikty klanów rozprzestrzeniają się na inne regiony."},ru={title="Felgur Twocuts",body="Felgur Twocuts собирает информацию о кентаврах из Поста Призрачного Ходока в Desolace. Его наблюдения помогают Horde понять, как конфликты кланов распространяются в другие регионы."},references={["organization:horde"]=true,["place:desolace"]=true}},
    ["person:felnok-steelspring"] = {title="Felnok Acerovera",kind="Personaje",aliases={"Felnok","Felnok Acerovera"},body="Felnok Acerovera fabrica componentes especiales en Vista Eterna. Sus trabajos de ingeniería ayudan a otros investigadores a preparar experimentos con temperaturas y materiales difíciles de manejar.",aliasQuestIDs={},en={title="Felnok Steelspring",aliases={"Felnok","Felnok Steelspring"},body="Felnok Steelspring makes specialized components in Everlook. His engineering helps other researchers prepare experiments involving temperatures and materials that are difficult to handle.",aliasQuestIDs={}},fr={title="Felnok Steelspring",body="Felnok Steelspring fabrique des composants spécialisés dans Everlook. Son ingénierie aide d’autres chercheurs à préparer des expériences impliquant des températures et des matériaux difficiles à manipuler."},de={title="Felnok Steelspring",body="Felnok Steelspring stellt in Everlook spezielle Komponenten her. Sein Ingenieurwesen hilft anderen Forschern, Experimente mit schwer handhabbaren Temperaturen und Materialien vorzubereiten."},pt={title="Felnok Steelspring",body="Felnok Steelspring faz componentes especializados em Everlook. Sua engenharia ajuda outros pesquisadores a preparar experimentos envolvendo temperaturas e materiais difíceis de manusear."},pl={title="Felnok Steelspring",body="Felnok Steelspring wytwarza specjalistyczne części w Everlook. Jego inżynieria pomaga innym badaczom przygotowywać eksperymenty z temperaturami i materiałami trudnymi do opanowania."},ru={title="Felnok Steelspring",body="Felnok Steelspring производит специализированные компоненты в Everlook. Его инженер помогает другим исследователям готовить эксперименты, связанные с температурами и материалами, которые трудно обрабатывать."},references={["place:everlook"]=true}},
    ["person:fillion-flamebreeze"] = {title="Fillion Brisallama",kind="Personaje",aliases={"Fillion","Fillion Brisallama"},body="Fillion Brisallama es un erudito de la Suma Orden dedicado al estudio de la magia transportada por el viento. Su investigación lo vincula con las formaciones de piedra de viento de las Tierras Altas de Shen'dar. Utiliza instrumentos capaces de medir la energía elemental, como el Index Esoteria.",aliasQuestIDs={},en={title="Fillion Flamebreeze",aliases={"Fillion","Fillion Flamebreeze"},body="Fillion Flamebreeze is a High Order scholar who studies windborne magic. His research concerns the windstone formations of the Shen'dar Highlands. He uses instruments capable of measuring elemental energy, including the Index Esoteria.",aliasQuestIDs={}},fr={title="Fillion Flamebreeze",body="Fillion Flamebreeze est un chercheur High Order qui étudie la magie éolienne. Ses recherches portent sur les formations de pierre du vent du Shen'dar Highlands. Il utilise des instruments capables de mesurer l'énergie élémentaire, y compris le Index Esoteria."},de={title="Fillion Flamebreeze",body="Fillion Flamebreeze ist ein High Order-Schüler, der sich mit windgetragener Magie beschäftigt. Seine Forschungen betreffen die Windsteinformationen des Shen'dar Highlands. Er benutzt Instrumente, die in der Lage sind, die Elementare Energie zu messen, einschließlich des Index Esoteria."},pt={title="Fillion Flamebreeze",body="Fillion Flamebreeze é um estudioso de High Order que estuda magia transmitida pelo vento. Sua pesquisa diz respeito às formações de pedra de vento do Shen'dar Highlands. Ele usa instrumentos capazes de medir a energia elementar, incluindo o Index Esoteria."},pl={title="Fillion Flamebreeze",body="Fillion Flamebreeze jest uczonym High Order badającym magię niesioną wiatrem. Zajmuje się formacjami kamieni wiatru w Shen'dar Highlands. Korzysta z instrumentów mierzących energię żywiołów, w tym Index Esoteria."},ru={title="Fillion Flamebreeze",body="Fillion Flamebreeze - это ученый High Order, который изучает волшебство ветра. Его исследования касаются формаций ветровых камней Shen'dar Highlands. Он использует инструменты, способные измерять энергию элементов, включая Index Esoteria."},references={["object:index-esoteria"]=true,["organization:high-order"]=true,["place:shendar"]=true,["place:shendar-highlands"]=true}},
    ["person:fiora-longears"] = {title="Fiora Orejona",kind="Personaje",aliases={"Fiora","Fiora Orejona"},body="Fiora Orejona ayuda a orientar a los viajeros que llegan a Theramore. Su labor forma parte de los contactos que convierten los viajes por mar en una puerta de entrada a Kalimdor.",aliasQuestIDs={},en={title="Fiora Longears",aliases={"Fiora","Fiora Longears"},body="Fiora Longears helps guide travelers arriving in Theramore. Her work is part of the network of contacts that makes sea travel a gateway to Kalimdor.",aliasQuestIDs={}},fr={title="Fiora Longears",body="Fiora Longears aide à guider les voyageurs arrivant à Theramore. Son travail fait partie du réseau de contacts qui fait du voyage en mer une passerelle vers Kalimdor."},de={title="Fiora Longears",body="Fiora Longears hilft Reisenden bei der Ankunft in Theramore. Ihre Arbeit ist Teil eines Netzwerks von Kontakten, das das die Seefahrt zu Kalimdor zu einem Tor macht."},pt={title="Fiora Longears",body="Fiora Longears ajuda a orientar os viajantes que chegam em Theramore. Seu trabalho faz parte da rede de contatos que faz das viagens marítimas uma porta de entrada para o Kalimdor."},pl={title="Fiora Longears",body="Fiora Longears pomaga prowadzić podróżnych przybywających do Theramore. Jej praca należy do sieci kontaktów czyniącej podróż morską bramą do kontynentu Kalimdor."},ru={title="Fiora Longears",body="Fiora Longears помогает вести путешественников, прибывающих в Theramore. Ее работа является частью сети контактов, которая делает морское путешествие воротами к Kalimdor."},references={["place:kalimdor"]=true,["place:theramore"]=true}},
    ["person:fisherman-lindo"] = {title="Pescador Len'do",kind="Personaje",aliases={"Pescador Len'do","Pescador Len’do","pescador Len'do","pescador Len’do"},body="El pescador Len'do aporta sus conocimientos al abastecimiento de la Horda. Su recolección de serviolas moteadas muestra cómo la pesca también sostiene a los ejércitos que se preparan para Ahn'Qiraj.",aliasQuestIDs={},en={title="Fisherman Lin'do",aliases={"Fisherman Lin'do","Fisherman Lin’do","Lin'do","Lin’do"},body="Fisherman Lin'do contributes his knowledge to supplying the Horde. His collection of spotted yellowtail shows how fishing also sustains armies preparing for Ahn'Qiraj.",aliasQuestIDs={}},fr={title="Fisherman Lin'do",body="Fisherman Lin'do apporte ses connaissances à la fourniture du Horde. Sa collection de queue jaune tachetée montre comment la pêche soutient également les armées se préparant pour Ahn'Qiraj."},de={title="Fisherman Lin'do",body="Fisherman Lin'do steuert sein Wissen zur Bereitstellung des Horde bei. Seine Sammlung gefleckter Gelbschwänze zeigt, wie die Fischerei auch Armeen unterstützt, die sich auf Ahn'Qiraj vorbereiten."},pt={title="Fisherman Lin'do",body="Fisherman Lin'do contribui com seu conhecimento para fornecer o Horde. Sua coleção de rabo amarelo manchado mostra como a pesca também sustenta os exércitos que se preparam para o Ahn'Qiraj."},pl={title="Fisherman Lin'do",body="Fisherman Lin'do wnosi wiedzę w zaopatrywanie frakcji Horde. Zbieranie nakrapianych żółtoogonów pokazuje, jak rybołówstwo podtrzymuje także armie przygotowujące się do Ahn'Qiraj."},ru={title="Fisherman Lin'do",body="Fisherman Lin'do вносит свои знания в поставки Horde. Его коллекция пятнистых желтых хвостов показывает, как рыбалка также поддерживает армии, готовящиеся к Ahn'Qiraj."},references={["organization:horde"]=true,["place:ahnqiraj"]=true}},
    ["person:fizzle-darkstorm"] = {title="Fizzle Tormenta Oscura",kind="Personaje",aliases={"Fizzle","Fizzle Tormenta Oscura"},body="Fizzle Tormenta Oscura es un brujo goblin del Filo Ardiente establecido en el Monte del Trueno. Reúne seguidores desde los que el culto extiende su influencia demoníaca por Durotar.",aliasQuestIDs={},en={title="Fizzle Darkstorm",aliases={"Fizzle","Fizzle Darkstorm"},body="Fizzle Darkstorm is a Burning Blade goblin warlock based in Thunder Ridge. He gathers followers through whom the cult spreads its demonic influence in Durotar.",aliasQuestIDs={}},fr={title="Fizzle Darkstorm",body="Fizzle Darkstorm est un démoniste gobelin Burning Blade basé sur Thunder Ridge. Il rassemble des adeptes à travers lesquels le culte répand son influence démoniaque dans Durotar."},de={title="Fizzle Darkstorm",body="Fizzle Darkstorm ist ein Hexenmeister von Burning Blade Goblin aus Thunder Ridge. Er sammelt Anhänger, durch die der Kult seinen dämonischen Einfluss auf Durotar verbreitet."},pt={title="Fizzle Darkstorm",body="Fizzle Darkstorm é um bruxo goblin Burning Blade baseado em Thunder Ridge. Ele reúne seguidores através dos quais o culto espalha sua influência demoníaca no Durotar."},pl={title="Fizzle Darkstorm",body="Fizzle Darkstorm jest goblińskim czarnoksiężnikiem Burning Blade działającym z Thunder Ridge. Gromadzi wyznawców, poprzez których kult szerzy demoniczny wpływ w Durotar."},ru={title="Fizzle Darkstorm",body="Fizzle Darkstorm - это зоопарк-чернокнижник-гоблин Burning Blade, базирующийся в Thunder Ridge. Он собирает последователей через которых культ распространяет свое демоническое влияние в Durotar."},references={["organization:burning-blade"]=true,["place:durotar"]=true,["place:thunder-ridge"]=true},questIDs={[806]=true}},
    ["person:foreman-thazzril"] = {title="Supervisor Thazz'ril",kind="Personaje",aliases={"Supervisor Thazz'ril","Supervisor Thazz’ril","Thazz'ril","Thazz’ril"},body="El supervisor Thazz'ril dirige peones y explora posibles fuentes de minerales. Su pico favorito está encantado para verse en la oscuridad, una herramienta útil para las cavernas donde busca nuevos lugares de excavación.",aliasQuestIDs={},en={title="Foreman Thazz'ril",aliases={"Foreman Thazz'ril","Foreman Thazz’ril","Thazz'ril","Thazz’ril"},body="Foreman Thazz'ril supervises peons and surveys possible mineral sources. His favorite pick is enchanted to be visible in darkness, a useful tool in the caves where he seeks new mining sites.",aliasQuestIDs={}},fr={title="Foreman Thazz'ril",body="Foreman Thazz'ril supervise les petits et étudie les sources minérales possibles. Son choix préféré est enchanté d'être visible dans l'obscurité, un outil utile dans les grottes où il cherche de nouveaux sites miniers."},de={title="Foreman Thazz'ril",body="Foreman Thazz'ril überwacht die Pfingstrosen und untersucht mögliche Mineralquellen. Seine Lieblingspflanze ist es, in der Dunkelheit sichtbar zu sein, ein nützliches Werkzeug in den Höhlen zu sein, wo er nach neuen Minen sucht."},pt={title="Foreman Thazz'ril",body="Foreman Thazz'ril supervisiona peões e pesquisa possíveis fontes minerais. Sua escolha favorita é encantada para ser visível na escuridão, uma ferramenta útil nas cavernas onde ele procura novos locais de mineração."},pl={title="Foreman Thazz'ril",body="Foreman Thazz'ril nadzoruje peonów i bada możliwe źródła minerałów. Ulubiony kilof jest zaklęty tak, by być widocznym w ciemności, co pomaga w jaskiniach, gdzie szuka nowych miejsc wydobycia."},ru={title="Foreman Thazz'ril",body="Foreman Thazz'ril контролирует рабочих и обследует возможные источники полезных ископаемых. Его любимый пик - зачарованный вид в темноте, полезный инструмент в пещерах, где он ищет новые места для добычи."},references={}},
    ["person:frahun-shadewhisper"] = {title="Frahun Sombrusurro",kind="Personaje",aliases={"Frahun","Frahun Sombrusurro"},body="Frahun es un instructor de pícaros entre los elfos de la noche. Considera que su oficio es especialmente necesario en una época de paz frágil y sospechas entre los distintos pueblos de Azeroth.",aliasQuestIDs={},en={title="Frahun Shadewhisper",aliases={"Frahun","Frahun Shadewhisper"},body="Frahun is a rogue trainer among the night elves. He considers his calling especially necessary in an age of fragile peace and suspicion among Azeroth’s peoples.",aliasQuestIDs={}},fr={title="Frahun Shadewhisper",body="Frahun est un formateur de voleurs parmi les elfes de la nuit. Il considère que sa vocation est particulièrement nécessaire à une époque de paix fragile et de suspicion parmi les peuples de Azeroth."},de={title="Frahun Shadewhisper",body="Frahun ist ein Schurkentrainer unter den Nachtelfen. Er betrachtet seine Berufung als besonders notwendig in einer Zeit des brüchigen Friedens und des Misstrauens unter den Völkern des Azeroth."},pt={title="Frahun Shadewhisper",body="Frahun é um instrutor de ladinos entre os elfos noturnos. Ele considera seu chamado especialmente necessário em uma era de paz frágil e suspeita entre os povos do Azeroth."},pl={title="Frahun Shadewhisper",body="Frahun jest nauczycielem łotrzyków wśród nocnych elfów. Uważa swoje powołanie za szczególnie potrzebne w epoce kruchego pokoju i podejrzliwości między ludami Azeroth."},ru={title="Frahun Shadewhisper",body="Frahun - это неудачник-тренер среди ночных эльфов. Он считает своё призвание особенно необходимым в эпоху хрупкого мира и подозрений между народами Azeroth."},references={["place:azeroth"]=true}},
    ["person:frang"] = {title="Frang",kind="Personaje",aliases={"Frang"},body="Frang es un instructor de guerreros del Valle de los Retos. Recibe a los nuevos combatientes junto a El Cubil y los incorpora a la disciplina con la que la Horda prepara a sus defensores.",aliasQuestIDs={},en={title="Frang",aliases={"Frang"},body="Frang is a warrior trainer in the Valley of Trials. He receives new fighters beside the Den and introduces them to the discipline through which the Horde prepares its defenders.",aliasQuestIDs={}},fr={title="Frang",body="Frang est un entraîneur de guerrier dans le Valley of Trials. Il reçoit de nouveaux combattants à côté de la tanière et les introduit à la discipline à travers laquelle le Horde prépare ses défenseurs."},de={title="Frang",body="Frang ist ein Kriegertrainer im Valley of Trials. Er empfängt neue Kämpfer neben der Höhle und führt sie in die Disziplin ein, mit der Horde seine Verteidiger vorbereitet."},pt={title="Frang",body="Frang é um treinador guerreiro no Valley of Trials. Ele recebe novos lutadores ao lado do Den e os apresenta à disciplina através da qual o Horde prepara seus defensores."},pl={title="Frang",body="Frang jest nauczycielem wojowników w Valley of Trials. Przyjmuje nowych wojowników przy Den i wprowadza ich w dyscyplinę, dzięki której organizacja Horde przygotowuje obrońców."},ru={title="Frang",body="Frang - это тренер воина в Valley of Trials. Он принимает новых бойцов рядом с Гурбиной и знакомит их с дисциплиной, с помощью которой Horde готовит своих защитников."},references={["organization:horde"]=true,["place:valley-of-trials"]=true}},
    ["person:frankal-stonebridge"] = {title="Frankal Petraponte",kind="Personaje",aliases={"Frankal","Frankal Petraponte"},body="Frankal estudia el lenguaje y los glifos de los silítidos y los qiraji. Su investigación combina transcripciones de cristales con la preparación de un elixir que podría facilitar la comprensión de esas inscripciones.",aliasQuestIDs={},en={title="Frankal Stonebridge",aliases={"Frankal","Frankal Stonebridge"},body="Frankal studies the language and glyphs of the silithid and Qiraji. His research combines crystal transcriptions with the preparation of an elixir that might make those inscriptions easier to understand.",aliasQuestIDs={}},fr={title="Frankal Stonebridge",body="Frankal étudie le langage et les glyphes du silithid et Qiraji. Ses recherches combinent des transcriptions cristallines avec la préparation d’un élixir qui pourrait rendre ces inscriptions plus faciles à comprendre."},de={title="Frankal Stonebridge",body="Frankal studiert die Sprache und die Zeichen des Silithid und Qiraji. Seine Forschung kombiniert Kristalltranskriptionen mit der Herstellung eines Elixiers, das diese Inschriften leichter verständlich machen könnte."},pt={title="Frankal Stonebridge",body="Frankal estuda a linguagem e os glifos do silithid e do Qiraji. Sua pesquisa combina transcrições de cristal com a preparação de um elixir que pode tornar essas inscrições mais fáceis de entender."},pl={title="Frankal Stonebridge",body="Frankal bada język i glify silithidów oraz Qiraji. Łączy transkrypcje kryształów z przygotowywaniem eliksiru, który mógłby ułatwić zrozumienie inskrypcji."},ru={title="Frankal Stonebridge",body="Frankal изучает язык и символы силицида и Qiraji. Его исследования сочетают кристаллические транскрипции с подготовкой эликсира, который может облегчить понимание этих надписей."},references={["people:qiraji"]=true}},
    ["person:furl-scornbrow"] = {title="Furl Ceñosprecio",kind="Personaje",aliases={"Furl","Furl Ceñosprecio"},body="Furl Ceñosprecio ya no puede combatir como antes, pero continúa sirviendo a la Horda como vigía. Desde su puesto advierte de posibles invasores y fabrica objetos que ayudan a los guerreros jóvenes a defender su hogar.",aliasQuestIDs={},en={title="Furl Scornbrow",aliases={"Furl","Furl Scornbrow"},body="Furl Scornbrow can no longer fight as he once did, but continues to serve the Horde as a lookout. From his post he watches for invaders and makes goods that help younger warriors defend their homeland.",aliasQuestIDs={}},fr={title="Furl Scornbrow",body="Furl Scornbrow ne peut plus se battre comme il l'a déjà fait, mais continue de servir le Horde comme vigie. De son poste, il surveille les envahisseurs et fabrique des biens qui aident les jeunes guerriers à défendre leur patrie."},de={title="Furl Scornbrow",body="Furl Scornbrow kann nicht mehr kämpfen wie früher, sondern dient dem Horde weiterhin als Aussichtspunkt. Von seinem Posten aus sieht er nach Invasoren und stellt Waren her, die jüngeren Kriegern helfen, ihre Heimat zu verteidigen."},pt={title="Furl Scornbrow",body="Furl Scornbrow já não pode lutar como ele fez uma vez, mas continua a servir o Horde como um vigia. A partir de seu post, ele observa os invasores e faz bens que ajudam os guerreiros mais jovens a defender sua terra natal."},pl={title="Furl Scornbrow",body="Furl Scornbrow nie może już walczyć jak dawniej, ale nadal służy frakcji Horde jako obserwator. Wypatruje najeźdźców z posterunku i wytwarza towary pomagające młodszym wojownikom bronić ojczyzny."},ru={title="Furl Scornbrow",body="Furl Scornbrow больше не может сражаться, как раньше, но продолжает служить Horde в качестве сторожа. На своем посту он следит за захватчиками и производит товары, которые помогают молодым воинам защищать свою родину."},references={["organization:horde"]=true}},
    ["person:gaeriyan"] = {title="Gaeriyan",kind="Personaje",aliases={"Gaeriyan"},body="Gaeriyan es una presencia misteriosa en las montañas al norte de Gadgetzan. Solo se deja encontrar en condiciones excepcionales: llegar a su retiro por un camino ordinario no basta para hablar con él.",aliasQuestIDs={},en={title="Gaeriyan",aliases={"Gaeriyan"},body="Gaeriyan is a mysterious presence in the mountains north of Gadgetzan. He can only be encountered under unusual conditions: an ordinary journey to his retreat is not enough to speak with him.",aliasQuestIDs={}},fr={title="Gaeriyan",body="Gaeriyan est une présence mystérieuse dans les montagnes au nord de Gadgetzan. Il ne peut être rencontré que dans des conditions inhabituelles: un voyage ordinaire à sa retraite ne suffit pas pour lui parler."},de={title="Gaeriyan",body="Gaeriyan ist eine geheimnisvolle Präsenz in den Bergen nördlich von Gadgetzan. Man kann ihm nur unter ungewöhnlichen Umständen begegnen: Eine gewöhnliche Reise zu seinem Exerholungsort reicht nicht aus, um mit ihm zu sprechen."},pt={title="Gaeriyan",body="Gaeriyan é uma presença misteriosa nas montanhas ao norte de Gadgetzan. Ele só pode ser encontrado em condições incomuns: uma jornada comum para seu retiro não é suficiente para falar com ele."},pl={title="Gaeriyan",body="Gaeriyan jest tajemniczą obecnością w górach na północ od Gadgetzan. Spotkać go można tylko w niezwykłych warunkach: zwykła podróż do jego schronienia nie wystarcza, by z nim porozmawiać."},ru={title="Gaeriyan",body="Gaeriyan - это таинственное присутствие в горах к северу от Gadgetzan. Его можно встретить только в необычных условиях: обычной поездки в его укрытие недостаточно, чтобы поговорить с ним."},references={["place:gadgetzan"]=true}},
    ["person:gaerolas-talvethren"] = {title="Gaerolas Talvethren",kind="Personaje",aliases={"Gaerolas","Gaerolas Talvethren"},body="Gaerolas Talvethren es el gran celador de los druidas de la Garra que duermen en Túmulo de Ban'ethil. Su responsabilidad es proteger su descanso y mantener el pacto que los une a Ysera.",aliasQuestIDs={},en={title="Gaerolas Talvethren",aliases={"Gaerolas","Gaerolas Talvethren"},body="Gaerolas Talvethren is the great warden of the Druids of the Talon sleeping in Ban'ethil Barrow Den. His responsibility is to protect their rest and preserve their pact with Ysera.",aliasQuestIDs={}},fr={title="Gaerolas Talvethren",body="Gaerolas Talvethren est le grand gardien du Druids de la Talon dormant dans Ban'ethil Barrow Den. Sa responsabilité est de protéger leur repos et de préserver leur pacte avec Ysera."},de={title="Gaerolas Talvethren",body="Gaerolas Talvethren ist der große Hüter des Druids vom Talon, der in Ban'ethil Barrow Den schläft. Seine Verantwortung ist es, ihre Ruhe zu schützen und ihren Pakt mit Ysera zu bewahren."},pt={title="Gaerolas Talvethren",body="Gaerolas Talvethren é o grande diretor da Druids do Talon dormindo em Ban'ethil Barrow Den. Sua responsabilidade é proteger seu descanso e preservar seu pacto com o Ysera."},pl={title="Gaerolas Talvethren",body="Gaerolas Talvethren jest wielkim strażnikiem Druids of the Talon śpiących w Ban'ethil Barrow Den. Odpowiada za ochronę ich odpoczynku i zachowanie paktu z istotą Ysera."},ru={title="Gaerolas Talvethren",body="Gaerolas Talvethren - великий надзиратель Druids Talon, который спит в Ban'ethil Barrow Den. Его обязанность - защитить их и сохранить договор с Ysera."},references={["npc:ysera"]=true,["place:banethil-barrow-den"]=true}},
    ["person:galgar"] = {title="Galgar",kind="Personaje",aliases={"Galgar"},body="Galgar prepara una especialidad refrescante con las manzanas de cactus que crecen en el Valle de los Retos. Su sorpresa de manzana de cactus ofrece un pequeño alivio frente al calor de Durotar a quienes comienzan sus viajes.",aliasQuestIDs={},en={title="Galgar",aliases={"Galgar"},body="Galgar makes a refreshing specialty from the cactus apples growing in the Valley of Trials. His cactus apple surprise offers relief from Durotar’s heat to those beginning their travels.",aliasQuestIDs={}},fr={title="Galgar",body="Galgar est une spécialité rafraîchissante des pommes de cactus qui poussent dans le Valley of Trials. Sa surprise de pomme de cactus offre un soulagement de la chaleur de Durotar à ceux qui commencent leurs voyages."},de={title="Galgar",body="Galgar macht eine erfrischende Spezialität aus den Kaktusäpfeln, die im Valley of Trials wachsen. Seine Kaktusapfelüberraschung bietet denjenigen, die ihre Reise antreten, Linderung von Durotar 'Hitze."},pt={title="Galgar",body="Galgar faz uma especialidade refrescante das maçãs do cacto que crescem no Valley of Trials. Sua surpresa de maçã cacto oferece alívio do calor do Durotar para aqueles que começam suas viagens."},pl={title="Galgar",body="Galgar wytwarza orzeźwiający specjał z jabłek kaktusowych rosnących w Valley of Trials. Jego kaktusowa niespodzianka przynosi ulgę od gorąca Durotar osobom rozpoczynającym podróże."},ru={title="Galgar",body="Galgar делает освежающее блюдо из яблок кактуса, растущих в Valley of Trials. Его неожиданный яблочный кактус предлагает облегчение от жары Durotar тем, кто начинает свое путешествие."},references={["place:durotar"]=true,["place:valley-of-trials"]=true}},
    ["person:gann-stonespire"] = {title="Gann Picopiedra",kind="Personaje",aliases={"Gann","Gann Picopiedra"},body="Gann Picopiedra es un tauren que considera las tierras de Bael Modan parte del hogar de su tribu. La destrucción causada por las excavaciones enanas ha convertido su vínculo con el lugar en una lucha por recuperar lo perdido.",aliasQuestIDs={},en={title="Gann Stonespire",aliases={"Gann","Gann Stonespire"},body="Gann Stonespire is a tauren who regards the lands of Bael Modan as part of his tribe’s home. Destruction caused by dwarven excavations has turned his connection to the place into a struggle to reclaim what was lost.",aliasQuestIDs={}},fr={title="Gann Stonespire",body="Gann Stonespire est un tauren qui considère les terres de Bael Modan comme faisant partie de la maison de sa tribu. La destruction causée par les fouilles de nains a transformé sa connexion à l'endroit dans une lutte pour récupérer ce qui a été perdu."},de={title="Gann Stonespire",body="Gann Stonespire ist ein Tauren, der das Land von Bael Modan als Teil der Heimat seines Stammes betrachtet. Zerstörungen durch Zwergengrabungen haben seine Verbindung zu diesem Ort in einen Kampf um die Rückgewinnung des Verlorenen Besitzes verwandelt."},pt={title="Gann Stonespire",body="Gann Stonespire é um tauren que considera as terras de Bael Modan como parte da casa de sua tribo. A destruição causada por escavações de anões transformou sua conexão com o lugar em uma luta para recuperar o que foi perdido."},pl={title="Gann Stonespire",body="Gann Stonespire jest taurenem uznającym ziemie Bael Modan za część domu swojego plemienia. Zniszczenia spowodowane krasnoludzkimi wykopaliskami przemieniły jego więź z tym miejscem w walkę o odzyskanie tego, co utracono."},ru={title="Gann Stonespire",body="Gann Stonespire - это таурен, который считает земли Bael Modan частью своего дома. Разрушение, вызванное карликовыми раскопками, превратило его связь с местом в борьбу за то, чтобы вернуть потерянное."},references={}},
    ["person:ganrul-bloodeye"] = {title="Gan'rul Ojosangre",kind="Personaje",aliases={"Gan'rul","Gan'rul Ojosangre","Gan’rul","Gan’rul Ojosangre"},body="Gan'rul Ojosangre es un instructor de brujos de Orgrimmar. Enseña rituales de invocación y subraya que dominar a un demonio requiere tanto preparar los componentes como evitar la arrogancia.",aliasQuestIDs={},en={title="Gan'rul Bloodeye",aliases={"Gan'rul","Gan'rul Bloodeye","Gan’rul","Gan’rul Bloodeye"},body="Gan'rul Bloodeye is a warlock trainer in Orgrimmar. He teaches summoning rituals and stresses that mastering a demon requires both preparing components and avoiding arrogance.",aliasQuestIDs={}},fr={title="Gan'rul Bloodeye",body="Gan'rul Bloodeye est un formateur de Démoniste dans Orgrimmar. Il enseigne les rituels d'invocation et souligne que la maîtrise d'un démon nécessite à la fois de préparer des composants et d'éviter l'arrogance."},de={title="Gan'rul Bloodeye",body="Gan'rul Bloodeye bildet in Orgrimmar Hexenmeister aus. Er unterrichtet Beschwörungsrituale und betont, dass zur Beherrschung eines Dämons sowohl die Vorbereitung von Komponenten als auch das Vermeiden von Überheblichkeit gehören."},pt={title="Gan'rul Bloodeye",body="Gan'rul Bloodeye é um treinador de bruxos em Orgrimmar. Ele ensina a convocar rituais e enfatiza que dominar um demônio requer tanto preparar componentes quanto evitar a arrogância."},pl={title="Gan'rul Bloodeye",body="Gan'rul Bloodeye jest nauczycielem czarnoksiężników w Orgrimmar. Uczy rytuałów przywoływania i podkreśla, że opanowanie demona wymaga zarówno przygotowania składników, jak i unikania pychy."},ru={title="Gan'rul Bloodeye",body="Gan'rul Bloodeye - это тренер-чернокнижник в Orgrimmar. Он учит призывать ритуалы и подчеркивает, что овладение демоном требует как подготовки компонентов, так и избегания высокомерия."},references={["place:orgrimmar"]=true}},
    ["person:gart-mistrunner"] = {title="Gart Correbruma",kind="Personaje",aliases={"Gart","Gart Correbruma"},body="Gart Correbruma instruye a los druidas tauren en las enseñanzas de la Madre Tierra. Reconoce su vínculo con los elfos de la noche, aunque sus lecciones también reflejan la desconfianza que todavía separa a ambos pueblos.",aliasQuestIDs={},en={title="Gart Mistrunner",aliases={"Gart","Gart Mistrunner"},body="Gart Mistrunner instructs tauren druids in the Earth Mother’s teachings. He recognizes their bond with the night elves, though his lessons also reflect the distrust that still separates the two peoples.",aliasQuestIDs={}},fr={title="Gart Mistrunner",body="Gart Mistrunner enseigne aux druides taurens les enseignements du Earth Mother. Il reconnaît leur lien avec les elfes de la nuit, bien que ses leçons reflètent également la méfiance qui sépare encore les deux peuples."},de={title="Gart Mistrunner",body="Gart Mistrunner unterrichtet die Tauren-Druiden in den Lehren des Earth Mother. Er erkennt ihre Verbindung zu den Nachtelfen, obwohl seine Lehren auch das Misstrauen widerspiegeln, das die die die die beide Völker noch immer trennt."},pt={title="Gart Mistrunner",body="Gart Mistrunner instrui os druidas tauren nos ensinamentos do Earth Mother. Ele reconhece seu vínculo com os elfos noturnos, embora suas lições também reflitam a desconfiança que ainda separa os dois povos."},pl={title="Gart Mistrunner",body="Gart Mistrunner wprowadza taurenskich druidów w nauki istoty Earth Mother. Uznaje więź z nocnymi elfami, choć lekcje odzwierciedlają również nieufność nadal dzielącą oba ludy."},ru={title="Gart Mistrunner",body="Gart Mistrunner обучает друидов-таурен в учении Earth Mother s. Он признает их связь с ночными эльфами, хотя его уроки также отражают недоверие, которое все еще разделяет два народа."},references={["person:earth-mother"]=true}},
    ["person:garthok"] = {title="Gar'Thok",kind="Personaje",aliases={"Gar'Thok","Gar'thok","Gar’Thok","Gar’thok"},body="Gar'Thok es un defensor de la Horda destinado en Cerrotajo. Atiende la seguridad de Durotar, desde los peligros que acechan en los caminos hasta la presencia de fuerzas humanas en la región.",aliasQuestIDs={},en={title="Gar'Thok",aliases={"Gar'Thok","Gar’Thok"},body="Gar'Thok is a Horde defender stationed in Razor Hill. He deals with Durotar’s security, from dangers on the roads to the presence of human forces in the region.",aliasQuestIDs={}},fr={title="Gar'Thok",body="Gar'Thok est un défenseur Horde stationné dans Razor Hill. Il s’occupe de la sécurité de Durotar, des dangers sur les routes à la présence de forces humaines dans la région."},de={title="Gar'Thok",body="Gar'Thok ist ein Horde Verteidiger, der in Razor Hill stationiert ist. Er befasst sich mit der Sicherheit von Durotar, von Gefahren auf den Straßen bis hin zur Präsenz menschlicher Kräfte in der Region."},pt={title="Gar'Thok",body="Gar'Thok é um defensor Horde estacionado em Razor Hill. Ele lida com a segurança do Durotar, desde perigos nas estradas até a presença de forças humanas na região."},pl={title="Gar'Thok",body="Gar'Thok jest obrońcą frakcji Horde stacjonującym w Razor Hill. Zajmuje się bezpieczeństwem Durotar, od niebezpieczeństw na drogach po obecność ludzkich wojsk w regionie."},ru={title="Gar'Thok",body="Gar'Thok - защитник Horde, дислоцированный в Razor Hill. Он занимается безопасностью Durotar, от опасностей на дорогах до присутствия человеческих сил в регионе."},references={["organization:horde"]=true,["place:durotar"]=true,["place:razor-hill"]=true}},
    ["person:gaxim-rustfizzle"] = {title="Gaxim Silvóxido",kind="Personaje",aliases={"Gaxim","Gaxim Silvóxido"},body="Gaxim Silvóxido trabaja en Sierra Espolón y recurre a sustancias químicas y explosivos para responder a los problemas de la región. Sus métodos dependen de materiales tan útiles como inestables.",aliasQuestIDs={},en={title="Gaxim Rustfizzle",aliases={"Gaxim","Gaxim Rustfizzle"},body="Gaxim Rustfizzle works in the Stonetalon Mountains and uses chemicals and explosives to respond to the region’s problems. His methods depend on materials that are as useful as they are unstable.",aliasQuestIDs={}},fr={title="Gaxim Rustfizzle",body="Gaxim Rustfizzle travaille dans le Stonetalon Mountains et utilise des produits chimiques et des explosifs pour répondre aux problèmes de la région. Ses méthodes dépendent de matériaux aussi utiles qu’instables."},de={title="Gaxim Rustfizzle",body="Gaxim Rustfizzle arbeitet im Stonetalon Mountains und verwendet Chemikalien und Sprengstoffe, um auf die Probleme der Region zu reagieren. Seine Methoden beruhen auf Materialien, die ebenso nützlich wie instabwechselnd sind."},pt={title="Gaxim Rustfizzle",body="Gaxim Rustfizzle trabalha no Stonetalon Mountains e usa produtos químicos e explosivos para responder aos problemas da região. Seus métodos dependem de materiais que são tão úteis quanto instáveis."},pl={title="Gaxim Rustfizzle",body="Gaxim Rustfizzle pracuje w regionie Stonetalon Mountains i wykorzystuje chemikalia oraz materiały wybuchowe do rozwiązywania miejscowych problemów. Jego metody zależą od materiałów równie użytecznych, co niestabilnych."},ru={title="Gaxim Rustfizzle",body="Gaxim Rustfizzle работает в Stonetalon Mountains и использует химикаты и взрывчатые вещества для решения проблем региона. Его методы зависят от материалов, которые так же полезны, как и нестабильны."},references={["place:stonetalon-mountains"]=true}},
    ["person:gazlowe"] = {title="Gazlowe",kind="Personaje",aliases={"Gazlowe"},body="Gazlowe es un goblin de Trinquete implicado en la seguridad y los negocios del puerto. Sus encargos y contactos reflejan una preocupación práctica por mantener en marcha el comercio y proteger a quienes trabajan junto al mar.",aliasQuestIDs={},en={title="Gazlowe",aliases={"Gazlowe"},body="Gazlowe is a goblin in Ratchet involved in the port’s security and business. His commissions and contacts reflect a practical concern for keeping trade moving and protecting those who work by the sea.",aliasQuestIDs={}},fr={title="Gazlowe",body="Gazlowe est un gobelin de Ratchet impliqué dans la sécurité et les affaires du port. Ses commissions et ses contacts reflètent un souci pratique de maintenir le commerce en mouvement et de protéger ceux qui travaillent en mer."},de={title="Gazlowe",body="Gazlowe ist ein Goblin in Ratchet, der sich um die Sicherheit und Geschäfte des Hafens kümmert. Seine Kommissionen und Kontakte spiegeln ein praktisches Anliegen wider, den Handel in Gang zu halten und diejenigen zu schützen, die am Meer arbeiten."},pt={title="Gazlowe",body="Gazlowe é um goblin no Ratchet envolvido na segurança e nos negócios do porto. Suas comissões e contatos refletem uma preocupação prática para manter o comércio em movimento e proteger aqueles que trabalham à beira-mar."},pl={title="Gazlowe",body="Gazlowe jest goblinem w Ratchet zaangażowanym w bezpieczeństwo portu i interesy. Jego zlecenia oraz kontakty odzwierciedlają praktyczną troskę o ciągłość handlu i ochronę ludzi pracujących nad morzem."},ru={title="Gazlowe",body="Gazlowe - это гоблин в Ratchet, участвующий в безопасности порта и бизнесе. Его комиссии и контакты отражают практическую заботу о сохранении торговли и защите тех, кто работает на море."},references={["place:ratchet"]=true}},
    ["person:gazrog"] = {title="Gazrog",kind="Personaje",aliases={"Gazrog"},body="Gazrog vive en El Cruce y conoce tanto a los soldados como a las bestias de Los Baldíos. Sus contactos y sus encargos lo sitúan entre quienes orientan a los viajeros por una región extensa y peligrosa.",aliasQuestIDs={},en={title="Gazrog",aliases={"Gazrog"},body="Gazrog lives at the Crossroads and knows both the soldiers and beasts of the Barrens. His contacts and commissions place him among those guiding travelers through a vast and dangerous region.",aliasQuestIDs={}},fr={title="Gazrog",body="Gazrog vit au Crossroads et connaît à la fois les soldats et les bêtes du Barrens. Ses contacts et ses commissions le placent parmi ceux qui guident les voyageurs à travers une région vaste et dangereuse."},de={title="Gazrog",body="Gazrog lebt im Crossroads und kennt sowohl die Soldaten als auch die Tiere des Barrens. Durch seine Kontakte und Aufträge gehört er zu denjenigen, die Reisende durch eine riesige und gefährliche Region führen."},pt={title="Gazrog",body="Gazrog vive no Crossroads e conhece tanto os soldados quanto os animais do Barrens. Seus contatos e comissões colocá-lo entre aqueles que orientam os viajantes através de uma região vasta e perigosa."},pl={title="Gazrog",body="Gazrog mieszka w Crossroads i zna zarówno żołnierzy, jak i bestie regionu Barrens. Kontakty i zlecenia stawiają go wśród osób udzielających podróżnym wskazówek w rozległej, niebezpiecznej krainie."},ru={title="Gazrog",body="Gazrog живет в Crossroads и знает как солдат, так и зверей Barrens. Его контакты и поручения делают его одним из тех, кто ведет путешественников через обширный и опасный регион."},references={["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:gazzuz"] = {title="Gazz'uz",kind="Personaje",aliases={"Gazz'uz","Gazz’uz"},body="Gazz'uz está vinculado con las comunicaciones mágicas de la Roca del Cráneo. Un colgante transmite a su destinatario voces que exigen informes y advierten de un ataque, revelando una red de contactos que opera a distancia.",aliasQuestIDs={},en={title="Gazz'uz",aliases={"Gazz'uz","Gazz’uz"},body="Gazz'uz is linked with magical communications concerning Skull Rock. A pendant carries voices demanding reports and warning of an attack, revealing contacts operating across a distance.",aliasQuestIDs={}},fr={title="Gazz'uz",body="Gazz'uz est lié à des communications magiques concernant Skull Rock. Un pendentif porte des voix exigeant des rapports et des avertissements d'une attaque, révélant des contacts opérant à distance."},de={title="Gazz'uz",body="Gazz'uz wird mit magischen Mitteilungen über Skull Rock in Verbindung gebracht. Ein Anhänger trägt Stimmen, die Berichte fordern und vor einem Angriff warnen, und Kontakte offenbaren, die über eine Entfernung hinweg operieren."},pt={title="Gazz'uz",body="Gazz'uz está ligado a comunicações mágicas sobre Skull Rock. Um pingente carrega vozes exigindo relatórios e aviso de um ataque, revelando contatos que operam através de uma distância."},pl={title="Gazz'uz",body="Gazz'uz jest powiązany z magiczną komunikacją dotyczącą Skull Rock. Wisiorek przenosi głosy żądające raportów i ostrzegające przed atakiem, ujawniając kontakty działające na odległość."},ru={title="Gazz'uz",body="Gazz'uz связана с магическими сообщениями, касающимися Skull Rock. На подвеске звучат голоса, требующие сообщений и предупреждения об атаке, показывающие контакты, действующие на расстоянии."},references={["place:skull-rock"]=true}},
    ["person:gelkak-gyromast"] = {title="Gelkak Gyromast",kind="Personaje",aliases={"Gelkak","Gelkak Gyromast"},body="Gelkak Gyromast es un inventor de Costa Oscura que considera su máquina un contramaestre. Sus dispositivos mezclan mecanismos prácticos con una visión muy personal de la vida marinera.",aliasQuestIDs={},en={title="Gelkak Gyromast",aliases={"Gelkak","Gelkak Gyromast","Gyromast"},body="Gelkak Gyromast is a Darkshore inventor who regards his machine as a first mate. His devices blend practical mechanisms with a highly personal view of seafaring life.",aliasQuestIDs={}},fr={title="Gelkak Gyromast",body="Gelkak Gyromast est un inventeur de Darkshore qui considère sa machine comme un premier maître. Ses appareils combinent des mécanismes pratiques avec une vision très personnelle de la vie en mer."},de={title="Gelkak Gyromast",body="Gelkak Gyromast ist ein Darkshore-Erfinder seine Maschine als ersten Kumpel betrachtet. Seine Geräte verbinden praktische Mechanismen mit einer sehr persönlichen Sicht auf das Leben in der Seefahrt."},pt={title="Gelkak Gyromast",body="Gelkak Gyromast é um inventor Darkshore que considera sua máquina como uma primeira companheira. Seus dispositivos misturam mecanismos práticos com uma visão altamente pessoal da vida marítima."},pl={title="Gelkak Gyromast",body="Gelkak Gyromast jest wynalazcą w Darkshore uznającym swoją maszynę za pierwszego oficera. Jego urządzenia łączą praktyczne mechanizmy z bardzo osobistym spojrzeniem na życie żeglarza."},ru={title="Gelkak Gyromast",body="Gelkak Gyromast - изобретатель Darkshore, который считает свою машину первым помощником. Его устройства сочетают в себе практические механизмы с очень личным взглядом на жизнь моряка."},references={["place:darkshore"]=true},questIDs={[2078]=true,[2098]=true}},
    ["person:general-kirika"] = {title="General Kirika",kind="Personaje",aliases={"General Kirika","Kirika"},body="Kirika dirige reclutas de la Horda en la lucha por los recursos de Silithus. El desgaste del desierto y los refuerzos que recibe la Alianza hacen que mantener las posiciones exija una llegada constante de combatientes.",aliasQuestIDs={},en={title="General Kirika",aliases={"General Kirika","Kirika"},body="Kirika commands Horde recruits in the struggle for Silithus’s resources. The desert’s toll and the Alliance’s reinforcements make a steady flow of fighters necessary to hold their positions.",aliasQuestIDs={}},fr={title="General Kirika",body="Kirika commande Horde recrute dans la lutte pour les ressources de Silithus. Le bilan du désert et les renforts du Alliance font un flux régulier de combattants nécessaires pour maintenir leurs positions."},de={title="General Kirika",body="Kirika befehligt Horde Rekruten im Kampf um Silithus 'Ressourcen. Der Tribut der Wüste und die Verstärkungen der Alliance machen einen stetigen Zustrom von Kämpfern notwendig, um ihre Stellungen zu halten."},pt={title="General Kirika",body="Kirika comanda recrutas Horde na luta pelos recursos do Silithus. O pedágio do deserto e os reforços do Alliance fazem com que um fluxo constante de combatentes seja necessário para manter suas posições."},pl={title="General Kirika",body="Kirika dowodzi rekrutami frakcji Horde w walce o zasoby Silithus. Wyniszczająca pustynia i posiłki Alliance wymagają stałego napływu wojowników, by utrzymać pozycje."},ru={title="General Kirika",body="Kirika командует рекрутами Horde в борьбе за ресурсы Silithus. Тяжёлые условия пустыни и подкрепления Alliance требуют постоянного притока бойцов для удержания позиций."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:silithus"]=true}},
    ["person:geologist-larksbane"] = {title="Geóloga Trotaruina",kind="Personaje",aliases={"Geóloga Trotaruina","Trotaruina","geóloga Trotaruina","geóloga Trotuina"},body="La geóloga Trotaruina estudia los materiales y mensajes extraños de Silithus desde el Fuerte Cenarion. Su experiencia es útil para analizar los cristales que las fuerzas del desierto emplean para comunicarse.",aliasQuestIDs={},en={title="Geologist Larksbane",aliases={"Geologist Larksbane","Larksbane"},body="Geologist Larksbane studies strange materials and messages in Silithus from Cenarion Hold. Her expertise helps analyze crystals used by the desert’s forces to communicate.",aliasQuestIDs={}},fr={title="Geologist Larksbane",body="Geologist Larksbane étudie des matériaux et des messages étranges dans Silithus de Cenarion Hold. Son expertise aide à analyser les cristaux utilisés par les forces du désert pour communiquer."},de={title="Geologist Larksbane",body="Geologist Larksbane studiert seltsame Materialien und Botschaften in Silithus von Cenarion Hold. Ihre Expertise hilft bei der Analyse von den Wüstenkräften verwendeter Kristalle zur Kommunikation."},pt={title="Geologist Larksbane",body="Geologist Larksbane estuda materiais estranhos e mensagens em Silithus de Cenarion Hold. Sua experiência ajuda a analisar cristais usados pelas forças do deserto para se comunicar."},pl={title="Geologist Larksbane",body="Geologist Larksbane bada niezwykłe materiały i wiadomości w Silithus, działając z Cenarion Hold. Jej wiedza pomaga analizować kryształy używane przez pustynne siły do porozumiewania się."},ru={title="Geologist Larksbane",body="Geologist Larksbane изучает странные материалы и сообщения в Silithus от Cenarion Hold. Ее опыт помогает анализировать кристаллы, используемые силами пустыни для общения."},references={["place:cenarion-hold"]=true,["place:silithus"]=true}},
    ["person:gerenzo-wrenchwhistle"] = {title="Gerenzo Silbillave",kind="Personaje",aliases={"Gerenzo","Gerenzo Silbillave"},body="Gerenzo Silbillave supervisa operaciones de Ventura y Cía. en Sierra Espolón. Su cuerpo incorpora miembros y piezas mecánicas, reflejo de una relación extrema entre la ingeniería y la propia carne.",aliasQuestIDs={},en={title="Gerenzo Wrenchwhistle",aliases={"Gerenzo","Gerenzo Wrenchwhistle"},body="Gerenzo Wrenchwhistle oversees Venture Company operations in the Stonetalon Mountains. His body incorporates mechanical limbs and parts, reflecting an extreme relationship between engineering and flesh.",aliasQuestIDs={}},fr={title="Gerenzo Wrenchwhistle",body="Gerenzo Wrenchwhistle supervise les opérations de Venture Company dans le Stonetalon Mountains. Son corps incorpore des membres et des parties mécaniques, reflétant une relation extrême entre l'ingénierie et la chair."},de={title="Gerenzo Wrenchwhistle",body="Gerenzo Wrenchwhistle beaufsichtigt die Operationen von Venture Company im Stonetalon Mountains. Sein Körper enthält mechanische Gliedmaßen und Teile, was eine extreme Beziehung zwischen Technik und Fleisch widerspiegelt."},pt={title="Gerenzo Wrenchwhistle",body="Gerenzo Wrenchwhistle supervisiona as operações Venture Company no Stonetalon Mountains. Seu corpo incorpora membros mecânicos e partes, refletindo uma relação extrema entre engenharia e carne."},pl={title="Gerenzo Wrenchwhistle",body="Gerenzo Wrenchwhistle nadzoruje działalność Venture Company w regionie Stonetalon Mountains. Jego ciało zawiera mechaniczne kończyny i części, odzwierciedlając skrajny związek inżynierii z żywą tkanką."},ru={title="Gerenzo Wrenchwhistle",body="Gerenzo Wrenchwhistle контролирует операции Venture Company в Stonetalon Mountains. Его тело включает в себя механические конечности и части, отражающие экстремальные отношения между машиностроением и плотью."},references={["organization:venture-company"]=true,["place:stonetalon-mountains"]=true}},
    ["person:gershala-nightwhisper"] = {title="Gershala Susurro Nocturno",kind="Personaje",aliases={"Gershala","Gershala Susurro Nocturno"},body="Gershala vive en Auberdine e investiga los efectos de la magia demoníaca sobre los seres vivos. Su temor a nuevas transformaciones lo lleva a estudiar a los nagas y los sátiros, en busca de indicios sobre los riesgos de la corrupción.",aliasQuestIDs={},en={title="Gershala Nightwhisper",aliases={"Gershala","Gershala Nightwhisper"},body="Gershala lives in Auberdine and investigates the effects of demonic magic on living beings. His fear of further transformations leads him to study naga and satyrs for clues to the dangers of corruption.",aliasQuestIDs={}},fr={title="Gershala Nightwhisper",body="Gershala vit dans Auberdine et étudie les effets de la magie démoniaque sur les êtres vivants. Sa peur de nouvelles transformations l'amène à étudier le naga et les satyres pour trouver des indices sur les dangers de la corruption."},de={title="Gershala Nightwhisper",body="Gershala lebt in Auberdine und untersucht die Auswirkungen dämonischer Magie auf Lebewesen. Seine Angst vor weiteren Transformationen veranlasst ihn, Naga und Satyre nach Hinweisen auf die Gefahren der Korruption zu studieren."},pt={title="Gershala Nightwhisper",body="Gershala vive em Auberdine e investiga os efeitos da magia demoníaca sobre os seres vivos. Seu medo de novas transformações o leva a estudar naga e sátiros em busca de pistas sobre os perigos da corrupção."},pl={title="Gershala Nightwhisper",body="Gershala mieszka w Auberdine i bada wpływ demonicznej magii na istoty żywe. Lęk przed dalszymi przemianami prowadzi go do badania nag i satyrów w poszukiwaniu wskazówek o niebezpieczeństwach skażenia."},ru={title="Gershala Nightwhisper",body="Gershala живет в Auberdine и исследует влияние демонической магии на живых существ. Страх дальнейших преобразований заставляет его изучать нагу и сатири в поисках подсказок к опасности порчи."},references={["place:auberdine"]=true}},
    ["person:ghost-howl"] = {title="Aullido Fantasma",kind="Personaje",aliases={"Aullido Fantasma"},body="Aullido Fantasma es un lobo conocido en Mulgore. Las marcas de una antigua herida vinculan su historia a los combates contra la Legión Ardiente y a la memoria que los tauren conservan de ellos.",aliasQuestIDs={},en={title="Ghost Howl",aliases={"Ghost Howl"},body="Ghost Howl is a wolf known in Mulgore. The marks of an old wound connect his history with battles against the Burning Legion and the memory the tauren preserve of them.",aliasQuestIDs={}},fr={title="Ghost Howl",body="Ghost Howl est un loup connu dans Mulgore. Les marques d'une vieille blessure relient son histoire avec des batailles contre le Burning Legion et la mémoire que les taurens conservent d'eux."},de={title="Ghost Howl",body="Ghost Howl ist ein Wolf, der in Mulgore bekannt ist. Die Spuren einer alten Wunde verbinden seine Geschichte mit den Kämpfen gegen den Burning Legion und die Erinnerung, die die von den Tauren bewahrt werden."},pt={title="Ghost Howl",body="Ghost Howl é um lobo conhecido no Mulgore. As marcas de uma ferida antiga conectam sua história com batalhas contra o Burning Legion e a memória que os tauren preservam."},pl={title="Ghost Howl",body="Ghost Howl jest wilkiem znanym w Mulgore. Ślady dawnej rany łączą jego historię z bitwami przeciw Burning Legion i pamięcią zachowywaną przez taurenów."},ru={title="Ghost Howl",body="Ghost Howl - это волк, известный в Mulgore. Следы старой раны связывают его историю с битвами против Burning Legion и памятью, которую о них хранят Таурены."},references={["organization:burning-legion"]=true,["place:mulgore"]=true}},
    ["person:gilshalan-windwalker"] = {title="Gilshalan Caminaviento",kind="Personaje",aliases={"Gilshalan","Gilshalan Caminaviento"},body="Gilshalan Caminaviento estudia las arañas tejemadera de Cañada Umbría. Compara su veneno con el de arañas más pequeñas para investigar su teoría de que el crecimiento del Árbol del Mundo ha transformado a estas criaturas.",aliasQuestIDs={},en={title="Gilshalan Windwalker",aliases={"Gilshalan","Gilshalan Windwalker"},body="Gilshalan Windwalker studies the webwood spiders of Shadowglen. He compares their venom with that of smaller spiders to investigate his theory that the World Tree’s growth has changed these creatures.",aliasQuestIDs={}},fr={title="Gilshalan Windwalker",body="Gilshalan Windwalker étudie les araignées webwood de Shadowglen. Il compare leur venin à celui de petites araignées pour étudier sa théorie selon laquelle la croissance du World Tree a changé ces créatures."},de={title="Gilshalan Windwalker",body="Gilshalan Windwalker studiert die Webwood-Spinnen von Shadowglen. Er vergleicht ihr Gift mit dem der kleineren Spinnen, um seine Theorie zu untersuchen, dass das Wachstum des World Tree diese Geschöpfe verändert habe."},pt={title="Gilshalan Windwalker",body="Gilshalan Windwalker estuda as aranhas de webwood de Shadowglen. Ele compara seu veneno com o de aranhas menores para investigar sua teoria de que o crescimento do World Tree mudou essas criaturas."},pl={title="Gilshalan Windwalker",body="Gilshalan Windwalker bada pająki leśnych sieci w Shadowglen. Porównuje jad z jadem mniejszych pająków, sprawdzając teorię, że wzrost World Tree zmienił te stworzenia."},ru={title="Gilshalan Windwalker",body="Gilshalan Windwalker изучает пауков-полосатых Shadowglen. Он сравнивает их яд с ядом небольших пауков, чтобы исследовать свою теорию о том, что рост World Tree  изменил этих существ."},references={["place:shadowglen"]=true}},
    ["person:gilthares-firebough"] = {title="Gilthares Ramafuego",kind="Personaje",aliases={"Gilthares","Gilthares Ramafuego"},body="Gilthares Ramafuego trabajaba como marinero en el transporte de licor entre Trinquete y Bahía del Botín. Los soldados de Theramore lo encarcelaron tras hundir su barco, pese a que él rechaza la acusación de ser una amenaza para la Alianza.",aliasQuestIDs={},en={title="Gilthares Firebough",aliases={"Gilthares","Gilthares Firebough"},body="Gilthares Firebough worked as a deckhand carrying moonshine between Ratchet and Booty Bay. Theramore soldiers imprisoned him after sinking his ship, though he rejects their accusation that he threatens the Alliance.",aliasQuestIDs={}},fr={title="Gilthares Firebough",body="Gilthares Firebough a travaillé comme un matelot de pont transportant moonshine entre Ratchet et Booty Bay. Les soldats Theramore l'ont emprisonné après avoir coulé son navire, bien qu'il rejette leur accusation selon laquelle il menace le Alliance."},de={title="Gilthares Firebough",body="Gilthares Firebough arbeitete als Decksmann, der Mondschein zwischen Ratchet und Booty Bay trug. Theramore Soldaten sperrten ihn ein, nachdem er sein Schiff versenkt hatte, obwohl er den Vorwurf, dass er die Alliance bedrohe, zurückweist."},pt={title="Gilthares Firebough",body="Gilthares Firebough trabalhou como um deckhand transportando moonshine entre Ratchet e Booty Bay. Soldados Theramore o prenderam depois de afundar seu navio, embora ele rejeite a acusação de que ameaça o Alliance."},pl={title="Gilthares Firebough",body="Gilthares Firebough pracował jako majtek przewożący bimber między Ratchet a Booty Bay. Żołnierze Theramore uwięzili go po zatopieniu statku, choć odrzuca oskarżenie o zagrażanie frakcji Alliance."},ru={title="Gilthares Firebough",body="Gilthares Firebough работал палубным помощником, перевозившим пиво между Ratchet и Booty Bay. Солдаты Theramore заключили его в тюрьму после того, как он потопил свой корабль, хотя он отвергает их обвинения в том, что он угрожает Alliance."},references={["organization:alliance"]=true,["place:booty-bay"]=true,["place:ratchet"]=true,["place:theramore"]=true}},
    ["person:gimashi"] = {title="Gimashi",kind="Personaje",aliases={"Gimashi"},body="Gimashi es una bruja del Filo Ardiente que estudia la draenetista. Su investigación busca aprovechar una sustancia procedente de más allá del Portal Oscuro para los fines de quienes practican las artes oscuras.",aliasQuestIDs={},en={title="Gimashi",aliases={"Gimashi"},body="Gimashi is a Burning Blade warlock studying draenethyst. Her research seeks to harness a substance from beyond the Dark Portal for the purposes of those practicing the dark arts.",aliasQuestIDs={}},fr={title="Gimashi",body="Gimashi est un démoniste Burning Blade étudiant le draenethyste. Sa recherche cherche à exploiter une substance au-delà de la Dark Portal pour les besoins de ceux qui pratiquent les arts sombres."},de={title="Gimashi",body="Gimashi ist ein Burning Blade-Hexenmeister, der Draenethyst studiert. Ihre Forschungen zielen darauf ab, eine Substanz jenseits der Dark Portal für die Ausübung dunkler Künste nutzbar zu machen."},pt={title="Gimashi",body="Gimashi é um bruxo Burning Blade que estuda draenethyst. Sua pesquisa busca aproveitar uma substância além do Dark Portal para os propósitos daqueles que praticam as artes das trevas."},pl={title="Gimashi",body="Gimashi jest czarnoksiężniczką Burning Blade badającą draenethyst. Próbuje wykorzystać substancję zza Dark Portal do celów adeptów mrocznych sztuk."},ru={title="Gimashi",body="Gimashi - это чернокнижник Burning Blade, изучающий дренатист. Ее исследование направлено на использование вещества извне Dark Portal для целей тех, кто практикует темные искусства."},references={["organization:burning-blade"]=true,["place:dark-portal"]=true}},
    ["person:ginro-hearthkindle"] = {title="Ginro Mechogar",kind="Personaje",aliases={"Ginro","Ginro Mechogar"},body="Ginro Mechogar pertenece al entorno del Bastión Plumaluna. Su labor incluye reunir pistas e informes sobre los mensajeros que recorren las costas y caminos de Feralas.",aliasQuestIDs={},en={title="Ginro Hearthkindle",aliases={"Ginro","Ginro Hearthkindle"},body="Ginro Hearthkindle is associated with Feathermoon Stronghold. His work includes gathering clues and reports about messengers traveling the coasts and roads of Feralas.",aliasQuestIDs={}},fr={title="Ginro Hearthkindle",body="Ginro Hearthkindle est associé à Feathermoon Stronghold. Son travail comprend la collecte d'indices et de rapports sur les messagers qui parcourent les côtes et les routes de Feralas."},de={title="Ginro Hearthkindle",body="Ginro Hearthkindle wird mit Feathermoon Stronghold in Verbindung gebracht. Seine Arbeit umfasst das Sammeln von Hinweisen und Berichten über Boten, die Küsten und Straßen von Feralas bereisen."},pt={title="Ginro Hearthkindle",body="Ginro Hearthkindle está associado ao Feathermoon Stronghold. Seu trabalho inclui a coleta de pistas e relatórios sobre mensageiros que viajam pelas costas e estradas de Feralas."},pl={title="Ginro Hearthkindle",body="Ginro Hearthkindle jest związany z Feathermoon Stronghold. Zajmuje się między innymi zbieraniem wskazówek i raportów dotyczących posłańców przemierzających wybrzeża oraz drogi Feralas."},ru={title="Ginro Hearthkindle",body="Ginro Hearthkindle ассоциируется с Feathermoon Stronghold. Его работа включает в себя сбор подсказок и сообщений о посланниках, путешествующих по берегам и дорогам Feralas."},references={["place:feathermoon-stronghold"]=true,["place:feralas"]=true}},
    ["person:gorbold-steelhand"] = {title="Gorbold Mano de Acero",kind="Personaje",aliases={"Gorbold","Gorbold Mano de Acero"},body="Gorbold Mano de Acero trabaja con un puesto de mercaderes de Auberdine. El abastecimiento de los barcos ofrece oportunidades comerciales a su familia, de la que también forma parte su hermano Borgus.",aliasQuestIDs={},en={title="Gorbold Steelhand",aliases={"Gorbold","Gorbold Steelhand"},body="Gorbold Steelhand works with a merchant stall in Auberdine. Supplying ships offers commercial opportunities to his family, which also includes his brother Borgus.",aliasQuestIDs={}},fr={title="Gorbold Steelhand",body="Gorbold Steelhand travaille avec un stand marchand dans Auberdine. Fournir des navires offre des opportunités commerciales à sa famille, qui comprend également son frère Borgus."},de={title="Gorbold Steelhand",body="Gorbold Steelhand arbeitet mit einem Verkaufsstand in Auberdine. Die Lieferung von Schiffen bietet seiner Familie, zu der auch sein Bruder Borgus gehört, kommerzielle Chancen."},pt={title="Gorbold Steelhand",body="Gorbold Steelhand trabalha com uma barraca de comerciante em Auberdine. O fornecimento de navios oferece oportunidades comerciais para sua família, que também inclui seu irmão Borgus."},pl={title="Gorbold Steelhand",body="Gorbold Steelhand pracuje przy straganie kupieckim w Auberdine. Zaopatrywanie statków daje możliwości handlowe rodzinie, do której należy również jego brat Borgus."},ru={title="Gorbold Steelhand",body="Gorbold Steelhand работает с торговым киоском в Auberdine. Поставки кораблей предлагают коммерческие возможности его семье, в которую также входит его брат Borgus."},references={["npc:borgus-steelhand"]=true,["place:auberdine"]=true}},
    ["person:gormarok-the-ravager"] = {title="Gor'marok el Devastador",kind="Personaje",aliases={"Gor'marok","Gor'marok el Devastador","Gor’marok","Gor’marok el Devastador"},body="Gor'marok el Devastador encabeza una banda de ogros nómadas que se ha instalado en Tanaris. Sus seguidores ocupan una base en el desierto y se extienden por las antiguas ruinas troll.",aliasQuestIDs={},en={title="Gor'marok the Ravager",aliases={"Gor'marok","Gor'marok the Ravager","Gor’marok","Gor’marok the Ravager"},body="Gor'marok the Ravager leads a band of nomadic ogres that has settled in Tanaris. His followers occupy a desert compound and spread into the ancient troll ruins.",aliasQuestIDs={}},fr={title="Gor'marok the Ravager",body="Gor'marok the Ravager mène une bande d'ogres nomades qui s'est installée dans Tanaris. Ses disciples occupent un complexe du désert et se propagent dans les anciennes ruines des trolls."},de={title="Gor'marok the Ravager",body="Gor'marok the Ravager führt eine Bande nomadischer Oger an, die sich in Tanaris niedergelassen haben. Seine Anhänger besetzen ein Wüstengelände und breiten sich in den antiken Trollruinen aus."},pt={title="Gor'marok the Ravager",body="Gor'marok the Ravager lidera uma banda de ogros nômades que se estabeleceu em Tanaris. Seus seguidores ocupam um complexo do deserto e se espalham pelas antigas ruínas dos trolls."},pl={title="Gor'marok the Ravager",body="Gor'marok the Ravager prowadzi grupę koczowniczych ogrów osiadłych w Tanaris. Jego zwolennicy zajmują pustynny kompleks i rozprzestrzeniają się w pradawnych ruinach trolli."},ru={title="Gor'marok the Ravager",body="Gor'marok the Ravager возглавляет группу кочевых огров, которые поселились в Tanaris. Его последователи заняли пустынное поселение и распространились на древние руины троллей."},references={["place:tanaris"]=true}},
    ["person:gornek"] = {title="Gornek",kind="Personaje",aliases={"Gornek"},body="Gornek instruye a nuevos aventureros de Durotar desde El Cubil. Sus primeras pruebas están pensadas para fortalecer a los recién llegados sin enviarlos de inmediato contra los peligros de regiones más lejanas.",aliasQuestIDs={},en={title="Gornek",aliases={"Gornek"},body="Gornek instructs new adventurers in Durotar from the Den. His early trials are meant to strengthen newcomers without immediately sending them against the dangers of more distant regions.",aliasQuestIDs={}},fr={title="Gornek",body="Gornek instruit de nouveaux aventuriers en Durotar depuis la tanière. Ses premiers essais visent à renforcer les nouveaux arrivants sans les envoyer immédiatement contre les dangers des régions plus lointaines."},de={title="Gornek",body="Gornek unterrichtet neue Abenteurer in Durotar von der Höhle aus. Seine frühen Versuche sollen Neuankömmlinge stärken, ohne sie sofort gegen die Gefahren aus weiter entfernten Regionen zu schützen zu müssen."},pt={title="Gornek",body="Gornek instrui novos aventureiros em Durotar do Den. Seus primeiros ensaios são destinados a fortalecer os recém-chegados sem enviá-los imediatamente contra os perigos de regiões mais distantes."},pl={title="Gornek",body="Gornek szkoli nowych poszukiwaczy przygód w Durotar, działając z Den. Pierwsze próby mają wzmacniać przybyszów, nie wysyłając ich od razu przeciw niebezpieczeństwom odleglejszych krain."},ru={title="Gornek",body="Gornek обучает новых искателей приключений в Durotar из Логовой. Его первые испытания предназначены для укрепления новичков, не отправляя их сразу против опасностей более отдаленных регионов."},references={["place:durotar"]=true}},
    ["person:gracina-spiritmight"] = {title="Gracina Poderespíritu",kind="Personaje",aliases={"Gracina","Gracina Poderespíritu"},body="Gracina Poderespíritu trabaja desde el Templo de la Luna en Darnassus. Recibe informes sobre amenazas naturales y mantiene contactos que pueden dar a esos hallazgos una atención más amplia dentro de la Alianza.",aliasQuestIDs={},en={title="Gracina Spiritmight",aliases={"Gracina","Gracina Spiritmight"},body="Gracina Spiritmight works from the Temple of the Moon in Darnassus. She receives reports of threats to nature and maintains contacts who can bring those findings to wider attention within the Alliance.",aliasQuestIDs={}},fr={title="Gracina Spiritmight",body="Gracina Spiritmight travaille à partir du Temple of the Moon dans Darnassus. Elle reçoit des rapports de menaces à la nature et maintient des contacts qui peuvent porter ces résultats à une plus grande attention au sein de la Alliance."},de={title="Gracina Spiritmight",body="Gracina Spiritmight arbeitet von der Temple of the Moon in Darnassus aus. Sie erhält Berichte über Bedrohungen der Natur und pflegt Kontakte, die diese Erkenntnisse innerhalb der Alliance einer breiteren Öffentlichkeit zugänglich machen können."},pt={title="Gracina Spiritmight",body="Gracina Spiritmight trabalha a partir do Temple of the Moon em Darnassus. Ela recebe relatos de ameaças à natureza e mantém contatos que podem trazer essas descobertas para uma atenção mais ampla dentro do Alliance."},pl={title="Gracina Spiritmight",body="Gracina Spiritmight działa w Temple of the Moon w Darnassus. Przyjmuje doniesienia o zagrożeniach dla przyrody i utrzymuje kontakty pozwalające zwrócić na te odkrycia szerszą uwagę frakcji Alliance."},ru={title="Gracina Spiritmight",body="Gracina Spiritmight работает из Temple of the Moon в Darnassus. Она получает сообщения об угрозах природе и поддерживает контакты с теми, кто может донести эти выводы до широкого внимания в Alliance."},references={["organization:alliance"]=true,["place:darnassus"]=true,["place:temple-of-the-moon"]=true}},
    ["person:grand-foreman-puzik-gallywix"] = {title="Gran Supervisor Puzik Gallywix",kind="Personaje",aliases={"Gallywix","Gran Supervisor Puzik Gallywix"},body="El gran supervisor Puzik Gallywix mantiene una torre protegida por subordinados como el supervisor Silixiz. Conserva en una caja fuerte reservas del preparado de Zanzil, una sustancia que ha atraído el interés de la Mano Destrozada.",aliasQuestIDs={},en={title="Grand Foreman Puzik Gallywix",aliases={"Gallywix","Grand Foreman Puzik Gallywix"},body="Grand Foreman Puzik Gallywix maintains a tower protected by subordinates such as Foreman Silixiz. He keeps supplies of Zanzil’s mixture in a lockbox, a substance that has drawn the Shattered Hand’s interest.",aliasQuestIDs={}},fr={title="Grand Foreman Puzik Gallywix",body="Grand Foreman Puzik Gallywix maintient une tour protégée par des subordonnés tels que Foreman Silixiz. Il conserve les approvisionnements du mélange de Zanzil dans une boîte à clé, une substance qui a attiré l’intérêt de la Shattered Hand."},de={title="Grand Foreman Puzik Gallywix",body="Grand Foreman Puzik Gallywix unterhält einen Turm, der von Untergebenen wie Vorarbeiter Silixiz geschützt wird. Er verwahrt die Vorräte von Zanzil \"Mischung in einem Schließfach auf, eine Substanz, die das Interesse des Shattered Hand gezogen hat."},pt={title="Grand Foreman Puzik Gallywix",body="Grand Foreman Puzik Gallywix mantém uma torre protegida por subordinados como Foreman Silixiz. Ele mantém suprimentos da mistura de Zanzil em uma caixa de bloqueio, uma substância que atraiu o interesse do Shattered Hand."},pl={title="Grand Foreman Puzik Gallywix",body="Grand Foreman Puzik Gallywix utrzymuje wieżę chronioną przez podwładnych takich jak nadzorca Silixiz. Przechowuje w zamykanej skrzyni zapasy mikstury Zanzil, substancji budzącej zainteresowanie Shattered Hand."},ru={title="Grand Foreman Puzik Gallywix",body="Grand Foreman Puzik Gallywix поддерживает башню, защищенную подчиненными, такими как Форман Silixiz. Он хранит запасы смеси Zanzil  в ящике, вещество, которое вызвало интерес Shattered Hand."},references={["npc:zanzil-outcast"]=true,["organization:shattered-hand"]=true},questIDs={[2478]=true}},
    ["person:grazle"] = {title="Grazle",kind="Personaje",aliases={"Grazle"},body="Grazle es un fúrbolg Fauces de Madera del sur de Frondavil. La violencia sufrida por su pueblo lo hace desconfiar de los forasteros, pero considera la ayuda contra los Muertobosque una señal de buena voluntad.",aliasQuestIDs={},en={title="Grazle",aliases={"Grazle"},body="Grazle is a Timbermaw furbolg in southern Felwood. Violence against his people makes him distrust outsiders, but he regards help against the Deadwood as a sign of goodwill.",aliasQuestIDs={}},fr={title="Grazle",body="Grazle est un furbolg Timbermaw dans le sud Felwood. La violence contre son peuple lui fait se méfier des étrangers, mais il considère l'aide contre le Deadwood comme un signe de bonne volonté."},de={title="Grazle",body="Grazle ist ein Timbermaw Furbolg im südlichen Felwood. Gewalt gegen sein Volk lässt ihn Außenstehenden misstrauen, aber Hilfe gegen den Deadwood betrachtet er als Zeichen guten Willens."},pt={title="Grazle",body="Grazle é um furbolg Timbermaw no sul de Felwood. A violência contra seu povo faz com que ele desconfie de forasteiros, mas ele considera a ajuda contra o Deadwood como um sinal de boa vontade."},pl={title="Grazle",body="Grazle jest furbolgiem społeczności Timbermaw w południowym Felwood. Przemoc wobec jego ludu czyni go nieufnym wobec obcych, lecz pomoc przeciw Deadwood uznaje za oznakę dobrej woli."},ru={title="Grazle",body="Grazle — фурболг Timbermaw в южной части Felwood. Насилие над его народом заставляет его не доверять чужакам, но помощь против Deadwood он считает знаком доброй воли."},references={["organization:deadwood"]=true,["organization:timbermaw"]=true,["place:felwood"]=true}},
    ["person:great-cat-spirit"] = {title="Gran espíritu felino",kind="Personaje",aliases={"Gran espíritu felino"},body="El Gran espíritu felino encarna las cualidades que los druidas aprenden a comprender al adoptar una forma felina. Sus pruebas conceden importancia a la astucia, el sigilo y la ferocidad, siempre unidos al respeto por la naturaleza que expresan.",aliasQuestIDs={},en={title="Great Cat Spirit",aliases={"Great Cat Spirit"},body="The Great Cat Spirit embodies the qualities druids learn to understand when taking a feline form. Its trials value cunning, stealth and ferocity, joined with respect for the nature those qualities express.",aliasQuestIDs={}},fr={title="Great Cat Spirit",body="Le Great Cat Spirit incarne les qualités que les druides apprennent à comprendre lorsqu'ils prennent une forme féline. Ses épreuves valorisent la ruse, la furtivité et la férocité, jointes avec respect pour la nature que ces qualités expriment."},de={title="Great Cat Spirit",body="Der Great Cat Spirit verkörpert die Eigenschaften, die Druiden zu verstehen lernen, wenn sie eine Katzenform annehmen. Seine Prüfungen schätzen List, Heimlichkeit und Wildheit, verbunden mit Respekt vor der Natur, die diese Eigenschaften zum Ausdruck bringen."},pt={title="Great Cat Spirit",body="O Great Cat Spirit incorpora as qualidades que os druidas aprendem a entender ao tomar uma forma felina. Seus ensaios valorizam astúcia, furtividade e ferocidade, unidos com respeito pela natureza que essas qualidades expressam."},pl={title="Great Cat Spirit",body="Great Cat Spirit ucieleśnia cechy, które druidzi uczą się rozumieć przy przyjmowaniu kociej postaci. Jego próby cenią przebiegłość, skradanie i zaciekłość połączone z szacunkiem dla wyrażanej przez te cechy natury."},ru={title="Great Cat Spirit",body="Great Cat Spirit воплощает качества, которые друиды узнают, когда принимают форму кошки. В его испытаниях ценятся хитрость, скрытность и жестокость, соединенные с уважением к природе, которую эти качества выражают."},references={}},
    ["person:gregan-brewspewer"] = {title="Gregan Tirabirras",kind="Personaje",aliases={"Gregan","Gregan Tirabirras"},body="Gregan Tirabirras vive apartado en las tierras salvajes de Feralas. Posee conocimientos sobre preparados poco comunes, incluido el Elixir de Videre, por los que otros viajeros buscan su ayuda.",aliasQuestIDs={},en={title="Gregan Brewspewer",aliases={"Gregan","Gregan Brewspewer"},body="Gregan Brewspewer lives apart in the wilds of Feralas. He possesses knowledge of unusual preparations, including the Videre Elixir, for which other travelers seek his help.",aliasQuestIDs={}},fr={title="Gregan Brewspewer",body="Gregan Brewspewer vit à part dans la nature sauvage de Feralas. Il possède des connaissances sur les préparatifs inhabituels, y compris le Videre Elixir, pour lesquels d'autres voyageurs demandent son aide."},de={title="Gregan Brewspewer",body="Gregan Brewspewer lebt getrennt in der Wildnis von Feralas. Er besitzt Kenntnisse über ungewöhnliche Vorbereitungen, unter anderem für den Videre Elixir, für den andere Reisende seine Hilfe suchen."},pt={title="Gregan Brewspewer",body="Gregan Brewspewer vive à parte nas selvas de Feralas. Ele possui conhecimento de preparações incomuns, incluindo o Videre Elixir, para o qual outros viajantes procuram sua ajuda."},pl={title="Gregan Brewspewer",body="Gregan Brewspewer mieszka na uboczu w dziczy Feralas. Zna niezwykłe preparaty, w tym Videre Elixir, z powodu których inni podróżnicy zwracają się do niego o pomoc."},ru={title="Gregan Brewspewer",body="Gregan Brewspewer живет в дикой природе Feralas. Он обладает знаниями необычных приготовлений, в том числе Videre Elixir, для которых другие путешественники ищут его помощи."},references={["place:feralas"]=true}},
    ["person:greta-mosshoof"] = {title="Greta Pezuñamusgo",kind="Personaje",aliases={"Greta","Greta Pezuñamusgo"},body="Greta Pezuñamusgo combate la corrupción de Frondavil. Sus esfuerzos se dirigen contra el Consejo de la Sombra y hacia la búsqueda de remedios para la tierra y las criaturas dañadas.",aliasQuestIDs={},en={title="Greta Mosshoof",aliases={"Greta","Greta Mosshoof"},body="Greta Mosshoof fights Felwood’s corruption. Her efforts target the Shadow Council and seek remedies for the damaged land and creatures.",aliasQuestIDs={}},fr={title="Greta Mosshoof",body="Greta Mosshoof combat la corruption de Felwood. Ses efforts ciblent le Shadow Council et cherchent des remèdes pour la terre et les créatures endommagées."},de={title="Greta Mosshoof",body="Greta Mosshoof kämpft gegen Felwoods Korruption. Ihre Bemühungen zielen auf die Shadow Council ab und suchen nach Heilmitteln für das beschädigte Land und die Kreaturen."},pt={title="Greta Mosshoof",body="O Greta Mosshoof combate a corrupção do Felwood. Seus esforços visam o Shadow Council e buscar remédios para a terra danificada e criaturas."},pl={title="Greta Mosshoof",body="Greta Mosshoof walczy ze skażeniem Felwood. Jej działania są wymierzone w Shadow Council i służą szukaniu środków zaradczych dla zniszczonej ziemi oraz stworzeń."},ru={title="Greta Mosshoof",body="Greta Mosshoof борется с порчей Felwood. Ее усилия направлены на Shadow Council и искать средства для устранения повреждений земли и существ."},references={["organization:shadow-council"]=true,["place:felwood"]=true}},
    ["person:grinkle"] = {title="Grinkle",kind="Personaje",aliases={"Grinkle"},body="Grinkle promueve la pesca desde Orgrimmar. Difunde el concurso de Bahía del Botín y entrega folletos con sus normas a quienes desean conocer la competición.",aliasQuestIDs={},en={title="Grinkle",aliases={"Grinkle"},body="Grinkle promotes fishing from Orgrimmar. He publicizes the Booty Bay contest and hands out fliers explaining its rules to prospective participants.",aliasQuestIDs={}},fr={title="Grinkle",body="Grinkle favorise la pêche de Orgrimmar. Il fait connaître le concours Booty Bay et distribue des dépliants expliquant ses règles aux participants potentiels."},de={title="Grinkle",body="Grinkle wirbt bei Orgrimmar für das Angeln. Er macht auf den Booty Bay-Wettbewerb aufmerksam und verteilt Flyer, in denen die Regeln erklärt werden."},pt={title="Grinkle",body="Grinkle promove a pesca de Orgrimmar. Ele divulga o concurso Booty Bay e distribui panfletos explicando suas regras para possíveis participantes."},pl={title="Grinkle",body="Grinkle promuje wędkarstwo w Orgrimmar. Rozgłasza wieści o zawodach w Booty Bay i rozdaje potencjalnym uczestnikom ulotki wyjaśniające zasady."},ru={title="Grinkle",body="Grinkle продвигает рыбную ловлю из Orgrimmar. Он объявляет о конкурсе Booty Bay и раздает листовки, объясняющие правила для потенциальных участников."},references={["place:booty-bay"]=true,["place:orgrimmar"]=true}},
    ["person:grish-longrunner"] = {title="Grish Largo Camino",kind="Personaje",aliases={"Grish","Grish Largo Camino"},body="Grish Largo Camino protege El Gran Elevador, en el sur de Los Baldíos. Su servicio muestra la vida de los guardias que sostienen los puestos de la Horda mientras esperan una oportunidad de regresar junto a sus familias.",aliasQuestIDs={},en={title="Grish Longrunner",aliases={"Grish","Grish Longrunner"},body="Grish Longrunner guards the Great Lift in the southern Barrens. His service reflects the lives of the guards maintaining Horde posts while awaiting a chance to return to their families.",aliasQuestIDs={}},fr={title="Grish Longrunner",body="Grish Longrunner garde le Great Lift dans le sud Barrens. Son service reflète la vie des gardes qui maintiennent des postes Horde en attendant une chance de retourner auprès de leurs familles."},de={title="Grish Longrunner",body="Grish Longrunner bewacht den Great Lift im südlichen Barrens. Sein Dienst spiegelt das Leben der Wachen wider, die Horde Posten innehatten, während sie auf eine Chance warteten, zu ihren Familien zurückzukehren."},pt={title="Grish Longrunner",body="Grish Longrunner protege o Great Lift no sul do Barrens. Seu serviço reflete a vida dos guardas que mantêm postos Horde enquanto aguardam uma chance de retornar às suas famílias."},pl={title="Grish Longrunner",body="Grish Longrunner strzeże Great Lift w południowym Barrens. Służba odzwierciedla życie strażników utrzymujących posterunki frakcji Horde w oczekiwaniu na możliwość powrotu do rodzin."},ru={title="Grish Longrunner",body="Grish Longrunner охраняет Great Lift в южной части Barrens. Его служба отражает жизнь охранников, которые поддерживают позиции Horde, ожидая шанса вернуться к своим семьям."},references={["organization:horde"]=true,["place:great-lift"]=true,["place:the-barrens"]=true}},
    ["person:grull-hawkwind"] = {title="Grull Viento de Halcón",kind="Personaje",aliases={"Grull","Grull Viento de Halcón"},body="Grull Viento de Halcón instruye a los tauren del Campamento Narache. Enseña que la caza debe sostener a la comunidad: las pieles y otros recursos sirven para vestir a los niños y reparar las tiendas.",aliasQuestIDs={},en={title="Grull Hawkwind",aliases={"Grull","Grull Hawkwind"},body="Grull Hawkwind instructs the tauren of Camp Narache. He teaches that hunting should sustain the community: hides and other resources clothe children and repair the tents.",aliasQuestIDs={}},fr={title="Grull Hawkwind",body="Grull Hawkwind commande le tauren de Camp Narache. Il enseigne que la chasse devrait soutenir la communauté: les peaux et autres ressources vêtissent les enfants et réparent les tentes."},de={title="Grull Hawkwind",body="Grull Hawkwind unterrichtet den Tauren von Camp Narache. Er lehrt, dass die Jagd die Gemeinschaft erhalten sollte: Verstecke und andere Ressourcen kleiden die Kinder und die Zelte reparieren."},pt={title="Grull Hawkwind",body="Grull Hawkwind instrui o tauren de Camp Narache. Ele ensina que a caça deve sustentar a comunidade: esconde e outros recursos vestir as crianças e reparar as tendas."},pl={title="Grull Hawkwind",body="Grull Hawkwind szkoli taurenów w Camp Narache. Uczy, że polowanie powinno utrzymywać społeczność: skóry i inne zasoby służą do odziewania dzieci oraz naprawiania namiotów."},ru={title="Grull Hawkwind",body="Grull Hawkwind дает инструкции таурену Camp Narache. Он учит, что охота должна поддерживать сообщество: шкуры и другие ресурсы одевают детей и ремонтируют палатки."},references={["place:camp-narache"]=true}},
    ["person:grundig-darkcloud"] = {title="Grundig Nube Negra",kind="Personaje",aliases={"Grundig","Grundig Nube Negra"},body="Grundig Nube Negra dirige una banda de Tótem Siniestro. Su responsabilidad en un ataque contra una aldea lo ha convertido en un enemigo especialmente temido por quienes han sufrido la violencia de sus seguidores.",aliasQuestIDs={},en={title="Grundig Darkcloud",aliases={"Grundig","Grundig Darkcloud"},body="Grundig Darkcloud commands a Grimtotem band. His role in an attack on a village has made him particularly feared by those who have suffered his followers’ violence.",aliasQuestIDs={}},fr={title="Grundig Darkcloud",body="Grundig Darkcloud commande une bande Grimtotem. Son rôle dans une attaque contre un village l’a rendu particulièrement craint par ceux qui ont subi la violence de ses partisans."},de={title="Grundig Darkcloud",body="Grundig Darkcloud befehligt eine Grimtotem Band. Seine Rolle bei einem Angriff auf ein Dorf hat ihn bei denjenigen, die Gewalt seiner Anhänger erlitten haben, besonders gefürchtet."},pt={title="Grundig Darkcloud",body="Grundig Darkcloud comanda uma banda Grimtotem. Seu papel em um ataque a uma aldeia o tornou particularmente temido por aqueles que sofreram a violência de seus seguidores."},pl={title="Grundig Darkcloud",body="Grundig Darkcloud dowodzi grupą Grimtotem. Udział w ataku na wioskę uczynił go szczególnie przerażającym dla osób, które doświadczyły przemocy jego zwolenników."},ru={title="Grundig Darkcloud",body="Grundig Darkcloud командует группой Grimtotem. Его роль в нападении на деревню сделала его особенно опасным для тех, кто подвергался насилию его последователей."},references={}},
    ["person:grunt-dogran"] = {title="Dogran",kind="Personaje",aliases={"Dogran"},body="El bruto Dogran es un soldado de la Horda destinado en Los Baldíos. Sus vínculos con Orgrimmar recuerdan que detrás de los traslados y patrullas también hay personas que esperan noticias de quienes parten.",aliasQuestIDs={},en={title="Dogran",aliases={"Dogran"},body="Grunt Dogran is a Horde soldier stationed in the Barrens. His ties to Orgrimmar are a reminder that behind transfers and patrols are people waiting for news of those who leave.",aliasQuestIDs={}},fr={title="Dogran",body="Grunt Dogran est un soldat Horde stationné dans le Barrens. Ses liens avec Orgrimmar rappellent que derrière les transferts et les patrouilles, il y a des gens qui attendent des nouvelles de ceux qui partent."},de={title="Dogran",body="Grunt Dogran ist ein Horde Soldat, der im Barrens stationiert ist. Seine Verbindungen zu Orgrimmar sind eine Erinnerung daran, dass hinter Transfers und Patrouillen Menschen stehen, die auf Nachrichten von denen warten, die abwarten, die weggehen."},pt={title="Dogran",body="Grunt Dogran é um soldado Horde estacionado no Barrens. Seus laços com o Orgrimmar são um lembrete de que por trás de transferências e patrulhas estão pessoas esperando notícias daqueles que saem."},pl={title="Dogran",body="Dogran jest żołnierzem frakcji Horde stacjonującym w regionie Barrens. Więzi z Orgrimmar przypominają, że za przeniesieniami i patrolami stoją ludzie czekający na wieści o tych, którzy wyruszyli."},ru={title="Dogran",body="Грант Dogran - солдат Horde, дислоцированный в Barrens. Его связи с Orgrimmar напоминают, что за перемещениями и патрулями стоят люди, ожидающие новостей о тех, кто уезжает."},references={["organization:horde"]=true,["place:orgrimmar"]=true,["place:the-barrens"]=true}},
    ["person:grunt-korja"] = {title="Bruto Kor'ja",kind="Personaje",aliases={"Bruto Kor'ja","Bruto Kor’ja","Kor'ja","Kor’ja"},body="Kor'ja defiende los alrededores de Cerrotajo como bruta de la Horda. Los enfrentamientos con las antiguas tropas de Valiente muestran los riesgos de su servicio y su necesidad del apoyo espiritual de los sacerdotes trols.",aliasQuestIDs={},en={title="Grunt Kor'ja",aliases={"Grunt Kor'ja","Grunt Kor’ja","Kor'ja","Kor’ja"},body="Kor'ja defends the area around Razor Hill as a Horde grunt. Fighting Proudmoore’s former troops reveals the dangers of her service and her need for support from troll priests.",aliasQuestIDs={}},fr={title="Grunt Kor'ja",body="Kor'ja défend la zone autour de Razor Hill en tant que grunt Horde. Combattre les anciennes troupes de Proudmoore révèle les dangers de son service et son besoin de soutien des prêtres trolls."},de={title="Grunt Kor'ja",body="Kor'ja verteidigt die Gegend um Razor Hill als Horde, die grungehalten wird. Der Kampf gegen Proudmoores ehemalige Truppen offenbart die Gefahren ihres Dienstes und ihren Bedarf an Unterstützung durch Trollpriester."},pt={title="Grunt Kor'ja",body="Kor'ja defende a área em torno de Razor Hill como um grunhido Horde. Combater as antigas tropas da Proudmoore revela os perigos de seu serviço e sua necessidade de apoio de padres troll."},pl={title="Grunt Kor'ja",body="Kor'ja broni okolic Razor Hill jako żołnierka frakcji Horde. Walki z dawnymi wojskami rodu Proudmoore ukazują niebezpieczeństwa służby i potrzebę wsparcia trollich kapłanów."},ru={title="Grunt Kor'ja",body="Kor'ja защищает область вокруг Razor Hill как Horde гручит. Борьба с бывшими войсками Proudmoore  раскрывает опасности ее службы и ее потребность в поддержке от жрецов троллей."},references={["organization:horde"]=true,["place:razor-hill"]=true}},
    ["person:grunt-logmar"] = {title="Bruto Logmar",kind="Personaje",aliases={"Bruto Logmar","Logmar","bruto Logmar"},body="El bruto Logmar sirve en el Campamento Taurajo. Participa tanto en la vigilancia de los conflictos de Los Baldíos como en las redes de ayuda a los soldados que resultan heridos lejos de los poblados.",aliasQuestIDs={},en={title="Grunt Logmar",aliases={"Grunt Logmar","Logmar"},body="Grunt Logmar serves at Camp Taurajo. He takes part both in watching conflicts in the Barrens and in networks helping soldiers injured far from settlements.",aliasQuestIDs={}},fr={title="Grunt Logmar",body="Grunt Logmar sert à Camp Taurajo. Il participe à la fois à l’observation des conflits dans le Barrens et à des réseaux d’aide aux soldats blessés loin des colonies."},de={title="Grunt Logmar",body="Grunt Logmar dient in Camp Taurajo. Er beobachtet Konflikte in den Barrens und ist zugleich an Netzwerken beteiligt, die fernab der Siedlungen verwundeten Soldaten helfen."},pt={title="Grunt Logmar",body="Grunt Logmar serve no Camp Taurajo. Ele participa tanto na observação de conflitos no BarrensQ e em redes que ajudam soldados feridos longe dos assentamentos."},pl={title="Grunt Logmar",body="Grunt Logmar służy w Camp Taurajo. Uczestniczy zarówno w obserwowaniu konfliktów regionu Barrens, jak i w sieciach pomocy żołnierzom rannym daleko od osad."},ru={title="Grunt Logmar",body="Grunt Logmar служит в Camp Taurajo. Он участвует как в наблюдении за конфликтами в Barrens, так и в сетях помощи раненым солдатам вдали от населенных пунктов."},references={["place:camp-taurajo"]=true,["place:the-barrens"]=true}},
    ["person:grunt-maug"] = {title="Bruto Maug",kind="Personaje",aliases={"Bruto Maug","Maug","bruto Maug"},body="El bruto Maug ha sido encargado de reunir estaño para la Horda. Aunque preferiría preparar armas y armaduras, su trabajo ayuda a obtener los metales necesarios para la movilización hacia Ahn'Qiraj.",aliasQuestIDs={},en={title="Grunt Maug",aliases={"Grunt Maug","Maug"},body="Grunt Maug has been assigned to gather tin for the Horde. Although he would prefer preparing weapons and armor, his work helps obtain the metals needed for the mobilization toward Ahn'Qiraj.",aliasQuestIDs={}},fr={title="Grunt Maug",body="Grunt Maug a été assigné pour rassembler l'étain pour le Horde. Bien qu'il préfère préparer des armes et des armures, son travail aide à obtenir les métaux nécessaires à la mobilisation vers Ahn'Qiraj."},de={title="Grunt Maug",body="Grunt Maug wurde beauftragt, Blech für den Horde zu sammeln. Obwohl er es vorziehen würde, Waffen und Rüstung vorzubereiten, trägt seine Arbeit dazu bei, das Metall zu erhalten, das für die für die Mobilisierung zu Ahn'Qiraj zu erhalten."},pt={title="Grunt Maug",body="Grunt Maug foi designado para recolher estanho para o Horde. Embora ele prefira preparar armas e armaduras, seu trabalho ajuda a obter os metais necessários para a mobilização em direção a Ahn'Qiraj."},pl={title="Grunt Maug",body="Grunt Maug otrzymał zadanie zbierania cyny dla frakcji Horde. Choć wolałby przygotowywać broń i zbroje, jego praca pomaga zdobywać metale potrzebne do mobilizacji ku Ahn'Qiraj."},ru={title="Grunt Maug",body="Grunt Maug был назначен собирать олово для Horde. Хотя он предпочитает готовить оружие и доспехи, его работа помогает получить металлы, необходимые для мобилизации к Ahn'Qiraj."},references={["organization:horde"]=true,["place:ahnqiraj"]=true}},
    ["person:gubber-blump"] = {title="Gubber Blump",kind="Personaje",aliases={"Gubber","Gubber Blump"},body="Gubber Blump es un pescador de Auberdine con un gran entusiasmo por la cocina de cangrejo. Sus preferencias vinculan la pesca y los recursos de la playa con la vida cotidiana del puerto.",aliasQuestIDs={},en={title="Gubber Blump",aliases={"Gubber","Gubber Blump"},body="Gubber Blump is an Auberdine fisherman with great enthusiasm for crab cookery. His preferences connect fishing and beach resources with the port’s everyday life.",aliasQuestIDs={}},fr={title="Gubber Blump",body="Gubber Blump est un pêcheur Auberdine avec un grand enthousiasme pour la cuisine du crabe. Ses préférences lient la pêche et les ressources de la plage à la vie quotidienne du port."},de={title="Gubber Blump",body="Gubber Blump ist ein Auberdine Fischer mit großer Begeisterung für die Krabbenküche. Seine Vorlieben verbinden Fischerei und Strandressourcen mit dem Alltag des Hafens."},pt={title="Gubber Blump",body="Gubber Blump é um pescador Auberdine com grande entusiasmo pela culinária de caranguejos. Suas preferências conectam a pesca e os recursos da praia com a vida cotidiana do porto."},pl={title="Gubber Blump",body="Gubber Blump jest wędkarzem z Auberdine z wielkim zamiłowaniem do potraw z krabów. Jego upodobania łączą wędkarstwo i zasoby plaż z codziennym życiem portu."},ru={title="Gubber Blump",body="Gubber Blump - рыбак Auberdine с большим энтузиазмом к крабовой кухне. Его предпочтения связывают рыболовство и пляжные ресурсы с повседневной жизнью порта."},references={["place:auberdine"]=true}},
    ["person:gwennyth-blyleggonde"] = {title="Gwennyth Bly'Leggonde",kind="Personaje",aliases={"Gwennyth","Gwennyth Bly'Leggonde","Gwennyth Bly’Leggonde"},body="Gwennyth Bly'Leggonde investiga los animales marinos que aparecen varados en Costa Oscura. Las muestras de sus restos le permiten estudiar un problema que afecta a las playas cercanas a Auberdine.",aliasQuestIDs={},en={title="Gwennyth Bly'Leggonde",aliases={"Gwennyth","Gwennyth Bly'Leggonde","Gwennyth Bly’Leggonde"},body="Gwennyth Bly'Leggonde investigates marine animals found stranded on Darkshore. Samples from their remains help her study a problem affecting the beaches near Auberdine.",aliasQuestIDs={}},fr={title="Gwennyth Bly'Leggonde",body="Gwennyth Bly'Leggonde étudie les animaux marins trouvés échoués sur Darkshore. Des échantillons de leurs restes l'aident à étudier un problème affectant les plages près de Auberdine."},de={title="Gwennyth Bly'Leggonde",body="Gwennyth Bly'Leggonde untersucht Meerestiere, die auf Darkshore gestrandet sind. Proben ihrer sterblichen Überreste helfen ihr, ein Problem an den Stränden nahe Auberdine zu untersuchen."},pt={title="Gwennyth Bly'Leggonde",body="Gwennyth Bly'Leggonde investiga animais marinhos encontrados encalhados no Darkshore. Amostras de seus restos mortais a ajudam a estudar um problema que afeta as praias perto de Auberdine."},pl={title="Gwennyth Bly'Leggonde",body="Gwennyth Bly'Leggonde bada zwierzęta morskie wyrzucone na brzeg Darkshore. Próbki ich szczątków pomagają jej poznawać problem dotykający plaże w pobliżu Auberdine."},ru={title="Gwennyth Bly'Leggonde",body="Gwennyth Bly'Leggonde расследует морских животных, найденных на Darkshore. Образцы из их останков помогают ей изучить проблему, затрагивающую пляжи возле Auberdine."},references={["place:auberdine"]=true,["place:darkshore"]=true}},
    ["person:hadoken-swiftstrider"] = {title="Hadoken Zanco Veloz",kind="Personaje",aliases={"Hadoken","Hadoken Zanco Veloz"},body="Hadoken Zanco Veloz organiza la respuesta de la Horda a amenazas de Feralas. Sus planes contra los gnolls buscan actuar sobre sus líderes para alterar la coordinación de las bandas.",aliasQuestIDs={},en={title="Hadoken Swiftstrider",aliases={"Hadoken","Hadoken Swiftstrider"},body="Hadoken Swiftstrider organizes the Horde’s response to threats in Feralas. His plans against gnolls target their leaders to disrupt the coordination of their bands.",aliasQuestIDs={}},fr={title="Hadoken Swiftstrider",body="Hadoken Swiftstrider organise la réponse du Horde aux menaces dans Feralas. Ses plans contre les gnolls visent leurs dirigeants pour perturber la coordination de leurs bandes."},de={title="Hadoken Swiftstrider",body="Hadoken Swiftstrider organisiert die Reaktion des Horde auf Bedrohungen in Feralas. Seine Pläne gegen die Gnolls zielen auf ihre Anführer ab, um die Koordination ihrer Gruppen zu stören."},pt={title="Hadoken Swiftstrider",body="Hadoken Swiftstrider organiza a resposta do Horde às ameaças no Feralas. Seus planos contra os gnolls visam seus líderes para interromper a coordenação de suas bandas."},pl={title="Hadoken Swiftstrider",body="Hadoken Swiftstrider organizuje odpowiedź frakcji Horde na zagrożenia w Feralas. Jego plany przeciw gnollom są wymierzone w ich przywódców, by zakłócić koordynację grup."},ru={title="Hadoken Swiftstrider",body="Hadoken Swiftstrider организует ответ Horde  на угрозы в Feralas. Его планы против гнолов направлены на их лидеров, чтобы нарушить координацию их групп."},references={["organization:horde"]=true,["place:feralas"]=true}},
    ["person:hagar-lightninghoof"] = {title="Hagar Pezuña del Rayo",kind="Personaje",aliases={"Hagar","Hagar Pezuña del Rayo"},body="Hagar Pezuña del Rayo investiga criaturas y objetos extraños desde el Poblado Viento Libre. Su interés por huevos poco comunes lo lleva a buscar pruebas en las guaridas y riscos de Las Mil Agujas.",aliasQuestIDs={},en={title="Hagar Lightninghoof",aliases={"Hagar","Hagar Lightninghoof"},body="Hagar Lightninghoof investigates unusual creatures and objects from Freewind Post. His interest in uncommon eggs leads him to seek evidence in Thousand Needles’ dens and cliffs.",aliasQuestIDs={}},fr={title="Hagar Lightninghoof",body="Hagar Lightninghoof enquête sur des créatures et des objets inhabituels de Freewind Post. Son intérêt pour les œufs rares l’amène à chercher des preuves dans les tanières et les falaises de Thousand Needles."},de={title="Hagar Lightninghoof",body="Hagar Lightninghoof untersucht ungewöhnliche Geschöpfe und Gegenstände von Freewind Post. Sein Interesse an ungewöhnlichen Eiern veranlasst ihn, in Thousand Needles 'Höhlen und Klippen nach Beweisen zu suchen."},pt={title="Hagar Lightninghoof",body="Hagar Lightninghoof investiga criaturas e objetos incomuns de Freewind Post. Seu interesse em ovos incomuns o leva a buscar evidências em tocas e penhascos do Thousand Needles."},pl={title="Hagar Lightninghoof",body="Hagar Lightninghoof bada niezwykłe stworzenia i przedmioty z Freewind Post. Zainteresowanie nietypowymi jajami skłania go do poszukiwania dowodów w legowiskach i na klifach Thousand Needles."},ru={title="Hagar Lightninghoof",body="Hagar Lightninghoof исследует необычные существа и объекты из Freewind Post. Его интерес к необычным яйцам приводит его искать доказательства в Thousand Needles  ловушках и скалах."},references={["place:freewind-post"]=true,["place:thousand-needles"]=true},questIDs={[4821]=true,[4865]=true}},
    ["person:halea"] = {title="Halea",kind="Personaje",aliases={"Halea"},body="Halea es una encantadora de los Gelkis en Desolace. Aprovecha la magia de las armas recuperadas para preparar materiales con los que reforzar el equipo de su comunidad, especialmente el de sus cazavientos.",aliasQuestIDs={},en={title="Halea",aliases={"Halea"},body="Halea is a Gelkis enchanter in Desolace. She draws on the magic of recovered weapons to prepare materials for strengthening her community’s equipment, especially that of its windchasers.",aliasQuestIDs={}},fr={title="Halea",body="Halea est un enchanteur Gelkis dans Desolace. Elle s’appuie sur la magie des armes récupérées pour préparer du matériel pour renforcer l’équipement de sa communauté, en particulier celui de ses chasseurs à vent."},de={title="Halea",body="Halea ist eine Gelkis-Verzaubererin in Desolace. Sie nutzt die Magie der wiedergewonnenen Waffen, um Materialien für die Stärkung der Ausrüstung ihrer Gemeinschaft vorzubereiten, insbesondere der Windjäger."},pt={title="Halea",body="Halea é um encantador Gelkis em Desolace. Ela se baseia na magia das armas recuperadas para preparar materiais para fortalecer o equipamento de sua comunidade, especialmente o de seus windchasers."},pl={title="Halea",body="Halea jest zaklinaczką klanu Gelkis w Desolace. Czerpie z magii odzyskanej broni, przygotowując materiały wzmacniające wyposażenie społeczności, szczególnie jej łowców wiatru."},ru={title="Halea",body="Halea - это Gelkis волшебник в Desolace. Она использует магию найденного оружия для подготовки материалов для укрепления оборудования своей общины, особенно для ее ловцов ветра."},references={["organization:gelkis"]=true,["place:desolace"]=true}},
    ["person:haleh"] = {title="Haleh",kind="Personaje",aliases={"Haleh"},body="Haleh es una protectora del Vuelo Azul en Cuna del Invierno, vinculada a las cavernas de Mazthoril. Sus aliados recurren a ella cuando necesitan que una autoridad de su vuelo conozca amenazas o abusos contra los suyos.",aliasQuestIDs={},en={title="Haleh",aliases={"Haleh"},body="Haleh is a protector of the Blue Dragonflight in Winterspring associated with the Mazthoril caves. Her allies turn to her when an authority of their flight must learn of threats or abuses against their kin.",aliasQuestIDs={}},fr={title="Haleh",body="Haleh est un protecteur du Blue Dragonflight dans Winterspring associé aux grottes Mazthoril. Ses alliés se tournent vers elle quand une autorité de leur fuite doit apprendre des menaces ou des abus contre leurs proches."},de={title="Haleh",body="Haleh ist die Beschützerin der Blue Dragonflight in Winterspring, die mit den Höhlen von Mazthoril in Verbindung steht. Ihre Verbündeten wenden sich an sie, wenn eine Autorität ihrer Flucht von Drohungen oder Misshandlungen gegen ihre Angehörigen erfahren muss."},pt={title="Haleh",body="Haleh é um protetor do Blue Dragonflight em Winterspring associado às cavernas Mazthoril. Seus aliados se voltam para ela quando uma autoridade de seu voo deve aprender sobre ameaças ou abusos contra seus parentes."},pl={title="Haleh",body="Haleh jest obrończynią Blue Dragonflight w Winterspring związaną z jaskiniami Mazthoril. Sojusznicy zwracają się do niej, gdy władza ich rodu musi poznać zagrożenia lub nadużycia wobec jego krewnych."},ru={title="Haleh",body="Haleh является защитником Blue Dragonflight в Winterspring, связанных с пещерами Mazthoril. Ее союзники обращаются к ней, когда власть их бегства должна узнать об угрозах или злоупотреблениях против их родственников."},references={["organization:blue-dragonflight"]=true,["place:winterspring"]=true}},
    ["person:halikor"] = {title="Halikor",kind="Personaje",aliases={"Halikor"},body="Halikor es un poderoso lagarto de grandes pezuñas. Una pezuña suya se reconoce como un trofeo que demuestra su derrota.",aliasQuestIDs={},en={title="Halikor",aliases={"Halikor"},body="Halikor is a powerful lizard with enormous hooves. One of its hooves is recognized as a trophy proving its defeat.",aliasQuestIDs={}},fr={title="Halikor",body="Halikor est un lézard puissant avec d'énormes sabots. Un de ses sabots est reconnu comme un trophée prouvant sa défaite."},de={title="Halikor",body="Halikor ist eine kräftige Eidechse mit enormen Hufen. Einer seiner Hufe wird als Trophäe erkannt, die seine Niederlage beweist."},pt={title="Halikor",body="Halikor é um lagarto poderoso com enormes cascos. Um de seus cascos é reconhecido como um troféu provando sua derrota."},pl={title="Halikor",body="Halikor jest potężnym jaszczurem o ogromnych kopytach. Jedno z jego kopyt jest uznawane za trofeum potwierdzające jego pokonanie."},ru={title="Halikor",body="Halikor - мощная ящерица с огромными копытами. Один из копытов считается трофеем, доказывающим поражение."},references={}},
    ["person:hamuul-runetotem"] = {title="Hamuul Tótem de Runa",kind="Personaje",aliases={"Hamuul","Hamuul Tótem de Runa"},body="Hamuul Tótem de Runa es un archidruida tauren de Cima del Trueno, vinculado al Círculo Cenarion. Desde el Alto de los Ancestros recibe informes y dirige investigaciones relacionadas con el mundo natural.",aliasQuestIDs={},en={title="Hamuul Runetotem",aliases={"Hamuul","Hamuul Runetotem"},body="Hamuul Runetotem is a tauren archdruid in Thunder Bluff associated with the Cenarion Circle. From Elder Rise, he receives reports and directs investigations concerning the natural world.",aliasQuestIDs={}},fr={title="Hamuul Runetotem",body="Hamuul Runetotem est un archidruide tauren dans Thunder Bluff associé au Cenarion Circle. De Elder Rise, il reçoit des rapports et dirige des enquêtes concernant le monde naturel."},de={title="Hamuul Runetotem",body="Hamuul Runetotem ist ein Tauren-Erzdruide in Thunder Bluff, der mit dem Cenarion Circle in Verbindung gebracht wird. Von Elder Rise erhält er Berichte und leitet Nachforschungen über die natürliche Welt."},pt={title="Hamuul Runetotem",body="Hamuul Runetotem é um archdruid tauren no Thunder Bluff associado ao Cenarion Circle. De Elder Rise, ele recebe relatórios e dirige investigações sobre o mundo natural."},pl={title="Hamuul Runetotem",body="Hamuul Runetotem jest taurenskim arcydruidem w Thunder Bluff związanym z Cenarion Circle. Z Elder Rise przyjmuje raporty i kieruje badaniami dotyczącymi świata przyrody."},ru={title="Hamuul Runetotem",body="Hamuul Runetotem — таурен-верховный друид из Thunder Bluff, связанный с Cenarion Circle. На Elder Rise он получает донесения и руководит расследованиями, касающимися мира природы."},references={["organization:cenarion-circle"]=true,["place:thunder-bluff"]=true}},
    ["person:hanazua"] = {title="Hana'zua",kind="Personaje",aliases={"Hana'zua","Hana’zua"},body="Hana'zua es un cazador del Valle de los Retos. Su enfrentamiento con Sarkoth muestra el peligro de los escórpidos de Durotar y la importancia que el honor tiene para quienes prueban su fuerza allí.",aliasQuestIDs={},en={title="Hana'zua",aliases={"Hana'zua","Hana’zua"},body="Hana'zua is a hunter in the Valley of Trials. His encounter with Sarkoth shows the danger of Durotar’s scorpids and the importance of honor to those testing their strength there.",aliasQuestIDs={}},fr={title="Hana'zua",body="Hana'zua est un chasseur dans le Valley of Trials. Sa rencontre avec Sarkoth montre le danger des scorpions de Durotar et l'importance de l'honneur pour ceux qui testent leur force là-bas."},de={title="Hana'zua",body="Hana'zua ist Jäger im Valley of Trials. Seine Begegnung mit Sarkoth zeigt die Gefahr der Skorpide Durotar und die Bedeutung der Ehre für diejenigen, die dort ihre Kräfte testen."},pt={title="Hana'zua",body="Hana'zua é um caçador no Valley of Trials. Seu encontro com o Sarkoth mostra o perigo dos escrúpulos do Durotar e a importância da honra para aqueles que testam sua força lá."},pl={title="Hana'zua",body="Hana'zua jest łowcą w Valley of Trials. Spotkanie z bestią Sarkoth pokazuje niebezpieczeństwo skorpionów Durotar i znaczenie honoru dla osób sprawdzających tam własną siłę."},ru={title="Hana'zua",body="Hana'zua - охотник в Valley of Trials. Его встреча с Sarkoth показывает опасность скорпидов Durotar  и важность чести для тех, кто испытывает там свою силу."},references={["person:sarkoth"]=true,["place:durotar"]=true,["place:valley-of-trials"]=true}},
    ["person:harb-clawhoof"] = {title="Harb Garrapezuña",kind="Personaje",aliases={"Harb","Harb Garrapezuña"},body="Harb ofrece kodos de monta en Mulgore. Entre los animales que proporciona hay kodos de pelaje gris y pardo, además de ejemplares grandes, una parte del vínculo entre los tauren y estas bestias de las llanuras.",aliasQuestIDs={},en={title="Harb Clawhoof",aliases={"Harb","Harb Clawhoof"},body="Harb supplies riding kodos in Mulgore. His animals include gray and brown kodos as well as larger specimens, reflecting the tauren’s bond with these plains beasts.",aliasQuestIDs={}},fr={title="Harb Clawhoof",body="Harb fournitures équitation kodos dans Mulgore. Ses animaux comprennent des kodos gris et bruns ainsi que des spécimens plus grands, reflétant le lien du tauren avec ces bêtes des plaines."},de={title="Harb Clawhoof",body="Harb liefert Reitkodos in Mulgore. Zu seinen Tieren gehören graue und braune Kodos sowie größere Exemplare, was die Verbundenheit des Tauren mit diesen Tieren widerspiegelt."},pt={title="Harb Clawhoof",body="Harb fornece passeios de kodos em Mulgore. Seus animais incluem kodos cinza e marrom, bem como espécimes maiores, refletindo o vínculo do tauren com esses animais de planície."},pl={title="Harb Clawhoof",body="Harb dostarcza kodo do jazdy w Mulgore. Wśród jego zwierząt są szare i brązowe kodo oraz większe okazy, odzwierciedlające więź taurenów z tymi mieszkańcami równin."},ru={title="Harb Clawhoof",body="Harb снабжает коды в Mulgore. Его животные включают серых и коричневых кодо, а также более крупные экземпляры, отражающие связь таурен с этими равнинными зверями."},references={["place:mulgore"]=true}},
    ["person:harken-windtotem"] = {title="Harken Tótem de Viento",kind="Personaje",aliases={"Harken","Harken Tótem de Viento"},body="Harken Tótem de Viento valora la astucia y la determinación de los cazadores de Mulgore. Para él, las plumas de aguilón son una señal de la habilidad necesaria para rastrear y alcanzar a una presa difícil.",aliasQuestIDs={},en={title="Harken Windtotem",aliases={"Harken","Harken Windtotem"},body="Harken Windtotem values the cunning and determination of Mulgore’s hunters. To him, swoop quills mark the skill needed to track and catch difficult prey.",aliasQuestIDs={}},fr={title="Harken Windtotem",body="Harken Windtotem valorise la ruse et la détermination des chasseurs de Mulgore. Pour lui, les piquants swoop marquent la compétence nécessaire pour suivre et attraper des proies difficiles."},de={title="Harken Windtotem",body="Harken Windtotem schätzt die List und Entschlossenheit der Jäger von Mulgore. Für ihn kennzeichnen Federkiele die Fertigkeit, die erforderlich ist, um schwierige Beute aufzuspüren und zu fangen."},pt={title="Harken Windtotem",body="Harken Windtotem valoriza a astúcia e determinação dos caçadores de Mulgore. Para ele, as penas de swoop marcam a habilidade necessária para rastrear e capturar presas difíceis."},pl={title="Harken Windtotem",body="Harken Windtotem ceni przebiegłość i determinację myśliwych Mulgore. Kolce ptaków uważa za oznakę umiejętności potrzebnych do wytropienia i schwytania trudnej zdobyczy."},ru={title="Harken Windtotem",body="Harken Windtotem ценит хитрость и решимость охотников Mulgore s. Для него, ускоренные перья значат умение, необходимое для отслеживания и ловли сложной добычи."},references={["place:mulgore"]=true}},
    ["person:harutt-thunderhorn"] = {title="Harutt Tronacuerno",kind="Personaje",aliases={"Harutt","Harutt Tronacuerno"},body="Harutt Tronacuerno enseña a los guerreros tauren. Sus lecciones recuerdan que cada integrante de la tribu tiene un papel y que ni el orgullo ni la especialidad eximen a nadie de compartir sus ritos.",aliasQuestIDs={},en={title="Harutt Thunderhorn",aliases={"Harutt","Harutt Thunderhorn"},body="Harutt Thunderhorn teaches tauren warriors. His lessons stress that every tribal member has a role, and that neither pride nor a particular calling excuses anyone from sharing its rites.",aliasQuestIDs={}},fr={title="Harutt Thunderhorn",body="Harutt Thunderhorn enseigne les guerriers taurens. Ses leçons soulignent que chaque membre de la tribu a un rôle à jouer, et que ni la fierté ni une vocation particulière n’excusent quiconque de partager ses rites."},de={title="Harutt Thunderhorn",body="Harutt Thunderhorn unterrichtet Tauren-Krieger. Seine Lehren betonen, dass jedes Stammesmitglied eine Rolle hat und dass weder Stolz noch eine bestimmte Berufung jemanden davon abhält, seine Riten zu teilen."},pt={title="Harutt Thunderhorn",body="Harutt Thunderhorn ensina guerreiros tauren. Suas lições enfatizam que cada membro tribal tem um papel, e que nem o orgulho nem um chamado particular desculpa ninguém de compartilhar seus ritos."},pl={title="Harutt Thunderhorn",body="Harutt Thunderhorn szkoli taurenskich wojowników. Podkreśla, że każdy członek plemienia ma swoją rolę, a ani duma, ani określone powołanie nie zwalniają nikogo z udziału w jego obrzędach."},ru={title="Harutt Thunderhorn",body="Harutt Thunderhorn обучает тауренских воинов. Его уроки подчеркивают, что каждый член племени играет свою роль и что ни гордость, ни определенное призвание не оправдывают кого-либо от участия в его обрядах."},references={}},
    ["person:hastat-the-ancient"] = {title="Hastat el Anciano",kind="Personaje",aliases={"Hastat","Hastat el Anciano"},body="Hastat el Anciano conserva conocimientos perdidos desde hace eones. Puede combinar una de sus hojas con tendón de dragón para crear un carcaj extraordinario, reflejo de una tradición que une naturaleza y poder.",aliasQuestIDs={},en={title="Hastat the Ancient",aliases={"Hastat","Hastat the Ancient"},body="Hastat the Ancient preserves knowledge lost for ages. He can combine one of his leaves with dragon sinew to create a remarkable quiver, reflecting a tradition joining nature and power.",aliasQuestIDs={}},fr={title="Hastat the Ancient",body="Hastat the Ancient préserve les connaissances perdues pendant des siècles. Il peut combiner une de ses feuilles avec un tendon de dragon pour créer un carquois remarquable, reflétant une tradition alliant nature et pouvoir."},de={title="Hastat the Ancient",body="Hastat the Ancient bewahrt Wissen auf, das seit Ewigkeiten verloren geht. Er kann eines seiner Blätter mit Drachensehnen kombinieren, um einen bemerkenswerten Köcher zu erzeugen, der eine Tradition widerspiegelt, die Natur und Kraft und Kraft mit Kraft zu verbinden."},pt={title="Hastat the Ancient",body="Hastat the Ancient preserva o conhecimento perdido por idades. Ele pode combinar uma de suas folhas com o seno de dragão para criar uma aljava notável, refletindo uma tradição que une natureza e poder."},pl={title="Hastat the Ancient",body="Hastat the Ancient przechowuje wiedzę utraconą przed wiekami. Potrafi połączyć jeden ze swoich liści ze smoczym ścięgnem w niezwykły kołczan, odzwierciedlający tradycję łączącą naturę i moc."},ru={title="Hastat the Ancient",body="Hastat the Ancient сохраняет знания, потерянные веками. Он может соединить один из своих листьев с драконьей сухожилиями, чтобы создать замечательный трепет, отражающий традицию объединения природы и силы."},references={}},
    ["person:haughty-modiste"] = {title="Modista Jactancia",kind="Personaje",aliases={"Modista Jactancia","modista Jactancia"},body="La modista Jactancia trabaja en el Puerto Bonvapor y presume de vestir a las figuras más importantes de Azeroth. Su negocio convierte incluso los sombreros de los piratas en materia prima para la moda.",aliasQuestIDs={},en={title="Haughty Modiste",aliases={"Haughty Modiste"},body="Haughty Modiste works in Steamwheedle Port and boasts of dressing Azeroth’s most important figures. Her business turns even pirate hats into raw material for fashion.",aliasQuestIDs={}},fr={title="Haughty Modiste",body="Haughty Modiste travaille dans Steamwheedle Port et se vante d’habiller les figures les plus importantes de Azeroth. Son entreprise transforme même les chapeaux de pirate en matière première pour la mode."},de={title="Haughty Modiste",body="Haughty Modiste arbeitet in Steamwheedle Port und prahlt damit, Azeroths wichtigste Figuren anzuziehen. Ihr Geschäft macht sogar Piratenhüte zu Moderohstoffen."},pt={title="Haughty Modiste",body="Haughty Modiste trabalha em Steamwheedle Port e se orgulha de vestir figuras mais importantes de Azeroth. Seu negócio transforma até mesmo chapéus piratas em matéria-prima para a moda."},pl={title="Haughty Modiste",body="Haughty Modiste pracuje w Steamwheedle Port i chwali się ubieraniem najważniejszych postaci Azeroth. Jej interes zamienia nawet pirackie kapelusze w surowiec dla mody."},ru={title="Haughty Modiste",body="Haughty Modiste работает в Steamwheedle Port и может похвастаться тем, что одевает самые важные фигуры Azeroth. Ее бизнес превращает даже пиратские шляпы в сырье для моды."},references={["place:azeroth"]=true,["place:steamwheedle-port"]=true}},
    ["person:healer-longrunner"] = {title="Sanador Largo Camino",kind="Personaje",aliases={"Largo Camino","Sanador Largo Camino"},body="El sanador Largo Camino coordina la recolección de vendas de lana para la Horda antes de la guerra de Ahn’Qiraj. Su experiencia le recuerda que no siempre habrá un sanador junto a cada soldado, por lo que prepara botiquines para que puedan atender sus propias heridas.",aliasQuestIDs={},en={title="Healer Longrunner",aliases={"Healer Longrunner","Longrunner"},body="Healer Longrunner coordinates the Horde’s collection of wool bandages before the Ahn’Qiraj war. Experience has taught him that a healer cannot always be beside every soldier, so he prepares first-aid kits for treating their own wounds.",aliasQuestIDs={}},fr={title="Healer Longrunner",body="Healer Longrunner coordonne la collection de bandages de laine Horde avant la guerre Ahn’Qiraj. L'expérience lui a appris qu'un guérisseur ne peut pas toujours être à côté de chaque soldat, alors il prépare des trousses de premiers soins pour traiter leurs propres blessures."},de={title="Healer Longrunner",body="Healer Longrunner koordiniert die Wollbindersammlung des Horde vor dem Ahn’Qiraj-Krieg. Die Erfahrung hat ihn gelehrt, dass ein Heiler nicht immer neben jedem Soldaten zur Seite stehen kann, also bereitet er Erste-Hilfe-Sets für ihre eigenen Wunden."},pt={title="Healer Longrunner",body="Healer Longrunner coordena a coleção Horde de bandagens de lã antes da guerra Ahn’Qiraj. A experiência lhe ensinou que um curandeiro nem sempre pode estar ao lado de cada soldado, então ele prepara kits de primeiros socorros para tratar suas próprias feridas."},pl={title="Healer Longrunner",body="Healer Longrunner koordynuje zbiórkę wełnianych bandaży dla Horde przed wojną w Ahn’Qiraj. Doświadczenie nauczyło go, że uzdrowiciel nie zawsze może być przy każdym żołnierzu, dlatego przygotowuje zestawy pierwszej pomocy pozwalające opatrywać własne rany."},ru={title="Healer Longrunner",body="Healer Longrunner координирует коллекцию шерстяных повязок Horde  перед войной Ahn’Qiraj. Опыт научил его, что врач не всегда может быть рядом с каждым солдатом, поэтому он готовит аптечки для лечения их собственных ран."},references={["event:ahnqiraj-war"]=true,["organization:horde"]=true,["place:ahnqiraj"]=true},questIDs={[8604]=true,[8605]=true}},
    ["person:heglan-shadeeye"] = {title="Heglan Sombramira",kind="Personaje",aliases={"Heglan","Heglan Sombramira"},body="Heglan Sombramira pertenece a la Mano Destrozada y realiza labores de vigilancia discreta. Sus observaciones del Fuerte de Tiragarde mantienen informados a los orcos sobre la presencia humana en Durotar.",aliasQuestIDs={},en={title="Heglan Shadeeye",aliases={"Heglan","Heglan Shadeeye"},body="Heglan Shadeeye belongs to the Shattered Hand and carries out discreet surveillance. Her observations of Tiragarde Keep keep the orcs informed about the human presence in Durotar.",aliasQuestIDs={}},fr={title="Heglan Shadeeye",body="Heglan Shadeeye appartient au Shattered Hand et effectue une surveillance discrète. Ses observations de Tiragarde garder les orcs informés sur la présence humaine dans Durotar."},de={title="Heglan Shadeeye",body="Heglan Shadeeye gehört zur Shattered Hand und überwacht diskret. Ihre Beobachtungen von Tiragarde Keep halten die Orks über die menschliche Präsenz in Durotar auf dem Laufenden."},pt={title="Heglan Shadeeye",body="Heglan Shadeeye faz parte da Shattered Hand e realiza vigilância discreta. Suas observações de Tiragarde Keep mantêm os orcs informados sobre a presença humana em Durotar."},pl={title="Heglan Shadeeye",body="Heglan Shadeeye należy do Shattered Hand i prowadzi dyskretną obserwację. Jej spostrzeżenia dotyczące twierdzy Tiragarde informują orków o ludzkiej obecności w Durotar."},ru={title="Heglan Shadeeye",body="Heglan Shadeeye принадлежит к Shattered Hand и осуществляет скрытное наблюдение. Ее наблюдения за Tiragarde держат орков в курсе присутствия человека в Durotar."},references={["organization:shattered-hand"]=true,["place:durotar"]=true}},
    ["person:herbalist-proudfeather"] = {title="Herborista Pluma Digna",kind="Personaje",aliases={"Herborista Pluma Digna","herborista Pluma Digna"},body="El herborista Pluma Digna se ha ofrecido a reunir flores de paz para los preparativos de guerra de la Horda. Considera esa labor una contribución a las pociones que ayudarán a poner a prueba la entereza de su generación.",aliasQuestIDs={},en={title="Herbalist Proudfeather",aliases={"Herbalist Proudfeather","Proudfeather"},body="Herbalist Proudfeather has volunteered to gather peacebloom for the Horde’s war preparations. He regards the work as a contribution to the potions that will help test his generation’s resolve.",aliasQuestIDs={}},fr={title="Herbalist Proudfeather",body="Herbalist Proudfeather s’est porté volontaire pour rassembler des fleurs de paix pour les préparatifs de guerre du Horde. Il considère le travail comme une contribution aux potions qui aideront à tester la détermination de sa génération."},de={title="Herbalist Proudfeather",body="Herbalist Proudfeather hat sich freiwillig gemeldet, um Friedenspapostel für die Kriegsvorbereitungen des Horde zu sammeln. Er betrachtet die Arbeit als Beitrag zu den Tränken, die helfen, die Entschlossenheit seiner Generation auf die Probe zu stellen."},pt={title="Herbalist Proudfeather",body="Herbalist Proudfeather se ofereceu para reunir paz para os preparativos de guerra do Horde. Ele considera o trabalho como uma contribuição para as poções que ajudarão a testar a determinação de sua geração."},pl={title="Herbalist Proudfeather",body="Herbalist Proudfeather zgłosił się do zbierania kwiatów pokoju na wojenne przygotowania frakcji Horde. Uważa pracę za wkład w mikstury, które pomogą sprawdzić determinację jego pokolenia."},ru={title="Herbalist Proudfeather",body="Herbalist Proudfeather добровольно подался на сбор цветов мира для подготовки к войне Horde. Он считает эту работу вкладом в создание зелья, которое поможет проверить решимость его поколения."},references={["organization:horde"]=true}},
    ["person:hermit-ortell"] = {title="Ermitaño Ortell",kind="Personaje",aliases={"Ermitaño Ortell","Ortell","ermitaño Ortell"},body="El ermitaño Ortell vive en Silithus y conoce los métodos de comunicación del Martillo Crepuscular. Tras abandonar el culto, utiliza ese conocimiento para interpretar sus escritos y ayudar a sus adversarios.",aliasQuestIDs={},en={title="Hermit Ortell",aliases={"Hermit Ortell","Ortell"},body="Hermit Ortell lives in Silithus and knows the Twilight’s Hammer’s methods of communication. Having left the cult, he uses that knowledge to interpret its writing and help its opponents.",aliasQuestIDs={}},fr={title="Hermit Ortell",body="Hermit Ortell vit dans Silithus et connaît les méthodes de communication du Twilight’s Hammer. Ayant quitté le culte, il utilise cette connaissance pour interpréter son écriture et aider ses adversaires."},de={title="Hermit Ortell",body="Hermit Ortell lebt in Silithus und kennt die Kommunikationsmethoden Twilight’s Hammer. Nachdem er den Kult verlassen hat, nutzt er dieses Wissen, um seine Schriften zu interpretieren und seinen Gegnern zu helfen."},pt={title="Hermit Ortell",body="Hermit Ortell vive em Silithus e conhece os métodos de comunicação do Twilight’s Hammer. Tendo deixado o culto, ele usa esse conhecimento para interpretar sua escrita e ajudar seus oponentes."},pl={title="Hermit Ortell",body="Hermit Ortell mieszka w Silithus i zna metody porozumiewania się Twilight’s Hammer. Po opuszczeniu kultu wykorzystuje tę wiedzę do odczytywania jego pisma oraz pomagania przeciwnikom."},ru={title="Hermit Ortell",body="Hermit Ortell живет в Silithus и знает методы связи Twilight’s Hammer s. Оставив культ, он использует это знание, чтобы интерпретировать его письмо и помочь его противникам."},references={["organization:twilights-hammer"]=true,["place:silithus"]=true}},
    ["person:hetaera"] = {title="Hetaera",kind="Personaje",aliases={"Hetaera"},body="Hetaera reclama el dominio sobre las aguas donde viven los hijos de Arkkoroc. Este la considera una falsa deidad y una amenaza para los suyos, una rivalidad que enfrenta a poderes de la costa de Azshara.",aliasQuestIDs={},en={title="Hetaera",aliases={"Hetaera"},body="Hetaera claims dominion over the waters inhabited by Arkkoroc’s children. He regards her as a false deity and a threat to his offspring, a rivalry between powers of the Azshara coast.",aliasQuestIDs={}},fr={title="Hetaera",body="Hetaera revendique la domination sur les eaux habitées par les enfants de Arkkoroc. Il la considère comme une fausse divinité et une menace pour sa progéniture, une rivalité entre les puissances de la côte Azshara."},de={title="Hetaera",body="Hetaera beansprucht die Herrschaft über die Gewässer, die von Arkkoroc 's Kindern bewohnt werden. Er betrachtet sie als eine falsche Gottheit und Bedrohung für seine Nachkommen, eine Rivalität zwischen den Mächten der Azshara-Küste."},pt={title="Hetaera",body="Hetaera reivindica domínio sobre as águas habitadas pelos filhos de Arkkoroc. Ele a considera como uma divindade falsa e uma ameaça à sua prole, uma rivalidade entre os poderes da costa Azshara."},pl={title="Hetaera",body="Hetaera rości sobie władzę nad wodami zamieszkanymi przez dzieci istoty Arkkoroc. Uważa on ją za fałszywe bóstwo i zagrożenie dla potomstwa, tworząc rywalizację między potęgami wybrzeża regionu Azshara."},ru={title="Hetaera",body="Hetaera претендует на владение водами, населенными детьми Arkkoroc. Он считает ее ложным божеством и угрозой для своего потомства, соперничеством между силами побережья Azshara."},references={["person:lord-arkkoroc"]=true}},
    ["person:hezrul-bloodmark"] = {title="Hezrul Marcasangre",kind="Personaje",aliases={"Hezrul","Hezrul Marcasangre"},body="Hezrul Marcasangre es un jefe de los centauros Kolkar de Los Baldíos. Su liderazgo combina fuerza y astucia para dirigir las bandas que operan cerca de los oasis.",aliasQuestIDs={},en={title="Hezrul Bloodmark",aliases={"Hezrul","Hezrul Bloodmark"},body="Hezrul Bloodmark is a leader of the Kolkar centaurs in the Barrens. His leadership combines strength and cunning to direct the bands operating near the oases.",aliasQuestIDs={}},fr={title="Hezrul Bloodmark",body="Hezrul Bloodmark est un leader des centaures Kolkar dans le Barrens. Son leadership combine la force et la ruse pour diriger les bandes opérant près des oasis."},de={title="Hezrul Bloodmark",body="Hezrul Bloodmark ist ein Anführer der Kolkar-Zentauren im Barrens. Seine Führung vereint Stärke und List, um die Bands zu leiten, die in der Nähe der Oasen operieren."},pt={title="Hezrul Bloodmark",body="Hezrul Bloodmark é um líder dos centauros Kolkar no Barrens. Sua liderança combina força e astúcia para direcionar as bandas que operam perto dos oásis."},pl={title="Hezrul Bloodmark",body="Hezrul Bloodmark jest przywódcą centaurów Kolkar w regionie Barrens. Łączy siłę z przebiegłością, kierując grupami działającymi w pobliżu oaz."},ru={title="Hezrul Bloodmark",body="Hezrul Bloodmark - лидер кентавров Kolkar в Barrens. Его лидерство сочетает в себе силу и хитрость, чтобы направлять группы, действующие возле оазисов."},references={["organization:kolkar"]=true,["place:the-barrens"]=true}},
    ["person:high-chief-winterfall"] = {title="Gran Jefe Nevada",kind="Personaje",aliases={"Gran Jefe Nevada"},body="El Gran Jefe Nevada dirige a los fúrbolgs del Poblado Nevada, en Cuna del Invierno. Su autoridad ha quedado bajo sospecha desde que una tribu normalmente poco agresiva comenzó a consumir una extraña sustancia y a actuar con violencia.",aliasQuestIDs={},en={title="High Chief Winterfall",aliases={"High Chief Winterfall"},body="High Chief Winterfall leads the furbolgs of Winterfall Village in Winterspring. His authority has come under suspicion since a normally unaggressive tribe began consuming a strange substance and behaving violently.",aliasQuestIDs={}},fr={title="High Chief Winterfall",body="High Chief Winterfall mène les furbolgs de Winterfall Village dans Winterspring. Son autorité est soupçonnée depuis qu’une tribu normalement peu agressive a commencé à consommer une substance étrange et à se comporter violemment."},de={title="High Chief Winterfall",body="High Chief Winterfall führt die Furbolgs von Winterfall Village in Winterspring an. Seine Autorität steht unter Verdacht, seit ein normalerweise unaggressiver Stamm begann, eine merkwürdige Substanz zu konsumieren und sich gewalttätig zu verhalten."},pt={title="High Chief Winterfall",body="High Chief Winterfall lidera os furbolgs de Winterfall Village em Winterspring. Sua autoridade ficou sob suspeita desde que uma tribo normalmente não agressiva começou a consumir uma substância estranha e se comportar violentamente."},pl={title="High Chief Winterfall",body="High Chief Winterfall przewodzi furbolgom w wiosce Winterfall w Winterspring. Jego władza wzbudza podejrzenia, odkąd zwykle nieagresywne plemię zaczęło spożywać niezwykłą substancję i zachowywać się gwałtownie."},ru={title="High Chief Winterfall",body="High Chief Winterfall возглавляет фуробольги деревни Winterfall в Winterspring. Его авторитет подвергся сомнению с тех пор, как обычно спокойное племя начало употреблять странное вещество и вести себя жестоко."},references={["organization:winterfall"]=true,["place:winterspring"]=true}},
    ["person:high-priestess-lorthuna"] = {title="Suma sacerdotisa Lorthuna",kind="Personaje",aliases={"Lorthuna","Suma sacerdotisa Lorthuna"},body="Lorthuna es una suma sacerdotisa del Culto de Al'Aketh vinculada al Santuario de Akir. Ejerce autoridad sobre grupos de cultores que actúan en Zephras. Los informes locales la relacionan con los ataques a viajeros y con la presión del culto sobre las comunidades de la isla.",aliasQuestIDs={},en={title="High Priestess Lorthuna",aliases={"High Priestess Lorthuna","Lorthuna"},body="Lorthuna is a high priestess of the Al'Aketh Cult associated with the Shrine of Akir. She exercises authority over cult groups operating on Zephras. Local reports connect her with attacks on travelers and the cult's pressure on the island's communities.",aliasQuestIDs={}},fr={title="High Priestess Lorthuna",body="Lorthuna est une grande prêtresse de la Al'Aketh Cult associée au Sanctuaire de Akir. Elle exerce une autorité sur les groupes cultes opérant sur Zephras. Des rapports locaux la relient aux attaques contre les voyageurs et à la pression du culte sur les communautés de l'île."},de={title="High Priestess Lorthuna",body="Lorthuna ist Hohepriesterin der Al'Aketh Cult, die mit dem Schrein von Akir in Verbindung steht. Sie übt Autorität über Sektengruppen aus, die auf Zephras operieren. Lokale Berichte bringen sie mit Angriffen auf Reisende und dem Druck des Kults auf die Inselgemeinden in Verbindung."},pt={title="High Priestess Lorthuna",body="Lorthuna é uma alta sacerdotisa do Al'Aketh Cult associada ao Santuário de Akir. Ela exerce autoridade sobre grupos de culto que operam no Zephras. Relatórios locais a conectam com ataques a viajantes e à pressão do culto sobre as comunidades da ilha."},pl={title="High Priestess Lorthuna",body="Lorthuna jest arcykapłanką Al'Aketh Cult związaną ze Shrine of Akir. Sprawuje władzę nad grupami kultu działającymi na Zephras. Miejscowe raporty łączą ją z atakami na podróżnych i naciskiem na społeczności wyspy."},ru={title="High Priestess Lorthuna",body="Lorthuna - это первосвященница Al'Aketh Cult, связанная со Святыней Akir. Она властвует над культовыми группами, действующими на Zephras. Местные сообщения связывают ее с нападениями на путешественников и давлением секты на общины острова."},references={["organization:al-aketh"]=true,["place:zephras"]=true}},
    ["person:highlord-demitrian"] = {title="Alto señor Demitrian",kind="Personaje",aliases={"Alto señor Demitrian","Demitrian","alto señor Demitrian"},body="El alto señor Demitrian estudia los vínculos que retienen el poder de seres elementales. Su conocimiento de vasijas y prisiones mágicas lo relaciona con fuerzas del viento que no obedecen a los mortales comunes.",aliasQuestIDs={},en={title="Highlord Demitrian",aliases={"Demitrian","Highlord Demitrian"},body="Highlord Demitrian studies the bindings holding the power of elemental beings. His knowledge of magical vessels and prisons connects him with powers of wind beyond the control of ordinary mortals.",aliasQuestIDs={}},fr={title="Highlord Demitrian",body="Highlord Demitrian étudie les liaisons qui détiennent le pouvoir des êtres élémentaires. Sa connaissance des vaisseaux magiques et des prisons le relie aux puissances du vent hors du contrôle des mortels ordinaires."},de={title="Highlord Demitrian",body="Highlord Demitrian untersucht die Bindungen, die die die die Macht von Elementarwesen besitzen. Sein Wissen über magische Gefäße und Gefängnisse verbindet ihn mit Windkräften, die sich außerhalb der Kontrolle der gewöhnlicher Sterblicher Menschen befinden."},pt={title="Highlord Demitrian",body="Highlord Demitrian estuda as ligações que detêm o poder dos seres elementais. Seu conhecimento de vasos mágicos e prisões conecta-o com poderes de vento além do controle de mortais comuns."},pl={title="Highlord Demitrian",body="Highlord Demitrian bada więzy utrzymujące moc istot żywiołów. Znajomość magicznych naczyń i więzień wiąże go z potęgami wiatru wykraczającymi poza kontrolę zwykłych śmiertelników."},ru={title="Highlord Demitrian",body="Highlord Demitrian изучает связи, которые удерживают силу элементарных существ. Его знания о магических сосудах и тюрьмах связывают его с силами ветра, которые выходят за пределы контроля обычных смертных."},references={}},
    ["person:holanyee-marshal"] = {title="Hol'anyee Marshal",kind="Personaje",aliases={"Hol'anyee Marshal","Hol’anyee Marshal"},body="Hol'anyee Marshal investiga los insectos Gorishi del Cráter de Un'Goro. El estudio de sus colmenas busca explicar por qué unas criaturas invasoras han llegado a un entorno ecológico tan particular.",aliasQuestIDs={},en={title="Hol'anyee Marshal",aliases={"Hol'anyee","Hol'anyee Marshal","Hol’anyee","Hol’anyee Marshal"},body="Hol'anyee Marshal studies the Gorishi insects of Un'Goro Crater. Research into their hives seeks to explain why invasive creatures have reached such a distinctive ecological environment.",aliasQuestIDs={}},fr={title="Hol'anyee Marshal",body="Hol'anyee Marshal étudie les insectes Gorishi de Un'Goro Crater. La recherche sur leurs ruches cherche à expliquer pourquoi les créatures envahissantes ont atteint un environnement écologique si distinctif."},de={title="Hol'anyee Marshal",body="Hol'anyee Marshal studiert die Gorishi-Insekten von Un'Goro Crater. Die Erforschung ihrer Bienenstöcke soll erklären, warum invasive Lebewesen ein so unverwechselbares ökologisches Umfeld erreicht haben."},pt={title="Hol'anyee Marshal",body="Hol'anyee Marshal estuda os insetos Gorishi de Un'Goro Crater. A pesquisa em suas colmeias procura explicar por que as criaturas invasoras alcançaram um ambiente ecológico tão distinto."},pl={title="Hol'anyee Marshal",body="Hol'anyee Marshal bada owady Gorishi z Un'Goro Crater. Badania ich rojów służą wyjaśnieniu, dlaczego inwazyjne stworzenia dotarły do tak wyjątkowego środowiska ekologicznego."},ru={title="Hol'anyee Marshal",body="Hol'anyee Marshal изучает насекомых Gorishi Un'Goro Crater. Исследования их ульев позволяют понять, почему инвазивные существа достигли такой уникальной экологической среды."},references={["organization:gorishi"]=true,["place:ungoro-crater"]=true}},
    ["person:holt-thunderhorn"] = {title="Holt Tronacuerno",kind="Personaje",aliases={"Holt","Holt Tronacuerno"},body="Holt Tronacuerno es un instructor de cazadores del Alto de los Cazadores de Cima del Trueno. Su experiencia abarca el adiestramiento de bestias y una forma de vida que busca armonía con la Madre Tierra.",aliasQuestIDs={},en={title="Holt Thunderhorn",aliases={"Holt","Holt Thunderhorn"},body="Holt Thunderhorn is a hunter trainer on Hunter Rise in Thunder Bluff. His experience includes training beasts and a way of life seeking harmony with the Earth Mother.",aliasQuestIDs={}},fr={title="Holt Thunderhorn",body="Holt Thunderhorn est un dresseur de chasseurs sur Hunter Rise dans Thunder Bluff. Son expérience comprend l'entraînement des bêtes et un mode de vie en harmonie avec le Earth Mother."},de={title="Holt Thunderhorn",body="Holt Thunderhorn ist Jäger-Trainer bei \"Hunter Rise in Thunder Bluff\". Zu seinen Erfahrungen gehören die Ausbildung von Tieren und eine Lebensweise, die Harmonie mit dem Earth Mother sucht."},pt={title="Holt Thunderhorn",body="Holt Thunderhorn é um treinador caçador em Hunter Rise em Thunder Bluff. Sua experiência inclui animais de treinamento e um modo de vida buscando harmonia com o Earth Mother."},pl={title="Holt Thunderhorn",body="Holt Thunderhorn jest nauczycielem łowców na wzniesieniu łowców w Thunder Bluff. Jego doświadczenie obejmuje szkolenie bestii oraz sposób życia dążący do harmonii z istotą Earth Mother."},ru={title="Holt Thunderhorn",body="Holt Thunderhorn - тренер охотников на Hunter Rise в Thunder Bluff. Его опыт включает обучение зверей и образ жизни, стремящийся к гармонии с Earth Mother."},references={["person:earth-mother"]=true,["place:thunder-bluff"]=true}},
    ["person:hornizz-brimbuzzle"] = {title="Hornizz Zumbala",kind="Personaje",aliases={"Hornizz","Hornizz Zumbala"},body="Hornizz Zumbala mantiene un campamento próximo al Cementerio de Kodos en Desolace. Sus negocios y su relación con su hermana Melizza lo vinculan a los intentos de comerciar con los pueblos de la región.",aliasQuestIDs={},en={title="Hornizz Brimbuzzle",aliases={"Hornizz","Hornizz Brimbuzzle"},body="Hornizz Brimbuzzle maintains a camp near the Kodo Graveyard in Desolace. His business and relationship with his sister Melizza connect him with attempts to trade with the region’s peoples.",aliasQuestIDs={}},fr={title="Hornizz Brimbuzzle",body="Hornizz Brimbuzzle maintient un camp près du cimetière Kodo dans Desolace. Ses affaires et sa relation avec sa sœur Melizza le relient à des tentatives de commerce avec les peuples de la région."},de={title="Hornizz Brimbuzzle",body="Hornizz Brimbuzzle unterhält ein Lager in der Nähe des Kodo Friedhofes in Desolace. Seine Geschäfte und Beziehungen zu seiner Schwester Melizza verbinden ihn mit Versuchen, mit den Völkern der Region Handel zu treiben."},pt={title="Hornizz Brimbuzzle",body="Hornizz Brimbuzzle mantém um acampamento perto do Cemitério Kodo em Desolace. Seu negócio e relacionamento com sua irmã Melizza o conectam com tentativas de comércio com os povos da região."},pl={title="Hornizz Brimbuzzle",body="Hornizz Brimbuzzle utrzymuje obóz przy cmentarzysku Kodo w Desolace. Interesy i relacja z siostrą noszącą imię Melizza wiążą go z próbami handlu z ludami regionu."},ru={title="Hornizz Brimbuzzle",body="Hornizz Brimbuzzle поддерживает лагерь возле кладбища Kodo в Desolace. Его бизнес и отношения с сестрой Melizza связывают его с попытками торговать с народами региона."},references={["person:melizza-brimbuzzle"]=true,["place:desolace"]=true}},
    ["person:huum-wildmane"] = {title="Huum Ferocrín",kind="Personaje",aliases={"Huum","Huum Ferocrín"},body="Huum Ferocrín trabaja contra el Martillo Crepuscular desde el Fuerte Cenarion. Sus esfuerzos se centran en los campamentos y líderes del culto mientras otros investigadores intentan entender sus rituales y cristales.",aliasQuestIDs={},en={title="Huum Wildmane",aliases={"Huum","Huum Wildmane"},body="Huum Wildmane works against the Twilight’s Hammer from Cenarion Hold. His efforts focus on the cult’s camps and leaders while other researchers try to understand its rituals and crystals.",aliasQuestIDs={}},fr={title="Huum Wildmane",body="Huum Wildmane fonctionne contre le Twilight’s Hammer de Cenarion Hold. Ses efforts se concentrent sur les camps et les dirigeants du culte tandis que d’autres chercheurs tentent de comprendre ses rituels et ses cristaux."},de={title="Huum Wildmane",body="Huum Wildmane arbeitet gegen den Twilight’s Hammer von Cenarion Hold. Seine Bemühungen konzentrieren sich auf die Lager und Führer des Kults, während andere Forscher versuchen, seine Rituale und Kristalle zu verstehen."},pt={title="Huum Wildmane",body="Huum Wildmane trabalha contra o Twilight’s Hammer da Cenarion Hold. Seus esforços se concentram nos campos e líderes do culto, enquanto outros pesquisadores tentam entender seus rituais e cristais."},pl={title="Huum Wildmane",body="Huum Wildmane działa przeciw Twilight’s Hammer z Cenarion Hold. Skupia się na obozach i przywódcach kultu, podczas gdy inni badacze próbują zrozumieć jego rytuały oraz kryształy."},ru={title="Huum Wildmane",body="Huum Wildmane работает против Twilight’s Hammer от Cenarion Hold. Его усилия сосредоточены на лагерях и лидерах культа, в то время как другие исследователи пытаются понять его ритуалы и кристаллы."},references={["organization:twilights-hammer"]=true,["place:cenarion-hold"]=true}},
    ["person:iaadaria-bitterwind"] = {title="Iaadaria Vientoglacial",kind="Personaje",aliases={"Iaadaria","Iaadaria Vientoglacial"},body="Iaadaria Vientoglacial se encuentra en Valanaar e investiga las propiedades alquímicas de las garfas de chillín. Su interés une el estudio de los materiales naturales con las preocupaciones por el crecimiento de estas criaturas en el Bosque Ventarrosombra. Considera que su investigación puede aprovechar muestras obtenidas al controlar esa expansión.",aliasQuestIDs={},en={title="Iaadaria Bitterwind",aliases={"Iaadaria","Iaadaria Bitterwind"},body="Iaadaria Bitterwind is based in Valanaar and studies the alchemical properties of shriekling talons. Her interests connect the study of natural materials with concern about the creatures’ growing numbers in Shadowgale Forest. She sees material gathered while controlling their expansion as an opportunity for research.",aliasQuestIDs={}},fr={title="Iaadaria Bitterwind",body="Iaadaria Bitterwind est basé dans Valanaar et étudie les propriétés alchimiques des serres criardes. Ses intérêts relient l’étude des matériaux naturels avec l’inquiétude concernant le nombre croissant de créatures dans la forêt Shadowgale. Elle voit le matériel recueilli tout en contrôlant leur expansion comme une opportunité pour la recherche."},de={title="Iaadaria Bitterwind",body="Iaadaria Bitterwind lebt in Valanaar und studiert die alchemistischen Eigenschaften kreischender Krallen. Ihre Interessen verbinden das Studium natürlicher Materialien mit der Sorge über die wachsende Zahl der Kreaturen im Shadowgale-Wald. Sie sieht das gesammelte Material bei gleichzeitiger Kontrolle ihrer Expansion als Chance für die Forschung."},pt={title="Iaadaria Bitterwind",body="O Iaadaria Bitterwind é baseado no Valanaar e estuda as propriedades alquímicas das garras estridentes. Seus interesses conectam o estudo de materiais naturais com a preocupação com o crescente número de criaturas na Floresta Shadowgale. Ela vê o material reunido enquanto controla sua expansão como uma oportunidade para a pesquisa."},pl={title="Iaadaria Bitterwind",body="Iaadaria Bitterwind działa w Valanaar i bada alchemiczne właściwości szponów shrieklingów. Jej zainteresowania łączą badania naturalnych materiałów z troską o rosnącą liczebność stworzeń w Shadowgale Forest. Materiał zbierany przy ograniczaniu ich ekspansji uważa za okazję do badań."},ru={title="Iaadaria Bitterwind",body="Iaadaria Bitterwind основана на Valanaar и изучает алхимические свойства скрипящих когтей. Ее интересы связывают изучение природных материалов с заботой о растущем количестве существ в лесу Shadowgale. Она видит материал, собранный при контроле их расширения как возможность для исследований."},references={["place:valanaar"]=true}},
    ["person:ilkrud-magthrull"] = {title="Ilkrud Magthrull",kind="Personaje",aliases={"Ilkrud","Ilkrud Magthrull"},body="Ilkrud Magthrull es un poderoso brujo orco del Santuario de la Escara, en el suroeste de Vallefresno. Sus escritos documentan el poder de otros practicantes de las artes oscuras y el uso de gemas de almas por los seguidores de Athrikus.",aliasQuestIDs={},en={title="Ilkrud Magthrull",aliases={"Ilkrud","Ilkrud Magthrull"},body="Ilkrud Magthrull is a powerful orc warlock at the Fire Scar Shrine in southwestern Ashenvale. His writings document other practitioners’ dark power and the use of soulgems by Athrikus’s followers.",aliasQuestIDs={}},fr={title="Ilkrud Magthrull",body="Ilkrud Magthrull est un puissant démoniste orc au Fire Scar Shrine dans le sud-ouest Ashenvale. Ses écrits documentent le pouvoir sombre d’autres pratiquants et l’utilisation de Soulgemes par les adeptes de Athrikus."},de={title="Ilkrud Magthrull",body="Ilkrud Magthrull ist ein mächtiger Ork-Hexenmeister bei den Fire Scar Shrine im Südwesten Ashenvale. Seine Schriften dokumentieren die dunkle Macht anderer Praktizierender und die Verwendung von Seelenjuwelen durch Athrikus \"Anhänger."},pt={title="Ilkrud Magthrull",body="Ilkrud Magthrull é um poderoso bruxo orc no Fire Scar Shrine no sudoeste do Ashenvale. Seus escritos documentam o poder sombrio de outros praticantes e o uso de soulgems pelos seguidores de Athrikus."},pl={title="Ilkrud Magthrull",body="Ilkrud Magthrull jest potężnym orczym czarnoksiężnikiem w Fire Scar Shrine, w południowo-zachodniej części Ashenvale. Jego pisma opisują mroczną moc innych adeptów oraz używanie klejnotów dusz przez zwolenników Athrikus."},ru={title="Ilkrud Magthrull",body="Ilkrud Magthrull - могущественный оркский чернокнижник в Fire Scar Shrine на юго-западе Ashenvale. Его труды документируют другие практикующие  темную силу и использование драгоценных камней души последователями Athrikus."},references={["person:athrikus-narassin"]=true,["place:ashenvale"]=true,["place:fire-scar-shrine"]=true}},
    ["person:illaya-amberwind"] = {title="Illaya Ventámbar",kind="Personaje",aliases={"Illaya","Illaya Ventámbar"},body="Illaya Ventámbar es una anciana de los Formavientos que vive en la Aldea Shen'dar. Su lugar habitual está cerca del centro del poblado. Es una figura de referencia para quienes reconocen un vínculo espiritual con la tradición de los Formavientos.",aliasQuestIDs={},en={title="Illaya Amberwind",aliases={"Illaya","Illaya Amberwind"},body="Illaya Amberwind is a Windshaper elder living in Shen'dar Village. She can usually be found near the center of the settlement. She is a point of contact for those who recognize a spiritual connection with the Windshapers' tradition.",aliasQuestIDs={}},fr={title="Illaya Amberwind",body="Illaya Amberwind est un aîné Windshaper vivant dans Shen'dar Village. Elle peut généralement être trouvée près du centre de la colonie. Elle est un point de contact pour ceux qui reconnaissent une connexion spirituelle avec la tradition Windshapers '."},de={title="Illaya Amberwind",body="Illaya Amberwind ist eine ältere Windshaper, die in Shen'dar Village lebt. Sie kann normalerweise in der Nähe des Zentrums der Siedlung gefunden werden. Sie ist eine Anlaufstelle für alle, die eine spirituelle Verbindung zur Tradition der Windshapers erkennen."},pt={title="Illaya Amberwind",body="Illaya Amberwind é um ancião Windshaper que vive em Shen'dar Village. Ela geralmente pode ser encontrada perto do centro do assentamento. Ela é um ponto de contato para aqueles que reconhecem uma conexão espiritual com a tradição do Windshapers."},pl={title="Illaya Amberwind",body="Illaya Amberwind jest starszą Windshaper mieszkającą w Shen'dar Village. Zwykle przebywa przy centrum osady. Jest kontaktem dla rozpoznających duchową więź z tradycją społeczności znanej jako the Windshapers."},ru={title="Illaya Amberwind",body="Illaya Amberwind - это пожилой человек Windshaper, живущий в Shen'dar Village. Обычно ее можно найти недалеко от центра поселения. Она - точка соприкосновения для тех, кто признает духовную связь с традицией Windshapers."},references={["organization:windshapers"]=true,["place:shendar"]=true}},
    ["person:illiyana"] = {title="Illiyana",kind="Personaje",aliases={"Illiyana"},body="Illiyana es una dríade de Vallefresno vinculada a la defensa de sus hermanas y de la Rama de Cenarius. Su preocupación por los objetos sagrados refleja la relación entre los seres del bosque y los poderes que los protegen.",aliasQuestIDs={},en={title="Illiyana",aliases={"Illiyana"},body="Illiyana is an Ashenvale dryad concerned with protecting her sisters and the Branch of Cenarius. Her care for sacred objects reflects the relationship between the forest’s beings and the powers protecting them.",aliasQuestIDs={}},fr={title="Illiyana",body="Illiyana est une dryade Ashenvale soucieuse de protéger ses sœurs et la Branch of Cenarius. Son souci des objets sacrés reflète la relation entre les êtres de la forêt et les pouvoirs qui les protègent."},de={title="Illiyana",body="Illiyana ist eine Ashenvale, die sich um den Schutz ihrer Schwestern und der Branch of Cenarius kümmert. Ihre Fürsorge für heilige Objekte spiegelt die Beziehung zwischen den Wesen des Waldes Waldes Menschen und den Kräften wider, die sie beschützen."},pt={title="Illiyana",body="Illiyana é uma dryad Ashenvale preocupada em proteger suas irmãs e a Branch of Cenarius. Seu cuidado com objetos sagrados reflete a relação entre os seres da floresta e os poderes que os protegem."},pl={title="Illiyana",body="Illiyana jest driadą w Ashenvale troszczącą się o ochronę sióstr i Branch of Cenarius. Opieka nad świętymi przedmiotami odzwierciedla więź istot lasu z chroniącymi je potęgami."},ru={title="Illiyana",body="Illiyana — дриада из Ashenvale, заботящаяся о защите своих сестёр и Branch of Cenarius. Её внимание к священным предметам отражает связь лесных существ с силами, которые их оберегают."},references={["npc:cenarius"]=true,["object:branch-of-cenarius"]=true,["place:ashenvale"]=true},questIDs={[1021]=true,[1031]=true,[1032]=true}},
    ["person:impsy"] = {title="Diblis",kind="Personaje",aliases={"Diblis"},body="Diblis es un diablillo que acompaña a Niby en Frondavil. Sus deseos y experimentos muestran una curiosidad propia, alimentada por los materiales extraños y las criaturas corruptas del bosque.",aliasQuestIDs={},en={title="Impsy",aliases={"Impsy"},body="Impsy is an imp who accompanies Niby in Felwood. His wishes and experiments reveal a curiosity of his own, fueled by the forest’s unusual materials and corrupted creatures.",aliasQuestIDs={}},fr={title="Impsy",body="Impsy est un imp qui accompagne Niby dans Felwood. Ses souhaits et ses expériences révèlent une curiosité propre, alimentée par les matériaux inhabituels de la forêt et les créatures corrompues."},de={title="Impsy",body="Impsy ist ein Wichtel, der Niby in Felwood begleitet. Seine Wünsche und Experimente offenbaren eine eigene Kuriosität, angeheizt durch die ungewöhnlichen Materialien und verdorbenen Kreaturen des Waldes."},pt={title="Impsy",body="Impsy é um imp que acompanha Niby em Felwood. Seus desejos e experimentos revelam uma curiosidade própria, alimentada por materiais incomuns da floresta e criaturas corrompidas."},pl={title="Impsy",body="Impsy jest chochlikiem towarzyszącym postaci Niby w Felwood. Jego pragnienia i eksperymenty ukazują własną ciekawość, podsycaną niezwykłymi materiałami oraz skażonymi stworzeniami lasu."},ru={title="Impsy",body="Impsy - это джинн, который сопровождает Niby в Felwood. Его желания и эксперименты раскрывают его любопытство, подпитываемое необычными материалами леса и испорченными существами."},references={["person:niby-the-almighty"]=true,["place:felwood"]=true}},
    ["person:innkeeper-faralia"] = {title="Tabernera Faralia",kind="Personaje",aliases={"Faralia","Tabernera Faralia"},body="La tabernera Faralia recibe suministros en Cima del Espolón. Su posada depende de cargamentos que atraviesan una región donde los dracoleones pueden convertir una entrega ordinaria en un viaje peligroso.",aliasQuestIDs={},en={title="Innkeeper Faralia",aliases={"Faralia","Innkeeper Faralia"},body="Innkeeper Faralia receives supplies at Stonetalon Peak. Her inn depends on shipments traveling through a region where wyverns can turn an ordinary delivery into a dangerous journey.",aliasQuestIDs={}},fr={title="Innkeeper Faralia",body="Innkeeper Faralia reçoit des fournitures à Stonetalon Peak. Son auberge dépend des expéditions qui traversent une région où les wyverns peuvent transformer une livraison ordinaire en un voyage dangereux."},de={title="Innkeeper Faralia",body="Innkeeper Faralia wird bei Stonetalon Peak versorgt. Ihr Gasthof ist auf Sendungen angewiesen, die durch eine Region reisen, wo Flügeldrachen eine gewöhnliche Lieferung in eine gefährliche Reise verwandeln können."},pt={title="Innkeeper Faralia",body="Innkeeper Faralia recebe suprimentos na Stonetalon Peak. Sua pousada depende de embarques que viajam através de uma região onde as wyverns podem transformar uma entrega comum em uma jornada perigosa."},pl={title="Innkeeper Faralia",body="Innkeeper Faralia odbiera zaopatrzenie na Stonetalon Peak. Gospoda zależy od przesyłek przemierzających region, w którym wiwerny mogą zamienić zwykłą dostawę w niebezpieczną podróż."},ru={title="Innkeeper Faralia",body="Innkeeper Faralia получает запасы на Stonetalon Peak. Ее гостиница зависит от грузов, проходящих через регион, где виверны могут превратить обычную доставку в опасное путешествие."},references={["place:stonetalon-mountains"]=true}},
    ["person:innkeeper-gryshka"] = {title="Tabernera Gryshka",kind="Personaje",aliases={"Gryshka","Tabernera Gryshka","tabernera Gryshka"},body="La tabernera Gryshka recibe a viajeros en Orgrimmar. Su posada también participa en celebraciones y costumbres de la ciudad, ofreciendo a los visitantes un contacto cotidiano con la vida de la Horda.",aliasQuestIDs={},en={title="Innkeeper Gryshka",aliases={"Gryshka","Innkeeper Gryshka"},body="Innkeeper Gryshka receives travelers in Orgrimmar. Her inn also takes part in the city’s celebrations and customs, giving visitors an everyday connection with Horde life.",aliasQuestIDs={}},fr={title="Innkeeper Gryshka",body="Innkeeper Gryshka reçoit les voyageurs dans Orgrimmar. Son auberge participe également aux célébrations et aux coutumes de la ville, offrant aux visiteurs un lien quotidien avec la vie Horde."},de={title="Innkeeper Gryshka",body="Innkeeper Gryshka empfängt Reisende in Orgrimmar. Ihr Gasthof nimmt auch an den Festen und Bräuchen der Stadt teil und vermittelt den Besuchern eine alltägliche Verbindung mit Hordes Leben."},pt={title="Innkeeper Gryshka",body="Innkeeper Gryshka recebe viajantes em Orgrimmar. Sua pousada também participa das celebrações e costumes da cidade, dando aos visitantes uma conexão diária com a vida Horde."},pl={title="Innkeeper Gryshka",body="Innkeeper Gryshka przyjmuje podróżnych w Orgrimmar. Jej gospoda uczestniczy również w miejskich uroczystościach i zwyczajach, zapewniając przybyszom codzienną więź z życiem frakcji Horde."},ru={title="Innkeeper Gryshka",body="Innkeeper Gryshka принимает путешественников в Orgrimmar. Ее гостиница также принимает участие в празднованиях и обычаях города, предоставляя посетителям повседневную связь с жизнью Horde."},references={["organization:horde"]=true,["place:orgrimmar"]=true}},
    ["person:innkeeper-pala"] = {title="Tabernera Pala",kind="Personaje",aliases={"Pala","Tabernera Pala","tabernera Pala"},body="La tabernera Pala recibe a visitantes de Cima del Trueno y participa en sus celebraciones. Sus intercambios de golosinas por bailes recuerdan que las posadas también mantienen costumbres compartidas entre generaciones.",aliasQuestIDs={},en={title="Innkeeper Pala",aliases={"Innkeeper Pala","Pala"},body="Innkeeper Pala receives visitors to Thunder Bluff and takes part in its celebrations. Her exchanges of treats for dances are a reminder that inns also preserve customs shared across generations.",aliasQuestIDs={}},fr={title="Innkeeper Pala",body="Innkeeper Pala reçoit les visiteurs de Thunder Bluff et participe à ses célébrations. Ses échanges de friandises pour les danses rappellent que les auberges préservent également les coutumes partagées entre les générations."},de={title="Innkeeper Pala",body="Innkeeper Pala empfängt Besucher von Thunder Bluff und nimmt an den Feierlichkeiten teil. Ihr Austausch von Leckereien gegen Tänze erinnert daran, dass Wirtshäuser auch generationenübergreifende Bräuche bewahren."},pt={title="Innkeeper Pala",body="Innkeeper Pala recebe visitantes do Thunder Bluff e participa de suas celebrações. Suas trocas de guloseimas para danças são um lembrete de que as pousadas também preservam os costumes compartilhados entre gerações."},pl={title="Innkeeper Pala",body="Innkeeper Pala przyjmuje gości w Thunder Bluff i uczestniczy w miejscowych uroczystościach. Wymiana smakołyków za tańce przypomina, że gospody także zachowują zwyczaje dzielone przez pokolenia."},ru={title="Innkeeper Pala",body="Innkeeper Pala принимает посетителей Thunder Bluff и участвует в его празднованиях. Ее обмен сладостями на танцы напоминает нам, что гостиницы также сохраняют обычаи, которые были распространены с поколениям."},references={["place:thunder-bluff"]=true}},
    ["person:innkeeper-saelienne"] = {title="Tabernera Saelienne",kind="Personaje",aliases={"Saelienne","Tabernera Saelienne"},body="La tabernera Saelienne participa en las costumbres de Halloween ofreciendo mazapán a quienes bailan para ella. Incluso cuando los dulces están destinados a un niño enfermo, procura conservar el intercambio festivo de trucos y golosinas.",aliasQuestIDs={},en={title="Innkeeper Saelienne",aliases={"Innkeeper Saelienne","Saelienne"},body="Innkeeper Saelienne takes part in Hallow’s End traditions by offering marzipan to those who dance for her. Even when the treats are intended for a sick child, she preserves the festive exchange of tricks and sweets.",aliasQuestIDs={}},fr={title="Innkeeper Saelienne",body="Innkeeper Saelienne participe aux traditions Hallow’s End en offrant du massepain à ceux qui dansent pour elle. Même lorsque les friandises sont destinées à un enfant malade, elle conserve l'échange festif de trucs et de bonbons."},de={title="Innkeeper Saelienne",body="Innkeeper Saelienne nimmt an Hallow’s Ends Traditionen teil, indem sie Marzipan diejenigen verkauft, die für sie tanzen. Auch wenn die Leckereien für ein krankes Kind bestimmt sind, bewahrt sie sich den festlichen Austausch von Tricks und Süßigkeiten."},pt={title="Innkeeper Saelienne",body="Innkeeper Saelienne participa das tradições Hallow’s End, oferecendo marzipan para aqueles que dançam para ela. Mesmo quando as guloseimas são destinadas a uma criança doente, ela preserva a troca festiva de truques e doces."},pl={title="Innkeeper Saelienne",body="Innkeeper Saelienne uczestniczy w tradycjach Hallow’s End, oferując marcepan osobom tańczącym dla niej. Nawet gdy smakołyki są przeznaczone dla chorego dziecka, zachowuje świąteczną wymianę sztuczek i słodyczy."},ru={title="Innkeeper Saelienne",body="Innkeeper Saelienne принимает участие в традициях Hallow’s End, предлагая марципан тем, кто танцует для нее. Даже когда лакомства предназначены для больного ребенка, она сохраняет праздничный обмен хитростями и сладостями."},references={["event:hallows-end"]=true}},
    ["person:isaac-pearson"] = {title="Isaac Pearson",kind="Personaje",aliases={"Isaac","Isaac Pearson"},body="Isaac Pearson busca prosperar en Trinquete, la ciudad costera de Los Baldíos. Mantiene un amor constante por Avelina Lilly, una costurera del Bosque de Argénteos, a pesar de la gran distancia que separa sus vidas.",aliasQuestIDs={},en={title="Isaac Pearson",aliases={"Isaac","Isaac Pearson"},body="Isaac Pearson hopes to prosper in Ratchet, the Barrens’ coastal town. He remains devoted to Avelina Lilly, a tailor in Silverpine Forest, despite the great distance separating their lives.",aliasQuestIDs={}},fr={title="Isaac Pearson",body="Isaac Pearson espère prospérer à Ratchet, la ville côtière de Barrens. Il reste dévoué à Avelina Lilly, tailleur en Silverpine Forest, malgré la grande distance qui sépare leurs vies."},de={title="Isaac Pearson",body="Isaac Pearson hofft, in Ratchet, der Küstenstadt von Barrens, zu gedeihen. Avelina Lilly, einem Schneider in Silverpine Forest, bleibt er trotz der großen Distanz, die ihr Leben trennt, treu."},pt={title="Isaac Pearson",body="Isaac Pearson espera prosperar em Ratchet, a cidade costeira de Barrens. Ele continua dedicado a Avelina Lilly, um alfaiate em Silverpine Forest, apesar da grande distância que separa suas vidas."},pl={title="Isaac Pearson",body="Isaac Pearson liczy na dostatnie życie w Ratchet, nadmorskim mieście w Barrens. Wciąż jest oddany Avelina Lilly, krawcowej w Silverpine Forest, mimo ogromnej odległości dzielącej ich życie."},ru={title="Isaac Pearson",body="Isaac Pearson надеется процветать в Ratchet, прибрежном городе Barrens. Он остается преданным Avelina Lilly, портному в Silverpine Forest, несмотря на большое расстояние, разделяющее их жизни."},references={["place:ratchet"]=true,["place:silverpine-forest"]=true,["place:the-barrens"]=true},questIDs={[65593]=true}},
    ["person:isha-awak"] = {title="Isha Awak",kind="Personaje",aliases={"Isha Awak"},body="Isha Awak es una gran criatura marina de las aguas próximas a Los Baldíos. Sus ataques hacen que los humanos de la costa lo teman, mientras los cazadores tauren ven en su fuerza una prueba digna de respeto.",aliasQuestIDs={},en={title="Isha Awak",aliases={"Isha Awak"},body="Isha Awak is a great sea creature in the waters near the Barrens. His attacks make coastal humans fear him, while tauren hunters see his strength as a challenge worthy of respect.",aliasQuestIDs={}},fr={title="Isha Awak",body="Isha Awak est une grande créature de la mer dans les eaux près de la Barrens. Ses attaques font craindre les humains côtiers, tandis que les chasseurs de taurens voient sa force comme un défi digne de respect."},de={title="Isha Awak",body="Isha Awak ist ein großartiges Meerestier in den Gewässern in der Nähe des Barrens. Seine Angriffe lassen Küstenmenschen vor ihm Angst haben, während Taurenjäger seine Stärke als respektvolle Herausforderung betrachten."},pt={title="Isha Awak",body="Isha Awak é uma grande criatura marinha nas águas perto do Barrens. Seus ataques fazem com que os humanos costeiros o temam, enquanto os caçadores de tauren veem sua força como um desafio digno de respeito."},pl={title="Isha Awak",body="Isha Awak jest wielkim morskim stworzeniem w wodach niedaleko Barrens. Jego ataki budzą lęk nadmorskich ludzi, podczas gdy taurenscy myśliwi widzą w jego sile wyzwanie godne szacunku."},ru={title="Isha Awak",body="Isha Awak - это великое морское существо в водах возле Barrens. Его атаки заставляют людей на побережье бояться его, в то время как охотники на быков видят его силу как вызов, достойный уважения."},references={["place:the-barrens"]=true}},
    ["person:ishamuhale"] = {title="Ishamuhale",kind="Personaje",aliases={"Dientarpón","Ishamuhale"},body="Ishamuhale es un raptor Solescama de Los Baldíos, también llamado Dientarpón. Se distingue por su ferocidad y por una inclinación a la caza que sus observadores consideran parte esencial de su naturaleza.",aliasQuestIDs={},en={title="Ishamuhale",aliases={"Ishamuhale"},body="Ishamuhale is a Sunscale raptor in the Barrens, also known as Speartooth. He is distinguished by his ferocity and a drive to hunt that observers regard as central to his nature.",aliasQuestIDs={}},fr={title="Ishamuhale",body="Ishamuhale est un raptor Sunscale dans le Barrens, également connu sous le nom de Speartooth. Il se distingue par sa férocité et sa chasse que les observateurs considèrent comme un élément central de sa nature."},de={title="Ishamuhale",body="Ishamuhale ist ein Sunscale Raptor in the Barrens, auch bekannt als Speartooth. Er zeichnet sich durch seine Wildheit und seinen Drang zur Jagd aus, die Beobachter als zentral für sein Wesen betrachten."},pt={title="Ishamuhale",body="Ishamuhale é um rapper Sunscale no Barrens, também conhecido como Speartooth. Distingue-se pela sua ferocidade e pela vontade de caçar que os observadores consideram central para a sua natureza."},pl={title="Ishamuhale",body="Ishamuhale jest raptorem Sunscale w regionie Barrens, znanym także jako Speartooth. Wyróżnia go zaciekłość i pęd do polowania uznawany przez obserwatorów za istotę jego natury."},ru={title="Ishamuhale",body="Ishamuhale - это Sunscale раптор из Barrens, также известный как Speartooth. Он отличается своей свирепостью и охотничьим влечением, которые наблюдатели считают центральным его характером."},references={["place:the-barrens"]=true}},
    ["person:islen-waterseer"] = {title="Islen Vidente del Agua",kind="Personaje",aliases={"Islen","Islen Vidente del Agua"},body="Islen Vidente del Agua es una guía chamánica de Los Baldíos vinculada al elemento del agua. Sus enseñanzas presentan el agua como una fuente de vida que debe protegerse de la corrupción.",aliasQuestIDs={},en={title="Islen Waterseer",aliases={"Islen","Islen Waterseer"},body="Islen Waterseer is a shamanic guide in the Barrens associated with the element of water. Her teachings present water as a source of life that must be protected from corruption.",aliasQuestIDs={}},fr={title="Islen Waterseer",body="Islen Waterseer est un guide chamanique dans le Barrens associé à l'élément d'eau. Ses enseignements présentent l’eau comme une source de vie qui doit être protégée de la corruption."},de={title="Islen Waterseer",body="Islen Waterseer ist eine schamanische Führerin in der Barrens, die mit dem Element Wasser in Verbindung gebracht wird. Ihre Lehren stellen Wasser als Lebensquelle dar, die vor Korruption geschützt werden muss."},pt={title="Islen Waterseer",body="Islen Waterseer é um guia xamânico no Barrens associado ao elemento água. Seus ensinamentos apresentam a água como uma fonte de vida que deve ser protegida da corrupção."},pl={title="Islen Waterseer",body="Islen Waterseer jest szamańską przewodniczką w regionie Barrens związaną z żywiołem wody. Jej nauki przedstawiają wodę jako źródło życia, które trzeba chronić przed skażeniem."},ru={title="Islen Waterseer",body="Islen Waterseer - шаманский гид в Barrens, связанный с элементом воды. Ее учения показывают, что вода - источник жизни, который нужно защищать от разложения."},references={["place:the-barrens"]=true}},
    ["person:iverron"] = {title="Iverron",kind="Personaje",aliases={"Iverron"},body="Iverron es un habitante de Teldrassil relacionado con los caminos próximos a Cañada Umbría. Su situación muestra los riesgos que las arañas venenosas suponen incluso cerca de los lugares de formación de los nuevos aventureros.",aliasQuestIDs={},en={title="Iverron",aliases={"Iverron"},body="Iverron is a Teldrassil resident associated with the paths near Shadowglen. His circumstances show the risks that venomous spiders pose even near the training grounds of new adventurers.",aliasQuestIDs={}},fr={title="Iverron",body="Iverron est un résident Teldrassil associé aux chemins proches de Shadowglen. Ses circonstances montrent les risques que les araignées venimeuses posent même près des terrains d'entraînement des nouveaux aventuriers."},de={title="Iverron",body="Iverron ist ein Teldrassil, der mit den Wegen in der Nähe von Shadowglen in Verbindung gebracht wird. Seine Umstände zeigen die Gefahren, die giftige Spinnen selbst in der Nähe von Trainingsplätzen neuer Abenteurer darstellen."},pt={title="Iverron",body="Iverron é um residente Teldrassil associado com os caminhos perto de Shadowglen. Suas circunstâncias mostram os riscos que as aranhas venenosas representam mesmo perto dos campos de treinamento de novos aventureiros."},pl={title="Iverron",body="Iverron jest mieszkańcem Teldrassil związanym ze ścieżkami w pobliżu Shadowglen. Jego sytuacja ukazuje ryzyko stwarzane przez jadowite pająki nawet przy terenach szkoleniowych początkujących poszukiwaczy przygód."},ru={title="Iverron",body="Iverron - это житель Teldrassil, связанный с путями возле Shadowglen. Его обстоятельства показывают, что ядовитые пауки представляют опасность даже вблизи учебных площадок новых искателей приключений."},references={["place:shadowglen"]=true,["place:teldrassil"]=true}},
    ["person:jahan-hawkwing"] = {title="Jahan Ala Halcón",kind="Personaje",aliases={"Jahan","Jahan Ala Halcón"},body="Jahan Ala Halcón comercia con artículos de cuero en El Cruce. Recibe mercancías confeccionadas por Ahanu y atiende la demanda de los numerosos cazadores y aventureros que pasan por el asentamiento.",aliasQuestIDs={},en={title="Jahan Hawkwing",aliases={"Jahan","Jahan Hawkwing"},body="Jahan Hawkwing trades leather goods in the Crossroads. He receives goods made by Ahanu and serves the demand from the many hunters and adventurers passing through the settlement.",aliasQuestIDs={}},fr={title="Jahan Hawkwing",body="Jahan Hawkwing commercialise des articles en cuir dans le Crossroads. Il reçoit des marchandises fabriquées par Ahanu et répond à la demande des nombreux chasseurs et aventuriers qui traversent la colonie."},de={title="Jahan Hawkwing",body="Jahan Hawkwing handelt im Crossroads mit Lederwaren. Er erhält von Ahanu hergestellte Waren und bedient die Nachfrage der vielen Jäger und Abenteurer, die durch die durch die Siedlung ziehen."},pt={title="Jahan Hawkwing",body="Jahan Hawkwing comercializa artigos de couro no Crossroads. Ele recebe bens feitos pela Ahanu e atende a demanda dos muitos caçadores e aventureiros que passam pelo assentamento."},pl={title="Jahan Hawkwing",body="Jahan Hawkwing handluje wyrobami skórzanymi w Crossroads. Odbiera towary wytwarzane przez postać Ahanu i obsługuje popyt licznych myśliwych oraz poszukiwaczy przygód przemierzających osadę."},ru={title="Jahan Hawkwing",body="Jahan Hawkwing торгует кожаными изделиями в Crossroads. Он получает товары, изготовленные Ahanu и обслуживает спрос от многих охотников и авантюристов, проходящих через поселение."},references={["person:ahanu"]=true,["place:the-crossroads"]=true}},
    ["person:jaina-proudmoore"] = {title="Jaina Valiente",kind="Personaje",aliases={"Jaina","Jaina Valiente"},body="Jaina Valiente es una dirigente humana de Theramore. Su posición la vincula a la diplomacia entre los pueblos de Azeroth y a la difícil convivencia de la Alianza y la Horda en Kalimdor.",aliasQuestIDs={},en={title="Jaina Proudmoore",aliases={"Jaina","Jaina Proudmoore"},body="Jaina Proudmoore is a human leader in Theramore. Her position connects her to diplomacy between the peoples of Azeroth and the difficult coexistence of Alliance and Horde in Kalimdor.",aliasQuestIDs={}},fr={title="Jaina Proudmoore",body="Jaina Proudmoore est un leader humain dans Theramore. Sa position la relie à la diplomatie entre les peuples de Azeroth et la difficile coexistence de Alliance avec Horde dans Kalimdor."},de={title="Jaina Proudmoore",body="Jaina Proudmoore ist in Theramore eine menschliche Führungspersönlichkeit. Ihre Position verbindet sie mit der Diplomatie zwischen den Völkern Azeroths und der schwierigen Koexistenz von Alliance und Horde in Kalimdor."},pt={title="Jaina Proudmoore",body="Jaina Proudmoore é um líder humano em Theramore. Sua posição a conecta à diplomacia entre os povos de Azeroth e a difícil coexistência de Alliance com Horde em Kalimdor."},pl={title="Jaina Proudmoore",body="Jaina Proudmoore jest ludzką przywódczynią w Theramore. Jej pozycja wiąże ją z dyplomacją między ludami Azeroth i trudnym współistnieniem frakcji Alliance oraz Horde na kontynencie Kalimdor."},ru={title="Jaina Proudmoore",body="Jaina Proudmoore - человеческий лидер Theramore. Ее позиция связывает ее с дипломатией между народами Azeroth и трудным сосуществованием Alliance и Horde в Kalimdor."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:azeroth"]=true,["place:kalimdor"]=true,["place:theramore"]=true}},
    ["person:jaivhanel"] = {title="Jai'vhanel",kind="Personaje",aliases={"Jai'vhanel","Jai’vhanel","Plumahoja"},body="Jai'vhanel, conocida como Plumahoja, es una búho de plumas negro azabache que ronda las cercanías de Auberdine. Su comportamiento alterado y sus ataques a los viajeros han llevado al concejo del poblado a ofrecer una recompensa por ella.",aliasQuestIDs={},en={title="Jai'vhanel",aliases={"Jai'vhanel","Jai’vhanel","Swordfeather"},body="Jai'vhanel, known as Swordfeather, is an owl with jet-black feathers who prowls near Auberdine. Her disturbed behavior and attacks on travelers have led the village council to offer a bounty on her.",aliasQuestIDs={}},fr={title="Jai'vhanel",body="Jai'vhanel, connu sous le nom de Swordfeather, est un hibou aux plumes noires qui rôde près de Auberdine. Son comportement perturbé et ses attaques contre les voyageurs ont conduit le conseil du village à lui offrir une prime."},de={title="Jai'vhanel",body="Jai'vhanel, bekannt als Swordfeather, ist eine Eule mit tiefschwarzen Federn, die sich in der Nähe von Auberdine umgibt. Ihr gestörtes Verhalten und Angriffe auf Reisende haben den Dorfrat veranlasst, ein Kopfgeld auf sie auszusetzen."},pt={title="Jai'vhanel",body="Jai'vhanel, conhecido como Swordfeather, é uma coruja com penas pretas que ronda perto de Auberdine. Seu comportamento perturbado e ataques aos viajantes levaram o conselho da aldeia a oferecer uma recompensa por ela."},pl={title="Jai'vhanel",body="Jai'vhanel, znana jako Swordfeather, jest sową o kruczoczarnych piórach krążącą koło Auberdine. Niespokojne zachowanie i ataki na podróżnych skłoniły radę wioski do wyznaczenia nagrody za nią."},ru={title="Jai'vhanel",body="Jai'vhanel, известный как Swordfeather, это сова с черно-черными перьями, которая бродит поблизости от Auberdine. Ее беспокойное поведение и нападки на путешественников заставили сельский совет предложить награду за нее."},references={["place:auberdine"]=true}},
    ["person:janela-stouthammer"] = {title="Janela Martillotenaz",kind="Personaje",aliases={"Janela","Janela Martillotenaz"},body="Janela Martillotenaz trabaja en la avanzada de la Brigada de Forjaz cerca de Colmen'Zora. Su labor logística mantiene equipadas a las fuerzas que operan en Silithus, especialmente mediante refuerzos para sus armaduras.",aliasQuestIDs={},en={title="Janela Stouthammer",aliases={"Janela","Janela Stouthammer"},body="Janela Stouthammer works at the Ironforge Brigade’s outpost near Hive'Zora. Her logistical work keeps the forces operating in Silithus equipped, especially through armor reinforcements.",aliasQuestIDs={}},fr={title="Janela Stouthammer",body="Janela Stouthammer travaille à l'avant-poste de la Ironforge Brigade près de Hive'Zora. Son travail logistique permet aux forces d’opérer en Silithus, en particulier grâce à des renforts blindés."},de={title="Janela Stouthammer",body="Janela Stouthammer arbeitet auf dem Außenposten der Ironforge Brigade in der Nähe von Hive'Zora. Ihre logistische Arbeit sorgt dafür, dass die in Silithus operierenden Truppen ausgerüstet sind, vor allem durch Panzerverstärkte Truppen."},pt={title="Janela Stouthammer",body="Janela Stouthammer trabalha no posto avançado do Ironforge Brigade perto de Hive'Zora. Seu trabalho logístico mantém as forças que operam no Silithus equipadas, especialmente através de reforços de armadura."},pl={title="Janela Stouthammer",body="Janela Stouthammer pracuje w posterunku Ironforge Brigade przy Hive'Zora. Jej praca logistyczna zapewnia wyposażenie siłom działającym w Silithus, szczególnie poprzez wzmocnienia zbroi."},ru={title="Janela Stouthammer",body="Janela Stouthammer работает на форпосте Ironforge Brigade  недалеко от Hive'Zora. Ее логистическая работа обеспечивает вооружение сил, действующих в Silithus, особенно с помощью бронежилетов."},references={["organization:ironforge-brigade"]=true,["place:hivezora"]=true,["place:ironforge"]=true,["place:silithus"]=true}},
    ["person:jangdor-swiftstrider"] = {title="Jangdor Zanco Veloz",kind="Personaje",aliases={"Jangdor","Jangdor Zanco Veloz"},body="Jangdor Zanco Veloz es un instructor de peletería del Campamento Mojache. Sus enseñanzas sobre el cuero salvaje relacionan la elección de materiales con la protección, la comodidad y el movimiento de quienes usan las prendas.",aliasQuestIDs={},en={title="Jangdor Swiftstrider",aliases={"Jangdor","Jangdor Swiftstrider"},body="Jangdor Swiftstrider is a leatherworking instructor in Camp Mojache. His lessons on wild leather connect the choice of materials with the protection, comfort and movement of the wearer.",aliasQuestIDs={}},fr={title="Jangdor Swiftstrider",body="Jangdor Swiftstrider est un instructeur de travail du cuir dans Camp Mojache. Ses leçons sur le cuir sauvage relient le choix des matériaux à la protection, au confort et au mouvement du porteur."},de={title="Jangdor Swiftstrider",body="Jangdor Swiftstrider ist Lederverarbeitungslehrer bei Camp Mojache. Seine Lektionen über Wildleder verbinden die Materialwahl mit dem Schutz, Komfort und der Beweglichkeit des Trägers."},pt={title="Jangdor Swiftstrider",body="Jangdor Swiftstrider é um instrutor de couro em Camp Mojache. Suas lições sobre couro selvagem conectam a escolha de materiais com a proteção, conforto e movimento do usuário."},pl={title="Jangdor Swiftstrider",body="Jangdor Swiftstrider jest nauczycielem kaletnictwa w Camp Mojache. Jego nauki o dzikiej skórze wiążą wybór materiałów z ochroną, wygodą i swobodą ruchu użytkownika."},ru={title="Jangdor Swiftstrider",body="Jangdor Swiftstrider - инструктор по кожевенному делу в Camp Mojache. Его уроки о дикой коже связывают выбор материалов с защитой, комфортом и движением носителя."},references={["place:camp-mojache"]=true}},
    ["person:jannok-breezesong"] = {title="Jannok Brisón",kind="Personaje",aliases={"Jannok","Jannok Brisón"},body="Jannok está enamorado de Syurna y llena su hogar de retratos de ella. Sus mensajes y flores expresan una devoción que no es correspondida, pues ella ha dejado claro que no desea recibirlo.",aliasQuestIDs={},en={title="Jannok Breezesong",aliases={"Jannok","Jannok Breezesong"},body="Jannok is infatuated with Syurna and fills his home with pictures of her. His messages and flowers express an unreturned devotion, as she has made clear that she does not wish to see him.",aliasQuestIDs={}},fr={title="Jannok Breezesong",body="Jannok est épris de Syurna et remplit sa maison avec des photos d'elle. Ses messages et ses fleurs expriment une dévotion non retournée, car elle a clairement fait savoir qu’elle ne souhaitait pas le voir."},de={title="Jannok Breezesong",body="Jannok ist von Syurna vernarrt und füllt sein Zuhause mit Bildern von ihr. Seine Botschaften und Blumen drücken eine nicht erwiderte Hingabe aus, da sie deutlich gemacht hat, dass sie ihn nicht sehen möchte."},pt={title="Jannok Breezesong",body="Jannok é apaixonado por Syurna e enche sua casa com fotos dela. Suas mensagens e flores expressam uma devoção não devolvida, pois ela deixou claro que não deseja vê-lo."},pl={title="Jannok Breezesong",body="Jannok jest zauroczony postacią Syurna i wypełnia dom jej podobiznami. Wiadomości i kwiaty wyrażają nieodwzajemnione oddanie, gdyż jasno powiedziała, że nie chce go widzieć."},ru={title="Jannok Breezesong",body="Jannok влюблен в Syurna и заполняет свой дом ее фотографиями. Его сообщения и цветы выражают безвозвратную преданность, так как она ясно дала понять, что не хочет его видеть."},references={["person:syurna"]=true}},
    ["person:jaron-stoneshaper"] = {title="Jaron Tallapiedras",kind="Personaje",aliases={"Jaron","Jaron Tallapiedras"},body="Jaron Tallapiedras estudia sucesos de Cuna del Invierno desde la Aldea Estrella Fugaz. Su trabajo lo relaciona con los campamentos y criaturas de una región donde los cambios de comportamiento pueden volverse peligrosos.",aliasQuestIDs={},en={title="Jaron Stoneshaper",aliases={"Jaron","Jaron Stoneshaper"},body="Jaron Stoneshaper studies events in Winterspring from Starfall Village. His work concerns the camps and creatures of a region where changes in behavior can become dangerous.",aliasQuestIDs={}},fr={title="Jaron Stoneshaper",body="Jaron Stoneshaper étudie les événements dans Winterspring de Starfall Village. Son travail concerne les camps et les créatures d’une région où les changements de comportement peuvent devenir dangereux."},de={title="Jaron Stoneshaper",body="Jaron Stoneshaper studiert Ereignisse in Winterspring von Starfall Village. Seine Arbeit betrifft die Lager und Lebewesen einer Region, in der Verhaltensänderungen gefährlich werden können."},pt={title="Jaron Stoneshaper",body="Jaron Stoneshaper estuda eventos em Winterspring de Starfall Village. Seu trabalho diz respeito aos campos e criaturas de uma região onde as mudanças de comportamento podem se tornar perigosas."},pl={title="Jaron Stoneshaper",body="Jaron Stoneshaper bada wydarzenia w Winterspring, działając z Starfall Village. Jego praca dotyczy obozów i stworzeń regionu, gdzie zmiany zachowania mogą stać się niebezpieczne."},ru={title="Jaron Stoneshaper",body="Jaron Stoneshaper изучает события в Winterspring от Starfall Village. Его работа касается лагерей и существ в регионе, где изменения поведения могут стать опасными."},references={["place:starfall-village"]=true,["place:winterspring"]=true}},
    ["person:javnir-nashak"] = {title="Javnir Nashak",kind="Personaje",aliases={"Javnir","Javnir Nashak"},body="Javnir Nashak participa en el Festival de la Cosecha honrando a los héroes de la Horda. Promueve las ofrendas al monumento de Grom Grito Infernal como una manera de recordar la fuerza y los sacrificios de quienes protegieron a su pueblo.",aliasQuestIDs={},en={title="Javnir Nashak",aliases={"Javnir","Javnir Nashak"},body="Javnir Nashak takes part in the Harvest Festival by honoring the Horde’s heroes. He encourages offerings at Grom Hellscream’s monument as a way to remember the strength and sacrifices of those who protected their people.",aliasQuestIDs={}},fr={title="Javnir Nashak",body="Javnir Nashak participe au Harvest Festival en honorant les héros du Horde. Il encourage les offrandes au monument de Grom Hellscream comme un moyen de se souvenir de la force et des sacrifices de ceux qui ont protégé leur peuple."},de={title="Javnir Nashak",body="Javnir Nashak beteiligt sich am Harvest Festival, indem er die Helden der Horde ehrt. Er regt dazu an, am Denkmal von Grom Hellscream Opfergaben niederzulegen, um an die Stärke und die Opfer jener zu erinnern, die ihr Volk beschützten."},pt={title="Javnir Nashak",body="Javnir Nashak participa no Harvest Festival honrando os heróis do Horde. Ele incentiva as ofertas no monumento do Grom Hellscream como uma maneira de lembrar a força e os sacrifícios daqueles que protegeram seu povo."},pl={title="Javnir Nashak",body="Javnir Nashak uczestniczy w Harvest Festival, oddając cześć bohaterom frakcji Horde. Zachęca do składania darów przy pomniku postaci Grom Hellscream, by pamiętać siłę i poświęcenia obrońców swojego ludu."},ru={title="Javnir Nashak",body="Javnir Nashak принимает участие в Harvest Festival, чествуя героев Horde s. Он поощряет жертвоприношения на памятнике Grom Hellscream как способ вспомнить о силе и жертвах тех, кто защищал свой народ."},references={["event:harvest-festival"]=true,["npc:grom-hellscream"]=true,["organization:horde"]=true}},
    ["person:jd-collie"] = {title="J.D. Collie",kind="Personaje",aliases={"J.D.","J.D. Collie"},body="J.D. Collie es una gnoma que investiga los cristales del Cráter de Un'Goro desde una cueva del Refugio de Marshal. Sus experimentos buscan comprender las propiedades y posibles usos de esos materiales.",aliasQuestIDs={},en={title="J.D. Collie",aliases={"J.D.","J.D. Collie"},body="J.D. Collie is a gnome researching the crystals of Un'Goro Crater from a cave in Marshal's Refuge. Her experiments seek to understand the properties and possible uses of those materials.",aliasQuestIDs={}},fr={title="J.D. Collie",body="J.D. Collie est un gnome recherchant les cristaux de Un'Goro Crater d'une caverne dans Marshal's Refuge. Ses expériences visent à comprendre les propriétés et les utilisations possibles de ces matériaux."},de={title="J.D. Collie",body="J.D. Collie ist ein Gnom, der die Kristalle von Un'Goro Crater aus einer Höhle in Marshal's Refuge erforscht. Ihre Experimente versuchen, die Eigenschaften und Einsatzmöglichkeiten dieser Materialien zu verstehen."},pt={title="J.D. Collie",body="J.D. Collie é um gnomo que pesquisa os cristais de Un'Goro Crater de uma caverna em Marshal's Refuge. Seus experimentos buscam entender as propriedades e possíveis usos desses materiais."},pl={title="J.D. Collie",body="J.D. Collie jest gnomką badającą kryształy Un'Goro Crater w jaskini w Marshal's Refuge. Jej eksperymenty służą poznaniu właściwości oraz możliwych zastosowań tych materiałów."},ru={title="J.D. Collie",body="J.D. Collie - это гном, который изучает кристаллы Un'Goro Crater из пещеры в Marshal's Refuge. Ее эксперименты направлены на понимание свойств и возможных применений этих материалов."},references={["place:marshals-refuge"]=true,["place:ungoro-crater"]=true}},
    ["person:jediga"] = {title="Jediga",kind="Personaje",aliases={"Jediga"},body="Jediga es una goblin de Azshara interesada en los objetos valiosos de sus ruinas. Sus contactos con estudiosos de la magia le permiten convertir los vestigios de los Altonato en oportunidades comerciales.",aliasQuestIDs={},en={title="Jediga",aliases={"Jediga"},body="Jediga is a goblin in Azshara interested in the valuable objects within its ruins. Her contacts among magical scholars allow her to turn Highborne relics into business opportunities.",aliasQuestIDs={}},fr={title="Jediga",body="Jediga est un gobelin en Azshara intéressé par les objets de valeur dans ses ruines. Ses contacts parmi les érudits magiques lui permettent de transformer les reliques Highborne en opportunités d'affaires."},de={title="Jediga",body="Jediga ist ein Goblin in Azshara, der sich für die wertvollen Gegenstände in den Ruinen interessiert. Ihre Kontakte unter magischen Gelehrten ermöglichen es ihr, Highborne-Reliquien in Geschäftschancen zu verwandeln."},pt={title="Jediga",body="Jediga é um goblin em Azshara interessado nos objetos valiosos dentro de suas ruínas. Seus contatos entre estudiosos mágicos permitem que ela transforme relíquias Highborne em oportunidades de negócios."},pl={title="Jediga",body="Jediga jest goblinką w regionie Azshara zainteresowaną cennymi przedmiotami skrytymi w ruinach. Kontakty z badaczami magii pozwalają jej zamieniać relikty Highborne w okazje do interesów."},ru={title="Jediga",body="Jediga - гоблин в Azshara, заинтересованный ценными предметами внутри его руин. Ее контакты с магическими учеными позволяют ей превратить реликвии Highborne в возможности для бизнеса."},references={["organization:highborne"]=true,["place:azshara"]=true}},
    ["person:jenal"] = {title="Jenal",kind="Personaje",aliases={"Jenal"},body="Jenal se ocupa de la logística de las muestras de tierra destinadas a las investigaciones del Círculo Cenarion. Su labor permite reunir materiales de Un’Goro para estudiar las propiedades mágicas atribuidas al suelo del cráter.",aliasQuestIDs={},en={title="Jenal",aliases={"Jenal"},body="Jenal handles the logistics of soil samples intended for Cenarion Circle research. His work gathers material from Un’Goro for study of the magical qualities attributed to the crater’s soil.",aliasQuestIDs={}},fr={title="Jenal",body="Jenal gère la logistique des échantillons de sol destinés à la recherche Cenarion Circle. Son travail rassemble du matériel de Un’Goro pour l’étude des qualités magiques attribuées au sol du cratère."},de={title="Jenal",body="Jenal kümmert sich um die Logistik der Bodenproben für die Cenarion Circle-Forschung. Seine Arbeit sammelt Material von Un’Goro, um die magischen Eigenschaften zu studieren, die dem Boden des Kraters zugeschrieben werden."},pt={title="Jenal",body="Jenal lida com a logística de amostras de solo destinadas à pesquisa Cenarion Circle. Seu trabalho reúne material da Un’Goro para o estudo das qualidades mágicas atribuídas ao solo da cratera."},pl={title="Jenal",body="Jenal zajmuje się logistyką próbek gleby do badań Cenarion Circle. Gromadzi materiał z Un’Goro na potrzeby badania magicznych właściwości przypisywanych glebie krateru."},ru={title="Jenal",body="Jenal занимается логистикой образцов почвы, предназначенных для исследований Cenarion Circle. Его работа собирает материал из Un’Goro для изучения магических качеств, приписываемых почве кратера."},references={["organization:cenarion-circle"]=true,["place:ungoro-crater"]=true}},
    ["person:jeneu-sancrea"] = {title="Je'neu Sancrea",kind="Personaje",aliases={"Je'neu","Je'neu Sancrea","Je’neu","Je’neu Sancrea"},body="Je'neu Sancrea es un estudioso de Zoram'gar que investiga los peligros de las Cavernas de Brazanegra. Su conocimiento de los espíritus de la naturaleza lo enfrenta a los cultos que veneran el caos y la destrucción.",aliasQuestIDs={},en={title="Je'neu Sancrea",aliases={"Je'neu","Je'neu Sancrea","Je’neu","Je’neu Sancrea"},body="Je'neu Sancrea is a scholar in Zoram'gar investigating the dangers of Blackfathom Deeps. His knowledge of nature spirits brings him into conflict with cults venerating chaos and destruction.",aliasQuestIDs={}},fr={title="Je'neu Sancrea",body="Je'neu Sancrea est un chercheur en Zoram'gar qui étudie les dangers de Blackfathom Deeps. Sa connaissance des esprits de la nature le met en conflit avec les cultes vénérant le chaos et la destruction."},de={title="Je'neu Sancrea",body="Je'neu Sancrea ist ein Gelehrter in Zoram'gar, der die Gefahren von Blackfathom Deeps untersucht. Seine Kenntnis der Naturgeister bringt ihn in Konflikt mit Kulten, die Chaos und Zerstörung verehren."},pt={title="Je'neu Sancrea",body="Je'neu Sancrea é um estudioso em Zoram'gar investigando os perigos de Blackfathom Deeps. Seu conhecimento dos espíritos da natureza o coloca em conflito com cultos que veneram o caos e a destruição."},pl={title="Je'neu Sancrea",body="Je'neu Sancrea jest uczonym w Zoram'gar badającym niebezpieczeństwa Blackfathom Deeps. Znajomość duchów przyrody prowadzi go do konfliktu z kultami czczącymi chaos oraz zniszczenie."},ru={title="Je'neu Sancrea",body="Je'neu Sancrea - ученый из Zoram'gar, который исследует опасность Blackfathom Deeps. Его знания о природе приводят его в конфликт с культами, поклоняющимися хаосу и разрушению."},references={["place:blackfathom-deeps"]=true,["place:zoramgar-outpost"]=true}},
    ["person:jenshan"] = {title="Jen'shan",kind="Personaje",aliases={"Jen'shan","Jen’shan"},body="Jen'shan es una instructora de cazadores del Valle de los Retos. Su formación forma parte del aprendizaje inicial con el que los nuevos miembros de la Horda se preparan para recorrer Durotar.",aliasQuestIDs={},en={title="Jen'shan",aliases={"Jen'shan","Jen’shan"},body="Jen'shan is a hunter trainer in the Valley of Trials. Her teaching is part of the early training through which new Horde members prepare to travel Durotar.",aliasQuestIDs={}},fr={title="Jen'shan",body="Jen'shan est un entraîneur de chasse dans le Valley of Trials. Son enseignement fait partie de la formation initiale à travers laquelle les nouveaux membres de Horde se préparent à voyager Durotar."},de={title="Jen'shan",body="Jen'shan ist Jägerin im Valley of Trials. Ihr Unterricht ist Teil des Frühtrainings, mit dem sich neue Horde-Mitglieder darauf vorbereiten, Durotar zu bereisen."},pt={title="Jen'shan",body="Jen'shan é um treinador de caçadores no Valley of Trials. Seu ensino faz parte do treinamento inicial através do qual os novos membros da Horde se preparam para viajar Durotar."},pl={title="Jen'shan",body="Jen'shan jest nauczycielką łowców w Valley of Trials. Jej nauczanie należy do początkowego szkolenia przygotowującego nowych członków frakcji Horde do podróży po Durotar."},ru={title="Jen'shan",body="Jen'shan обучает охотников в Valley of Trials. Ее преподавание является частью ранней подготовки, через которую новые члены Horde готовятся к путешествиям Durotar."},references={["organization:horde"]=true,["place:durotar"]=true,["place:valley-of-trials"]=true}},
    ["person:jerkai-moonweaver"] = {title="Jer'kai Tejeluna",kind="Personaje",aliases={"Jer'kai","Jer'kai Tejeluna","Jer’kai","Jer’kai Tejeluna"},body="Jer'kai Tejeluna actúa junto a Kindal en Feralas. Su labor busca responder a los Tótem Siniestro y proteger a las criaturas atrapadas por sus fuerzas.",aliasQuestIDs={},en={title="Jer'kai Moonweaver",aliases={"Jer'kai","Jer'kai Moonweaver","Jer’kai","Jer’kai Moonweaver"},body="Jer'kai Moonweaver acts alongside Kindal in Feralas. Her work seeks to answer the Grimtotem and protect creatures trapped by their forces.",aliasQuestIDs={}},fr={title="Jer'kai Moonweaver",body="Jer'kai Moonweaver agit aux côtés de Kindal dans Feralas. Son travail cherche à répondre au Grimtotem et à protéger les créatures piégées par leurs forces."},de={title="Jer'kai Moonweaver",body="Jer'kai Moonweaver spielt an der Seite von Kindal in Feralas. Ihre Arbeit versucht, die Grimtotem zu beantworten und Kreaturen zu schützen, die von ihren Kräften gefangen sind."},pt={title="Jer'kai Moonweaver",body="Jer'kai Moonweaver atua ao lado de Kindal em Feralas. Seu trabalho procura responder ao Grimtotem e proteger criaturas presas por suas forças."},pl={title="Jer'kai Moonweaver",body="Jer'kai Moonweaver działa u boku postaci Kindal w Feralas. Jej praca służy przeciwstawianiu się Grimtotem i ochronie stworzeń uwięzionych przez ich siły."},ru={title="Jer'kai Moonweaver",body="Jer'kai Moonweaver действует вместе с Kindal в Feralas. Ее работа направлена на то, чтобы ответить на Grimtotem и защитить существ, попавших в ловушку их сил."},references={["organization:grimtotem"]=true,["person:kindal-moonweaver"]=true,["place:feralas"]=true}},
    ["person:jesrimon"] = {title="Jes'rimon",kind="Personaje",aliases={"Jes'rimon","Jes’rimon"},body="Jes'rimon vive en Orgrimmar y se interesa por tablillas y objetos mágicos de origen antiguo. Sus contactos le permiten obtener piezas que requieren tanto recursos como discreción.",aliasQuestIDs={},en={title="Jes'rimon",aliases={"Jes'rimon","Jes’rimon"},body="Jes'rimon lives in Orgrimmar and takes an interest in tablets and magical objects of ancient origin. His contacts allow him to obtain pieces requiring both resources and discretion.",aliasQuestIDs={}},fr={title="Jes'rimon",body="Jes'rimon vit à Orgrimmar et s'intéresse aux tablettes et objets magiques d'origine ancienne. Ses contacts lui permettent d’obtenir des pièces nécessitant à la fois des ressources et de la discrétion."},de={title="Jes'rimon",body="Jes'rimon lebt in Orgrimmar und interessiert sich für Tabletten und magische Objekte uralten Ursprungs. Seine Kontakte ermöglichen es ihm, Stücke zu erwerben, die sowohl Ressourcen als auch Diskretion erfordern."},pt={title="Jes'rimon",body="Jes'rimon vive em Orgrimmar e tem interesse em tablets e objetos mágicos de origem antiga. Seus contatos permitem que ele obtenha peças que exigem recursos e discrição."},pl={title="Jes'rimon",body="Jes'rimon mieszka w Orgrimmar i interesuje się tablicami oraz magicznymi przedmiotami pradawnego pochodzenia. Kontakty pozwalają mu zdobywać elementy wymagające zarówno zasobów, jak i dyskrecji."},ru={title="Jes'rimon",body="Jes'rimon живет в Orgrimmar и интересуется табличками и магическими предметами древнего происхождения. Его контакты позволяют ему получить кусочки, требующие ресурсов и дискреции."},references={["place:orgrimmar"]=true}},
    ["person:jessir-moonbow"] = {title="Jessir Arcolunar",kind="Personaje",aliases={"Jessir","Jessir Arcolunar"},body="Jessir Arcolunar mantiene vínculos con exploradores que recorren Frondavil. Sus contactos cerca de Vallefresno permiten recibir noticias sobre quienes se enfrentan a la corrupción del bosque.",aliasQuestIDs={},en={title="Jessir Moonbow",aliases={"Jessir","Jessir Moonbow"},body="Jessir Moonbow maintains ties with explorers traveling Felwood. Her contacts near Ashenvale allow her to receive news about those confronting the forest’s corruption.",aliasQuestIDs={}},fr={title="Jessir Moonbow",body="Jessir Moonbow entretient des liens avec les explorateurs voyageant Felwood. Ses contacts près de Ashenvale lui permettent de recevoir des nouvelles de ceux qui sont confrontés à la corruption de la forêt."},de={title="Jessir Moonbow",body="Jessir Moonbow unterhält Verbindungen zu Entdeckern, die Felwood bereisen. Ihre Kontakte in der Nähe von Ashenvale ermöglichen es ihr, Nachrichten über diejenigen zu erhalten, die mit denen es zu tun haben, die mit der Korruption im Wald zu kämpfen."},pt={title="Jessir Moonbow",body="Jessir Moonbow mantém laços com exploradores que viajam Felwood. Seus contatos perto de Ashenvale permitem que ela receba notícias sobre aqueles que enfrentam a corrupção da floresta."},pl={title="Jessir Moonbow",body="Jessir Moonbow utrzymuje więzi z odkrywcami przemierzającymi Felwood. Kontakty w pobliżu Ashenvale pozwalają jej otrzymywać wiadomości o osobach stawiających czoła skażeniu lasu."},ru={title="Jessir Moonbow",body="Jessir Moonbow поддерживает связи с исследователями, путешествующими Felwood. Ее контакты вблизи Ashenvale позволяют ей получать новости о тех, кто сталкивается с порчей леса."},references={["place:ashenvale"]=true,["place:felwood"]=true}},
    ["person:jinarzillen"] = {title="Jinar'Zillen",kind="Personaje",aliases={"Jinar'Zillen","Jinar’Zillen"},body="Jinar'Zillen es un pescador de la Aldea Cazasombras. Su pesca de panzasangre abastece incluso a quienes viven lejos de la costa, como los habitantes del Campamento del Espíritu Errante.",aliasQuestIDs={},en={title="Jinar'Zillen",aliases={"Jinar'Zillen","Jinar’Zillen"},body="Jinar'Zillen is a fisherman in Shadowprey Village. His Bloodbelly catch supplies even those living far from the coast, including people at Ghost Walker Post.",aliasQuestIDs={}},fr={title="Jinar'Zillen",body="Jinar'Zillen est un pêcheur dans Shadowprey Village. Ses prises Bloodbelly approvisionnent même ceux qui vivent loin de la côte, y compris les gens de Ghost Walker Post."},de={title="Jinar'Zillen",body="Jinar'Zillen ist Fischer in Shadowprey Village. Sein Bloodbelly-Fang versorgt sogar diejenigen, die weit von der Küste entfernt leben, darunter auch die Leute von der Ghost Walker Post."},pt={title="Jinar'Zillen",body="Jinar'Zillen é um pescador em Shadowprey Village. Sua captura Bloodbelly fornece até mesmo aqueles que vivem longe da costa, incluindo pessoas no Ghost Walker Post."},pl={title="Jinar'Zillen",body="Jinar'Zillen jest rybakiem w Shadowprey Village. Połów ryb Bloodbelly zaopatruje nawet mieszkańców odległych od wybrzeża, w tym osoby z Ghost Walker Post."},ru={title="Jinar'Zillen",body="Jinar'Zillen - рыбак в Shadowprey Village. Его вылов Bloodbelly снабжает даже тех, кто живет далеко от побережья, включая людей в Пост Призрака Уокера."},references={["place:shadowprey-village"]=true}},
    ["person:jocaste"] = {title="Jocaste",kind="Personaje",aliases={"Jocaste"},body="Jocaste es una cazadora venerada que instruye en Darnassus. Su trato puede parecer severo, pero acoge con satisfacción a los nuevos cazadores y les enseña a cuidar y entrenar a sus compañeros animales.",aliasQuestIDs={},en={title="Jocaste",aliases={"Jocaste"},body="Jocaste is a revered hunter who teaches in Darnassus. Her manner may seem stern, but she welcomes rising hunters and teaches them to care for and train their animal companions.",aliasQuestIDs={}},fr={title="Jocaste",body="Jocaste est un chasseur vénéré qui enseigne dans Darnassus. Sa manière peut sembler sévère, mais elle accueille les chasseurs et leur apprend à prendre soin et à former leurs compagnons animaux."},de={title="Jocaste",body="Jocaste ist eine verehrte Jägerin, die in Darnassus unterrichtet. Ihre Art mag streng erscheinen, aber sie begrüßt aufstrebende Jäger und lehrt sie, ihre tierischen Begleiter zu pflegen und auszubilden."},pt={title="Jocaste",body="Jocaste é um caçador reverenciado que ensina em Darnassus. Sua maneira pode parecer severa, mas ela acolhe caçadores em ascensão e os ensina a cuidar e treinar seus companheiros de animais."},pl={title="Jocaste",body="Jocaste jest czczoną łowczynią nauczającą w Darnassus. Może wydawać się surowa, lecz przyjmuje rozwijających się łowców i uczy opiekowania się zwierzęcymi towarzyszami oraz ich szkolenia."},ru={title="Jocaste",body="Jocaste - это почитаемый охотник, который преподает на Darnassus. Она может показаться строгой, но она радушно принимает начинающих охотников и учит их заботиться и тренировать своих животных-сопутников."},references={["place:darnassus"]=true}},
    ["person:jorn-skyseer"] = {title="Jorn Vidente del Cielo",kind="Personaje",aliases={"Jorn","Jorn Vidente del Cielo"},body="Jorn Vidente del Cielo es un guía tauren del Campamento Taurajo. Su visión de la caza reúne la prueba personal con el respeto por los grandes animales de Los Baldíos.",aliasQuestIDs={},en={title="Jorn Skyseer",aliases={"Jorn","Jorn Skyseer"},body="Jorn Skyseer is a tauren guide at Camp Taurajo. His view of hunting joins personal trials with respect for the Barrens’ great animals.",aliasQuestIDs={}},fr={title="Jorn Skyseer",body="Jorn Skyseer est un guide tauren chez Camp Taurajo. Sa vision de la chasse rejoint les essais personnels dans le respect des grands animaux de la Barrens."},de={title="Jorn Skyseer",body="Jorn Skyseer ist Tauren-Guide bei Camp Taurajo. Seine Sicht der Jagd verbindet persönliche Prüfungen mit Respekt vor den großen Tieren des Barrens."},pt={title="Jorn Skyseer",body="Jorn Skyseer é um guia de tauren em Camp Taurajo. Sua visão de caça se junta a testes pessoais com respeito aos grandes animais do Barrens."},pl={title="Jorn Skyseer",body="Jorn Skyseer jest taurenskim przewodnikiem w Camp Taurajo. Jego podejście do polowania łączy osobiste próby z szacunkiem dla wielkich zwierząt regionu Barrens."},ru={title="Jorn Skyseer",body="Jorn Skyseer - это путеводитель быка в Camp Taurajo. В его понимании охоты личные испытания сочетаются с уважением к великим зверям Barrens."},references={["place:camp-taurajo"]=true,["place:the-barrens"]=true}},
    ["person:kadrak"] = {title="Kadrak",kind="Personaje",aliases={"Kadrak"},body="Kadrak coordina informes de los exploradores de la Horda entre Los Baldíos y Vallefresno. Los mensajeros que acuden a sus avanzadas mantienen el flujo de órdenes y noticias necesario para vigilar el territorio.",aliasQuestIDs={},en={title="Kadrak",aliases={"Kadrak"},body="Kadrak coordinates reports from Horde scouts between the Barrens and Ashenvale. Messengers traveling to the outposts maintain the flow of orders and news needed to watch the territory.",aliasQuestIDs={}},fr={title="Kadrak",body="Kadrak coordonne les rapports des éclaireurs Horde entre Barrens et Ashenvale. Les messagers qui se rendent aux avant-postes maintiennent le flux d’ordres et de nouvelles nécessaires pour surveiller le territoire."},de={title="Kadrak",body="Kadrak koordiniert die Berichte von Horde-Pfadfindern zwischen Barrens und Ashenvale. Boten, die zu den Außenposten reisen, halten den Fluss von Befehlen und Nachrichten aufrecht, die notwendig sind, um das Gebiet zu überwachen."},pt={title="Kadrak",body="Kadrak coordena relatórios de escoteiros Horde entre o Barrens e Ashenvale. Os mensageiros que viajam para os postos avançados mantêm o fluxo de ordens e notícias necessárias para observar o território."},pl={title="Kadrak",body="Kadrak koordynuje raporty zwiadowców frakcji Horde między Barrens i Ashenvale. Posłańcy podróżujący do posterunków zapewniają przepływ rozkazów oraz wieści potrzebnych do obserwowania terytorium."},ru={title="Kadrak",body="Kadrak координирует сообщения разведчиков Horde между Barrens и Ashenvale. Посланники, направляющиеся в форпосты, обеспечивают поток приказов и новостей, необходимых для наблюдения за территорией."},references={["organization:horde"]=true,["place:ashenvale"]=true,["place:the-barrens"]=true}},
    ["person:kaela-shadowspear"] = {title="Kaela Lanzasombra",kind="Personaje",aliases={"Kaela","Kaela Lanzasombra"},body="Kaela Lanzasombra es una centinela que investiga el daño causado en Sierra Espolón. Su colaboración con Gaxim Silvóxido reúne métodos distintos alrededor de un objetivo compartido: detener la destrucción de la tierra.",aliasQuestIDs={},en={title="Kaela Shadowspear",aliases={"Kaela","Kaela Shadowspear"},body="Kaela Shadowspear is a sentinel investigating the damage in the Stonetalon Mountains. Her collaboration with Gaxim Rustfizzle brings different methods together around a shared goal: stopping the land’s destruction.",aliasQuestIDs={}},fr={title="Kaela Shadowspear",body="Kaela Shadowspear est une sentinelle enquêtant sur les dommages dans le Stonetalon Mountains. Sa collaboration avec Gaxim Rustfizzle rassemble différentes méthodes autour d’un objectif commun: arrêter la destruction de la terre."},de={title="Kaela Shadowspear",body="Kaela Shadowspear ist eine Wache, die den Schaden in der Stonetalon Mountains untersucht. Ihre Zusammenarbeit mit Gaxim Rustfizzle bringt verschiedene Methoden um ein gemeinsames Ziel zusammen: die Zerstörung des Landes zu stoppen."},pt={title="Kaela Shadowspear",body="Kaela Shadowspear é uma sentinela que investiga os danos no Stonetalon Mountains. Sua colaboração com a Gaxim Rustfizzle reúne diferentes métodos em torno de um objetivo compartilhado: parar a destruição da terra."},pl={title="Kaela Shadowspear",body="Kaela Shadowspear jest strażniczką badającą zniszczenia w regionie Stonetalon Mountains. Współpraca z postacią Gaxim Rustfizzle łączy odmienne metody we wspólnym celu: powstrzymaniu dewastacji ziemi."},ru={title="Kaela Shadowspear",body="Kaela Shadowspear - это сторожевой, который расследует повреждения в Stonetalon Mountains. Ее сотрудничество с Gaxim Rustfizzle объединяет различные методы вокруг общей цели: остановить разрушение земли."},references={["person:gaxim-rustfizzle"]=true,["place:stonetalon-mountains"]=true}},
    ["person:kaga-wildhoof"] = {title="Kuga Cascosalvaje",kind="Personaje",aliases={"Kuga","Kuga Cascosalvaje"},body="Kuga Cascosalvaje es una aventurera que acampa a las afueras del Poblado Pezuña de Sangre. Comparte conocimientos para sobrevivir en la naturaleza y pertenece a quienes buscan fortuna y gloria sin quedarse demasiado tiempo en un mismo lugar.",aliasQuestIDs={},en={title="Kaga Wildhoof",aliases={"Kaga","Kaga Wildhoof"},body="Kaga Wildhoof is an adventurer camped outside Bloodhoof Village. She shares wilderness survival skills and numbers among those who seek fortune and glory beyond a settled life.",aliasQuestIDs={}},fr={title="Kaga Wildhoof",body="Kaga Wildhoof est un aventurier campé en dehors de Bloodhoof Village. Elle partage des compétences et des chiffres de survie en milieu sauvage parmi ceux qui cherchent la fortune et la gloire au-delà d'une vie stable."},de={title="Kaga Wildhoof",body="Kaga Wildhoof ist eine Abenteurerin, die außerhalb von Bloodhoof Village kampiert. Sie teilt die Fähigkeiten zum Überleben in der Wildnis und zählt zu denen, die nach Glück und Ruhm jenseits eines geregelten Lebens streben."},pt={title="Kaga Wildhoof",body="Kaga Wildhoof é um aventureiro acampado fora de Bloodhoof Village. Ela compartilha habilidades de sobrevivência no deserto e números entre aqueles que buscam fortuna e glória além de uma vida estabelecida."},pl={title="Kaga Wildhoof",body="Kaga Wildhoof jest poszukiwaczką przygód obozującą poza Bloodhoof Village. Dzieli się umiejętnościami przetrwania i należy do osób szukających fortuny oraz chwały poza osiadłym życiem."},ru={title="Kaga Wildhoof",body="Kaga Wildhoof - это авантюрист, который расположен за пределами Bloodhoof Village. Она делится навыками выживания в дикой природе и численностью среди тех, кто ищет удачу и славу за пределами устойчивой жизни."},references={["place:bloodhoof-village"]=true}},
    ["person:kali-remik"] = {title="Kali Remik",kind="Personaje",aliases={"Kali Remik"},body="Kali Remik es un trol del Poblado Sen'jin que participa en las celebraciones de Halloween. Sus golosinas y pequeños desafíos permiten que los visitantes conozcan una tradición compartida por las comunidades de la Horda.",aliasQuestIDs={},en={title="Kali Remik",aliases={"Kali Remik"},body="Kali Remik is a troll in Sen'jin Village who takes part in Hallow’s End celebrations. His treats and small challenges let visitors experience a tradition shared by Horde communities.",aliasQuestIDs={}},fr={title="Kali Remik",body="Kali Remik est un troll de Sen'jin Village qui participe aux célébrations Hallow’s End. Ses friandises et ses petits défis permettent aux visiteurs de découvrir une tradition partagée par les communautés Horde."},de={title="Kali Remik",body="Kali Remik ist in Sen'jin Village ein Troll, der an Hallow’s End-Feiern teilnimmt. Seine Leckereien und kleinen Herausforderungen lassen die Besucher eine gemeinsame Tradition der Horde-Gemeinden erleben."},pt={title="Kali Remik",body="Kali Remik é um troll no Sen'jin Village que participa das celebrações do Hallow’s End. Suas guloseimas e pequenos desafios permitem que os visitantes experimentem uma tradição compartilhada pelas comunidades Horde."},pl={title="Kali Remik",body="Kali Remik jest trollem w Sen'jin Village uczestniczącym w obchodach Hallow’s End. Poczęstunki i małe wyzwania pozwalają przybyszom poznać tradycję wspólną społecznościom frakcji Horde."},ru={title="Kali Remik",body="Kali Remik - тролль из Sen'jin Village, который принимает участие в празднованиях Hallow’s End. Его угощения и небольшие вызовы позволяют посетителям испытать традицию, разделяемую сообществами Horde."},references={["event:hallows-end"]=true,["organization:horde"]=true,["place:senjin-village"]=true}},
    ["person:kamari"] = {title="Kamari",kind="Personaje",aliases={"Kamari"},body="Kamari trabaja con cueros que sirven a la expansión de Orgrimmar. Distingue las pieles demasiado gruesas para una armadura de las que resultan útiles para revestir muros y techos.",aliasQuestIDs={},en={title="Kamari",aliases={"Kamari"},body="Kamari works with hides supporting Orgrimmar’s expansion. The work distinguishes skins too thick for armor from those useful for lining walls and roofs.",aliasQuestIDs={}},fr={title="Kamari",body="Kamari travaille avec des peaux prenant en charge l'expansion de Orgrimmar. Le travail distingue les peaux trop épaisses pour l'armure de celles utiles pour le revêtement des murs et des toits."},de={title="Kamari",body="Kamari arbeitet mit Fellen, die Orgrimmar 'Expansion unterstützen. Die Arbeit unterscheidet Felle, die zu dick für eine Rüstung sind, von denen, die nützlich für die Verkleidung von Wänden und Dächern sind."},pt={title="Kamari",body="O Kamari trabalha com peles que apoiam a expansão do Orgrimmar. O trabalho distingue peles muito grossas para armaduras daquelas úteis para forrar paredes e telhados."},pl={title="Kamari",body="Kamari pracuje ze skórami wspierającymi rozbudowę Orgrimmar. Rozróżnia skóry zbyt grube na pancerze od tych przydatnych do wykładania ścian i dachów."},ru={title="Kamari",body="Kamari работает с кожей, поддерживающими расширение Orgrimmar. В этой работе различают кожи, слишком толстые для брони, от тех, которые полезны для облицовки стен и крыш."},references={["place:orgrimmar"]=true}},
    ["person:kanati-greycloud"] = {title="Kanati Nube Gris",kind="Personaje",aliases={"Kanati","Kanati Nube Gris"},body="Kanati Nube Gris es un tauren que mantiene un campamento de caza en Las Mil Agujas. Su presencia en un territorio disputado lo enfrenta con grupos que consideran ese asentamiento una intrusión.",aliasQuestIDs={},en={title="Kanati Greycloud",aliases={"Kanati","Kanati Greycloud"},body="Kanati Greycloud is a tauren maintaining a hunting camp in Thousand Needles. His presence in contested territory brings him into conflict with groups that regard the settlement as an intrusion.",aliasQuestIDs={}},fr={title="Kanati Greycloud",body="Kanati Greycloud est un tauren qui maintient un camp de chasse à Thousand Needles. Sa présence en territoire contesté le met en conflit avec des groupes qui considèrent le règlement comme une intrusion."},de={title="Kanati Greycloud",body="Kanati Greycloud ist ein Tauren, der in Thousand Needles ein Jagdlager unterhält. Seine Anwesenheit in umkämpften Gebieten bringt ihn in Konflikt mit Gruppen, die die die die Siedlung als Eindringen betrachten."},pt={title="Kanati Greycloud",body="Kanati Greycloud é um tauren que mantém um campo de caça em Thousand Needles. Sua presença em território contestado o coloca em conflito com grupos que consideram o assentamento como uma intrusão."},pl={title="Kanati Greycloud",body="Kanati Greycloud jest taurenem utrzymującym obóz łowiecki w Thousand Needles. Obecność na spornym terytorium prowadzi go do konfliktu z grupami uznającymi osadę za wtargnięcie."},ru={title="Kanati Greycloud",body="Kanati Greycloud - это таурен, который поддерживает охотничий лагерь в Thousand Needles. Его присутствие на спорной территории вызывает конфликт с группами, которые считают поселение вторжением."},references={["place:thousand-needles"]=true}},
    ["person:karang-amakkar"] = {title="Karang Amakkar",kind="Personaje",aliases={"Karang","Karang Amakkar"},body="Karang Amakkar actúa desde Zoram'gar frente a las tribus fúrbolgs de Vallefresno. Su estrategia se basa en demostrar fuerza para reducir la amenaza que atribuye a los poblados hostiles del bosque.",aliasQuestIDs={},en={title="Karang Amakkar",aliases={"Karang","Karang Amakkar"},body="Karang Amakkar acts from Zoram'gar against Ashenvale’s furbolg tribes. His strategy relies on displays of strength to reduce the threat he attributes to hostile forest settlements.",aliasQuestIDs={}},fr={title="Karang Amakkar",body="Karang Amakkar agit depuis Zoram'gar contre les tribus furbolg de Ashenvale. Sa stratégie repose sur des démonstrations de force pour réduire la menace qu’il attribue aux établissements forestiers hostiles."},de={title="Karang Amakkar",body="Karang Amakkar agiert von Zoram'gar aus gegen Ashenvale 'wütende Stämme. Seine Strategie beruht auf der Zurschaustellung von Stärke, um die Bedrohung zu verringern, die er feindlichen Waldsiedlungen zuschreibt."},pt={title="Karang Amakkar",body="Karang Amakkar atua de Zoram'gar contra as tribos furbolg do Ashenvale. Sua estratégia depende de demonstrações de força para reduzir a ameaça que ele atribui a assentamentos florestais hostis."},pl={title="Karang Amakkar",body="Karang Amakkar działa z Zoram'gar przeciw plemionom furbolgów w Ashenvale. Jego strategia opiera się na pokazach siły ograniczających zagrożenie, które przypisuje wrogim leśnym osadom."},ru={title="Karang Amakkar",body="Karang Amakkar действует из Zoram'gar против племён фурболгов Ashenvale. Он рассчитывает демонстрацией силы уменьшить угрозу, которую видит во враждебных лесных поселениях."},references={["place:ashenvale"]=true,["place:zoramgar-outpost"]=true}},
    ["person:kargal-battlescar"] = {title="Kargal Marca de Guerra",kind="Personaje",aliases={"Kargal","Kargal Marca de Guerra"},body="Kargal recibe a nuevos reclutas destinados al servicio de la Horda en Los Baldíos. Mantiene contacto con exploradores como Takrin, cuyas recomendaciones ayudan a encontrar combatientes para una región que necesita refuerzos.",aliasQuestIDs={},en={title="Kargal Battlescar",aliases={"Kargal","Kargal Battlescar"},body="Kargal receives recruits entering Horde service in the Barrens. He works with scouts such as Takrin, whose recommendations help find fighters for a region in need of reinforcements.",aliasQuestIDs={}},fr={title="Kargal Battlescar",body="Kargal reçoit les recrues entrant dans le service Horde dans le Barrens. Il travaille avec des éclaireurs tels que Takrin, dont les recommandations aident à trouver des combattants pour une région qui a besoin de renforts."},de={title="Kargal Battlescar",body="Kargal erhält Rekruten, die in den Dienst von Horde im Barrens antreten. Er arbeitet mit Pfadfindern wie Takrin zusammen, deren Empfehlungen helfen, Kämpfer für eine Region zu finden, die Verstärkung braucht."},pt={title="Kargal Battlescar",body="Kargal recebe recrutas que entram no serviço Horde no Barrens. Ele trabalha com olheiros como Takrin, cujas recomendações ajudam a encontrar lutadores para uma região que precisa de reforços."},pl={title="Kargal Battlescar",body="Kargal przyjmuje rekrutów rozpoczynających służbę frakcji Horde w regionie Barrens. Współpracuje ze zwiadowcami takimi jak Takrin, których rekomendacje pomagają znajdować wojowników dla regionu potrzebującego posiłków."},ru={title="Kargal Battlescar",body="Kargal принимает новобранцев, поступающих на службу в Horde в Barrens. Он работает со скаутами, такими как Takrin, чьи рекомендации помогают найти бойцов для региона, нуждающегося в подкреплении."},references={["organization:horde"]=true,["place:the-barrens"]=true},questIDs={[840]=true}},
    ["person:karna-remtravel"] = {title="Karna Tripirrem",kind="Personaje",aliases={"Karna","Karna Tripirrem"},body="Karna Tripirrem investiga los animales de Un'Goro mediante dispositivos de observación. Su creación de una mona mecánica con gemas de visión ofrece una forma de acercarse a criaturas que sería peligroso estudiar de otro modo.",aliasQuestIDs={},en={title="Karna Remtravel",aliases={"Karna","Karna Remtravel"},body="Karna Remtravel studies Un'Goro’s animals through observation devices. Creating a mechanical female ape with scrying gems offers a way to approach creatures that would otherwise be dangerous to study.",aliasQuestIDs={}},fr={title="Karna Remtravel",body="Karna Remtravel étudie les animaux de Un'Goro à travers des dispositifs d'observation. Créer un singe femelle mécanique avec des pierres précieuses offre un moyen d'approcher des créatures qui seraient autrement dangereuses à étudier."},de={title="Karna Remtravel",body="Karna Remtravel untersucht die Tiere von Un'Goro 'durch Beobachtungsgeräte. Die Erschaffung eines mechanischen Affenweibchens mit versuchenden Edelsteinen bietet eine Möglichkeit, sich Kreaturen zu nähern, die sonst gefährlich zu studieren."},pt={title="Karna Remtravel",body="Karna Remtravel estuda os animais de Un'Goro através de dispositivos de observação. Criar um macaco feminino mecânico com pedras preciosas oferece uma maneira de abordar criaturas que, de outra forma, seriam perigosas de estudar."},pl={title="Karna Remtravel",body="Karna Remtravel bada zwierzęta Un'Goro za pomocą urządzeń obserwacyjnych. Stworzenie mechanicznej samicy małpy z klejnotami jasnowidzenia pozwala zbliżać się do stworzeń, których badanie byłoby inaczej niebezpieczne."},ru={title="Karna Remtravel",body="Karna Remtravel изучает животных Un'Goro s с помощью наблюдений. Создание механической обезьяны с драгоценными камнями дает возможность приблизиться к существам, которые в противном случае были бы опасны для изучения."},references={["person:prospector-remtravel"]=true,["place:ungoro-crater"]=true}},
    ["person:kaya-flathoof"] = {title="Kaya Pezuña Plana",kind="Personaje",aliases={"Kaya","Kaya Pezuña Plana"},body="Kaya Pezuña Plana es hija de Makaba y sobrina de Tammra Campo de Viento. Sus vínculos entre los campamentos de Sierra Espolón muestran una comunidad que depende de noticias y ayuda mutua para afrontar las amenazas a sus poblados.",aliasQuestIDs={},en={title="Kaya Flathoof",aliases={"Kaya","Kaya Flathoof"},body="Kaya Flathoof is Makaba’s daughter and Tammra Windfield’s niece. Her ties between Stonetalon camps show a community depending on news and mutual help to face threats to its villages.",aliasQuestIDs={}},fr={title="Kaya Flathoof",body="Kaya Flathoof est la fille de Makaba et la nièce de Tammra Windfield. Ses liens entre les camps de Stonetalon illustrent une communauté qui compte sur les nouvelles et l'entraide pour faire face aux menaces pesant sur ses villages."},de={title="Kaya Flathoof",body="Kaya Flathoof ist Makabas Tochter und Tammra Windfields Nichte. Ihre Verbindungen zwischen den Stonetalon-Lagern zeigen eine Gemeinschaft, die auf Nachrichten und gegenseitige Hilfe angewiesen ist, um Bedrohungen ihrer Dörfer zu begegnen."},pt={title="Kaya Flathoof",body="Kaya Flathoof é filha de Makaba e sobrinha de Tammra Windfield. Seus laços entre os campos Stonetalon mostram uma comunidade dependendo de notícias e ajuda mútua para enfrentar ameaças às suas aldeias."},pl={title="Kaya Flathoof",body="Kaya Flathoof jest córką postaci Makaba i siostrzenicą postaci Tammra Windfield. Więzi między obozami Stonetalon ukazują społeczność zależną od wiadomości oraz wzajemnej pomocy wobec zagrożeń dla wiosek."},ru={title="Kaya Flathoof",body="Kaya Flathoof - дочь Makaba  и племянница Tammra Windfield. Ее связи между лагерями Stonetalon показывают, что сообщество зависит от новостей и взаимной помощи, чтобы противостоять угрозам для своих деревень."},references={["person:tammra-windfield"]=true,["place:stonetalon-mountains"]=true}},
    ["person:kayneth-stillwind"] = {title="Kayneth Ventoleve",kind="Personaje",aliases={"Kayneth","Kayneth Ventoleve"},body="Kayneth Ventoleve trabaja desde Canción del Bosque en Vallefresno. Sus experiencias lo han llevado a preocuparse por los venenos y por el destino de los druidas de Túmulo de Dor'danil.",aliasQuestIDs={},en={title="Kayneth Stillwind",aliases={"Kayneth","Kayneth Stillwind"},body="Kayneth Stillwind works from Forest Song in Ashenvale. His experiences have led him to take an interest in poisons and the fate of the druids of Dor'danil Barrow Den.",aliasQuestIDs={}},fr={title="Kayneth Stillwind",body="Kayneth Stillwind travaille à partir de Forest Song dans Ashenvale. Ses expériences l'ont amené à s'intéresser aux poisons et au sort des druides de Dor'danil Barrow Den."},de={title="Kayneth Stillwind",body="Kayneth Stillwind arbeitet von Forest Song in Ashenvale. Seine Erfahrungen haben ihn dazu gebracht, sich für Gifte und das Schicksal der Druiden von Dor'danil Barrow Den zu interessieren."},pt={title="Kayneth Stillwind",body="Kayneth Stillwind trabalha a partir de Forest Song em Ashenvale. Suas experiências o levaram a se interessar por venenos e o destino dos druidas de Dor'danil Barrow Den."},pl={title="Kayneth Stillwind",body="Kayneth Stillwind działa z Forest Song w Ashenvale. Doświadczenia skłoniły go do zainteresowania truciznami i losem druidów z kurhanów Dor'danil."},ru={title="Kayneth Stillwind",body="Kayneth Stillwind работает от Forest Song в Ashenvale. Его опыт привел к тому, что он заинтересовался ядами и судьбой друидов Dor'danil Barrow Den."},references={["place:ashenvale"]=true,["place:forest-song"]=true}},
    ["person:keeper-albagorm"] = {title="Vigilante Albagorm",kind="Personaje",aliases={"Albagorm","Vigilante Albagorm"},body="El vigilante Albagorm aguarda en la Cima del Espolón y mantiene vínculos con quienes escuchan a los espíritus del bosque. Busca ayuda druídica para impedir que los enemigos de La Vega Carbonizada vuelvan a reagruparse.",aliasQuestIDs={},en={title="Keeper Albagorm",aliases={"Albagorm","Keeper Albagorm"},body="Keeper Albagorm waits at Stonetalon Peak and maintains ties with those who listen to forest spirits. He seeks druidic aid to prevent the enemies of the Charred Vale from regrouping.",aliasQuestIDs={}},fr={title="Keeper Albagorm",body="Keeper Albagorm attend à Stonetalon Peak et entretient des liens avec ceux qui écoutent les esprits de la forêt. Il cherche une aide druidique pour empêcher les ennemis du Charred Vale de se regrouper."},de={title="Keeper Albagorm",body="Keeper Albagorm wartet auf Stonetalon Peak und pflegt Verbindungen zu denen, die Waldgeister hören. Er sucht druidische Hilfe, um zu verhindern, dass sich die Feinde der Charred Vale neu gruppieren."},pt={title="Keeper Albagorm",body="Keeper Albagorm espera no Stonetalon Peak e mantém laços com aqueles que ouvem espíritos da floresta. Ele procura ajuda druídica para evitar que os inimigos do Charred Vale se reagrupem."},pl={title="Keeper Albagorm",body="Keeper Albagorm czeka na Stonetalon Peak i utrzymuje więzi z osobami słuchającymi leśnych duchów. Szuka pomocy druidów, by uniemożliwić wrogom Charred Vale ponowne zebranie sił."},ru={title="Keeper Albagorm",body="Keeper Albagorm ждет в Stonetalon Peak и поддерживает связи с теми, кто слушает лесных духов. Он ищет друидскую помощь, чтобы предотвратить перегруппировку врагов Charred Vale."},references={["place:charred-vale"]=true,["place:stonetalon-mountains"]=true}},
    ["person:keeper-marandis"] = {title="Vigilante Marandis",kind="Personaje",aliases={"Marandis","Vigilante Marandis"},body="El vigilante Marandis estudia la amenaza de Maraudon y el destino de los restos de Zaetar. Su preocupación por el hijo de Cenarius lo lleva a buscar aliados capaces de enfrentarse a los poderes que dominan las cavernas.",aliasQuestIDs={},en={title="Keeper Marandis",aliases={"Keeper Marandis","Marandis"},body="Keeper Marandis studies Maraudon’s threat and the fate of Zaetar’s remains. His concern for Cenarius’s son leads him to seek allies capable of confronting the powers ruling the caverns.",aliasQuestIDs={}},fr={title="Keeper Marandis",body="Keeper Marandis étudie la menace de Maraudon et le sort des restes de Zaetar. Son inquiétude pour le fils de Cenarius le pousse à chercher des alliés capables d'affronter les puissances qui règnent sur les cavernes."},de={title="Keeper Marandis",body="Keeper Marandis untersucht Maraudon 'Bedrohung und das Schicksal von Zaetar' Überresten. Seine Sorge um den Sohn Cenarius veranlasst ihn, Verbündete zu suchen, die den Mächten entgegenzutreten, die in den Höhlen regieren."},pt={title="Keeper Marandis",body="Keeper Marandis estuda a ameaça de Maraudon e o destino dos restos mortais de Zaetar. Sua preocupação com o filho de Cenarius o leva a buscar aliados capazes de confrontar os poderes que governam as cavernas."},pl={title="Keeper Marandis",body="Keeper Marandis bada zagrożenie Maraudon i los szczątków istoty Zaetar. Troska o syna istoty Cenarius skłania go do szukania sojuszników zdolnych stawić czoła potęgom władającym jaskiniami."},ru={title="Keeper Marandis",body="Keeper Marandis изучает угрозу Maraudon  и судьбу Zaetar. Его беспокойство за сына Cenarius  заставляет его искать союзников, способных противостоять силам, управляющим пещерами."},references={["npc:cenarius"]=true,["place:maraudon"]=true}},
    ["person:keeper-ordanus"] = {title="Vigilante Ordanus",kind="Personaje",aliases={"Ordanus","Vigilante Ordanus"},body="El vigilante Ordanus es uno de los hijos mayores del dios del bosque. Se refugia en un gran árbol de Algaba, en Vallefresno, donde su linaje lo vincula con los poderes más antiguos de la naturaleza.",aliasQuestIDs={},en={title="Keeper Ordanus",aliases={"Keeper Ordanus","Ordanus"},body="Keeper Ordanus is one of the forest god’s eldest sons. He shelters in a great tree in Raynewood, Ashenvale, where his lineage links him with nature’s most ancient powers.",aliasQuestIDs={}},fr={title="Keeper Ordanus",body="Keeper Ordanus est l’un des fils aînés du dieu de la forêt. Il se réfugie dans un grand arbre à Raynewood, Ashenvale, où sa lignée le relie aux pouvoirs les plus anciens de la nature."},de={title="Keeper Ordanus",body="Keeper Ordanus ist einer der ältesten Söhne des Waldgottes. Er versteckt sich in einem großen Baum bei Raynewood, Ashenvale, wo ihn seine Abstammung mit den ältesten Kräften der Natur verbindet."},pt={title="Keeper Ordanus",body="Keeper Ordanus é um dos filhos mais velhos do deus da floresta. Ele abriga em uma grande árvore em Raynewood, Ashenvale, onde sua linhagem o liga aos poderes mais antigos da natureza."},pl={title="Keeper Ordanus",body="Keeper Ordanus jest jednym z najstarszych synów boga lasu. Chroni się w wielkim drzewie w Raynewood w Ashenvale, gdzie pochodzenie wiąże go z najdawniejszymi potęgami natury."},ru={title="Keeper Ordanus",body="Keeper Ordanus - один из старших сыновей лесного бога. Он укрывается в большом дереве в Raynewood, Ashenvale, где его родословная связывает его с древнейшими силами природы."},references={["place:ashenvale"]=true,["place:raynewood"]=true}},
    ["person:keeper-remulos"] = {title="Guardián Remulos",kind="Personaje",aliases={"Guardián Remulos","Remulos","guardián Remulos"},body="El guardián Remulos es una figura protectora de Claro de la Luna, vinculada al Círculo Cenarion. Su entorno reúne a druidas y servidores que investigan amenazas contra los lugares sagrados y el mundo natural.",aliasQuestIDs={},en={title="Keeper Remulos",aliases={"Keeper Remulos","Remulos"},body="Keeper Remulos is a protective figure in Moonglade associated with the Cenarion Circle. His circle brings together druids and attendants investigating threats to sacred places and the natural world.",aliasQuestIDs={}},fr={title="Keeper Remulos",body="Keeper Remulos est une figure de protection dans Moonglade associée à la Cenarion Circle. Son cercle rassemble des druides et des assistants qui enquêtent sur les menaces qui pèsent sur les lieux sacrés et le monde naturel."},de={title="Keeper Remulos",body="Keeper Remulos ist eine beschützende Figur in Moonglade, der mit dem Cenarion Circle in Verbindung gebracht wird. Sein Kreis versammelt Druiden und Begleiter, die Bedrohungen heiliger Stätten und der Natur untersuchen."},pt={title="Keeper Remulos",body="Keeper Remulos é uma figura protetora no Moonglade associada ao Cenarion Circle. Seu círculo reúne druidas e assistentes que investigam ameaças a lugares sagrados e ao mundo natural."},pl={title="Keeper Remulos",body="Keeper Remulos jest opiekuńczą postacią w Moonglade związaną z Cenarion Circle. Jego krąg skupia druidów i pomocników badających zagrożenia dla świętych miejsc oraz świata przyrody."},ru={title="Keeper Remulos",body="Keeper Remulos - это защитная фигура в Moonglade, связанная с Cenarion Circle. Его круг объединяет друидов и слуг, расследующих угрозы священным местам и миру природы."},references={["organization:cenarion-circle"]=true,["place:moonglade"]=true}},
    ["person:keldran"] = {title="Keldran",kind="Personaje",aliases={"Keldran"},body="Keldran es un orco de Orgrimmar conocedor de la historia de su pueblo y de los conflictos con los humanos. Su perspectiva concede importancia a la prudencia y a la diplomacia que Thrall intenta ejercer como jefe de guerra.",aliasQuestIDs={},en={title="Keldran",aliases={"Keldran"},body="Keldran is an Orgrimmar orc familiar with his people’s history and conflicts with humans. His perspective values the caution and diplomacy Thrall seeks to exercise as warchief.",aliasQuestIDs={}},fr={title="Keldran",body="Keldran est un Orc Orgrimmar familier avec l'histoire de son peuple et les conflits avec les humains. Sa perspective valorise la prudence et la diplomatie que Thrall cherche à exercer en tant que chef de guerre."},de={title="Keldran",body="Keldran ist ein Orgrimmar-Ork, der mit der Geschichte und Konflikten mit Menschen vertraut ist. Aus seiner Perspektive schätzt er die Vorsicht und Diplomatie, die Thrall als Kriegsoberhaupt auszuüben versucht."},pt={title="Keldran",body="Keldran é um orc Orgrimmar familiarizado com a história de seu povo e os conflitos com os seres humanos. Sua perspectiva valoriza a cautela e a diplomacia que Thrall procura exercer como chefe de guerra."},pl={title="Keldran",body="Keldran jest orkiem z Orgrimmar znającym historię swojego ludu i konflikty z ludźmi. Ceni ostrożność oraz dyplomację, które Thrall stara się stosować jako wódz wojenny."},ru={title="Keldran",body="Keldran - это орк Orgrimmar, знакомый с историей своего народа и конфликтами с людьми. Его взгляд ценит осторожность и дипломатию, которую Thrall стремится проявлять как военачальник."},references={["person:thrall"]=true,["place:orgrimmar"]=true}},
    ["person:kelek-skykeeper"] = {title="Kelek Guardacielo",kind="Personaje",aliases={"Kelek","Kelek Guardacielo"},body="Kelek Guardacielo pertenece al Círculo Esmeralda, cuyos druidas trabajan para sanar Frondavil. Su experiencia con los fúrbolgs de la región también le permite estudiar y traducir documentos relacionados con ellos.",aliasQuestIDs={},en={title="Kelek Skykeeper",aliases={"Kelek","Kelek Skykeeper"},body="Kelek Skykeeper belongs to the Emerald Circle, whose druids work to heal Felwood. His experience with the region’s furbolgs also allows him to examine and translate documents concerning them.",aliasQuestIDs={}},fr={title="Kelek Skykeeper",body="Kelek Skykeeper appartient à l'Emerald Circle, dont les druides travaillent pour guérir Felwood. Son expérience avec les furbolgs de la région lui permet également d’examiner et de traduire des documents les concernant."},de={title="Kelek Skykeeper",body="Kelek Skykeeper gehört zu dem smaragdgrünen Circle, dessen Druiden daran arbeiten, Felwood zu heilen. Seine Erfahrung mit den Furbolgs der Region ermöglicht es ihm auch, Dokumente zu prüfen und zu übersetzen, die sie betreffen."},pt={title="Kelek Skykeeper",body="Kelek Skykeeper pertence à Esmeralda Circle, cujos druidas trabalham para curar Felwood. Sua experiência com os furbolgs da região também lhe permite examinar e traduzir documentos sobre eles."},pl={title="Kelek Skykeeper",body="Kelek Skykeeper należy do Emerald Circle, którego druidzi pracują nad uzdrowieniem Felwood. Doświadczenie z miejscowymi furbolgami pozwala mu także badać i tłumaczyć dotyczące ich dokumenty."},ru={title="Kelek Skykeeper",body="Kelek Skykeeper принадлежит изумрудному Circle, чьи друиды работают над исцелением Felwood. Его опыт работы с местными фермерами позволяет ему также изучать и переводить документы, касающиеся этих фермеров."},references={["place:felwood"]=true}},
    ["person:kenjai"] = {title="Ken'jai",kind="Personaje",aliases={"Ken'jai","Ken’jai"},body="Ken'jai instruye a los sacerdotes y les enseña a profundizar su relación con los espíritus. Sus lecciones vinculan el crecimiento del poder con la experiencia que se obtiene al ponerse a prueba.",aliasQuestIDs={},en={title="Ken'jai",aliases={"Ken'jai","Ken’jai"},body="Ken'jai trains priests and teaches them to deepen their relationship with the spirits. His lessons connect growing power with the experience gained through testing oneself.",aliasQuestIDs={}},fr={title="Ken'jai",body="Ken'jai forme les prêtres et leur apprend à approfondir leur relation avec les esprits. Ses leçons relient la puissance croissante avec l’expérience acquise en se testant soi-même."},de={title="Ken'jai",body="Ken'jai bildet Priester aus und lehrt sie, ihre Beziehung zu den Geistern zu vertiefen. Seine Lehren verbinden wachsende Macht mit den Erfahrungen, die man durch Selbstprüfung gewinnt."},pt={title="Ken'jai",body="Ken'jai treina sacerdotes e os ensina a aprofundar sua relação com os espíritos. Suas lições conectam o poder crescente com a experiência adquirida através do teste de si mesmo."},pl={title="Ken'jai",body="Ken'jai szkoli kapłanów i uczy pogłębiania relacji z duchami. Łączy wzrost mocy z doświadczeniem zdobywanym poprzez poddawanie siebie próbom."},ru={title="Ken'jai",body="Ken'jai обучает жрецов и учит их углублять свои отношения с духами. Его уроки связывают растущую силу с опытом, полученным путем самоиспытания."},references={}},
    ["person:kenzigla"] = {title="Ken'zigla",kind="Personaje",aliases={"Ken'zigla","Ken’zigla"},body="Ken'zigla prepara remedios para heridas graves. Su conocimiento de las dosis permite devolver fuerzas a un herido sin que el esfuerzo de moverlo agrave la pérdida de sangre.",aliasQuestIDs={},en={title="Ken'zigla",aliases={"Ken'zigla","Ken’zigla"},body="Ken'zigla prepares remedies for serious wounds. His knowledge of dosage can restore a wounded person’s strength without letting the effort of moving them worsen their blood loss.",aliasQuestIDs={}},fr={title="Ken'zigla",body="Ken'zigla prépare des remèdes pour les plaies graves. Sa connaissance du dosage peut restaurer la force d'une personne blessée sans laisser l'effort de les déplacer aggraver leur perte de sang."},de={title="Ken'zigla",body="Ken'zigla bereitet Mittel gegen schwere Wunden vor. Sein Wissen über die Dosierung kann die Kraft eines Verwundeten wiederherstellen, ohne dass die Anstrengungen, ihn zu bewegen, seinen Blutverlust zu verschlimmern."},pt={title="Ken'zigla",body="Ken'zigla prepara remédios para feridas graves. Seu conhecimento de dosagem pode restaurar a força de uma pessoa ferida sem deixar o esforço de movê-los piorar sua perda de sangue."},pl={title="Ken'zigla",body="Ken'zigla przygotowuje środki na poważne rany. Znajomość dawkowania pozwala przywracać siły rannej osobie bez narażania jej na pogłębienie utraty krwi wskutek wysiłku przenoszenia."},ru={title="Ken'zigla",body="Ken'zigla готовит лекарства для серьезных ран. Его знание дозировки может восстановить силу раненого человека, не позволяя усилиям перемещения усугубить потерю крови."},references={}},
    ["person:kerlonian-evershade"] = {title="Kerlonian Semprumbrío",kind="Personaje",aliases={"Kerlonian","Kerlonian Semprumbrío"},body="Kerlonian sufre una profunda somnolencia desde que despertó del Sueño Esmeralda. Viaja hacia la Atalaya de Maestra para reunirse con Liladris Rioluna y conserva un cuerno cuyo sonido permite despertarlo cuando vuelve a quedarse dormido.",aliasQuestIDs={},en={title="Kerlonian Evershade",aliases={"Kerlonian","Kerlonian Evershade"},body="Kerlonian has suffered deep drowsiness since waking from the Emerald Dream. He travels toward Maestra’s Post to meet Liladris Moonriver and carries a horn whose sound can wake him when he falls asleep again.",aliasQuestIDs={}},fr={title="Kerlonian Evershade",body="Kerlonian a souffert de somnolence profonde depuis son réveil du Emerald Dream. Il se dirige vers Maestra’s Post pour rencontrer Liladris Moonriver et porte une corne dont le son peut le réveiller quand il s’endort à nouveau."},de={title="Kerlonian Evershade",body="Kerlonian leidet seit dem Aufwachen vom Emerald Dream unter tiefer Schläfrigkeit. Er fährt zu Maestra 'Post, um Liladris Moonriver zu treffen und trägt eine Hupe, deren Klang ihn wecken, wenn er wieder einschläft."},pt={title="Kerlonian Evershade",body="Kerlonian sofreu sonolência profunda desde que acordou do Emerald Dream. Ele viaja em direção ao Post de Maestra para conhecer Liladris Moonriver e carrega um chifre cujo som pode acordá-lo quando ele adormecer novamente."},pl={title="Kerlonian Evershade",body="Kerlonian cierpi na głęboką senność od przebudzenia z Emerald Dream. Podróżuje do posterunku Maestra, by spotkać postać Liladris Moonriver, i nosi róg, którego dźwięk budzi go po ponownym zaśnięciu."},ru={title="Kerlonian Evershade",body="С тех пор как Kerlonian пробудился от Emerald Dream, его одолевает сильная сонливость. Он направляется к Посту Maestra, чтобы встретиться с Liladris Moonriver и несет рог, звук которого может разбудить его, когда он снова засыпает."},references={["concept:emerald-dream"]=true,["person:liladris-moonriver"]=true}},
    ["person:keyl-swiftclaw"] = {title="Keyl Patacerce",kind="Personaje",aliases={"Keyl","Keyl Patacerce"},body="Keyl confecciona prendas protectoras para quienes se enfrentan a los qiraji. Adapta sus mantos y emplea ídolos y escarabajos en los broches, buscando que el resultado proteja a su portador de la magia enemiga.",aliasQuestIDs={},en={title="Keyl Swiftclaw",aliases={"Keyl","Keyl Swiftclaw"},body="Keyl fashions protective garments for those facing the Qiraji. He adjusts their drapes and uses idols and scarabs in the clasps, seeking to shield the wearer from hostile magic.",aliasQuestIDs={}},fr={title="Keyl Swiftclaw",body="Keyl mode vêtements de protection pour ceux qui font face à la Qiraji. Il ajuste leurs rideaux et utilise des idoles et des scarabées dans les fermoirs, cherchant à protéger le porteur de la magie hostile."},de={title="Keyl Swiftclaw",body="Keyl schneidet Schutzanzüge für diejenigen, die dem Qiraji gegenüberstehen. Er justiert ihre Gardinen und verwendet Götzen und Skarabäen in den Klammern, um den Träger vor feindlicher Magie zu schützen."},pt={title="Keyl Swiftclaw",body="Keyl forma roupas de proteção para aqueles que enfrentam o Qiraji. Ele ajusta suas cortinas e usa ídolos e escaravelhos nos fechos, buscando proteger o usuário da magia hostil."},pl={title="Keyl Swiftclaw",body="Keyl wykonuje ochronne szaty dla osób walczących z Qiraji. Dostosowuje ich fałdy i wykorzystuje bożki oraz skarabeusze w zapięciach, próbując osłonić użytkownika przed wrogą magią."},ru={title="Keyl Swiftclaw",body="Keyl создает защитные одежды для тех, кто сталкивается с Qiraji. Он настраивает их занавески и использует в застежках идолы и скарабеи, пытаясь защитить носителя от враждебного колдовства."},references={["people:qiraji"]=true}},
    ["person:khan-hratha"] = {title="Khan Hratha",kind="Personaje",aliases={"Hratha","Khan Hratha","khan Hratha"},body="Khan Hratha es el jefe de los centauros Maraudine del Valle de las Lanzas. Su autoridad está vinculada al cuerno de guerra del clan y a una parte de una llave que otros centauros consideran valiosa.",aliasQuestIDs={},en={title="Khan Hratha",aliases={"Hratha","Khan Hratha"},body="Khan Hratha is the leader of the Maraudine centaurs in the Valley of Spears. His authority is tied to the clan’s war horn and part of a key valued by other centaurs.",aliasQuestIDs={}},fr={title="Khan Hratha",body="Khan Hratha est le leader des centaures Maraudine dans la vallée de Spears. Son autorité est liée à la corne de guerre du clan et à une partie d’une clé appréciée par d’autres centaures."},de={title="Khan Hratha",body="Khan Hratha ist der Anführer der Maraudine-Zentauren im Tal der Speere. Seine Autorität ist an das Kriegshorn des Clans gebunden und Teil eines Schlüssels, das von anderen Zentworfen wurde."},pt={title="Khan Hratha",body="Khan Hratha é o líder dos centauros Maraudine no Vale de Spears. Sua autoridade está ligada ao chifre de guerra do clã e parte de uma chave valorizada por outros centauros."},pl={title="Khan Hratha",body="Khan Hratha jest przywódcą centaurów Maraudine w Valley of Spears. Władza wiąże się z rogiem wojennym klanu i częścią klucza cenionego przez inne centaury."},ru={title="Khan Hratha",body="Khan Hratha - лидер кентавров Maraudine в Долине копьев. Его власть связана с военным рогом клана и частью ключа, ценного другими кентаврами."},references={["organization:maraudine"]=true}},
    ["person:khan-jehn"] = {title="Khan Jehn",kind="Personaje",aliases={"Jehn","Khan Jehn","Khan Jhen"},body="Khan Jehn es el líder del clan Magram de Desolace. Su autoridad lo sitúa en el centro de una rivalidad entre clanes en la que los movimientos militares y las alianzas con forasteros pueden alterar el equilibrio de poder.",aliasQuestIDs={},en={title="Khan Jehn",aliases={"Jehn","Khan Jehn"},body="Khan Jehn is the leader of the Magram clan in Desolace. His authority places him at the center of a rivalry in which military movements and alliances with outsiders can change the balance of power.",aliasQuestIDs={}},fr={title="Khan Jehn",body="Khan Jehn est le chef du clan Magram dans Desolace. Son autorité le place au centre d’une rivalité dans laquelle les mouvements militaires et les alliances avec des étrangers peuvent changer l’équilibre du pouvoir."},de={title="Khan Jehn",body="Khan Jehn ist der Anführer des Magram-Clans in Desolace. Seine Autorität stellt ihn ins Zentrum einer Rivalität, in der militärische Bewegungen und Bündnisse mit Außenstehenden das Machtgleichgewicht verändern kann."},pt={title="Khan Jehn",body="Khan Jehn é o líder do clã Magram em Desolace. Sua autoridade o coloca no centro de uma rivalidade em que movimentos militares e alianças com pessoas de fora podem mudar o equilíbrio de poder."},pl={title="Khan Jehn",body="Khan Jehn jest przywódcą klanu Magram w Desolace. Władza stawia go w centrum rywalizacji, w której ruchy wojsk i sojusze z obcymi mogą zmieniać układ sił."},ru={title="Khan Jehn",body="Khan Jehn - лидер клана Magram в Desolace. Его власть ставит его в центр соперничества, в котором военные движения и союзы с внешними странами могут изменить баланс сил."},references={["organization:magram"]=true,["place:desolace"]=true}},
    ["person:khan-shaka"] = {title="Khan Shaka",kind="Personaje",aliases={"Khan Shaka","Shaka"},body="Khan Shaka dirige a los Gelkis en sus disputas con los Magram. La rivalidad entre los clanes centauros convierte su liderazgo en un símbolo de la fuerza de su pueblo frente a sus enemigos.",aliasQuestIDs={},en={title="Khan Shaka",aliases={"Khan Shaka","Shaka"},body="Khan Shaka leads the Gelkis in their disputes with the Magram. Rivalry between the centaur clans makes his leadership a symbol of his people’s strength against their enemies.",aliasQuestIDs={}},fr={title="Khan Shaka",body="Khan Shaka mène le Gelkis dans leurs différends avec le Magram. La rivalité entre les clans centaures fait de son leadership un symbole de la force de son peuple contre ses ennemis."},de={title="Khan Shaka",body="Khan Shaka führt den Gelkis in ihren Streitigkeiten mit dem Magram an. Die Rivalität zwischen den Kentaurenclans macht seine Führung zu einem Symbol der Stärke seines Volkes gegen seine Feinde."},pt={title="Khan Shaka",body="Khan Shaka lidera o Gelkis em suas disputas com o Magram. A rivalidade entre os clãs centauros faz de sua liderança um símbolo da força de seu povo contra seus inimigos."},pl={title="Khan Shaka",body="Khan Shaka przewodzi Gelkis w sporach z Magram. Rywalizacja klanów centaurów czyni jego przywództwo symbolem siły ludu wobec wrogów."},ru={title="Khan Shaka",body="Khan Shaka возглавляет Gelkis в их спорах с Magram. Соперничество между кланами кентавров делает его лидерство символом силы его народа против их врагов."},references={["organization:gelkis"]=true,["organization:magram"]=true}},
    ["person:kilhala"] = {title="Kil'hala",kind="Personaje",aliases={"Kil'hala","Kil’hala"},body="Kil'hala confecciona prendas de encaje abisal que conservan la magia del cabello de las hermanas sonrientes. Su oficio combina comodidad y resistencia con materiales capaces de albergar propiedades sobrenaturales.",aliasQuestIDs={},en={title="Kil'hala",aliases={"Kil'hala","Kil’hala"},body="Kil'hala makes nether-lace garments preserving the magic in the laughing sisters’ hair. The craft combines comfort and durability with materials capable of holding supernatural properties.",aliasQuestIDs={}},fr={title="Kil'hala",body="Kil'hala fabrique des vêtements en dentelle qui préservent la magie dans les cheveux des sœurs rieuses. L'artisanat combine confort et durabilité avec des matériaux capables de contenir des propriétés surnaturelles."},de={title="Kil'hala",body="Kil'hala fertigt Unterklöppelige Kleidungsstücke, die den Zauber im Haar der lachenden Schwestern bewahren. Das Fahrzeug vereint Komfort und Haltbarkeit mit Materialien, die übernatürliche Eigenschaften aufweisen können."},pt={title="Kil'hala",body="Kil'hala faz roupas de laço inferior preservando a magia no cabelo das irmãs rindo. A embarcação combina conforto e durabilidade com materiais capazes de manter propriedades sobrenaturais."},pl={title="Kil'hala",body="Kil'hala wytwarza szaty z nieziemskiej koronki zachowującej magię włosów śmiejących się sióstr. Rzemiosło łączy wygodę i trwałość z materiałami zdolnymi przechowywać nadprzyrodzone właściwości."},ru={title="Kil'hala",body="Kil'hala делает шнурки, которые сохраняют магию в волосах смеющихся сестер. Этот корабль сочетает в себе комфорт и долговечность с материалами, способными обладать сверхъестественными свойствами."},references={}},
    ["person:kilram"] = {title="Kilram",kind="Personaje",aliases={"Kilram"},body="Kilram conoce el arte de forjar hachas y está dispuesto a transmitirlo a otros herreros. Una cicatriz en su rostro recuerda su encuentro con la cazadora de las sombras Vosh’gajin, a quien considera una enemiga personal.",aliasQuestIDs={},en={title="Kilram",aliases={"Kilram"},body="Kilram knows the art of axesmithing and is willing to teach other smiths. A scar on his face recalls his encounter with Shadow Hunter Vosh’gajin, whom he considers a personal enemy.",aliasQuestIDs={}},fr={title="Kilram",body="Kilram connaît l'art de hacher et est prêt à enseigner à d'autres forgerons. Une cicatrice sur son visage rappelle sa rencontre avec Shadow Hunter Vosh’gajin, qu'il considère comme un ennemi personnel."},de={title="Kilram",body="Kilram beherrscht die Kunst des Axtschmiedens und ist bereit, andere Schmiede zu unterrichten. Eine Narbe im Gesicht erinnert an seine Begegnung mit Schattenjäger Vosh’gajin, den er als persönlichen Feind betrachtet."},pt={title="Kilram",body="Kilram conhece a arte de axesmithing e está disposto a ensinar outros ferreiros. Uma cicatriz em seu rosto lembra seu encontro com Shadow Hunter Vosh’gajin, a quem ele considera um inimigo pessoal."},pl={title="Kilram",body="Kilram zna sztukę wykuwania toporów i jest gotów uczyć innych kowali. Blizna na twarzy przypomina spotkanie z łowczynią cienia Vosh’gajin, którą uważa za osobistego wroga."},ru={title="Kilram",body="Kilram знает искусство ковального дела и готов учить других ковалов. Шрам на его лице напоминает о его встрече с Охотником-тенью Vosh’gajin, которого он считает личным врагом."},references={}},
    ["person:kimjael"] = {title="Kim'jael",kind="Personaje",aliases={"Kim'jael","Kim’jael"},body="Kim'jael es un explorador contratado para buscar tesoros en Azshara. Sus instrumentos de orientación y observación son esenciales para un trabajo en el que confiar en los socios equivocados puede resultar peligroso.",aliasQuestIDs={},en={title="Kim'jael",aliases={"Kim'jael","Kim’jael"},body="Kim'jael is an explorer hired to search for treasure in Azshara. His navigation and observation instruments are essential to work in which trusting the wrong partners can prove dangerous.",aliasQuestIDs={}},fr={title="Kim'jael",body="Kim'jael est un explorateur engagé pour rechercher des trésors dans Azshara. Ses instruments de navigation et d’observation sont essentiels pour travailler dans lesquels faire confiance aux mauvais partenaires peut s’avérer dangereux."},de={title="Kim'jael",body="Kim'jael ist ein Forscher, der angeheuert wird, um in Azshara nach Schätzen zu suchen. Seine Navigations- und Beobachtungsinstrumente sind unverzichtbar, um dort zu arbeiten, wo sich das Vertrauen in die falschen Partner als gefährlich erweisen kann."},pt={title="Kim'jael",body="Kim'jael é um explorador contratado para procurar tesouros em Azshara. Seus instrumentos de navegação e observação são essenciais para trabalhar no qual confiar nos parceiros errados pode ser perigoso."},pl={title="Kim'jael",body="Kim'jael jest odkrywcą wynajętym do poszukiwania skarbów w regionie Azshara. Przyrządy nawigacyjne i obserwacyjne są niezbędne w pracy, w której zaufanie niewłaściwym wspólnikom może okazać się niebezpieczne."},ru={title="Kim'jael",body="Kim'jael - исследователь, нанятый для поиска сокровищ в Azshara. Его навигационные и наблюдательные инструменты необходимы для работы, в которой доверять неверным партнерам может оказаться опасно."},references={["place:azshara"]=true}},
    ["person:kindal-moonweaver"] = {title="Kindal Tejeluna",kind="Personaje",aliases={"Kindal","Kindal Tejeluna"},body="Kindal Tejeluna protege a las criaturas de Feralas junto a Jer'kai. Su oposición a la captura de dragones feéricos la enfrenta a los campamentos Tótem Siniestro de la región.",aliasQuestIDs={},en={title="Kindal Moonweaver",aliases={"Kindal","Kindal Moonweaver"},body="Kindal Moonweaver protects Feralas’s creatures alongside Jer'kai. Her opposition to the capture of faerie dragons brings her into conflict with the region’s Grimtotem camps.",aliasQuestIDs={}},fr={title="Kindal Moonweaver",body="Kindal Moonweaver protège les créatures Feralas aux côtés de Jer'kai. Son opposition à la capture des dragons féeriques la met en conflit avec les camps Grimtotem de la région."},de={title="Kindal Moonweaver",body="Kindal Moonweaver beschützt Feralass Geschöpfe neben Jer'kai. Ihr Widerstand gegen die Gefangennahme von Feendrachen bringt sie in Konflikt mit den Grimtotem-Lagern der Region."},pt={title="Kindal Moonweaver",body="Kindal Moonweaver protege as criaturas do Feralas ao lado de Jer'kai. Sua oposição à captura de dragões fada a coloca em conflito com os campos Grimtotem da região."},pl={title="Kindal Moonweaver",body="Kindal Moonweaver chroni stworzenia Feralas u boku postaci Jer'kai. Sprzeciw wobec chwytania baśniowych smoków prowadzi ją do konfliktu z miejscowymi obozami Grimtotem."},ru={title="Kindal Moonweaver",body="Kindal Moonweaver защищает создания Feralas  вместе с Jer'kai. Ее оппозиция захвата драконов фейри вызывает конфликт с лагерями Grimtotem региона."},references={["organization:grimtotem"]=true,["person:jerkai-moonweaver"]=true,["place:feralas"]=true}},
    ["person:klannoc-macleod"] = {title="Klannoc Macleod",kind="Personaje",aliases={"Klannoc","Klannoc Macleod"},body="Klannoc Macleod pone a prueba a los guerreros en la Isla de la Contienda. Sus desafíos obligan a los combatientes a medir lo aprendido frente a otros rivales, más allá de la fama conseguida en sus viajes.",aliasQuestIDs={},en={title="Klannoc Macleod",aliases={"Klannoc","Klannoc Macleod"},body="Klannoc Macleod tests warriors on Fray Island. His challenges require fighters to measure what they have learned against other opponents, beyond the reputation earned on their travels.",aliasQuestIDs={}},fr={title="Klannoc Macleod",body="Klannoc Macleod teste des guerriers sur Fray Island. Ses défis exigent que les combattants mesurent ce qu’ils ont appris contre d’autres adversaires, au-delà de la réputation acquise lors de leurs voyages."},de={title="Klannoc Macleod",body="Klannoc Macleod testet Krieger auf Fray Island. Seine Herausforderungen erfordern, dass die Kämpfer das, was sie gelernt haben, an anderen Gegnern messen, über den Ruf hinaus, den sie sich auf ihren Reisen erworben haben."},pt={title="Klannoc Macleod",body="Klannoc Macleod testa guerreiros na Ilha Fray. Seus desafios exigem que os lutadores meçam o que aprenderam contra outros oponentes, além da reputação conquistada em suas viagens."},pl={title="Klannoc Macleod",body="Klannoc Macleod poddaje wojowników próbom na Fray Island. Wyzwania wymagają sprawdzenia zdobytej wiedzy przeciw innym przeciwnikom, niezależnie od reputacji zyskanej podczas podróży."},ru={title="Klannoc Macleod",body="Klannoc Macleod тестирует воинов на острове Фрей. Его вызовы требуют от бойцов, чтобы они оценивали то, что они узнали против других соперников, помимо репутации, заработанной в своих путешествиях."},references={}},
    ["person:knot-thimblejack"] = {title="Knot Llavededo",kind="Personaje",aliases={"Knot","Knot Llavededo"},body="Knot Llavededo es un artesano prisionero en el ala Gordok de La Masacre. Su habilidad con telas y cuero le permite confeccionar disfraces de ogro capaces de engañar a sus captores durante un tiempo limitado.",aliasQuestIDs={},en={title="Knot Thimblejack",aliases={"Knot","Knot Thimblejack"},body="Knot Thimblejack is a craftsperson imprisoned in Dire Maul’s Gordok wing. His skill with cloth and leather allows him to make ogre disguises capable of deceiving his captors for a limited time.",aliasQuestIDs={}},fr={title="Knot Thimblejack",body="Knot Thimblejack est un artisan emprisonné dans l’aile Dire Maul de Gordok. Son habileté avec le tissu et le cuir lui permet de faire des déguisements d'ogre capables de tromper ses ravisseurs pour un temps limité."},de={title="Knot Thimblejack",body="Knot Thimblejack ist ein Handwerker, der im Gordok-Flügel von Dire Maul gefangen ist. Seine Geschicklichkeit im Umgang mit Stoff und Leder erlaubt es ihm, Oger-Verkleidungen herzustellen, die seine Entführer für eine begrenzte Zeit lang zu täuschen."},pt={title="Knot Thimblejack",body="Knot Thimblejack é um artesão preso na ala Dire Maul do Gordok. Sua habilidade com pano e couro permite que ele faça disfarces ogro capazes de enganar seus captores por um tempo limitado."},pl={title="Knot Thimblejack",body="Knot Thimblejack jest rzemieślnikiem więzionym w części Dire Maul zajmowanej przez Gordok. Umiejętność pracy z tkaniną i skórą pozwala mu tworzyć przebrania ogrów, które przez ograniczony czas potrafią zwieść jego strażników."},ru={title="Knot Thimblejack",body="Knot Thimblejack - ремесленник, заключенный в крыло Dire Maul  Gordok. Его мастерство с тканями и кожей позволяет ему делать обнаженные изображения, способные обмануть своих похитителей в течение ограниченного времени."},references={["organization:gordok"]=true,["place:dire-maul"]=true},questIDs={[5518]=true,[5519]=true,[5525]=true,[7429]=true}},
    ["person:korgeld"] = {title="Kor'geld",kind="Personaje",aliases={"Kor'geld","Kor’geld"},body="Kor'geld trabaja en Alquimia y Pociones de Yelmak en Orgrimmar. Ayuda a coordinar el abastecimiento y la formación de los aprendices, incluyendo el uso de plantas que crecen dentro de la ciudad.",aliasQuestIDs={},en={title="Kor'geld",aliases={"Kor'geld","Kor’geld"},body="Kor'geld works in Yelmak's Alchemy and Potions in Orgrimmar. He helps coordinate supplies and apprentice training, including the use of plants growing within the city.",aliasQuestIDs={}},fr={title="Kor'geld",body="Kor'geld travaille dans l'Alchimie de Yelmak et Potions dans Orgrimmar. Il aide à coordonner les fournitures et la formation des apprentis, y compris l'utilisation des plantes qui poussent dans la ville."},de={title="Kor'geld",body="Kor'geld arbeitet in Yelmak 'Alchemie und Potions in Orgrimmar. Er hilft bei der Koordinierung von Nachschub und Lehrlingsausbildung, einschließlich der Nutzung von Pflanzen, die innerhalb der Stadt wachsen."},pt={title="Kor'geld",body="Kor'geld trabalha na Alquimia de Yelmak e Potions em Orgrimmar. Ele ajuda a coordenar suprimentos e treinamento de aprendizes, incluindo o uso de plantas que crescem dentro da cidade."},pl={title="Kor'geld",body="Kor'geld pracuje w Yelmak's Alchemy and Potions w Orgrimmar. Pomaga koordynować dostawy i szkolenie uczniów, w tym wykorzystanie roślin rosnących w mieście."},ru={title="Kor'geld",body="Kor'geld работает в Yelmak \" Алхимии \" и Potions в Orgrimmar. Он помогает координировать снабжение и обучение учеников, включая использование растений, растущих в городе."},references={["person:yelmak"]=true,["place:orgrimmar"]=true}},
    ["person:korghan"] = {title="Kor'ghan",kind="Personaje",aliases={"Kor'ghan","Kor’ghan"},body="Kor'ghan conoce la preparación de antídotos en Orgrimmar. Su experiencia con el veneno de los venocolas ofrece ayuda a quienes sufren las picaduras de esos escórpidos en Durotar.",aliasQuestIDs={},en={title="Kor'ghan",aliases={"Kor'ghan","Kor’ghan"},body="Kor'ghan knows how to prepare antidotes in Orgrimmar. His experience with venomtail poison offers help to those stung by those scorpids in Durotar.",aliasQuestIDs={}},fr={title="Kor'ghan",body="Kor'ghan sait comment préparer des antidotes dans Orgrimmar. Son expérience avec le poison à queue de venin offre une aide à ceux qui sont piqué par les scorpions dans Durotar."},de={title="Kor'ghan",body="Kor'ghan weiß, wie man bei Orgrimmar Gegenmittel zubereitet. Seine Erfahrung mit Giftschwanzgiften hilft denjenigen, die von diesen Skorpiden bei Durotar gestochen werden."},pt={title="Kor'ghan",body="Kor'ghan sabe como preparar antídotos em Orgrimmar. Sua experiência com veneno de cauda de veneno oferece ajuda àqueles picados por esses escrúpulos em Durotar."},pl={title="Kor'ghan",body="Kor'ghan zna przygotowywanie odtrutek w Orgrimmar. Doświadczenie z trucizną jadowitego ogona pomaga osobom ukąszonym przez te skorpiony w Durotar."},ru={title="Kor'ghan",body="Kor'ghan знает, как готовить противоядие в Orgrimmar. Его опыт с ядом от хвостового яда помогает тем, кто был укушен скорпидами в Durotar."},references={["place:durotar"]=true,["place:orgrimmar"]=true}},
    ["person:korran"] = {title="Korran",kind="Personaje",aliases={"Korran"},body="Korran estudia los insectos de Los Baldíos desde El Cruce. Los testimonios de viajeros y las muestras de las colmenas lo ayudan a evaluar una amenaza que podría superar los límites de la región.",aliasQuestIDs={},en={title="Korran",aliases={"Korran"},body="Korran studies the Barrens’ insects from the Crossroads. Travelers’ accounts and hive samples help him assess a threat that may extend beyond the region.",aliasQuestIDs={}},fr={title="Korran",body="Korran étudie les insectes Barrens du Crossroads. Les récits des voyageurs et les échantillons de ruche l’aident à évaluer une menace qui peut s’étendre au-delà de la région."},de={title="Korran",body="Korran studiert die Barrens 'Insekten vom Crossroads aus. Reiseberichte und Bienenstockproben helfen ihm, eine Bedrohung einzuschätzen, die über die sich über die Region hinaus erstrecken kann."},pt={title="Korran",body="Korran estuda os insetos Barrens do Crossroads. As contas dos viajantes e amostras de colmeias o ajudam a avaliar uma ameaça que pode se estender além da região."},pl={title="Korran",body="Korran bada owady regionu Barrens z Crossroads. Relacje podróżnych i próbki z rojów pomagają mu oceniać zagrożenie mogące wykraczać poza region."},ru={title="Korran",body="Korran изучает Barrens  насекомых из Crossroads. Сведения путешественников и образцы ульев помогают ему оценить угрозу, которая может распространиться за пределы региона."},references={["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:krakle"] = {title="Krakle",kind="Personaje",aliases={"Krakle"},body="Krakle investiga el calor del Cráter de Un'Goro y su relación con las fuentes termales. Su termómetro, que mide en grados Kraklenheit, convierte la actividad volcánica en un problema que puede observarse y compararse.",aliasQuestIDs={},en={title="Krakle",aliases={"Krakle"},body="Krakle studies Un'Goro Crater’s heat and its relationship with hot springs. His thermometer, measuring in Kraklenheit, turns volcanic activity into a problem that can be observed and compared.",aliasQuestIDs={}},fr={title="Krakle",body="Krakle étudie la chaleur de Un'Goro Crater et sa relation avec les sources chaudes. Son thermomètre, mesurant en Kraklenheit, transforme l’activité volcanique en un problème qui peut être observé et comparé."},de={title="Krakle",body="Krakle untersucht die Hitze von Un'Goro Crater und ihre Beziehung zu heißen Quellen. Sein Thermometer, das in Kraklenheit misst, macht vulkanische Aktivität zu einem Problem, das beobachtet und verglichen werden kann."},pt={title="Krakle",body="Krakle estuda o calor de Un'Goro Crater e sua relação com fontes termais. Seu termômetro, medindo em Kraklenheit, transforma a atividade vulcânica em um problema que pode ser observado e comparado."},pl={title="Krakle",body="Krakle bada ciepło Un'Goro Crater i jego związek z gorącymi źródłami. Termometr mierzący w skali Kraklenheit zamienia aktywność wulkaniczną w zjawisko dające się obserwować oraz porównywać."},ru={title="Krakle",body="Krakle изучает тепло Un'Goro Crater  и его отношение к горячим источникам. Его термометр, измеряющий в Kraklenheit, превращает вулканическую активность в проблему, которую можно наблюдать и сравнивать."},references={["place:ungoro-crater"]=true}},
    ["person:kranal-fiss"] = {title="Kranal Fiss",kind="Personaje",aliases={"Kranal","Kranal Fiss"},body="Kranal Fiss es un guía chamánico de Los Baldíos, al norte de El Cruce. Sus enseñanzas ayudan a comprender el fuego como un elemento de destrucción y caos cuyo poder exige preparación.",aliasQuestIDs={},en={title="Kranal Fiss",aliases={"Kranal","Kranal Fiss"},body="Kranal Fiss is a shamanic guide in the Barrens, north of the Crossroads. His teaching helps explain fire as an element of destruction and chaos whose power demands preparation.",aliasQuestIDs={}},fr={title="Kranal Fiss",body="Kranal Fiss est un guide chamanique dans le Barrens, au nord du Crossroads. Son enseignement aide à expliquer le feu comme un élément de destruction et de chaos dont le pouvoir exige une préparation."},de={title="Kranal Fiss",body="Kranal Fiss ist ein schamanischer Führer im Barrens nördlich des Crossroads. Seine Lehre hilft, Feuer als Element der Zerstörung und des Chaos zu erklären, dessen Macht Vorbereitung Vorbereitung erfordert."},pt={title="Kranal Fiss",body="Kranal Fiss é um guia xamânico no Barrens, ao norte do Crossroads. Seu ensino ajuda a explicar o fogo como um elemento de destruição e caos cujo poder exige preparação."},pl={title="Kranal Fiss",body="Kranal Fiss jest szamańskim przewodnikiem w regionie Barrens, na północ od Crossroads. Jego nauki pomagają zrozumieć ogień jako żywioł zniszczenia i chaosu, którego moc wymaga przygotowania."},ru={title="Kranal Fiss",body="Kranal Fiss - шаманский гид в Barrens, к северу от Crossroads. Его учение помогает объяснить огонь как элемент разрушения и хаоса, сила которого требует подготовки."},references={["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:kravel-koalbeard"] = {title="Kravel Karbarbán",kind="Personaje",aliases={"Kravel","Kravel Karbarbán"},body="Kravel Karbarbán trabaja en el ambiente de las carreras del Desierto de Sal. Los suministros, los tratos y las rivalidades entre equipos forman parte de una actividad en la que la información puede ser tan valiosa como una buena máquina.",aliasQuestIDs={},en={title="Kravel Koalbeard",aliases={"Kravel","Kravel Koalbeard"},body="Kravel Koalbeard works amid the racing scene of the Shimmering Flats. Supplies, deals and rivalries between teams shape an activity in which information can be as valuable as a good machine.",aliasQuestIDs={}},fr={title="Kravel Koalbeard",body="Kravel Koalbeard fonctionne au milieu de la scène de course de la Shimmering Flats. Les fournitures, les transactions et les rivalités entre les équipes façonnent une activité dans laquelle l'information peut être aussi précieuse qu'une bonne machine."},de={title="Kravel Koalbeard",body="Kravel Koalbeard arbeitet inmitten der Rennszene des Shimmering Flats. Lieferungen, Deals und Rivalitäten zwischen Teams prägen eine Aktivität, in der Information, die so wertvoll sein kann wie eine gute Maschine."},pt={title="Kravel Koalbeard",body="Kravel Koalbeard funciona em meio à cena de corrida do Shimmering Flats. Suprimentos, negócios e rivalidades entre equipes moldam uma atividade na qual a informação pode ser tão valiosa quanto uma boa máquina."},pl={title="Kravel Koalbeard",body="Kravel Koalbeard działa w środowisku wyścigowym Shimmering Flats. Dostawy, umowy i rywalizacja zespołów kształtują zajęcie, w którym informacja potrafi być równie cenna jak dobra maszyna."},ru={title="Kravel Koalbeard",body="Kravel Koalbeard работает на фоне гоночной сцены Shimmering Flats. Поставки, сделки и соперничество между командами формируют деятельность, в которой информация может быть столь же ценной, как и хорошая машина."},references={["place:shimmering-flats"]=true}},
    ["person:kreenig-snarlsnout"] = {title="Kreenig Gruñucico",kind="Personaje",aliases={"Kreenig","Kreenig Gruñucico"},body="Kreenig Gruñucico dirige los asaltos de los jabaespines Crines de Acero contra las caravanas de Durotar. Sus ataques amenazan el tránsito de personas y suministros que sostiene a los asentamientos de la Horda.",aliasQuestIDs={},en={title="Kreenig Snarlsnout",aliases={"Kreenig","Kreenig Snarlsnout"},body="Kreenig Snarlsnout leads Razormane quilboar raids against caravans from Durotar. His attacks threaten the movement of people and supplies sustaining Horde settlements.",aliasQuestIDs={}},fr={title="Kreenig Snarlsnout",body="Kreenig Snarlsnout mène Razormane raids quilboar contre les caravanes de Durotar. Ses attaques menacent la circulation des personnes et des fournitures qui soutiennent les colonies Horde."},de={title="Kreenig Snarlsnout",body="Kreenig Snarlsnout führt Razormane Steppenwildschweine gegen Wohnwagen von Durotar an. Seine Angriffe bedrohen die Bewegung der Menschen und die Versorgung der Horde-Siedlungen."},pt={title="Kreenig Snarlsnout",body="Kreenig Snarlsnout lidera ataques de quilboar Razormane contra caravanas da Durotar. Seus ataques ameaçam o movimento de pessoas e suprimentos que sustentam os assentamentos Horde."},pl={title="Kreenig Snarlsnout",body="Kreenig Snarlsnout prowadzi najazdy kolcozwierzy Razormane na karawany z Durotar. Ataki zagrażają przemieszczaniu się ludzi i zapasów podtrzymujących osady frakcji Horde."},ru={title="Kreenig Snarlsnout",body="Kreenig Snarlsnout возглавляет Razormane набеги на караваны из Durotar. Его атаки угрожают передвижению людей и снабжения, поддерживающих поселения Horde."},references={["organization:horde"]=true,["organization:razormane"]=true,["place:durotar"]=true}},
    ["person:kreldig-ungor"] = {title="Kreldig Ungor",kind="Personaje",aliases={"Kreldig","Kreldig Ungor"},body="Kreldig Ungor es un contacto de Punta de Nijel que reúne información sobre Desolace. Su labor sirve a quienes intentan establecerse o trabajar en una región disputada por centauros y otros grupos.",aliasQuestIDs={},en={title="Kreldig Ungor",aliases={"Kreldig","Kreldig Ungor"},body="Kreldig Ungor is a contact in Nijel’s Point who gathers information about Desolace. His work serves those trying to settle or work in a region contested by centaurs and other groups.",aliasQuestIDs={}},fr={title="Kreldig Ungor",body="Kreldig Ungor est un contact en Nijel’s Point qui rassemble des informations sur Desolace. Son travail est au service de ceux qui tentent de s’installer ou de travailler dans une région contestée par des centaures et d’autres groupes."},de={title="Kreldig Ungor",body="Kreldig Ungor ist ein Ansprechpartner in Nijel’s Point, der Informationen über Desolace sammelt. Seine Arbeit dient denjenigen, die versuchen, sich in einer von Zentauren und anderen Gruppen umkämpften Region niederzulassen oder dort zu arbeiten."},pt={title="Kreldig Ungor",body="Kreldig Ungor é um contato em Nijel’s Point que reúne informações sobre Desolace. Seu trabalho serve aqueles que tentam se estabelecer ou trabalhar em uma região contestada por centauros e outros grupos."},pl={title="Kreldig Ungor",body="Kreldig Ungor jest kontaktem w Nijel’s Point zbierającym informacje o Desolace. Jego praca służy osobom próbującym osiedlić się lub działać w regionie będącym przedmiotem walk centaurów i innych grup."},ru={title="Kreldig Ungor",body="Kreldig Ungor - это контакт в Nijel’s Point, который собирает информацию о Desolace. Его работа служит тем, кто пытается поселиться или работать в регионе, оспариваемом кентаврами и другими группами."},references={["place:desolace"]=true,["place:nijels-point"]=true}},
    ["person:krinkle-goodsteel"] = {title="Krinkle Buenacero",kind="Personaje",aliases={"Krinkle","Krinkle Buenacero"},body="Krinkle Buenacero trabaja en Gadgetzan y busca materiales y herramientas procedentes de lugares lejanos. Su libro de contabilidad convierte las necesidades de su oficio en una red de encargos y suministros.",aliasQuestIDs={},en={title="Krinkle Goodsteel",aliases={"Krinkle","Krinkle Goodsteel"},body="Krinkle Goodsteel works in Gadgetzan and seeks materials and tools from distant places. His ledger connects the needs of his craft with a network of commissions and supplies.",aliasQuestIDs={}},fr={title="Krinkle Goodsteel",body="Krinkle Goodsteel travaille dans Gadgetzan et recherche des matériaux et des outils à partir de lieux éloignés. Son registre relie les besoins de son métier à un réseau de commissions et de fournitures."},de={title="Krinkle Goodsteel",body="Krinkle Goodsteel arbeitet in Gadgetzan und sucht Materialien und Werkzeuge von weit entfernten Orten. Sein Hauptbuch verbindet die Bedürfnisse seines Handwerks mit einem Netz von Kommissionen und Vorräten."},pt={title="Krinkle Goodsteel",body="Krinkle Goodsteel trabalha em Gadgetzan e procura materiais e ferramentas de lugares distantes. Seu livro-razão conecta as necessidades de seu ofício com uma rede de comissões e suprimentos."},pl={title="Krinkle Goodsteel",body="Krinkle Goodsteel pracuje w Gadgetzan i poszukuje materiałów oraz narzędzi z odległych miejsc. Jego księga łączy potrzeby rzemiosła z siecią zleceń i dostaw."},ru={title="Krinkle Goodsteel",body="Krinkle Goodsteel работает в Gadgetzan и ищет материалы и инструменты из далеких мест. Его бухгалтерская книга связывает потребности его корабля с сетью комиссий и поставок."},references={["place:gadgetzan"]=true}},
    ["person:krog"] = {title="Krog",kind="Personaje",aliases={"Krog"},body="Krog es un contacto del Poblado Murohelecho que investiga sucesos del Marjal Revolcafango. Las pistas recogidas en los caminos y en edificios dañados forman parte de sus esfuerzos por comprender la violencia de la región.",aliasQuestIDs={},en={title="Krog",aliases={"Krog"},body="Krog is a contact in Brackenwall Village investigating events in Dustwallow Marsh. Clues found on roads and in damaged buildings form part of his efforts to understand the region’s violence.",aliasQuestIDs={}},fr={title="Krog",body="Krog est un contact dans Brackenwall Village enquêtant sur des événements dans Dustwallow Marsh. Les indices trouvés sur les routes et dans les bâtiments endommagés font partie de ses efforts pour comprendre la violence dans la région."},de={title="Krog",body="Krog ist ein Ansprechpartner in Brackenwall Village, der die Geschehnisse in Dustwallow Marsh untersucht. Hinweise auf Straßen und beschädigte Gebäude sind Teil seiner Bemühungen, die Gewalt in der Region zu verstehen."},pt={title="Krog",body="Krog é um contato no Brackenwall Village investigando eventos em Dustwallow Marsh. As pistas encontradas nas estradas e em edifícios danificados fazem parte de seus esforços para entender a violência da região."},pl={title="Krog",body="Krog jest kontaktem w Brackenwall Village badającym wydarzenia w Dustwallow Marsh. Wskazówki znajdowane na drogach i w uszkodzonych budynkach pomagają mu zrozumieć przemoc w regionie."},ru={title="Krog",body="Krog - это контакт в Brackenwall Village, который расследует события в Dustwallow Marsh. Следы, найденные на дорогах и в поврежденных зданиях, являются частью его усилий по пониманию насилия в регионе."},references={["place:brackenwall-village"]=true,["place:dustwallow-marsh"]=true}},
    ["person:kroshius"] = {title="Kroshius",kind="Personaje",aliases={"Kroshius"},body="Kroshius es un infernal de Frondavil cuyo núcleo conserva un intenso poder demoníaco. Sus restos pueden volver a arder mediante componentes apropiados, una propiedad que interesa a quienes estudian la invocación de infernales.",aliasQuestIDs={},en={title="Kroshius",aliases={"Kroshius"},body="Kroshius is an infernal in Felwood whose core preserves intense demonic power. His remains can be rekindled with suitable components, a property of interest to those studying infernal summoning.",aliasQuestIDs={}},fr={title="Kroshius",body="Kroshius est un infernal dans Felwood dont le noyau préserve une puissance démoniaque intense. Ses restes peuvent être rallumés avec des composants appropriés, une propriété d'intérêt pour ceux qui étudient l'invocation infernale."},de={title="Kroshius",body="Kroshius ist in Felwood ein Höllenwesen, dessen Kern eine intensive dämonische Macht bewahrt. Seine sterblichen Überreste können mit geeigneten Bestandteilen wiederangezündet werden, eine Eigenschaft, die für diejenigen interessant ist, die höllische Vorladung studieren."},pt={title="Kroshius",body="Kroshius é um infernal no Felwood cujo núcleo preserva o poder demoníaco intenso. Seus restos mortais podem ser reacendidos com componentes adequados, uma propriedade de interesse para aqueles que estudam a convocação infernal."},pl={title="Kroshius",body="Kroshius jest infernalem w Felwood, którego rdzeń zachowuje intensywną demoniczną moc. Szczątki można ponownie rozpalić odpowiednimi składnikami, co interesuje badaczy przywoływania infernali."},ru={title="Kroshius",body="Kroshius - это адский в Felwood, чье ядро сохраняет сильную демоническую силу. Его останки можно восстановить с помощью подходящих компонентов, что представляет интерес для тех, кто изучает призыв к ада."},references={["place:felwood"]=true}},
    ["person:krueg-skullsplitter"] = {title="Krueg Machacacráneos",kind="Personaje",aliases={"Krueg","Krueg Machacacráneos"},body="Krueg Machacacráneos forma parte de una expedición enviada a Feralas desde Orgrimmar. Su interés por elaborar una capa para su compañera Korrin lo lleva a buscar las delicadas alas de los dragones feéricos.",aliasQuestIDs={},en={title="Krueg Skullsplitter",aliases={"Krueg","Krueg Skullsplitter"},body="Krueg Skullsplitter is part of an expedition sent to Feralas from Orgrimmar. His interest in making a cloak for his companion Korrin leads him to seek the delicate wings of faerie dragons.",aliasQuestIDs={}},fr={title="Krueg Skullsplitter",body="Krueg Skullsplitter fait partie d'une expédition envoyée à Feralas depuis Orgrimmar. Son intérêt pour la confection d’un manteau pour son compagnon Korrin l’amène à chercher les ailes délicates des fées dragons."},de={title="Krueg Skullsplitter",body="Krueg Skullsplitter ist Teil einer Expedition, die Orgrimmar zu Feralas geschickt hat. Sein Interesse, seinem Gefährten Korrin einen Mantel anzufertigen, bringt ihn dazu, die zarten Flügel von Feendrachen zu suchen."},pt={title="Krueg Skullsplitter",body="Krueg Skullsplitter faz parte de uma expedição enviada à Feralas da Orgrimmar. Seu interesse em fazer um manto para seu companheiro Korrin o leva a buscar as delicadas asas de dragões fadas."},pl={title="Krueg Skullsplitter",body="Krueg Skullsplitter należy do ekspedycji wysłanej do Feralas z Orgrimmar. Chęć wykonania płaszcza dla towarzyszki o imieniu Korrin prowadzi go do poszukiwania delikatnych skrzydeł baśniowych smoków."},ru={title="Krueg Skullsplitter",body="Krueg Skullsplitter - часть экспедиции, отправленной в Feralas из Orgrimmar. Его интерес к изготовлению платья для своего товарища Korrin заставляет его искать тонкие крылья фейских драконов."},references={["organization:skullsplitter"]=true,["place:feralas"]=true,["place:orgrimmar"]=true}},
    ["person:kuramaa"] = {title="Kuramaa",kind="Personaje",aliases={"Kuramaa"},body="Los habitantes de las Tierras Altas de Shen'dar describen a Kuramaa como un antiguo espíritu del bosque. Según sus relatos, vive dentro de un tocón retorcido cerca del pilón de anclaje de las tierras altas. Los relatos sobre este ser incluyen una máscara de madera.",aliasQuestIDs={},en={title="Kuramaa",aliases={"Kuramaa"},body="Residents of the Shen'dar Highlands describe Kuramaa as an ancient forest spirit. According to their accounts, it lives inside a twisted stump near the highlands' Anchor Pylon. A wooden mask is associated with the spirit and the traditions surrounding it.",aliasQuestIDs={}},fr={title="Kuramaa",body="Les habitants du Shen'dar Highlands décrivent le Kuramaa comme un ancien esprit forestier. Selon leurs récits, il vit à l'intérieur d'une souche tordue près de l'ancre des hauts plateaux Pylon. Un masque en bois est associé à l’esprit et aux traditions qui l’entourent."},de={title="Kuramaa",body="Bewohner des Shen'dar Highlands beschreiben Kuramaa als uralten Waldgeist. Ihren Schilderungen zufolge lebt sie in einem verdrehten Baumstumpf in der Nähe des Ankers Pylon im Hochland. Eine hölzerne Maske wird mit dem Geist und den sie umgebenden Traditionen in Verbindung gebracht."},pt={title="Kuramaa",body="Residentes do Shen'dar Highlands descrevem o Kuramaa como um espírito de floresta antiga. De acordo com suas contas, ele vive dentro de um toco torcido perto da Anchor Pylon das terras altas. Uma máscara de madeira está associada ao espírito e às tradições que a cercam."},pl={title="Kuramaa",body="Mieszkańcy Shen'dar Highlands opisują Kuramaa jako pradawnego ducha lasu. Według ich relacji żyje wewnątrz powykręcanego pnia przy Anchor Pylon na wyżynach. Drewniana maska wiąże się z duchem i otaczającymi go tradycjami."},ru={title="Kuramaa",body="Жители Shen'dar Highlands описывают Kuramaa как древнего лесного духа. Согласно их рассказам, он живет внутри извилистого пнёвника возле высокогорного якоря Pylon. Деревянная маска связана с духом и традициями, которые его окружают."},references={["place:shendar"]=true,["place:shendar-highlands"]=true}},
    ["person:kurothel"] = {title="Kurothel",kind="Personaje",aliases={"Kurothel"},body="Kurothel es el esposo de Maseara Lunaotoño, de Canción del Bosque. La violencia contra los templos y los habitantes del bosque lo llevó a seguir a los druidas que se enfrentaban a los sátiros.",aliasQuestIDs={},en={title="Kurothel",aliases={"Kurothel"},body="Kurothel is Maseara Autumnmoon’s husband from Forest Song. Violence against the forest’s temples and inhabitants led him to follow the druids confronting the satyrs.",aliasQuestIDs={}},fr={title="Kurothel",body="Kurothel est le mari de Maseara Autumnmoon depuis Forest Song. La violence contre les temples et les habitants de la forêt l’a amené à suivre les druides affrontant les satyres."},de={title="Kurothel",body="Kurothel ist Maseara Autumnmoon 'Ehemann von Forest Song. Die Gewalt gegen die Tempel und Einwohner des Waldes Waldes veranlasste ihn, den Druiden zu folgen, die sich den Satyren gegenüber zu stellen."},pt={title="Kurothel",body="Kurothel é o marido de Maseara Autumnmoon da Forest Song. A violência contra os templos e habitantes da floresta levou-o a seguir os druidas que confrontavam os sátiros."},pl={title="Kurothel",body="Kurothel jest mężem postaci Maseara Autumnmoon z Forest Song. Przemoc wobec świątyń i mieszkańców lasu skłoniła go do podążenia za druidami walczącymi z satyrami."},ru={title="Kurothel",body="Kurothel — супруг Maseara Autumnmoon родом из Forest Song. Насилие против храмов и жителей леса заставило его следовать за друидами, противостоящими сатирикам."},references={["person:maseara-autumnmoon"]=true,["place:forest-song"]=true}},
    ["person:kyle-the-frenzied"] = {title="Kyle el Demenciado",kind="Personaje",aliases={"Kyle","Kyle el Demenciado"},body="Kyle es el apreciado cachorro de Ahab Pezuña de Trigo. Recorre el Poblado Pezuña de Sangre y siente especial predilección por la carne de zancudo, un alimento capaz de captar enseguida su atención.",aliasQuestIDs={},en={title="Kyle the Frenzied",aliases={"Kyle","Kyle the Frenzied"},body="Kyle is Ahab Wheathoof’s treasured puppy. He roams Bloodhoof Village and is especially fond of strider meat, a meal that quickly catches his attention.",aliasQuestIDs={}},fr={title="Kyle the Frenzied",body="Kyle est le chiot chéri de Ahab Wheathoof. Il erre Bloodhoof Village et est particulièrement friand de viande striever, un repas qui attire rapidement son attention."},de={title="Kyle the Frenzied",body="Kyle ist Ahab Wheathoof 'geschätzter Welpe. Er streift durch Bloodhoof Village und liebt vor allem Schreitbares Fleisch, eine Mahlzeit, die ihm schnell ins Auge fällt."},pt={title="Kyle the Frenzied",body="Kyle é o filhote de cachorro estimado da Ahab Wheathoof. Ele vagueia por Bloodhoof Village e gosta especialmente de carne estridente, uma refeição que rapidamente chama sua atenção."},pl={title="Kyle the Frenzied",body="Kyle jest ukochanym szczeniakiem postaci Ahab Wheathoof. Wędruje po Bloodhoof Village i szczególnie lubi mięso biegacza, posiłek szybko przyciągający jego uwagę."},ru={title="Kyle the Frenzied",body="Kyle - это драгоценный щенк Ahab Wheathoof. Он бродит по Bloodhoof Village и особенно любит мясо долгоногов — такую еду он замечает очень быстро."},references={["person:ahab-wheathoof"]=true,["place:bloodhoof-village"]=true}},
    ["person:kzan"] = {title="Kzan",kind="Personaje",aliases={"Kzan"},body="Kzan es un forjador de armas de El Cubil. Mantener equipados a los nuevos reclutas forma parte de su trabajo, en un lugar donde las armas de entrenamiento abandonadas todavía pueden recuperarse para quienes comienzan su formación.",aliasQuestIDs={},en={title="Kzan",aliases={"Kzan"},body="Kzan is a weaponsmith in the Den. Keeping new recruits supplied is part of his work, in a place where abandoned training weapons can still be recovered for those beginning their instruction.",aliasQuestIDs={}},fr={title="Kzan",body="Kzan est un forgeron dans la fosse. Garder de nouvelles recrues fait partie de son travail, dans un endroit où les armes d'entraînement abandonnées peuvent encore être récupérées pour ceux qui commencent leur instruction."},de={title="Kzan",body="Kzan ist Waffenschmied in der Höhle. Die Versorgung neuer Rekruten ist Teil seiner Arbeit, an einem Ort, an dem verlassene Trainingswaffen noch immer für diejenigen zurückgeholt werden können, die ihre Ausbildung beginnen."},pt={title="Kzan",body="Kzan é um armeiro no Den. Manter novos recrutas fornecidos é parte de seu trabalho, em um lugar onde armas de treinamento abandonadas ainda podem ser recuperadas para aqueles que iniciam suas instruções."},pl={title="Kzan",body="Kzan jest kowalem broni w Den. Zapewnianie wyposażenia nowym rekrutom należy do jego pracy w miejscu, gdzie porzucona broń treningowa nadal może służyć rozpoczynającym naukę."},ru={title="Kzan",body="Kzan - оружейник в \"Крыле\". Поддержание новых рекрутов в снабжении является частью его работы, в месте, где заброшенное оружие обучения все еще может быть восстановлено для тех, кто начинает их обучение."},references={}},
    ["person:lady-callow"] = {title="Lady Callow",kind="Personaje",aliases={"Lady Callow"},body="Lady Callow reúne vendas de tejido mágico en Orgrimmar. Su papel en los preparativos militares de la Horda se centra en obtener los suministros que permitirán atender a los heridos.",aliasQuestIDs={},en={title="Lady Callow",aliases={"Lady Callow"},body="Lady Callow gathers mageweave bandages in Orgrimmar. Her part in Horde military preparations centers on obtaining the supplies needed to care for the wounded.",aliasQuestIDs={}},fr={title="Lady Callow",body="Lady Callow rassemble des bandages mageweave dans Orgrimmar. Sa participation aux préparatifs militaires de la Horde est axée sur l’obtention des fournitures nécessaires aux soins des blessés."},de={title="Lady Callow",body="Lady Callow sammelt in Orgrimmar Magnetbandagierte Binden. Ihre Rolle bei Horde militärischen Vorbereitungen konzentriert sich auf die Beschaffung der Vorräte, die zur Versorgung der Verwundeten benötigt werden."},pt={title="Lady Callow",body="Lady Callow reúne bandagens mageweave em Orgrimmar. Sua parte na preparação militar Horde centra-se na obtenção dos suprimentos necessários para cuidar dos feridos."},pl={title="Lady Callow",body="Lady Callow zbiera bandaże z tkaniny magii w Orgrimmar. Jej udział w wojskowych przygotowaniach frakcji Horde skupia się na zdobywaniu zapasów potrzebnych do opieki nad rannymi."},ru={title="Lady Callow",body="Lady Callow собирает магия-ткажные бинты в Orgrimmar. Ее роль в военной подготовке Horde сосредоточена на получении необходимых материалов для ухода за ранеными."},references={["organization:horde"]=true,["place:orgrimmar"]=true}},
    ["person:lady-sathrah"] = {title="Lady Sathrah",kind="Personaje",aliases={"Lady Sathrah","Sathrah"},body="Lady Sathrah es una araña de Teldrassil que estuvo vinculada a la gracia de Elune. Sus telas plateadas recogían el rocío de la noche, al que se atribuían propiedades curativas conservadas por las sacerdotisas del templo.",aliasQuestIDs={},en={title="Lady Sathrah",aliases={"Lady Sathrah","Sathrah"},body="Lady Sathrah is a Teldrassil spider once associated with Elune’s grace. Her silver webs gathered night dew credited with healing properties preserved by the temple’s priestesses.",aliasQuestIDs={}},fr={title="Lady Sathrah",body="Lady Sathrah est une araignée Teldrassil autrefois associée à la grâce de Elune. Ses toiles d’argent rassemblaient la rosée nocturne créditée de propriétés curatives préservées par les prêtresses du temple."},de={title="Lady Sathrah",body="Lady Sathrah ist eine Teldrassil-Spinne, die einst mit Elunes Anmut in Verbindung gebracht wurde. Ihre silbernen Netze sammelten den Nachttau, der von den Priesterinnen des Tempels erhaltenen heilenden Eigenschaften zugeschrieben wurde."},pt={title="Lady Sathrah",body="Lady Sathrah é uma aranha Teldrassil, uma vez associada à graça de Elune. Suas teias de prata reuniam orvalho noturno creditado com propriedades curativas preservadas pelas sacerdotisas do templo."},pl={title="Lady Sathrah",body="Lady Sathrah jest pająkiem Teldrassil niegdyś związanym z łaską bogini Elune. Jej srebrne sieci zbierały nocną rosę, której przypisywano lecznicze właściwości zachowywane w wiedzy kapłanek świątyni."},ru={title="Lady Sathrah",body="Lady Sathrah - паук Teldrassil, когда-то ассоциированный с благодатью Elune. Ее серебряные сети собирали ночную росу, которая обладала целебными свойствами, сохраненными священницей храма."},references={["npc:elune"]=true,["place:teldrassil"]=true}},
    ["person:laird"] = {title="Laird",kind="Personaje",aliases={"Laird"},body="Laird intercambia observaciones sobre los peces de la costa con Nessa. Le interesan las diferencias entre la fauna local y la de Teldrassil, y considera posible que el Árbol del Mundo influya en los animales de sus aguas.",aliasQuestIDs={},en={title="Laird",aliases={"Laird"},body="Laird exchanges observations about coastal fish with Nessa. He is interested in differences between local wildlife and Teldrassil’s, and suspects the World Tree may influence the animals in its waters.",aliasQuestIDs={}},fr={title="Laird",body="Laird échange des observations sur les poissons côtiers avec Nessa. Il s’intéresse aux différences entre la faune locale et celle de Teldrassil, et soupçonne que le World Tree pourrait influencer les animaux dans ses eaux."},de={title="Laird",body="Laird tauscht mit Nessa Beobachtungen über Küstenfische aus. Er interessiert sich für die Unterschiede zwischen lokaler Tierwelt und Teldrassil 's und vermutet, dass der World Tree die Tiere in seinen Gewässern beeinflussen könnte."},pt={title="Laird",body="Laird troca observações sobre peixes costeiros com Nessa. Ele está interessado nas diferenças entre a vida selvagem local e a vida selvagem de Teldrassil, e suspeita que o World Tree possa influenciar os animais em suas águas."},pl={title="Laird",body="Laird wymienia obserwacje ryb przybrzeżnych z postacią Nessa. Interesują go różnice między miejscową fauną a fauną Teldrassil i podejrzewa, że World Tree może wpływać na zwierzęta w otaczających wodach."},ru={title="Laird",body="Laird обменивается наблюдениями о прибрежных рыбах с Nessa. Он интересуется различиями между местной дикой природой и Teldrassil s, и подозревает, что World Tree может влиять на животных в его водах."},references={["person:nessa-shadowsong"]=true,["place:teldrassil"]=true}},
    ["person:lakota-windsong"] = {title="Lakota Son del Viento",kind="Personaje",aliases={"Lakota","Lakota Son del Viento"},body="Lakota Son del Viento es una tauren de Las Mil Agujas con vínculos en el Poblado Viento Libre. Su historia está ligada a las tensiones y amenazas que rodean la Cumbre de la Nube Negra.",aliasQuestIDs={},en={title="Lakota Windsong",aliases={"Lakota","Lakota Windsong"},body="Lakota Windsong is a tauren of Thousand Needles with ties to Freewind Post. Her story is connected with the tensions and threats surrounding Darkcloud Pinnacle.",aliasQuestIDs={}},fr={title="Lakota Windsong",body="Lakota Windsong est un tauren de Thousand Needles avec des liens vers Freewind Post. Son histoire est liée aux tensions et aux menaces entourant Darkcloud Pinnacle."},de={title="Lakota Windsong",body="Lakota Windsong ist ein Tauren von Thousand Needles mit Verbindungen zu Freewind Post. Ihre Geschichte ist mit den Spannungen und Bedrohungen verbunden, die Darkcloud Pinnacle umgeben."},pt={title="Lakota Windsong",body="Lakota Windsong é um tauren de Thousand Needles com laços com Freewind Post. Sua história está ligada às tensões e ameaças em torno do Darkcloud Pinnacle."},pl={title="Lakota Windsong",body="Lakota Windsong jest taurenką z Thousand Needles związaną z Freewind Post. Jej historia splata się z napięciami i zagrożeniami otaczającymi Darkcloud Pinnacle."},ru={title="Lakota Windsong",body="Lakota Windsong - это таурен Thousand Needles, связанный с Freewind Post. Ее история связана с напряженностью и угрозами, окружающими Darkcloud Pinnacle."},references={["place:darkcloud-pinnacle"]=true,["place:freewind-post"]=true,["place:thousand-needles"]=true}},
    ["person:lakotamani"] = {title="Lakota'mani",kind="Personaje",aliases={"Lakota'mani","Lakota’mani"},body="Lakota'mani es un gran kodo de Los Baldíos. Su tamaño y su fuerza lo convierten en una de las bestias que los cazadores de la región reconocen como pruebas de valor.",aliasQuestIDs={},en={title="Lakota'mani",aliases={"Lakota'mani","Lakota’mani"},body="Lakota'mani is a great kodo in the Barrens. Its size and strength make it one of the beasts that the region’s hunters recognize as tests of courage.",aliasQuestIDs={}},fr={title="Lakota'mani",body="Lakota'mani est un grand kodo dans le Barrens. Sa taille et sa force en font l’une des bêtes que les chasseurs de la région reconnaissent comme des tests de courage."},de={title="Lakota'mani",body="Lakota'mani ist ein großartiger Kodo im Barrens. Seine Größe und Stärke machen ihn zu einem der Tiere, die von den Jägern der Region als Mutprobe erkannt werden."},pt={title="Lakota'mani",body="Lakota'mani é um ótimo kodo no Barrens. Seu tamanho e força o tornam uma das bestas que os caçadores da região reconhecem como testes de coragem."},pl={title="Lakota'mani",body="Lakota'mani jest wielkim kodo regionu Barrens. Rozmiar i siła czynią to zwierzę jedną z bestii uznawanych przez miejscowych myśliwych za próbę odwagi."},ru={title="Lakota'mani",body="Lakota'mani - отличный кодо в Barrens. Его размер и сила делают его одним из зверей, которые охотники региона признают испытанием мужества."},references={["place:the-barrens"]=true}},
    ["person:lanka-farshot"] = {title="Lanka Tirolejano",kind="Personaje",aliases={"Lanka","Lanka Tirolejano"},body="Lanka instruye a los nuevos cazadores tauren en los fundamentos de su oficio. Su tarea consiste en prepararlos para una vida en la que conocer a la presa es tan necesario como aprender a usar sus armas.",aliasQuestIDs={},en={title="Lanka Farshot",aliases={"Lanka","Lanka Farshot"},body="Lanka teaches new tauren hunters the foundations of their calling. The work prepares them for a life in which understanding prey is as necessary as learning to use their weapons.",aliasQuestIDs={}},fr={title="Lanka Farshot",body="Lanka enseigne aux nouveaux chasseurs de taurens les fondements de leur vocation. Le travail les prépare à une vie dans laquelle la compréhension des proies est aussi nécessaire que l'apprentissage de l'utilisation de leurs armes."},de={title="Lanka Farshot",body="Lanka lehrt neue Taurenjäger die Grundlagen ihrer Berufung. Die Arbeit bereitet sie auf ein Leben vor, in dem das Verständnis der Beute ebenso notwendig ist wie das Lernen, ihre Waffen zu benutzen."},pt={title="Lanka Farshot",body="Lanka ensina aos novos caçadores de tauren os fundamentos de sua vocação. O trabalho os prepara para uma vida em que a compreensão da presa é tão necessária quanto aprender a usar suas armas."},pl={title="Lanka Farshot",body="Lanka uczy nowych taurenskich łowców podstaw powołania. Przygotowuje ich do życia, w którym zrozumienie zdobyczy jest równie niezbędne jak nauka władania bronią."},ru={title="Lanka Farshot",body="Lanka учит новых охотников на быков основам их призвания. Эта работа готовит их к жизни, в которой понимание добычи так же важно, как и знание использования оружия."},references={}},
    ["person:lar-prowltusk"] = {title="Lar Colmillo Acechador",kind="Personaje",aliases={"Lar","Lar Colmillo Acechador"},body="Lar Colmillo Acechador es uno de los exploradores de confianza de los Lanza Negra. Vigila el flanco occidental del Poblado Sen'jin, ayudando a sostener el pacto de protección entre trols y orcos.",aliasQuestIDs={},en={title="Lar Prowltusk",aliases={"Lar","Lar Prowltusk"},body="Lar Prowltusk is one of the Darkspear’s trusted scouts. He watches Sen'jin Village’s western flank, helping uphold the pact of protection between trolls and orcs.",aliasQuestIDs={}},fr={title="Lar Prowltusk",body="Lar Prowltusk est l'un des éclaireurs de confiance du Darkspear. Il regarde le flanc ouest de Sen'jin Village, aidant à faire respecter le pacte de protection entre les trolls et les orcs."},de={title="Lar Prowltusk",body="Lar Prowltusk ist einer der vertrauenswürdigen Kundschafter von Darkspear. Er beobachtet die Westflanke von Sen'jin Village und hilft, den Schutzpakt zwischen Trollen und Orks aufrechtzuerhalten."},pt={title="Lar Prowltusk",body="Lar Prowltusk é um dos olheiros confiáveis do Darkspear. Ele observa o flanco ocidental do Sen'jin Village, ajudando a manter o pacto de proteção entre trolls e orcs."},pl={title="Lar Prowltusk",body="Lar Prowltusk jest jednym z zaufanych zwiadowców Darkspear. Obserwuje zachodnią flankę Sen'jin Village, pomagając podtrzymywać pakt ochronny między trollami a orkami."},ru={title="Lar Prowltusk",body="Lar Prowltusk - один из доверенных разведчиков Darkspear. Он наблюдает за западным флангом Sen'jin Village, помогая поддерживать пакт о защите между троллями и орками."},references={["organization:darkspear-tribe"]=true,["place:senjin-village"]=true}},
    ["person:larion"] = {title="Larion",kind="Personaje",aliases={"Larion"},body="Larion es un viajero del Refugio de Marshal, en el Cráter de Un'Goro. Su rivalidad con Muigin se mezcla con el estudio y el uso de las plantas peligrosas del cráter.",aliasQuestIDs={},en={title="Larion",aliases={"Larion"},body="Larion is a traveler at Marshal's Refuge in Un'Goro Crater. His rivalry with Muigin overlaps with the study and use of the crater’s dangerous plants.",aliasQuestIDs={}},fr={title="Larion",body="Larion est un voyageur chez Marshal's Refuge à Un'Goro Crater. Sa rivalité avec Muigin chevauche l’étude et l’utilisation des plantes dangereuses du cratère."},de={title="Larion",body="Larion ist Reisender bei Marshal's Refuge in Un'Goro Crater. Seine Rivalität mit Muigin überschneidet sich mit dem Studium und der Nutzung der gefährlichen Pflanzen des Kraters."},pt={title="Larion",body="Larion é um viajante no Marshal's Refuge em Un'Goro Crater. Sua rivalidade com Muigin se sobrepõe com o estudo e uso das plantas perigosas da cratera."},pl={title="Larion",body="Larion jest podróżnikiem w Marshal's Refuge w Un'Goro Crater. Jego rywalizacja z postacią Muigin splata się z badaniem i wykorzystywaniem niebezpiecznych roślin krateru."},ru={title="Larion",body="Larion — путешественник, остановившийся в Marshal's Refuge на территории Un'Goro Crater. Его соперничество с Muigin перекрывается с изучением и использованием опасных растений кратера."},references={["person:muigin"]=true,["place:marshals-refuge"]=true,["place:ungoro-crater"]=true}},
    ["person:larkorwi"] = {title="Lar'korwi",kind="Personaje",aliases={"Lar'korwi","Lar’korwi"},body="Lar'korwi es un gran depredador del Cráter de Un'Goro. Defiende sus presas con una persistencia extraordinaria y puede perseguir durante días a quien considere un intruso en su caza.",aliasQuestIDs={},en={title="Lar'korwi",aliases={"Lar'korwi","Lar’korwi"},body="Lar'korwi is a great predator of Un'Goro Crater. He defends his kills with extraordinary persistence and can pursue anyone he considers an intruder in his hunt for days.",aliasQuestIDs={}},fr={title="Lar'korwi",body="Lar'korwi est un grand prédateur de Un'Goro Crater. Il défend ses meurtres avec une persistance extraordinaire et peut poursuivre n'importe qui qu'il considère comme un intrus dans sa chasse pendant des jours."},de={title="Lar'korwi",body="Lar'korwi ist ein großer Feind von Un'Goro Crater. Er verteidigt seine Morde mit außergewöhnlicher Ausdauer und kann jeden, den er für einen Eindringling hält, tagelang auf seiner Jagd verfolgen."},pt={title="Lar'korwi",body="Lar'korwi é um grande predador de Un'Goro Crater. Ele defende suas mortes com extraordinária persistência e pode perseguir qualquer um que considere um intruso em sua caçada por dias."},pl={title="Lar'korwi",body="Lar'korwi jest wielkim drapieżnikiem Un'Goro Crater. Broni zdobyczy z niezwykłą wytrwałością i potrafi przez wiele dni ścigać każdego, kogo uzna za intruza w swoich łowach."},ru={title="Lar'korwi",body="Lar'korwi - большой хищник Un'Goro Crater. Он защищает свою добычу с необычайной настойчивостью и может преследовать любого, кого он считает злоумышленником в своей охоте, в течение нескольких дней."},references={["place:ungoro-crater"]=true}},
    ["person:latronicus-moonspear"] = {title="Latronicus Lanzaluna",kind="Personaje",aliases={"Latronicus","Latronicus Lanzaluna"},body="Latronicus Lanzaluna trabaja desde el Bastión Plumaluna en la defensa de Feralas. Reúne informes de exploradores sobre los nagas y los objetos que encuentran en sus excavaciones.",aliasQuestIDs={},en={title="Latronicus Moonspear",aliases={"Latronicus","Latronicus Moonspear"},body="Latronicus Moonspear works from Feathermoon Stronghold in the defense of Feralas. He gathers scouts’ reports about the naga and the objects they uncover in their excavations.",aliasQuestIDs={}},fr={title="Latronicus Moonspear",body="Latronicus Moonspear travaille de Feathermoon Stronghold dans la défense de Feralas. Il rassemble les rapports des éclaireurs sur le naga et les objets qu’ils découvrent dans leurs fouilles."},de={title="Latronicus Moonspear",body="Latronicus Moonspear arbeitet von Feathermoon Stronghold aus in der Verteidigung von Feralas. Er sammelt Berichte von Pfadfindern über die Naga und die Gegenstände, die sie bei ihren Ausgrabungen freilegen."},pt={title="Latronicus Moonspear",body="Latronicus Moonspear trabalha a partir Feathermoon Stronghold na defesa de Feralas. Ele reúne relatórios de batedores sobre a naga e os objetos que eles descobrem em suas escavações."},pl={title="Latronicus Moonspear",body="Latronicus Moonspear działa z Feathermoon Stronghold na rzecz obrony Feralas. Gromadzi raporty zwiadowców dotyczące nag oraz przedmiotów odkrywanych podczas ich wykopalisk."},ru={title="Latronicus Moonspear",body="Latronicus Moonspear работает от Feathermoon Stronghold в защиту Feralas. Он собирает отчёты разведчиков о нагах и предметах, которые они обнаруживают при раскопках."},references={["place:feathermoon-stronghold"]=true,["place:feralas"]=true}},
    ["person:laurna-morninglight"] = {title="Laurna Luzdelalba",kind="Personaje",aliases={"Laurna","Laurna Luzdelalba"},body="Laurna Luzdelalba enseña en Dolanaar los caminos de Elune. Guía a los nuevos sacerdotes y los ayuda a obtener las vestimentas que expresan su vocación al servicio de la diosa.",aliasQuestIDs={},en={title="Laurna Morninglight",aliases={"Laurna","Laurna Morninglight"},body="Laurna Morninglight teaches the ways of Elune in Dolanaar. She guides new priests and helps them earn the garments expressing their calling in the goddess’s service.",aliasQuestIDs={}},fr={title="Laurna Morninglight",body="Laurna Morninglight enseigne les manières de Elune dans Dolanaar. Elle guide les nouveaux prêtres et les aide à gagner les vêtements exprimant leur vocation au service de la déesse."},de={title="Laurna Morninglight",body="Laurna Morninglight lehrt Dolanaar die Wege von Elune. Sie leitet neue Priester und hilft ihnen, die Gewänder zu verdienen, die ihrer Berufung im Dienst der Göttin der Göttin auszudrücken."},pt={title="Laurna Morninglight",body="Laurna Morninglight ensina os caminhos de Elune em Dolanaar. Ela guia novos sacerdotes e os ajuda a ganhar as roupas expressando seu chamado no serviço da deusa."},pl={title="Laurna Morninglight",body="Laurna Morninglight uczy dróg bogini Elune w Dolanaar. Prowadzi nowych kapłanów i pomaga zdobywać szaty wyrażające powołanie w służbie bogini."},ru={title="Laurna Morninglight",body="Laurna Morninglight обучает традициям Elune на территории Dolanaar. Она направляет новых жрецов и помогает им заработать одежду, выражающую их призвание в служении богине."},references={["npc:elune"]=true,["place:dolanaar"]=true}},
    ["person:layo-starstrike"] = {title="Layo Golpe Estelar",kind="Personaje",aliases={"Layo","Layo Golpe Estelar"},body="Layo Golpe Estelar es un agente del Círculo Cenarion en Silithus. Su posición en Sosiego del Valor lo vincula a la vigilancia de una región marcada por antiguas guerras y por nuevas señales de peligro.",aliasQuestIDs={},en={title="Layo Starstrike",aliases={"Layo","Layo Starstrike"},body="Layo Starstrike is a Cenarion Circle agent in Silithus. His position at Valor’s Rest connects him with watching a region marked by ancient wars and new signs of danger.",aliasQuestIDs={}},fr={title="Layo Starstrike",body="Layo Starstrike est un agent Cenarion Circle dans Silithus. Sa position à Valor's Rest le relie à regarder une région marquée par des guerres anciennes et de nouveaux signes de danger."},de={title="Layo Starstrike",body="Layo Starstrike ist ein Agent von Cenarion Circle in Silithus. Seine Position bei Valor 's Rest verbindet ihn mit der Beobachtung einer Region, die von alten Kriegen und neuen Zeichen der Gefahr gekennzeichnet ist."},pt={title="Layo Starstrike",body="Layo Starstrike é um agente Cenarion Circle em Silithus. Sua posição no Resto de Valor o conecta com a observação de uma região marcada por guerras antigas e novos sinais de perigo."},pl={title="Layo Starstrike",body="Layo Starstrike jest agentem Cenarion Circle w Silithus. Placówka w Valor’s Rest wiąże go z obserwacją regionu naznaczonego pradawnymi wojnami i nowymi oznakami niebezpieczeństwa."},ru={title="Layo Starstrike",body="Layo Starstrike - агент Cenarion Circle в Silithus. Его должность в \"Валлор\" связывает его с наблюдением за регионом, отмеченным древними войнами и новыми признаками опасности."},references={["organization:cenarion-circle"]=true,["place:silithus"]=true}},
    ["person:lelanai"] = {title="Lelanai",kind="Personaje",aliases={"Lelanai"},body="Lelanai se ocupa de los sables de monta en Darnassus. Ofrece felinos de distintos pelajes, incluidos ejemplares de rayas y manchas, que permiten a sus jinetes recorrer los caminos sobre los grandes depredadores de su tierra.",aliasQuestIDs={},en={title="Lelanai",aliases={"Lelanai"},body="Lelanai handles riding sabers in Darnassus. She offers cats with varied coats, including striped and spotted animals, enabling riders to travel on their homeland’s great predators.",aliasQuestIDs={}},fr={title="Lelanai",body="Lelanai poignées de conduite sabres en Darnassus. Elle offre des chats avec des manteaux variés, y compris des animaux rayés et tachetés, permettant aux cavaliers de voyager sur les grands prédateurs de leur patrie."},de={title="Lelanai",body="Lelanai hantiert mit reitenden Säbeln in Darnassus. Sie bietet Katzen mit unterschiedlichem Fell an, darunter gestreifte und gefleckte Tiere, was es den Reitern ermöglicht, auf den großen Raubtieren ihrer Heimat zu reisen."},pt={title="Lelanai",body="Lelanai lida montando sabres em Darnassus. Ela oferece gatos com casacos variados, incluindo animais listrados e manchados, permitindo que os pilotos viajem nos grandes predadores de sua terra natal."},pl={title="Lelanai",body="Lelanai zajmuje się kotami szablozębnymi do jazdy w Darnassus. Oferuje zwierzęta o rozmaitym umaszczeniu, w tym pręgowane i cętkowane, dzięki którym jeźdźcy podróżują na wielkich drapieżnikach swojej ojczyzny."},ru={title="Lelanai",body="Lelanai управляет ездой сабель в Darnassus. Она предлагает кошек с разнообразными шерсти, в том числе полосатые и пятнистые животные, позволяя гонщикам путешествовать на своей родине  большие хищники."},references={["place:darnassus"]=true}},
    ["person:lethtendris"] = {title="Lethtendris",kind="Personaje",aliases={"Lethtendris"},body="Lethtendris es una maga elfa de sangre refugiada en el Barrio Alabeo de La Masacre. Su adicción a la magia la ha llevado a crear una red para atrapar las energías del lugar, una práctica que amenaza el equilibrio de su entorno.",aliasQuestIDs={},en={title="Lethtendris",aliases={"Lethtendris"},body="Lethtendris is a blood elf mage sheltering in Dire Maul’s Warpwood Quarter. Her addiction to magic has driven her to create a web trapping the site’s energies, a practice threatening the balance around it.",aliasQuestIDs={}},fr={title="Lethtendris",body="Lethtendris est un mage elfe de sang abritant dans le quartier Dire Maul de Warpwood. Son addiction à la magie l’a poussée à créer une toile piégeant les énergies du site, une pratique menaçant l’équilibre autour d’elle."},de={title="Lethtendris",body="Lethtendris ist eine Blutelfen-Magierin, die in Dire Mauls Warpwood Quarter Schutz sucht. Ihre Sucht nach Magie hat sie dazu veranlasst, eine Webfalle für die Energien der Seite zu schaffen, eine Praxis zu schaffen, die das das Gleichgewicht um sie herum bedroht."},pt={title="Lethtendris",body="Lethtendris é um elfo de sangue que abriga no Dire Maul do Warpwood Quarter. Seu vício em magia a levou a criar uma teia prendendo as energias do site, uma prática que ameaça o equilíbrio em torno dele."},pl={title="Lethtendris",body="Lethtendris jest krwawą elfką i maginią, która znalazła schronienie w części Dire Maul zwanej Warpwood Quarter. Uzależnienie od magii skłoniło ją do stworzenia sieci chwytającej energię tego miejsca, co zagraża otaczającej je równowadze."},ru={title="Lethtendris",body="Lethtendris - маг-кровный эльф, который живет в квартале Dire Maul s Warpwood. Ее зависимость от магии заставила ее создать сеть, ловящую в ловушку энергии сайта, практика, угрожающая равновесию вокруг него."},references={["place:dire-maul"]=true}},
    ["person:lieutenant-paval-reethe"] = {title="Teniente Paval Reethe",kind="Personaje",aliases={"Reethe","Teniente Paval Reethe","teniente Paval Reethe"},body="El teniente Paval Reethe es un soldado relacionado con Theramore. Su insignia lleva el ancla de la ciudad, un símbolo que identifica su pertenencia a sus fuerzas.",aliasQuestIDs={},en={title="Lieutenant Paval Reethe",aliases={"Lieutenant Paval Reethe","Reethe"},body="Lieutenant Paval Reethe is a soldier associated with Theramore. His badge bears the city’s anchor, a symbol identifying his membership of its forces.",aliasQuestIDs={}},fr={title="Lieutenant Paval Reethe",body="Lieutenant Paval Reethe est un soldat associé à Theramore. Son insigne porte l’ancre de la ville, un symbole identifiant son appartenance à ses forces."},de={title="Lieutenant Paval Reethe",body="Lieutenant Paval Reethe ist ein mit Theramore verbundener Soldat. Sein Abzeichen trägt den Anker der Stadt, ein Symbol für seine Zugehörigkeit zu deren Streitkräften."},pt={title="Lieutenant Paval Reethe",body="Lieutenant Paval Reethe é um soldado associado ao Theramore. Seu distintivo traz a âncora da cidade, um símbolo que identifica sua participação em suas forças."},pl={title="Lieutenant Paval Reethe",body="Lieutenant Paval Reethe jest żołnierzem związanym z Theramore. Jego odznaka nosi miejską kotwicę, symbol określający przynależność do miejscowych sił."},ru={title="Lieutenant Paval Reethe",body="Lieutenant Paval Reethe - солдат, связанный с Theramore. На его значке - якорь города, символ, обозначающий его членство в войсках."},references={["place:theramore"]=true}},
    ["person:liladris-moonriver"] = {title="Liladris Rioluna",kind="Personaje",aliases={"Liladris","Liladris Rioluna"},body="Liladris Rioluna se encuentra en la Atalaya de Maestra, donde espera al viajero Kerlonian. Conoce la somnolencia que lo acompaña y se preocupa por su llegada a través de los caminos de Vallefresno.",aliasQuestIDs={},en={title="Liladris Moonriver",aliases={"Liladris","Liladris Moonriver"},body="Liladris Moonriver is found at Maestra’s Post, where she awaits the traveler Kerlonian. She knows his persistent drowsiness and is concerned for his journey along Ashenvale’s roads.",aliasQuestIDs={}},fr={title="Liladris Moonriver",body="Liladris Moonriver se trouve au Maestra’s Post, où elle attend le voyageur Kerlonian. Elle connaît sa somnolence persistante et est préoccupée par son voyage le long des routes de Ashenvale."},de={title="Liladris Moonriver",body="Liladris Moonriver wird bei Maestra 's Post gefunden, wo sie die Reisende Kerlonian erwartet. Sie kennt seine anhaltende Schläfrigkeit und sorgt sich um seine Reise auf Ashenvales Straßen."},pt={title="Liladris Moonriver",body="Liladris Moonriver é encontrado no Posto de Maestra, onde ela aguarda o viajante Kerlonian. Ela conhece sua sonolência persistente e está preocupada com sua jornada ao longo das estradas da Ashenvale."},pl={title="Liladris Moonriver",body="Liladris Moonriver przebywa na posterunku Maestra, czekając na podróżnego noszącego imię Kerlonian. Zna jego uporczywą senność i martwi się podróżą po drogach Ashenvale."},ru={title="Liladris Moonriver",body="Liladris Moonriver находится на посту Maestra, где она ждет путешественника Kerlonian. Она знает о его постоянной сонливости и беспокоится о его путешествии по дорогам Ashenvale."},references={["person:kerlonian-evershade"]=true,["place:ashenvale"]=true}},
    ["person:linken"] = {title="Linken",kind="Personaje",aliases={"Linken"},body="Linken es un viajero del Cráter de Un'Goro que ha perdido la memoria. Los objetos de su pasado y la ayuda de otros habitantes forman los pocos vínculos con una historia que no consigue recordar.",aliasQuestIDs={},en={title="Linken",aliases={"Linken"},body="Linken is a traveler in Un'Goro Crater who has lost his memory. Objects from his past and the help of other residents provide the few connections to a history he cannot recall.",aliasQuestIDs={}},fr={title="Linken",body="Linken est un voyageur en Un'Goro Crater qui a perdu la mémoire. Les objets de son passé et l'aide d'autres résidents fournissent les quelques liens avec une histoire dont il ne se souvient pas."},de={title="Linken",body="Linken ist ein Reisender in Un'Goro Crater, der sein Gedächtnis verloren hat. Objekte aus seiner Vergangenheit und die Hilfe anderer Bewohner stellen die wenigen Verbindungen zu einer Geschichte her, an die er sich nicht erinnern kann."},pt={title="Linken",body="Linken é um viajante em Un'Goro Crater que perdeu a memória. Objetos de seu passado e a ajuda de outros residentes fornecem as poucas conexões com uma história que ele não consegue lembrar."},pl={title="Linken",body="Linken jest podróżnikiem w Un'Goro Crater, który utracił pamięć. Przedmioty z przeszłości i pomoc innych mieszkańców stanowią nieliczne więzi z historią, której nie potrafi sobie przypomnieć."},ru={title="Linken",body="Linken - путешественник в Un'Goro Crater, который потерял память. Объекты из его прошлого и помощь других жителей обеспечивают немногие связи с историей, которую он не может вспомнить."},references={["place:ungoro-crater"]=true}},
    ["person:lohatu"] = {title="Loh'atu",kind="Personaje",aliases={"Loh'atu","Loh’atu"},body="Loh'atu se ocupa de los espíritus de los Altonato que permanecen ligados a Azshara. Su compromiso con las centinelas busca aliviar las consecuencias de una historia de poder arcano y corrupción.",aliasQuestIDs={},en={title="Loh'atu",aliases={"Loh'atu","Loh’atu"},body="Loh'atu concerns himself with the Highborne spirits still bound to Azshara. His pledge to the sentinels seeks to ease the consequences of a history of arcane power and corruption.",aliasQuestIDs={}},fr={title="Loh'atu",body="Loh'atu se préoccupe des esprits the Highborne toujours liés à Azshara. Son engagement envers les sentinelles cherche à atténuer les conséquences d’une histoire de pouvoir obscur et de corruption."},de={title="Loh'atu",body="Loh'atu kümmert sich um the Highborne Geister, die noch an Azshara gebunden sind. Sein Versprechen an die Wächter zielt darauf ab, die Folgen einer Geschichte obskurer Macht und Korruption zu mildern."},pt={title="Loh'atu",body="Loh'atu preocupa-se com os espíritos the Highborne ainda ligados ao Azshara. Seu compromisso com as sentinelas busca aliviar as consequências de uma história de poder arcano e corrupção."},pl={title="Loh'atu",body="Loh'atu troszczy się o duchy społeczności „the Highborne” nadal związane z regionem Azshara. Obietnica złożona strażniczkom służy łagodzeniu następstw historii mocy arkana i skażenia."},ru={title="Loh'atu",body="Loh'atu занимается the Highborne духами, которые все еще связаны с Azshara. Его приверженность sentinels стремится облегчить последствия истории тайной власти и порчи."},references={["organization:highborne"]=true,["organization:night-elf-sentinels"]=true,["place:azshara"]=true}},
    ["person:loramus-thalipedes"] = {title="Loramus Thalimedes",kind="Personaje",aliases={"Loramus","Loramus Thalimedes"},body="Loramus Thalimedes es un cazador de demonios de Azshara. Conoce la naturaleza de sus enemigos y los materiales de la región, y cuenta con manáfagos capaces de ayudar a localizar recursos mágicos.",aliasQuestIDs={},en={title="Loramus Thalipedes",aliases={"Loramus","Loramus Thalipedes"},body="Loramus Thalipedes is a demon hunter in Azshara. He knows the nature of his enemies and the region’s materials and has felhunters capable of helping locate magical resources.",aliasQuestIDs={}},fr={title="Loramus Thalipedes",body="Loramus Thalipedes est un chasseur de démons dans Azshara. Il connaît la nature de ses ennemis et les matériaux de la région et a des compagnons capables d'aider à localiser des ressources magiques."},de={title="Loramus Thalipedes",body="Loramus Thalipedes ist in Azshara ein Dämonenjäger. Er kennt das Wesen seiner Feinde und das Material der Region und verfügt über Felsjäger, die ihm helfen können, magische Ressourcen zu finden."},pt={title="Loramus Thalipedes",body="Loramus Thalipedes é um caçador de demônios em Azshara. Ele conhece a natureza de seus inimigos e os materiais da região e tem felhunters capazes de ajudar a localizar recursos mágicos."},pl={title="Loramus Thalipedes",body="Loramus Thalipedes jest łowcą demonów w regionie Azshara. Zna naturę przeciwników i miejscowe materiały oraz posiada felhuntery zdolne pomagać w odnajdywaniu magicznych zasobów."},ru={title="Loramus Thalipedes",body="Loramus Thalipedes - охотник за демонами в Azshara. Он знает природу своих врагов и материалы региона, и у него есть охотники, способные помочь найти магические ресурсы."},references={["place:azshara"]=true}},
    ["person:lorax"] = {title="Lorax",kind="Personaje",aliases={"Lorax"},body="Lorax es un sátiro de Cuna del Invierno que conoce los secretos de la forja demoníaca. Sus tratos vinculan la fabricación de objetos con energías malditas y con el precio que exige obtener ese conocimiento.",aliasQuestIDs={},en={title="Lorax",aliases={"Lorax"},body="Lorax is a Winterspring satyr who knows the secrets of demonic forging. His bargains connect making objects with cursed energies and the price demanded for obtaining that knowledge.",aliasQuestIDs={}},fr={title="Lorax",body="Lorax est un satyre Winterspring qui connaît les secrets de la forge démoniaque. Ses bonnes affaires relient la fabrication d’objets avec des énergies maudites et le prix demandé pour obtenir cette connaissance."},de={title="Lorax",body="Lorax ist ein Winterspring Satyr, der die Geheimnisse des dämonischen Schmiedens kennt. Seine Schnäppchen verbinden die Herstellung von Objekten mit verfluchten Energien und dem Preis, der für die für den Erwerb dieses Wissen verlangt werden."},pt={title="Lorax",body="Lorax é um sátiro Winterspring que conhece os segredos do forjamento demoníaco. Suas barganhas conectam fazer objetos com energias amaldiçoadas e o preço exigido para obter esse conhecimento."},pl={title="Lorax",body="Lorax jest satyrem Winterspring znającym tajniki demonicznego kucia. Jego układy łączą wytwarzanie przedmiotów z przeklętymi energiami i ceną żądaną za zdobycie tej wiedzy."},ru={title="Lorax",body="Lorax - это Winterspring сатир, который знает секреты демонической ковки. Его сделки связывают изготовление предметов с проклятой энергией и цену, требуемую за получение этого знания."},references={["place:winterspring"]=true}},
    ["person:lord-arkkoroc"] = {title="Lord Arkkoroc",kind="Personaje",aliases={"Arkkoroc","Lord Arkkoroc"},body="Lord Arkkoroc es una deidad menor de la costa de Azshara. Sus servidores protegen su territorio, y quienes buscan sus conocimientos deben acercarse con cautela a su templo.",aliasQuestIDs={},en={title="Lord Arkkoroc",aliases={"Arkkoroc","Lord Arkkoroc"},body="Lord Arkkoroc is a minor deity on Azshara’s coast. His servants protect his territory, and those seeking his knowledge must approach his temple with care.",aliasQuestIDs={}},fr={title="Lord Arkkoroc",body="Lord Arkkoroc est une divinité mineure sur la côte de Azshara. Ses serviteurs protègent son territoire, et ceux qui cherchent sa connaissance doivent approcher son temple avec soin."},de={title="Lord Arkkoroc",body="Lord Arkkoroc ist eine kleine Gottheit an der Küste von Azshara. Seine Diener schützen sein Territorium, und diejenigen, die sein Wissen suchen, müssen sich seinem Tempel mit Vorsicht nähern."},pt={title="Lord Arkkoroc",body="Lord Arkkoroc é uma divindade menor na costa de Azshara. Seus servos protegem seu território, e aqueles que buscam seu conhecimento devem se aproximar de seu templo com cuidado."},pl={title="Lord Arkkoroc",body="Lord Arkkoroc jest pomniejszym bóstwem na wybrzeżu regionu Azshara. Słudzy chronią jego terytorium, a osoby szukające jego wiedzy muszą ostrożnie zbliżać się do świątyni."},ru={title="Lord Arkkoroc",body="Lord Arkkoroc - второстепенное божество на побережье Azshara. Его служители охраняют его территорию, и те, кто ищет знания о нем, должны осторожно приближаться к его храму."},references={["place:azshara"]=true},questIDs={[3509]=true,[3510]=true,[3511]=true}},
    ["person:lord-azrethoc"] = {title="Lord Azrethoc",kind="Personaje",aliases={"Azrethoc","Lord Azrethoc"},body="Lord Azrethoc es un señor demoníaco que busca extender su influencia en Desolace. Sus relaciones con practicantes de magia oscura lo convierten en una amenaza para quienes vigilan el Filo Ardiente.",aliasQuestIDs={},en={title="Lord Azrethoc",aliases={"Azrethoc","Lord Azrethoc"},body="Lord Azrethoc is a demon lord seeking to extend his influence in Desolace. His relationships with practitioners of dark magic make him a threat to those watching the Burning Blade.",aliasQuestIDs={}},fr={title="Lord Azrethoc",body="Lord Azrethoc est un seigneur démon cherchant à étendre son influence dans Desolace. Ses relations avec les praticiens de la magie noire font de lui une menace pour ceux qui regardent le Burning Blade."},de={title="Lord Azrethoc",body="Lord Azrethoc ist ein Dämonenherr, der versucht, seinen Einfluss auf Desolace auszuweiten. Seine Beziehungen zu Praktizierenden der dunklen Magie machen ihn zu einer Bedrohung für diejenigen, die den Burning Blade beobachten."},pt={title="Lord Azrethoc",body="Lord Azrethoc é um senhor demônio que procura estender sua influência no Desolace. Suas relações com praticantes de magia negra fazem dele uma ameaça para aqueles que assistem ao Burning Blade."},pl={title="Lord Azrethoc",body="Lord Azrethoc jest władcą demonów próbującym rozszerzyć wpływy w Desolace. Relacje z adeptami mrocznej magii czynią go zagrożeniem dla osób obserwujących Burning Blade."},ru={title="Lord Azrethoc",body="Lord Azrethoc - это лорд демонов, стремящийся расширить свое влияние в Desolace. Его отношения с практикующими темную магию делают его угрозой для тех, кто следит за Burning Blade."},references={["organization:burning-blade"]=true,["place:desolace"]=true}},
    ["person:lord-banehollow"] = {title="Lord Pesadilla",kind="Personaje",aliases={"Lord Pesadilla"},body="Lord Pesadilla es un miembro del Consejo de la Sombra en Jaedenar. Tiene acceso a materiales de otros mundos, lo que atrae a brujos que buscan componentes difíciles de conseguir en Azeroth.",aliasQuestIDs={},en={title="Lord Banehollow",aliases={"Banehollow","Lord Banehollow"},body="Lord Banehollow is a member of the Shadow Council in Jaedenar. He has access to materials from other worlds, attracting warlocks seeking components that are difficult to obtain in Azeroth.",aliasQuestIDs={}},fr={title="Lord Banehollow",body="Lord Banehollow est membre de la Shadow Council dans Jaedenar. Il a accès à des matériaux d'autres mondes, attirant des démonistes à la recherche de composants difficiles à obtenir dans Azeroth."},de={title="Lord Banehollow",body="Lord Banehollow ist Mitglied des Shadow Council in Jaedenar. Er hat Zugang zu Materialien aus anderen Welten und zieht Hexenmeister an, die nach Bauteilen suchen, die bei Azeroth schwer zu beschaffen sind."},pt={title="Lord Banehollow",body="Lord Banehollow é um membro do Shadow Council em Jaedenar. Ele tem acesso a materiais de outros mundos, atraindo bruxos que buscam componentes que são difíceis de obter no Azeroth."},pl={title="Lord Banehollow",body="Lord Banehollow jest członkiem Shadow Council w Jaedenar. Ma dostęp do materiałów z innych światów, przyciągając czarnoksiężników szukających składników trudnych do zdobycia w Azeroth."},ru={title="Lord Banehollow",body="Lord Banehollow - это член Shadow Council в Jaedenar. Он имеет доступ к материалам из других миров, привлекая чернокнижников, ищущих компоненты, которые трудно получить в Azeroth."},references={["organization:shadow-council"]=true,["place:azeroth"]=true,["place:jaedenar"]=true}},
    ["person:lord-lakmaeran"] = {title="Lord Lakmaeran",kind="Personaje",aliases={"Lakmaeran","Lord Lakmaeran"},body="Lord Lakmaeran es una gran criatura asociada con los quimerok de la Isla del Terror, en Feralas. Su tamaño y su relación con aquellas bestias han atraído la atención de quienes buscan carnes extraordinarias para sus recetas.",aliasQuestIDs={},en={title="Lord Lakmaeran",aliases={"Lakmaeran","Lord Lakmaeran"},body="Lord Lakmaeran is a great creature associated with the chimaerok of the Isle of Dread in Feralas. His size and relationship with those beasts have drawn the attention of cooks seeking extraordinary meats.",aliasQuestIDs={}},fr={title="Lord Lakmaeran",body="Lord Lakmaeran est une grande créature associée au chimaerok du Isle of Dread dans Feralas. Sa taille et sa relation avec ces bêtes ont attiré l'attention des cuisiniers à la recherche de viandes extraordinaires."},de={title="Lord Lakmaeran",body="Lord Lakmaeran ist ein großartiges Geschöpf, das mit dem Chimaerok des Isle of Dread in Feralas in Verbindung gebracht wird. Seine Größe und seine Beziehung zu diesen Tieren haben die Aufmerksamkeit von Köchen auf sich auf der Suche nach außergewöhnlichem Fleisch gemacht."},pt={title="Lord Lakmaeran",body="Lord Lakmaeran é uma grande criatura associada com o quimaerok do Isle of Dread em Feralas. Seu tamanho e relacionamento com esses animais chamaram a atenção de cozinheiros que procuram carnes extraordinárias."},pl={title="Lord Lakmaeran",body="Lord Lakmaeran jest wielkim stworzeniem związanym z chimaerokami Isle of Dread w Feralas. Rozmiar i relacja z tymi bestiami zwróciły uwagę kucharzy szukających niezwykłego mięsa."},ru={title="Lord Lakmaeran",body="Lord Lakmaeran - это великое существо, связанное с химаэроком Isle of Dread в Feralas. Его размер и отношения с этими зверями привлекли внимание поваров, которые ищут необычное мясо."},references={["place:feralas"]=true}},
    ["person:lord-melenas"] = {title="Lord Melenas",kind="Personaje",aliases={"Lord Melenas","Melenas"},body="Lord Melenas es un sátiro de Roca Mácula, cerca de Dolanaar. Ha reunido guerreros grells y representa una presencia corruptora demasiado próxima a las comunidades de Teldrassil.",aliasQuestIDs={},en={title="Lord Melenas",aliases={"Lord Melenas","Melenas"},body="Lord Melenas is a satyr in Fel Rock near Dolanaar. He has gathered grell warriors and represents a corrupting presence uncomfortably close to Teldrassil’s communities.",aliasQuestIDs={}},fr={title="Lord Melenas",body="Lord Melenas est un satyre dans Fel Rock près de Dolanaar. Il a rassemblé des guerriers grell et représente une présence corruptrice inconfortablement proche des communautés de Teldrassil."},de={title="Lord Melenas",body="Lord Melenas ist ein Satyr in Fel Rock nahe Dolanaar. Er hat Grellkrieger um sich geschart und stellt eine verderbliche Präsenz dar, die den Gemeinschaften von Teldrassil beunruhigend nahe ist."},pt={title="Lord Melenas",body="Lord Melenas é um sátiro no Fel Rock perto de Dolanaar. Ele reuniu guerreiros grill e representa uma presença corruptora desconfortavelmente perto das comunidades de Teldrassil."},pl={title="Lord Melenas",body="Lord Melenas jest satyrem w Fel Rock przy Dolanaar. Zgromadził wojowników grell i stanowi skażoną obecność niepokojąco blisko społeczności Teldrassil."},ru={title="Lord Melenas",body="Lord Melenas — сатир, обитающий у скалы Fel возле Dolanaar. Он собрал воинов Греллов и представляет собой коррумпирующее присутствие, некомфортно близкое к общинам Teldrassil."},references={["place:dolanaar"]=true,["place:teldrassil"]=true}},
    ["person:lord-shalzaru"] = {title="Lord Shalzaru",kind="Personaje",aliases={"Lord Shalzaru","Shalzaru"},body="Lord Shalzaru pertenece a la realeza que dirige a los nagas de la Isla del Terror. Se le atribuye especial crueldad y supervisa excavaciones donde han aparecido reliquias que atraen la atención de sus adversarios.",aliasQuestIDs={},en={title="Lord Shalzaru",aliases={"Lord Shalzaru","Shalzaru"},body="Lord Shalzaru belongs to the royalty directing the naga on the Isle of Dread. Known for particular cruelty, he oversees excavations where relics have drawn his adversaries’ attention.",aliasQuestIDs={}},fr={title="Lord Shalzaru",body="Lord Shalzaru appartient à la royauté dirigeant le naga sur le Isle of Dread. Connu pour sa cruauté particulière, il supervise les fouilles où des reliques ont attiré l’attention de ses adversaires."},de={title="Lord Shalzaru",body="Lord Shalzaru gehört zu den Königen, die den Naga auf dem Isle of Dread dirigieren. Bekannt für seine besondere Graussichtslosigkeit, leitet er Ausgrabungen, bei denen Relikte die Aufmerksamkeit seiner Gegner auf sich gelenkt haben."},pt={title="Lord Shalzaru",body="Lord Shalzaru pertence à realeza que dirige a naga no Isle of Dread. Conhecido por particular crueldade, ele supervisiona escavações onde relíquias chamaram a atenção de seus adversários."},pl={title="Lord Shalzaru",body="Lord Shalzaru należy do królewskiego rodu kierującego nagami na Isle of Dread. Znany ze szczególnego okrucieństwa, nadzoruje wykopaliska, których relikty zwróciły uwagę przeciwników."},ru={title="Lord Shalzaru",body="Lord Shalzaru принадлежит королевской семье, которая управляет нагой на Isle of Dread. Известный своей жестокостью, он руководит раскопками, где реликвии привлекают внимание его противников."},references={}},
    ["person:lorekeeper-javon"] = {title="Tradicionalista Javon",kind="Personaje",aliases={"Javon","Tradicionalista Javon"},body="El tradicionalista Javon custodia libros del Athenaeum de La Masacre. Entre las obras que recibe figuran tratados sobre las enseñanzas de sacerdotes, chamanes y druidas, conservando conocimientos de distintas tradiciones espirituales.",aliasQuestIDs={},en={title="Lorekeeper Javon",aliases={"Javon","Lorekeeper Javon"},body="Lorekeeper Javon safeguards books belonging to Dire Maul’s Athenaeum. The works returned to his care include treatises on priestly, shamanic, and druidic teachings, preserving knowledge from different spiritual traditions.",aliasQuestIDs={}},fr={title="Lorekeeper Javon",body="Lorekeeper Javon protège les livres appartenant à Dire Maul Athenaeum. Les travaux retournés à ses soins comprennent des traités sur les enseignements sacerdotaux, chamaniques et druidiques, préservant la connaissance de différentes traditions spirituelles."},de={title="Lorekeeper Javon",body="Lorekeeper Javon bewahrt Bücher von Dire Maul 's Athenaeum auf. Die Werke, die ihm zurückgegeben wurden, umfassen Abhandlungen über priesterliche, schamanische und druidische Lehren und druide Lehren und bewahren Wissen aus verschiedenen spirituellen Traditionen."},pt={title="Lorekeeper Javon",body="O Lorekeeper Javon protege os livros pertencentes ao Dire Maul do Athenaeum. As obras devolvidas aos seus cuidados incluem tratados sobre ensinamentos sacerdotais, xamânicos e druídicos, preservando o conhecimento de diferentes tradições espirituais."},pl={title="Lorekeeper Javon",body="Lorekeeper Javon strzeże ksiąg należących do Athenaeum w Dire Maul. Zwracane mu dzieła obejmują traktaty o naukach kapłańskich, szamańskich i druidycznych, zachowując wiedzę różnych tradycji duchowych."},ru={title="Lorekeeper Javon",body="Lorekeeper Javon защищает книги, принадлежащие Dire Maul s Athenaeum. Среди работ, возвращенных ему, - трактаты о священнических, шаманских и друидских учениях, сохраняющие знания из различных духовных традиций."},references={["place:athenaeum"]=true,["place:dire-maul"]=true}},
    ["person:lorekeeper-kildrath"] = {title="Tradicionalista Kildrath",kind="Personaje",aliases={"Kildrath","Tradicionalista Kildrath"},body="El tradicionalista Kildrath conserva obras del Athenaeum de La Masacre. Los libros que recibe abarcan el sigilo, la defensa y las artes arcanas, conectando la biblioteca con el conocimiento de pícaros, guerreros y magos.",aliasQuestIDs={},en={title="Lorekeeper Kildrath",aliases={"Kildrath","Lorekeeper Kildrath"},body="Lorekeeper Kildrath preserves works belonging to Dire Maul’s Athenaeum. The books returned to him cover stealth, defense, and arcane arts, connecting the library with the knowledge of rogues, warriors, and mages.",aliasQuestIDs={}},fr={title="Lorekeeper Kildrath",body="Lorekeeper Kildrath conserve des ouvrages de l'Athenaeum de Dire Maul. Les livres qui lui sont rendus traitent de la furtivité, de la défense et des arts arcaniques, reliant la bibliothèque aux connaissances des voleurs, des guerriers et des mages."},de={title="Lorekeeper Kildrath",body="Lorekeeper Kildrath bewahrt Werke von Dire Maul 's Athenaeum auf. Die Bücher, die ihm zurückgegeben wurden, behandeln Tarnung, Verteidigung und geheimnisvolle Künste und verbinden die Bibliothek mit dem Wissen von Schurken, Kriegern und Magischem Wissen."},pt={title="Lorekeeper Kildrath",body="Lorekeeper Kildrath preserva obras pertencentes ao Dire Maul de Athenaeum. Os livros devolvidos a ele cobrem furtividade, defesa e artes arcanas, conectando a biblioteca com o conhecimento de bandidos, guerreiros e magos."},pl={title="Lorekeeper Kildrath",body="Lorekeeper Kildrath przechowuje dzieła należące do Athenaeum w Dire Maul. Zwracane mu księgi dotyczą skradania, obrony i sztuk tajemnych, łącząc bibliotekę z wiedzą łotrów, wojowników i magów."},ru={title="Lorekeeper Kildrath",body="Lorekeeper Kildrath сохраняет произведения, принадлежащие Dire Maul s Athenaeum. Книги, возвращенные ему, охватывают скрытность, оборону и тайные искусства, связывая библиотеку с знаниями о злодеях, воинах и магах."},references={["place:athenaeum"]=true,["place:dire-maul"]=true}},
    ["person:lorekeeper-lydros"] = {title="Tradicionalista Lydros",kind="Personaje",aliases={"Lydros","Tradicionalista Lydros","tradicionalista Lydros"},body="El tradicionalista Lydros conserva conocimientos en El Athenaeum de La Masacre. Su interés por catalogar las anomalías de Eldre'Thalas convive con un dominio de conjuros arcanos que puede transmitir a otros estudiosos.",aliasQuestIDs={},en={title="Lorekeeper Lydros",aliases={"Lorekeeper Lydros","Lydros"},body="Lorekeeper Lydros preserves knowledge in Dire Maul’s Athenaeum. His interest in cataloguing Eldre'Thalas’s anomalies accompanies a mastery of arcane spells that he can share with other scholars.",aliasQuestIDs={}},fr={title="Lorekeeper Lydros",body="Lorekeeper Lydros préserve le savoir dans l'Athenaeum de Dire Maul. Son intérêt pour le recensement des anomalies d'Eldre'Thalas s'accompagne d'une maîtrise des sorts arcaniques qu'il peut partager avec d'autres érudits."},de={title="Lorekeeper Lydros",body="Lorekeeper Lydros bewahrt sein Wissen in Dire Maul 's Athenaeum auf. Sein Interesse an der Katalogisierung der Anomalien von Eldre'Thalas geht einher mit einer Beherrschung geheimnisvoller Zaubersprüche, die er mit denen er mit anderen Wissenschaftlern teilen kann."},pt={title="Lorekeeper Lydros",body="Lorekeeper Lydros preserva o conhecimento no Dire Maul de Athenaeum. Seu interesse em catalogar as anomalias de Eldre'Thalas acompanha um domínio de feitiços arcanos que ele pode compartilhar com outros estudiosos."},pl={title="Lorekeeper Lydros",body="Lorekeeper Lydros przechowuje wiedzę w Athenaeum w Dire Maul. Zainteresowaniu katalogowaniem anomalii Eldre'Thalas towarzyszy opanowanie zaklęć arkana, którymi potrafi dzielić się z innymi uczonymi."},ru={title="Lorekeeper Lydros",body="Lorekeeper Lydros сохраняет знания в Dire Maul s Athenaeum. Его интерес к каталогизации аномалий Eldre'Thalas  сопровождает мастерство в загадочных заклинаниях, которыми он может поделиться с другими учеными."},references={["place:athenaeum"]=true,["place:dire-maul"]=true}},
    ["person:lorekeeper-mykos"] = {title="Tradicionalista Mykos",kind="Personaje",aliases={"Mykos","Tradicionalista Mykos"},body="El tradicionalista Mykos reúne libros del Athenaeum de La Masacre. Entre sus obras recuperadas hay textos destinados a paladines, brujos y cazadores, una colección que abarca tanto la Luz como las sombras y la caza.",aliasQuestIDs={},en={title="Lorekeeper Mykos",aliases={"Lorekeeper Mykos","Mykos"},body="Lorekeeper Mykos gathers books belonging to Dire Maul’s Athenaeum. Works returned to him include texts intended for paladins, warlocks, and hunters, a collection spanning the Light, shadows, and the hunt.",aliasQuestIDs={}},fr={title="Lorekeeper Mykos",body="Lorekeeper Mykos rassemble des livres appartenant à l'Athenaeum de Dire Maul. Les ouvrages qui lui sont rendus comprennent des textes destinés aux paladins, aux démonistes et aux chasseurs, une collection qui couvre «the Light», les ombres et la chasse."},de={title="Lorekeeper Mykos",body="Lorekeeper Mykos sammelt Bücher von Dire Maul 's Athenaeum. Zu seinen Werken gehören Texte für Paladine, Hexenmeister und Jäger, eine Sammlung über the Light, Schatten und die Jagd."},pt={title="Lorekeeper Mykos",body="Lorekeeper Mykos reúne livros pertencentes ao Dire Maul de Athenaeum. Os trabalhos devolvidos a ele incluem textos destinados a paladinos, bruxos e caçadores, uma coleção que abrange the Light, sombras e caça."},pl={title="Lorekeeper Mykos",body="Lorekeeper Mykos gromadzi księgi należące do Athenaeum w Dire Maul. Zwracane mu dzieła obejmują teksty dla paladynów, czarnoksiężników i łowców, tworząc zbiór poświęcony tematyce „the Light”, cienia i łowów."},ru={title="Lorekeeper Mykos",body="Lorekeeper Mykos собирает книги, принадлежащие Dire Maul s Athenaeum. Работы, возвращенные ему, включают тексты, предназначенные для паладинов, чернокнижников и охотников, коллекцию, охватывающую the Light, тени и охоту."},references={["concept:holy-light"]=true,["place:athenaeum"]=true,["place:dire-maul"]=true}},
    ["person:lorekeeper-raintotem"] = {title="Tradicionalista Tótem de Lluvia",kind="Personaje",aliases={"Tradicionalista Tótem de Lluvia","Tótem de Lluvia"},body="El tradicionalista Tótem de Lluvia vela por el respeto a Roca Roja, el cementerio sagrado de los tauren. Recuerda a los guerreros que fundaron y defendieron Cima del Trueno y busca impedir que los intrusos profanen su descanso.",aliasQuestIDs={},en={title="Lorekeeper Raintotem",aliases={"Lorekeeper Raintotem","Raintotem"},body="Lorekeeper Raintotem safeguards respect for Red Rocks, the tauren’s sacred burial ground. He remembers the warriors who founded and defended Thunder Bluff and seeks to stop intruders from desecrating their rest.",aliasQuestIDs={}},fr={title="Lorekeeper Raintotem",body="Lorekeeper Raintotem garantit le respect de Red Rocks, le lieu de sépulture sacré des taurens. Il se souvient des guerriers qui ont fondé et défendu Thunder Bluff et cherche à empêcher les intrus de profaner leur repos."},de={title="Lorekeeper Raintotem",body="Lorekeeper Raintotem bewahrt Respekt vor Red Rocks, dem heiligen Grab des Tauren. Er erinnert sich an die Krieger, die Thunder Bluff gegründet und verteidigt haben und versucht, Eindringlinge davon abzuhalten, ihre Ruhe zu schänden."},pt={title="Lorekeeper Raintotem",body="Lorekeeper Raintotem salvaguarda o respeito pelo Red Rocks, o cemitério sagrado do tauren. Ele se lembra dos guerreiros que fundaram e defenderam o Thunder Bluff e procura impedir que intrusos profanassem seu descanso."},pl={title="Lorekeeper Raintotem",body="Lorekeeper Raintotem strzeże szacunku dla Red Rocks, świętego cmentarzyska taurenów. Pamięta wojowników, którzy założyli i bronili Thunder Bluff, oraz próbuje powstrzymywać intruzów przed bezczeszczeniem ich spoczynku."},ru={title="Lorekeeper Raintotem",body="Lorekeeper Raintotem защищает уважение к Red Rocks, священному месту захоронения Таурен. Он помнит воинов, которые основали и защищали Thunder Bluff и пытается остановить злоумышленников от осквернения их отдыха."},references={["place:thunder-bluff"]=true}},
    ["person:lumak"] = {title="Lumak",kind="Personaje",aliases={"Lumak"},body="Lumak es un instructor de pesca que conoce a Nat Pagle. Reconoce cuándo sus alumnos han superado lo que puede enseñarles y los orienta hacia pescadores con otra experiencia.",aliasQuestIDs={},en={title="Lumak",aliases={"Lumak"},body="Lumak is a fishing instructor who knows Nat Pagle. He recognizes when students have learned all he can teach and directs them toward anglers with different experience.",aliasQuestIDs={}},fr={title="Lumak",body="Lumak est un instructeur de pêche qui connaît Nat Pagle. Il reconnaît quand les élèves ont appris tout ce qu’il peut enseigner et les oriente vers des pêcheurs ayant une expérience différente."},de={title="Lumak",body="Lumak ist Angellehrer und kennt Nat Pagle. Er erkennt, wenn die Schüler alles gelernt haben, was er ihnen beibringen kann, und weist sie auf Angler mit anderer Erfahrung hin."},pt={title="Lumak",body="Lumak é um instrutor de pesca que conhece Nat Pagle. Ele reconhece quando os alunos aprenderam tudo o que ele pode ensinar e os direciona para pescadores com experiência diferente."},pl={title="Lumak",body="Lumak jest nauczycielem wędkarstwa znającym postać Nat Pagle. Rozpoznaje chwilę, gdy uczniowie nauczyli się wszystkiego, co może im przekazać, i kieruje ich do wędkarzy o innym doświadczeniu."},ru={title="Lumak",body="Lumak - это инструктор по рыбалке, который знает Nat Pagle. Он распознает, когда ученики узнали все, чему может научить, и направляет их к рыбакам с другим опытом."},references={["person:nat-pagle"]=true}},
    ["person:lyreena-duskblade"] = {title="Lyreena Hoja Umbría",kind="Personaje",aliases={"Lyreena","Lyreena Hoja Umbría"},body="Lyreena Hoja Umbría es una aventurera que acampa cerca de Dolanaar. Comparte conocimientos para desenvolverse en la naturaleza y conserva en su diario recuerdos de viajes y campamentos.",aliasQuestIDs={},en={title="Lyreena Duskblade",aliases={"Lyreena","Lyreena Duskblade"},body="Lyreena Duskblade is an adventurer camped near Dolanaar. She shares knowledge of wilderness survival and records journeys and camping experiences in her journal.",aliasQuestIDs={}},fr={title="Lyreena Duskblade",body="Lyreena Duskblade est un aventurier campé près de Dolanaar. Elle partage ses connaissances sur la survie en milieu sauvage et enregistre les voyages et les expériences de camping dans son journal."},de={title="Lyreena Duskblade",body="Lyreena Duskblade ist eine Abenteurerin, die in der Nähe von Dolanaar zeltet. Sie teilt ihr Wissen über das Überleben in der Wildnis und hält Reisen und Zelten in ihrem Tagebuch fest."},pt={title="Lyreena Duskblade",body="Lyreena Duskblade é um aventureiro acampado perto de Dolanaar. Ela compartilha o conhecimento da sobrevivência do deserto e registra viagens e experiências de acampamento em seu diário."},pl={title="Lyreena Duskblade",body="Lyreena Duskblade jest poszukiwaczką przygód obozującą koło Dolanaar. Dzieli się wiedzą o przetrwaniu i zapisuje podróże oraz doświadczenia obozowe w dzienniku."},ru={title="Lyreena Duskblade",body="Lyreena Duskblade - это авантюрист, расположенный рядом с Dolanaar. Она делится знаниями о выживании в дикой природе и записывает в своем дневнике путешествия и опыт кемпинга."},references={["place:dolanaar"]=true}},
    ["person:mad-magglish"] = {title="Loco Magglish",kind="Personaje",aliases={"Loco Magglish","Magglish"},body="Loco Magglish merodea entre los cargamentos de Trinquete. Su robo de una botella de oporto de noventa y nueve años lo llevó hasta las Cuevas de los Lamentos, donde pocos trabajadores del puerto se atreverían a perseguirlo.",aliasQuestIDs={},en={title="Mad Magglish",aliases={"Mad Magglish","Magglish"},body="Mad Magglish prowls around Ratchet’s cargo shipments. Stealing a bottle of ninety-nine-year-old port took him to the Wailing Caverns, where few dockworkers would dare follow him.",aliasQuestIDs={}},fr={title="Mad Magglish",body="Mad Magglish rôde autour des expéditions de fret de Ratchet. Voler une bouteille d'un port de quatre-vingt-dix-neuf ans l'a emmené à la Wailing Caverns, où peu de dockers osaient le suivre."},de={title="Mad Magglish",body="Mad Magglish stöbert durch Ratchet \"Frachtladungen. Der Diebstahl einer Flasche des 99 Jahre alten Hafens brachte ihn zum Wailing Caverns, wo sich nur wenige Hafenarbeiter trauten, ihm zu folgen."},pt={title="Mad Magglish",body="Mad Magglish ronda os embarques de carga da Ratchet. Roubar uma garrafa de porto de noventa e nove anos de idade levou-o para o Wailing Caverns, onde poucos trabalhadores portuários ousaria segui-lo."},pl={title="Mad Magglish",body="Mad Magglish krąży przy ładunkach Ratchet. Kradzież butelki dziewięćdziesięciodziewięcioletniego porto zaprowadziła go do Wailing Caverns, gdzie niewielu robotników portowych ośmieliłoby się podążyć."},ru={title="Mad Magglish",body="Mad Magglish бродит вокруг грузовых грузов Ratchet. Кража бутылки девяносто девятилетнего порто привела его в Wailing Caverns, где мало кто из доководов осмелился бы следовать за ним."},references={["place:ratchet"]=true,["place:wailing-caverns"]=true}},
    ["person:magar"] = {title="Magar",kind="Personaje",aliases={"Magar"},body="Magar vive en la calle principal de Orgrimmar, al este del Circo de las Sombras. Su añoranza por Krilge representa un vínculo personal de amor y devoción en medio de la vida de la capital de la Horda.",aliasQuestIDs={},en={title="Magar",aliases={"Magar"},body="Magar lives along Orgrimmar’s main drag, east of the Cleft of Shadow. His longing for Krilge reflects a personal bond of love and devotion amid life in the Horde’s capital.",aliasQuestIDs={}},fr={title="Magar",body="Magar vit le long de la traînée principale de Orgrimmar, à l'est de la Cleft of Shadow. Son désir ardent pour Krilge reflète un lien personnel d'amour et de dévotion au milieu de la vie dans la capitale de la Horde."},de={title="Magar",body="Magar lebt an der Hauptstraße von Orgrimmar, östlich des Cleft of Shadow. Seine Sehnsucht nach Krilge zeigt ein persönliches Band der Liebe und Hingabe inmitten des Lebens in der Hauptstadt der Horde."},pt={title="Magar",body="Magar vive ao longo do arrasto principal de Orgrimmar, a leste do Cleft of Shadow. Seu desejo por Krilge reflete um vínculo pessoal de amor e devoção em meio à vida na capital do Horde."},pl={title="Magar",body="Magar mieszka przy głównej ulicy Orgrimmar, na wschód od Cleft of Shadow. Tęsknota za postacią Krilge odzwierciedla osobistą więź miłości i oddania pośród życia stolicy frakcji Horde."},ru={title="Magar",body="Magar живет вдоль Orgrimmar  главного сопротивления, к востоку от Cleft of Shadow. Его стремление к Krilge отражает личную связь любви и преданности среди жизни в столице Horde."},references={["organization:horde"]=true,["place:orgrimmar"]=true}},
    ["person:magatha-grimtotem"] = {title="Magatha Tótem Siniestro",kind="Personaje",aliases={"Magatha","Magatha Tótem Siniestro"},body="Magatha Tótem Siniestro es una de las ancianas de Cima del Trueno. Participa en asuntos espirituales y políticos de los tauren y manifiesta interés en la relación de su pueblo con los Renegados.",aliasQuestIDs={},en={title="Magatha Grimtotem",aliases={"Magatha","Magatha Grimtotem"},body="Magatha Grimtotem is one of Thunder Bluff’s elders. She takes part in tauren spiritual and political affairs and expresses interest in her people’s relationship with the Forsaken.",aliasQuestIDs={}},fr={title="Magatha Grimtotem",body="Magatha Grimtotem est l’un des aînés de Thunder Bluff. Elle prend part aux affaires spirituelles et politiques tauren et exprime son intérêt pour la relation de son peuple avec the Forsaken."},de={title="Magatha Grimtotem",body="Magatha Grimtotem ist eine von Thunder Bluffs Ältesten. Sie nimmt an spirituellen und politischen Angelegenheiten teil und zeigt Interesse an der Beziehung ihres Volkes zu the Forsaken."},pt={title="Magatha Grimtotem",body="Magatha Grimtotem é um dos mais velhos do Thunder Bluff. Ela participa de tauren assuntos espirituais e políticos e expressa interesse na relação de seu povo com the Forsaken."},pl={title="Magatha Grimtotem",body="Magatha Grimtotem należy do starszyzny Thunder Bluff. Uczestniczy w duchowych i politycznych sprawach taurenów oraz wyraża zainteresowanie relacjami swojego ludu ze społecznością „the Forsaken”."},ru={title="Magatha Grimtotem",body="Magatha Grimtotem - один из старейшин Thunder Bluff. Она участвует в духовных и политических делах Таурена и выражает интерес к отношениям своего народа с the Forsaken."},references={["organization:forsaken"]=true,["organization:grimtotem"]=true,["place:thunder-bluff"]=true}},
    ["person:magga"] = {title="Magga",kind="Personaje",aliases={"Magga"},body="Magga da la bienvenida a los nuevos viajeros del Valle de los Retos. Entre los obsequios que entrega hay pequeños compañeros, capaces de acompañar a quienes se disponen a iniciar una vida de aventuras.",aliasQuestIDs={},en={title="Magga",aliases={"Magga"},body="Magga welcomes new travelers in the Valley of Trials. The gifts offered include small companions for those preparing to begin a life of adventure.",aliasQuestIDs={}},fr={title="Magga",body="Magga accueille les nouveaux voyageurs dans le Valley of Trials. Les cadeaux offerts comprennent de petits compagnons pour ceux qui se préparent à commencer une vie d'aventure."},de={title="Magga",body="Magga begrüßt neue Reisende im Valley of Trials. Zu den Geschenken gehören kleine Begleiter für diejenigen, die sich auf ein abenteuerliches Leben vorbereiten."},pt={title="Magga",body="Magga recebe novos viajantes no Valley of Trials. Os presentes oferecidos incluem pequenos companheiros para aqueles que se preparam para começar uma vida de aventura."},pl={title="Magga",body="Magga wita nowych podróżnych w Valley of Trials. Wśród oferowanych darów są mali towarzysze dla osób przygotowujących się do rozpoczęcia życia pełnego przygód."},ru={title="Magga",body="Magga приветствует новых путешественников в Valley of Trials. В числе подарков - маленькие компаньоны для тех, кто готовится начать приключенческую жизнь."},references={["place:valley-of-trials"]=true}},
    ["person:maggran-earthbinder"] = {title="Maggran Vinculador terrestre",kind="Personaje",aliases={"Maggran","Maggran Vinculador terrestre"},body="Maggran Vinculador terrestre vive en el Refugio Roca del Sol. Conoce de cerca el peligro de Besseleth, que le causó una herida, y busca proteger a quienes recorren los bosques cercanos.",aliasQuestIDs={},en={title="Maggran Earthbinder",aliases={"Maggran","Maggran Earthbinder"},body="Maggran Earthbinder lives in Sun Rock Retreat. He knows Besseleth’s danger firsthand from a wound she inflicted and seeks to protect those traveling the nearby forests.",aliasQuestIDs={}},fr={title="Maggran Earthbinder",body="Maggran Earthbinder vit à Sun Rock Retreat. Il connaît le danger de Besseleth d'une blessure qu'elle a infligée et cherche à protéger ceux qui voyagent dans les forêts voisines."},de={title="Maggran Earthbinder",body="Maggran Earthbinder lebt in Sun Rock Retreat. Er kennt die Gefahr von Besseleth aus erster Hand aus einer Wunde, die sie ihm zugefügt hat, und versucht, diejenigen zu schützen, die in den nahe gelegenen Wältern unterwegs sind."},pt={title="Maggran Earthbinder",body="Maggran Earthbinder vive em Sun Rock Retreat. Ele conhece o perigo de Besseleth de uma ferida que ela infligiu e procura proteger aqueles que viajam pelas florestas próximas."},pl={title="Maggran Earthbinder",body="Maggran Earthbinder mieszka w Sun Rock Retreat. Zna niebezpieczeństwo bestii Besseleth z własnej rany zadanej przez nią i chce chronić podróżnych pobliskich lasów."},ru={title="Maggran Earthbinder",body="Maggran Earthbinder живет в Sun Rock Retreat. Он знает опасность Besseleth из первых рук из раны, которую она нанесла и стремится защитить тех, кто путешествует по близлежащим лесам."},references={["person:besseleth"]=true,["place:sun-rock-retreat"]=true}},
    ["person:magus-rimtori"] = {title="Maga Rimtori",kind="Personaje",aliases={"Maga Rimtori","Rimtori","maga Rimtori"},body="La maga Rimtori utiliza cristales y círculos de poder en Azshara. Sus prácticas arcanas han generado un conflicto con las fuerzas de la Horda que intentan descubrir el propósito de sus dispositivos.",aliasQuestIDs={},en={title="Magus Rimtori",aliases={"Magus Rimtori","Rimtori"},body="Magus Rimtori uses crystals and circles of power in Azshara. Her arcane practices have generated a conflict with Horde forces trying to discover the purpose of her devices.",aliasQuestIDs={}},fr={title="Magus Rimtori",body="Magus Rimtori utilise des cristaux et des cercles de pouvoir dans Azshara. Ses pratiques obscures ont généré un conflit avec les forces Horde qui tentent de découvrir le but de ses appareils."},de={title="Magus Rimtori",body="Magus Rimtori verwendet Kristalle und Kreise der Macht in Azshara. Ihre obskuren Praktiken haben einen Konflikt mit Hordes Kräften hervorgerufen, die versuchen, den Zweck ihrer Geräte zu entdecken."},pt={title="Magus Rimtori",body="Magus Rimtori usa cristais e círculos de poder em Azshara. Suas práticas arcanas geraram um conflito com as forças Horde tentando descobrir o propósito de seus dispositivos."},pl={title="Magus Rimtori",body="Magus Rimtori używa kryształów i kręgów mocy w regionie Azshara. Jej praktyki arkana wywołały konflikt z siłami frakcji Horde próbującymi odkryć przeznaczenie tych urządzeń."},ru={title="Magus Rimtori",body="Magus Rimtori использует кристаллы и круги силы в Azshara. Ее таинственные практики вызвали конфликт с силами Horde, пытающимися узнать цель ее устройств."},references={["organization:horde"]=true,["place:azshara"]=true}},
    ["person:magus-tirth"] = {title="Magus Tirth",kind="Personaje",aliases={"Magus Tirth","Tirth"},body="Magus Tirth conoce rituales relacionados con la creación de varitas. Sus problemas con el juego lo han obligado a desprenderse de libros de magia importantes, dificultando el uso de conocimientos que antes tenía a mano.",aliasQuestIDs={},en={title="Magus Tirth",aliases={"Magus Tirth","Tirth"},body="Magus Tirth knows rituals used in crafting wands. Gambling troubles have forced him to part with important magical books, complicating the use of knowledge he once had close at hand.",aliasQuestIDs={}},fr={title="Magus Tirth",body="Magus Tirth connaît les rituels utilisés dans la fabrication des baguettes. Les problèmes de jeu l'ont forcé à se séparer de livres magiques importants, compliquant l'utilisation des connaissances qu'il avait autrefois à portée de main."},de={title="Magus Tirth",body="Magus Tirth kennt Rituale beim Basteln von Zauberstäben. Glücksspielprobleme haben ihn gezwungen, sich von wichtigen magischen Büchern zu trennen, was die Nutzung des Wissens, das er einst in greifbarer Nähe erschwert."},pt={title="Magus Tirth",body="Magus Tirth conhece rituais usados na fabricação de varinhas. Problemas com jogos de azar o forçaram a se separar de importantes livros mágicos, complicando o uso do conhecimento que ele já teve por perto."},pl={title="Magus Tirth",body="Magus Tirth zna rytuały wykorzystywane w tworzeniu różdżek. Problemy z hazardem zmusiły go do rozstania z ważnymi magicznymi księgami, utrudniając korzystanie z wiedzy dawniej dostępnej pod ręką."},ru={title="Magus Tirth",body="Magus Tirth знает ритуалы, используемые в изготовлении палочек. Проблемы с азартными играми заставили его отказаться от важных книг о магии, что затруднило использование знаний, которые он когда-то имел под рукой."},references={}},
    ["person:mahren-skyseer"] = {title="Mahren Vidente del Cielo",kind="Personaje",aliases={"Mahren","Mahren Vidente del Cielo"},body="Mahren Vidente del Cielo es un guía tauren ligado a las tradiciones de la caza. Para él, enfrentarse a una gran criatura no consiste solo en vencerla, sino también en reconocer su fuerza y su espíritu.",aliasQuestIDs={},en={title="Mahren Skyseer",aliases={"Mahren","Mahren Skyseer"},body="Mahren Skyseer is a tauren guide associated with hunting traditions. To him, facing a great creature means more than defeating it: it also requires acknowledging its strength and spirit.",aliasQuestIDs={}},fr={title="Mahren Skyseer",body="Mahren Skyseer est un guide tauren associé aux traditions de chasse. Pour lui, faire face à une grande créature signifie plus que la vaincre: cela exige aussi de reconnaître sa force et son esprit."},de={title="Mahren Skyseer",body="Mahren Skyseer ist ein Tauren-Führer, der mit Jagdtradition verbunden ist. Sich einem großen Geschöpf zu stellen bedeutet für ihn mehr als es zu besiegen: Es erfordert auch, seine Stärke und seinen Geist anzuerkennen."},pt={title="Mahren Skyseer",body="Mahren Skyseer é um guia de tauren associado às tradições de caça. Para ele, enfrentar uma grande criatura significa mais do que derrotá-la: também requer reconhecer sua força e espírito."},pl={title="Mahren Skyseer",body="Mahren Skyseer jest taurenskim przewodnikiem związanym z tradycjami łowieckimi. Stawienie czoła wielkiemu stworzeniu oznacza dla niego więcej niż zwycięstwo: wymaga także uznania jego siły oraz ducha."},ru={title="Mahren Skyseer",body="Mahren Skyseer - это путеводитель быка, связанный с охотничьими традициями. Для него противостояние с великим созданием означает больше, чем победа над ним: это также требует признания его силы и духа."},references={}},
    ["person:maiah"] = {title="Mai'ah",kind="Personaje",aliases={"Mai'ah","Mai’ah"},body="Mai'ah es una instructora de magos del Valle de los Retos. Orienta a quienes comienzan a aprender magia entre los nuevos miembros de la Horda.",aliasQuestIDs={},en={title="Mai'ah",aliases={"Mai'ah","Mai’ah"},body="Mai'ah is a mage trainer in the Valley of Trials. She guides those beginning to study magic among the Horde’s new members.",aliasQuestIDs={}},fr={title="Mai'ah",body="Mai'ah est un entraîneur de mage dans le Valley of Trials. Elle guide ceux qui commencent à étudier la magie parmi les nouveaux membres de la Horde."},de={title="Mai'ah",body="Mai'ah ist Magiertrainerin im Valley of Trials. Sie leitet diejenigen, die beginnen, Magie unter den neuen Mitgliedern der Horde zu studieren."},pt={title="Mai'ah",body="Mai'ah é um treinador de magia no Valley of Trials. Ela orienta aqueles que começam a estudar magia entre os novos membros do Horde."},pl={title="Mai'ah",body="Mai'ah jest nauczycielką magów w Valley of Trials. Prowadzi osoby rozpoczynające naukę magii wśród nowych członków frakcji Horde."},ru={title="Mai'ah",body="Mai'ah - тренер магов в Valley of Trials. Она направляет тех, кто начинает изучать магию среди новых членов Horde."},references={["organization:horde"]=true,["place:valley-of-trials"]=true}},
    ["person:malah-longwind"] = {title="Malah Ventolongo",kind="Personaje",aliases={"Malah","Malah Ventolongo"},body="Malah Ventolongo es una zancalargo que explora las fronteras de Mulgore. Su cinta y su bastón con plumas identifican a una de las personas que mantienen informado al gran jefe sobre los peligros de las praderas.",aliasQuestIDs={},en={title="Malah Longwind",aliases={"Malah","Malah Longwind"},body="Malah Longwind is a Longwalker scouting Mulgore’s borders. Her headband and feathered staff identify one of the people keeping the high chieftain informed about dangers on the grasslands.",aliasQuestIDs={}},fr={title="Malah Longwind",body="Malah Longwind est une Longwalker qui surveille les frontières de Mulgore. Son bandeau et son bâton orné de plumes permettent de reconnaître l'une des personnes qui informent le grand chef des dangers des prairies."},de={title="Malah Longwind",body="Malah Longwind ist eine Longwalker, die die Grenzen von Mulgore erkundet. Ihr Stirnband und der mit Federn geschmückte Stab kennzeichnen sie als eine der Personen, die den obersten Häuptling über Gefahren im Grasland auf dem Laufenden halten."},pt={title="Malah Longwind",body="Malah Longwind é uma Longwalker que vigia as fronteiras de Mulgore. Sua faixa de cabeça e seu cajado enfeitado com penas identificam uma das pessoas que mantêm o grande chefe informado sobre os perigos das pradarias."},pl={title="Malah Longwind",body="Malah Longwind jest zwiadowczynią Longwalker obserwującą granice Mulgore. Opaska i kostur z piórami wyróżniają jedną z osób informujących najwyższego wodza o zagrożeniach na równinach."},ru={title="Malah Longwind",body="Malah Longwind - это Longwalker, разведка границ Mulgore s. Ее ленточка и пернатый посох идентифицируют одного из тех, кто держал верховного вождя в курсе опасностей на лугах."},references={["place:mulgore"]=true}},
    ["person:malduko-cloudcrush"] = {title="Malduko Rompenubes",kind="Personaje",aliases={"Malduko","Malduko Rompenubes"},body="Malduko Rompenubes dirige a un grupo de seguidores Al'Aketh instalado cerca de las ruinas de un templo, al suroeste de Arboleda Thendal. Sus subordinados amenazan a los viajeros y presionan a los habitantes para que se unan al culto. Su presencia convierte esa ruta en un peligro para quienes salen del poblado.",aliasQuestIDs={},en={title="Malduko Cloudcrush",aliases={"Malduko","Malduko Cloudcrush"},body="Malduko Cloudcrush leads a group of Al'Aketh followers near temple ruins southwest of Thendal Grove. His subordinates threaten travelers and pressure local people to join the cult. Their presence makes the route dangerous for those leaving the settlement.",aliasQuestIDs={}},fr={title="Malduko Cloudcrush",body="Malduko Cloudcrush mène un groupe d'adeptes Al'Aketh près des ruines du temple au sud-ouest de Thendal Grove. Ses subordonnés menacent les voyageurs et font pression sur la population locale pour qu’elle rejoigne le culte. Leur présence rend la route dangereuse pour ceux qui quittent la colonie."},de={title="Malduko Cloudcrush",body="Malduko Cloudcrush führt eine Gruppe von Al'Aketh-Anhängern in der Nähe von Tempelruinen südwestlich von Thendal Grove an. Seine Untergebenen drohen Reisenden und drängen die Einheimischen, sich dem Kult anzuschließen. Ihre Anwesenheit macht die Route für diejenigen, die die die Siedlung verlassen, gefährlich."},pt={title="Malduko Cloudcrush",body="Malduko Cloudcrush lidera um grupo de seguidores Al'Aketh perto de ruínas do templo a sudoeste de Thendal Grove. Seus subordinados ameaçam os viajantes e pressionam a população local a se juntar ao culto. Sua presença torna a rota perigosa para aqueles que deixam o assentamento."},pl={title="Malduko Cloudcrush",body="Malduko Cloudcrush przewodzi grupie wyznawców Al'Aketh przy ruinach świątyni na południowy zachód od Thendal Grove. Podwładni zagrażają podróżnym i naciskają na miejscowych, by dołączyli do kultu. Ich obecność czyni drogę niebezpieczną dla opuszczających osadę."},ru={title="Malduko Cloudcrush",body="Malduko Cloudcrush возглавляет группу последователей Al'Aketh возле руин храмов к юго-западу от Thendal Grove. Его подчиненные угрожают путешественникам и давили на местных жителей, чтобы они присоединились к культу. Их присутствие делает маршрут опасным для тех, кто покидает поселение."},references={["organization:al-aketh"]=true,["place:thendal-grove"]=true}},
    ["person:maliynn"] = {title="Maliynn",kind="Personaje",aliases={"Maliynn"},body="Maliynn vende alimentos y bebidas en Vallefresno. Su oferta de frutas, leche, agua y jugos abastece las necesidades cotidianas de quienes viven en el bosque o recorren sus caminos.",aliasQuestIDs={},en={title="Maliynn",aliases={"Maliynn"},body="Maliynn sells food and drink in Ashenvale. A stock of fruit, milk, water, and juices supplies the everyday needs of those living in the forest or traveling its roads.",aliasQuestIDs={}},fr={title="Maliynn",body="Maliynn vend de la nourriture et des boissons à Ashenvale. Un stock de fruits, de lait, d’eau et de jus de fruits répond aux besoins quotidiens de ceux qui vivent dans la forêt ou parcourent ses routes."},de={title="Maliynn",body="Maliynn verkauft in Ashenvale Essen und Trinken. Ein Vorrat an Obst, Milch, Wasser und Säften versorgt die Menschen, die im Wald leben oder auf ihren Straßen unterwegs sind, mit den täglichen Bedürfnissen."},pt={title="Maliynn",body="Maliynn vende alimentos e bebidas em Ashenvale. Um estoque de frutas, leite, água e sucos supre as necessidades diárias daqueles que vivem na floresta ou percorrem suas estradas."},pl={title="Maliynn",body="Maliynn sprzedaje jedzenie i napoje w Ashenvale. Zapasy owoców, mleka, wody i soków zaspokajają codzienne potrzeby mieszkańców lasu oraz podróżujących jego drogami."},ru={title="Maliynn",body="Maliynn продает еду и напитки в Ashenvale. Содержание фруктов, молока, воды и соков обеспечивает повседневные потребности тех, кто живет в лесу или путешествует по его дорогам."},references={["place:ashenvale"]=true}},
    ["person:malton-droffers"] = {title="Malton Droffers",kind="Personaje",aliases={"Malton","Malton Droffers"},body="Malton Droffers es hijo de Dran Droffers y participa en sus asuntos comerciales. Sus encargos lo relacionan con el transporte de mercancías y con los riesgos de obtener suministros en territorios lejanos.",aliasQuestIDs={},en={title="Malton Droffers",aliases={"Malton","Malton Droffers"},body="Malton Droffers is Dran Droffers’s son and takes part in his commercial affairs. His commissions connect him with transporting goods and the risks of obtaining supplies in distant territories.",aliasQuestIDs={}},fr={title="Malton Droffers",body="Malton Droffers est le fils de Dran Droffers et prend part à ses affaires commerciales. Ses commissions le relient au transport de marchandises et aux risques d’approvisionnement dans des territoires lointains."},de={title="Malton Droffers",body="Malton Droffers ist der Sohn von Dran Droffers und kümmert sich um seine kaufmännischen Angelegenheiten. Seine Aufträge verbinden ihn mit dem Transport von Waren und den Risiken der Beschaffung von Vorräten in fernen Territorien."},pt={title="Malton Droffers",body="Malton Droffers é filho de Dran Droffers e participa de seus assuntos comerciais. Suas comissões o conectam com o transporte de mercadorias e os riscos de obter suprimentos em territórios distantes."},pl={title="Malton Droffers",body="Malton Droffers jest synem postaci Dran Droffers i uczestniczy w jego sprawach handlowych. Zlecenia wiążą go z transportem towarów oraz ryzykiem zdobywania zapasów w odległych terytoriach."},ru={title="Malton Droffers",body="Malton Droffers - сын Dran Droffers  и участвует в его коммерческих делах. Его задания связывают его с транспортировкой товаров и рисками получения поставок на отдаленных территориях."},references={["person:dran-droffers"]=true}},
    ["person:malyfous-darkhammer"] = {title="Malyfous Martilloscuro",kind="Personaje",aliases={"Malyfous","Malyfous Martilloscuro"},body="Malyfous Martilloscuro es una especialista en la elaboración de equipo que estudia técnicas y componentes poco comunes. Su trabajo permite reconstruir métodos de fabricación a partir de muestras y materiales cuidadosamente elegidos.",aliasQuestIDs={},en={title="Malyfous Darkhammer",aliases={"Malyfous","Malyfous Darkhammer"},body="Malyfous Darkhammer is an equipment-making specialist who studies unusual techniques and components. Her work reconstructs crafting methods from samples and carefully chosen materials.",aliasQuestIDs={}},fr={title="Malyfous Darkhammer",body="Malyfous Darkhammer est un spécialiste de la fabrication d'équipements qui étudie des techniques et des composants inhabituels. Son travail reconstitue les méthodes de fabrication à partir d’échantillons et de matériaux soigneusement choisis."},de={title="Malyfous Darkhammer",body="Malyfous Darkhammer ist Spezialistin für Gerätebau und studiert ungewöhnliche Techniken und Komponenten. Ihre Arbeit rekonstruiert Herstellungsmethoden anhand von Mustern und sorgfältig ausgewählten Materialien."},pt={title="Malyfous Darkhammer",body="Malyfous Darkhammer é um especialista em fabricação de equipamentos que estuda técnicas e componentes incomuns. Seu trabalho reconstrói métodos de elaboração de amostras e materiais cuidadosamente escolhidos."},pl={title="Malyfous Darkhammer",body="Malyfous Darkhammer jest specjalistką w wytwarzaniu wyposażenia, badającą niezwykłe techniki i składniki. Odtwarza metody rzemieślnicze na podstawie próbek oraz starannie dobranych materiałów."},ru={title="Malyfous Darkhammer",body="Malyfous Darkhammer - специалист по производству оборудования, который изучает необычные методы и компоненты. Ее работа восстанавливает методы изготовления из образцов и тщательно отобранных материалов."},references={}},
    ["person:mangletooth"] = {title="Quebrantadientes",kind="Personaje",aliases={"Quebrantadientes"},body="Quebrantadientes es un jabaespín del Campamento Taurajo que conoce la magia de Agamaggan. Utiliza las esquirlas de sangre de Los Baldíos para conceder bendiciones relacionadas con ese poder.",aliasQuestIDs={},en={title="Mangletooth",aliases={"Mangletooth"},body="Mangletooth is a quilboar at Camp Taurajo who knows the magic of Agamaggan. He uses the Barrens’ blood shards to grant blessings associated with that power.",aliasQuestIDs={}},fr={title="Mangletooth",body="Mangletooth est un quilboar à Camp Taurajo qui connaît la magie de Agamaggan. Il utilise les éclats de sang de Barrens pour accorder des bénédictions associées à ce pouvoir."},de={title="Mangletooth",body="Mangletooth ist ein Quiltschwein bei Camp Taurajo, der die Magie von Agamaggan kennt. Er verwendet die Blutscherben des Barrens, um den mit dieser Macht verbundenen Segen zu erteilen."},pt={title="Mangletooth",body="Mangletooth é um quilboar no Camp Taurajo que conhece a magia do Agamaggan. Ele usa os fragmentos de sangue do Barrens para conceder bênçãos associadas a esse poder."},pl={title="Mangletooth",body="Mangletooth jest kolcozwierzem w Camp Taurajo znającym magię istoty Agamaggan. Wykorzystuje odłamki krwi z Barrens, by udzielać błogosławieństw związanych z tą mocą."},ru={title="Mangletooth",body="Mangletooth - это кульбар из Camp Taurajo, который знает магию Agamaggan. Он использует Barrens  blood shards, чтобы дарить благословения, связанные с этой силой."},references={["object:blood-shards"]=true,["person:agamaggan"]=true,["place:camp-taurajo"]=true,["place:the-barrens"]=true}},
    ["person:mankrik"] = {title="Mankrik",kind="Personaje",aliases={"Mankrik"},body="Mankrik es un orco de Los Baldíos cuya vida ha sido marcada por la violencia de los jabaespines. Su historia expresa el costo personal que la lucha por sobrevivir impone a las familias de la región.",aliasQuestIDs={},en={title="Mankrik",aliases={"Mankrik"},body="Mankrik is an orc in the Barrens whose life has been marked by quilboar violence. His story reflects the personal cost that the struggle for survival imposes on the region’s families.",aliasQuestIDs={}},fr={title="Mankrik",body="Mankrik est un orc de la Barrens dont la vie a été marquée par une violence quilboar. Son histoire reflète le coût personnel que la lutte pour la survie impose aux familles de la région."},de={title="Mankrik",body="Mankrik ist ein Ork im Barrens, dessen Leben von Quiltboar-Gewalt geprägt ist. Seine Geschichte spiegelt die persönlichen Kosten wider, die der Überlebenskampf den Familien der Region auferlegt."},pt={title="Mankrik",body="Mankrik é um orc no Barrens cuja vida foi marcada pela violência quilboar. Sua história reflete o custo pessoal que a luta pela sobrevivência impõe às famílias da região."},pl={title="Mankrik",body="Mankrik jest orkiem w regionie Barrens, którego życie naznaczyła przemoc kolcozwierzy. Jego historia ukazuje osobistą cenę, jaką rodziny tego regionu płacą za walkę o przetrwanie."},ru={title="Mankrik",body="Mankrik - это орк из Barrens, чья жизнь была отмечена насилием квилборов. Его история отражает личную цену, которую борьба за выживание накладывает на семьи региона."},references={["place:the-barrens"]=true}},
    ["person:mardant-strongoak"] = {title="Mardant Fuerterroble",kind="Personaje",aliases={"Mardant","Mardant Fuerterroble"},body="Mardant Fuerterroble es un instructor de druidas de Cañada Umbría. Sus alumnos dan con él los primeros pasos de una disciplina que vincula la formación personal con el mundo natural.",aliasQuestIDs={},en={title="Mardant Strongoak",aliases={"Mardant","Mardant Strongoak"},body="Mardant Strongoak is a druid trainer in Shadowglen. His students take their first steps in a discipline linking personal training with the natural world.",aliasQuestIDs={}},fr={title="Mardant Strongoak",body="Mardant Strongoak est un entraîneur de druide dans Shadowglen. Ses étudiants font leurs premiers pas dans une discipline liant l’entraînement personnel au monde naturel."},de={title="Mardant Strongoak",body="Mardant Strongoak ist Druidentrainer in Shadowglen. Seine Studenten beginnen ihre ersten Schritte in einer Disziplin, die persönliches Training mit der Natur verbindet."},pt={title="Mardant Strongoak",body="Mardant Strongoak é um treinador druida em Shadowglen. Seus alunos dão seus primeiros passos em uma disciplina que liga o treinamento pessoal com o mundo natural."},pl={title="Mardant Strongoak",body="Mardant Strongoak jest nauczycielem druidów w Shadowglen. Jego uczniowie stawiają pierwsze kroki w dyscyplinie łączącej osobiste szkolenie ze światem przyrody."},ru={title="Mardant Strongoak",body="Mardant Strongoak - тренер друидов в Shadowglen. Его ученики делают первые шаги в дисциплине, связывающей личную подготовку с миром природы."},references={["place:shadowglen"]=true}},
    ["person:marg-nighteye"] = {title="Marg Ojonocturno",kind="Personaje",aliases={"Marg","Marg Ojonocturno"},body="Marg Ojonocturno sirvió como agente orco destinado a vigilar Theramore. Sus informes mantenían al servicio de espionaje de la Horda en el Poblado Murohelecho al tanto de lo que ocurría en la ciudad humana.",aliasQuestIDs={},en={title="Marg Nighteye",aliases={"Marg","Marg Nighteye"},body="Marg Nighteye served as an orc agent posted to watch Theramore. His reports kept the Horde’s intelligence service in Brackenwall Village informed about events in the human city.",aliasQuestIDs={}},fr={title="Marg Nighteye",body="Marg Nighteye a servi comme agent orc chargé de surveiller Theramore. Ses rapports tenaient le service de renseignement de la Horde, à Brackenwall Village, informé des événements dans la ville humaine."},de={title="Marg Nighteye",body="Marg Nighteye war ein orkischer Agent, der zur Beobachtung von Theramore eingesetzt wurde. Seine Berichte hielten den Nachrichtendienst der Horde in Brackenwall Village über die Ereignisse in der Menschenstadt auf dem Laufenden."},pt={title="Marg Nighteye",body="Marg Nighteye serviu como um agente orc postado para assistir Theramore. Seus relatórios mantiveram o serviço de inteligência do Horde em Brackenwall Village informado sobre eventos na cidade humana."},pl={title="Marg Nighteye",body="Marg Nighteye służył jako orczy agent obserwujący Theramore. Jego raporty informowały wywiad Horde w Brackenwall Village o wydarzeniach w ludzkim mieście."},ru={title="Marg Nighteye",body="Marg Nighteye служил агентом орков, который наблюдал за Theramore. Его донесения позволяли разведке Horde в Brackenwall Village следить за событиями в людском городе."},references={["organization:horde"]=true,["place:brackenwall-village"]=true,["place:theramore"]=true}},
    ["person:margoz"] = {title="Margoz",kind="Personaje",aliases={"Margoz"},body="Margoz es un chamán que investiga objetos de poder encontrados en Durotar. Reconoce los límites de su propia disciplina y busca ayuda de otros practicantes para comprender la magia demoníaca.",aliasQuestIDs={},en={title="Margoz",aliases={"Margoz"},body="Margoz is a shaman investigating objects of power found in Durotar. He recognizes the limits of his own discipline and seeks other practitioners’ help to understand demonic magic.",aliasQuestIDs={}},fr={title="Margoz",body="Margoz est un chaman enquêtant sur des objets de pouvoir trouvés dans Durotar. Il reconnaît les limites de sa propre discipline et cherche l’aide d’autres pratiquants pour comprendre la magie démoniaque."},de={title="Margoz",body="Margoz ist ein Schamane, der Objekte der Macht untersucht, die in Durotar gefunden hat. Er erkennt die Grenzen seiner eigenen Disziplin und sucht die Hilfe anderer Praktiker, um dämonische Magie zu verstehen."},pt={title="Margoz",body="Margoz é um xamã que investiga objetos de poder encontrados no Durotar. Ele reconhece os limites de sua própria disciplina e busca a ajuda de outros praticantes para entender a magia demoníaca."},pl={title="Margoz",body="Margoz jest szamanem badającym przedmioty mocy znajdowane w Durotar. Rozpoznaje ograniczenia własnej dyscypliny i szuka pomocy innych adeptów, aby zrozumieć demoniczną magię."},ru={title="Margoz",body="Margoz - шаман, который исследует объекты силы, найденные в Durotar. Он осознает пределы своей собственной дисциплины и обращается к другим практикующим, чтобы получить помощь в понимании демонической магии."},references={["place:durotar"]=true}},
    ["person:marin-noggenfogger"] = {title="Marin Tragonublo",kind="Personaje",aliases={"Marin","Marin Tragonublo"},body="Marin Tragonublo es un habitante de Gadgetzan interesado en preparados alquímicos. Sus experimentos lo llevan a buscar ingredientes poco comunes y ayuda de otros especialistas de Tanaris.",aliasQuestIDs={},en={title="Marin Noggenfogger",aliases={"Marin","Marin Noggenfogger"},body="Marin Noggenfogger is a Gadgetzan resident interested in alchemical preparations. His experiments lead him to seek unusual ingredients and assistance from other specialists in Tanaris.",aliasQuestIDs={}},fr={title="Marin Noggenfogger",body="Marin Noggenfogger est un résident de Gadgetzan intéressé par les préparations alchimiques. Ses expériences l'amènent à rechercher des ingrédients inhabituels et l'aide d'autres spécialistes en Tanaris."},de={title="Marin Noggenfogger",body="Marin Noggenfogger ist ein Gadgetzan, der sich für alchemistische Präparate interessiert. Seine Experimente führen ihn dazu, ungewöhnliche Zutaten und Hilfe bei anderen Spezialisten in Tanaris zu suchen."},pt={title="Marin Noggenfogger",body="Marin Noggenfogger é um residente Gadgetzan interessado em preparações alquímicas. Seus experimentos o levaram a procurar ingredientes incomuns e assistência de outros especialistas em Tanaris."},pl={title="Marin Noggenfogger",body="Marin Noggenfogger jest mieszkańcem Gadgetzan zainteresowanym preparatami alchemicznymi. Eksperymenty skłaniają go do szukania niezwykłych składników i pomocy innych specjalistów z Tanaris."},ru={title="Marin Noggenfogger",body="Marin Noggenfogger - житель Gadgetzan, заинтересованный в алхимических препаратах. Его эксперименты привели его к поиску необычных ингредиентов и помощи других специалистов в Tanaris."},references={["place:gadgetzan"]=true,["place:tanaris"]=true}},
    ["person:marli-wishrunner"] = {title="Marli Corredeseos",kind="Personaje",aliases={"Marli","Marli Corredeseos"},body="Marli Corredeseos puede enviar visitantes a lo alto de uno de Los Dos Colosos de Feralas. Su magia ofrece una vista extraordinaria, pero solo cubre el ascenso: descender queda en manos del viajero.",aliasQuestIDs={},en={title="Marli Wishrunner",aliases={"Marli","Marli Wishrunner"},body="Marli Wishrunner can send visitors to the top of one of Feralas’s Twin Colossals. Her magic offers an extraordinary view but covers only the ascent, leaving travelers to arrange their own descent.",aliasQuestIDs={}},fr={title="Marli Wishrunner",body="Marli Wishrunner peut envoyer les visiteurs vers le haut de l’un des Twin Colossals de Feralas. Sa magie offre une vue extraordinaire mais ne couvre que l'ascension, laissant les voyageurs organiser leur propre descente."},de={title="Marli Wishrunner",body="Marli Wishrunner kann Besucher an die Spitze einer von Feralass Twin Colossals schicken. Ihre Magie bietet eine außergewöhnliche Aussicht, deckt aber nur den Aufstieg ab, so dass die Reisenden ihre eigene Abfahrt organisieren können."},pt={title="Marli Wishrunner",body="Marli Wishrunner pode enviar visitantes para o topo de um dos Feralas Twin Colossals. Sua magia oferece uma visão extraordinária, mas cobre apenas a subida, deixando os viajantes para organizar sua própria descida."},pl={title="Marli Wishrunner",body="Marli Wishrunner potrafi wysyłać przybyszów na szczyt jednego z Twin Colossals w Feralas. Magia oferuje niezwykły widok, lecz obejmuje tylko wejście, pozostawiając podróżnym zorganizowanie zejścia."},ru={title="Marli Wishrunner",body="Marli Wishrunner может отправить посетителей на вершину одного из Feralas s Twin Colossals. Ее магия предлагает необычайный вид, но охватывает только подъем, оставляя путешественникам самостоятельно организовать спуск."},references={["place:feralas"]=true}},
    ["person:marshal-bluewall"] = {title="Alguacil Murazul",kind="Personaje",aliases={"Alguacil Murazul","alguacil Murazul"},body="El alguacil Murazul recibe refuerzos de la Alianza destinados a la lucha en el desierto. Su mando depende de mantener suficientes soldados frente a una Horda que también abastece y refuerza sus posiciones.",aliasQuestIDs={},en={title="Marshal Bluewall",aliases={"Bluewall","Marshal Bluewall"},body="Marshal Bluewall receives Alliance reinforcements for the struggle in the desert. His command depends on maintaining enough soldiers against a Horde that also supplies and reinforces its positions.",aliasQuestIDs={}},fr={title="Marshal Bluewall",body="Marshal Bluewall reçoit des renforts Alliance pour la lutte dans le désert. Son commandement dépend du maintien d'un nombre suffisant de soldats contre un Horde qui fournit et renforce également ses positions."},de={title="Marshal Bluewall",body="Marshal Bluewall empfängt Verstärkung der Alliance für den Kampf in der Wüste. Seine Führung ist darauf angewiesen, genügend Soldaten gegen eine Horde aufzubieten, die ihre Stellungen ebenfalls versorgt und verstärkt."},pt={title="Marshal Bluewall",body="Marshal Bluewall recebe reforços Alliance para a luta no deserto. Seu comando depende da manutenção de soldados suficientes contra um Horde que também fornece e reforça suas posições."},pl={title="Marshal Bluewall",body="Marshal Bluewall przyjmuje posiłki frakcji Alliance do walki na pustyni. Jego dowództwo zależy od utrzymywania dostatecznej liczby żołnierzy przeciw Horde, która także zaopatruje i wzmacnia własne pozycje."},ru={title="Marshal Bluewall",body="Marshal Bluewall получает Alliance подкрепления для борьбы в пустыне. Его командование зависит от поддержания достаточного количества солдат против Horde, который также снабжает и укрепляет его позиции."},references={["organization:alliance"]=true,["organization:horde"]=true}},
    ["person:marvon-rivetseeker"] = {title="Marvon Buscarroblones",kind="Personaje",aliases={"Marvon","Marvon Buscarroblones"},body="Marvon Buscarroblones es un estudioso e inventor con un taller en Trinquete. Sus contactos lo buscan tanto por sus conocimientos técnicos como por su interés en restos y mecanismos antiguos.",aliasQuestIDs={},en={title="Marvon Rivetseeker",aliases={"Marvon","Marvon Rivetseeker"},body="Marvon Rivetseeker is a scholar and inventor with a workshop in Ratchet. His contacts seek him out for both his technical knowledge and his interest in ancient remains and mechanisms.",aliasQuestIDs={}},fr={title="Marvon Rivetseeker",body="Marvon Rivetseeker est un chercheur et inventeur avec un atelier dans Ratchet. Ses contacts le recherchent à la fois pour ses connaissances techniques et son intérêt pour les vestiges et les mécanismes anciens."},de={title="Marvon Rivetseeker",body="Marvon Rivetseeker ist Wissenschaftler und Erfinder mit einer Werkstatt in Ratchet. Seine Kontakte suchen ihn sowohl wegen seines technischen Wissens als auch wegen seines Interesses an antiken Überresten und Mechanismen."},pt={title="Marvon Rivetseeker",body="Marvon Rivetseeker é um estudioso e inventor com uma oficina em Ratchet. Seus contatos o procuram tanto por seu conhecimento técnico quanto por seu interesse em restos e mecanismos antigos."},pl={title="Marvon Rivetseeker",body="Marvon Rivetseeker jest uczonym i wynalazcą prowadzącym warsztat w Ratchet. Znajomi szukają jego pomocy zarówno ze względu na wiedzę techniczną, jak i zainteresowanie pradawnymi pozostałościami oraz mechanizmami."},ru={title="Marvon Rivetseeker",body="Marvon Rivetseeker - ученый и изобретатель с мастерской в Ratchet. Его контакты ищут его как за технические знания, так и за интерес к древним останкам и механизмам."},references={["place:ratchet"]=true}},
    ["person:maseara-autumnmoon"] = {title="Maseara Lunaotoño",kind="Personaje",aliases={"Maseara","Maseara Lunaotoño"},body="Maseara Lunaotoño vive en Canción del Bosque y está unida a Kurothel por un vínculo que siente incluso en la distancia. Los ataques de los sátiros al bosque han separado a la pareja y la mantienen pendiente de noticias sobre él.",aliasQuestIDs={},en={title="Maseara Autumnmoon",aliases={"Maseara","Maseara Autumnmoon"},body="Maseara Autumnmoon lives in Forest Song and shares a bond with Kurothel that she feels even at a distance. Satyr attacks on the forest have separated the pair and left her waiting for news of him.",aliasQuestIDs={}},fr={title="Maseara Autumnmoon",body="Maseara Autumnmoon vit à Forest Song et partage une obligation avec Kurothel qu'elle se sent même à distance. Les attaques de satyres sur la forêt ont séparé la paire et l'ont laissée attendre des nouvelles de lui."},de={title="Maseara Autumnmoon",body="Maseara Autumnmoon lebt in Forest Song und teilt eine Bindung mit Kurothel, die sie auch aus der Ferne spürt. Satyrs Angriffe auf den Wald haben das Paar getrennt und sie auf Nachrichten von ihm warten lassen."},pt={title="Maseara Autumnmoon",body="Maseara Autumnmoon vive em Forest Song e compartilha um vínculo com Kurothel que ela sente mesmo à distância. Os ataques de Satyr na floresta separaram o par e a deixaram esperando notícias dele."},pl={title="Maseara Autumnmoon",body="Maseara Autumnmoon mieszka w Forest Song i dzieli z postacią Kurothel więź odczuwaną nawet na odległość. Ataki satyrów na las rozdzieliły parę i pozostawiły ją w oczekiwaniu na wieści o nim."},ru={title="Maseara Autumnmoon",body="Maseara Autumnmoon живет в Forest Song и разделяет связь с Kurothel, которую она чувствует даже на расстоянии. Атаки сатириков на лес разлучили пару и оставили ее ждать от него новостей."},references={["person:kurothel"]=true,["place:forest-song"]=true}},
    ["person:master-gadrin"] = {title="Maestro Gadrin",kind="Personaje",aliases={"Gadrin","Maestro Gadrin"},body="El Maestro Gadrin es un guía del Poblado Sen'jin vinculado a las tradiciones espirituales de los Lanza Negra. Concede gran importancia a los loa y a los ídolos mediante los cuales su tribu mantiene la relación con ellos.",aliasQuestIDs={},en={title="Master Gadrin",aliases={"Gadrin","Master Gadrin"},body="Master Gadrin is a guide in Sen'jin Village associated with Darkspear spiritual traditions. He places great importance on the loa and the idols through which his tribe maintains its relationship with them.",aliasQuestIDs={}},fr={title="Master Gadrin",body="Master Gadrin est un guide en Sen'jin Village associé aux traditions spirituelles Darkspear. Il accorde une grande importance au loa et aux idoles à travers lesquels sa tribu maintient ses relations avec eux."},de={title="Master Gadrin",body="Master Gadrin ist ein Führer in Sen'jin Village, der mit Darkspear spirituellen Traditionen verbunden ist. Er legt großen Wert auf die Loa und die Götzen, durch die sein Stamm seine Beziehung zu ihnen unterhält."},pt={title="Master Gadrin",body="Master Gadrin é um guia no Sen'jin Village associado às tradições espirituais do Darkspear. Ele dá grande importância ao loa e aos ídolos através dos quais sua tribo mantém sua relação com eles."},pl={title="Master Gadrin",body="Master Gadrin jest przewodnikiem w Sen'jin Village związanym z duchowymi tradycjami plemienia Darkspear. Przywiązuje wielką wagę do loa i bożków, dzięki którym jego plemię utrzymuje z nimi więź."},ru={title="Master Gadrin",body="Master Gadrin - это руководство по Sen'jin Village, связанное с духовными традициями Darkspear. Он придает большое значение лоа и идолам, через которые его племя поддерживает отношения с ними."},references={["organization:darkspear-tribe"]=true,["place:senjin-village"]=true}},
    ["person:master-vornal"] = {title="Maestro Vornal",kind="Personaje",aliases={"Maestro Vornal","Vornal"},body="El maestro Vornal recurre a la alquimia para sostener las capacidades mágicas que la edad ha debilitado. Es exigente con los posibles aprendices y trabaja con ingredientes de las criaturas costeras de Durotar.",aliasQuestIDs={},en={title="Master Vornal",aliases={"Master Vornal","Vornal"},body="Master Vornal turns to alchemy to sustain magical abilities weakened by age. He is demanding of prospective apprentices and works with ingredients from Durotar’s coastal creatures.",aliasQuestIDs={}},fr={title="Master Vornal",body="Master Vornal se tourne vers l'alchimie pour soutenir les capacités magiques affaiblies par l'âge. Il exige des apprentis potentiels et travaille avec les ingrédients des créatures côtières de Durotar."},de={title="Master Vornal",body="Master Vornal wendet sich der Alchemie zu, um seine altersgeschwächten magischen Fähigkeiten aufrechtzuerhalten. Er verlangt den angehenden Lehrlingen alles ab und arbeitet mit Zutaten von Durotar 's Küstenwesen."},pt={title="Master Vornal",body="Master Vornal se volta para a alquimia para sustentar habilidades mágicas enfraquecidas pela idade. Ele está exigindo de futuros aprendizes e trabalha com ingredientes das criaturas costeiras do Durotar."},pl={title="Master Vornal",body="Master Vornal zwraca się ku alchemii, aby podtrzymywać magiczne zdolności osłabione wiekiem. Jest wymagający wobec przyszłych uczniów i pracuje ze składnikami stworzeń wybrzeża Durotar."},ru={title="Master Vornal",body="Master Vornal обращается к алхимии, чтобы поддерживать магические способности ослабленные возрастом. Он требовательный к будущим ученикам и работает с ингредиентами из прибрежных существ Durotar."},references={["place:durotar"]=true}},
    ["person:mastok-wrilehiss"] = {title="Mastok Bufido",kind="Personaje",aliases={"Mastok","Mastok Bufido"},body="Mastok Bufido actúa en el Puesto del Hachazo y presta atención a lo que ocurre en el Lago Mystral. Sus encargos ponen a los viajeros en contacto con las aguas contaminadas y los elementales afectados por ellas.",aliasQuestIDs={},en={title="Mastok Wrilehiss",aliases={"Mastok","Mastok Wrilehiss"},body="Mastok Wrilehiss operates at Splintertree Post and watches events at Mystral Lake. His assignments bring travelers into contact with polluted water and the elementals affected by it.",aliasQuestIDs={}},fr={title="Mastok Wrilehiss",body="Mastok Wrilehiss opère à Splintertree Post et regarde les événements au lac Mystral. Ses missions mettent les voyageurs en contact avec l’eau polluée et les élémentaux affectés par celle-ci."},de={title="Mastok Wrilehiss",body="Mastok Wrilehiss arbeitet bei Splintertree Post und schaut sich Veranstaltungen am Mystral Lake an. Seine Aufgaben bringen Reisende mit verschmutztem Wasser und den davon betroffenen Elementaren in Kontakt."},pt={title="Mastok Wrilehiss",body="Mastok Wrilehiss opera na Splintertree Post e assiste a eventos no Lago Mystral. Suas atribuições trazem os viajantes em contato com a água poluída e os elementais afetados por ela."},pl={title="Mastok Wrilehiss",body="Mastok Wrilehiss działa w Splintertree Post i obserwuje wydarzenia przy jeziorze Mystral. Jego zadania prowadzą podróżnych do zanieczyszczonej wody i dotkniętych nią żywiołaków."},ru={title="Mastok Wrilehiss",body="Mastok Wrilehiss работает в Splintertree Post и следит за событиями в Mystral Lake. Его задания приводят путешественников в контакт с загрязненной водой и элементальными телами, которые подвержены ей."},references={["place:splintertree-post"]=true}},
    ["person:mathiel"] = {title="Mathiel",kind="Personaje",aliases={"Mathiel"},body="Mathiel es un herrero de Darnassus que trabaja con elunita. Su oficio da forma a armas vinculadas a los recursos y tradiciones de los elfos de la noche.",aliasQuestIDs={},en={title="Mathiel",aliases={"Mathiel"},body="Mathiel is a Darnassus blacksmith who works with elunite. His craft gives shape to weapons connected with night elf resources and traditions.",aliasQuestIDs={}},fr={title="Mathiel",body="Mathiel est un forgeron Darnassus qui travaille avec elunite. Son métier donne forme à des armes liées aux ressources et aux traditions des elfes de la nuit."},de={title="Mathiel",body="Mathiel ist ein Schmied von Darnassus, der mit elunite arbeitet. Sein Handwerk gibt Waffen Gestalt, die mit den Ressourcen und Traditionen der Nachtelfen verbunden sind."},pt={title="Mathiel",body="Mathiel é um ferreiro Darnassus que trabalha com elunite. Seu ofício dá forma a armas conectadas com recursos e tradições de elfo noturno."},pl={title="Mathiel",body="Mathiel jest kowalem w Darnassus pracującym z elunitem. Jego rzemiosło nadaje kształt broni związanej z zasobami i tradycjami nocnych elfów."},ru={title="Mathiel",body="Mathiel - это Darnassus кузнец, который работает с элунитом. Его ремесло придает форму оружию, связанному с ресурсами и традициями ночных эльфов."},references={["object:elunite"]=true,["place:darnassus"]=true}},
    ["person:mathrengyl-bearwalker"] = {title="Mathrengyl Garroso",kind="Personaje",aliases={"Mathrengyl","Mathrengyl Garroso"},body="Mathrengyl Garroso es un druida del Enclave Cenarion de Darnassus y ayudante del archidruida. Su experiencia y su papel como instructor lo convierten en una referencia para quienes avanzan en la disciplina druídica.",aliasQuestIDs={},en={title="Mathrengyl Bearwalker",aliases={"Mathrengyl","Mathrengyl Bearwalker"},body="Mathrengyl Bearwalker is a druid in Darnassus’s Cenarion Enclave and an assistant to the archdruid. His experience and role as a teacher make him a guide for those advancing in druidic practice.",aliasQuestIDs={}},fr={title="Mathrengyl Bearwalker",body="Mathrengyl Bearwalker est un druide dans Darnassus’s Cenarion Enclave et un assistant de l’archidruide. Son expérience et son rôle d’enseignant font de lui un guide pour ceux qui avancent dans la pratique druidique."},de={title="Mathrengyl Bearwalker",body="Mathrengyl Bearwalker ist Druide in Darnassus 's Cenarion Enclave und Assistent des Erzdruiden. Seine Erfahrung und seine Rolle als Lehrer machen ihn zu einem Führer für diejenigen, die in der druidischen Praxis voranschreiten."},pt={title="Mathrengyl Bearwalker",body="Mathrengyl Bearwalker é um druida no Darnassus de Cenarion Enclave e um assistente do arque-druida. Sua experiência e papel como professor fazem dele um guia para aqueles que avançam na prática druídica."},pl={title="Mathrengyl Bearwalker",body="Mathrengyl Bearwalker jest druidem w Cenarion Enclave w mieście Darnassus i pomocnikiem arcydruida. Doświadczenie oraz rola nauczyciela czynią go przewodnikiem osób doskonalących praktyki druidyczne."},ru={title="Mathrengyl Bearwalker",body="Mathrengyl Bearwalker - друид в Darnassus s Cenarion Enclave и помощник архдруида. Его опыт и роль учителя делают его наставником для тех, кто продвигается в друидской практике."},references={["place:darnassus"]=true}},
    ["person:maur-raincaller"] = {title="Maur Clamalluvias",kind="Personaje",aliases={"Maur","Maur Clamalluvias"},body="Maur conoce los peligros de las bestias de Mulgore a través de su propia experiencia y de los relatos de su abuelo. También sabe combinar distintos ingredientes animales para tratar la infección de una mordedura venenosa.",aliasQuestIDs={},en={title="Maur Raincaller",aliases={"Maur","Maur Raincaller"},body="Maur knows Mulgore’s dangerous beasts through personal experience and his grandfather’s stories. He also knows how to combine different animal ingredients to treat infection from a venomous bite.",aliasQuestIDs={}},fr={title="Maur Raincaller",body="Maur connaît les bêtes dangereuses de Mulgore à travers son expérience personnelle et les histoires de son grand-père. Il sait également comment combiner différents ingrédients animaux pour traiter l'infection d'une morsure venimeuse."},de={title="Maur Raincaller",body="Maur kennt die gefährlichen Tiere von Mulgore aus eigener Erfahrung und aus den Geschichten seines Großväterlichs. Er weiß auch, wie man verschiedene tierische Inhaltsstoffe kombiniert, um Infektionen durch einen Giftbiss zu behandeln."},pt={title="Maur Raincaller",body="Maur conhece os animais perigosos do Mulgore através da experiência pessoal e das histórias de seu avô. Ele também sabe como combinar diferentes ingredientes animais para tratar a infecção de uma mordida venenosa."},pl={title="Maur Raincaller",body="Maur zna niebezpieczne bestie Mulgore z własnych doświadczeń i opowieści dziadka. Potrafi także łączyć różne składniki zwierzęce, by leczyć zakażenie po jadowitym ugryzieniu."},ru={title="Maur Raincaller",body="Maur знает опасных зверей Mulgore через личный опыт и истории своего деда. Он также знает, как сочетать различные животные ингредиенты для лечения инфекции от ядовитого укуса."},references={["place:mulgore"]=true}},
    ["person:maurin-bonesplitter"] = {title="Maurin Partehuesos",kind="Personaje",aliases={"Maurin","Maurin Partehuesos"},body="Maurin Partehuesos investiga la corrupción de Desolace. Su trabajo abarca cristales, magia demoníaca y las señales que permiten rastrear amenazas ocultas en la región.",aliasQuestIDs={},en={title="Maurin Bonesplitter",aliases={"Maurin","Maurin Bonesplitter"},body="Maurin Bonesplitter investigates corruption in Desolace. His work includes crystals, demonic magic and signs that can be used to track hidden threats in the region.",aliasQuestIDs={}},fr={title="Maurin Bonesplitter",body="Maurin Bonesplitter enquête sur la corruption dans Desolace. Son travail comprend des cristaux, de la magie démoniaque et des signes qui peuvent être utilisés pour suivre les menaces cachées dans la région."},de={title="Maurin Bonesplitter",body="Maurin Bonesplitter untersucht die Korruption in Desolace. Seine Arbeit umfasst Kristalle, dämonische Magie und Zeichen, mit denen man versteckte Bedrohungen in der Region aufspüren kann."},pt={title="Maurin Bonesplitter",body="Maurin Bonesplitter investiga corrupção em Desolace. Seu trabalho inclui cristais, magia demoníaca e sinais que podem ser usados para rastrear ameaças ocultas na região."},pl={title="Maurin Bonesplitter",body="Maurin Bonesplitter bada skażenie w Desolace. Jego praca obejmuje kryształy, demoniczną magię i oznaki pozwalające tropić ukryte zagrożenia w regionie."},ru={title="Maurin Bonesplitter",body="Maurin Bonesplitter исследует порчу в Desolace. Его работа включает кристаллы, демоническую магию и знаки, которые могут быть использованы для отслеживания скрытых угроз в регионе."},references={["place:desolace"]=true}},
    ["person:maws"] = {title="Fauces",kind="Personaje",aliases={"Fauces"},body="Fauces es una criatura marina gigantesca vinculada con la Bahía de la Tempestad, frente a Azshara. Su presencia se asocia con un remolino y restos de naufragios, un peligro muy distinto de los que acechan en tierra firme.",aliasQuestIDs={},en={title="Maws",aliases={"Maws"},body="Maws is a gigantic sea creature associated with the Bay of Storms off Azshara. Its presence is linked with a maelstrom and wreckage, a danger very different from those lurking on land.",aliasQuestIDs={}},fr={title="Maws",body="Maws est une gigantesque créature marine associée au Bay of Storms au large de Azshara. Sa présence est liée à un maelstrm et à une épave, un danger très différent de ceux qui rôdent sur terre."},de={title="Maws",body="Maws ist ein gigantisches Meerestier, das mit dem Bay of Storms vor Azshara in Verbindung gebracht wird. Seine Anwesenheit ist mit einem Strudel von Trümmern und Trümmern verbunden, eine Gefahr, die sich sehr von der anderen an Land unterscheidet."},pt={title="Maws",body="Maws é uma gigantesca criatura marinha associada ao Bay of Storms off Azshara. Sua presença está ligada a um turbilhão e destroços, um perigo muito diferente daqueles que se escondem em terra."},pl={title="Maws",body="Maws jest gigantycznym morskim stworzeniem związanym z Bay of Storms u wybrzeży regionu Azshara. Obecność wiąże się z wirem i szczątkami wraków, niebezpieczeństwem bardzo odmiennym od zagrożeń lądu."},ru={title="Maws",body="Maws - это гигантское морское существо, связанное с Bay of Storms от Azshara. Его присутствие связано с водоворотом и обломками, опасностью, сильно отличающейся от тех, которые скрываются на суше."},references={},questIDs={[8729]=true}},
    ["person:maybess-riverbreeze"] = {title="Maybess Brisa de Río",kind="Personaje",aliases={"Maybess","Maybess Brisa de Río"},body="Maybess Brisa de Río participa en la restauración de Frondavil para el Círculo Cenarion. Estudia sustancias de los elementales corruptos con la intención de salvar otras formas de vida de la región.",aliasQuestIDs={},en={title="Maybess Riverbreeze",aliases={"Maybess","Maybess Riverbreeze"},body="Maybess Riverbreeze takes part in restoring Felwood for the Cenarion Circle. She studies substances from corrupted elementals in hopes of saving other forms of life in the region.",aliasQuestIDs={}},fr={title="Maybess Riverbreeze",body="Maybess Riverbreeze participe à la restauration de Felwood pour le Cenarion Circle. Elle étudie les substances des élémentaux corrompus dans l'espoir de sauver d'autres formes de vie dans la région."},de={title="Maybess Riverbreeze",body="Maybess Riverbreeze beteiligt sich an der Restaurierung von Felwood für die Cenarion Circle. Sie untersucht Substanzen von korrumpierten Elementaren in der Hoffnung, andere Lebensformen in der Region zu retten."},pt={title="Maybess Riverbreeze",body="Maybess Riverbreeze participa na restauração do Felwood para o Cenarion Circle. Ela estuda substâncias de elementais corrompidos na esperança de salvar outras formas de vida na região."},pl={title="Maybess Riverbreeze",body="Maybess Riverbreeze uczestniczy w odnawianiu Felwood na rzecz Cenarion Circle. Bada substancje skażonych żywiołaków w nadziei ocalenia innych form życia w regionie."},ru={title="Maybess Riverbreeze",body="Maybess Riverbreeze участвует в восстановлении Felwood для Cenarion Circle. Она изучает вещества из испорченных элементалов в надежде спасти другие формы жизни в регионе."},references={["organization:cenarion-circle"]=true,["place:felwood"]=true}},
    ["person:mazukon"] = {title="Mazu'kon",kind="Personaje",aliases={"Mazu'kon","Mazu’kon"},body="Mazu'kon estudia venenos y prácticas mágicas de distintos pueblos. Su curiosidad abarca tanto las criaturas del Alto Penumbroso como los antiguos ídolos de magia de sangre de los Gurubashi.",aliasQuestIDs={},en={title="Mazu'kon",aliases={"Mazu'kon","Mazu’kon"},body="Mazu'kon studies venoms and the magical practices of different peoples. His curiosity ranges from Gloomrise’s creatures to ancient Gurubashi blood-magic idols.",aliasQuestIDs={}},fr={title="Mazu'kon",body="Mazu'kon étudie les venins et les pratiques magiques des différents peuples. Sa curiosité va des créatures de Gloomrise aux anciennes idoles de la magie du sang Gurubashi."},de={title="Mazu'kon",body="Mazu'kon studiert Gifte und die magischen Praktiken verschiedener Völker. Seine Neugier reicht von den Geschöpfen des Gloomrise bis zu den blutmagischen Vorbildern des alten Gurubashi."},pt={title="Mazu'kon",body="Mazu'kon estuda venenos e as práticas mágicas de diferentes povos. Sua curiosidade varia de criaturas de Gloomrise a antigos ídolos mágicos de sangue Gurubashi."},pl={title="Mazu'kon",body="Mazu'kon bada jady i praktyki magiczne różnych ludów. Jego ciekawość obejmuje stworzenia Gloomrise oraz pradawne bożki magii krwi Gurubashi."},ru={title="Mazu'kon",body="Mazu'kon изучает яды и магические практики разных народов. Его любопытство охватывает от созданий Gloomrise  до древних идолов кровомагии Gurubashi."},references={["organization:gurubashi"]=true,["place:gloomrise"]=true}},
    ["person:mazzranache"] = {title="Mazzranache",kind="Personaje",aliases={"Mazzranache"},body="Mazzranache es un zancudo de las llanuras conocido por sus ojos rojos, sus garras afiladas y su mordedura venenosa. Las historias sobre sus ataques han pasado de una generación a otra entre quienes viven en Mulgore.",aliasQuestIDs={},en={title="Mazzranache",aliases={"Mazzranache"},body="Mazzranache is a plains strider known for red eyes, sharp talons, and a venomous bite. Stories of its attacks have passed between generations among the people of Mulgore.",aliasQuestIDs={}},fr={title="Mazzranache",body="Mazzranache est un striker des plaines connu pour ses yeux rouges, ses serres pointues et sa morsure venimeuse. Des histoires de ses attaques se sont passées entre les générations parmi les habitants de Mulgore."},de={title="Mazzranache",body="Mazzranache ist ein einfacher Mann, der für rote Augen, scharfe Krallen und einen giftigen Biss bekannt ist. Die Geschichten über ihre Angriffe wurden zwischen den Generationen unter den Menschen von Mulgore weitergegeben."},pt={title="Mazzranache",body="Mazzranache é um estridente de planícies conhecido por olhos vermelhos, garras afiadas e uma mordida venenosa. Histórias de seus ataques passaram entre gerações entre o povo de Mulgore."},pl={title="Mazzranache",body="Mazzranache jest biegaczem równin znanym z czerwonych oczu, ostrych szponów i jadowitego ugryzienia. Opowieści o atakach przechodzą między pokoleniami mieszkańców Mulgore."},ru={title="Mazzranache",body="Mazzranache - это планинский страйддер, известный своими красными глазами, острыми когтями и ядовитым укусом. Истории о его нападениях передавались из поколения в поколение среди жителей Mulgore."},references={["place:mulgore"]=true}},
    ["person:mebok-mizzyrix"] = {title="Mebok Mizzyrix",kind="Personaje",aliases={"Mebok","Mebok Mizzyrix"},body="Mebok Mizzyrix trabaja en Trinquete con ideas comerciales basadas en recursos poco comunes. Sus proyectos relacionan ingredientes de criaturas con alimentos y preparados que podrían abrir nuevos mercados.",aliasQuestIDs={},en={title="Mebok Mizzyrix",aliases={"Mebok","Mebok Mizzyrix"},body="Mebok Mizzyrix works in Ratchet on business ideas based on unusual resources. His projects connect creature ingredients with foods and preparations that might open new markets.",aliasQuestIDs={}},fr={title="Mebok Mizzyrix",body="Mebok Mizzyrix travaille dans Ratchet sur des idées d'affaires basées sur des ressources inhabituelles. Ses projets relient les ingrédients des créatures avec des aliments et des préparations qui pourraient ouvrir de nouveaux marchés."},de={title="Mebok Mizzyrix",body="Mebok Mizzyrix arbeitet in Ratchet an Geschäftsideen auf der Grundlage ungewöhnlicher Ressourcen. Seine Projekte verbinden Zutaten aus Kreaturen mit Lebensmitteln und Zubereitungen, die neue Märkte erschließen könnten."},pt={title="Mebok Mizzyrix",body="Mebok Mizzyrix trabalha em Ratchet em ideias de negócios com base em recursos incomuns. Seus projetos conectam ingredientes de criaturas com alimentos e preparações que podem abrir novos mercados."},pl={title="Mebok Mizzyrix",body="Mebok Mizzyrix pracuje w Ratchet nad pomysłami handlowymi opartymi na niezwykłych zasobach. Jego projekty łączą składniki pochodzące ze stworzeń z potrawami i preparatami mogącymi otworzyć nowe rynki."},ru={title="Mebok Mizzyrix",body="Mebok Mizzyrix работает в Ratchet на бизнес-идеях, основанных на необычных ресурсах. Его проекты связывают ингредиенты из животных с продуктами питания и препаратами, которые могут открыть новые рынки."},references={["place:ratchet"]=true}},
    ["person:meela-dawnstrider"] = {title="Meela Caminalba",kind="Personaje",aliases={"Meela","Meela Caminalba"},body="Meela enseña a los jóvenes chamanes tauren y los acompaña durante su formación. Entiende esa tarea como una relación continuada, en la que cada encuentro debe dejar al aprendiz con una comprensión mayor.",aliasQuestIDs={},en={title="Meela Dawnstrider",aliases={"Meela","Meela Dawnstrider"},body="Meela teaches young tauren shamans and accompanies their training. She sees this as an ongoing relationship in which each meeting should leave the pupil with greater understanding.",aliasQuestIDs={}},fr={title="Meela Dawnstrider",body="Meela enseigne aux jeunes chamans taurens et accompagne leur formation. Elle voit cela comme une relation continue dans laquelle chaque réunion devrait laisser l'élève avec une plus grande compréhension."},de={title="Meela Dawnstrider",body="Meela unterrichtet junge Tauren-Schamanen und begleitet ihre Ausbildung. Sie sieht dies als eine fortdauernde Beziehung, in der jedes Treffen den Schüler mit größerem Verständnis zurücklassen sollte."},pt={title="Meela Dawnstrider",body="Meela ensina jovens xamãs tauren e acompanha seu treinamento. Ela vê isso como uma relação contínua em que cada reunião deve deixar o aluno com maior compreensão."},pl={title="Meela Dawnstrider",body="Meela uczy młodych taurenskich szamanów i towarzyszy ich szkoleniu. Widzi w tym trwałą relację, w której każde spotkanie powinno pozostawić ucznia z głębszym zrozumieniem."},ru={title="Meela Dawnstrider",body="Meela обучает молодых шаманов-таурен и сопровождает их обучение. Она видит это как постоянную связь, в которой каждая встреча должна оставить ученика с большим пониманием."},references={}},
    ["person:meilosh"] = {title="Meilosh",kind="Personaje",aliases={"Meilosh"},body="Meilosh confecciona ropajes para los Fauces de Madera. El interés de su pueblo por el paño rúnico y la importancia sagrada de la tela lunar lo han llevado a buscar materiales más allá de un bastión poco abierto al comercio.",aliasQuestIDs={},en={title="Meilosh",aliases={"Meilosh"},body="Meilosh makes garments for the Timbermaw. His people’s interest in runecloth and the sacred importance of mooncloth have led him to seek materials beyond a hold reluctant to trade.",aliasQuestIDs={}},fr={title="Meilosh",body="Meilosh fabrique des vêtements pour le Timbermaw. L’intérêt de son peuple pour le runecloth et l’importance sacrée du mooncloth l’ont amené à chercher des matériaux au-delà d’une prise réticente au commerce."},de={title="Meilosh",body="Meilosh macht Kleidungsstücke für den Timbermaw. Das Interesse seines Volkes an Runenstoff und die heilige Bedeutung von Mondstoffen haben ihn dazu gebracht, Materialien zu suchen, die nicht nur in einem Lasten des Handels zu halten."},pt={title="Meilosh",body="Meilosh faz roupas para o Timbermaw. O interesse de seu povo em roupas de runa e a importância sagrada da roupa de lua o levaram a buscar materiais além de um porão relutante em negociar."},pl={title="Meilosh",body="Meilosh wytwarza ubrania dla Timbermaw. Zainteresowanie ludu tkaniną runiczną i święte znaczenie tkaniny księżycowej skłoniły go do poszukiwania materiałów poza niechętnym handlowi schronieniem."},ru={title="Meilosh",body="Meilosh делает одежду для Timbermaw. Интерес его народа к руне и священное значение лунной ткани привели его искать материалы за пределами хранения не желающих торговать."},references={["organization:timbermaw"]=true}},
    ["person:melizza-brimbuzzle"] = {title="Melizza Zumbala",kind="Personaje",aliases={"Melizza","Melizza Zumbala"},body="Melizza Zumbala es una comerciante de Desolace interesada en negociar con los centauros. Sus contactos familiares cerca del Cementerio de Kodos forman parte de una actividad comercial que debe adaptarse a la desconfianza de los clanes.",aliasQuestIDs={},en={title="Melizza Brimbuzzle",aliases={"Melizza","Melizza Brimbuzzle"},body="Melizza Brimbuzzle is a Desolace trader interested in doing business with centaurs. Her family contacts near the Kodo Graveyard are part of a trade network that must adapt to the clans’ distrust.",aliasQuestIDs={}},fr={title="Melizza Brimbuzzle",body="Melizza Brimbuzzle est un trader Desolace intéressé à faire des affaires avec des centaures. Ses contacts familiaux près du cimetière Kodo font partie d’un réseau commercial qui doit s’adapter à la méfiance des clans."},de={title="Melizza Brimbuzzle",body="Melizza Brimbuzzle ist eine Desolace-Händlerin, die sich für Geschäfte mit Zentauren interessiert. Ihre Familienkontakte in der Nähe des Kodo-Friedhofes sind Teil eines Handelsnetzes, das sich dem Misstrauen der Clans anpassen muss."},pt={title="Melizza Brimbuzzle",body="Melizza Brimbuzzle é um comerciante Desolace interessado em fazer negócios com centauros. Seus contatos familiares perto do Cemitério Kodo fazem parte de uma rede comercial que deve se adaptar à desconfiança dos clãs."},pl={title="Melizza Brimbuzzle",body="Melizza Brimbuzzle jest handlarką w Desolace zainteresowaną interesami z centaurami. Rodzinne kontakty przy cmentarzysku Kodo stanowią część sieci handlowej, która musi dostosować się do nieufności klanów."},ru={title="Melizza Brimbuzzle",body="Melizza Brimbuzzle - трейдер Desolace, заинтересованный в бизнесе с кентаврами. Ее семейные контакты возле кладбища Kodo являются частью торговой сети, которая должна адаптироваться к недоверию кланов."},references={["place:desolace"]=true}},
    ["person:melor-stonehoof"] = {title="Melor Pezuña Pétrea",kind="Personaje",aliases={"Melor","Melor Pezuña Pétrea"},body="Melor Pezuña Pétrea es un tauren de Cima del Trueno vinculado a la caza y al respeto por los espíritus de los animales. Su visión de la caza exige reconocer tanto el vigor de una criatura como el sufrimiento que puede acompañar su vejez.",aliasQuestIDs={},en={title="Melor Stonehoof",aliases={"Melor","Melor Stonehoof"},body="Melor Stonehoof is a tauren in Thunder Bluff associated with hunting and respect for animal spirits. His view of the hunt requires recognizing both a creature’s strength and the suffering that may accompany old age.",aliasQuestIDs={}},fr={title="Melor Stonehoof",body="Melor Stonehoof est un tauren dans Thunder Bluff associé à la chasse et au respect des esprits animaux. Sa vision de la chasse exige de reconnaître à la fois la force d’une créature et la souffrance qui peut accompagner la vieillesse."},de={title="Melor Stonehoof",body="Melor Stonehoof ist ein Tauren in Thunder Bluff, der mit Jagd und Respekt für tierische Geister assoziiert wird. Seine Sicht der Jagd erfordert, dass man sowohl die Stärke eines Geschöpfes als auch das Leid anerkennt, das mit dem Alter einhergehen kann."},pt={title="Melor Stonehoof",body="Melor Stonehoof é um tauren no Thunder Bluff associado à caça e ao respeito pelos espíritos animais. Sua visão da caça exige reconhecer tanto a força de uma criatura quanto o sofrimento que pode acompanhar a velhice."},pl={title="Melor Stonehoof",body="Melor Stonehoof jest taurenem w Thunder Bluff związanym z łowiectwem i szacunkiem dla duchów zwierząt. Jego podejście do polowania wymaga dostrzegania zarówno siły stworzenia, jak i cierpienia, które może towarzyszyć starości."},ru={title="Melor Stonehoof",body="Melor Stonehoof - это таурен в Thunder Bluff, связанный с охотой и уважением к духам животных. Его взгляд на охоту требует признания как силы существа, так и страданий, которые могут сопровождать старость."},references={["place:thunder-bluff"]=true}},
    ["person:menara-voidrender"] = {title="Menara Nadiz",kind="Personaje",aliases={"Menara","Menara Nadiz"},body="Menara Nadiz es una instructora de brujos en Los Baldíos. Su experiencia abarca la creación de prendas y armas mágicas, así como el uso de componentes demoníacos para fortalecer el equipo de sus discípulos.",aliasQuestIDs={},en={title="Menara Voidrender",aliases={"Menara","Menara Voidrender"},body="Menara Voidrender is a warlock instructor in the Barrens. Her expertise includes creating magical garments and weapons and using demonic components to strengthen her students’ equipment.",aliasQuestIDs={}},fr={title="Menara Voidrender",body="Menara Voidrender est un instructeur de démoniste dans le Barrens. Son expertise comprend la création de vêtements et d’armes magiques et l’utilisation de composants démoniaques pour renforcer l’équipement de ses élèves."},de={title="Menara Voidrender",body="Menara Voidrender ist Hexenlehrerin in der Barrens. Zu ihren Fähigkeiten gehören die Herstellung magischer Kleider und Waffen sowie die Verwendung dämonischer Komponenten, um die Ausrüstung ihrer Schüler zu stärken."},pt={title="Menara Voidrender",body="Menara Voidrender é um instrutor de bruxo no Barrens. Sua experiência inclui a criação de roupas e armas mágicas e o uso de componentes demoníacos para fortalecer o equipamento de seus alunos."},pl={title="Menara Voidrender",body="Menara Voidrender jest nauczycielką czarnoksiężników w regionie Barrens. Specjalizuje się między innymi w tworzeniu magicznych szat i broni oraz wykorzystywaniu demonicznych składników do wzmacniania wyposażenia uczniów."},ru={title="Menara Voidrender",body="Menara Voidrender - инструктор-чернокнижник в Barrens. Ее опыт включает в себя создание магических одежд и оружия и использование демонических компонентов для укрепления оборудования ее учеников."},references={["place:the-barrens"]=true}},
    ["person:meridith-the-mermaiden"] = {title="Meridith la Sirenita",kind="Personaje",aliases={"Meridith","Meridith la Sirenita"},body="Meridith la Sirenita recibe pocas visitas en su retiro. Conserva un profundo afecto por Narain Sabelotodo, el gnomo al que rescató de los restos de una máquina voladora estrellada.",aliasQuestIDs={},en={title="Meridith the Mermaiden",aliases={"Meridith","Meridith the Mermaiden"},body="Meridith the Mermaiden rarely receives visitors at her retreat. She retains a deep affection for Narain Soothfancy, the gnome she rescued from a crashed flying machine.",aliasQuestIDs={}},fr={title="Meridith the Mermaiden",body="Meridith the Mermaiden reçoit rarement des visiteurs à sa retraite. Elle conserve une profonde affection pour Narain Soothfancy, le gnome qu'elle a sauvé d'une machine volante écrasée."},de={title="Meridith the Mermaiden",body="Meridith the Mermaiden bekommt selten Besuch in ihrem Rückzugsort. Sie hegt nach wie vor eine tiefe Zuneigung zu Narain Soothfancy, dem Zwerg, den sie aus einer abgestürzten Flugmaschine gerettet hat."},pt={title="Meridith the Mermaiden",body="Meridith the Mermaiden raramente recebe visitantes em seu retiro. Ela mantém uma profunda afeição por Narain Soothfancy, o gnomo que ela resgatou de uma máquina voadora acidentada."},pl={title="Meridith the Mermaiden",body="Meridith the Mermaiden rzadko przyjmuje gości w swoim schronieniu. Nadal żywi głębokie uczucie do postaci Narain Soothfancy, gnoma uratowanego z rozbitej maszyny latającej."},ru={title="Meridith the Mermaiden",body="Meridith the Mermaiden редко принимает гостей в своём уединённом убежище. Она сохраняет глубокую привязанность к Narain Soothfancy, гному, которого она спасла из разбившейся летающей машины."},references={["person:narain-soothfancy"]=true}},
    ["person:merithra-of-the-dream"] = {title="Merithra del Sueño",kind="Personaje",aliases={"Merithra","Merithra del Sueño"},body="Merithra del Sueño posee conocimientos sobre el uso del elementium en el Templo de Ahn'Qiraj. Su trabajo transforma objetos ceremoniales qiraji en equipo preparado para enfrentarse a los poderes que dominan el lugar.",aliasQuestIDs={},en={title="Merithra of the Dream",aliases={"Merithra","Merithra of the Dream"},body="Merithra of the Dream possesses knowledge about the use of elementium in the Temple of Ahn'Qiraj. Her work transforms qiraji ceremonial objects into equipment suited to facing the powers that dominate the site.",aliasQuestIDs={}},fr={title="Merithra of the Dream",body="Merithra of the Dream possède des connaissances sur l'utilisation de l'élémentium dans le Temple de Ahn'Qiraj. Son travail transforme les objets cérémoniels qiraji en équipement adapté pour faire face aux pouvoirs qui dominent le site."},de={title="Merithra of the Dream",body="Merithra of the Dream verfügt über Wissen zur Verwendung von Elementium im Temple of Ahn'Qiraj. Durch ihre Arbeit werden Zeremonialgegenstände der Qiraji zu Ausrüstung, die sich für den Kampf gegen die dort herrschenden Mächte eignet."},pt={title="Merithra of the Dream",body="Merithra of the Dream possui conhecimento sobre o uso de elementium no Templo de Ahn'Qiraj. Seu trabalho transforma objetos cerimoniais qiraji em equipamentos adequados para enfrentar os poderes que dominam o local."},pl={title="Merithra of the Dream",body="Merithra of the Dream posiada wiedzę o wykorzystaniu elementium w świątyni Ahn'Qiraj. Przekształca ceremonialne przedmioty qiraji w wyposażenie przystosowane do stawienia czoła potęgom władającym tym miejscem."},ru={title="Merithra of the Dream",body="Merithra of the Dream обладает знаниями об использовании элемента в Храме Ahn'Qiraj. Ее работа превращает церемониальные предметы qiraji в оборудование, подходящее для противостояния силам, которые доминируют на этом месте."},references={["people:qiraji"]=true,["place:ahnqiraj"]=true}},
    ["person:merok-longstride"] = {title="Merok Zancada Larga",kind="Personaje",aliases={"Merok","Merok Zancada Larga"},body="Merok Zancada Larga participa en la logística de la Legión de Orgrimmar en Silithus. La llegada de armas a su campamento cerca de Colmen'Regal ayuda a sostener a las fuerzas que combaten en el desierto.",aliasQuestIDs={},en={title="Merok Longstride",aliases={"Merok","Merok Longstride"},body="Merok Longstride participates in the Orgrimmar Legion’s logistics in Silithus. Weapons reaching his camp near Hive'Regal help sustain the forces fighting in the desert.",aliasQuestIDs={}},fr={title="Merok Longstride",body="Merok Longstride participe à la logistique du Orgrimmar Legion dans Silithus. Les armes atteignant son camp près de Hive'Regal aident à soutenir les forces combattant dans le désert."},de={title="Merok Longstride",body="Merok Longstride nimmt an der Logistik des Orgrimmar Legion 'in Silithus teil. Waffen, die sein Lager in der Nähe von Hive'Regal erreichen, tragen dazu bei, die in der Wüste kämpfenden Truppen zu unterstützen."},pt={title="Merok Longstride",body="Merok Longstride participa da logística do Orgrimmar Legion no Silithus. As armas que chegam ao seu acampamento perto de Hive'Regal ajudam a sustentar as forças que lutam no deserto."},pl={title="Merok Longstride",body="Merok Longstride uczestniczy w logistyce Orgrimmar Legion w Silithus. Broń docierająca do jego obozu koło Hive'Regal wspiera siły walczące na pustyni."},ru={title="Merok Longstride",body="Merok Longstride участвует в логистике Orgrimmar Legion  в Silithus. Оружие, доходящее до его лагеря возле Hive'Regal, помогает поддерживать силы, сражающиеся в пустыне."},references={["organization:orgrimmar-legion"]=true,["place:hiveregal"]=true,["place:orgrimmar"]=true,["place:silithus"]=true}},
    ["person:migi"] = {title="Migi",kind="Personaje",aliases={"Migi"},body="Migi es un niño de Orgrimmar que prefiere jugar con sus amigos antes que detenerse a almorzar. La preocupación de su familia y sus gustos por la comida de Borstan muestran un lado cotidiano de la ciudad de los orcos.",aliasQuestIDs={},en={title="Migi",aliases={"Migi"},body="Migi is an Orgrimmar child who prefers playing with friends to stopping for lunch. His family’s concern and his taste for Borstan’s food reveal an everyday side of the orc city.",aliasQuestIDs={}},fr={title="Migi",body="Migi est un enfant Orgrimmar qui préfère jouer avec des amis plutôt que de s'arrêter pour le déjeuner. La préoccupation de sa famille et son goût pour la nourriture de Borstan révèlent un côté quotidien de la ville orc."},de={title="Migi",body="Migi ist ein Orgrimmar-Kind, das lieber mit Freunden spielt, als zu Mittag zu essen. Die Sorge seiner Familie und seine Vorliebe für Borstan 's Essen offenbaren eine alltägliche Seite der Orc-Stadt."},pt={title="Migi",body="Migi é uma criança Orgrimmar que prefere brincar com os amigos a parar para almoçar. A preocupação de sua família e seu gosto pela comida de Borstan revelam um lado cotidiano da cidade orc."},pl={title="Migi",body="Migi jest dzieckiem z Orgrimmar, które woli bawić się z przyjaciółmi niż zatrzymywać na obiad. Troska rodziny i upodobanie do jedzenia z lokalu Borstan ukazują codzienną stronę orczego miasta."},ru={title="Migi",body="Migi - это ребенок Orgrimmar, который предпочитает играть с друзьями, чем останавливаться на обед. Забота его семьи и вкус к еде Borstan раскрывают повседневную сторону города орков."},references={["person:borstan"]=true,["place:orgrimmar"]=true}},
    ["person:mirda"] = {title="Mirda",kind="Personaje",aliases={"Mirda"},body="Mirda es una integrante de los Magram de Desolace preocupada por los suministros de su clan. La preparación de protección mágica para quienes cruzan tierras peligrosas forma parte de sus responsabilidades.",aliasQuestIDs={},en={title="Mirda",aliases={"Mirda"},body="Mirda is a member of the Magram in Desolace concerned with her clan’s supplies. Preparing magical protection for those crossing dangerous lands is part of her responsibilities.",aliasQuestIDs={}},fr={title="Mirda",body="Mirda est membre de la Magram dans Desolace concernée par les approvisionnements de son clan. Préparer une protection magique pour ceux qui traversent des terres dangereuses fait partie de ses responsabilités."},de={title="Mirda",body="Mirda ist Mitglied der Magram in Desolace, die sich um die Vorräte ihres Clans kümmert. Die Vorbereitung des magischen Schutzes für diejenigen, die gefährliches Land überqueren, ist Teil ihrer Verantwortlichkeit."},pt={title="Mirda",body="Mirda é um membro do Magram no Desolace preocupado com os suprimentos de seu clã. Preparar proteção mágica para aqueles que atravessam terras perigosas é parte de suas responsabilidades."},pl={title="Mirda",body="Mirda jest członkinią klanu Magram w Desolace troszczącą się o jego zaopatrzenie. Przygotowywanie magicznej ochrony dla osób przemierzających niebezpieczne ziemie należy do jej obowiązków."},ru={title="Mirda",body="Mirda является членом Magram в Desolace, занимающейся снабжением своего клана. Подготовка магической защиты для тех, кто пересекает опасные земли, является частью ее обязанностей."},references={["organization:magram"]=true,["place:desolace"]=true}},
    ["person:missionary-jasaan"] = {title="Misionero Jasaan",kind="Personaje",aliases={"Jasaan","Misionero Jasaan","misionero Jasaan"},body="Jasaan es un misionero que recibe a los reclutas de los seguidores de Al'Akir en el Poblado Falaath. Se encuentra cerca de la entrada del poblado y orienta el acceso de los recién llegados. Su función lo vincula con la expansión de los fieles del Culto de Al'Aketh.",aliasQuestIDs={},en={title="Missionary Jasaan",aliases={"Jasaan","Missionary Jasaan"},body="Jasaan is a missionary who receives recruits among Al'Akir's followers at Falaath Village. He can be found near the village entrance and directs the access of newcomers. His role connects him with the growth of the Al'Aketh Cult's faithful.",aliasQuestIDs={}},fr={title="Missionary Jasaan",body="Jasaan est un missionnaire qui reçoit des recrues parmi les adeptes de Al'Akir à Falaath Village. Il se trouve près de l'entrée du village et dirige l'accès des nouveaux arrivants. Son rôle le relie à la croissance des fidèles de la Al'Aketh Cult."},de={title="Missionary Jasaan",body="Jasaan ist ein Missionar, der in Falaath Village Rekruten aus Al'Akir \"Gefolgschaft aufnimmt. Er ist in der Nähe des Ortseingangs zu finden und leitet den Zugang für Neuankömmlinge. Seine Rolle verbindet ihn mit dem Wachstum der Al'Aketh Cult-Gläubigen."},pt={title="Missionary Jasaan",body="Jasaan é um missionário que recebe recrutas entre os seguidores de Al'Akir no Falaath Village. Ele pode ser encontrado perto da entrada da aldeia e dirige o acesso de recém-chegados. Seu papel o conecta com o crescimento dos fiéis do Al'Aketh Cult."},pl={title="Missionary Jasaan",body="Jasaan jest misjonarzem przyjmującym rekrutów wśród wyznawców Al'Akir w Falaath Village. Przebywa przy wejściu do wioski i kieruje dostępem nowych przybyszów. Jego rola wiąże go ze wzrostem liczby wiernych Al'Aketh Cult."},ru={title="Missionary Jasaan",body="Jasaan - миссионер, который принимает новобранцев из числа последователей Al'Akir в Falaath Village. Он находится возле входа в деревню и направляет приезжих. Его роль связывает его с ростом последователей Al'Aketh Cult."},references={["npc:alakir"]=true,["organization:al-aketh"]=true,["place:falaath-village"]=true}},
    ["person:mokmorokk"] = {title="Mok'Morokk",kind="Personaje",aliases={"Mok'Morokk","Mok’Morokk"},body="Mok'Morokk es el señor supremo de los ogros del Poblado Murohelecho, nombrado por Rexxar. Su autoridad se ejerce sobre una comunidad desplazada por el peligro de los dragones negros.",aliasQuestIDs={},en={title="Mok'Morokk",aliases={"Mok'Morokk","Mok’Morokk"},body="Mok'Morokk is the overlord of the ogres in Brackenwall Village, appointed by Rexxar. He rules a community displaced by the danger of black dragons.",aliasQuestIDs={}},fr={title="Mok'Morokk",body="Mok'Morokk est le suzerain des ogres dans Brackenwall Village, nommé par Rexxar. Il gouverne une communauté déplacée par le danger des dragons noirs."},de={title="Mok'Morokk",body="Mok'Morokk ist der Herr der Oger in Brackenwall Village, der von Rexxar ernannt wird. Er regiert eine Gemeinschaft, die von der Gefahr schwarzer Drachen verdrängt wird."},pt={title="Mok'Morokk",body="Mok'Morokk é o senhor supremo dos ogres em Brackenwall Village, nomeado pela Rexxar. Ele governa uma comunidade deslocada pelo perigo de dragões negros."},pl={title="Mok'Morokk",body="Mok'Morokk jest władcą ogrów w Brackenwall Village, mianowanym przez postać Rexxar. Rządzi społecznością wysiedloną wskutek zagrożenia ze strony czarnych smoków."},ru={title="Mok'Morokk",body="Mok'Morokk - это повелитель огров в Brackenwall Village, назначенный Rexxar. Он правит общиной, вынужденной покинуть свои дома из-за опасности черных драконов."},references={["person:rexxar"]=true,["place:brackenwall-village"]=true}},
    ["person:moktar-krin"] = {title="Moktar Krin",kind="Personaje",aliases={"Moktar","Moktar Krin"},body="Moktar Krin dirige fuerzas de la Horda en Las Mil Agujas. La presencia de excavadores e insectos peligrosos ha añadido nuevas dificultades a la defensa de las rutas del Desierto de Sal.",aliasQuestIDs={},en={title="Moktar Krin",aliases={"Moktar","Moktar Krin"},body="Moktar Krin commands Horde forces in Thousand Needles. Excavators and dangerous insects have added new difficulties to defending the Shimmering Flats’ routes.",aliasQuestIDs={}},fr={title="Moktar Krin",body="Moktar Krin commande les forces Horde dans Thousand Needles. Les excavatrices et les insectes dangereux ont ajouté de nouvelles difficultés à la défense des routes du Shimmering Flats."},de={title="Moktar Krin",body="Moktar Krin befehligt Streitkräfte der Horde in Thousand Needles. Ausgräber und gefährliche Insekten haben die Verteidigung der Wege durch die Shimmering Flats zusätzlich erschwert."},pt={title="Moktar Krin",body="Moktar Krin comanda as forças Horde em Thousand Needles. Escavadoras e insetos perigosos adicionaram novas dificuldades para defender as rotas do Shimmering Flats."},pl={title="Moktar Krin",body="Moktar Krin dowodzi siłami frakcji Horde w Thousand Needles. Koparki i niebezpieczne owady dodały nowych trudności obronie szlaków Shimmering Flats."},ru={title="Moktar Krin",body="Moktar Krin командует силами Horde в Thousand Needles. Раскопки и опасные насекомые создали новые трудности для защиты маршрутов Shimmering Flats."},references={["organization:horde"]=true,["place:shimmering-flats"]=true,["place:thousand-needles"]=true}},
    ["person:mokvar"] = {title="Mokvar",kind="Personaje",aliases={"Mokvar"},body="Mokvar es un contacto de Orgrimmar interesado en equipo especializado y fenómenos sobrenaturales. Su trabajo lo relaciona con dispositivos capaces de detectar presencias que no se perciben con facilidad.",aliasQuestIDs={},en={title="Mokvar",aliases={"Mokvar"},body="Mokvar is an Orgrimmar contact interested in specialized equipment and supernatural phenomena. His work connects him with devices capable of detecting presences that are not easily perceived.",aliasQuestIDs={}},fr={title="Mokvar",body="Mokvar est un contact Orgrimmar intéressé par les équipements spécialisés et les phénomènes surnaturels. Son travail le relie à des dispositifs capables de détecter des présences qui ne sont pas facilement perceptibles."},de={title="Mokvar",body="Mokvar ist ein Orgrimmar-Kontakt, der sich für spezielle Ausrüstung und übernatürliche Phänomene interessiert. Seine Arbeit verbindet ihn mit Geräten, die in der Lage sind, Anwesenheiten zu erkennen, die nicht leicht wahrgenommen werden."},pt={title="Mokvar",body="Mokvar é um contato Orgrimmar interessado em equipamentos especializados e fenômenos sobrenaturais. Seu trabalho o conecta com dispositivos capazes de detectar presenças que não são facilmente percebidas."},pl={title="Mokvar",body="Mokvar jest kontaktem w Orgrimmar zainteresowanym specjalistycznym wyposażeniem i zjawiskami nadprzyrodzonymi. Jego praca wiąże go z urządzeniami wykrywającymi obecności, których niełatwo dostrzec zwykłymi zmysłami."},ru={title="Mokvar",body="Mokvar - это контакт Orgrimmar, заинтересованный в специализированном оборудовании и сверхъестественных явлениях. Его работа связывает его с устройствами, способными обнаруживать присутствие, которое не легко воспринимается."},references={["place:orgrimmar"]=true}},
    ["person:molkar"] = {title="Molkar",kind="Personaje",aliases={"Molkar"},body="Molkar es un centauro responsable de mantener al Poblado Gelkis abastecido y equipado. Colabora con Halea para que el trabajo de encantamiento pueda sostener las necesidades del clan.",aliasQuestIDs={},en={title="Molkar",aliases={"Molkar"},body="Molkar is a centaur responsible for keeping Gelkis Village supplied and equipped. He works with Halea so that enchanting can support the clan’s needs.",aliasQuestIDs={}},fr={title="Molkar",body="Molkar est un centaure responsable de l'approvisionnement et de l'équipement de Gelkis Village. Il travaille avec Halea afin que l’enchantement puisse répondre aux besoins du clan."},de={title="Molkar",body="Molkar ist als Zentaur dafür verantwortlich, dass Gelkis Village versorgt und ausgerüstet bleibt. Er arbeitet mit Halea zusammen, damit Zauberer die Bedürfnisse des Clans unterstützen kann."},pt={title="Molkar",body="Molkar é um centauro responsável por manter o Gelkis Village fornecido e equipado. Ele trabalha com Halea para que o encantamento possa suportar as necessidades do clã."},pl={title="Molkar",body="Molkar jest centaurem odpowiedzialnym za zaopatrzenie i wyposażenie wioski Gelkis. Współpracuje z postacią Halea, aby zaklinanie wspierało potrzeby klanu."},ru={title="Molkar",body="Molkar - это кентавр, ответственный за обеспечение поселка Gelkis снабжением и оборудованием. Он работает с Halea, чтобы заклинание могло удовлетворить потребности клана."},references={["organization:gelkis"]=true,["person:halea"]=true}},
    ["person:moon-priestess-amara"] = {title="Sacerdotisa Lunar Amara",kind="Personaje",aliases={"Amara","Sacerdotisa Lunar Amara"},body="La sacerdotisa lunar Amara forma parte de las centinelas de Teldrassil. Protege el camino entre Dolanaar y Darnassus, una vía esencial para el comercio y las noticias que los ataques de los Tuercepinos han vuelto peligrosa.",aliasQuestIDs={},en={title="Moon Priestess Amara",aliases={"Amara","Moon Priestess Amara"},body="Moon Priestess Amara is a member of Teldrassil’s Sentinel force. She protects the road between Dolanaar and Darnassus, an important route for trade and news threatened by Gnarlpine attacks.",aliasQuestIDs={}},fr={title="Moon Priestess Amara",body="Moon Priestess Amara est membre de la force Sentinel de Teldrassil. Elle protège la route entre Dolanaar et Darnassus, une route importante pour le commerce et les nouvelles menacées par les attaques Gnarlpine."},de={title="Moon Priestess Amara",body="Moon Priestess Amara ist Mitglied der Wache von Teldrassil. Sie schützt die Straße zwischen Dolanaar und Darnassus, eine wichtige Straße für Handel und Nachrichten, die durch Gnarlpine Angriffe bedroht sind."},pt={title="Moon Priestess Amara",body="Moon Priestess Amara é um membro da força Sentinel do Teldrassil. Ela protege a estrada entre Dolanaar e Darnassus, uma rota importante para o comércio e notícias ameaçadas por ataques Gnarlpine."},pl={title="Moon Priestess Amara",body="Moon Priestess Amara należy do sił strażniczek Teldrassil. Chroni drogę między Dolanaar a Darnassus, ważny szlak handlu i wiadomości zagrożony atakami Gnarlpine."},ru={title="Moon Priestess Amara",body="Moon Priestess Amara состоит в силах Sentinels на Teldrassil. Она защищает дорогу между Dolanaar и Darnassus — важный путь для торговли и новостей, которому угрожают нападения Gnarlpine."},references={["organization:gnarlpine"]=true,["place:darnassus"]=true,["place:dolanaar"]=true,["place:teldrassil"]=true}},
    ["person:morgan-stern"] = {title="Morgan Stern",kind="Personaje",aliases={"Morgan","Morgan Stern"},body="Morgan Stern es un cocinero de Theramore que experimenta con los recursos del Marjal Revolcafango. Busca ingredientes específicos de las tortugas y otras criaturas para dar un sabor propio a sus platos.",aliasQuestIDs={},en={title="Morgan Stern",aliases={"Morgan","Morgan Stern"},body="Morgan Stern is a Theramore cook experimenting with Dustwallow Marsh’s resources. He seeks specific ingredients from turtles and other creatures to give his dishes a distinctive flavor.",aliasQuestIDs={}},fr={title="Morgan Stern",body="Morgan Stern est un cuisinier Theramore expérimentant avec les ressources de Dustwallow Marsh. Il cherche des ingrédients spécifiques de tortues et d'autres créatures pour donner à ses plats une saveur distinctive."},de={title="Morgan Stern",body="Morgan Stern ist ein Theramore Koch, der mit Dustwallow Marsh 'Ressourcen experimentiert. Er sucht bestimmte Zutaten von Schildkröten und anderen Lebewesen, um seinen Gerichten einen unverwechselbaren Geschmack zu verleihen."},pt={title="Morgan Stern",body="Morgan Stern é um cozinheiro Theramore que experimenta os recursos do Dustwallow Marsh. Ele procura ingredientes específicos de tartarugas e outras criaturas para dar aos seus pratos um sabor distinto."},pl={title="Morgan Stern",body="Morgan Stern jest kucharzem w Theramore eksperymentującym z zasobami Dustwallow Marsh. Szuka określonych składników żółwi i innych stworzeń, by nadawać potrawom wyjątkowy smak."},ru={title="Morgan Stern",body="Morgan Stern - это повар Theramore, экспериментирующий с ресурсами Dustwallow Marsh s. Он ищет специальные ингредиенты у черепах и других существ, чтобы придать своим блюдам особый вкус."},references={["place:dustwallow-marsh"]=true,["place:theramore"]=true},questIDs={[1204]=true,[1222]=true,[1258]=true,[1260]=true,[1271]=true}},
    ["person:morin-cloudstalker"] = {title="Morin Acechanubes",kind="Personaje",aliases={"Morin","Morin Acechanubes"},body="Morin Acechanubes es un tauren de Mulgore que sigue las actividades de Ventura y Cía. Busca información sobre sus operaciones para entender el peligro que representan para las tierras próximas al Poblado Pezuña de Sangre.",aliasQuestIDs={},en={title="Morin Cloudstalker",aliases={"Morin","Morin Cloudstalker"},body="Morin Cloudstalker is a tauren in Mulgore who watches Venture Company activity. He seeks information on its operations to understand the danger they pose to lands near Bloodhoof Village.",aliasQuestIDs={}},fr={title="Morin Cloudstalker",body="Morin Cloudstalker est un tauren en Mulgore qui regarde l'activité Venture Company. Il cherche des informations sur ses opérations pour comprendre le danger qu'elles représentent pour les terres proches de Bloodhoof Village."},de={title="Morin Cloudstalker",body="Morin Cloudstalker ist ein Tauren in Mulgore, der Venture Company Aktivität beobachtet. Er bittet um Informationen über die Operationen, um zu verstehen, welche Gefahren sie für die Landungen in der Nähe von Bloodhoof Village darstellen."},pt={title="Morin Cloudstalker",body="Morin Cloudstalker é um tauren no Mulgore que observa a atividade do Venture Company. Ele busca informações sobre suas operações para entender o perigo que representam para terras próximas a Bloodhoof Village."},pl={title="Morin Cloudstalker",body="Morin Cloudstalker jest taurenem w Mulgore obserwującym działalność Venture Company. Szuka informacji o jej przedsięwzięciach, by zrozumieć zagrożenie dla ziem w pobliżu Bloodhoof Village."},ru={title="Morin Cloudstalker",body="Morin Cloudstalker - это таурен в Mulgore, который наблюдает за деятельностью Venture Company. Он ищет информацию о его операциях, чтобы понять опасность, которую они представляют для земли вблизи Bloodhoof Village."},references={["organization:venture-company"]=true,["place:bloodhoof-village"]=true,["place:mulgore"]=true}},
    ["person:morja"] = {title="Morja",kind="Personaje",aliases={"Morja"},body="Morja cuida de la rana Jubjub, que siente una gran afición por la cerveza Hierro Negro. Mantener a su compañera cerca la lleva a reunir esa bebida y a compartir huevos de rana con quienes la ayudan.",aliasQuestIDs={},en={title="Morja",aliases={"Morja"},body="Morja cares for Jubjub, a frog with a great fondness for Dark Iron ale. Keeping her companion nearby leads her to gather the drink and share frog eggs with those who help.",aliasQuestIDs={}},fr={title="Morja",body="Morja prend soin de Jubjub, une grenouille avec un grand penchant pour Dark Iron ale. Garder son compagnon à proximité la conduit à recueillir la boisson et à partager les œufs de grenouille avec ceux qui l'aident."},de={title="Morja",body="Morja kümmert sich um Jubjub, einen Frosch mit einer großen Vorliebe für Dark Iron ale. Ihre Begleiterin in der Nähe zu halten, bringt sie dazu, das Getränk zu sammeln und Froscheiße mit denen zu teilen, die helfen, die helfen."},pt={title="Morja",body="Morja se preocupa com Jubjub, um sapo com um grande carinho por Dark Iron ale. Manter seu companheiro por perto a leva a colher a bebida e compartilhar ovos de rã com aqueles que ajudam."},pl={title="Morja",body="Morja opiekuje się postacią Jubjub, żabą o wielkim zamiłowaniu do Dark Iron ale. Chęć utrzymania towarzysza w pobliżu skłania ją do zbierania napoju i dzielenia się żabimi jajami z pomagającymi."},ru={title="Morja",body="Morja заботится о Jubjub, лягушке с большой привязанностью к Dark Iron ale. Сопровождая своего товарища, она собирает напиток и делится яйцами лягушек с теми, кто помогает."},references={["object:dark-iron-ale"]=true}},
    ["person:morrogal"] = {title="Mor'rogal",kind="Personaje",aliases={"Mor'rogal","Mor’rogal"},body="Mor'rogal conoce usos para las piedrasoles relumbrantes que acumulan las arpías Furia Sangrienta. Su interés por estas piedras lo relaciona con los materiales recuperados de La Vega Carbonizada.",aliasQuestIDs={},en={title="Mor'rogal",aliases={"Mor'rogal","Mor’rogal"},body="Mor'rogal knows uses for the glittering sunstones gathered by the Bloodfury harpies. His interest in these stones connects him with materials recovered from the Charred Vale.",aliasQuestIDs={}},fr={title="Mor'rogal",body="Mor'rogal connaît les utilisations pour les pierres de soleil scintillantes recueillies par les harpies Bloodfury. Son intérêt pour ces pierres le relie aux matériaux récupérés de la Charred Vale."},de={title="Mor'rogal",body="Mor'rogal kennt die Verwendung für die glitzernden Sonnensteine, die von den Bloodfury Harpies gesammelt hat. Sein Interesse an diesen Steinen verbindet ihn mit Materialien, die vom Charred Vale gewonnen wurden."},pt={title="Mor'rogal",body="Mor'rogal conhece usos para as brilhantes pedras solares reunidas pelas harpias Bloodfury. Seu interesse por essas pedras o conecta com materiais recuperados do Charred Vale."},pl={title="Mor'rogal",body="Mor'rogal zna zastosowania błyszczących kamieni słonecznych zbieranych przez harpie Bloodfury. Zainteresowanie kamieniami wiąże go z materiałami odzyskiwanymi z Charred Vale."},ru={title="Mor'rogal",body="Mor'rogal знает, как использовать блестящие солнечные камни, собранные гарпиями Bloodfury. Его интерес к этим камням связывает его с материалами, извлеченными из Charred Vale."},references={["organization:bloodfury"]=true,["place:charred-vale"]=true}},
    ["person:mosarn"] = {title="Mosarn",kind="Personaje",aliases={"Mosarn"},body="Mosarn es un herrero respetado de Cima del Trueno. La calidad de sus armaduras le ha permitido trabajar para aliados como el Anillo de la Tierra, y sus marcas de forja ayudan a reconocer el origen de las piezas.",aliasQuestIDs={},en={title="Mosarn",aliases={"Mosarn"},body="Mosarn is a respected blacksmith in Thunder Bluff. The quality of his armor has allowed him to work for allies such as the Earthen Ring, and his forge marks help identify the origins of pieces.",aliasQuestIDs={}},fr={title="Mosarn",body="Mosarn est un forgeron respecté dans Thunder Bluff. La qualité de son armure lui a permis de travailler pour des alliés tels que le Earthen Ring, et ses marques de forge aident à identifier les origines des pièces."},de={title="Mosarn",body="Mosarn ist ein angesehener Schmied in Thunder Bluff. Die Qualität seiner Rüstung ermöglichte es ihm, für Verbündete wie die Earthen Ring zu arbeiten, und seine Schmiedetes zu arbeiten. Seine Schmiedemarken helfen ihm, die Herkunft der Stücke zu identifizieren."},pt={title="Mosarn",body="Mosarn é um ferreiro respeitado no Thunder Bluff. A qualidade de sua armadura permitiu que ele trabalhasse para aliados como o Earthen Ring, e suas marcas de forja ajudam a identificar as origens das peças."},pl={title="Mosarn",body="Mosarn jest szanowanym kowalem w Thunder Bluff. Jakość zbroi pozwoliła mu pracować dla sojuszników takich jak Earthen Ring, a oznaczenia kuźni pomagają określać pochodzenie przedmiotów."},ru={title="Mosarn",body="Mosarn - уважаемый кузнец в Thunder Bluff. Качество его доспехов позволило ему работать на союзников, таких как Earthen Ring, и его ковальные знаки помогают определить происхождение деталей."},references={["organization:earthen-ring"]=true,["place:thunder-bluff"]=true}},
    ["person:motega-firemane"] = {title="Motega Pirocabello",kind="Personaje",aliases={"Motega","Motega Pirocabello"},body="Motega Pirocabello trabaja en el Campamento del Tramo Blanco de Las Mil Agujas. Se interesa por los dracoleones de la región y por la seguridad de quienes se acercan a estudiarlos.",aliasQuestIDs={},en={title="Motega Firemane",aliases={"Motega","Motega Firemane"},body="Motega Firemane works at Whitereach Post in Thousand Needles. He is concerned with the region’s wyverns and the safety of those approaching them to study them.",aliasQuestIDs={}},fr={title="Motega Firemane",body="Motega Firemane travaille à Whitereach Post dans Thousand Needles. Il est préoccupé par les wyverns de la région et la sécurité de ceux qui les approchent pour les étudier."},de={title="Motega Firemane",body="Motega Firemane arbeitet bei Whitereach Post in Thousand Needles. Ihm geht es um die Flügeltürme der Region und die Sicherheit derjenigen, die sich ihnen nähern, um sie zu untersuchen."},pt={title="Motega Firemane",body="Motega Firemane trabalha na Whitereach Post em Thousand Needles. Ele está preocupado com as wyverns da região e a segurança daqueles que se aproximam delas para estudá-las."},pl={title="Motega Firemane",body="Motega Firemane pracuje w Whitereach Post w Thousand Needles. Interesuje się miejscowymi wiwernami i bezpieczeństwo osób zbliżających się do nich w celu prowadzenia badań."},ru={title="Motega Firemane",body="Motega Firemane работает на Whitereach Post в Thousand Needles. Он беспокоится о вивернах региона и безопасности тех, кто приближается к ним для изучения."},references={["place:thousand-needles"]=true,["place:whitereach-post"]=true}},
    ["person:muigin"] = {title="Muigin",kind="Personaje",aliases={"Muigin"},body="Muigin es un habitante del Refugio de Marshal relacionado con la flora del Cráter de Un'Goro. Su enfrentamiento con Larion convierte las plantas y los inventos de la región en herramientas de una disputa personal.",aliasQuestIDs={},en={title="Muigin",aliases={"Muigin"},body="Muigin is a resident of Marshal's Refuge associated with the plants of Un'Goro Crater. His quarrel with Larion turns the region’s plants and inventions into tools of a personal dispute.",aliasQuestIDs={}},fr={title="Muigin",body="Muigin est un résident de Marshal's Refuge associé aux plantes de Un'Goro Crater. Sa querelle avec Larion transforme les plantes et les inventions de la région en outils d’une dispute personnelle."},de={title="Muigin",body="Muigin wohnt in Marshal's Refuge, der mit den Pflanzen von Un'Goro Crater in Verbindung gebracht wird. Sein Streit mit Larion macht die Pflanzen und Erfindungen der Region zu Werkzeugen eines persönlichen Streits."},pt={title="Muigin",body="Muigin é um residente de Marshal's Refuge associado com as plantas de Un'Goro Crater. Sua briga com o Larion transforma as plantas e invenções da região em ferramentas de uma disputa pessoal."},pl={title="Muigin",body="Muigin jest mieszkańcem Marshal's Refuge związanym z roślinami Un'Goro Crater. Jego kłótnia z postacią Larion zamienia miejscowe rośliny oraz wynalazki w narzędzia osobistego sporu."},ru={title="Muigin",body="Muigin - резидент Marshal's Refuge, связанный с растениями Un'Goro Crater. Его ссора с Larion превращает заводы и изобретения региона в инструменты личного спора."},references={["person:larion"]=true,["place:marshals-refuge"]=true,["place:ungoro-crater"]=true}},
    ["person:mull-thunderhorn"] = {title="Mull Tronacuerno",kind="Personaje",aliases={"Mull","Mull Tronacuerno"},body="Mull Tronacuerno ayuda a proteger las fuentes de agua de Mulgore. Sus tótems de limpieza vinculan los recursos de las criaturas de la llanura con el cuidado espiritual y material de su pueblo.",aliasQuestIDs={},en={title="Mull Thunderhorn",aliases={"Mull","Mull Thunderhorn"},body="Mull Thunderhorn helps protect Mulgore’s water sources. His cleansing totems connect resources from the plains’ creatures with the spiritual and material care of his people.",aliasQuestIDs={}},fr={title="Mull Thunderhorn",body="Mull Thunderhorn aide à protéger les sources d'eau de Mulgore. Ses totems de purification relient les ressources des créatures des plaines aux soins spirituels et matériels de son peuple."},de={title="Mull Thunderhorn",body="Mull Thunderhorn hilft, die Wasserquellen von Mulgore zu schützen. Seine reinigenden Totems verbinden Ressourcen aus den Geschöpfen der Ebene mit der geistigen und materiellen Fürsorge seines Volkes."},pt={title="Mull Thunderhorn",body="O Mull Thunderhorn ajuda a proteger as fontes de água do Mulgore. Seus totens de limpeza conectam recursos das criaturas das planícies com o cuidado espiritual e material de seu povo."},pl={title="Mull Thunderhorn",body="Mull Thunderhorn pomaga chronić źródła wody w Mulgore. Jego totemy oczyszczające łączą zasoby pochodzące ze stworzeń równin z duchową oraz materialną troską o lud."},ru={title="Mull Thunderhorn",body="Mull Thunderhorn помогает защитить источники воды Mulgore. Его очистительные тотемы связывают ресурсы из равнинных созданий с духовным и материальным уходом за его народом."},references={["place:mulgore"]=true}},
    ["person:muln-earthfury"] = {title="Muln Furiatierra",kind="Personaje",aliases={"Muln","Muln Furiatierra"},body="Muln Furiatierra se reúne con el consejo de ancianos del Anillo de la Tierra en la Meseta Miracielos. Se le atribuye sabiduría sobre ruinas ocultas y tierras olvidadas, un conocimiento valioso para comprender artefactos antiguos.",aliasQuestIDs={},en={title="Muln Earthfury",aliases={"Muln","Muln Earthfury"},body="Muln Earthfury meets with the Earthen Ring’s council of elders at Skywatcher Plateau. He is credited with wisdom about buried ruins and forgotten lands, knowledge valuable for understanding ancient artifacts.",aliasQuestIDs={}},fr={title="Muln Earthfury",body="Muln Earthfury rencontre le conseil des aînés de la Earthen Ring au Plateau Skywatcher. Il est crédité de la sagesse sur les ruines enterrées et les terres oubliées, des connaissances précieuses pour comprendre les artefacts anciens."},de={title="Muln Earthfury",body="Muln Earthfury trifft sich mit dem Ältestenrat von Earthen Ring auf dem Skywatcher Plateau. Ihm wird Weisheit über vergrabene Ruinen und vergessenes Land zugeschrieben, ein Wissen, das wertvoll ist, um uralte Artefakte Artefakten zu verstehen."},pt={title="Muln Earthfury",body="Muln Earthfury reúne-se com o conselho de anciãos do Earthen Ring no Planalto Skywatcher. Ele é creditado com sabedoria sobre ruínas enterradas e terras esquecidas, conhecimento valioso para a compreensão de artefatos antigos."},pl={title="Muln Earthfury",body="Muln Earthfury spotyka się z radą starszyzny Earthen Ring na płaskowyżu Skywatcher. Przypisuje mu się mądrość o pogrzebanych ruinach i zapomnianych ziemiach, cenną dla rozumienia pradawnych artefaktów."},ru={title="Muln Earthfury",body="Muln Earthfury встречается с советом старейшин Earthen Ring на плато Skywatcher. Ему приписывают мудрость в отношении захороненных руин и забытых земель, знания, ценные для понимания древних артефактов."},references={["organization:earthen-ring"]=true}},
    ["person:musha"] = {title="Mu'sha",kind="Personaje",aliases={"Mu'sha","Mu’sha"},body="Mu'sha representa la luna en las creencias de los tauren y comparte con An'she la condición de gemelo celeste. Recibe respeto y ofrendas porque la luz de ambos acompaña la vida de su pueblo con orientación y esperanza.",aliasQuestIDs={},en={title="Mu'sha",aliases={"Mu'sha","Mu’sha"},body="Mu'sha represents the moon in tauren belief and shares with An'she the role of celestial twin. Both receive respect and offerings because their light accompanies their people’s lives with guidance and hope.",aliasQuestIDs={}},fr={title="Mu'sha",body="Mu'sha représente la lune dans la croyance tauren et partage avec An'she le rôle de jumeau céleste. Tous deux reçoivent du respect et des offrandes parce que leur lumière accompagne la vie de leur peuple avec guidance et espoir."},de={title="Mu'sha",body="Mu'sha verkörpert den Mond im Tauren-Glauben und teilt sich mit An'she die Rolle des himmlischen Zwillings. Beide erhalten Respekt und Opfer, weil ihr Licht das Leben ihres Volkes mit Führung und Hoffnung begleitet."},pt={title="Mu'sha",body="Mu'sha representa a lua na crença tauren e compartilha com An'she o papel de gêmeo celestial. Ambos recebem respeito e ofertas porque sua luz acompanha a vida de seu povo com orientação e esperança."},pl={title="Mu'sha",body="Mu'sha uosabia księżyc w wierzeniach taurenów i dzieli z An'she rolę niebiańskiego bliźnięcia. Oboje otaczani są szacunkiem i otrzymują dary, ponieważ ich światło towarzyszy życiu ich ludu, niosąc wskazówki i nadzieję."},ru={title="Mu'sha",body="Mu'sha представляет луну в вере быков и разделяет с An'she роль небесного близнеца. Оба получают уважение и подарки, потому что их свет сопровождает жизнь их народа руководством и надеждой."},references={["person:anshe"]=true}},
    ["person:mux-manascambler"] = {title="Mux Cazamaná",kind="Personaje",aliases={"Mux","Mux Cazamaná"},body="Mux Cazamaná es un ingeniero de Gadgetzan interesado en los fenómenos sobrenaturales. Entre sus proyectos hay instrumentos concebidos para investigar a los muertos y comunicarse con ellos.",aliasQuestIDs={},en={title="Mux Manascrambler",aliases={"Mux","Mux Manascrambler"},body="Mux Manascrambler is an engineer in Gadgetzan interested in supernatural phenomena. His projects include instruments designed to investigate the dead and communicate with them.",aliasQuestIDs={}},fr={title="Mux Manascrambler",body="Mux Manascrambler est un ingénieur en Gadgetzan intéressé par les phénomènes surnaturels. Ses projets comprennent des instruments conçus pour enquêter sur les morts et communiquer avec eux."},de={title="Mux Manascrambler",body="Mux Manascrambler ist Ingenieur bei Gadgetzan und interessiert sich für übernatürliche Phänomene. Seine Projekte umfassen Instrumente, die darauf ausgelegt sind, Tote zu untersuchen und mit ihnen zu kommunizieren."},pt={title="Mux Manascrambler",body="Mux Manascrambler é um engenheiro em Gadgetzan interessado em fenômenos sobrenaturais. Seus projetos incluem instrumentos projetados para investigar os mortos e se comunicar com eles."},pl={title="Mux Manascrambler",body="Mux Manascrambler jest inżynierem w Gadgetzan zainteresowanym zjawiskami nadprzyrodzonymi. Jego projekty obejmują przyrządy do badania zmarłych i porozumiewania się z nimi."},ru={title="Mux Manascrambler",body="Mux Manascrambler - инженер из Gadgetzan, интересующийся сверхъестественными явлениями. Его проекты включают в себя инструменты, предназначенные для исследования мертвых и общения с ними."},references={["place:gadgetzan"]=true}},
    ["person:nafien"] = {title="Nafien",kind="Personaje",aliases={"Nafien"},body="Nafien es un guardián fúrbolg de la entrada del Bastión Fauces de Madera en Frondavil. Su aspecto puede intimidar a los visitantes, pero su preocupación principal es defender su hogar de la corrupción.",aliasQuestIDs={},en={title="Nafien",aliases={"Nafien"},body="Nafien is a furbolg guardian at the entrance to Timbermaw Hold in Felwood. His appearance may intimidate visitors, but his main concern is defending his home against corruption.",aliasQuestIDs={}},fr={title="Nafien",body="Nafien est un gardien de furbolg à l'entrée de Timbermaw Hold dans Felwood. Son apparence peut intimider les visiteurs, mais sa principale préoccupation est de défendre sa maison contre la corruption."},de={title="Nafien",body="Nafien ist ein fürchterlicher Wächter am Eingang zu Timbermaw Hold in Felwood. Sein Erscheinen mag Besucher einschüchtern, aber sein Hauptanliegen die Verteidigung seines Hauses gegen Korruption."},pt={title="Nafien",body="Nafien é um guardião furbolg na entrada do Timbermaw Hold em Felwood. Sua aparência pode intimidar os visitantes, mas sua principal preocupação é defender sua casa contra a corrupção."},pl={title="Nafien",body="Nafien jest furbolgim strażnikiem przy wejściu do Timbermaw Hold w Felwood. Wygląd może onieśmielać przybyszów, lecz jego główną troską jest obrona domu przed skażeniem."},ru={title="Nafien",body="Nafien — фурболг, охраняющий вход в Timbermaw Hold в Felwood. Его облик может пугать посетителей, но прежде всего он стремится защитить свой дом от порчи."},references={["organization:timbermaw"]=true,["place:felwood"]=true,["place:timbermaw-hold"]=true}},
    ["person:nalpak"] = {title="Nalpak",kind="Personaje",aliases={"Nalpak"},body="Nalpak trabaja en las Cuevas de los Lamentos y conoce a las extrañas criaturas que las habitan. Considera que sus pellejos pueden tener aplicaciones útiles para la peletería, a pesar del peligro de las bestias.",aliasQuestIDs={},en={title="Nalpak",aliases={"Nalpak"},body="Nalpak works in the Wailing Caverns and knows the strange creatures living there. He believes their hides may have useful applications in leatherworking despite the danger posed by the beasts.",aliasQuestIDs={}},fr={title="Nalpak",body="Nalpak travaille dans le Wailing Caverns et connaît les créatures étranges qui y vivent. Il croit que leurs peaux peuvent avoir des applications utiles dans le travail du cuir malgré le danger posé par les bêtes."},de={title="Nalpak",body="Nalpak arbeitet im Wailing Caverns und kennt die seltsamen Wesen, die dort leben. Er glaubt, dass ihre Häute trotz der von den Tieren ausgehenden Gefahr nützliche Anwendungen in der Lederverarbeitung haben könnten."},pt={title="Nalpak",body="Nalpak trabalha no Wailing Caverns e conhece as estranhas criaturas que vivem lá. Ele acredita que suas peles podem ter aplicações úteis no trabalho de couro, apesar do perigo representado pelos animais."},pl={title="Nalpak",body="Nalpak pracuje w Wailing Caverns i zna zamieszkujące je niezwykłe stworzenia. Uważa, że ich skóry mogą znaleźć użyteczne zastosowanie w kaletnictwie mimo niebezpieczeństwa stwarzanego przez bestie."},ru={title="Nalpak",body="Nalpak работает в Wailing Caverns и знает странных существ, живущих там. Он считает, что их шкуры могут быть полезны в кожевенной промышленности, несмотря на опасность, которую представляют животные."},references={["place:wailing-caverns"]=true}},
    ["person:nara-wildmane"] = {title="Nara Ferocrín",kind="Personaje",aliases={"Nara","Nara Ferocrín"},body="Nara Ferocrín es una tauren de Cima del Trueno con experiencia en el mundo de los sueños. Sus investigaciones la relacionan con la corrupción que afecta a los druidas y con el conocimiento conservado en antiguos vestigios.",aliasQuestIDs={},en={title="Nara Wildmane",aliases={"Nara","Nara Wildmane"},body="Nara Wildmane is a tauren in Thunder Bluff with experience of the dream world. Her investigations connect her with the corruption affecting druids and the knowledge preserved in ancient remains.",aliasQuestIDs={}},fr={title="Nara Wildmane",body="Nara Wildmane est un tauren dans Thunder Bluff avec une expérience du monde du rêve. Ses enquêtes la relient à la corruption des druides et aux connaissances préservées dans les vestiges antiques."},de={title="Nara Wildmane",body="Nara Wildmane ist eine Taure in Thunder Bluff mit Erfahrung in der Traumwelt. Ihre Untersuchungen verbinden sie mit der Korruption der Druiden und dem Wissen, das in antiken Überresten bewahrt wurde."},pt={title="Nara Wildmane",body="Nara Wildmane é um tauren em Thunder Bluff com experiência do mundo dos sonhos. Suas investigações a conectam com a corrupção que afeta os druidas e o conhecimento preservado em restos antigos."},pl={title="Nara Wildmane",body="Nara Wildmane jest taurenką mieszkającą w Thunder Bluff i posiadającą doświadczenie ze światem snów. Jej badania wiążą się ze skażeniem dotykającym druidów oraz wiedzą przechowywaną w pradawnych pozostałościach."},ru={title="Nara Wildmane",body="Nara Wildmane - это таурен в Thunder Bluff с опытом в мире сновидений. Ее расследования связывают ее с коррупцией, поражающей друидов и знаниями, сохранившимися в древних останках."},references={["place:thunder-bluff"]=true},questIDs={[914]=true,[1489]=true,[1490]=true,[2965]=true,[2966]=true,[2967]=true,[2968]=true,[4883]=true,[4987]=true}},
    ["person:narain-soothfancy"] = {title="Narain Sabelotodo",kind="Personaje",aliases={"Narain","Narain Sabelotodo"},body="Narain Sabelotodo es un estudioso de Tanaris al que se recurre para interpretar escritos extraños. Su labor mezcla conocimientos poco comunes con una vida personal y unos métodos de trabajo igualmente peculiares.",aliasQuestIDs={},en={title="Narain Soothfancy",aliases={"Narain","Narain Soothfancy"},body="Narain Soothfancy is a scholar in Tanaris approached to interpret unusual writing. His work combines uncommon knowledge with an equally peculiar personal life and working methods.",aliasQuestIDs={}},fr={title="Narain Soothfancy",body="Narain Soothfancy est un érudit en Tanaris approché pour interpréter une écriture inhabituelle. Son travail combine des connaissances hors du commun avec une vie personnelle et des méthodes de travail tout aussi particulières."},de={title="Narain Soothfancy",body="Narain Soothfancy ist ein Gelehrter in Tanaris näherte sich ungewöhnliche Schrift zu interpretieren. Sein Werk verbindet ungewöhnliches Wissen mit einem ebenso eigentümlichen Privatleben und Arbeitsmethoden."},pt={title="Narain Soothfancy",body="Narain Soothfancy é um estudioso em Tanaris abordado para interpretar a escrita incomum. Seu trabalho combina conhecimento incomum com uma vida pessoal igualmente peculiar e métodos de trabalho."},pl={title="Narain Soothfancy",body="Narain Soothfancy jest uczonym w Tanaris, do którego zwracają się osoby potrzebujące odczytania niezwykłego pisma. Jego praca łączy niepospolitą wiedzę z równie osobliwym życiem prywatnym i metodami działania."},ru={title="Narain Soothfancy",body="Narain Soothfancy - это ученый в Tanaris, к которому обратились с просьбой интерпретировать необычное письмо. Его работа сочетает в себе необычные знания с одинаково своеобразной личной жизнью и методами работы."},references={["place:tanaris"]=true}},
    ["person:naralex"] = {title="Naralex",kind="Personaje",aliases={"Naralex"},body="Naralex es un druida que intentó restaurar la vida de Los Baldíos mediante el Sueño Esmeralda. Sus discípulos permanecen en las Cuevas de los Lamentos, donde lidian con los peligros surgidos de su sueño alterado.",aliasQuestIDs={},en={title="Naralex",aliases={"Naralex"},body="Naralex is a druid who tried to restore life to the Barrens through the Emerald Dream. His disciples remain in the Wailing Caverns, dealing with the dangers arising from his troubled dream.",aliasQuestIDs={}},fr={title="Naralex",body="Naralex est un druide qui a essayé de redonner vie au Barrens via le Emerald Dream. Ses disciples restent dans le Wailing Caverns, traitant des dangers découlant de son rêve troublé."},de={title="Naralex",body="Naralex ist ein Druide, der versucht hat, dem Barrens durch den Emerald Dream wieder Leben einzuhauchen. Seine Jünger bleiben im Wailing Caverns und beschäftigen sich mit den Gefahren, die aus seinem unruhigen Traum entstehen."},pt={title="Naralex",body="Naralex é um druida que tentou restaurar a vida ao Barrens através do Emerald Dream. Seus discípulos permanecem no Wailing Caverns, lidando com os perigos decorrentes de seu sonho conturbado."},pl={title="Naralex",body="Naralex jest druidem, który próbował przywrócić życie regionowi Barrens poprzez Emerald Dream. Jego uczniowie pozostają w Wailing Caverns, mierząc się z niebezpieczeństwami płynącymi z jego niespokojnego snu."},ru={title="Naralex",body="Naralex - это друид, который пытался вернуть жизнь Barrens через Emerald Dream. Его ученики остаются в Wailing Caverns, имея дело с опасностями, возникающими из его тревожного сна."},references={["concept:emerald-dream"]=true,["place:the-barrens"]=true,["place:wailing-caverns"]=true}},
    ["person:nartok"] = {title="Nartok",kind="Personaje",aliases={"Nartok"},body="Nartok es un instructor de brujos de El Cubil, en el Valle de los Retos. Forma parte de los maestros que encauzan el aprendizaje de una disciplina que despierta desconfianza incluso entre los miembros de la Horda.",aliasQuestIDs={},en={title="Nartok",aliases={"Nartok"},body="Nartok is a warlock trainer at the Den in the Valley of Trials. He is one of the teachers guiding a discipline that inspires distrust even among members of the Horde.",aliasQuestIDs={}},fr={title="Nartok",body="Nartok est un entraîneur de démoniste au Den dans le Valley of Trials. Il est l’un des enseignants guidant une discipline qui inspire la méfiance même parmi les membres de la Horde."},de={title="Nartok",body="Nartok ist Hexenmeister bei der Höhle im Valley of Trials. Er ist einer der Lehrer, die eine Disziplin leiten, die selbst bei den Horde-Mitgliedern Misstrauen auslöst."},pt={title="Nartok",body="Nartok é um treinador de bruxos no Den no Valley of Trials. Ele é um dos professores que orienta uma disciplina que inspira desconfiança mesmo entre os membros do Horde."},pl={title="Nartok",body="Nartok jest nauczycielem czarnoksiężników przy Den w Valley of Trials. Należy do nauczycieli dyscypliny budzącej nieufność nawet wśród członków frakcji Horde."},ru={title="Nartok",body="Nartok - тренер-чернокнижник в \" Яме \" в Valley of Trials. Он один из учителей, ведущих дисциплину, которая вызывает недоверие даже среди членов Horde."},references={["organization:horde"]=true,["place:valley-of-trials"]=true}},
    ["person:nat-pagle"] = {title="Nat Pagle",kind="Personaje",aliases={"Nat Pagle"},body="Nat Pagle es un pescador humano del Marjal Revolcafango. Su experiencia se apoya en muchos años de práctica, y considera la paciencia y la determinación elementos esenciales para dominar la pesca.",aliasQuestIDs={},en={title="Nat Pagle",aliases={"Nat","Nat Pagle"},body="Nat Pagle is a human fisherman in Dustwallow Marsh. His experience rests on many years of practice, and he regards patience and determination as essential to mastering fishing.",aliasQuestIDs={}},fr={title="Nat Pagle",body="Nat Pagle est un pêcheur humain dans Dustwallow Marsh. Son expérience repose sur de nombreuses années de pratique, et il considère la patience et la détermination comme essentielles à la maîtrise de la pêche."},de={title="Nat Pagle",body="Nat Pagle ist ein menschlicher Fischer in Dustwallow Marsh. Seine Erfahrung beruht auf jahrelanger Praxis, und er betrachtet Geduld und Entschlossenheit als unverzichtbar, um die Fischerei zu meistern."},pt={title="Nat Pagle",body="Nat Pagle é um pescador humano em Dustwallow Marsh. Sua experiência se baseia em muitos anos de prática, e ele considera a paciência e a determinação como essenciais para dominar a pesca."},pl={title="Nat Pagle",body="Nat Pagle jest ludzkim wędkarzem w Dustwallow Marsh. Jego doświadczenie opiera się na wielu latach praktyki, a cierpliwość i determinację uważa za niezbędne do opanowania wędkarstwa."},ru={title="Nat Pagle",body="Nat Pagle - рыбак-человек в Dustwallow Marsh. Его опыт основан на многолетней практике, и он считает, что терпение и решимость необходимы для овладения рыбалкой."},references={["place:dustwallow-marsh"]=true}},
    ["person:nataka-longhorn"] = {title="Nataka Cuerno Largo",kind="Personaje",aliases={"Nataka","Nataka Cuerno Largo"},body="Nataka Cuerno Largo está destacado en el Campamento del Espíritu Errante, en Desolace. Mantiene contacto con su hermano y recibe información sobre la actividad centaura que afecta a la región.",aliasQuestIDs={},en={title="Nataka Longhorn",aliases={"Nataka","Nataka Longhorn"},body="Nataka Longhorn is stationed at Ghost Walker Post in Desolace. He stays in contact with his brother and receives intelligence about the centaur activity affecting the region.",aliasQuestIDs={}},fr={title="Nataka Longhorn",body="Nataka Longhorn est stationné à Ghost Walker Post dans Desolace. Il reste en contact avec son frère et reçoit des informations sur l’activité centaure qui affecte la région."},de={title="Nataka Longhorn",body="Nataka Longhorn ist bei der Ghost Walker Post in Desolace stationiert. Er bleibt mit seinem Bruder in Kontakt und erhält Informationen über die Aktivitäten der Zentauren in der Region."},pt={title="Nataka Longhorn",body="Nataka Longhorn está estacionado no Ghost Walker Post em Desolace. Ele fica em contato com seu irmão e recebe informações sobre a atividade centauro que afeta a região."},pl={title="Nataka Longhorn",body="Nataka Longhorn stacjonuje w Ghost Walker Post w Desolace. Utrzymuje kontakt z bratem i otrzymuje informacje o działalności centaurów dotykającej regionu."},ru={title="Nataka Longhorn",body="Nataka Longhorn дислоцирована в Пост Призрака Уокера в Desolace. Он поддерживает связь со своим братом и получает информацию о деятельности кентавров, влияющих на регион."},references={["place:desolace"]=true}},
    ["person:natalia-maralith"] = {title="Natalia Mar'alith",kind="Personaje",aliases={"Natalia","Natalia Mar'alith","Natalia Mar’alith"},body="Natalia Mar'alith es una investigadora de Silithus vinculada con los estudios de las colmenas silítidas. Su trabajo preocupa de manera personal al comandante Mar'alith, cuyas responsabilidades militares lo mantienen en el Fuerte Cenarion.",aliasQuestIDs={},en={title="Natalia Mar'alith",aliases={"Natalia","Natalia Mar'alith","Natalia Mar’alith"},body="Natalia Mar'alith is a Silithus researcher connected with studies of the silithid hives. Her work is a personal concern for Commander Mar'alith, whose military duties keep him at Cenarion Hold.",aliasQuestIDs={}},fr={title="Natalia Mar'alith",body="Natalia Mar'alith est un chercheur de Silithus lié aux études des ruches silithid. Son travail est une préoccupation personnelle pour Commander Mar'alith, dont les fonctions militaires le maintiennent à Cenarion Hold."},de={title="Natalia Mar'alith",body="Natalia Mar'alith ist Silithus-Forscherin, die sich mit der Erforschung der Silithidbestände beschäftigt. Ihre Arbeit ist ein persönliches Anliegen für Commander Mar'alith, deren militärische Pflichten ihn bei Cenarion Hold halten."},pt={title="Natalia Mar'alith",body="Natalia Mar'alith é um pesquisador Silithus ligado aos estudos das colmeias silitídicas. Seu trabalho é uma preocupação pessoal para Commander Mar'alith, cujos deveres militares mantê-lo em Cenarion Hold."},pl={title="Natalia Mar'alith",body="Natalia Mar'alith jest badaczką w Silithus zajmującą się ulami silithidów. Jej praca ma osobiste znaczenie dla Commander Mar'alith, którego obowiązki wojskowe zatrzymują w Cenarion Hold."},ru={title="Natalia Mar'alith",body="Natalia Mar'alith - исследователь Silithus, связанный с исследованиями силитидных ульев. Ее работа является личной заботой для Commander Mar'alith, чьи военные обязанности держат его в Cenarion Hold."},references={["person:commander-maralith"]=true,["place:silithus"]=true},questIDs={[8304]=true,[8306]=true,[8309]=true}},
    ["person:nazeer-bloodpike"] = {title="Nazeer Picasangre",kind="Personaje",aliases={"Nazeer","Nazeer Picasangre"},body="Nazeer Picasangre es un maestro de espías orco del Poblado Murohelecho. Sus agentes reúnen información sobre Theramore y las actividades humanas del Marjal Revolcafango.",aliasQuestIDs={},en={title="Nazeer Bloodpike",aliases={"Nazeer","Nazeer Bloodpike"},body="Nazeer Bloodpike is an orc spymaster in Brackenwall Village. His agents gather information about Theramore and human activity in Dustwallow Marsh.",aliasQuestIDs={}},fr={title="Nazeer Bloodpike",body="Nazeer Bloodpike est un maître espion orc dans Brackenwall Village. Ses agents recueillent des informations sur Theramore et l'activité humaine dans Dustwallow Marsh."},de={title="Nazeer Bloodpike",body="Nazeer Bloodpike ist ein Ork-Spion in Brackenwall Village. Seine Agenten sammeln Informationen über Theramore und menschliche Aktivitäten in Dustwallow Marsh."},pt={title="Nazeer Bloodpike",body="Nazeer Bloodpike é um orc spymaster em Brackenwall Village. Seus agentes coletam informações sobre Theramore e atividade humana em Dustwallow Marsh."},pl={title="Nazeer Bloodpike",body="Nazeer Bloodpike jest orczym mistrzem szpiegów w Brackenwall Village. Jego agenci zbierają informacje o Theramore i działalności ludzi w Dustwallow Marsh."},ru={title="Nazeer Bloodpike",body="Nazeer Bloodpike - оркский шпион в Brackenwall Village. Его агенты собирают информацию о Theramore и человеческой деятельности в Dustwallow Marsh."},references={["place:brackenwall-village"]=true,["place:dustwallow-marsh"]=true,["place:theramore"]=true}},
    ["person:nazgrel"] = {title="Nazgrel",kind="Personaje",aliases={"Nazgrel"},body="Nazgrel se encuentra en la Cámara de Thrall en Orgrimmar y atiende las amenazas contra la Horda. Su experiencia lo ha hecho desconfiar de los humanos, aunque antepone la seguridad de su pueblo al orgullo de que sus advertencias resulten ciertas.",aliasQuestIDs={},en={title="Nazgrel",aliases={"Nazgrel"},body="Nazgrel is found in Thrall’s chamber in Orgrimmar and deals with threats against the Horde. Experience has left him distrustful of humans, though he puts his people’s safety ahead of pride in seeing his warnings vindicated.",aliasQuestIDs={}},fr={title="Nazgrel",body="Nazgrel se trouve dans la chambre de Thrall dans Orgrimmar et traite des menaces contre le Horde. L’expérience l’a laissé méfiant envers les humains, bien qu’il mette la sécurité de son peuple avant la fierté de voir ses avertissements confirmés."},de={title="Nazgrel",body="Nazgrel wird in Thrall \"Kammer in Orgrimmar gefunden und muss sich mit Drohungen gegen den Horde auseinandersetzen. Die Erfahrung hat ihn misstrauisch gegenüber den Menschen gemacht, obwohl er die Sicherheit seines Volkes über den Stolz stellt, wenn er seine Warnungen bestätigt sieht."},pt={title="Nazgrel",body="O Nazgrel é encontrado na câmara do Thrall no Orgrimmar e lida com ameaças contra o Horde. A experiência o deixou desconfiado dos seres humanos, embora ele coloque a segurança de seu povo à frente do orgulho de ver seus avisos vindicados."},pl={title="Nazgrel",body="Nazgrel przebywa w komnacie przywódcy Thrall w Orgrimmar i zajmuje się zagrożeniami wobec frakcji Horde. Doświadczenie uczyniło go nieufnym wobec ludzi, lecz bezpieczeństwo ludu stawia ponad dumę z potwierdzenia własnych ostrzeżeń."},ru={title="Nazgrel",body="Nazgrel находится в Thrall s камере в Orgrimmar и занимается угрозами против Horde. Опыт побудил его не доверять людям, хотя он ставит безопасность своего народа выше гордости, видя, что его предупреждения подтверждаются."},references={["organization:horde"]=true,["person:thrall"]=true,["place:orgrimmar"]=true}},
    ["person:neeru-fireblade"] = {title="Neeru Hojafuego",kind="Personaje",aliases={"Neeru","Neeru Hojafuego"},body="Neeru Hojafuego es un brujo del Circo de las Sombras en Orgrimmar. Se presenta como un investigador de lo oculto capaz de estudiar instrumentos demoníacos y afirma usar sus conocimientos contra los demonios.",aliasQuestIDs={},en={title="Neeru Fireblade",aliases={"Neeru","Neeru Fireblade"},body="Neeru Fireblade is a warlock in Orgrimmar’s Cleft of Shadow. He presents himself as an occult investigator capable of studying demonic instruments and claims to use his knowledge against demons.",aliasQuestIDs={}},fr={title="Neeru Fireblade",body="Neeru Fireblade est un démoniste dans Orgrimmar’s Cleft of Shadow. Il se présente comme un investigateur occulte capable d'étudier les instruments démoniaques et prétend utiliser ses connaissances contre les démons."},de={title="Neeru Fireblade",body="Neeru Fireblade ist in Orgrimmar’s Cleft of Shadow ein Hexenmeister. Er präsentiert sich als okkultischer Ermittler, der dämonische Instrumente studieren kann und behauptet, sein Wissen gegen Dämonische Dämonen einzusetzen."},pt={title="Neeru Fireblade",body="Neeru Fireblade é um bruxo em Orgrimmar’s Cleft of Shadow. Ele se apresenta como um investigador oculto capaz de estudar instrumentos demoníacos e alega usar seu conhecimento contra demônios."},pl={title="Neeru Fireblade",body="Neeru Fireblade jest czarnoksiężnikiem w miejscu zwanym Orgrimmar’s Cleft of Shadow. Przedstawia się jako badacz okultyzmu potrafiący analizować demoniczne przyrządy i twierdzi, że wykorzystuje wiedzę przeciw demonom."},ru={title="Neeru Fireblade",body="Neeru Fireblade - чернокнижник в Orgrimmar’s Cleft of Shadow. Он представляет себя исследователем оккультизма, способным изучать инструменты демонов и утверждает, что использует свои знания против демонов."},references={["place:orgrimmar"]=true}},
    ["person:nerlokh"] = {title="Nerlokh",kind="Personaje",aliases={"Nerlokh"},body="Nerlokh es un explorador Gelkis destinado cerca del Valle de los Huesos. Su vigilancia busca aclarar los movimientos de los Magram y preservar la seguridad de su propio clan.",aliasQuestIDs={},en={title="Nerlokh",aliases={"Nerlokh"},body="Nerlokh is a Gelkis scout stationed near the Valley of Bones. His watch seeks to explain Magram movements and preserve the safety of his own clan.",aliasQuestIDs={}},fr={title="Nerlokh",body="Nerlokh est un éclaireur Gelkis stationné près du Valley of Bones. Sa montre cherche à expliquer les mouvements de Magram et à préserver la sécurité de son propre clan."},de={title="Nerlokh",body="Nerlokh ist Pfadfinder Gelkis, der in der Nähe des Valley of Bones stationiert ist. Seine Uhr versucht, Magram Bewegungen zu erklären und die Sicherheit seines eigenen Clans zu wahren."},pt={title="Nerlokh",body="Nerlokh é um olheiro Gelkis estacionado perto do Valley of Bones. Seu relógio procura explicar os movimentos Magram e preservar a segurança de seu próprio clã."},pl={title="Nerlokh",body="Nerlokh jest zwiadowcą klanu Gelkis stacjonującym w pobliżu Valley of Bones. Jego obserwacja służy zrozumieniu ruchów klanu Magram i zachowaniu bezpieczeństwa własnego klanu."},ru={title="Nerlokh",body="Nerlokh - это разведчик Gelkis, дислоцированный возле Valley of Bones. Его часы пытаются объяснить движения Magram и сохранить безопасность его собственного клана."},references={["organization:gelkis"]=true,["organization:magram"]=true,["place:valley-of-bones"]=true}},
    ["person:nessa-shadowsong"] = {title="Nessa Cantosombrío",kind="Personaje",aliases={"Nessa","Nessa Cantosombrío"},body="Nessa Cantosombrío organiza envíos desde la Aldea Rut'theran. Sus mercancías recorren las rutas de hipogrifos y barcos que mantienen conectadas las comunidades de Teldrassil y Costa Oscura.",aliasQuestIDs={},en={title="Nessa Shadowsong",aliases={"Nessa","Nessa Shadowsong"},body="Nessa Shadowsong organizes shipments from Rut'theran Village. Her goods travel the hippogryph and ferry routes keeping the communities of Teldrassil and Darkshore connected.",aliasQuestIDs={}},fr={title="Nessa Shadowsong",body="Nessa Shadowsong organise des expéditions de Rut'theran Village. Ses marchandises parcourent les routes de l'hippogryphe et du ferry en gardant les communautés de Teldrassil et Darkshore connectées."},de={title="Nessa Shadowsong",body="Nessa Shadowsong organisiert Sendungen von Rut'theran Village. Ihre Güter reisen über die Flussprophippogryphen und Fährrouten und halten die Gemeinschaften von Teldrassil und Darkshore verbunden."},pt={title="Nessa Shadowsong",body="Nessa Shadowsong organiza remessas de Rut'theran Village. Suas mercadorias viajam pelas rotas de hippogryph e ferry mantendo as comunidades de Teldrassil e Darkshore conectadas."},pl={title="Nessa Shadowsong",body="Nessa Shadowsong organizuje przesyłki z Rut'theran Village. Jej towary podróżują szlakami hipogryfów i promów łączącymi społeczności Teldrassil oraz Darkshore."},ru={title="Nessa Shadowsong",body="Nessa Shadowsong организует поставки из Rut'theran Village. Ее товары путешествуют по гиппогрифным и паромным маршрутам, соединяя сообщества Teldrassil и Darkshore."},references={["place:darkshore"]=true,["place:ruttheran-village"]=true,["place:teldrassil"]=true}},
    ["person:niby-the-almighty"] = {title="Niby el Todopoderoso",kind="Personaje",aliases={"Niby","Niby el Todopoderoso"},body="Niby el Todopoderoso es un brujo de Frondavil acompañado por el diablillo Diblis. Sus actividades de invocación lo sitúan entre los practicantes que buscan poder demoníaco en un bosque ya marcado por la corrupción.",aliasQuestIDs={},en={title="Niby the Almighty",aliases={"Niby","Niby the Almighty"},body="Niby the Almighty is a warlock in Felwood accompanied by the imp Impsy. His summoning work places him among practitioners seeking demonic power in a forest already marked by corruption.",aliasQuestIDs={}},fr={title="Niby the Almighty",body="Niby the Almighty est un démoniste en Felwood accompagné de l'imp Impsy. Son travail d’invocation le place parmi les pratiquants en quête de pouvoir démoniaque dans une forêt déjà marquée par la corruption."},de={title="Niby the Almighty",body="Niby the Almighty ist in Felwood ein Hexenmeister in Begleitung des Wichtelmännlichen Impsy. Seine Berufungsarbeit stellt ihn unter Praktiker, die dämonische Macht in einem Wald suchen, der bereits von Korruption gekennzeichnet ist."},pt={title="Niby the Almighty",body="Niby the Almighty é um bruxo no Felwood acompanhado pelo imp Impsy. Seu trabalho de convocação o coloca entre os praticantes que buscam poder demoníaco em uma floresta já marcada pela corrupção."},pl={title="Niby the Almighty",body="Niby the Almighty jest czarnoksiężnikiem w Felwood, któremu towarzyszy chochlik Impsy. Praca nad przywołaniami stawia go wśród adeptów szukających demonicznej mocy w lesie już naznaczonym skażeniem."},ru={title="Niby the Almighty",body="Niby the Almighty - это чернокнижник в Felwood, сопровождаемый импом Impsy. Его призывная работа помещает его среди практикующих, ищущих демоническую силу в лесу, уже отмеченном порчей."},references={["person:impsy"]=true,["place:felwood"]=true}},
    ["person:nixx-sprocketspring"] = {title="Nixx Muellepiñón",kind="Personaje",aliases={"Nixx","Nixx Muellepiñón"},body="Nixx Muellepiñón enseña ingeniería goblin en Gadgetzan. Su especialidad destaca el uso de explosivos potentes y aparatos capaces de convertir una idea arriesgada en una ventaja técnica.",aliasQuestIDs={},en={title="Nixx Sprocketspring",aliases={"Nixx","Nixx Sprocketspring"},body="Nixx Sprocketspring teaches goblin engineering in Gadgetzan. His specialty emphasizes powerful explosives and devices capable of turning a risky idea into a technical advantage.",aliasQuestIDs={}},fr={title="Nixx Sprocketspring",body="Nixx Sprocketspring enseigne l'ingénierie des gobelins dans Gadgetzan. Sa spécialité met l’accent sur les explosifs puissants et les dispositifs capables de transformer une idée risquée en avantage technique."},de={title="Nixx Sprocketspring",body="Nixx Sprocketspring unterrichtet Koboldtechnik bei Gadgetzan. Seine Spezialität sind leistungsstarke Sprengstoffe und Geräte, die eine riskante Idee in einen technischen Vorteil verwandeln können."},pt={title="Nixx Sprocketspring",body="Nixx Sprocketspring ensina engenharia goblin em Gadgetzan. Sua especialidade enfatiza explosivos poderosos e dispositivos capazes de transformar uma ideia arriscada em uma vantagem técnica."},pl={title="Nixx Sprocketspring",body="Nixx Sprocketspring uczy goblińskiej inżynierii w Gadgetzan. Specjalizuje się w potężnych materiałach wybuchowych i urządzeniach zdolnych zamienić ryzykowny pomysł w przewagę techniczną."},ru={title="Nixx Sprocketspring",body="Nixx Sprocketspring преподает инженерное искусство гоблинов в Gadgetzan. Его специальность - мощные взрывчатые вещества и устройства, способные превратить рискованную идею в техническое преимущество."},references={["place:gadgetzan"]=true}},
    ["person:nogg"] = {title="Nogg",kind="Personaje",aliases={"Nogg"},body="Nogg es un ingeniero de Orgrimmar atento a los avances de la tecnología gnómica. Su interés por planos y plataformas rivales muestra una competencia en la que obtener información técnica puede ser tan importante como construir máquinas.",aliasQuestIDs={},en={title="Nogg",aliases={"Nogg"},body="Nogg is an Orgrimmar engineer attentive to advances in gnomish technology. His interest in rival plans and rigs shows a competition in which obtaining technical information can matter as much as building machines.",aliasQuestIDs={}},fr={title="Nogg",body="Nogg est un ingénieur Orgrimmar attentif aux avancées de la technologie gnomish. Son intérêt pour les plans et les plates-formes rivales montre une compétition dans laquelle l'obtention d'informations techniques peut avoir autant d'importance que la construction de machines."},de={title="Nogg",body="Nogg ist ein Ingenieur von Orgrimmar, der auf die Fortschritte in der gnomischen Technologie achtet. Sein Interesse an konkurrierenden Plänen und Anlagen zeigt einen Wettbewerb, bei dem die Beschaffung technischer Informationen ebenso wichtig sein kann wie der Bau von Maschinen."},pt={title="Nogg",body="Nogg é um engenheiro Orgrimmar atento aos avanços na tecnologia gnomosa. Seu interesse em planos e plataformas rivais mostra uma competição na qual a obtenção de informações técnicas pode importar tanto quanto máquinas de construção."},pl={title="Nogg",body="Nogg jest inżynierem w Orgrimmar śledzącym postępy gnomiej technologii. Zainteresowanie planami i urządzeniami rywali ukazuje współzawodnictwo, w którym zdobywanie informacji technicznych bywa równie ważne jak budowanie maszyn."},ru={title="Nogg",body="Nogg - инженер Orgrimmar, внимательный к достижениям в гномной технологии. Его интерес к конкурирующим планам и установкам показывает конкуренцию, в которой получение технической информации может иметь такое же значение, как и создание машин."},references={["place:orgrimmar"]=true}},
    ["person:noggle-ficklespragg"] = {title="Noggle",kind="Personaje",aliases={"Noggle"},body="Noggle recolecta hierbas exóticas para los alquimistas del Fuerte Cenarion. Su oficio exige internarse en el desierto de Silithus, donde los recursos útiles se encuentran junto a animales venenosos.",aliasQuestIDs={},en={title="Noggle Ficklespragg",aliases={"Noggle","Noggle Ficklespragg"},body="Noggle Ficklespragg gathers exotic herbs for the alchemists at Cenarion Hold. His trade requires venturing into the Silithus desert, where useful resources are found beside venomous animals.",aliasQuestIDs={}},fr={title="Noggle Ficklespragg",body="Noggle Ficklespragg rassemble des herbes exotiques pour les alchimistes à Cenarion Hold. Son métier exige de s'aventurer dans le désert Silithus, où des ressources utiles se trouvent à côté d'animaux venimeux."},de={title="Noggle Ficklespragg",body="Noggle Ficklespragg sammelt exotische Kräuter für die Alchemisten bei Cenarion Hold. Sein Handwerk erfordert den Ausflug in die Silithus-Wüste, wo neben giftigen Tieren nützliche Ressourcen zu finden sind."},pt={title="Noggle Ficklespragg",body="Noggle Ficklespragg reúne ervas exóticas para os alquimistas no Cenarion Hold. Seu comércio requer aventurar-se no deserto de Silithus, onde recursos úteis são encontrados ao lado de animais venenosos."},pl={title="Noggle Ficklespragg",body="Noggle Ficklespragg zbiera egzotyczne zioła dla alchemików w Cenarion Hold. Jego zajęcie wymaga wypraw na pustynię Silithus, gdzie przydatne zasoby występują obok jadowitych zwierząt."},ru={title="Noggle Ficklespragg",body="Noggle Ficklespragg собирает экзотические травы для алхимиков в Cenarion Hold. Его профессия требует отвлечения в пустыне Silithus, где полезные ресурсы находятся рядом с ядовитыми животными."},references={["place:cenarion-hold"]=true,["place:silithus"]=true}},
    ["person:nyrill"] = {title="Nyrill",kind="Personaje",aliases={"Nyrill"},body="Nyrill facilita el regreso desde la torre de Azshara hasta el campamento de Sanath. Sus habilidades de transporte conectan el retiro de su maestro con quienes se acercan a ese rincón apartado de la región.",aliasQuestIDs={},en={title="Nyrill",aliases={"Nyrill"},body="Nyrill provides a return journey from the Azshara tower to Sanath’s camp. These transportation skills connect the master’s retreat with visitors reaching that remote corner of the region.",aliasQuestIDs={}},fr={title="Nyrill",body="Nyrill offre un voyage de retour de la tour Azshara au camp de Sanath. Ces compétences de transport relient la retraite du maître avec les visiteurs atteignant ce coin reculé de la région."},de={title="Nyrill",body="Nyrill bietet eine Rückfahrt vom Azshara-Turm zum Sanath-Lager an. Diese Transportfähigkeiten verbinden den Rückzugsort des Meisters mit Besuchern, die diesen entlegenen Winkel der Region erreichen."},pt={title="Nyrill",body="Nyrill fornece uma viagem de retorno da torre Azshara para o acampamento de Sanath. Essas habilidades de transporte conectam o retiro do mestre com os visitantes que chegam a esse canto remoto da região."},pl={title="Nyrill",body="Nyrill zapewnia podróż powrotną z wieży w regionie Azshara do obozu postaci Sanath. Te umiejętności transportowe łączą schronienie mistrza z przybyszami docierającymi do odległego zakątka regionu."},ru={title="Nyrill",body="Nyrill обеспечивает обратное путешествие от башни Azshara до лагеря Sanath s. Эти транспортные средства связывают место отдыха мастеров с посетителями, которые приезжают в этот отдаленный уголок региона."},references={["person:sanath-limyo"]=true}},
    ["person:oben-rageclaw"] = {title="Oben Garrafuria",kind="Personaje",aliases={"Oben","Oben Garrafuria"},body="Oben Garrafuria es un druida asociado al Túmulo de Ban'ethil. Su conocimiento abarca la relación entre el cuerpo durmiente y el espíritu en el Sueño Esmeralda, un vínculo que puede ser alterado por la magia de otros.",aliasQuestIDs={},en={title="Oben Rageclaw",aliases={"Oben","Oben Rageclaw"},body="Oben Rageclaw is a druid associated with Ban'ethil Barrow Den. His knowledge includes the relationship between a sleeping body and its spirit in the Emerald Dream, a bond that others’ magic can disturb.",aliasQuestIDs={}},fr={title="Oben Rageclaw",body="Oben Rageclaw est un druide associé à Ban'ethil Barrow Den. Ses connaissances incluent la relation entre un corps endormi et son esprit dans le Emerald Dream, un lien que la magie des autres peut perturber."},de={title="Oben Rageclaw",body="Oben Rageclaw ist ein Druide, der mit Ban'ethil Barrow Den in Verbindung gebracht wird. Zu seinen Kenntnissen gehört die Beziehung zwischen einem schlafenden Körper und seinem Geist im Emerald Dream, eine Verbindung, die durch die durch die Magie anderer stören kann."},pt={title="Oben Rageclaw",body="Oben Rageclaw é um druida associado ao Ban'ethil Barrow Den. Seu conhecimento inclui a relação entre um corpo adormecido e seu espírito no Emerald Dream, um vínculo que a magia dos outros pode perturbar."},pl={title="Oben Rageclaw",body="Oben Rageclaw jest druidem związanym z Ban'ethil Barrow Den. Jego wiedza obejmuje relację śpiącego ciała z jego duchem w Emerald Dream, więź, którą cudza magia może zakłócić."},ru={title="Oben Rageclaw",body="Oben Rageclaw - это друид, связанный с Ban'ethil Barrow Den. Его знания включают в себя связь между спящим телом и его духом в Emerald Dream, связи, которые другие могут нарушить."},references={["concept:emerald-dream"]=true,["place:banethil-barrow-den"]=true}},
    ["person:ogron"] = {title="Ogron",kind="Personaje",aliases={"Ogron"},body="Ogron trabaja con los habitantes del Poblado Murohelecho para investigar sucesos del pantano. Su capacidad para localizar a personas escondidas resulta útil cuando las pistas llevan lejos de los caminos.",aliasQuestIDs={},en={title="Ogron",aliases={"Ogron"},body="Ogron works with Brackenwall Village’s residents to investigate events in the marsh. His ability to locate hidden people proves useful when clues lead far from the roads.",aliasQuestIDs={}},fr={title="Ogron",body="Ogron travaille avec les résidents de Brackenwall Village pour enquêter sur les événements dans le marais. Sa capacité à localiser des personnes cachées s'avère utile lorsque des indices mènent loin des routes."},de={title="Ogron",body="Ogron arbeitet mit den Bewohnern von Brackenwall Village zusammen, um die Geschehnisse im Sumpfgebiet zu untersuchen. Seine Fähigkeit, versteckte Personen zu finden, erweist sich als nützlich, wenn Hinweise weit weg von den Straßen führen."},pt={title="Ogron",body="Ogron trabalha com os residentes de Brackenwall Village para investigar eventos no pântano. Sua capacidade de localizar pessoas escondidas prova útil quando pistas levam longe das estradas."},pl={title="Ogron",body="Ogron współpracuje z mieszkańcami Brackenwall Village przy badaniu wydarzeń na bagnach. Zdolność odnajdywania ukrytych osób okazuje się przydatna, gdy wskazówki prowadzą daleko od dróg."},ru={title="Ogron",body="Ogron работает с жителями Brackenwall Village s, чтобы расследовать события в болоте. Его способность находить скрытых людей оказывается полезной, когда улицы уходят далеко от дорог."},references={["place:brackenwall-village"]=true}},
    ["person:ogtinc"] = {title="Ogtinc",kind="Personaje",aliases={"Ogtinc"},body="Ogtinc es un guía de cazadores que vive en los precipicios de Azshara. Sus enseñanzas utilizan las cualidades de las criaturas locales para poner a prueba la fuerza y la resistencia de sus alumnos.",aliasQuestIDs={},en={title="Ogtinc",aliases={"Ogtinc"},body="Ogtinc is a guide to hunters living on Azshara’s cliffs. His teaching uses the qualities of local creatures to test his students’ strength and endurance.",aliasQuestIDs={}},fr={title="Ogtinc",body="Ogtinc est un guide pour les chasseurs vivant sur les falaises de Azshara. Son enseignement utilise les qualités des créatures locales pour tester la force et l’endurance de ses élèves."},de={title="Ogtinc",body="Ogtinc ist ein Führer zu den Jägern, die auf Felsen von Azshara 's leben. Sein Unterricht nutzt die Qualitäten lokaler Lebewesen, um die Stärke und Ausdauer seiner Schüler auf die Probe zu stellen."},pt={title="Ogtinc",body="Ogtinc é um guia para caçadores que vivem nas falésias de Azshara. Seu ensino usa as qualidades das criaturas locais para testar a força e a resistência de seus alunos."},pl={title="Ogtinc",body="Ogtinc jest przewodnikiem łowców mieszkającym na klifach regionu Azshara. W nauczaniu wykorzystuje cechy miejscowych stworzeń, by sprawdzać siłę i wytrzymałość uczniów."},ru={title="Ogtinc",body="Ogtinc - это руководство для охотников, живущих на скалах Azshara s. Его учение использует качества местных существ, чтобы испытать силу и выносливость учеников."},references={["place:azshara"]=true}},
    ["person:ogunaro-wolfrunner"] = {title="Ogunaro Correlobo",kind="Personaje",aliases={"Ogunaro","Ogunaro Correlobo"},body="Ogunaro dirige las perreras de Orgrimmar y ofrece lobos de monta. Entre sus animales figuran lobos pardos, grises y de bosque, compañeros de viaje que mantienen cercana la relación de los orcos con los lobos.",aliasQuestIDs={},en={title="Ogunaro Wolfrunner",aliases={"Ogunaro","Ogunaro Wolfrunner"},body="Ogunaro is Orgrimmar’s kennel master and supplies riding wolves. His animals include brown, gray, and timber wolves, traveling companions that keep the orcs’ connection with wolves close.",aliasQuestIDs={}},fr={title="Ogunaro Wolfrunner",body="Ogunaro est le maître de chenil de Orgrimmar et fournit des loups à cheval. Ses animaux comprennent des loups bruns, gris et en bois, compagnons de voyage qui gardent la connexion des orcs avec les loups à proximité."},de={title="Ogunaro Wolfrunner",body="Ogunaro ist Orgrimmar 'Zwingermeister und versorgt Reitwölfe. Zu seinen Tieren gehören Braun-, Grau- und Holzwölfe - Reisegefährten, die die die den Kontakt der Orks zu Wölfen halten."},pt={title="Ogunaro Wolfrunner",body="Ogunaro é o mestre de canil e suprimentos da Orgrimmar que monta lobos. Seus animais incluem lobos marrons, cinzentos e madeireiros, companheiros de viagem que mantêm a conexão dos orcs com lobos perto."},pl={title="Ogunaro Wolfrunner",body="Ogunaro prowadzi wilczarnię w Orgrimmar i dostarcza wilki do jazdy. Wśród jego zwierząt są wilki brązowe, szare i leśne, towarzysze podróży podtrzymujący bliską więź orków z wilkami."},ru={title="Ogunaro Wolfrunner",body="Ogunaro - это Orgrimmar, хозяин питомника и снабжение для верховой езды на волках. Его животные включают коричневых, серых и деревянных волков, путешествующих товарищей, которые поддерживают близкую связь орков с волками."},references={["place:orgrimmar"]=true}},
    ["person:olariaan-swiftburn"] = {title="Olariaan Fuegoveloz",kind="Personaje",aliases={"Olariaan","Olariaan Fuegoveloz"},body="Olariaan Fuegoveloz es un shen'dorei de los Formavientos con una afinidad especial por el fuego. Se encuentra en el Santuario de las Llamas, en los Bajíos Ventobaya, al oeste de Valanaar. Su enseñanza representa la relación de los Formavientos con otros espíritus elementales además del viento.",aliasQuestIDs={},en={title="Olariaan Swiftburn",aliases={"Olariaan","Olariaan Swiftburn"},body="Olariaan Swiftburn is a shen'dorei Windshaper with a special affinity for fire. He can be found at the Shrine of Flames in the Gustberry Lowlands, west of Valanaar. His teaching represents the Windshapers’ relationship with elemental spirits beyond the wind.",aliasQuestIDs={}},fr={title="Olariaan Swiftburn",body="Olariaan Swiftburn est un shen'dorei Windshaper avec une affinité particulière pour le feu. Il peut être trouvé au Shrine of Flames dans le Gustberry Lowlands, à l'ouest de Valanaar. Son enseignement représente la relation de la Windshapers avec les esprits élémentaires au-delà du vent."},de={title="Olariaan Swiftburn",body="Olariaan Swiftburn ist ein shen 'dorei Windshaper mit einer besonderen Affinität zum Feuer. Er ist im Shrine of Flames im Gustberry Lowlands westlich von Valanaar zu finden. Seine Lehre repräsentiert die Beziehung des Windshapers zu Elementaren Geistern jenseits des Windes Winds."},pt={title="Olariaan Swiftburn",body="Olariaan Swiftburn é um shen'dorei Windshaper com uma afinidade especial para o fogo. Ele pode ser encontrado no Shrine of Flames em Gustberry Lowlands, a oeste de Valanaar. Seu ensino representa a relação do Windshapers com espíritos elementais além do vento."},pl={title="Olariaan Swiftburn",body="Olariaan Swiftburn jest shen'dorei Windshaper o szczególnej więzi z ogniem. Przebywa przy Shrine of Flames w Gustberry Lowlands na zachód od Valanaar. Jego nauki reprezentują relację społeczności znanej jako the Windshapers z duchami żywiołów innymi niż wiatr."},ru={title="Olariaan Swiftburn",body="Olariaan Swiftburn - это шен'дорей Windshaper с особой привязанностью к огню. Его можно найти в Shrine of Flames в Gustberry Lowlands, к западу от Valanaar. Его учение представляет собой Windshapers  отношения с элементарными духами за ветром."},references={["organization:windshapers"]=true,["place:gustberry-lowlands"]=true,["place:shrine-of-flames"]=true,["place:valanaar"]=true}},
    ["person:onu"] = {title="Onus",kind="Personaje",aliases={"Onu","Onus"},body="Onus es un Anciano del conocimiento del Páramo de los Ancianos, en Costa Oscura. Los habitantes de la región recurren a su sabiduría para comprender fenómenos ligados al bosque y a sus antiguas ruinas.",aliasQuestIDs={},en={title="Onu",aliases={"Onu"},body="Onu is an Ancient of Lore in the Grove of the Ancients in Darkshore. The region’s inhabitants seek his wisdom to understand phenomena connected to the forest and its ancient ruins.",aliasQuestIDs={}},fr={title="Onu",body="Onu est un ancien de la tradition dans le bosquet des anciens dans Darkshore. Les habitants de la région cherchent sa sagesse pour comprendre les phénomènes liés à la forêt et à ses ruines antiques."},de={title="Onu",body="Onu ist ein Uralter von Lore im Hain Darkshore. Die Bewohner der Region suchen seine Weisheit, um Phänomene zu verstehen, die mit dem Wald und seinen uralten Ruinen verbunden sind."},pt={title="Onu",body="Onu é um Ancião de Lore no Bosque dos Antigos em Darkshore. Os habitantes da região buscam sua sabedoria para entender os fenômenos conectados à floresta e suas ruínas antigas."},pl={title="Onu",body="Onu jest pradawnym strażnikiem wiedzy w gaju pradawnych w Darkshore. Mieszkańcy regionu szukają w jego mądrości pomocy w zrozumieniu zjawisk związanych z lasem oraz pradawnymi ruinami."},ru={title="Onu",body="Onu - Древний из легенд в роще Древних в Darkshore. Жители региона ищут его мудрость, чтобы понять явления, связанные с лесом и его древними руинами."},references={["place:darkshore"]=true}},
    ["person:orendil"] = {title="Orendil",kind="Personaje",aliases={"Orendil"},body="Orendil estudia las plantas curativas de Vallefresno. Su conocimiento del cabello de Bathran incluye la posibilidad de tratar males del espíritu, además de las dolencias del cuerpo.",aliasQuestIDs={},en={title="Orendil",aliases={"Orendil"},body="Orendil studies Ashenvale’s healing plants. His knowledge of Bathran’s Hair includes the possibility of treating ailments of the spirit as well as those of the body.",aliasQuestIDs={}},fr={title="Orendil",body="Orendil étudie les plantes curatives de Ashenvale. Sa connaissance de Bathran’s Hair comprend la possibilité de traiter les maux de l'esprit ainsi que ceux du corps."},de={title="Orendil",body="Orendil studiert Ashenvale 'Heilpflanzen. Zu seinen Kenntnissen über Bathran’s Hair gehört auch die Möglichkeit, Krankheiten des Geistes und des Körpers zu behandeln."},pt={title="Orendil",body="Orendil estuda as plantas curativas de Ashenvale. Seu conhecimento de Bathran’s Hair inclui a possibilidade de tratar doenças do espírito, bem como as do corpo."},pl={title="Orendil",body="Orendil bada lecznicze rośliny Ashenvale. Jego wiedza o Bathran’s Hair obejmuje możliwość leczenia dolegliwości ducha, a nie tylko ciała."},ru={title="Orendil",body="Orendil изучает лечебные растения Ashenvale. Его знания о Bathran’s Hair включают возможность лечения недугов духа, а также тех, которые находятся в теле."},references={["place:ashenvale"]=true}},
    ["person:orenthil-whisperwind"] = {title="Orenthil Susurravientos",kind="Personaje",aliases={"Orenthil","Orenthil Susurravientos"},body="Orenthil Susurravientos recibe visitantes en Cañada Umbría y entrega pequeños compañeros de viaje. Su bienvenida expresa una faceta tranquila del comienzo de una aventura, junto a los desafíos que esperan fuera del hogar.",aliasQuestIDs={},en={title="Orenthil Whisperwind",aliases={"Orenthil","Orenthil Whisperwind"},body="Orenthil Whisperwind welcomes visitors in Shadowglen and provides small traveling companions. His welcome reflects a quieter side of beginning an adventure alongside the challenges waiting beyond home.",aliasQuestIDs={}},fr={title="Orenthil Whisperwind",body="Orenthil Whisperwind accueille les visiteurs dans Shadowglen et fournit de petits compagnons de voyage. Son accueil reflète un côté plus calme de commencer une aventure aux côtés des défis qui attendent au-delà de la maison."},de={title="Orenthil Whisperwind",body="Orenthil Whisperwind begrüßt die Besucher in Shadowglen und stellt kleine Reisebegleiter zur Verfügung. Seine Begrüßung spiegelt eine ruhigere Seite des Beginns eines Abenteuers neben den Herausforderungen wider, die jenseits der Heimat warten."},pt={title="Orenthil Whisperwind",body="Orenthil Whisperwind recebe visitantes em Shadowglen e fornece pequenos companheiros de viagem. Sua recepção reflete um lado mais tranquilo de começar uma aventura ao lado dos desafios que esperam além de casa."},pl={title="Orenthil Whisperwind",body="Orenthil Whisperwind wita gości w Shadowglen i zapewnia małych towarzyszy podróży. Jego gościnność ukazuje spokojniejszą stronę rozpoczynania przygody obok wyzwań czekających poza domem."},ru={title="Orenthil Whisperwind",body="Orenthil Whisperwind приветствует посетителей в Shadowglen и предоставляет маленьких спутников. Его приветствие отражает более спокойную сторону начала приключения наряду с проблемами, ожидающими за пределами дома."},references={["place:shadowglen"]=true}},
    ["person:orgrul"] = {title="Orgrul",kind="Personaje",aliases={"Orgrul"},body="Orgrul es un centauro Magram establecido cerca del Valle de los Huesos en Desolace. Su actividad está vinculada al interés de su clan por la nigromancia y por los recursos de las tierras malditas.",aliasQuestIDs={},en={title="Orgrul",aliases={"Orgrul"},body="Orgrul is a Magram centaur established near the Valley of Bones in Desolace. His activities are tied to his clan’s interest in necromancy and the resources of the cursed lands.",aliasQuestIDs={}},fr={title="Orgrul",body="Orgrul est un centaure Magram établi près du Valley of Bones dans Desolace. Ses activités sont liées à l’intérêt de son clan pour la nécromancie et les ressources des terres maudites."},de={title="Orgrul",body="Orgrul ist ein Magram-Zentaur, der in der Nähe des Valley of Bones in Desolace angesiedelt ist. Seine Aktivitäten sind an das Interesse seines Clans an Totenbeschwörung und den Ressourcen des verfluchten Landes geknüpft."},pt={title="Orgrul",body="Orgrul é um centauro Magram estabelecido perto do Valley of Bones em Desolace. Suas atividades estão ligadas ao interesse de seu clã em necromancia e os recursos das terras amaldiçoadas."},pl={title="Orgrul",body="Orgrul jest centaurem klanu Magram osiadłym przy Valley of Bones w Desolace. Jego działania wiążą się z zainteresowaniem klanu nekromancją oraz zasobami przeklętych ziem."},ru={title="Orgrul",body="Orgrul - это кентавр Magram, установленный рядом с Valley of Bones в Desolace. Его деятельность связана с интересом клана к некромантии и ресурсам проклятых земель."},references={["organization:magram"]=true,["place:desolace"]=true,["place:valley-of-bones"]=true}},
    ["person:orm-stonehoof"] = {title="Orm Pezuña Pétrea",kind="Personaje",aliases={"Orm","Orm Pezuña Pétrea"},body="Orm Pezuña Pétrea es un artesano de Cima del Trueno conocido por fabricar armaduras. Su trabajo exige materiales resistentes y une la protección del guerrero con pruebas de su capacidad para conseguirlos.",aliasQuestIDs={},en={title="Orm Stonehoof",aliases={"Orm","Orm Stonehoof"},body="Orm Stonehoof is a Thunder Bluff craftsperson known for making armor. His work requires strong materials and connects a warrior’s protection with tests of their ability to obtain them.",aliasQuestIDs={}},fr={title="Orm Stonehoof",body="Orm Stonehoof est un artisan Thunder Bluff connu pour la fabrication d'armures. Son travail exige des matériaux solides et relie la protection d'un guerrier avec des tests de leur capacité à les obtenir."},de={title="Orm Stonehoof",body="Orm Stonehoof ist ein Thunder Bluff Handwerker, der für seine Rüstungen bekannt ist. Seine Arbeit erfordert starke Materialien und verbindet den Schutz eines Kriegers mit Tests ihrer Fähigkeit, sie zu erhalten."},pt={title="Orm Stonehoof",body="Orm Stonehoof é um artesão Thunder Bluff conhecido por fazer armaduras. Seu trabalho requer materiais fortes e conecta a proteção de um guerreiro com testes de sua capacidade de obtê-los."},pl={title="Orm Stonehoof",body="Orm Stonehoof jest rzemieślnikiem z Thunder Bluff znanym z wytwarzania zbroi. Jego praca wymaga wytrzymałych materiałów i łączy ochronę wojownika z próbami jego zdolności do zdobywania surowców."},ru={title="Orm Stonehoof",body="Orm Stonehoof - мастер Thunder Bluff, известный изготовлением брони. Его работа требует прочных материалов и связывает защиту воина с испытаниями их способности их получить."},references={["place:thunder-bluff"]=true}},
    ["person:ormak-grimshot"] = {title="Ormak Tirosiniestro",kind="Personaje",aliases={"Ormak","Ormak Tirosiniestro"},body="Ormak Tirosiniestro es un cazador respetado de Orgrimmar. Cerca del Bastión de los Valientes enseña a los nuevos cazadores a cuidar, guiar y amaestrar a sus mascotas.",aliasQuestIDs={},en={title="Ormak Grimshot",aliases={"Ormak","Ormak Grimshot"},body="Ormak Grimshot is a respected hunter in Orgrimmar. Near the Hall of the Brave, he teaches new hunters to care for, guide, and train their pets.",aliasQuestIDs={}},fr={title="Ormak Grimshot",body="Ormak Grimshot est un chasseur respecté dans Orgrimmar. Près de la salle des Braves, il enseigne aux nouveaux chasseurs à soigner, guider et former leurs animaux de compagnie."},de={title="Ormak Grimshot",body="Ormak Grimshot ist in Orgrimmar ein angesehener Jäger. In der Nähe der Halle der Tapferen bringt er neuen Jägern bei, ihre Haustiere zu versorgen, zu führen und zu schulen."},pt={title="Ormak Grimshot",body="Ormak Grimshot é um caçador respeitado em Orgrimmar. Perto do Salão do Valente, ele ensina novos caçadores a cuidar, orientar e treinar seus animais de estimação."},pl={title="Ormak Grimshot",body="Ormak Grimshot jest szanowanym łowcą w Orgrimmar. Przy Hall of the Brave uczy nowych łowców opieki nad zwierzętami, ich prowadzenia oraz szkolenia."},ru={title="Ormak Grimshot",body="Ormak Grimshot - уважаемый охотник в Orgrimmar. Рядом с Залом храбрых он учит новых охотников заботиться, вести и тренировать своих домашних животных."},references={["place:orgrimmar"]=true}},
    ["person:orokk-omosh"] = {title="Orokk Omosh",kind="Personaje",aliases={"Orokk","Orokk Omosh"},body="Orokk Omosh es un herrero de Orgrimmar que conserva una tradición familiar transmitida durante generaciones. Busca enseñar los secretos de su oficio para que ese legado no desaparezca con él.",aliasQuestIDs={},en={title="Orokk Omosh",aliases={"Orokk","Orokk Omosh"},body="Orokk Omosh is an Orgrimmar blacksmith preserving a family tradition passed down for generations. He seeks to teach the secrets of his craft so that the legacy will not die with him.",aliasQuestIDs={}},fr={title="Orokk Omosh",body="Orokk Omosh est un forgeron Orgrimmar qui préserve une tradition familiale transmise de génération en génération. Il cherche à enseigner les secrets de son métier afin que l’héritage ne meure pas avec lui."},de={title="Orokk Omosh",body="Orokk Omosh ist ein Schmied von Orgrimmar und pflegt eine Familientradition, die seit Generationen weitergegeben wird. Er versucht, die Geheimnisse seines Handwerks zu lehren, damit das Vermächtnis nicht mit ihm stirbt."},pt={title="Orokk Omosh",body="Orokk Omosh é um ferreiro Orgrimmar que preserva uma tradição familiar transmitida por gerações. Ele procura ensinar os segredos de seu ofício para que o legado não morra com ele."},pl={title="Orokk Omosh",body="Orokk Omosh jest kowalem w Orgrimmar pielęgnującym rodzinną tradycję przekazywaną od pokoleń. Chce uczyć tajników swojego rzemiosła, aby dziedzictwo nie umarło wraz z nim."},ru={title="Orokk Omosh",body="Orokk Omosh - это кузнец Orgrimmar, который сохраняет семейную традицию, передаваемую поколениями. Он стремится научить его секретам своего ремесла, чтобы наследие не умерло вместе с ним."},references={["place:orgrimmar"]=true}},
    ["person:orwin-gizzmick"] = {title="Orwin Cacharrejos",kind="Personaje",aliases={"Orwin","Orwin Cacharrejos"},body="Orwin Cacharrejos investiga los minerales de los Gordunni desde el Campamento Mojache. Su curiosidad por los recursos de los ogros lo lleva a estudiar los lugares donde entierran sus reservas.",aliasQuestIDs={},en={title="Orwin Gizzmick",aliases={"Orwin","Orwin Gizzmick"},body="Orwin Gizzmick investigates Gordunni minerals from Camp Mojache. His curiosity about the ogres’ resources leads him to study the places where they bury their stores.",aliasQuestIDs={}},fr={title="Orwin Gizzmick",body="Orwin Gizzmick étudie les minéraux Gordunni de Camp Mojache. Sa curiosité pour les ressources des ogres l’amène à étudier les lieux où ils enterrent leurs magasins."},de={title="Orwin Gizzmick",body="Orwin Gizzmick untersucht Gordunni Mineralien von Camp Mojache. Seine Neugier auf die Ressourcen der Oger veranlasst ihn, die Orte zu studieren, an denen sie ihre Vorräte vergraben."},pt={title="Orwin Gizzmick",body="Orwin Gizzmick investiga minerais Gordunni de Camp Mojache. Sua curiosidade sobre os recursos dos ogres o leva a estudar os lugares onde eles enterram suas lojas."},pl={title="Orwin Gizzmick",body="Orwin Gizzmick bada minerały Gordunni z Camp Mojache. Ciekawość zasobów ogrów prowadzi go do badania miejsc, w których zakopują zapasy."},ru={title="Orwin Gizzmick",body="Orwin Gizzmick исследует Gordunni минералы из Camp Mojache. Его любопытство к ресурсам огров заставляет его изучать места, где они хоронили свои запасы."},references={["organization:gordunni"]=true,["place:camp-mojache"]=true}},
    ["person:ouro"] = {title="Ouro",kind="Personaje",aliases={"Ouro"},body="Ouro es un antiguo gusano de arena de Ahn'Qiraj de poder legendario. Su piel combina un grosor casi impenetrable con una flexibilidad que le permite moverse con una agilidad sorprendente para su tamaño.",aliasQuestIDs={},en={title="Ouro",aliases={"Ouro"},body="Ouro is an ancient sandworm of legendary power in Ahn'Qiraj. His skin combines near-impenetrable thickness with a flexibility that gives him surprising agility for his size.",aliasQuestIDs={}},fr={title="Ouro",body="Ouro est un ancien ver de sable de puissance légendaire dans Ahn'Qiraj. Sa peau combine une épaisseur quasi-impénétrable avec une souplesse qui lui donne une agilité surprenante pour sa taille."},de={title="Ouro",body="Ouro ist ein uralter Sandwurm von sagenhafter Kraft in Ahn'Qiraj. Seine Haut verbindet nahezu undurchdringliche Dicke mit einer Flexibilität, die ihm für seine Größe überraschende Beweglichkeit verleiht."},pt={title="Ouro",body="Ouro é um antigo verme de areia de poder lendário em Ahn'Qiraj. Sua pele combina espessura quase impenetrável com uma flexibilidade que lhe dá agilidade surpreendente para seu tamanho."},pl={title="Ouro",body="Ouro jest pradawnym czerwiem piaskowym o legendarnej mocy w Ahn'Qiraj. Skóra łączy niemal nieprzeniknioną grubość z elastycznością dającą mu zaskakującą zwinność mimo rozmiaru."},ru={title="Ouro",body="Ouro - древний песчаник легендарной силы в Ahn'Qiraj. Его кожа сочетает в себе почти непроницаемую толщину и гибкость, которая дает ему удивительную ловкость для его размера."},references={["place:ahnqiraj"]=true}},
    ["person:overlord-ror"] = {title="Señor supremo Ror",kind="Personaje",aliases={"Ror","Señor supremo Ror"},body="El señor supremo Ror es un gran fúrbolg corrompido del sur de Frondavil. Su violencia ha alcanzado tanto a druidas como a combatientes enviados para frenar las amenazas del bosque.",aliasQuestIDs={},en={title="Overlord Ror",aliases={"Overlord Ror","Ror"},body="Overlord Ror is a large corrupted furbolg in southern Felwood. His violence has reached druids and fighters sent to oppose the forest’s threats alike.",aliasQuestIDs={}},fr={title="Overlord Ror",body="Overlord Ror est un gros furbolg corrompu dans le sud Felwood. Sa violence a atteint les druides et les combattants envoyés pour s’opposer aux menaces de la forêt."},de={title="Overlord Ror",body="Overlord Ror ist ein großer, korrupter Furbolg im südlichen Felwood. Seine Gewalt hat Druiden und Kämpfer erreicht, die entsandt wurden, um den Bedrohungen des Waldes Waldes gleichen zu widerstehen."},pt={title="Overlord Ror",body="Overlord Ror é um grande furbolg corrompido no sul de Felwood. Sua violência atingiu druidas e combatentes enviados para se opor às ameaças da floresta."},pl={title="Overlord Ror",body="Overlord Ror jest wielkim skażonym furbolgiem w południowym Felwood. Przemoc dotknęła zarówno druidów, jak i wojowników wysłanych przeciw zagrożeniom lasu."},ru={title="Overlord Ror",body="Overlord Ror - это большой испорченный фуролог в южной части Felwood. Его насилие достигло и друидов, и бойцов, посланных противостоять угрозам леса."},references={["place:felwood"]=true}},
    ["person:overlord-runthak"] = {title="Señor supremo Runthak",kind="Personaje",aliases={"Runthak","Señor supremo Runthak","señor supremo Runthak"},body="El señor supremo Runthak representa a la Horda en el Valle de la Fuerza de Orgrimmar. Participa en el reconocimiento público de las hazañas con las que sus campeones afianzan la seguridad y el prestigio de su pueblo.",aliasQuestIDs={},en={title="Overlord Runthak",aliases={"Overlord Runthak","Runthak"},body="Overlord Runthak represents the Horde in Orgrimmar’s Valley of Strength. He takes part in publicly recognizing the deeds through which its champions strengthen their people’s safety and standing.",aliasQuestIDs={}},fr={title="Overlord Runthak",body="Overlord Runthak représente le Horde en Orgrimmar’s Valley de force. Il participe à la reconnaissance publique des actes par lesquels ses champions renforcent la sécurité et la position de leur peuple."},de={title="Overlord Runthak",body="Overlord Runthak repräsentiert den Horde in Orgrimmar’s Valley der Kraft. Er nimmt teil an der öffentlichen Anerkennung der Taten, durch die ihre Verfechter die die die Sicherheit und das Ansehen ihres Volkes stärken."},pt={title="Overlord Runthak",body="Overlord Runthak representa o Horde em Orgrimmar’s Valley de Força. Ele participa no reconhecimento público das ações através das quais seus campeões fortalecem a segurança e a posição de seu povo."},pl={title="Overlord Runthak",body="Overlord Runthak reprezentuje frakcję Horde w Orgrimmar’s Valley of Strength. Uczestniczy w publicznym uznawaniu czynów, dzięki którym czempioni wzmacniają bezpieczeństwo oraz pozycję swojego ludu."},ru={title="Overlord Runthak",body="Overlord Runthak представляет собой Horde в Orgrimmar’s Valley Силы. Он принимает участие в публичном признании действий, посредством которых его защитники укрепляют безопасность и репутацию своего народа."},references={["organization:horde"]=true,["place:orgrimmar"]=true}},
    ["person:owatanka"] = {title="Owatanka",kind="Personaje",aliases={"Owatanka"},body="Owatanka es un truenagarto al que los tauren llaman Rayo Azul. Combina un gran tamaño con una velocidad inesperada, y su espina caudal desprende chispas al tocarla.",aliasQuestIDs={},en={title="Owatanka",aliases={"Owatanka"},body="Owatanka is a thunder lizard called Bluebolt by the tauren. It combines great size with unexpected speed, and its tailspike gives off sparks when touched.",aliasQuestIDs={}},fr={title="Owatanka",body="Owatanka est un lézard de tonnerre appelé Bluebolt par les taurens. Il combine une grande taille avec une vitesse inattendue, et son tailspike dégage des étincelles au toucher."},de={title="Owatanka",body="Owatanka ist eine Donner-Echse, die von den Tauren Bluebolt genannt wird. Er vereint große Größe mit unerwarteter Geschwindigkeit, und seine Schwanzspitze gibt bei Berührung Funken ab."},pt={title="Owatanka",body="Owatanka é um lagarto trovão chamado Bluebolt pelos tauren. Ele combina grande tamanho com velocidade inesperada, e seu tailspike emite faíscas quando tocado."},pl={title="Owatanka",body="Owatanka jest jaszczurką piorunową zwaną przez taurenów Bluebolt. Łączy wielki rozmiar z nieoczekiwaną szybkością, a kolec ogona iskrzy przy dotknięciu."},ru={title="Owatanka",body="Owatanka - это гусеница-громовой, которую таурены называют Bluebolt. Его огромный размер сочетается с неожиданной скоростью, а хвостовой шип отпускает искры при прикосновении."},references={}},
    ["person:paljuh"] = {title="Pal'juh",kind="Personaje",aliases={"Pal'juh","Pal’juh"},body="Pal'juh explora el Risco Kolkar valiéndose de la magia. Su experiencia muestra la vulnerabilidad de quienes se aventuran en territorio hostil cuando sus fuerzas mágicas se agotan.",aliasQuestIDs={},en={title="Pal'juh",aliases={"Pal'juh","Pal’juh"},body="Pal'juh scouts Kolkar Crag relying on magic. Her experience shows the vulnerability of travelers in hostile territory when their magical strength runs out.",aliasQuestIDs={}},fr={title="Pal'juh",body="Pal'juh éclaireurs Kolkar Crag s'appuyant sur la magie. Son expérience montre la vulnérabilité des voyageurs en territoire hostile lorsque leur force magique s’épuise."},de={title="Pal'juh",body="Pal'juh Scouts Kolkar Crag verlässt sich auf Magie. Ihre Erfahrung zeigt die Verletzlichkeit von Reisenden in feindlichem Territorium, wenn ihre magische Kraft erschöpft ist."},pt={title="Pal'juh",body="Pal'juh escoteiros Kolkar Crag confiando na magia. Sua experiência mostra a vulnerabilidade dos viajantes em território hostil quando sua força mágica se esgota."},pl={title="Pal'juh",body="Pal'juh prowadzi zwiad Kolkar Crag, polegając na magii. Doświadczenie pokazuje bezbronność podróżnych na wrogim terytorium, gdy magiczna siła się wyczerpuje."},ru={title="Pal'juh",body="Pal'juh разведчики Kolkar Crag полагаются на магию. Ее опыт показывает, как уязвимы путешественники на враждебной территории, когда их магическая сила исчезает."},references={["organization:kolkar"]=true}},
    ["person:paoka-swiftmount"] = {title="Pao'ka Monte Presto",kind="Personaje",aliases={"Pao'ka","Pao'ka Monte Presto","Pao’ka","Pao’ka Monte Presto"},body="Pao'ka Monte Presto estudia los dracoleones de Las Mil Agujas. Su curiosidad por las criaturas de Nido Alto lo lleva a explorar un territorio donde observar de cerca también supone exponerse al peligro.",aliasQuestIDs={},en={title="Pao'ka Swiftmount",aliases={"Pao'ka","Pao'ka Swiftmount","Pao’ka","Pao’ka Swiftmount"},body="Pao'ka Swiftmount studies the wyverns of Thousand Needles. His curiosity about the creatures of Highperch takes him into terrain where close observation also means exposure to danger.",aliasQuestIDs={}},fr={title="Pao'ka Swiftmount",body="Pao'ka Swiftmount étudie les wyvernes de Thousand Needles. Sa curiosité pour les créatures de Highperch l'emmène sur un terrain où l'observation rapprochée signifie également l'exposition au danger."},de={title="Pao'ka Swiftmount",body="Pao'ka Swiftmount studiert die Flügelschläge von Thousand Needles. Seine Neugier auf die Geschöpfe von Highperch führt ihn in ein Terrain, in dem eine Umgebung, in dem genaue Beobachtung auch Gefährdung bedeutet."},pt={title="Pao'ka Swiftmount",body="Pao'ka Swiftmount estuda as wyverns de Thousand Needles. Sua curiosidade sobre as criaturas de Highperch o leva a um terreno onde a observação próxima também significa exposição ao perigo."},pl={title="Pao'ka Swiftmount",body="Pao'ka Swiftmount bada wiwerny Thousand Needles. Ciekawość stworzeń Highperch prowadzi go na tereny, gdzie obserwacja z bliska oznacza również narażenie na niebezpieczeństwo."},ru={title="Pao'ka Swiftmount",body="Pao'ka Swiftmount изучает вивернов Thousand Needles. Его любопытство к существам Highperch приводит его в местность, где пристальное наблюдение также означает воздействие опасности."},references={["place:highperch"]=true,["place:thousand-needles"]=true}},
    ["person:pazula"] = {title="Pa'zula",kind="Personaje",aliases={"Pa'zula","Pa’zula"},body="Pa'zula enseña encantamiento en el Poblado Sen'jin. Sus conocimientos permiten extraer magia de los colgantes con los que Zalazane somete a sus prisioneros, en lugar de quedar expuesto a sus hechizos de vinculación.",aliasQuestIDs={},en={title="Pa'zula",aliases={"Pa'zula","Pa’zula"},body="Pa'zula teaches enchanting in Sen'jin Village. This knowledge allows magic to be extracted from pendants Zalazane uses to subdue prisoners, rather than leaving the wearer exposed to their binding spells.",aliasQuestIDs={}},fr={title="Pa'zula",body="Pa'zula enseigne enchanteur dans Sen'jin Village. Cette connaissance permet d'extraire la magie des pendentifs que Zalazane utilise pour soumettre les prisonniers, plutôt que de laisser le porteur exposé à leurs sorts de reliure."},de={title="Pa'zula",body="Pa'zula lehrt bezaubernd in Sen'jin Village. Dieses Wissen erlaubt es, aus Anhängern, die Magie zu extrahieren, die Zalazane benutzt, um Gefangene zu unterwerfen, anstatt den Träger ihren Bindungszaubern."},pt={title="Pa'zula",body="Pa'zula ensina encantamento em Sen'jin Village. Esse conhecimento permite que a magia seja extraída dos pingentes que a Zalazane usa para subjugar os prisioneiros, em vez de deixar o usuário exposto a seus feitiços de ligação."},pl={title="Pa'zula",body="Pa'zula uczy zaklinania w Sen'jin Village. Wiedza pozwala wydobywać magię z wisiorków używanych przez postać Zalazane do ujarzmiania więźniów zamiast pozostawiać użytkownika pod wpływem wiążących zaklęć."},ru={title="Pa'zula",body="Pa'zula учит волшебству в Sen'jin Village. Эти знания позволяют извлекать магию из подвесок, которые Zalazane использует для подчинения заключенных, вместо того чтобы оставлять носителя подверженным их связывающим заклинаниям."},references={["person:zalazane"]=true,["place:senjin-village"]=true}},
    ["person:pelturas-whitemoon"] = {title="Pelturas Lunablanca",kind="Personaje",aliases={"Pelturas","Pelturas Lunablanca"},body="Pelturas Lunablanca es un habitante de Astranaar preocupado por la salud de su hija. Su búsqueda de ayuda lo relaciona con los sanadores y recursos del bosque, donde las enfermedades pueden tener causas más allá de lo físico.",aliasQuestIDs={},en={title="Pelturas Whitemoon",aliases={"Pelturas","Pelturas Whitemoon"},body="Pelturas Whitemoon is an Astranaar resident concerned about his daughter’s health. His search for help connects him with the forest’s healers and resources, where illnesses can have causes beyond the physical.",aliasQuestIDs={}},fr={title="Pelturas Whitemoon",body="Pelturas Whitemoon est un résident de Astranaar préoccupé par la santé de sa fille. Sa recherche d’aide le relie aux guérisseurs et aux ressources de la forêt, où les maladies peuvent avoir des causes au-delà du physique."},de={title="Pelturas Whitemoon",body="Pelturas Whitemoon ist ein Astranaar-Bewohner, der sich Sorgen um den Gesundheitszustand seiner Tochter macht. Seine Suche nach Hilfe verbindet ihn mit den Heilern und Ressourcen des Waldes Waldes Landes, wo Krankheiten über das Physische hinaus Ursachen haben können."},pt={title="Pelturas Whitemoon",body="Pelturas Whitemoon é um residente Astranaar preocupado com a saúde de sua filha. Sua busca por ajuda o conecta com os curandeiros e recursos da floresta, onde as doenças podem ter causas além do físico."},pl={title="Pelturas Whitemoon",body="Pelturas Whitemoon jest mieszkańcem Astranaar zaniepokojonym zdrowiem córki. Poszukiwanie pomocy wiąże go z uzdrowicielami i zasobami lasu, gdzie choroby mogą mieć przyczyny wykraczające poza ciało."},ru={title="Pelturas Whitemoon",body="Pelturas Whitemoon - житель Astranaar, который беспокоится о здоровье своей дочери. Его поиск помощи связывает его с лечебниками и ресурсами леса, где болезни могут иметь причины за пределами физических."},references={["place:astranaar"]=true}},
    ["person:perith-stormhoof"] = {title="Perith Pezuña Tempestuosa",kind="Personaje",aliases={"Perith","Perith Pezuña Tempestuosa"},body="Perith Pezuña Tempestuosa pertenece a los Zancalargos, los exploradores de confianza de Cairne Pezuña de Sangre. Participa en esfuerzos diplomáticos con los gnolls, pero mantiene en secreto los demás objetivos de su misión.",aliasQuestIDs={},en={title="Perith Stormhoof",aliases={"Perith","Perith Stormhoof"},body="Perith Stormhoof belongs to the Longwalkers, Cairne Bloodhoof’s trusted scouts. He takes part in diplomatic efforts with the gnolls while keeping his mission’s other objectives secret.",aliasQuestIDs={}},fr={title="Perith Stormhoof",body="Perith Stormhoof appartient à la Longwalkers, Cairne Bloodhoof scouts de confiance. Il participe aux efforts diplomatiques avec les gnolls tout en gardant secrets les autres objectifs de sa mission."},de={title="Perith Stormhoof",body="Perith Stormhoof gehört zu den Longwalkers, Cairne Bloodhoof 'vertrauenswürdigen Kundschaftern. Er nimmt an diplomatischen Bemühungen mit den Gnolls teil und hält die anderen Ziele seiner Mission geheim."},pt={title="Perith Stormhoof",body="Perith Stormhoof pertence ao Longwalkers, escoteiros confiáveis do Cairne Bloodhoof. Ele participa de esforços diplomáticos com os gnolls, mantendo os outros objetivos de sua missão em segredo."},pl={title="Perith Stormhoof",body="Perith Stormhoof należy do Longwalkers, zaufanych zwiadowców postaci Cairne Bloodhoof. Uczestniczy w działaniach dyplomatycznych z gnollami, zachowując w tajemnicy pozostałe cele misji."},ru={title="Perith Stormhoof",body="Perith Stormhoof принадлежит Longwalkers, Cairne Bloodhoof  доверенным разведчикам. Он участвует в дипломатических усилиях с гнолами, сохраняя в тайне другие цели своей миссии."},references={["person:cairne-bloodhoof"]=true}},
    ["person:peter-galen"] = {title="Peter Galen",kind="Personaje",aliases={"Peter Galen"},body="Peter Galen enseña peletería dragontina en Azshara. Su especialidad aprovecha escamas y materiales resistentes para elaborar armaduras, y exige dominar una técnica distinta de las otras ramas del oficio.",aliasQuestIDs={},en={title="Peter Galen",aliases={"Peter Galen"},body="Peter Galen teaches dragonscale leatherworking in Azshara. His specialty uses scales and durable materials to make armor and requires mastery of a technique distinct from the craft’s other branches.",aliasQuestIDs={}},fr={title="Peter Galen",body="Peter Galen enseigne le travail du cuir à l'échelle du dragon dans Azshara. Sa spécialité utilise des échelles et des matériaux durables pour fabriquer des armures et nécessite la maîtrise d’une technique distincte des autres branches de l’engin."},de={title="Peter Galen",body="Peter Galen lehrt Drachenschuppenleder in Azshara. Seine Spezialität ist die Herstellung von Rüstungen mit Waagen und haltbaren Materialien und erfordert die Beherrschung einer Technik, die sich von anderen Zweigen muss."},pt={title="Peter Galen",body="Peter Galen ensina couro em escala de dragão trabalhando em Azshara. Sua especialidade usa escalas e materiais duráveis para fazer armaduras e requer o domínio de uma técnica distinta dos outros ramos da embarcação."},pl={title="Peter Galen",body="Peter Galen uczy kaletnictwa smoczych łusek w regionie Azshara. Jego specjalność wykorzystuje łuski i wytrzymałe materiały do wytwarzania zbroi oraz wymaga opanowania techniki odmiennej od innych gałęzi rzemiosła."},ru={title="Peter Galen",body="Peter Galen учит драконьей коже в Azshara. Его специальность - использовать весы и прочные материалы для изготовления брони, и требует мастерства в технике, отличающейся от других отраслей ремесла."},references={["place:azshara"]=true}},
    ["person:pozzik"] = {title="Pozzik",kind="Personaje",aliases={"Pozzik"},body="Pozzik es un mecánico relacionado con las carreras del Desierto de Sal. Su trabajo consiste en desarrollar vehículos y mejorar su rendimiento en una competencia donde cada avance técnico cuenta.",aliasQuestIDs={},en={title="Pozzik",aliases={"Pozzik"},body="Pozzik is a mechanic associated with racing in the Shimmering Flats. His work involves developing vehicles and improving their performance in a competition where every technical advance matters.",aliasQuestIDs={}},fr={title="Pozzik",body="Pozzik est un mécanicien associé à la course dans le Shimmering Flats. Son travail consiste à développer des véhicules et à améliorer leurs performances dans une compétition où chaque progrès technique compte."},de={title="Pozzik",body="Pozzik ist Mechaniker im Rennstall Shimmering Flats. Seine Arbeit besteht darin, Fahrzeuge zu entwickeln und ihre Leistung in einem Wettbewerb zu verbessern, bei dem es auf jeden technischen Fortschritt ankommt."},pt={title="Pozzik",body="Pozzik é um mecânico associado às corridas no Shimmering Flats. Seu trabalho envolve desenvolver veículos e melhorar seu desempenho em uma competição onde cada avanço técnico é importante."},pl={title="Pozzik",body="Pozzik jest mechanikiem związanym z wyścigami w Shimmering Flats. Pracuje nad rozwojem pojazdów i poprawą osiągów w rywalizacji, gdzie każdy postęp techniczny ma znaczenie."},ru={title="Pozzik",body="Pozzik - механик, связанный с гонками в Shimmering Flats. Его работа включает в себя разработку автомобилей и улучшение их производительности на соревнованиях, где каждый технический прогресс имеет значение."},references={["place:shimmering-flats"]=true}},
    ["person:prate-cloudseer"] = {title="Prate Vidente de las Nubes",kind="Personaje",aliases={"Prate","Prate Vidente de las Nubes"},body="Prate Vidente de las Nubes guía a los chamanes en Las Mil Agujas. Sus enseñanzas relacionadas con el aire exigen respeto y preparación antes de asumir nuevas responsabilidades con los elementos.",aliasQuestIDs={},en={title="Prate Cloudseer",aliases={"Prate","Prate Cloudseer"},body="Prate Cloudseer guides shamans in Thousand Needles. Her teachings concerning air demand respect and preparation before taking on new responsibilities toward the elements.",aliasQuestIDs={}},fr={title="Prate Cloudseer",body="Prate Cloudseer guide les chamans dans Thousand Needles. Ses enseignements sur l’air exigent respect et préparation avant d’assumer de nouvelles responsabilités envers les éléments."},de={title="Prate Cloudseer",body="Prate Cloudseer führt Schamanen in Thousand Needles. Ihre Lehren über Luft erfordern Respekt und Vorbereitung, bevor sie neue Verantwortlichkeiten gegenüber den Elementen übernehmen."},pt={title="Prate Cloudseer",body="Prate Cloudseer guia xamãs em Thousand Needles. Seus ensinamentos sobre o respeito e a preparação da demanda aérea antes de assumir novas responsabilidades em relação aos elementos."},pl={title="Prate Cloudseer",body="Prate Cloudseer prowadzi szamanów w Thousand Needles. Jej nauki o powietrzu wymagają szacunku i przygotowania przed przyjęciem nowych obowiązków wobec żywiołów."},ru={title="Prate Cloudseer",body="Prate Cloudseer направляет шаманов в Thousand Needles. Ее учения о воздухе требуют уважения и подготовки, прежде чем брать на себя новые обязанности перед стихией."},references={["place:thousand-needles"]=true}},
    ["person:pratt-mcgrubben"] = {title="Pratt McGrubben",kind="Personaje",aliases={"Pratt","Pratt McGrubben"},body="Pratt McGrubben trabaja con pieles y técnicas de peletería en el Bastión Plumaluna. Busca materiales de distintas criaturas de Feralas para ampliar las posibilidades de su oficio.",aliasQuestIDs={},en={title="Pratt McGrubben",aliases={"Pratt","Pratt McGrubben"},body="Pratt McGrubben works with hides and leatherworking techniques at Feathermoon Stronghold. He seeks materials from different Feralas creatures to expand the possibilities of his craft.",aliasQuestIDs={}},fr={title="Pratt McGrubben",body="Pratt McGrubben travaille avec les peaux et les techniques de travail du cuir chez Feathermoon Stronghold. Il cherche des matériaux de différentes créatures Feralas pour élargir les possibilités de son métier."},de={title="Pratt McGrubben",body="Pratt McGrubben arbeitet bei Feathermoon Stronghold mit Fellen und Lederverarbeitungstechniken. Er sucht Materialien von verschiedenen Feralas-Lebewesen, um die Möglichkeiten seines Handwerks zu erweitern."},pt={title="Pratt McGrubben",body="Pratt McGrubben trabalha com peles e técnicas de couro na Feathermoon Stronghold. Ele procura materiais de diferentes criaturas Feralas para expandir as possibilidades de seu ofício."},pl={title="Pratt McGrubben",body="Pratt McGrubben zajmuje się skórami i technikami kaletniczymi w Feathermoon Stronghold. Szuka materiałów różnych stworzeń Feralas, by poszerzać możliwości swojego rzemiosła."},ru={title="Pratt McGrubben",body="Pratt McGrubben работает с кожами и методами обработки кожи в Feathermoon Stronghold. Он ищет материалы у разных существ Feralas, чтобы расширить возможности своего корабля."},references={["place:feathermoon-stronghold"]=true,["place:feralas"]=true}},
    ["person:priestess-alathea"] = {title="Sacerdotisa Alathea",kind="Personaje",aliases={"Alathea","Sacerdotisa Alathea","sacerdotisa Alathea"},body="La sacerdotisa Alathea instruye a otros sacerdotes desde el Templo de la Luna de Darnassus. Su labor vincula el aprendizaje de nuevas habilidades con las tradiciones religiosas de los elfos de la noche.",aliasQuestIDs={},en={title="Priestess Alathea",aliases={"Alathea","Priestess Alathea"},body="Priestess Alathea trains other priests at the Temple of the Moon in Darnassus. Her work connects learning new abilities with night elf religious traditions.",aliasQuestIDs={}},fr={title="Priestess Alathea",body="Priestess Alathea forme d'autres prêtres au Temple of the Moon à Darnassus. Son travail relie l'apprentissage de nouvelles capacités avec les traditions religieuses des elfes de la nuit."},de={title="Priestess Alathea",body="Priestess Alathea bildet im Temple of the Moon in Darnassus andere Priester aus. Ihre Arbeit verbindet das Erlernen neuer Fähigkeiten mit religiösen Traditionen der Nachtelfen."},pt={title="Priestess Alathea",body="Priestess Alathea treina outros sacerdotes no Temple of the Moon em Darnassus. Seu trabalho conecta o aprendizado de novas habilidades com as tradições religiosas dos elfos noturnos."},pl={title="Priestess Alathea",body="Priestess Alathea szkoli innych kapłanów w Temple of the Moon w Darnassus. Jej praca łączy naukę nowych zdolności z tradycjami religijnymi nocnych elfów."},ru={title="Priestess Alathea",body="Priestess Alathea обучает других жрецов в Temple of the Moon в Darnassus. Ее работа связывает изучение новых способностей с религиозными традициями ночных эльфов."},references={["place:darnassus"]=true,["place:temple-of-the-moon"]=true}},
    ["person:priestess-amoora"] = {title="Sacerdotisa A'moora",kind="Personaje",aliases={"A'moora","A’moora","Sacerdotisa A'moora","Sacerdotisa A’moora","sacerdotisa A'moora","sacerdotisa A’moora"},body="La sacerdotisa A'moora sirve en el Templo de la Luna de Darnassus. Sus conocimientos relacionan la gracia de Elune con las propiedades curativas de ciertas criaturas y con el cuidado de sus espíritus.",aliasQuestIDs={},en={title="Priestess A'moora",aliases={"A'moora","A’moora","Priestess A'moora","Priestess A’moora"},body="Priestess A'moora serves in Darnassus’s Temple of the Moon. Her knowledge connects Elune’s grace with the healing properties of certain creatures and care for their spirits.",aliasQuestIDs={}},fr={title="Priestess A'moora",body="Priestess A'moora sert dans Darnassus’s Temple of the Moon. Ses connaissances relient la grâce de Elune aux propriétés curatives de certaines créatures et aux soins de leurs esprits."},de={title="Priestess A'moora",body="Priestess A'moora dient in Darnassus’s Temple of the Moon. Ihr Wissen verbindet die Gnade von Elune mit den heilenden Eigenschaften bestimmter Geschöpfe und der Fürsorge für deren Geister."},pt={title="Priestess A'moora",body="Priestess A'moora serve em Darnassus’s Temple of the Moon. Seu conhecimento conecta a graça de Elune com as propriedades curativas de certas criaturas e cuidam de seus espíritos."},pl={title="Priestess A'moora",body="Priestess A'moora służy w miejscu zwanym Darnassus’s Temple of the Moon. Jej wiedza łączy łaskę bogini Elune z leczniczymi właściwościami pewnych stworzeń oraz opieką nad ich duchami."},ru={title="Priestess A'moora",body="Priestess A'moora служит в Darnassus’s Temple of the Moon. Ее знания связывают благодать Elune с целебными свойствами некоторых существ и заботой о их духах."},references={["npc:elune"]=true,["place:darnassus"]=true,["place:temple-of-the-moon"]=true}},
    ["person:private-hendel"] = {title="Soldado Hendel",kind="Personaje",aliases={"Hendel","Soldado Hendel","soldado Hendel"},body="El soldado Hendel pertenece al entorno militar de Theramore. Sus movimientos por el Marjal Revolcafango lo sitúan entre las personas a las que se busca cuando las noticias y los viajeros dejan de llegar a su destino.",aliasQuestIDs={},en={title="Private Hendel",aliases={"Hendel","Private Hendel"},body="Private Hendel belongs to Theramore’s military world. His movements through Dustwallow Marsh place him among those sought when news and travelers stop reaching their destinations.",aliasQuestIDs={}},fr={title="Private Hendel",body="Private Hendel appartient au monde militaire de Theramore. Ses déplacements à travers Dustwallow Marsh le placent parmi ceux recherchés lorsque les nouvelles et les voyageurs cessent d’atteindre leurs destinations."},de={title="Private Hendel",body="Private Hendel gehört zur militärischen Welt von Theramore. Seine Bewegungen durch Dustwallow Marsh stellen ihn unter jene dar, die gesucht werden, wenn Nachrichten und Reisende ihr Ziel nicht mehr erreichen."},pt={title="Private Hendel",body="Private Hendel pertence ao mundo militar de Theramore. Seus movimentos através do Dustwallow Marsh o colocam entre aqueles procurados quando as notícias e os viajantes param de chegar aos seus destinos."},pl={title="Private Hendel",body="Private Hendel należy do wojskowego świata Theramore. Podróże po Dustwallow Marsh stawiają go wśród osób poszukiwanych, gdy wiadomości oraz podróżni przestają docierać do celu."},ru={title="Private Hendel",body="Private Hendel принадлежит к военному миру Theramore. Его движения через Dustwallow Marsh помещают его в число тех, кого ищут, когда новости и путешественники перестают достигать своих пунктов назначения."},references={["place:dustwallow-marsh"]=true,["place:theramore"]=true}},
    ["person:privateer-groy"] = {title="Corsario Groy",kind="Personaje",aliases={"Corsario Groy","Groy"},body="El corsario Groy mantiene negocios de suministros con Bloads y con clientes de Theramore. Sus acuerdos dependen de transportar mercancías por rutas donde el comercio y los riesgos políticos conviven.",aliasQuestIDs={},en={title="Privateer Groy",aliases={"Groy","Privateer Groy"},body="Privateer Groy trades supplies with Bloads and clients in Theramore. His deals depend on carrying goods along routes where commerce and political dangers coexist.",aliasQuestIDs={}},fr={title="Privateer Groy",body="Privateer Groy négocie des fournitures avec Bloads et ses clients dans Theramore. Ses transactions dépendent du transport de marchandises le long de routes où le commerce et les dangers politiques coexistent."},de={title="Privateer Groy",body="Privateer Groy handelt mit Bloads und Kunden in Theramore. Seine Geschäfte hängen davon ab, Güter entlang von Routen zu transportieren, wo Handel und politische Gefahren nebeneinander bestehen."},pt={title="Privateer Groy",body="Privateer Groy comercializa suprimentos com Bloads e clientes em Theramore. Seus negócios dependem do transporte de mercadorias ao longo de rotas onde o comércio e os perigos políticos coexistem."},pl={title="Privateer Groy",body="Privateer Groy handluje zapasami z postacią Bloads i klientami w Theramore. Umowy zależą od przewożenia towarów szlakami, na których współistnieją handel oraz polityczne niebezpieczeństwa."},ru={title="Privateer Groy",body="Privateer Groy торгует поставками с Bloads и клиентами в Theramore. Его сделки зависят от перевозки товаров по маршрутам, где сосуществуют коммерческая и политическая опасность."},references={["npc:privateer-bloads"]=true,["place:theramore"]=true}},
    ["person:prospector-ironboot"] = {title="Prospector Ferrobota",kind="Personaje",aliases={"Prospector Ferrobota","prospector Ferrobota"},body="El prospector Ferrobota estudia antiguas tablillas desde Tanaris. Su investigación de los textos Mosh'aru lo lleva a reunir conocimientos dispersos entre los trols y otros habitantes de territorios lejanos.",aliasQuestIDs={},en={title="Prospector Ironboot",aliases={"Ironboot","Prospector Ironboot"},body="Prospector Ironboot studies ancient tablets from Tanaris. His research into the Mosh'aru texts leads him to gather knowledge scattered among trolls and other inhabitants of distant territories.",aliasQuestIDs={}},fr={title="Prospector Ironboot",body="Prospector Ironboot étudie les tablettes anciennes de Tanaris. Ses recherches sur les textes Mosh'aru l’amènent à rassembler des connaissances éparpillées parmi les trolls et autres habitants de territoires lointains."},de={title="Prospector Ironboot",body="Prospector Ironboot studiert uralte Tabletten von Tanaris. Seine Forschungen zu den Mosh'aru-Texten führen ihn dazu, Wissen zu sammeln, das unter Trollen und anderen Bewohnern ferner Territorien verstreut ist."},pt={title="Prospector Ironboot",body="Prospector Ironboot estuda comprimidos antigos de Tanaris. Sua pesquisa sobre os textos do Mosh'aru o leva a reunir conhecimento espalhado entre trolls e outros habitantes de territórios distantes."},pl={title="Prospector Ironboot",body="Prospector Ironboot bada pradawne tablice z Tanaris. Dociekania dotyczące tekstów Mosh'aru skłaniają go do gromadzenia wiedzy rozproszonej wśród trolli oraz innych mieszkańców odległych terytoriów."},ru={title="Prospector Ironboot",body="Prospector Ironboot изучает древние таблички Tanaris. Его исследования текстов Mosh'aru приводят его к сбору знаний, разбросанных среди троллей и других жителей отдаленных территорий."},references={["place:tanaris"]=true}},
    ["person:prospector-remtravel"] = {title="Prospector Tripirrem",kind="Personaje",aliases={"Prospector Tripirrem","Tripirrem"},body="El prospector Tripirrem es un investigador enano que explora antiguos yacimientos de Costa Oscura. Su reputación académica convive con una concentración tan intensa en sus hallazgos que puede pasar por alto los peligros cercanos.",aliasQuestIDs={},en={title="Prospector Remtravel",aliases={"Prospector Remtravel","Remtravel"},body="Prospector Remtravel is a dwarven researcher exploring ancient sites in Darkshore. His academic reputation goes alongside such intense focus on discoveries that he can overlook nearby dangers.",aliasQuestIDs={}},fr={title="Prospector Remtravel",body="Prospector Remtravel est un chercheur nain explorant des sites anciens dans Darkshore. Sa réputation académique va de pair avec une telle concentration sur les découvertes qu’il peut ignorer les dangers à proximité."},de={title="Prospector Remtravel",body="Prospector Remtravel ist ein Zwergenforscher, der antike Stätten in Darkshore erforscht. Sein akademischer Ruf geht mit einem derart intensiven Fokus auf Entdeckungen einher, dass er Gefahren in der Nähe übersehen kann."},pt={title="Prospector Remtravel",body="Prospector Remtravel é um pesquisador anão que explora locais antigos em Darkshore. Sua reputação acadêmica vai ao lado de um foco tão intenso em descobertas que ele pode ignorar os perigos próximos."},pl={title="Prospector Remtravel",body="Prospector Remtravel jest krasnoludzkim badaczem pradawnych miejsc w Darkshore. Naukowej reputacji towarzyszy tak silne skupienie na odkryciach, że potrafi przeoczyć pobliskie niebezpieczeństwa."},ru={title="Prospector Remtravel",body="Prospector Remtravel - это исследователь-карлик, исследующий древние места в Darkshore. Его академическая репутация сочетается с таким интенсивным вниманием к открытиям, что он может упускать из виду близлежащие опасности."},references={["place:darkshore"]=true},questIDs={[729]=true,[731]=true,[741]=true}},
    ["person:quelana-quickgale"] = {title="Quel'ana Ventarrápido",kind="Personaje",aliases={"Quel'ana","Quel'ana Ventarrápido","Quel’ana","Quel’ana Ventarrápido"},body="Quel'ana Ventarrápido enseña a domesticar bestias en el puerto de Valanaar. Su labor se centra en la relación entre el cazador y su compañero animal. Es un instructor para quienes han adquirido experiencia en las tierras altas y están preparados para desarrollar ese vínculo.",aliasQuestIDs={},en={title="Quel'ana Quickgale",aliases={"Quel'ana","Quel'ana Quickgale","Quel’ana","Quel’ana Quickgale"},body="Quel'ana Quickgale teaches beast taming at Valanaar's port. His work concerns the bond between a hunter and an animal companion. He instructs those with experience in the highlands who are ready to develop that relationship.",aliasQuestIDs={}},fr={title="Quel'ana Quickgale",body="Quel'ana Quickgale enseigne l'apprivoisement des bêtes au port de Valanaar. Son travail concerne le lien entre un chasseur et un animal de compagnie. Il instruit ceux qui ont de l’expérience dans les hautes terres et qui sont prêts à développer cette relation."},de={title="Quel'ana Quickgale",body="Quel'ana Quickgale lehrt im Hafen von Valanaar das Zähmen von Tieren. In seiner Arbeit geht es um die Bindung zwischen Jäger und tierischen Gefährten. Er weist diejenigen mit Erfahrung im Hochland an, die bereit sind, diese Beziehung zu entwickeln."},pt={title="Quel'ana Quickgale",body="Quel'ana Quickgale ensina animais domesticando no porto de Valanaar. Seu trabalho diz respeito ao vínculo entre um caçador e um companheiro animal. Ele instrui aqueles com experiência nas terras altas que estão prontos para desenvolver esse relacionamento."},pl={title="Quel'ana Quickgale",body="Quel'ana Quickgale uczy oswajania bestii w porcie Valanaar. Jego praca dotyczy więzi łowcy ze zwierzęcym towarzyszem. Szkoli doświadczonych na wyżynach, gotowych rozwijać tę relację."},ru={title="Quel'ana Quickgale",body="Quel'ana Quickgale учит приручать зверей в порту Valanaar. Его работа касается связи между охотником и животным-компаньоном. Он обучает тех, кто имеет опыт в горах и готов развивать такие отношения."},references={["place:valanaar"]=true}},
    ["person:quentin"] = {title="Quentin",kind="Personaje",aliases={"Quentin"},body="Quentin conoce los cuidados que necesitan las crías de dragón feérico. Su experiencia ayuda a quienes asumen la responsabilidad de alimentar y criar a uno de estos seres tras la pérdida de su madre.",aliasQuestIDs={},en={title="Quentin",aliases={"Quentin"},body="Quentin knows the care needed by faerie dragon hatchlings. His experience helps those taking responsibility for feeding and raising one of these beings after the loss of its mother.",aliasQuestIDs={}},fr={title="Quentin",body="Quentin connaît les soins nécessaires aux nouveau-nés féeriques. Son expérience aide ceux qui prennent la responsabilité de nourrir et d’élever l’un de ces êtres après la perte de sa mère."},de={title="Quentin",body="Quentin kennt die Fürsorge, die Feen-Drachenschlüpflinge brauchen. Seine Erfahrung hilft denjenigen, die nach dem Verlust der Mutter die Verantwortung für die Ernährung und Erziehung eines dieser Wesen übernehmen."},pt={title="Quentin",body="Quentin conhece os cuidados necessários por filhotes de dragão fada. Sua experiência ajuda aqueles que assumem a responsabilidade de alimentar e criar um desses seres após a perda de sua mãe."},pl={title="Quentin",body="Quentin zna opiekę potrzebną młodym baśniowym smokom. Jego doświadczenie pomaga osobom biorącym odpowiedzialność za karmienie i wychowanie takiej istoty po utracie matki."},ru={title="Quentin",body="Quentin знает, какая забота нужна детенышам фей. Его опыт помогает тем, кто берет на себя ответственность за кормление и воспитание одного из этих существ после потери его матери."},references={}},
    ["person:quintis-jonespyre"] = {title="Quintis Jonguja",kind="Personaje",aliases={"Quintis","Quintis Jonguja"},body="Quintis Jonguja es un investigador del Bastión Plumaluna especializado en maldiciones. Sus estudios abarcan las propiedades de plantas como la mañagrana y los usos que otras personas hacen de ellas.",aliasQuestIDs={},en={title="Quintis Jonespyre",aliases={"Quintis","Quintis Jonespyre"},body="Quintis Jonespyre is a researcher at Feathermoon Stronghold specializing in curses. His studies include the properties of plants such as morrowgrain and the uses others make of them.",aliasQuestIDs={}},fr={title="Quintis Jonespyre",body="Quintis Jonespyre est chercheur à Feathermoon Stronghold spécialisé dans les malédictions. Ses études portent sur les propriétés de plantes telles que le morrowgrain et les utilisations que d’autres en font."},de={title="Quintis Jonespyre",body="Quintis Jonespyre ist Forscher bei Feathermoon Stronghold und hat sich auf Flüche spezialisiert. Seine Studien umfassen die Eigenschaften von Pflanzen wie Morrowgrain und die Verwendung anderer Getreide."},pt={title="Quintis Jonespyre",body="Quintis Jonespyre é um pesquisador da Feathermoon Stronghold especializado em maldições. Seus estudos incluem as propriedades de plantas como a morrowgrain e os usos que outros fazem delas."},pl={title="Quintis Jonespyre",body="Quintis Jonespyre jest badaczem w Feathermoon Stronghold specjalizującym się w klątwach. Bada między innymi właściwości roślin takich jak morrowgrain oraz sposoby ich wykorzystywania przez innych."},ru={title="Quintis Jonespyre",body="Quintis Jonespyre - исследователь в Feathermoon Stronghold, специализирующийся на проклятиях. Его исследования включают свойства растений, таких как моргрен и использование их другими."},references={["object:morrowgrain"]=true,["place:feathermoon-stronghold"]=true}},
    ["person:rabine-saturna"] = {title="Rabine Saturna",kind="Personaje",aliases={"Rabine","Rabine Saturna"},body="Rabine Saturna es el mayordomo del guardián Remulos en Claro de la Luna. Participa en las investigaciones y tareas con las que el Círculo Cenarion intenta comprender las amenazas a los territorios de Kalimdor.",aliasQuestIDs={},en={title="Rabine Saturna",aliases={"Rabine","Rabine Saturna"},body="Rabine Saturna is Keeper Remulos’s steward in Moonglade. He participates in the investigations and work through which the Cenarion Circle seeks to understand threats to Kalimdor’s lands.",aliasQuestIDs={}},fr={title="Rabine Saturna",body="Rabine Saturna est le steward de Keeper Remulos dans Moonglade. Il participe aux enquêtes et aux travaux par lesquels le Cenarion Circle cherche à comprendre les menaces qui pèsent sur les terres du Kalimdor."},de={title="Rabine Saturna",body="Rabine Saturna ist Keeper Remulos \"Verwalter in Moonglade. Er beteiligt sich an den Untersuchungen und der Arbeit, durch die Cenarion Circle versucht, Bedrohungen für Kalimdor 's Land zu verstehen."},pt={title="Rabine Saturna",body="Rabine Saturna é o mordomo da Keeper Remulos em Moonglade. Ele participa das investigações e trabalhos através dos quais o Cenarion Circle procura entender as ameaças às terras do Kalimdor."},pl={title="Rabine Saturna",body="Rabine Saturna jest zarządcą służącym postaci Keeper Remulos w Moonglade. Uczestniczy w badaniach i pracach, poprzez które Cenarion Circle próbuje zrozumieć zagrożenia dla ziem kontynentu Kalimdor."},ru={title="Rabine Saturna",body="Rabine Saturna это Keeper Remulos  управляющий в Moonglade. Он участвует в расследованиях и работе, посредством которой Cenarion Circle стремится понять угрозы для земель Kalimdor."},references={["organization:cenarion-circle"]=true,["person:keeper-remulos"]=true,["place:kalimdor"]=true,["place:moonglade"]=true}},
    ["person:raene-wolfrunner"] = {title="Raene Correlobo",kind="Personaje",aliases={"Raene","Raene Correlobo"},body="Raene Correlobo participa en la defensa de Astranaar y de los caminos de Vallefresno. Sus tareas se centran en proteger a los habitantes del bosque y en comprender las amenazas que alteran su equilibrio.",aliasQuestIDs={},en={title="Raene Wolfrunner",aliases={"Raene","Raene Wolfrunner"},body="Raene Wolfrunner takes part in defending Astranaar and Ashenvale’s roads. Her work centers on protecting the forest’s inhabitants and understanding threats disturbing its balance.",aliasQuestIDs={}},fr={title="Raene Wolfrunner",body="Raene Wolfrunner participe à la défense des routes Astranaar et Ashenvale. Son travail se concentre sur la protection des habitants de la forêt et la compréhension des menaces qui perturbent son équilibre."},de={title="Raene Wolfrunner",body="Raene Wolfrunner nimmt an der Verteidigung der Straßen von Astranaar und Ashenvale teil. Im Mittelpunkt ihrer Arbeit stehen der Schutz der Waldbewohner und das Verständnis von Bedrohungen, die das Gleichgewicht störenden Gefahren."},pt={title="Raene Wolfrunner",body="Raene Wolfrunner participa na defesa das estradas de Astranaar e Ashenvale. Seu trabalho centra-se na proteção dos habitantes da floresta e na compreensão de ameaças que perturbam seu equilíbrio."},pl={title="Raene Wolfrunner",body="Raene Wolfrunner uczestniczy w obronie Astranaar i dróg Ashenvale. Skupia się na ochronie mieszkańców lasu oraz zrozumieniu zagrożeń zakłócających jego równowagę."},ru={title="Raene Wolfrunner",body="Raene Wolfrunner участвует в защите дорог Astranaar и Ashenvale s. Ее работа сосредоточена на защите обитателей леса и понимании угроз, нарушающих его равновесие."},references={["place:ashenvale"]=true,["place:astranaar"]=true}},
    ["person:rahauro"] = {title="Rahauro",kind="Personaje",aliases={"Rahauro"},body="Rahauro actúa en Cima del Trueno y participa en encargos de Magatha. Recibe noticias y objetos recuperados por quienes buscan a miembros de su clan lejos de las cumbres de la ciudad.",aliasQuestIDs={},en={title="Rahauro",aliases={"Rahauro"},body="Rahauro operates in Thunder Bluff and takes part in Magatha’s affairs. He receives reports and recovered belongings from those searching for members of her clan far from the city’s mesas.",aliasQuestIDs={}},fr={title="Rahauro",body="Rahauro opère à Thunder Bluff et participe aux affaires de Magatha. Il reçoit des rapports et récupère des biens de ceux qui cherchent des membres de son clan loin des mesas de la ville."},de={title="Rahauro",body="Rahauro arbeitet in Thunder Bluff und kümmert sich um Magatha 'Angelegenheiten. Er erhält Berichte und erlangt Habseligkeiten von Menschen, die nach Mitgliedern ihres Clangt haben, die weit entfernt von den Tafas der Stadt suchen."},pt={title="Rahauro",body="Rahauro opera em Thunder Bluff e participa nos assuntos de Magatha. Ele recebe relatórios e bens recuperados daqueles que procuram por membros de seu clã longe das mesas da cidade."},pl={title="Rahauro",body="Rahauro działa w Thunder Bluff i uczestniczy w sprawach postaci Magatha. Przyjmuje raporty i odzyskane rzeczy od osób szukających członków jej klanu daleko od miejskich płaskowyżów."},ru={title="Rahauro",body="Rahauro работает в Thunder Bluff и участвует в делах Magatha. Он получает сообщения и извлекает вещи от тех, кто ищет членов ее клана далеко от городских столов."},references={["person:magatha-grimtotem"]=true,["place:thunder-bluff"]=true}},
    ["person:ranshalla"] = {title="Ranshalla",kind="Personaje",aliases={"Ranshalla"},body="Ranshalla investiga antiguos lugares de culto de Elune en Cuna del Invierno. Su trabajo combina el estudio de inscripciones con la reconstrucción de los ritos que permiten acceder a esos santuarios.",aliasQuestIDs={},en={title="Ranshalla",aliases={"Ranshalla"},body="Ranshalla investigates ancient sites of Elune worship in Winterspring. Her work combines studying inscriptions with reconstructing the rites allowing access to those sanctuaries.",aliasQuestIDs={}},fr={title="Ranshalla",body="Ranshalla étudie les sites antiques du culte Elune dans Winterspring. Son travail combine l’étude des inscriptions avec la reconstruction des rites permettant l’accès à ces sanctuaires."},de={title="Ranshalla",body="Ranshalla untersucht antike Stätten der Elune-Verehrung in Winterspring. Ihre Arbeit verbindet das Studium von Inschriften mit der Rekonstruktion der Riten, die Zugang zu diesen Heiligtümern ermöglichen."},pt={title="Ranshalla",body="Ranshalla investiga locais antigos de adoração Elune em Winterspring. Seu trabalho combina o estudo de inscrições com a reconstrução dos ritos que permitem o acesso a esses santuários."},pl={title="Ranshalla",body="Ranshalla bada pradawne miejsca kultu bogini Elune w Winterspring. Łączy badanie inskrypcji z odtwarzaniem obrzędów umożliwiających dostęp do tych sanktuariów."},ru={title="Ranshalla",body="Ranshalla исследует древние места поклонения Elune в Winterspring. Ее работа сочетает в себе изучение надписей с реконструкцией обрядов, позволяющих получить доступ к этим святыням."},references={["npc:elune"]=true,["place:winterspring"]=true}},
    ["person:raschal"] = {title="Raschal",kind="Personaje",aliases={"Raschal"},body="Raschal es un mensajero de las fuerzas del Bastión Plumaluna. Su experiencia en Feralas le permite llevar noticias entre asentamientos, aunque los caminos y las rutas costeras siguen siendo peligrosos.",aliasQuestIDs={},en={title="Raschal",aliases={"Raschal"},body="Raschal is a messenger for the forces at Feathermoon Stronghold. His experience of Feralas allows him to carry news between settlements, although the roads and coastal routes remain dangerous.",aliasQuestIDs={}},fr={title="Raschal",body="Raschal est un messager pour les forces à Feathermoon Stronghold. Son expérience de Feralas lui permet de transporter des nouvelles entre les colonies, bien que les routes et les routes côtières restent dangereuses."},de={title="Raschal",body="Raschal ist ein Bote für die Kräfte bei Feathermoon Stronghold. Seine Erfahrung mit Feralas erlaubt es ihm, Nachrichten zwischen den Siedlungen hindurch zu tragen, obwohl die Straßen und die Küstenrouten gefährlich bleiben."},pt={title="Raschal",body="Raschal é um mensageiro para as forças em Feathermoon Stronghold. Sua experiência com o Feralas lhe permite levar notícias entre assentamentos, embora as estradas e rotas costeiras permaneçam perigosas."},pl={title="Raschal",body="Raschal jest posłańcem sił z Feathermoon Stronghold. Znajomość Feralas pozwala mu przenosić wieści między osadami, choć drogi oraz szlaki wybrzeża pozostają niebezpieczne."},ru={title="Raschal",body="Raschal - это посланник сил Feathermoon Stronghold. Его опыт Feralas позволяет ему нести новости между поселениями, хотя дороги и прибрежные маршруты остаются опасными."},references={["place:feathermoon-stronghold"]=true,["place:feralas"]=true}},
    ["person:rathiril-sunlance"] = {title="Rathiril Lanzasol",kind="Personaje",aliases={"Rathiril","Rathiril Lanzasol"},body="Rathiril Lanzasol es un veterano de la Suma Orden que reside en la Aldea Shen'dar. Se encuentra en la cabaña principal y actúa como referente local de la tradición de la orden. Su presencia vincula a esta pequeña comunidad de Zephras con la herencia arcana de los altonatos.",aliasQuestIDs={},en={title="Rathiril Sunlance",aliases={"Rathiril","Rathiril Sunlance"},body="Rathiril Sunlance is an elder of the High Order living in Shen'dar Village. He can be found in the main lodge and serves as a local representative of the order's tradition. His presence connects this small Zephras community with the arcane heritage of the highborne.",aliasQuestIDs={}},fr={title="Rathiril Sunlance",body="Rathiril Sunlance est un aîné de the High Order vivant à Shen'dar Village. Il peut être trouvé dans la loge principale et sert de représentant local de la tradition de l'ordre. Sa présence relie cette petite communauté Zephras au patrimoine arcanique de la haute société."},de={title="Rathiril Sunlance",body="Rathiril Sunlance ist ein Ältester von „the High Order“ und lebt in Shen'dar Village. Er ist im Haupthaus anzutreffen und vertritt vor Ort die Tradition seines Ordens. Seine Anwesenheit verbindet diese kleine Gemeinschaft auf Zephras mit dem arkanen Erbe der Hochgeborenen."},pt={title="Rathiril Sunlance",body="Rathiril Sunlance é um ancião de the High Order que vive em Shen'dar Village. Ele pode ser encontrado na loja principal e serve como um representante local da tradição da ordem. Sua presença conecta esta pequena comunidade Zephras com a herança arcana do highborne."},pl={title="Rathiril Sunlance",body="Rathiril Sunlance jest starszym organizacji znanej jako the High Order mieszkającym w Shen'dar Village. Przebywa w głównej siedzibie i reprezentuje lokalnie tradycję zakonu. Jego obecność łączy małą społeczność Zephras z tajemnym dziedzictwem highborne."},ru={title="Rathiril Sunlance",body="Rathiril Sunlance - старший из the High Order, живущий в Shen'dar Village. Его можно найти в главной ложе и он служит местным представителем традиции ордена. Его присутствие связывает это маленькое сообщество Zephras с тайным наследием высокого рода."},references={["organization:high-order"]=true,["organization:highborne"]=true,["place:shendar"]=true,["place:zephras"]=true}},
    ["person:rau-cliffrunner"] = {title="Rau Abiscorredor",kind="Personaje",aliases={"Rau","Rau Abiscorredor"},body="Rau Abiscorredor trabaja en el Poblado Viento Libre, en Las Mil Agujas. Estudia los vínculos entre dríades y centauros y las propiedades del agua sagrada que puede servir para enfrentarse a estos últimos.",aliasQuestIDs={},en={title="Rau Cliffrunner",aliases={"Rau","Rau Cliffrunner"},body="Rau Cliffrunner works at Freewind Post in Thousand Needles. He studies the shared ancestry of dryads and centaurs and the properties of sacred water that can be used against the latter.",aliasQuestIDs={}},fr={title="Rau Cliffrunner",body="Rau Cliffrunner travaille à Freewind Post dans Thousand Needles. Il étudie l'ascendance commune des dryades et des centaures et les propriétés de l'eau sacrée qui peuvent être utilisées contre cette dernière."},de={title="Rau Cliffrunner",body="Rau Cliffrunner arbeitet bei Freewind Post in Thousand Needles. Er untersucht die gemeinsame Abstammung von Trocken- und Zentauren sowie die Eigenschaften von Weihwasser, die gegen letzteres eingesetzt werden können."},pt={title="Rau Cliffrunner",body="Rau Cliffrunner trabalha na Freewind Post em Thousand Needles. Ele estuda a ancestralidade compartilhada de dryads e centauros e as propriedades da água sagrada que pode ser usada contra o último."},pl={title="Rau Cliffrunner",body="Rau Cliffrunner pracuje w Freewind Post w Thousand Needles. Bada wspólne pochodzenie driad i centaurów oraz właściwości świętej wody, którą można wykorzystać przeciw tym drugim."},ru={title="Rau Cliffrunner",body="Rau Cliffrunner работает на Freewind Post в Thousand Needles. Он изучает общие предки дриадов и кентавров и свойства священной воды, которые могут быть использованы против последних."},references={["place:freewind-post"]=true,["place:thousand-needles"]=true}},
    ["person:rawrk"] = {title="Rawrk",kind="Personaje",aliases={"Rawrk"},body="Rawrk enseña primeros auxilios en Cerrotajo. Sus conocimientos también permiten preparar equipo para los campamentos, de modo que los aventureros puedan atender heridas durante sus viajes.",aliasQuestIDs={},en={title="Rawrk",aliases={"Rawrk"},body="Rawrk teaches first aid in Razor Hill. His knowledge also supports the preparation of camp equipment so that adventurers can treat wounds during their travels.",aliasQuestIDs={}},fr={title="Rawrk",body="Rawrk enseigne les premiers soins dans Razor Hill. Ses connaissances soutiennent également la préparation de l'équipement du camp afin que les aventuriers puissent traiter les blessures pendant leurs voyages."},de={title="Rawrk",body="Rawrk bringt Razor Hill Erste Hilfe bei. Sein Wissen unterstützt auch die Vorbereitung der Lagerausrüstung, damit Abenteurer auf ihren Reisen Wunden behandeln können."},pt={title="Rawrk",body="Rawrk ensina primeiros socorros no Razor Hill. Seu conhecimento também suporta a preparação de equipamentos de acampamento para que os aventureiros possam tratar feridas durante suas viagens."},pl={title="Rawrk",body="Rawrk uczy pierwszej pomocy w Razor Hill. Jego wiedza wspiera również przygotowywanie wyposażenia obozowego, aby poszukiwacze przygód mogli leczyć rany podczas podróży."},ru={title="Rawrk",body="Rawrk учит первой помощи в Razor Hill. Его знания также помогают в подготовке лагерного снаряжения, чтобы авантюристы могли лечить раны во время путешествий."},references={["place:razor-hill"]=true}},
    ["person:razzeric"] = {title="Razzeric",kind="Personaje",aliases={"Razzeric"},body="Razzeric trabaja con los vehículos de carreras del Desierto de Sal. Busca aumentar su potencia mediante ajustes y componentes especiales, con una inclinación por la velocidad que supera la cautela de otros mecánicos.",aliasQuestIDs={},en={title="Razzeric",aliases={"Razzeric"},body="Razzeric works with racing vehicles in the Shimmering Flats. He seeks greater power through adjustments and specialized components, with an appetite for speed that exceeds the caution of other mechanics.",aliasQuestIDs={}},fr={title="Razzeric",body="Razzeric travaille avec les véhicules de course dans le Shimmering Flats. Il cherche une plus grande puissance grâce à des ajustements et des composants spécialisés, avec un appétit pour la vitesse qui dépasse la prudence des autres mécaniciens."},de={title="Razzeric",body="Razzeric arbeitet mit Rennfahrzeugen im Shimmering Flats. Er strebt nach größerer Macht durch Anpassungen und spezialisierte Komponenten, mit einem Drang nach Geschwindigkeit, der die die die die Vorsicht anderer Mechanik übersteigt."},pt={title="Razzeric",body="Razzeric trabalha com veículos de corrida no Shimmering Flats. Ele busca maior poder através de ajustes e componentes especializados, com um apetite por velocidade que excede a cautela de outros mecânicos."},pl={title="Razzeric",body="Razzeric pracuje przy pojazdach wyścigowych w Shimmering Flats. Szuka większej mocy dzięki regulacjom i specjalistycznym częściom, a jego głód szybkości przewyższa ostrożność innych mechaników."},ru={title="Razzeric",body="Razzeric работает с гоночными машинами в Shimmering Flats. Он стремится к большей мощности с помощью регулировок и специализированных компонентов, с аппетитом к скорости, который превышает осторожность других механиков."},references={["place:shimmering-flats"]=true}},
    ["person:regthar-deathgate"] = {title="Regthar Portamorta",kind="Personaje",aliases={"Regthar","Regthar Portamorta"},body="Regthar Portamorta vigila a los centauros Kolkar al oeste de El Cruce. Su labor se centra en debilitar a sus jefes y reducir la amenaza que sus bandas representan para Los Baldíos.",aliasQuestIDs={},en={title="Regthar Deathgate",aliases={"Regthar","Regthar Deathgate"},body="Regthar Deathgate watches the Kolkar centaurs west of the Crossroads. His work focuses on weakening their leaders and reducing the threat their bands pose to the Barrens.",aliasQuestIDs={}},fr={title="Regthar Deathgate",body="Regthar Deathgate regarde les centaures Kolkar à l'ouest de la Crossroads. Son travail se concentre sur l'affaiblissement de leurs dirigeants et la réduction de la menace que leurs groupes posent pour le Barrens."},de={title="Regthar Deathgate",body="Regthar Deathgate beobachtet die Kolkar-Zentauren westlich des Crossroads. Seine Arbeit konzentriert sich auf die Schwächung ihrer Führer und die Verringerung der Bedrohung, die ihre Bands für die Barrens darstellen."},pt={title="Regthar Deathgate",body="Regthar Deathgate observa os centauros Kolkar a oeste do Crossroads. Seu trabalho se concentra em enfraquecer seus líderes e reduzir a ameaça que suas bandas representam para o Barrens."},pl={title="Regthar Deathgate",body="Regthar Deathgate obserwuje centaury Kolkar na zachód od Crossroads. Skupia się na osłabianiu ich przywódców i ograniczaniu zagrożenia, jakie ich grupy stanowią dla Barrens."},ru={title="Regthar Deathgate",body="Regthar Deathgate следит за кентаврами Kolkar к западу от Crossroads. Его работа направлена на ослабление их лидеров и снижение угрозы, которую их группы представляют для Barrens."},references={["organization:kolkar"]=true,["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:rellian-greenspyre"] = {title="Rellian Verdeguja",kind="Personaje",aliases={"Rellian","Rellian Verdeguja"},body="Rellian Verdeguja es un druida del Enclave Cenarion de Darnassus. Investiga la flora de Teldrassil y mantiene un intercambio de muestras e ideas con otros estudiosos del bosque.",aliasQuestIDs={},en={title="Rellian Greenspyre",aliases={"Rellian","Rellian Greenspyre"},body="Rellian Greenspyre is a druid in Darnassus’s Cenarion Enclave. He studies Teldrassil’s plants and exchanges samples and ideas with other students of the forest.",aliasQuestIDs={}},fr={title="Rellian Greenspyre",body="Rellian Greenspyre est un druide dans Darnassus’s Cenarion Enclave. Il étudie les plantes de Teldrassil et échange des échantillons et des idées avec d’autres étudiants de la forêt."},de={title="Rellian Greenspyre",body="Rellian Greenspyre ist Druide in Darnassus 's Cenarion Enclave. Er studiert die Pflanzen von Teldrassil und tauscht sich mit anderen Waldschülern über Muster und Ideen aus."},pt={title="Rellian Greenspyre",body="Rellian Greenspyre é um druida no Darnassus do Cenarion Enclave. Ele estuda as plantas do Teldrassil e troca amostras e ideias com outros estudantes da floresta."},pl={title="Rellian Greenspyre",body="Rellian Greenspyre jest druidem w Cenarion Enclave w mieście Darnassus. Bada rośliny Teldrassil, wymieniając próbki oraz pomysły z innymi badaczami lasu."},ru={title="Rellian Greenspyre",body="Rellian Greenspyre - это друид в Darnassus s Cenarion Enclave. Он изучает растения Teldrassil  и обменивается образцами и идеями с другими студентами леса."},references={["place:darnassus"]=true,["place:teldrassil"]=true}},
    ["person:rexxar"] = {title="Rexxar",kind="Personaje",aliases={"Rexxar"},body="Rexxar es un campeón de la Horda que recorre las tierras salvajes de Kalimdor. Su reputación como combatiente y su relación con distintos pueblos hacen de él un aliado respetado en asuntos que requieren fuerza y criterio.",aliasQuestIDs={},en={title="Rexxar",aliases={"Rexxar"},body="Rexxar is a Horde champion who travels Kalimdor’s wild lands. His reputation as a fighter and his relationships with different peoples make him a respected ally in matters requiring strength and judgment.",aliasQuestIDs={}},fr={title="Rexxar",body="Rexxar est un champion Horde qui parcourt les terres sauvages de Kalimdor. Sa réputation de combattant et ses relations avec différents peuples font de lui un allié respecté dans les domaines exigeant force et jugement."},de={title="Rexxar",body="Rexxar ist ein Horde-Champion, der Kalimdor 'wilde Länder bereist. Sein Ruf als Kämpfer und seine Beziehungen zu verschiedenen Völkern machen ihn zu einem respektierten Verbündeten in Angelegenheiten, die Stärke und Urteilsvermögen erfordern."},pt={title="Rexxar",body="Rexxar é um campeão Horde que viaja pelas terras selvagens de Kalimdor. Sua reputação como lutador e suas relações com diferentes povos fazem dele um aliado respeitado em questões que exigem força e julgamento."},pl={title="Rexxar",body="Rexxar jest czempionem frakcji Horde przemierzającym dzikie ziemie kontynentu Kalimdor. Sława wojownika i relacje z różnymi ludami czynią go szanowanym sojusznikiem w sprawach wymagających siły oraz rozwagi."},ru={title="Rexxar",body="Rexxar - чемпион Horde, который путешествует по диким землям Kalimdor. Его репутация воина и отношения с разными народами делают его уважаемым союзником в вопросах, требующих силы и мудрости."},references={["organization:horde"]=true,["place:kalimdor"]=true}},
    ["person:rezlak"] = {title="Rezlak",kind="Personaje",aliases={"Rezlak"},body="Rezlak trabaja para Gazlowe cerca de Orgrimmar. Su tarea de ayudar a los orcos de Durotar depende de que las caravanas y los suministros puedan llegar a destino.",aliasQuestIDs={},en={title="Rezlak",aliases={"Rezlak"},body="Rezlak works for Gazlowe near Orgrimmar. His job of helping Durotar’s orcs depends on caravans and supplies reaching their destination.",aliasQuestIDs={}},fr={title="Rezlak",body="Rezlak travaille pour Gazlowe près de Orgrimmar. Son travail d’aider les orcs de Durotar dépend des caravanes et des fournitures qui arrivent à destination."},de={title="Rezlak",body="Rezlak arbeitet für Gazlowe bei Orgrimmar. Seine Aufgabe, den Orks von Durotar zu helfen, hängt davon ab, dass Karawanen und Vorräte ihr Ziel erreichen."},pt={title="Rezlak",body="Rezlak trabalha para Gazlowe perto de Orgrimmar. Seu trabalho de ajudar os orcs do Durotar depende de caravanas e suprimentos chegarem ao seu destino."},pl={title="Rezlak",body="Rezlak pracuje dla postaci Gazlowe w pobliżu Orgrimmar. Jego zadanie pomagania orkom Durotar zależy od docierania karawan i zapasów do celu."},ru={title="Rezlak",body="Rezlak работает для Gazlowe рядом с Orgrimmar. Его работа, помогать оркам Durotar  зависит от караванов и припасов, которые доберутся до их места назначения."},references={["person:gazlowe"]=true,["place:durotar"]=true,["place:orgrimmar"]=true}},
    ["person:rhinag"] = {title="Rhinag",kind="Personaje",aliases={"Rhinag"},body="Rhinag es un combatiente de Durotar que conoce el peligro del veneno de los venocolas. Sus contactos con Orgrimmar muestran la importancia de disponer de antídotos y ayuda rápida en los caminos de la región.",aliasQuestIDs={},en={title="Rhinag",aliases={"Rhinag"},body="Rhinag is a Durotar fighter who knows the danger of venomtail poison. His contacts in Orgrimmar show the importance of antidotes and prompt help on the region’s roads.",aliasQuestIDs={}},fr={title="Rhinag",body="Rhinag est un combattant Durotar qui connaît le danger du poison à queue de venin. Ses contacts à Orgrimmar montrent l’importance des antidotes et de l’aide rapide sur les routes de la région."},de={title="Rhinag",body="Rhinag ist ein Durotar-Kämpfer, der die Gefahr des Giftschwanzgiftes kennt. Seine Kontakte zu Orgrimmar zeigen, wie wichtig Gegenmittel und schnelle Hilfe auf den Straßen der Region sind."},pt={title="Rhinag",body="Rhinag é um lutador Durotar que conhece o perigo do veneno de cauda de veneno. Seus contatos no Orgrimmar mostram a importância de antídotos e ajuda imediata nas estradas da região."},pl={title="Rhinag",body="Rhinag jest wojownikiem Durotar znającym niebezpieczeństwo trucizny jadowitego ogona. Kontakty w Orgrimmar pokazują znaczenie odtrutek i szybkiej pomocy na drogach regionu."},ru={title="Rhinag",body="Rhinag - это боец Durotar, который знает опасность яда от ядовитого хвоста. Его контакты в Orgrimmar показывают важность противоядий и оперативной помощи на дорогах региона."},references={["place:durotar"]=true,["place:orgrimmar"]=true}},
    ["person:rigger-gizelton"] = {title="Rigger Gizelton",kind="Personaje",aliases={"Rigger","Rigger Gizelton"},body="Rigger fundó junto con Cork una caravana comercial en busca de ganancias. Transportar sus mercancías por Desolace exige proteger a los kodos y mantener acuerdos con socios como Smeed, incluso cuando los peligros del Aquelarre Mannoroc reducen el beneficio.",aliasQuestIDs={},en={title="Rigger Gizelton",aliases={"Rigger","Rigger Gizelton"},body="Rigger founded a trading caravan with Cork in pursuit of profit. Carrying goods through Desolace requires protecting the kodos and maintaining agreements with associates such as Smeed, even when Mannoroc Coven’s dangers cut into the returns.",aliasQuestIDs={}},fr={title="Rigger Gizelton",body="Rigger a fondé une caravane de négociation avec Cork dans la poursuite du profit. Le transport de marchandises via Desolace nécessite de protéger les kodos et de maintenir des accords avec des associés tels que Smeed, même lorsque les dangers de Mannoroc Coven se répercutent sur les retours."},de={title="Rigger Gizelton",body="Rigger gründete mit Cork eine Handelskarawane, um Profit zu machen. Der Warentransport durch Desolace erfordert den Schutz der Kodos und die Einhaltung von Vereinbarungen mit Partnern wie Smeed, auch wenn Mannoroc Coven 'Gefahren die Retouren behindern."},pt={title="Rigger Gizelton",body="Rigger fundou uma caravana comercial com Cork em busca de lucro. O transporte de mercadorias através do Desolace requer a proteção dos kodos e a manutenção de acordos com associados, como o Smeed, mesmo quando os perigos do Mannoroc Coven cortam os retornos."},pl={title="Rigger Gizelton",body="Rigger założył wspólnie z Cork karawanę handlową, licząc na zyski. Przewożenie towarów przez Desolace wymaga ochrony kodo i dotrzymywania umów ze wspólnikami takimi jak Smeed, nawet gdy zagrożenia ze strony Mannoroc Coven uszczuplają zarobek."},ru={title="Rigger Gizelton",body="Rigger основал торговый караван с Cork в погоне за прибылью. Перевозка товаров через Desolace требует защиты кодо и поддержания соглашений с партнерами, такими как Smeed, даже когда опасности Mannoroc Coven  препятствуют возврату."},references={["person:cork-gizelton"]=true,["person:smeed"]=true,["place:desolace"]=true,["place:mannoroc-coven"]=true},questIDs={[5943]=true}},
    ["person:rilli-greasygob"] = {title="Rilli Gapegajoso",kind="Personaje",aliases={"Rilli","Rilli Gapegajoso"},body="Rilli Gapegajoso es un técnico que trabajó para Ventura y Cía. y ahora se encuentra en el Rincón de la Maquinaria de Nogg. Su experiencia industrial ayuda a comprender y reparar aparatos como el churumbele.",aliasQuestIDs={},en={title="Rilli Greasygob",aliases={"Rilli","Rilli Greasygob"},body="Rilli Greasygob is a technician who worked for the Venture Company and is now at Nogg’s Machine Shop. His industrial experience helps him understand and repair devices such as the Samophlange.",aliasQuestIDs={}},fr={title="Rilli Greasygob",body="Rilli Greasygob est un technicien qui a travaillé pour le Venture Company et est maintenant à Nogg’s Machine Shop. Son expérience industrielle lui permet de comprendre et de réparer des appareils tels que le Samophlange."},de={title="Rilli Greasygob",body="Rilli Greasygob ist Techniker bei der Firma Venture Company und arbeitet jetzt bei Nogg 's Maschinenfabrik. Seine industrielle Erfahrung hilft ihm, Geräte wie den Samophlange zu verstehen und zu reparieren."},pt={title="Rilli Greasygob",body="Rilli Greasygob é um técnico que trabalhou para o Venture Company e agora está na Loja de Máquinas do Nogg. Sua experiência industrial o ajuda a entender e reparar dispositivos como o Samophlange."},pl={title="Rilli Greasygob",body="Rilli Greasygob jest technikiem, który pracował dla Venture Company, a obecnie działa w warsztacie maszynowym Nogg. Doświadczenie przemysłowe pomaga mu rozumieć i naprawiać urządzenia takie jak Samophlange."},ru={title="Rilli Greasygob",body="Rilli Greasygob - технический специалист, работавший на Venture Company и сейчас работает в Nogg 's Machine Shop. Его опыт в промышленности помогает ему понимать и ремонтировать такие устройства, как Samophlange."},references={["object:samophlange"]=true,["organization:venture-company"]=true,["person:nogg"]=true}},
    ["person:ringo"] = {title="Ringo",kind="Personaje",aliases={"Ringo"},body="Ringo es un explorador del Cráter de Un'Goro relacionado con Spraggle Frock. El calor extremo de la región pone a prueba su resistencia y recuerda que la exploración depende tanto del agua como del valor.",aliasQuestIDs={},en={title="Ringo",aliases={"Ringo"},body="Ringo is an explorer in Un'Goro Crater associated with Spraggle Frock. The region’s extreme heat tests his endurance and serves as a reminder that exploration depends as much on water as on courage.",aliasQuestIDs={}},fr={title="Ringo",body="Ringo est un explorateur dans Un'Goro Crater associé à Spraggle Frock. La chaleur extrême de la région met à l’épreuve son endurance et rappelle que l’exploration dépend autant de l’eau que du courage."},de={title="Ringo",body="Ringo ist ein Forscher in Un'Goro Crater, der mit Spraggle Frock in Verbindung gebracht wird. Die extreme Hitze in der Region stellt seine Ausdauer auf die Probe und erinnert ihn daran, dass die Erforschung ebenso sehr vom Wasser wie vom Mut abhängt."},pt={title="Ringo",body="Ringo é um explorador no Un'Goro Crater associado ao Spraggle Frock. O calor extremo da região testa sua resistência e serve como um lembrete de que a exploração depende tanto da água quanto da coragem."},pl={title="Ringo",body="Ringo jest odkrywcą w Un'Goro Crater związanym z postacią Spraggle Frock. Skrajne gorąco wystawia jego wytrzymałość na próbę i przypomina, że eksploracja zależy od wody równie mocno jak od odwagi."},ru={title="Ringo",body="Ringo - это исследователь в Un'Goro Crater, связанный с Spraggle Frock. Экстремальная жара в этом регионе испытывает его выносливость и служит напоминанием о том, что исследования зависят от воды так же, как от мужества."},references={["person:spraggle-frock"]=true,["place:ungoro-crater"]=true}},
    ["person:rivern-frostwind"] = {title="Rivern Ventogélido",kind="Personaje",aliases={"Rivern","Rivern Ventogélido"},body="Rivern Ventogélido entrena sables de hielo en Cuna del Invierno. Su labor exige conseguir alimento para los animales y mantener a raya a las criaturas que amenazan su refugio.",aliasQuestIDs={},en={title="Rivern Frostwind",aliases={"Rivern","Rivern Frostwind"},body="Rivern Frostwind trains frostsabers in Winterspring. His work requires obtaining food for the animals and keeping creatures that threaten their refuge at bay.",aliasQuestIDs={}},fr={title="Rivern Frostwind",body="Rivern Frostwind entraîne des sabres givrés dans Winterspring. Son travail exige d’obtenir de la nourriture pour les animaux et de tenir à distance les créatures qui menacent leur refuge."},de={title="Rivern Frostwind",body="Rivern Frostwind trainiert in Winterspring Frostsäbel. Seine Arbeit erfordert es, Nahrung für die Tiere zu beschaffen und Kreaturen, die ihre Zuflucht bedrohen, in Schach zu halten."},pt={title="Rivern Frostwind",body="Rivern Frostwind treina geadas em Winterspring. Seu trabalho requer a obtenção de alimentos para os animais e manter as criaturas que ameaçam seu refúgio na baía."},pl={title="Rivern Frostwind",body="Rivern Frostwind szkoli lodowe pantery w Winterspring. Jego praca wymaga zdobywania pokarmu dla zwierząt i powstrzymywania stworzeń zagrażających ich schronieniu."},ru={title="Rivern Frostwind",body="Rivern Frostwind обучает морозомеров в Winterspring. Его работа состоит в том, чтобы снабжать животных пищей и держать на расстоянии животных, которые угрожают их убежищу."},references={["place:winterspring"]=true}},
    ["person:rizzle-brassbolts"] = {title="Rizzle Pernolatón",kind="Personaje",aliases={"Rizzle","Rizzle Pernolatón"},body="Rizzle Pernolatón trabaja con diseños de vehículos para las carreras del Desierto de Sal. Los avances de su equipo despiertan la atención de rivales que intentan comprender cómo consiguen mejorar su velocidad.",aliasQuestIDs={},en={title="Rizzle Brassbolts",aliases={"Rizzle","Rizzle Brassbolts"},body="Rizzle Brassbolts works on vehicle designs for races in the Shimmering Flats. His team’s advances attract rivals trying to understand how they improve their speed.",aliasQuestIDs={}},fr={title="Rizzle Brassbolts",body="Rizzle Brassbolts travaille sur la conception de véhicules pour les courses dans le Shimmering Flats. Les progrès de son équipe attirent des rivaux qui essaient de comprendre comment ils améliorent leur vitesse."},de={title="Rizzle Brassbolts",body="Rizzle Brassbolts arbeitet an Fahrzeugkonstruktionen für Rennen im Shimmering Flats. Die Fortschritte seines Teams locken Rivalen an, die versuchen zu verstehen, wie sie ihre Geschwindigkeit verbessern."},pt={title="Rizzle Brassbolts",body="Rizzle Brassbolts trabalha em projetos de veículos para corridas no Shimmering Flats. Os avanços de sua equipe atraem rivais tentando entender como eles melhoram sua velocidade."},pl={title="Rizzle Brassbolts",body="Rizzle Brassbolts opracowuje projekty pojazdów na wyścigi w Shimmering Flats. Postępy jego zespołu przyciągają rywali próbujących zrozumieć, jak udaje mu się zwiększać szybkość."},ru={title="Rizzle Brassbolts",body="Rizzle Brassbolts работает над проектами автомобилей для гонок в Shimmering Flats. Прогресс его команды привлекает соперников, пытающихся понять, как они улучшают свою скорость."},references={["place:shimmering-flats"]=true}},
    ["person:rockbiter"] = {title="Muerdepiedras",kind="Personaje",aliases={"Muerdepiedras"},body="Muerdepiedras es un gigante de Feralas preocupado por la seguridad de su amiga Shay. Su relación muestra una amistad que atraviesa las diferencias entre quienes comparten las ruinas y los bosques de la región.",aliasQuestIDs={},en={title="Rockbiter",aliases={"Rockbiter"},body="Rockbiter is a giant in Feralas concerned for his friend Shay’s safety. Their relationship shows a friendship across differences between those sharing the region’s ruins and forests.",aliasQuestIDs={}},fr={title="Rockbiter",body="Rockbiter est un géant de Feralas inquiet pour la sécurité de son ami Shay. Leur relation montre une amitié à travers les différences entre ceux qui partagent les ruines de la région et les forêts."},de={title="Rockbiter",body="Rockbiter ist in Feralas ein Riese, der um die Sicherheit seines Freundes Shay besorgt ist. Ihre Beziehung zeigt eine Freundschaft über Unterschiede hinweg zwischen denjenigen, die die die die Ruinen und Wälder der Region teilen."},pt={title="Rockbiter",body="Rockbiter é um gigante em Feralas preocupado com a segurança de seu amigo Shay. Sua relação mostra uma amizade entre as diferenças entre aqueles que compartilham as ruínas da região e as florestas."},pl={title="Rockbiter",body="Rockbiter jest olbrzymem w Feralas troszczącym się o bezpieczeństwo przyjaciółki o imieniu Shay. Ich relacja ukazuje przyjaźń ponad różnicami między mieszkańcami wspólnych ruin i lasów regionu."},ru={title="Rockbiter",body="Rockbiter - гигант в Feralas, который беспокоится о безопасности своего друга Shay. Их отношения показывают дружбу между теми, кто разделяет руины и леса региона."},references={["person:shay-leafrunner"]=true,["place:feralas"]=true}},
    ["person:rok-orhan"] = {title="Rok Orhan",kind="Personaje",aliases={"Rok","Rok Orhan"},body="Rok Orhan organiza la respuesta del Campamento Mojache a los ogros Gordunni. Considera su expansión una amenaza para los asentamientos y las tierras de Feralas.",aliasQuestIDs={},en={title="Rok Orhan",aliases={"Rok","Rok Orhan"},body="Rok Orhan organizes Camp Mojache’s response to the Gordunni ogres. She regards their expansion as a threat to Feralas’s settlements and lands.",aliasQuestIDs={}},fr={title="Rok Orhan",body="Rok Orhan organise la réponse de Camp Mojache aux ogres Gordunni. Elle considère leur expansion comme une menace pour les colonies et les terres de Feralas."},de={title="Rok Orhan",body="Rok Orhan organisiert Camp Mojaches Antwort auf die Gordunni-Oger. Sie sieht ihre Expansion als Bedrohung für Feralass Siedlungen und Land."},pt={title="Rok Orhan",body="Rok Orhan organiza a resposta do Camp Mojache aos ogres Gordunni. Ela considera sua expansão como uma ameaça aos assentamentos e terras da Feralas."},pl={title="Rok Orhan",body="Rok Orhan organizuje odpowiedź Camp Mojache na zagrożenie ze strony ogrów Gordunni. Ich ekspansję uważa za niebezpieczeństwo dla osad i ziem Feralas."},ru={title="Rok Orhan",body="Rok Orhan организует реакцию Camp Mojache  на Огров Gordunni. Она считает их расширение угрозой для поселений и земель Feralas."},references={["organization:gordunni"]=true,["place:camp-mojache"]=true,["place:feralas"]=true}},
    ["person:rokalim-the-pounder"] = {title="Rok'Alim el Aporreador",kind="Personaje",aliases={"Rok'Alim","Rok'Alim el Aporreador","Rok’Alim","Rok’Alim el Aporreador"},body="Rok'Alim es un elemental de Las Mil Agujas. Según las enseñanzas de las pruebas tauren, su poder le permitió permanecer en el mundo por sí mismo cuando otros elementales se desvanecieron o quedaron sujetos a las invocaciones de los magos.",aliasQuestIDs={},en={title="Rok'Alim the Pounder",aliases={"Rok'Alim","Rok'Alim the Pounder","Rok’Alim","Rok’Alim the Pounder"},body="Rok'Alim is an elemental of Thousand Needles. According to the teachings of the tauren trials, his power allowed him to remain in the world independently when other elementals faded or became dependent on mages’ summons.",aliasQuestIDs={}},fr={title="Rok'Alim the Pounder",body="Rok'Alim est un élémental de Thousand Needles. Selon les enseignements des épreuves des taurens, son pouvoir lui a permis de rester dans le monde indépendamment lorsque d’autres élémentaux se sont évanouis ou sont devenus dépendants de l’invocation des mages."},de={title="Rok'Alim the Pounder",body="Rok'Alim ist ein Elementar von Thousand Needles. Gemäß den Lehren der Tauren-Prozesse ermöglichte es ihm seine Macht, unabhängig in der Welt zu bleiben, wenn andere Elementare verblassten oder von den Vorladungen der Magier abhängig wurden."},pt={title="Rok'Alim the Pounder",body="Rok'Alim é um elemento do Thousand Needles. De acordo com os ensinamentos dos julgamentos de tauren, seu poder permitiu que ele permanecesse no mundo independentemente quando outros elementais se desvaneceram ou se tornaram dependentes da convocação dos magos."},pl={title="Rok'Alim the Pounder",body="Rok'Alim jest żywiołakiem Thousand Needles. Według nauk taurenskich prób jego moc pozwoliła mu samodzielnie pozostać na świecie, gdy inne żywiołaki zanikały lub uzależniały się od przywołań magów."},ru={title="Rok'Alim the Pounder",body="Rok'Alim - элементарный Thousand Needles. Согласно учениям о испытаниях Таурена, его сила позволила ему оставаться в мире самостоятельно, когда другие элементалы исчезали или стали зависеть от призыва магов."},references={["place:thousand-needles"]=true}},
    ["person:roon-wildmane"] = {title="Roon Ferocrín",kind="Personaje",aliases={"Roon","Roon Ferocrín"},body="Roon Ferocrín es un cazador de Desolace que conoce a Hemet Nesingwary. Su amistad nació de la caza compartida y muestra que el respeto por una habilidad puede cruzar las enemistades entre pueblos.",aliasQuestIDs={},en={title="Roon Wildmane",aliases={"Roon","Roon Wildmane"},body="Roon Wildmane is a hunter in Desolace who knows Hemet Nesingwary. Their friendship grew from hunting together and shows that respect for a skill can cross hostilities between peoples.",aliasQuestIDs={}},fr={title="Roon Wildmane",body="Roon Wildmane est un chasseur en Desolace qui connaît Hemet Nesingwary. Leur amitié a grandi de la chasse ensemble et montre que le respect pour une compétence peut traverser les hostilités entre les peuples."},de={title="Roon Wildmane",body="Roon Wildmane ist ein Jäger in Desolace, der Hemet Nesingwary kennt. Ihre Freundschaft wuchs aus der gemeinsamen Jagd und zeigt, dass der Respekt für eine Fertigkeit Feindschaften zwischen Völkern überwinden kann."},pt={title="Roon Wildmane",body="Roon Wildmane é um caçador em Desolace que conhece Hemet Nesingwary. Sua amizade cresceu a partir da caça juntos e mostra que o respeito por uma habilidade pode atravessar as hostilidades entre os povos."},pl={title="Roon Wildmane",body="Roon Wildmane jest myśliwym w Desolace znającym postać Hemet Nesingwary. Przyjaźń narodziła się podczas wspólnych polowań i pokazuje, że szacunek dla umiejętności potrafi przekraczać wrogość między ludami."},ru={title="Roon Wildmane",body="Roon Wildmane - это охотник в Desolace, который знает Hemet Nesingwary. Их дружба возникла из-за совместной охоты и показывает, что уважение к искусству может преодолеть вражду между народами."},references={["npc:hemet-nesingwary"]=true,["place:desolace"]=true}},
    ["person:rorian-the-dayseeker"] = {title="Rorian, el Buscadías",kind="Personaje",aliases={"Rorian","Rorian el Buscadías","Rorian, el Buscadías"},body="Rorian, el Buscadías, dirige el Poblado Thendal y recibe a los jóvenes que alcanzan la edad adulta. Se encuentra junto a la entrada del árbol abuelo. Entre sus responsabilidades está atender los problemas cotidianos del poblado y procurar el equilibrio de la fauna de Arboleda Thendal.",aliasQuestIDs={},en={title="Rorian the Dayseeker",aliases={"Rorian","Rorian the Dayseeker"},body="Rorian the Dayseeker leads Thendal Village and welcomes young people coming of age. He can be found beside the entrance to the greatfather tree. His responsibilities include the settlement’s everyday problems and the balance of wildlife in Thendal Grove.",aliasQuestIDs={}},fr={title="Rorian the Dayseeker",body="Rorian the Dayseeker dirige le village Thendal et accueille les jeunes adultes. Il peut être trouvé à côté de l'entrée de l'arbre grand-père. Ses responsabilités comprennent les problèmes quotidiens du règlement et l'équilibre de la faune dans Thendal Grove."},de={title="Rorian the Dayseeker",body="Rorian the Dayseeker leitet das Thendal Village und heißt die heranwachsenden Jugendlichen willkommen. Er steht neben dem Eingang zum Urvater-Baum. Zu seinen Aufgaben gehören die Alltagsprobleme der Siedlung und das Gleichgewicht der Wildtiere in Thendal Grove."},pt={title="Rorian the Dayseeker",body="Rorian the Dayseeker lidera Thendal Village e recebe os jovens que atingem a maioridade. Ele pode ser encontrado ao lado da entrada da árvore do bisavô. Suas responsabilidades incluem os problemas cotidianos do assentamento e o equilíbrio da vida selvagem no Thendal Grove."},pl={title="Rorian the Dayseeker",body="Rorian the Dayseeker przewodzi Thendal Village i wita młodych osiągających dojrzałość. Przebywa przy wejściu do drzewa przodka. Jego obowiązki obejmują codzienne problemy osady i równowagę dzikiej przyrody Thendal Grove."},ru={title="Rorian the Dayseeker",body="Rorian the Dayseeker возглавляет деревню Thendal и принимает молодых людей, достигших совершеннолетия. Его можно найти рядом с входом на древо деда. Его обязанности включают повседневные проблемы поселения и баланс дикой природы в Thendal Grove."},references={["place:thendal-grove"]=true}},
    ["person:ruga-ragetotem"] = {title="Ruga Tótem de Ira",kind="Personaje",aliases={"Ruga","Ruga Tótem de Ira"},body="Ruga Tótem de Ira pone a prueba a los guerreros desde el Campamento Taurajo. Su instrucción se dirige a combatientes que ya han demostrado talento y buscan nuevas exigencias para su disciplina.",aliasQuestIDs={},en={title="Ruga Ragetotem",aliases={"Ruga","Ruga Ragetotem"},body="Ruga Ragetotem tests warriors from Camp Taurajo. His instruction is aimed at fighters who have already shown talent and seek new demands in their discipline.",aliasQuestIDs={}},fr={title="Ruga Ragetotem",body="Ruga Ragetotem teste les guerriers de Camp Taurajo. Ses instructions s’adressent aux combattants qui ont déjà fait preuve de talent et qui recherchent de nouvelles exigences dans leur discipline."},de={title="Ruga Ragetotem",body="Ruga Ragetotem testet Krieger von Camp Taurajo. Sein Unterricht richtet sich an Kämpfer, die bereits Talent gezeigt haben und neue Anforderungen in ihrer Disziplin suchen."},pt={title="Ruga Ragetotem",body="Ruga Ragetotem testa guerreiros de Camp Taurajo. Sua instrução é destinada a lutadores que já mostraram talento e buscam novas demandas em sua disciplina."},pl={title="Ruga Ragetotem",body="Ruga Ragetotem poddaje wojowników próbom w Camp Taurajo. Jego nauczanie jest skierowane do osób, które już wykazały talent i szukają nowych wymagań w swojej dyscyplinie."},ru={title="Ruga Ragetotem",body="Ruga Ragetotem тестирует воинов из Camp Taurajo. Его обучение направлено на бойцов, которые уже проявили талант и ищут новых требований в своей дисциплине."},references={["place:camp-taurajo"]=true}},
    ["person:rutgar-glyphshaper"] = {title="Rutgar Glifoforma",kind="Personaje",aliases={"Rutgar","Rutgar Glifoforma"},body="Rutgar Glifoforma investiga los glifos y cristales de Silithus. Su trabajo intenta descifrar los mensajes que circulan entre las fuerzas qiraji y las criaturas de las colmenas.",aliasQuestIDs={},en={title="Rutgar Glyphshaper",aliases={"Rutgar","Rutgar Glyphshaper"},body="Rutgar Glyphshaper investigates Silithus’s glyphs and crystals. His work seeks to decipher messages passing between qiraji forces and the creatures of the hives.",aliasQuestIDs={}},fr={title="Rutgar Glyphshaper",body="Rutgar Glyphshaper étudie les glyphes et les cristaux de Silithus. Son travail cherche à déchiffrer les messages passant entre les forces qiraji et les créatures des ruches."},de={title="Rutgar Glyphshaper",body="Rutgar Glyphshaper untersucht die Glyphen und Kristalle von Silithus. Seine Arbeit versucht, Botschaften zu entschlüsseln, die zwischen den Qiraji-Kräften und den Geschöpfen der Bienenstöcke übergehen."},pt={title="Rutgar Glyphshaper",body="Rutgar Glyphshaper investiga os glifos e cristais de Silithus. Seu trabalho procura decifrar mensagens que passam entre as forças qiraji e as criaturas das colmeias."},pl={title="Rutgar Glyphshaper",body="Rutgar Glyphshaper bada glify i kryształy Silithus. Próbuje rozszyfrować wiadomości przekazywane między siłami qiraji a stworzeniami rojów."},ru={title="Rutgar Glyphshaper",body="Rutgar Glyphshaper исследует Silithus s глифы и кристаллы. Его работа направлена на расшифровку сообщений, передаваемых между силами qiraji и существами ульев."},references={["people:qiraji"]=true,["place:silithus"]=true}},
    ["person:ruul-eagletalon"] = {title="Ruul Garraguilar",kind="Personaje",aliases={"Ruul","Ruul Garraguilar"},body="Ruul es un guerrero y maestro de Mulgore. Prepara a los jóvenes para las pruebas que preceden a sus viajes más allá de las llanuras, valorando que demuestren su fuerza ante los enemigos naturales de su pueblo.",aliasQuestIDs={},en={title="Ruul Eagletalon",aliases={"Ruul","Ruul Eagletalon"},body="Ruul is a warrior and teacher in Mulgore. He prepares the young for trials preceding their journeys beyond the plains, valuing demonstrations of strength against their people’s natural enemies.",aliasQuestIDs={}},fr={title="Ruul Eagletalon",body="Ruul est un guerrier et un enseignant dans Mulgore. Il prépare les jeunes aux épreuves précédant leurs voyages au-delà des plaines, valorisant les démonstrations de force contre les ennemis naturels de leur peuple."},de={title="Ruul Eagletalon",body="Ruul ist ein Krieger und Lehrer in Mulgore. Er bereitet die Jugendlichen auf Prüfungen vor, die ihren Reisen über die Ebene hinaus vorausgehen, und schätzt Machtdemonstrationen gegen die natürlichen Feinde ihres Volkes."},pt={title="Ruul Eagletalon",body="Ruul é um guerreiro e professor em Mulgore. Ele prepara os jovens para julgamentos que precedem suas jornadas além das planícies, valorizando demonstrações de força contra os inimigos naturais de seu povo."},pl={title="Ruul Eagletalon",body="Ruul jest wojownikiem i nauczycielem w Mulgore. Przygotowuje młodych do prób poprzedzających wyprawy poza równiny, ceniąc dowody siły okazywane w starciach z naturalnymi wrogami ich ludu."},ru={title="Ruul Eagletalon",body="Ruul - воин и учитель в Mulgore. Он готовит молодых к испытаниям, предшествующим их путешествиям за равнины, ценит демонстрации силы против естественных врагов своего народа."},references={["place:mulgore"]=true},questIDs={[743]=true}},
    ["person:ruul-snowhoof"] = {title="Ruul Pezuña Nevada",kind="Personaje",aliases={"Ruul","Ruul Pezuña Nevada"},body="Ruul Pezuña Nevada es el hermano de Yama, del Puesto del Hachazo. Sus viajes lo llevan a territorios de los Piel de Cardo, donde los fúrbolgs corrompidos confunden su figura con la de un oso.",aliasQuestIDs={},en={title="Ruul Snowhoof",aliases={"Ruul","Ruul Snowhoof"},body="Ruul Snowhoof is Yama’s brother from Splintertree Post. His travels take him into Thistlefur territory, where corrupted furbolgs mistake his shape for that of a bear.",aliasQuestIDs={}},fr={title="Ruul Snowhoof",body="Ruul Snowhoof est le frère de Yama depuis Splintertree Post. Ses voyages l'emmènent en territoire Thistlefur, où les furbolgs corrompus confondent sa forme avec celle d'un ours."},de={title="Ruul Snowhoof",body="Ruul Snowhoof ist der Bruder von Yama aus Splintertree Post. Seine Reisen führen ihn in das Gebiet der Thistlefur, wo verderbte Furbolgs seine Gestalt mit der eines Bären verwechseln."},pt={title="Ruul Snowhoof",body="Ruul Snowhoof é irmão de Yama da Splintertree Post. Suas viagens o levam ao território Thistlefur, onde furbolgs corrompidos confundem sua forma com a de um urso."},pl={title="Ruul Snowhoof",body="Ruul Snowhoof jest bratem postaci imieniem Yama ze Splintertree Post. Jego podróże prowadzą na tereny Thistlefur, gdzie skażone furbolgi mylnie biorą jego postać za niedźwiedzia."},ru={title="Ruul Snowhoof",body="Ruul Snowhoof - это брат Yama  от Splintertree Post. Его путешествия ведут его на территорию Thistlefur, где коррумпированные фуроболы принимают его форму за медведя."},references={["organization:thistlefur"]=true,["person:yama-snowhoof"]=true,["place:splintertree-post"]=true},questIDs={[6482]=true}},
    ["person:ruuzel"] = {title="Ruuzel",kind="Personaje",aliases={"Ruuzel"},body="Ruuzel dirige a los nagas de la zona norte de Zoram. Posee el antiguo anillo de los gobernantes de la ciudad hundida, un objeto que permite acceder a secretos conservados desde antes del Cataclismo.",aliasQuestIDs={},en={title="Ruuzel",aliases={"Ruuzel"},body="Ruuzel leads the naga in northern Zoram. Ruuzel possesses the ancient ring of the drowned city’s rulers, an object that opens secrets preserved since before the Sundering.",aliasQuestIDs={}},fr={title="Ruuzel",body="Ruuzel mène le naga dans le nord de Zoram. Ruuzel possède l'ancien anneau des dirigeants de la ville noyée, un objet qui ouvre des secrets préservés depuis avant le Sundering."},de={title="Ruuzel",body="Ruuzel führt die Naga im nördlichen Zoram an. Ruuzel besitzt den uralten Ring der ertrunkenen Stadtherrscher, ein Objekt, das Geheimnisse öffnet, die schon vor dem Sundering aufbewahrt wurden."},pt={title="Ruuzel",body="Ruuzel lidera a naga no norte de Zoram. Ruuzel possui o anel antigo dos governantes da cidade afogada, um objeto que abre segredos preservados desde antes do Sundering."},pl={title="Ruuzel",body="Ruuzel przewodzi nagom północnego Zoram. Ruuzel posiada pradawny pierścień władców zatopionego miasta, przedmiot otwierający tajemnice zachowane jeszcze sprzed Sundering."},ru={title="Ruuzel",body="Ruuzel возглавляет наг на севере Zoram. Ruuzel обладает древним кольцом правителей утонувшего города, объектом, который открывает секреты, сохранившиеся до Sundering."},references={}},
    ["person:rwag"] = {title="Rwag",kind="Personaje",aliases={"Rwag"},body="Rwag es un instructor de pícaros del Valle de los Retos. Enseña a los recién llegados una disciplina en la que la discreción y la habilidad pueden ser tan útiles como la fuerza.",aliasQuestIDs={},en={title="Rwag",aliases={"Rwag"},body="Rwag is a rogue trainer in the Valley of Trials. He teaches newcomers a discipline in which discretion and skill can be as useful as strength.",aliasQuestIDs={}},fr={title="Rwag",body="Rwag est un formateur de voleurs dans le Valley of Trials. Il enseigne aux nouveaux arrivants une discipline dans laquelle la discrétion et la compétence peuvent être aussi utiles que la force."},de={title="Rwag",body="Rwag ist ein Schurkentrainer im Valley of Trials. Er lehrt Neulinge eine Disziplin, in der Diskretion und Geschicklichkeit ebenso nützlich sein können wie Stärke."},pt={title="Rwag",body="Rwag é um instrutor de ladinos no Valley of Trials. Ele ensina aos recém-chegados uma disciplina na qual a discrição e a habilidade podem ser tão úteis quanto a força."},pl={title="Rwag",body="Rwag jest nauczycielem łotrzyków w Valley of Trials. Uczy przybyszów dyscypliny, w której dyskrecja i zręczność mogą być równie użyteczne jak siła."},ru={title="Rwag",body="Rwag - это тренер-изгои в Valley of Trials. Он учит новичков дисциплине, в которой благоразумие и умение могут быть такими же полезными, как сила."},references={["place:valley-of-trials"]=true}},
    ["person:ryntariel-the-keymaster"] = {title="Rynthariel la Maestra de llaves",kind="Personaje",aliases={"Rynthariel","Rynthariel la Maestra de llaves"},body="Rynthariel la Maestra de llaves es una dríade encargada de El Cubil del Espolón. Su control del lugar forma parte de la presencia de los defensores de la naturaleza en las alturas de Sierra Espolón.",aliasQuestIDs={},en={title="Rynthariel the Keymaster",aliases={"Rynthariel","Rynthariel the Keymaster"},body="Rynthariel the Keymaster is a dryad in charge of the Stonetalon Den. Her control of the site is part of the defenders of nature’s presence in the heights of the Stonetalon Mountains.",aliasQuestIDs={}},fr={title="Rynthariel the Keymaster",body="Rynthariel the Keymaster est une dryade en charge du Stonetalon Den. Son contrôle du site fait partie des défenseurs de la présence de la nature dans les hauteurs de la Stonetalon Mountains."},de={title="Rynthariel the Keymaster",body="Rynthariel the Keymaster ist eine Trockenhaube, die für die Stonetalon Den zuständig ist. Ihre Kontrolle über das Gebiet gehört zu den Verteidigern der Präsenz der Natur in den Höhen der Stonetalon Mountains."},pt={title="Rynthariel the Keymaster",body="Rynthariel the Keymaster é um dryad responsável pelo Stonetalon Den. Seu controle do site faz parte dos defensores da presença da natureza nas alturas do Stonetalon Mountains."},pl={title="Rynthariel the Keymaster",body="Rynthariel the Keymaster jest driadą zarządzającą legowiskiem Stonetalon. Kontrola nad nim stanowi część obecności obrońców przyrody na wyżynach Stonetalon Mountains."},ru={title="Rynthariel the Keymaster",body="Rynthariel the Keymaster - это драйд, отвечающий за зону Stonetalon. Ее контроль над местом является частью защиты природы присутствия на высотах Stonetalon Mountains."},references={["place:stonetalon-mountains"]=true}},
    ["person:sagorne-creststrider"] = {title="Sagorne Montacresta",kind="Personaje",aliases={"Sagorne","Sagorne Montacresta","Sagorne Zanca Cresta"},body="Sagorne Montacresta es un chamán del Valle de la Sabiduría de Orgrimmar. Conserva tradiciones espirituales y conocimientos sobre objetos capaces de enfrentarse a poderes de las sombras.",aliasQuestIDs={},en={title="Sagorne Creststrider",aliases={"Sagorne","Sagorne Creststrider"},body="Sagorne Creststrider is a shaman in Orgrimmar’s Valley of Wisdom. He preserves spiritual traditions and knowledge of objects capable of confronting powers of shadow.",aliasQuestIDs={}},fr={title="Sagorne Creststrider",body="Sagorne Creststrider est un chaman dans Orgrimmar’s Valley of Wisdom. Il préserve les traditions spirituelles et la connaissance des objets capables de faire face aux pouvoirs de l’ombre."},de={title="Sagorne Creststrider",body="Sagorne Creststrider ist ein Schamane in Orgrimmar’s Valley der Weisheit. Er bewahrt spirituelle Traditionen und Wissen über Objekte, die imstande sind, Mächten des Schattens entgegenzutreten."},pt={title="Sagorne Creststrider",body="Sagorne Creststrider é um xamã em Orgrimmar’s Valley de Sabedoria. Ele preserva tradições espirituais e conhecimento de objetos capazes de confrontar poderes de sombra."},pl={title="Sagorne Creststrider",body="Sagorne Creststrider jest szamanem w miejscu zwanym Orgrimmar’s Valley of Wisdom. Przechowuje tradycje duchowe i wiedzę o przedmiotach zdolnych przeciwstawić się mocom cienia."},ru={title="Sagorne Creststrider",body="Sagorne Creststrider - шаман в Orgrimmar’s Valley Мудрости. Он сохраняет духовные традиции и знания об объектах, способных противостоять силам теней."},references={["place:orgrimmar"]=true}},
    ["person:salfa"] = {title="Salfa",kind="Personaje",aliases={"Salfa"},body="Salfa es un guardián Fauces de Madera que vigila el acceso a su bastión desde Cuna del Invierno. Busca ayuda frente a los fúrbolgs corruptos sin olvidar la seguridad de su propio pueblo.",aliasQuestIDs={},en={title="Salfa",aliases={"Salfa"},body="Salfa is a Timbermaw guardian watching the entrance to the hold from Winterspring. He seeks help against corrupted furbolgs while remaining mindful of his own people’s safety.",aliasQuestIDs={}},fr={title="Salfa",body="Salfa est un gardien Timbermaw qui surveille l'entrée de la cale depuis Winterspring. Il cherche de l'aide contre les furbolgs corrompus tout en restant conscient de la sécurité de son propre peuple."},de={title="Salfa",body="Salfa ist ein Timbermaw-Wächter, der den Eingang zum Laderaum von Winterspring beobachtet. Er sucht Hilfe gegen korrupte Furbolgs und achtet gleichzeitig auf die Sicherheit seines eigenen Volkes."},pt={title="Salfa",body="Salfa é um Timbermaw guardião assistindo a entrada para o porão de Winterspring. Ele procura ajuda contra furbolgs corrompidos, mantendo-se consciente da segurança de seu próprio povo."},pl={title="Salfa",body="Salfa jest strażnikiem Timbermaw obserwującym wejście do schronienia od strony Winterspring. Szuka pomocy przeciw skażonym furbolgom, pamiętając zarazem o bezpieczeństwie własnego ludu."},ru={title="Salfa",body="Salfa - это хранитель Timbermaw, который наблюдает за входом в трюм с Winterspring. Он ищет помощи против коррумпированных фуробогов, но не забывает о безопасности своих людей."},references={["organization:timbermaw"]=true,["place:winterspring"]=true}},
    ["person:sanath-limyo"] = {title="Sanath Lim-yo",kind="Personaje",aliases={"Sanath","Sanath Lim-yo"},body="Sanath Lim-yo es un sirviente del archimago Xylem en Azshara. Controla el acceso a la torre de su maestro mediante un hechizo de teletransporte desde la base de los precipicios.",aliasQuestIDs={},en={title="Sanath Lim-yo",aliases={"Sanath","Sanath Lim-yo"},body="Sanath Lim-yo is a servant of Archmage Xylem in Azshara. He controls access to his master’s tower through a teleportation spell from the base of the cliffs.",aliasQuestIDs={}},fr={title="Sanath Lim-yo",body="Sanath Lim-yo est un serviteur de Archmage Xylem dans Azshara. Il contrôle l'accès à la tour de son maître grâce à un sort de téléportation depuis la base des falaises."},de={title="Sanath Lim-yo",body="Sanath Lim-yo ist ein Diener von Archmage Xylem in Azshara. Er kontrolliert den Zugang zum Turm seines Herrn durch einen Teleportationszauber von der Klippe aus."},pt={title="Sanath Lim-yo",body="Sanath Lim-yo é um servo de Archmage Xylem em Azshara. Ele controla o acesso à torre de seu mestre através de um feitiço de teletransporte da base das falésias."},pl={title="Sanath Lim-yo",body="Sanath Lim-yo jest sługą postaci Archmage Xylem w regionie Azshara. Kontroluje dostęp do wieży mistrza za pomocą zaklęcia teleportacji u podstawy klifów."},ru={title="Sanath Lim-yo",body="Sanath Lim-yo - слуга Archmage Xylem в Azshara. Он контролирует доступ к башне своего хозяина с помощью телепортационного заклинания из основания скал."},references={["person:archmage-xylem"]=true,["place:azshara"]=true}},
    ["person:sania-silverstream"] = {title="Sania Brisargenta",kind="Personaje",aliases={"Sania","Sania Brisargenta"},body="Sania Brisargenta se encuentra en la Aldea Shen'dar y anima a otros shen'dorei a servir a Al'Akir. Interpreta los problemas de su pueblo como consecuencia de la arrogancia y el alejamiento de los espíritus del viento. Identifica a los aspirantes con la Marca de Akir y los dirige hacia el Poblado Falaath.",aliasQuestIDs={},en={title="Sania Silverstream",aliases={"Sania","Sania Silverstream"},body="Sania Silverstream can be found in Shen'dar Village, where she encourages other shen'dorei to serve Al'Akir. She interprets her people's troubles as the result of pride and estrangement from the wind spirits. She identifies prospective followers with the Mark of Akir and directs them to Falaath Village.",aliasQuestIDs={}},fr={title="Sania Silverstream",body="Sania Silverstream peut être trouvé dans Shen'dar Village, où elle encourage les autres shen'dorei à servir Al'Akir. Elle interprète les problèmes de son peuple comme le résultat de l'orgueil et de l'éloignement des esprits du vent. Elle identifie les suiveurs potentiels avec la Marque de Akir et les dirige vers Falaath Village."},de={title="Sania Silverstream",body="Sania Silverstream kann in Shen'dar Village gefunden werden, wo sie andere shen 'dorei ermutigt, Al'Akir zu dienen. Sie interpretiert die Probleme ihres Volkes als das Ergebnis von Stolz und Entfremdung von den Windgeistern. Sie identifiziert potenzielle Anhänger mit dem Zeichen Akirs und leitet sie zu Falaath Village."},pt={title="Sania Silverstream",body="Sania Silverstream pode ser encontrada em Shen'dar Village, onde ela incentiva outros shen'dorei a servir Al'Akir. Ela interpreta os problemas de seu povo como resultado do orgulho e distanciamento dos espíritos do vento. Ela identifica possíveis seguidores com a Marca de Akir e os direciona para Falaath Village."},pl={title="Sania Silverstream",body="Sania Silverstream przebywa w Shen'dar Village, gdzie zachęca innych shen'dorei do służby Al'Akir. Uważa problemy ludu za skutek pychy i oddalenia od duchów wiatru. Oznacza przyszłych wyznawców Mark of Akir i kieruje ich do Falaath Village."},ru={title="Sania Silverstream",body="Sania Silverstream можно найти в Shen'dar Village, где она поощряет других шен'дорей служить Al'Akir. Она интерпретирует проблемы своего народа как результат гордости и отчуждения от духов ветра. Она идентифицирует потенциальных последователей с знаком Akir и направляет их к Falaath Village."},references={["npc:alakir"]=true,["place:falaath-village"]=true,["place:shendar"]=true}},
    ["person:sarilus-foulborne"] = {title="Sarilus Fuenteviciosa",kind="Personaje",aliases={"Sarilus","Sarilus Fuenteviciosa"},body="Sarilus Fuenteviciosa es un mago no-muerto asociado con Cima Calígine, en Los Baldíos. Las centinelas lo consideran capaz de corromper elementales de agua y lo acusan de utilizar ese poder para hostigarlas.",aliasQuestIDs={},en={title="Sarilus Foulborne",aliases={"Sarilus","Sarilus Foulborne"},body="Sarilus Foulborne is an undead mage associated with Dreadmist Peak in the Barrens. The Sentinels believe him capable of corrupting water elementals and accuse him of using that power to harass them.",aliasQuestIDs={}},fr={title="Sarilus Foulborne",body="Sarilus Foulborne est un mage mort-vivant associé à Dreadmist Peak dans le Barrens. Les Sentinels le croient capable de corrompre les élémentaux de l'eau et l'accusent d'utiliser ce pouvoir pour les harceler."},de={title="Sarilus Foulborne",body="Sarilus Foulborne ist ein untoter Magier, der mit Dreadmist Peak im Barrens in Verbindung gebracht wird. Die Sentinels glauben, dass er in der Lage ist, Wasserelemente zu korrumpieren und beschuldigen, und werfen ihm vor, diese Macht zu benutzen, um sie zu belästigen."},pt={title="Sarilus Foulborne",body="Sarilus Foulborne é um mago morto-vivo associado ao Dreadmist Peak no Barrens. O Sentinels acredita que ele é capaz de corromper os elementais da água e o acusa de usar esse poder para assediá-los."},pl={title="Sarilus Foulborne",body="Sarilus Foulborne jest nieumarłym magiem związanym z Dreadmist Peak w regionie Barrens. Sentinels uważają, że potrafi skażać żywiołaki wody, i oskarżają go o używanie tej mocy do nękania ich."},ru={title="Sarilus Foulborne",body="Sarilus Foulborne - это неживой магический маг, связанный с Dreadmist Peak в Barrens. Sentinels считают, что он способен испортить водные элементалы и обвиняют его в использовании этой силы для их преследования."},references={["organization:night-elf-sentinels"]=true,["place:dreadmist-peak"]=true,["place:the-barrens"]=true}},
    ["person:sarkoth"] = {title="Sarkoth",kind="Personaje",aliases={"Sarkoth"},body="Sarkoth es un escórpido especialmente feroz del Valle de los Retos. Sus pinzas y su aguijón representan un peligro serio incluso para los cazadores que se lanzan contra él con confianza.",aliasQuestIDs={},en={title="Sarkoth",aliases={"Sarkoth"},body="Sarkoth is an especially fierce scorpid of the Valley of Trials. His claws and stinger pose a serious danger even to hunters who charge at him with confidence.",aliasQuestIDs={}},fr={title="Sarkoth",body="Sarkoth est un scorpion particulièrement féroce du Valley of Trials. Ses griffes et son aiguillon représentent un grave danger, même pour les chasseurs qui le chargent avec confiance."},de={title="Sarkoth",body="Sarkoth ist ein besonders grimmiger Skorpide des Valley of Trials. Seine Krallen und sein Stachel stellen sogar für Jäger, die ihn mit Zuversicht angreifen, eine ernsthafte Gefahr dar."},pt={title="Sarkoth",body="Sarkoth é um escrúpulo especialmente feroz do Valley of Trials. Suas garras e ferrão representam um perigo sério até mesmo para os caçadores que cobram dele com confiança."},pl={title="Sarkoth",body="Sarkoth jest szczególnie zaciekłym skorpionem Valley of Trials. Szczypce i żądło stanowią poważne zagrożenie nawet dla myśliwych pewnie ruszających do ataku."},ru={title="Sarkoth",body="Sarkoth - особенно свирепый скорпид Valley of Trials. Его когти и жало представляют серьезную опасность даже для охотников, которые с уверенностью нападают на него."},references={["place:valley-of-trials"]=true}},
    ["person:scout-azenel"] = {title="Exploradora Azenel",kind="Personaje",aliases={"Azenel","Exploradora Azenel"},body="La exploradora Azenel vigila los movimientos de los silítidos de Colmen'Zora. Sus observaciones aportan información para que las fuerzas desplegadas en Silithus puedan responder con conocimiento del enemigo.",aliasQuestIDs={},en={title="Cenarion Scout Azenel",aliases={"Azenel","Cenarion Scout Azenel"},body="Scout Azenel watches silithid movements at Hive'Zora. Her observations provide intelligence that helps the forces deployed in Silithus respond with a clearer understanding of the enemy.",aliasQuestIDs={}},fr={title="Cenarion Scout Azenel",body="Scout Azenel montres mouvements silithid à Hive'Zora. Ses observations fournissent des renseignements qui aident les forces déployées dans Silithus à répondre avec une meilleure compréhension de l'ennemi."},de={title="Cenarion Scout Azenel",body="Scout Azenel beobachtet die Bewegungen der Silithiden bei Hive'Zora. Ihre Beobachtungen liefern Informationen, die den in Silithus eingesetzten Kräften helfen, den Feind besser zu verstehen und entsprechend zu reagieren."},pt={title="Cenarion Scout Azenel",body="Scout Azenel observa movimentos silitídeos em Hive'Zora. Suas observações fornecem inteligência que ajuda as forças implantadas no Silithus a responder com uma compreensão mais clara do inimigo."},pl={title="Cenarion Scout Azenel",body="Azenel obserwuje ruchy silithidów przy Hive'Zora. Jej obserwacje dostarczają informacji pomagających siłom rozlokowanym w Silithus reagować z lepszym zrozumieniem przeciwnika."},ru={title="Cenarion Scout Azenel",body="Скаут Azenel следит за движением силицидов на Hive'Zora. Ее наблюдения обеспечивают информацию, которая помогает силам, развернутым в Silithus, реагировать с более четким пониманием врага."},references={["place:hivezora"]=true,["place:silithus"]=true}},
    ["person:scout-jalia"] = {title="Explorador Cenarion Jalia",kind="Personaje",aliases={"Explorador Cenarion Jalia","Jalia"},body="La exploradora Jalia vigila los movimientos de los silítidos de Colmen'Ashi. Sus informes ayudan a comprender lo que sucede dentro de las colmenas antes de que los aliados del Fuerte Cenarion decidan cómo responder.",aliasQuestIDs={},en={title="Cenarion Scout Jalia",aliases={"Cenarion Scout Jalia","Jalia"},body="Scout Jalia watches silithid movements at Hive'Ashi. Her reports help reveal events within the hives before Cenarion Hold’s allies decide how to respond.",aliasQuestIDs={}},fr={title="Cenarion Scout Jalia",body="Scout Jalia montres mouvements silithid à Hive'Ashi. Ses rapports aident à révéler les événements dans les ruches avant que les alliés de Cenarion Hold ne décident comment réagir."},de={title="Cenarion Scout Jalia",body="Scout Jalia beobachtet die Bewegungen der Silithiden bei Hive'Ashi. Ihre Berichte helfen, das Geschehen in den Bauten zu erkennen, bevor die Verbündeten von Cenarion Hold über ihre Reaktion entscheiden."},pt={title="Cenarion Scout Jalia",body="Scout Jalia observa movimentos silitídeos em Hive'Ashi. Seus relatórios ajudam a revelar eventos dentro das colmeias antes que os aliados da Cenarion Hold decidam como responder."},pl={title="Cenarion Scout Jalia",body="Jalia obserwuje ruchy silithidów przy Hive'Ashi. Raporty pomagają ujawniać wydarzenia wewnątrz rojów, zanim sojusznicy Cenarion Hold zdecydują o odpowiedzi."},ru={title="Cenarion Scout Jalia",body="Скаут Jalia следит за движением силицидов на Hive'Ashi. Ее отчеты помогают раскрыть события внутри ульев, прежде чем союзники Cenarion Hold  решат, как реагировать."},references={["place:hive-ashi"]=true}},
    ["person:scout-landion"] = {title="Explorador Cenarion Landion",kind="Personaje",aliases={"Explorador Cenarion Landion","Landion"},body="El explorador Landion observa los movimientos de los silítidos en Colmen'Regal. Trabaja en una labor de vigilancia prolongada, cuyo valor está en transformar lo que sucede dentro de las colmenas en información útil para sus aliados.",aliasQuestIDs={},en={title="Cenarion Scout Landion",aliases={"Cenarion Scout Landion","Landion"},body="Scout Landion watches silithid movements at Hive'Regal. His sustained watch turns events within the hives into intelligence his allies can use.",aliasQuestIDs={}},fr={title="Cenarion Scout Landion",body="Scout Landion montres mouvements silithid à Hive'Regal. Sa veille soutenue transforme les événements dans les ruches en renseignements que ses alliés peuvent utiliser."},de={title="Cenarion Scout Landion",body="Scout Landion beobachtet die Bewegungen der Silithiden bei Hive'Regal. Seine anhaltende Beobachtung liefert seinen Verbündeten nützliche Nachrichten über das Geschehen in den Bauten."},pt={title="Cenarion Scout Landion",body="Scout Landion observa movimentos silitídeos em Hive'Regal. Seu relógio contínuo transforma eventos dentro das colmeias em inteligência que seus aliados podem usar."},pl={title="Cenarion Scout Landion",body="Landion obserwuje ruchy silithidów przy Hive'Regal. Długotrwała warta zamienia wydarzenia wewnątrz rojów w informacje użyteczne dla sojuszników."},ru={title="Cenarion Scout Landion",body="Скаут Landion следит за движением силицидов на Hive'Regal. Его постоянные часы превращают события внутри ульев в информацию, которую могут использовать его союзники."},references={["place:hiveregal"]=true}},
    ["person:scryer"] = {title="Arúspice",kind="Personaje",aliases={"Arúspice"},body="Arúspice es un poderoso dragón azul de Cuna del Invierno. Su condición de campeón de su vuelo lo convierte en un objetivo de los dragones negros que buscan afirmar la supremacía de Alamuerte.",aliasQuestIDs={},en={title="Scryer",aliases={"Scryer"},body="Scryer is a powerful blue drake in Winterspring. His standing as a champion of his flight makes him a target for black dragons seeking to enforce Deathwing’s supremacy.",aliasQuestIDs={}},fr={title="Scryer",body="Scryer est un puissant drake bleu dans Winterspring. Sa position en tant que champion de son vol fait de lui une cible pour les dragons noirs qui cherchent à faire respecter la suprématie de Deathwing."},de={title="Scryer",body="Scryer ist ein kräftiger blauer Erpel in Winterspring. Sein Ruf als Verfechter seiner Flucht macht ihn zum Ziel schwarzer Drachen, die versuchen, Deathwing 'Vorherrschaft durchzusetzen."},pt={title="Scryer",body="Scryer é um poderoso drake azul em Winterspring. Sua posição como campeão de seu voo faz dele um alvo para dragões negros que buscam impor a supremacia do Deathwing."},pl={title="Scryer",body="Scryer jest potężnym błękitnym smokiem w Winterspring. Pozycja czempiona rodu czyni go celem czarnych smoków próbujących narzucić zwierzchnictwo istoty Deathwing."},ru={title="Scryer",body="Scryer - это мощный синий дракон в Winterspring. Его положение как чемпиона своего полета делает его мишенью для черных драконов, стремящихся обеспечить превосходство Deathwing."},references={["npc:deathwing"]=true,["place:winterspring"]=true},questIDs={[6582]=true}},
    ["person:security-chief-bilgewhizzle"] = {title="Jefe de seguridad Pasaquillas",kind="Personaje",aliases={"Jefe de seguridad Pasaquillas","Pasaquillas","jefe de seguridad Pasaquillas"},body="El jefe de seguridad Pasaquillas mantiene el orden en el Puerto Bonvapor. Los conflictos con los piratas de los Mares del Sur lo obligan a buscar ayuda fuera del puerto, incluso cuando el Cártel Bonvapor ya paga para evitar problemas con ellos.",aliasQuestIDs={},en={title="Security Chief Bilgewhizzle",aliases={"Bilgewhizzle","Security Chief Bilgewhizzle"},body="Security Chief Bilgewhizzle maintains order in Steamwheedle Port. Conflicts with the Southsea pirates force him to seek help beyond the port, even when the Steamwheedle Cartel already pays to avoid trouble with them.",aliasQuestIDs={}},fr={title="Security Chief Bilgewhizzle",body="Security Chief Bilgewhizzle maintient l'ordre dans Steamwheedle Port. Les conflits avec les pirates Southsea le forcent à chercher de l'aide au-delà du port, même lorsque le Cartel Steamwheedle paie déjà pour éviter les problèmes avec eux."},de={title="Security Chief Bilgewhizzle",body="Security Chief Bilgewhizzle sorgt in Steamwheedle Port für Ordnung. Konflikte mit den Southsea-Piraten zwingen ihn, Hilfe außerhalb des Hafens zu suchen, auch wenn das Steamwheedle-Kartell bereits zahlt, um Ärger mit ihnen zu vermeiden."},pt={title="Security Chief Bilgewhizzle",body="Security Chief Bilgewhizzle mantém ordem em Steamwheedle Port. Os conflitos com os piratas Southsea o forçam a procurar ajuda além do porto, mesmo quando o Cartel Steamwheedle já paga para evitar problemas com eles."},pl={title="Security Chief Bilgewhizzle",body="Security Chief Bilgewhizzle utrzymuje porządek w Steamwheedle Port. Konflikty z piratami Southsea zmuszają go do szukania pomocy poza portem, nawet gdy kartel Steamwheedle już płaci za unikanie kłopotów z nimi."},ru={title="Security Chief Bilgewhizzle",body="Security Chief Bilgewhizzle поддерживает порядок в Steamwheedle Port. Конфликты с пиратами Southsea заставляют его искать помощи за пределами порта, даже когда картель Steamwheedle уже платит, чтобы избежать проблем с ними."},references={["place:south-seas"]=true,["place:steamwheedle-port"]=true},questIDs={[2875]=true,[8366]=true}},
    ["person:seer-ravenfeather"] = {title="Vidente Pluma de Cuervo",kind="Personaje",aliases={"Vidente Pluma de Cuervo","vidente Pluma de Cuervo"},body="La vidente Pluma de Cuervo guía a los chamanes del Campamento Narache. Sus enseñanzas de paciencia, fortaleza y respeto por la tierra reconocen que incluso una piedra pequeña puede ser el corazón de un tótem.",aliasQuestIDs={},en={title="Seer Ravenfeather",aliases={"Seer Ravenfeather"},body="Seer Ravenfeather guides shamans at Camp Narache. Her lessons in patience, strength and respect for the earth recognize that even a small stone can be a totem’s heart.",aliasQuestIDs={}},fr={title="Seer Ravenfeather",body="Seer Ravenfeather guide les chamans chez Camp Narache. Ses leçons de patience, de force et de respect de la terre reconnaissent que même une petite pierre peut être le cœur d’un totem."},de={title="Seer Ravenfeather",body="Seer Ravenfeather führt Schamanen zu Camp Narache. Ihre Lektionen in Geduld, Stärke und Respekt für die Erde erkennen, dass selbst ein kleiner Stein das Herz eines Totems sein kann."},pt={title="Seer Ravenfeather",body="Seer Ravenfeather guia xamãs em Camp Narache. Suas lições de paciência, força e respeito pela terra reconhecem que mesmo uma pequena pedra pode ser o coração de um totem."},pl={title="Seer Ravenfeather",body="Seer Ravenfeather prowadzi szamanów w Camp Narache. Lekcje cierpliwości, siły i szacunku dla ziemi uznają, że nawet mały kamień może być sercem totemu."},ru={title="Seer Ravenfeather",body="Seer Ravenfeather руководит шаманами в Camp Narache. Ее уроки терпения, силы и уважения к земле признают, что даже маленький камень может быть сердцем тотема."},references={["place:camp-narache"]=true}},
    ["person:seereth-stonebreak"] = {title="Seereth Petrajada",kind="Personaje",aliases={"Seereth","Seereth Petrajada"},body="Seereth Petrajada es una chamana de la Horda enviada a Sierra Espolón. Atiende la inquietud de los espíritus de la tierra y busca ayuda frente a la rápida destrucción causada por las operaciones goblin.",aliasQuestIDs={},en={title="Seereth Stonebreak",aliases={"Seereth","Seereth Stonebreak"},body="Seereth Stonebreak is a Horde shaman sent to the Stonetalon Mountains. She responds to the land spirits’ unrest and seeks help against the rapid destruction caused by goblin operations.",aliasQuestIDs={}},fr={title="Seereth Stonebreak",body="Seereth Stonebreak est un shaman Horde envoyé au Stonetalon Mountains. Elle répond à l’agitation des esprits de la terre et cherche de l’aide contre la destruction rapide causée par les opérations des gobelins."},de={title="Seereth Stonebreak",body="Seereth Stonebreak ist eine Horde-Schamanin der Stonetalon Mountains. Sie reagiert auf die Unruhen der Landgeister und sucht Hilfe gegen die rasche Zerstörung durch Goblin-Operationen."},pt={title="Seereth Stonebreak",body="Seereth Stonebreak é um xamã Horde enviado para o Stonetalon Mountains. Ela responde à agitação dos espíritos terrestres e procura ajuda contra a rápida destruição causada pelas operações goblins."},pl={title="Seereth Stonebreak",body="Seereth Stonebreak jest szamanką frakcji Horde wysłaną do Stonetalon Mountains. Odpowiada na niepokój duchów ziemi i szuka pomocy przeciw szybkiemu zniszczeniu powodowanemu przez goblińską działalność."},ru={title="Seereth Stonebreak",body="Seereth Stonebreak - это шаман Horde, посланный в Stonetalon Mountains. Она реагирует на беспорядки земных духов и ищет помощи против быстрого разрушения, вызванного операциями гоблинов."},references={["organization:horde"]=true,["place:stonetalon-mountains"]=true}},
    ["person:selendra"] = {title="Selendra",kind="Personaje",aliases={"Selendra"},body="Selendra se preocupa por los poderes que dominan Maraudon y por los restos de Zaetar. Busca aliados capaces de afrontar a Theradras y consulta al vigilante Marandis sobre cómo tratar ese legado.",aliasQuestIDs={},en={title="Selendra",aliases={"Selendra"},body="Selendra is concerned with the powers ruling Maraudon and the remains of Zaetar. She seeks allies capable of confronting Theradras and consults Keeper Marandis about that legacy.",aliasQuestIDs={}},fr={title="Selendra",body="Selendra est concerné par les pouvoirs qui régissent Maraudon et les restes de Zaetar. Elle cherche des alliés capables d'affronter Theradras et consulte Keeper Marandis à propos de cet héritage."},de={title="Selendra",body="Selendra kümmert sich um die Macht, die Maraudon regiert, und um die Überreste von Zaetar. Sie sucht Verbündete, die in der Lage sind, Theradras entgegenzutreten und konsultiert Keeper Marandis zu diesem Vermächtnis."},pt={title="Selendra",body="Selendra está preocupado com os poderes que governam Maraudon e os restos de Zaetar. Ela procura aliados capazes de confrontar Theradras e consulta Keeper Marandis sobre esse legado."},pl={title="Selendra",body="Selendra troszczy się o potęgi władające Maraudon i szczątki istoty Zaetar. Szuka sojuszników zdolnych stawić czoła istocie Theradras i konsultuje to dziedzictwo z postacią Keeper Marandis."},ru={title="Selendra",body="Selendra занимается властью, управляющей Maraudon и остатками Zaetar. Она ищет союзников, способных противостоять Theradras и консультируется с Keeper Marandis о том, что наследие."},references={["person:keeper-marandis"]=true,["place:maraudon"]=true}},
    ["person:senani-thunderheart"] = {title="Senani Corazón Atronador",kind="Personaje",aliases={"Senani","Senani Corazón Atronador"},body="Senani Corazón Atronador supervisa la Caza de Vallefresno desde el Puesto del Hachazo. Reconoce los trofeos de las grandes bestias del bosque como prueba del progreso de quienes participan en esa tradición.",aliasQuestIDs={},en={title="Senani Thunderheart",aliases={"Senani","Senani Thunderheart"},body="Senani Thunderheart oversees the Ashenvale Hunt from Splintertree Post. She recognizes trophies from the forest’s great beasts as evidence of participants’ progress in that tradition.",aliasQuestIDs={}},fr={title="Senani Thunderheart",body="Senani Thunderheart supervise le Ashenvale Hunt de Splintertree Post. Elle reconnaît les trophées des grandes bêtes de la forêt comme preuve du progrès des participants dans cette tradition."},de={title="Senani Thunderheart",body="Senani Thunderheart beaufsichtigt die Ashenvale Hunt von Splintertree Post aus. Sie erkennt Trophäen der großen Tiere aus dem Wald als Beleg für den Fortschritt der Teilnehmer in dieser Tradition."},pt={title="Senani Thunderheart",body="Senani Thunderheart supervisiona o Ashenvale Hunt de Splintertree Post. Ela reconhece troféus dos grandes animais da floresta como evidência do progresso dos participantes nessa tradição."},pl={title="Senani Thunderheart",body="Senani Thunderheart nadzoruje Ashenvale Hunt z Splintertree Post. Uznaje trofea wielkich bestii lasu za dowód postępów uczestników tej tradycji."},ru={title="Senani Thunderheart",body="Senani Thunderheart контролирует Ashenvale Hunt от Splintertree Post. Она признает трофеи от лесных зверей доказательством прогресса участников в этой традиции."},references={["place:ashenvale"]=true,["place:splintertree-post"]=true}},
    ["person:senior-sergeant-tkelah"] = {title="Sargento jefe T'kelah",kind="Personaje",aliases={"Sargento jefe T'kelah","Sargento jefe T’kelah","T'kelah","T’kelah","sargento jefe T'kelah","sargento jefe T’kelah"},body="El sargento jefe T'kelah coordina la obtención de mitril para la Horda. Sus reservas de metal forman parte de una preparación militar que depende de la minería y la fundición, además de los combatientes.",aliasQuestIDs={},en={title="Senior Sergeant T'kelah",aliases={"Senior Sergeant T'kelah","Senior Sergeant T’kelah","T'kelah","T’kelah"},body="Senior Sergeant T'kelah coordinates the Horde’s supply of mithril. His metal reserves are part of military preparations depending on mining and smelting as well as fighters.",aliasQuestIDs={}},fr={title="Senior Sergeant T'kelah",body="Senior Sergeant T'kelah coordonne l’alimentation en mithril du Horde. Ses réserves de métaux font partie des préparatifs militaires en fonction de l'exploitation minière et de la fusion ainsi que des combattants."},de={title="Senior Sergeant T'kelah",body="Senior Sergeant T'kelah koordiniert die Versorgung des Horde mit Mitril. Seine Metallreserven sind Teil militärischer Vorbereitungen, die vom Bergbau und Schmelzen sowie von Kämpfern abhängen."},pt={title="Senior Sergeant T'kelah",body="Senior Sergeant T'kelah coordena o fornecimento de mithril do Horde. Suas reservas de metal são parte de preparações militares, dependendo da mineração e fundição, bem como lutadores."},pl={title="Senior Sergeant T'kelah",body="Senior Sergeant T'kelah koordynuje dostawy mithrilu frakcji Horde. Rezerwy metalu należą do przygotowań wojskowych zależnych zarówno od górnictwa i wytopu, jak i od wojowników."},ru={title="Senior Sergeant T'kelah",body="Senior Sergeant T'kelah координирует поставку митрила Horde s. Его запасы металла являются частью военной подготовки, которая зависит от добычи и плавки, а также бойцов."},references={["organization:horde"]=true}},
    ["person:sentinel-arynia-cloudsbreak"] = {title="Centinela Arynia Quiebranubes",kind="Personaje",aliases={"Arynia","Centinela Arynia Quiebranubes","centinela Arynia Quiebranubes"},body="La centinela Arynia Quiebranubes protege el Árbol del Oráculo de Teldrassil. Sus patrullas intentan expulsar a las arpías que atacan a los mensajeros y ponen en peligro el contacto con Darnassus.",aliasQuestIDs={},en={title="Sentinel Arynia Cloudsbreak",aliases={"Arynia","Sentinel Arynia Cloudsbreak"},body="Sentinel Arynia Cloudsbreak protects Teldrassil’s Oracle Tree. Her patrols try to drive off harpies attacking messengers and endangering contact with Darnassus.",aliasQuestIDs={}},fr={title="Sentinel Arynia Cloudsbreak",body="Sentinel Arynia Cloudsbreak protège Teldrassil de Oracle Tree. Ses patrouilles tentent de chasser les harpies attaquant les messagers et mettant en danger le contact avec Darnassus."},de={title="Sentinel Arynia Cloudsbreak",body="Sentinel Arynia Cloudsbreak beschützt Teldrassils Oracle Tree. Ihre Patrouillen versuchen, Harpies zu vertreiben, die Boten angreifen und den Kontakt zu Darnassus zu gefährden."},pt={title="Sentinel Arynia Cloudsbreak",body="Sentinel Arynia Cloudsbreak protege Teldrassil do Oracle Tree. Suas patrulhas tentam expulsar harpias atacando mensageiros e colocando em perigo o contato com Darnassus."},pl={title="Sentinel Arynia Cloudsbreak",body="Sentinel Arynia Cloudsbreak chroni Oracle Tree w Teldrassil. Jej patrole próbują odpędzać harpie atakujące posłańców i zagrażające kontaktowi z Darnassus."},ru={title="Sentinel Arynia Cloudsbreak",body="Sentinel Arynia Cloudsbreak защищает Teldrassil s Oracle Tree. Ее патрули пытаются отгонять гарпий, атакующих посланников и угрожающих контактам с Darnassus."},references={["place:darnassus"]=true,["place:oracle-tree"]=true,["place:teldrassil"]=true}},
    ["person:sentinel-dalia-sunblade"] = {title="Centinela Dalia Filosol",kind="Personaje",aliases={"Centinela Dalia Filosol","Dalia"},body="La centinela Dalia Filosol cumple labores de vigilancia en Darnassus. Vincula la protección de la ciudad con la devoción a Elune y con los dones de la diosa que acompañan las armas de las cazadoras.",aliasQuestIDs={},en={title="Sentinel Dalia Sunblade",aliases={"Dalia","Sentinel Dalia Sunblade"},body="Sentinel Dalia Sunblade carries out watch duties in Darnassus. She connects protecting the city with devotion to Elune and the goddess’s gifts that accompany a huntress’s weapons.",aliasQuestIDs={}},fr={title="Sentinel Dalia Sunblade",body="Sentinel Dalia Sunblade effectue des tâches de veille dans Darnassus. Elle relie la protection de la ville avec la dévotion à Elune et les dons de la déesse qui accompagnent les armes d'une chasseuse."},de={title="Sentinel Dalia Sunblade",body="Sentinel Dalia Sunblade nimmt Wachdienst in Darnassus wahr. Sie verbindet den Schutz der Stadt mit der Hingabe an Elune und die Gaben der Göttin Verbindung mit den Waffen einer Jägerin."},pt={title="Sentinel Dalia Sunblade",body="Sentinel Dalia Sunblade realiza tarefas de vigilância em Darnassus. Ela conecta proteger a cidade com devoção ao Elune e os presentes da deusa que acompanham as armas de uma caçadora."},pl={title="Sentinel Dalia Sunblade",body="Sentinel Dalia Sunblade pełni wartę w Darnassus. Łączy ochronę miasta z oddaniem bogini Elune i jej darami towarzyszącymi broni łowczyni."},ru={title="Sentinel Dalia Sunblade",body="Sentinel Dalia Sunblade выполняет дежурные обязанности в Darnassus. Она связывает защиту города с преданностью Elune и дарами богини, которые сопровождают оружие охотницы."},references={["npc:elune"]=true,["place:darnassus"]=true},questIDs={[98067]=true}},
    ["person:sentinel-glynda-nalshea"] = {title="Centinela Glynda Nal'Shea",kind="Personaje",aliases={"Centinela Glynda Nal'Shea","Centinela Glynda Nal’Shea","Glynda","centinela Glynda Nal'Shea","centinela Glynda Nal’Shea"},body="La centinela Glynda Nal'Shea vigila las amenazas cercanas a Auberdine. Reúne informes sobre criaturas hostiles y fenómenos extraños antes de decidir cómo proteger a los habitantes del puerto.",aliasQuestIDs={},en={title="Sentinel Glynda Nal'Shea",aliases={"Glynda","Sentinel Glynda Nal'Shea","Sentinel Glynda Nal’Shea"},body="Sentinel Glynda Nal'Shea watches threats near Auberdine. She gathers reports of hostile creatures and strange phenomena before deciding how to protect the port’s residents.",aliasQuestIDs={}},fr={title="Sentinel Glynda Nal'Shea",body="Sentinel Glynda Nal'Shea regarde les menaces près de Auberdine. Elle rassemble des rapports de créatures hostiles et de phénomènes étranges avant de décider comment protéger les résidents du port."},de={title="Sentinel Glynda Nal'Shea",body="Sentinel Glynda Nal'Shea sieht Drohungen in der Nähe von Auberdine. Sie sammelt Berichte über feindliche Kreaturen und seltsame Phänomene, bevor sie entscheidet, wie die Hafenbewohner zu schützen."},pt={title="Sentinel Glynda Nal'Shea",body="Sentinel Glynda Nal'Shea observa ameaças perto de Auberdine. Ela reúne relatos de criaturas hostis e fenômenos estranhos antes de decidir como proteger os moradores do porto."},pl={title="Sentinel Glynda Nal'Shea",body="Sentinel Glynda Nal'Shea obserwuje zagrożenia w pobliżu Auberdine. Zbiera raporty o wrogich stworzeniach i niezwykłych zjawiskach, zanim zdecyduje, jak chronić mieszkańców portu."},ru={title="Sentinel Glynda Nal'Shea",body="Sentinel Glynda Nal'Shea следит за угрозами возле Auberdine. Она собирает сообщения о враждебных существах и странных явлениях, прежде чем решить, как защитить жителей порта."},references={["place:auberdine"]=true}},
    ["person:sentinel-lynessa-duskblossom"] = {title="Centinela Lynesa Flor del Ocaso",kind="Personaje",aliases={"Centinela Lynesa Flor del Ocaso","Lynesa"},body="La centinela Lynesa Flor del Ocaso sirve como mensajera del árbol del oráculo para los druidas de Ban'ethil. Su misión la lleva a los túmulos bajo tierra, un entorno que considera ajeno a la vida de los kaldorei.",aliasQuestIDs={},en={title="Sentinel Lynessa Duskblossom",aliases={"Lynessa","Sentinel Lynessa Duskblossom"},body="Sentinel Lynessa Duskblossom carries messages from the Oracle Tree to the druids of Ban'ethil. Her duties take her into the underground barrows, surroundings she considers ill-suited to kaldorei life.",aliasQuestIDs={}},fr={title="Sentinel Lynessa Duskblossom",body="Sentinel Lynessa Duskblossom transporte les messages du Oracle Tree vers les druides de Ban'ethil. Ses fonctions l'emmènent dans les terriers souterrains, un environnement qu'elle considère mal adapté à la vie kaldorei."},de={title="Sentinel Lynessa Duskblossom",body="Sentinel Lynessa Duskblossom trägt Botschaften von der Oracle Tree zu den Druiden Ban'ethils. Ihre Pflichten führen sie in die unterirdischen Schubkarren, eine Umgebung, die sie für das Kaldorei-Leben als ungeeignet erachtet."},pt={title="Sentinel Lynessa Duskblossom",body="Sentinel Lynessa Duskblossom carrega mensagens do Oracle Tree para os druidas de Ban'ethil. Seus deveres a levam para os esconderijos subterrâneos, arredores que ela considera inadequados para a vida kaldorei."},pl={title="Sentinel Lynessa Duskblossom",body="Sentinel Lynessa Duskblossom przenosi wiadomości od Oracle Tree do druidów Ban'ethil. Obowiązki prowadzą ją do podziemnych kurhanów, otoczenia uznawanego przez nią za nieodpowiednie dla życia kaldorei."},ru={title="Sentinel Lynessa Duskblossom",body="Sentinel Lynessa Duskblossom несет сообщения от Oracle Tree к друидам Ban'ethil. Ее обязанности ведут ее в подземные кладовые, окружение, которое она считает не подходит для жизни Кальдорей."},references={["place:banethil-barrow-den"]=true,["place:duskwood"]=true,["place:oracle-tree"]=true}},
    ["person:sentinel-shaya"] = {title="Centinela Shaya",kind="Personaje",aliases={"Centinela Shaya","Shaya"},body="Shaya patrulla los alrededores de Dolanaar como integrante de las centinelas. Sus heridas recuerdan los riesgos de proteger la comunidad y la importancia del apoyo de los sacerdotes de Elune a sus defensoras.",aliasQuestIDs={},en={title="Sentinel Shaya",aliases={"Sentinel Shaya","Shaya"},body="Shaya patrols around Dolanaar as a member of the Sentinels. Her wounds reflect the dangers of protecting the community and the importance of Elune’s priests in supporting its defenders.",aliasQuestIDs={}},fr={title="Sentinel Shaya",body="Shaya patrouille autour de Dolanaar en tant que membre de la Sentinels. Ses blessures reflètent les dangers de la protection de la communauté et l’importance des prêtres de Elune pour soutenir ses défenseurs."},de={title="Sentinel Shaya",body="Shaya patrouilliert als Mitglied der Sentinels um Dolanaar herum. Ihre Wunden spiegeln die Gefahren des Schutzes der Gemeinschaft und die Bedeutung der Priester Elunes bei der Unterstützung ihrer Verteidiger wider."},pt={title="Sentinel Shaya",body="Shaya patrulha em torno Dolanaar como um membro do Sentinels. Suas feridas refletem os perigos de proteger a comunidade e a importância dos sacerdotes do Elune em apoiar seus defensores."},pl={title="Sentinel Shaya",body="Shaya patroluje okolice Dolanaar jako członkini Sentinels. Rany odzwierciedlają niebezpieczeństwa ochrony społeczności i znaczenie kapłanów bogini Elune dla wspierania obrońców."},ru={title="Sentinel Shaya",body="Shaya патрулирует Dolanaar как член Sentinels. Ее раны отражают опасность защиты общины и важность жрецов Elune в поддержке ее защитников."},references={["npc:elune"]=true,["place:dolanaar"]=true}},
    ["person:sentinel-tysha-moonblade"] = {title="Centinela Tysha Filoluna",kind="Personaje",aliases={"Centinela Tysha Filoluna","Tysha"},body="La centinela Tysha Filoluna explora las ruinas de Ameth’Aran. Le interesa conservar los relatos de sus antiguas tablillas, una fuente escasa de conocimiento sobre los sucesos de la Guerra de los Ancestros.",aliasQuestIDs={},en={title="Sentinel Tysha Moonblade",aliases={"Sentinel Tysha Moonblade","Tysha"},body="Sentinel Tysha Moonblade explores the ruins of Ameth’Aran. She seeks to preserve the stories on its ancient tablets, a scarce source of knowledge about events surrounding the War of the Ancients.",aliasQuestIDs={}},fr={title="Sentinel Tysha Moonblade",body="Sentinel Tysha Moonblade explore les ruines de Ameth’Aran. Elle cherche à préserver les histoires sur ses tablettes anciennes, une source rare de connaissances sur les événements entourant la guerre des anciens."},de={title="Sentinel Tysha Moonblade",body="Sentinel Tysha Moonblade erkundet die Ruinen von Ameth’Aran. Sie ist bestrebt, die Geschichten auf ihren uralten Tafeln zu bewahren, einer spärlichen Wissensquelle über die Ereignisse rund um den Altertumskrieg."},pt={title="Sentinel Tysha Moonblade",body="Sentinel Tysha Moonblade explora as ruínas de Ameth’Aran. Ela procura preservar as histórias em seus tablets antigos, uma fonte escassa de conhecimento sobre eventos que cercam a Guerra dos Antigos."},pl={title="Sentinel Tysha Moonblade",body="Sentinel Tysha Moonblade bada ruiny Ameth’Aran. Próbuje zachować historie z pradawnych tablic, rzadkiego źródła wiedzy o wydarzeniach wokół wojny pradawnych."},ru={title="Sentinel Tysha Moonblade",body="Sentinel Tysha Moonblade исследует руины Ameth’Aran. Она стремится сохранить истории на древних табличках, редкий источник знаний о событиях вокруг войны Древних."},references={["place:ametharan"]=true}},
    ["person:sergeant-umala"] = {title="Sargento Umala",kind="Personaje",aliases={"Sargento Umala","Umala","sargento Umala"},body="El sargento Umala participa en los preparativos de guerra de Orgrimmar reuniendo cuero grueso. Ese material se destina a distintas necesidades del ejército, una tarea de apoyo que complementa las acciones de sus guerreros.",aliasQuestIDs={},en={title="Sergeant Umala",aliases={"Sergeant Umala","Umala"},body="Sergeant Umala takes part in Orgrimmar’s war preparations by gathering thick leather. The material serves different military needs, supporting the actions of its warriors.",aliasQuestIDs={}},fr={title="Sergeant Umala",body="Sergeant Umala participe aux préparatifs de guerre de Orgrimmar en rassemblant du cuir épais. Le matériel sert différents besoins militaires, soutenant les actions de ses guerriers."},de={title="Sergeant Umala",body="Sergeant Umala nimmt an den Kriegsvorbereitungen von Orgrimmar teil, indem er dickes Leder sammelt. Das Material dient unterschiedlichen militärischen Bedürfnissen und unterstützt die Handlungen seiner Krieger."},pt={title="Sergeant Umala",body="Sergeant Umala participa dos preparativos de guerra do Orgrimmar, reunindo couro grosso. O material atende a diferentes necessidades militares, apoiando as ações de seus guerreiros."},pl={title="Sergeant Umala",body="Sergeant Umala uczestniczy w wojennych przygotowaniach Orgrimmar, zbierając grubą skórę. Materiał zaspokaja rozmaite potrzeby wojskowe, wspierając działania wojowników."},ru={title="Sergeant Umala",body="Sergeant Umala принимает участие в подготовке войны Orgrimmar, собирая толстую кожу. Материал служит различным военным нуждам, поддерживая действия своих воинов."},references={["place:orgrimmar"]=true}},
    ["person:sergra-darkthorn"] = {title="Sergra Espinoscura",kind="Personaje",aliases={"Sergra","Sergra Espinoscura"},body="Sergra Espinoscura es una cazadora de El Cruce que orienta a quienes recorren Los Baldíos. Conoce las bestias de la región y presenta la caza como una prueba de habilidad y una forma de ayudar al asentamiento.",aliasQuestIDs={},en={title="Sergra Darkthorn",aliases={"Sergra","Sergra Darkthorn"},body="Sergra Darkthorn is a hunter at the Crossroads who guides those traveling through the Barrens. She knows the region’s beasts and treats hunting as both a test of skill and a way to help the settlement.",aliasQuestIDs={}},fr={title="Sergra Darkthorn",body="Sergra Darkthorn est un chasseur au Crossroads qui guide ceux qui voyagent à travers le Barrens. Elle connaît les bêtes de la région et considère la chasse à la fois comme un test d’habileté et un moyen d’aider la colonie."},de={title="Sergra Darkthorn",body="Sergra Darkthorn ist eine Jägerin bei der Crossroads, die diejenigen anleitet, die durch die Barrens reisen. Sie kennt die Tiere der Region und betrachtet die Jagd sowohl als Geschicklichkeitstest als auch als Möglichkeit, der Siedlung zu helfen."},pt={title="Sergra Darkthorn",body="Sergra Darkthorn é um caçador no Crossroads que guia aqueles que viajam através do Barrens. Ela conhece os animais da região e trata a caça como um teste de habilidade e uma maneira de ajudar o assentamento."},pl={title="Sergra Darkthorn",body="Sergra Darkthorn jest łowczynią w Crossroads, która udziela wskazówek podróżującym przez Barrens. Zna miejscowe bestie i traktuje polowanie zarówno jako sprawdzian umiejętności, jak i sposób pomocy osadzie."},ru={title="Sergra Darkthorn",body="Sergra Darkthorn - охотник в Crossroads, который направляет тех, кто путешествует через Barrens. Она знает зверей региона и относится к охоте как к испытанию на умение, так и как к способу помочь поселению."},references={["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:sethir-the-ancient"] = {title="Sethir el Ancestro",kind="Personaje",aliases={"Sethir","Sethir el Ancestro"},body="Sethir el Ancestro es un sátiro que se oculta en las ramas cercanas a El Claro del Oráculo. Quienes investigan la enfermedad de Teldrassil creen que podría conocer sus causas, pero todos los intentos de aproximarse a él han resultado peligrosos.",aliasQuestIDs={},en={title="Sethir the Ancient",aliases={"Sethir","Sethir the Ancient"},body="Sethir the Ancient is a satyr hiding among the branches near the Oracle Glade. Those investigating Teldrassil’s sickness believe he may know its causes, but every attempt to approach him has proved dangerous.",aliasQuestIDs={}},fr={title="Sethir the Ancient",body="Sethir the Ancient est un satyre se cachant parmi les branches proches de l'Oracle Glade. Ceux qui enquêtent sur la maladie de Teldrassil croient qu'il peut connaître ses causes, mais chaque tentative de l'approcher s'est avérée dangereuse."},de={title="Sethir the Ancient",body="Sethir the Ancient ist ein Satyr, der sich zwischen den Ästen in der Nähe des Orakels Glade versteckt. Diejenigen, die Teldrassil \"Krankheit untersuchen, glauben, dass er die Ursachen dafür kennen könnte, aber jeder Versuch, sich ihm zu nähern, hat sich als gefährlich erwiesen."},pt={title="Sethir the Ancient",body="Sethir the Ancient é um sátiro escondido entre os ramos perto do Oracle Glade. Aqueles que investigam a doença de Teldrassil acreditam que ele pode saber suas causas, mas toda tentativa de abordá-lo provou ser perigosa."},pl={title="Sethir the Ancient",body="Sethir the Ancient jest satyrem ukrywającym się wśród gałęzi przy Oracle Glade. Badacze choroby Teldrassil uważają, że może znać jej przyczyny, lecz każda próba zbliżenia się do niego okazała się niebezpieczna."},ru={title="Sethir the Ancient",body="Sethir the Ancient - сатир, скрывающийся среди ветвей возле Оракула Glade. Те, кто изучает болезнь Teldrassil, считают, что он может знать причины, но всякие попытки подойти к нему оказались опасными."},references={["place:teldrassil"]=true}},
    ["person:shadow-lord-feldan"] = {title="Señor de las Sombras Fel'dan",kind="Personaje",aliases={"Fel'dan","Fel’dan","Señor de las Sombras Fel'dan","Señor de las Sombras Fel’dan"},body="Fel'dan dirige las fuerzas de la Guarida Sombría y establece pactos con la Legión. Este señor de las sombras representa una parte importante del poder del Consejo de la Sombra en Frondavil.",aliasQuestIDs={},en={title="Shadow Lord Fel'dan",aliases={"Fel'dan","Fel’dan","Shadow Lord Fel'dan","Shadow Lord Fel’dan"},body="Fel'dan commands the forces in Shadow Hold and makes pacts with the Legion. The shadow lord represents an important part of the Shadow Council’s power in Felwood.",aliasQuestIDs={}},fr={title="Shadow Lord Fel'dan",body="Fel'dan commande les forces dans Shadow Hold et fait des pactes avec le Legion. Le seigneur des ombres représente une partie importante de la puissance du Shadow Council dans Felwood."},de={title="Shadow Lord Fel'dan",body="Fel'dan befehligt die Kräfte in Shadow Hold und schließt Pakte mit dem Legion. Der Schattenfürst stellt einen wichtigen Teil der Macht des Shadow Council in Felwood dar."},pt={title="Shadow Lord Fel'dan",body="Fel'dan comanda as forças em Shadow Hold e faz pactos com o Legion. O Senhor das Sombras representa uma parte importante do poder do Shadow Council no Felwood."},pl={title="Shadow Lord Fel'dan",body="Fel'dan dowodzi siłami Shadow Hold i zawiera pakty z Legion. Ten władca cienia stanowi ważną część potęgi Shadow Council w Felwood."},ru={title="Shadow Lord Fel'dan",body="Fel'dan командует силами в Shadow Hold и заключает пакты с Legion. Теневой лорд представляет собой важную часть силы Shadow Council  в Felwood."},references={["organization:burning-legion"]=true,["organization:shadow-council"]=true,["place:felwood"]=true}},
    ["person:shadow-priestess-shai"] = {title="Sacerdotisa de las Sombras Shai",kind="Personaje",aliases={"Sacerdotisa de las Sombras Shai","Shai"},body="Shai sirve a la Legión de Orgrimmar en Silithus. Prepara brebajes con ingredientes poco usuales para ayudar a sus fuerzas contra los silítidos que amenazan el desierto.",aliasQuestIDs={},en={title="Shadow Priestess Shai",aliases={"Shadow Priestess Shai","Shai"},body="Shai serves the Orgrimmar Legion in Silithus. She prepares concoctions from unusual ingredients to aid its forces against the silithid threatening the desert.",aliasQuestIDs={}},fr={title="Shadow Priestess Shai",body="Shai sert le Orgrimmar Legion dans Silithus. Elle prépare des concoctions à partir d'ingrédients inhabituels pour aider ses forces contre les silithid menaçant le désert."},de={title="Shadow Priestess Shai",body="Shai bedient die Orgrimmar Legion in Silithus. Sie bereitet Mixturen aus ungewöhnlichen Zutaten zu, um ihre Kräfte gegen den Silithid zu unterstützen, der die die die die Wüste bedrohen."},pt={title="Shadow Priestess Shai",body="Shai serve o Orgrimmar Legion em Silithus. Ela prepara misturas de ingredientes incomuns para ajudar suas forças contra o silithid ameaçando o deserto."},pl={title="Shadow Priestess Shai",body="Shai służy Orgrimmar Legion w Silithus. Przygotowuje mikstury z niezwykłych składników, by wspierać siły przeciw silithidom zagrażającym pustyni."},ru={title="Shadow Priestess Shai",body="Shai обслуживает Orgrimmar Legion в Silithus. Она готовит смеси из необычных ингредиентов, чтобы помочь своим силам против силитида, угрожающего пустыне."},references={["organization:orgrimmar-legion"]=true,["place:orgrimmar"]=true,["place:silithus"]=true}},
    ["person:shadumbra"] = {title="Shadumbra",kind="Personaje",aliases={"Shadumbra"},body="Shadumbra es un sable de la noche de Vallefresno conocido por su agilidad. Los cazadores del bosque lo cuentan entre las criaturas que exigen una demostración especial de habilidad.",aliasQuestIDs={},en={title="Shadumbra",aliases={"Shadumbra"},body="Shadumbra is a nightsaber in Ashenvale known for its agility. The forest’s hunters count it among the creatures that demand a particular display of skill.",aliasQuestIDs={}},fr={title="Shadumbra",body="Shadumbra est un nightsaber en Ashenvale connu pour son agilité. Les chasseurs de la forêt la comptent parmi les créatures qui exigent une démonstration particulière d’habileté."},de={title="Shadumbra",body="Shadumbra ist ein Nachtschwert in Ashenvale, das für seine Wendigkeit bekannt ist. Die Jäger des Waldes zählen ihn zu den Geschöpfen, die besondere Geschicklichkeit erfordern."},pt={title="Shadumbra",body="Shadumbra é um nightsaber em Ashenvale conhecido por sua agilidade. Os caçadores da floresta contam entre as criaturas que exigem uma exibição particular de habilidade."},pl={title="Shadumbra",body="Shadumbra jest nocną panterą w Ashenvale znaną ze zwinności. Myśliwi lasu zaliczają ją do stworzeń wymagających szczególnego pokazu umiejętności."},ru={title="Shadumbra",body="Shadumbra - ночной меч в Ashenvale, известный своей ловкостью. Охотники считают его одним из животных, требующих особого мастерства."},references={["place:ashenvale"]=true}},
    ["person:shaeldryn"] = {title="Shael'dryn",kind="Personaje",aliases={"Shael'dryn","Shael’dryn"},body="Shael'dryn es una dríade de la poza de la luna próxima al Lago Iris. Conoce la vara de Dartol y puede interpretar los materiales necesarios para recomponer ese objeto mágico.",aliasQuestIDs={},en={title="Shael'dryn",aliases={"Shael'dryn","Shael’dryn"},body="Shael'dryn is a dryad at the moonwell near Iris Lake. She knows about Dartol’s rod and can interpret the materials needed to restore that magical object.",aliasQuestIDs={}},fr={title="Shael'dryn",body="Shael'dryn est une dryade au puits de lune près du lac Iris. Elle connaît la canne de Dartol et peut interpréter les matériaux nécessaires pour restaurer cet objet magique."},de={title="Shael'dryn",body="Shael'dryn ist eine Dryade am Mondbrunnen nahe Iris Lake. Sie kennt sich mit dem Stab von Dartol aus und weiß, welche Materialien zur Wiederherstellung dieses magischen Gegenstands benötigt werden."},pt={title="Shael'dryn",body="Shael'dryn é um dryad no moonwell perto de Iris Lake. Ela sabe sobre a haste do Dartol e pode interpretar os materiais necessários para restaurar esse objeto mágico."},pl={title="Shael'dryn",body="Shael'dryn jest driadą przy księżycowej studni w pobliżu Iris Lake. Zna kostur postaci Dartol i potrafi określić materiały potrzebne do odnowienia tego magicznego przedmiotu."},ru={title="Shael'dryn",body="Shael'dryn - это дрияд в лунной колодце возле озера Айрис. Она знает о трость Dartol  и может интерпретировать материалы, необходимые для восстановления этого магического объекта."},references={["object:dartols-rod"]=true}},
    ["person:shanda"] = {title="Shanda",kind="Personaje",aliases={"Shanda"},body="Shanda es una instructora de sacerdotes de Cañada Umbría. Forma parte de los maestros que orientan a los nuevos aventureros elfos de la noche en el comienzo de su vocación.",aliasQuestIDs={},en={title="Shanda",aliases={"Shanda"},body="Shanda is a priest trainer in Shadowglen. She is one of the teachers guiding new night elf adventurers as they begin their calling.",aliasQuestIDs={}},fr={title="Shanda",body="Shanda est un prêtre formateur dans Shadowglen. Elle est l'une des enseignantes qui guident les nouveaux aventuriers elfes de la nuit alors qu'ils commencent leur appel."},de={title="Shanda",body="Shanda ist Priestertrainerin in Shadowglen. Sie ist eine der Lehrerinnen, die neue Nachtelfen-Abenteurer auf ihrem Weg zu ihrer Berufung begleiten."},pt={title="Shanda",body="Shanda é um treinador padre em Shadowglen. Ela é uma das professoras que guiam novos aventureiros elfos noturnos à medida que começam sua vocação."},pl={title="Shanda",body="Shanda jest nauczycielką kapłanów w Shadowglen. Należy do grona nauczycieli prowadzących początkujących poszukiwaczy przygód nocnych elfów na początku ich powołania."},ru={title="Shanda",body="Shanda - тренер жреца в Shadowglen. Она одна из учителей, направляющих новых приключенцев ночных эльфов, когда они начинают свое призвание."},references={["place:shadowglen"]=true},questIDs={[3119]=true,[5622]=true}},
    ["person:shandrina"] = {title="Shandrina",kind="Personaje",aliases={"Shandrina"},body="Shandrina participa en la defensa de los bosques de Vallefresno frente a los orcos. Recupera sus espadas y cuchillos para reciclarlos, aprovechando las armas enemigas en lugar de dejar que se desperdicien.",aliasQuestIDs={},en={title="Shandrina",aliases={"Shandrina"},body="Shandrina takes part in defending Ashenvale’s woods against the orcs. She recovers their swords and knives for salvage, repurposing enemy weapons rather than letting them go to waste.",aliasQuestIDs={}},fr={title="Shandrina",body="Shandrina prend part à la défense des bois de Ashenvale contre les orcs. Elle récupère leurs épées et leurs couteaux pour le sauvetage, réutilisant les armes ennemies plutôt que de les laisser se perdre."},de={title="Shandrina",body="Shandrina beteiligt sich an der Verteidigung der Wälder von Ashenvale gegen die Orks. Sie sammelt deren Schwerter und Messer zur Wiederverwertung ein und nutzt die Waffen des Feindes, statt sie verkommen zu lassen."},pt={title="Shandrina",body="Shandrina participa na defesa das madeiras de Ashenvale contra os orcs. Ela recupera suas espadas e facas para salvamento, reaproveitando armas inimigas em vez de deixá-las ir para o lixo."},pl={title="Shandrina",body="Shandrina uczestniczy w obronie lasów Ashenvale przed orkami. Odzyskuje ich miecze i noże na surowce, wykorzystując broń przeciwnika zamiast pozwalać jej się zmarnować."},ru={title="Shandrina",body="Shandrina участвует в защите лесов Ashenvale  от орков. Она извлекает их мечи и ножи для спасения, перерабатывая оружие врага, а не позволяя им растрачиваться."},references={["place:ashenvale"]=true}},
    ["person:shandris-feathermoon"] = {title="Shandris Plumaluna",kind="Personaje",aliases={"Shandris","Shandris Plumaluna"},body="Shandris Plumaluna es una general de los elfos de la noche vinculada al Bastión Plumaluna. Supervisa informes y exploraciones sobre los peligros que afectan a Feralas.",aliasQuestIDs={},en={title="Shandris Feathermoon",aliases={"Shandris","Shandris Feathermoon"},body="Shandris Feathermoon is a night elf general associated with Feathermoon Stronghold. She oversees reports and scouting concerning the dangers affecting Feralas.",aliasQuestIDs={}},fr={title="Shandris Feathermoon",body="Shandris Feathermoon est un elfe de nuit général associé à Feathermoon Stronghold. Elle supervise les rapports et le repérage concernant les dangers affectant Feralas."},de={title="Shandris Feathermoon",body="Shandris Feathermoon ist ein Nachtelfengeneral, der mit Feathermoon Stronghold in Verbindung gebracht wird. Sie beaufsichtigt Berichte und Auskundschaften über die Gefahren, denen Feralas ausgesetzt ist."},pt={title="Shandris Feathermoon",body="Shandris Feathermoon é um elfo noturno geral associado ao Feathermoon Stronghold. Ela supervisiona relatórios e pesquisas sobre os perigos que afetam o Feralas."},pl={title="Shandris Feathermoon",body="Shandris Feathermoon jest generałką nocnych elfów związaną z Feathermoon Stronghold. Nadzoruje raporty i zwiad dotyczące niebezpieczeństw dotykających Feralas."},ru={title="Shandris Feathermoon",body="Shandris Feathermoon - это генерал ночного эльфа, связанный с Feathermoon Stronghold. Она контролирует отчеты и разведку, касающиеся опасностей, затрагивающих Feralas."},references={["place:feathermoon-stronghold"]=true,["place:feralas"]=true}},
    ["person:sharptalon"] = {title="Garfafilada",kind="Personaje",aliases={"Garfafilada"},body="Garfafilada es un poderoso hipogrifo de Vallefresno. Su fuerza lo sitúa entre las grandes bestias del bosque reconocidas por quienes practican la Caza de Vallefresno.",aliasQuestIDs={},en={title="Sharptalon",aliases={"Sharptalon"},body="Sharptalon is a powerful hippogryph in Ashenvale. His strength places him among the forest’s great beasts recognized by those practicing the Ashenvale Hunt.",aliasQuestIDs={}},fr={title="Sharptalon",body="Sharptalon est un hippogryphe puissant dans Ashenvale. Sa force le place parmi les grandes bêtes de la forêt reconnues par ceux qui pratiquent le Ashenvale Hunt."},de={title="Sharptalon",body="Sharptalon ist ein mächtiger Hippogryph in Ashenvale. Seine Stärke macht ihn zu einem der großen Tiere des Waldes Waldes, die von den Übenden Ashenvale Hunt erkannt werden."},pt={title="Sharptalon",body="Sharptalon é um hipocrifo poderoso em Ashenvale. Sua força o coloca entre os grandes animais da floresta reconhecidos por aqueles que praticam o Ashenvale Hunt."},pl={title="Sharptalon",body="Sharptalon jest potężnym hipogryfem w Ashenvale. Siła stawia go wśród wielkich bestii lasu uznawanych przez uczestników Ashenvale Hunt."},ru={title="Sharptalon",body="Sharptalon - мощный гипогриф в Ashenvale. Его сила помещает его в число величайших зверей леса, признанных теми, кто практикует Ashenvale Hunt."},references={["place:ashenvale"]=true}},
    ["person:shay-leafrunner"] = {title="Shay Correhoja",kind="Personaje",aliases={"Shay","Shay Correhoja"},body="Shay Correhoja es una elfa de la noche que explora las ruinas de Feralas. Su curiosidad y su facilidad para apartarse del camino preocupan a quienes intentan mantenerla a salvo en el bosque.",aliasQuestIDs={},en={title="Shay Leafrunner",aliases={"Shay","Shay Leafrunner"},body="Shay Leafrunner is a night elf exploring Feralas’s ruins. Her curiosity and tendency to wander concern those trying to keep her safe in the forest.",aliasQuestIDs={}},fr={title="Shay Leafrunner",body="Shay Leafrunner est une elfe de nuit explorant les ruines de Feralas. Sa curiosité et sa tendance à errer concernent ceux qui tentent de la garder en sécurité dans la forêt."},de={title="Shay Leafrunner",body="Shay Leafrunner ist eine Nachtelfe, die Feralass Ruinen erkundet. Ihre Neugier und ihre Neigung zum Wandern betreffen diejenigen, die versuchen, sie im Wald sicher zu halten."},pt={title="Shay Leafrunner",body="Shay Leafrunner é um elfo noturno que explora as ruínas de Feralas. Sua curiosidade e tendência a vagar dizem respeito àqueles que tentam mantê-la segura na floresta."},pl={title="Shay Leafrunner",body="Shay Leafrunner jest nocną elfką badającą ruiny Feralas. Ciekawość i skłonność do oddalania się niepokoją osoby próbujące zapewnić jej bezpieczeństwo w lesie."},ru={title="Shay Leafrunner",body="Shay Leafrunner - это ночной эльф, исследующий руины Feralas. Ее любопытство и склонность бродить беспокоят тех, кто пытается сохранить ее в безопасности в лесу."},references={["place:feralas"]=true},questIDs={[2844]=true,[2845]=true}},
    ["person:shenthul"] = {title="Shenthul",kind="Personaje",aliases={"Shenthul"},body="Shenthul es un instructor del Circo de las Sombras de Orgrimmar vinculado a los Mano Destrozada. Su enseñanza desarrolla las habilidades de sigilo, engaño e infiltración de quienes trabajan en las sombras.",aliasQuestIDs={},en={title="Shenthul",aliases={"Shenthul"},body="Shenthul is a trainer in Orgrimmar’s Cleft of Shadow associated with the Shattered Hand. His teaching develops the stealth, deception and infiltration skills of those who work in the shadows.",aliasQuestIDs={}},fr={title="Shenthul",body="Shenthul est un formateur en Orgrimmar’s Cleft of Shadow associé au Shattered Hand. Son enseignement développe les compétences de furtivité, de tromperie et d'infiltration de ceux qui travaillent dans l'ombre."},de={title="Shenthul",body="Shenthul ist Trainer in Orgrimmar’s Cleft of Shadow, der mit dem Shattered Hand in Verbindung gebracht wird. Seine Lehre entwickelt die Geheimniskrämerei, Täuschungs- und Infiltrationsfähigkeiten jener, die im Schatten arbeiten."},pt={title="Shenthul",body="Shenthul é um treinador no Orgrimmar’s Cleft of Shadow associado ao Shattered Hand. Seu ensino desenvolve as habilidades de furtividade, engano e infiltração daqueles que trabalham nas sombras."},pl={title="Shenthul",body="Shenthul jest nauczycielem w miejscu zwanym Orgrimmar’s Cleft of Shadow związanym z Shattered Hand. Jego nauki rozwijają skradanie, podstęp i infiltrację u osób działających w cieniu."},ru={title="Shenthul",body="Shenthul - это тренер в Orgrimmar’s Cleft of Shadow, связанный с Shattered Hand. Его учение развивает скрытность, обман и навыки проникновения тех, кто работает в тени."},references={["organization:shattered-hand"]=true,["place:orgrimmar"]=true}},
    ["person:shikrik"] = {title="Shikrik",kind="Personaje",aliases={"Shikrik"},body="Shikrik es un instructor de chamanes del Valle de los Retos. Su enseñanza introduce a los nuevos aventureros en una práctica que vincula la formación de la Horda con la escucha de los elementos.",aliasQuestIDs={},en={title="Shikrik",aliases={"Shikrik"},body="Shikrik is a shaman trainer in the Valley of Trials. His teaching introduces new adventurers to a practice connecting Horde training with listening to the elements.",aliasQuestIDs={}},fr={title="Shikrik",body="Shikrik est un shaman formateur dans le Valley of Trials. Son enseignement introduit de nouveaux aventuriers à une pratique reliant la formation Horde à l'écoute des éléments."},de={title="Shikrik",body="Shikrik ist Schamanentrainer im Valley of Trials. Seine Lehre führt neue Abenteurer in eine Praxis ein, die Horde-Training mit dem Hören auf die Elemente verbindet."},pt={title="Shikrik",body="Shikrik é um treinador de xamãs no Valley of Trials. Seu ensino introduz novos aventureiros a uma prática que conecta o treinamento Horde com a escuta dos elementos."},pl={title="Shikrik",body="Shikrik jest nauczycielem szamanów w Valley of Trials. Wprowadza nowych poszukiwaczy przygód w praktykę łączącą szkolenie frakcji Horde ze słuchaniem żywiołów."},ru={title="Shikrik",body="Shikrik обучает шаманов в Valley of Trials. Его преподавание знакомит новых искателей приключений с практикой, соединяющей обучение Horde с прослушиванием стихии."},references={["organization:horde"]=true,["place:valley-of-trials"]=true}},
    ["person:shindrell-swiftfire"] = {title="Shindrell Fuegoveloz",kind="Personaje",aliases={"Shindrell","Shindrell Fuegoveloz"},body="Shindrell Fuegoveloz recibe en Astranaar a quienes ofrecen ayuda a la Alianza. Su labor conecta a los recién llegados con las necesidades de Vallefresno, un bosque cuya belleza no lo libra del peligro.",aliasQuestIDs={},en={title="Shindrell Swiftfire",aliases={"Shindrell","Shindrell Swiftfire"},body="Shindrell Swiftfire receives those offering aid to the Alliance in Astranaar. Her work connects newcomers with the needs of Ashenvale, a forest whose beauty does not spare it from danger.",aliasQuestIDs={}},fr={title="Shindrell Swiftfire",body="Shindrell Swiftfire reçoit ceux offrant l'aide à la Alliance dans Astranaar. Son travail relie les nouveaux arrivants aux besoins de Ashenvale, une forêt dont la beauté ne l’épargne pas du danger."},de={title="Shindrell Swiftfire",body="Shindrell Swiftfire nimmt diejenigen auf, die Alliance in Astranaar Hilfe anbieten. Ihre Arbeit verbindet Neuankömmlinge mit den Bedürfnissen Ashenvales, einem Wald, dessen Schönheit ihn nicht vor Gefahren bewahrt."},pt={title="Shindrell Swiftfire",body="Shindrell Swiftfire recebe aqueles que oferecem ajuda ao Alliance em Astranaar. Seu trabalho conecta os recém-chegados com as necessidades de Ashenvale, uma floresta cuja beleza não o poupa do perigo."},pl={title="Shindrell Swiftfire",body="Shindrell Swiftfire przyjmuje osoby oferujące pomoc frakcji Alliance w Astranaar. Łączy przybyszów z potrzebami Ashenvale, lasu, którego piękno nie chroni przed niebezpieczeństwem."},ru={title="Shindrell Swiftfire",body="Shindrell Swiftfire принимает тех, кто предлагает помощь Alliance в Astranaar. Ее работа связывает новичков с потребностями Ashenvale, леса, красота которого не избавляет от опасности."},references={["organization:alliance"]=true,["place:ashenvale"]=true,["place:astranaar"]=true}},
    ["person:shizzle"] = {title="Shizzle",kind="Personaje",aliases={"Shizzle"},body="Shizzle es un inventor varado en el Refugio de Marshal, en Un'Goro. Su desconfianza hacia las monturas voladoras lo ha llevado a intentar construir una máquina que le permita salir del cráter.",aliasQuestIDs={},en={title="Shizzle",aliases={"Shizzle"},body="Shizzle is an inventor stranded at Marshal's Refuge in Un'Goro. His distrust of flying mounts has led him to try building a machine that can take him out of the crater.",aliasQuestIDs={}},fr={title="Shizzle",body="Shizzle est un inventeur échoué à Marshal's Refuge dans Un'Goro. Sa méfiance à l'égard des montures volantes l'a amené à essayer de construire une machine qui peut le sortir du cratère."},de={title="Shizzle",body="Shizzle ist ein Erfinder bei Marshal's Refuge in Un'Goro gestrandet ist. Sein Misstrauen gegenüber fliegenden Reittieren hat ihn veranlasst, eine Maschine zu bauen zu versuchen, die ihn aus dem Krater zu lassen."},pt={title="Shizzle",body="Shizzle é um inventor encalhado no Marshal's Refuge em Un'Goro. Sua desconfiança de montares voadores o levou a tentar construir uma máquina que pode tirá-lo da cratera."},pl={title="Shizzle",body="Shizzle jest wynalazcą uwięzionym w Marshal's Refuge w Un'Goro. Nieufność wobec latających wierzchowców skłoniła go do próby budowy maszyny, która pozwoli opuścić krater."},ru={title="Shizzle",body="Shizzle - изобретатель, застрявший в Marshal's Refuge в Un'Goro. Недоверие к летающим лошадям побудило его попытаться построить машину, которая выведет его из кратера."},references={["place:marshals-refuge"]=true,["place:ungoro-crater"]=true}},
    ["person:shreev"] = {title="Shreev",kind="Personaje",aliases={"Shreev"},body="Shreev trabaja con componentes de maquinaria en Gadgetzan. Sus propulsores de seforio muestran la tensión entre las medidas de seguridad y la búsqueda de mayor potencia en los vehículos de carreras.",aliasQuestIDs={},en={title="Shreev",aliases={"Shreev"},body="Shreev works with machine components in Gadgetzan. His seaforium boosters show the tension between safety measures and the pursuit of greater power in racing vehicles.",aliasQuestIDs={}},fr={title="Shreev",body="Shreev travaille avec les composants de la machine dans Gadgetzan. Ses boosters seaforium montrent la tension entre les mesures de sécurité et la poursuite d'une plus grande puissance dans les véhicules de course."},de={title="Shreev",body="Shreev arbeitet in Gadgetzan mit Maschinenkomponenten. Seine Seaforium-Booster zeigen das Spannungsverhältnis zwischen Sicherheitsmaßnahmen und dem Streben nach mehr Macht in Rennfahrzeugen."},pt={title="Shreev",body="Shreev trabalha com componentes de máquina em Gadgetzan. Seus impulsionadores do seaforium mostram a tensão entre medidas de segurança e a busca de maior potência em veículos de corrida."},pl={title="Shreev",body="Shreev pracuje z częściami maszyn w Gadgetzan. Jego wzmacniacze seforium pokazują napięcie między środkami bezpieczeństwa a dążeniem do większej mocy pojazdów wyścigowych."},ru={title="Shreev",body="Shreev работает с компонентами машины в Gadgetzan. Его сиефориумные усилители показывают напряженность между мерами безопасности и стремлением к большей мощности в гоночных автомобилях."},references={["place:gadgetzan"]=true}},
    ["person:shy-rotam"] = {title="Shi-Rotam",kind="Personaje",aliases={"Shi-Rotam"},body="Shi-Rotam es la matriarca de los grandes felinos que se reúnen en Roca Sable de Hielo. Su autoridad entre los sables de hielo del norte de Cuna del Invierno hace de ella una adversaria respetada por los cazadores.",aliasQuestIDs={},en={title="Shy-Rotam",aliases={"Shy-Rotam"},body="Shy-Rotam is the matriarch of the great cats gathering at Frostsaber Rock. Her standing among northern Winterspring’s frostsabers makes her an adversary respected by hunters.",aliasQuestIDs={}},fr={title="Shy-Rotam",body="Shy-Rotam est la matriarche des grands félins réunis au Frostsaber Rock. Sa position parmi les sabres glacés du nord de Winterspring fait d'elle un adversaire respecté par les chasseurs."},de={title="Shy-Rotam",body="Shy-Rotam ist die Matriarchin der großen Katzen, die sich in Frostsaber Rock versammeln. Ihr Standing unter den Frostsäbeln Wintersprings im Norden macht sie zu einer Gegnerin, die von den Jägern respektiert wird."},pt={title="Shy-Rotam",body="Shy-Rotam é a matriarca da reunião de grandes gatos no Frostsaber Rock. Sua posição entre os frostsabers do norte da Winterspring faz dela uma adversária respeitada pelos caçadores."},pl={title="Shy-Rotam",body="Shy-Rotam jest matriarchinią wielkich kotów gromadzących się przy Frostsaber Rock. Pozycja wśród lodowych panter północnego Winterspring czyni ją przeciwniczką szanowaną przez myśliwych."},ru={title="Shy-Rotam",body="Shy-Rotam - матриарха больших кошек, собравшихся в Frostsaber Рок. Ее положение среди северных зимовых мечов Winterspring делает ее уважаемым противником охотников."},references={["place:winterspring"]=true}},
    ["person:sister-aquinne"] = {title="Hermana Aquinne",kind="Personaje",aliases={"Aquinne","Hermana Aquinne"},body="La hermana Aquinne es una sacerdotisa novicia de Darnassus. Comparte con la sacerdotisa A'moora la preocupación por las grandes criaturas del bosque que necesitan ayuda, conectando a los visitantes con ese deber de cuidado.",aliasQuestIDs={},en={title="Sister Aquinne",aliases={"Aquinne","Sister Aquinne"},body="Sister Aquinne is a novice priestess in Darnassus. She shares Priestess A'moora’s concern for great forest creatures in need, bringing visitors into contact with that duty of care.",aliasQuestIDs={}},fr={title="Sister Aquinne",body="Sister Aquinne est une prêtresse novice en Darnassus. Elle partage le souci de Priestess A'moora pour les grandes créatures forestières dans le besoin, mettant les visiteurs en contact avec ce devoir de diligence."},de={title="Sister Aquinne",body="Sister Aquinne ist Priesteranfängerin in Darnassus. Sie teilt Priestess A'mooras Sorge um die großen Waldbewohner in Not und bringt die Besucher mit dieser Fürsorgepflicht in Berührung."},pt={title="Sister Aquinne",body="Sister Aquinne é uma sacerdotisa iniciante em Darnassus. Ela compartilha a preocupação da Priestess A'moora com as grandes criaturas florestais necessitadas, trazendo os visitantes em contato com esse dever de cuidado."},pl={title="Sister Aquinne",body="Sister Aquinne jest początkującą kapłanką w Darnassus. Podziela troskę Priestess A'moora o wielkie leśne stworzenia potrzebujące pomocy i zapoznaje przybyszów z obowiązkiem opieki nad nimi."},ru={title="Sister Aquinne",body="Sister Aquinne - начинающая жрица в Darnassus. Она разделяет заботу Priestess A'moora о больших лесных существах, нуждающихся в помощи, и привлекает посетителей к этой обязанности заботы."},references={["person:priestess-amoora"]=true,["place:darnassus"]=true}},
    ["person:skinner-jamani"] = {title="Desollador Jamani",kind="Personaje",aliases={"Desollador Jamani","Jamani","desollador Jamani"},body="El desollador Jamani participa en los preparativos de la Horda para Ahn'Qiraj. Reúne cuero pesado para materiales tan distintos como refuerzos de armadura y lonas, mostrando la variedad de necesidades de un ejército.",aliasQuestIDs={},en={title="Skinner Jamani",aliases={"Jamani","Skinner Jamani"},body="Skinner Jamani takes part in the Horde’s preparations for Ahn'Qiraj. He gathers heavy leather for materials ranging from armor reinforcement to canvas, showing the variety of an army’s needs.",aliasQuestIDs={}},fr={title="Skinner Jamani",body="Skinner Jamani participe aux préparations du Horde pour le Ahn'Qiraj. Il rassemble du cuir lourd pour des matériaux allant du renforcement d'armure à la toile, montrant la variété des besoins d'une armée."},de={title="Skinner Jamani",body="Skinner Jamani beteiligt sich an den Vorbereitungen der Horde für Ahn'Qiraj. Er sammelt schweres Leder für unterschiedliche Verwendungszwecke, von der Verstärkung von Rüstungen bis hin zu Planen, und verdeutlicht damit die vielfältigen Bedürfnisse einer Armee."},pt={title="Skinner Jamani",body="Skinner Jamani participa dos preparativos do Horde para o Ahn'Qiraj. Ele reúne couro pesado para materiais que vão desde reforço de armadura até lona, mostrando a variedade de necessidades de um exército."},pl={title="Skinner Jamani",body="Skinner Jamani uczestniczy w przygotowaniach frakcji Horde do Ahn'Qiraj. Zbiera grubą skórę na materiały służące od wzmacniania pancerzy po płótna, ukazując różnorodność potrzeb armii."},ru={title="Skinner Jamani",body="Skinner Jamani участвует в подготовке Horde s к Ahn'Qiraj. Он собирает тяжелую кожу для материалов от арматуры до холста, показывая разнообразие потребностей армии."},references={["organization:horde"]=true,["place:ahnqiraj"]=true}},
    ["person:smeed"] = {title="Smeed",kind="Personaje",aliases={"Smeed"},body="Smeed trabaja en el Campamento de los Mezclatornillos de Desolace y mantiene negocios relacionados con las caravanas. Su actividad depende de que los cargamentos atraviesen territorios amenazados por centauros y demonios.",aliasQuestIDs={},en={title="Smeed",aliases={"Smeed"},body="Smeed works at Scrabblescrew’s Camp in Desolace and conducts business associated with caravans. His livelihood depends on cargo crossing territories threatened by centaurs and demons.",aliasQuestIDs={}},fr={title="Smeed",body="Smeed travaille au camp de Scrabblescrew à Desolace et mène des affaires associées aux caravanes. Son gagne-pain dépend de la traversée de territoires menacés par des centaures et des démons."},de={title="Smeed",body="Smeed arbeitet im Scrabblescrew 's Camp in Desolace und betreibt Geschäfte im Zusammenhang mit Wohnwagen. Sein Lebensunterhalt hängt davon ab, dass Fracht Gebiete überquert, die von Zentauren und Dämonen bedroht sind."},pt={title="Smeed",body="Smeed trabalha no acampamento de Scrabblescrew em Desolace e conduz negócios associados a caravanas. Sua subsistência depende de territórios de passagem de carga ameaçados por centauros e demônios."},pl={title="Smeed",body="Smeed pracuje w obozie Scrabblescrew w Desolace i prowadzi interesy związane z karawanami. Jego utrzymanie zależy od ładunków przemierzających terytoria zagrożone przez centaury oraz demony."},ru={title="Smeed",body="Smeed работает в лагере Scrabblescrew s в Desolace и ведет бизнес, связанный с караванами. Его средства к существованию зависят от грузов, пересекающих территории, которым угрожают кентавры и демоны."},references={["place:desolace"]=true}},
    ["person:spigot-operator-luglunket"] = {title="Grifoperador Llantalunket",kind="Personaje",aliases={"Grifoperador Llantalunket","grifoperador Llantalunket"},body="El grifoperador Llantalunket trabaja para la compañía de aguas de Gadgetzan. Recuperar las reservas robadas por los Vagayermos forma parte de su labor para mantener abastecido al poblado del desierto.",aliasQuestIDs={},en={title="Spigot Operator Luglunket",aliases={"Luglunket","Spigot Operator Luglunket"},body="Spigot Operator Luglunket works for the Gadgetzan Water Company. Recovering reserves stolen by the Wastewander is part of his work to keep the desert town supplied.",aliasQuestIDs={}},fr={title="Spigot Operator Luglunket",body="Spigot Operator Luglunket travaille pour la Gadgetzan Water Company. La récupération des réserves volées par le Wastewander fait partie de son travail pour garder la ville du désert approvisionnée."},de={title="Spigot Operator Luglunket",body="Spigot Operator Luglunket arbeitet für die Gadgetzan Water Company. Die Rückgewinnung von den Wastewander gestohlener Reserven ist Teil seiner Arbeit, um die Versorgung der Wüstenstadt aufrechtzuerhalten."},pt={title="Spigot Operator Luglunket",body="Spigot Operator Luglunket trabalha para a Gadgetzan Water Company. A recuperação de reservas roubadas pelo Wastewander faz parte de seu trabalho para manter a cidade do deserto fornecida."},pl={title="Spigot Operator Luglunket",body="Spigot Operator Luglunket pracuje dla przedsiębiorstwa wodnego Gadgetzan. Odzyskiwanie rezerw skradzionych przez Wastewander należy do jego pracy nad utrzymaniem zaopatrzenia pustynnego miasta."},ru={title="Spigot Operator Luglunket",body="Spigot Operator Luglunket работает в компании Gadgetzan Water. Восстановление запасов, украденных Wastewander, является частью его работы, чтобы обеспечить пустынный город."},references={["place:gadgetzan"]=true}},
    ["person:spraggle-frock"] = {title="Spraggle Frock",kind="Personaje",aliases={"Spraggle Frock"},body="Spraggle Frock mantiene un interés práctico en la seguridad del Refugio de Marshal. Las criaturas voladoras del Cráter de Un'Goro son una de sus preocupaciones por el peligro que representan para los viajeros.",aliasQuestIDs={},en={title="Spraggle Frock",aliases={"Spraggle","Spraggle Frock"},body="Spraggle Frock takes a practical interest in the safety of Marshal's Refuge. The flying creatures of Un'Goro Crater are among the concerns she raises because of their danger to travelers.",aliasQuestIDs={}},fr={title="Spraggle Frock",body="Spraggle Frock prend un intérêt pratique dans la sécurité de Marshal's Refuge. Les créatures volantes de Un'Goro Crater font partie des préoccupations qu'elle soulève en raison de leur danger pour les voyageurs."},de={title="Spraggle Frock",body="Spraggle Frock hat ein praktisches Interesse an der Sicherheit von Marshal's Refuge. Die fliegenden Kreaturen Un'Goro Craters gehören zu den Bedenken, die sie aufgrund ihrer Gefährdung der Reisenden aufwirft."},pt={title="Spraggle Frock",body="Spraggle Frock tem um interesse prático na segurança do Marshal's Refuge. As criaturas voadoras de Un'Goro Crater estão entre as preocupações que ela levanta por causa de seu perigo para os viajantes."},pl={title="Spraggle Frock",body="Spraggle Frock troszczy się w praktyczny sposób o bezpieczeństwo Marshal's Refuge. Wśród zgłaszanych przez nią problemów są latające stworzenia Un'Goro Crater ze względu na niebezpieczeństwo, jakie stanowią dla podróżnych."},ru={title="Spraggle Frock",body="Spraggle Frock проявляет практический интерес к безопасности Marshal's Refuge. Летящие существа Un'Goro Crater являются одной из проблем, которые она поднимает из-за их опасности для путешественников."},references={["place:marshals-refuge"]=true,["place:ungoro-crater"]=true}},
    ["person:sputtervalve"] = {title="Petardol",kind="Personaje",aliases={"Petardol"},body="Petardol es un técnico goblin de Trinquete con interés en máquinas y diseños industriales. Su conocimiento le permite examinar mecanismos y planos relacionados con las operaciones de Ventura y Cía.",aliasQuestIDs={},en={title="Sputtervalve",aliases={"Sputtervalve"},body="Sputtervalve is a goblin technician in Ratchet with an interest in machines and industrial designs. His expertise allows him to examine mechanisms and plans connected with Venture Company operations.",aliasQuestIDs={}},fr={title="Sputtervalve",body="Sputtervalve est un technicien gobelin à Ratchet avec un intérêt pour les machines et les dessins industriels. Son expertise lui permet d’examiner les mécanismes et les plans liés aux opérations Venture Company."},de={title="Sputtervalve",body="Sputtervalve ist Koboldtechniker in Ratchet und interessiert sich für Maschinen und Industriedesign. Seine Expertise ermöglicht es ihm, Mechanismen und Pläne im Zusammenhang mit Venture Company-Operationen zu untersuchen."},pt={title="Sputtervalve",body="Sputtervalve é um técnico goblin em Ratchet com interesse em máquinas e projetos industriais. Sua experiência lhe permite examinar mecanismos e planos relacionados com as operações Venture Company."},pl={title="Sputtervalve",body="Sputtervalve jest goblińskim technikiem w Ratchet zainteresowanym maszynami i projektami przemysłowymi. Wiedza pozwala mu badać mechanizmy oraz plany związane z działalnością Venture Company."},ru={title="Sputtervalve",body="Sputtervalve - технический гоблин в Ratchet, интересующийся машинами и промышленными конструкциями. Его опыт позволяет ему исследовать механизмы и планы, связанные с операциями Venture Company."},references={["organization:venture-company"]=true,["place:ratchet"]=true}},
    ["person:steelsnap"] = {title="Metaleador",kind="Personaje",aliases={"Metaleador"},body="Metaleador es una hiena de Las Mil Agujas que atrae a otras de su especie. Su agresividad provoca miedo y derramamiento de sangre entre las bestias más pacíficas, hasta el punto de que los cazadores lo consideran ajeno a la bendición de la Madre Tierra.",aliasQuestIDs={},en={title="Steelsnap",aliases={"Steelsnap"},body="Steelsnap is a Thousand Needles hyena who draws others of his kind to him. His aggression spreads fear and bloodshed among more peaceful beasts, leading hunters to regard him as outside the Earth Mother’s blessing.",aliasQuestIDs={}},fr={title="Steelsnap",body="Steelsnap est une hyène Thousand Needles qui attire d'autres de son genre à lui. Son agression répand la peur et l'effusion de sang parmi les bêtes plus pacifiques, ce qui conduit les chasseurs à le considérer comme en dehors de la bénédiction de la Earth Mother."},de={title="Steelsnap",body="Steelsnap ist eine Thousand Needles-Hyäne, die andere seiner Art zu sich anzieht. Seine Aggression verbreitet Angst und Blutvergießen unter friedlicheren Tieren, was dazu führt, dass die Jäger ihn als außerhalb des Segens des Segens von Earth Mother betrachten."},pt={title="Steelsnap",body="Steelsnap é uma hiena Thousand Needles que atrai outros de sua espécie para ele. Sua agressão espalha medo e derramamento de sangue entre animais mais pacíficos, levando os caçadores a considerá-lo fora da bênção do Earth Mother."},pl={title="Steelsnap",body="Steelsnap jest hieną Thousand Needles przyciągającą inne zwierzęta swojego gatunku. Agresja szerzy lęk i rozlew krwi wśród spokojniejszych bestii, dlatego myśliwi uznają go za pozbawionego błogosławieństwa istoty Earth Mother."},ru={title="Steelsnap",body="Steelsnap - хиена Thousand Needles, которая привлекает к себе других своих родственников. Его агрессия распространяет страх и кровопролитие среди более мирных зверей, что заставляет охотников считать его вне благословения Earth Mother."},references={["person:earth-mother"]=true,["place:thousand-needles"]=true}},
    ["person:stinglasher"] = {title="Latigador con aguijón",kind="Personaje",aliases={"Latigador con aguijón"},body="Latigador con aguijón es un insecto de gran tamaño avistado en Las Galerías Retorcidas. Su secreción produce un aura distinta a la de las otras criaturas de la zona, una particularidad que despierta el interés de quienes estudian la amenaza.",aliasQuestIDs={},en={title="Stinglasher",aliases={"Stinglasher"},body="Stinglasher is an unusually large insect sighted in the Writhing Deep. Its secretions produce an aura unlike that of the other creatures nearby, drawing the interest of those studying the threat.",aliasQuestIDs={}},fr={title="Stinglasher",body="Stinglasher est un insecte inhabituellement grand aperçu dans le Writhing Deep. Ses sécrétions produisent une aura différente de celle des autres créatures voisines, attirant l'intérêt de ceux qui étudient la menace."},de={title="Stinglasher",body="Stinglasher ist ein ungewöhnlich großes Insekt, das im Writhing Deep gesichtet wird. Seine Sekrete erzeugen eine Aura, die anders ist als die der anderer Kreaturen in der Nähe, was das Interesse derjenigen weckt, die diese Bedrohung untersuchen."},pt={title="Stinglasher",body="Stinglasher é um inseto invulgarmente grande avistado no Writhing Deep. Suas secreções produzem uma aura diferente das outras criaturas próximas, atraindo o interesse daqueles que estudam a ameaça."},pl={title="Stinglasher",body="Stinglasher jest niezwykle dużym owadem widywanym w Writhing Deep. Wydzieliny tworzą aurę inną niż u pozostałych pobliskich stworzeń, budząc zainteresowanie badaczy tego zagrożenia."},ru={title="Stinglasher",body="Stinglasher - это необычно большое насекомое, замеченное в Writhing Deep. Его секреты создают ауру, отличную от той, что бывает у других животных, и это вызывает интерес у тех, кто изучает угрозу."},references={["place:writhing-deep"]=true}},
    ["person:stinky-ignatz"] = {title="\"Apestoso\" Ignatz",kind="Personaje",aliases={"\"Apestoso\" Ignatz","Ignatz"},body="\"Apestoso\" Ignatz recolecta plantas en el Marjal Revolcafango para recetas de Morgan Stern. Su trabajo permite obtener ingredientes de un pantano cuyas criaturas dificultan incluso las tareas más cotidianas.",aliasQuestIDs={},en={title="\"Stinky\" Ignatz",aliases={"\"Stinky\" Ignatz","Ignatz"},body="\"Stinky\" Ignatz gathers plants in Dustwallow Marsh for Morgan Stern’s recipes. His work supplies ingredients from a marsh whose creatures make even everyday tasks difficult.",aliasQuestIDs={}},fr={title="\"Stinky\" Ignatz",body="\"Stinky\" Ignatz rassemble des plantes dans Dustwallow Marsh pour les recettes de Morgan Stern. Son travail fournit des ingrédients à partir d'un marais dont les créatures rendent même les tâches quotidiennes difficiles."},de={title="\"Stinky\" Ignatz",body="\"Stinky\" Ignatz sammelt Pflanzen in Dustwallow Marsh für Morgan Stern 'Rezepte. Seine Arbeit liefert Zutaten aus einem Sumpf, dessen Geschöpfe selbst alltägliche Aufgaben erschweren."},pt={title="\"Stinky\" Ignatz",body="\"Stinky\" Ignatz reúne plantas em Dustwallow Marsh para receitas de Morgan Stern. Seu trabalho fornece ingredientes de um pântano cujas criaturas dificultam até mesmo as tarefas diárias."},pl={title="\"Stinky\" Ignatz",body="\"Stinky\" Ignatz zbiera rośliny w Dustwallow Marsh do przepisów postaci Morgan Stern. Jego praca dostarcza składników z bagien, których stworzenia utrudniają nawet codzienne zadania."},ru={title="\"Stinky\" Ignatz",body="\"Stinky\" Ignatz собирает растения в Dustwallow Marsh для рецептов Morgan Stern s. Его работа снабжает ингредиентами из болота, чьи существа затрудняют даже повседневные задачи."},references={["person:morgan-stern"]=true,["place:dustwallow-marsh"]=true}},
    ["person:stoley"] = {title="Stoley",kind="Personaje",aliases={"Stoley"},body="Stoley atiende un bar en el Puerto Bonvapor de Tanaris. Sus tratos con otros taberneros y su orgullo por el ron local reflejan una vida comercial que une los puertos de ambos continentes.",aliasQuestIDs={},en={title="Stoley",aliases={"Stoley"},body="Stoley runs a bar in Steamwheedle Port in Tanaris. His deals with other bartenders and pride in local rum reflect a commercial life connecting ports on both continents.",aliasQuestIDs={}},fr={title="Stoley",body="Stoley tient un bar à Steamwheedle Port, en Tanaris. Ses affaires avec d'autres tenanciers et sa fierté pour le rhum local reflètent une vie commerciale qui relie les ports des deux continents."},de={title="Stoley",body="Stoley betreibt eine Bar in Steamwheedle Port in Tanaris. Seine Geschäfte mit anderen Barkeepern und sein Stolz auf lokalen Rum spiegeln ein kommerzielles Leben wider, das die Häfen auf beiden Kontinente verbindet."},pt={title="Stoley",body="Stoley executa uma barra no Steamwheedle Port em Tanaris. Seus negócios com outros bartenders e o orgulho no rum local refletem uma vida comercial conectando portos em ambos os continentes."},pl={title="Stoley",body="Stoley prowadzi bar w Steamwheedle Port w Tanaris. Umowy z innymi barmanami i duma z miejscowego rumu odzwierciedlają życie handlowe łączące porty obu kontynentów."},ru={title="Stoley",body="Stoley управляет баром в Steamwheedle Port на территории Tanaris. Его отношения с другими барменами и гордость за местный ром отражают коммерческую жизнь, соединяющую порты на обоих континентах."},references={["place:steamwheedle-port"]=true,["place:tanaris"]=true}},
    ["person:stoma-the-ancient"] = {title="Estoma el Anciano",kind="Personaje",aliases={"Estoma","Estoma el Anciano"},body="Estoma el Anciano domina el encantamiento de materiales para armas de los antiguos. Su conocimiento permite transformar tendones de dragón en cuerdas de arco de resistencia extraordinaria.",aliasQuestIDs={},en={title="Stoma the Ancient",aliases={"Stoma","Stoma the Ancient"},body="Stoma the Ancient masters the enchanting of materials for the ancients’ weapons. His knowledge can transform dragon sinew into bowstrings of extraordinary strength.",aliasQuestIDs={}},fr={title="Stoma the Ancient",body="Stoma the Ancient maîtrise l’enchantement des matériaux pour les armes des anciens. Sa connaissance peut transformer le tendon de dragon en cordes d'une force extraordinaire."},de={title="Stoma the Ancient",body="Stoma the Ancient beherrscht das bezaubernde Material für die Waffen der Alten. Sein Wissen kann Drachensehnen in Bogensehnen von außergewöhnlicher Stärke verwandeln."},pt={title="Stoma the Ancient",body="Stoma the Ancient domina o encantamento de materiais para as armas dos antigos. Seu conhecimento pode transformar tendões de dragão em cordas de arco de extraordinária força."},pl={title="Stoma the Ancient",body="Stoma the Ancient opanował zaklinanie materiałów na broń pradawnych. Jego wiedza pozwala zamieniać smocze ścięgna w cięciwy o niezwykłej wytrzymałości."},ru={title="Stoma the Ancient",body="Stoma the Ancient владеет магией материалов для древних оружий. Его знания могут превратить драконьи сухожилия в луковые струны с необычайной силой."},references={}},
    ["person:stoneguard-clayhoof"] = {title="Guardia de piedra Pezuña de Barro",kind="Personaje",aliases={"Guardia de piedra Pezuña de Barro"},body="Guardia de piedra Pezuña de Barro reúne vendas para los soldados de la Horda que se preparan para Ahn'Qiraj. Su tarea se centra en el abastecimiento médico, una necesidad compartida incluso por ejércitos que normalmente son rivales.",aliasQuestIDs={},en={title="Stoneguard Clayhoof",aliases={"Clayhoof","Stoneguard Clayhoof"},body="Stoneguard Clayhoof gathers bandages for Horde soldiers preparing for Ahn'Qiraj. His work concerns medical supplies, a need shared even by armies that are normally rivals.",aliasQuestIDs={}},fr={title="Stoneguard Clayhoof",body="Stoneguard Clayhoof rassemble des bandages pour les soldats Horde se préparant pour Ahn'Qiraj. Son travail concerne les fournitures médicales, un besoin partagé même par des armées qui sont normalement rivales."},de={title="Stoneguard Clayhoof",body="Stoneguard Clayhoof sammelt Verbände für Horde Soldaten, die sich auf Ahn'Qiraj vorbereiten. Seine Arbeit betrifft die medizinische Versorgung, ein Bedürfnis, das selbst Armeen teilen, die normalerweise rivalisierende Armeen."},pt={title="Stoneguard Clayhoof",body="Stoneguard Clayhoof reúne bandagens para soldados Horde se preparando para Ahn'Qiraj. Seu trabalho diz respeito a suprimentos médicos, uma necessidade compartilhada até mesmo por exércitos que normalmente são rivais."},pl={title="Stoneguard Clayhoof",body="Stoneguard Clayhoof zbiera bandaże dla żołnierzy frakcji Horde przygotowujących się do Ahn'Qiraj. Zajmuje się zaopatrzeniem medycznym, potrzebnym nawet armiom będącym zazwyczaj rywalami."},ru={title="Stoneguard Clayhoof",body="Stoneguard Clayhoof собирает повязки для солдат Horde, готовящихся к Ahn'Qiraj. Его работа связана с медицинскими припасами, нуждой, которая есть даже у враждующих армий."},references={["organization:horde"]=true,["place:ahnqiraj"]=true}},
    ["person:stormheart"] = {title="Cuoretormenta",kind="Personaje",aliases={"Cuoretormenta"},body="Cuoretormenta es un truenagarto de tamaño excepcional que recorre el borde del cañón en Las Mil Agujas. Su fuerza y su comportamiento poco dócil hacen peligroso enfrentarse a él sin ayuda.",aliasQuestIDs={},en={title="Stormheart",aliases={"Stormheart"},body="Stormheart is an exceptionally large thunder lizard patrolling the canyon edge in Thousand Needles. Its strength and undocile nature make confronting it alone dangerous.",aliasQuestIDs={}},fr={title="Stormheart",body="Stormheart est un lézard tonnerre exceptionnellement grand patrouillant le bord du canyon dans Thousand Needles. Sa force et sa nature peu docile le rendent dangereux."},de={title="Stormheart",body="Stormheart ist eine außergewöhnlich große Donner-Eidechse, die den Canyonrand in Thousand Needles patrouilliert. Seine Stärke und seine Unfügsamkeit machen seine Konfrontation allein gefährlich."},pt={title="Stormheart",body="Stormheart é um lagarto trovão excepcionalmente grande patrulhando a borda do canyon em Thousand Needles. Sua força e natureza desobediente tornam perigoso confrontá-lo sozinho."},pl={title="Stormheart",body="Stormheart jest wyjątkowo wielką jaszczurką piorunową patrolującą krawędź kanionu w Thousand Needles. Siła i nieposkromiona natura czynią samotne starcie niebezpiecznym."},ru={title="Stormheart",body="Stormheart - это исключительно большая молниеносная ящерица, патрулирующая краю каньона в Thousand Needles. Его сила и непокорный характер делают его опасной."},references={["place:thousand-needles"]=true}},
    ["person:strahad-farsan"] = {title="Strahad Farsan",kind="Personaje",aliases={"Strahad","Strahad Farsan"},body="Strahad Farsan es un instructor de brujos de Trinquete interesado en la invocación de demonios. El estudio de textos antiguos y el dominio de rituales forman parte de la formación que ofrece.",aliasQuestIDs={},en={title="Strahad Farsan",aliases={"Strahad","Strahad Farsan"},body="Strahad Farsan is a warlock instructor in Ratchet interested in summoning demons. Studying old texts and mastering rituals are part of the training he offers.",aliasQuestIDs={}},fr={title="Strahad Farsan",body="Strahad Farsan est un instructeur de démoniste en Ratchet intéressé à invoquer des démons. L’étude des textes anciens et la maîtrise des rituels font partie de la formation qu’il propose."},de={title="Strahad Farsan",body="Strahad Farsan ist Hexenmeister und Ratchet interessiert daran, Dämonen heraufzubeschwören. Das Studium alter Texte und das Beherrschen von Ritualen sind Teil seiner Ausbildung."},pt={title="Strahad Farsan",body="Strahad Farsan é um instrutor de bruxo em Ratchet interessado em convocar demônios. Estudar textos antigos e dominar rituais fazem parte do treinamento que ele oferece."},pl={title="Strahad Farsan",body="Strahad Farsan jest nauczycielem czarnoksiężników w Ratchet zainteresowanym przywoływaniem demonów. Badanie starych tekstów i opanowywanie rytuałów stanowią część oferowanego przez niego szkolenia."},ru={title="Strahad Farsan",body="Strahad Farsan - инструктор-чернокнижник в Ratchet, заинтересованный в вызове демонов. Изучение древних текстов и овладение ритуалами - часть обучения, которое он предлагает."},references={["place:ratchet"]=true}},
    ["person:sulhasa"] = {title="Sulhasa",kind="Personaje",aliases={"Sulhasa"},body="Sulhasa vive en el Campamento Taurajo y recorre el Camino Dorado. La abundancia de hienas y lagartos tormenteros en sus alrededores recuerda que incluso un paseo cerca de casa puede resultar peligroso en Los Baldíos.",aliasQuestIDs={},en={title="Sulhasa",aliases={"Sulhasa"},body="Sulhasa lives at Camp Taurajo and walks the Gold Road. The hyenas and Stormhide lizards nearby are a reminder that even a stroll close to home can be dangerous in the Barrens.",aliasQuestIDs={}},fr={title="Sulhasa",body="Sulhasa vit à Camp Taurajo et parcourt la Gold Road. Les hyènes et les lézards Stormhide à proximité rappellent que même une promenade près de chez vous peut être dangereuse dans le Barrens."},de={title="Sulhasa",body="Sulhasa wohnt in Camp Taurajo und geht die Goldstraße entlang. Die Hyänen und Stormhide-Eidechsen in der Nähe erinnern daran, dass selbst ein Spaziergang in der Barrens gefährlich sein kann."},pt={title="Sulhasa",body="Sulhasa vive em Camp Taurajo e anda pela Gold Road. As hienas e lagartos Stormhide nas proximidades são um lembrete de que mesmo um passeio perto de casa pode ser perigoso no Barrens."},pl={title="Sulhasa",body="Sulhasa mieszka w Camp Taurajo i spaceruje po Gold Road. Pobliskie hieny i jaszczurki Stormhide przypominają, że nawet przechadzka blisko domu może być niebezpieczna w Barrens."},ru={title="Sulhasa",body="Sulhasa живет в Camp Taurajo и ходит по Золотой дороге. Гиены и ящерицы Stormhide напоминают нам, что даже прогулка рядом с домом может быть опасной в Barrens."},references={["place:camp-taurajo"]=true,["place:the-barrens"]=true}},
    ["person:supervisor-fizsprocket"] = {title="Supervisor Saltatuercas",kind="Personaje",aliases={"Supervisor Saltatuercas","supervisor Saltatuercas"},body="El supervisor Saltatuercas controla operaciones de Ventura y Cía. en Mulgore. Sus notas y planes ofrecen información sobre una explotación que preocupa a las comunidades tauren próximas.",aliasQuestIDs={},en={title="Supervisor Fizsprocket",aliases={"Fizsprocket","Supervisor Fizsprocket"},body="Supervisor Fizsprocket controls Venture Company operations in Mulgore. His notes and plans offer information about an enterprise concerning nearby tauren communities.",aliasQuestIDs={}},fr={title="Supervisor Fizsprocket",body="Supervisor Fizsprocket contrôle les opérations Venture Company dans Mulgore. Ses notes et plans offrent des informations sur une entreprise concernant les communautés tauren voisines."},de={title="Supervisor Fizsprocket",body="Supervisor Fizsprocket kontrolliert den Betrieb von Venture Company in Mulgore. Seine Notizen und Pläne geben Auskunft über ein Unternehmen, das nahe gelegene Tauren-Gemeinschaften betrifft."},pt={title="Supervisor Fizsprocket",body="Supervisor Fizsprocket controla operações Venture Company em Mulgore. Suas notas e planos oferecem informações sobre uma empresa relativa às comunidades de tauren próximas."},pl={title="Supervisor Fizsprocket",body="Supervisor Fizsprocket kontroluje działalność Venture Company w Mulgore. Jego notatki i plany dostarczają informacji o przedsięwzięciu niepokojącym pobliskie społeczności taurenów."},ru={title="Supervisor Fizsprocket",body="Supervisor Fizsprocket контролирует операции Venture Company в Mulgore. Его записки и планы дают информацию о предприятии, касающемся близлежащих общин Таурен."},references={["organization:venture-company"]=true,["place:mulgore"]=true}},
    ["person:swamp-eye-jarl"] = {title="\"Ojolodo\" Jarl",kind="Personaje",aliases={"\"Ojolodo\" Jarl","Jarl"},body="Jarl, conocido como \"Ojolodo\", vive en la Mansión Cienaluz del Marjal Revolcafango. Sus peticiones revelan gustos culinarios peculiares y una afición por ingredientes que otros habitantes del pantano prefieren evitar.",aliasQuestIDs={},en={title="\"Swamp Eye\" Jarl",aliases={"\"Swamp Eye\" Jarl","Jarl"},body="Jarl, known as \"Swamp Eye,\" lives at Swamplight Manor in Dustwallow Marsh. His requests reveal unusual culinary tastes and a liking for ingredients that other marsh residents prefer to avoid.",aliasQuestIDs={}},fr={title="\"Swamp Eye\" Jarl",body="Jarl, connu sous le nom de « Swamp Eye », vit au Swamplight Manor à Dustwallow Marsh. Ses demandes révèlent des goûts culinaires inhabituels et un goût pour les ingrédients que les autres résidents des marais préfèrent éviter."},de={title="\"Swamp Eye\" Jarl",body="Jarl, bekannt als \"Swamp Eye\", lebt auf dem Anwesen Swamplight in Dustwallow Marsh. Seine Wünsche offenbaren ungewöhnliche kulinarische Geschmäcker und eine Vorliebe für Zutaten, die andere Sumpfbewohner lieber vermeiden möchten."},pt={title="\"Swamp Eye\" Jarl",body="Jarl, conhecido como \"Swamp Eye\", vive na Mansão Swamplight em Dustwallow Marsh. Seus pedidos revelam gostos culinários incomuns e um gosto por ingredientes que outros moradores de pântano preferem evitar."},pl={title="\"Swamp Eye\" Jarl",body="Jarl, znany jako „Bagienne Oko”, mieszka w posiadłości Swamplight w Dustwallow Marsh. Jego prośby ukazują niezwykłe upodobania kulinarne i zamiłowanie do składników, których inni mieszkańcy bagien wolą unikać."},ru={title="\"Swamp Eye\" Jarl",body="Jarl, известный как \"Око болота\", живет в поместье Swamplight в Dustwallow Marsh. Его просьбы показывают, что он любит необычный вкус и предпочитает ингредиенты, которых другие жители болота предпочитают избегать."},references={["place:dustwallow-marsh"]=true}},
    ["person:syurna"] = {title="Syurna",kind="Personaje",aliases={"Syurna"},body="Syurna es una instructora de pícaros que limita el acceso a quienes buscan su enseñanza. Rechaza las insistentes atenciones de Jannok y prefiere reservar su tiempo para los asuntos de su oficio.",aliasQuestIDs={},en={title="Syurna",aliases={"Syurna"},body="Syurna is a rogue trainer who limits access to those seeking her instruction. She rejects Jannok’s persistent attentions and prefers to reserve her time for the matters of her calling.",aliasQuestIDs={}},fr={title="Syurna",body="Syurna est un formateur de voleurs qui limite l'accès à ceux qui cherchent son instruction. Elle rejette les attentions persistantes de Jannok et préfère réserver son temps pour les questions de son appel."},de={title="Syurna",body="Syurna ist eine Schurkenlehrerin, die den Zugang zu denjenigen beschränkt, die ihren Unterricht suchen. Sie lehnt Jannoks beharrliche Aufmerksamkeit ab und zieht es vor, ihre Zeit für die Angelegenheiten ihrer Berufung zu reservieren."},pt={title="Syurna",body="Syurna é um instrutor de ladinos que limita o acesso àqueles que procuram sua instrução. Ela rejeita as atenções persistentes de Jannok e prefere reservar seu tempo para os assuntos de seu chamado."},pl={title="Syurna",body="Syurna jest nauczycielką łotrzyków ograniczającą dostęp osobom szukającym nauki. Odrzuca uporczywe zaloty postaci Jannok i woli zachowywać czas na sprawy swojego powołania."},ru={title="Syurna",body="Syurna - это отступническая тренерка, которая ограничивает доступ к тем, кто ищет ее инструкции. Она отвергает упорные обращения внимания Jannok и предпочитает уделять время делам своего призвания."},references={["person:jannok-breezesong"]=true}},
    ["person:tabetha"] = {title="Tabetha",kind="Personaje",aliases={"Tabetha"},body="Tabetha es una maga del Marjal Revolcafango con experiencia en la elaboración de objetos mágicos. Trabaja con materiales y recipientes capaces de contener poder, y presta atención a los riesgos de utilizar componentes demoníacos.",aliasQuestIDs={},en={title="Tabetha",aliases={"Tabetha"},body="Tabetha is a mage in Dustwallow Marsh experienced in making magical objects. She works with materials and vessels capable of containing power and pays attention to the risks of using demonic components.",aliasQuestIDs={}},fr={title="Tabetha",body="Tabetha est un mage en Dustwallow Marsh expérimenté dans la fabrication d'objets magiques. Elle travaille avec des matériaux et des récipients capables de contenir de l’énergie et prête attention aux risques liés à l’utilisation de composants démoniaques."},de={title="Tabetha",body="Tabetha ist eine Magierin in Dustwallow Marsh, die Erfahrung in der Herstellung magischer Objekte hat. Sie arbeitet mit Materialien und Gefäßen, die in der Lage sind, die Macht einzudämmen und achtet auf die Risiken der Verwendung dämonischer Komponenten."},pt={title="Tabetha",body="Tabetha é um mago em Dustwallow Marsh experiente na fabricação de objetos mágicos. Ela trabalha com materiais e embarcações capazes de conter poder e presta atenção aos riscos do uso de componentes demoníacos."},pl={title="Tabetha",body="Tabetha jest maginią w Dustwallow Marsh doświadczoną w tworzeniu magicznych przedmiotów. Pracuje z materiałami i naczyniami zdolnymi pomieścić moc oraz zwraca uwagę na ryzyko używania demonicznych składników."},ru={title="Tabetha",body="Tabetha - магический маг из Dustwallow Marsh, который имеет опыт создания магических предметов. Она работает с материалами и сосудами, способными содержать силу и обращает внимание на риски использования демонических компонентов."},references={["place:dustwallow-marsh"]=true}},
    ["person:taiga-wisemane"] = {title="Taiga Crin Sabia",kind="Personaje",aliases={"Taiga","Taiga Crin Sabia"},body="Taiga Crin Sabia actúa desde la Aldea Cazasombras contra las influencias demoníacas de Desolace. Conoce objetos y herramientas capaces de intervenir en los rituales y portales del Filo Ardiente.",aliasQuestIDs={},en={title="Taiga Wisemane",aliases={"Taiga","Taiga Wisemane"},body="Taiga Wisemane acts from Shadowprey Village against demonic influences in Desolace. She knows objects and tools capable of interfering with Burning Blade rituals and portals.",aliasQuestIDs={}},fr={title="Taiga Wisemane",body="Taiga Wisemane agit à partir de Shadowprey Village contre les influences démoniaques dans Desolace. Elle connaît des objets et des outils capables d'interférer avec les rituels et les portails Burning Blade."},de={title="Taiga Wisemane",body="Taiga Wisemane agiert von Shadowprey Village aus gegen dämonische Einflüsse in Desolace. Sie kennt Objekte und Werkzeuge, die Burning Blade Rituale und Portale stören können."},pt={title="Taiga Wisemane",body="Taiga Wisemane atua a partir de Shadowprey Village contra influências demoníacas em Desolace. Ela conhece objetos e ferramentas capazes de interferir com rituais e portais Burning Blade."},pl={title="Taiga Wisemane",body="Taiga Wisemane działa z Shadowprey Village przeciw demonicznym wpływom w Desolace. Zna przedmioty i narzędzia zdolne zakłócać rytuały oraz portale Burning Blade."},ru={title="Taiga Wisemane",body="Taiga Wisemane действует от Shadowprey Village против демонических влияний в Desolace. Она знает предметы и инструменты, способные вмешиваться в ритуалы Burning Blade и порталы."},references={["organization:burning-blade"]=true,["place:desolace"]=true,["place:shadowprey-village"]=true},questIDs={[5381]=true,[5581]=true}},
    ["person:taijin"] = {title="Tai'jin",kind="Personaje",aliases={"Tai'jin","Tai’jin"},body="Tai'jin enseña en Cerrotajo la historia y las costumbres de su tribu. Mantiene vivas tradiciones que no siempre cuentan con la aprobación de los orcos, incluso dentro de la alianza de los trols con la Horda.",aliasQuestIDs={},en={title="Tai'jin",aliases={"Tai'jin","Tai’jin"},body="Tai'jin teaches her tribe’s history and customs in Razor Hill. She keeps alive traditions that do not always meet with orc approval, even within the trolls’ alliance with the Horde.",aliasQuestIDs={}},fr={title="Tai'jin",body="Tai'jin enseigne l'histoire et les coutumes de sa tribu dans Razor Hill. Elle maintient vivantes des traditions qui ne rencontrent pas toujours l’approbation des orcs, même au sein de l’alliance des trolls avec la Horde."},de={title="Tai'jin",body="Tai'jin lehrt in Razor Hill Geschichte und Bräuche ihres Stammes. Sie hält Traditionen am Leben, die nicht immer auf Zustimmung der Orks stoßen, selbst innerhalb des Bündnisses der Trolle mit den Horde."},pt={title="Tai'jin",body="Tai'jin ensina a história e os costumes de sua tribo em Razor Hill. Ela mantém tradições vivas que nem sempre se encontram com aprovação orc, mesmo dentro da aliança dos trolls com o Horde."},pl={title="Tai'jin",body="Tai'jin uczy historii i zwyczajów swojego plemienia w Razor Hill. Podtrzymuje tradycje nie zawsze spotykające się z aprobatą orków, nawet w sojuszu trolli z frakcją Horde."},ru={title="Tai'jin",body="Tai'jin учит истории и обычаям своего племени на Razor Hill. Она поддерживает традиции, которые не всегда одобряются орками, даже в союзе троллей с Horde."},references={["organization:horde"]=true,["place:razor-hill"]=true}},
    ["person:tairee-farsight"] = {title="Tai'ree Vistadista",kind="Personaje",aliases={"Tai'ree","Tai'ree Vistadista","Tai’ree","Tai’ree Vistadista"},body="Tai'ree Vistadista es la instructora de cazadores de Arboleda Thendal y se encuentra cerca del centro del poblado. Es uno de los contactos para quienes comienzan a aprender las habilidades de esta vocación. Sus enseñanzas forman parte de la preparación de los jóvenes aventureros de la comunidad.",aliasQuestIDs={},en={title="Tai'ree Farsight",aliases={"Tai'ree","Tai'ree Farsight","Tai’ree","Tai’ree Farsight"},body="Tai'ree Farsight is Thendal Grove's hunter trainer and can be found near the center of the village. She is a point of contact for those beginning to learn the skills of that calling. Her instruction is part of the community's preparation of young adventurers.",aliasQuestIDs={}},fr={title="Tai'ree Farsight",body="Tai'ree Farsight est l'entraîneur de chasseur de Thendal Grove et peut être trouvé près du centre du village. Elle est un point de contact pour ceux qui commencent à apprendre les compétences de cet appel. Son instruction fait partie de la préparation de la communauté des jeunes aventuriers."},de={title="Tai'ree Farsight",body="Tai'ree Farsight ist Thendal Groves Jagdtrainerin und befindet sich in der Nähe des Dorfzentrums. Sie ist eine Anlaufstelle für diejenigen, die anfangen, die Fähigkeiten dieser Berufung zu erlernen. Ihr Unterricht ist Teil der Vorbereitung der Gemeinschaft auf junge Abenteurer."},pt={title="Tai'ree Farsight",body="Tai'ree Farsight é o treinador de caçadores do Thendal Grove e pode ser encontrado perto do centro da aldeia. Ela é um ponto de contato para aqueles que começam a aprender as habilidades desse chamado. Sua instrução faz parte da preparação da comunidade de jovens aventureiros."},pl={title="Tai'ree Farsight",body="Tai'ree Farsight jest instruktorką łowców Thendal Grove i przebywa przy centrum wioski. Jest kontaktem dla rozpoczynających naukę umiejętności tej profesji. Jej nauki należą do przygotowania młodych poszukiwaczy przygód przez społeczność."},ru={title="Tai'ree Farsight",body="Tai'ree Farsight - это тренер охотников Thendal Grove и находится недалеко от центра деревни. Она - точка соприкосновения для тех, кто начинает изучать навыки этого призвания. Ее обучение является частью подготовки молодых авантюристов."},references={["place:thendal-grove"]=true}},
    ["person:tajarri"] = {title="Tajarri",kind="Personaje",aliases={"Tajarri"},body="Tajarri es una de las celadoras de confianza de Claro de la Luna. Atiende a los druidas junto al Santuario de Remulos y participa en las pruebas que valoran su destreza física y mental.",aliasQuestIDs={},en={title="Tajarri",aliases={"Tajarri"},body="Tajarri is one of Moonglade’s trusted wardens. She receives druids beside the Shrine of Remulos and takes part in trials testing their physical and mental dexterity.",aliasQuestIDs={}},fr={title="Tajarri",body="Tajarri est l'un des gardiens de confiance de Moonglade. Elle reçoit des druides à côté du Shrine of Remulos et participe à des essais testant leur dextérité physique et mentale."},de={title="Tajarri",body="Tajarri ist eine von Moonglades Vertrauenspersonen. Sie empfängt Druiden neben der Shrine of Remulos und nimmt an Prüfungen teil, die ihre körperliche und geistige Geschicklichkeit testen."},pt={title="Tajarri",body="Tajarri é um dos guardas de confiança da Moonglade. Ela recebe druidas ao lado do Shrine of Remulos e participa de testes testando sua destreza física e mental."},pl={title="Tajarri",body="Tajarri należy do zaufanych strażniczek Moonglade. Przyjmuje druidów przy Shrine of Remulos i uczestniczy w próbach ich sprawności fizycznej oraz umysłowej."},ru={title="Tajarri",body="Tajarri - один из доверенных охранников Moonglade. Она принимает друидов рядом с Shrine of Remulos и участвует в испытаниях, проверяющих их физическую и умственную ловкость."},references={["person:keeper-remulos"]=true,["place:moonglade"]=true,["place:shrine-of-remulos"]=true}},
    ["person:takar-the-seer"] = {title="Takar",kind="Personaje",aliases={"Takar"},body="Takar posee una visión que alcanza lugares lejanos y atraviesa las nieblas del tiempo. Su conocimiento de antiguos vínculos emocionales puede servir a quienes buscan objetos capaces de influir en los demonios.",aliasQuestIDs={},en={title="Takar the Seer",aliases={"Takar","Takar the Seer"},body="Takar possesses sight reaching distant places and piercing the mists of time. His knowledge of ancient emotional bonds can aid those seeking objects capable of influencing demons.",aliasQuestIDs={}},fr={title="Takar the Seer",body="Takar possède la vue atteignant des endroits éloignés et perçant les brumes du temps. Sa connaissance des liens émotionnels anciens peut aider ceux qui cherchent des objets capables d’influencer les démons."},de={title="Takar the Seer",body="Takar besitzt einen Anblick, der weit in die Ferne reicht und die Nebel der Zeit durchdringt. Sein Wissen über uralte emotionale Bindungen kann jenen helfen, die Objekte suchen, die imstande sind Dämonen zu beeinflussen."},pt={title="Takar the Seer",body="Takar possui visão atingindo lugares distantes e perfurando as névoas do tempo. Seu conhecimento de laços emocionais antigos pode ajudar aqueles que procuram objetos capazes de influenciar demônios."},pl={title="Takar the Seer",body="Takar posiada wzrok sięgający odległych miejsc i przenikający mgły czasu. Znajomość pradawnych więzi emocjonalnych pomaga osobom szukającym przedmiotów zdolnych wpływać na demony."},ru={title="Takar the Seer",body="Takar обладает зрением, достигающим дальних мест и проникающим в туман времени. Его знание древних эмоциональных связей может помочь тем, кто ищет предметы, способные влиять на демонов."},references={}},
    ["person:takata-steelblade"] = {title="Takata Hoja de Acero",kind="Personaje",aliases={"Takata","Takata Hoja de Acero"},body="Takata Hoja de Acero es un espadachín que actúa en Desolace. Su sentido del honor y su autoridad lo relacionan con las respuestas de la Horda a los peligros demoníacos de la región.",aliasQuestIDs={},en={title="Takata Steelblade",aliases={"Takata","Takata Steelblade"},body="Takata Steelblade is a swordsman operating in Desolace. His sense of honor and authority connect him with the Horde’s responses to the region’s demonic dangers.",aliasQuestIDs={}},fr={title="Takata Steelblade",body="Takata Steelblade est un épéiste opérant en Desolace. Son sens de l'honneur et de l'autorité le relient aux réponses du Horde aux dangers démoniaques de la région."},de={title="Takata Steelblade",body="Takata Steelblade ist Schwertkämpfer in Desolace. Sein Ehrgefühl und seine Autorität verbinden ihn mit den Reaktionen der Horde auf die dämonischen Gefahren der Region."},pt={title="Takata Steelblade",body="Takata Steelblade é um espadachim que opera em Desolace. Seu senso de honra e autoridade o conecta com as respostas do Horde aos perigos demoníacos da região."},pl={title="Takata Steelblade",body="Takata Steelblade jest szermierzem działającym w Desolace. Poczucie honoru i autorytet wiążą go z odpowiedzią frakcji Horde na demoniczne zagrożenia regionu."},ru={title="Takata Steelblade",body="Takata Steelblade - это фехтовальщик, работающий в Desolace. Его чувство чести и власти связывают его с реакцией Horde на демонические опасности региона."},references={["organization:horde"]=true,["place:desolace"]=true}},
    ["person:talaanis-shadowsong"] = {title="Talaanis Cantosombrío",kind="Personaje",aliases={"Cantosombrío","Talaanis","Talaanis Cantosombrío","Talanaanis Cantosombrío","gran ancestro Cantosombrío","gran anciano Cantosombrío"},body="Talaanis Cantosombrío es el gran ancestro de Isla Zephras y reside en Valanaar. Es una figura muy querida por su pueblo en una época de dificultades. Su cargo lo vincula con las decisiones que afectan a la protección y el porvenir de la comunidad.",aliasQuestIDs={["Cantosombrío"]={[92644]=true,[92881]=true,[93836]=true,[93948]=true,[94369]=true},["Talaanis"]={[92644]=true,[92881]=true,[93836]=true,[93948]=true,[94369]=true}},en={title="Talaanis Shadowsong",aliases={"High Elder Shadowsong","Shadowsong","Talaanis","Talaanis Shadowsong","Talanaanis Shadowsong"},body="Talaanis Shadowsong is the High Elder of Zephras Isle and lives in Valanaar. He is well loved by his people during a difficult period. His position connects him with decisions affecting the community’s protection and future.",aliasQuestIDs={["Shadowsong"]={[92644]=true,[92881]=true,[93836]=true,[93948]=true,[94369]=true},["Talaanis"]={[92644]=true,[92881]=true,[93836]=true,[93948]=true,[94369]=true}}},fr={title="Talaanis Shadowsong",body="Talaanis Shadowsong est le High Elder de Zephras Isle et vit dans Valanaar. Il est aimé par son peuple pendant une période difficile. Sa position le relie à des décisions affectant la protection et l’avenir de la communauté."},de={title="Talaanis Shadowsong",body="Talaanis Shadowsong ist der High Elder von Zephras Isle und lebt in Valanaar. Er wird von seinem Volk in einer schwierigen Zeit sehr geliebt. Seine Position verbindet ihn mit Entscheidungen, die den Schutz und die Zukunft der Gemeinschaft betreffen."},pt={title="Talaanis Shadowsong",body="Talaanis Shadowsong é o High Elder de Zephras Isle e vive em Valanaar. Ele é bem amado por seu povo durante um período difícil. Sua posição o conecta com decisões que afetam a proteção e o futuro da comunidade."},pl={title="Talaanis Shadowsong",body="Talaanis Shadowsong jest High Elder Zephras Isle i mieszka w Valanaar. Lud darzy go wielką sympatią w trudnym okresie. Jego pozycja łączy go z decyzjami dotyczącymi ochrony i przyszłości społeczności."},ru={title="Talaanis Shadowsong",body="Talaanis Shadowsong - это High Elder из Zephras Isle и живет в Valanaar. Его народ очень любит в трудный период. Его должность связывает его с решениями, влияющими на защиту и будущее сообщества."},references={["place:valanaar"]=true,["place:zephras"]=true}},
    ["person:tallonkai-swiftroot"] = {title="Tallonkai Cruzarraíz",kind="Personaje",aliases={"Tallonkai","Tallonkai Cruzarraíz"},body="Tallonkai se preocupa por las amenazas que se acercan a las comunidades de Teldrassil. La presencia de sátiros y sus seguidores cerca de Dolanaar lo obliga a actuar con discreción para proteger su hogar.",aliasQuestIDs={},en={title="Tallonkai Swiftroot",aliases={"Tallonkai","Tallonkai Swiftroot"},body="Tallonkai is concerned with threats approaching Teldrassil’s communities. Satyrs and their followers near Dolanaar compel him to act discreetly to protect his home.",aliasQuestIDs={}},fr={title="Tallonkai Swiftroot",body="Tallonkai est préoccupé par les menaces qui approchent les communautés de Teldrassil. Satyrs et leurs partisans près de Dolanaar l'obligent à agir discrètement pour protéger sa maison."},de={title="Tallonkai Swiftroot",body="Tallonkai beschäftigt sich mit Bedrohungen, die auf Teldrassil 'Gemeinden zukommen. Satyrs und ihre Anhänger in der Nähe von Dolanaar zwingen ihn, diskret zu handeln, um sein Haus zu schützen."},pt={title="Tallonkai Swiftroot",body="Tallonkai está preocupado com as ameaças que se aproximam das comunidades de Teldrassil. Satyrs e seus seguidores perto de Dolanaar obrigam-no a agir discretamente para proteger sua casa."},pl={title="Tallonkai Swiftroot",body="Tallonkai troszczy się o zagrożenia zbliżające się do społeczności Teldrassil. Satyrowie i ich zwolennicy koło Dolanaar zmuszają go do dyskretnego działania dla ochrony domu."},ru={title="Tallonkai Swiftroot",body="Tallonkai обеспокоена угрозами, приближающимися к сообществам Teldrassil s. Satyrs и их последователи возле Dolanaar заставляют его действовать сдержанно, чтобы защитить свой дом."},references={["place:dolanaar"]=true,["place:teldrassil"]=true}},
    ["person:talo-thornhoof"] = {title="Talo Pezuñahendida",kind="Personaje",aliases={"Talo","Talo Pezuñahendida"},body="Talo Pezuñahendida es un cazador del Campamento Mojache. Estudia los puntos fuertes de sus adversarios y las alteraciones que la energía vil provoca en las criaturas de Frondavil.",aliasQuestIDs={},en={title="Talo Thornhoof",aliases={"Talo","Talo Thornhoof"},body="Talo Thornhoof is a hunter in Camp Mojache. He studies his opponents’ strengths and the changes fel energy causes in Felwood’s creatures.",aliasQuestIDs={}},fr={title="Talo Thornhoof",body="Talo Thornhoof est un chasseur dans Camp Mojache. Il étudie les forces de ses adversaires et les changements causés par l’énergie chez les créatures de Felwood."},de={title="Talo Thornhoof",body="Talo Thornhoof ist in Camp Mojache ein Jäger. Er untersucht die Stärken seiner Gegner und die Veränderungen der Energie, die Felwood \"Lebewirkt."},pt={title="Talo Thornhoof",body="Talo Thornhoof é um caçador em Camp Mojache. Ele estuda os pontos fortes de seus oponentes e as mudanças que a energia fel causa nas criaturas de Felwood."},pl={title="Talo Thornhoof",body="Talo Thornhoof jest łowcą w Camp Mojache. Bada mocne strony przeciwników i zmiany wywoływane przez energię spaczenia u stworzeń Felwood."},ru={title="Talo Thornhoof",body="Talo Thornhoof — охотник из Camp Mojache. Он изучает сильные стороны противников и изменения, которые энергия скверны вызывает у существ Felwood."},references={["place:camp-mojache"]=true,["place:felwood"]=true}},
    ["person:tammra-windfield"] = {title="Tammra Campo de Viento",kind="Personaje",aliases={"Tammra","Tammra Campo de Viento"},body="Tammra Campo de Viento vive en el Refugio Roca del Sol y es tía de Kaya. Sus preocupaciones familiares reflejan el impacto que los ataques a los poblados tienen sobre las comunidades de Sierra Espolón.",aliasQuestIDs={},en={title="Tammra Windfield",aliases={"Tammra","Tammra Windfield"},body="Tammra Windfield lives in Sun Rock Retreat and is Kaya’s aunt. Her family concerns reflect the impact that attacks on villages have on Stonetalon’s communities.",aliasQuestIDs={}},fr={title="Tammra Windfield",body="Tammra Windfield vit à Sun Rock Retreat et est la tante de Kaya. Ses préoccupations familiales reflètent l’impact des attaques sur les villages sur les communautés de Stonetalon."},de={title="Tammra Windfield",body="Tammra Windfield lebt in Sun Rock Retreat und ist Kayas Tante. Ihre familiären Sorgen spiegeln die Auswirkungen wider, die Angriffe auf Dörfer auf Stonetalons Gemeinschaften haben."},pt={title="Tammra Windfield",body="Tammra Windfield vive em Sun Rock Retreat e é tia de Kaya. Suas preocupações familiares refletem o impacto que os ataques às aldeias têm sobre as comunidades da Stonetalon."},pl={title="Tammra Windfield",body="Tammra Windfield mieszka w Sun Rock Retreat i jest ciotką postaci Kaya. Jej rodzinne troski odzwierciedlają wpływ ataków na wioski na społeczności Stonetalon."},ru={title="Tammra Windfield",body="Tammra Windfield живёт в Sun Rock Retreat и приходится тётей Kaya. Заботы её семьи отражают то, как нападения на деревни сказываются на общинах Stonetalon."},references={["person:kaya-flathoof"]=true,["place:stonetalon-mountains"]=true,["place:sun-rock-retreat"]=true}},
    ["person:tarindrella"] = {title="Tarindrella",kind="Personaje",aliases={"Tarindrella"},body="Tarindrella es una dríade protectora de los bosques de Kalimdor. Su regreso a Cañada Umbría preocupa a quienes escuchan a los espíritus, pues su presencia suele estar vinculada a alteraciones del equilibrio natural.",aliasQuestIDs={},en={title="Tarindrella",aliases={"Tarindrella"},body="Tarindrella is a dryad protecting Kalimdor’s forests. Her return to Shadowglen concerns those listening to the spirits, as her presence is associated with disturbances of the natural balance.",aliasQuestIDs={}},fr={title="Tarindrella",body="Tarindrella est une dryade protégeant les forêts de Kalimdor. Son retour à Shadowglen concerne ceux qui écoutent les esprits, car sa présence est associée à des perturbations de l’équilibre naturel."},de={title="Tarindrella",body="Tarindrella ist eine Trockenfliege, die Kalimdors Wälder schützt. Ihre Rückkehr zu Shadowglen betrifft jene, die den Geistern zuhören, da ihre Anwesenheit mit Störungen des natürlichen Gleichgewichts verbunden ist."},pt={title="Tarindrella",body="Tarindrella é um dryad que protege as florestas de Kalimdor. Seu retorno ao Shadowglen diz respeito àqueles que ouvem os espíritos, já que sua presença está associada a distúrbios do equilíbrio natural."},pl={title="Tarindrella",body="Tarindrella jest driadą chroniącą lasy kontynentu Kalimdor. Powrót do Shadowglen niepokoi osoby słuchające duchów, gdyż jej obecność wiąże się z zakłóceniami naturalnej równowagi."},ru={title="Tarindrella",body="Tarindrella - это дриад, защищающий леса Kalimdor s. Ее возвращение в Shadowglen касается тех, кто слушает духов, так как ее присутствие связано с нарушениями естественного равновесия."},references={["place:kalimdor"]=true,["place:shadowglen"]=true}},
    ["person:taronn-redfeather"] = {title="Taronn Plumarroja",kind="Personaje",aliases={"Taronn","Taronn Plumarroja"},body="Taronn Plumarroja investiga las secuelas de la guerra en Frondavil. Los infernales, los cráteres y las aguas contaminadas de la Cañada Gran Cicatriz son parte de los peligros que intenta comprender.",aliasQuestIDs={},en={title="Taronn Redfeather",aliases={"Taronn","Taronn Redfeather"},body="Taronn Redfeather investigates the war’s aftermath in Felwood. Infernals, craters and tainted waters in Shatter Scar Vale are among the dangers he seeks to understand.",aliasQuestIDs={}},fr={title="Taronn Redfeather",body="Taronn Redfeather enquête sur les conséquences de la guerre dans Felwood. Infernals, les cratères et les eaux contaminées de Shatter Scar Vale sont parmi les dangers qu'il cherche à comprendre."},de={title="Taronn Redfeather",body="Taronn Redfeather untersucht in Felwood die Nachwirkungen des Krieges. Infernals, Krater und verseuchte Gewässer im Shatter Scar Vale gehören zu den Gefahren, die er zu verstehen sucht."},pt={title="Taronn Redfeather",body="Taronn Redfeather investiga as consequências da guerra no Felwood. Infernals, crateras e águas contaminadas em Shatter Scar Vale estão entre os perigos que ele procura entender."},pl={title="Taronn Redfeather",body="Taronn Redfeather bada następstwa wojny w Felwood. Infernale, kratery i skażone wody Shatter Scar Vale należą do niebezpieczeństw, które próbuje zrozumieć."},ru={title="Taronn Redfeather",body="Taronn Redfeather расследует последствия войны в Felwood. Infernals, кратеры и загрязненные воды в долине Шаттер Скар - это одни из опасностей, которые он пытается понять."},references={["place:felwood"]=true}},
    ["person:tatternack-steelforge"] = {title="Jironack Forjacero",kind="Personaje",aliases={"Jironack Forjacero","Tatternack"},body="Tatternack estudia las armas de los jabaespines Crines de Acero. Su interés por las nuevas técnicas de sus adversarios muestra que la forja también progresa observando herramientas fabricadas fuera de la Horda.",aliasQuestIDs={},en={title="Tatternack Steelforge",aliases={"Tatternack","Tatternack Steelforge"},body="Tatternack studies the weapons of the Razormane quilboar. His interest in his adversaries’ new techniques shows that smithing can also advance by observing tools made outside the Horde.",aliasQuestIDs={}},fr={title="Tatternack Steelforge",body="Tatternack étudie les armes du quilboar Razormane. Son intérêt pour les nouvelles techniques de ses adversaires montre que la forge peut également progresser en observant des outils fabriqués en dehors de la Horde."},de={title="Tatternack Steelforge",body="Tatternack studiert die Waffen des Razormane-Steppschweins. Sein Interesse an den neuen Techniken seiner Gegner zeigt, dass das Schmieden Fortschritt auch durch Beobachten von Werkzeugen außerhalb des Horde bewirken kann."},pt={title="Tatternack Steelforge",body="Tatternack estuda as armas do quilboar Razormane. Seu interesse nas novas técnicas de seus adversários mostra que a ferraria também pode avançar observando ferramentas feitas fora do Horde."},pl={title="Tatternack Steelforge",body="Tatternack bada broń kolcozwierzy Razormane. Zainteresowanie nowymi technikami przeciwników pokazuje, że kowalstwo może rozwijać się także dzięki obserwowaniu narzędzi wykonanych poza frakcją Horde."},ru={title="Tatternack Steelforge",body="Tatternack изучает оружие свинобразов Razormane. Его интерес к новым приёмам противников показывает, что кузнец может совершенствовать ремесло, изучая изделия за пределами Horde."},references={["organization:horde"]=true,["organization:razormane"]=true}},
    ["person:tazan"] = {title="Tazan",kind="Personaje",aliases={"Tazan"},body="Tazan es una figura de Orgrimmar relacionada con asuntos que interesan a los Mano Destrozada. La protección de sus documentos y su relación con Gamon lo sitúan en el mundo de los secretos y las investigaciones discretas.",aliasQuestIDs={},en={title="Tazan",aliases={"Tazan"},body="Tazan is an Orgrimmar figure involved in affairs of interest to the Shattered Hand. The protection of his papers and his association with Gamon place him in a world of secrets and discreet investigations.",aliasQuestIDs={}},fr={title="Tazan",body="Tazan est une figure Orgrimmar impliquée dans des affaires d'intérêt pour le Shattered Hand. La protection de ses papiers et son association avec Gamon le placent dans un monde de secrets et d’enquêtes discrètes."},de={title="Tazan",body="Tazan ist eine Orgrimmar-Figur, die in Angelegenheiten verwickelt ist, die Shattered Hand interessieren. Der Schutz seiner Papiere und seine Verbindung zu Gamon versetzen ihn in eine Welt der Geheimnisse und diskreter Ermittlungen."},pt={title="Tazan",body="Tazan é uma figura Orgrimmar envolvida em assuntos de interesse para o Shattered Hand. A proteção de seus documentos e sua associação com o Gamon o colocam em um mundo de segredos e investigações discretas."},pl={title="Tazan",body="Tazan jest postacią z Orgrimmar uwikłaną w sprawy interesujące Shattered Hand. Ochrona dokumentów i związek z postacią Gamon umieszczają go w świecie tajemnic oraz dyskretnych dochodzeń."},ru={title="Tazan",body="Tazan - фигура Orgrimmar, участвующая в делах, представляющих интерес для Shattered Hand. Защита его документов и его связь с Gamon помещает его в мир секретов и дискретных расследований."},references={["organization:shattered-hand"]=true,["place:orgrimmar"]=true}},
    ["person:telf-joolam"] = {title="Telf Joolam",kind="Personaje",aliases={"Telf","Telf Joolam"},body="Telf Joolam es un guía de chamanes relacionado con el elemento del fuego. La sapta que proporciona permite acercarse a una experiencia espiritual que exige preparación y respeto.",aliasQuestIDs={},en={title="Telf Joolam",aliases={"Telf","Telf Joolam"},body="Telf Joolam is a shamanic guide associated with the element of fire. The sapta he provides offers access to a spiritual experience requiring preparation and respect.",aliasQuestIDs={}},fr={title="Telf Joolam",body="Telf Joolam est un guide chamanique associé à l'élément de feu. La sapta qu’il fournit offre l’accès à une expérience spirituelle nécessitant préparation et respect."},de={title="Telf Joolam",body="Telf Joolam ist ein schamanischer Führer, der mit dem Element Feuer in Verbindung gebracht wird. Das von ihm angebotene sapta bietet Zugang zu einer spirituellen Erfahrung, die Vorbereitung und Respekt erfordert."},pt={title="Telf Joolam",body="Telf Joolam é um guia xamânico associado ao elemento fogo. O sapta ele oferece acesso a uma experiência espiritual que requer preparação e respeito."},pl={title="Telf Joolam",body="Telf Joolam jest szamańskim przewodnikiem związanym z żywiołem ognia. Dostarczana przez niego sapta daje dostęp do duchowego doświadczenia wymagającego przygotowania i szacunku."},ru={title="Telf Joolam",body="Telf Joolam - шаманский гид, связанный с элементом огня. sapta, который он предоставляет, дает доступ к духовному опыту, требующему подготовки и уважения."},references={["object:sapta"]=true}},
    ["person:telonis"] = {title="Telonis",kind="Personaje",aliases={"Telonis"},body="Telonis enseña peletería en Darnassus y fue maestro de Pratt. Respeta la dedicación de los artesanos de otros pueblos y reconoce el dominio del cuero salvaje como un logro que merece tratar al aprendiz como a un igual.",aliasQuestIDs={},en={title="Telonis",aliases={"Telonis"},body="Telonis teaches leatherworking in Darnassus and trained Pratt. He respects the dedication of craftspeople from other peoples and recognizes mastery of wild leather as an achievement deserving treatment as an equal.",aliasQuestIDs={}},fr={title="Telonis",body="Telonis enseigne le travail du cuir dans Darnassus et formé Pratt. Il respecte le dévouement des artisans des autres peuples et reconnaît la maîtrise du cuir sauvage comme une réalisation méritant un traitement égal."},de={title="Telonis",body="Telonis unterrichtet Lederverarbeitung bei Darnassus und bildet Pratt aus. Er respektiert die Hingabe von Handwerkern anderer Völker und erkennt die Beherrschung des Wildleders als gleichberechtigte Errungenschaft an."},pt={title="Telonis",body="Telonis ensina couro trabalhando em Darnassus e treinado Pratt. Ele respeita a dedicação de artesãos de outros povos e reconhece o domínio do couro selvagem como uma conquista que merece tratamento igual."},pl={title="Telonis",body="Telonis uczy kaletnictwa w Darnassus i szkolił postać Pratt. Szanuje poświęcenie rzemieślników innych ludów i uznaje opanowanie dzikiej skóry za osiągnięcie zasługujące na równe traktowanie."},ru={title="Telonis",body="Telonis преподает кожевенную работу в Darnassus и обучает Pratt. Он уважает преданность мастеров из других народов и признает, что мастерство в дикой коже является достижением, заслуживающим равного отношения."},references={["person:pratt-mcgrubben"]=true,["place:darnassus"]=true}},
    ["person:tenaron-stormgrip"] = {title="Tenaron Tormentagarre",kind="Personaje",aliases={"Tenaron","Tenaron Tormentagarre"},body="Tenaron Tormentagarre atiende a los nuevos aventureros desde Aldrassil, en Cañada Umbría. Su presencia forma parte de la orientación que reciben quienes comienzan a servir a la comunidad de Teldrassil.",aliasQuestIDs={},en={title="Tenaron Stormgrip",aliases={"Tenaron","Tenaron Stormgrip"},body="Tenaron Stormgrip receives new adventurers in Aldrassil, in Shadowglen. His presence is part of the guidance offered to those beginning their service to Teldrassil’s community.",aliasQuestIDs={}},fr={title="Tenaron Stormgrip",body="Tenaron Stormgrip reçoit de nouveaux aventuriers en Aldrassil, en Shadowglen. Sa présence fait partie des conseils offerts à ceux qui commencent leur service à la communauté de Teldrassil."},de={title="Tenaron Stormgrip",body="Tenaron Stormgrip empfängt neue Abenteurer in Aldrassil in Shadowglen. Seine Anwesenheit gehört zu der Unterstützung, die jenen zuteilwird, die ihren Dienst für die Gemeinschaft von Teldrassil beginnen."},pt={title="Tenaron Stormgrip",body="Tenaron Stormgrip recebe novos aventureiros em Aldrassil, em Shadowglen. Sua presença faz parte da orientação oferecida àqueles que iniciam seu serviço à comunidade do Teldrassil."},pl={title="Tenaron Stormgrip",body="Tenaron Stormgrip przyjmuje nowych poszukiwaczy przygód w Aldrassil, w Shadowglen. Jego obecność stanowi część wsparcia oferowanego osobom rozpoczynającym służbę społeczności Teldrassil."},ru={title="Tenaron Stormgrip",body="Tenaron Stormgrip принимает новых приключенцев в Aldrassil, в Shadowglen. Его присутствие является частью руководства, предлагаемого тем, кто начинает свою службу в сообществе Teldrassil."},references={["place:aldrassil"]=true,["place:shadowglen"]=true,["place:teldrassil"]=true}},
    ["person:terenthis"] = {title="Terenthis",kind="Personaje",aliases={"Terenthis"},body="Terenthis participa en la protección de los habitantes de Auberdine. Su trabajo lo relaciona con la seguridad de los viajeros y con las amenazas que se ocultan en las cuevas y bosques de Costa Oscura.",aliasQuestIDs={},en={title="Terenthis",aliases={"Terenthis"},body="Terenthis helps protect Auberdine’s inhabitants. His work concerns the safety of travelers and the threats hidden in Darkshore’s caves and forests.",aliasQuestIDs={}},fr={title="Terenthis",body="Terenthis aide à protéger les habitants de Auberdine. Son travail concerne la sécurité des voyageurs et les menaces cachées dans les grottes et les forêts de Darkshore."},de={title="Terenthis",body="Terenthis hilft, die Bewohner von Auberdine zu beschützen. Seine Arbeit betrifft die Sicherheit der Reisenden und die Bedrohungen, die in den Höhlen und Wäldern von Darkshore versteckt sind."},pt={title="Terenthis",body="Terenthis ajuda a proteger os habitantes de Auberdine. Seu trabalho diz respeito à segurança dos viajantes e às ameaças escondidas nas cavernas e florestas do Darkshore."},pl={title="Terenthis",body="Terenthis pomaga chronić mieszkańców Auberdine. Jego praca dotyczy bezpieczeństwa podróżnych oraz zagrożeń ukrytych w jaskiniach i lasach Darkshore."},ru={title="Terenthis",body="Terenthis помогает защитить жителей Auberdine s. Его работа касается безопасности путешественников и угроз, скрытых в пещерах и лесах Darkshore."},references={["place:auberdine"]=true,["place:darkshore"]=true}},
    ["person:teronis"] = {title="Teronis",kind="Personaje",aliases={"Teronis"},body="Teronis es un investigador relacionado con las labores de Raene Correlobo en Vallefresno. Sus escritos y observaciones se centran en objetos cuyo poder puede ayudar a comprender los problemas del bosque.",aliasQuestIDs={},en={title="Teronis",aliases={"Teronis"},body="Teronis is an investigator associated with Raene Wolfrunner’s work in Ashenvale. His writings and observations concern objects whose power may help explain the forest’s problems.",aliasQuestIDs={}},fr={title="Teronis",body="Teronis est un chercheur associé au travail de Raene Wolfrunner dans Ashenvale. Ses écrits et observations concernent des objets dont la puissance peut aider à expliquer les problèmes de la forêt."},de={title="Teronis",body="Teronis ist Ermittler im Zusammenhang mit der Arbeit von Raene Wolfrunner in Ashenvale. Seine Schriften und Beobachtungen betreffen Objekte, deren Macht dazu beitragen könnte, die Probleme des Waldes Waldes Landes zu erklären."},pt={title="Teronis",body="Teronis é um investigador associado ao trabalho de Raene Wolfrunner no Ashenvale. Seus escritos e observações dizem respeito a objetos cujo poder pode ajudar a explicar os problemas da floresta."},pl={title="Teronis",body="Teronis jest badaczem związanym z pracą postaci Raene Wolfrunner w Ashenvale. Jego pisma i obserwacje dotyczą przedmiotów, których moc może pomóc wyjaśnić problemy lasu."},ru={title="Teronis",body="Teronis - исследователь, связанный с работой Raene Wolfrunner  в Ashenvale. Его труды и наблюдения касаются объектов, чья сила может помочь объяснить проблемы леса."},references={["person:raene-wolfrunner"]=true,["place:ashenvale"]=true}},
    ["person:thalia-amberhide"] = {title="Thalia Ocultaámbar",kind="Personaje",aliases={"Thalia","Thalia Ocultaámbar"},body="Thalia Ocultaámbar vive en el Poblado Viento Libre de Las Mil Agujas. Sus vínculos personales con quienes recorren la región muestran la preocupación cotidiana de una comunidad expuesta a la violencia.",aliasQuestIDs={},en={title="Thalia Amberhide",aliases={"Thalia","Thalia Amberhide"},body="Thalia Amberhide lives in Freewind Post in Thousand Needles. Her personal ties to those traveling the region reflect the daily concerns of a community exposed to violence.",aliasQuestIDs={}},fr={title="Thalia Amberhide",body="Thalia Amberhide vit dans Freewind Post dans Thousand Needles. Ses liens personnels avec ceux qui voyagent dans la région reflètent les préoccupations quotidiennes d’une communauté exposée à la violence."},de={title="Thalia Amberhide",body="Thalia Amberhide lebt in Freewind Post in Thousand Needles. Ihre persönlichen Verbindungen zu den Reisenden in der Region spiegeln die täglichen Sorgen einer Gemeinschaft wider, die Gewalt ausgesetzt ist."},pt={title="Thalia Amberhide",body="Thalia Amberhide vive em Freewind Post no Thousand Needles. Seus laços pessoais com aqueles que viajam pela região refletem as preocupações diárias de uma comunidade exposta à violência."},pl={title="Thalia Amberhide",body="Thalia Amberhide mieszka w Freewind Post w Thousand Needles. Osobiste więzi z podróżującymi po regionie odzwierciedlają codzienne troski społeczności narażonej na przemoc."},ru={title="Thalia Amberhide",body="Thalia Amberhide живёт в Freewind Post на территории Thousand Needles. Ее личные связи с теми, кто путешествует по региону, отражают ежедневные заботы общины, подверженной насилию."},references={["place:freewind-post"]=true,["place:thousand-needles"]=true}},
    ["person:tharg"] = {title="Tharg",kind="Personaje",aliases={"Tharg"},body="Tharg es un ogro del Poblado Murohelecho que añora su hogar en las Ruinas Quebrantarrocas. La presencia de dragones negros alimenta su deseo de combatir para recuperar la tierra de su comunidad.",aliasQuestIDs={},en={title="Tharg",aliases={"Tharg"},body="Tharg is an ogre in Brackenwall Village who longs for his home in Stonemaul Ruins. The presence of black dragons fuels his wish to fight and reclaim his community’s land.",aliasQuestIDs={}},fr={title="Tharg",body="Tharg est un ogre dans Brackenwall Village qui aspire à sa maison dans les ruines de Stonemaul. La présence de dragons noirs alimente son désir de se battre et de récupérer les terres de sa communauté."},de={title="Tharg",body="Tharg ist ein Menschenfresser in Brackenwall Village, der sich nach seiner Heimat in Stonemaul Ruinen sehnt. Die Anwesenheit schwarzer Drachen heizt seinen Wunsch an, zu kämpfen und das Land seiner Gemeinde zurückzuerobern."},pt={title="Tharg",body="Tharg é um ogro em Brackenwall Village que anseia por sua casa nas Ruínas de Stonemaul. A presença de dragões negros alimenta seu desejo de lutar e recuperar a terra de sua comunidade."},pl={title="Tharg",body="Tharg jest ogrem w Brackenwall Village tęskniącym za domem w ruinach Stonemaul. Obecność czarnych smoków podsyca chęć walki i odzyskania ziemi jego społeczności."},ru={title="Tharg",body="Tharg - это Огр в Brackenwall Village, который жаждет своего дома в Stonemaul Ruins. Присутствие черных драконов подпитывает его желание сражаться и отвоевать землю своей общины."},references={["place:brackenwall-village"]=true}},
    ["person:tharnariun-treetender"] = {title="Tharnariun Espinarbolado",kind="Personaje",aliases={"Tharnariun","Tharnariun Espinarbolado"},body="Tharnariun Espinarbolado estudia la enfermedad de los animales de Costa Oscura. Prefiere examinar ejemplares vivos para comprender el mal y buscar una cura que permita preservar la vida del bosque.",aliasQuestIDs={},en={title="Tharnariun Treetender",aliases={"Tharnariun","Tharnariun Treetender"},body="Tharnariun Treetender studies the sickness affecting Darkshore’s animals. He seeks to examine living specimens to understand the illness and find a cure preserving the forest’s life.",aliasQuestIDs={}},fr={title="Tharnariun Treetender",body="Tharnariun Treetender étudie la maladie affectant les animaux de Darkshore. Il cherche à examiner des spécimens vivants pour comprendre la maladie et trouver un remède préservant la vie de la forêt."},de={title="Tharnariun Treetender",body="Tharnariun Treetender untersucht die Krankheit von Darkshore 'Tieren. Er versucht, lebende Exemplare zu untersuchen, um die Krankheit zu verstehen und ein Heilmittel zu finden, das das das das Leben des Waldes Waldes erhalten."},pt={title="Tharnariun Treetender",body="Tharnariun Treetender estuda a doença que afeta os animais de Darkshore. Ele procura examinar espécimes vivos para entender a doença e encontrar uma cura preservando a vida da floresta."},pl={title="Tharnariun Treetender",body="Tharnariun Treetender bada chorobę zwierząt Darkshore. Chce badać żywe okazy, aby zrozumieć chorobę i znaleźć lekarstwo zachowujące życie lasu."},ru={title="Tharnariun Treetender",body="Tharnariun Treetender изучает болезнь, поражающую животных Darkshore s. Он пытается изучить живые образцы, чтобы понять болезнь и найти лекарство, сохраняющее жизнь леса."},references={["place:darkshore"]=true}},
    ["person:therylune"] = {title="Therylune",kind="Personaje",aliases={"Therylune"},body="Therylune es una dríade relacionada con el Santuario de Aessina en Vallefresno. Los peligros de La Espada del Maestro muestran lo difícil que puede resultar moverse entre los santuarios del bosque.",aliasQuestIDs={},en={title="Therylune",aliases={"Therylune"},body="Therylune is a dryad associated with the Shrine of Aessina in Ashenvale. The dangers of the Master’s Glaive show how difficult travel between the forest’s sanctuaries can become.",aliasQuestIDs={}},fr={title="Therylune",body="Therylune est une dryade associée au sanctuaire de Aessina dans Ashenvale. Les dangers de la Master’s Glaive montrent à quel point les déplacements entre les sanctuaires de la forêt peuvent devenir difficiles."},de={title="Therylune",body="Therylune ist eine Trockenfliege, die mit dem Schrein des Aessina in Ashenvale in Verbindung gebracht wird. Die Gefahren des Master’s Glaive zeigen, wie schwierig das Reisen zwischen den Schutzgebieten des Waldes Waldes Regenwaldes werden kann."},pt={title="Therylune",body="Therylune é uma dryad associada ao Santuário de Aessina em Ashenvale. Os perigos do Master’s Glaive mostram como as viagens difíceis entre os santuários da floresta podem se tornar."},pl={title="Therylune",body="Therylune jest driadą związaną ze świątynią Aessina w Ashenvale. Niebezpieczeństwa miejsca Master’s Glaive pokazują, jak trudne mogą być podróże między leśnymi sanktuariami."},ru={title="Therylune",body="Therylune - это дряд, связанный со Святыней Aessina в Ashenvale. Опасность Master’s Glaive показывает, насколько трудно путешествовать между заповедниками леса."},references={["place:ashenvale"]=true,["place:masters-glaive"]=true}},
    ["person:therysil"] = {title="Therysil",kind="Personaje",aliases={"Therysil"},body="Therysil vive en el Santuario de Aessina de Vallefresno y es hermana de Therylune. Su presencia vincula los lugares sagrados del bosque con las relaciones personales de quienes los protegen.",aliasQuestIDs={},en={title="Therysil",aliases={"Therysil"},body="Therysil lives at the Shrine of Aessina in Ashenvale and is Therylune’s sister. Her presence connects the forest’s sacred places with the personal relationships of those protecting them.",aliasQuestIDs={}},fr={title="Therysil",body="Therysil vit au sanctuaire de Aessina à Ashenvale et est la sœur de Therylune. Sa présence relie les lieux sacrés de la forêt aux relations personnelles de ceux qui les protègent."},de={title="Therysil",body="Therysil lebt im Schrein von Aessina in Ashenvale und ist Therylunes Schwester. Ihre Gegenwart verbindet die heiligen Stätten des Waldes mit den persönlichen Beziehungen derer, die sie beschützen."},pt={title="Therysil",body="Therysil vive no Santuário de Aessina em Ashenvale e é irmã do Therylune. Sua presença conecta os lugares sagrados da floresta com as relações pessoais daqueles que os protegem."},pl={title="Therysil",body="Therysil mieszka przy świątyni Aessina w Ashenvale i jest siostrą postaci Therylune. Jej obecność łączy święte miejsca lasu z osobistymi relacjami ich obrońców."},ru={title="Therysil",body="Therysil живет в Храме Aessina в Ashenvale и является сестрой Therylune. Ее присутствие связывает священные места леса с личными отношениями тех, кто их защищает."},references={["person:therylune"]=true,["place:ashenvale"]=true}},
    ["person:therzok"] = {title="Therzok",kind="Personaje",aliases={"Therzok"},body="Therzok actúa en Orgrimmar y presta atención a quienes combinan destreza en combate con discreción. Sus contactos le permiten buscar posibles colaboradores para la Mano sin recurrir a invitaciones públicas.",aliasQuestIDs={},en={title="Therzok",aliases={"Therzok"},body="Therzok operates in Orgrimmar and takes an interest in those who combine combat skill with discretion. His contacts allow him to seek prospective associates for the Hand without relying on public invitations.",aliasQuestIDs={}},fr={title="Therzok",body="Therzok opère en Orgrimmar et s'intéresse à ceux qui combinent les compétences de combat avec discrétion. Ses contacts lui permettent de rechercher des associés potentiels pour la Main sans compter sur des invitations publiques."},de={title="Therzok",body="Therzok arbeitet in Orgrimmar und interessiert sich für diejenigen, die Kampfkunst mit Diskretion verbinden. Seine Kontakte ermöglichen es ihm, potenzielle Partner für die Hand zu finden, ohne sich auf öffentliche Einladungen verlassen."},pt={title="Therzok",body="Therzok opera em Orgrimmar e se interessa por aqueles que combinam habilidade de combate com discrição. Seus contatos permitem que ele procure possíveis associados para a Mão sem depender de convites públicos."},pl={title="Therzok",body="Therzok działa w Orgrimmar i interesuje się osobami łączącymi zdolności bojowe z dyskrecją. Kontakty pozwalają mu szukać potencjalnych współpracowników dla Ręki bez publicznych zaproszeń."},ru={title="Therzok",body="Therzok работает в Orgrimmar и интересуется теми, кто сочетает боевые навыки с дискрецией. Его контакты позволяют ему искать потенциальных партнеров для Руки без публичных приглашений."},references={["place:orgrimmar"]=true}},
    ["person:thork"] = {title="Thork",kind="Personaje",aliases={"Thork"},body="Thork es un representante de la Horda en El Cruce. Recibe a aventureros que llegan a Los Baldíos y participa en la defensa de un poblado expuesto a amenazas de todo el territorio.",aliasQuestIDs={},en={title="Thork",aliases={"Thork"},body="Thork is a Horde representative at the Crossroads. He receives adventurers arriving in the Barrens and takes part in defending a settlement exposed to threats from across the region.",aliasQuestIDs={}},fr={title="Thork",body="Thork est un représentant Horde au Crossroads. Il reçoit des aventuriers arrivant dans le Barrens et prend part à la défense d'une colonie exposée aux menaces de toute la région."},de={title="Thork",body="Thork ist ein Horde-Vertreter im Crossroads. Er empfängt Abenteurer, die im Barrens ankommen, und beteiligt sich an der Verteidigung einer Siedlung, die von Bedrohungen aus der ganzen Region ausgesetzt ist."},pt={title="Thork",body="Thork é um representante da Horde no Crossroads. Ele recebe aventureiros que chegam no Barrens e participa na defesa de um assentamento exposto a ameaças de toda a região."},pl={title="Thork",body="Thork jest przedstawicielem frakcji Horde w Crossroads. Przyjmuje poszukiwaczy przygód przybywających do Barrens i uczestniczy w obronie osady narażonej na zagrożenia z całego regionu."},ru={title="Thork",body="Thork - это представитель Horde в Crossroads. Он принимает приезжающих в Barrens авантюристов и участвует в защите поселения, подверженного угрозам со всего региона."},references={["organization:horde"]=true,["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:thotar"] = {title="Thotar",kind="Personaje",aliases={"Thotar"},body="Thotar es un instructor de cazadores de Cerrotajo. Enseña a establecer una relación con las bestias y a convertir a un animal en compañero de viaje y de combate.",aliasQuestIDs={},en={title="Thotar",aliases={"Thotar"},body="Thotar is a hunter trainer in Razor Hill. He teaches how to form a bond with beasts and make an animal a companion in travel and battle.",aliasQuestIDs={}},fr={title="Thotar",body="Thotar est un entraîneur de chasse dans Razor Hill. Il enseigne comment établir un lien avec les bêtes et faire d’un animal un compagnon de voyage et de combat."},de={title="Thotar",body="Thotar bildet in Razor Hill Jäger aus. Er lehrt, wie sich eine Bindung zu Wildtieren aufbauen lässt und wie ein Tier zum Begleiter auf Reisen und im Kampf wird."},pt={title="Thotar",body="Thotar é um treinador de caçadores em Razor Hill. Ele ensina como formar um vínculo com bestas e fazer um animal um companheiro em viagens e batalhas."},pl={title="Thotar",body="Thotar jest nauczycielem łowców w Razor Hill. Uczy nawiązywania więzi z bestiami i czynienia zwierzęcia towarzyszem podróży oraz walki."},ru={title="Thotar",body="Thotar - тренер охотников в Razor Hill. Он учит, как сблизиться с животными и сделать из животного компаньона в путешествиях и битвах."},references={["place:razor-hill"]=true}},
    ["person:thrall"] = {title="Thrall",kind="Personaje",aliases={"Thrall"},body="Thrall es el jefe de guerra de la Horda y dirige a su pueblo desde Orgrimmar. Su autoridad combina la defensa de los nuevos asentamientos con la búsqueda de aliados que permitan a la Horda afianzarse en Azeroth.",aliasQuestIDs={},en={title="Thrall",aliases={"Thrall"},body="Thrall is the warchief of the Horde and leads his people from Orgrimmar. His authority combines the defense of new settlements with the search for allies who can help the Horde establish itself in Azeroth.",aliasQuestIDs={}},fr={title="Thrall",body="Thrall est le chef de guerre de la Horde et dirige son peuple de Orgrimmar. Son autorité combine la défense de nouveaux établissements avec la recherche d'alliés qui peuvent aider le Horde à s'établir dans Azeroth."},de={title="Thrall",body="Thrall ist der Kriegshäuptling der Horde und führt sein Volk von Orgrimmar aus. Seine Autorität verbindet die Verteidigung neuer Siedlungen mit der Suche nach Verbündeten, die den Horde helfen können, sich in Azeroth zu etablieren."},pt={title="Thrall",body="Thrall é o chefe de guerra do Horde e lidera seu povo a partir de Orgrimmar. Sua autoridade combina a defesa de novos assentamentos com a busca de aliados que possam ajudar o Horde a se estabelecer no Azeroth."},pl={title="Thrall",body="Thrall jest wodzem wojennym frakcji Horde i przewodzi swojemu ludowi z Orgrimmar. Jego władza łączy obronę nowych osad z poszukiwaniem sojuszników, którzy pomogą Horde umocnić swoją pozycję w Azeroth."},ru={title="Thrall",body="Thrall - вождь Horde и возглавляет свой народ из Orgrimmar. Его авторитет сочетает в себе защиту новых поселений с поиском союзников, которые помогут Horde утвердиться в Azeroth."},references={["organization:horde"]=true,["place:azeroth"]=true,["place:orgrimmar"]=true}},
    ["person:thundris-windweaver"] = {title="Thundris Tejevientos",kind="Personaje",aliases={"Thundris","Thundris Tejevientos"},body="Thundris Tejevientos es un anciano de Auberdine. Sus responsabilidades lo vinculan tanto al bienestar del puerto como a la memoria y las tradiciones de los elfos de la noche.",aliasQuestIDs={},en={title="Thundris Windweaver",aliases={"Thundris","Thundris Windweaver"},body="Thundris Windweaver is an elder in Auberdine. His responsibilities connect him both to the port’s well-being and to the memory and traditions of the night elves.",aliasQuestIDs={}},fr={title="Thundris Windweaver",body="Thundris Windweaver est un aîné de Auberdine. Ses responsabilités le relient à la fois au bien-être du port et à la mémoire et aux traditions des elfes de la nuit."},de={title="Thundris Windweaver",body="Thundris Windweaver ist ein Ältester in Auberdine. Seine Verantwortung verbindet ihn sowohl mit dem Wohlergehen des Hafens als auch mit der Erinnerung und den Traditionen der Nachtelfen."},pt={title="Thundris Windweaver",body="Thundris Windweaver é um ancião em Auberdine. Suas responsabilidades o conectam tanto ao bem-estar do porto quanto à memória e às tradições dos elfos noturnos."},pl={title="Thundris Windweaver",body="Thundris Windweaver należy do starszyzny Auberdine. Obowiązki wiążą go zarówno z dobrem portu, jak i z pamięcią oraz tradycjami nocnych elfów."},ru={title="Thundris Windweaver",body="Thundris Windweaver - старейшина в Auberdine. Его обязанности связывают его как с благополучием порта, так и с памятью и традициями ночных эльфов."},references={["place:auberdine"]=true}},
    ["person:thungrim-firegaze"] = {title="Thun'grim Vistafuego",kind="Personaje",aliases={"Thun'grim","Thun'grim Vistafuego","Thun’grim","Thun’grim Vistafuego"},body="Thun'grim Vistafuego es un herrero orco que vive apartado en las colinas al este de El Cruce. Su reputación procede de la calidad de las armas y armaduras que fabrica para los guerreros de la Horda.",aliasQuestIDs={},en={title="Thun'grim Firegaze",aliases={"Thun'grim","Thun'grim Firegaze","Thun’grim","Thun’grim Firegaze"},body="Thun'grim Firegaze is an orc blacksmith living apart in the hills east of the Crossroads. His reputation rests on the quality of the weapons and armor he makes for Horde warriors.",aliasQuestIDs={}},fr={title="Thun'grim Firegaze",body="Thun'grim Firegaze est un forgeron orc vivant à part dans les collines à l'est de la Crossroads. Sa réputation repose sur la qualité des armes et des armures qu'il fabrique pour les guerriers Horde."},de={title="Thun'grim Firegaze",body="Thun'grim Firegaze ist ein Ork-Schmied, der getrennt in den Hügeln östlich des Crossroads lebt. Sein Ruf beruht auf der Qualität der Waffen und Rüstungen, die er für Horde-Krieger herstellt."},pt={title="Thun'grim Firegaze",body="Thun'grim Firegaze é um ferreiro orc que vive separado nas colinas a leste do Crossroads. Sua reputação se baseia na qualidade das armas e armaduras que ele faz para os guerreiros Horde."},pl={title="Thun'grim Firegaze",body="Thun'grim Firegaze jest orczym kowalem mieszkającym na uboczu, we wzgórzach na wschód od Crossroads. Sławę zawdzięcza jakości broni i zbroi wytwarzanych dla wojowników frakcji Horde."},ru={title="Thun'grim Firegaze",body="Thun'grim Firegaze - оркский кузнец, живущий в горах к востоку от Crossroads. Его репутация зависит от качества оружия и доспехов, которые он делает для воинов Horde."},references={["organization:horde"]=true,["place:the-crossroads"]=true}},
    ["person:tonga-runetotem"] = {title="Tonga Tótem de Runa",kind="Personaje",aliases={"Tonga","Tonga Tótem de Runa"},body="Tonga Tótem de Runa estudia los oasis de Los Baldíos desde El Cruce. Sus observaciones buscan comprender por qué la vida y el agua se concentran en determinados puntos de una región tan seca.",aliasQuestIDs={},en={title="Tonga Runetotem",aliases={"Tonga","Tonga Runetotem"},body="Tonga Runetotem studies the oases of the Barrens from the Crossroads. His observations seek to explain why life and water gather at particular points in such a dry region.",aliasQuestIDs={}},fr={title="Tonga Runetotem",body="Tonga Runetotem étudie les oasis de la Barrens à partir du Crossroads. Ses observations cherchent à expliquer pourquoi la vie et l'eau se rassemblent à des points particuliers dans une région aussi sèche."},de={title="Tonga Runetotem",body="Tonga Runetotem studiert die Oasen des Barrens vom Crossroads aus. Seine Beobachtungen versuchen zu erklären, warum sich Leben und Wasser an bestimmten Stellen in einer so trockenen Region sammeln."},pt={title="Tonga Runetotem",body="Tonga Runetotem estuda os oásis do Barrens do Crossroads. Suas observações procuram explicar por que a vida e a água se reúnem em pontos específicos em uma região tão seca."},pl={title="Tonga Runetotem",body="Tonga Runetotem bada oazy regionu Barrens z osady Crossroads. Jego obserwacje mają wyjaśnić, dlaczego życie i woda skupiają się w określonych miejscach tak suchej krainy."},ru={title="Tonga Runetotem",body="Tonga Runetotem изучает оазисы Barrens от Crossroads. Его наблюдения пытаются объяснить, почему жизнь и вода собираются в определенных точках в таком сухом регионе."},references={["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:tooga"] = {title="Tooga",kind="Personaje",aliases={"Tooga"},body="Tooga vive junto a su esposa Thorta en los alrededores del Puerto Bonvapor. Sus recorridos en busca de comida pueden dejarlo desorientado, lejos del lugar donde ella espera su regreso.",aliasQuestIDs={},en={title="Tooga",aliases={"Tooga"},body="Tooga lives with his wife Torta near Steamwheedle Port. His journeys to find food can leave him lost, far from the place where she waits for his return.",aliasQuestIDs={}},fr={title="Tooga",body="Tooga vit avec sa femme Torta près de Steamwheedle Port. Ses voyages pour trouver de la nourriture peuvent le laisser perdu, loin de l'endroit où elle attend son retour."},de={title="Tooga",body="Tooga lebt mit seiner Frau Torta in der Nähe von Steamwheedle Port. Seine Reisen, um Nahrung zu finden, können ihn verloren gehen lassen, weit weg von dem Ort, wo sie auf seine Rückkehr wartet."},pt={title="Tooga",body="Tooga vive com sua esposa Torta perto de Steamwheedle Port. Suas jornadas para encontrar comida podem deixá-lo perdido, longe do lugar onde ela espera seu retorno."},pl={title="Tooga",body="Tooga mieszka z żoną noszącą imię Torta przy Steamwheedle Port. Wyprawy po jedzenie potrafią pozostawić go zagubionym daleko od miejsca, gdzie czeka ona na jego powrót."},ru={title="Tooga",body="Tooga живет со своей женой Torta рядом с Steamwheedle Port. Его путешествия в поисках пищи могут оставить его потерянным, далеко от места, где она ждет его возвращения."},references={["person:torta"]=true,["place:steamwheedle-port"]=true}},
    ["person:torek"] = {title="Torek",kind="Personaje",aliases={"Torek"},body="Torek dirige asaltantes que combaten a las fuerzas de la Avanzada Ala de Plata. Responde ante Ertog Colmillorrabioso, en el Hachazo, y considera la lucha contra las centinelas una ocasión de alcanzar gloria para su grupo.",aliasQuestIDs={},en={title="Torek",aliases={"Torek"},body="Torek leads raiders fighting the forces of Silverwing Outpost. He answers to Ertog Ragetusk at Splintertree and sees combat against the sentinels as an opportunity for his band to earn glory.",aliasQuestIDs={}},fr={title="Torek",body="Torek mène raiders combattant les forces de Silverwing Outpost. Il répond à Ertog Ragetusk au Splintertree et voit le combat contre les sentinelles comme une opportunité pour son groupe de gagner la gloire."},de={title="Torek",body="Torek führt Plünderer an, die gegen die Kräfte von Silverwing Outpost kämpfen. Er antwortet Ertog Ragetusk am Splintertree und sieht den Kampf gegen die Wachtposten als Chance für seine Band, sich Ruhm zu verdienen."},pt={title="Torek",body="Torek lidera os invasores que lutam contra as forças de Silverwing Outpost. Ele responde ao Ertog Ragetusk no Splintertree e vê o combate contra as sentinelas como uma oportunidade para sua banda ganhar glória."},pl={title="Torek",body="Torek przewodzi najeźdźcom walczącym z siłami Silverwing Outpost. Podlega postaci Ertog Ragetusk w Splintertree i widzi w walce ze strażniczkami szansę zdobycia chwały przez swoją grupę."},ru={title="Torek",body="Torek возглавляет рейдеры, сражающиеся с силами Silverwing Outpost. Он отвечает на Ertog Ragetusk в Splintertree и видит бой против sentinels как возможность для его группы заработать славу."},references={["organization:silverwing-sentinels"]=true}},
    ["person:torta"] = {title="Thorta",kind="Personaje",aliases={"Thorta"},body="Thorta espera a su esposo Tooga al sur del Puerto Bonvapor. Su vida familiar forma parte de las pequeñas historias que transcurren junto a los viajes, los puertos y los peligros del desierto de Tanaris.",aliasQuestIDs={},en={title="Torta",aliases={"Torta"},body="Torta waits for her husband Tooga south of Steamwheedle Port. Their family life is one of the small stories unfolding alongside the journeys, ports, and dangers of the Tanaris desert.",aliasQuestIDs={}},fr={title="Torta",body="Torta attend son mari Tooga au sud de Steamwheedle Port. Leur vie de famille est l'une des petites histoires qui se déroulent aux côtés des voyages, des ports et des dangers du désert Tanaris."},de={title="Torta",body="Torta wartet südlich von Steamwheedle Port auf ihren Mann Tooga. Ihr Familienleben ist eine der kleinen Geschichten, die sich entlang der Reisen, Häfen und Gefahren der Tanaris-Wüste entfalten."},pt={title="Torta",body="Torta espera por seu marido Tooga sul de Steamwheedle Port. Sua vida familiar é uma das pequenas histórias que se desenrolam ao longo das viagens, portos e perigos do deserto de Tanaris."},pl={title="Torta",body="Torta czeka na męża noszącego imię Tooga na południe od Steamwheedle Port. Ich życie rodzinne należy do małych historii toczących się obok podróży, portów i niebezpieczeństw pustyni Tanaris."},ru={title="Torta",body="Torta ждет своего мужа Tooga к югу от Steamwheedle Port. Их семейная жизнь - одна из маленьких историй, разворачивающихся вместе с путешествиями, портами и опасностями пустыни Tanaris."},references={["person:tooga"]=true,["place:steamwheedle-port"]=true,["place:tanaris"]=true}},
    ["person:torwa-pathfinder"] = {title="Torwa Abrecaminos",kind="Personaje",aliases={"Torwa","Torwa Abrecaminos"},body="Torwa Abrecaminos es un cazador del Cráter de Un'Goro que estudia su fauna. Su interés por las toxinas y la conducta de los animales lo acerca a una forma de caza que también depende de observar y comprender.",aliasQuestIDs={},en={title="Torwa Pathfinder",aliases={"Torwa","Torwa Pathfinder"},body="Torwa Pathfinder is a hunter in Un'Goro Crater who studies its wildlife. His interest in toxins and animal behavior places observation and understanding alongside the act of hunting.",aliasQuestIDs={}},fr={title="Torwa Pathfinder",body="Torwa Pathfinder est un chasseur de Un'Goro Crater qui étudie sa faune. Son intérêt pour les toxines et le comportement animal place l’observation et la compréhension à côté de l’acte de chasser."},de={title="Torwa Pathfinder",body="Torwa Pathfinder ist ein Jäger in Un'Goro Crater, der die Tierwelt studiert. Sein Interesse an Toxinen und tierischem Verhalten stellt Beobachtung und Verständnis neben den Akt der Jagd."},pt={title="Torwa Pathfinder",body="Torwa Pathfinder é um caçador em Un'Goro Crater que estuda sua vida selvagem. Seu interesse em toxinas e comportamento animal coloca observação e compreensão ao lado do ato de caça."},pl={title="Torwa Pathfinder",body="Torwa Pathfinder jest łowcą w Un'Goro Crater badającym miejscową faunę. Zainteresowanie toksynami i zachowaniem zwierząt sprawia, że obok polowania stawia obserwację oraz zrozumienie."},ru={title="Torwa Pathfinder",body="Torwa Pathfinder - охотник в Un'Goro Crater, который изучает его дикую природу. Его интерес к токсинам и поведению животных придает место наблюдению и пониманию наряду с актом охоты."},references={["place:ungoro-crater"]=true}},
    ["person:tranrek"] = {title="Tran'rek",kind="Personaje",aliases={"Tran'rek","Tran’rek"},body="Tran'rek es un habitante de Gadgetzan relacionado con el suministro de caparazones de escarabajo. Sus tratos muestran cómo los recursos de las criaturas del desierto entran en las redes comerciales de Tanaris.",aliasQuestIDs={},en={title="Tran'rek",aliases={"Tran'rek","Tran’rek"},body="Tran'rek is a Gadgetzan resident associated with supplying scarab shells. His deals show how resources from desert creatures enter Tanaris’s trade networks.",aliasQuestIDs={}},fr={title="Tran'rek",body="Tran'rek est un résident Gadgetzan associé à la fourniture de coques de scarabées. Ses offres montrent comment les ressources des créatures du désert entrent dans les réseaux commerciaux de Tanaris."},de={title="Tran'rek",body="Tran'rek ist ein Einwohner von Gadgetzan, der mit Skarabäusmuscheln in Verbindung gebracht wird. Seine Deals zeigen, wie Ressourcen von Wüstenwesen in Tanaris 'Handelsnetzwerke gelangen."},pt={title="Tran'rek",body="Tran'rek é um residente Gadgetzan associado ao fornecimento de conchas de escaravelho. Seus negócios mostram como os recursos de criaturas do deserto entram nas redes comerciais da Tanaris."},pl={title="Tran'rek",body="Tran'rek jest mieszkańcem Gadgetzan związanym z dostawami pancerzy skarabeuszy. Jego transakcje pokazują, jak zasoby pustynnych stworzeń trafiają do sieci handlowych Tanaris."},ru={title="Tran'rek",body="Tran'rek - это житель Gadgetzan, связанный с поставкой раковин скарабея. Его сделки показывают, как ресурсы пустынных существ проникают в торговые сети Tanaris."},references={["place:gadgetzan"]=true,["place:tanaris"]=true}},
    ["person:trenton-lighthammer"] = {title="Trenton Mazaligera",kind="Personaje",aliases={"Trenton","Trenton Mazaligera"},body="Trenton Mazaligera es un artesano de Gadgetzan interesado en técnicas de templado y materiales especiales. Su trabajo muestra cómo los conocimientos de los trols y los recursos del desierto pueden tener valor para otros oficios.",aliasQuestIDs={},en={title="Trenton Lighthammer",aliases={"Trenton","Trenton Lighthammer"},body="Trenton Lighthammer is a Gadgetzan craftsperson interested in tempering techniques and special materials. His work shows how troll knowledge and desert resources can have value for other crafts.",aliasQuestIDs={}},fr={title="Trenton Lighthammer",body="Trenton Lighthammer est un artisan Gadgetzan intéressé par les techniques de trempe et les matériaux spéciaux. Son travail montre comment les connaissances des trolls et les ressources du désert peuvent avoir de la valeur pour d’autres métiers."},de={title="Trenton Lighthammer",body="Trenton Lighthammer ist ein Gadgetzan Handwerker, der sich für Temperiertechniken und spezielle Materialien interessiert. Seine Arbeit zeigt, wie Trollwissen und Wüstenressourcen einen Wert für andere Handwerke haben können."},pt={title="Trenton Lighthammer",body="Trenton Lighthammer é um artesão Gadgetzan interessado em técnicas de têmpera e materiais especiais. Seu trabalho mostra como o conhecimento dos trolls e os recursos do deserto podem ter valor para outros ofícios."},pl={title="Trenton Lighthammer",body="Trenton Lighthammer jest rzemieślnikiem w Gadgetzan zainteresowanym technikami hartowania i szczególnymi materiałami. Jego praca ukazuje wartość wiedzy trolli i zasobów pustyni dla innych rzemiosł."},ru={title="Trenton Lighthammer",body="Trenton Lighthammer - мастер Gadgetzan, заинтересованный в технике закаливания и специальных материалах. Его работа показывает, как знания троллей и ресурсы пустыни могут иметь ценность для других ремесел."},references={["place:gadgetzan"]=true}},
    ["person:treshala-fallowbrook"] = {title="Treshala",kind="Personaje",aliases={"Treshala"},body="Treshala vive en Darnassus y está unida a Heralath por un colgante de vínculo. Ese objeto expresa una relación personal que existe más allá de los deberes y los peligros que llevan a su esposo lejos de casa.",aliasQuestIDs={},en={title="Treshala Fallowbrook",aliases={"Treshala","Treshala Fallowbrook"},body="Treshala lives in Darnassus and is bonded to Heralath through a pendant. The object expresses a personal relationship extending beyond the duties and dangers that take her husband far from home.",aliasQuestIDs={}},fr={title="Treshala Fallowbrook",body="Treshala vit dans Darnassus et est lié à Heralath à travers un pendentif. L'objet exprime une relation personnelle qui s'étend au-delà des devoirs et des dangers qui emmènent son mari loin de chez lui."},de={title="Treshala Fallowbrook",body="Treshala lebt in Darnassus und ist mit Heralath durch einen Anhänger verbunden. Das Objekt drückt eine persönliche Beziehung aus, die über die Pflichten und Gefahren hinausgeht, die ihren Mann weit weg von zu Hause bringen."},pt={title="Treshala Fallowbrook",body="Treshala vive em Darnassus e é ligado a Heralath através de um pingente. O objeto expressa uma relação pessoal que se estende além dos deveres e perigos que levam seu marido longe de casa."},pl={title="Treshala Fallowbrook",body="Treshala mieszka w Darnassus i jest związana z postacią Heralath poprzez wisiorek. Przedmiot wyraża osobistą relację sięgającą poza obowiązki i zagrożenia zabierające jej męża daleko od domu."},ru={title="Treshala Fallowbrook",body="Treshala живет в Darnassus и связан с Heralath через подвесок. Объект выражает личные отношения, которые выходят за рамки обязанностей и опасностей, которые отводят ее мужа далеко от дома."},references={["place:darnassus"]=true}},
    ["person:trey-lightforge"] = {title="Trey Forjaluz",kind="Personaje",aliases={"Trey","Trey Forjaluz"},body="Trey Forjaluz es un paladín relacionado con los exploradores de Frondavil. Su nombre y el de su espada están ligados a la lucha contra la corrupción y a los vínculos que unen a quienes la afrontan.",aliasQuestIDs={},en={title="Trey Lightforge",aliases={"Trey","Trey Lightforge"},body="Trey Lightforge is a paladin associated with Felwood’s explorers. His name and that of his sword are tied to the struggle against corruption and the bonds between those facing it.",aliasQuestIDs={}},fr={title="Trey Lightforge",body="Trey Lightforge est un paladin associé aux explorateurs de Felwood. Son nom et celui de son épée sont liés à la lutte contre la corruption et les liens entre ceux qui y font face."},de={title="Trey Lightforge",body="Trey Lightforge ist ein Paladin, der mit den Entdeckern von Felwood in Verbindung gebracht wird. Sein Name und der seines Schwertes sind an den Kampf gegen die Korruption und die Bande zwischen denen geknüpft, die ihr ausgesetzt sind."},pt={title="Trey Lightforge",body="Trey Lightforge é um paladino associado aos exploradores do Felwood. Seu nome e o de sua espada estão ligados à luta contra a corrupção e os laços entre aqueles que a enfrentam."},pl={title="Trey Lightforge",body="Trey Lightforge jest paladynem związanym z odkrywcami Felwood. Jego imię i nazwa miecza wiążą się z walką ze skażeniem oraz więziami osób stawiających mu czoła."},ru={title="Trey Lightforge",body="Trey Lightforge - паладин, связанный с исследователями Felwood. Его имя и меч связаны с борьбой с порчей и с тем, как они объединяют тех, кто сталкивается с ней."},references={["place:felwood"]=true}},
    ["person:troyas-moonbreeze"] = {title="Troyas Brisaluna",kind="Personaje",aliases={"Troyas","Troyas Brisaluna"},body="Troyas Brisaluna es un estudioso de antiguas regiones y ruinas de Azeroth. Sus contactos con otros investigadores permiten reunir conocimientos conservados en lugares alejados entre sí.",aliasQuestIDs={},en={title="Troyas Moonbreeze",aliases={"Troyas","Troyas Moonbreeze"},body="Troyas Moonbreeze is a scholar of Azeroth’s ancient regions and ruins. His contacts with other researchers help bring together knowledge preserved in distant places.",aliasQuestIDs={}},fr={title="Troyas Moonbreeze",body="Troyas Moonbreeze est un savant des anciennes régions et ruines de Azeroth. Ses contacts avec d’autres chercheurs aident à rassembler des connaissances préservées dans des lieux lointains."},de={title="Troyas Moonbreeze",body="Troyas Moonbreeze ist ein Gelehrter der antiken Regionen und Ruinen von Azeroth. Seine Kontakte zu anderen Forschern tragen dazu bei, Wissen zusammenzubringen, das in fernen Gegenden bewahrt wurde."},pt={title="Troyas Moonbreeze",body="Troyas Moonbreeze é um estudioso das antigas regiões e ruínas do Azeroth. Seus contatos com outros pesquisadores ajudam a reunir conhecimentos preservados em lugares distantes."},pl={title="Troyas Moonbreeze",body="Troyas Moonbreeze jest badaczem pradawnych regionów i ruin Azeroth. Kontakty z innymi uczonymi pomagają łączyć wiedzę przechowywaną w odległych miejscach."},ru={title="Troyas Moonbreeze",body="Troyas Moonbreeze изучает древние области и руины Azeroth. Его контакты с другими исследователями помогают собрать знания, сохраненные в далеких местах."},references={["place:azeroth"]=true}},
    ["person:trull-failbane"] = {title="Trull Fallarruina",kind="Personaje",aliases={"Trull","Trull Fallarruina"},body="Trull Fallarruina actúa desde Frondavil frente a los peligros de las regiones del norte. Le preocupan especialmente las criaturas alteradas y la seguridad de quienes recorren Cuna del Invierno.",aliasQuestIDs={},en={title="Trull Failbane",aliases={"Trull","Trull Failbane"},body="Trull Failbane acts from Felwood against dangers in the northern regions. He is particularly concerned with disturbed creatures and the safety of those traveling through Winterspring.",aliasQuestIDs={}},fr={title="Trull Failbane",body="Trull Failbane agit à partir de Felwood contre les dangers dans les régions du nord. Il est particulièrement préoccupé par les créatures perturbées et la sécurité de ceux qui voyagent à travers Winterspring."},de={title="Trull Failbane",body="Trull Failbane agiert von Felwood aus gegen Gefahren in den nördlichen Regionen. Ihm geht es vor allem um gestörte Lebewesen und die Sicherheit der Winterspring-Reisenden."},pt={title="Trull Failbane",body="Trull Failbane atua a partir de Felwood contra perigos nas regiões do norte. Ele está particularmente preocupado com criaturas perturbadas e a segurança daqueles que viajam através do Winterspring."},pl={title="Trull Failbane",body="Trull Failbane działa z Felwood przeciw niebezpieczeństwom północnych regionów. Szczególnie niepokoją go niespokojne stworzenia i bezpieczeństwo osób przemierzających Winterspring."},ru={title="Trull Failbane",body="Trull Failbane действует из Felwood против опасностей в северных регионах. Он особенно беспокоится о беспокойных существах и безопасности тех, кто путешествует через Winterspring."},references={["place:felwood"]=true,["place:winterspring"]=true}},
    ["person:tsunaman"] = {title="Tsunaman",kind="Personaje",aliases={"Tsunaman"},body="Tsunaman actúa en el Refugio Roca del Sol en nombre del Tribunal de las Mareas. Su labor está relacionada con la rivalidad entre los poderes del agua y los elementales de fuego de Sierra Espolón.",aliasQuestIDs={},en={title="Tsunaman",aliases={"Tsunaman"},body="Tsunaman acts at Sun Rock Retreat on behalf of the Tribunal of the Tides. His work concerns the rivalry between the powers of water and the fire elementals of the Stonetalon Mountains.",aliasQuestIDs={}},fr={title="Tsunaman",body="Tsunaman agit à Sun Rock Retreat pour le compte du Tribunal of the Tides. Son travail concerne la rivalité entre les pouvoirs de l'eau et les élémentaux de feu de la Stonetalon Mountains."},de={title="Tsunaman",body="Tsunaman agiert bei Sun Rock Retreat im Auftrag des Tribunal of the Tides. Seine Arbeit beschäftigt sich mit der Rivalität zwischen den Kräften des Wassers und den Feuerelementen der Stonetalon Mountains."},pt={title="Tsunaman",body="Tsunaman atua na Sun Rock Retreat em nome da Tribunal of the Tides. Seu trabalho diz respeito à rivalidade entre os poderes da água e os elementos de fogo do Stonetalon Mountains."},pl={title="Tsunaman",body="Tsunaman działa w Sun Rock Retreat w imieniu Tribunal of the Tides. Jego praca dotyczy rywalizacji potęg wody z żywiołakami ognia regionu Stonetalon Mountains."},ru={title="Tsunaman",body="Tsunaman действует в Sun Rock Retreat от имени Tribunal of the Tides. Его работа касается соперничества между силами воды и огненными элементалами Stonetalon Mountains."},references={["organization:tribunal-of-the-tides"]=true,["place:stonetalon-mountains"]=true,["place:sun-rock-retreat"]=true}},
    ["person:turak-runetotem"] = {title="Turak Tótem de Runa",kind="Personaje",aliases={"Turak","Turak Tótem de Runa"},body="Turak Tótem de Runa es un instructor de druidas en Cima del Trueno. Ayuda a sus discípulos a convertir lo aprendido sobre los animales y sus cualidades en nuevas formas de relacionarse con la naturaleza.",aliasQuestIDs={},en={title="Turak Runetotem",aliases={"Turak","Turak Runetotem"},body="Turak Runetotem is a druid trainer in Thunder Bluff. He helps his students turn what they have learned about animals and their qualities into new ways of relating to nature.",aliasQuestIDs={}},fr={title="Turak Runetotem",body="Turak Runetotem est un entraîneur de druide dans Thunder Bluff. Il aide ses élèves à transformer ce qu’ils ont appris sur les animaux et leurs qualités en nouvelles façons de se rapporter à la nature."},de={title="Turak Runetotem",body="Turak Runetotem ist Druidentrainer in Thunder Bluff. Er hilft seinen Schülern, das, was sie über Tiere und ihre Eigenschaften gelernt haben, in neue Wege der Beziehung zur Natur zu verwandeln."},pt={title="Turak Runetotem",body="Turak Runetotem é um treinador druida em Thunder Bluff. Ele ajuda seus alunos a transformar o que aprenderam sobre os animais e suas qualidades em novas maneiras de se relacionar com a natureza."},pl={title="Turak Runetotem",body="Turak Runetotem jest nauczycielem druidów w Thunder Bluff. Pomaga uczniom przekuwać wiedzę o zwierzętach i ich cechach w nowe sposoby nawiązywania więzi z naturą."},ru={title="Turak Runetotem",body="Turak Runetotem - тренер друидов в Thunder Bluff. Он помогает своим ученикам использовать то, что они узнали о животных и их качествах, для новых отношений с природой."},references={["place:thunder-bluff"]=true}},
    ["person:twilight-marauder-morna"] = {title="Maleante Crepuscular Morna",kind="Personaje",aliases={"Maleante Crepuscular Morna","Morna"},body="Morna dirige a los maleantes montados del Martillo Crepuscular en Silithus. Su banda ataca patrullas y caravanas pequeñas, aprovechando la distancia a la que operan las fuerzas del Fuerte Cenarion.",aliasQuestIDs={},en={title="Twilight Marauder Morna",aliases={"Morna","Twilight Marauder Morna"},body="Morna leads mounted Twilight’s Hammer marauders in Silithus. The band attacks small patrols and caravans, taking advantage of its distance from the forces at Cenarion Hold.",aliasQuestIDs={}},fr={title="Twilight Marauder Morna",body="Morna conduit monté maraudeurs Twilight’s Hammer dans Silithus. La bande attaque les petites patrouilles et caravanes, profitant de sa distance avec les forces de Cenarion Hold."},de={title="Twilight Marauder Morna",body="Morna führt die berittenen Twilight’s Hammer-Marodeure in Silithus an. Die Bande greift kleine Patrouillen und Wohnwagen an und nutzt ihre Entfernung zu den Kräften bei Cenarion Hold aus."},pt={title="Twilight Marauder Morna",body="Morna leva montado Twilight’s Hammer marauders em Silithus. A banda ataca pequenas patrulhas e caravanas, aproveitando sua distância das forças do Cenarion Hold."},pl={title="Twilight Marauder Morna",body="Morna prowadzi konnych najeźdźców Twilight’s Hammer w Silithus. Grupa atakuje małe patrole i karawany, wykorzystując oddalenie od sił Cenarion Hold."},ru={title="Twilight Marauder Morna",body="Morna ведет конных мародеров Twilight’s Hammer в Silithus. Группа атакует небольшие патрули и караваны, используя свое расстояние от сил в Cenarion Hold."},references={["organization:twilights-hammer"]=true,["place:silithus"]=true}},
    ["person:tyrande-whisperwind"] = {title="Tyrande Susurravientos",kind="Personaje",aliases={"Tyrande","Tyrande Susurravientos"},body="Tyrande Susurravientos es la suma sacerdotisa de Elune y una figura dirigente de los elfos de la noche. Desde el Templo de la Luna de Darnassus, su labor une la protección de su pueblo con la devoción a la diosa.",aliasQuestIDs={},en={title="Tyrande Whisperwind",aliases={"Tyrande","Tyrande Whisperwind"},body="Tyrande Whisperwind is the high priestess of Elune and a leader of the night elves. From the Temple of the Moon in Darnassus, her work joins the protection of her people with devotion to the goddess.",aliasQuestIDs={}},fr={title="Tyrande Whisperwind",body="Tyrande Whisperwind est la grande prêtresse de Elune et un chef des elfes de la nuit. De la Temple of the Moon en Darnassus, son travail rejoint la protection de son peuple avec dévotion à la déesse."},de={title="Tyrande Whisperwind",body="Tyrande Whisperwind ist die Hohepriesterin von Elune und Anführerin der Nachtelfen. Von der Temple of the Moon in Darnassus bis zu ihrer Arbeit verbindet ihre Arbeit den Schutz ihres Volkes mit Hingabe an die Göttin den Schutz der Göttin der Göttin."},pt={title="Tyrande Whisperwind",body="Tyrande Whisperwind é a alta sacerdotisa do Elune e líder dos elfos noturnos. Do Temple of the Moon em Darnassus, seu trabalho une a proteção de seu povo com devoção à deusa."},pl={title="Tyrande Whisperwind",body="Tyrande Whisperwind jest najwyższą kapłanką bogini Elune i przywódczynią nocnych elfów. Działając w Temple of the Moon w Darnassus, łączy ochronę swojego ludu z oddaniem bogini."},ru={title="Tyrande Whisperwind",body="Tyrande Whisperwind - первосвященница Elune и лидер ночных эльфов. С Temple of the Moon в Darnassus, ее работа сочетает защиту своего народа с преданностью богине."},references={["npc:elune"]=true,["place:darnassus"]=true,["place:temple-of-the-moon"]=true}},
    ["person:tyranis-malem"] = {title="Tyranis Malem",kind="Personaje",aliases={"Tyranis","Tyranis Malem"},body="Tyranis Malem es un noble de una familia de mercaderes de Darnassus, hermano de Dalinda. Sus conocimientos de lo arcano y sus motivos para viajar a Desolace despiertan preguntas entre quienes intentan encontrarlo.",aliasQuestIDs={},en={title="Tyranis Malem",aliases={"Tyranis","Tyranis Malem"},body="Tyranis Malem is a noble from a Darnassus merchant family and Dalinda’s brother. His arcane knowledge and reasons for traveling to Desolace raise questions among those trying to find him.",aliasQuestIDs={}},fr={title="Tyranis Malem",body="Tyranis Malem est un noble d’une famille de marchands Darnassus et le frère de Dalinda. Ses connaissances obscures et les raisons de son voyage à Desolace soulèvent des questions parmi ceux qui tentent de le trouver."},de={title="Tyranis Malem",body="Tyranis Malem ist ein Edelmann aus einer Darnassus Kaufmannsfamilie und Dalinda \"Bruder. Sein undurchsichtiges Wissen und seine Gründe für die Reise zu Desolace werfen Fragen bei denen auf, die versuchen, ihn zu finden."},pt={title="Tyranis Malem",body="Tyranis Malem é um nobre de uma família de comerciantes Darnassus e irmão de Dalinda. Seu conhecimento arcano e razões para viajar para Desolace levantam questões entre aqueles que tentam encontrá-lo."},pl={title="Tyranis Malem",body="Tyranis Malem jest szlachcicem z kupieckiej rodziny Darnassus i bratem postaci Dalinda. Wiedza arkana oraz powody podróży do Desolace budzą pytania wśród próbujących go odnaleźć."},ru={title="Tyranis Malem",body="Tyranis Malem - дворянин из семьи купцов Darnassus и брат Dalinda. Его таинственные знания и причины путешествия в Desolace поднимают вопросы среди тех, кто пытается найти его."},references={["person:dalinda-malem"]=true,["place:darnassus"]=true,["place:desolace"]=true}},
    ["person:ucha"] = {title="U'cha",kind="Personaje",aliases={"U'cha","U’cha"},body="U'cha es un gorila enorme de las cavernas del norte de Un'Goro. Su tamaño y su fuerza le han ganado el respeto de los cazadores que consideran a las grandes bestias hijos de la Madre Tierra.",aliasQuestIDs={},en={title="U'cha",aliases={"U'cha","U’cha"},body="U'cha is an enormous gorilla of the caves in northern Un'Goro. His size and strength have earned the respect of hunters who regard the great beasts as children of the Earth Mother.",aliasQuestIDs={}},fr={title="U'cha",body="U'cha est un énorme gorille des grottes du nord de Un'Goro. Sa taille et sa force ont gagné le respect des chasseurs qui considèrent les grandes bêtes comme des enfants de la Earth Mother."},de={title="U'cha",body="U'cha ist ein riesiger Gorilla der Höhlen im nördlichen Un'Goro. Seine Größe und Stärke haben sich den Respekt der Jäger erworben, die die die die großen Tiere als Kinder des Earth Mother betrachten."},pt={title="U'cha",body="U'cha é um enorme gorila das cavernas no norte de Un'Goro. Seu tamanho e força ganharam o respeito dos caçadores que consideram os grandes animais como filhos do Earth Mother."},pl={title="U'cha",body="U'cha jest ogromnym gorylem jaskiń północnego Un'Goro. Rozmiar i siła zyskały mu szacunek myśliwych uznających wielkie bestie za dzieci istoty Earth Mother."},ru={title="U'cha",body="U'cha - это огромная горилла из пещер северной части Un'Goro. Его размер и сила заслужили уважение охотников, которые считают этих зверей детьми Earth Mother."},references={["person:earth-mother"]=true,["place:ungoro-crater"]=true}},
    ["person:ugthok"] = {title="Ug'thok",kind="Personaje",aliases={"Ug'thok","Ug’thok"},body="Ug'thok enseña herrería y busca materiales poco habituales para fabricar armas. Considera que las espinas de las bestias de Monte del Trueno pueden convertirse en la cabeza de un hacha, una idea que no todos sus colegas comparten.",aliasQuestIDs={},en={title="Ug'thok",aliases={"Ug'thok","Ug’thok"},body="Ug'thok teaches smithing and seeks unusual materials for weapons. He believes the spines of Thunder Ridge’s beasts can become an axe head, an idea not shared by all his colleagues.",aliasQuestIDs={}},fr={title="Ug'thok",body="Ug'thok enseigne la forge et recherche des matériaux inhabituels pour les armes. Il croit que les épines des bêtes de Thunder Ridge peuvent devenir une tête de hache, une idée qui n’est pas partagée par tous ses collègues."},de={title="Ug'thok",body="Ug'thok lehrt Schmieden und sucht ungewöhnliche Materialien für Waffen. Er glaubt, dass aus den Stacheln von Thunder Ridge \"Tieren ein Axtkopf werden kann, eine Idee, die nicht alle seine Kollegen teilen."},pt={title="Ug'thok",body="Ug'thok ensina ourivesaria e procura materiais incomuns para armas. Ele acredita que as espinhas dos animais do Thunder Ridge podem se tornar uma cabeça de machado, uma ideia não compartilhada por todos os seus colegas."},pl={title="Ug'thok",body="Ug'thok uczy kowalstwa i szuka niezwykłych materiałów na broń. Wierzy, że kolce bestii Thunder Ridge mogą stać się głowicą topora, choć nie wszyscy koledzy podzielają ten pomysł."},ru={title="Ug'thok",body="Ug'thok учит ковалку и ищет необычные материалы для оружия. Он считает, что позвонки зверей Thunder Ridge могут стать головой топора, идея, которой не разделяют все его коллеги."},references={["place:thunder-ridge"]=true}},
    ["person:ukor"] = {title="Ukor",kind="Personaje",aliases={"Ukor"},body="Ukor recorre el sur de Durotar y confía a los viajeros pequeños asuntos de transporte. Las pertenencias que deja a su paso recuerdan la vida de quienes se mueven entre los asentamientos de la región.",aliasQuestIDs={},en={title="Ukor",aliases={"Ukor"},body="Ukor travels southern Durotar and entrusts travelers with small transport matters. Belongings left along his route reflect the lives of those moving between the region’s settlements.",aliasQuestIDs={}},fr={title="Ukor",body="Ukor voyage dans le sud de Durotar et confie aux voyageurs de petites questions de transport. Les appartenances laissées le long de son itinéraire reflètent la vie de ceux qui se déplacent entre les colonies de la région."},de={title="Ukor",body="Ukor reist durch den Süden von Durotar und vertraut Reisenden kleinere Transportaufgaben an. Gegenstände, die entlang seiner Route zurückbleiben, geben Einblick in das Leben der Reisenden, die zwischen den Siedlungen der Region unterwegs sind."},pt={title="Ukor",body="Ukor viaja para o sul de Durotar e confia aos viajantes pequenas questões de transporte. Pertencimentos deixados ao longo de sua rota refletem a vida daqueles que se deslocam entre os assentamentos da região."},pl={title="Ukor",body="Ukor przemierza południowe Durotar i powierza podróżnym drobne sprawy transportowe. Rzeczy pozostawione na trasie odzwierciedlają życie osób przemieszczających się między osadami regionu."},ru={title="Ukor",body="Ukor путешествует на юг Durotar и доверяет путешественникам небольшие транспортные вопросы. Вещи, оставленные на его пути, отражают жизнь тех, кто перемещается между населенными пунктами региона."},references={["place:durotar"]=true}},
    ["person:ulaelek"] = {title="Ula'elek",kind="Personaje",aliases={"Ula'elek","Ula’elek"},body="Ula'elek es un herrero trol del Poblado Sen'jin. Sus conocimientos permiten elaborar piezas de armadura para los guerreros, una contribución del oficio de los Lanza Negra a la defensa de la Horda.",aliasQuestIDs={},en={title="Ula'elek",aliases={"Ula'elek","Ula’elek"},body="Ula'elek is a troll blacksmith in Sen'jin Village. His expertise allows him to make armor for warriors, a contribution by Darkspear craftsmanship to the Horde’s defense.",aliasQuestIDs={}},fr={title="Ula'elek",body="Ula'elek est un forgeron troll dans Sen'jin Village. Son expertise lui permet de fabriquer des armures pour guerriers, une contribution de l’artisanat Darkspear à la défense de la Horde."},de={title="Ula'elek",body="Ula'elek ist ein Trollschmied in Sen'jin Village. Seine Expertise ermöglicht es ihm, Rüstungen für Krieger herzustellen, ein Beitrag von Darkspear handwerkliches Geschick zur Verteidigung des Horde."},pt={title="Ula'elek",body="Ula'elek é um ferreiro troll em Sen'jin Village. Sua experiência lhe permite fazer armaduras para guerreiros, uma contribuição do artesanato Darkspear para a defesa do Horde."},pl={title="Ula'elek",body="Ula'elek jest trollim kowalem w Sen'jin Village. Potrafi wykonywać zbroje dla wojowników, wnosząc rzemiosło Darkspear w obronę frakcji Horde."},ru={title="Ula'elek",body="Ula'elek - троллинский кузнец в Sen'jin Village. Его опыт позволяет ему делать доспехи для воинов, вклад мастерства Darkspear в защиту Horde."},references={["organization:darkspear-tribe"]=true,["organization:horde"]=true,["place:senjin-village"]=true}},
    ["person:ulathek"] = {title="Ulathek",kind="Personaje",aliases={"Ulathek"},body="Ulathek es un sirviente de Lord Pesadilla establecido en la Guarida Sombría. Forma parte del círculo de subordinados de un poder demoníaco cuyas rivalidades se extienden hasta Xoroth.",aliasQuestIDs={},en={title="Ulathek",aliases={"Ulathek"},body="Ulathek is a servant of Lord Banehollow based in Shadow Hold. He belongs to the circle of followers around a demonic power whose rivalries reach as far as Xoroth.",aliasQuestIDs={}},fr={title="Ulathek",body="Ulathek est un serviteur de Lord Banehollow basé dans Shadow Hold. Il appartient au cercle des suiveurs autour d'un pouvoir démoniaque dont les rivalités atteignent Xoroth."},de={title="Ulathek",body="Ulathek ist ein Diener von Lord Banehollow aus Shadow Hold. Er gehört zum Kreis der Anhänger einer dämonischen Macht, deren Rivalitäten bis zu Xoroth reichen."},pt={title="Ulathek",body="Ulathek é um servo de Lord Banehollow baseado em Shadow Hold. Ele pertence ao círculo de seguidores em torno de um poder demoníaco cujas rivalidades chegam até Xoroth."},pl={title="Ulathek",body="Ulathek jest sługą postaci Lord Banehollow działającym z Shadow Hold. Należy do kręgu wyznawców demonicznej potęgi, której rywalizacje sięgają aż do Xoroth."},ru={title="Ulathek",body="Ulathek - слуга Lord Banehollow, базирующийся в Shadow Hold. Он принадлежит к кругу последователей демонической силы, соперничество которой достигает Xoroth."},references={["person:lord-banehollow"]=true}},
    ["person:umber"] = {title="Umber",kind="Personaje",aliases={"Umber"},body="Umber es el archivista del Círculo Cenarion en Amparo de la Noche. Su habilidad para recuperar libros dañados permite estudiar testimonios del pasado incluso cuando solo quedan vestigios muy deteriorados.",aliasQuestIDs={},en={title="Umber",aliases={"Umber"},body="Umber is the Cenarion Circle’s archivist in Nighthaven. His ability to restore damaged books allows accounts of the past to be studied even when only badly deteriorated remains survive.",aliasQuestIDs={}},fr={title="Umber",body="Umber est l’archiviste du Cenarion Circle dans Nighthaven. Sa capacité à restaurer des livres endommagés permet d'étudier les récits du passé même lorsque seuls des restes gravement détériorés survivent."},de={title="Umber",body="Umber ist der Archivar des Cenarion Circle in Nighthaven. Seine Fähigkeit, beschädigte Bücher zu restaurieren, ermöglicht es, Berichte der Vergangenheit zu studieren, selbst dann, wenn nur noch schwer beschädigte Überreste Überreste überleben."},pt={title="Umber",body="Umber é arquivista do Cenarion Circle no Nighthaven. Sua capacidade de restaurar livros danificados permite que relatos do passado sejam estudados mesmo quando apenas os restos gravemente deteriorados sobrevivem."},pl={title="Umber",body="Umber jest archiwistą Cenarion Circle w Nighthaven. Umiejętność odnawiania zniszczonych ksiąg pozwala badać relacje z przeszłości nawet wtedy, gdy zachowały się tylko mocno uszkodzone pozostałości."},ru={title="Umber",body="Umber - архивист Cenarion Circle  в Nighthaven. Благодаря его способности восстанавливать поврежденные книги можно изучать истории, даже если сохранились только сильно испорченные останки."},references={["organization:cenarion-circle"]=true,["place:nighthaven"]=true},questIDs={[6844]=true,[6845]=true}},
    ["person:umbranse-the-spiritspeaker"] = {title="Umbranse el Hablaalmas",kind="Personaje",aliases={"Umbranse","Umbranse el Hablaalmas"},body="Umbranse el Hablaalmas es un médium humano de las tierras orientales de Cuna del Invierno. Su capacidad de comunicarse con los muertos lo convierte en aliado de quienes buscan hablar con espíritus que no pueden alcanzar por medios ordinarios.",aliasQuestIDs={},en={title="Umbranse the Spiritspeaker",aliases={"Umbranse","Umbranse the Spiritspeaker"},body="Umbranse the Spiritspeaker is a human medium in eastern Winterspring. His ability to communicate with the dead makes him an ally to those seeking contact with spirits beyond ordinary reach.",aliasQuestIDs={}},fr={title="Umbranse the Spiritspeaker",body="Umbranse the Spiritspeaker est un milieu humain dans l'est de Winterspring. Sa capacité à communiquer avec les morts fait de lui un allié pour ceux qui cherchent le contact avec des esprits hors de portée ordinaire."},de={title="Umbranse the Spiritspeaker",body="Umbranse the Spiritspeaker ist ein menschliches Medium im östlichen Winterspring. Seine Fähigkeit, mit Toten zu kommunizieren, macht ihn zu einem Verbündeten für diejenigen, die den Kontakt mit Geistern suchen, die außerhalb der gewöhnlichen Reichweite suchen."},pt={title="Umbranse the Spiritspeaker",body="Umbranse the Spiritspeaker é um meio humano no leste de Winterspring. Sua capacidade de se comunicar com os mortos faz dele um aliado para aqueles que procuram contato com espíritos além do alcance comum."},pl={title="Umbranse the Spiritspeaker",body="Umbranse the Spiritspeaker jest ludzkim medium we wschodnim Winterspring. Zdolność porozumiewania się ze zmarłymi czyni go sojusznikiem osób szukających kontaktu z duchami poza zwykłym zasięgiem."},ru={title="Umbranse the Spiritspeaker",body="Umbranse the Spiritspeaker - это человеческий медиум в восточной части Winterspring. Его способность общаться с мертвыми делает его союзником тех, кто стремится связаться с духом."},references={["place:winterspring"]=true}},
    ["person:umi-rumplesnicker"] = {title="Umi Risitas",kind="Personaje",aliases={"Umi","Umi Risitas"},body="Umi Risitas es una inventora de Vista Eterna. Su proyecto de construir un yeti mecánico combina la curiosidad por la ingeniería con el deseo de sorprender a sus amigos.",aliasQuestIDs={},en={title="Umi Rumplesnicker",aliases={"Umi","Umi Rumplesnicker"},body="Umi Rumplesnicker is an inventor in Everlook. Her project to build a mechanical yeti combines an interest in engineering with a wish to surprise her friends.",aliasQuestIDs={}},fr={title="Umi Rumplesnicker",body="Umi Rumplesnicker est un inventeur de Everlook. Son projet de construction d’un yéti mécanique combine un intérêt pour l’ingénierie avec un désir de surprendre ses amis."},de={title="Umi Rumplesnicker",body="Umi Rumplesnicker ist Erfinderin in Everlook. Ihr Projekt, einen mechanischen Yeti zu bauen, verbindet technisches Interesse mit dem Wunsch, ihre Freunde zu überraschen."},pt={title="Umi Rumplesnicker",body="Umi Rumplesnicker é um inventor do Everlook. Seu projeto para construir um yeti mecânico combina um interesse em engenharia com um desejo de surpreender seus amigos."},pl={title="Umi Rumplesnicker",body="Umi Rumplesnicker jest wynalazczynią w Everlook. Jej projekt budowy mechanicznego yeti łączy zainteresowanie inżynierią z pragnieniem zaskoczenia przyjaciół."},ru={title="Umi Rumplesnicker",body="Umi Rumplesnicker - изобретатель Everlook. Ее проект по созданию механического йети сочетает в себе интерес к инженерным технологиям и желание удивить друзей."},references={["place:everlook"]=true}},
    ["person:urkyo"] = {title="Ur'kyo",kind="Personaje",aliases={"Ur'kyo","Ur’kyo"},body="Ur'kyo es un sacerdote trol del Valle de los Espíritus de Orgrimmar. Conduce ritos de paso mediante los que otros sacerdotes aprenden habilidades y se incorporan más plenamente a las costumbres de su tribu.",aliasQuestIDs={},en={title="Ur'kyo",aliases={"Ur'kyo","Ur’kyo"},body="Ur'kyo is a troll priest in Orgrimmar’s Valley of Spirits. He conducts rites of passage through which other priests learn abilities and become more fully involved in their tribe’s customs.",aliasQuestIDs={}},fr={title="Ur'kyo",body="Ur'kyo est un prêtre troll dans Orgrimmar’s Valley of Spirits. Il conduit des rites de passage par lesquels d’autres prêtres acquièrent des capacités et s’impliquent davantage dans les coutumes de leur tribu."},de={title="Ur'kyo",body="Ur'kyo ist ein Trollpriester in Orgrimmar’s Valley of Spirits. Er führt Übergangsriten durch, durch die andere Priester Fähigkeiten erlernen und sich stärker in die Bräuche ihres Stammes einbinden."},pt={title="Ur'kyo",body="Ur'kyo é um padre troll em Orgrimmar’s Valley of Spirits. Ele conduz ritos de passagem através dos quais outros sacerdotes aprendem habilidades e se envolvem mais plenamente nos costumes de sua tribo."},pl={title="Ur'kyo",body="Ur'kyo jest trollim kapłanem w miejscu zwanym Orgrimmar’s Valley of Spirits. Prowadzi obrzędy przejścia, dzięki którym inni kapłani poznają zdolności i pełniej uczestniczą w zwyczajach swojego plemienia."},ru={title="Ur'kyo",body="Ur'kyo - жрец троллей в Orgrimmar’s Valley of Spirits. Он проводит обряды перехода, благодаря которым другие жрецы получают знания и становятся более полно вовлеченными в обычаи своего племени."},references={["place:orgrimmar"]=true,["place:valley-of-spirits"]=true}},
    ["person:ursal-the-mauler"] = {title="Ursal el Violento",kind="Personaje",aliases={"Ursal","Ursal el Violento"},body="Ursal el Violento es una presencia maldita entre los Tuercepinos. Ha interferido con la llamada de los druidas de la Garfa, vinculando su amenaza con el sueño del que los druidas intentan despertar.",aliasQuestIDs={},en={title="Ursal the Mauler",aliases={"Ursal","Ursal the Mauler"},body="Ursal the Mauler is a cursed presence among the Gnarlpine. He has interfered with the calling of the Druids of the Talon, linking his threat to the sleep from which the druids seek to wake.",aliasQuestIDs={}},fr={title="Ursal the Mauler",body="Ursal the Mauler est une présence maudite parmi les Gnarlpine. Il a interféré avec l'appel du Druids de la Talon, reliant sa menace au sommeil dont les druides cherchent à se réveiller."},de={title="Ursal the Mauler",body="Ursal the Mauler ist eine verfluchte Präsenz unter den Gnarlpine. Er hat sich in die Berufung des Druids vom Talon eingemischt und seine Bedrohung mit dem Schlaf verknüpft, aus dem die die die die Druiden zu wecken suchen."},pt={title="Ursal the Mauler",body="Ursal the Mauler é uma presença amaldiçoada entre o Gnarlpine. Ele interferiu com o chamado do Druids do Talon, ligando sua ameaça ao sono do qual os druidas procuram acordar."},pl={title="Ursal the Mauler",body="Ursal the Mauler jest przeklętą obecnością wśród Gnarlpine. Zakłócił powołanie Druids of the Talon, wiążąc zagrożenie ze snem, z którego druidzi próbują się obudzić."},ru={title="Ursal the Mauler",body="Ursal the Mauler - это проклятое присутствие среди Gnarlpine. Он помешал вызову Druids из Talon, связывая свою угрозу со сном, из которого друиды пытаются проснуться."},references={["organization:gnarlpine"]=true}},
    ["person:ursanah"] = {title="Urs'anah",kind="Personaje",aliases={"Urs'anah","Urs’anah"},body="Urs'anah es la matriarca de los ursera que habitan las cuevas al oeste de Arboleda Thendal. Los forestales del poblado utilizan ese nombre para distinguir a la madre del cubil. Su presencia está asociada a una zona peligrosa para quienes se adentran en las cavernas.",aliasQuestIDs={},en={title="Urs'anah",aliases={"Urs'anah","Urs’anah"},body="Urs'anah is the matriarch of the ursera living in the caves west of Thendal Grove. The settlement's rangers use that name to distinguish the den mother. Her presence marks a dangerous area for anyone venturing into the caverns.",aliasQuestIDs={}},fr={title="Urs'anah",body="Urs'anah est la matriarche de l'ursera vivant dans les grottes à l'ouest de Thendal Grove. Les rangers du village utilisent ce nom pour distinguer la mère de la tanière. Sa présence marque une zone dangereuse pour quiconque s'aventure dans les cavernes."},de={title="Urs'anah",body="Urs'anah ist die Matriarchin der Ursera, die in, die in der Höhlen westlich von Thendal Grove lebt. Die Ranger der Siedlung verwenden diesen Namen, um die Mutter zu unterscheiden. Ihre Anwesenheit markiert ein gefährliches Gebiet für jeden, der sich in die Höhlen wagt."},pt={title="Urs'anah",body="Urs'anah é a matriarca da ursera que vive nas cavernas a oeste de Thendal Grove. Os guardas florestais do assentamento usam esse nome para distinguir a mãe den. Sua presença marca uma área perigosa para qualquer um que se aventurar nas cavernas."},pl={title="Urs'anah",body="Urs'anah jest matriarchinią ursera zamieszkujących jaskinie na zachód od Thendal Grove. Strażnicy osady używają tego imienia, by odróżnić matkę stada. Jej obecność wyznacza niebezpieczny obszar dla wchodzących do jaskiń."},ru={title="Urs'anah",body="Urs'anah - матриарх Ursera, живущий в пещерах к западу от Thendal Grove. Рейнджеры поселения используют это название, чтобы отличить мать-колыбели. Её присутствие знаменует опасность для всех, кто захочет войти в пещеры."},references={["place:thendal-grove"]=true}},
    ["person:ursangous"] = {title="Ursangous",kind="Personaje",aliases={"Ursangous"},body="Ursangous es un gran oso de Vallefresno. Su nombre forma parte de la tradición de caza del bosque, en la que los trofeos de criaturas extraordinarias sirven como símbolos de destreza.",aliasQuestIDs={},en={title="Ursangous",aliases={"Ursangous"},body="Ursangous is a great bear in Ashenvale. His name is part of the forest’s hunting tradition, in which trophies from remarkable creatures serve as symbols of skill.",aliasQuestIDs={}},fr={title="Ursangous",body="Ursangous est un excellent ours en Ashenvale. Son nom fait partie de la tradition de chasse de la forêt, dans laquelle les trophées de créatures remarquables servent de symboles d’habileté."},de={title="Ursangous",body="Ursangous ist ein großer Bär in Ashenvale. Sein Name ist Teil der Jagdtradition des Waldes Waldes, in dem Trophäen bemerkenswerter Lebewesen als Symbol für Geschicklichkeit dienen."},pt={title="Ursangous",body="Ursangous é um grande urso em Ashenvale. Seu nome faz parte da tradição de caça da floresta, na qual troféus de criaturas notáveis servem como símbolos de habilidade."},pl={title="Ursangous",body="Ursangous jest wielkim niedźwiedziem w Ashenvale. Jego imię należy do miejscowej tradycji łowieckiej, w której trofea niezwykłych stworzeń symbolizują umiejętności."},ru={title="Ursangous",body="Ursangous - отличный медведь в Ashenvale. Его имя является частью охотничьей традиции леса, в которой трофеи от замечательных существ служат символом мастерства."},references={["place:ashenvale"]=true}},
    ["person:ursius"] = {title="Ursius",kind="Personaje",aliases={"Ursius"},body="Ursius es un oso Dentoesquirla de las colinas al noroeste de Vista Eterna. Ágil e inteligente, es conocido por invertir los papeles de una cacería y convertir en presas a quienes intentan perseguirlo.",aliasQuestIDs={},en={title="Ursius",aliases={"Ursius"},body="Ursius is a shardtooth bear of the hills northwest of Everlook. Agile and clever, he is known for reversing a hunt and turning those who pursue him into prey.",aliasQuestIDs={}},fr={title="Ursius",body="Ursius est un ours en dents de scie des collines au nord-ouest de Everlook. Agile et intelligent, il est connu pour inverser une chasse et transformer ceux qui le poursuivent en proie."},de={title="Ursius",body="Ursius ist ein Scherbenzahnbär der Hügel nordwestlich von Everlook. Er ist agil und schlau und dafür bekannt, eine Jagd umzukehren und diejenigen, die ihn verfolgen zur Beute zu machen."},pt={title="Ursius",body="Ursius é um urso shardtooth das colinas a noroeste de Everlook. Agile e inteligente, ele é conhecido por reverter uma caçada e transformar aqueles que o perseguem em presas."},pl={title="Ursius",body="Ursius jest niedźwiedziem ostrych zębów ze wzgórz na północny zachód od Everlook. Zwinny i sprytny, znany jest z odwracania łowów i zamieniania prześladowców w ofiary."},ru={title="Ursius",body="Ursius - это медведь с осколочным зубом, живущий на северо-западе от Everlook. Он ловкий и хитрый, он известен тем, что может отменить охоту и превратить преследующих в добычу."},references={["place:everlook"]=true}},
    ["person:uthek-the-wise"] = {title="Uthek la Sabia",kind="Personaje",aliases={"Uthek","Uthek la Sabia","Uthek la sabia"},body="Uthek la Sabia es una chamana de los Gelkis de Desolace. Su posición la convierte en una interlocutora para quienes intentan ganarse la confianza del clan y comprender sus rivalidades.",aliasQuestIDs={},en={title="Uthek the Wise",aliases={"Uthek","Uthek the Wise"},body="Uthek the Wise is a shaman of the Gelkis in Desolace. Her position makes her a contact for those trying to earn the clan’s trust and understand its rivalries.",aliasQuestIDs={}},fr={title="Uthek the Wise",body="Uthek the Wise est un chaman du Gelkis dans Desolace. Sa position fait d’elle un contact pour ceux qui essaient de gagner la confiance du clan et de comprendre ses rivalités."},de={title="Uthek the Wise",body="Uthek the Wise ist eine Schamanin der Gelkis in Desolace. Ihre Position macht sie zu einem Ansprechpartner für diejenigen, die versuchen, das Vertrauen des Clans zu gewinnen und seine Rivalitäten zu verstehen."},pt={title="Uthek the Wise",body="Uthek the Wise é um xamã do Gelkis em Desolace. Sua posição faz dela um contato para aqueles que tentam ganhar a confiança do clã e entender suas rivalidades."},pl={title="Uthek the Wise",body="Uthek the Wise jest szamanką klanu Gelkis w Desolace. Jej pozycja czyni ją kontaktem dla osób próbujących zdobyć zaufanie klanu i zrozumieć jego rywalizacje."},ru={title="Uthek the Wise",body="Uthek the Wise - шаман Gelkis в Desolace. Ее положение делает ее контактом для тех, кто пытается завоевать доверие клана и понять его соперничество."},references={["organization:gelkis"]=true,["place:desolace"]=true}},
    ["person:uthelnay"] = {title="Uthel'nay",kind="Personaje",aliases={"Uthel'nay","Uthel’nay"},body="Uthel'nay es un mago de la Cabaña de Brezo de Orgrimmar. Otros miembros de la Horda recurren a él para interpretar objetos arcanos cuyo funcionamiento supera los conocimientos de un combatiente.",aliasQuestIDs={},en={title="Uthel'nay",aliases={"Uthel'nay","Uthel’nay"},body="Uthel'nay is a mage in Orgrimmar’s Spirit Lodge. Other Horde members turn to him to interpret arcane objects whose workings exceed a fighter’s knowledge.",aliasQuestIDs={}},fr={title="Uthel'nay",body="Uthel'nay est un mage du Spirit Lodge de Orgrimmar. D’autres membres de Horde se tournent vers lui pour interpréter des objets obscurs dont le fonctionnement dépasse les connaissances d’un combattant."},de={title="Uthel'nay",body="Uthel'nay ist ein Magier in Orgrimmar 's Spirit Lodge. Andere Horde-Mitglieder wenden sich an ihn, um obskure Objekte zu interpretieren, deren Funktionsweise das Wissen eines Kämpfers übersteigt."},pt={title="Uthel'nay",body="Uthel'nay é um mago na Loja Espiritual da Orgrimmar. Outros membros do Horde recorrem a ele para interpretar objetos arcanos cujo funcionamento excede o conhecimento de um lutador."},pl={title="Uthel'nay",body="Uthel'nay jest magiem w Spirit Lodge w Orgrimmar. Inni członkowie frakcji Horde zwracają się do niego, by odczytywać tajniki przedmiotów arkana wykraczające poza wiedzę wojownika."},ru={title="Uthel'nay",body="Uthel'nay - магический маг в Духовной Ложе Orgrimmar. Другие члены Horde обращаются к нему, чтобы интерпретировать таинственные объекты, работа которых превышает знания бойца."},references={["organization:horde"]=true,["place:orgrimmar"]=true}},
    ["person:uzzek"] = {title="Uzzek",kind="Personaje",aliases={"Uzzek"},body="Uzzek es un veterano de muchas batallas que enseña a los guerreros jóvenes de la Horda. Imparte sus lecciones cerca de la frontera entre Los Baldíos y Durotar, donde recuerda que la fuerza también exige estudio.",aliasQuestIDs={},en={title="Uzzek",aliases={"Uzzek"},body="Uzzek is a veteran of many battles who teaches the Horde’s young warriors. He gives instruction near the border between the Barrens and Durotar, where his work reflects the belief that strength also requires study.",aliasQuestIDs={}},fr={title="Uzzek",body="Uzzek est un vétéran de nombreuses batailles qui enseigne les jeunes guerriers de la Horde. Il donne des instructions près de la frontière entre le Barrens et Durotar, où son travail reflète la conviction que la force nécessite également l'étude."},de={title="Uzzek",body="Uzzek ist ein Veteran vielen Schlachten und lehrt die jungen Krieger des Horde. Er gibt Unterricht nahe der Grenze zwischen Barrens und Durotar, wo seine Arbeit den Glauben widerspiegelt, dass Stärke auch Studium erfordert."},pt={title="Uzzek",body="Uzzek é um veterano de muitas batalhas que ensina os jovens guerreiros do Horde. Ele dá instruções perto da fronteira entre o Barrens e Durotar, onde seu trabalho reflete a crença de que a força também requer estudo."},pl={title="Uzzek",body="Uzzek jest weteranem wielu bitew szkolącym młodych wojowników frakcji Horde. Naucza przy granicy Barrens i Durotar, odzwierciedlając przekonanie, że siła wymaga także nauki."},ru={title="Uzzek",body="Uzzek - ветеран многих сражений, который обучает молодых воинов Horde. Он дает инструкции вблизи границы между Barrens и Durotar, где его работа отражает убеждение, что сила также требует изучения."},references={["organization:horde"]=true,["place:durotar"]=true,["place:the-barrens"]=true}},
    ["person:vahlarriel-demonslayer"] = {title="Vahlarriel Destripademonios",kind="Personaje",aliases={"Vahlarriel","Vahlarriel Destripademonios"},body="Vahlarriel Destripademonios es un elfo de la noche destinado en Desolace. Trabaja para localizar a viajeros desaparecidos de familias de Darnassus, manteniendo contacto con quienes esperan noticias de ellos.",aliasQuestIDs={},en={title="Vahlarriel Demonslayer",aliases={"Vahlarriel","Vahlarriel Demonslayer"},body="Vahlarriel Demonslayer is a night elf stationed in Desolace. He works to locate missing travelers from Darnassus families, maintaining contact with those awaiting news of them.",aliasQuestIDs={}},fr={title="Vahlarriel Demonslayer",body="Vahlarriel Demonslayer est un elfe de nuit stationné à Desolace. Il travaille à localiser les voyageurs disparus des familles Darnassus, en maintenant le contact avec ceux qui attendent des nouvelles d'eux."},de={title="Vahlarriel Demonslayer",body="Vahlarriel Demonslayer ist ein Nachtelf, der in Desolace stationiert ist. Er sucht nach vermissten Reisenden aus Familien von Darnassus und hält Kontakt zu jenen, die auf Nachrichten über sie warten."},pt={title="Vahlarriel Demonslayer",body="Vahlarriel Demonslayer é um elfo noturno estacionado em Desolace. Ele trabalha para localizar viajantes desaparecidos das famílias Darnassus, mantendo contato com aqueles que aguardam notícias deles."},pl={title="Vahlarriel Demonslayer",body="Vahlarriel Demonslayer jest nocnym elfem stacjonującym w Desolace. Stara się odnaleźć zaginionych podróżnych z rodzin Darnassus, utrzymując kontakt z osobami oczekującymi wieści."},ru={title="Vahlarriel Demonslayer",body="Vahlarriel Demonslayer - это ночной эльф, дислоцированный в Desolace. Он работает над поиском пропавших путешественников из семей Darnassus, поддерживая связь с теми, кто ждет новостей от них."},references={["place:darnassus"]=true,["place:desolace"]=true}},
    ["person:valennia-stormfist"] = {title="Valennia Puñotormenta",kind="Personaje",aliases={"Valennia","Valennia Puñotormenta"},body="Valennia Puñotormenta dirige a los pacificadores de Isla Zephras desde Valanaar. Recibe información de comunidades como Shen'dar para evaluar las amenazas del culto y preparar la defensa de la ciudad. Su cargo la vincula con la seguridad de la isla y la coordinación entre sus poblados.",aliasQuestIDs={},en={title="Valennia Stormfist",aliases={"Valennia","Valennia Stormfist"},body="Valennia Stormfist leads the peacekeepers of Zephras Isle from Valanaar. She receives information from communities such as Shen'dar to assess the cult's threats and prepare the city's defenses. Her role connects the island's security with coordination among its settlements.",aliasQuestIDs={}},fr={title="Valennia Stormfist",body="Valennia Stormfist dirige les forces de maintien de la paix de Zephras Isle depuis Valanaar. Elle reçoit des informations de communautés telles que Shen'dar pour évaluer les menaces du culte et préparer les défenses de la ville. Son rôle relie la sécurité de l'île à la coordination entre ses colonies."},de={title="Valennia Stormfist",body="Valennia Stormfist führt die Friedenstruppen von Zephras Isle von Valanaar aus an. Sie erhält Informationen von Gemeinschaften wie Shen'dar, um die Bedrohungen durch den Kult einzuschätzen und die Verteidigung der Stadt vorzubereiten. Ihre Rolle verbindet die Sicherheit der Insel mit der Koordinierung ihrer Siedlungen untereinander."},pt={title="Valennia Stormfist",body="Valennia Stormfist lidera as forças de paz do Zephras Isle da Valanaar. Ela recebe informações de comunidades como Shen'dar para avaliar as ameaças do culto e preparar as defesas da cidade. Seu papel conecta a segurança da ilha com a coordenação entre seus assentamentos."},pl={title="Valennia Stormfist",body="Valennia Stormfist dowodzi strażnikami pokoju Zephras Isle z Valanaar. Otrzymuje informacje od społeczności takich jak Shen'dar, by oceniać zagrożenia kultu i przygotowywać obronę miasta. Jej rola łączy bezpieczeństwo wyspy z koordynacją osad."},ru={title="Valennia Stormfist",body="Valennia Stormfist возглавляет миротворцев Zephras Isle из Valanaar. Она получает информацию от сообществ, таких как Shen'dar, чтобы оценить угрозы секты и подготовить защиту города. Ее роль связывает безопасность острова с координацией между его поселениями."},references={["place:shendar"]=true,["place:valanaar"]=true,["place:zephras"]=true}},
    ["person:vargus"] = {title="Vargus",kind="Personaje",aliases={"Vargus"},body="Vargus es un herrero del Fuerte Cenarion en Silithus. Proporciona equipo a quienes colaboran con la defensa del desierto, vinculando su oficio a las necesidades de los combatientes.",aliasQuestIDs={},en={title="Vargus",aliases={"Vargus"},body="Vargus is a blacksmith at Cenarion Hold in Silithus. He supplies equipment to those assisting in the desert’s defense, connecting his craft with the needs of its fighters.",aliasQuestIDs={}},fr={title="Vargus",body="Vargus est un forgeron chez Cenarion Hold dans Silithus. Il fournit du matériel à ceux qui aident à la défense du désert, reliant son vaisseau aux besoins de ses combattants."},de={title="Vargus",body="Vargus ist Schmied bei Cenarion Hold in Silithus. Er liefert Ausrüstung an diejenigen, die bei der Verteidigung der Wüste helfen, und verbindet sein Boot mit den Bedürfnissen seiner Kämpfer."},pt={title="Vargus",body="Vargus é um ferreiro na Cenarion Hold em Silithus. Ele fornece equipamentos para aqueles que auxiliam na defesa do deserto, conectando seu ofício com as necessidades de seus combatentes."},pl={title="Vargus",body="Vargus jest kowalem w Cenarion Hold w Silithus. Dostarcza wyposażenie osobom pomagającym w obronie pustyni, łącząc swoje rzemiosło z potrzebami jej wojowników."},ru={title="Vargus",body="Vargus работает кузнецом в Cenarion Hold на территории Silithus. Он снабжает оборудованием тех, кто помогает в обороне пустыни, соединяя свое ремесло с потребностями его бойцов."},references={["place:cenarion-hold"]=true,["place:silithus"]=true}},
    ["person:vartrus-the-ancient"] = {title="Vartrus el Ancestro",kind="Personaje",aliases={"Vartrus","Vartrus el Ancestro"},body="Vartrus el Ancestro es un antiguo de Frondavil preocupado por la presencia de la Legión Ardiente. Busca a quienes puedan responder a los demonios que marchitan la naturaleza con su influencia.",aliasQuestIDs={},en={title="Vartrus the Ancient",aliases={"Vartrus","Vartrus the Ancient"},body="Vartrus the Ancient is an ancient in Felwood concerned with the Burning Legion’s presence. He seeks those capable of answering demons whose influence withers nature.",aliasQuestIDs={}},fr={title="Vartrus the Ancient",body="Vartrus the Ancient est un ancien dans Felwood concerné par la présence de la Burning Legion. Il cherche ceux qui sont capables de répondre à des démons dont l’influence flétrit la nature."},de={title="Vartrus the Ancient",body="Vartrus the Ancient ist ein Uralter in Felwood, der sich um die Anwesenheit des Burning Legion sorgt. Er sucht diejenigen, die in der Lage sind, Dämonen zu antworten, deren Einfluss die die die Natur verwelkt."},pt={title="Vartrus the Ancient",body="Vartrus the Ancient é um antigo Felwood preocupado com a presença do Burning Legion. Ele procura aqueles capazes de responder a demônios cuja influência murcha a natureza."},pl={title="Vartrus the Ancient",body="Vartrus the Ancient jest pradawnym w Felwood zaniepokojonym obecnością Burning Legion. Szuka osób zdolnych przeciwstawić się demonom, których wpływ powoduje więdnięcie natury."},ru={title="Vartrus the Ancient",body="Vartrus the Ancient - древний в Felwood, связанный с присутствием Burning Legion s. Он ищет тех, кто способен отвечать демонам, чье влияние сжигает природу."},references={["organization:burning-legion"]=true,["place:felwood"]=true}},
    ["person:vaxug-firefure"] = {title="Va'xug",kind="Personaje",aliases={"Va'xug","Va’xug"},body="Va'xug es un practicante de magia que recorre Vallefresno. Emplea un ojo de Kilrogg para explorar caminos, aunque mantener la visión exige una concentración que no puede prolongar indefinidamente.",aliasQuestIDs={},en={title="Va'xug",aliases={"Va'xug","Va’xug"},body="Va'xug is a magic user traveling Ashenvale. He uses an Eye of Kilrogg to scout routes, although maintaining the vision requires concentration that cannot last indefinitely.",aliasQuestIDs={}},fr={title="Va'xug",body="Va'xug est un utilisateur magique voyageant Ashenvale. Il utilise un Eye of Kilrogg pour repérer les routes, bien que le maintien de la vision nécessite une concentration qui ne peut pas durer indéfiniment."},de={title="Va'xug",body="Va'xug ist ein magischer Benutzer, der Ashenvale bereist. Er benutzt einen Eye of Kilrogg, um Routen zu erkunden, obwohl die Aufrechterhaltung der Vision Konzentration erfordert, die nicht ewig dauern kann."},pt={title="Va'xug",body="Va'xug é um usuário mágico que viaja Ashenvale. Ele usa um Eye of Kilrogg para rastrear rotas, embora a manutenção da visão exija concentração que não pode durar indefinidamente."},pl={title="Va'xug",body="Va'xug jest użytkownikiem magii przemierzającym Ashenvale. Wykorzystuje Eye of Kilrogg do rozpoznawania szlaków, choć utrzymanie wizji wymaga skupienia, którego nie sposób zachować bez końca."},ru={title="Va'xug",body="Va'xug - это волшебник, путешествующий Ashenvale. Он использует Eye of Kilrogg для разведки маршрутов, хотя поддержание зрения требует концентрации, которая не может длиться вечно."},references={["object:eye-of-kilrogg"]=true,["place:ashenvale"]=true}},
    ["person:vayn-moonclaw"] = {title="Vayn Zarpaluna",kind="Personaje",aliases={"Vayn","Vayn Zarpaluna"},body="Vayn Zarpaluna pertenece a una orden de druidas que vive en el Bosque Ventarrosombra. Busca preservar la tranquilidad de su comunidad frente a las amenazas del Culto de Al'Aketh. Ofrece un punto de contacto con la orden para quienes desean ayudar a sus miembros.",aliasQuestIDs={},en={title="Vayn Moonclaw",aliases={"Vayn","Vayn Moonclaw"},body="Vayn Moonclaw belongs to a druid order living in Shadowgale Forest. This druid seeks to preserve his community's peace against threats from the Al'Aketh Cult. Vayn acts as a point of contact with people offering help to the order's members.",aliasQuestIDs={}},fr={title="Vayn Moonclaw",body="Vayn Moonclaw appartient à un ordre de druides vivant dans la forêt Shadowgale. Ce druide cherche à préserver la paix de sa communauté contre les menaces du Al'Aketh Cult. Vayn agit comme un point de contact avec les personnes offrant de l'aide aux membres de l'ordre."},de={title="Vayn Moonclaw",body="Vayn Moonclaw gehört einem Druidenorden in Shadowgale Forest lebenden Orden an. Dieser Druide ist bestrebt, den Frieden seiner Gemeinschaft gegen Bedrohungen durch die Al'Aketh Cult zu bewahren. Vayn fungiert als Kontaktperson zu Menschen, die den Ordensmitgliedern Hilfe anbieten."},pt={title="Vayn Moonclaw",body="Vayn Moonclaw pertence a uma ordem de druida que vive na Floresta Shadowgale. Este druida procura preservar a paz de sua comunidade contra ameaças do Al'Aketh Cult. Vayn atua como um ponto de contato com pessoas que oferecem ajuda aos membros da ordem."},pl={title="Vayn Moonclaw",body="Vayn Moonclaw należy do zakonu druidów żyjącego w Shadowgale Forest. Ten druid próbuje zachować spokój swojej społeczności wobec zagrożeń Al'Aketh Cult. Vayn jest kontaktem dla osób oferujących pomoc członkom zakonu."},ru={title="Vayn Moonclaw",body="Vayn Moonclaw принадлежит к ордену друидов, живущих в лесу Shadowgale. Этот друид стремится сохранить мир своей общины против угроз от Al'Aketh Cult. Vayn действует как точка контакта с людьми, предлагающими помощь членам ордена."},references={["organization:al-aketh"]=true}},
    ["person:vazario-linkgrease"] = {title="Vazario Grasenlace",kind="Personaje",aliases={"Vazario","Vazario Grasenlace"},body="Vazario Grasenlace gestiona afiliaciones de ingeniería goblin. Su labor administrativa permite que los profesionales acreditados mantengan el acceso a los esquemas y conocimientos compartidos por sus instructores.",aliasQuestIDs={},en={title="Vazario Linkgrease",aliases={"Vazario","Vazario Linkgrease"},body="Vazario Linkgrease manages Goblin engineering memberships. His administrative work lets accredited practitioners retain access to the schematics and knowledge shared by their trainers.",aliasQuestIDs={}},fr={title="Vazario Linkgrease",body="Vazario Linkgrease gère les adhésions d'ingénierie Gobelin. Son travail administratif permet aux praticiens accrédités de conserver l’accès aux schémas et connaissances partagés par leurs formateurs."},de={title="Vazario Linkgrease",body="Vazario Linkgrease verwaltet Goblin Engineering Mitgliedschaften. Seine administrative Arbeit ermöglicht es akkreditierten Praktikern, Zugang zu den Schaltplänen und Kenntplänen zu erhalten, die von ihren Trainern geteilt werden."},pt={title="Vazario Linkgrease",body="Vazario Linkgrease gerencia associações de engenharia Goblin. Seu trabalho administrativo permite que os profissionais credenciados mantenham o acesso aos esquemas e conhecimentos compartilhados por seus treinadores."},pl={title="Vazario Linkgrease",body="Vazario Linkgrease zarządza członkostwem w goblińskiej inżynierii. Praca administracyjna pozwala uprawnionym adeptom zachowywać dostęp do schematów i wiedzy dzielonej przez nauczycieli."},ru={title="Vazario Linkgrease",body="Vazario Linkgrease управляет членством в инженерном корпусе Гоблинов. Его административная работа позволяет аккредитованным специалистам сохранить доступ к схемам и знаниям, которыми делятся их тренеры."},references={}},
    ["person:veenix"] = {title="Veenix",kind="Personaje",aliases={"Veenix"},body="Veenix mantiene contactos en Sierra Espolón capaces de ayudar a viajeros discretos. Su conocimiento de accesos y rutas lo relaciona con encargos que requieren entrar en lugares peligrosos sin llamar la atención.",aliasQuestIDs={},en={title="Veenix",aliases={"Veenix"},body="Veenix maintains contacts in the Stonetalon Mountains who can help discreet travelers. His knowledge of entrances and routes connects him with work requiring access to dangerous places without attracting attention.",aliasQuestIDs={}},fr={title="Veenix",body="Veenix maintient des contacts dans le Stonetalon Mountains qui peuvent aider les voyageurs discrets. Sa connaissance des entrées et des itinéraires le relie à un travail nécessitant l’accès à des lieux dangereux sans attirer l’attention."},de={title="Veenix",body="Veenix unterhält Kontakte im Stonetalon Mountains, die diskreten Reisenden helfen können. Sein Wissen über Zugänge und Routen verbindet ihn mit Arbeiten, die den Zugang zu gefährlichen Orten erfordern, ohne Aufmerksamkeit zu erregen."},pt={title="Veenix",body="Veenix mantém contatos no Stonetalon Mountains que podem ajudar viajantes discretos. Seu conhecimento de entradas e rotas conecta-o com o trabalho que requer acesso a lugares perigosos sem atrair a atenção."},pl={title="Veenix",body="Veenix utrzymuje kontakty w regionie Stonetalon Mountains, które mogą pomagać dyskretnym podróżnym. Znajomość wejść i szlaków wiąże go z pracą wymagającą dostępu do niebezpiecznych miejsc bez zwracania uwagi."},ru={title="Veenix",body="Veenix поддерживает контакты в Stonetalon Mountains, которые могут помочь дискретно путешествующим. Его знание входов и маршрутов связывает его с работой, требующей доступа к опасным местам без привлечения внимания."},references={["place:stonetalon-mountains"]=true}},
    ["person:velinde-starsong"] = {title="Velinde Cantoestelar",kind="Personaje",aliases={"Velinde","Velinde Cantoestelar"},body="Velinde Cantoestelar es una sacerdotisa elfa de la noche que trabajó para afrontar los problemas de los bosques de Vallefresno y Frondavil. Las centinelas respetan su servicio y conservan el diario en el que anotaba sus deberes.",aliasQuestIDs={},en={title="Velinde Starsong",aliases={"Velinde","Velinde Starsong"},body="Velinde Starsong is a night elf priestess who worked to address the troubles of Ashenvale and Felwood’s forests. The Sentinels respect her service and preserve the journal in which she recorded her duties.",aliasQuestIDs={}},fr={title="Velinde Starsong",body="Velinde Starsong est une prêtresse elfe de nuit qui a travaillé pour résoudre les problèmes des forêts de Ashenvale et Felwood. La Sentinels respecte son service et préserve le journal dans lequel elle a enregistré ses fonctions."},de={title="Velinde Starsong",body="Velinde Starsong ist eine Nachtelfen-Priesterin, die sich um die Probleme der Wälder von Ashenvale und Felwood kümmerte. Die Sentinels respektiert ihren Dienst und bewahrt das Tagebuch, in dem sie ihre Pflichten festgehalten hat."},pt={title="Velinde Starsong",body="Velinde Starsong é uma sacerdotisa elfa noturna que trabalhou para resolver os problemas das florestas de Ashenvale e Felwood. O Sentinels respeita seu serviço e preserva o diário em que ela registrou seus deveres."},pl={title="Velinde Starsong",body="Velinde Starsong jest kapłanką nocnych elfów, która starała się zaradzić problemom lasów Ashenvale i Felwood. Sentinels szanują jej służbę i przechowują dziennik, w którym zapisywała swoje obowiązki."},ru={title="Velinde Starsong",body="Velinde Starsong - это жрица-ночной эльфа, которая работала над решением проблем лесов Ashenvale и Felwood s. Sentinels уважают ее службу и хранят дневник, в котором она записывала свои обязанности."},references={["organization:night-elf-sentinels"]=true,["place:ashenvale"]=true,["place:felwood"]=true}},
    ["person:velrin-fang"] = {title="Vel'rin Colmillo",kind="Personaje",aliases={"Vel'rin","Vel'rin Colmillo","Vel’rin","Vel’rin Colmillo"},body="Vel'rin Colmillo prepara bienes con los pelajes de los tigres de Durotar. Su trabajo abastece de mantas, tiendas y protección a su pueblo, procurando equilibrar las necesidades de la comunidad con la conservación de las bestias.",aliasQuestIDs={},en={title="Vel'rin Fang",aliases={"Vel'rin","Vel'rin Fang","Vel’rin","Vel’rin Fang"},body="Vel'rin Fang makes goods from Durotar tiger furs. His work supplies his people with blankets, tents, and protection, balancing community needs with allowing the beasts to thrive.",aliasQuestIDs={}},fr={title="Vel'rin Fang",body="Vel'rin Fang fabrique des produits à partir de fourrures de tigre Durotar. Son travail fournit à son peuple des couvertures, des tentes et une protection, équilibrant les besoins de la communauté et permettant aux bêtes de prospérer."},de={title="Vel'rin Fang",body="Vel'rin Fang macht Waren aus Tigerfellen von Durotar. Seine Arbeit versorgt sein Volk mit Decken, Zelten und Schutz und bringt einen Ausgleich zwischen den Bedürfnissen der Gemeinschaft und dem Wohlergehen der Tiere."},pt={title="Vel'rin Fang",body="Vel'rin Fang faz produtos de peles de tigre Durotar. Seu trabalho abastece seu povo com cobertores, tendas e proteção, equilibrando as necessidades da comunidade com permitir que os animais prosperem."},pl={title="Vel'rin Fang",body="Vel'rin Fang wytwarza wyroby z futer tygrysów Durotar. Dostarcza ludowi koce, namioty i ochronę, równoważąc potrzeby społeczności z umożliwieniem bestiom pomyślnego życia."},ru={title="Vel'rin Fang",body="Vel'rin Fang производит товары из тигровых шкур Durotar. Его работа обеспечивает его людей одеялами, палатками и защитой, уравновешивая потребности сообщества с тем, чтобы животные процветали."},references={["place:durotar"]=true}},
    ["person:veren-tallstrider"] = {title="Veren Zancaalta",kind="Personaje",aliases={"Veren","Veren Zancaalta"},body="Veren Zancaalta trabaja con pieles en Cima del Trueno. Confecciona ropa y armaduras para su pueblo y transforma los frutos de la caza en protección para la comunidad.",aliasQuestIDs={},en={title="Veren Tallstrider",aliases={"Veren","Veren Tallstrider"},body="Veren Tallstrider works with hides in Thunder Bluff. He makes clothing and armor for his people, turning the results of the hunt into protection for the community.",aliasQuestIDs={}},fr={title="Veren Tallstrider",body="Veren Tallstrider travaille avec les peaux dans Thunder Bluff. Il fabrique des vêtements et des armures pour son peuple, transformant les résultats de la chasse en protection pour la communauté."},de={title="Veren Tallstrider",body="Veren Tallstrider arbeitet mit Verstecken in Thunder Bluff. Er fertigt Kleidung und Rüstungen für sein Volk und verwandelt die Ergebnisse der Jagd in Schutz für die Gemeinschaft."},pt={title="Veren Tallstrider",body="Veren Tallstrider trabalha com peles em Thunder Bluff. Ele faz roupas e armaduras para seu povo, transformando os resultados da caça em proteção para a comunidade."},pl={title="Veren Tallstrider",body="Veren Tallstrider pracuje ze skórami w Thunder Bluff. Wytwarza odzież i zbroje dla swojego ludu, zamieniając rezultaty polowania w ochronę społeczności."},ru={title="Veren Tallstrider",body="Veren Tallstrider работает с шкурами в Thunder Bluff. Он делает одежду и доспехи для своего народа, превращая результаты охоты в защиту для общества."},references={["place:thunder-bluff"]=true}},
    ["person:verog-the-dervish"] = {title="Verog el Derviche",kind="Personaje",aliases={"Verog","Verog el Derviche"},body="Verog el Derviche es un líder Kolkar que opera en torno al Oasis Estancado. Dirige sus fuerzas desde lugares protegidos, lo que dificulta que sus enemigos puedan acercarse a él directamente.",aliasQuestIDs={},en={title="Verog the Dervish",aliases={"Verog","Verog the Dervish"},body="Verog the Dervish is a Kolkar leader operating around the Stagnant Oasis. He directs his forces from protected positions, making it difficult for his enemies to reach him directly.",aliasQuestIDs={}},fr={title="Verog the Dervish",body="Verog the Dervish est un leader Kolkar opérant autour de l'Oasis Stagnant. Il dirige ses forces depuis des positions protégées, ce qui rend difficile pour ses ennemis de l'atteindre directement."},de={title="Verog the Dervish",body="Verog the Dervish ist ein Kolkar-Führer, der rund um die stagnierende Oase operiert. Er lenkt seine Truppen aus geschützten Stellungen, wodurch es seinen Feinden direkten Zugriff auf ihn erschwert."},pt={title="Verog the Dervish",body="Verog the Dervish é um líder Kolkar que opera em torno do Oásis Estagnado. Ele dirige suas forças de posições protegidas, tornando difícil para seus inimigos alcançá-lo diretamente."},pl={title="Verog the Dervish",body="Verog the Dervish jest przywódcą Kolkar działającym wokół stojącej oazy. Kieruje siłami z chronionych pozycji, utrudniając przeciwnikom bezpośrednie dotarcie do niego."},ru={title="Verog the Dervish",body="Verog the Dervish - лидер Kolkar, действующий вокруг Стаганного Оазиса. Он направляет свои войска из защищенных позиций, что мешает врагам достичь его напрямую."},references={["organization:kolkar"]=true}},
    ["person:vestia-moonspear"] = {title="Vestia Lanzaluna",kind="Personaje",aliases={"Vestia","Vestia Lanzaluna"},body="Vestia Lanzaluna es una sacerdotisa y estudiosa reconocida por su comunidad. Su erudición permite examinar reliquias antiguas, como las que aparecen en las Ruinas de Solarsal, para comprender su naturaleza.",aliasQuestIDs={},en={title="Vestia Moonspear",aliases={"Vestia","Vestia Moonspear"},body="Vestia Moonspear is a priestess and scholar respected by her community. Her learning allows her to examine ancient relics, including those found in the Ruins of Solarsal, to understand their nature.",aliasQuestIDs={}},fr={title="Vestia Moonspear",body="Vestia Moonspear est une prêtresse et une universitaire respectée par sa communauté. Son apprentissage lui permet d'examiner d'anciennes reliques, y compris celles trouvées dans les ruines de Solarsal, pour comprendre leur nature."},de={title="Vestia Moonspear",body="Vestia Moonspear ist eine Priesterin und Gelehrte, die von ihrer Gemeinschaft respektiert wird. Ihr Lernen ermöglicht es ihr, antike Relikte zu untersuchen, einschließlich jener, die in den Ruinen Solarsals gefunden wurden, um ihre Natur zu verstehen."},pt={title="Vestia Moonspear",body="Vestia Moonspear é uma sacerdotisa e estudiosa respeitada por sua comunidade. Seu aprendizado permite que ela examine relíquias antigas, incluindo aquelas encontradas nas Ruínas de Solarsal, para entender sua natureza."},pl={title="Vestia Moonspear",body="Vestia Moonspear jest kapłanką i uczoną szanowaną przez społeczność. Wiedza pozwala badać pradawne relikty, w tym znaleziska z ruin Solarsal, aby zrozumieć ich naturę."},ru={title="Vestia Moonspear",body="Vestia Moonspear - священница и ученый, уважаемый своей общиной. Ее знания позволяют ей исследовать древние реликвии, в том числе те, которые были найдены в руинах Solarsal, чтобы понять их природу."},references={}},
    ["person:vish-kozus"] = {title="Vish Kozus",kind="Personaje",aliases={"Vish Kozus"},body="Vish Kozus es capitán de la guardia del Fuerte Cenarion en Silithus. Entre sus responsabilidades está mantener equipada a su división montada, cuyas necesidades de protección deben atenderse incluso durante los combates.",aliasQuestIDs={},en={title="Vish Kozus",aliases={"Vish Kozus"},body="Vish Kozus is a captain of the guard at Cenarion Hold in Silithus. His responsibilities include keeping the mounted division equipped, meeting its protection needs even during fighting.",aliasQuestIDs={}},fr={title="Vish Kozus",body="Vish Kozus est capitaine de la garde à Cenarion Hold dans Silithus. Ses responsabilités comprennent le maintien de la division montée équipée, répondant à ses besoins de protection même pendant les combats."},de={title="Vish Kozus",body="Vish Kozus ist Kapitän der Wache bei Cenarion Hold in Silithus. Zu seinen Aufgaben gehört es, die berittene Division auszurüsten und ihre Schutzbedürfnisse auch während der Kämpfe zu erfüllen."},pt={title="Vish Kozus",body="Vish Kozus é um capitão da guarda na Cenarion Hold em Silithus. Suas responsabilidades incluem manter a divisão montada equipada, atendendo às suas necessidades de proteção, mesmo durante os combates."},pl={title="Vish Kozus",body="Vish Kozus jest kapitanem straży w Cenarion Hold w Silithus. Odpowiada między innymi za wyposażenie oddziału konnego, zaspokajając potrzeby jego ochrony nawet podczas walk."},ru={title="Vish Kozus",body="Vish Kozus - капитан охраны в Cenarion Hold в Silithus. Его обязанности включают обеспечение оснащенности конной дивизии, удовлетворение ее потребностей в защите даже во время боя."},references={["place:cenarion-hold"]=true,["place:silithus"]=true}},
    ["person:vizzklick"] = {title="Vizzklick",kind="Personaje",aliases={"Vizzklick"},body="Vizzklick vive en Gadgetzan y se preocupa por el comercio de la ciudad. Considera que las operaciones turbias de Kovic perjudican a los comerciantes honestos, una rivalidad donde las ganancias y los agravios personales se entrelazan.",aliasQuestIDs={},en={title="Vizzklick",aliases={"Vizzklick"},body="Vizzklick lives in Gadgetzan and takes an interest in its trade. He considers Kovic’s shady dealings harmful to honest merchants, a rivalry in which profit and personal grievances intertwine.",aliasQuestIDs={}},fr={title="Vizzklick",body="Vizzklick vit à Gadgetzan et s'intéresse à son commerce. Il considère que les transactions louches de Kovic nuisent aux marchands honnêtes, une rivalité dans laquelle le profit et les griefs personnels s’entremêlent."},de={title="Vizzklick",body="Vizzklick lebt in Gadgetzan und interessiert sich für sein Gewerbe. Er betrachtet Kovic \"zwielichtige Geschäfte als schädlich für ehrliche Kaufleute, eine Rivalität, in der Profit und persönliche Missstände miteinander verknüpft."},pt={title="Vizzklick",body="Vizzklick vive em Gadgetzan e tem interesse em seu comércio. Ele considera os negócios obscuros do Kovic prejudiciais aos comerciantes honestos, uma rivalidade na qual o lucro e as queixas pessoais se entrelaçam."},pl={title="Vizzklick",body="Vizzklick mieszka w Gadgetzan i interesuje się miejscowym handlem. Uważa podejrzane interesy postaci Kovic za szkodliwe dla uczciwych kupców, w rywalizacji splatającej zysk z osobistymi urazami."},ru={title="Vizzklick",body="Vizzklick живет в Gadgetzan и интересуется его торговлей. Он считает, что теневые сделки Kovic  вредны для честных торговцев, соперничество, в котором взаимосвязаны прибыль и личные претензии."},references={["npc:trade-master-kovic"]=true,["place:gadgetzan"]=true}},
    ["person:volcor"] = {title="Volcor",kind="Personaje",aliases={"Volcor"},body="Volcor es un druida que recorre los bosques de Costa Oscura. Su conocimiento del territorio y de las formas animales le ofrece distintas maneras de afrontar los peligros de la región.",aliasQuestIDs={},en={title="Volcor",aliases={"Volcor"},body="Volcor is a druid who travels Darkshore’s forests. His knowledge of the land and animal forms offers different ways to face the region’s dangers.",aliasQuestIDs={}},fr={title="Volcor",body="Volcor est un druide qui parcourt les forêts de Darkshore. Sa connaissance de la terre et des formes animales offre différentes manières de faire face aux dangers de la région."},de={title="Volcor",body="Volcor ist ein Druide, der durch die Wälder von Darkshore reist. Sein Wissen über Land und Tierformen bietet verschiedene Möglichkeiten, den Gefahren der Region zu begegnen."},pt={title="Volcor",body="Volcor é um druida que viaja pelas florestas de Darkshore. Seu conhecimento da terra e formas animais oferece diferentes maneiras de enfrentar os perigos da região."},pl={title="Volcor",body="Volcor jest druidem przemierzającym lasy Darkshore. Znajomość ziemi i zwierzęcych postaci daje mu różne sposoby stawiania czoła niebezpieczeństwom regionu."},ru={title="Volcor",body="Volcor — друид, странствующий по лесам Darkshore. Знание местности и звериных обликов позволяет ему по-разному противостоять опасностям этих земель."},references={["place:darkshore"]=true}},
    ["person:vorn-skyseer"] = {title="Vorn Vidente del Cielo",kind="Personaje",aliases={"Vorn","Vorn Vidente del Cielo"},body="Vorn Vidente del Cielo recibe a nuevos viajeros en el Campamento Narache. Entrega pequeños compañeros que pueden acompañarlos mientras dejan atrás la seguridad de su hogar y comienzan a explorar Azeroth.",aliasQuestIDs={},en={title="Vorn Skyseer",aliases={"Vorn","Vorn Skyseer"},body="Vorn Skyseer welcomes new travelers at Camp Narache. He provides small companions to accompany them as they leave home’s safety behind and begin exploring Azeroth.",aliasQuestIDs={}},fr={title="Vorn Skyseer",body="Vorn Skyseer accueille de nouveaux voyageurs à Camp Narache. Il fournit de petits compagnons pour les accompagner alors qu’ils quittent la sécurité de la maison et commencent à explorer Azeroth."},de={title="Vorn Skyseer",body="Vorn Skyseer begrüßt neue Reisende bei Camp Narache. Er stellt ihnen kleine Begleiter zur Verfügung, die sie begleiten, wenn sie die Sicherheit ihres Hauses hinter sich lassen und beginnen, Azeroth zu erkunden."},pt={title="Vorn Skyseer",body="Vorn Skyseer recebe novos viajantes no Camp Narache. Ele fornece pequenos companheiros para acompanhá-los à medida que saem da segurança de casa e começam a explorar o Azeroth."},pl={title="Vorn Skyseer",body="Vorn Skyseer wita nowych podróżnych w Camp Narache. Zapewnia małych towarzyszy na czas opuszczania bezpiecznego domu i rozpoczynania odkrywania Azeroth."},ru={title="Vorn Skyseer",body="Vorn Skyseer приветствует новых путешественников в Camp Narache. Он предоставляет маленьких товарищей, которые сопровождают их, когда они оставляют безопасность дома и начинают исследовать Azeroth."},references={["place:azeroth"]=true,["place:camp-narache"]=true}},
    ["person:vrang-wildgore"] = {title="Vrang Sangrevaje",kind="Personaje",aliases={"Vrang","Vrang Sangrevaje"},body="Vrang mantiene trampas para animales pequeños repartidas por el valle. Su labor requiere revisar las capturas y mantenerse atento a las otras criaturas, capaces de volver peligroso un recorrido cotidiano.",aliasQuestIDs={},en={title="Vrang Wildgore",aliases={"Vrang","Vrang Wildgore"},body="Vrang maintains traps for small game throughout the valley. His work requires checking catches and watching for the other creatures that can make an ordinary round dangerous.",aliasQuestIDs={}},fr={title="Vrang Wildgore",body="Vrang maintient des pièges pour le petit gibier dans toute la vallée. Son travail exige de vérifier les prises et de surveiller les autres créatures qui peuvent rendre un tour ordinaire dangereux."},de={title="Vrang Wildgore",body="Vrang hält Fallen für Niederwild im ganzen Tal. Seine Arbeit erfordert, die Fänge zu überprüfen und auf die anderen Kreaturen zu achten, die eine gewöhnliche Runde gefährlich machen können."},pt={title="Vrang Wildgore",body="Vrang mantém armadilhas para pequenos jogos em todo o vale. Seu trabalho requer verificar as capturas e observar as outras criaturas que podem tornar uma rodada comum perigosa."},pl={title="Vrang Wildgore",body="Vrang utrzymuje pułapki na małą zwierzynę w całej dolinie. Praca wymaga sprawdzania zdobyczy i wypatrywania innych stworzeń mogących uczynić zwykły obchód niebezpiecznym."},ru={title="Vrang Wildgore",body="Vrang поддерживает ловушки для мелкой дичи по всей долине. Его работа требует проверки улова и наблюдения за другими существами, которые могут сделать обычный раунд опасным."},references={}},
    ["person:vulgara-the-insatiable"] = {title="Vulgara, la Insaciable",kind="Personaje",aliases={"Vulgara","Vulgara, la Insaciable"},body="Vulgara, la Insaciable, es una peligrosa vuldren alada de las Tierras Altas de Shen'dar. Los avisos de los pacificadores la sitúan en una colina al suroeste de la aldea. Su reputación como amenaza para la zona ha llevado a la agente Aonda a ofrecer una recompensa por su captura.",aliasQuestIDs={},en={title="Vulgara the Insatiable",aliases={"Vulgara","Vulgara the Insatiable"},body="Vulgara the Insatiable is a dangerous winged vuldren of the Shen'dar Highlands. Peacekeeper notices place her on a hill southwest of the village. Her reputation as a threat to the area has led Constable Aonda to place a bounty on her.",aliasQuestIDs={}},fr={title="Vulgara the Insatiable",body="Vulgara the Insatiable est un dangereux vautour ailé du Shen'dar Highlands. Peacekeeper remarque la placer sur une colline au sud-ouest du village. Sa réputation de menace pour la région a conduit Constable Aonda à lui accorder une prime."},de={title="Vulgara the Insatiable",body="Vulgara the Insatiable ist eine gefährliche geflügelte Geierin der Shen'dar Highlands. Peacekeeper bemerkt, dass sie auf einem Hügel südwestlich des Dorfes liegt. Ihr Ruf als Bedrohung der Gegend hat Constable Aonda veranlasst, ein Kopfgeld auf sie zu setzen."},pt={title="Vulgara the Insatiable",body="Vulgara the Insatiable é uma ala perigosa do Shen'dar Highlands. Os avisos Peacekeeper a colocam em uma colina a sudoeste da aldeia. Sua reputação como uma ameaça para a área levou Constable Aonda a colocar uma recompensa sobre ela."},pl={title="Vulgara the Insatiable",body="Vulgara the Insatiable jest niebezpieczną skrzydlatą vuldren z Shen'dar Highlands. Ogłoszenia strażników pokoju umieszczają ją na wzgórzu na południowy zachód od wioski. Reputacja zagrożenia dla okolicy skłoniła Constable Aonda do wyznaczenia nagrody."},ru={title="Vulgara the Insatiable",body="Vulgara the Insatiable - опасный крылатый стервятник Shen'dar Highlands. Peacekeeper сообщает, что она на холме к юго-западу от деревни. Ее репутация угрозы для района заставила Constable Aonda выставить на нее награду."},references={["person:constable-aonda"]=true,["place:shendar"]=true,["place:shendar-highlands"]=true}},
    ["person:vyral-the-vile"] = {title="Vyral el Vil",kind="Personaje",aliases={"Vyral","Vyral el Vil"},body="Vyral el Vil es un dirigente local del Martillo Crepuscular en Silithus. Su base se encuentra en Paseo Crepúsculo, una cueva del noreste desde donde el culto mantiene parte de sus operaciones.",aliasQuestIDs={},en={title="Vyral the Vile",aliases={"Vyral","Vyral the Vile"},body="Vyral the Vile is a local Twilight’s Hammer leader in Silithus. He is based in Twilight’s Run, a northeastern cave supporting part of the cult’s operations.",aliasQuestIDs={}},fr={title="Vyral the Vile",body="Vyral the Vile est un leader local Twilight’s Hammer dans Silithus. Il est basé dans Twilight’s Run, une grotte du nord-est soutenant une partie des opérations du culte."},de={title="Vyral the Vile",body="Vyral the Vile ist ein lokaler Twilight’s Hammer Führer in Silithus. Er ist in Twilight 's Run stationiert, einer nordöstlichen Höhle, die einen Teil des Kults unterstützt."},pt={title="Vyral the Vile",body="Vyral the Vile é um líder local Twilight’s Hammer em Silithus. Ele está baseado em Twilight's Run, uma caverna no nordeste que apoia parte das operações do culto."},pl={title="Vyral the Vile",body="Vyral the Vile jest miejscowym przywódcą Twilight’s Hammer w Silithus. Działa z Twilight’s Run, północno-wschodniej jaskini wspierającej część przedsięwzięć kultu."},ru={title="Vyral the Vile",body="Vyral the Vile - это местный лидер Twilight’s Hammer в Silithus. Он базируется в Твайлайтс-Ран, северо-восточной пещере, поддерживающей часть операций культа."},references={["organization:twilights-hammer"]=true,["place:silithus"]=true}},
    ["person:warlord-gorchuk"] = {title="Señor de la guerra Gorchuk",kind="Personaje",aliases={"Gorchuk","Señor de la guerra Gorchuk","señor de la guerra Gorchuk"},body="El señor de la guerra Gorchuk dirige los preparativos de la Horda para la guerra de Ahn'Qiraj desde Orgrimmar. Coordina una movilización en la que reunir materiales y abastecer al ejército es tan necesario como combatir.",aliasQuestIDs={},en={title="Warlord Gorchuk",aliases={"Gorchuk","Warlord Gorchuk"},body="Warlord Gorchuk directs the Horde’s preparations for the Ahn'Qiraj war from Orgrimmar. He coordinates a mobilization in which gathering materials and supplying the army are as necessary as fighting.",aliasQuestIDs={}},fr={title="Warlord Gorchuk",body="Warlord Gorchuk dirige les préparatifs du Horde pour la guerre Ahn'Qiraj de Orgrimmar. Il coordonne une mobilisation dans laquelle la collecte de matériel et la fourniture de l’armée sont aussi nécessaires que les combats."},de={title="Warlord Gorchuk",body="Warlord Gorchuk leitet von Orgrimmar aus die Vorbereitungen des Horde für den Ahn'Qiraj-Krieg. Er koordiniert eine Mobilisierung, bei der das Sammeln von Material und die Versorgung der Armee ebenso notwendig sind wie das Kämpfen."},pt={title="Warlord Gorchuk",body="Warlord Gorchuk dirige os preparativos do Horde para a guerra Ahn'Qiraj da Orgrimmar. Ele coordena uma mobilização na qual a coleta de materiais e o fornecimento do exército são tão necessários quanto a luta."},pl={title="Warlord Gorchuk",body="Warlord Gorchuk kieruje przygotowaniami frakcji Horde do wojny Ahn'Qiraj z Orgrimmar. Koordynuje mobilizację, w której gromadzenie materiałów i zaopatrywanie armii są równie niezbędne jak walka."},ru={title="Warlord Gorchuk",body="Warlord Gorchuk направляет Horde  к подготовке к войне Ahn'Qiraj с Orgrimmar. Он координирует мобилизацию, в которой сбор материалов и снабжение армии так же необходимы, как борьба."},references={["event:ahnqiraj-war"]=true,["organization:horde"]=true,["place:ahnqiraj"]=true,["place:orgrimmar"]=true}},
    ["person:warlord-krellian"] = {title="Señor de la Guerra Krellian",kind="Personaje",aliases={"Krellian","Señor de la Guerra Krellian"},body="El señor de la guerra Krellian se protege entre sus guardias en el Templo de Zin-Malor. Posee una concha centelleante cuya poderosa aura ha llamado la atención de quienes observan las energías mágicas de Azshara.",aliasQuestIDs={},en={title="Warlord Krellian",aliases={"Krellian","Warlord Krellian"},body="Warlord Krellian shelters among his guards in the Temple of Zin-Malor. He possesses a prismatic shell whose powerful aura has drawn the attention of those watching Azshara’s magical energies.",aliasQuestIDs={}},fr={title="Warlord Krellian",body="Warlord Krellian abrite parmi ses gardes dans le Temple de Zin-Malor. Il possède une coquille prismatique dont la puissante aura a attiré l’attention de ceux qui regardent les énergies magiques de Azshara."},de={title="Warlord Krellian",body="Warlord Krellian versteckt sich unter seinen Bewachern im Tempel von Zin-Malor. Er besitzt eine prismatische Schale Hülle, deren mächtige Aura die Aufmerksamkeit der Betrachter auf Azshara 's magische Energien gelenkt hat."},pt={title="Warlord Krellian",body="Warlord Krellian abriga entre seus guardas no Templo de Zin-Malor. Ele possui uma concha prismática cuja aura poderosa chamou a atenção daqueles que assistem às energias mágicas do Azshara."},pl={title="Warlord Krellian",body="Warlord Krellian chroni się wśród strażników w świątyni Zin-Malor. Posiada pryzmatyczną muszlę, której potężna aura zwróciła uwagę obserwatorów magicznych energii regionu Azshara."},ru={title="Warlord Krellian",body="Warlord Krellian укрывается среди своих охранников в Храме Zin-Malor. Он обладает призматической оболочкой, чья мощная аура привлекла внимание тех, кто наблюдал за магическими энергиями Azshara."},references={}},
    ["person:warug"] = {title="Warug",kind="Personaje",aliases={"Warug"},body="Warug es un centauro relacionado con los Magram de Desolace. Participa en los esfuerzos de su clan por obtener recursos y ventajas frente a sus rivales.",aliasQuestIDs={},en={title="Warug",aliases={"Warug"},body="Warug is a centaur associated with the Magram in Desolace. He participates in his clan’s efforts to obtain resources and advantages over its rivals.",aliasQuestIDs={}},fr={title="Warug",body="Warug est un centaure associé au Magram dans Desolace. Il participe aux efforts de son clan pour obtenir des ressources et des avantages par rapport à ses rivaux."},de={title="Warug",body="Warug ist ein Zentaur, der mit dem Magram in Desolace in Verbindung gebracht wird. Er beteiligt sich an den Bemühungen seines Clans, Ressourcen und Vorteile gegenüber seinen Rivalen zu erlangen."},pt={title="Warug",body="Warug é um centauro associado ao Magram no Desolace. Ele participa dos esforços de seu clã para obter recursos e vantagens sobre seus rivais."},pl={title="Warug",body="Warug jest centaurem związanym z klanem Magram w Desolace. Uczestniczy w wysiłkach klanu zmierzających do zdobywania zasobów i przewagi nad rywalami."},ru={title="Warug",body="Warug - это кентавр, связанный с Magram в Desolace. Он участвует в усилиях своего клана, чтобы получить ресурсы и преимущества над его соперниками."},references={["organization:magram"]=true,["place:desolace"]=true}},
    ["person:washte-pawne"] = {title="Washte Pawne",kind="Personaje",aliases={"Washte Pawne"},body="Washte Pawne es un raro halcón trueno de Los Baldíos, cuyas plumas resultan dolorosas al tacto. Los relatos sobre la bestia atribuyen a su muerte el carácter de un presagio, capaz de anunciar fortuna o desgracia.",aliasQuestIDs={},en={title="Washte Pawne",aliases={"Washte Pawne"},body="Washte Pawne is a rare thunderhawk of the Barrens whose feathers are painful to touch. Stories about the beast treat its death as an omen that may herald fortune or disaster.",aliasQuestIDs={}},fr={title="Washte Pawne",body="Le Washte Pawne est un rare Thunderhawk du Barrens dont les plumes sont douloureuses au toucher. Les histoires sur la bête traitent sa mort comme un présage qui peut annoncer la fortune ou le désastre."},de={title="Washte Pawne",body="Washte Pawne ist ein seltener Gewitterfalke des Barrens, dessen Federn schmerzhaft zu berühren sind. Geschichten über das Tier behandeln seinen Tod als ein Omen, das Glück oder eine Katastrophe ankündigen kann."},pt={title="Washte Pawne",body="Washte Pawne é um raro trovão do Barrens cujas penas são dolorosas ao toque. As histórias sobre a besta tratam sua morte como um presságio que pode anunciar fortuna ou desastre."},pl={title="Washte Pawne",body="Washte Pawne jest rzadkim jastrzębiem piorunowym regionu Barrens, którego pióra sprawiają ból przy dotknięciu. Opowieści traktują śmierć bestii jako omen mogący zwiastować szczęście lub katastrofę."},ru={title="Washte Pawne",body="Washte Pawne - редкий грозовой ястреб Barrens, перья которого болезненны при ощущении. В рассказах о звере его смерть рассматривается как предзнаменование, которое может предвещать удачу или бедствие."},references={["npc:omen"]=true,["place:the-barrens"]=true}},
    ["person:wenikee-boltbucket"] = {title="Wenikee Tuercasmil",kind="Personaje",aliases={"Wenikee","Wenikee Tuercasmil"},body="Wenikee Tuercasmil es una técnica de Los Baldíos, próxima a la Empalizada de Mor'shan. Su curiosidad y su capacidad para estudiar máquinas la convierten en una especialista a la que recurren otros inventores cuando un aparato falla.",aliasQuestIDs={},en={title="Wenikee Boltbucket",aliases={"Wenikee","Wenikee Boltbucket"},body="Wenikee Boltbucket is a technician in the Barrens near the Mor'shan Rampart. Her curiosity and ability to study machines make her a specialist other inventors consult when a device fails.",aliasQuestIDs={}},fr={title="Wenikee Boltbucket",body="Wenikee Boltbucket est un technicien dans le Barrens près du Mor'shan Rampart. Sa curiosité et sa capacité à étudier les machines font d'elle une spécialiste que d'autres inventeurs consultent lorsqu'un appareil tombe en panne."},de={title="Wenikee Boltbucket",body="Wenikee Boltbucket ist Technikerin in der Barrens in der Nähe der Mor'shan Rampart. Ihre Neugier und ihre Fähigkeit, Maschinen zu studieren, machen sie zu einem Spezialisten, den andere Erfinder sie konsultieren, wenn ein Gerät ausfällt."},pt={title="Wenikee Boltbucket",body="Wenikee Boltbucket é um técnico no Barrens perto do Mor'shan Rampart. Sua curiosidade e capacidade de estudar máquinas fazem dela uma especialista que outros inventores consultam quando um dispositivo falha."},pl={title="Wenikee Boltbucket",body="Wenikee Boltbucket jest techniczką w regionie Barrens, przy Mor'shan Rampart. Ciekawość i zdolność badania maszyn czynią ją specjalistką, do której zwracają się inni wynalazcy przy awarii urządzenia."},ru={title="Wenikee Boltbucket",body="Wenikee Boltbucket - технический работник в Barrens рядом с Mor'shan Rampart. Ее любопытство и умение изучать машины делают ее специалистом, к которому обращаются другие изобретатели, когда устройство выходит из строя."},references={["place:the-barrens"]=true}},
    ["person:wharfmaster-dizzywig"] = {title="Maestro de muelles Vertipeluca",kind="Personaje",aliases={"Maestro de muelles Vertipeluca","Vertipeluca"},body="El maestro de muelles Vertipeluca sigue de cerca el intercambio de mercancías y dinero entre Trinquete y Bahía del Botín. Su posición en el puerto le permite reunir noticias comerciales y detectar negocios que podrían dejar buenas ganancias.",aliasQuestIDs={},en={title="Wharfmaster Dizzywig",aliases={"Dizzywig","Wharfmaster Dizzywig"},body="Wharfmaster Dizzywig keeps close track of goods and money passing between Ratchet and Booty Bay. His position at the port lets him gather commercial news and spot potentially profitable deals.",aliasQuestIDs={}},fr={title="Wharfmaster Dizzywig",body="Wharfmaster Dizzywig suit de près les marchandises et l'argent passant entre Ratchet et Booty Bay. Sa position au port lui permet de recueillir des nouvelles commerciales et de repérer des transactions potentiellement rentables."},de={title="Wharfmaster Dizzywig",body="Wharfmaster Dizzywig behält den Überblick über Waren und Geld, das zwischen Ratchet und Booty Bay fließt. Seine Position im Hafen ermöglicht es ihm, kommerzielle Nachrichten zu sammeln und potenziell lukrative Geschäfte aufzudecken."},pt={title="Wharfmaster Dizzywig",body="Wharfmaster Dizzywig mantém o controle próximo de bens e dinheiro que passam entre Ratchet e Booty Bay. Sua posição no porto permite-lhe reunir notícias comerciais e encontrar ofertas potencialmente lucrativas."},pl={title="Wharfmaster Dizzywig",body="Wharfmaster Dizzywig uważnie śledzi towary i pieniądze przepływające między Ratchet a Booty Bay. Pozycja w porcie pozwala mu zbierać wieści handlowe i dostrzegać potencjalnie zyskowne umowy."},ru={title="Wharfmaster Dizzywig",body="Wharfmaster Dizzywig следит за товарами и деньгами, перемещающимися между Ratchet и Booty Bay. Его должность в порту позволяет ему собирать коммерческие новости и выявлять потенциально прибыльные сделки."},references={["place:booty-bay"]=true,["place:ratchet"]=true}},
    ["person:whuut"] = {title="Whuut",kind="Personaje",aliases={"Whuut"},body="Whuut es un aprendiz de alquimia de Orgrimmar con un talento reconocido por Yelmak. Su orgullo y su interés por los componentes exóticos contrastan con la paciencia y la práctica que sus maestros consideran necesarias.",aliasQuestIDs={},en={title="Whuut",aliases={"Whuut"},body="Whuut is an alchemy apprentice in Orgrimmar whose talent is recognized by Yelmak. His pride and interest in exotic components contrast with the patience and practice his teachers regard as necessary.",aliasQuestIDs={}},fr={title="Whuut",body="Whuut est un apprenti en alchimie à Orgrimmar dont le talent est reconnu par Yelmak. Sa fierté et son intérêt pour les composants exotiques contrastent avec la patience et la pratique que ses professeurs considèrent comme nécessaires."},de={title="Whuut",body="Whuut ist Alchemie-Lehrling bei Orgrimmar, dessen Talent Yelmak erkannt wird. Sein Stolz und Interesse an exotischen Komponenten stehen im Gegensatz zu der Geduld und Übung, die seine Lehrer als notwendig erachten."},pt={title="Whuut",body="Whuut é um aprendiz de alquimia na Orgrimmar cujo talento é reconhecido pela Yelmak. Seu orgulho e interesse em componentes exóticos contrastam com a paciência e a prática que seus professores consideram necessárias."},pl={title="Whuut",body="Whuut jest uczniem alchemii w Orgrimmar, którego talent uznaje Yelmak. Duma i zainteresowanie egzotycznymi składnikami kontrastują z cierpliwością oraz praktyką uważanymi przez nauczycieli za niezbędne."},ru={title="Whuut",body="Whuut - ученик алхимии в Orgrimmar, чьи таланты признаны Yelmak. Его гордость и интерес к экзотическим компонентам контрастируют с терпением и практикой, которые его учителя считают необходимыми."},references={["person:yelmak"]=true,["place:orgrimmar"]=true}},
    ["person:williden-marshal"] = {title="Williden Marshal",kind="Personaje",aliases={"Williden Marshal"},body="Williden Marshal dirige una expedición independiente en el Cráter de Un'Goro. La dureza del territorio y la pérdida de suministros muestran hasta qué punto la investigación allí depende de mantener a salvo a los exploradores.",aliasQuestIDs={},en={title="Williden Marshal",aliases={"Williden","Williden Marshal"},body="Williden Marshal leads an independent expedition in Un'Goro Crater. The harsh terrain and loss of supplies show how strongly research there depends on keeping explorers safe.",aliasQuestIDs={}},fr={title="Williden Marshal",body="Williden Marshal mène une expédition indépendante à Un'Goro Crater. Le terrain accidenté et la perte de matériel montrent à quel point la recherche dépend fortement de la sécurité des explorateurs."},de={title="Williden Marshal",body="Williden Marshal leitet eine unabhängige Expedition in Un'Goro Crater. Das raue Gelände und der Versorgungsverluste zeigen, wie stark die Forschung von der Sicherheit der Entdehnenden Forscher abhängt."},pt={title="Williden Marshal",body="Williden Marshal lidera uma expedição independente em Un'Goro Crater. O terreno duro e a perda de suprimentos mostram quão fortemente a pesquisa lá depende de manter os exploradores seguros."},pl={title="Williden Marshal",body="Williden Marshal prowadzi niezależną ekspedycję w Un'Goro Crater. Trudny teren i utrata zapasów pokazują, jak mocno badania zależą tam od zapewnienia odkrywcom bezpieczeństwa."},ru={title="Williden Marshal",body="Williden Marshal возглавляет независимую экспедицию в Un'Goro Crater. Жестокая местность и потеря запасов показывают, насколько исследования там зависят от безопасности исследователей."},references={["place:ungoro-crater"]=true}},
    ["person:windcaller-kaldon"] = {title="Clamavientos Kaldon",kind="Personaje",aliases={"Clamavientos Kaldon","Kaldon"},body="Clamavientos Kaldon organiza tareas de las fuerzas que se preparan para combatir en Silithus. Su coordinación tiene en cuenta la rivalidad entre la Brigada de Forjaz y la Legión de Orgrimmar, incluso cuando afrontan una amenaza común.",aliasQuestIDs={},en={title="Windcaller Kaldon",aliases={"Kaldon","Windcaller Kaldon"},body="Windcaller Kaldon organizes tasks for the forces preparing to fight in Silithus. His coordination takes account of the rivalry between the Ironforge Brigade and Orgrimmar Legion even as they face a shared threat.",aliasQuestIDs={}},fr={title="Windcaller Kaldon",body="Windcaller Kaldon organise des tâches pour les forces qui se préparent à combattre dans Silithus. Sa coordination tient compte de la rivalité entre les Ironforge Brigade et Orgrimmar Legion même s’ils font face à une menace commune."},de={title="Windcaller Kaldon",body="Windcaller Kaldon organisiert Aufgaben für die Kräfte, die sich auf den Kampf in Silithus vorbereiten. Seine Koordinierung berücksichtigt die Rivalität zwischen Ironforge Brigade und Orgrimmar Legion, obwohl sie mit einer gemeinsamen Bedrohung konfrontiert sind."},pt={title="Windcaller Kaldon",body="Windcaller Kaldon organiza tarefas para as forças que se preparam para lutar em Silithus. Sua coordenação leva em conta a rivalidade entre o Ironforge Brigade e Orgrimmar Legion, mesmo quando enfrentam uma ameaça compartilhada."},pl={title="Windcaller Kaldon",body="Windcaller Kaldon organizuje zadania sił przygotowujących się do walki w Silithus. Uwzględnia rywalizację między Ironforge Brigade a Orgrimmar Legion, nawet gdy mierzą się ze wspólnym zagrożeniem."},ru={title="Windcaller Kaldon",body="Windcaller Kaldon организует задания для сил, готовящихся к бою в Silithus. Его координация учитывает соперничество между Ironforge Brigade и Orgrimmar Legion, даже когда они сталкиваются с общей угрозой."},references={["organization:ironforge-brigade"]=true,["organization:orgrimmar-legion"]=true,["place:ironforge"]=true,["place:orgrimmar"]=true,["place:silithus"]=true}},
    ["person:windcaller-proudhorn"] = {title="Clamavientos Cuerno Digno",kind="Personaje",aliases={"Clamavientos Cuerno Digno"},body="Clamavientos Cuerno Digno recibe a quienes acuden al Fuerte Cenarion para ayudar en Silithus. Su labor forma parte de los preparativos del Círculo Cenarion para frenar la expansión de los silítidos.",aliasQuestIDs={},en={title="Windcaller Proudhorn",aliases={"Proudhorn","Windcaller Proudhorn"},body="Windcaller Proudhorn receives those arriving at Cenarion Hold to help in Silithus. His work is part of the Cenarion Circle’s preparations to contain the spread of the silithid.",aliasQuestIDs={}},fr={title="Windcaller Proudhorn",body="Windcaller Proudhorn reçoit ceux qui arrivent à Cenarion Hold pour aider dans Silithus. Son travail fait partie des préparatifs de la Cenarion Circle pour contenir la propagation du silithid."},de={title="Windcaller Proudhorn",body="Windcaller Proudhorn empfängt diejenigen, die bei Cenarion Hold ankommen, um Silithus zu helfen. Seine Arbeit ist Teil der Vorbereitungen der Cenarion Circle, um die Ausbreitung des Silithid einzudämmen."},pt={title="Windcaller Proudhorn",body="Windcaller Proudhorn recebe aqueles que chegam ao Cenarion Hold para ajudar no Silithus. Seu trabalho faz parte dos preparativos do Cenarion Circle para conter a propagação da silitídea."},pl={title="Windcaller Proudhorn",body="Windcaller Proudhorn przyjmuje osoby przybywające do Cenarion Hold, by pomóc w Silithus. Jego praca stanowi część przygotowań Cenarion Circle do powstrzymywania rozprzestrzeniania się silithidów."},ru={title="Windcaller Proudhorn",body="Windcaller Proudhorn принимает тех, кто прибывает на Cenarion Hold, чтобы помочь в Silithus. Его работа является частью Cenarion Circle s препаратов для сдерживания распространения силитида."},references={["organization:cenarion-circle"]=true,["place:cenarion-hold"]=true,["place:silithus"]=true},questIDs={[8275]=true,[8276]=true,[8280]=true,[8281]=true,[8496]=true,[8534]=true,[8782]=true,[8808]=true,[8810]=true}},
    ["person:windshaper-boro"] = {title="Formavientos Boro",kind="Personaje",aliases={"Boro","Formavientos Boro"},body="Boro es el instructor de chamanes de Arboleda Thendal y pertenece a los Formavientos. Su enseñanza está vinculada al encuentro con los espíritus elementales y a la creación de tótems. Un fragmento de cuarzo puede servir como corazón de uno de esos objetos rituales.",aliasQuestIDs={},en={title="Windshaper Boro",aliases={"Boro","Windshaper Boro"},body="Boro is Thendal Grove’s shaman trainer and a member of the Windshapers. His teaching concerns encounters with elemental spirits and the creation of totems. A piece of quartz can serve as the heart of one of these ritual objects.",aliasQuestIDs={}},fr={title="Windshaper Boro",body="Boro est le shaman formateur de Thendal Grove et un membre de la Windshapers. Son enseignement concerne les rencontres avec les esprits élémentaires et la création de totems. Un morceau de quartz peut servir de cœur à l’un de ces objets rituels."},de={title="Windshaper Boro",body="Boro ist Thendal Grove 'Schamanentrainer und Mitglied der Windshapers. Seine Lehre betrifft Begegnungen mit Elementaren Geistern und die Erschaffung von Totems. Ein Stück Quarz kann als Herzstück eines dieser rituellen Objekte dienen."},pt={title="Windshaper Boro",body="Boro é o treinador de xamãs da Thendal Grove e membro do Windshapers. Seu ensino diz respeito a encontros com espíritos elementares e a criação de totens. Um pedaço de quartzo pode servir como o coração de um desses objetos rituais."},pl={title="Windshaper Boro",body="Boro jest instruktorem szamanów Thendal Grove i członkiem społeczności znanej jako the Windshapers. Uczy spotkań z duchami żywiołów i tworzenia totemów. Kawałek kwarcu może służyć jako serce jednego z tych rytualnych przedmiotów."},ru={title="Windshaper Boro",body="Boro - это тренер шамана Thendal Grove  и член Windshapers. Его учение касается встреч с духов-элементалов и создания тотемов. Кусок кварца может служить сердцем одного из этих ритуальных предметов."},references={["organization:windshapers"]=true,["place:thendal-grove"]=true}},
    ["person:winna-hazzard"] = {title="Winna Riessgo",kind="Personaje",aliases={"Winna","Winna Riessgo"},body="Winna Riessgo experimenta con la corrupción de Frondavil desde el Puesto del Veneno. Busca convertir sus efectos sobre los animales en una ventaja para la Horda, sin compartir la preocupación de otros por sus métodos.",aliasQuestIDs={},en={title="Winna Hazzard",aliases={"Winna","Winna Hazzard"},body="Winna Hazzard experiments with Felwood’s corruption from Bloodvenom Post. She seeks to turn its effects on animals into an advantage for the Horde, without sharing others’ concern about her methods.",aliasQuestIDs={}},fr={title="Winna Hazzard",body="Winna Hazzard expérimente la corruption de Felwood depuis Bloodvenom Post. Elle cherche à transformer ses effets sur les animaux en un avantage pour le Horde, sans partager l’inquiétude des autres au sujet de ses méthodes."},de={title="Winna Hazzard",body="Winna Hazzard experimentiert mit Felwoods Korruption von Bloodvenom Post. Sie versucht, ihre Auswirkungen auf die Tiere in einen Vorteil für die Horde zu verwandeln, ohne die Besorgnis anderer über ihre Methoden zu teilen."},pt={title="Winna Hazzard",body="Winna Hazzard experimenta com a corrupção de Felwood da Bloodvenom Post. Ela procura transformar seus efeitos sobre os animais em uma vantagem para o Horde, sem compartilhar a preocupação dos outros com seus métodos."},pl={title="Winna Hazzard",body="Winna Hazzard eksperymentuje ze skażeniem Felwood, działając z posterunku Bloodvenom. Próbuje wykorzystać jego wpływ na zwierzęta na korzyść frakcji Horde, nie podzielając cudzych obaw dotyczących jej metod."},ru={title="Winna Hazzard",body="Winna Hazzard экспериментирует с порчей Felwood s от Bloodvenom Post. Она стремится превратить его влияние на животных в преимущество для Horde, не разделяя других беспокойства о ее методах."},references={["organization:horde"]=true,["place:felwood"]=true}},
    ["person:witch-doctor-jinzil"] = {title="Médico brujo Jin'Zil",kind="Personaje",aliases={"Jin'Zil","Jin’Zil","Médico brujo Jin'Zil","Médico brujo Jin’Zil","médico brujo Jin'Zil","médico brujo Jin’Zil"},body="El médico brujo Jin'Zil trabaja en Malaka'jin, en Sierra Espolón. Utiliza partes de animales y recursos del bosque en prácticas que expresan su hostilidad hacia los elfos de la noche.",aliasQuestIDs={},en={title="Witch Doctor Jin'Zil",aliases={"Jin'Zil","Jin’Zil","Witch Doctor Jin'Zil","Witch Doctor Jin’Zil"},body="Witch Doctor Jin'Zil works in Malaka'jin in the Stonetalon Mountains. He uses animal parts and forest resources in practices expressing his hostility toward the night elves.",aliasQuestIDs={}},fr={title="Witch Doctor Jin'Zil",body="Witch Doctor Jin'Zil travaille dans Malaka'jin dans le Stonetalon Mountains. Il utilise des parties animales et des ressources forestières dans des pratiques exprimant son hostilité envers les elfes de la nuit."},de={title="Witch Doctor Jin'Zil",body="Witch Doctor Jin'Zil arbeitet in Malaka'jin im Stonetalon Mountains. Er verwendet Tierteile und Waldressourcen, um seine Feindseligkeit gegenüber den Nachtelfen auszudrücken."},pt={title="Witch Doctor Jin'Zil",body="Witch Doctor Jin'Zil trabalha em Malaka'jin no Stonetalon Mountains. Ele usa partes de animais e recursos florestais em práticas que expressam sua hostilidade para com os elfos noturnos."},pl={title="Witch Doctor Jin'Zil",body="Witch Doctor Jin'Zil pracuje w Malaka'jin w regionie Stonetalon Mountains. Używa części zwierząt i zasobów lasu w praktykach wyrażających wrogość wobec nocnych elfów."},ru={title="Witch Doctor Jin'Zil",body="Witch Doctor Jin'Zil работает на Malaka'jin в Stonetalon Mountains. Он использует части животных и лесные ресурсы в практиках, выражающих свою враждебность к ночным эльфам."},references={["place:stonetalon-mountains"]=true}},
    ["person:witch-doctor-mauari"] = {title="Médica bruja Mau'ari",kind="Personaje",aliases={"Mau'ari","Mau’ari","Médica bruja Mau'ari","Médica bruja Mau’ari","médica bruja Mau'ari","médica bruja Mau’ari"},body="La médica bruja Mau'ari vive en Vista Eterna y practica una magia relacionada con la suerte y las criaturas de Cuna del Invierno. Sus encantamientos atraen a viajeros dispuestos a buscar una pequeña ventaja frente a los peligros de las montañas.",aliasQuestIDs={},en={title="Witch Doctor Mau'ari",aliases={"Mau'ari","Mau’ari","Witch Doctor Mau'ari","Witch Doctor Mau’ari"},body="Witch Doctor Mau'ari lives in Everlook and practices magic associated with luck and the creatures of Winterspring. Her enchantments attract travelers seeking an advantage against the dangers of the mountains.",aliasQuestIDs={}},fr={title="Witch Doctor Mau'ari",body="Witch Doctor Mau'ari vit dans Everlook et pratique la magie associée à la chance et aux créatures de Winterspring. Ses enchantements attirent les voyageurs à la recherche d'un avantage contre les dangers de la montagne."},de={title="Witch Doctor Mau'ari",body="Witch Doctor Mau'ari lebt in Everlook und übt Magie, die mit Glück und den Geschöpfen von Winterspring verbunden ist. Ihre Verzauberungen ziehen Reisende an, die einen Vorteil gegen die Gefahren der Berge suchen."},pt={title="Witch Doctor Mau'ari",body="Witch Doctor Mau'ari vive em Everlook e pratica magia associada à sorte e às criaturas de Winterspring. Seus encantamentos atraem viajantes que buscam uma vantagem contra os perigos das montanhas."},pl={title="Witch Doctor Mau'ari",body="Witch Doctor Mau'ari mieszka w Everlook i praktykuje magię związaną ze szczęściem oraz stworzeniami Winterspring. Jej zaklęcia przyciągają podróżnych szukających przewagi nad niebezpieczeństwami gór."},ru={title="Witch Doctor Mau'ari",body="Witch Doctor Mau'ari живет в Everlook и практикует магию, связанную с удачей и существами Winterspring. Ее заклинания привлекают путешественников, которые хотят выиграть от опасностей гор."},references={["place:everlook"]=true,["place:winterspring"]=true}},
    ["person:witch-doctor-uzeri"] = {title="Médico brujo Uzer'i",kind="Personaje",aliases={"Médico brujo Uzer'i","Médico brujo Uzer’i","Uzer'i","Uzer’i","médico brujo Uzer'i","médico brujo Uzer’i"},body="El médico brujo Uzer'i trabaja en el Campamento Mojache. Su práctica combina materiales de plantas, criaturas y otros recursos de Feralas para elaborar objetos y preparados de poder.",aliasQuestIDs={},en={title="Witch Doctor Uzer'i",aliases={"Uzer'i","Uzer’i","Witch Doctor Uzer'i","Witch Doctor Uzer’i"},body="Witch Doctor Uzer'i works in Camp Mojache. His practice combines materials from plants, creatures and other Feralas resources to make objects and preparations of power.",aliasQuestIDs={}},fr={title="Witch Doctor Uzer'i",body="Witch Doctor Uzer'i travaille dans Camp Mojache. Sa pratique combine des matériaux de plantes, de créatures et d'autres ressources Feralas pour faire des objets et des préparations de pouvoir."},de={title="Witch Doctor Uzer'i",body="Witch Doctor Uzer'i arbeitet in Camp Mojache. In seiner Praxis kombiniert er Materialien aus Pflanzen, Kreaturen und anderen Feralas-Ressourcen zu Objekten und Machtpräparaprodukten."},pt={title="Witch Doctor Uzer'i",body="Witch Doctor Uzer'i funciona em Camp Mojache. Sua prática combina materiais de plantas, criaturas e outros recursos Feralas para fazer objetos e preparações de poder."},pl={title="Witch Doctor Uzer'i",body="Witch Doctor Uzer'i pracuje w Camp Mojache. Łączy materiały pochodzące z roślin, stworzeń i innych zasobów Feralas, by wytwarzać przedmioty oraz preparaty o magicznej mocy."},ru={title="Witch Doctor Uzer'i",body="Witch Doctor Uzer'i работает в Camp Mojache. Его практика объединяет материалы из растений, существ и других ресурсов Feralas для создания объектов и препаратов силы."},references={["place:camp-mojache"]=true,["place:feralas"]=true}},
    ["person:wizzle-brassbolts"] = {title="Wizzle Pernolatón",kind="Personaje",aliases={"Wizzle","Wizzle Pernolatón"},body="Wizzle Pernolatón trabaja en los vehículos de carreras del Desierto de Sal. Siempre busca mejorar su velocidad mediante nuevas piezas y experimentos, incluso cuando su equipo ya supera a sus rivales.",aliasQuestIDs={},en={title="Wizzle Brassbolts",aliases={"Wizzle","Wizzle Brassbolts"},body="Wizzle Brassbolts works on racing vehicles in the Shimmering Flats. He constantly seeks greater speed through new parts and experiments, even when his team already outperforms its rivals.",aliasQuestIDs={}},fr={title="Wizzle Brassbolts",body="Wizzle Brassbolts travaille sur les véhicules de course dans le Shimmering Flats. Il cherche constamment plus de vitesse à travers de nouvelles pièces et expériences, même lorsque son équipe surpasse déjà ses rivaux."},de={title="Wizzle Brassbolts",body="Wizzle Brassbolts arbeitet an Rennfahrzeugen im Shimmering Flats. Ständig versucht er, durch neue Teile und Experimente mehr Geschwindigkeit zu erreichen, auch wenn sein Team die Konkurrenz bereits übertrifft."},pt={title="Wizzle Brassbolts",body="Wizzle Brassbolts trabalha em veículos de corrida no Shimmering Flats. Ele constantemente busca maior velocidade através de novas peças e experimentos, mesmo quando sua equipe já supera seus rivais."},pl={title="Wizzle Brassbolts",body="Wizzle Brassbolts pracuje nad pojazdami wyścigowymi w Shimmering Flats. Stale szuka większej szybkości poprzez nowe części i eksperymenty, nawet gdy jego zespół już przewyższa rywali."},ru={title="Wizzle Brassbolts",body="Wizzle Brassbolts работает над гоночными машинами в Shimmering Flats. Он постоянно стремится к большей скорости с помощью новых деталей и экспериментов, даже когда его команда уже превосходит своих соперников."},references={["place:shimmering-flats"]=true}},
    ["person:wrenix-the-wretched"] = {title="Desdio el Desdichado",kind="Personaje",aliases={"Desdio","Desdio el Desdichado"},body="Desdio el Desdichado trabaja con máquinas en Trinquete. Sus intentos de responder al problema de los piratas mediante inventos muestran tanto su ingenio como la fragilidad de sus creaciones ante los peligros de la costa.",aliasQuestIDs={},en={title="Wrenix the Wretched",aliases={"Wrenix","Wrenix the Wretched"},body="Wrenix the Wretched works with machines in Ratchet. His attempts to answer the pirate problem through inventions show both his ingenuity and how vulnerable his creations are to coastal dangers.",aliasQuestIDs={}},fr={title="Wrenix the Wretched",body="Wrenix the Wretched travaille avec des machines dans Ratchet. Ses tentatives pour répondre au problème des pirates à travers des inventions montrent à la fois son ingéniosité et à quel point ses créations sont vulnérables aux dangers côtiers."},de={title="Wrenix the Wretched",body="Wrenix the Wretched arbeitet mit Maschinen in Ratchet. Seine Versuche, das Piratenproblem durch Erfindungen zu lösen, zeigen sowohl seinen Einfallsreichtum als auch, wie verwundbar seine Kreationen gegenüber Gefahren an der Küste sind."},pt={title="Wrenix the Wretched",body="Wrenix the Wretched trabalha com máquinas em Ratchet. Suas tentativas de responder ao problema pirata por meio de invenções mostram tanto sua engenhosidade quanto quão vulneráveis são suas criações aos perigos costeiros."},pl={title="Wrenix the Wretched",body="Wrenix the Wretched pracuje z maszynami w Ratchet. Próby rozwiązania problemu piratów za pomocą wynalazków ukazują zarówno pomysłowość, jak i podatność jego konstrukcji na niebezpieczeństwa wybrzeża."},ru={title="Wrenix the Wretched",body="Wrenix the Wretched работает с машинами в Ratchet. Его попытки найти ответ на проблему пиратов с помощью изобретений показывают как его изобретательность, так и уязвимость его творений к прибрежным опасностям."},references={["place:ratchet"]=true}},
    ["person:wynd-nightchaser"] = {title="Wynd Cazanoche",kind="Personaje",aliases={"Wynd","Wynd Cazanoche"},body="Wynd Cazanoche conoce las ruinas y los secretos de Cuna del Invierno desde la Aldea Estrella Fugaz. Sus conocimientos ofrecen orientación a quienes intentan explorar una tierra tan dura como antigua.",aliasQuestIDs={},en={title="Wynd Nightchaser",aliases={"Wynd","Wynd Nightchaser"},body="Wynd Nightchaser knows Winterspring’s ruins and secrets from Starfall Village. His knowledge offers guidance to those trying to explore a land as harsh as it is ancient.",aliasQuestIDs={}},fr={title="Wynd Nightchaser",body="À Starfall Village, Wynd Nightchaser connaît les ruines et les secrets de Winterspring. Son savoir guide ceux qui cherchent à explorer une terre aussi rude qu'ancienne."},de={title="Wynd Nightchaser",body="Wynd Nightchaser kennt die Ruinen und Geheimnisse von Winterspring von Starfall Village. Sein Wissen bietet denjenigen Orientierung, die versuchen, ein so hartes wie uraltes Land zu erkunden."},pt={title="Wynd Nightchaser",body="Em Starfall Village, Wynd Nightchaser conhece as ruínas e os segredos de Winterspring. Seu conhecimento orienta quem busca explorar uma terra tão inóspita quanto antiga."},pl={title="Wynd Nightchaser",body="Wynd Nightchaser zna ruiny i tajemnice Winterspring, działając z Starfall Village. Jego wiedza wskazuje drogę osobom próbującym badać krainę równie surową, co pradawną."},ru={title="Wynd Nightchaser",body="Wynd Nightchaser знает руины и секреты Winterspring от Starfall Village. Его знания помогают исследовать страну, которая была так же жестока, как и древняя."},references={["place:starfall-village"]=true,["place:winterspring"]=true}},
    ["person:xarti"] = {title="Xar'Ti",kind="Personaje",aliases={"Xar'Ti","Xar’Ti"},body="Xar'Ti entrena raptores en el Poblado Sen'jin. Trabaja con animales procedentes de todo Kalimdor y considera a los Garrasangre de las islas cercanas especialmente valiosos para criar nuevos aliados.",aliasQuestIDs={},en={title="Xar'Ti",aliases={"Xar'Ti","Xar’Ti"},body="Xar'Ti trains raptors in Sen'jin Village. Working with animals from across Kalimdor, he considers the Bloodtalon of the nearby islands especially valuable for raising new allies.",aliasQuestIDs={}},fr={title="Xar'Ti",body="Xar'Ti forme des rapaces à Sen'jin Village. Travaillant avec des animaux de l'ensemble de Kalimdor, il considère le Bloodtalon des îles voisines comme particulièrement précieux pour lever de nouveaux alliés."},de={title="Xar'Ti",body="Xar'Ti trainiert in Sen'jin Village die Raptors. Er arbeitet mit Tieren aus ganz Kalimdor und hält den Bloodtalon von den nahegelegenen Inseln für besonders wertvoll, um neue Verbündete zu gewinnen."},pt={title="Xar'Ti",body="Xar'Ti treina raptores em Sen'jin Village. Trabalhando com animais de toda a Kalimdor, ele considera o Bloodtalon das ilhas próximas especialmente valioso para criar novos aliados."},pl={title="Xar'Ti",body="Xar'Ti szkoli raptory w Sen'jin Village. Pracując ze zwierzętami z całego Kalimdor, uważa Bloodtalon z pobliskich wysp za szczególnie cenne do wychowywania nowych sojuszników."},ru={title="Xar'Ti",body="Xar'Ti обучает рапторов в Sen'jin Village. Работая с животными из Kalimdor, он считает, что Bloodtalon соседних островов особенно ценны для воспитания новых союзников."},references={["place:kalimdor"]=true,["place:senjin-village"]=true}},
    ["person:xavaric"] = {title="Xavaric",kind="Personaje",aliases={"Xavaric"},body="Xavaric es un sátiro de Frondavil relacionado con objetos que emiten una influencia inquietante. Su flauta y otros componentes de su entorno interesan a quienes intentan comprender las formas de la corrupción del bosque.",aliasQuestIDs={},en={title="Xavaric",aliases={"Xavaric"},body="Xavaric is a Felwood satyr associated with objects emitting an unsettling influence. His flute and other materials from his surroundings interest those trying to understand the forest’s corruption.",aliasQuestIDs={}},fr={title="Xavaric",body="Xavaric est un satyre Felwood associé à des objets émettant une influence troublante. Sa flûte et d’autres matériaux de son environnement intéressent ceux qui tentent de comprendre la corruption de la forêt."},de={title="Xavaric",body="Xavaric ist ein Felwood-Satyr, der mit Gegenständen in Verbindung gebracht wird, die einen beunruhigenden Einfluss aussenden. Seine Flöte und andere Materialien aus seiner Umgebung interessieren diejenigen, die versuchen, die Korruption im Wald zu verstehen."},pt={title="Xavaric",body="Xavaric é um sátiro Felwood associado a objetos que emitem uma influência perturbadora. Sua flauta e outros materiais de seu entorno interessam àqueles que tentam entender a corrupção da floresta."},pl={title="Xavaric",body="Xavaric jest satyrem Felwood związanym z przedmiotami emitującymi niepokojący wpływ. Jego flet i inne materiały z otoczenia interesują osoby próbujące zrozumieć skażenie lasu."},ru={title="Xavaric",body="Xavaric - это сатир Felwood, связанный с объектами, излучающими тревожное влияние. Его флейта и другие материалы из его окружения интересуют тех, кто пытается понять разложение леса."},references={["place:felwood"]=true}},
    ["person:xavathras"] = {title="Xavathras",kind="Personaje",aliases={"Xavathras"},body="Xavathras es un sátiro Fuego de Jade de las Ruinas de Constellas. Dirige a quienes propagan la enfermedad entre las criaturas de Frondavil, en oposición al esfuerzo del Círculo Esmeralda por sanar la tierra.",aliasQuestIDs={},en={title="Xavathras",aliases={"Xavathras"},body="Xavathras is a Jadefire satyr in the Ruins of Constellas. He leads those spreading sickness among Felwood’s creatures, opposing the Emerald Circle’s efforts to heal the land.",aliasQuestIDs={}},fr={title="Xavathras",body="Xavathras est un satyre Jadefire dans les Ruines de Constellas. Il dirige ceux qui propagent la maladie parmi les créatures de Felwood, s'opposant aux efforts de l'Emeraude Circle pour guérir la terre."},de={title="Xavathras",body="Xavathras ist ein Jadefire Satyr in den Ruinen von Constellas. Er führt diejenigen an, die Krankheit unter den Kreaturen des Felwood verbreiten, und widersetzt sich den Bemühungen des smaragdgrünen Circle, das Land zu heilen."},pt={title="Xavathras",body="Xavathras é um sátiro Jadefire nas Ruínas de Constellas. Ele lidera aqueles que espalham doenças entre as criaturas do Felwood, opondo-se aos esforços do Emerald Circle para curar a terra."},pl={title="Xavathras",body="Xavathras jest satyrem Jadefire w ruinach Constellas. Prowadzi istoty szerzące chorobę wśród stworzeń Felwood, przeciwstawiając się wysiłkom Emerald Circle na rzecz uzdrowienia ziemi."},ru={title="Xavathras",body="Xavathras - это Jadefire сатир в Руинах Constellas. Он возглавляет тех, кто распространяет болезни среди созданий Felwood, противодействуя усилиям Изумрудного Circle  исцелять землю."},references={["place:felwood"]=true}},
    ["person:xethorr-the-wicked"] = {title="Xethorr el Maldito",kind="Personaje",aliases={"Xethorr","Xethorr el Maldito"},body="Xethorr el Maldito es un sátiro que habita en la Grieta, en lo profundo de los bosques de Teldrassil. Corrompe a las arañas de la zona y busca utilizar su veneno para fines siniestros.",aliasQuestIDs={},en={title="Xethorr the Wicked",aliases={"Xethorr","Xethorr the Wicked"},body="Xethorr the Wicked is a satyr dwelling in the Cleft deep within Teldrassil’s forests. He corrupts local spiders and seeks to use their venom for sinister purposes.",aliasQuestIDs={}},fr={title="Xethorr the Wicked",body="Xethorr the Wicked est un logement satyre dans le Cleft profondément dans les forêts de Teldrassil. Il corrompt les araignées locales et cherche à utiliser leur venin à des fins sinistres."},de={title="Xethorr the Wicked",body="Xethorr the Wicked ist ein Satyr, der im Cleft tief in Teldrassil 'Wäldern lebt. Er korrumpiert lokale Spinnen und versucht, ihr Gift für finstere Zwecke einzusetzen."},pt={title="Xethorr the Wicked",body="Xethorr the Wicked é uma habitação sátira no Cleft nas profundezas das florestas do Teldrassil. Ele corrompe aranhas locais e procura usar seu veneno para fins sinistros."},pl={title="Xethorr the Wicked",body="Xethorr the Wicked jest satyrem mieszkającym w Cleft, głęboko w lasach Teldrassil. Skaża miejscowe pająki i chce wykorzystać ich jad do złowrogich celów."},ru={title="Xethorr the Wicked",body="Xethorr the Wicked — сатир, обитающий в Cleft в глубине лесов Teldrassil. Он развращает местных пауков и пытается использовать их яд в зловещих целях."},references={["place:teldrassil"]=true}},
    ["person:xyton-silverwind"] = {title="Xyton Ventargento",kind="Personaje",aliases={"Xyton","Xyton Ventargento"},body="Xyton Ventargento es el instructor de druidas de Arboleda Thendal. Se encuentra en la base del gran árbol del poblado y orienta a quienes comienzan esa formación. Sus consejos forman parte de las enseñanzas que preparan a los jóvenes druidas para su vida fuera de la comunidad.",aliasQuestIDs={},en={title="Xyton Silverwind",aliases={"Xyton","Xyton Silverwind"},body="Xyton Silverwind is Thendal Grove’s druid trainer. He can be found on the ground floor of the village’s great tree and guides those beginning their training. His counsel is part of preparing young druids for life beyond the community.",aliasQuestIDs={}},fr={title="Xyton Silverwind",body="Xyton Silverwind est l'entraîneur de druide de Thendal Grove. Il se trouve au rez-de-chaussée du grand arbre du village et guide ceux qui commencent leur formation. Ses conseils font partie de la préparation des jeunes druides à la vie au-delà de la communauté."},de={title="Xyton Silverwind",body="Xyton Silverwind ist der Druidentrainer von Thendal Grove. Er ist im Erdgeschoss des großen Baumes des Dorfes zu finden und leitet die Ausbildungsanfänger. Sein Rat ist Teil der Vorbereitung junger Druiden auf das Leben außerhalb der Gemeinschaft."},pt={title="Xyton Silverwind",body="Xyton Silverwind é o treinador druida do Thendal Grove. Ele pode ser encontrado no piso térreo da grande árvore da aldeia e guia aqueles que começam seu treinamento. Seu conselho faz parte da preparação de jovens druidas para a vida além da comunidade."},pl={title="Xyton Silverwind",body="Xyton Silverwind jest instruktorem druidów Thendal Grove. Przebywa na parterze wielkiego drzewa wioski i prowadzi rozpoczynających szkolenie. Jego rady przygotowują młodych druidów do życia poza społecznością."},ru={title="Xyton Silverwind",body="Xyton Silverwind - это тренер друидов Thendal Grove. Он находится на первом этаже деревни и направляет тех, кто начинает обучение. Его советы - часть подготовки молодых друидов к жизни вне общины."},references={["place:thendal-grove"]=true}},
    ["person:yala-windwatcher"] = {title="Yala Vigía del Viento",kind="Personaje",aliases={"Yala","Yala Vigía del Viento"},body="Yala Vigía del Viento es una aprendiz que observa las manifestaciones del viento cerca de las piedras erguidas de Arboleda Thendal. Su estudio se centra en pequeños duendes que reaccionan a las fuerzas, emociones e intenciones de los seres cercanos. Estas manifestaciones se distinguen de los espíritus del viento conscientes que antes vivían allí.",aliasQuestIDs={},en={title="Yala Windwatcher",aliases={"Yala","Yala Windwatcher"},body="Yala Windwatcher is an apprentice observing wind manifestations near Thendal Grove’s standing stones. Her study concerns small sprites that react to the forces, emotions and intentions of nearby creatures. These manifestations differ from the self-aware wind spirits that once lived there.",aliasQuestIDs={}},fr={title="Yala Windwatcher",body="Yala Windwatcher est un apprenti observant les manifestations du vent près des pierres dressées de Thendal Grove. Son étude porte sur les petits sprites qui réagissent aux forces, aux émotions et aux intentions des créatures voisines. Ces manifestations diffèrent des esprits du vent conscients qui y vivaient autrefois."},de={title="Yala Windwatcher",body="Yala Windwatcher ist eine Lehrling, die Winderscheinungen in der Nähe von Thendal Groves stehenden Steinen beobachtet. Ihre Studie befasst sich mit kleinen Spriten, die auf Kräfte, Emotionen und Absichten naher Kreaturen reagieren. Diese Manifestationen unterscheiden sich von den selbstbewussten Windgeistern, die einst dort lebten."},pt={title="Yala Windwatcher",body="Yala Windwatcher é um aprendiz que observa as manifestações do vento perto das pedras de pé do Thendal Grove. Seu estudo diz respeito a pequenos sprites que reagem às forças, emoções e intenções das criaturas próximas. Essas manifestações diferem dos espíritos de vento autoconscientes que uma vez viveram lá."},pl={title="Yala Windwatcher",body="Yala Windwatcher jest uczennicą obserwującą przejawy wiatru przy stojących kamieniach Thendal Grove. Bada małe duszki reagujące na siły, emocje i zamiary pobliskich stworzeń. Te przejawy różnią się od samoświadomych duchów wiatru, które niegdyś tam żyły."},ru={title="Yala Windwatcher",body="Yala Windwatcher - ученик, наблюдающий за проявлениями ветра возле стоящих камней Thendal Grove. Ее исследование касается маленьких призраков, которые реагируют на силы, эмоции и намерения близлежащих существ. Эти проявления отличаются от самосознательных духов ветра, которые когда-то жили там."},references={["place:thendal-grove"]=true}},
    ["person:yama-snowhoof"] = {title="Yama",kind="Personaje",aliases={"Yama"},body="Yama se encuentra en el Puesto del Hachazo y es hermana de Ruul. Reconoce la nobleza de muchos fúrbolgs, aunque distingue a los Piel de Cardo corrompidos que amenazan a quienes se adentran en sus dominios.",aliasQuestIDs={},en={title="Yama Snowhoof",aliases={"Yama","Yama Snowhoof"},body="Yama is found at Splintertree Post and is Ruul’s sister. She recognizes the nobility of many furbolgs while distinguishing the corrupted Thistlefur who threaten those entering their territory.",aliasQuestIDs={}},fr={title="Yama Snowhoof",body="Yama se trouve à Splintertree Post et est la sœur de Ruul. Elle reconnaît la noblesse de nombreux furbolgs tout en distinguant les corrompus Thistlefur qui menacent ceux qui entrent sur leur territoire."},de={title="Yama Snowhoof",body="Yama wird bei Splintertree Post gefunden und ist Ruuls Schwester. Sie erkennt den Adel vieler Furbolgs und unterscheidet die korrupte Thistlefur, die jene, die jene bedrohen, die ihr Territorium sie betreten."},pt={title="Yama Snowhoof",body="Yama é encontrado em Splintertree Post e é irmã de Ruul. Ela reconhece a nobreza de muitos furbolgs enquanto distingue o Thistlefur corrompido que ameaçam aqueles que entram em seu território."},pl={title="Yama Snowhoof",body="Yama przebywa w Splintertree Post i jest siostrą postaci Ruul. Dostrzega szlachetność wielu furbolgów, odróżniając je od skażonych Thistlefur zagrażających osobom wkraczającym na ich terytorium."},ru={title="Yama Snowhoof",body="Yama находится в Splintertree Post и является сестрой Ruul. Она признает благородство многих фурбольгов, отличая коррумпированных Thistlefur, которые угрожают тем, кто входит на их территорию."},references={["organization:thistlefur"]=true,["person:ruul-snowhoof"]=true,["place:splintertree-post"]=true}},
    ["person:yehkinya"] = {title="Yeh'kinya",kind="Personaje",aliases={"Yeh'kinya","Yeh’kinya"},body="Yeh'kinya es un estudioso de Tanaris interesado en la profecía de Mosh'aru y los antiguos conocimientos trols. Sus investigaciones giran en torno a tablillas, rituales y formas de conservar la esencia de seres poderosos.",aliasQuestIDs={},en={title="Yeh'kinya",aliases={"Yeh'kinya","Yeh’kinya"},body="Yeh'kinya is a scholar in Tanaris interested in the prophecy of Mosh'aru and ancient troll knowledge. His investigations concern tablets, rituals and ways of preserving the essence of powerful beings.",aliasQuestIDs={}},fr={title="Yeh'kinya",body="Yeh'kinya est un érudit en Tanaris intéressé par la prophétie de Mosh'aru et la connaissance des trolls anciens. Ses recherches portent sur les tablettes, les rituels et les moyens de préserver l’essence des êtres puissants."},de={title="Yeh'kinya",body="Yeh'kinya ist ein Gelehrter in Tanaris, der sich für die Prophezeiung von Mosh'aru und uraltes Trollwissen interessiert. Seine Untersuchungen betreffen Tabletten, Rituale und Wege, wie das Wesen mächtiger Wesen zu bewahren."},pt={title="Yeh'kinya",body="Yeh'kinya é um estudioso em Tanaris interessado na profecia de Mosh'aru e conhecimento antigo de trolls. Suas investigações dizem respeito a tablets, rituais e formas de preservar a essência de seres poderosos."},pl={title="Yeh'kinya",body="Yeh'kinya jest uczonym w Tanaris zainteresowanym przepowiednią Mosh'aru i pradawną wiedzą trolli. Bada tablice, rytuały oraz sposoby zachowania esencji potężnych istot."},ru={title="Yeh'kinya",body="Yeh'kinya - ученый в Tanaris, заинтересованный в пророчестве Mosh'aru и древних знаниях троллей. Его исследования касаются табличек, ритуалов и способов сохранения сущности могущественных существ."},references={["place:tanaris"]=true}},
    ["person:yelmak"] = {title="Yelmak",kind="Personaje",aliases={"Yelmak"},body="Yelmak dirige un taller de alquimia en Orgrimmar. Concede importancia a la experiencia, los ingredientes locales y el dominio de las técnicas básicas, incluso cuando sus aprendices muestran un talento extraordinario.",aliasQuestIDs={},en={title="Yelmak",aliases={"Yelmak"},body="Yelmak runs an alchemy shop in Orgrimmar. He values experience, local ingredients and mastery of basic techniques, even when his apprentices show extraordinary talent.",aliasQuestIDs={}},fr={title="Yelmak",body="Yelmak exploite un magasin d'alchimie à Orgrimmar. Il valorise l’expérience, les ingrédients locaux et la maîtrise des techniques de base, même lorsque ses apprentis font preuve d’un talent extraordinaire."},de={title="Yelmak",body="Yelmak betreibt in Orgrimmar einen Chemieladen. Er schätzt Erfahrung, lokale Zutaten und die Beherrschung grundlegender Techniken, auch wenn seine Lehrlinge außergewöhnliches Talent zeigen."},pt={title="Yelmak",body="Yelmak administra uma loja de alquimia em Orgrimmar. Ele valoriza a experiência, os ingredientes locais e o domínio das técnicas básicas, mesmo quando seus aprendizes mostram um talento extraordinário."},pl={title="Yelmak",body="Yelmak prowadzi sklep alchemiczny w Orgrimmar. Ceni doświadczenie, miejscowe składniki i opanowanie podstawowych technik, nawet gdy uczniowie wykazują niezwykły talent."},ru={title="Yelmak",body="У Yelmak есть магазин алхимии в Orgrimmar. Он ценит опыт, местные ингредиенты и мастерство в базовых методах, даже когда его ученики проявляют необычайный талант."},references={["place:orgrimmar"]=true}},
    ["person:zalazane"] = {title="Zalazane",kind="Personaje",aliases={"Zalazane"},body="Zalazane es un médico brujo de las Islas del Eco que utiliza magia para dominar la voluntad de otros trols. Sus seguidores y sus prácticas representan una amenaza para la libertad y las tradiciones de los Lanza Negra.",aliasQuestIDs={},en={title="Zalazane",aliases={"Zalazane"},body="Zalazane is a witch doctor in the Echo Isles who uses magic to dominate the will of other trolls. His followers and practices threaten Darkspear freedom and traditions.",aliasQuestIDs={}},fr={title="Zalazane",body="Zalazane est un sorcier dans le Echo Isles qui utilise la magie pour dominer la volonté des autres trolls. Ses adeptes et ses pratiques menacent la liberté et les traditions de Darkspear."},de={title="Zalazane",body="Zalazane ist ein Hexendoktor im Echo Isles, der durch Magie den Willen anderer Trolle beherrscht. Seine Anhänger und Praktiken bedrohen Darkspear Freiheit und Traditionen."},pt={title="Zalazane",body="Zalazane é um feiticeiro no Echo Isles que usa magia para dominar a vontade de outros trolls. Seus seguidores e práticas ameaçam a liberdade e as tradições do Darkspear."},pl={title="Zalazane",body="Zalazane jest znachorem w Echo Isles używającym magii do podporządkowywania sobie woli innych trolli. Jego wyznawcy i praktyki zagrażają wolności oraz tradycjom plemienia Darkspear."},ru={title="Zalazane",body="Zalazane - это ведьма-врач из Echo Isles, которая использует магию, чтобы управлять волей других троллей. Его последователи и практики угрожают свободе и традициям Darkspear."},references={["organization:darkspear-tribe"]=true,["place:echo-isles"]=true}},
    ["person:zamek"] = {title="Zamek",kind="Personaje",aliases={"Zamek"},body="Zamek está relacionado con los equipos de carreras del Desierto de Sal. Sus actividades incluyen ayudar a sus aliados en la competencia por diseños y ventajas sobre los rivales.",aliasQuestIDs={},en={title="Zamek",aliases={"Zamek"},body="Zamek is associated with the racing teams of the Shimmering Flats. His activities include helping his allies compete for designs and advantages over their rivals.",aliasQuestIDs={}},fr={title="Zamek",body="Zamek est associé aux équipes de course de la Shimmering Flats. Ses activités comprennent aider ses alliés à rivaliser pour les conceptions et les avantages sur leurs rivaux."},de={title="Zamek",body="Zamek wird mit den Rennställen der Shimmering Flats in Verbindung gebracht. Zu seinen Aktivitäten gehört es, seinen Verbündeten dabei zu helfen, um Designs und Vorteile gegenüber ihren Rivalen zu konkurrieren."},pt={title="Zamek",body="Zamek está associado às equipes de corrida do Shimmering Flats. Suas atividades incluem ajudar seus aliados a competir por projetos e vantagens sobre seus rivais."},pl={title="Zamek",body="Zamek jest związany z zespołami wyścigowymi Shimmering Flats. Pomaga między innymi swoim sojusznikom rywalizować o projekty i przewagę nad przeciwnikami."},ru={title="Zamek",body="Zamek связана с гоночными командами Shimmering Flats. Его деятельность включает в себя помощь его союзникам конкурировать за дизайн и преимущества над их соперниками."},references={["place:shimmering-flats"]=true}},
    ["person:zamja"] = {title="Zamja",kind="Personaje",aliases={"Zamja"},body="Zamja enseña cocina y reconoce los límites de su propio conocimiento. Cuando sus alumnos necesitan técnicas más avanzadas, los orienta hacia otros maestros con la esperanza de que algún día regresen con nuevas enseñanzas.",aliasQuestIDs={},en={title="Zamja",aliases={"Zamja"},body="Zamja teaches cooking and recognizes the limits of her own knowledge. When pupils need more advanced techniques, she directs them to other masters in the hope that they may one day return with new lessons.",aliasQuestIDs={}},fr={title="Zamja",body="Zamja enseigne la cuisine et reconnaît les limites de ses propres connaissances. Lorsque les élèves ont besoin de techniques plus avancées, elle les dirige vers d'autres maîtres dans l'espoir qu'ils puissent un jour revenir avec de nouvelles leçons."},de={title="Zamja",body="Zamja lehrt Kochen und erkennt die Grenzen ihres eigenen Wissens. Wenn Schüler fortgeschrittenere Techniken brauchen, leitet sie sie zu anderen Meistern, in der Hoffnung, dass sie eines Tages mit neuem Unterricht zurückkehren."},pt={title="Zamja",body="Zamja ensina culinária e reconhece os limites de seu próprio conhecimento. Quando os alunos precisam de técnicas mais avançadas, ela os direciona para outros mestres na esperança de que um dia eles possam retornar com novas lições."},pl={title="Zamja",body="Zamja uczy gotowania i rozpoznaje granice własnej wiedzy. Gdy uczniowie potrzebują bardziej zaawansowanych technik, kieruje ich do innych mistrzów w nadziei, że kiedyś wrócą z nowymi naukami."},ru={title="Zamja",body="Zamja учит готовить и понимает границы собственных знаний. Когда ученикам нужны более совершенные методы, она направляет их к другим мастерам в надежде, что они могут однажды вернуться с новыми уроками."},references={}},
    ["person:zandozan"] = {title="Zando'zan",kind="Personaje",aliases={"Zando'zan","Zando’zan"},body="Zando'zan instruye a miembros de los Mano Destrozada en el Circo de las Sombras de Orgrimmar. Su enseñanza insiste en el dominio del sigilo y del robo como herramientas para afrontar los peligros que esperan a un pícaro.",aliasQuestIDs={},en={title="Zando'zan",aliases={"Zando'zan","Zando’zan"},body="Zando'zan trains Shattered Hand members in Orgrimmar’s Cleft of Shadow. His teaching emphasizes mastery of stealth and theft as tools for facing the dangers awaiting a rogue.",aliasQuestIDs={}},fr={title="Zando'zan",body="Zando'zan entraîne les membres Shattered Hand dans Orgrimmar’s Cleft of Shadow. Son enseignement met l'accent sur la maîtrise de la furtivité et du vol comme outils pour faire face aux dangers qui attendent un voleur."},de={title="Zando'zan",body="Zando'zan trainiert Shattered Hand in Orgrimmar’s Cleft of Shadow. Seine Lehre betont die Beherrschung von Verborgenheit und Diebstahl als Werkzeuge, um den Gefahren zu begegnen, die auf einen Schurken warten."},pt={title="Zando'zan",body="Zando'zan treina membros Shattered Hand em Orgrimmar’s Cleft of Shadow. Seu ensino enfatiza o domínio da furtividade e do roubo como ferramentas para enfrentar os perigos que aguardam um desonesto."},pl={title="Zando'zan",body="Zando'zan szkoli członków Shattered Hand w miejscu zwanym Orgrimmar’s Cleft of Shadow. Podkreśla opanowanie skradania i kradzieży jako narzędzi stawiania czoła niebezpieczeństwom czekającym łotrzyka."},ru={title="Zando'zan",body="Zando'zan обучает членов Shattered Hand в Orgrimmar’s Cleft of Shadow. Его учение подчеркивает мастерство кражи и кражи, как инструмента для противостояния опасности, ожидающей разбойника."},references={["organization:shattered-hand"]=true,["place:orgrimmar"]=true}},
    ["person:zangen-stonehoof"] = {title="Zangen Pezuña Pétrea",kind="Personaje",aliases={"Zangen","Zangen Pezuña Pétrea"},body="Zangen Pezuña Pétrea trabaja en Cima del Trueno con artefactos y materiales de poder. Sus intereses incluyen objetos de los centauros y el uso de agua de las Pozas de la Luna de los elfos de la noche.",aliasQuestIDs={},en={title="Zangen Stonehoof",aliases={"Zangen","Zangen Stonehoof"},body="Zangen Stonehoof works in Thunder Bluff with artifacts and materials of power. His interests include centaur objects and the use of water from night elf moonwells.",aliasQuestIDs={}},fr={title="Zangen Stonehoof",body="Zangen Stonehoof travaille dans Thunder Bluff avec des artefacts et des matériaux de puissance. Ses intérêts incluent les objets centaures et l'utilisation de l'eau des puits de lune des elfes de la nuit."},de={title="Zangen Stonehoof",body="Zangen Stonehoof arbeitet in Thunder Bluff mit Artefakten und Machtmaterialien. Seine Interessen umfassen Zentaur-Objekte und die Nutzung von Wasser aus Nachtelfen-Mondbrunnen."},pt={title="Zangen Stonehoof",body="Zangen Stonehoof trabalha em Thunder Bluff com artefatos e materiais de poder. Seus interesses incluem objetos centauros e o uso de água de poços noturnos de elfo."},pl={title="Zangen Stonehoof",body="Zangen Stonehoof pracuje w Thunder Bluff z artefaktami i materiałami obdarzonymi mocą. Interesują go między innymi przedmioty centaurów oraz wykorzystanie wody z księżycowych studni nocnych elfów."},ru={title="Zangen Stonehoof",body="Zangen Stonehoof работает в Thunder Bluff с артефактами и материалами силы. Его интересы включают в себя предметы кентавра и использование воды из лунных колодцев ночных эльфов."},references={["place:thunder-bluff"]=true}},
    ["person:zankaja"] = {title="Zankaja",kind="Personaje",aliases={"Zankaja"},body="Zankaja vive en los riscos de Orgrimmar y espera el regreso de su compañero. Su historia conserva el lado personal de una ciudad marcada por la guerra, los viajes y las largas ausencias.",aliasQuestIDs={},en={title="Zankaja",aliases={"Zankaja"},body="Zankaja lives on the cliffs of Orgrimmar and waits for her companion’s return. Her story preserves the personal side of a city shaped by war, travel and long absences.",aliasQuestIDs={}},fr={title="Zankaja",body="Zankaja vit sur les falaises de Orgrimmar et attend le retour de son compagnon. Son histoire préserve le côté personnel d'une ville façonnée par la guerre, les voyages et les longues absences."},de={title="Zankaja",body="Zankaja lebt auf den Klippen von Orgrimmar und wartet auf die Rückkehr ihres Gefährten. Ihre Geschichte bewahrt die persönliche Seite einer Stadt, die von Krieg, Reisen und langen Abwesenheiten geprägt ist."},pt={title="Zankaja",body="Zankaja vive nas falésias de Orgrimmar e espera pelo retorno de sua companheira. Sua história preserva o lado pessoal de uma cidade moldada pela guerra, viagens e longas ausências."},pl={title="Zankaja",body="Zankaja mieszka na klifach Orgrimmar i czeka na powrót swojego towarzysza. Jej historia zachowuje osobisty wymiar miasta ukształtowanego przez wojnę, podróże oraz długie nieobecności."},ru={title="Zankaja",body="Zankaja живет на скалах Orgrimmar и ждет возвращения своего спутника. Ее история сохраняет личную сторону города, сформированного войной, путешествиями и длительным отсутствием."},references={["place:orgrimmar"]=true}},
    ["person:zargh"] = {title="Zargh",kind="Personaje",aliases={"Zargh"},body="Zargh prepara carne en El Cruce y mantiene contacto con la tabernera Gryshka de Orgrimmar. Sus envíos muestran cómo los productos de Los Baldíos abastecen la vida cotidiana de la capital de la Horda.",aliasQuestIDs={},en={title="Zargh",aliases={"Zargh"},body="Zargh prepares meat at the Crossroads and maintains contact with Innkeeper Gryshka in Orgrimmar. His shipments show how the Barrens’ products supply everyday life in the Horde capital.",aliasQuestIDs={}},fr={title="Zargh",body="Zargh prépare la viande au Crossroads et maintient le contact avec Innkeeper Gryshka dans Orgrimmar. Ses expéditions montrent comment les produits Barrens fournissent la vie quotidienne dans la capitale Horde."},de={title="Zargh",body="Zargh bereitet im Crossroads Fleisch zu und hält den Kontakt zu Innkeeper Gryshka in Orgrimmar. Seine Lieferungen zeigen, wie die Produkte von Barrens den Alltag in der Hauptstadt Horde bereichern."},pt={title="Zargh",body="Zargh prepara carne no Crossroads e mantém contato com Innkeeper Gryshka em Orgrimmar. Seus embarques mostram como os produtos Barrens fornecem a vida cotidiana na capital Horde."},pl={title="Zargh",body="Zargh przygotowuje mięso w Crossroads i utrzymuje kontakt z postacią Innkeeper Gryshka w Orgrimmar. Przesyłki pokazują, jak produkty Barrens zaopatrują codzienne życie stolicy frakcji Horde."},ru={title="Zargh",body="Zargh готовит мясо в Crossroads и поддерживает контакт с Innkeeper Gryshka в Orgrimmar. Его поставки показывают, как продукция Barrens  обеспечивает повседневную жизнь в столице Horde."},references={["organization:horde"]=true,["person:innkeeper-gryshka"]=true,["place:orgrimmar"]=true,["place:the-barrens"]=true,["place:the-crossroads"]=true}},
    ["person:zarlman-two-moons"] = {title="Zarlman Dos Lunas",kind="Personaje",aliases={"Zarlman","Zarlman Dos Lunas"},body="Zarlman Dos Lunas es un guía espiritual del Poblado Pezuña de Sangre. Conduce el Rito de la Visión, una enseñanza de los ritos de la Madre Tierra que prepara a los jóvenes para ganarse el respeto de los ancestros.",aliasQuestIDs={},en={title="Zarlman Two-Moons",aliases={"Zarlman","Zarlman Two-Moons"},body="Zarlman Two-Moons is a spiritual guide in Bloodhoof Village. He conducts the Rite of Vision, an Earth Mother rite preparing the young to earn their elders’ respect.",aliasQuestIDs={}},fr={title="Zarlman Two-Moons",body="Zarlman Two-Moons est un guide spirituel dans Bloodhoof Village. Il dirige le rite de la vision, un rite Earth Mother qui prépare les jeunes à gagner le respect de leurs aînés."},de={title="Zarlman Two-Moons",body="Zarlman Two-Moons ist ein spiritueller Führer in Bloodhoof Village. Er führt den Ritus der Vision durch, einen Earth Mother-Ritus, der die jungen Menschen darauf vorbereitet, sich den Respekt der Älteren zu verdienen."},pt={title="Zarlman Two-Moons",body="Zarlman Two-Moons é um guia espiritual em Bloodhoof Village. Ele conduz o Rito da Visão, um rito Earth Mother que prepara os jovens para ganhar o respeito dos mais velhos."},pl={title="Zarlman Two-Moons",body="Zarlman Two-Moons jest duchowym przewodnikiem w Bloodhoof Village. Prowadzi obrzęd wizji, rytuał istoty Earth Mother przygotowujący młodych do zdobycia szacunku starszyzny."},ru={title="Zarlman Two-Moons",body="Zarlman Two-Moons - духовный гид в Bloodhoof Village. Он проводит обряд видения, обряд Earth Mother, который готовит молодых людей к уважению старших."},references={["person:earth-mother"]=true,["place:bloodhoof-village"]=true}},
    ["person:zenn-foulhoof"] = {title="Zenn Nauseapezuña",kind="Personaje",aliases={"Zenn","Zenn Nauseapezuña"},body="Zenn Nauseapezuña busca componentes de animales cerca de Dolanaar. Sus promesas de recompensas y su insistencia en la discreción lo distinguen de los guardianes que protegen abiertamente el equilibrio del bosque.",aliasQuestIDs={},en={title="Zenn Foulhoof",aliases={"Zenn","Zenn Foulhoof"},body="Zenn Foulhoof seeks animal ingredients near Dolanaar. His promises of rewards and insistence on discretion distinguish him from the guardians openly protecting the forest’s balance.",aliasQuestIDs={}},fr={title="Zenn Foulhoof",body="Zenn Foulhoof recherche des ingrédients animaux près de Dolanaar. Ses promesses de récompenses et son insistance sur la discrétion le distinguent des gardiens qui protègent ouvertement l’équilibre de la forêt."},de={title="Zenn Foulhoof",body="Zenn Foulhoof sucht tierische Zutaten in der Nähe von Dolanaar. Seine Versprechen der Belohnung und sein Beharren auf Diskretion unterscheiden ihn von den Wächtern, die offen das Gleichgewicht des Waldes Waldes Gleichgewichts zu schützen."},pt={title="Zenn Foulhoof",body="Zenn Foulhoof procura ingredientes animais perto de Dolanaar. Suas promessas de recompensas e insistência em discrição o distinguem dos guardiões que protegem abertamente o equilíbrio da floresta."},pl={title="Zenn Foulhoof",body="Zenn Foulhoof szuka składników zwierzęcych w pobliżu Dolanaar. Obietnice nagród i naleganie na dyskrecję odróżniają go od strażników otwarcie chroniących równowagę lasu."},ru={title="Zenn Foulhoof",body="Zenn Foulhoof ищет животные ингредиенты возле Dolanaar. Его обещания вознаграждения и настойчивость в соблюдении тайны отличают его от хранителей, открыто защищающих баланс леса."},references={["place:dolanaar"]=true}},
    ["person:zevrost"] = {title="Zevrost",kind="Personaje",aliases={"Zevrost"},body="Zevrost conoce los peligros de buscar poder mediante las artes oscuras. Desconfía de la ambición de los brujos y advierte que la corrupción y la dependencia pueden convertir a un aspirante a dominador en esclavo de lo que pretende controlar.",aliasQuestIDs={},en={title="Zevrost",aliases={"Zevrost"},body="Zevrost knows the dangers of seeking power through the dark arts. He distrusts warlocks’ ambition and warns that corruption and dependence can make an aspiring master a slave to the forces they seek to control.",aliasQuestIDs={}},fr={title="Zevrost",body="Zevrost connaît les dangers de la recherche du pouvoir à travers les arts sombres. Il se méfie de l’ambition des démonistes et avertit que la corruption et la dépendance peuvent faire d’un aspirant maître un esclave des forces qu’ils cherchent à contrôler."},de={title="Zevrost",body="Zevrost kennt die Gefahren des Strebens nach Macht durch dunkle Künste. Er misstraut dem Ehrgeiz der Hexenmeister und warnt, dass Korruption und Abhängigkeit einen aufstrebenden Herrn zu einem Sklaven der Kräfte machen können, die sie kontrollieren wollen."},pt={title="Zevrost",body="Zevrost conhece os perigos de buscar poder através das artes das trevas. Ele desconfia da ambição dos bruxos e adverte que a corrupção e a dependência podem tornar um aspirante a mestre um escravo das forças que procuram controlar."},pl={title="Zevrost",body="Zevrost zna niebezpieczeństwa poszukiwania mocy poprzez mroczne sztuki. Nie ufa ambicji czarnoksiężników i ostrzega, że skażenie oraz zależność mogą zamienić przyszłego mistrza w niewolnika sił, które chce kontrolować."},ru={title="Zevrost",body="Zevrost знает опасность поиска силы с помощью темных сил. Он не доверяет амбициям чернокнижников и предупреждает, что коррупция и зависимость могут сделать начинающего мастера рабом сил, которые они стремятся контролировать."},references={}},
    ["person:zilzibin-drumlore"] = {title="Zilzibin Tambor Sabio",kind="Personaje",aliases={"Zil","Zilzibin","Zilzibin Tambor Sabio"},body="Zilzibin Tambor Sabio es un erudito trol de Orgrimmar dedicado al estudio de los seres vivos de Azeroth. Sus conocimientos de historia natural ayudan a interpretar informes sobre criaturas poco conocidas.",aliasQuestIDs={},en={title="Zilzibin Drumlore",aliases={"Zilzibin","Zilzibin Drumlore"},body="Zilzibin Drumlore is a troll scholar in Orgrimmar devoted to studying Azeroth’s living creatures. His knowledge of natural history helps interpret reports about unfamiliar beings.",aliasQuestIDs={}},fr={title="Zilzibin Drumlore",body="Zilzibin Drumlore est un chercheur de troll dans Orgrimmar consacré à l'étude des créatures vivantes de Azeroth. Sa connaissance de l'histoire naturelle aide à interpréter les rapports sur des êtres inconnus."},de={title="Zilzibin Drumlore",body="Zilzibin Drumlore ist ein Trollforscher in Orgrimmar, der sich dem Studium der Lebefleißigen Lebewesen Azeroth widmet. Seine Kenntnisse der Naturgeschichte helfen bei der Interpretation von Berichten über unbekannte Wesen."},pt={title="Zilzibin Drumlore",body="Zilzibin Drumlore é um estudioso de trolls no Orgrimmar dedicado a estudar as criaturas vivas do Azeroth. Seu conhecimento da história natural ajuda a interpretar relatórios sobre seres desconhecidos."},pl={title="Zilzibin Drumlore",body="Zilzibin Drumlore jest trollim uczonym w Orgrimmar poświęcającym się badaniu żywych stworzeń Azeroth. Wiedza o historii naturalnej pomaga mu interpretować raporty dotyczące nieznanych istot."},ru={title="Zilzibin Drumlore",body="Zilzibin Drumlore - учёный троллей в Orgrimmar, занимающийся изучением живых существ Azeroth. Его знания естественной истории помогают интерпретировать сообщения о незнакомых существах."},references={["place:azeroth"]=true,["place:orgrimmar"]=true}},
    ["person:ziz-fizziks"] = {title="Ziz Fizziks",kind="Personaje",aliases={"Ziz","Ziz Fizziks"},body="Ziz Fizziks es un técnico que busca información sobre las operaciones industriales de Sierra Espolón. Mantiene contactos entre los trabajadores para descubrir los planes de quienes controlan las minas.",aliasQuestIDs={},en={title="Ziz Fizziks",aliases={"Ziz","Ziz Fizziks"},body="Ziz Fizziks is a technician seeking information on industrial operations in the Stonetalon Mountains. He maintains contacts among the workers to discover the plans of those controlling the mines.",aliasQuestIDs={}},fr={title="Ziz Fizziks",body="Ziz Fizziks est un technicien à la recherche d'informations sur les opérations industrielles dans le Stonetalon Mountains. Il entretient des contacts entre les ouvriers pour découvrir les plans de ceux qui contrôlent les mines."},de={title="Ziz Fizziks",body="Ziz Fizziks ist Techniker auf der Suche nach Informationen über Industriebetriebe im Stonetalon Mountains. Er unterhält Kontakte zwischen den Arbeitern, um die Pläne derjenigen zu entdecken, die die die die das Bergwerk kontrollieren."},pt={title="Ziz Fizziks",body="Ziz Fizziks é um técnico que procura informações sobre operações industriais no Stonetalon Mountains. Ele mantém contatos entre os trabalhadores para descobrir os planos daqueles que controlam as minas."},pl={title="Ziz Fizziks",body="Ziz Fizziks jest technikiem szukającym informacji o działalności przemysłowej w regionie Stonetalon Mountains. Utrzymuje kontakty wśród robotników, aby poznawać plany osób kontrolujących kopalnie."},ru={title="Ziz Fizziks",body="Ziz Fizziks - это техник, ищущий информацию о промышленной работе в Stonetalon Mountains. Он поддерживает контакты между рабочими, чтобы узнать планы тех, кто контролирует шахты."},references={["place:stonetalon-mountains"]=true}},
    ["person:zjolnir"] = {title="Zjolnir",kind="Personaje",aliases={"Zjolnir"},body="Zjolnir se ocupa de los raptores de monta en Durotar. Ofrece animales de colores como el verde, el turquesa y el violeta, una variedad que refleja el lugar de estos reptiles entre los compañeros de viaje de los trols.",aliasQuestIDs={},en={title="Zjolnir",aliases={"Zjolnir"},body="Zjolnir handles riding raptors in Durotar. His animals come in colors including green, turquoise, and violet, reflecting these reptiles’ place among the trolls’ traveling companions.",aliasQuestIDs={}},fr={title="Zjolnir",body="Zjolnir gère l'équitation rapaces dans Durotar. Ses animaux sont de couleur verte, turquoise et violette, reflétant la place de ces reptiles parmi les compagnons de voyage des trolls."},de={title="Zjolnir",body="Zjolnir kümmert sich in Durotar um reitende Raptoren. Seine Tiere gibt es in den Farben Grün, Türkis und Violett, was den Platz dieser Reptilien unter den Reisebegleitern der Trolle widerspiegelt."},pt={title="Zjolnir",body="Zjolnir lida montando raptores em Durotar. Seus animais vêm em cores, incluindo verde, turquesa e violeta, refletindo o lugar desses répteis entre os companheiros de viagem dos trolls."},pl={title="Zjolnir",body="Zjolnir zajmuje się raptorami do jazdy w Durotar. Jego zwierzęta mają między innymi zielone, turkusowe i fioletowe ubarwienie, odzwierciedlające miejsce tych gadów wśród towarzyszy podróży trolli."},ru={title="Zjolnir",body="Zjolnir управляет верховыми рапторами в Durotar. Его животные бывают в цветах, включая зеленый, бирюзовый и фиолетовый, отражая место этих рептилий среди троллей."},references={["place:durotar"]=true}},
    ["person:zor-lonetree"] = {title="Zor Árbol Solitario",kind="Personaje",aliases={"Zor","Zor Árbol Solitario"},body="Zor Árbol Solitario conoce el ámbito político de la Alianza desde Orgrimmar. Su familiaridad con la nobleza de Ventormenta permite interpretar objetos e historias cuyo significado otros miembros de la Horda desconocen.",aliasQuestIDs={},en={title="Zor Lonetree",aliases={"Zor","Zor Lonetree"},body="Zor Lonetree knows Alliance political affairs from Orgrimmar. His familiarity with Stormwind’s nobility helps interpret objects and stories whose significance other Horde members do not understand.",aliasQuestIDs={}},fr={title="Zor Lonetree",body="Zor Lonetree connaît Alliance affaires politiques de Orgrimmar. Sa familiarité avec la noblesse de Stormwind aide à interpréter des objets et des histoires dont les autres membres du Horde ne comprennent pas la signification."},de={title="Zor Lonetree",body="Zor Lonetree kennt Alliance politische Angelegenheiten von Orgrimmar. Seine Vertrautheit mit dem Adel des Stormwind hilft, Objekte und Geschichten zu interpretieren, deren Bedeutung andere Horde-Mitglieder nicht verstehen."},pt={title="Zor Lonetree",body="Zor Lonetree conhece os assuntos políticos Alliance da Orgrimmar. Sua familiaridade com a nobreza de Stormwind ajuda a interpretar objetos e histórias cujo significado outros membros Horde não entendem."},pl={title="Zor Lonetree",body="Zor Lonetree zna sprawy polityczne frakcji Alliance, działając z Orgrimmar. Znajomość szlachty Stormwind pomaga mu wyjaśniać przedmioty i historie, których znaczenia inni członkowie Horde nie rozumieją."},ru={title="Zor Lonetree",body="Zor Lonetree знает политические дела Alliance от Orgrimmar. Его знакомство с дворянством Stormwind помогает интерпретировать предметы и истории, значение которых другие члены Horde не понимают."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:orgrimmar"]=true,["place:stormwind"]=true}},
    ["person:zorbin-fandazzle"] = {title="Zorbin Hipnoviento",kind="Personaje",aliases={"Zorbin","Zorbin Hipnoviento"},body="Zorbin Hipnoviento es un ingeniero de La Costa Olvidada de Feralas. Sus inventos, como el Ultra-reductor, relacionan el negocio de la ingeniería con el aprovechamiento de las criaturas y elementos del entorno.",aliasQuestIDs={},en={title="Zorbin Fandazzle",aliases={"Zorbin","Zorbin Fandazzle"},body="Zorbin Fandazzle is an engineer on the Forgotten Coast in Feralas. His inventions, such as the Ultra-Shrinker, connect the business of engineering with the use of nearby creatures and elements.",aliasQuestIDs={}},fr={title="Zorbin Fandazzle",body="Zorbin Fandazzle est ingénieur sur la côte oubliée dans Feralas. Ses inventions, telles que la Ultra-Shrinker, relient l'activité de l'ingénierie à l'utilisation de créatures et d'éléments à proximité."},de={title="Zorbin Fandazzle",body="Zorbin Fandazzle ist Ingenieur an der vergessenen Küste in Feralas. Seine Erfindungen, wie der Ultra-Shrinker, verbinden das Ingenieursgeschäft mit dem Einsatz nahe gelegener Kreaturen und Elemente."},pt={title="Zorbin Fandazzle",body="Zorbin Fandazzle é um engenheiro na Costa Esquecida em Feralas. Suas invenções, como o Ultra-Shrinker, conectam o negócio de engenharia com o uso de criaturas e elementos próximos."},pl={title="Zorbin Fandazzle",body="Zorbin Fandazzle jest inżynierem na zapomnianym wybrzeżu w Feralas. Jego wynalazki, takie jak Ultra-Shrinker, łączą interesy inżynierii z wykorzystywaniem pobliskich stworzeń oraz żywiołów."},ru={title="Zorbin Fandazzle",body="Zorbin Fandazzle - инженер на Забужденном побережье в Feralas. Его изобретения, такие как Ultra-Shrinker, связывают бизнес инженерии с использованием близлежащих существ и элементов."},references={["place:feralas"]=true}},
    ["person:zureetha-fargaze"] = {title="Zureetha Vistalonga",kind="Personaje",aliases={"Zureetha","Zureetha Vistalonga"},body="Zureetha Vistalonga es una guía del Valle de los Retos. Además de instruir a los recién llegados, intenta contener la corrupción de los cultistas del Filo Ardiente y sus criaturas.",aliasQuestIDs={},en={title="Zureetha Fargaze",aliases={"Zureetha","Zureetha Fargaze"},body="Zureetha Fargaze is a guide in the Valley of Trials. Besides teaching newcomers, she tries to contain the corruption spread by Burning Blade cultists and their creatures.",aliasQuestIDs={}},fr={title="Zureetha Fargaze",body="Zureetha Fargaze est un guide dans le Valley of Trials. En plus d'enseigner aux nouveaux arrivants, elle tente de contenir la corruption répandue par les cultes Burning Blade et leurs créatures."},de={title="Zureetha Fargaze",body="Zureetha Fargaze ist eine Führerin in der Valley of Trials. Neben der Belehrung von Neuankömmlingen versucht sie, die Korruption einzudämmen, die von Burning Blade Kultisten und ihren Geschöpfen verbreitet wird."},pt={title="Zureetha Fargaze",body="Zureetha Fargaze é um guia no Valley of Trials. Além de ensinar os recém-chegados, ela tenta conter a corrupção espalhada pelos cultos Burning Blade e suas criaturas."},pl={title="Zureetha Fargaze",body="Zureetha Fargaze jest przewodniczką w Valley of Trials. Oprócz szkolenia przybyszów próbuje powstrzymywać skażenie szerzone przez kultystów Burning Blade i ich stworzenia."},ru={title="Zureetha Fargaze",body="Zureetha Fargaze - это гид в Valley of Trials. Помимо обучения новичков, она пытается сдержать коррупцию, распространяемую культовыми людьми Burning Blade и их созданиями."},references={["organization:burning-blade"]=true,["place:valley-of-trials"]=true}},
    ["place:aerie-peak"] = {title="Pico Nidal",kind="Lugar",aliases={"Pico Nidal"},body="Pico Nidal es una comunidad de los enanos Martillo Salvaje en las Tierras del Interior. Sus habitantes mantienen una estrecha relación con los grifos y con las tradiciones de su pueblo.",aliasQuestIDs={},en={title="Aerie Peak",aliases={"Aerie Peak"},body="Aerie Peak is a Wildhammer dwarven community in the Hinterlands. Its inhabitants maintain close ties with gryphons and with their people’s traditions.",aliasQuestIDs={}},fr={title="Aerie Peak",body="Aerie Peak est une communauté naine Wildhammer dans le Hinterlands. Ses habitants entretiennent des liens étroits avec les griffons et les traditions de leur peuple."},de={title="Aerie Peak",body="Aerie Peak ist eine Wildhammer-Zwergengemeinschaft im Hinterlands. Seine Bewohner pflegen enge Beziehungen zu den Greifen und zu den Traditionen ihres Volkes."},pt={title="Aerie Peak",body="Aerie Peak é uma comunidade anã Wildhammer no Hinterlands. Seus habitantes mantêm laços estreitos com os grifos e com as tradições de seu povo."},pl={title="Aerie Peak",body="Aerie Peak to społeczność krasnoludów Wildhammer w Hinterlands. Jej mieszkańcy utrzymują bliskie więzi z gryfami i tradycjami swojego ludu."},ru={title="Aerie Peak",body="Aerie Peak - это сообщество карликов Wildhammer в Hinterlands. Ее жители поддерживают тесные связи с грифонами и традициями своего народа."},references={["organization:wildhammer"]=true,["place:hinterlands"]=true}},
    ["place:agamand-family-crypt"] = {title="Cripta de la Familia Agamand",kind="Lugar",aliases={"Cripta de la Familia","Cripta de la Familia Agamand"},body="La cripta de los Agamand alberga a los ancestros de una familia de Tirisfal. Bajo la ocupación de la Plaga, ese lugar funerario se ha convertido en un puesto de mando del capitán Dargol.",aliasQuestIDs={},en={title="Agamand Family Crypt",aliases={"Agamand Family Crypt","Family Crypt"},body="The Agamand crypt holds the ancestors of a Tirisfal family. Under Scourge occupation, the burial site has become Captain Dargol's command post.",aliasQuestIDs={}},fr={title="Agamand Family Crypt",body="La crypte Agamand contient les ancêtres d'une famille Tirisfal. Sous l'occupation Scourge, le site funéraire est devenu le poste de commandement de Captain Dargol."},de={title="Agamand Family Crypt",body="Die Krypta des Agamand beherbergt die Vorfahren einer Familie Tirisfal. Unter Scourge wurde die Begräbnisstätte zum Kommandostand von Captain Dargol."},pt={title="Agamand Family Crypt",body="A cripta Agamand detém os ancestrais de uma família Tirisfal. Sob a ocupação Scourge, o local do enterro tornou-se o posto de comando do Captain Dargol."},pl={title="Agamand Family Crypt",body="Krypta Agamand kryje przodków rodziny z Tirisfal. Pod okupacją Scourge miejsce pochówku stało się stanowiskiem dowodzenia Captain Dargol."},ru={title="Agamand Family Crypt",body="В крипте Agamand хранятся предки семейства Tirisfal. Под оккупацией Scourge, место захоронения стало командным пунктом Captain Dargol."},references={["npc:captain-dargol"]=true,["organization:agamand-family"]=true,["organization:scourge"]=true,["place:tirisfal-glades"]=true}},
    ["place:agamand-mills"] = {title="Molinos de Agamand",kind="Lugar",aliases={"Molinos de Agamand"},body="Los Molinos de Agamand son una antigua propiedad familiar de Tirisfal ocupada por la Plaga. Su cripta conserva los restos de los Agamand y constituye una posición importante para los no-muertos hostiles.",aliasQuestIDs={},en={title="Agamand Mills",aliases={"Agamand Mills"},body="Agamand Mills is a former family estate in Tirisfal occupied by the Scourge. Its crypt holds the Agamands' remains and forms an important position for hostile undead.",aliasQuestIDs={}},fr={title="Agamand Mills",body="Agamand Mills est un ancien domaine familial à Tirisfal occupé par the Scourge. Sa crypte contient les restes Agamands ' et forme une position importante pour les morts-vivants hostiles."},de={title="Agamand Mills",body="Agamand Mills ist ein ehemaliges Familienanwesen in Tirisfal, das the Scourge bewohnt. Seine Krypta birgt die sterblichen Überreste des Agamands und stellt eine wichtige Stellung für feindliche Untote dar."},pt={title="Agamand Mills",body="Agamand Mills é uma antiga propriedade familiar em Tirisfal ocupada por the Scourge. Sua cripta detém o Agamands ' permanece e forma uma posição importante para mortos-vivos hostis."},pl={title="Agamand Mills",body="Agamand Mills jest dawną rodzinną posiadłością w Tirisfal zajętą przez siły znane jako the Scourge. W krypcie spoczywają szczątki rodziny Agamands, a samo miejsce jest ważną pozycją wrogich nieumarłych."},ru={title="Agamand Mills",body="Agamand Mills - это бывшее семейное поместье в Tirisfal, занятое the Scourge. В его склепе находятся останки Agamands и это важное место для враждебных неживых."},references={["organization:agamand-family"]=true,["organization:scourge"]=true,["place:tirisfal-glades"]=true}},
    ["place:ahnqiraj"] = {title="Ahn'Qiraj",kind="Lugar",aliases={"Ahn'Qiraj","Ahn’Qiraj"},body="Ahn'Qiraj es un antiguo dominio qiraji de Silithus. Sus templos y cámaras albergan poderes y criaturas que han llevado a los defensores de Kalimdor a reunir fuerzas para contener la amenaza.",aliasQuestIDs={},en={title="Ahn'Qiraj",aliases={"Ahn'Qiraj","Ahn’Qiraj"},body="Ahn'Qiraj is an ancient qiraji domain in Silithus. Its temples and chambers harbor powers and creatures that have led Kalimdor’s defenders to gather forces to contain the threat.",aliasQuestIDs={}},fr={title="Ahn'Qiraj",body="Ahn'Qiraj est un ancien domaine qiraji dans Silithus. Ses temples et ses chambres abritent des pouvoirs et des créatures qui ont conduit les défenseurs de Kalimdor à rassembler leurs forces pour contenir la menace."},de={title="Ahn'Qiraj",body="Ahn'Qiraj ist eine uralte qiraji Domäne in Silithus. Seine Tempel und Kammern beherbergen Mächte und Geschöpfe, die die die die Verteidiger des Kalimdor veranlasst haben, Kräfte zu sammeln, um die Bedrohung einzudämmen."},pt={title="Ahn'Qiraj",body="Ahn'Qiraj é um antigo domínio qiraji em Silithus. Seus templos e câmaras abrigam poderes e criaturas que levaram os defensores do Kalimdor a reunir forças para conter a ameaça."},pl={title="Ahn'Qiraj",body="Ahn'Qiraj to pradawna domena qiraji w Silithus. Świątynie i komnaty kryją potęgi oraz stworzenia, które skłoniły obrońców kontynentu Kalimdor do zgromadzenia sił mających powstrzymać zagrożenie."},ru={title="Ahn'Qiraj",body="Ahn'Qiraj - это древний домен qiraji в Silithus. В храмах и камерах хранятся силы и существа, которые привели защитников Kalimdor к сбору сил для сдерживания угрозы."},references={["people:qiraji"]=true,["place:kalimdor"]=true,["place:silithus"]=true}},
    ["place:aldrassil"] = {title="Aldrassil",kind="Lugar",aliases={"Aldrassil"},body="Aldrassil es un árbol habitado de Cañada Umbría. Sus salas reúnen a instructores y guías de los elfos de la noche, mientras Tenaron Tormentagarre atiende a los visitantes desde la estancia más alta.",aliasQuestIDs={},en={title="Aldrassil",aliases={"Aldrassil"},body="Aldrassil is an inhabited tree in Shadowglen. Its rooms bring together night elf trainers and guides, while Tenaron Stormgrip receives visitors from the highest chamber.",aliasQuestIDs={}},fr={title="Aldrassil",body="Aldrassil est un arbre habité dans Shadowglen. Ses salles réunissent des entraîneurs et des guides elfes de nuit, tandis que Tenaron Stormgrip reçoit des visiteurs de la plus haute chambre."},de={title="Aldrassil",body="Aldrassil ist ein bewohnter Baum in Shadowglen. Seine Räume bringen Nachtelfentrainer und Führer zusammen, während Tenaron Stormgrip Besucher aus der obersten Kammer empfängt."},pt={title="Aldrassil",body="Aldrassil é uma árvore habitada em Shadowglen. Seus quartos reúnem instrutores e guias de elfo noturnos, enquanto o Tenaron Stormgrip recebe visitantes da câmara mais alta."},pl={title="Aldrassil",body="Aldrassil jest zamieszkanym drzewem w Shadowglen. W jego komnatach spotykają się nauczyciele i przewodnicy nocnych elfów, a Tenaron Stormgrip przyjmuje gości w najwyżej położonej sali."},ru={title="Aldrassil",body="Aldrassil - это обитаемое дерево в Shadowglen. В его комнатах собраны инструкторы и гиды ночных эльфов, в то время как Tenaron Stormgrip принимает посетителей из высшей камеры."},references={["person:tenaron-stormgrip"]=true,["place:shadowglen"]=true}},
    ["place:alexston-farmstead"] = {title="Hacienda de Alexston",kind="Lugar",aliases={"Hacienda de Alexston"},body="La Hacienda de Alexston forma parte del paisaje agrícola de los Páramos de Poniente. Los saqueos de los Defias reflejan allí el deterioro de la seguridad que obliga a los habitantes de la región a organizar su propia defensa.",aliasQuestIDs={},en={title="Alexston Farmstead",aliases={"Alexston","Alexston Farmstead"},body="Alexston Farmstead belongs to Westfall’s farming countryside. Defias raids there reflect the collapse of security that forces local people to organize their own defense.",aliasQuestIDs={}},fr={title="Alexston Farmstead",body="Alexston Farmstead appartient à la campagne agricole de Westfall. Les raids Defias là-bas reflètent l'effondrement de la sécurité qui oblige les populations locales à organiser leur propre défense."},de={title="Alexston Farmstead",body="Alexston Farmstead gehört zur bäuerlichen Landschaft von Westfall. Defias-Razzien dort spiegeln den Zusammenbruch der Sicherheit wider, der die die die die Menschen vor Ort zwingt, ihre eigene Verteidigung zu organisieren."},pt={title="Alexston Farmstead",body="Alexston Farmstead pertence ao campo agrícola de Westfall. Os ataques Defias refletem o colapso da segurança que força a população local a organizar sua própria defesa."},pl={title="Alexston Farmstead",body="Alexston Farmstead należy do rolniczych terenów Westfall. Najazdy Defias odzwierciedlają załamanie bezpieczeństwa, które zmusza mieszkańców do organizowania własnej obrony."},ru={title="Alexston Farmstead",body="Alexston Farmstead принадлежит сельской местности Westfall. Налеты Defias отражают крах безопасности, что заставляет местных жителей организовать свою собственную оборону."},references={["organization:defias-brotherhood"]=true,["place:westfall"]=true}},
    ["place:altar-of-zul"] = {title="Altar de Zul",kind="Lugar",aliases={"Altar de Zul"},body="El Altar de Zul es un lugar de los trols Vilrama en las Tierras del Interior. Su ubicación marca uno de los puntos que los exploradores examinan al investigar las actividades de esa tribu.",aliasQuestIDs={},en={title="Altar of Zul",aliases={"Altar of Zul"},body="The Altar of Zul is a Vilebranch troll site in the Hinterlands. Its location is one of the places scouts examine when investigating that tribe’s activities.",aliasQuestIDs={}},fr={title="Altar of Zul",body="Le Altar of Zul est un site de trolls Vilebranch dans le Hinterlands. Son emplacement est l'un des endroits que les scouts examinent lorsqu'ils enquêtent sur les activités de cette tribu."},de={title="Altar of Zul",body="Der Altar of Zul ist eine Vilebranch-Troll-Seite im Hinterlands. Sein Standort ist einer der Orte, den Späher untersuchen, wenn sie die Aktivitäten dieses Stammes untersuchen."},pt={title="Altar of Zul",body="O Altar of Zul é um site de trolls Vilebranch no Hinterlands. Sua localização é um dos locais que os escoteiros examinam ao investigar as atividades dessa tribo."},pl={title="Altar of Zul",body="Altar of Zul to miejsce trolli Vilebranch w Hinterlands. Należy do punktów sprawdzanych przez zwiadowców badających działalność tego plemienia."},ru={title="Altar of Zul",body="Altar of Zul - это сайт троллей Vilebranch в Hinterlands. Его местоположение является одним из мест, которые скауты изучают при расследовании деятельности этого племени."},references={["organization:vilebranch"]=true,["place:hinterlands"]=true}},
    ["place:alterac-mountains"] = {title="Montañas de Alterac",kind="Lugar",aliases={"Alterac","Montañas de Alterac"},body="Las Montañas de Alterac son tierras elevadas donde los viajeros encuentran campamentos, ruinas y habitantes apartados. Sus cumbres también atraen a quienes estudian los elementales y buscan conocimientos fuera de las ciudades.",aliasQuestIDs={},en={title="Alterac Mountains",aliases={"Alterac","Alterac Mountains"},body="The Alterac Mountains are uplands where travelers encounter camps, ruins and isolated inhabitants. Their heights also attract students of the elements seeking knowledge away from the cities.",aliasQuestIDs={}},fr={title="Alterac Mountains",body="Les Alterac Mountains sont des hautes terres où les voyageurs rencontrent des camps, des ruines et des habitants isolés. Leurs hauteurs attirent également les étudiants des éléments qui cherchent la connaissance loin des villes."},de={title="Alterac Mountains",body="Die Alterac Mountains sind Hochebenen, wo Reisende auf Lager, Ruinen und isolierte Bewohner treffen. Ihre Höhen ziehen auch Studenten jener Elemente an, die außerhalb der Städte Wissen suchen."},pt={title="Alterac Mountains",body="O Alterac Mountains são terras altas onde os viajantes encontram acampamentos, ruínas e habitantes isolados. Suas alturas também atraem os alunos dos elementos que buscam conhecimento longe das cidades."},pl={title="Alterac Mountains",body="Alterac Mountains to wyżynna kraina obozów, ruin i odosobnionych mieszkańców. Jej szczyty przyciągają także badaczy żywiołów poszukujących wiedzy z dala od miast."},ru={title="Alterac Mountains",body="Alterac Mountains - это высокие земли, где путешественники встречают лагеря, руины и изолированных жителей. Их высоты также привлекают студентов стихийных условий, ищущих знания вдали от городов."},references={}},
    ["place:alterac-valley"] = {title="Valle de Alterac",kind="Lugar",aliases={"Valle de Alterac"},body="El Valle de Alterac es un territorio disputado por la Horda y la Alianza, donde los Lobo Gélido y los Pico Tormenta han convertido la lucha por recursos en una guerra de posiciones. Minas, fortalezas y cementerios sostienen el avance de ambos ejércitos.",aliasQuestIDs={},en={title="Alterac Valley",aliases={"Alterac Valley"},body="Alterac Valley is contested by the Horde and Alliance, where the Frostwolves and Stormpike have turned a struggle over resources into positional warfare. Mines, keeps and graveyards sustain both armies' advance.",aliasQuestIDs={}},fr={title="Alterac Valley",body="Alterac Valley est disputée par la Horde et l'Alliance. Les Frostwolves et les Stormpike y ont transformé une lutte pour les ressources en guerre de positions. Mines, forteresses et cimetières soutiennent la progression des deux armées."},de={title="Alterac Valley",body="Alterac Valley bekommt es mit den Horde und Alliance zu tun, wo Frostwolves und Stormpike den Kampf um Ressourcen in Stellungskrieg verwandeln. Minen, Festungen und Friedhöfe sichern den Vormarsch beider Armeen."},pt={title="Alterac Valley",body="Alterac Valley é contestado pelo Horde e Alliance, onde o Frostwolves and Stormpike transformaram uma luta por recursos em guerra posicional. Minas, mantimentos e cemitérios sustentam o avanço de ambos os exércitos."},pl={title="Alterac Valley",body="Alterac Valley jest obszarem spornym między sojuszami znanymi jako the Horde i Alliance, gdzie Frostwolves i Stormpike zmienili walkę o zasoby w wojnę pozycyjną. Kopalnie, warownie i cmentarze podtrzymują postępy obu armii."},ru={title="Alterac Valley",body="Alterac Valley соперничает с Horde и Alliance, где Frostwolves и Stormpike превратили борьбу за ресурсы в позиционную войну. Шахты, крепости и кладбища поддерживают продвижение обеих армий."},references={["organization:alliance"]=true,["organization:frostwolf-clan"]=true,["organization:horde"]=true,["organization:stormpike-expedition"]=true,["place:alterac-mountains"]=true}},
    ["place:althers-mill"] = {title="Molino de Alther",kind="Lugar",aliases={"Molino de Alther"},body="El Molino de Alther es una instalación de Crestagrana ligada al suministro de madera. La presencia de tarántulas en sus alrededores interfiere con el trabajo y con las obras que dependen de sus recursos.",aliasQuestIDs={},en={title="Alther's Mill",aliases={"Alther","Alther's Mill","Alther’s Mill"},body="Alther’s Mill is a Redridge installation tied to the timber supply. Tarantulas in the area interfere with its work and with construction that depends on its resources.",aliasQuestIDs={}},fr={title="Alther's Mill",body="Alther’s Mill est une installation Redridge liée à l'approvisionnement en bois. Tarantulas dans la zone interfère avec son travail et avec la construction qui dépend de ses ressources."},de={title="Alther's Mill",body="Alther’s Mill ist eine Redridge-Installation, die an den Holzlieferanten gebunden ist. Tarantulas in der Gegend stört seine Arbeit und die Bautätigkeit, die von seinen Ressourcen abhängig ist."},pt={title="Alther's Mill",body="Alther’s Mill é uma instalação Redridge ligada ao fornecimento de madeira. Tarantulas na área interfere com seu trabalho e com a construção que depende de seus recursos."},pl={title="Alther's Mill",body="Alther’s Mill to zakład w Redridge związany z dostawami drewna. Miejscowe tarantule utrudniają jego pracę oraz budowę obiektów zależnych od jego zasobów."},ru={title="Alther's Mill",body="Alther’s Mill - это установка Redridge, связанная с поставкой древесины. Tarantulas в этом районе мешают его работе и строительству, которое зависит от его ресурсов."},references={["place:redridge-mountains"]=true}},
    ["place:ambermill"] = {title="Molino Ámbar",kind="Lugar",aliases={"Molino Ámbar"},body="Molino Ámbar es una población humana de Argénteos que recibe apoyo de los magos de Dalaran. Sus vínculos con suministros y estudios arcanos hacen que el lugar tenga una importancia mayor de la que su aspecto remoto sugiere.",aliasQuestIDs={},en={title="Ambermill",aliases={"Ambermill"},body="Ambermill is a human settlement in Silverpine supported by Dalaran's wizards. Its connections with supply routes and arcane research give the place greater importance than its remote appearance suggests.",aliasQuestIDs={}},fr={title="Ambermill",body="Ambermill est un établissement humain dans Silverpine soutenu par les assistants de Dalaran. Ses connexions avec les voies d'approvisionnement et la recherche arcanique donnent à la place plus d'importance que son apparence lointaine ne le suggère."},de={title="Ambermill",body="Ambermill ist eine menschliche Siedlung in Silverpine, die von Dalaran 'Zauberern unterstützt wird. Seine Verbindungen zu Versorgungsrouten und geheimnisvolle Forschung verleihen dem Ort größere Bedeutung, als sein abgelegenes Erscheinungsbild vermuten lässt."},pt={title="Ambermill",body="Ambermill é um assentamento humano em Silverpine apoiado pelos bruxos de Dalaran. Suas conexões com rotas de fornecimento e pesquisas arcanas dão ao lugar maior importância do que sua aparência remota sugere."},pl={title="Ambermill",body="Ambermill jest ludzką osadą w Silverpine wspieraną przez czarodziejów Dalaran. Powiązania ze szlakami zaopatrzenia i badaniami magii nadają miejscu większe znaczenie, niż sugeruje odległe położenie."},ru={title="Ambermill",body="Ambermill - это человеческое поселение в Silverpine, поддерживаемое волшебниками Dalaran. Его связи с маршрутами поставок и таинственными исследованиями придают этому месту большее значение, чем предполагает его отдаленный вид."},references={["place:dalaran"]=true,["place:silverpine-forest"]=true}},
    ["place:ametharan"] = {title="Ameth'Aran",kind="Lugar",aliases={"Ameth'Aran","Ameth’Aran"},body="Ameth'Aran es una antigua ciudad en ruinas de Costa Oscura. Sus restos conservan huellas de la historia de los elfos de la noche, aunque hoy sus caminos están ocupados por presencias que impiden una exploración tranquila.",aliasQuestIDs={},en={title="Ameth'Aran",aliases={"Ameth'Aran","Ameth’Aran"},body="Ameth'Aran is an ancient ruined city in Darkshore. Its remains preserve traces of night elf history, although dangerous presences now keep its paths from being explored in peace.",aliasQuestIDs={}},fr={title="Ameth'Aran",body="Ameth'Aran est une ancienne ville en ruine dans Darkshore. Ses vestiges conservent des traces de l'histoire des elfes de la nuit, bien que des présences dangereuses empêchent désormais d'explorer ses chemins en paix."},de={title="Ameth'Aran",body="Ameth'Aran ist eine antike Ruinenstadt in Darkshore. Seine Überreste bewahren Spuren der Geschichte der Nachtelfen, obwohl gefährliche Anwesenheit seine Pfade daran hindert, in Frieden erkundet zu werden."},pt={title="Ameth'Aran",body="Ameth'Aran é uma antiga cidade em ruínas em Darkshore. Seus restos preservam vestígios da história do elfo noturno, embora as presenças perigosas agora mantenham seus caminhos de serem explorados em paz."},pl={title="Ameth'Aran",body="Ameth'Aran to pradawne zrujnowane miasto w Darkshore. Jego pozostałości przechowują ślady historii nocnych elfów, choć niebezpieczne istoty nie pozwalają dziś spokojnie przemierzać jego ścieżek."},ru={title="Ameth'Aran",body="Ameth'Aran - это древний город в руинах в Darkshore. Его останки сохраняют следы истории ночных эльфов, хотя опасные присутствия теперь мешают исследовать его пути в мире."},references={["place:darkshore"]=true}},
    ["place:andorhal"] = {title="Andorhal",kind="Lugar",aliases={"Andorhal"},body="Andorhal es una ciudad arruinada de las Tierras de la Peste del Oeste. La Plaga ocupa su centro, donde el exánime Araj mantiene un séquito de guardianes.",aliasQuestIDs={},en={title="Andorhal",aliases={"Andorhal"},body="Andorhal is a ruined town in Western Plaguelands. The Scourge occupies its center, where the lich Araj maintains a retinue of guards.",aliasQuestIDs={}},fr={title="Andorhal",body="Andorhal est une ville en ruine dans Western Plaguelands. La Scourge occupe son centre, où la liche Araj maintient une suite de gardes."},de={title="Andorhal",body="Andorhal ist eine Ruinenstadt in Western Plaguelands. Der Scourge besetzt sein Zentrum, wo der lichte Araj einen Tross von Wachen unterhält."},pt={title="Andorhal",body="Andorhal é uma cidade em ruínas em Western Plaguelands. O Scourge ocupa seu centro, onde o lich Araj mantém um séquito de guardas."},pl={title="Andorhal",body="Andorhal jest zrujnowanym miastem w Western Plaguelands. Siły znane jako The Scourge zajmują jego centrum, gdzie lisz Araj utrzymuje orszak strażników."},ru={title="Andorhal",body="Andorhal - разрушенный город в Western Plaguelands. Scourge занимает его центр, где лич Araj поддерживает свиток охранников."},references={["npc:araj-the-summoner"]=true,["organization:scourge"]=true,["place:plaguelands"]=true,["place:western-plaguelands"]=true}},
    ["place:anvilmar"] = {title="Yunquemar",kind="Lugar",aliases={"Yunquemar"},body="Yunquemar es una fortaleza de Dun Morogh situada en el Valle de Crestanevada. La forja, la instrucción y la defensa de los asentamientos nevados forman parte de la vida que comienza en sus alrededores.",aliasQuestIDs={},en={title="Anvilmar",aliases={"Anvilmar"},body="Anvilmar is a Dun Morogh stronghold in Coldridge Valley. Forging, training and the defense of snowy settlements are part of life beginning in its surroundings.",aliasQuestIDs={}},fr={title="Anvilmar",body="Anvilmar est un bastion Dun Morogh dans Coldridge Valley. La forge, la formation et la défense des établissements enneigés font partie de la vie qui commence dans son environnement."},de={title="Anvilmar",body="Anvilmar ist eine Dun Morogh-Hochburg in Coldridge Valley. Schmieden, Training und die Verteidigung von verschneiten Siedlungen gehören zum Leben, das in der Umgebung beginnt."},pt={title="Anvilmar",body="Anvilmar é uma fortaleza Dun Morogh em Coldridge Valley. Forjamento, treinamento e defesa de assentamentos nevados fazem parte da vida começando em seus arredores."},pl={title="Anvilmar",body="Anvilmar to warownia w Coldridge Valley w Dun Morogh. Kowalstwo, szkolenie i obrona śnieżnych osad należą do życia rozpoczynającego się w jej otoczeniu."},ru={title="Anvilmar",body="Anvilmar - это крепость Dun Morogh в Coldridge Valley. Ковка, тренировка и защита снежных поселений - часть жизни, начинающейся в его окрестностях."},references={["place:coldridge-valley"]=true,["place:dun-morogh"]=true}},
    ["place:apothecarium"] = {title="Apothecarium",kind="Lugar",aliases={"Apothecarium"},body="El Apothecarium es el centro de investigaciones de los boticarios en Entrañas. Sus laboratorios estudian especímenes y venenos de Azeroth para los proyectos de los Renegados.",aliasQuestIDs={},en={title="Apothecarium",aliases={"Apothecarium"},body="The Apothecarium is the apothecaries' research center in Undercity. Its laboratories study specimens and poisons from across Azeroth for Forsaken projects.",aliasQuestIDs={}},fr={title="Apothecarium",body="Le Apothecarium est le centre de recherche des apothicaires du Undercity. Ses laboratoires étudient des échantillons et des poisons provenant de Azeroth pour des projets Forsaken."},de={title="Apothecarium",body="Das Apothecarium ist das Forschungszentrum der Apotheken in Undercity. Seine Labors untersuchen Proben und Gifte aus ganz Azeroth für Forsaken-Projekte."},pt={title="Apothecarium",body="O Apothecarium é o centro de pesquisa dos boticários no Undercity. Seus laboratórios estudam espécimes e venenos de todo o Azeroth para projetos Forsaken."},pl={title="Apothecarium",body="The Apothecarium jest ośrodkiem badań aptekarzy w Undercity. Jego laboratoria badają okazy i trucizny z całego Azeroth na potrzeby projektów Forsaken."},ru={title="Apothecarium",body="Apothecarium - это исследовательский центр аптеков в Undercity. В лабораториях изучаются образцы и яды из Azeroth для проектов Forsaken."},references={["organization:forsaken"]=true,["place:azeroth"]=true,["place:undercity"]=true}},
    ["place:arathi-basin"] = {title="Cuenca de Arathi",kind="Lugar",aliases={"Cuenca de Arathi"},body="La Cuenca de Arathi es un territorio cuyos recursos sostienen el esfuerzo de guerra de sus contendientes. El control de suministros, metales y posiciones de producción hace que su valor sea tanto económico como militar.",aliasQuestIDs={},en={title="Arathi Basin",aliases={"Arathi Basin"},body="Arathi Basin is territory whose resources sustain its rivals’ war efforts. Control of supplies, metals and production sites makes it economically as well as militarily valuable.",aliasQuestIDs={}},fr={title="Arathi Basin",body="Arathi Basin est un territoire dont les ressources soutiennent les efforts de guerre de ses rivaux. Le contrôle des approvisionnements, des métaux et des sites de production le rend économiquement et militairement précieux."},de={title="Arathi Basin",body="Arathi Basin ist ein Territorium, dessen Ressourcen die Kriegsbemühungen seiner Rivalen unterstützen. Die Kontrolle über Vorräte, Metalle und Produktionsstätten macht sie sowohl wirtschaftlich als auch militärisch wertvoll."},pt={title="Arathi Basin",body="Arathi Basin é um território cujos recursos sustentam os esforços de guerra de seus rivais. O controle de suprimentos, metais e locais de produção o torna econômico, bem como militarmente valioso."},pl={title="Arathi Basin",body="Arathi Basin to terytorium, którego zasoby wspierają wysiłki wojenne rywali. Kontrola nad zaopatrzeniem, metalami i miejscami produkcji nadaje mu wartość gospodarczą oraz wojskową."},ru={title="Arathi Basin",body="Arathi Basin - это территория, ресурсы которой поддерживают военные усилия соперников. Контроль над поставками, металлами и производственными площадками делает его экономически и военно ценным."},references={["place:arathi-highlands"]=true}},
    ["place:arathi-highlands"] = {title="Tierras Altas de Arathi",kind="Lugar",aliases={"Arathi","Tierras Altas de Arathi"},body="Las Tierras Altas de Arathi son una región de fortalezas, caminos y recursos disputados. El antiguo poder de Stromgarde todavía marca el paisaje, mientras distintas fuerzas compiten por sus bastiones y por el control del territorio.",aliasQuestIDs={},en={title="Arathi Highlands",aliases={"Arathi","Arathi Highlands"},body="The Arathi Highlands are a region of fortresses, roads and contested resources. Stromgarde’s former power still marks the landscape as rival forces compete for its strongholds and territory.",aliasQuestIDs={}},fr={title="Arathi Highlands",body="Les Arathi Highlands sont une région de forteresses, de routes et de ressources contestées. L’ancienne puissance de Stromgarde marque toujours le paysage alors que les forces rivales rivalisent pour ses bastions et son territoire."},de={title="Arathi Highlands",body="Die Arathi Highlands sind eine Region mit Festungen, Straßen und umkämpften Ressourcen. Die einstige Macht von Stromgarde prägt noch immer die Landschaft, während rivalisierende Streitkräfte um ihre Stützpunkte und Gebiete ringen."},pt={title="Arathi Highlands",body="O Arathi Highlands é uma região de fortalezas, estradas e recursos contestados. O antigo poder do Stromgarde ainda marca a paisagem à medida que forças rivais competem por suas fortalezas e território."},pl={title="Arathi Highlands",body="Arathi Highlands to region fortec, dróg i zasobów, o które toczą się spory. Dawna potęga Stromgarde nadal odciska piętno na krajobrazie, podczas gdy rywalizujące siły walczą o warownie i terytorium."},ru={title="Arathi Highlands",body="Arathi Highlands - это регион крепостей, дорог и спорных ресурсов. Бывшая власть Stromgarde  по-прежнему отмечает пейзаж, поскольку соперничающие силы конкурируют за свои оплоты и территорию."},references={["place:stromgarde"]=true}},
    ["place:ashenvale"] = {title="Vallefresno",kind="Lugar",aliases={"Vallefresno"},body="Vallefresno es un bosque de Kalimdor defendido por los elfos de la noche. Sus rutas, claros y recursos son escenario de conflictos con fuerzas invasoras y con la expansión de la Horda.",aliasQuestIDs={},en={title="Ashenvale",aliases={"Ashenvale"},body="Ashenvale is a forest of Kalimdor defended by the night elves. Its routes, clearings and resources are the setting for conflicts with invading forces and the expansion of the Horde.",aliasQuestIDs={}},fr={title="Ashenvale",body="Ashenvale est une forêt de Kalimdor défendue par les elfes de la nuit. Ses routes, ses clairières et ses ressources sont le théâtre de conflits avec les forces d'invasion et de l'expansion du Horde."},de={title="Ashenvale",body="Ashenvale ist ein Wald von Kalimdor, der von den Nachtelfen verteidigt wird. Seine Routen, Lichtungen und Ressourcen sind der Schauplatz für Konflikte mit Invasionstrukturen und die Ausweitung der Horde."},pt={title="Ashenvale",body="Ashenvale é uma floresta de Kalimdor defendida pelos elfos noturnos. Suas rotas, clareiras e recursos são o cenário para conflitos com forças invasoras e a expansão do Horde."},pl={title="Ashenvale",body="Ashenvale to las na kontynencie Kalimdor broniony przez nocne elfy. Jego szlaki, polany i zasoby są areną konfliktów z najeźdźcami oraz ekspansją frakcji Horde."},ru={title="Ashenvale",body="Ashenvale - это лес Kalimdor, защищаемый ночными эльфами. Его маршруты, проемы и ресурсы являются местом конфликтов с вторгающимися силами и расширения Horde."},references={["organization:horde"]=true,["place:kalimdor"]=true}},
    ["place:astranaar"] = {title="Astranaar",kind="Lugar",aliases={"Astranaar"},body="Astranaar es un asentamiento de los elfos de la noche en Vallefresno, rodeado por las aguas de un lago. Sus habitantes y centinelas mantienen un punto de apoyo importante para la defensa del bosque.",aliasQuestIDs={},en={title="Astranaar",aliases={"Astranaar"},body="Astranaar is a night elf settlement in Ashenvale surrounded by the waters of a lake. Its residents and sentinels maintain an important foothold in the defense of the forest.",aliasQuestIDs={}},fr={title="Astranaar",body="Astranaar est une colonie d'elfes de nuit à Ashenvale entourée par les eaux d'un lac. Ses habitants et sentinelles maintiennent un ancrage important dans la défense de la forêt."},de={title="Astranaar",body="Astranaar ist eine Nachtelfensiedlung in Ashenvale, umgeben von den Wassern eines Sees. Seine Bewohner und Wächter halten ein wichtiges Standbein bei der Verteidigung des Waldes Waldes."},pt={title="Astranaar",body="Astranaar é um assentamento de elfo noturno em Ashenvale cercado pelas águas de um lago. Seus moradores e sentinelas mantêm uma posição importante na defesa da floresta."},pl={title="Astranaar",body="Astranaar to osada nocnych elfów w Ashenvale otoczona wodami jeziora. Jej mieszkańcy i strażniczki utrzymują ważny punkt oparcia w obronie lasu."},ru={title="Astranaar",body="Astranaar - это поселение ночных эльфов в Ashenvale, окруженное водой озера. Его жители и sentinels поддерживают важную опору в защите леса."},references={["organization:night-elf-sentinels"]=true,["place:ashenvale"]=true}},
    ["place:athenaeum"] = {title="El Athenaeum",kind="Lugar",aliases={"Athenaeum","El Athenaeum"},body="El Athenaeum es un recinto de La Masacre donde se conservan conocimientos de Eldre'Thalas. Sus estudiosos trabajan entre las ruinas mientras intentan mantener sus prácticas frente a vecinos mucho más violentos.",aliasQuestIDs={},en={title="The Athenaeum",aliases={"Athenaeum","The Athenaeum"},body="The Athenaeum is a chamber in Dire Maul preserving knowledge of Eldre'Thalas. Its scholars work among the ruins while trying to maintain their practices alongside much more violent neighbors.",aliasQuestIDs={}},fr={title="The Athenaeum",body="The Athenaeum est une chambre en Dire Maul préservant la connaissance de Eldre'Thalas. Ses érudits travaillent parmi les ruines tout en essayant de maintenir leurs pratiques aux côtés de voisins beaucoup plus violents."},de={title="The Athenaeum",body="The Athenaeum ist eine Kammer in Dire Maul, die das Wissen über Eldre'Thalas bewahrt. Seine Gelehrten arbeiten in den Ruinen, während sie versuchen, ihre Praktiken an der Seite mit viel gewalttätigeren Nachbarn aufrechtzuerhalten."},pt={title="The Athenaeum",body="The Athenaeum é uma câmara em Dire Maul que preserva o conhecimento de Eldre'Thalas. Seus estudiosos trabalham entre as ruínas enquanto tentam manter suas práticas ao lado de vizinhos muito mais violentos."},pl={title="The Athenaeum",body="The Athenaeum to komnata w Dire Maul przechowująca wiedzę Eldre'Thalas. Uczeni pracują pośród ruin, starając się podtrzymywać swoje praktyki w sąsiedztwie znacznie bardziej brutalnych mieszkańców."},ru={title="The Athenaeum",body="The Athenaeum - это камера в Dire Maul, хранящая знания о Eldre'Thalas. Его ученые работают среди руин, пытаясь сохранить свои обычаи наряду с гораздо более жестокими соседями."},references={["place:dire-maul"]=true}},
    ["place:auberdine"] = {title="Auberdine",kind="Lugar",aliases={"Auberdine"},body="Auberdine es un puerto de Costa Oscura que conecta a sus habitantes con otros asentamientos. Sus muelles sostienen el comercio y los viajes por mar, mientras sus centinelas vigilan los peligros del bosque y de las ruinas próximas.",aliasQuestIDs={},en={title="Auberdine",aliases={"Auberdine"},body="Auberdine is a port in Darkshore that connects its residents with other settlements. Its docks support trade and sea travel, while its sentinels watch for dangers in the forest and nearby ruins.",aliasQuestIDs={}},fr={title="Auberdine",body="Auberdine est un port dans Darkshore qui relie ses résidents avec d'autres colonies. Ses quais soutiennent le commerce et les voyages en mer, tandis que ses sentinelles surveillent les dangers dans la forêt et les ruines voisines."},de={title="Auberdine",body="Auberdine ist ein Hafen in Darkshore, der seine Bewohner mit anderen Siedlungen verbindet. Seine Docks unterstützen den Handel und den Schiffsverkehr, während seine Wachen im Wald und in der nahe gelegenen Ruinen nach Gefahren Ausschau halten."},pt={title="Auberdine",body="Auberdine é um porto em Darkshore que conecta seus moradores com outros assentamentos. Suas docas apoiam o comércio e as viagens marítimas, enquanto suas sentinelas vigiam os perigos na floresta e nas ruínas próximas."},pl={title="Auberdine",body="Auberdine to port w Darkshore łączący mieszkańców regionu z innymi osadami. Nabrzeża wspierają handel i podróże morskie, a strażniczki wypatrują zagrożeń w lesie i pobliskich ruinach."},ru={title="Auberdine",body="Auberdine - это порт в Darkshore, который соединяет его жителей с другими поселениями. Его доки поддерживают торговлю и морское путешествие, а его sentinels следит за опасностями в лесу и близлежащих руинах."},references={["organization:night-elf-sentinels"]=true,["place:darkshore"]=true}},
    ["place:azeroth"] = {title="Azeroth",kind="Lugar",aliases={"Azeroth"},body="Azeroth es el mundo que comparten pueblos como los de la Horda y la Alianza. Sus tierras reúnen culturas, ciudades y paisajes muy distintos, conectados por viajes y por conflictos que atraviesan las fronteras.",aliasQuestIDs={},en={title="Azeroth",aliases={"Azeroth"},body="Azeroth is the world shared by peoples such as those of the Horde and Alliance. Its lands contain very different cultures, cities and landscapes, connected by travel and conflicts crossing borders.",aliasQuestIDs={}},fr={title="Azeroth",body="Azeroth est le monde partagé par des peuples tels que ceux de la Horde et Alliance. Ses terres contiennent des cultures, des villes et des paysages très différents, liés par des voyages et des conflits traversant les frontières."},de={title="Azeroth",body="Azeroth ist die Welt, die Völker wie die Horde und Alliance teilen. Seine Ländereien enthalten sehr unterschiedliche Kulturen, Städte und Landschaften, die durch Reisen und grenzüberschreitende Konflikte miteinander verbunden sind."},pt={title="Azeroth",body="Azeroth é o mundo compartilhado por povos como os do Horde e Alliance. Suas terras contêm culturas, cidades e paisagens muito diferentes, conectadas por viagens e conflitos que atravessam fronteiras."},pl={title="Azeroth",body="Azeroth jest światem wspólnym dla ludów takich jak te należące do sojuszy znanych jako the Horde i Alliance. Jego ziemie mieszczą bardzo różne kultury, miasta i krajobrazy, połączone podróżami oraz konfliktami przekraczającymi granice."},ru={title="Azeroth",body="Azeroth - это мир, в котором живут люди, такие как Horde и Alliance. Его земли содержат очень разные культуры, города и пейзажи, связанные путешествиями и конфликтами через границы."},references={["organization:alliance"]=true,["organization:horde"]=true}},
    ["place:azshara"] = {title="Azshara",kind="Lugar",aliases={"Azshara"},body="Azshara es una región costera de Kalimdor cubierta por ruinas antiguas. Sus restos atraen a estudiosos de la magia y cazadores de tesoros, mientras grupos hostiles ocupan buena parte del territorio.",aliasQuestIDs={},en={title="Azshara",aliases={"Azshara"},body="Azshara is a coastal region of Kalimdor covered in ancient ruins. Its remains attract students of magic and treasure seekers, while hostile groups occupy much of the territory.",aliasQuestIDs={}},fr={title="Azshara",body="Azshara est une région côtière de Kalimdor couverte de ruines antiques. Ses vestiges attirent les étudiants en magie et les chercheurs de trésors, tandis que des groupes hostiles occupent une grande partie du territoire."},de={title="Azshara",body="Azshara ist eine Küstenregion von Kalimdor, die von antiken Ruinen bedeckt ist. Seine Überreste ziehen Zauberschüler und Schatzsucher an, während feindliche Gruppen große Teile des Territoriums besetzen."},pt={title="Azshara",body="Azshara é uma região costeira de Kalimdor coberta de ruínas antigas. Seus restos mortais atraem estudantes de magia e caçadores de tesouros, enquanto grupos hostis ocupam grande parte do território."},pl={title="Azshara",body="Azshara to nadmorski region kontynentu Kalimdor pokryty pradawnymi ruinami. Pozostałości przyciągają badaczy magii i poszukiwaczy skarbów, podczas gdy wrogie grupy zajmują znaczną część terytorium."},ru={title="Azshara",body="Azshara - это прибрежный регион Kalimdor, покрытый древними руинами. Его останки привлекают учеников магии и искателей сокровищ, в то время как враждебные группы занимают большую часть территории."},references={["place:kalimdor"]=true},questIDs={[953]=true,[2744]=true,[3448]=true,[3449]=true,[3450]=true,[3451]=true,[3505]=true,[3509]=true,[3517]=true,[3561]=true,[3562]=true,[3563]=true,[3564]=true,[3565]=true,[3568]=true,[3601]=true,[3602]=true,[4201]=true,[5141]=true,[5246]=true,[5534]=true,[5535]=true,[6543]=true,[7602]=true,[9322]=true,[9364]=true}},
    ["place:badlands"] = {title="Tierras Inhóspitas",kind="Lugar",aliases={"Las Tierras Inhóspitas","Tierras Inhóspitas"},body="Las Tierras Inhóspitas son una región árida vinculada a la exploración y a los restos de Uldaman. Los viajeros encuentran allí bestias resistentes, excavaciones y puestos que dependen de suministros y de ayuda exterior.",aliasQuestIDs={},en={title="Badlands",aliases={"Badlands"},body="The Badlands are an arid region associated with exploration and the remains of Uldaman. Travelers encounter hardy beasts, excavations and outposts dependent on supplies and outside help.",aliasQuestIDs={}},fr={title="Badlands",body="Les Badlands sont une région aride associée à l'exploration et aux restes de Uldaman. Les voyageurs rencontrent des bêtes robustes, des fouilles et des avant-postes dépendant de fournitures et d'aide extérieure."},de={title="Badlands",body="Die Badlands sind eine trockene Region, die mit der Erforschung und den Überresten von Uldaman verbunden ist. Reisende begegnen robusten Tieren, Ausgrabungen und Außenposten, die auf Vorräte und Hilfe von außen angewiesen sind."},pt={title="Badlands",body="O Badlands é uma região árida associada à exploração e aos restos mortais do Uldaman. Os viajantes encontram animais resistentes, escavações e postos avançados dependentes de suprimentos e ajuda externa."},pl={title="Badlands",body="Badlands to suchy region związany z wyprawami badawczymi i pozostałościami Uldaman. Podróżni spotykają tu wytrzymałe bestie, wykopaliska i posterunki zależne od dostaw oraz pomocy z zewnątrz."},ru={title="Badlands",body="Badlands - это засушливый регион, связанный с разведкой и остатками Uldaman. Путешественники сталкиваются с стойкими зверями, раскопами и форпостами, зависящими от запасов и помощи извне."},references={["place:uldaman"]=true}},
    ["place:balnir-farmstead"] = {title="Hacienda Balnir",kind="Lugar",aliases={"Hacienda Balnir"},body="La Hacienda Balnir es una explotación rural de Tirisfal afectada por la presencia de la Plaga. Sus campos también albergan plantas alteradas por los experimentos de los boticarios.",aliasQuestIDs={},en={title="Balnir Farmstead",aliases={"Balnir Farmstead"},body="Balnir Farmstead is a rural holding in Tirisfal affected by the Scourge. Its fields also hold plants altered by apothecary experiments.",aliasQuestIDs={}},fr={title="Balnir Farmstead",body="Balnir Farmstead est une exploitation rurale dans Tirisfal affectée par the Scourge. Ses champs contiennent également des plantes modifiées par des expériences d'apothicaire."},de={title="Balnir Farmstead",body="Balnir Farmstead ist ein ländliches Anwesen in Tirisfal, das von the Scourge betroffen ist. Auf seinen Feldern wachsen auch Pflanzen, die durch Experimente von Apothekern verändert wurden."},pt={title="Balnir Farmstead",body="Balnir Farmstead é uma participação rural na Tirisfal afetada pela the Scourge. Seus campos também contêm plantas alteradas por experimentos de boticário."},pl={title="Balnir Farmstead",body="Balnir Farmstead jest gospodarstwem w Tirisfal dotkniętym przez siły znane jako the Scourge. Na jego polach rosną również rośliny zmienione w wyniku eksperymentów aptekarzy."},ru={title="Balnir Farmstead",body="Balnir Farmstead - это сельское хозяйство в Tirisfal, пораженное the Scourge. На его полях также растут растения, измененные аптечными экспериментами."},references={["organization:scourge"]=true,["place:tirisfal-glades"]=true}},
    ["place:bandarion-keep"] = {title="Fuerte de Bandarion",kind="Lugar",aliases={"Fuerte de Bandarion"},body="El Fuerte de Bandarion es una posición de Claros de Tirisfal vinculada a defensores y paladines de los Renegados. Allí coinciden las preocupaciones militares de la región y la enseñanza del uso de la Luz.",aliasQuestIDs={},en={title="Bandarion Keep",aliases={"Bandarion Keep"},body="Bandarion Keep is a Tirisfal Glades position associated with Forsaken defenders and paladins. Regional military concerns and instruction in the Light meet there.",aliasQuestIDs={}},fr={title="Bandarion Keep",body="Bandarion Keep est une position Tirisfal Glades associée aux défenseurs et paladins Forsaken. Les préoccupations militaires régionales et l'instruction dans the Light s'y rencontrent."},de={title="Bandarion Keep",body="Bandarion Keep ist eine Tirisfal Glades-Position, die mit Forsaken Verteidigern und Paladinen in Verbindung gebracht wird. Regionale militärische Belange und die Ausbildung in the Light treffen sich dort."},pt={title="Bandarion Keep",body="Bandarion Keep é uma posição Tirisfal Glades associada aos defensores e paladinos do Forsaken. Preocupações militares regionais e instrução em the Light se encontram lá."},pl={title="Bandarion Keep",body="Bandarion Keep jest pozycją w Tirisfal Glades związaną z obrońcami i paladynami Forsaken. Łączą się tu regionalne sprawy wojskowe i nauka posługiwania się mocą the Light."},ru={title="Bandarion Keep",body="Bandarion Keep - это позиция Tirisfal Glades, связанная с защитниками и паладинами Forsaken. Региональные военные интересы и инструкции в the Light встречаются там."},references={["concept:holy-light"]=true,["organization:forsaken"]=true,["place:tirisfal-glades"]=true}},
    ["place:banethil-barrow-den"] = {title="Túmulo de Ban'ethil",kind="Lugar",aliases={"Ban'ethil","Ban’ethil","Túmulo de Ban'ethil","Túmulo de Ban’ethil"},body="El Túmulo de Ban'ethil es un recinto subterráneo de Teldrassil asociado al descanso de los druidas. La presencia de fúrbolgs hostiles ha convertido sus pasadizos en un peligro para los guardianes y mensajeros del bosque.",aliasQuestIDs={},en={title="Ban'ethil Barrow Den",aliases={"Ban'ethil","Ban'ethil Barrow Den","Ban’ethil","Ban’ethil Barrow Den"},body="Ban'ethil Barrow Den is an underground site in Teldrassil associated with the rest of druids. Hostile furbolgs have made its passages dangerous for the forest’s guardians and messengers.",aliasQuestIDs={}},fr={title="Ban'ethil Barrow Den",body="Ban'ethil Barrow Den est un site souterrain dans Teldrassil associé au reste des druides. Les furbolgs hostiles ont rendu ses passages dangereux pour les gardiens et les messagers de la forêt."},de={title="Ban'ethil Barrow Den",body="Ban'ethil Barrow Den ist eine unterirdische Stätte in Teldrassil, die mit dem Rest der Druiden in Verbindung gebracht wird. Feindliche Furbolgs haben seine Durchgänge für die Wächter und Boten des Waldes Waldes gefährlich gemacht."},pt={title="Ban'ethil Barrow Den",body="Ban'ethil Barrow Den é um site subterrâneo em Teldrassil associado com o resto dos druidas. Furbolgs hostis tornaram suas passagens perigosas para os guardiões e mensageiros da floresta."},pl={title="Ban'ethil Barrow Den",body="Ban'ethil Barrow Den to podziemne miejsce w Teldrassil związane ze spoczynkiem druidów. Wrogie furbolgi uczyniły jego korytarze niebezpiecznymi dla strażników lasu i posłańców."},ru={title="Ban'ethil Barrow Den",body="Ban'ethil Barrow Den - подземный участок в Teldrassil, связанный с остальными друидами. Враждебные пушистые волки сделали его проходы опасными для хранителей и посланников леса."},references={["place:teldrassil"]=true}},
    ["place:bashalaran"] = {title="Bashal'Aran",kind="Lugar",aliases={"Bashal'Aran","Bashal’Aran"},body="Bashal'Aran es uno de los antiguos asentamientos de Costa Oscura reducidos a ruinas. Su memoria forma parte del pasado de los elfos de la noche, mientras criaturas hostiles ocupan los vestigios del lugar.",aliasQuestIDs={},en={title="Bashal'Aran",aliases={"Bashal'Aran","Bashal’Aran"},body="Bashal'Aran is one of Darkshore’s ancient settlements reduced to ruins. Its memory forms part of the night elves’ past, while hostile creatures occupy what remains.",aliasQuestIDs={}},fr={title="Bashal'Aran",body="Bashal'Aran est l'un des anciens établissements de Darkshore réduits en ruines. Sa mémoire fait partie du passé des elfes de la nuit, tandis que des créatures hostiles occupent ce qui reste."},de={title="Bashal'Aran",body="Bashal'Aran ist eine der alten Siedlungen von Darkshore, die heute in Trümmern liegen. Die Erinnerung daran gehört zur Vergangenheit der Nachtelfen, während feindselige Kreaturen die Überreste besetzen."},pt={title="Bashal'Aran",body="Bashal'Aran é um dos antigos assentamentos de Darkshore reduzidos a ruínas. Sua memória faz parte do passado dos elfos noturnos, enquanto criaturas hostis ocupam o que resta."},pl={title="Bashal'Aran",body="Bashal'Aran to jedna z pradawnych osad Darkshore obróconych w ruinę. Pamięć o niej stanowi część przeszłości nocnych elfów, a jej pozostałości zajmują wrogie stworzenia."},ru={title="Bashal'Aran",body="Bashal'Aran - одно из древних поселений Darkshore, превращенных в руины. Ее память является частью прошлого ночных эльфов, а враждебные существа занимают то, что осталось."},references={["place:darkshore"]=true}},
    ["place:blackfathom-deeps"] = {title="Cavernas de Brazanegra",kind="Lugar",aliases={"Cavernas de Brazanegra"},body="Las Cavernas de Brazanegra son un complejo subterráneo de la costa de Vallefresno. Sus aguas y antiguos recintos están ocupados por criaturas hostiles y seguidores de poderes que amenazan el litoral.",aliasQuestIDs={},en={title="Blackfathom Deeps",aliases={"Blackfathom Deeps"},body="Blackfathom Deeps is an underground complex on the coast of Ashenvale. Its waters and ancient chambers are occupied by hostile creatures and followers of powers that threaten the shore.",aliasQuestIDs={}},fr={title="Blackfathom Deeps",body="Blackfathom Deeps est un complexe souterrain sur la côte de Ashenvale. Ses eaux et ses chambres anciennes sont occupées par des créatures hostiles et des adeptes de pouvoirs qui menacent le rivage."},de={title="Blackfathom Deeps",body="Blackfathom Deeps ist ein unterirdischer Komplex an der Küste von Ashenvale. Seine Gewässer und uralten Kammern sind von feindlichen Kreaturen und Anhängern von Mächsen besetzt, die das Ufer bedrohen."},pt={title="Blackfathom Deeps",body="Blackfathom Deeps é um complexo subterrâneo na costa de Ashenvale. Suas águas e câmaras antigas são ocupadas por criaturas hostis e seguidores de poderes que ameaçam a costa."},pl={title="Blackfathom Deeps",body="Blackfathom Deeps to podziemny kompleks na wybrzeżu Ashenvale. Jego wody i pradawne komnaty zajmują wrogie stworzenia oraz wyznawcy mocy zagrażających wybrzeżu."},ru={title="Blackfathom Deeps",body="Blackfathom Deeps - это подземный комплекс на побережье Ashenvale. В его водах и древних камерах обитают враждебные существа и последователи сил, угрожающих берегу."},references={["place:ashenvale"]=true}},
    ["place:blackrock-depths"] = {title="Profundidades de Roca Negra",kind="Lugar",aliases={"Profundidades de Roca Negra"},body="Las Profundidades de Roca Negra forman un complejo de galerías, instalaciones y posiciones militares dentro de la montaña. Sus prisiones y fuerzas hostiles atraen a expedicionarios que intentan comprender y contener los peligros del enclave.",aliasQuestIDs={},en={title="Blackrock Depths",aliases={"Blackrock Depths"},body="Blackrock Depths form a complex of tunnels, installations and military positions within the mountain. Its prisons and hostile forces draw expeditionaries trying to understand and contain the stronghold’s dangers.",aliasQuestIDs={}},fr={title="Blackrock Depths",body="Blackrock Depths forme un complexe de tunnels, d'installations et de positions militaires dans la montagne. Ses prisons et ses forces hostiles attirent les expéditionnaires qui tentent de comprendre et de contenir les dangers de la forteresse."},de={title="Blackrock Depths",body="Blackrock Depths bildet einen Komplex von Tunneln, Anlagen und militärischen Stellungen im Gebirge. Seine Gefängnisse und feindlichen Kräfte ziehen Expeditionäre an, die versuchen, die Gefahren der Festung zu verstehen und einzudämmen."},pt={title="Blackrock Depths",body="Blackrock Depths formam um complexo de túneis, instalações e posições militares dentro da montanha. Suas prisões e forças hostis atraem expedicionários que tentam entender e conter os perigos da fortaleza."},pl={title="Blackrock Depths",body="Blackrock Depths tworzą kompleks tuneli, obiektów i pozycji wojskowych wewnątrz góry. Więzienia i wrogie siły przyciągają uczestników wypraw próbujących zrozumieć oraz powstrzymywać niebezpieczeństwa warowni."},ru={title="Blackrock Depths",body="Blackrock Depths образуют комплекс туннелей, сооружений и военных позиций в горах. Его тюрьмы и враждебные силы привлекают экспедиционеров, пытающихся понять и сдержать опасность крепости."},references={}},
    ["place:blackrock-mountain"] = {title="Montaña Roca Negra",kind="Lugar",aliases={"Montaña Roca Negra"},body="La Montaña Roca Negra reúne fortalezas, galerías y pasos interiores que atraen a expedicionarios y fuerzas rivales. Su importancia militar y los poderes que se ocultan en sus profundidades la convierten en un foco de conflicto para las regiones vecinas.",aliasQuestIDs={},en={title="Blackrock Mountain",aliases={"Blackrock Mountain"},body="Blackrock Mountain contains strongholds, tunnels and interior passages drawing expeditionaries and rival forces. Its military importance and the powers hidden in its depths make it a center of conflict for neighboring regions.",aliasQuestIDs={}},fr={title="Blackrock Mountain",body="Blackrock Mountain contient des bastions, des tunnels et des passages intérieurs dessinant des expéditionnaires et des forces rivales. Son importance militaire et les pouvoirs cachés dans ses profondeurs en font un centre de conflit pour les régions voisines."},de={title="Blackrock Mountain",body="Blackrock Mountain enthält Festungen, Tunnel und innere Gänge, die Expeditionäre und rivalisierende Kräfte anziehen. Seine militärische Bedeutung und die in seiner Tiefe verborgenen Mächte Macht machen es zu einem Konfliktherd für benachbarte Regionen."},pt={title="Blackrock Mountain",body="Blackrock Mountain contém fortalezas, túneis e passagens interiores desenhando expedicionários e forças rivais. Sua importância militar e os poderes ocultos em suas profundezas o tornam um centro de conflito para as regiões vizinhas."},pl={title="Blackrock Mountain",body="Blackrock Mountain kryje warownie, tunele i wewnętrzne przejścia przyciągające uczestników wypraw oraz rywalizujące siły. Znaczenie wojskowe i moce ukryte w głębinach czynią ją centrum konfliktów sąsiednich regionów."},ru={title="Blackrock Mountain",body="В Blackrock Mountain есть крепости, туннели и внутренние проходы, привлекающие экспедиционеров и соперничающие силы. Его военная важность и скрытые в глубине силы делают его центром конфликта для соседних регионов."},references={}},
    ["place:blackrock-spire"] = {title="Cumbre de Roca Negra",kind="Lugar",aliases={"Cumbre de Roca Negra"},body="La Cumbre de Roca Negra es una fortaleza dentro de la montaña del mismo nombre. Sus guarniciones y mandos militares la convierten en un objetivo importante para quienes investigan las amenazas que parten de ese enclave.",aliasQuestIDs={},en={title="Blackrock Spire",aliases={"Blackrock Spire"},body="Blackrock Spire is a fortress within the mountain of the same name. Its garrisons and military leaders make it an important objective for those investigating threats from that stronghold.",aliasQuestIDs={}},fr={title="Blackrock Spire",body="Blackrock Spire est une forteresse dans la montagne du même nom. Ses garnisons et ses chefs militaires en font un objectif important pour ceux qui enquêtent sur les menaces de ce bastion."},de={title="Blackrock Spire",body="Blackrock Spire ist eine Festung im gleichnamigen Berg. Seine Garnisonen und militärischen Führer machen es zu einem wichtigen Ziel für diejenigen, die Bedrohungen aus dieser Hochburg untersuchen."},pt={title="Blackrock Spire",body="Blackrock Spire é uma fortaleza dentro da montanha de mesmo nome. Suas guarnições e líderes militares o tornam um objetivo importante para aqueles que investigam ameaças dessa fortaleza."},pl={title="Blackrock Spire",body="Blackrock Spire to forteca wewnątrz góry o tej samej nazwie. Garnizony i dowódcy wojskowi czynią ją ważnym celem dla tych, którzy badają zagrożenia płynące z tej warowni."},ru={title="Blackrock Spire",body="Blackrock Spire - крепость в горах с тем же названием. Его гарнизоны и военные руководители делают его важной целью для тех, кто расследует угрозы от этого оплота."},references={}},
    ["place:blasted-lands"] = {title="Tierras Devastadas",kind="Lugar",aliases={"Las Tierras Devastadas","Tierras Devastadas"},body="Las Tierras Devastadas son un territorio hostil asociado al Portal Oscuro y a la memoria de las guerras de la Horda. Entre sus habitantes y visitantes hay espíritus y estudiosos que conservan testimonios de esos conflictos.",aliasQuestIDs={},en={title="Blasted Lands",aliases={"Blasted Lands"},body="The Blasted Lands are hostile territory associated with the Dark Portal and the memory of the Horde’s wars. Spirits and scholars among its inhabitants and visitors preserve testimony to those conflicts.",aliasQuestIDs={}},fr={title="Blasted Lands",body="Les Blasted Lands sont des territoires hostiles associés au Dark Portal et à la mémoire des guerres du Horde. Les esprits et les érudits parmi ses habitants et ses visiteurs conservent le témoignage de ces conflits."},de={title="Blasted Lands",body="Die Blasted Lands sind feindliches Territorium, das mit dem Dark Portal und der Erinnerung an die Kriege der Horde in Verbindung gebracht wird. Geister und Gelehrte unter seinen Bewohnern und Besuchern bewahren Zeugnisse dieser Konflikte."},pt={title="Blasted Lands",body="O Blasted Lands é um território hostil associado ao Dark Portal e à memória das guerras do Horde. Espíritos e estudiosos entre seus habitantes e visitantes preservam o testemunho desses conflitos."},pl={title="Blasted Lands",body="Blasted Lands to wrogi obszar związany z Dark Portal i pamięcią o wojnach Horde. Duchy i uczeni znajdujący się wśród jego mieszkańców oraz gości zachowują świadectwa tych konfliktów."},ru={title="Blasted Lands",body="Blasted Lands - враждебная территория, связанная с Dark Portal и памятью о войнах Horde s. Духи и ученые среди его жителей и посетителей хранят свидетельства этих конфликтов."},references={["organization:horde"]=true,["place:dark-portal"]=true}},
    ["place:bloodhoof-village"] = {title="Poblado Pezuña de Sangre",kind="Lugar",aliases={"Poblado Pezuña de Sangre"},body="El Poblado Pezuña de Sangre es una comunidad tauren de Mulgore. Sus cazadores y guías enseñan a aprovechar los recursos de la llanura y a defender el territorio frente a las amenazas que lo rodean.",aliasQuestIDs={},en={title="Bloodhoof Village",aliases={"Bloodhoof Village"},body="Bloodhoof Village is a tauren community in Mulgore. Its hunters and guides teach the use of the plains’ resources and the defense of the land against surrounding threats.",aliasQuestIDs={}},fr={title="Bloodhoof Village",body="Bloodhoof Village est une communauté tauren dans Mulgore. Ses chasseurs et ses guides enseignent l’utilisation des ressources des plaines et la défense de la terre contre les menaces environnantes."},de={title="Bloodhoof Village",body="Bloodhoof Village ist eine Tauren-Gemeinschaft in Mulgore. Seine Jäger und Führer lehren die Nutzung der Ressourcen der Ebenen und die Verteidigung des Landes gegen umgebende Bedrohungen."},pt={title="Bloodhoof Village",body="Bloodhoof Village é uma comunidade tauren em Mulgore. Seus caçadores e guias ensinam o uso dos recursos das planícies e a defesa da terra contra ameaças ao redor."},pl={title="Bloodhoof Village",body="Bloodhoof Village to społeczność taurenów w Mulgore. Jej myśliwi i przewodnicy uczą korzystania z zasobów równin oraz obrony ziemi przed otaczającymi zagrożeniami."},ru={title="Bloodhoof Village",body="Bloodhoof Village - это сообщество быков в Mulgore. Охотники и гиды учат пользоваться ресурсами равнины и защищать землю от окружающих угроз."},references={["place:mulgore"]=true}},
    ["place:booty-bay"] = {title="Bahía del Botín",kind="Lugar",aliases={"Bahía del Botín","La Bahía del Botín"},body="Bahía del Botín es una comunidad portuaria de Tuercespina ligada al comercio y a los Asaltantes Aguasnegras. La navegación, las mercancías y la rivalidad con otros piratas influyen en la vida de sus habitantes.",aliasQuestIDs={},en={title="Booty Bay",aliases={"Booty Bay"},body="Booty Bay is a Stranglethorn port associated with trade and the Blackwater Raiders. Shipping, merchandise and rivalry with other pirates shape the lives of its inhabitants.",aliasQuestIDs={}},fr={title="Booty Bay",body="Booty Bay est un port Stranglethorn associé au commerce et au Blackwater Raiders. Le transport maritime, la marchandise et la rivalité avec d'autres pirates façonnent la vie de ses habitants."},de={title="Booty Bay",body="Booty Bay ist ein Stranglethorn-Hafen, der mit dem Handel und dem Blackwater Raiders in Verbindung gebracht wird. Schifffahrt, Waren und Rivalität mit anderen Piraten prägen das Leben seiner Bewohner."},pt={title="Booty Bay",body="Booty Bay é um porto Stranglethorn associado ao comércio e ao Blackwater Raiders. O transporte, a mercadoria e a rivalidade com outros piratas moldam a vida de seus habitantes."},pl={title="Booty Bay",body="Booty Bay to port w Stranglethorn związany z handlem i Blackwater Raiders. Żegluga, towary oraz rywalizacja z innymi piratami kształtują życie jego mieszkańców."},ru={title="Booty Bay",body="Booty Bay - это порт Stranglethorn, связанный с торговлей и Blackwater Raiders. Перевозки, торговля и соперничество с другими пиратами формируют жизнь его жителей."},references={["organization:blackwater-raiders"]=true,["place:stranglethorn-vale"]=true}},
    ["place:brackenwall-village"] = {title="Poblado Murohelecho",kind="Lugar",aliases={"Poblado Murohelecho"},body="El Poblado Murohelecho es un asentamiento ogro de Marjal Revolcafango. Sus habitantes mantienen vínculos con la Horda y deben afrontar las criaturas y tensiones militares del pantano.",aliasQuestIDs={},en={title="Brackenwall Village",aliases={"Brackenwall","Brackenwall Village"},body="Brackenwall Village is an ogre settlement in Dustwallow Marsh. Its inhabitants maintain ties with the Horde while facing the marsh’s creatures and military tensions.",aliasQuestIDs={}},fr={title="Brackenwall Village",body="Brackenwall Village est un règlement d'ogre dans Dustwallow Marsh. Ses habitants entretiennent des liens avec la Horde tout en faisant face aux créatures du marais et aux tensions militaires."},de={title="Brackenwall Village",body="Brackenwall Village ist eine Oger-Siedlung in Dustwallow Marsh. Seine Bewohner unterhalten Beziehungen zu den Horde, während sie den Geschöpfen des Sumpfes und den militärischen Spannungen ausgesetzt sind."},pt={title="Brackenwall Village",body="Brackenwall Village é um assentamento ogro em Dustwallow Marsh. Seus habitantes mantêm laços com o Horde enquanto enfrentam as criaturas do pântano e as tensões militares."},pl={title="Brackenwall Village",body="Brackenwall Village to osada ogrów w Dustwallow Marsh. Mieszkańcy utrzymują więzi z organizacją Horde, zmagając się ze stworzeniami bagien i napięciami militarnymi."},ru={title="Brackenwall Village",body="Brackenwall Village - это поселение Огров в Dustwallow Marsh. Ее жители поддерживают связи с Horde, несмотря на мусорные существа и военную напряженность."},references={["organization:horde"]=true,["place:dustwallow-marsh"]=true}},
    ["place:brewnall-village"] = {title="Las Birras",kind="Lugar",aliases={"Las Birras"},body="Las Birras es una comunidad de Dun Morogh vinculada a la elaboración de cerveza. Sus productores intercambian ingredientes, recetas y barriles con otros asentamientos de la región.",aliasQuestIDs={},en={title="Brewnall Village",aliases={"Brewnall","Brewnall Village"},body="Brewnall Village is a Dun Morogh community associated with brewing. Its producers exchange ingredients, recipes and kegs with other settlements in the region.",aliasQuestIDs={}},fr={title="Brewnall Village",body="Brewnall Village est une communauté Dun Morogh associée au brassage. Ses producteurs échangent des ingrédients, des recettes et des fûts avec d’autres établissements de la région."},de={title="Brewnall Village",body="Brewnall Village ist eine Dun Morogh-Gemeinschaft, die mit dem Brauen verbunden ist. Seine Produzenten tauschen Zutaten, Rezepte und Fässer mit anderen Siedlungen in der Region aus."},pt={title="Brewnall Village",body="Brewnall Village é uma comunidade Dun Morogh associada à fabricação de cerveja. Seus produtores trocam ingredientes, receitas e barris com outros assentamentos na região."},pl={title="Brewnall Village",body="Brewnall Village to społeczność w Dun Morogh związana z piwowarstwem. Wytwórcy wymieniają składniki, przepisy i beczki z innymi osadami regionu."},ru={title="Brewnall Village",body="Brewnall Village - это сообщество Dun Morogh, связанное с пивоварением. Производители обмениваются ингредиентами, рецептами и бочками с другими населенными пунктами региона."},references={["place:dun-morogh"]=true}},
    ["place:brill"] = {title="Rémol",kind="Lugar",aliases={"Rémol"},body="Rémol es un centro de los Renegados en Claros de Tirisfal. Oficiales, boticarios e instructores trabajan allí mientras sus defensores vigilan los caminos y los campos cercanos.",aliasQuestIDs={},en={title="Brill",aliases={"Brill"},body="Brill is a Forsaken center in Tirisfal Glades. Officers, apothecaries and trainers work there while its defenders watch nearby roads and fields.",aliasQuestIDs={}},fr={title="Brill",body="Brill est un centre Forsaken dans Tirisfal Glades. Les officiers, les apothicaires et les entraîneurs y travaillent pendant que ses défenseurs surveillent les routes et les champs à proximité."},de={title="Brill",body="Brill ist ein Forsaken-Center in Tirisfal Glades. Offiziere, Apotheker und Trainer arbeiten dort, während seine Verteidiger nahe gelegene Straßen und Felder Stadt überwachen."},pt={title="Brill",body="Brill é um centro Forsaken em Tirisfal Glades. Oficiais, boticários e treinadores trabalham lá enquanto seus defensores observam estradas e campos próximos."},pl={title="Brill",body="Brill jest ośrodkiem Forsaken w Tirisfal Glades. Pracują tu oficerowie, aptekarze i instruktorzy, a obrońcy obserwują pobliskie drogi i pola."},ru={title="Brill",body="Brill - это центр Forsaken в Tirisfal Glades. Там работают офицеры, аптеки и тренеры, а защитники охраняют близлежащие дороги и поля."},references={["organization:forsaken"]=true,["place:tirisfal-glades"]=true}},
    ["place:burning-steppes"] = {title="Estepas Ardientes",kind="Lugar",aliases={"Estepas Ardientes","Las Estepas Ardientes"},body="Las Estepas Ardientes son una región de la que parten fuerzas orcas Roca Negra que amenazan a sus vecinos. Sus caminos y puestos militares forman parte de la lucha por contener la influencia de la montaña cercana.",aliasQuestIDs={},en={title="Burning Steppes",aliases={"Burning Steppes"},body="The Burning Steppes are a region from which Blackrock orc forces threaten neighboring lands. Its roads and military posts are part of the struggle to contain the influence of the nearby mountain.",aliasQuestIDs={}},fr={title="Burning Steppes",body="Les Burning Steppes sont une région à partir de laquelle les forces orques Blackrock menacent les terres voisines. Ses routes et ses postes militaires font partie de la lutte pour contenir l'influence de la montagne voisine."},de={title="Burning Steppes",body="Die Burning Steppes sind eine Region, von der aus Blackrock-Orks Truppen benachbarte Länder bedrohen. Seine Straßen und Militärposten sind Teil des Kampfes, den Einfluss des nahegelegenen Gebirges einzudämmen."},pt={title="Burning Steppes",body="O Burning Steppes é uma região da qual as forças orc Blackrock ameaçam terras vizinhas. Suas estradas e postos militares fazem parte da luta para conter a influência da montanha próxima."},pl={title="Burning Steppes",body="Burning Steppes to region, z którego orkowe siły Blackrock zagrażają sąsiednim ziemiom. Jego drogi i posterunki wojskowe są częścią walki o powstrzymanie wpływów pobliskiej góry."},ru={title="Burning Steppes",body="Burning Steppes - это регион, из которого силы орков Blackrock угрожают соседним землям. Дороги и военные пункты являются частью борьбы за сдерживание влияния близлежащей горы."},references={}},
    ["place:caer-darrow"] = {title="Castel Darrow",kind="Lugar",aliases={"Castel Darrow"},body="Castel Darrow es la isla donde se encuentra Scholomance. La presencia de esa escuela ha convertido el lugar en un enclave de investigación y poder para la Plaga.",aliasQuestIDs={},en={title="Caer Darrow",aliases={"Caer Darrow"},body="Caer Darrow is the island on which Scholomance stands. The school's presence has made the site a center of research and power for the Scourge.",aliasQuestIDs={}},fr={title="Caer Darrow",body="Caer Darrow est l'île sur laquelle se trouve Scholomance. La présence de l'école a fait du site un centre de recherche et de puissance pour the Scourge."},de={title="Caer Darrow",body="Caer Darrow ist die Insel, auf der Scholomance steht. Die Anwesenheit der Schule hat den Standort zu einem Zentrum der Forschung und der Macht für the Scourge gemacht."},pt={title="Caer Darrow",body="Caer Darrow é a ilha em que se situa o Scholomance. A presença da escola fez do local um centro de pesquisa e poder para o the Scourge."},pl={title="Caer Darrow",body="Caer Darrow jest wyspą, na której stoi Scholomance. Obecność szkoły uczyniła to miejsce ośrodkiem badań i władzy sił znanych jako the Scourge."},ru={title="Caer Darrow",body="Caer Darrow - это остров, на котором стоит Scholomance. Присутствие школы сделало это место центром исследований и власти для the Scourge."},references={["organization:scourge"]=true,["place:scholomance"]=true}},
    ["place:camp-mojache"] = {title="Campamento Mojache",kind="Lugar",aliases={"Campamento Mojache"},body="El Campamento Mojache es un asentamiento de la Horda en Feralas. Sus habitantes, cazadores y artesanos ofrecen un punto de apoyo entre los bosques y las ruinas de la región.",aliasQuestIDs={},en={title="Camp Mojache",aliases={"Camp Mojache"},body="Camp Mojache is a Horde settlement in Feralas. Its residents, hunters and craftspeople provide a foothold among the region’s forests and ruins.",aliasQuestIDs={}},fr={title="Camp Mojache",body="Camp Mojache est un règlement Horde dans Feralas. Ses habitants, chasseurs et artisans s’installent au milieu des forêts et des ruines de la région."},de={title="Camp Mojache",body="Camp Mojache ist eine Horde-Siedlung in Feralas. Seine Bewohner, Jäger und Handwerker stellen ein Standbein in den Wäldern und Ruinen der Region dar."},pt={title="Camp Mojache",body="Camp Mojache é um assentamento Horde em Feralas. Seus moradores, caçadores e artesãos fornecem uma base entre as florestas e ruínas da região."},pl={title="Camp Mojache",body="Camp Mojache to osada frakcji Horde w Feralas. Jej mieszkańcy, myśliwi i rzemieślnicy zapewniają punkt oparcia pośród lasów i ruin regionu."},ru={title="Camp Mojache",body="Camp Mojache — поселение Horde на территории Feralas. Его жители, охотники и ремесленники обеспечивают себе место среди лесов и руин региона."},references={["organization:horde"]=true,["place:feralas"]=true}},
    ["place:camp-narache"] = {title="Campamento Narache",kind="Lugar",aliases={"Campamento Narache"},body="El Campamento Narache es un lugar de aprendizaje para los jóvenes tauren. La protección de sus habitantes, la caza y las enseñanzas de los ancestros vinculan la preparación individual con las necesidades del poblado.",aliasQuestIDs={},en={title="Camp Narache",aliases={"Camp Narache"},body="Camp Narache is a place of learning for young tauren. Protecting its residents, hunting and listening to the elders connect personal training with the needs of the village.",aliasQuestIDs={}},fr={title="Camp Narache",body="Camp Narache est un lieu d'apprentissage pour les jeunes taurens. Protéger ses habitants, chasser et écouter les anciens relient la formation personnelle aux besoins du village."},de={title="Camp Narache",body="Camp Narache ist ein Lernort für junge Tauren. Der Schutz seiner Bewohner, die Jagd und das Zuhören auf die Ältesten verbinden persönliches Training mit den Bedürfnissen des Dorfes."},pt={title="Camp Narache",body="Camp Narache é um lugar de aprendizagem para jovens tauren. Proteger seus moradores, caçar e ouvir os mais velhos conectar treinamento pessoal com as necessidades da aldeia."},pl={title="Camp Narache",body="Camp Narache to miejsce nauki młodych taurenów. Ochrona mieszkańców, polowania i słuchanie starszyzny łączą osobiste szkolenie z potrzebami wioski."},ru={title="Camp Narache",body="Camp Narache - это место обучения для молодых быков. Защита жителей, охота и слушание старейшин связывают личную подготовку с потребностями деревни."},references={}},
    ["place:camp-taurajo"] = {title="Campamento Taurajo",kind="Lugar",aliases={"Campamento Taurajo"},body="El Campamento Taurajo es un asentamiento tauren de Los Baldíos. Sus habitantes sostienen las rutas del sur y viven cerca de los territorios de caza y de los conflictos con los jabaespines.",aliasQuestIDs={},en={title="Camp Taurajo",aliases={"Camp Taurajo"},body="Camp Taurajo is a tauren settlement in the Barrens. Its residents support the southern routes and live close to both hunting grounds and conflicts with the quilboar.",aliasQuestIDs={}},fr={title="Camp Taurajo",body="Camp Taurajo est un règlement tauren dans le Barrens. Ses habitants soutiennent les routes du sud et vivent à proximité des terrains de chasse et des conflits avec le quilboar."},de={title="Camp Taurajo",body="Camp Taurajo ist eine Tauren-Siedlung im Barrens. Seine Bewohner unterstützen die südlichen Routen und leben sowohl in der Nähe von Jagdrevieren als auch in Konflikten mit den Quilbern."},pt={title="Camp Taurajo",body="Camp Taurajo é um assentamento de tauren no Barrens. Seus moradores apoiam as rotas do sul e vivem perto de ambos os campos de caça e conflitos com o quilboar."},pl={title="Camp Taurajo",body="Camp Taurajo to osada taurenów w regionie Barrens. Mieszkańcy zapewniają wsparcie na południowych szlakach, żyjąc blisko terenów łowieckich i obszarów konfliktu z kolcozwierzami."},ru={title="Camp Taurajo",body="Camp Taurajo - это поселение Тауренов в Barrens. Жители города поддерживают южные маршруты и живут недалеко от охотничьих угодий и конфликтов с кульбором."},references={["place:the-barrens"]=true}},
    ["place:cathedral-of-light"] = {title="Catedral de la Luz",kind="Lugar",aliases={"Catedral de la Luz"},body="La Catedral de la Luz es un centro de fe e instrucción en Ventormenta. Sus maestros orientan a quienes sirven a la Luz y entienden su aprendizaje como una responsabilidad de fe, humildad y trabajo.",aliasQuestIDs={},en={title="Cathedral of Light",aliases={"Cathedral of Light"},body="The Cathedral of Light is a center of faith and instruction in Stormwind. Its teachers guide those serving the Light and view their training as a responsibility grounded in faith, humility and work.",aliasQuestIDs={}},fr={title="Cathedral of Light",body="Le Cathedral of Light est un centre de foi et d'instruction en Stormwind. Ses enseignants guident ceux qui servent the Light et considèrent leur formation comme une responsabilité fondée sur la foi, l'humilité et le travail."},de={title="Cathedral of Light",body="Der Cathedral of Light ist ein Zentrum des Glaubens und der Lehre in Stormwind. Seine Lehrer leiten diejenigen, die the Light dienen und betrachten ihre Ausbildung als eine Verantwortung, die auf Glauben, Demut und Arbeit beruht."},pt={title="Cathedral of Light",body="O Cathedral of Light é um centro de fé e instrução no Stormwind. Seus professores orientam aqueles que servem the Light e vêem seu treinamento como uma responsabilidade fundamentada na fé, humildade e trabalho."},pl={title="Cathedral of Light",body="Cathedral of Light jest ośrodkiem wiary i nauki w Stormwind. Nauczyciele prowadzą tych, którzy służą „the Light”, traktując ich szkolenie jako odpowiedzialność opartą na wierze, pokorze i pracy."},ru={title="Cathedral of Light",body="Cathedral of Light - это центр веры и обучения в Stormwind. Наставники обучают тех, кто служит the Light, считая подготовку ответственным делом, основанным на вере, смирении и труде."},references={["concept:holy-light"]=true,["place:stormwind"]=true}},
    ["place:caverns-of-time"] = {title="Cavernas del Tiempo",kind="Lugar",aliases={"Cavernas del Tiempo"},body="Las Cavernas del Tiempo son un lugar de Tanaris custodiado por los guardianes del tiempo. Su relación con Nozdormu y sus hijos las sitúa bajo una protección distinta a la de los asentamientos del desierto.",aliasQuestIDs={},en={title="Caverns of Time",aliases={"Caverns of Time"},body="The Caverns of Time are a site in Tanaris watched by the guardians of time. Their relationship with Nozdormu and his children places them under a different kind of protection from the desert’s settlements.",aliasQuestIDs={}},fr={title="Caverns of Time",body="Les Caverns of Time sont un site en Tanaris surveillé par les gardiens du temps. Leur relation avec Nozdormu et ses enfants les place sous un autre type de protection contre les colonies du désert."},de={title="Caverns of Time",body="Die Caverns of Time sind eine Stätte in Tanaris, die von den Hütern der Zeit beobachtet wird. Ihre Beziehung zu Nozdormu und seinen Kindern stellt sie unter einen anderen Schutz als die Siedlungen in der Wüste."},pt={title="Caverns of Time",body="O Caverns of Time é um site no Tanaris assistido pelos guardiões do tempo. Sua relação com Nozdormu e seus filhos os coloca sob um tipo diferente de proteção contra os assentamentos do deserto."},pl={title="Caverns of Time",body="Caverns of Time to miejsce w Tanaris strzeżone przez strażników czasu. Związek z postacią Nozdormu i jego dziećmi zapewnia mu inny rodzaj ochrony niż osadom pustyni."},ru={title="Caverns of Time",body="Caverns of Time - это место в Tanaris, которое охраняют хранители времени. Их отношения с Nozdormu и его детьми обеспечивают им другую защиту от пустынных поселений."},references={["npc:nozdormu"]=true,["place:tanaris"]=true}},
    ["place:cenarion-hold"] = {title="Fuerte Cenarion",kind="Lugar",aliases={"Fuerte Cenarion"},body="El Fuerte Cenarion es una base de operaciones en Silithus. Desde allí se organizan patrullas, investigaciones y respuestas a las amenazas de las colmenas y los cultistas del desierto.",aliasQuestIDs={},en={title="Cenarion Hold",aliases={"Cenarion Hold"},body="Cenarion Hold is an operational base in Silithus. Patrols, investigations and responses to the threats from the desert’s hives and cultists are organized there.",aliasQuestIDs={}},fr={title="Cenarion Hold",body="Cenarion Hold est une base opérationnelle dans Silithus. Des patrouilles, des enquêtes et des réponses aux menaces des ruches et des cultes du désert y sont organisées."},de={title="Cenarion Hold",body="Cenarion Hold ist ein Stützpunkt in Silithus. Patrouillen, Untersuchungen und Reaktionen auf die Bedrohungen durch Bienenstöcke und Kultisten in der Wüste werden organisiert."},pt={title="Cenarion Hold",body="Cenarion Hold é uma base operacional em Silithus. Patrulhas, investigações e respostas às ameaças das colmeias e cultistas do deserto estão organizadas lá."},pl={title="Cenarion Hold",body="Cenarion Hold to baza operacyjna w Silithus. Organizowane są tam patrole, badania i działania przeciw zagrożeniom ze strony pustynnych rojów oraz kultystów."},ru={title="Cenarion Hold",body="Cenarion Hold - это оперативная база в Silithus. Там организуются патрули, расследования и реагирование на угрозы от ульев пустыни и культовых групп."},references={["place:silithus"]=true},questIDs={[8275]=true,[8276]=true,[8277]=true,[8278]=true,[8280]=true,[8281]=true,[8282]=true,[8283]=true,[8284]=true,[8285]=true,[8288]=true,[8302]=true,[8304]=true,[8306]=true,[8307]=true,[8313]=true,[8314]=true,[8315]=true,[8317]=true,[8318]=true,[8320]=true,[8321]=true,[8331]=true,[8332]=true,[8341]=true,[8343]=true,[8348]=true,[8349]=true,[8351]=true,[8352]=true,[8361]=true,[8446]=true,[8496]=true,[8497]=true,[8498]=true,[8501]=true,[8502]=true,[8507]=true,[8508]=true,[8534]=true,[8535]=true,[8536]=true,[8537]=true,[8538]=true,[8539]=true,[8540]=true,[8541]=true,[8548]=true,[8572]=true,[8573]=true,[8574]=true,[8687]=true,[8731]=true,[8732]=true,[8737]=true,[8738]=true,[8739]=true,[8740]=true,[8770]=true,[8771]=true,[8772]=true,[8773]=true,[8774]=true,[8775]=true,[8776]=true,[8777]=true,[8779]=true,[8782]=true,[8783]=true,[8791]=true,[8800]=true,[8804]=true,[8805]=true,[8806]=true,[8807]=true,[8808]=true,[8809]=true,[8810]=true,[8829]=true,[8856]=true,[9023]=true,[9248]=true}},
    ["place:cenarion-hold-darnassus"] = {title="Fuerte Cenarion",kind="Lugar",aliases={"Fuerte Cenarion"},body="El Fuerte Cenarion de Darnassus se encuentra en el sector norte de la ciudad y tiene profundidades a las que se accede por túneles. Las centinelas vigilan su entrada como parte de las medidas de protección de la ciudad.",aliasQuestIDs={},en={title="Cenarion Hold",aliases={"Cenarion Hold"},body="Darnassus’s Cenarion Hold stands in the northern part of the city and has depths reached through tunnels. Sentinels watch its entrance as part of the measures protecting the city.",aliasQuestIDs={}},fr={title="Cenarion Hold",body="Le Cenarion Hold de Darnassus se trouve dans la partie nord de la ville et possède des profondeurs accessibles par des tunnels. Les Sentinels surveillent son entrée dans le cadre des mesures de protection de la cité."},de={title="Cenarion Hold",body="Darnassus 's Cenarion Hold steht im nördlichen Teil der Stadt und hat eine Tiefe, die durch Tunnel erreicht wird. Sentinels beobachtet die Einfahrt als Teil der Maßnahmen zum Schutz der Stadt."},pt={title="Cenarion Hold",body="Darnassus do Cenarion Hold está na parte norte da cidade e tem profundidades alcançadas através de túneis. Sentinels observa sua entrada como parte das medidas que protegem a cidade."},pl={title="Cenarion Hold",body="Cenarion Hold w Darnassus znajduje się w północnej części miasta i posiada głębiny dostępne przez tunele. Sentinels obserwują wejście w ramach środków ochrony miasta."},ru={title="Cenarion Hold",body="Darnassus s Cenarion Hold находится в северной части города и имеет глубины, достигаемые через туннели. Sentinels следите за входом в качестве части мер по защите города."},references={["organization:night-elf-sentinels"]=true,["place:darnassus"]=true},questIDs={[98067]=true}},
    ["place:charred-vale"] = {title="La Vega Carbonizada",kind="Lugar",aliases={"La Vega Carbonizada","Vega Carbonizada"},body="La Vega Carbonizada es una zona de Sierra Espolón marcada por la destrucción del bosque. La presencia de fuego y criaturas hostiles dificulta la recuperación de un lugar donde el daño a la naturaleza sigue siendo visible.",aliasQuestIDs={},en={title="Charred Vale",aliases={"Charred Vale","The Charred Vale"},body="The Charred Vale is an area of the Stonetalon Mountains marked by the destruction of its forest. Fire and hostile creatures hinder the recovery of a place where the damage to nature remains visible.",aliasQuestIDs={}},fr={title="Charred Vale",body="The Charred Vale est une zone de la Stonetalon Mountains marquée par la destruction de sa forêt. Le feu et les créatures hostiles empêchent la récupération d'un endroit où les dommages à la nature restent visibles."},de={title="Charred Vale",body="The Charred Vale ist ein Gebiet des Stonetalon Mountains, das durch die Zerstörung seines Waldes Waldes Landes gekennzeichnet ist. Feuer und feindliche Kreaturen behindern die Wiederherstellung eines Ortes, wo die Schäden für die Natur sichtbar bleiben."},pt={title="Charred Vale",body="The Charred Vale é uma área do Stonetalon Mountains marcada pela destruição de sua floresta. Fogo e criaturas hostis impedem a recuperação de um lugar onde os danos à natureza permanecem visíveis."},pl={title="Charred Vale",body="The Charred Vale to obszar regionu Stonetalon Mountains naznaczony zniszczeniem lasu. Ogień i wrogie stworzenia utrudniają odrodzenie miejsca, w którym szkody wyrządzone przyrodzie wciąż są widoczne."},ru={title="Charred Vale",body="The Charred Vale - это район Stonetalon Mountains, отмеченный уничтожением леса. Огонь и враждебные существа препятствуют восстановлению места, где повреждения природы остаются видимыми."},references={["place:stonetalon-mountains"]=true}},
    ["place:chillwind-camp"] = {title="Campamento del Orvallo",kind="Lugar",aliases={"Campamento del Orvallo"},body="El Campamento del Orvallo es una base de la Alianza en las Tierras de la Peste del Oeste. Desde allí se investigan los venenos de los calderos y las actividades de enemigos de Lordaeron.",aliasQuestIDs={},en={title="Chillwind Camp",aliases={"Chillwind Camp"},body="Chillwind Camp is an Alliance base in Western Plaguelands. Research into cauldron poisons and the activities of Lordaeron's enemies is conducted from there.",aliasQuestIDs={}},fr={title="Chillwind Camp",body="Chillwind Camp est une base Alliance dans Western Plaguelands. Des recherches sur les poisons des chaudrons et les activités des ennemis de Lordaeron sont menées à partir de là."},de={title="Chillwind Camp",body="Chillwind Camp ist ein Alliance-Stützpunkt in Western Plaguelands. Von dort aus werden Forschungen über Hexenkesselgifte und die Aktivitäten der Feinde von Lordaeron \"durchgeführt."},pt={title="Chillwind Camp",body="Chillwind Camp é uma base Alliance em Western Plaguelands. A pesquisa sobre venenos de caldeirão e as atividades dos inimigos de Lordaeron é conduzida a partir daí."},pl={title="Chillwind Camp",body="Chillwind Camp jest bazą Alliance w Western Plaguelands. Prowadzi się stąd badania nad truciznami z kotłów i działaniami wrogów Lordaeron."},ru={title="Chillwind Camp",body="Chillwind Camp - это база Alliance в Western Plaguelands. Исследования ядов котла и деятельности врагов Lordaeron проводятся оттуда."},references={["organization:alliance"]=true,["place:lordaeron"]=true,["place:plaguelands"]=true,["place:western-plaguelands"]=true}},
    ["place:coldridge-valley"] = {title="Valle de Crestanevada",kind="Lugar",aliases={"Crestanevada","Valle de Crestanevada"},body="El Valle de Crestanevada forma parte de las tierras nevadas de Dun Morogh. La caza y la defensa frente a los troggs forman parte de la vida de quienes comienzan allí su camino entre los enanos.",aliasQuestIDs={},en={title="Coldridge Valley",aliases={"Coldridge","Coldridge Valley"},body="Coldridge Valley is part of Dun Morogh’s snowy lands. Hunting and defense against troggs are part of everyday life for those beginning their journey among the dwarves.",aliasQuestIDs={}},fr={title="Coldridge Valley",body="Coldridge Valley fait partie des terres enneigées de Dun Morogh. La chasse et la défense contre les trolls font partie de la vie quotidienne de ceux qui commencent leur voyage parmi les nains."},de={title="Coldridge Valley",body="Coldridge Valley gehört zu Dun Morogh \"verschneiten Ländern. Jagd und Verteidigung gegen Troggs gehören zum Alltag derer, die ihre Reise zwischen den Zwergen antreten."},pt={title="Coldridge Valley",body="Coldridge Valley faz parte das terras nevadas da Dun Morogh. A caça e a defesa contra os troggs fazem parte da vida cotidiana daqueles que começam sua jornada entre os anões."},pl={title="Coldridge Valley",body="Coldridge Valley należy do zaśnieżonych ziem Dun Morogh. Polowania i obrona przed troggami są codziennością tych, którzy rozpoczynają swoją drogę wśród krasnoludów."},ru={title="Coldridge Valley",body="Coldridge Valley является частью снежных земель Dun Morogh. Охота и защита от трогов - часть повседневной жизни тех, кто начинает свое путешествие среди карликов."},references={["place:dun-morogh"]=true}},
    ["place:coldtooth-mine"] = {title="Mina Dentefrío",kind="Lugar",aliases={"Dentefrío","Mina Dentefrío"},body="Mina Dentefrío sirve como reserva de suministros en el Valle de Alterac. Sus túneles cambian de manos cuando los ejércitos o los habitantes del subsuelo aprovechan la ausencia de una guarnición suficiente.",aliasQuestIDs={},en={title="Coldtooth Mine",aliases={"Coldtooth","Coldtooth Mine","Coldtooth mine"},body="Coldtooth Mine serves as a supply reserve in Alterac Valley. Its tunnels change hands when armies or underground inhabitants exploit the absence of a sufficient garrison.",aliasQuestIDs={}},fr={title="Coldtooth Mine",body="Coldtooth Mine sert de réserve d'approvisionnement dans Alterac Valley. Ses tunnels changent de mains lorsque les armées ou les habitants souterrains exploitent l'absence d'une garnison suffisante."},de={title="Coldtooth Mine",body="Coldtooth Mine dient in Alterac Valley als Versorgungsreserve. Seine Tunnel wechseln den Besitzer, wenn Armeen oder Untergrundbewohner das Fehlen einer ausreichenden Garnison ausnutzen."},pt={title="Coldtooth Mine",body="Coldtooth Mine serve como uma reserva de abastecimento em Alterac Valley. Seus túneis mudam de mãos quando exércitos ou habitantes subterrâneos exploram a ausência de uma guarnição suficiente."},pl={title="Coldtooth Mine",body="Coldtooth Mine służy jako magazyn zaopatrzenia w Alterac Valley. Jej tunele przechodzą z rąk do rąk, gdy armie lub podziemni mieszkańcy wykorzystują brak dostatecznego garnizonu."},ru={title="Coldtooth Mine",body="Coldtooth Mine служит запасом в Alterac Valley. Его туннели меняют владельцев, когда армии или подземные жители используют отсутствие достаточного гарнизона."},references={["place:alterac-mountains"]=true,["place:alterac-valley"]=true}},
    ["place:crystal-lake"] = {title="Lago de Cristal",kind="Lugar",aliases={"Lago de Cristal"},body="El Lago de Cristal ofrece recursos de pesca a los habitantes de Elwynn. La presencia de múrlocs en sus orillas amenaza tanto a los pescadores como al equilibrio de los peces que necesitan.",aliasQuestIDs={},en={title="Crystal Lake",aliases={"Crystal Lake"},body="Crystal Lake provides fishing resources for Elwynn’s inhabitants. Murlocs along its shores threaten both the fishers and the balance of fish they depend on.",aliasQuestIDs={}},fr={title="Crystal Lake",body="Crystal Lake fournit des ressources de pêche pour les habitants de Elwynn. Le Murlocs le long de ses rives menace à la fois les pêcheurs et l'équilibre des poissons dont ils dépendent."},de={title="Crystal Lake",body="Crystal Lake versorgt die Einwohner von Elwynn mit Fischereiressourcen. Murlocs an seinen Ufern bedroht sowohl die Fischer als auch das Gleichgewicht der Fische, von denen sie abhängig sind."},pt={title="Crystal Lake",body="Crystal Lake fornece recursos de pesca para os habitantes de Elwynn. Murlocs ao longo de suas costas ameaçam tanto os pescadores quanto o equilíbrio de peixes de que dependem."},pl={title="Crystal Lake",body="Crystal Lake dostarcza ryb mieszkańcom Elwynn. Murloki na jego brzegach zagrażają zarówno rybakom, jak i równowadze rybnych zasobów, od których zależy ich byt."},ru={title="Crystal Lake",body="Crystal Lake обеспечивает рыболовные ресурсы для жителей Elwynn s. Murlocs вдоль берегов угрожает рыбакам и балансу рыбы, от которой они зависят."},references={["place:elwynn-forest"]=true}},
    ["place:dagger-hills"] = {title="Colinas Afiladas",kind="Lugar",aliases={"Colinas Afiladas","Las Colinas Afiladas"},body="Las Colinas Afiladas se encuentran en el sureste de los Páramos de Poniente. Sus elevaciones ofrecen escondites a grupos de Defias que recorren y saquean las tierras cercanas.",aliasQuestIDs={},en={title="Dagger Hills",aliases={"Dagger Hills"},body="The Dagger Hills lie in southeastern Westfall. Their slopes provide hiding places for Defias groups raiding the surrounding countryside.",aliasQuestIDs={}},fr={title="Dagger Hills",body="Le Dagger Hills se trouve dans le sud-est Westfall. Leurs pentes fournissent des cachettes pour les groupes Defias qui pillent la campagne environnante."},de={title="Dagger Hills",body="Der Dagger Hills liegt im Südosten von Westfall. Ihre Hänge dienen als Verstecke für Defias-Gruppen, die die das umliegende Land überfallen."},pt={title="Dagger Hills",body="O Dagger Hills situa-se no sudeste do Westfall. Suas encostas fornecem esconderijos para grupos Defias que invadem a paisagem circundante."},pl={title="Dagger Hills",body="Dagger Hills leżą w południowo-wschodniej części Westfall. Ich zbocza zapewniają kryjówki grupom Defias najeżdżającym okoliczne ziemie."},ru={title="Dagger Hills",body="Dagger Hills лежат на юго-востоке Westfall. Их склоны обеспечивают укрытие для групп Defias, наносящих удары по окружающей сельской местности."},references={["organization:defias-brotherhood"]=true,["place:westfall"]=true}},
    ["place:dalaran"] = {title="Dalaran",kind="Lugar",aliases={"Ciudad de Dalaran","Dalaran"},body="Dalaran es una ciudad de magos vinculada al Kirin Tor y al estudio de las corrientes arcanas. La Ciudadela Violeta concentra parte de esa actividad, mientras los resguardos y las líneas ley tienen una importancia central para su seguridad.",aliasQuestIDs={},en={title="Dalaran",aliases={"City of Dalaran","Dalaran"},body="Dalaran is a city of mages associated with the Kirin Tor and the study of arcane currents. The Violet Citadel concentrates part of that work, while wards and ley lines are central to the city’s security.",aliasQuestIDs={}},fr={title="Dalaran",body="Dalaran est une ville de mages associée au Kirin Tor et à l'étude des courants arcaniques. Le Violet Citadel concentre une partie de ce travail, tandis que les quartiers et les lignes telluriques sont au cœur de la sécurité de la ville."},de={title="Dalaran",body="Dalaran ist eine Stadt der Magier, die mit dem Kirin Tor und dem Studium geheimnisvoller Strömungen in Verbindung gebracht werden. Der Violet Citadel konzentriert einen Teil dieser Arbeit, während Stationen und Leitungen zentral für die Sicherheit der Stadt sind."},pt={title="Dalaran",body="Dalaran é uma cidade de magos associada ao Kirin Tor e ao estudo de correntes arcanas. O Violet Citadel concentra parte desse trabalho, enquanto alas e linhas ley são centrais para a segurança da cidade."},pl={title="Dalaran",body="Dalaran to miasto magów związane z Kirin Tor i badaniem prądów magii tajemnej. Violet Citadel skupia część tych prac, a osłony i linie mocy mają kluczowe znaczenie dla bezpieczeństwa miasta."},ru={title="Dalaran",body="Dalaran - это город магов, связанный с Kirin Tor и изучением таинственных потоков. Часть этой работы сосредоточена в Violet Citadel, а отделения и линии лей являются центральными для безопасности города."},references={["organization:kirin-tor"]=true,["place:violet-citadel"]=true}},
    ["place:dalsons-tears"] = {title="Llanto de Dalson",kind="Lugar",aliases={"Llanto de Dalson"},body="El Llanto de Dalson es una antigua granja situada al norte de Andorhal. Su caldera de la Plaga utiliza una mezcla propia de componentes, parte de la contaminación que convierte los campos de Lordaeron en armas contra los vivos.",aliasQuestIDs={},en={title="Dalson's Tears",aliases={"Dalson's Tears","Dalson’s Tears"},body="Dalson's Tears is a former farm north of Andorhal. Its Scourge cauldron uses a distinct mixture of reagents, part of the contamination turning Lordaeron's fields into weapons against the living.",aliasQuestIDs={}},fr={title="Dalson's Tears",body="Dalson's Tears est une ancienne ferme au nord de Andorhal. Son chaudron Scourge utilise un mélange distinct de réactifs, une partie de la contamination transformant les champs de Lordaeron en armes contre les vivants."},de={title="Dalson's Tears",body="Dalson's Tears ist ein ehemaliger Bauernhof nördlich von Andorhal. Sein Scourge-Hexenkessel verwendet eine deutliche Mischung aus Reagenzien, die Felder Felder Lordaeron teilweise in Waffen gegen die Lebenden verwandelt."},pt={title="Dalson's Tears",body="Dalson's Tears é uma antiga fazenda ao norte de Andorhal. Seu caldeirão Scourge usa uma mistura distinta de reagentes, parte da contaminação transformando os campos de Lordaeron em armas contra os vivos."},pl={title="Dalson's Tears",body="Dalson's Tears jest dawną farmą na północ od Andorhal. Jej kocioł Scourge wykorzystuje odrębną mieszankę odczynników, stanowiącą część skażenia zmieniającego pola Lordaeron w broń przeciw żywym."},ru={title="Dalson's Tears",body="Dalson's Tears - это бывшая ферма к северу от Andorhal. Его котёл Scourge использует различную смесь реагентов, часть загрязнения превращает поля Lordaeron в оружие против живых."},references={["organization:scourge"]=true,["place:andorhal"]=true,["place:lordaeron"]=true}},
    ["place:dark-portal"] = {title="Portal Oscuro",kind="Lugar",aliases={"Portal Oscuro"},body="El Portal Oscuro es el paso asociado con la llegada de los orcos a Azeroth. Su presencia da a las Tierras Devastadas una importancia que supera sus fronteras: representa tanto un peligro mágico como un recuerdo de las guerras entre mundos.",aliasQuestIDs={},en={title="Dark Portal",aliases={"Dark Portal"},body="The Dark Portal is the gateway associated with the orcs’ arrival on Azeroth. Its presence gives the Blasted Lands an importance beyond their borders, representing both a magical danger and a memory of war between worlds.",aliasQuestIDs={}},fr={title="Dark Portal",body="Le Dark Portal est la passerelle associée à l'arrivée des orcs sur Azeroth. Sa présence confère au Blasted Lands une importance au-delà de leurs frontières, représentant à la fois un danger magique et un souvenir de guerre entre les mondes."},de={title="Dark Portal",body="Der Dark Portal ist das Tor zur Ankunft der Orks auf Azeroth. Seine Anwesenheit verleiht den Blasted Lands eine Bedeutung über ihre Grenzen hinaus und stellt sowohl eine magische Gefahr als auch eine Erinnerung an den Krieg zwischen den Welten dar."},pt={title="Dark Portal",body="O Dark Portal é o portal associado à chegada dos orcs ao Azeroth. Sua presença dá ao Blasted Lands uma importância além de suas fronteiras, representando tanto um perigo mágico quanto uma memória de guerra entre mundos."},pl={title="Dark Portal",body="Dark Portal to brama związana z przybyciem orków do Azeroth. Nadaje Blasted Lands znaczenie wykraczające poza ich granice, przypominając o magicznym zagrożeniu i wojnie między światami."},ru={title="Dark Portal",body="Dark Portal - это шлюз, связанный с прибытием орков на Azeroth. Его присутствие придает Blasted Lands важность за пределами их границ, представляя одновременно магическую опасность и память о войне между мирами."},references={["place:azeroth"]=true,["place:blasted-lands"]=true}},
    ["place:darkcloud-pinnacle"] = {title="Cumbre de la Nube Negra",kind="Lugar",aliases={"Cumbre de la Nube Negra"},body="Cumbre de la Nube Negra es un enclave de los Tótem Siniestro en Las Mil Agujas. Sus riscos albergan actividades del clan y cofres vigilados donde se mantienen sus comunicaciones.",aliasQuestIDs={},en={title="Darkcloud Pinnacle",aliases={"Darkcloud Pinnacle"},body="Darkcloud Pinnacle is a Grimtotem enclave in Thousand Needles. Its cliffs shelter the clan’s activities and guarded chests holding its communications.",aliasQuestIDs={}},fr={title="Darkcloud Pinnacle",body="Darkcloud Pinnacle est une enclave Grimtotem dans Thousand Needles. Ses falaises abritaient les activités du clan et gardaient les coffres qui retenaient ses communications."},de={title="Darkcloud Pinnacle",body="Darkcloud Pinnacle ist eine Enklave von Grimtotem in Thousand Needles. Seine Klippen schützen die Aktivitäten des Clans und bewachen die Truhen, in denen seine Kommunikation stattfindet."},pt={title="Darkcloud Pinnacle",body="Darkcloud Pinnacle é um enclave Grimtotem em Thousand Needles. Suas falésias abrigam as atividades do clã e os baús guardados segurando suas comunicações."},pl={title="Darkcloud Pinnacle",body="Darkcloud Pinnacle jest enklawą Grimtotem w Thousand Needles. Klify skrywają działalność klanu oraz strzeżone skrzynie z jego korespondencją."},ru={title="Darkcloud Pinnacle",body="Darkcloud Pinnacle - это анклав Grimtotem в Thousand Needles. Его скалы защищают деятельность клана и охраняют сундуки, содержащие его коммуникации."},references={["place:thousand-needles"]=true}},
    ["place:darkmist-cavern"] = {title="Cueva Niebla Negra",kind="Lugar",aliases={"Cueva Niebla Negra"},body="La Cueva Niebla Negra alberga las arañas del mismo nombre en el Marjal Revolcafango. Su relación con esas criaturas es tan estrecha que los habitantes de la región se preguntan si la cueva recibió el nombre de ellas o a la inversa.",aliasQuestIDs={},en={title="Darkmist Cavern",aliases={"Darkmist Cavern"},body="Darkmist Cavern houses its namesake spiders in Dustwallow Marsh. The association is so close that local people wonder whether the cave was named after the spiders or the other way around.",aliasQuestIDs={}},fr={title="Darkmist Cavern",body="Darkmist Cavern abrite ses araignées homonymes dans Dustwallow Marsh. L'association est si proche que les gens locaux se demandent si la grotte a été nommée d'après les araignées ou l'inverse."},de={title="Darkmist Cavern",body="Darkmist Cavern beherbergt seine namensgebenden Spinnen in Dustwallow Marsh. Der Verein ist so eng verbunden, dass sich die Anwohner fragen, ob die Höhle nach den Spinnen benannt wurde oder umgekehrt."},pt={title="Darkmist Cavern",body="Darkmist Cavern abriga suas aranhas homônimas em Dustwallow Marsh. A associação é tão próxima que as pessoas locais se perguntam se a caverna recebeu o nome das aranhas ou o contrário."},pl={title="Darkmist Cavern",body="Darkmist Cavern jest jaskinią w Dustwallow Marsh zamieszkaną przez pająki o tej samej nazwie. Związek jest tak bliski, że miejscowi zastanawiają się, czy nazwano jaskinię od pająków, czy odwrotnie."},ru={title="Darkmist Cavern",body="Darkmist Cavern хранит своих одноименных пауков в Dustwallow Marsh. Это связь настолько тесная, что местные жители задаются вопросом, названа ли пещера в честь пауков или наоборот."},references={["place:dustwallow-marsh"]=true}},
    ["place:darkshire"] = {title="Villa Oscura",kind="Lugar",aliases={"Villa Oscura"},body="Villa Oscura es el núcleo de la comunidad humana del Bosque del Ocaso. Su concejo, sus guardias y sus vecinos intentan mantener una vida organizada en medio de un bosque donde incluso los cementerios representan una amenaza.",aliasQuestIDs={},en={title="Darkshire",aliases={"Darkshire"},body="Darkshire is the center of Duskwood’s human community. Its council, guards and residents try to maintain an orderly life in a forest where even the graveyards pose a threat.",aliasQuestIDs={}},fr={title="Darkshire",body="Darkshire est le centre de la communauté humaine de Duskwood. Son conseil, ses gardes et ses habitants tentent de maintenir une vie ordonnée dans une forêt où même les cimetières constituent une menace."},de={title="Darkshire",body="Darkshire ist das Zentrum der menschlichen Gemeinschaft von Duskwood. Rat, Wächter und Bewohner versuchen, ein geordnetes Leben in einem Wald aufrechtzuerhalten, in dem sogar die Friedhöfe eine Bedrohung darstellen."},pt={title="Darkshire",body="Darkshire é o centro da comunidade humana de Duskwood. Seu conselho, guardas e moradores tentam manter uma vida ordenada em uma floresta onde até mesmo os cemitérios representam uma ameaça."},pl={title="Darkshire",body="Darkshire jest centrum ludzkiej społeczności Duskwood. Rada, strażnicy i mieszkańcy próbują utrzymać uporządkowane życie w lesie, w którym nawet cmentarze stanowią zagrożenie."},ru={title="Darkshire",body="Darkshire - это центр человеческого сообщества Duskwood. Его совет, охранники и жители пытаются сохранить порядок в лесу, где даже кладбища представляют угрозу."},references={["place:duskwood"]=true}},
    ["place:darkshore"] = {title="Costa Oscura",kind="Lugar",aliases={"Costa Oscura"},body="Costa Oscura es una región costera de Kalimdor donde los bosques se encuentran con un mar peligroso. Sus antiguos asentamientos en ruinas y sus restos de naufragios conviven con los esfuerzos de Auberdine por mantener abiertas las rutas marítimas.",aliasQuestIDs={},en={title="Darkshore",aliases={"Darkshore"},body="Darkshore is a coastal region of Kalimdor where forests meet a dangerous sea. Ruined ancient settlements and shipwrecks stand alongside Auberdine’s efforts to keep sea routes open.",aliasQuestIDs={}},fr={title="Darkshore",body="Darkshore est une région côtière de Kalimdor où les forêts rencontrent une mer dangereuse. Les anciennes colonies en ruine et les épaves côtoient les efforts de Auberdine pour garder les routes maritimes ouvertes."},de={title="Darkshore",body="Darkshore ist eine Küstenregion von Kalimdor, wo Wälder auf ein gefährliches Meer treffen. Zerstörte antike Siedlungen und Schiffswracks stehen neben Auberdine \"Bemühungen, die Seewege offen zu halten."},pt={title="Darkshore",body="Darkshore é uma região costeira de Kalimdor onde as florestas encontram um mar perigoso. Os antigos assentamentos e naufrágios arruinados estão ao lado dos esforços da Auberdine para manter as rotas marítimas abertas."},pl={title="Darkshore",body="Darkshore to nadmorski region kontynentu Kalimdor, w którym lasy spotykają się z niebezpiecznym morzem. Ruiny pradawnych osad i wraki statków sąsiadują z wysiłkami mieszkańców Auberdine, by utrzymać otwarte szlaki morskie."},ru={title="Darkshore",body="Darkshore - это прибрежный регион Kalimdor, где леса встречаются с опасным морем. Разрушенные древние поселения и кораблекрушения стоят наряду с усилиями Auberdine  сохранить открытыми морские пути."},references={["place:auberdine"]=true,["place:kalimdor"]=true}},
    ["place:darkspear-islands"] = {title="Islas Lanza Negra",kind="Lugar",aliases={"Islas Lanza Negra"},body="Las Islas Lanza Negra son un territorio disputado entre la Horda y la Fuerza Expedicionaria de Theramore. El envío constante de refuerzos muestra la importancia militar que ambos bandos conceden a mantener una posición en las islas.",aliasQuestIDs={},en={title="Darkspear Islands",aliases={"Darkspear Islands"},body="The Darkspear Islands are a territory contested by the Horde and the Theramore Expeditionary Force. The constant arrival of reinforcements shows the military importance both sides place on maintaining a position on the islands.",aliasQuestIDs={}},fr={title="Darkspear Islands",body="Les Darkspear Islands sont un territoire contesté par les Horde et Theramore Expeditionary Force. L'arrivée constante de renforts montre l'importance militaire que les deux parties accordent au maintien d'une position sur les îles."},de={title="Darkspear Islands",body="Die Darkspear Islands sind ein Territorium, das von Horde und Theramore Expeditionary Force umkämpft wird. Das ständige Eintreffen von Verstärkungen zeigt die militärische Bedeutung, die beide Seiten der Aufrechterhalten einer Position auf den Inseln beimessen."},pt={title="Darkspear Islands",body="O Darkspear Islands é um território contestado pelo Horde e o Theramore Expeditionary Force. A chegada constante de reforços mostra a importância militar que ambos os lados colocam na manutenção de uma posição nas ilhas."},pl={title="Darkspear Islands",body="Darkspear Islands to terytorium będące przedmiotem walk między frakcją Horde a Theramore Expeditionary Force. Stały napływ posiłków pokazuje wojskowe znaczenie przypisywane przez obie strony utrzymaniu pozycji na wyspach."},ru={title="Darkspear Islands",body="Darkspear Islands - это территория, на которой спорят Horde и Theramore Expeditionary Force. Постоянное прибытие подкреплений показывает военную важность обеих сторон для поддержания позиции на островах."},references={["organization:darkspear-tribe"]=true,["organization:horde"]=true,["organization:theramore-expeditionary-force"]=true,["place:theramore"]=true}},
    ["place:darnassus"] = {title="Darnassus",kind="Lugar",aliases={"Darnassus"},body="Darnassus es una ciudad de los elfos de la noche en Teldrassil. Sus templos, santuarios y bancales reúnen a sacerdotisas, druidas, centinelas y artesanos alrededor de la vida espiritual y comunitaria de su pueblo.",aliasQuestIDs={},en={title="Darnassus",aliases={"Darnassus"},body="Darnassus is a night elf city in Teldrassil. Its temples, shrines and terraces bring priestesses, druids, sentinels and craftspeople together around their people’s spiritual and communal life.",aliasQuestIDs={}},fr={title="Darnassus",body="Darnassus est une ville elfe de nuit dans Teldrassil. Ses temples, sanctuaires et terrasses rassemblent prêtresses, druides, sentinelles et artisans autour de la vie spirituelle et communautaire de leur peuple."},de={title="Darnassus",body="Darnassus ist eine Nachtelfenstadt in Teldrassil. Seine Tempel, Schreine und Terrassen bringen Priesterinnen, Druiden, Wachtposten und Handwerker um das spirituelle und Gemeinschaftsleben ihres Volkes zusammen."},pt={title="Darnassus",body="Darnassus é uma cidade de elfo noturno em Teldrassil. Seus templos, santuários e terraços trazem sacerdotisas, druidas, sentinelas e artesãos juntos em torno da vida espiritual e comunitária de seu povo."},pl={title="Darnassus",body="Darnassus to miasto nocnych elfów w Teldrassil. Jego świątynie, kapliczki i tarasy skupiają kapłanki, druidów, strażniczki i rzemieślników wokół duchowego oraz wspólnotowego życia ich ludu."},ru={title="Darnassus",body="Darnassus - город ночных эльфов в Teldrassil. Храмы, святилища и террасы объединяют жриц, друидов, sentinels и ремесленников вокруг духовной и общественной жизни народа."},references={["organization:night-elf-sentinels"]=true,["place:teldrassil"]=true}},
    ["place:darrowshire"] = {title="Villa Darrow",kind="Lugar",aliases={"Villa Darrow"},body="Villa Darrow es una aldea de Lordaeron devastada durante la guerra contra la Plaga. Su historia persiste en crónicas, reliquias y recuerdos de familias como los Rutagrana.",aliasQuestIDs={},en={title="Darrowshire",aliases={"Darrowshire"},body="Darrowshire is a Lordaeron village devastated during the war against the Scourge. Its history survives in chronicles, relics and the memories of families such as the Redpaths.",aliasQuestIDs={}},fr={title="Darrowshire",body="Darrowshire est un village Lordaeron dévasté pendant la guerre contre the Scourge. Son histoire survit dans les chroniques, les reliques et les souvenirs de familles telles que la Redpaths."},de={title="Darrowshire",body="Darrowshire ist ein Lordaeron Dorf, das während des Krieges gegen the Scourge zerstört wurde. Seine Geschichte ist in Chroniken, Relikten und Erinnerungen von Familien wie den Redpaths überliefert."},pt={title="Darrowshire",body="Darrowshire é uma aldeia Lordaeron devastada durante a guerra contra the Scourge. Sua história sobrevive em crônicas, relíquias e memórias de famílias como o Redpaths."},pl={title="Darrowshire",body="Darrowshire jest wioską Lordaeron zniszczoną podczas wojny przeciw siłom znanym jako the Scourge. Jej historia przetrwała w kronikach, reliktach i wspomnieniach rodzin takich jak Redpaths."},ru={title="Darrowshire",body="Darrowshire - это деревня Lordaeron, разрушенная во время войны против the Scourge. Его история сохранилась в летописях, реликвиях и воспоминаниях таких семей, как Redpaths."},references={["organization:scourge"]=true,["place:lordaeron"]=true}},
    ["place:dead-fields"] = {title="El Campo Muerto",kind="Lugar",aliases={"Campo Muerto","El Campo Muerto"},body="El Campo Muerto es una antigua granja del norte de Argénteos que sirve como base a los gnolls Putrepellejo. La magia de Latipesadilla refuerza sus defensas y dificulta los asaltos de los agentes de El Sepulcro.",aliasQuestIDs={},en={title="The Dead Fields",aliases={"Dead Field","Dead Fields","The Dead Fields"},body="The Dead Fields is an old northern Silverpine farm serving as a Rot Hide gnoll base. Nightlash's magic strengthens its defenses and hinders assaults by the Sepulcher's agents.",aliasQuestIDs={}},fr={title="The Dead Fields",body="The Dead Fields est une ancienne ferme du nord de Silverpine servant de base de gnoll Rot Hide. La magie de Nightlash renforce ses défenses et entrave les assauts des agents du Sepulcher."},de={title="The Dead Fields",body="The Dead Fields ist ein alter Bauernhof im Norden von Silverpine, der den Gnollen der Rot Hide als Stützpunkt dient. Die Magie von Nightlash stärkt seine Verteidigung und erschwert Angriffe der Agenten von Sepulcher."},pt={title="The Dead Fields",body="The Dead Fields é uma antiga fazenda do norte do Silverpine que serve como uma base de gnoll Rot Hide. A magia de Nightlash fortalece suas defesas e dificulta os ataques dos agentes do Sepulcher."},pl={title="The Dead Fields",body="The Dead Fields jest dawną farmą w północnym Silverpine służącą gnollom Rot Hide jako baza. Magia Nightlash wzmacnia obronę i utrudnia szturmy agentów Sepulcher."},ru={title="The Dead Fields",body="The Dead Fields — старая ферма на севере Silverpine, служащая базой гноллам Rot Hide. Магия Nightlash укрепляет её защиту и мешает нападениям агентов Sepulcher."},references={["npc:nightlash"]=true,["organization:rot-hide"]=true,["place:silverpine-forest"]=true,["place:the-sepulcher"]=true}},
    ["place:deadmines"] = {title="Minas de la Muerte",kind="Lugar",aliases={"Minas de la Muerte"},body="Las Minas de la Muerte forman un complejo de galerías bajo la región de Arroyo de la Luna. La actividad minera y la presencia de los Defias convierten sus profundidades en un lugar peligroso, alejado del control de los defensores de Poniente.",aliasQuestIDs={},en={title="The Deadmines",aliases={"Deadmines","The Deadmines"},body="The Deadmines form a network of tunnels beneath the Moonbrook district. Mining and the presence of the Defias make their depths a dangerous place beyond the control of Westfall’s defenders.",aliasQuestIDs={}},fr={title="The Deadmines",body="The Deadmines forme un réseau de tunnels sous le quartier Moonbrook. L’exploitation minière et la présence du Defias font de leurs profondeurs un endroit dangereux, hors du contrôle des défenseurs du Westfall."},de={title="The Deadmines",body="The Deadmines bildet ein Tunnelnetz unter dem Moonbrook-Viertel. Der Bergbau und die Anwesenheit der Defias machen ihre Tiefen zu einem gefährlichen Ort, der sich der Kontrolle der Verteidiger von Westfall 's entzieht."},pt={title="The Deadmines",body="The Deadmines formam uma rede de túneis sob o distrito de Moonbrook. A mineração e a presença do Defias fazem de suas profundezas um lugar perigoso além do controle dos defensores do Westfall."},pl={title="The Deadmines",body="The Deadmines to sieć tuneli pod okolicą Moonbrook. Górnictwo i obecność Defias czynią ich głębiny niebezpiecznym miejscem, pozostającym poza kontrolą obrońców Westfall."},ru={title="The Deadmines",body="The Deadmines образуют сеть туннелей под районом Moonbrook. Шахтование и присутствие Defias делают их глубины опасным местом, за пределами контроля защитников Westfall."},references={["organization:defias-brotherhood"]=true,["place:moonbrook"]=true,["place:westfall"]=true}},
    ["place:deadwind-pass"] = {title="Paso de la Muerte",kind="Lugar",aliases={"Paso de la Muerte"},body="El Paso de la Muerte es una región asociada a los temidos Jinetes Oscuros. Las noticias de sus incursiones alcanzan a las comunidades vecinas del Bosque del Ocaso y refuerzan la inquietud de quienes viven cerca de sus caminos.",aliasQuestIDs={},en={title="Deadwind Pass",aliases={"Deadwind","Deadwind Pass"},body="Deadwind Pass is a region associated with the feared Dark Riders. Reports of their raids reach neighboring Duskwood communities and deepen the unease of those living near its roads.",aliasQuestIDs={}},fr={title="Deadwind Pass",body="Deadwind Pass est une région associée aux redoutables Dark Riders. Les rapports de leurs raids atteignent les communautés voisines de Duskwood et approfondissent le malaise de ceux qui vivent près de ses routes."},de={title="Deadwind Pass",body="Deadwind Pass ist eine Region, die mit den gefürchteten Dunklen Reitern in Verbindung steht. Berichte über ihre Überfälle erreichen die benachbarten Gemeinschaften von Duskwood und verstärken die Unruhe der Bewohner entlang der Straßen."},pt={title="Deadwind Pass",body="Deadwind Pass é uma região associada aos temidos Dark Riders. Os relatórios de seus ataques chegam às comunidades vizinhas Duskwood e aprofundam o mal-estar daqueles que vivem perto de suas estradas."},pl={title="Deadwind Pass",body="Deadwind Pass to region związany z budzącymi lęk Mrocznymi Jeźdźcami. Wieści o ich najazdach docierają do sąsiednich społeczności Duskwood i pogłębiają niepokój mieszkańców przydrożnych terenów."},ru={title="Deadwind Pass",body="Deadwind Pass - это регион, связанный с страшными Темными Всадниками. Сообщения об их рейдах доходят до соседних общин Duskwood и усугубляют беспокойство тех, кто живет рядом с дорогами."},references={["place:duskwood"]=true}},
    ["place:deathknell"] = {title="Camposanto",kind="Lugar",aliases={"Camposanto"},body="Camposanto es una comunidad de los Renegados en Claros de Tirisfal. Su cripta y su capilla acogen a no-muertos que despiertan libres del Rey Exánime y necesitan orientación.",aliasQuestIDs={},en={title="Deathknell",aliases={"Deathknell"},body="Deathknell is a Forsaken community in Tirisfal Glades. Its crypt and chapel receive undead who awaken free of the Lich King and need guidance.",aliasQuestIDs={}},fr={title="Deathknell",body="Deathknell est une communauté de Forsaken dans la communauté Tirisfal Glades. Sa crypte et sa chapelle reçoivent des morts-vivants qui se réveillent sans le Lich King et ont besoin de conseils."},de={title="Deathknell",body="Deathknell ist eine Forsaken-Gemeinschaft in Tirisfal Glades. Seine Krypta und seine Kapelle empfangen Untote, die frei vom Lich King erwachen und Führung brauchen."},pt={title="Deathknell",body="Deathknell é uma comunidade Forsaken em Tirisfal Glades. Sua cripta e capela recebem mortos-vivos que despertam livres do Lich King e precisam de orientação."},pl={title="Deathknell",body="Deathknell jest społecznością Forsaken w Tirisfal Glades. Jej krypta i kaplica przyjmują nieumarłych, którzy budzą się wolni od Lich King i potrzebują wskazówek."},ru={title="Deathknell",body="Deathknell - это сообщество Forsaken в Tirisfal Glades. В его склепе и часовне живут неживые, которые просыпаются свободными от Lich King и нуждаются в руководстве."},references={["npc:lich-king"]=true,["organization:forsaken"]=true,["place:tirisfal-glades"]=true}},
    ["place:desolace"] = {title="Desolace",kind="Lugar",aliases={"Desolace"},body="Desolace es una región de Kalimdor marcada por la aridez y las disputas entre clanes de centauros. Los pequeños asentamientos de otras razas intentan sobrevivir entre esas rivalidades y las amenazas de sus ruinas y valles.",aliasQuestIDs={},en={title="Desolace",aliases={"Desolace"},body="Desolace is a region of Kalimdor marked by aridity and disputes between centaur clans. Small settlements of other peoples try to survive amid those rivalries and the threats in its ruins and valleys.",aliasQuestIDs={}},fr={title="Desolace",body="Desolace est une région de Kalimdor marquée par l'aridité et les conflits entre les clans centaures. De petites colonies d'autres peuples tentent de survivre au milieu de ces rivalités et des menaces dans ses ruines et ses vallées."},de={title="Desolace",body="Desolace ist eine Region von Kalimdor, die von Trockenheit und Streitigkeiten zwischen den Zentauren-Clans geprägt ist. Kleine Siedlungen anderer Völker versuchen inmitten dieser Rivalitäten und der Bedrohungen in ihren Ruinen und Tälern zu überleben."},pt={title="Desolace",body="Desolace é uma região do Kalimdor marcada por aridez e disputas entre clãs centauros. Pequenos assentamentos de outros povos tentam sobreviver em meio a essas rivalidades e as ameaças em suas ruínas e vales."},pl={title="Desolace",body="Desolace to region kontynentu Kalimdor naznaczony suszą i sporami klanów centaurów. Małe osady innych ludów próbują przetrwać pośród tych rywalizacji oraz zagrożeń kryjących się w ruinach i dolinach."},ru={title="Desolace",body="Desolace - это регион Kalimdor, отмеченный засушливостью и спорами между кланами кентавров. Небольшие поселения других народов пытаются выжить среди этих соперничеств и угроз в его руинах и долинах."},references={["place:kalimdor"]=true}},
    ["place:dire-maul"] = {title="La Masacre",kind="Lugar",aliases={"Eldre'Thalas","Eldre’Thalas","La Masacre"},body="La Masacre ocupa las ruinas de Eldre'Thalas en Feralas. Los restos de esta ciudad albergan habitantes y poderes rivales, por lo que sus antiguos conocimientos y recursos están lejos de encontrarse a salvo.",aliasQuestIDs={},en={title="Dire Maul",aliases={"Dire Maul","Eldre'Thalas","Eldre’Thalas"},body="Dire Maul occupies the ruins of Eldre'Thalas in Feralas. Rival inhabitants and powers occupy the remains of the city, leaving its ancient knowledge and resources far from secure.",aliasQuestIDs={}},fr={title="Dire Maul",body="Dire Maul occupe les ruines de Eldre'Thalas dans Feralas. Les habitants rivaux et les pouvoirs occupent les vestiges de la ville, laissant ses connaissances et ses ressources anciennes loin d'être en sécurité."},de={title="Dire Maul",body="Dire Maul besetzt die Ruinen von Eldre'Thalas in Feralas. Rivalisierende Einwohner und Mächte besetzen die Überreste der Stadt und lassen ihr uraltes Wissen und ihre Ressourcen alles andere als sicher zurück."},pt={title="Dire Maul",body="Dire Maul ocupa as ruínas de Eldre'Thalas em Feralas. Habitantes e poderes rivais ocupam os restos da cidade, deixando seus antigos conhecimentos e recursos longe de serem seguros."},pl={title="Dire Maul",body="Dire Maul zajmuje ruiny Eldre'Thalas w Feralas. Rywalizujący mieszkańcy i potęgi władają pozostałościami miasta, przez co jego pradawna wiedza oraz zasoby są dalekie od bezpieczeństwa."},ru={title="Dire Maul",body="Dire Maul занимает руины Eldre'Thalas в Feralas. Соперничающие жители и державы занимают руины города, оставляя его древние знания и ресурсы далеко не безопасными."},references={["place:feralas"]=true}},
    ["place:dolanaar"] = {title="Dolanaar",kind="Lugar",aliases={"Dolanaar"},body="Dolanaar es un poblado de Teldrassil. Sus instructores, artesanos y guardianes atienden las necesidades de quienes viven en el gran árbol y de los viajeros que empiezan a recorrerlo.",aliasQuestIDs={},en={title="Dolanaar",aliases={"Dolanaar"},body="Dolanaar is a village in Teldrassil. Its trainers, craftspeople and guardians serve the people living within the great tree and travelers beginning to explore it.",aliasQuestIDs={}},fr={title="Dolanaar",body="Dolanaar est village en Teldrassil. Ses formateurs, artisans et gardiens servent les personnes vivant dans le grand arbre et les voyageurs qui commencent à l'explorer."},de={title="Dolanaar",body="Dolanaar ist ein Dorf in Teldrassil. Seine Trainer, Handwerker und Wächter dienen den Menschen, die innerhalb des großen Baumes leben und den Reisenden, die ihn zu erkunden beginnen."},pt={title="Dolanaar",body="Dolanaar é uma vila localizada no estado americano de Teldrassil. Seus treinadores, artesãos e guardiões servem as pessoas que vivem dentro da grande árvore e os viajantes começam a explorá-la."},pl={title="Dolanaar",body="Dolanaar to wioska w Teldrassil. Jej nauczyciele, rzemieślnicy i strażnicy służą mieszkańcom wielkiego drzewa oraz podróżnym rozpoczynającym jego poznawanie."},ru={title="Dolanaar",body="Dolanaar - это деревня в Teldrassil. Его тренеры, ремесленники и хранители служат людям, живущим внутри большого дерева и путешественникам, начинающим исследовать его."},references={["place:teldrassil"]=true}},
    ["place:dreadmaul-rock"] = {title="Roca Machacamiedo",kind="Lugar",aliases={"Roca Machacamiedo"},body="La Roca Machacamiedo es un enclave de ogros con cuevas y posiciones en las Estepas Ardientes. La presencia de jefes y cautivos lo relaciona con los peligros que afrontan las tropas que recorren la región.",aliasQuestIDs={},en={title="Dreadmaul Rock",aliases={"Dreadmaul Rock"},body="Dreadmaul Rock is an ogre stronghold with caves and positions in the Burning Steppes. The presence of leaders and captives connects it with dangers faced by troops traveling through the region.",aliasQuestIDs={}},fr={title="Dreadmaul Rock",body="Dreadmaul Rock est un bastion ogre avec des grottes et des positions dans le Burning Steppes. La présence de dirigeants et de captifs le relie aux dangers auxquels sont confrontées les troupes qui traversent la région."},de={title="Dreadmaul Rock",body="Dreadmaul Rock ist eine Oger-Hochburg mit Höhlen und Stellungen im Burning Steppes. Die Anwesenheit von Führern und Gefangenen verbindet sie mit den Gefahren, denen Truppen ausgesetzt sind, die durch die Region reisen."},pt={title="Dreadmaul Rock",body="Dreadmaul Rock é um reduto ogro com cavernas e posições no Burning Steppes. A presença de líderes e cativos conecta-o com os perigos enfrentados pelas tropas que viajam pela região."},pl={title="Dreadmaul Rock",body="Dreadmaul Rock to warownia ogrów z jaskiniami i stanowiskami w Burning Steppes. Obecność przywódców i jeńców wiąże ją z zagrożeniami dla wojsk przemierzających region."},ru={title="Dreadmaul Rock",body="Dreadmaul Rock - это крепость Огров с пещерами и позициями в Burning Steppes. Присутствие вождей и пленных связывает его с опасностями, с которыми сталкиваются войска, путешествующие по этому региону."},references={["place:burning-steppes"]=true}},
    ["place:dreadmist-peak"] = {title="Cima Calígine",kind="Lugar",aliases={"Cima Calígine"},body="Cima Calígine es una montaña de Los Baldíos que alberga actividades de adoradores de demonios. Sus estanques y su altar muestran cómo un lugar elevado puede extender su influencia tanto por la magia como por el agua del entorno.",aliasQuestIDs={},en={title="Dreadmist Peak",aliases={"Dreadmist Peak"},body="Dreadmist Peak is a mountain in the Barrens hosting demon worshippers. Its pools and altar show how a high place can spread its influence through both magic and the surrounding waters.",aliasQuestIDs={}},fr={title="Dreadmist Peak",body="Dreadmist Peak est une montagne dans le Barrens hébergeant des adorateurs de démons. Ses piscines et son autel montrent comment un haut lieu peut répandre son influence à la fois par la magie et les eaux environnantes."},de={title="Dreadmist Peak",body="Dreadmist Peak ist ein Berg im Barrens, der Dämonenanbetende Gläubige beherbergt. Seine Becken und sein Altar zeigen, wie ein hoher Ort seinen Einfluss sowohl durch Magie als auch durch die umgebenden Gewässer ausbreiten kann."},pt={title="Dreadmist Peak",body="Dreadmist Peak é uma montanha no Barrens que hospeda adoradores de demônios. Suas piscinas e altar mostram como um lugar alto pode espalhar sua influência através da magia e das águas circundantes."},pl={title="Dreadmist Peak",body="Dreadmist Peak to góra w regionie Barrens zamieszkana przez czcicieli demonów. Sadzawki i ołtarz pokazują, jak wysoko położone miejsce może szerzyć wpływ poprzez magię oraz okoliczne wody."},ru={title="Dreadmist Peak",body="Dreadmist Peak - это гора в Barrens, где живут поклонники демонов. Ее бассейны и алтарь показывают, как высокое место может распространять свое влияние как через магию, так и через окружающие воды."},references={["place:the-barrens"]=true}},
    ["place:dun-baldar"] = {title="Dun Baldar",kind="Lugar",aliases={"Dun Baldar"},body="Dun Baldar es la base de Vanndar Pico Tormenta en el norte del Valle de Alterac. Su situación la convierte en un centro del avance y la resistencia de las fuerzas de la Alianza.",aliasQuestIDs={},en={title="Dun Baldar",aliases={"Dun Baldar"},body="Dun Baldar is Vanndar Stormpike's base in northern Alterac Valley. Its position makes it a center for the advance and resistance of Alliance forces.",aliasQuestIDs={}},fr={title="Dun Baldar",body="Dun Baldar est la base de Vanndar Stormpike dans le nord Alterac Valley. Sa position en fait un centre pour l'avance et la résistance des forces Alliance."},de={title="Dun Baldar",body="Dun Baldar ist der Stützpunkt von Vanndar Stormpike im Norden von Alterac Valley. Seine Lage macht ihn zu einem Zentrum für den Vormarsch und den Widerstand der Streitkräfte der Alliance."},pt={title="Dun Baldar",body="Dun Baldar é a base da Vanndar Stormpike no norte de Alterac Valley. Sua posição o torna um centro para o avanço e resistência das forças Alliance."},pl={title="Dun Baldar",body="Dun Baldar jest bazą Vanndar Stormpike w północnym Alterac Valley. Jego położenie czyni je ośrodkiem natarcia i oporu sił Alliance."},ru={title="Dun Baldar",body="Dun Baldar - база Vanndar Stormpike на севере Alterac Valley. Его положение делает его центром для продвижения и сопротивления сил Alliance."},references={["npc:vanndar-stormpike"]=true,["organization:alliance"]=true,["organization:stormpike-expedition"]=true,["place:alterac-mountains"]=true,["place:alterac-valley"]=true}},
    ["place:dun-garok"] = {title="Dun Garok",kind="Lugar",aliases={"Dun Garok"},body="Dun Garok es un enclave de las Laderas de Trabalomas rodeado por alturas de valor estratégico. Sus alrededores forman parte de las rutas y puntos de vigilancia utilizados por las fuerzas que actúan en la región.",aliasQuestIDs={},en={title="Dun Garok",aliases={"Dun Garok"},body="Dun Garok is a Hillsbrad Foothills enclave surrounded by strategically important heights. Its surroundings form part of the routes and lookout points used by forces operating in the region.",aliasQuestIDs={}},fr={title="Dun Garok",body="Dun Garok est une enclave Hillsbrad Foothills entourée de hauteurs stratégiquement importantes. Ses environs font partie des routes et des points de vue utilisés par les forces opérant dans la région."},de={title="Dun Garok",body="Dun Garok ist eine Hillsbrad Foothills-Enklave, die von strategisch wichtigen Höhen umgeben ist. Seine Umgebung ist Teil der Routen und Aussichtspunkte, die von den in der Region operierenden Streitkräften genutzt werden."},pt={title="Dun Garok",body="Dun Garok é um enclave Hillsbrad Foothills cercado por alturas estrategicamente importantes. Seus arredores fazem parte das rotas e pontos de observação usados pelas forças que operam na região."},pl={title="Dun Garok",body="Dun Garok to enklawa w Hillsbrad Foothills otoczona strategicznie ważnymi wzniesieniami. Okolica stanowi część szlaków i punktów obserwacyjnych wykorzystywanych przez działające w regionie siły."},ru={title="Dun Garok",body="Dun Garok - это анклав Hillsbrad Foothills, окруженный стратегически важными высотами. Его окрестности являются частью маршрутов и наблюдательных пунктов, используемых силами, действующими в регионе."},references={["place:hillsbrad-foothills"]=true}},
    ["place:dun-modr"] = {title="Dun Modr",kind="Lugar",aliases={"Dun Modr"},body="Dun Modr es un asentamiento de los Humedales situado junto a las rutas del norte. Su nombre aparece como referencia para viajeros y para quienes organizan actividades en la región pantanosa.",aliasQuestIDs={},en={title="Dun Modr",aliases={"Dun Modr"},body="Dun Modr is a Wetlands settlement beside the northern routes. Its name serves as a landmark for travelers and for people organizing activities in the marshy region.",aliasQuestIDs={}},fr={title="Dun Modr",body="Dun Modr est une colonie Wetlands à côté des routes du nord. Son nom sert de repère pour les voyageurs et pour les personnes organisant des activités dans la région marécageuse."},de={title="Dun Modr",body="Dun Modr ist eine Wetlands-Siedlung neben den nördlichen Routen. Sein Name dient als Wahrzeichen für Reisende und für Menschen, die Aktivitäten in der sumpfigen Region organisieren."},pt={title="Dun Modr",body="Dun Modr é um assentamento Wetlands ao lado das rotas do norte. Seu nome serve como um marco para os viajantes e para as pessoas que organizam atividades na região pantanosa."},pl={title="Dun Modr",body="Dun Modr to osada w Wetlands położona przy północnych szlakach. Jej nazwa służy za punkt orientacyjny podróżnym i osobom organizującym działania na podmokłych terenach."},ru={title="Dun Modr",body="Dun Modr - это поселение Wetlands рядом с северными маршрутами. Его название служит ориентиром для путешественников и людей, организующих мероприятия в болотистом регионе."},references={["place:wetlands"]=true}},
    ["place:dun-morogh"] = {title="Dun Morogh",kind="Lugar",aliases={"Dun Morogh"},body="Dun Morogh es la región montañosa y nevada donde los enanos mantienen poblados, talleres y rutas de abastecimiento. Los ataques de troggs y otras amenazas obligan a vigilar tanto los pasos como las instalaciones cercanas a Forjaz.",aliasQuestIDs={},en={title="Dun Morogh",aliases={"Dun Morogh"},body="Dun Morogh is a snowy mountain region where dwarves maintain settlements, workshops and supply routes. Trogg attacks and other dangers require watchfulness over both the passes and the installations near Ironforge.",aliasQuestIDs={}},fr={title="Dun Morogh",body="Dun Morogh est une région de montagne enneigée où les nains entretiennent des colonies, des ateliers et des routes d'approvisionnement. Les attaques Trogg et autres dangers nécessitent une vigilance sur les passes et les installations à proximité de Ironforge."},de={title="Dun Morogh",body="Dun Morogh ist eine verschneite Bergregion, wo Zwerge Siedlungen, Werkstätten und Versorgungsrouten unterhalten. Trogg Angriffe und andere Gefahren erfordern Wachsamkeit sowohl über die Pässe als auch über die Anlagen in der Nähe von Ironforge."},pt={title="Dun Morogh",body="Dun Morogh é uma região montanhosa nevada onde os anões mantêm assentamentos, oficinas e rotas de abastecimento. Ataques Trogg e outros perigos exigem vigilância sobre os passes e as instalações perto de Ironforge."},pl={title="Dun Morogh",body="Dun Morogh to śnieżny, górski region, w którym krasnoludy utrzymują osady, warsztaty i szlaki zaopatrzeniowe. Ataki troggów i inne zagrożenia wymagają czujności zarówno na przełęczach, jak i przy obiektach niedaleko Ironforge."},ru={title="Dun Morogh",body="Dun Morogh - это снежный горный регион, где карлики поддерживают поселения, мастерские и маршруты снабжения. Атаки Trogg и другие опасности требуют бдительности как над проходами, так и над установками возле Ironforge."},references={["place:ironforge"]=true}},
    ["place:durnholde-keep"] = {title="Castillo de Durnholde",kind="Lugar",aliases={"Castillo de Durnholde","Fortaleza de Dunholde"},body="El Castillo de Durnholde es una fortaleza de las Laderas de Trabalomas vinculada a la Hermandad. Sus muros ofrecen una base importante para quienes intentan controlar las actividades y los caminos de la región.",aliasQuestIDs={},en={title="Durnholde Keep",aliases={"Durnholde","Durnholde Keep"},body="Durnholde Keep is a Hillsbrad Foothills fortress associated with the Syndicate. Its walls provide an important base for those attempting to control the region’s activities and roads.",aliasQuestIDs={}},fr={title="Durnholde Keep",body="Durnholde Keep est une forteresse Hillsbrad Foothills associée au Syndicate. Ses murs constituent une base importante pour ceux qui tentent de contrôler les activités et les routes de la région."},de={title="Durnholde Keep",body="Durnholde Keep ist eine Hillsbrad Foothills-Festung, die mit dem Syndicate in Verbindung gebracht wird. Seine Mauern bieten eine wichtige Basis für diejenigen, die versuchen, die Aktivitäten und Straßen der Region zu kontrollieren."},pt={title="Durnholde Keep",body="Durnholde Keep é uma fortaleza Hillsbrad Foothills associada ao Syndicate. Suas paredes fornecem uma base importante para aqueles que tentam controlar as atividades e estradas da região."},pl={title="Durnholde Keep",body="Durnholde Keep to twierdza w Hillsbrad Foothills związana z Syndicate. Jej mury zapewniają ważną bazę osobom próbującym kontrolować działalność i drogi regionu."},ru={title="Durnholde Keep",body="Durnholde Keep - это крепость Hillsbrad Foothills, связанная с Syndicate. Его стены являются важной базой для тех, кто пытается контролировать деятельность и дороги региона."},references={["organization:syndicate"]=true,["place:hillsbrad-foothills"]=true}},
    ["place:durotar"] = {title="Durotar",kind="Lugar",aliases={"Durotar"},body="Durotar es una región árida de la costa oriental de Kalimdor y el nuevo hogar de los orcos de la Horda. Thrall le dio ese nombre en honor a su padre, Durotan. La tierra rojiza, las colinas rocosas y la escasez de recursos hacen que establecerse aquí exija una lucha constante.\n\nOrgrimmar se alza en el norte, mientras asentamientos como Cerrotajo y el Poblado Sen'jin sostienen la vida fuera de la ciudad. La región es tanto un refugio como un comienzo: un territorio donde los orcos y sus aliados buscan afianzar su independencia.",aliasQuestIDs={},en={title="Durotar",aliases={"Durotar"},body="Durotar is an arid region on Kalimdor’s eastern coast and the new home of the Horde’s orcs. Thrall named it in honor of his father, Durotan. Red earth, rocky hills and scarce resources make settlement a constant struggle.\n\nOrgrimmar stands in the north, while communities such as Razor Hill and Sen'jin Village support life outside the city. The region is both a refuge and a beginning: a land where the orcs and their allies seek to secure their independence.",aliasQuestIDs={}},fr={title="Durotar",body="Durotar est une région aride sur la côte est de Kalimdor et la nouvelle maison des orcs de la Horde. Thrall l'a nommé en l'honneur de son père, Durotan. La terre rouge, les collines rocheuses et les ressources rares font de la colonisation une lutte constante. Orgrimmar se trouve dans le nord, tandis que des communautés telles que Razor Hill et Sen'jin Village soutiennent la vie en dehors de la ville. La région est à la fois un refuge et un début: une terre où les orcs et leurs alliés cherchent à assurer leur indépendance."},de={title="Durotar",body="Durotar ist eine trockene Region an der Ostküste von Kalimdor und die neue Heimat der Horde 's Orks. Thrall nannte es zu Ehren seines Vaters Durotan. Rote Erde, felsige Hügel und knappe Ressourcen machen Siedlungen zu einem ständigen Kampf. Orgrimmar steht im Norden, während Gemeinden wie Razor Hill und Sen'jin Village das Leben außerhalb der Stadt unterstützen. Die Region ist Zufluchtsort und Anfang zugleich: ein Land, in dem die Orks und ihre Unabhängigkeit mit ihren Verbündeten zu sichern trachten."},pt={title="Durotar",body="Durotar é uma região árida na costa leste de Kalimdor e a nova casa dos orcs do Horde. Thrall nomeou-o em homenagem ao seu pai, Durotan. Terra vermelha, colinas rochosas e recursos escassos fazem do assentamento uma luta constante. Orgrimmar está no norte, enquanto comunidades como Razor Hill e Sen'jin Village apoiam a vida fora da cidade. A região é ao mesmo tempo um refúgio e um começo: uma terra onde os orcs e seus aliados buscam garantir sua independência."},pl={title="Durotar",body="Durotar to suchy region na wschodnim wybrzeżu kontynentu Kalimdor i nowy dom orków frakcji Horde. Thrall nadał mu nazwę na cześć swojego ojca, noszącego imię Durotan. Czerwona ziemia, skaliste wzgórza i skąpe zasoby czynią osadnictwo nieustanną walką. Na północy wznosi się Orgrimmar, a społeczności takie jak Razor Hill i Sen'jin Village wspierają życie poza miastem. Region jest zarazem schronieniem i początkiem: krainą, gdzie orkowie oraz ich sojusznicy próbują zabezpieczyć niezależność."},ru={title="Durotar",body="Durotar - это засушливый регион на восточном побережье Kalimdor  и новый дом орков Horde. Thrall назвал его в честь своего отца, Durotan. Красная земля, скалистые холмы и скудные ресурсы делают поселение постоянной борьбой. Orgrimmar находится на севере, в то время как сообщества, такие как Razor Hill и Sen'jin Village поддерживают жизнь за пределами города. Регион является и убежищем, и началом: землей, где орки и их союзники стремятся обеспечить свою независимость."},references={["organization:horde"]=true,["person:thrall"]=true,["place:kalimdor"]=true,["place:orgrimmar"]=true,["place:razor-hill"]=true,["place:senjin-village"]=true}},
    ["place:duskwood"] = {title="Bosque del Ocaso",kind="Lugar",aliases={"Bosque del Ocaso","Ocaso"},body="El Bosque del Ocaso es una región donde la oscuridad, los no muertos y otras criaturas dificultan la vida de los poblados humanos. Los habitantes de Villa Oscura dependen de una vigilancia constante para recorrer los caminos y conservar sus hogares.",aliasQuestIDs={},en={title="Duskwood",aliases={"Duskwood"},body="Duskwood is a region where darkness, undead and other creatures make life difficult for its human communities. Darkshire’s people depend on constant vigilance to travel the roads and hold on to their homes.",aliasQuestIDs={}},fr={title="Duskwood",body="Duskwood est une région où l'obscurité, les morts-vivants et d'autres créatures rendent la vie difficile pour ses communautés humaines. Les gens de Darkshire dépendent d’une vigilance constante pour parcourir les routes et s’accrocher à leurs maisons."},de={title="Duskwood",body="Duskwood ist eine Region, in der Dunkelheit, Untote und andere Kreaturen den menschlichen Gemeinschaften das Leben schwer machen. Die Menschen in Darkshire sind auf ständige Wachsamkeit angewiesen, wenn es darum geht, die Straßen zu überqueren und sich in ihren Häusern zu halten."},pt={title="Duskwood",body="Duskwood é uma região onde a escuridão, mortos-vivos e outras criaturas dificultam a vida de suas comunidades humanas. As pessoas do Darkshire dependem da vigilância constante para viajar pelas estradas e manter suas casas."},pl={title="Duskwood",body="Duskwood to region, w którym mrok, nieumarli i inne stworzenia utrudniają życie ludzkim społecznościom. Mieszkańcy Darkshire muszą stale czuwać, by podróżować drogami i zachować swoje domy."},ru={title="Duskwood",body="Duskwood - это регион, где тьма, неживые мертвецы и другие существа затрудняют жизнь человеческой общины. Люди Darkshire  зависят от постоянной бдительности, чтобы путешествовать по дорогам и держаться за свои дома."},references={["place:darkshire"]=true}},
    ["place:dustwallow-marsh"] = {title="Marjal Revolcafango",kind="Lugar",aliases={"Marjal Revolcafango"},body="Marjal Revolcafango es una región pantanosa de Kalimdor. Sus rutas difíciles, criaturas y asentamientos enfrentados convierten la exploración en una tarea incierta para las comunidades de la costa y del interior.",aliasQuestIDs={},en={title="Dustwallow Marsh",aliases={"Dustwallow Marsh"},body="Dustwallow Marsh is a swampy region of Kalimdor. Difficult roads, dangerous creatures and rival settlements make exploration uncertain for communities on the coast and inland.",aliasQuestIDs={}},fr={title="Dustwallow Marsh",body="Dustwallow Marsh est une région marécageuse de Kalimdor. Les routes difficiles, les créatures dangereuses et les colonies rivales rendent l'exploration incertaine pour les communautés de la côte et de l'intérieur des terres."},de={title="Dustwallow Marsh",body="Dustwallow Marsh ist eine sumpfige Gegend von Kalimdor. Schwierige Straßen, gefährliche Lebewesen und rivalisierende Siedlungen machen die Erkundung für Gemeinden an der Küste und im Landesinneren unsicher."},pt={title="Dustwallow Marsh",body="Dustwallow Marsh é uma região pantanosa do Kalimdor. Estradas difíceis, criaturas perigosas e assentamentos rivais tornam a exploração incerta para as comunidades na costa e no interior."},pl={title="Dustwallow Marsh",body="Dustwallow Marsh to bagnisty region kontynentu Kalimdor. Trudne drogi, niebezpieczne stworzenia i rywalizujące osady czynią wyprawy niepewnym przedsięwzięciem dla społeczności wybrzeża oraz głębi lądu."},ru={title="Dustwallow Marsh",body="Dustwallow Marsh - это болотистая область Kalimdor. Труднопроходимые дороги, опасные существа и соперничающие поселения делают исследование неопределенным для сообществ на побережье и вглубь страны."},references={["place:kalimdor"]=true}},
    ["place:eastern-kingdoms"] = {title="Reinos del Este",kind="Lugar",aliases={"Los Reinos del Este","Reinos del Este"},body="Los Reinos del Este forman una gran región de Azeroth. En sus tierras se encuentran Lordaeron y Ventormenta, con pueblos y rutas compartidos o disputados por la Horda y la Alianza.",aliasQuestIDs={},en={title="Eastern Kingdoms",aliases={"Eastern Kingdoms","The Eastern Kingdoms"},body="The Eastern Kingdoms form a major region of Azeroth. Their lands include Lordaeron and Stormwind, with peoples and routes shared or contested by the Horde and Alliance.",aliasQuestIDs={}},fr={title="Eastern Kingdoms",body="The Eastern Kingdoms forment une vaste région d'Azeroth. Leurs terres comprennent Lordaeron et Stormwind, avec des peuples et des routes partagés ou disputés par la Horde et l'Alliance."},de={title="Eastern Kingdoms",body="The Eastern Kingdoms bildet eine wichtige Region von Azeroth. Zu ihren Ländern gehören Lordaeron und Stormwind, mit Völkern und Routen, die von den Horde und Alliance geteilt oder umkämpft wurden."},pt={title="Eastern Kingdoms",body="The Eastern Kingdoms formam uma grande região de Azeroth. Suas terras incluem Lordaeron e Stormwind, com povos e rotas compartilhados ou disputados pela Horde e pela Alliance."},pl={title="Eastern Kingdoms",body="The Eastern Kingdoms stanowią wielki region Azeroth. Ich ziemie obejmują Lordaeron i Stormwind, a ludy oraz szlaki są wspólne lub sporne dla sojuszy znanych jako the Horde i Alliance."},ru={title="Eastern Kingdoms",body="The Eastern Kingdoms образуют главную область Azeroth. Их земли включают Lordaeron и Stormwind, с народами и маршрутами, разделяемыми или оспариваемыми Horde и Alliance."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:azeroth"]=true,["place:lordaeron"]=true,["place:stormwind"]=true}},
    ["place:eastern-plaguelands"] = {title="Tierras de la Peste del Este",kind="Lugar",aliases={"Tierras de la Peste del Este"},body="Las Tierras de la Peste del Este son una región azotada por la corrupción y las criaturas de la Plaga. La Capilla de la Esperanza de la Luz reúne a quienes intentan resistir esa amenaza.",aliasQuestIDs={},en={title="Eastern Plaguelands",aliases={"Eastern Plaguelands"},body="Eastern Plaguelands is a region afflicted by corruption and Scourge creatures. Light's Hope Chapel gathers those trying to resist that threat.",aliasQuestIDs={}},fr={title="Eastern Plaguelands",body="Eastern Plaguelands est une région touchée par la corruption et les créatures Scourge. Light's Hope Chapel rassemble ceux qui tentent de résister à cette menace."},de={title="Eastern Plaguelands",body="Eastern Plaguelands ist eine Region, die von Korruption und Scourge Kreaturen heimgesucht wird. Light's Hope Chapel sammelt diejenigen, die versuchen, dieser Bedrohung zu widerstehen."},pt={title="Eastern Plaguelands",body="Eastern Plaguelands é uma região afetada pela corrupção e criaturas Scourge. Light's Hope Chapel reúne aqueles que tentam resistir a essa ameaça."},pl={title="Eastern Plaguelands",body="Eastern Plaguelands jest krainą dotkniętą skażeniem i obecnością stworzeń Scourge. Light's Hope Chapel gromadzi tych, którzy próbują stawić opór temu zagrożeniu."},ru={title="Eastern Plaguelands",body="Eastern Plaguelands - это регион, пораженный порчей и созданиями Scourge. Light's Hope Chapel собирает тех, кто пытается противостоять этой угрозе."},references={["concept:holy-light"]=true,["organization:scourge"]=true,["place:lights-hope-chapel"]=true,["place:plaguelands"]=true}},
    ["place:eastvale-logging-camp"] = {title="Aserradero de la Vega del Este",kind="Lugar",aliases={"Aserradero de la Vega del Este","Vega del Este"},body="El Aserradero de la Vega del Este es una comunidad de trabajo en el extremo oriental de Elwynn. La tala y el transporte de madera comparten espacio con granjas y caminos que necesitan protección frente a los peligros del bosque.",aliasQuestIDs={},en={title="Eastvale Logging Camp",aliases={"Eastvale","Eastvale Logging Camp"},body="Eastvale Logging Camp is a working community in eastern Elwynn. Logging and timber transport share the district with farms and roads that need protection from the forest’s dangers.",aliasQuestIDs={}},fr={title="Eastvale Logging Camp",body="Eastvale Logging Camp est une communauté de travail dans l'est de Elwynn. L’exploitation forestière et le transport du bois partagent le quartier avec des fermes et des routes qui ont besoin d’être protégées des dangers de la forêt."},de={title="Eastvale Logging Camp",body="Eastvale Logging Camp ist eine Arbeitsgemeinschaft im östlichen Elwynn. Holzeinschlag und Holztransport teilen sich den Landkreis mit Höfen und Straßen, die vor Waldgefahren werden müssen."},pt={title="Eastvale Logging Camp",body="Eastvale Logging Camp é uma comunidade de trabalho no leste de Elwynn. O transporte de madeira e madeira compartilha o distrito com fazendas e estradas que precisam de proteção contra os perigos da floresta."},pl={title="Eastvale Logging Camp",body="Eastvale Logging Camp to osada robotnicza we wschodniej części Elwynn. Wyrąb i transport drewna współistnieją tu z gospodarstwami oraz drogami wymagającymi ochrony przed niebezpieczeństwami lasu."},ru={title="Eastvale Logging Camp",body="Eastvale Logging Camp - это рабочее сообщество в восточной части Elwynn. Добыча и транспортировка древесины разделяют район с фермами и дорогами, которые нуждаются в защите от опасностей леса."},references={["place:elwynn-forest"]=true}},
    ["place:echo-isles"] = {title="Islas del Eco",kind="Lugar",aliases={"Islas del Eco"},body="Las Islas del Eco se encuentran frente a la costa de Durotar y están ligadas a la historia de los Lanza Negra. Sus playas y poblados son un punto de conflicto para los trols que intentan mantener un hogar en la región.",aliasQuestIDs={},en={title="Echo Isles",aliases={"Echo Isles"},body="The Echo Isles lie off the coast of Durotar and are closely tied to Darkspear history. Their beaches and villages are a point of conflict for trolls trying to maintain a home in the region.",aliasQuestIDs={}},fr={title="Echo Isles",body="Les Echo Isles se trouvent au large des côtes de Durotar et sont étroitement liés à l'histoire de Darkspear. Leurs plages et villages sont un point de conflit pour les trolls qui tentent de maintenir une maison dans la région."},de={title="Echo Isles",body="Die Echo Isles liegen vor der Küste von Durotar und sind eng mit Darkspear \"Geschichte verbunden. Ihre Strände und Dörfer sind ein Konfliktherd für Trolle, die versuchen, in der Region ein Zuhause zu erhalten."},pt={title="Echo Isles",body="O Echo Isles situa-se ao largo da costa do Durotar e está intimamente ligado à história do Darkspear. Suas praias e aldeias são um ponto de conflito para os trolls que tentam manter uma casa na região."},pl={title="Echo Isles",body="Echo Isles leżą u wybrzeży Durotar i są ściśle związane z historią plemienia Darkspear. Plaże i wioski tych wysp są przedmiotem walk trolli starających się zachować dom w tym regionie."},ru={title="Echo Isles",body="Echo Isles лежат у побережья Durotar и тесно связаны с историей Darkspear. Их пляжи и деревни являются точкой конфликта для троллей, пытающихся сохранить дом в регионе."},references={["organization:darkspear-tribe"]=true,["place:durotar"]=true}},
    ["place:eldarath"] = {title="Ruinas de Eldarath",kind="Lugar",aliases={"Eldarath","Ruinas de Eldarath"},body="Las Ruinas de Eldarath conservan restos de la antigua civilización de los Altonato en Azshara. Tablillas y otros vestigios atraen a quienes buscan conocimientos o riqueza entre los peligros de la región.",aliasQuestIDs={},en={title="Ruins of Eldarath",aliases={"Eldarath","Ruins of Eldarath"},body="The Ruins of Eldarath preserve remains of the ancient Highborne civilization in Azshara. Tablets and other relics attract those seeking knowledge or wealth amid the region’s dangers.",aliasQuestIDs={}},fr={title="Ruins of Eldarath",body="Les Ruins of Eldarath préservent les vestiges de l'ancienne civilisation Highborne dans Azshara. Les tablettes et autres reliques attirent ceux qui cherchent la connaissance ou la richesse au milieu des dangers de la région."},de={title="Ruins of Eldarath",body="Die Ruins of Eldarath bewahren Überreste der alten Zivilisation der Highborne in Azshara. Tafeln und andere Relikte ziehen jene an, die inmitten der Gefahren der Region nach Wissen oder Reichtum suchen."},pt={title="Ruins of Eldarath",body="O Ruins of Eldarath preservar restos da antiga civilização Highborne em Azshara. Tablets e outras relíquias atraem aqueles que buscam conhecimento ou riqueza em meio aos perigos da região."},pl={title="Ruins of Eldarath",body="Ruins of Eldarath przechowują pozostałości pradawnej cywilizacji Highborne w regionie Azshara. Tablice i inne relikty przyciągają poszukiwaczy wiedzy lub bogactwa pośród niebezpieczeństw tych ziem."},ru={title="Ruins of Eldarath",body="Заповедник Ruins of Eldarath сохранил останки древней цивилизации Highborne в Azshara. Планшеты и другие реликвии привлекают тех, кто ищет знания или богатство среди опасностей региона."},references={["organization:highborne"]=true,["place:azshara"]=true}},
    ["place:elwynn-forest"] = {title="Bosque de Elwynn",kind="Lugar",aliases={"Bosque de Elwynn","Elwynn"},body="El Bosque de Elwynn reúne granjas, caminos y pequeños poblados bajo la protección de Ventormenta. Sus minas y tierras de cultivo sostienen la vida cotidiana, aunque kóbolds, gnolls y bandidos dificultan mantener seguros sus límites.",aliasQuestIDs={},en={title="Elwynn Forest",aliases={"Elwynn","Elwynn Forest"},body="Elwynn Forest is a countryside of farms, roads and small settlements under Stormwind’s protection. Its mines and fields support everyday life, although kobolds, gnolls and bandits make its borders difficult to secure.",aliasQuestIDs={}},fr={title="Elwynn Forest",body="Elwynn Forest est une campagne de fermes, de routes et de petits villages sous la protection de Stormwind. Ses mines et ses champs soutiennent la vie quotidienne, bien que les kobolds, les gnolls et les bandits rendent ses frontières difficiles à sécuriser."},de={title="Elwynn Forest",body="Elwynn Forest ist eine Landschaft mit Höfen, Straßen und kleinen Siedlungen unter dem Schutz von Stormwind. Seine Minen und Felder unterstützen den Alltag, obwohl Kobolds, Gnolls und Banditen seine Grenzen schwer zu sichern machen."},pt={title="Elwynn Forest",body="Elwynn Forest é um campo de fazendas, estradas e pequenos assentamentos sob a proteção de Stormwind. Suas minas e campos suportam a vida cotidiana, embora kobolds, gnolls e bandidos tornem suas fronteiras difíceis de proteger."},pl={title="Elwynn Forest",body="Elwynn Forest to kraina gospodarstw, dróg i niewielkich osad pozostająca pod ochroną Stormwind. Kopalnie i pola podtrzymują codzienne życie, choć koboldy, gnolle i bandyci utrudniają zabezpieczenie jej granic."},ru={title="Elwynn Forest",body="Elwynn Forest - это сельская местность с фермами, дорогами и небольшими поселениями под защитой Stormwind s. Его шахты и поля поддерживают повседневную жизнь, хотя кобольды, гнолы и бандиты затрудняют обеспечение безопасности его границ."},references={["place:stormwind"]=true}},
    ["place:equinex-monolith"] = {title="Monolito de Equinex",kind="Lugar",aliases={"Monolito de Equinex"},body="El Monolito de Equinex es un monumento de las Ruinas de Viento Azabache en Feralas. Su cierre responde a un báculo imbuido con las esencias de las llamas del lugar, señal de una protección mágica vinculada al santuario.",aliasQuestIDs={},en={title="Equinex Monolith",aliases={"Equinex Monolith"},body="The Equinex Monolith is a monument in Feralas’s Ruins of Ravenwind. Its seal responds to a stave infused with the essences of the site’s flames, revealing magical protection tied to the sanctuary.",aliasQuestIDs={}},fr={title="Equinex Monolith",body="Le Equinex Monolith est un monument dans les ruines Feralas de Ravenwind. Son sceau répond à une baguette magique infusée des essences des flammes du site, révélant une protection magique liée au sanctuaire."},de={title="Equinex Monolith",body="Der Equinex Monolith ist ein Denkmal in Feralas 's Ruinen von Ravenwind. Seine Dichtung reagiert auf einen magischen Stab, der mit den Essenzen der Flammen des Ortes durchdrungen ist und offenbart magischen Schutz, der an das Heiligtum gebunden ist."},pt={title="Equinex Monolith",body="O Equinex Monolith é um monumento nas Ruínas do Feralas de Ravenwind. Seu selo responde a uma haste mágica infundida com as essências das chamas do local, revelando proteção mágica ligada ao santuário."},pl={title="Equinex Monolith",body="Equinex Monolith to monument w ruinach Ravenwind w Feralas. Pieczęć reaguje na kostur nasycony esencjami miejscowych płomieni, ujawniając magiczną ochronę związaną z sanktuarium."},ru={title="Equinex Monolith",body="Equinex Monolith — памятник в руинах Ravenwind на территории Feralas. Его печать отвечает на палку, в которой пропитаны сущности пламени места, раскрывая магическую защиту, связанную с святыней."},references={["place:feralas"]=true}},
    ["place:everlook"] = {title="Vista Eterna",kind="Lugar",aliases={"Vista Eterna"},body="Vista Eterna es un poblado goblin de Cuna del Invierno. Sus comerciantes e inventores ofrecen apoyo a los viajeros y oportunidades de negocio entre la nieve, las montañas y las criaturas de la región.",aliasQuestIDs={},en={title="Everlook",aliases={"Everlook"},body="Everlook is a goblin town in Winterspring. Its traders and inventors offer travelers support and business opportunities amid the region’s snow, mountains and wildlife.",aliasQuestIDs={}},fr={title="Everlook",body="Everlook est une ville gobelin dans Winterspring. Ses commerçants et inventeurs offrent aux voyageurs un soutien et des opportunités d'affaires au milieu de la neige, des montagnes et de la faune de la région."},de={title="Everlook",body="Everlook ist eine Koboldstadt in Winterspring. Seine Händler und Erfinder bieten Reisenden Unterstützung und Geschäftsmöglichkeiten inmitten im Schnee, in den Bergen und in der Natur der Region."},pt={title="Everlook",body="Everlook é uma cidade goblin em Winterspring. Seus comerciantes e inventores oferecem aos viajantes suporte e oportunidades de negócios em meio à neve, montanhas e vida selvagem da região."},pl={title="Everlook",body="Everlook to goblińskie miasto w Winterspring. Kupcy i wynalazcy oferują podróżnym wsparcie oraz okazje do interesów pośród śniegów, gór i dzikiej przyrody regionu."},ru={title="Everlook",body="Everlook - город гоблинов в Winterspring. Его торговцы и изобретатели предлагают путешественникам поддержку и возможности для бизнеса среди снега, гор и дикой природы региона."},references={["place:winterspring"]=true}},
    ["place:falaath-village"] = {title="Poblado Falaath",kind="Lugar",aliases={"Falaath","Poblado Falaath"},body="El Poblado Falaath se encuentra en las Tierras Altas de Shen'dar y alberga seguidores de Al'Akir. El Culto de Al'Aketh lo utiliza como punto de reunión y recepción de reclutas. Entre los edificios mencionados por sus habitantes hay una posada en el norte del poblado.",aliasQuestIDs={},en={title="Falaath Village",aliases={"Falaath","Falaath Village"},body="Falaath Village stands in the Shen'dar Highlands and is home to followers of Al'Akir. The Al'Aketh Cult uses it as a gathering place and a point for receiving recruits. Its buildings include an inn on the northern side of the settlement.",aliasQuestIDs={}},fr={title="Falaath Village",body="Falaath Village se trouve dans le Shen'dar Highlands et abrite les adeptes de Al'Akir. Le Al'Aketh Cult l’utilise comme lieu de rassemblement et de réception des recrues. Ses bâtiments comprennent une auberge sur le côté nord de la colonie."},de={title="Falaath Village",body="Falaath Village steht im Shen'dar Highlands und beherbergt Anhänger von Al'Akir. Die Al'Aketh Cult nutzen sie als Sammelplatz und Anlaufstelle für Rekruten. Zu seinen Gebäuden gehört ein Gasthof auf der Nordseite der Siedlung."},pt={title="Falaath Village",body="Falaath Village está no Shen'dar Highlands e é o lar de seguidores de Al'Akir. O Al'Aketh Cult usa-o como um local de encontro e um ponto para receber recrutas. Seus edifícios incluem uma pousada no lado norte do assentamento."},pl={title="Falaath Village",body="Falaath Village stoi w Shen'dar Highlands i jest domem wyznawców Al'Akir. The Al'Aketh Cult używa jej jako miejsca zgromadzeń i przyjmowania rekrutów. Wśród budynków znajduje się gospoda po północnej stronie osady."},ru={title="Falaath Village",body="Falaath Village - это Shen'dar Highlands и является домом для последователей Al'Akir. Al'Aketh Cult использует его как место сбора и пункт приема новобранцев. Среди зданий - гостиница на северной стороне поселения."},references={["npc:alakir"]=true,["organization:al-aketh"]=true,["place:shendar"]=true,["place:shendar-highlands"]=true}},
    ["place:faldirs-cove"] = {title="Cala de Faldir",kind="Lugar",aliases={"Cala de Faldir","Faldir"},body="La Cala de Faldir es un refugio costero de Arathi relacionado con marinos y expediciones submarinas. Los tesoros del fondo y la presencia de naga hacen que la exploración de sus aguas requiera tanto equipo como protección.",aliasQuestIDs={},en={title="Faldir's Cove",aliases={"Faldir","Faldir's Cove","Faldir’s Cove"},body="Faldir’s Cove is an Arathi coastal refuge associated with sailors and underwater expeditions. Treasures on the seabed and the presence of naga mean exploring its waters requires both equipment and protection.",aliasQuestIDs={}},fr={title="Faldir's Cove",body="Faldir’s Cove est un refuge côtier Arathi associé aux marins et aux expéditions sous-marines. Les trésors sur le fond marin et la présence de naga signifient explorer ses eaux nécessite à la fois l'équipement et la protection."},de={title="Faldir's Cove",body="Faldir’s Cove ist ein Zufluchtsort für Segler und Unterwasserexpeditionen an der Arathi Küsten. Schätze auf dem Meeresboden und die Anwesenheit von Naga bedeuten, dass die Erforschung seiner Gewässer sowohl Ausrüstung als auch Schutz erfordert."},pt={title="Faldir's Cove",body="Faldir’s Cove é um refúgio costeiro Arathi associado a marinheiros e expedições subaquáticas. Tesouros no fundo do mar e a presença de naga significa explorar suas águas requer equipamentos e proteção."},pl={title="Faldir's Cove",body="Faldir’s Cove to nadmorskie schronienie w Arathi związane z żeglarzami i podwodnymi ekspedycjami. Skarby na dnie oraz obecność nag sprawiają, że badanie tych wód wymaga wyposażenia i ochrony."},ru={title="Faldir's Cove",body="Faldir’s Cove - это прибрежное убежище Arathi, связанное с моряками и подводными экспедициями. Сокровища на морском дне и наличие наги означают, что исследование его вод требует как оборудования, так и защиты."},references={["place:arathi-highlands"]=true}},
    ["place:fallow-sanctuary"] = {title="Retiro Fangoso",kind="Lugar",aliases={"Retiro Fangoso"},body="Retiro Fangoso es un enclave de los Perdidos en el Pantano de las Penas. La violencia de sus habitantes contrasta con los esfuerzos de otras comunidades de su linaje por conservar la razón y una vida organizada.",aliasQuestIDs={},en={title="Fallow Sanctuary",aliases={"Fallow Sanctuary"},body="Fallow Sanctuary is a Lost One enclave in the Swamp of Sorrows. Its inhabitants’ violence contrasts with efforts by other communities of their lineage to preserve sanity and an orderly life.",aliasQuestIDs={}},fr={title="Fallow Sanctuary",body="Fallow Sanctuary est une enclave Lost One dans le Swamp of Sorrows. La violence de ses habitants contraste avec les efforts déployés par d’autres communautés de leur lignée pour préserver la santé mentale et une vie ordonnée."},de={title="Fallow Sanctuary",body="Fallow Sanctuary ist eine Enklave von Lost One im Swamp of Sorrows. Die Gewalt seiner Bewohner steht im Gegensatz zu den Bemühungen anderer Gemeinschaften ihrer Abstammung, Gesundheit und ein geordnetes Leben zu bewahren."},pt={title="Fallow Sanctuary",body="Fallow Sanctuary é um enclave Lost One no Swamp of Sorrows. A violência de seus habitantes contrasta com os esforços de outras comunidades de sua linhagem para preservar a sanidade e uma vida ordenada."},pl={title="Fallow Sanctuary",body="Fallow Sanctuary to enklawa Lost One w Swamp of Sorrows. Przemoc mieszkańców kontrastuje ze staraniami innych społeczności tego samego pochodzenia o zachowanie rozsądku i uporządkowanego życia."},ru={title="Fallow Sanctuary",body="Fallow Sanctuary - это анклав Lost One в Swamp of Sorrows. Насилие его жителей контрастирует с усилиями других общин их рода сохранить здравомыслие и упорядоченную жизнь."},references={["place:swamp-of-sorrows"]=true}},
    ["place:faols-rest"] = {title="Tumba de Faol",kind="Lugar",aliases={"Tumba de Faol"},body="La Tumba de Faol es un lugar funerario de Tirisfal. Sus alrededores marcan una zona de actividad de la Cruzada Escarlata al norte de los asentamientos de los Renegados.",aliasQuestIDs={},en={title="Faol's Rest",aliases={"Faol's Rest","Faol’s Rest"},body="Faol's Rest is a burial site in Tirisfal. Its surroundings mark an area of Scarlet Crusade activity north of Forsaken settlements.",aliasQuestIDs={}},fr={title="Faol's Rest",body="Faol's Rest est un site funéraire dans Tirisfal. Ses environs marquent une zone d'activité Scarlet Crusade au nord des colonies Forsaken."},de={title="Faol's Rest",body="Faol's Rest ist eine Begräbnisstätte in Tirisfal. Seine Umgebung markiert ein Gebiet mit Scarlet Crusade-Aktivitäten nördlich der Forsaken-Siedlungen."},pt={title="Faol's Rest",body="Faol's Rest é um local de enterro em Tirisfal. Seus arredores marcam uma área da atividade Scarlet Crusade ao norte dos assentamentos Forsaken."},pl={title="Faol's Rest",body="Faol's Rest jest miejscem pochówku w Tirisfal. Jego okolice wyznaczają obszar działań Scarlet Crusade na północ od osad Forsaken."},ru={title="Faol's Rest",body="Faol's Rest - это место захоронения в Tirisfal. Его окрестности обозначают зону активности Scarlet Crusade к северу от поселений Forsaken."},references={["organization:forsaken"]=true,["organization:scarlet-crusade"]=true,["place:tirisfal-glades"]=true}},
    ["place:fargodeep-mine"] = {title="Mina Abisal",kind="Lugar",aliases={"Mina Abisal"},body="La Mina Abisal es una explotación minera situada al sur de Villadorada. La presencia de kóbolds convierte sus galerías en un problema para la seguridad y el aprovechamiento de los recursos de Elwynn.",aliasQuestIDs={},en={title="Fargodeep Mine",aliases={"Fargodeep","Fargodeep Mine"},body="Fargodeep Mine is a mine south of Goldshire. Kobold occupation makes its tunnels a problem for both local security and the use of Elwynn’s resources.",aliasQuestIDs={}},fr={title="Fargodeep Mine",body="Fargodeep Mine est une mine au sud de Goldshire. L'occupation Kobold rend ses tunnels un problème à la fois pour la sécurité locale et l'utilisation des ressources de Elwynn."},de={title="Fargodeep Mine",body="Fargodeep Mine ist eine Mine südlich von Goldshire. Kobold Okkupation macht seine Tunnel sowohl für die lokale Sicherheit als auch für den Einsatz von Elwynn 's Ressourcen zu einem Problem."},pt={title="Fargodeep Mine",body="Fargodeep Mine é uma mina ao sul de Goldshire. A ocupação Kobold torna seus túneis um problema tanto para a segurança local quanto para o uso dos recursos da Elwynn."},pl={title="Fargodeep Mine",body="Fargodeep Mine to kopalnia na południe od Goldshire. Okupacja przez koboldy sprawia, że jej tunele stanowią problem zarówno dla miejscowego bezpieczeństwa, jak i wykorzystania zasobów Elwynn."},ru={title="Fargodeep Mine",body="Fargodeep Mine — шахта к югу от Goldshire. Кобольды, занявшие её туннели, угрожают безопасности окрестностей и мешают пользоваться ресурсами Elwynn."},references={["place:elwynn-forest"]=true,["place:goldshire"]=true}},
    ["place:farstrider-lodge"] = {title="Cabaña del Errante",kind="Lugar",aliases={"Cabaña del Errante"},body="La Cabaña del Errante es un punto de encuentro para cazadores en Loch Modan. Allí se intercambian historias, se organizan pruebas de habilidad y se valoran los trofeos de las bestias de la región.",aliasQuestIDs={},en={title="Farstrider Lodge",aliases={"Farstrider","Farstrider Lodge"},body="Farstrider Lodge is a gathering place for hunters in Loch Modan. Stories are exchanged, tests of skill arranged and trophies from the region’s beasts judged there.",aliasQuestIDs={}},fr={title="Farstrider Lodge",body="Farstrider Lodge est un lieu de rassemblement pour les chasseurs dans Loch Modan. Des histoires sont échangées, des tests d’habileté sont organisés et des trophées des bêtes de la région y sont jugés."},de={title="Farstrider Lodge",body="Farstrider Lodge ist ein Sammelplatz für Jäger in Loch Modan. Geschichten werden ausgetauscht, Geschicklichkeitstests veranstaltet und Trophäen der Tiere der Region bewertet."},pt={title="Farstrider Lodge",body="Farstrider Lodge é um local de encontro para caçadores em Loch Modan. Histórias são trocadas, testes de habilidade arranjados e troféus das bestas da região são julgados lá."},pl={title="Farstrider Lodge",body="Farstrider Lodge jest miejscem spotkań myśliwych w Loch Modan. Wymienia się tu opowieści, urządza próby umiejętności i ocenia trofea zdobyte na miejscowych bestiach."},ru={title="Farstrider Lodge",body="Farstrider Lodge - это место для охотников в Loch Modan. Там обмениваются историями, проводятся испытания на мастерство и присуждаются трофеи от местных зверей."},references={["place:loch-modan"]=true}},
    ["place:feathermoon-stronghold"] = {title="Bastión Plumaluna",kind="Lugar",aliases={"Bastión Plumaluna"},body="El Bastión Plumaluna es una base de los elfos de la noche en Feralas. Desde allí, sus fuerzas vigilan el territorio y reciben informes de las amenazas que afectan a sus costas y bosques.",aliasQuestIDs={},en={title="Feathermoon Stronghold",aliases={"Feathermoon Stronghold"},body="Feathermoon Stronghold is a night elf base in Feralas. Its forces watch the region and receive reports of threats affecting its coasts and forests.",aliasQuestIDs={}},fr={title="Feathermoon Stronghold",body="Feathermoon Stronghold est une base d'elfe de nuit dans Feralas. Ses forces surveillent la région et reçoivent des informations faisant état de menaces affectant ses côtes et ses forêts."},de={title="Feathermoon Stronghold",body="Feathermoon Stronghold ist eine Nachtelfen-Basis in Feralas. Seine Streitkräfte beobachten die Region und erhalten Berichte über Bedrohungen ihrer Küsten und Wälder."},pt={title="Feathermoon Stronghold",body="Feathermoon Stronghold é uma base de elfo noturno em Feralas. Suas forças vigiam a região e recebem relatos de ameaças que afetam suas costas e florestas."},pl={title="Feathermoon Stronghold",body="Feathermoon Stronghold to baza nocnych elfów w Feralas. Jej siły obserwują region i przyjmują doniesienia o zagrożeniach dotykających wybrzeża oraz lasy."},ru={title="Feathermoon Stronghold",body="Feathermoon Stronghold - это база ночных эльфов в Feralas. Ее войска следят за регионом и получают сообщения об угрозах, затрагивающих его побережья и леса."},references={["place:feralas"]=true}},
    ["place:felstone-field"] = {title="Campo de Piedramácula",kind="Lugar",aliases={"Campo de Piedramácula","Piedramácula"},body="El Campo de Piedramácula se encuentra al noroeste de Andorhal, en las Tierras de la Peste del Oeste. La presencia de una caldera de la Plaga transforma sus tierras agrícolas en un foco de toxinas vigilado por tropas no muertas.",aliasQuestIDs={["Piedramácula"]={[5216]=true,[5217]=true,[5229]=true,[5230]=true}},en={title="Felstone Field",aliases={"Felstone","Felstone Field"},body="Felstone Field lies northwest of Andorhal in the Western Plaguelands. A Scourge cauldron turns its farmland into a source of toxins guarded by undead troops.",aliasQuestIDs={["Felstone"]={[5216]=true,[5217]=true,[5229]=true,[5230]=true}}},fr={title="Felstone Field",body="Felstone Field se trouve au nord-ouest de Andorhal dans le Western Plaguelands. Un chaudron Scourge transforme ses terres agricoles en une source de toxines gardée par des troupes de morts-vivants."},de={title="Felstone Field",body="Felstone Field liegt nordwestlich von Andorhal im Western Plaguelands. Ein Scourge-Hexenkessel verwandelt sein Ackerland in eine Giftquelle, die von untoten Truppen bewacht wird."},pt={title="Felstone Field",body="Felstone Field fica a noroeste de Andorhal no Western Plaguelands. O caldeirão Scourge transforma suas terras agrícolas em uma fonte de toxinas guardadas por tropas mortas-vivos."},pl={title="Felstone Field",body="Felstone Field leży na północny zachód od Andorhal w Western Plaguelands. Kocioł Scourge zmienia pola w źródło toksyn strzeżone przez oddziały nieumarłych."},ru={title="Felstone Field",body="Felstone Field находится к северо-западу от Andorhal в Western Plaguelands. Казан Scourge превращает свои сельскохозяйственные угодья в источник токсинов, охраняемых неживыми трупами."},references={["organization:scourge"]=true,["place:andorhal"]=true,["place:plaguelands"]=true,["place:western-plaguelands"]=true}},
    ["place:felwood"] = {title="Frondavil",kind="Lugar",aliases={"Frondavil"},body="Frondavil es un bosque de Kalimdor profundamente afectado por la corrupción. Los seres y plantas de la región muestran sus efectos, mientras sus defensores buscan formas de limpiar la tierra y preservar lo que todavía resiste.",aliasQuestIDs={},en={title="Felwood",aliases={"Felwood"},body="Felwood is a forest of Kalimdor deeply affected by corruption. The region’s creatures and plants show its effects, while its defenders seek ways to cleanse the land and preserve what still endures.",aliasQuestIDs={}},fr={title="Felwood",body="Felwood est une forêt de Kalimdor profondément affectée par la corruption. Les créatures et les plantes de la région montrent ses effets, tandis que ses défenseurs cherchent des moyens de nettoyer la terre et de préserver ce qui perdure encore."},de={title="Felwood",body="Felwood ist ein Wald von Kalimdor, der tief von Korruption betroffen ist. Die Geschöpfe und Pflanzen der Region zeigen ihre Auswirkungen, während ihre Verteidiger nach Wegen suchen, das Land zu säubern und zu erhalten, was noch überdauert."},pt={title="Felwood",body="Felwood é uma floresta de Kalimdor profundamente afetada pela corrupção. As criaturas e plantas da região mostram seus efeitos, enquanto seus defensores buscam maneiras de limpar a terra e preservar o que ainda perdura."},pl={title="Felwood",body="Felwood to las na kontynencie Kalimdor głęboko dotknięty skażeniem. Stworzenia i rośliny regionu noszą jego ślady, a obrońcy szukają sposobów oczyszczenia ziemi oraz zachowania tego, co jeszcze przetrwało."},ru={title="Felwood",body="Felwood - это лес Kalimdor, глубоко пораженный порчей. Животные и растения этого региона демонстрируют его последствия, а защитники его стремятся очистить землю и сохранить то, что еще существует."},references={["place:kalimdor"]=true}},
    ["place:fenris-isle"] = {title="Isla de Fenris",kind="Lugar",aliases={"Isla de Fenris"},body="La Isla de Fenris contiene una fortaleza y zonas ocupadas por gnolls Putrepellejo. Sus caminos y ruinas son parte de los peligros que complican los viajes por Argénteos.",aliasQuestIDs={},en={title="Fenris Isle",aliases={"Fenris Isle"},body="Fenris Isle contains a keep and areas occupied by Rot Hide gnolls. Its paths and ruins are among the dangers complicating travel through Silverpine.",aliasQuestIDs={}},fr={title="Fenris Isle",body="Fenris Isle contient un donjon et des zones occupées par les gnolls Rot Hide. Ses chemins et ses ruines sont parmi les dangers qui compliquent le voyage à travers Silverpine."},de={title="Fenris Isle",body="Fenris Isle enthält einen Bergfried und Bereiche, die von Rot Hide Gnolls besetzt sind. Seine Wege und Ruinen gehören zu den Gefahren, die das Reisen durch Silverpine erschweren."},pt={title="Fenris Isle",body="Fenris Isle contém uma manutenção e áreas ocupadas por gnolls Rot Hide. Seus caminhos e ruínas estão entre os perigos que complicam as viagens através do Silverpine."},pl={title="Fenris Isle",body="Fenris Isle mieści warownię i obszary zajęte przez gnolle Rot Hide. Jej ścieżki i ruiny należą do niebezpieczeństw utrudniających podróż przez Silverpine."},ru={title="Fenris Isle",body="Fenris Isle включает крепость и земли, занятые гноллами Rot Hide. Его тропы и руины — одни из опасных мест, осложняющих путешествия через Silverpine."},references={["organization:rot-hide"]=true,["place:silverpine-forest"]=true}},
    ["place:fenris-keep"] = {title="Castillo de Fenris",kind="Lugar",aliases={"Castillo de Fenris","castillo de Fenris"},body="El Castillo de Fenris es una fortaleza de la Isla de Fenris. Sus ruinas guardan rastros de antiguos vínculos mágicos y permanecen en una zona peligrosa del Bosque de Argénteos.",aliasQuestIDs={},en={title="Fenris Keep",aliases={"Fenris Keep"},body="Fenris Keep is a fortress on Fenris Isle. Its ruins preserve traces of old magical connections and stand in a dangerous part of Silverpine Forest.",aliasQuestIDs={}},fr={title="Fenris Keep",body="Fenris Keep est une forteresse sur Fenris Isle. Ses ruines conservent des traces d'anciennes connexions magiques et se trouvent dans une partie dangereuse de Silverpine Forest."},de={title="Fenris Keep",body="Fenris Keep ist eine Festung auf Fenris Isle. Seine Ruinen bewahren Spuren alter magischer Verbindungen und stehen in einem gefährlichen Teil von Silverpine Forest."},pt={title="Fenris Keep",body="Fenris Keep é uma fortaleza em Fenris Isle. Suas ruínas preservam vestígios de antigas conexões mágicas e estão em uma parte perigosa do Silverpine Forest."},pl={title="Fenris Keep",body="Fenris Keep jest twierdzą na Fenris Isle. Jej ruiny zachowują ślady dawnych magicznych powiązań i stoją w niebezpiecznej części Silverpine Forest."},ru={title="Fenris Keep",body="Fenris Keep - это крепость на Fenris Isle. Его руины сохраняют следы старых магических связей и находятся в опасной части Silverpine Forest."},references={["place:fenris-isle"]=true,["place:silverpine-forest"]=true}},
    ["place:feralas"] = {title="Feralas",kind="Lugar",aliases={"Feralas"},body="Feralas es una región boscosa de Kalimdor donde los asentamientos actuales conviven con antiguas ruinas. Sus habitantes se enfrentan a ogros, sátiros y otros peligros que disputan el control de sus recursos y santuarios.",aliasQuestIDs={},en={title="Feralas",aliases={"Feralas"},body="Feralas is a forested region of Kalimdor where present-day settlements stand alongside ancient ruins. Its residents contend with ogres, satyrs and other dangers that contest its resources and sanctuaries.",aliasQuestIDs={}},fr={title="Feralas",body="Feralas est une région boisée de Kalimdor où les colonies actuelles côtoient des ruines anciennes. Ses habitants sont confrontés à des ogres, des satyres et d’autres dangers qui contestent ses ressources et ses sanctuaires."},de={title="Feralas",body="Feralas ist ein bewaldetes Gebiet von Kalimdor, wo heutige Siedlungen neben antiken Ruinen stehen. Seine Bewohner kämpfen mit Ogern, Satyren und anderen Gefahren, die ihnen Ressourcen und Zufluchtsstätten streitig machen."},pt={title="Feralas",body="Feralas é uma região florestal de Kalimdor onde os assentamentos atuais estão ao lado de ruínas antigas. Seus moradores lutam com ogros, sátiros e outros perigos que contestam seus recursos e santuários."},pl={title="Feralas",body="Feralas to lesisty region kontynentu Kalimdor, gdzie współczesne osady sąsiadują z pradawnymi ruinami. Mieszkańcy mierzą się z ogrami, satyrami i innymi zagrożeniami walczącymi o jego zasoby oraz sanktuaria."},ru={title="Feralas",body="Feralas - это лесистый регион Kalimdor, где современные поселения стоят рядом с древними руинами. Жители борются с великанами, сатирами и другими опасностями, которые бросают вызов его ресурсам и святилищам."},references={["place:kalimdor"]=true}},
    ["place:fire-plume-ridge"] = {title="Cresta del Penacho en Llamas",kind="Lugar",aliases={"Cresta del Penacho en Llamas"},body="La Cresta del Penacho en Llamas es una zona volcánica del Cráter de Un'Goro. Sus altas temperaturas y su relación con las fuentes termales cercanas la convierten en un lugar de interés para quienes estudian el calor del cráter.",aliasQuestIDs={},en={title="Fire Plume Ridge",aliases={"Fire Plume Ridge"},body="Fire Plume Ridge is a volcanic area in Un'Goro Crater. Its intense heat and relationship to nearby hot springs make it a subject of interest for those studying the crater’s temperatures.",aliasQuestIDs={}},fr={title="Fire Plume Ridge",body="Fire Plume Ridge est une zone volcanique dans Un'Goro Crater. Sa chaleur intense et sa relation avec les sources chaudes voisines en font un sujet d’intérêt pour ceux qui étudient les températures du cratère."},de={title="Fire Plume Ridge",body="Fire Plume Ridge ist ein vulkanisches Gebiet in Un'Goro Crater. Seine intensive Hitze und die Beziehung zu den nahe gelegenen heißen Quellen machen ihn zu einem interessanten Gegenstand für diejenigen, die die die die Temperatur des Kraters untersuchen."},pt={title="Fire Plume Ridge",body="Fire Plume Ridge é uma área vulcânica no Un'Goro Crater. Seu calor intenso e sua relação com as fontes termais próximas fazem com que seja um assunto de interesse para aqueles que estudam as temperaturas da cratera."},pl={title="Fire Plume Ridge",body="Fire Plume Ridge to obszar wulkaniczny w Un'Goro Crater. Ogromne gorąco i powiązanie z pobliskimi gorącymi źródłami budzą zainteresowanie badaczy temperatur panujących w kraterze."},ru={title="Fire Plume Ridge",body="Fire Plume Ridge - это вулканический район в Un'Goro Crater. Его сильная жара и связь с близлежащими горячими источниками делают его предметом интереса для тех, кто изучает температуру кратера."},references={["place:ungoro-crater"]=true}},
    ["place:fire-scar-shrine"] = {title="Santuario de la Escara",kind="Lugar",aliases={"Santuario de la Escara"},body="El Santuario de la Escara se encuentra en el suroeste de Vallefresno. Su reputación siniestra se relaciona con la presencia de poderosos brujos como Ilkrud Magthrull y con las artes oscuras que practican.",aliasQuestIDs={},en={title="Fire Scar Shrine",aliases={"Fire Scar Shrine"},body="The Fire Scar Shrine lies in southwestern Ashenvale. Its sinister reputation is associated with powerful warlocks such as Ilkrud Magthrull and the dark arts they practice.",aliasQuestIDs={}},fr={title="Fire Scar Shrine",body="Le Fire Scar Shrine se trouve dans le sud-ouest Ashenvale. Sa sinistre réputation est associée à de puissants démonistes tels que Ilkrud Magthrull et les arts sombres qu'ils pratiquent."},de={title="Fire Scar Shrine",body="Der Fire Scar Shrine liegt im Südwesten von Ashenvale. Sein düsterer Ruf hängt mit mächtigen Hexenmeistern wie Ilkrud Magthrull und den dunklen Künsten zusammen, die sie ausüben."},pt={title="Fire Scar Shrine",body="O Fire Scar Shrine encontra-se no sudoeste do Ashenvale. Sua reputação sinistra está associada a poderosos bruxos como Ilkrud Magthrull e as artes das trevas que eles praticam."},pl={title="Fire Scar Shrine",body="Fire Scar Shrine leży w południowo-zachodniej części Ashenvale. Jego złowroga reputacja wiąże się z potężnymi czarnoksiężnikami, takimi jak Ilkrud Magthrull, i uprawianymi przez nich mrocznymi sztukami."},ru={title="Fire Scar Shrine",body="Fire Scar Shrine находится на юго-западе Ashenvale. Его зловещая репутация связана с такими могущественными чернокнижниками, как Ilkrud Magthrull и темными искусствами, которыми они занимаются."},references={["person:ilkrud-magthrull"]=true,["place:ashenvale"]=true}},
    ["place:flame-crest"] = {title="Peñasco Llamarada",kind="Lugar",aliases={"Peñasco Llamarada"},body="El Peñasco Llamarada es un puesto de las Estepas Ardientes desde el que se realizan estudios y expediciones. La investigación de dragones conecta a sus habitantes con zonas distantes y con criaturas difíciles de observar.",aliasQuestIDs={},en={title="Flame Crest",aliases={"Flame Crest"},body="Flame Crest is a Burning Steppes post supporting research and expeditions. Dragon research connects its inhabitants with distant areas and creatures difficult to observe.",aliasQuestIDs={}},fr={title="Flame Crest",body="Flame Crest est un poste des Burning Steppes qui soutient la recherche et les expéditions. L'étude des dragons relie ses habitants à des régions lointaines et à des créatures difficiles à observer."},de={title="Flame Crest",body="Flame Crest ist ein Burning Steppes Post, der Forschung und Expeditionen unterstützt. Die Drachenforschung verbindet ihre Bewohner mit weit entfernten Gegenden und schwer zu beobachtenden Kreaturen."},pt={title="Flame Crest",body="Flame Crest é um post Burning Steppes que apoia pesquisas e expedições. A pesquisa do dragão conecta seus habitantes com áreas distantes e criaturas difíceis de observar."},pl={title="Flame Crest",body="Flame Crest to posterunek w Burning Steppes wspierający badania i wyprawy. Badania smoków łączą mieszkańców z odległymi obszarami oraz stworzeniami trudnymi do obserwacji."},ru={title="Flame Crest",body="Flame Crest - это пост Burning Steppes, поддерживающий исследования и экспедиции. Исследования драконов связывают его жителей с отдаленными районами и существами, которые трудно наблюдать."},references={["place:burning-steppes"]=true}},
    ["place:forest-song"] = {title="Canción del Bosque",kind="Lugar",aliases={"Canción del Bosque"},body="Canción del Bosque es un enclave de Vallefresno desde el que se vigilan los peligros del bosque. Sus habitantes mantienen contacto con exploradores y druidas que investigan venenos, sátiros y otras amenazas a los santuarios.",aliasQuestIDs={},en={title="Forest Song",aliases={"Forest Song"},body="Forest Song is an enclave in Ashenvale from which the forest’s dangers are watched. Its residents maintain contact with scouts and druids investigating poisons, satyrs and other threats to sacred places.",aliasQuestIDs={}},fr={title="Forest Song",body="Forest Song est une enclave dans Ashenvale à partir de laquelle les dangers de la forêt sont surveillés. Ses habitants maintiennent le contact avec les scouts et les druides qui enquêtent sur les poisons, les satyres et autres menaces sur les lieux sacrés."},de={title="Forest Song",body="Forest Song ist eine Enklave in Ashenvale, von wo aus die Gefahren des Waldes Waldes beobachtet werden. Seine Bewohner halten Kontakt zu Kundschaftern und Druiden, die Gifte, Satyre und andere Bedrohungen heiliger Stätten untersuchen."},pt={title="Forest Song",body="Forest Song é um enclave em Ashenvale a partir do qual os perigos da floresta são observados. Seus moradores mantêm contato com batedores e druidas que investigam venenos, sátiros e outras ameaças a lugares sagrados."},pl={title="Forest Song",body="Forest Song to enklawa w Ashenvale, z której obserwuje się niebezpieczeństwa lasu. Mieszkańcy utrzymują kontakt ze zwiadowcami i druidami badającymi trucizny, satyrów oraz inne zagrożenia dla świętych miejsc."},ru={title="Forest Song",body="Forest Song - это анклав в Ashenvale, из которого наблюдаются опасности леса. Жители города поддерживают связь со скаутами и друидами, которые расследуют яды, сатири и другие угрозы священным местам."},references={["place:ashenvale"]=true}},
    ["place:forlorn-cavern"] = {title="Caverna Abandonada",kind="Lugar",aliases={"Caverna Abandonada","La Caverna Abandonada"},body="La Caverna Abandonada es una zona de Forjaz asociada a conocimientos y contactos menos visibles. Allí llegan textos sobre poderes oscuros que interesan a estudiosos apartados de la enseñanza pública de la ciudad.",aliasQuestIDs={},en={title="Forlorn Cavern",aliases={"Forlorn Cavern"},body="The Forlorn Cavern is an Ironforge area associated with less visible knowledge and contacts. Texts on dark powers reach scholars there who work apart from the city’s public teaching.",aliasQuestIDs={}},fr={title="Forlorn Cavern",body="Le Forlorn Cavern est une zone Ironforge associée à des connaissances et des contacts moins visibles. Les textes sur les pouvoirs obscurs atteignent les érudits qui travaillent en dehors de l'enseignement public de la ville."},de={title="Forlorn Cavern",body="Der Forlorn Cavern-Bereich ist ein Ironforge-Bereich, der mit weniger sichtbarem Wissen und Kontakten verbunden ist. Texte über dunkle Mächte erreichen dort Gelehrte, die außerhalb der öffentlichen Lehre der Stadt arbeiten."},pt={title="Forlorn Cavern",body="O Forlorn Cavern é uma área Ironforge associada a menos conhecimento visível e contatos. Textos sobre poderes obscuros chegam a estudiosos lá que trabalham além do ensino público da cidade."},pl={title="Forlorn Cavern",body="Forlorn Cavern to część Ironforge związana z mniej widoczną wiedzą i kontaktami. Teksty o mrocznych mocach trafiają do uczonych działających poza publicznym nauczaniem miasta."},ru={title="Forlorn Cavern",body="Forlorn Cavern - это область Ironforge, связанная с менее заметными знаниями и контактами. Тексты о темных силах доходят до ученых, которые работают вне общественного образования города."},references={["place:ironforge"]=true}},
    ["place:freewind-post"] = {title="Poblado Viento Libre",kind="Lugar",aliases={"Poblado Viento Libre"},body="El Poblado Viento Libre es un asentamiento de la Horda en Las Mil Agujas. Sus habitantes dependen de los suministros que recorren la región y deben defender esas rutas de las arpías y otros atacantes.",aliasQuestIDs={},en={title="Freewind Post",aliases={"Freewind Post"},body="Freewind Post is a Horde settlement in Thousand Needles. Its residents depend on supplies carried through the region and must defend those routes from harpies and other attackers.",aliasQuestIDs={}},fr={title="Freewind Post",body="Freewind Post est un règlement Horde dans Thousand Needles. Ses habitants dépendent des fournitures acheminées à travers la région et doivent défendre ces routes contre les harpies et autres assaillants."},de={title="Freewind Post",body="Freewind Post ist eine Horde-Siedlung in Thousand Needles. Seine Bewohner sind von Lieferungen abhängig, die durch die Region getragen werden und müssen, und müssen diese Routen gegen Harpies und andere Angreifer verteidigen."},pt={title="Freewind Post",body="Freewind Post é um assentamento Horde em Thousand Needles. Seus moradores dependem de suprimentos transportados pela região e devem defender essas rotas de harpias e outros atacantes."},pl={title="Freewind Post",body="Freewind Post to osada frakcji Horde w regionie Thousand Needles. Mieszkańcy zależą od dostaw przewożonych przez te ziemie i muszą bronić szlaków przed harpiami oraz innymi napastnikami."},ru={title="Freewind Post",body="Freewind Post — поселение Horde на территории Thousand Needles. Жители города зависят от поставок, которые проходят через этот регион, и должны защищать эти маршруты от гарпий и других нападавших."},references={["organization:horde"]=true,["place:thousand-needles"]=true}},
    ["place:frostwolf-keep"] = {title="Bastión Lobo Gélido",kind="Lugar",aliases={"Bastión Lobo Gélido"},body="El Bastión Lobo Gélido es una posición del sur del Valle de Alterac y la sede del general Drek'Thar. Es un punto central de la defensa del clan frente a sus adversarios.",aliasQuestIDs={},en={title="Frostwolf Keep",aliases={"Frostwolf Keep"},body="Frostwolf Keep is a southern Alterac Valley position and General Drek'Thar's headquarters. It is a central point in the clan's defense against its opponents.",aliasQuestIDs={}},fr={title="Frostwolf Keep",body="Frostwolf Keep est une position au sud d'Alterac Valley et le quartier général de General Drek'Thar. C'est un point central de la défense du clan face à ses adversaires."},de={title="Frostwolf Keep",body="Frostwolf Keep ist eine südliche Alterac Valley-Position und Hauptquartier von General Drek'Thar. Sie ist ein zentraler Punkt bei der Verteidigung des Clans gegen seine Gegner."},pt={title="Frostwolf Keep",body="Frostwolf Keep é uma posição no sul de Alterac Valley e o quartel-general de General Drek'Thar. É um ponto central da defesa do clã contra seus adversários."},pl={title="Frostwolf Keep",body="Frostwolf Keep jest pozycją w południowym Alterac Valley i kwaterą General Drek'Thar. Stanowi centralny punkt obrony klanu przed jego przeciwnikami."},ru={title="Frostwolf Keep",body="Frostwolf Keep - это южная позиция Alterac Valley и штаб генерала Drek'Thar. Это центральная точка в обороне клана от его противников."},references={["npc:drekthar"]=true,["organization:frostwolf-clan"]=true,["place:alterac-mountains"]=true,["place:alterac-valley"]=true}},
    ["place:gadgetzan"] = {title="Gadgetzan",kind="Lugar",aliases={"Gadgetzan"},body="Gadgetzan es un poblado goblin de Tanaris que reúne comercio, investigación e intereses muy diversos. Sus habitantes intentan obtener beneficios del desierto sin perder de vista los peligros que rodean sus rutas y pozos de agua.",aliasQuestIDs={},en={title="Gadgetzan",aliases={"Gadgetzan"},body="Gadgetzan is a goblin town in Tanaris that brings together trade, research and a wide range of interests. Its residents seek profit in the desert while watching the dangers around their routes and water sources.",aliasQuestIDs={}},fr={title="Gadgetzan",body="Gadgetzan est une ville gobelin dans Tanaris qui rassemble le commerce, la recherche et un large éventail d'intérêts. Ses habitants recherchent le profit dans le désert tout en observant les dangers autour de leurs routes et de leurs sources d’eau."},de={title="Gadgetzan",body="Gadgetzan ist eine Koboldstadt in Tanaris, die Handel, Forschung und ein breites Spektrum an Interessen vereint. Seine Bewohner streben nach Profit in der Wüste, während sie die Gefahren rund um ihre Routen und Wasserquellen beobachten."},pt={title="Gadgetzan",body="Gadgetzan é uma cidade goblin em Tanaris que reúne comércio, pesquisa e uma ampla gama de interesses. Seus moradores buscam lucro no deserto enquanto observam os perigos em torno de suas rotas e fontes de água."},pl={title="Gadgetzan",body="Gadgetzan to goblińskie miasto w Tanaris łączące handel, badania i rozmaite interesy. Mieszkańcy poszukują zysku na pustyni, wypatrując zagrożeń wokół szlaków oraz źródeł wody."},ru={title="Gadgetzan",body="Gadgetzan - это город-гоблин в Tanaris, который объединяет торговлю, исследования и широкий спектр интересов. Жители города ищут прибыль в пустыне, наблюдая за опасностями на своих путях и водяных источниках."},references={["place:tanaris"]=true}},
    ["place:gallows-end-tavern"] = {title="Mesón La Horca",kind="Lugar",aliases={"Mesón La Horca"},body="El Mesón La Horca se encuentra en la parte oriental de Rémol. Además de recibir a habitantes como Coleman Farthing, su sótano sirve de lugar de detención para la Guardia de la Muerte.",aliasQuestIDs={},en={title="Gallow's End Tavern",aliases={"Gallow's End Tavern","Gallows End Tavern","Gallow’s End Tavern"},body="The Gallow's End Tavern stands in eastern Brill. Besides receiving residents such as Coleman Farthing, its cellar serves as a holding area for the Deathguard.",aliasQuestIDs={}},fr={title="Gallow's End Tavern",body="Le Gallow's End Tavern se trouve dans l'est du Brill. En plus de recevoir des résidents tels que Coleman Farthing, sa cave sert de zone de rétention pour le Deathguard."},de={title="Gallow's End Tavern",body="Der Gallow's End Tavern steht im östlichen Brill. Neben der Aufnahme von Bewohnern wie Coleman Farthing dient der Keller als Auffangstation für den Deathguard."},pt={title="Gallow's End Tavern",body="O Gallow's End Tavern fica no leste do Brill. Além de receber residentes como Coleman Farthing, sua adega serve como uma área de espera para o Deathguard."},pl={title="Gallow's End Tavern",body="The Gallow's End Tavern stoi we wschodnim Brill. Przyjmuje mieszkańców takich jak Coleman Farthing, a jej piwnica służy Deathguard jako miejsce przetrzymywania więźniów."},ru={title="Gallow's End Tavern",body="Gallow's End Tavern стоит на востоке Brill. Помимо приема жителей, таких как Coleman Farthing, его подвал служит зоной хранения для Deathguard."},references={["npc:coleman-farthing"]=true,["organization:deathguard"]=true,["place:brill"]=true}},
    ["place:gloomrise"] = {title="Alto Penumbroso",kind="Lugar",aliases={"Alto Penumbroso"},body="Alto Penumbroso es un antiguo cementerio tauren de Mulgore. Una infestación de arañas agresivas amenaza tanto a los visitantes como a un lugar que sus habitantes consideran sagrado.",aliasQuestIDs={},en={title="Gloomrise",aliases={"Gloomrise"},body="Gloomrise is an ancient tauren burial ground in Mulgore. An infestation of aggressive spiders threatens both visitors and a site the inhabitants regard as sacred.",aliasQuestIDs={}},fr={title="Gloomrise",body="Gloomrise est un ancien cimetière tauren dans Mulgore. Une infestation d'araignées agressives menace à la fois les visiteurs et un site que les habitants considèrent comme sacré."},de={title="Gloomrise",body="Gloomrise ist ein uraltes Tauren-Gräberfeld in Mulgore. Ein Befall mit aggressiven Spinnen bedroht sowohl Besucher als auch eine Stätte, die von der den Bewohnern als heilig betrachtet wird."},pt={title="Gloomrise",body="Gloomrise é um antigo cemitério de tauren em Mulgore. Uma infestação de aranhas agressivas ameaça os visitantes e um local que os habitantes consideram sagrado."},pl={title="Gloomrise",body="Gloomrise to pradawne cmentarzysko taurenów w Mulgore. Plaga agresywnych pająków zagraża zarówno przybyszom, jak i miejscu uznawanemu przez mieszkańców za święte."},ru={title="Gloomrise",body="Gloomrise - это древнее место захоронения Тауренов в Mulgore. Наводнение агрессивных пауков угрожает как посетителям, так и месту, которое жители считают священным."},references={["place:mulgore"]=true}},
    ["place:gnomeregan"] = {title="Gnomeregan",kind="Lugar",aliases={"Gnomeregan"},body="Gnomeregan es una ciudad gnómica cuyos archivos y dispositivos representan generaciones de inventiva. Su pérdida ha dejado a los supervivientes la tarea de recuperar conocimientos, herramientas y recuerdos que no pueden reemplazarse con facilidad.",aliasQuestIDs={},en={title="Gnomeregan",aliases={"Gnomeregan"},body="Gnomeregan is a gnomish city whose archives and devices represent generations of invention. Its loss has left the survivors trying to recover knowledge, tools and memories that cannot easily be replaced.",aliasQuestIDs={}},fr={title="Gnomeregan",body="Gnomeregan est une ville gnome dont les archives et les dispositifs représentent des générations d'inventions. Sa perte a laissé les survivants essayer de récupérer des connaissances, des outils et des souvenirs qui ne peuvent pas être facilement remplacés."},de={title="Gnomeregan",body="Gnomeregan ist eine gnomische Stadt, deren Archive und Geräte Generationen von Erfindungen repräsentieren. Sein Verlust hat dazu geführt, dass die Überlebenden versuchen, Wissen, Werkzeuge und Erinnerungen wiederzuerlangen, die nicht so einfach ersetzt werden können."},pt={title="Gnomeregan",body="Gnomeregan é uma cidade gnomosa cujos arquivos e dispositivos representam gerações de invenções. Sua perda deixou os sobreviventes tentando recuperar conhecimento, ferramentas e memórias que não podem ser facilmente substituídas."},pl={title="Gnomeregan",body="Gnomeregan to miasto gnomów, którego archiwa i urządzenia reprezentują pokolenia wynalazczości. Po jego utracie ocaleni próbują odzyskać wiedzę, narzędzia i pamiątki, których niełatwo zastąpić."},ru={title="Gnomeregan",body="Gnomeregan - это гномский город, архивы и устройства которого представляют поколения изобретений. Потеря этого оружия заставила выживших пытаться восстановить знания, инструменты и воспоминания, которые не могут быть легко заменены."},references={}},
    ["place:golbolar-quarry"] = {title="Cantera de Gol'Bolar",kind="Lugar",aliases={"Cantera de Gol'Bolar","Cantera de Gol’Bolar","Gol'Bolar","Gol’Bolar"},body="La Cantera de Gol'Bolar es una explotación de Dun Morogh que utiliza pólvora para sus trabajos. Los troggs de sus alrededores amenazan tanto a los trabajadores como a los materiales peligrosos almacenados allí.",aliasQuestIDs={},en={title="Gol'Bolar Quarry",aliases={"Gol'Bolar","Gol'Bolar Quarry","Gol’Bolar","Gol’Bolar Quarry"},body="Gol’Bolar Quarry is a Dun Morogh mining site using blasting powder in its work. Troggs in the area threaten both the workers and the dangerous materials stored there.",aliasQuestIDs={}},fr={title="Gol'Bolar Quarry",body="Gol’Bolar Quarry est un site minier Dun Morogh utilisant de la poudre de sablage dans son travail. Troggs dans la région menacent à la fois les travailleurs et les matières dangereuses qui y sont stockées."},de={title="Gol'Bolar Quarry",body="Gol’Bolar Quarry ist ein Dun Morogh Minenstandort, der Sprengpulver bei seiner Arbeit einsetzt. Troggs in der Gegend bedroht sowohl die Arbeiter als auch die dort gelagerten gefährlichen Stoffe."},pt={title="Gol'Bolar Quarry",body="Gol’Bolar Quarry é um local de mineração Dun Morogh usando pó de jateamento em seu trabalho. O Troggs na área ameaça tanto os trabalhadores quanto os materiais perigosos armazenados lá."},pl={title="Gol'Bolar Quarry",body="Gol’Bolar Quarry to wyrobisko w Dun Morogh wykorzystujące proch strzelniczy. Miejscowi troggowie zagrażają zarówno robotnikom, jak i składowanym tam niebezpiecznym materiałom."},ru={title="Gol'Bolar Quarry",body="Gol’Bolar Quarry - это зона добычи Dun Morogh, использующая в работе взрывный порошок. Troggs в этом районе угрожают как рабочим, так и опасным материалам, хранящимся там."},references={["place:dun-morogh"]=true}},
    ["place:gold-coast-quarry"] = {title="Mina de la Costa del Oro",kind="Lugar",aliases={"Mina de la Costa del Oro"},body="La Mina de la Costa del Oro es una explotación cercana a la costa de Poniente. Las incursiones de los Defias afectan tanto a este lugar como a las haciendas y poblados que lo rodean.",aliasQuestIDs={},en={title="Gold Coast Quarry",aliases={"Gold Coast","Gold Coast Quarry"},body="Gold Coast Quarry is a mining site near Westfall’s coast. Defias raids affect this location as well as the surrounding farms and settlements.",aliasQuestIDs={}},fr={title="Gold Coast Quarry",body="Gold Coast Quarry est un site minier près de la côte de Westfall. Les raids Defias affectent cet endroit ainsi que les fermes et les colonies environnantes."},de={title="Gold Coast Quarry",body="Gold Coast Quarry ist ein Bergbaugebiet in der Nähe von Westfall 's Küste. Defias-Razzien betreffen diesen Ort ebenso wie die umliegenden Höfe und Siedlungen."},pt={title="Gold Coast Quarry",body="Gold Coast Quarry é um local de mineração perto da costa de Westfall. Os ataques Defias afetam este local, bem como as fazendas e assentamentos circundantes."},pl={title="Gold Coast Quarry",body="Gold Coast Quarry to wyrobisko niedaleko wybrzeża Westfall. Najazdy Defias dotykają zarówno tego miejsca, jak i okolicznych gospodarstw oraz osad."},ru={title="Gold Coast Quarry",body="Gold Coast Quarry - это рудниковая площадка недалеко от побережья Westfall. Нападения Defias влияют на это место, а также на окружающие фермы и поселения."},references={["organization:defias-brotherhood"]=true,["place:westfall"]=true}},
    ["place:goldshire"] = {title="Villadorada",kind="Lugar",aliases={"Villadorada"},body="Villadorada es un poblado del Bosque de Elwynn donde confluyen viajeros, guardias y vecinos de las granjas. Desde allí se coordinan investigaciones sobre las minas y la protección de los asentamientos más alejados.",aliasQuestIDs={},en={title="Goldshire",aliases={"Goldshire"},body="Goldshire is an Elwynn Forest settlement where travelers, guards and farm families meet. Investigations of the mines and the protection of outlying settlements are coordinated from here.",aliasQuestIDs={}},fr={title="Goldshire",body="Goldshire est un établissement Elwynn Forest où les voyageurs, les gardes et les familles de la ferme se rencontrent. Les enquêtes sur les mines et la protection des colonies périphériques sont coordonnées à partir d'ici."},de={title="Goldshire",body="Goldshire ist eine Elwynn Forest-Siedlung, in der sich Reisende, Wachen und Bauernfamilien treffen. Von hier aus werden die Untersuchungen der Minen und der Schutz der abgelegenen Siedlungen koordiniert."},pt={title="Goldshire",body="Goldshire é um assentamento Elwynn Forest onde viajantes, guardas e famílias de agricultores se encontram. As investigações das minas e a proteção de assentamentos periféricos são coordenadas a partir daqui."},pl={title="Goldshire",body="Goldshire to osada w Elwynn Forest, w której spotykają się podróżni, strażnicy i rodziny rolników. Stąd koordynowane są badania kopalń oraz ochrona odleglejszych osiedli."},ru={title="Goldshire",body="Goldshire - это поселение Elwynn Forest, где встречаются путешественники, охранники и фермерские семьи. Здесь координируются расследования шахт и защита отдаленных поселений."},references={["place:elwynn-forest"]=true}},
    ["place:great-lift"] = {title="El Gran Elevador",kind="Lugar",aliases={"El Gran Elevador","Gran Elevador"},body="El Gran Elevador permite salvar el desnivel entre Los Baldíos y Las Mil Agujas. Su posición lo convierte en un acceso importante para los viajeros y para quienes intentan controlar el paso entre ambas regiones.",aliasQuestIDs={},en={title="Great Lift",aliases={"Great Lift","The Great Lift"},body="The Great Lift crosses the change in elevation between the Barrens and Thousand Needles. Its position makes it an important passage for travelers and those seeking to control movement between the regions.",aliasQuestIDs={}},fr={title="Great Lift",body="The Great Lift croise l'évolution de l'élévation entre Barrens et Thousand Needles. Sa position en fait un passage important pour les voyageurs et ceux qui cherchent à contrôler les mouvements entre les régions."},de={title="Great Lift",body="The Great Lift überquert den Höhenunterschied zwischen Barrens und Thousand Needles. Seine Lage macht es zu einer wichtigen Durchgangsstation für Reisende und diejenigen, die den Verkehr zwischen den Regionen kontrollieren suchen."},pt={title="Great Lift",body="The Great Lift cruza a mudança de elevação entre o Barrens e Thousand Needles. Sua posição faz com que seja uma passagem importante para os viajantes e aqueles que procuram controlar o movimento entre as regiões."},pl={title="Great Lift",body="The Great Lift pokonuje różnicę wysokości między regionami Barrens i Thousand Needles. Położenie czyni ten obiekt ważnym przejściem dla podróżnych oraz tych, którzy chcą kontrolować ruch między obiema krainami."},ru={title="Great Lift",body="The Great Lift пересекает изменение высоты между Barrens и Thousand Needles. Его положение делает его важным переходом для путешественников и тех, кто хочет контролировать движение между регионами."},references={["place:the-barrens"]=true,["place:thousand-needles"]=true}},
    ["place:great-ossuary"] = {title="El Gran Osario",kind="Lugar",aliases={"El Gran Osario","Gran Osario"},body="El Gran Osario es una cámara de Scholomance, en Lordaeron. Sus sombras y su presencia espiritual atraen investigaciones sobre instrumentos capaces de penetrar la oscuridad de ese recinto.",aliasQuestIDs={},en={title="Great Ossuary",aliases={"Great Ossuary","The Great Ossuary"},body="The Great Ossuary is a chamber within Scholomance in Lordaeron. Its shadows and spiritual presence draw research into instruments capable of piercing the room's darkness.",aliasQuestIDs={}},fr={title="Great Ossuary",body="The Great Ossuary est une chambre de Scholomance dans Lordaeron. Ses ombres et sa présence spirituelle attirent la recherche sur des instruments capables de percer les ténèbres de la pièce."},de={title="Great Ossuary",body="The Great Ossuary ist eine Kammer innerhalb von Scholomance in Lordaeron. Seine Schatten und spirituelle Präsenz ziehen die Forschung nach Instrumenten an, die in der Lage sind, die Dunkelheit des Raumes zu durchdringen."},pt={title="Great Ossuary",body="The Great Ossuary é uma câmara dentro de Scholomance em Lordaeron. Suas sombras e presença espiritual atraem pesquisas em instrumentos capazes de perfurar a escuridão da sala."},pl={title="Great Ossuary",body="The Great Ossuary jest komnatą w Scholomance w Lordaeron. Jej cienie i duchowa obecność przyciągają badania nad instrumentami zdolnymi przeniknąć mrok pomieszczenia."},ru={title="Great Ossuary",body="The Great Ossuary - это камера внутри Scholomance в Lordaeron. Его тени и духовное присутствие приводят к исследованиям инструментов, способных проникнуть в темноту комнаты."},references={["place:lordaeron"]=true,["place:scholomance"]=true}},
    ["place:greymane-wall"] = {title="Muralla de Cringris",kind="Lugar",aliases={"Muralla de Cringris"},body="La Muralla de Cringris se alza en el sur del Bosque de Argénteos, en el acceso al reino de Gilneas. Es un límite territorial que también condiciona la huida y los desplazamientos de quienes buscan cruzar hacia ese reino.",aliasQuestIDs={},en={title="Greymane Wall",aliases={"Greymane Wall"},body="The Greymane Wall stands in southern Silverpine Forest at the approach to the kingdom of Gilneas. It is a territorial boundary that also shapes the movements of people seeking to flee or cross into that kingdom.",aliasQuestIDs={}},fr={title="Greymane Wall",body="Le Greymane Wall se trouve dans le sud Silverpine Forest à l'approche du royaume de Gilneas. C’est une frontière territoriale qui façonne également les mouvements des personnes qui cherchent à fuir ou à traverser dans ce royaume."},de={title="Greymane Wall",body="Der Greymane Wall steht im Süden von Silverpine Forest an der Annäherung an das Königreich von Gilneas. Es ist eine territoriale Grenze, die auch die die Bewegungen von Menschen prägt, die versuchen, in dieses Königreich zu fliehen oder es zu überqueren."},pt={title="Greymane Wall",body="O Greymane Wall situa-se no sul do Silverpine Forest na aproximação ao reino de Gilneas. É uma fronteira territorial que também molda os movimentos de pessoas que procuram fugir ou atravessar esse reino."},pl={title="Greymane Wall",body="The Greymane Wall stoi w południowym Silverpine Forest przy drodze do królestwa Gilneas. Jest granicą terytorialną kształtującą też ruchy osób próbujących uciec lub przedostać się do tego królestwa."},ru={title="Greymane Wall",body="Greymane Wall стоит в южной части Silverpine Forest на подходе к королевству Gilneas. Это территориальная граница, которая также формирует движение людей, стремящихся бежать или пересекать в это царство."},references={["place:silverpine-forest"]=true}},
    ["place:grim-batol"] = {title="Grim Batol",kind="Lugar",aliases={"Grim Batol"},body="Grim Batol fue una fortaleza montañosa de los Martillo Salvaje en los Humedales. El recuerdo de sus grifos y de la comunidad que existió allí sigue siendo importante para los enanos que regresan a esas tierras.",aliasQuestIDs={},en={title="Grim Batol",aliases={"Grim Batol"},body="Grim Batol was a Wildhammer mountain fortress in the Wetlands. Memories of its gryphons and former community remain important to dwarves returning to those lands.",aliasQuestIDs={}},fr={title="Grim Batol",body="Grim Batol était une forteresse de montagne Wildhammer dans le Wetlands. Les souvenirs de ses griffons et de son ancienne communauté restent importants pour les nains qui retournent sur ces terres."},de={title="Grim Batol",body="Grim Batol war eine Wildhammer-Bergfestung im Wetlands. Die Erinnerungen an die Gryphons und die ehemalige Gemeinschaft bleiben für die Zwerge, die in diese Länder zurückkehren, wichtig."},pt={title="Grim Batol",body="Grim Batol foi uma fortaleza de montanha Wildhammer no Wetlands. Memórias de seus grifons e ex-comunidade permanecem importantes para os anões que retornam a essas terras."},pl={title="Grim Batol",body="Grim Batol było górską twierdzą Wildhammer w Wetlands. Wspomnienia gryfów i dawnej społeczności pozostają ważne dla krasnoludów powracających na te ziemie."},ru={title="Grim Batol",body="Grim Batol была горной крепостью Wildhammer в Wetlands. Память о грифонах и бывшей общине остается важной для дворфов, возвращающихся на эти земли."},references={["organization:wildhammer"]=true,["place:wetlands"]=true}},
    ["place:gromgol"] = {title="Campamento Grom'gol",kind="Lugar",aliases={"Campamento Grom'gol","Campamento Grom’gol","Grom'gol","Grom’gol"},body="El Campamento Grom'gol es una base de la Horda en Tuercespina. Desde allí se exploran la selva y las ruinas cercanas, y se investigan las amenazas que rodean a sus expedicionarios.",aliasQuestIDs={},en={title="Grom'gol Base Camp",aliases={"Grom'gol","Grom'gol Base Camp","Grom’gol","Grom’gol Base Camp"},body="Grom’gol Base Camp is a Horde base in Stranglethorn. Its expeditionaries explore the jungle and nearby ruins while investigating the threats surrounding their position.",aliasQuestIDs={}},fr={title="Grom'gol Base Camp",body="Grom’gol Base Camp est une base Horde dans Stranglethorn. Ses expéditionnaires explorent la jungle et les ruines voisines tout en enquêtant sur les menaces entourant leur position."},de={title="Grom'gol Base Camp",body="Grom’gol Base Camp ist ein Horde-Stützpunkt in Stranglethorn. Seine Expeditionäre erkunden den Dschungel und die nahe gelegenen Ruinen, während sie die Bedrohungen rund um ihre Position untersuchen."},pt={title="Grom'gol Base Camp",body="Grom’gol Base Camp é uma base Horde em Stranglethorn. Seus expedicionários exploram a selva e as ruínas próximas enquanto investigam as ameaças que cercam sua posição."},pl={title="Grom'gol Base Camp",body="Grom’gol Base Camp to baza Horde w Stranglethorn. Jej uczestnicy wypraw badają dżunglę i pobliskie ruiny, jednocześnie rozpoznając zagrożenia wokół swojej placówki."},ru={title="Grom'gol Base Camp",body="Grom’gol Base Camp - это база Horde в Stranglethorn. Его экспедиционеры исследуют джунгли и близлежащие руины, изучая угрозы, окружающие их положение."},references={["organization:horde"]=true,["place:stranglethorn-vale"]=true}},
    ["place:gustberry-lowlands"] = {title="Bajíos Ventobaya",kind="Lugar",aliases={"Bajíos Ventobaya"},body="Los Bajíos Ventobaya son una zona de Isla Zephras situada al oeste de Valanaar. Cerca del borde de la isla albergan el Santuario de las Llamas, donde Olariaan Fuegoveloz mantiene su vínculo con los espíritus del fuego. El lugar forma parte del paisaje espiritual de los Formavientos.",aliasQuestIDs={},en={title="Gustberry Lowlands",aliases={"Gustberry Lowlands"},body="The Gustberry Lowlands are an area of Zephras Isle west of Valanaar. Near the island’s edge stands the Shrine of Flames, where Olariaan Swiftburn maintains his connection with fire spirits. The site is part of the Windshapers’ spiritual landscape.",aliasQuestIDs={}},fr={title="Gustberry Lowlands",body="Les Gustberry Lowlands sont une zone de Zephras Isle à l'ouest de Valanaar. Près du bord de l'île se trouve la Shrine of Flames, où Olariaan Swiftburn maintient sa connexion avec les esprits du feu. Le site fait partie du paysage spirituel de la Windshapers."},de={title="Gustberry Lowlands",body="Die Gustberry Lowlands sind ein Gebiet von Zephras Isle westlich von Valanaar. Am Rande der Insel steht der Shrine of Flames, wo Olariaan Swiftburn seine Verbindung zu den Feuergeistern pflegt. Die Stätte ist Teil der geistlichen Landschaft des Windshapers."},pt={title="Gustberry Lowlands",body="O Gustberry Lowlands é uma área de Zephras Isle a oeste de Valanaar. Perto da borda da ilha fica o Shrine of Flames, onde Olariaan Swiftburn mantém sua conexão com os espíritos de fogo. O site faz parte da paisagem espiritual do Windshapers."},pl={title="Gustberry Lowlands",body="The Gustberry Lowlands są obszarem Zephras Isle na zachód od Valanaar. Przy krańcu wyspy stoi Shrine of Flames, gdzie Olariaan Swiftburn utrzymuje więź z duchami ognia. Miejsce należy do duchowego krajobrazu społeczności znanej jako the Windshapers."},ru={title="Gustberry Lowlands",body="Gustberry Lowlands - это район Zephras Isle к западу от Valanaar. Рядом с краем острова стоит Shrine of Flames, где Olariaan Swiftburn поддерживает связь со духами огня. Сайт является частью духовного ландшафта Windshapers."},references={["organization:windshapers"]=true,["person:olariaan-swiftburn"]=true,["place:shrine-of-flames"]=true,["place:valanaar"]=true,["place:zephras"]=true}},
    ["place:hall-of-explorers"] = {title="Sala de los Expedicionarios",kind="Lugar",aliases={"Sala de los Expedicionarios"},body="La Sala de los Expedicionarios es un centro de estudio en Forjaz que recibe reliquias e informes de yacimientos lejanos. Sus libros y colecciones permiten relacionar los hallazgos de los exploradores con investigaciones más amplias.",aliasQuestIDs={},en={title="Hall of Explorers",aliases={"Hall of Explorers"},body="The Hall of Explorers is an Ironforge center of study receiving relics and reports from distant dig sites. Its books and collections connect explorers’ discoveries with wider research.",aliasQuestIDs={}},fr={title="Hall of Explorers",body="Le Hall of Explorers est un centre d'étude Ironforge recevant des reliques et des rapports de sites de fouille distants. Ses livres et ses collections relient les découvertes des explorateurs à des recherches plus vastes."},de={title="Hall of Explorers",body="Das Hall of Explorers ist ein Ironforge-Studienzentrum, das Relikte und Berichte von weit entfernten Ausgrabenden Fundorten erhält. Ihre Bücher und Sammlungen verbinden die Entdeckungen der Entdecker mit umfassenderer Forschung."},pt={title="Hall of Explorers",body="O Hall of Explorers é um centro de estudo Ironforge que recebe relíquias e relatórios de locais de escavação distantes. Seus livros e coleções conectam as descobertas dos exploradores com pesquisas mais amplas."},pl={title="Hall of Explorers",body="Hall of Explorers to ośrodek badań w Ironforge przyjmujący relikty i meldunki z odległych wykopalisk. Księgi i kolekcje łączą odkrycia podróżników z szerszą pracą naukową."},ru={title="Hall of Explorers",body="Hall of Explorers - это центр исследований Ironforge, принимающий реликвии и отчеты с отдаленных мест раскопок. Книги и коллекции связывают открытия исследователей с более широкими исследованиями."},references={["place:ironforge"]=true}},
    ["place:hall-of-mysteries"] = {title="Sala de los Misterios",kind="Lugar",aliases={"Sala de los Misterios"},body="La Sala de los Misterios es un lugar de Forjaz al que acuden quienes continúan su formación religiosa. Sus instructores orientan a discípulos de la Luz y les transmiten las responsabilidades de su vocación.",aliasQuestIDs={},en={title="Hall of Mysteries",aliases={"Hall of Mysteries"},body="The Hall of Mysteries is an Ironforge place visited by those continuing religious training. Its instructors guide students of the Light and pass on the responsibilities of their calling.",aliasQuestIDs={}},fr={title="Hall of Mysteries",body="Le Hall of Mysteries est un endroit Ironforge visité par ceux qui continuent la formation religieuse. Ses instructeurs guident les étudiants de the Light et transmettent les responsabilités de leur appel."},de={title="Hall of Mysteries",body="Der Hall of Mysteries ist ein Ironforge-Ort, der von denen besucht wird, die sich fortbilden. Seine Dozenten leiten die the Light-Schüler an und geben ihnen die Verantwortung ihrer Berufung weiter."},pt={title="Hall of Mysteries",body="O Hall of Mysteries é um lugar Ironforge visitado por aqueles que continuam o treinamento religioso. Seus instrutores orientam os alunos do the Light e transmitem as responsabilidades de seu chamado."},pl={title="Hall of Mysteries",body="Hall of Mysteries to miejsce w Ironforge odwiedzane przez osoby kontynuujące naukę religijną. Instruktorzy prowadzą uczniów „the Light” i przekazują im obowiązki wynikające z powołania."},ru={title="Hall of Mysteries",body="Hall of Mysteries - это место Ironforge, которое посещают те, кто продолжает религиозное обучение. Его инструкторы направляют студентов the Light и передают ответственность за их призвание."},references={["concept:holy-light"]=true,["place:ironforge"]=true}},
    ["place:hammerfall"] = {title="Sentencia",kind="Lugar",aliases={"Sentencia"},body="Sentencia es un puesto de la Horda en Arathi que recibe noticias de las amenazas de la región. Sus habitantes reúnen información, recursos y recuerdos de viejos conflictos para mantener su posición.",aliasQuestIDs={},en={title="Hammerfall",aliases={"Hammerfall"},body="Hammerfall is a Horde post in Arathi receiving reports of regional threats. Its inhabitants gather intelligence, resources and memories of old conflicts to maintain their position.",aliasQuestIDs={}},fr={title="Hammerfall",body="Hammerfall est un poste Horde dans Arathi recevant des rapports de menaces régionales. Ses habitants rassemblent des renseignements, des ressources et des souvenirs d'anciens conflits pour maintenir leur position."},de={title="Hammerfall",body="Hammerfall ist ein Horde in Arathi, der Berichte über regionale Bedrohungen erhält. Seine Bewohner sammeln Informationen, Ressourcen und Erinnerungen an alte Konflikte, um ihre Position zu behaupten."},pt={title="Hammerfall",body="Hammerfall é um post Horde no Arathi recebendo relatórios de ameaças regionais. Seus habitantes reúnem inteligência, recursos e memórias de antigos conflitos para manter sua posição."},pl={title="Hammerfall",body="Hammerfall jest posterunkiem Horde w Arathi przyjmującym meldunki o miejscowych zagrożeniach. Mieszkańcy gromadzą informacje, zasoby i wspomnienia dawnych konfliktów, by utrzymać pozycję."},ru={title="Hammerfall",body="Hammerfall - это пост Horde в Arathi, принимающий сообщения о региональных угрозах. Ее жители собирают информацию, ресурсы и воспоминания о старых конфликтах, чтобы сохранить свою позицию."},references={["organization:horde"]=true,["place:arathi-highlands"]=true}},
    ["place:harborage"] = {title="El Puerto",kind="Lugar",aliases={"El Puerto"},body="El Puerto es una comunidad draenei del Pantano de las Penas. Sus habitantes consideran sagrados los cristales draenetistas y los relacionan con su resistencia frente a la pérdida de la razón.",aliasQuestIDs={},en={title="Harborage",aliases={"Harborage"},body="The Harborage is a draenei community in the Swamp of Sorrows. Its inhabitants consider draenethyst crystals sacred and associate them with resisting the loss of their sanity.",aliasQuestIDs={}},fr={title="Harborage",body="Le Harborage est une communauté draenei dans le Swamp of Sorrows. Ses habitants considèrent les cristaux draenethyst sacrés et les associent à la résistance à la perte de leur santé mentale."},de={title="Harborage",body="Die Harborage sind eine Draenei-Gemeinschaft im Swamp of Sorrows. Seine Bewohner betrachten Draenethystkristalle als heilig und assoziieren sie mit dem Widerstand gegen den Verlust ihrer geistigen Gesundheit."},pt={title="Harborage",body="O Harborage é uma comunidade draenei do Swamp of Sorrows. Seus habitantes consideram os cristais de draenétis sagrados e os associam a resistir à perda de sua sanidade."},pl={title="Harborage",body="Harborage to społeczność draenei w Swamp of Sorrows. Mieszkańcy uważają kryształy draenetystu za święte i wiążą je z opieraniem się utracie zdrowych zmysłów."},ru={title="Harborage",body="Harborage - это сообщество дренаев в Swamp of Sorrows. Жители считают кристаллы дренатиста священными и связывают их с сопротивлением утрате сознания."},references={["place:swamp-of-sorrows"]=true},questIDs={[1389]=true,[1392]=true,[93464]=true,[93585]=true,[93663]=true,[93678]=true}},
    ["place:hearthglen"] = {title="Vega del Amparo",kind="Lugar",aliases={"La Vega del Amparo","Vega del Amparo"},body="La Vega del Amparo es una población de las Tierras de la Peste del Oeste controlada por la Cruzada Escarlata. Sus caminos de acceso y puestos exteriores forman una red defensiva vigilada por oficiales de la orden.",aliasQuestIDs={},en={title="Hearthglen",aliases={"Hearthglen"},body="Hearthglen is a Western Plaguelands settlement controlled by the Scarlet Crusade. Its approaches and outlying posts form a defensive network watched by the order's officers.",aliasQuestIDs={}},fr={title="Hearthglen",body="Hearthglen est un règlement Western Plaguelands contrôlé par le Scarlet Crusade. Ses approches et ses postes périphériques forment un réseau défensif surveillé par les officiers de l'ordre."},de={title="Hearthglen",body="Hearthglen ist eine Western Plaguelands-Siedlung, die vom Scarlet Crusade kontrolliert wird. Seine Zugänge und Außenposten bilden ein Verteidigungsnetzwerk, das von den Offizieren des Ordens überwacht wird."},pt={title="Hearthglen",body="Hearthglen é um acordo Western Plaguelands controlado pelo Scarlet Crusade. Suas abordagens e postos periféricos formam uma rede defensiva vigiada pelos oficiais da ordem."},pl={title="Hearthglen",body="Hearthglen jest osadą Western Plaguelands kontrolowaną przez organizację znaną jako the Scarlet Crusade. Drogi do niej i oddalone posterunki tworzą sieć obronną obserwowaną przez oficerów zakonu."},ru={title="Hearthglen",body="Hearthglen - это расчетный пункт Western Plaguelands, контролируемый Scarlet Crusade. Его подходы и окраинные посты образуют защитную сеть, которую следят офицеры ордена."},references={["organization:scarlet-crusade"]=true,["place:plaguelands"]=true,["place:western-plaguelands"]=true}},
    ["place:highperch"] = {title="Nido Alto",kind="Lugar",aliases={"Nido Alto"},body="Nido Alto es una zona de Las Mil Agujas donde anidan dracoleones. Sus huevos atraen el interés de quienes abastecen a los jinetes del viento, aunque las criaturas defienden sus nidos con gran ferocidad.",aliasQuestIDs={},en={title="Highperch",aliases={"Highperch"},body="Highperch is a nesting area for wyverns in Thousand Needles. Their eggs interest those supplying the wind riders, though the creatures defend their nests fiercely.",aliasQuestIDs={}},fr={title="Highperch",body="Highperch est une zone de nidification pour les wyverns dans Thousand Needles. Leurs œufs intéressent ceux qui fournissent les cavaliers du vent, bien que les créatures défendent farouchement leurs nids."},de={title="Highperch",body="Highperch ist ein Nistplatz für Flügeldrachen in Thousand Needles. Ihre Eier interessieren diejenigen, die die die Windräder versorgen, obwohl die Kreaturen ihre Nester heftig verteidigen."},pt={title="Highperch",body="Highperch é uma área de nidificação para wyverns em Thousand Needles. Seus ovos interessam àqueles que fornecem os pilotos de vento, embora as criaturas defendam ferozmente seus ninhos."},pl={title="Highperch",body="Highperch jest miejscem gniazdowania wywern w Thousand Needles. Ich jaja interesują dostawców jeźdźców wiatru, choć stworzenia zaciekle bronią swoich gniazd."},ru={title="Highperch",body="Highperch - это зона гнездования вивернов в Thousand Needles. Их яйца интересуют тех, кто снабжает ветровых всадников, хотя эти существа яростно защищают свои гнезда."},references={["place:thousand-needles"]=true}},
    ["place:hillsbrad-foothills"] = {title="Laderas de Trabalomas",kind="Lugar",aliases={"Laderas de Trabalomas"},body="Las Laderas de Trabalomas reúnen campos, caminos y asentamientos disputados por fuerzas rivales. Las montañas y fortalezas cercanas influyen en la seguridad de los viajeros y de las comunidades que dependen de sus tierras.",aliasQuestIDs={},en={title="Hillsbrad Foothills",aliases={"Hillsbrad","Hillsbrad Foothills"},body="The Hillsbrad Foothills contain fields, roads and settlements contested by rival forces. Nearby mountains and strongholds influence the safety of travelers and communities dependent on the land.",aliasQuestIDs={}},fr={title="Hillsbrad Foothills",body="Les Hillsbrad Foothills contiennent des champs, des routes et des colonies contestés par des forces rivales. Les montagnes et les bastions à proximité influencent la sécurité des voyageurs et des communautés dépendantes de la terre."},de={title="Hillsbrad Foothills",body="Die Hillsbrad Foothills umfassen Felder, Straßen und Siedlungen, die von rivalisierenden Streitkräften umkämpft werden. Die nahen Berge und Festungen beeinflussen die Sicherheit der Reisenden und der Gemeinschaften, die von diesem Land leben."},pt={title="Hillsbrad Foothills",body="O Hillsbrad Foothills contém campos, estradas e assentamentos contestados por forças rivais. Montanhas e fortalezas próximas influenciam a segurança dos viajantes e comunidades dependentes da terra."},pl={title="Hillsbrad Foothills",body="Hillsbrad Foothills obejmują pola, drogi i osady, o które walczą rywalizujące siły. Pobliskie góry i warownie wpływają na bezpieczeństwo podróżnych oraz społeczności utrzymujących się z ziemi."},ru={title="Hillsbrad Foothills",body="В Hillsbrad Foothills есть поля, дороги и поселения, которые оспариваются соперничающими силами. Ближайшие горы и крепости влияют на безопасность путешественников и общин, зависящих от земли."},references={},questIDs={[493]=true,[495]=true,[1065]=true,[1536]=true,[2479]=true,[6681]=true,[7261]=true,[7645]=true,[9389]=true,[96779]=true,[98071]=true,[98095]=true,[98197]=true,[98219]=true}},
    ["place:hillsbrad-town"] = {title="Trabalomas",kind="Lugar",aliases={"Trabalomas"},body="Trabalomas es una comunidad humana con campos, minas y un consejo local. Sus habitantes y suministros interesan a las fuerzas que vigilan el poblado y disputan el control de las laderas que lo rodean.",aliasQuestIDs={},en={title="Hillsbrad",aliases={"Hillsbrad"},body="Hillsbrad is a human community with fields, mines and a local council. Its inhabitants and supplies interest forces watching the town and competing for control of the surrounding foothills.",aliasQuestIDs={}},fr={title="Hillsbrad",body="Hillsbrad est une communauté humaine avec des champs, des mines et un conseil local. Ses habitants et les forces d'intérêt de fournitures surveillent la ville et en compétition pour le contrôle des contreforts environnants."},de={title="Hillsbrad",body="Hillsbrad ist eine menschliche Gemeinschaft mit Feldern, Minen und einem Gemeinderat. Seine Einwohner und Lieferanten beobachten die Stadt und konkurrieren um die Kontrolle über die umliegenden Ausläufer."},pt={title="Hillsbrad",body="Hillsbrad é uma comunidade humana com campos, minas e um conselho local. Seus habitantes e fornece forças de interesse observando a cidade e competindo pelo controle do sopé circundante."},pl={title="Hillsbrad",body="Hillsbrad to ludzka społeczność z polami, kopalniami i lokalną radą. Mieszkańcy oraz zapasy interesują siły obserwujące miasto i rywalizujące o kontrolę nad okolicznym podgórzem."},ru={title="Hillsbrad",body="Hillsbrad - это человеческое сообщество с полями, рудниками и местным советом. Его жители и снабжение интересуют силы, наблюдающие за городом и соперничающие за контроль над окружающими предгорьями."},references={},questIDs={[494]=true,[501]=true,[502]=true,[503]=true,[506]=true,[507]=true,[509]=true,[527]=true,[528]=true,[529]=true,[546]=true,[567]=true,[568]=true,[98059]=true}},
    ["place:hinterlands"] = {title="Tierras del Interior",kind="Lugar",aliases={"Las Tierras del Interior","Tierras del Interior"},body="Las Tierras del Interior son una región de comunidades Martillo Salvaje, poblados trol y lugares de poder. La búsqueda de reliquias y el cuidado de los grifos conviven con conflictos entre los distintos habitantes del territorio.",aliasQuestIDs={},en={title="The Hinterlands",aliases={"Hinterlands","The Hinterlands"},body="The Hinterlands are a region of Wildhammer communities, troll settlements and places of power. Relic hunting and gryphon care coexist with conflicts among the territory’s inhabitants.",aliasQuestIDs={}},fr={title="The Hinterlands",body="The Hinterlands est une région de communautés Wildhammer, de colonies de trolls et de lieux de pouvoir. La chasse aux reliques et les soins aux griffons coexistent avec les conflits entre les habitants du territoire."},de={title="The Hinterlands",body="The Hinterlands sind eine Region mit Wildhammer-Gemeinden, Trollsiedlungen und Kraftorten. Reliquienjagd und Greifen Pflege gehen Hand in Hand in Hand mit Konflikten zwischen den Bewohnern des Territoriums."},pt={title="The Hinterlands",body="The Hinterlands são uma região de comunidades Wildhammer, assentamentos de trolls e locais de poder. A caça de relíquias e o cuidado com gryphon coexistem com conflitos entre os habitantes do território."},pl={title="The Hinterlands",body="The Hinterlands to region społeczności Wildhammer, osad trolli i miejsc mocy. Poszukiwanie reliktów oraz opieka nad gryfami współistnieją tu z konfliktami między mieszkańcami tych ziem."},ru={title="The Hinterlands",body="The Hinterlands - это регион сообществ Wildhammer, поселений троллей и мест власти. Охота на реликвии и забота о грифонах сосуществуют с конфликтами между жителями территории."},references={["organization:wildhammer"]=true}},
    ["place:hive-ashi"] = {title="Colmen'Ashi",kind="Lugar",aliases={"Colmen'Ashi","Colmen’Ashi"},body="Colmen'Ashi es una de las colmenas de silítidos de Silithus. La exploradora Jalia vigila los movimientos de sus habitantes para aportar información a quienes se enfrentan a la amenaza del desierto.",aliasQuestIDs={},en={title="Hive'Ashi",aliases={"Hive'Ashi","Hive’Ashi"},body="Hive'Ashi is one of Silithus’s silithid hives. Scout Jalia watches its inhabitants’ movements to provide intelligence for those opposing the desert’s threat.",aliasQuestIDs={}},fr={title="Hive'Ashi",body="Hive'Ashi est l'une des ruches silithid de Silithus. Scout Jalia surveille les mouvements de ses habitants pour fournir des renseignements à ceux qui s’opposent à la menace du désert."},de={title="Hive'Ashi",body="Hive'Ashi ist einer von Silithus 'Silithidbeuten. Pfadfinder Jalia beobachtet die Bewegungen seiner Bewohner, um Informationen für die Gegner der Bedrohung durch die Wüste bereitzustellen."},pt={title="Hive'Ashi",body="Hive'Ashi é uma das colmeias silitídeas do Silithus. O Scout Jalia observa os movimentos de seus habitantes para fornecer inteligência para aqueles que se opõem à ameaça do deserto."},pl={title="Hive'Ashi",body="Hive'Ashi jest jednym z uli silithidów w Silithus. Zwiadowczyni Jalia obserwuje ruchy jego mieszkańców, dostarczając informacji tym, którzy przeciwstawiają się pustynnemu zagrożeniu."},ru={title="Hive'Ashi",body="Hive'Ashi - один из силитидных ульев Silithus. Скаут Jalia следит за движениями жителей, чтобы предоставить информацию тем, кто выступает против угрозы пустыни."},references={["person:scout-jalia"]=true,["place:silithus"]=true}},
    ["place:hiveregal"] = {title="Colmen'Regal",kind="Lugar",aliases={"Colmen'Regal","Colmen’Regal"},body="Colmen'Regal es una de las grandes colmenas de Silithus. Sus alrededores también forman parte de las rutas y posiciones disputadas por las fuerzas que buscan recursos en el desierto.",aliasQuestIDs={},en={title="Hive'Regal",aliases={"Hive'Regal","Hive’Regal"},body="Hive'Regal is one of the great hives of Silithus. Its surroundings also form part of the routes and positions contested by forces seeking resources in the desert.",aliasQuestIDs={}},fr={title="Hive'Regal",body="Hive'Regal est l'une des grandes ruches de Silithus. Ses environs font également partie des routes et des positions contestées par les forces à la recherche de ressources dans le désert."},de={title="Hive'Regal",body="Hive'Regal ist einer der großen Bienenstöcke von Silithus. Seine Umgebung ist auch Teil der Routen und Stellungen, die von Streitkräften auf der Suche nach Bodenschätzen in der Wüste umkämpft werden."},pt={title="Hive'Regal",body="Hive'Regal é uma das grandes colmeias de Silithus. Seu entorno também faz parte das rotas e posições contestadas pelas forças que buscam recursos no deserto."},pl={title="Hive'Regal",body="Hive'Regal to jeden z wielkich rojów Silithus. Otoczenie obejmuje także szlaki i pozycje będące przedmiotem walk sił poszukujących zasobów na pustyni."},ru={title="Hive'Regal",body="Hive'Regal - один из больших ульев Silithus. Его окрестности также являются частью маршрутов и позиций, на которых борются силы, ищущие ресурсы в пустыне."},references={["place:silithus"]=true}},
    ["place:hivezora"] = {title="Colmen'Zora",kind="Lugar",aliases={"Colmen'Zora","Colmen’Zora"},body="Colmen'Zora es una de las colmenas de Silithus. La presencia de fuerzas armadas en sus alrededores combina el peligro de sus criaturas con las disputas por el control del desierto.",aliasQuestIDs={},en={title="Hive'Zora",aliases={"Hive'Zora","Hive’Zora"},body="Hive'Zora is one of the hives of Silithus. Armed forces in its surroundings combine the danger of its creatures with disputes over control of the desert.",aliasQuestIDs={}},fr={title="Hive'Zora",body="Hive'Zora est l'une des ruches de Silithus. Les forces armées dans ses environs combinent le danger de ses créatures avec des disputes sur le contrôle du désert."},de={title="Hive'Zora",body="Hive'Zora ist einer der Bienenstöcke von Silithus. Die bewaffneten Kräfte in seiner Umgebung verbinden die Gefahr seiner Kreaturen mit Streitigkeiten um die Kontrolle über die Wüste."},pt={title="Hive'Zora",body="Hive'Zora é uma das colmeias de Silithus. As forças armadas em seus arredores combinam o perigo de suas criaturas com disputas sobre o controle do deserto."},pl={title="Hive'Zora",body="Hive'Zora to jeden z rojów Silithus. Siły zbrojne w otoczeniu tego miejsca sprawiają, że zagrożenie ze strony jego stworzeń łączy się ze sporami o kontrolę nad pustynią."},ru={title="Hive'Zora",body="Hive'Zora - это один из ульев Silithus. Вооруженные силы в его окрестностях сочетают опасность его существ с спорами о контроле над пустыней."},references={["place:silithus"]=true}},
    ["place:hyjal"] = {title="Monte Hyjal",kind="Lugar",aliases={"Hyjal","Monte Hyjal"},body="El Monte Hyjal es una montaña de Kalimdor vinculada al antiguo hogar de los elfos de la noche. Su memoria permanece en las tradiciones de su pueblo y en plantas sagradas que crecían en sus alturas.",aliasQuestIDs={},en={title="Mount Hyjal",aliases={"Hyjal","Mount Hyjal"},body="Mount Hyjal is a mountain in Kalimdor tied to the night elves’ former home. Its memory remains in their traditions and in sacred plants that grew on its heights.",aliasQuestIDs={}},fr={title="Mount Hyjal",body="Mount Hyjal est une montagne de Kalimdor liée à l’ancienne maison des elfes de la nuit. Sa mémoire demeure dans leurs traditions et dans les plantes sacrées qui poussaient sur ses hauteurs."},de={title="Mount Hyjal",body="Mount Hyjal ist ein Berg in Kalimdor, der an die ehemalige Heimat der Nachtelfen gebunden ist. Seine Erinnerung bleibt in ihren Traditionen und in heiligen Pflanzen, die auf seinen Höhen wuchsen."},pt={title="Mount Hyjal",body="Mount Hyjal é uma montanha em Kalimdor amarrada à antiga casa dos elfos da noite. Sua memória permanece em suas tradições e em plantas sagradas que cresceram em suas alturas."},pl={title="Mount Hyjal",body="Mount Hyjal to góra na kontynencie Kalimdor związana z dawnym domem nocnych elfów. Pamięć o niej pozostaje w ich tradycjach i świętych roślinach rosnących na jej wysokościach."},ru={title="Mount Hyjal",body="Mount Hyjal - это гора в Kalimdor, связанная с бывшим домом ночных эльфов. Ее память сохранилась в их традициях и священных растениях, которые росли на ее высотах."},references={["place:kalimdor"]=true}},
    ["place:icewing-caverns"] = {title="Cueva Ala Gélida",kind="Lugar",aliases={"Cueva Ala Gélida"},body="La Cueva Ala Gélida está situada al suroeste de Dun Baldar en el Valle de Alterac. Uno de los estandartes de los Pico Tormenta permanece en su interior como símbolo que deben recuperar los aspirantes a la expedición.",aliasQuestIDs={},en={title="Icewing Caverns",aliases={"Icewing Caverns"},body="Icewing Caverns lies southwest of Dun Baldar in Alterac Valley. A Stormpike banner remains inside as a symbol that prospective expedition members must recover.",aliasQuestIDs={}},fr={title="Icewing Caverns",body="Icewing Caverns se trouve au sud-ouest de Dun Baldar dans Alterac Valley. Une bannière Stormpike reste à l'intérieur comme un symbole que les membres potentiels de l'expédition doivent récupérer."},de={title="Icewing Caverns",body="Icewing Caverns liegt südwestlich von Dun Baldar in Alterac Valley. Ein Stormpike-Banner bleibt im Inneren als Symbol, das künftige Expeditionsmitglieder erholen müssen."},pt={title="Icewing Caverns",body="Icewing Caverns fica a sudoeste de Dun Baldar em Alterac Valley. A bandeira Stormpike permanece dentro como um símbolo que os futuros membros da expedição devem recuperar."},pl={title="Icewing Caverns",body="Icewing Caverns leży na południowy zachód od Dun Baldar w Alterac Valley. W środku pozostaje sztandar Stormpike, symbol, który muszą odzyskać przyszli członkowie ekspedycji."},ru={title="Icewing Caverns",body="Icewing Caverns находится к юго-западу от Dun Baldar в Alterac Valley. Внутри остается значок Stormpike как символ, который должны восстановить потенциальные члены экспедиции."},references={["organization:stormpike-expedition"]=true,["place:alterac-mountains"]=true,["place:alterac-valley"]=true,["place:dun-baldar"]=true}},
    ["place:ironbands-excavation"] = {title="Excavación de Vetaferro",kind="Lugar",aliases={"Excavación de Vetaferro"},body="La Excavación de Vetaferro investiga ruinas antiguas al este del lago de Loch Modan. El suministro de materiales y la seguridad de los exploradores son esenciales para que sus investigaciones puedan continuar.",aliasQuestIDs={},en={title="Ironband's Excavation",aliases={"Ironband's Excavation","Ironband’s Excavation"},body="Ironband’s Excavation investigates ancient ruins east of Loch Modan’s lake. Material supplies and the explorers’ safety are essential for its research to continue.",aliasQuestIDs={}},fr={title="Ironband's Excavation",body="Ironband’s Excavation étudie les ruines antiques à l'est du lac Loch Modan. L’approvisionnement en matériel et la sécurité des explorateurs sont essentiels à la poursuite de ses recherches."},de={title="Ironband's Excavation",body="Ironband’s Excavation untersucht antike Ruinen östlich des Loch Modan 'schen Sees. Materialvorräte und die Sicherheit der Entdecker sind für die Fortsetzung ihrer Forschung von entscheidender Bedeutung."},pt={title="Ironband's Excavation",body="Ironband’s Excavation investiga ruínas antigas a leste do lago Loch Modan. Os suprimentos de materiais e a segurança dos exploradores são essenciais para que sua pesquisa continue."},pl={title="Ironband's Excavation",body="Ironband’s Excavation bada starożytne ruiny na wschód od jeziora w Loch Modan. Dostawy materiałów i bezpieczeństwo odkrywców są niezbędne do kontynuowania prac."},ru={title="Ironband's Excavation",body="Ironband’s Excavation исследует древние руины к востоку от озера Loch Modan s. Материальные запасы и безопасность исследователей необходимы для продолжения исследований."},references={["npc:prospector-ironband"]=true,["place:loch-modan"]=true}},
    ["place:irondeep-mine"] = {title="Mina Ferrohondo",kind="Lugar",aliases={"Ferro Hondo","Ferrohondo","Mina Ferro Hondo","Mina Ferrohondo"},body="Mina Ferrohondo es un enclave del Valle de Alterac que contiene minerales y depósitos de suministros. La presencia de troggs y la guerra hacen difícil conservar el control de sus recursos.",aliasQuestIDs={},en={title="Irondeep Mine",aliases={"Irondeep","Irondeep Mine","Irondeep mine"},body="Irondeep Mine is an Alterac Valley site holding minerals and supply stores. Troggs and the ongoing war make control of its resources difficult to maintain.",aliasQuestIDs={}},fr={title="Irondeep Mine",body="Irondeep Mine est un site Alterac Valley contenant des minéraux et des magasins d'approvisionnement. Troggs et la guerre en cours rendent le contrôle de ses ressources difficile à maintenir."},de={title="Irondeep Mine",body="Irondeep Mine ist ein Alterac Valley-Standort mit Mineralien- und Versorgungsgeschäften. Troggs und der andauernde Krieg erschweren die Kontrolle über seine Ressourcen."},pt={title="Irondeep Mine",body="Irondeep Mine é um site Alterac Valley que contém minerais e lojas de suprimentos. O Troggs e a guerra em curso dificultam a manutenção do controle de seus recursos."},pl={title="Irondeep Mine",body="Irondeep Mine jest miejscem w Alterac Valley zawierającym minerały i zapasy. Troggi oraz trwająca wojna utrudniają utrzymanie kontroli nad jej zasobami."},ru={title="Irondeep Mine",body="Irondeep Mine - это сайт Alterac Valley, на котором хранятся минералы и запасы. Troggs и продолжающаяся война затрудняют контроль над его ресурсами."},references={["place:alterac-mountains"]=true,["place:alterac-valley"]=true}},
    ["place:ironforge"] = {title="Forjaz",kind="Lugar",aliases={"Forjaz"},body="Forjaz es una ciudad enana que reúne artesanos, soldados y estudiosos. Su Sala de los Expedicionarios conserva e investiga hallazgos de lugares lejanos, mientras la ciudad también ofrece refugio a los gnomos desplazados de Gnomeregan.",aliasQuestIDs={},en={title="Ironforge",aliases={"Ironforge"},body="Ironforge is a dwarven city bringing together craftspeople, soldiers and scholars. Its Hall of Explorers preserves and studies finds from distant lands, while the city also shelters gnomes displaced from Gnomeregan.",aliasQuestIDs={}},fr={title="Ironforge",body="Ironforge est une ville naine qui rassemble des artisans, des soldats et des savants. Sa Hall of Explorers conserve et étudie les découvertes de terres lointaines, tandis que la ville abrite également des gnomes déplacés de Gnomeregan."},de={title="Ironforge",body="Ironforge ist eine Zwergenstadt, die Handwerker, Soldaten und Gelehrte zusammenbringt. Sein Hall of Explorers bewahrt und untersucht Funde aus fernen Ländern, während die Stadt auch Gnome beherbergt, die vor Gnomeregan vertrieben haben."},pt={title="Ironforge",body="Ironforge é uma cidade anã que reúne artesãos, soldados e estudiosos. Sua Hall of Explorers preserva e estuda achados de terras distantes, enquanto a cidade também abriga gnomos deslocados de Gnomeregan."},pl={title="Ironforge",body="Ironforge to krasnoludzkie miasto skupiające rzemieślników, żołnierzy i uczonych. Hall of Explorers przechowuje i bada znaleziska z odległych krain, a miasto daje też schronienie gnomom wypartym z Gnomeregan."},ru={title="Ironforge",body="Ironforge - город карликов, объединяющий ремесленников, солдат и ученых. Его Hall of Explorers сохраняет и изучает находки из далеких земель, в то время как город также укрывает гномов, перемещенных из Gnomeregan."},references={["place:gnomeregan"]=true,["place:hall-of-explorers"]=true}},
    ["place:ironforge-military-ward"] = {title="Sala Militar",kind="Lugar",aliases={"Sala Militar"},body="La Sala Militar de Forjaz reúne actividades de preparación y abastecimiento para la guerra. Los materiales entregados allí, desde metales hasta vendas, muestran la variedad de recursos que necesita un ejército.",aliasQuestIDs={},en={title="Military Ward",aliases={"Military Ward"},body="Ironforge’s Military Ward gathers preparations and supplies for war. Materials delivered there, from metals to bandages, show the variety of resources an army needs.",aliasQuestIDs={}},fr={title="Military Ward",body="Ironforge Military Ward rassemble les préparatifs et les fournitures pour la guerre. Les matériaux livrés là-bas, des métaux aux bandages, montrent la variété des ressources dont une armée a besoin."},de={title="Military Ward",body="Ironforge 's Military Ward sammelt Kriegsvorbereitungen und Vorräte. Die dort gelieferten Materialien, von Metallen bis hin zu Verbänden, zeigen die Vielfalt der Ressourcen, die eine Armee braucht."},pt={title="Military Ward",body="Ironforge do Military Ward reúne preparações e suprimentos para a guerra. Materiais entregues lá, de metais a bandagens, mostram a variedade de recursos que um exército precisa."},pl={title="Military Ward",body="Military Ward w Ironforge skupia przygotowania i zapasy wojenne. Dostarczane materiały, od metali po bandaże, pokazują różnorodność zasobów potrzebnych armii."},ru={title="Military Ward",body="Ironforge s Military Ward собирает приготовления и припасы для войны. Материалы, доставленные туда, от металлов до повязок, показывают разнообразие ресурсов, необходимых армии."},references={["place:ironforge"]=true}},
    ["place:ironforge-mystic-ward"] = {title="Sala Mística",kind="Lugar",aliases={"Sala Mística"},body="La Sala Mística es una zona de Forjaz que recibe estudiosos y celebraciones de carácter espiritual. Las investigaciones y reuniones de sus habitantes forman parte de una vida urbana que va más allá de la forja y la guerra.",aliasQuestIDs={},en={title="Mystic Ward",aliases={"Mystic Ward"},body="The Mystic Ward is an Ironforge district welcoming scholars and spiritual celebrations. Its inhabitants’ studies and gatherings are part of city life beyond forging and war.",aliasQuestIDs={}},fr={title="Mystic Ward",body="Le Mystic Ward est un quartier Ironforge accueillant des érudits et des célébrations spirituelles. Les études et les rassemblements de ses habitants font partie de la vie urbaine au-delà de la forge et de la guerre."},de={title="Mystic Ward",body="Der Mystic Ward ist ein Ironforge-Bezirk, der Gelehrte und spirituelle Feiern willkommen heißt. Die Studien und Versammlungen seiner Bewohner sind Teil des städtischen Lebens über Schmieden Krieg hinaus."},pt={title="Mystic Ward",body="O Mystic Ward é um distrito de Ironforge que recebe estudiosos e celebrações espirituais. Os estudos e encontros de seus habitantes fazem parte da vida da cidade além da forja e da guerra."},pl={title="Mystic Ward",body="Mystic Ward to dzielnica Ironforge goszcząca uczonych i duchowe uroczystości. Badania i spotkania mieszkańców są częścią miejskiego życia wykraczającą poza kuźnie i wojnę."},ru={title="Mystic Ward",body="Mystic Ward - это район Ironforge, где принимают ученых и духовные праздники. Ее жители изучают и собираются в городе, не говоря уже о ковчеге и войне."},references={["place:ironforge"]=true}},
    ["place:ivar-patch"] = {title="Dominios de Ivar",kind="Lugar",aliases={"Dominios de Ivar"},body="Los Dominios de Ivar se encuentran al norte de El Sepulcro. Este rincón de Argénteos también sirve de refugio provisional para agentes heridos de los Renegados.",aliasQuestIDs={},en={title="Ivar Patch",aliases={"Ivar Patch"},body="Ivar Patch lies north of the Sepulcher. This corner of Silverpine also serves as temporary shelter for wounded Forsaken operatives.",aliasQuestIDs={}},fr={title="Ivar Patch",body="Ivar Patch se trouve au nord de la Sepulcher. Ce coin de Silverpine sert également d’abri temporaire pour les membres blessés du Forsaken."},de={title="Ivar Patch",body="Ivar Patch liegt nördlich des Sepulcher. Diese Ecke von Silverpine dient auch als provisorische Unterkunft für die verletzten Forsaken-Aktivisten."},pt={title="Ivar Patch",body="Ivar Patch fica ao norte do Sepulcher. Este canto do Silverpine também serve como abrigo temporário para agentes Forsaken feridos."},pl={title="Ivar Patch",body="Ivar Patch leży na północ od Sepulcher. Ten zakątek Silverpine służy także jako tymczasowe schronienie rannych agentów Forsaken."},ru={title="Ivar Patch",body="Ivar Patch находится к северу от Sepulcher. Этот уголок Silverpine также служит временным убежищем для раненых оперативников Forsaken."},references={["npc:ivar-the-foul"]=true,["organization:forsaken"]=true,["place:silverpine-forest"]=true,["place:the-sepulcher"]=true}},
    ["place:jaedenar"] = {title="Jaedenar",kind="Lugar",aliases={"Jaedenar"},body="Jaedenar es un enclave del Consejo de la Sombra en Frondavil. Sus cuevas y túmulos corruptos sirven de refugio a cultores y criaturas ligados a las actividades de la Legión Ardiente.",aliasQuestIDs={},en={title="Jaedenar",aliases={"Jaedenar"},body="Jaedenar is a Shadow Council enclave in Felwood. Its caves and corrupted barrows shelter cultists and creatures connected with Burning Legion activity.",aliasQuestIDs={}},fr={title="Jaedenar",body="Jaedenar est une enclave Shadow Council dans Felwood. Ses grottes et ses terriers corrompus abritent des cultes et des créatures liés à l'activité Burning Legion."},de={title="Jaedenar",body="Jaedenar ist eine Enklave von Shadow Council in Felwood. Seine Höhlen und verdorbenen Grabhütten beherbergen Kultisten und Kreaturen, die mit der Aktivität von Burning Legion verbunden sind."},pt={title="Jaedenar",body="Jaedenar é um enclave Shadow Council em Felwood. Suas cavernas e barrows corrompidos abrigam cultistas e criaturas ligadas à atividade Burning Legion."},pl={title="Jaedenar",body="Jaedenar to enklawa Shadow Council w Felwood. Jaskinie i skażone kurhany dają schronienie kultystom oraz stworzeniom powiązanym z działalnością Burning Legion."},ru={title="Jaedenar",body="Jaedenar - это анклав Shadow Council в Felwood. В его пещерах и испорченных гробницах находятся культисты и существа, связанные с деятельностью Burning Legion."},references={["organization:burning-legion"]=true,["organization:shadow-council"]=true,["place:felwood"]=true}},
    ["place:jangolode-mine"] = {title="Mina de Jango",kind="Lugar",aliases={"Mina de Jango"},body="La Mina de Jango se encuentra en el noroeste de los Páramos de Poniente. La presencia de los Defias en sus alrededores relaciona la explotación de los recursos con la lucha por mantener habitables las granjas de la región.",aliasQuestIDs={},en={title="Jangolode Mine",aliases={"Jangolode","Jangolode Mine"},body="Jangolode Mine lies in northwestern Westfall. Defias activity around it ties access to local resources to the struggle to keep the region’s farms habitable.",aliasQuestIDs={}},fr={title="Jangolode Mine",body="Jangolode Mine se trouve dans le nord-ouest Westfall. L’activité autour de Defias lie l’accès aux ressources locales à la lutte pour maintenir les fermes de la région habitables."},de={title="Jangolode Mine",body="Jangolode Mine liegt im Nordwesten von Westfall. Defias \"Aktivität um sie herum verknüpft den Zugang zu lokalen Ressourcen mit dem Kampf, die Höfe der Region bewohnbar zu halten zu halten."},pt={title="Jangolode Mine",body="Jangolode Mine fica no noroeste de Westfall. A atividade do Defias em torno dele vincula o acesso aos recursos locais à luta para manter as fazendas da região habitáveis."},pl={title="Jangolode Mine",body="Jangolode Mine leży w północno-zachodniej części Westfall. Działalność Defias w jej pobliżu wiąże dostęp do miejscowych zasobów z walką o zachowanie warunków do życia w gospodarstwach regionu."},ru={title="Jangolode Mine",body="Jangolode Mine находится на северо-западе Westfall. Деятельность Defias вокруг него связывает доступ к местным ресурсам с борьбой за сохранение пригодности сельскохозяйственных хозяйств региона."},references={["organization:defias-brotherhood"]=true,["place:westfall"]=true}},
    ["place:jasperlode-mine"] = {title="Cantera de Jaspe",kind="Lugar",aliases={"Cantera de Jaspe"},body="La Cantera de Jaspe es una mina de Elwynn situada más allá de la Torre de Azora. Sus galerías atraen a los kóbolds y requieren exploración para que los guardias conozcan el alcance de su presencia.",aliasQuestIDs={},en={title="Jasperlode Mine",aliases={"Jasperlode","Jasperlode Mine"},body="Jasperlode Mine lies in Elwynn beyond the Tower of Azora. Its tunnels attract kobolds and require scouting so the guards can understand the extent of their occupation.",aliasQuestIDs={}},fr={title="Jasperlode Mine",body="Jasperlode Mine se trouve dans Elwynn au-delà de la Tower of Azora. Ses tunnels attirent les kobolds et nécessitent un repérage afin que les gardes puissent comprendre l'étendue de leur occupation."},de={title="Jasperlode Mine",body="Jasperlode Mine liegt in Elwynn jenseits des Tower of Azora. Seine Tunnel ziehen Kobolde an und erfordern Kundschafter, damit die Wachen das Ausmaß ihrer Besetzung verstehen können."},pt={title="Jasperlode Mine",body="Jasperlode Mine encontra-se em Elwynn além do Tower of Azora. Seus túneis atraem kobolds e exigem reconhecimento para que os guardas possam entender a extensão de sua ocupação."},pl={title="Jasperlode Mine",body="Jasperlode Mine leży w Elwynn, za Tower of Azora. Jej tunele przyciągają koboldy i wymagają zwiadu, aby strażnicy mogli ustalić skalę ich obecności."},ru={title="Jasperlode Mine",body="Jasperlode Mine находится в Elwynn за Tower of Azora. Его туннели привлекают коболов и требуют разведки, чтобы охранники могли понять масштаб их занятости."},references={["place:elwynn-forest"]=true,["place:tower-of-azora"]=true}},
    ["place:jintha-alor"] = {title="Jintha'alor",kind="Lugar",aliases={"Jintha'alor","Jintha’alor"},body="Jintha'alor es un asentamiento trol de las Tierras del Interior. Sus recintos y alturas intervienen en las disputas entre las tribus de la región, incluidas las situaciones de cautiverio que afectan a sus rivales.",aliasQuestIDs={},en={title="Jintha'Alor",aliases={"Jintha'Alor","Jintha'alor","Jintha’Alor","Jintha’alor"},body="Jintha’Alor is a troll settlement in the Hinterlands. Its enclosures and heights feature in disputes among the region’s tribes, including the captivity of their rivals.",aliasQuestIDs={}},fr={title="Jintha'Alor",body="Jintha’Alor est un règlement de troll dans le Hinterlands. Ses enclos et ses hauteurs figurent dans les conflits entre les tribus de la région, y compris la captivité de leurs rivaux."},de={title="Jintha'Alor",body="Jintha’Alor ist eine Trollsiedlung im Hinterlands. Seine Einfriedungen und Höhen spielen bei Streitigkeiten zwischen den Stämmen der Region eine Rolle, einschließlich der Gefangenschaft ihrer Rivalen."},pt={title="Jintha'Alor",body="Jintha’Alor é um assentamento de trolls no Hinterlands. Seus recintos e alturas aparecem em disputas entre as tribos da região, incluindo o cativeiro de seus rivais."},pl={title="Jintha'Alor",body="Jintha’Alor to osada trolli w Hinterlands. Jej ogrodzone tereny i wzniesienia odgrywają rolę w sporach miejscowych plemion, obejmujących także więzienie przeciwników."},ru={title="Jintha'Alor",body="Jintha’Alor - это поселение троллей в Hinterlands. Его ограждения и высоты являются предметом споров между племенами региона, в том числе и о плену их соперников."},references={["place:hinterlands"]=true}},
    ["place:kalimdor"] = {title="Kalimdor",kind="Lugar",aliases={"Kalimdor"},body="Kalimdor es uno de los grandes continentes de Azeroth. Sus costas, bosques, montañas y desiertos albergan pueblos como los elfos de la noche, los tauren y los nuevos asentamientos de la Horda, unidos y separados por rutas terrestres y marítimas.",aliasQuestIDs={},en={title="Kalimdor",aliases={"Kalimdor"},body="Kalimdor is one of Azeroth’s great continents. Its coasts, forests, mountains and deserts are home to peoples such as the night elves, the tauren and the Horde’s new settlements, connected and separated by land and sea routes.",aliasQuestIDs={}},fr={title="Kalimdor",body="Kalimdor est l'un des grands continents de Azeroth. Ses côtes, ses forêts, ses montagnes et ses déserts abritent des peuples tels que les elfes de la nuit, les taurens et les nouvelles colonies de la Horde, reliées et séparées par des routes terrestres et maritimes."},de={title="Kalimdor",body="Kalimdor ist einer von Azeroth 'großen Kontinenten. Seine Küsten, Wälder, Berge und Wüsten beherbergen Völker wie die Nachtelfen, Tauren und die neuen Siedlungen der Horde, die durch Land- und Wasserwege miteinander verbunden und voneinander getrennt sind."},pt={title="Kalimdor",body="Kalimdor é um dos grandes continentes do Azeroth. Suas costas, florestas, montanhas e desertos são o lar de povos como os elfos noturnos, os tauren e os novos assentamentos do Horde, conectados e separados por rotas terrestres e marítimas."},pl={title="Kalimdor",body="Kalimdor to jeden z wielkich kontynentów Azeroth. Jego wybrzeża, lasy, góry i pustynie zamieszkują między innymi nocne elfy, taureni oraz nowe osady frakcji Horde, łączone i rozdzielane szlakami lądowymi oraz morskimi."},ru={title="Kalimdor",body="Kalimdor - один из великих континентов Azeroth. Его побережья, леса, горы и пустыни являются домом для таких народов, как ночные эльфы, таурены и новые поселения Horde, соединенные и разделенные сухопутными и морскими путями."},references={["organization:horde"]=true,["place:azeroth"]=true}},
    ["place:kargath"] = {title="Kargath",kind="Lugar",aliases={"Kargath"},body="Kargath es una base de la Horda en las Tierras Inhóspitas. Sus expedicionarios mantienen conflictos con las fuerzas de Roca Negra y organizan respuestas a las pérdidas sufridas en esas campañas.",aliasQuestIDs={},en={title="Kargath",aliases={"Kargath"},body="Kargath is a Horde base in the Badlands. Its expeditionary forces contend with Blackrock’s troops and organize responses to losses suffered in those campaigns.",aliasQuestIDs={}},fr={title="Kargath",body="Kargath est une base Horde dans le Badlands. Ses forces expéditionnaires font face aux troupes de Blackrock et organisent des réponses aux pertes subies lors de ces campagnes."},de={title="Kargath",body="Kargath ist ein Horde-Stützpunkt im Badlands. Seine Expeditionstruppen kümmern sich um die Truppen von Blackrock und organisieren Reaktionen auf die Verluste, die bei diesen Feldzügen erlitten wurden."},pt={title="Kargath",body="Kargath é uma base Horde no Badlands. Suas forças expedicionárias lutam com as tropas do Blackrock e organizam respostas às perdas sofridas nessas campanhas."},pl={title="Kargath",body="Kargath to baza Horde w Badlands. Jej siły ekspedycyjne mierzą się z oddziałami Blackrock i organizują odpowiedź na straty ponoszone podczas tych kampanii."},ru={title="Kargath",body="Kargath - это база Horde в Badlands. Ее экспедиционные силы борются с войсками Blackrock  и организуют ответы на потери, понесенные в этих кампаниях."},references={["organization:horde"]=true,["place:badlands"]=true}},
    ["place:keltheril"] = {title="Kel'Theril",kind="Lugar",aliases={"Kel'Theril","Kel’Theril","Lago Kel'Theril","Lago Kel’Theril","Ruinas de Kel'Theril","Ruinas de Kel’Theril"},body="Kel'Theril es un conjunto de ruinas junto a un lago helado de Cuna del Invierno. Los espíritus de los Altonato permanecen ligados al lugar, donde todavía se conservan inscripciones de antiguos encantamientos.",aliasQuestIDs={},en={title="Kel'Theril",aliases={"Kel'Theril","Kel’Theril","Lake Kel'Theril","Lake Kel’Theril","Ruins of Kel'Theril","Ruins of Kel’Theril"},body="Kel'Theril is a site of ruins beside a frozen lake in Winterspring. Highborne spirits remain bound to the place, where inscriptions of ancient incantations can still be found.",aliasQuestIDs={}},fr={title="Kel'Theril",body="Kel'Theril est un site de ruines au bord d'un lac gelé dans Winterspring. Les esprits Highborne restent liés à l'endroit, où des inscriptions d'incantations anciennes peuvent encore être trouvées."},de={title="Kel'Theril",body="Kel'Theril ist eine Ruinenstätte an einem zugefrorenen See in Winterspring. Geister der Highborne sind weiterhin an diesen Ort gebunden, an dem noch immer Inschriften alter Beschwörungsformeln zu finden sind."},pt={title="Kel'Theril",body="Kel'Theril é um local de ruínas ao lado de um lago congelado em Winterspring. Os espíritos Highborne permanecem ligados ao local, onde inscrições de encantamentos antigos ainda podem ser encontradas."},pl={title="Kel'Theril",body="Kel'Theril jest miejscem ruin nad zamarzniętym jeziorem w Winterspring. Duchy Highborne pozostają związane z tym miejscem, gdzie nadal można znaleźć inskrypcje dawnych zaklęć."},ru={title="Kel'Theril",body="Kel'Theril - это место руин рядом с замерзшим озером в Winterspring. Духи Highborne остаются привязаны к месту, где еще можно найти надписи древних заклинаний."},references={["organization:highborne"]=true,["place:winterspring"]=true}},
    ["place:kezan"] = {title="Kezan",kind="Lugar",aliases={"Kezan"},body="Kezan fue un territorio del Imperio Zandalar y sigue siendo tierra sagrada para sus descendientes. La expansión de los príncipes mercantes goblin cambió su población y su poder, y el lugar alberga la capital goblin de Minahonda.",aliasQuestIDs={},en={title="Kezan",aliases={"Kezan"},body="Kezan was a territory of the Zandalar Empire and remains sacred land to its descendants. The goblin trade princes' expansion changed its population and power, and the place houses the goblin capital of Undermine.",aliasQuestIDs={}},fr={title="Kezan",body="Kezan était un territoire de la Zandalar Empire et reste une terre sacrée pour ses descendants. L'expansion commerciale des princes gobelins changea sa population et sa puissance, et l'endroit abrite la capitale gobeline de Undermine."},de={title="Kezan",body="Kezan war ein Territorium des Zandalar Empire und bleibt seinen Nachfahren heiliges Land. Die Expansion der Goblin-Handelsprinzen veränderte ihre Bevölkerung und Macht, und den Ort beherbergte die Hauptstadt Undermine."},pt={title="Kezan",body="Kezan era um território do Zandalar Empire e continua a ser terra sagrada para seus descendentes. A expansão dos príncipes do comércio goblin mudou sua população e poder, e o lugar abriga a capital goblin de Undermine."},pl={title="Kezan",body="Kezan było terytorium Zandalar Empire i pozostaje świętą ziemią jego potomków. Ekspansja goblińskich książąt handlu zmieniła ludność i układ sił, a na miejscu znajduje się goblińska stolica Undermine."},ru={title="Kezan",body="Kezan была территорией Zandalar Empire и остается священной землей для его потомков. Расширение торговли гоблинами принцами изменило его население и власть, и здесь находится столица гоблинов Подмин."},references={["organization:zandalar-empire"]=true,["organization:zandalar-tribe"]=true}},
    ["place:kharanos"] = {title="Kharanos",kind="Lugar",aliases={"Kharanos"},body="Kharanos es una comunidad enana de Dun Morogh y un centro para la vigilancia de sus alrededores. Las noticias de exploradores y montaraces ayudan a sus defensores a responder a las amenazas de las montañas.",aliasQuestIDs={},en={title="Kharanos",aliases={"Kharanos"},body="Kharanos is a dwarven community in Dun Morogh and a center for watching the surrounding district. Reports from scouts and mountaineers help its defenders respond to mountain threats.",aliasQuestIDs={}},fr={title="Kharanos",body="Kharanos est une communauté naine dans Dun Morogh et un centre pour regarder le quartier environnant. Les rapports des scouts et des alpinistes aident ses défenseurs à répondre aux menaces de montagne."},de={title="Kharanos",body="Kharanos ist eine Zwergengemeinschaft in Dun Morogh und ein Beobachtungszentrum für die Umgebung. Berichte von Pfadfindern und Bergsteigern helfen seinen Verteidigern, auf Bedrohungen am Berg zu reagieren."},pt={title="Kharanos",body="Kharanos é uma comunidade anã em Dun Morogh e um centro para observar o distrito circundante. Relatórios de olheiros e montanhistas ajudam seus defensores a responder às ameaças da montanha."},pl={title="Kharanos",body="Kharanos to krasnoludzka społeczność w Dun Morogh i ośrodek obserwacji okolicy. Meldunki zwiadowców oraz górskich strażników pomagają obrońcom reagować na zagrożenia w górach."},ru={title="Kharanos",body="Kharanos - это сообщество дворфов в Dun Morogh и центр наблюдения за окружающим районом. Отчеты разведчиков и альпинистов помогают защитникам противостоять угрозам."},references={["place:dun-morogh"]=true}},
    ["place:kul-tiras"] = {title="Kul Tiras",kind="Lugar",aliases={"Kul Tiras"},body="Kul Tiras es una potencia humana conocida por sus flotas y sus infantes de marina. Sus barcos y soldados aparecen en los conflictos de Azeroth, desde las costas de Los Humedales hasta las expediciones que cruzaron el mar hacia Kalimdor.",aliasQuestIDs={},en={title="Kul Tiras",aliases={"Kul Tiras"},body="Kul Tiras is a human power known for its fleets and marines. Its ships and soldiers appear in Azeroth’s conflicts, from the Wetlands coast to expeditions crossing the sea to Kalimdor.",aliasQuestIDs={}},fr={title="Kul Tiras",body="Kul Tiras est une puissance humaine connue pour ses flottes et ses marines. Ses navires et ses soldats apparaissent dans les conflits de Azeroth, de la côte Wetlands aux expéditions traversant la mer à Kalimdor."},de={title="Kul Tiras",body="Kul Tiras ist eine menschliche Macht, die für ihre Flotten und Marinesoldaten bekannt ist. Ihre Schiffe und Soldaten treten in den Konflikten von Azeroth auf, von der Küste der Wetlands bis zu Expeditionen, die das Meer nach Kalimdor überquerten."},pt={title="Kul Tiras",body="Kul Tiras é um poder humano conhecido por suas frotas e fuzileiros navais. Seus navios e soldados aparecem nos conflitos do Azeroth, desde a costa do Wetlands até expedições que cruzam o mar até o Kalimdor."},pl={title="Kul Tiras",body="Kul Tiras to ludzka potęga znana z flot i piechoty morskiej. Jej statki i żołnierze pojawiają się w konfliktach Azeroth, od wybrzeża Wetlands po wyprawy przez morze do Kalimdor."},ru={title="Kul Tiras",body="Kul Tiras - это человеческая сила, известная своими флотами и морской пехотой. Его корабли и солдаты появляются в конфликтах Azeroth, от побережья Wetlands до экспедиций, пересекающих море до Kalimdor."},references={["place:azeroth"]=true,["place:kalimdor"]=true,["place:wetlands"]=true}},
    ["place:kurzens-compound"] = {title="Base de Kurzen",kind="Lugar",aliases={"Base de Kurzen"},body="La Base de Kurzen es un enclave armado en la selva de Tuercespina. Sus ocupantes mantienen prisioneros y representan un peligro para los exploradores que recorren esa parte de la región.",aliasQuestIDs={},en={title="Kurzen's Compound",aliases={"Kurzen's Compound","Kurzen’s Compound"},body="Kurzen’s Compound is an armed enclave in Stranglethorn’s jungle. Its occupants hold prisoners and endanger explorers traveling through that part of the region.",aliasQuestIDs={}},fr={title="Kurzen's Compound",body="Kurzen’s Compound est une enclave armée dans la jungle de Stranglethorn. Ses occupants détiennent des prisonniers et mettent en danger les explorateurs qui traversent cette partie de la région."},de={title="Kurzen's Compound",body="Kurzen’s Compound ist eine bewaffnete Enklave in Stranglethorn \"Dschungel. Seine Bewohner halten Gefangene fest und gefährden Entdecker, die durch diesen Teil der Region reisen."},pt={title="Kurzen's Compound",body="Kurzen’s Compound é um enclave armado na selva de Stranglethorn. Seus ocupantes mantêm prisioneiros e colocam em perigo exploradores que viajam por essa parte da região."},pl={title="Kurzen's Compound",body="Kurzen’s Compound to zbrojna enklawa w dżungli Stranglethorn. Jej mieszkańcy przetrzymują jeńców i zagrażają odkrywcom przemierzającym tę część regionu."},ru={title="Kurzen's Compound",body="Kurzen’s Compound - это вооруженный анклав в джунглях Stranglethorn. Его обитатели держат в заключении заключенных и подвергают опасности путешественников, путешествующих по этой части региона."},references={["npc:colonel-kurzen"]=true,["place:stranglethorn-vale"]=true}},
    ["place:lake-eluneara"] = {title="Lago Elune'ara",kind="Lugar",aliases={"Lago Elune'ara","Lago Elune’ara"},body="El Lago Elune'ara es un cuerpo de agua de Claro de la Luna vinculado a las prácticas de los druidas. Sus profundidades forman parte de las pruebas y los ritos que se celebran cerca de los santuarios.",aliasQuestIDs={},en={title="Lake Elune'ara",aliases={"Lake Elune'ara","Lake Elune’ara"},body="Lake Elune'ara is a body of water in Moonglade associated with druidic practices. Its depths are part of the trials and rites observed near the sanctuaries.",aliasQuestIDs={}},fr={title="Lake Elune'ara",body="Lake Elune'ara est un plan d'eau dans Moonglade associé à des pratiques druidiques. Ses profondeurs font partie des épreuves et des rites observés près des sanctuaires."},de={title="Lake Elune'ara",body="Lake Elune'ara ist bei Moonglade ein Gewässer, das mit druidischen Praktiken in Verbindung gebracht wird. Seine Tiefe ist Teil der Prozesse und Riten, die in der Nähe der Heiligtümer beobachtet werden."},pt={title="Lake Elune'ara",body="Lake Elune'ara é um corpo de água no Moonglade associado a práticas druídicas. Suas profundezas fazem parte dos ensaios e ritos observados perto dos santuários."},pl={title="Lake Elune'ara",body="Lake Elune'ara to zbiornik wodny w Moonglade związany z praktykami druidów. Jego głębiny stanowią część prób i obrzędów odbywających się w pobliżu sanktuariów."},ru={title="Lake Elune'ara",body="Lake Elune'ara - это водоем в Moonglade, связанный с друидскими практиками. Его глубины являются частью испытаний и обрядов, которые отмечаются возле святынь."},references={["place:moonglade"]=true}},
    ["place:lake-everstill"] = {title="Lago Sempiterno",kind="Lugar",aliases={"Lago Sempiterno"},body="El Lago Sempiterno es una fuente de agua para Crestagrana. El curso que desciende desde él y las criaturas que habitan sus alrededores interesan a quienes estudian la pureza de las aguas.",aliasQuestIDs={},en={title="Lake Everstill",aliases={"Lake Everstill"},body="Lake Everstill is a water source for Redridge. Its outflow and the creatures living nearby interest those studying the purity of water.",aliasQuestIDs={}},fr={title="Lake Everstill",body="Lake Everstill est une source d'eau pour Redridge. Son écoulement et les créatures vivant à proximité intéressent ceux qui étudient la pureté de l'eau."},de={title="Lake Everstill",body="Lake Everstill ist eine Wasserquelle für Redridge. Sein Abfluss und die in der Nähe lebenden Lebefindlichen Lebewesen interessieren diejenigen, die sich für die die die Reinheit des Wassers studieren."},pt={title="Lake Everstill",body="Lake Everstill é uma fonte de água para Redridge. Sua saída e as criaturas que vivem nas proximidades interessam aqueles que estudam a pureza da água."},pl={title="Lake Everstill",body="Lake Everstill jest źródłem wody dla Redridge. Odpływ i żyjące w pobliżu stworzenia interesują badaczy czystości wody."},ru={title="Lake Everstill",body="Lake Everstill - это источник воды для Redridge. Его отток и животные, живущие рядом с ним, интересуют тех, кто изучает чистоту воды."},references={["place:redridge-mountains"]=true}},
    ["place:lakeshire"] = {title="Villa del Lago",kind="Lugar",aliases={"Villa del Lago"},body="Villa del Lago es la comunidad humana que coordina la defensa de Crestagrana. Su concejo y sus guardias afrontan las amenazas de las montañas mientras los trabajadores mantienen los caminos y otras obras necesarias para la vida del poblado.",aliasQuestIDs={},en={title="Lakeshire",aliases={"Lakeshire"},body="Lakeshire is the human community coordinating Redridge’s defense. Its council and guards confront threats from the mountains while workers maintain the roads and other works needed by the settlement.",aliasQuestIDs={}},fr={title="Lakeshire",body="Lakeshire est la communauté humaine qui coordonne la défense de Redridge. Son conseil et ses gardes sont menacés par les montagnes tandis que les travailleurs entretiennent les routes et autres travaux nécessaires à la colonie."},de={title="Lakeshire",body="Lakeshire ist die menschliche Gemeinschaft, die Redridge 's Verteidigung koordiniert. Sein Rat und seine Wachen sehen sich Bedrohungen aus den Bergen ausgesetzt, während Arbeiter die Straßen und andere Arbeiten instand halten, die von der Siedlung benötigen."},pt={title="Lakeshire",body="Lakeshire é a comunidade humana que coordena a defesa do Redridge. Seu conselho e guardas enfrentam ameaças das montanhas, enquanto os trabalhadores mantêm as estradas e outras obras necessárias para o assentamento."},pl={title="Lakeshire",body="Lakeshire to ludzka osada koordynująca obronę Redridge. Jej rada i strażnicy mierzą się z zagrożeniami z gór, a robotnicy utrzymują drogi oraz inne obiekty potrzebne osadzie."},ru={title="Lakeshire",body="Lakeshire - это человеческое сообщество, координирующее защиту Redridge. Совет и охранники города сталкиваются с угрозами из горы, а рабочие обслуживают дороги и другие работы, необходимые поселению."},references={["place:redridge-mountains"]=true}},
    ["place:lethlor-ravine"] = {title="Barranco Lethlor",kind="Lugar",aliases={"Barranco Lethlor"},body="El Barranco Lethlor es una zona de las Tierras Inhóspitas marcada por pilares y piedras rúnicas. Sus sellos y la presencia de dragones negros atraen a quienes investigan la magia del lugar.",aliasQuestIDs={},en={title="Lethlor Ravine",aliases={"Lethlor Ravine"},body="Lethlor Ravine is a Badlands district marked by pillars and runestones. Its seals and the presence of black dragons draw those investigating the place’s magic.",aliasQuestIDs={}},fr={title="Lethlor Ravine",body="Lethlor Ravine est un quartier Badlands marqué par des piliers et des pierres runiques. Ses sceaux et la présence de dragons noirs attirent ceux qui enquêtent sur la magie du lieu."},de={title="Lethlor Ravine",body="Lethlor Ravine ist ein von Säulen und Runensteinen geprägtes Badlands-Viertel. Seine Siegel und die Anwesenheit schwarzer Drachen ziehen diejenigen an, die die den Zauber des Ortes erforschen."},pt={title="Lethlor Ravine",body="Lethlor Ravine é um distrito Badlands marcado por pilares e runas. Seus selos e a presença de dragões negros atraem aqueles que investigam a magia do lugar."},pl={title="Lethlor Ravine",body="Lethlor Ravine to część Badlands wyróżniająca się filarami i kamieniami runicznymi. Pieczęcie oraz obecność czarnych smoków przyciągają badaczy miejscowej magii."},ru={title="Lethlor Ravine",body="Lethlor Ravine - это район Badlands, отмеченный столбами и руновыми камнями. Его печати и присутствие черных драконов привлекают тех, кто изучает магию этого места."},references={["place:badlands"]=true}},
    ["place:lights-hope-chapel"] = {title="Capilla de la Esperanza de la Luz",kind="Lugar",aliases={"Capilla de la Esperanza de la Luz","Esperanza de la Luz"},body="La Capilla de la Esperanza de la Luz es un punto de reunión de los combatientes contra la Plaga en las Tierras de la Peste del Este. Allí trabajan combatientes, estudiosos y responsables de suministros para sostener esa lucha.",aliasQuestIDs={},en={title="Light's Hope Chapel",aliases={"Light's Hope","Light's Hope Chapel","Light’s Hope","Light’s Hope Chapel"},body="Light's Hope Chapel is a gathering place for fighters opposing the Scourge in Eastern Plaguelands. Warriors, scholars and supply officers work there to sustain that struggle.",aliasQuestIDs={}},fr={title="Light's Hope Chapel",body="Light's Hope Chapel est un lieu de rassemblement pour les combattants opposés à the Scourge dans Eastern Plaguelands. Des guerriers, des érudits et des officiers de ravitaillement y travaillent pour soutenir cette lutte."},de={title="Light's Hope Chapel",body="Light's Hope Chapel ist ein Sammelplatz für Kämpfer gegen the Scourge in Eastern Plaguelands. Krieger, Gelehrte und Nachschuboffiziere arbeiten dort, um diesen Kampf aufrechtzuerhalten."},pt={title="Light's Hope Chapel",body="Light's Hope Chapel é um local de encontro para combatentes que se opõem the Scourge em Eastern Plaguelands. Guerreiros, estudiosos e oficiais de suprimentos trabalham lá para sustentar essa luta."},pl={title="Light's Hope Chapel",body="Light's Hope Chapel jest miejscem spotkań wojowników walczących przeciw siłom znanym jako the Scourge w Eastern Plaguelands. Wojownicy, uczeni i oficerowie zaopatrzenia pracują tu, by podtrzymywać tę walkę."},ru={title="Light's Hope Chapel",body="Light's Hope Chapel - это место для сбора бойцов, противостоящих the Scourge в Eastern Plaguelands. Воины, ученые и офицеры снабжения работают там, чтобы поддерживать эту борьбу."},references={["concept:holy-light"]=true,["organization:scourge"]=true,["place:eastern-plaguelands"]=true,["place:plaguelands"]=true}},
    ["place:lions-pride-inn"] = {title="Posada Orgullo de León",kind="Lugar",aliases={"Posada Orgullo de León"},body="La Posada Orgullo de León es un punto de reunión de Villadorada. Sus viajeros y huéspedes conectan las necesidades de las granjas con los oficios y los servicios que ofrece el poblado.",aliasQuestIDs={},en={title="Lion's Pride Inn",aliases={"Lion's Pride Inn","Lion’s Pride Inn"},body="The Lion’s Pride Inn is a gathering place in Goldshire. Its travelers and guests connect the farms’ needs with the trades and services offered by the settlement.",aliasQuestIDs={}},fr={title="Lion's Pride Inn",body="Le Lion’s Pride Inn est un lieu de rassemblement dans Goldshire. Ses voyageurs et invités relient les besoins des fermes avec les métiers et les services offerts par la colonie."},de={title="Lion's Pride Inn",body="Der Lion’s Pride Inn ist ein Sammelplatz in Goldshire. Seine Reisenden und Gäste verbinden die Bedürfnisse der Höfe mit dem Gewerbe und den Dienstleistungen der Siedlung."},pt={title="Lion's Pride Inn",body="O Lion’s Pride Inn é um local de encontro em Goldshire. Seus viajantes e convidados conectam as necessidades das fazendas com os comércios e serviços oferecidos pelo assentamento."},pl={title="Lion's Pride Inn",body="Lion’s Pride Inn jest miejscem spotkań w Goldshire. Podróżni i goście łączą potrzeby gospodarstw z handlem oraz usługami oferowanymi przez osadę."},ru={title="Lion's Pride Inn",body="Lion’s Pride Inn - это место собрания в Goldshire. Его путешественники и гости связывают потребности ферм с торговлей и услугами, предлагаемыми поселением."},references={["place:goldshire"]=true}},
    ["place:loch-modan"] = {title="Loch Modan",kind="Lugar",aliases={"Loch Modan"},body="Loch Modan es una región de lago, colinas y asentamientos enanos. La caza, la exploración y las excavaciones conviven allí con amenazas como los troggs y los ataques contra quienes transportan suministros.",aliasQuestIDs={},en={title="Loch Modan",aliases={"Loch Modan"},body="Loch Modan is a region of lake waters, hills and dwarven settlements. Hunting, exploration and excavation coexist with threats such as troggs and attacks on supply convoys.",aliasQuestIDs={}},fr={title="Loch Modan",body="Loch Modan est une région d'eaux lacustres, de collines et d'établissements nains. La chasse, l'exploration et l'excavation coexistent avec des menaces telles que les trogs et les attaques contre les convois d'approvisionnement."},de={title="Loch Modan",body="Loch Modan ist eine Region mit Seen, Hügeln und Zwergensiedlungen. Jagd, Erkundung und Ausgrabungen gehen Hand in Hand in Hand mit Bedrohungen wie Troggs und Angriffen auf Versorgungskonvois."},pt={title="Loch Modan",body="Loch Modan é uma região de águas do lago, colinas e assentamentos anões. Caça, exploração e escavação coexistem com ameaças como troggs e ataques a comboios de abastecimento."},pl={title="Loch Modan",body="Loch Modan to region jeziornych wód, wzgórz i krasnoludzkich osad. Łowiectwo, wyprawy badawcze i wykopaliska współistnieją tu z zagrożeniami takimi jak troggowie oraz ataki na konwoje zaopatrzeniowe."},ru={title="Loch Modan",body="Loch Modan - это регион озерных вод, холмов и населенных пунктов карликов. Охота, разведка и раскопки сосуществуют с такими угрозами, как прорывы и нападения на конвои снабжения."},references={}},
    ["place:longshore"] = {title="Playa Larga",kind="Lugar",aliases={"Playa Larga"},body="Playa Larga recorre la costa de los Páramos de Poniente. La vida de sus peces y de los múrlocs que la habitan interesa a quienes vigilan los recursos de alimentación que necesita Ventormenta.",aliasQuestIDs={},en={title="Longshore",aliases={"Longshore"},body="Longshore stretches along Westfall’s coast. Its fish and resident murlocs interest those watching the food resources Stormwind needs.",aliasQuestIDs={}},fr={title="Longshore",body="Longshore s’étend le long de la côte de Westfall. Ses poissons et murlocs résidents intéressent ceux qui surveillent les ressources alimentaires dont Stormwind a besoin."},de={title="Longshore",body="Longshore erstreckt sich entlang der Küste von Westfall. Seine Fische und ansässigen Murloks interessieren diejenigen, die beobachten, welche die Nahrungsressourcen Stormwind braucht."},pt={title="Longshore",body="Longshore se estende ao longo da costa do Westfall. Seus peixes e murlocs residentes interessam àqueles que observam os recursos alimentares que o Stormwind precisa."},pl={title="Longshore",body="Longshore rozciąga się wzdłuż wybrzeża Westfall. Ryby i miejscowe murloki interesują osoby nadzorujące zasoby żywności potrzebne Stormwind."},ru={title="Longshore",body="Longshore простирается вдоль побережья Westfall. Рыбы и живые мурлоки интересуют тех, кто следит за потребностями Stormwind в продовольствии."},references={["place:stormwind"]=true,["place:westfall"]=true}},
    ["place:lordaeron"] = {title="Lordaeron",kind="Lugar",aliases={"Lordaeron"},body="Lordaeron es una tierra marcada por la guerra y la expansión de la Plaga. Sus antiguas ciudades, fincas y aldeas siguen siendo hogares disputados para supervivientes y no-muertos.",aliasQuestIDs={},en={title="Lordaeron",aliases={"Lordaeron"},body="Lordaeron is a land marked by war and the Scourge's spread. Its former cities, estates and villages remain contested homes for survivors and undead.",aliasQuestIDs={}},fr={title="Lordaeron",body="Lordaeron est une terre marquée par la guerre et la propagation de the Scourge. Ses anciennes villes, domaines et villages restent des maisons contestées pour les survivants et les morts-vivants."},de={title="Lordaeron",body="Lordaeron ist ein Land, das von Krieg und Verbreitung durch the Scourge gekennzeichnet ist. Seine ehemaligen Städte, Ländereien und Dörfer bleiben umkämpfte Heime für Überlebende und Untote."},pt={title="Lordaeron",body="Lordaeron é uma terra marcada pela guerra e pela disseminação de the Scourge. Suas antigas cidades, propriedades e aldeias continuam sendo casas contestadas para sobreviventes e mortos-vivos."},pl={title="Lordaeron",body="Lordaeron jest krainą naznaczoną wojną i ekspansją sił znanych jako the Scourge. Jej dawne miasta, posiadłości i wioski pozostają domami, o które rywalizują ocalali i nieumarli."},ru={title="Lordaeron",body="Lordaeron - это земля, отмеченная войной и распространением the Scourge. Его бывшие города, поместья и деревни остаются спорными домами для выживших и не мертвых."},references={["organization:scourge"]=true}},
    ["place:lordamere-lake"] = {title="Lago Lordamere",kind="Lugar",aliases={"Lago Lordamere","Lago de Lordamere"},body="El Lago Lordamere alberga islas y criaturas acuáticas al este del Bosque de Argénteos. En sus orillas se encuentra la residencia de Aliden Perenolde, de modo que el lago también sirve como referencia para los asentamientos de la zona.",aliasQuestIDs={},en={title="Lordamere Lake",aliases={"Lake Lordamere","Lordamere Lake"},body="Lordamere Lake contains islands and aquatic creatures east of Silverpine Forest. Aliden Perenolde's residence stands on its shores, making the lake a landmark for settlements in the area.",aliasQuestIDs={}},fr={title="Lordamere Lake",body="Lordamere Lake abrite des îles et des créatures aquatiques à l'est de Silverpine Forest. La résidence d'Aliden Perenolde se trouve sur ses rives, faisant du lac un repère pour les établissements de la région."},de={title="Lordamere Lake",body="Lordamere Lake enthält Inseln und Wassertiere östlich von Silverpine Forest. Die Residenz von Aliden Perenolde steht direkt am Ufer und macht den See zu einem Wahrzeichen für die Siedlungen in der Umgebung."},pt={title="Lordamere Lake",body="Lordamere Lake contém ilhas e criaturas aquáticas a leste de Silverpine Forest. A residência de Aliden Perenolde está em suas margens, tornando o lago um marco para assentamentos na área."},pl={title="Lordamere Lake",body="Lordamere Lake mieści wyspy i wodne stworzenia na wschód od Silverpine Forest. Siedziba Aliden Perenolde stoi nad jego brzegami, czyniąc jezioro punktem orientacyjnym okolicznych osad."},ru={title="Lordamere Lake",body="Lordamere Lake содержит острова и водные существа к востоку от Silverpine Forest. Жилье Aliden Perenolde стоит на его берегу, что делает озеро ориентиром для поселений в этом районе."},references={["npc:lord-aliden-perenolde"]=true,["place:silverpine-forest"]=true}},
    ["place:maclure-vineyards"] = {title="Viñedos de Maclure",kind="Lugar",aliases={"Los Viñedos de Maclure","Viñedos de Maclure"},body="Los Viñedos de Maclure forman parte de las tierras agrícolas de Elwynn. La vida de su familia está relacionada con los cultivos, los intercambios y las rivalidades entre granjas vecinas.",aliasQuestIDs={},en={title="Maclure Vineyards",aliases={"Maclure Vineyards"},body="Maclure Vineyards are part of Elwynn’s farming lands. The family’s life is connected with crops, exchanges and rivalries between neighboring farms.",aliasQuestIDs={}},fr={title="Maclure Vineyards",body="Maclure Vineyards fait partie des terres agricoles de Elwynn. La vie de la famille est liée aux cultures, aux échanges et aux rivalités entre les fermes voisines."},de={title="Maclure Vineyards",body="Maclure Vineyards gehört zu Elwynn \"Ackerland. Das Leben der Familie ist mit Ernten, Austausch und Rivalitäten zwischen benachbarten Höfen verbunden."},pt={title="Maclure Vineyards",body="Maclure Vineyards fazem parte das terras agrícolas da Elwynn. A vida da família está ligada a culturas, trocas e rivalidades entre fazendas vizinhas."},pl={title="Maclure Vineyards",body="Maclure Vineyards należą do rolniczych terenów Elwynn. Życie rodziny wiąże się z uprawami, wymianą i rywalizacją między sąsiednimi gospodarstwami."},ru={title="Maclure Vineyards",body="Maclure Vineyards являются частью сельскохозяйственных угодий Elwynn. Жизнь семьи связана с посевом, обменом и соперничеством между соседними фермами."},references={["place:elwynn-forest"]=true}},
    ["place:maelstrom"] = {title="La Vorágine",kind="Lugar",aliases={"La Vorágine","Vorágine"},body="La Vorágine es un lugar del mar al que viajan grandes cazadores Zandalar para demostrar su determinación. De sus límites obtienen algas con las que tejen talismanes, vinculando una prueba de valor con la artesanía mágica de la tribu.",aliasQuestIDs={},en={title="The Maelstrom",aliases={"Maelstrom","The Maelstrom"},body="The Maelstrom is a place in the sea to which great Zandalar hunters travel to prove their resolve. From its edges they gather kelp for woven talismans, linking a test of courage with the tribe's magical craftsmanship.",aliasQuestIDs={}},fr={title="The Maelstrom",body="The Maelstrom est un endroit dans la mer où les grands chasseurs de Zandalar voyagent pour prouver leur détermination. De ses bords, ils rassemblent varech pour les talismans tissés, reliant un test de courage avec l'artisanat magique de la tribu."},de={title="The Maelstrom",body="The Maelstrom ist ein Ort im Meer, an den große Zandalar-Jäger reisen, um ihre Entschlossenheit unter Beweis zu stellen. An ihren Rändern sammeln sie Seetang für geflochtene Talismane und verbinden so eine Mutprobe mit dem magischen Handwerk des Stammes."},pt={title="The Maelstrom",body="The Maelstrom é um lugar no mar para o qual grandes caçadores Zandalar viajam para provar sua determinação. De suas bordas eles coletam algas para talismãs tecidos, ligando um teste de coragem com o artesanato mágico da tribo."},pl={title="The Maelstrom",body="The Maelstrom jest miejscem na morzu, do którego wielcy łowcy Zandalar podróżują, by dowieść determinacji. Z jego obrzeży zbierają wodorosty na plecione talizmany, łącząc próbę odwagi z magicznym rzemiosłem plemienia."},ru={title="The Maelstrom",body="The Maelstrom - это место в море, куда путешествуют великие охотники Zandalar, чтобы доказать свою решимость. С его краев они собирают водоросли для тканевых талисманов, связывая испытание мужества с магическим мастерством племени."},references={["organization:zandalar-tribe"]=true}},
    ["place:mannoroc-coven"] = {title="Aquelarre Mannoroc",kind="Lugar",aliases={"Aquelarre Mannoroc","Mannoroc"},body="El Aquelarre Mannoroc es un enclave de Desolace relacionado con brujos e invocadores del Filo Ardiente. Allí se utilizan objetos que contienen poder demoníaco, señal del tipo de magia practicada en el lugar.",aliasQuestIDs={},en={title="Mannoroc Coven",aliases={"Mannoroc","Mannoroc Coven"},body="Mannoroc Coven is an enclave in Desolace associated with Burning Blade warlocks and summoners. Objects containing demonic power are used there, reflecting the magic practiced at the site.",aliasQuestIDs={}},fr={title="Mannoroc Coven",body="Mannoroc Coven est une enclave dans Desolace associée aux démons et aux invocateurs Burning Blade. Des objets contenant un pouvoir démoniaque y sont utilisés, reflétant la magie pratiquée sur le site."},de={title="Mannoroc Coven",body="Mannoroc Coven ist eine Enklave in Desolace, die mit Burning Blade Hexenmeistern und Beschwörern in Verbindung steht. Objekte mit dämonischer Macht werden dort verwendet, was die dort praktizierte Magie widerspiegelt."},pt={title="Mannoroc Coven",body="Mannoroc Coven é um enclave no Desolace associado a feiticeiros e invocadores Burning Blade. Objetos contendo poder demoníaco são usados lá, refletindo a magia praticada no local."},pl={title="Mannoroc Coven",body="Mannoroc Coven to enklawa w Desolace związana z czarnoksiężnikami i przywoływaczami Burning Blade. Wykorzystywane są tam przedmioty zawierające demoniczną moc, odzwierciedlające magię praktykowaną w tym miejscu."},ru={title="Mannoroc Coven",body="Mannoroc Coven - это анклав в Desolace, связанный с чернокнижниками и призывателями Burning Blade. Там используются предметы, содержащие демоническую силу, отражающие магию, практикуемую на этом месте."},references={["organization:burning-blade"]=true,["place:desolace"]=true},questIDs={[1799]=true,[1954]=true,[4783]=true,[5381]=true,[5581]=true,[5943]=true}},
    ["place:maraudon"] = {title="Maraudon",kind="Lugar",aliases={"Maraudon"},body="Maraudon es un antiguo complejo de cuevas de Desolace ligado a los centauros. Sus recintos reúnen fuerzas de la naturaleza y focos de corrupción que han alterado el equilibrio de sus cavernas.",aliasQuestIDs={},en={title="Maraudon",aliases={"Maraudon"},body="Maraudon is an ancient cave complex in Desolace tied to the centaurs. Its chambers bring together forces of nature and sources of corruption that have disturbed the balance of its caverns.",aliasQuestIDs={}},fr={title="Maraudon",body="Maraudon est un ancien complexe de grottes dans Desolace lié aux centaures. Ses chambres rassemblent des forces de la nature et des sources de corruption qui ont perturbé l’équilibre de ses cavernes."},de={title="Maraudon",body="Maraudon ist ein uralter Höhlenkomplex in Desolace, der an die Kentauren gebunden ist. Seine Kammern bringen Naturgewalten und Korruptionsquellen zusammen, die das Gleichgewicht seiner Höhlen gestört haben."},pt={title="Maraudon",body="Maraudon é um antigo complexo de cavernas em Desolace amarrado aos centauros. Suas câmaras reúnem forças da natureza e fontes de corrupção que perturbaram o equilíbrio de suas cavernas."},pl={title="Maraudon",body="Maraudon to pradawny kompleks jaskiń w Desolace związany z centaurami. W jego komnatach spotykają się siły natury i źródła skażenia, które zakłóciły równowagę podziemi."},ru={title="Maraudon",body="Maraudon - это древний пещерный комплекс в Desolace, связанный с кентаврами. В его камерах соединяются силы природы и источники разложения, нарушающие равновесие пещер."},references={["place:desolace"]=true}},
    ["place:marshals-refuge"] = {title="Refugio de Marshal",kind="Lugar",aliases={"Refugio de Marshal"},body="El Refugio de Marshal es un campamento de expedicionarios en el Cráter de Un'Goro. Ofrece un lugar desde el que investigar la región y organizar la supervivencia de quienes han llegado para estudiarla.",aliasQuestIDs={},en={title="Marshal's Refuge",aliases={"Marshal's Refuge","Marshal’s Refuge"},body="Marshal's Refuge is an expedition camp in Un'Goro Crater. It provides a base for investigating the region and organizing the survival of those who have come to study it.",aliasQuestIDs={}},fr={title="Marshal's Refuge",body="Marshal's Refuge est un camp d'expédition à Un'Goro Crater. Il fournit une base pour enquêter sur la région et organiser la survie de ceux qui sont venus l'étudier."},de={title="Marshal's Refuge",body="Marshal's Refuge ist ein Expeditionslager in Un'Goro Crater. Sie bietet eine Grundlage für die Erforschung der Region und die Organisation des Überlebens derjenigen, die gekommen sind, um sie zu studieren."},pt={title="Marshal's Refuge",body="Marshal's Refuge é um acampamento de expedição em Un'Goro Crater. Ele fornece uma base para investigar a região e organizar a sobrevivência daqueles que vieram estudá-la."},pl={title="Marshal's Refuge",body="Marshal's Refuge to obóz ekspedycyjny w Un'Goro Crater. Stanowi bazę do badania regionu oraz organizowania przetrwania tych, którzy przybyli go poznawać."},ru={title="Marshal's Refuge",body="Marshal's Refuge - это экспедиционный лагерь в Un'Goro Crater. Он дает основу для исследования региона и организации выживания тех, кто пришел его изучить."},references={["place:ungoro-crater"]=true}},
    ["place:masters-glaive"] = {title="La Espada del Maestro",kind="Lugar",aliases={"Espada del Maestro","La Espada del Maestro"},body="La Espada del Maestro es un lugar de Costa Oscura frecuentado por seguidores del Martillo Crepuscular. Sus restos atraen un interés religioso oscuro y convierten el paraje en algo más que una simple ruina.",aliasQuestIDs={},en={title="Master's Glaive",aliases={"Master's Glaive","Master’s Glaive","The Master's Glaive","The Master’s Glaive"},body="The Master’s Glaive is a site in Darkshore frequented by followers of the Twilight’s Hammer. Its remains attract dark religious interest, making it more than a simple ruin.",aliasQuestIDs={}},fr={title="Master's Glaive",body="The Master’s Glaive est un site en Darkshore fréquenté par les adeptes de la Twilight’s Hammer. Ses restes attirent un intérêt religieux sombre, ce qui en fait plus qu'une simple ruine."},de={title="Master's Glaive",body="The Master’s Glaive ist eine Seite in Darkshore, die von Twilight’s Hammer-Anhängern frequentiert wird. Ihre Überreste ziehen dunkles religiöses Interesse auf sich und machen sie mehr als nur zu einer bloßen Ruine."},pt={title="Master's Glaive",body="The Master’s Glaive é um site em Darkshore frequentado por seguidores do Twilight’s Hammer. Seus restos mortais atraem interesse religioso sombrio, tornando-o mais do que uma simples ruína."},pl={title="Master's Glaive",body="The Master’s Glaive to miejsce w Darkshore odwiedzane przez wyznawców Twilight’s Hammer. Jego pozostałości budzą mroczne zainteresowanie religijne, czyniąc je czymś więcej niż zwykłą ruiną."},ru={title="Master's Glaive",body="The Master’s Glaive - это сайт в Darkshore, посещаемый последователями Twilight’s Hammer. Его останки привлекают глубокий религиозный интерес, что делает его больше, чем просто руиной."},references={["organization:twilights-hammer"]=true,["place:darkshore"]=true}},
    ["place:menethil-harbor"] = {title="Puerto de Menethil",kind="Lugar",aliases={"Menethil","Puerto de Menethil"},body="Puerto de Menethil es una comunidad portuaria de los Humedales que conecta las rutas marítimas con los caminos del interior. El castillo y sus autoridades forman parte de la protección y la administración del puerto.",aliasQuestIDs={},en={title="Menethil Harbor",aliases={"Menethil","Menethil Harbor"},body="Menethil Harbor is a Wetlands port connecting sea routes with roads into the interior. Its castle and officials form part of the port’s defense and administration.",aliasQuestIDs={}},fr={title="Menethil Harbor",body="Menethil Harbor est un port Wetlands reliant les routes maritimes avec les routes à l'intérieur. Son château et ses fonctionnaires font partie de la défense et de l'administration du port."},de={title="Menethil Harbor",body="Menethil Harbor ist ein Wetlands-Hafen, der Seewege mit Straßen ins Landesinnere verbindet. Seine Burg und seine Beamten sind Teil der Verteidigung und Verwaltung des Hafens."},pt={title="Menethil Harbor",body="Menethil Harbor é um porto Wetlands que conecta rotas marítimas com estradas para o interior. Seu castelo e funcionários fazem parte da defesa e administração do porto."},pl={title="Menethil Harbor",body="Menethil Harbor to port w Wetlands łączący szlaki morskie z drogami w głąb lądu. Zamek i urzędnicy stanowią część jego systemu obrony oraz administracji."},ru={title="Menethil Harbor",body="Menethil Harbor - это порт Wetlands, соединяющий морские пути с дорогами вглубь страны. Замок и чиновники являются частью обороны и администрации порта."},references={["person:zamek"]=true,["place:wetlands"]=true}},
    ["place:mirror-lake"] = {title="Lago Espejo",kind="Lugar",aliases={"Lago Espejo"},body="El Lago Espejo es una masa de agua del Bosque de Elwynn que también interesa a los estudiosos de la magia. Sus aguas pueden servir como muestras para investigar los cambios en las corrientes arcanas del mundo.",aliasQuestIDs={},en={title="Mirror Lake",aliases={"Mirror Lake"},body="Mirror Lake is a body of water in Elwynn Forest that also interests students of magic. Samples from its waters help investigate changes in the world’s arcane currents.",aliasQuestIDs={}},fr={title="Mirror Lake",body="Mirror Lake est un plan d'eau dans Elwynn Forest qui intéresse également les étudiants en magie. Des échantillons provenant de ses eaux aident à étudier les changements dans les courants arcaniques du monde."},de={title="Mirror Lake",body="Mirror Lake ist in Elwynn Forest ein Gewässer, das auch Zauberschüler interessiert. Proben aus seinen Gewässern tragen dazu bei, Veränderungen in den geheimnisvollen Strömungen der Welt zu untersuchen."},pt={title="Mirror Lake",body="Mirror Lake é um corpo de água no Elwynn Forest que também interessa aos estudantes de magia. Amostras de suas águas ajudam a investigar mudanças nas correntes arcanas do mundo."},pl={title="Mirror Lake",body="Mirror Lake to zbiornik wodny w Elwynn Forest, którym interesują się również adepci magii. Próbki jego wody pomagają badać zmiany w magicznych prądach świata."},ru={title="Mirror Lake",body="Mirror Lake - это водоем в Elwynn Forest, который также интересует студентов магии. Образцы из его вод помогают исследовать изменения в таинственных течениях мира."},references={["place:elwynn-forest"]=true}},
    ["place:molten-core"] = {title="Núcleo de Magma",kind="Lugar",aliases={"Núcleo de Magma"},body="El Núcleo de Magma se encuentra en las profundidades de Roca Negra, cerca del dominio del Señor del Fuego. Las grietas y pasos hacia su interior interesan a quienes investigan los vínculos entre el mundo y los poderes elementales.",aliasQuestIDs={},en={title="Molten Core",aliases={"Molten Core"},body="The Molten Core lies deep beneath Blackrock, close to the Firelord’s domain. Rifts and passages leading inside interest those studying the connections between the world and elemental powers.",aliasQuestIDs={}},fr={title="Molten Core",body="Le Molten Core se trouve profondément sous le Blackrock, à proximité du domaine du Firelord. Les failles et les passages menant à l'intérieur intéressent ceux qui étudient les liens entre le monde et les pouvoirs élémentaires."},de={title="Molten Core",body="Der Molten Core liegt tief unter Blackrock, in der Nähe der Domäne des Firelord. Risse und Passagen, die ins Innere führen, interessieren diejenigen, die die die sich mit den Verbindungen zwischen der Welt und den Urmächten beschäftigen."},pt={title="Molten Core",body="O Molten Core encontra-se profundamente abaixo de Blackrock, perto do domínio do Firelord. Rifts e passagens que levam a interesse interior aqueles que estudam as conexões entre o mundo e poderes elementais."},pl={title="Molten Core",body="Molten Core leży głęboko pod Blackrock, blisko domeny Firelord. Szczeliny i przejścia do jego wnętrza interesują badaczy więzi między światem a mocami żywiołów."},ru={title="Molten Core",body="Molten Core находится глубоко под Blackrock, близко к домену Firelord s. Разломы и проходы, ведущие внутрь интересуют тех, кто изучает связи между миром и элементарными силами."},references={}},
    ["place:moonbrook"] = {title="Arroyo de la Luna",kind="Lugar",aliases={"Arroyo de la Luna"},body="Arroyo de la Luna es un poblado de los Páramos de Poniente vinculado a la minería. Sus edificios, incluida la antigua escuela, conservan rastros de la vida de una comunidad desplazada por la inseguridad de la región.",aliasQuestIDs={},en={title="Moonbrook",aliases={"Moonbrook"},body="Moonbrook is a Westfall settlement associated with mining. Its buildings, including the old schoolhouse, preserve traces of a community displaced by the region’s insecurity.",aliasQuestIDs={}},fr={title="Moonbrook",body="Moonbrook est un règlement Westfall associé à l'exploitation minière. Ses bâtiments, dont l’ancienne école, conservent les traces d’une communauté déplacée par l’insécurité de la région."},de={title="Moonbrook",body="Moonbrook ist eine mit dem Bergbau verbundene Westfall-Siedlung. Seine Gebäude, einschließlich des alten Schulhauses, bewahren die Spuren einer Gemeinschaft, die durch die Unsicherheit der Region vertrieben wurde."},pt={title="Moonbrook",body="Moonbrook é um assentamento Westfall associado à mineração. Seus edifícios, incluindo a antiga escola, preservam vestígios de uma comunidade deslocada pela insegurança da região."},pl={title="Moonbrook",body="Moonbrook to osada w Westfall związana z górnictwem. Jej budynki, w tym dawna szkoła, zachowują ślady społeczności wypartej przez brak bezpieczeństwa w regionie."},ru={title="Moonbrook",body="Moonbrook - это поселение Westfall, связанное с добычей полезных ископаемых. В зданиях, в том числе и в старой школе, сохранились следы общины, перемещенной из-за нестабильности в регионе."},references={["place:westfall"]=true}},
    ["place:moonglade"] = {title="Claro de la Luna",kind="Lugar",aliases={"Claro de la Luna"},body="Claro de la Luna es un refugio de los druidas de Kalimdor. Sus santuarios, guardianes y aguas sagradas sirven a una tradición que busca comprender la naturaleza y preservar su equilibrio.",aliasQuestIDs={},en={title="Moonglade",aliases={"Moonglade"},body="Moonglade is a sanctuary for the druids of Kalimdor. Its shrines, guardians and sacred waters serve a tradition devoted to understanding nature and preserving its balance.",aliasQuestIDs={}},fr={title="Moonglade",body="Moonglade est un sanctuaire pour les druides de Kalimdor. Ses sanctuaires, ses gardiens et ses eaux sacrées servent une tradition consacrée à la compréhension de la nature et à la préservation de son équilibre."},de={title="Moonglade",body="Moonglade ist ein Zufluchtsort für die Druiden von Kalimdor. Seine Schreine, Wächter und heiligen Gewässer dienen einer Tradition, die sich dem Verständnis der Natur und der Erhaltung ihres Gleichgewichts widmet."},pt={title="Moonglade",body="Moonglade é um santuário para os druidas de Kalimdor. Seus santuários, guardiões e águas sagradas servem uma tradição dedicada à compreensão da natureza e à preservação de seu equilíbrio."},pl={title="Moonglade",body="Moonglade to sanktuarium druidów kontynentu Kalimdor. Jego kapliczki, strażnicy i święte wody służą tradycji poświęconej poznawaniu przyrody oraz zachowaniu jej równowagi."},ru={title="Moonglade",body="Moonglade - это убежище для друидов Kalimdor. Его святыни, хранители и священные воды служат традиции, посвященной пониманию природы и сохранению ее равновесия."},references={["place:kalimdor"]=true}},
    ["place:morgans-vigil"] = {title="Vigilia de Morgan",kind="Lugar",aliases={"Vigilia de Morgan"},body="La Vigilia de Morgan es un puesto de la Alianza en las Estepas Ardientes. Sus mandos sostienen las operaciones en torno a Roca Negra y reciben noticias de quienes se adentran en sus fortalezas.",aliasQuestIDs={},en={title="Morgan's Vigil",aliases={"Morgan's Vigil","Morgan’s Vigil"},body="Morgan’s Vigil is an Alliance post in the Burning Steppes. Its officers support operations around Blackrock and receive reports from those who venture into its strongholds.",aliasQuestIDs={}},fr={title="Morgan's Vigil",body="Morgan’s Vigil est un poste Alliance dans le Burning Steppes. Ses officiers soutiennent les opérations autour de Blackrock et reçoivent des rapports de ceux qui s'aventurent dans ses bastions."},de={title="Morgan's Vigil",body="Morgan’s Vigil ist ein Alliance im Burning Steppes. Seine Offiziere unterstützen die Operationen rund um Blackrock und erhalten Berichte von denjenigen, die sich in seine Hochburgen wagen."},pt={title="Morgan's Vigil",body="Morgan’s Vigil é um post Alliance no Burning Steppes. Seus oficiais apoiam operações em torno do Blackrock e recebem relatórios daqueles que se aventuram em suas fortalezas."},pl={title="Morgan's Vigil",body="Morgan’s Vigil to posterunek Alliance w Burning Steppes. Jego oficerowie wspierają działania wokół Blackrock i przyjmują meldunki od tych, którzy zapuszczają się do tamtejszych warowni."},ru={title="Morgan's Vigil",body="Morgan’s Vigil - это пост Alliance в Burning Steppes. Его офицеры поддерживают операции вокруг Blackrock и получают сообщения от тех, кто входит в его оплоты."},references={["organization:alliance"]=true,["place:burning-steppes"]=true}},
    ["place:mount-kajaro"] = {title="Monte Kajaro",kind="Lugar",aliases={"Monte Kajaro"},body="El Monte Kajaro se encuentra en los Mares del Sur y es conocido por sus erupciones violentas, a menudo mágicas. Los fragmentos de su roca pueden incorporarse a talismanes que canalizan una parte de ese poder volcánico.",aliasQuestIDs={},en={title="Mount Kajaro",aliases={"Mount Kajaro"},body="Mount Kajaro stands in the South Seas and is known for violent, often magical eruptions. Fragments of its rock can be set into talismans channeling part of that volcanic power.",aliasQuestIDs={}},fr={title="Mount Kajaro",body="Mount Kajaro se trouve dans le South Seas et est connu pour ses éruptions violentes, souvent magiques. Des fragments de sa roche peuvent être mis en talismans canalisant une partie de cette puissance volcanique."},de={title="Mount Kajaro",body="Mount Kajaro steht im South Seas und ist für gewalttätige, oft magische Ausbrüche bekannt. Fragmente seines Gesteins lassen sich in Talismane verwandeln, die einen Teil dieser vulkanischen Kraft kanalisieren."},pt={title="Mount Kajaro",body="Mount Kajaro está no South Seas e é conhecido por erupções violentas, muitas vezes mágicas. Fragmentos de sua rocha podem ser colocados em talismãs canalizando parte desse poder vulcânico."},pl={title="Mount Kajaro",body="Mount Kajaro stoi na South Seas i słynie z gwałtownych, często magicznych erupcji. Odłamki skał można osadzać w talizmanach skupiających część tej wulkanicznej mocy."},ru={title="Mount Kajaro",body="Mount Kajaro - это South Seas и известен своими жестокими, часто магическими извержениями. Фрагменты его скалы могут быть установлены в талисманы, направляющие часть этой вулканической энергии."},references={["place:south-seas"]=true}},
    ["place:mount-mugamba"] = {title="Monte Mugamba",kind="Lugar",aliases={"Monte Mugamba"},body="El Monte Mugamba es un lugar ligado a las tradiciones de la tribu Zandalar y al origen de Jin'rokh. Su fuerza se invoca mediante talismanes que representan tenacidad y poder para quienes reciben el reconocimiento de la tribu.",aliasQuestIDs={},en={title="Mount Mugamba",aliases={"Mount Mugamba"},body="Mount Mugamba is connected with Zandalar traditions and Jin'rokh's origins. Its strength is invoked through talismans representing tenacity and power for those receiving the tribe's recognition.",aliasQuestIDs={}},fr={title="Mount Mugamba",body="Mount Mugamba est connecté avec Zandalar traditions et Jin'rokh 's origines. Sa force est invoquée par des talismans représentant la ténacité et le pouvoir pour ceux qui reçoivent la reconnaissance de la tribu."},de={title="Mount Mugamba",body="Mount Mugamba ist mit den Traditionen von Zandalar und den Ursprüngen von Jin'rokh verbunden. Seine Stärke wird durch Talismane beschworen, die Beharrlichkeit und Macht für diejenigen repräsentieren, die die die Anerkennung des Stammes erhalten."},pt={title="Mount Mugamba",body="Mount Mugamba está conectado com as tradições Zandalar e as origens de Jin'rokh. Sua força é invocada através de talismãs que representam tenacidade e poder para aqueles que recebem o reconhecimento da tribo."},pl={title="Mount Mugamba",body="Mount Mugamba wiąże się z tradycjami Zandalar i pochodzeniem Jin'rokh. Jej siłę przywołują talizmany reprezentujące wytrwałość i moc dla otrzymujących uznanie plemienia."},ru={title="Mount Mugamba",body="Mount Mugamba связано с традициями Zandalar и происхождением Jin'rokh. Его сила призвана через талисманы, представляющие стойкость и силу для тех, кто получает признание племени."},references={["npc:jinrokh-the-breaker"]=true,["organization:zandalar-tribe"]=true}},
    ["place:mulgore"] = {title="Mulgore",kind="Lugar",aliases={"Mulgore"},body="Mulgore es una región de praderas y mesetas que sirve de hogar a los tauren. La caza y el cuidado de los pozos de agua sostienen a sus comunidades, mientras los ancestros enseñan a respetar a la Madre Tierra.",aliasQuestIDs={},en={title="Mulgore",aliases={"Mulgore"},body="Mulgore is a land of grasslands and mesas that serves as a home for the tauren. Hunting and care for the water wells sustain its communities, while the elders teach respect for the Earth Mother.",aliasQuestIDs={}},fr={title="Mulgore",body="Mulgore est une terre de prairies et de mesas qui sert de maison pour les taurens. La chasse et les soins pour les puits d'eau soutiennent ses communautés, tandis que les aînés enseignent le respect pour le Earth Mother."},de={title="Mulgore",body="Mulgore ist ein Land voller Wiesen und Tafelberge, das den Tauren als Heimat dient. Jagd und Pflege der Brunnen erhalten die Gemeinschaften, während die Ältesten Respekt für die Earth Mother lehren."},pt={title="Mulgore",body="Mulgore é uma terra de pastagens e mesas que serve como um lar para os tauren. A caça e o cuidado com os poços de água sustentam suas comunidades, enquanto os anciãos ensinam respeito pelo Earth Mother."},pl={title="Mulgore",body="Mulgore to kraina trawiastych równin i płaskowyżów, będąca domem taurenów. Polowania i troska o studnie zapewniają utrzymanie społecznościom, a starszyzna uczy szacunku dla istoty zwanej Earth Mother."},ru={title="Mulgore",body="Mulgore - это земля лугов и меса, которая служит домом для таурен. Охота и забота о колодцах поддерживают его общины, в то время как старейшины учат уважению к Earth Mother."},references={["person:earth-mother"]=true}},
    ["place:naxxramas"] = {title="Naxxramas",kind="Lugar",aliases={"Naxxramas"},body="Naxxramas es una ciudadela flotante de la Plaga ligada a Kel'Thuzad. Alberga tropas y armaduras profanadas arrebatadas a defensores caídos, mientras sus resguardos dificultan el acceso de los enemigos.",aliasQuestIDs={},en={title="Naxxramas",aliases={"Naxxramas"},body="Naxxramas is a floating Scourge citadel associated with Kel'Thuzad. It holds troops and desecrated armor stripped from fallen defenders, while its wards obstruct enemy access.",aliasQuestIDs={}},fr={title="Naxxramas",body="Naxxramas est une citadelle flottante Scourge associée à Kel'Thuzad. Il détient des troupes et des armures profanées dépouillées des défenseurs tombés, tandis que ses quartiers entravent l'accès de l'ennemi."},de={title="Naxxramas",body="Naxxramas ist eine schwimmende Scourge-Zitadelle Zitadelle, die mit Kel'Thuzad in Verbindung gebracht wird. Es hält Truppen und geschändete Rüstungen, die gefallenen Verteidigern entzogen wurden, während seine Münzen den Zugang des Feindes Feindes Gegners versperren."},pt={title="Naxxramas",body="Naxxramas é uma cidadela Scourge flutuante associada ao Kel'Thuzad. Ele mantém tropas e armaduras profanadas despojadas de defensores caídos, enquanto suas alas obstruem o acesso inimigo."},pl={title="Naxxramas",body="Naxxramas jest latającą cytadelą Scourge związaną z Kel'Thuzad. Mieści wojska i zbezczeszczone pancerze zdarte z poległych obrońców, a magiczne osłony utrudniają dostęp wrogom."},ru={title="Naxxramas",body="Naxxramas - это плавучая цитадель Scourge, связанная с Kel'Thuzad. В нем хранятся войска и оскверненная броня, лишенная погибших защитников, в то время как его приборы препятствуют доступу врага."},references={["npc:kelthuzad"]=true,["organization:scourge"]=true}},
    ["place:nethergarde-keep"] = {title="Castillo de Nethergarde",kind="Lugar",aliases={"Castillo de Nethergarde","Nethergarde"},body="El Castillo de Nethergarde es una fortaleza de las Tierras Devastadas. Sus habitantes y visitantes forman parte de la presencia que vigila una región marcada por la magia peligrosa y por el Portal Oscuro.",aliasQuestIDs={},en={title="Nethergarde Keep",aliases={"Nethergarde","Nethergarde Keep"},body="Nethergarde Keep is a fortress in the Blasted Lands. Its inhabitants and visitors form part of the watch over a region marked by dangerous magic and the Dark Portal.",aliasQuestIDs={}},fr={title="Nethergarde Keep",body="Nethergarde Keep est une forteresse dans le Blasted Lands. Ses habitants et visiteurs font partie de la veille sur une région marquée par la magie dangereuse et la Dark Portal."},de={title="Nethergarde Keep",body="Nethergarde Keep ist eine Festung im Blasted Lands. Seine Bewohner und Besucher sind Teil der Wache über eine Region, die von gefährlicher Magie und Dark Portal gekennzeichnet ist."},pt={title="Nethergarde Keep",body="Nethergarde Keep é uma fortaleza no Blasted Lands. Seus habitantes e visitantes fazem parte do relógio sobre uma região marcada por magia perigosa e o Dark Portal."},pl={title="Nethergarde Keep",body="Nethergarde Keep to twierdza w Blasted Lands. Jej mieszkańcy i goście uczestniczą w czuwaniu nad regionem naznaczonym niebezpieczną magią oraz obecnością Dark Portal."},ru={title="Nethergarde Keep",body="Nethergarde Keep - это крепость в Blasted Lands. Ее жители и посетители являются частью охраны региона, отмеченного опасной магией и Dark Portal."},references={["place:blasted-lands"]=true,["place:dark-portal"]=true}},
    ["place:nighthaven"] = {title="Amparo de la Noche",kind="Lugar",aliases={"Amparo de la Noche"},body="Amparo de la Noche es un asentamiento de Claro de la Luna. Es un punto de encuentro para druidas y visitantes que acuden a buscar orientación, formación o ayuda frente a las amenazas al mundo natural.",aliasQuestIDs={},en={title="Nighthaven",aliases={"Nighthaven"},body="Nighthaven is a settlement in Moonglade. It is a meeting place for druids and visitors seeking guidance, training or help against threats to the natural world.",aliasQuestIDs={}},fr={title="Nighthaven",body="Nighthaven est un règlement dans Moonglade. C'est un lieu de rencontre pour les druides et les visiteurs à la recherche d'orientation, de formation ou d'aide contre les menaces pour le monde naturel."},de={title="Nighthaven",body="Nighthaven ist eine Siedlung in Moonglade. Es ist ein Treffpunkt für Druiden und Besucher, die Anleitung, Training oder Hilfe gegen Bedrohungen der Natur suchen."},pt={title="Nighthaven",body="Nighthaven é um assentamento em Moonglade. É um ponto de encontro para druidas e visitantes que buscam orientação, treinamento ou ajuda contra ameaças ao mundo natural."},pl={title="Nighthaven",body="Nighthaven to osada w Moonglade. Jest miejscem spotkań druidów i przybyszów szukających wskazówek, szkolenia lub pomocy przeciw zagrożeniom dla świata przyrody."},ru={title="Nighthaven",body="Nighthaven - это поселение в Moonglade. Это место встречи друидов и посетителей, ищущих руководства, обучения или помощи против угроз для природы."},references={["place:moonglade"]=true}},
    ["place:nijels-point"] = {title="Punta de Nijel",kind="Lugar",aliases={"Punta de Nijel"},body="Punta de Nijel es un asentamiento de la Alianza en Desolace. Sirve de apoyo a expediciones y viajeros en una región donde los conflictos con centauros y otros grupos hacen difícil mantener una presencia estable.",aliasQuestIDs={},en={title="Nijel's Point",aliases={"Nijel's Point","Nijel’s Point"},body="Nijel’s Point is an Alliance settlement in Desolace. It supports expeditions and travelers in a region where conflicts with centaurs and other groups make a stable presence difficult.",aliasQuestIDs={}},fr={title="Nijel's Point",body="Nijel’s Point est un règlement Alliance dans Desolace. Il soutient les expéditions et les voyageurs dans une région où les conflits avec les centaures et d’autres groupes rendent difficile une présence stable."},de={title="Nijel's Point",body="Nijel’s Point ist ein Alliance in Desolace. Sie unterstützt Expeditionen und Reisende in einer Region, in der Konflikte mit Zentauren und anderen Gruppen eine stabile Präsenz erschweren."},pt={title="Nijel's Point",body="Nijel’s Point é um assentamento Alliance em Desolace. Apoia expedições e viajantes em uma região onde conflitos com centauros e outros grupos dificultam uma presença estável."},pl={title="Nijel's Point",body="Nijel’s Point to osada frakcji Alliance w Desolace. Zapewnia wsparcie wyprawom i podróżnym w regionie, gdzie konflikty z centaurami oraz innymi grupami utrudniają utrzymanie stałej obecności."},ru={title="Nijel's Point",body="Nijel’s Point - это распределение Alliance в Desolace. Он поддерживает экспедиции и путешественников в регионе, где конфликты с кентаврами и другими группами затрудняют стабильное присутствие."},references={["organization:alliance"]=true,["place:desolace"]=true}},
    ["place:northdale"] = {title="Vallenorte",kind="Lugar",aliases={"Vallenorte"},body="Vallenorte es una población de las Tierras de la Peste del Este marcada por los combates. Sus calles conservan vestigios de quienes defendieron Lordaeron y de los símbolos que llevaron a la batalla.",aliasQuestIDs={},en={title="Northdale",aliases={"Northdale"},body="Northdale is an Eastern Plaguelands settlement scarred by fighting. Its streets preserve traces of Lordaeron's defenders and the symbols they carried into battle.",aliasQuestIDs={}},fr={title="Northdale",body="Northdale est une colonie Eastern Plaguelands marquée par les combats. Ses rues conservent les traces des défenseurs de Lordaeron et les symboles qu'ils portaient dans la bataille."},de={title="Northdale",body="Northdale ist ein vom Kampf gezeichneter Eastern Plaguelands. Seine Straßen bewahren die Spuren der Verteidiger des Lordaeron und die Symbole, die sie in den Kampf trugen."},pt={title="Northdale",body="Northdale é um assentamento Eastern Plaguelands marcado por lutas. Suas ruas preservam vestígios dos defensores do Lordaeron e os símbolos que levaram para a batalha."},pl={title="Northdale",body="Northdale jest osadą w Eastern Plaguelands naznaczoną walkami. Jej ulice zachowują ślady obrońców Lordaeron oraz symboli, które nieśli do bitwy."},ru={title="Northdale",body="Northdale - это поселение Eastern Plaguelands, пострадавшее от боев. На улицах хранятся следы защитников Lordaeron и символы, которые они носили в битве."},references={["place:eastern-plaguelands"]=true,["place:lordaeron"]=true,["place:plaguelands"]=true}},
    ["place:northpass-tower"] = {title="Torre del Paso Norte",kind="Lugar",aliases={"Torre del Paso Norte"},body="La Torre del Paso Norte es una referencia del norte de las Tierras de la Peste del Este. Sus inmediaciones sirven de lugar de encuentro para quienes investigan reliquias y amenazas de la región.",aliasQuestIDs={},en={title="Northpass Tower",aliases={"Northpass Tower"},body="Northpass Tower is a landmark in northern Eastern Plaguelands. Its surroundings serve as a meeting place for those investigating the region's relics and threats.",aliasQuestIDs={}},fr={title="Northpass Tower",body="Northpass Tower est un point de repère dans le nord de Eastern Plaguelands. Ses environs servent de lieu de rencontre pour ceux qui enquêtent sur les reliques et les menaces de la région."},de={title="Northpass Tower",body="Northpass Tower ist ein Wahrzeichen im nördlichen Eastern Plaguelands. Seine Umgebung dient als Versammlungsort für diejenigen, die Relikte und Bedrohungen der Region erforschen."},pt={title="Northpass Tower",body="Northpass Tower é um marco no norte de Eastern Plaguelands. Seus arredores servem como um ponto de encontro para aqueles que investigam as relíquias e ameaças da região."},pl={title="Northpass Tower",body="Northpass Tower jest punktem orientacyjnym na północy Eastern Plaguelands. Jego okolice służą jako miejsce spotkań badających relikty i zagrożenia regionu."},ru={title="Northpass Tower",body="Northpass Tower - это достопримечательность на севере Eastern Plaguelands. Его окрестности служат местом встречи для тех, кто изучает реликвии и угрозы региона."},references={["place:eastern-plaguelands"]=true,["place:plaguelands"]=true}},
    ["place:northshire"] = {title="Villanorte",kind="Lugar",aliases={"Villanorte"},body="Villanorte es una comunidad del Bosque de Elwynn organizada alrededor de su abadía. Los guardias vigilan los bosques, las minas y los viñedos cercanos, donde las amenazas locales ponen a prueba a quienes comienzan a servir a Ventormenta.",aliasQuestIDs={},en={title="Northshire",aliases={"Northshire"},body="Northshire is an Elwynn Forest community centered on its abbey. Guards watch the nearby woods, mines and vineyards, where local threats test those beginning their service to Stormwind.",aliasQuestIDs={}},fr={title="Northshire",body="Northshire est une communauté Elwynn Forest centrée sur son abbaye. Les gardes surveillent les bois, les mines et les vignobles à proximité, où les menaces locales testent ceux qui commencent leur service à Stormwind."},de={title="Northshire",body="Northshire ist eine Gemeinschaft im Elwynn Forest, deren Mittelpunkt die Abtei bildet. Wachen überwachen die nahen Wälder, Minen und Weinberge, wo örtliche Gefahren jene auf die Probe stellen, die ihren Dienst für Stormwind beginnen."},pt={title="Northshire",body="Northshire é uma comunidade Elwynn Forest centrada em sua abadia. Guardas vigiam os bosques, minas e vinhedos próximos, onde ameaças locais testam aqueles que começam seu serviço para Stormwind."},pl={title="Northshire",body="Northshire to osada w Elwynn Forest skupiona wokół opactwa. Strażnicy pilnują pobliskich lasów, kopalń i winnic, gdzie miejscowe zagrożenia wystawiają na próbę tych, którzy rozpoczynają służbę dla Stormwind."},ru={title="Northshire",body="Northshire - это сообщество Elwynn Forest, сосредоточенное в своем аббатстве. Охранники наблюдают за близлежащими лесами, шахтами и виноградниками, где местные угрозы проверяют тех, кто начинает свою службу в Stormwind."},references={["place:elwynn-forest"]=true,["place:stormwind"]=true}},
    ["place:northshire-abbey"] = {title="Abadía de Villanorte",kind="Lugar",aliases={"Abadía de Villanorte"},body="La Abadía de Villanorte es un punto de reunión para los habitantes y defensores de la zona. Sus alrededores ofrecen un primer contacto con la vida de Elwynn: instrucción, labores agrícolas y la vigilancia de los caminos.",aliasQuestIDs={},en={title="Northshire Abbey",aliases={"Northshire Abbey"},body="Northshire Abbey is a meeting place for the inhabitants and defenders of the surrounding district. Its grounds introduce the everyday life of Elwynn: training, farm work and keeping watch over the roads.",aliasQuestIDs={}},fr={title="Northshire Abbey",body="Northshire Abbey est un lieu de rencontre pour les habitants et les défenseurs du quartier environnant. Ses terrains introduisent le quotidien de la Elwynn: formation, travaux agricoles et veille sur les routes."},de={title="Northshire Abbey",body="Northshire Abbey ist ein Treffpunkt für die Bewohner und Verteidiger des umliegenden Bezirks. Sein Gelände führt in den Alltag von Elwynn ein: Ausbildung, landwirtschaftliche Arbeit und Straßenwacht."},pt={title="Northshire Abbey",body="Northshire Abbey é um ponto de encontro para os habitantes e defensores do distrito circundante. Seus fundamentos introduzem a vida cotidiana do Elwynn: treinamento, trabalho agrícola e vigilância nas estradas."},pl={title="Northshire Abbey",body="Northshire Abbey jest miejscem spotkań mieszkańców i obrońców okolicy. Jego teren wprowadza w codzienne życie Elwynn: szkolenie, pracę na roli i pilnowanie dróg."},ru={title="Northshire Abbey",body="Northshire Abbey - это место встречи жителей и защитников окружающего района. На его территории представлена повседневная жизнь Elwynn: обучение, сельскохозяйственная работа и наблюдение за дорогами."},references={["place:elwynn-forest"]=true,["place:northshire"]=true}},
    ["place:northwatch-hold"] = {title="Fuerte del Norte",kind="Lugar",aliases={"Fuerte del Norte"},body="El Fuerte del Norte es una posición militar humana próxima a la costa de Los Baldíos. Su guarnición forma parte de la presencia de Theramore en una región donde las rutas de la Alianza y la Horda se disputan con frecuencia.",aliasQuestIDs={},en={title="Northwatch Hold",aliases={"Northwatch Hold"},body="Northwatch Hold is a human military position near the coast of the Barrens. Its garrison is part of Theramore’s presence in a region where Alliance and Horde routes are frequently contested.",aliasQuestIDs={}},fr={title="Northwatch Hold",body="Northwatch Hold est une position militaire humaine près de la côte de la Barrens. Sa garnison fait partie de la présence de Theramore dans une région où les routes Alliance et Horde sont fréquemment contestées."},de={title="Northwatch Hold",body="Northwatch Hold ist eine menschliche Militärposition in der Nähe der Küste des Barrens. Seine Garnison ist Teil der Präsenz von Theramore in einer Region, in der häufig umkämpften Alliance und Horde Routen."},pt={title="Northwatch Hold",body="Northwatch Hold é uma posição militar humana perto da costa do Barrens. Sua guarnição faz parte da presença da Theramore em uma região onde as rotas Alliance e Horde são frequentemente contestadas."},pl={title="Northwatch Hold",body="Northwatch Hold to ludzka placówka wojskowa w pobliżu wybrzeża regionu Barrens. Jej garnizon stanowi część obecności Theramore na ziemiach, gdzie szlaki frakcji Alliance i Horde często stają się przedmiotem sporu."},ru={title="Northwatch Hold",body="Northwatch Hold - это человеческая военная позиция недалеко от побережья Barrens. Его гарнизон является частью присутствия Theramore в регионе, где маршруты Alliance и Horde часто оспариваются."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:the-barrens"]=true,["place:theramore"]=true}},
    ["place:noxious-lair"] = {title="Guarida Ponzoñosa",kind="Lugar",aliases={"Guarida Ponzoñosa"},body="La Guarida Ponzoñosa es un enclave de Tanaris ocupado por los Centipaar. La actividad de estas criaturas drena las pozas de agua que existían en el lugar y provoca inquietud entre quienes intentan comprender su avance.",aliasQuestIDs={},en={title="Noxious Lair",aliases={"Noxious Lair"},body="The Noxious Lair is a Tanaris site occupied by the Centipaar. The creatures’ activity drains the pools once present there, alarming those trying to understand their spread.",aliasQuestIDs={}},fr={title="Noxious Lair",body="Le Noxious Lair est un site Tanaris occupé par le Centipaar. L’activité des créatures draine les piscines une fois présentes, alarmant ceux qui tentent de comprendre leur propagation."},de={title="Noxious Lair",body="Der Noxious Lair ist ein Tanaris-Standort, der vom Centipaar besetzt ist. Die Aktivität der Kreaturen entwässert die einst dort vorhandenen Becken, was diejenigen alarmiert, die versuchen, ihre Ausbreitung zu verstehen."},pt={title="Noxious Lair",body="O Noxious Lair é um site Tanaris ocupado pelo Centipaar. A atividade das criaturas drena as piscinas uma vez presentes lá, alarmando aqueles que tentam entender sua propagação."},pl={title="Noxious Lair",body="Noxious Lair jest miejscem w Tanaris zajmowanym przez Centipaar. Działalność tych istot osusza dawne zbiorniki wody, budząc niepokój osób próbujących zrozumieć ich rozprzestrzenianie się."},ru={title="Noxious Lair",body="Noxious Lair - это Tanaris, на котором находится Centipaar. Деятельность этих существ истощает бассейны, которые когда-то были там, что вызывает тревогу у тех, кто пытается понять их распространение."},references={["organization:centipaar"]=true,["place:tanaris"]=true}},
    ["place:oracle-tree"] = {title="Árbol del Oráculo",kind="Lugar",aliases={"Árbol del Oráculo","árbol del oráculo"},body="El Árbol del Oráculo es un lugar de Teldrassil del que parten mensajes para los ancianos de los elfos de la noche. Las centinelas ayudan a llevar esas noticias a Darnassus y a mantener la comunicación con el claro.",aliasQuestIDs={},en={title="Oracle Tree",aliases={"Oracle Tree"},body="The Oracle Tree is a place in Teldrassil from which messages are sent to night elf elders. Sentinels help carry that news to Darnassus and maintain contact with the glade.",aliasQuestIDs={}},fr={title="Oracle Tree",body="Le Oracle Tree est un endroit dans Teldrassil à partir duquel les messages sont envoyés aux anciens elfes de la nuit. Sentinels aide à transmettre cette nouvelle à Darnassus et à maintenir le contact avec la clairière."},de={title="Oracle Tree",body="Der Oracle Tree ist ein Ort in Teldrassil, von dem aus Nachrichten an die Nachtelfenältesten gesendet werden. Sentinels hilft, diese Nachricht zu Darnassus zu tragen und den Kontakt zur Lichtung aufrechtzuerhalten."},pt={title="Oracle Tree",body="O Oracle Tree é um lugar no Teldrassil a partir do qual as mensagens são enviadas para os elfos da noite. Sentinels ajudar a levar essa notícia para Darnassus e manter contato com a clareira."},pl={title="Oracle Tree",body="Oracle Tree to miejsce w Teldrassil, z którego wysyłane są wiadomości do starszyzny nocnych elfów. Sentinels pomagają dostarczać te wieści do Darnassus i utrzymywać kontakt z polaną."},ru={title="Oracle Tree",body="Oracle Tree - это место в Teldrassil, откуда отправляются сообщения старейшинам ночных эльфов. Sentinels помогают передать эту новость Darnassus и поддерживать контакт с поляной."},references={["organization:night-elf-sentinels"]=true,["place:darnassus"]=true,["place:teldrassil"]=true}},
    ["place:orgrimmar"] = {title="Orgrimmar",kind="Lugar",aliases={"Orgrimmar"},body="Orgrimmar es la capital de los orcos en Durotar y un centro de mando de la Horda. Sus barrios reúnen guerreros, comerciantes e instructores, mientras la fortaleza de Thrall representa la autoridad del jefe de guerra.",aliasQuestIDs={},en={title="Orgrimmar",aliases={"Orgrimmar"},body="Orgrimmar is the orc capital in Durotar and a command center of the Horde. Its districts bring together warriors, traders and trainers, while Thrall’s stronghold represents the warchief’s authority.",aliasQuestIDs={}},fr={title="Orgrimmar",body="Orgrimmar est la capitale orc dans Durotar et un centre de commande de la Horde. Ses quartiers rassemblent des guerriers, des commerçants et des entraîneurs, tandis que la forteresse de Thrall représente l’autorité du chef de guerre."},de={title="Orgrimmar",body="Orgrimmar ist die Hauptstadt der Orks in Durotar und Kommandozentrale der Horde. Seine Bezirke bringen Krieger, Händler und Ausbilder zusammen, während Thrall \"Hochburg die Autorität des Kriegshäupr darstellt."},pt={title="Orgrimmar",body="Orgrimmar é a capital do orc em Durotar e um centro de comando do Horde. Seus distritos reúnem guerreiros, comerciantes e treinadores, enquanto a fortaleza do Thrall representa a autoridade do chefe de guerra."},pl={title="Orgrimmar",body="Orgrimmar to stolica orków w Durotar i ośrodek dowodzenia frakcji Horde. W dzielnicach miasta spotykają się wojownicy, kupcy i nauczyciele, a twierdza, w której rezyduje Thrall, symbolizuje władzę wodza wojennego."},ru={title="Orgrimmar",body="Orgrimmar - это столица орков в Durotar и командный центр Horde. В его районах собраны воины, торговцы и тренеры, в то время как крепость Thrall  представляет собой власть военачальника."},references={["organization:horde"]=true,["person:thrall"]=true,["place:durotar"]=true}},
    ["place:overlook-standing-stones"] = {title="Piedras Erguidas del Mirador",kind="Lugar",aliases={"Piedras Erguidas del Mirador"},body="Las Piedras Erguidas del Mirador son un lugar de las Tierras Altas de Shen'dar donde se alzan grandes formaciones de piedra de viento. La energía elemental que concentran atrae el interés de los eruditos de la Suma Orden. Los Formavientos también muestran un fuerte interés en proteger este sitio.",aliasQuestIDs={},en={title="Overlook Standing Stones",aliases={"Overlook Standing Stones"},body="The Overlook Standing Stones are a site in the Shen'dar Highlands marked by large windstone formations. Their concentration of elemental energy draws the interest of High Order scholars. The Windshapers also take a strong interest in guarding the site.",aliasQuestIDs={}},fr={title="Overlook Standing Stones",body="Les Overlook Standing Stones sont un site dans le Shen'dar Highlands marqué par de grandes formations de pierres du vent. Leur concentration d'énergie élémentaire attire l'intérêt des chercheurs de High Order. Les Windshapers s’intéressent également à la protection du site."},de={title="Overlook Standing Stones",body="Die Overlook Standing Stones sind ein Fundort im Shen'dar Highlands, der von großen Windsteinformationen gekennzeichnet ist. Ihre Konzentration der Elementarenergie zieht das Interesse der High Order-Gelehrten auf sich. Auch die Windshapers haben ein starkes Interesse an der Bewachung des Geländes Geländes."},pt={title="Overlook Standing Stones",body="O Overlook Standing Stones é um site no Shen'dar Highlands marcado por grandes formações de pedras de vento. Sua concentração de energia elementar atrai o interesse dos estudiosos do High Order. O Windshapers também tem um forte interesse em proteger o site."},pl={title="Overlook Standing Stones",body="The Overlook Standing Stones są miejscem w Shen'dar Highlands wyróżniającym się wielkimi formacjami kamieni wiatru. Skupienie energii żywiołów interesuje uczonych High Order. Społeczność znana jako The Windshapers także przywiązuje dużą wagę do ochrony miejsca."},ru={title="Overlook Standing Stones",body="Overlook Standing Stones - это место в Shen'dar Highlands, отмеченное большими форматами ветровых камней. Их концентрация элементарной энергии привлекает интерес ученых High Order. Windshapers также проявляют большой интерес к охране места."},references={["organization:high-order"]=true,["organization:windshapers"]=true,["place:shendar"]=true,["place:shendar-highlands"]=true}},
    ["place:plaguelands"] = {title="Tierras de la Peste",kind="Lugar",aliases={"Tierras de la Peste"},body="Las Tierras de la Peste reúnen regiones de Lordaeron devastadas por la enfermedad y los no-muertos. Sus antiguas poblaciones y campos se han convertido en lugares donde la guerra también se libra por recuperar la naturaleza y la memoria de sus habitantes.",aliasQuestIDs={},en={title="Plaguelands",aliases={"Plaguelands"},body="The Plaguelands comprise Lordaeron regions devastated by disease and undead. Their former settlements and fields have become places where the struggle also concerns reclaiming nature and their inhabitants' memory.",aliasQuestIDs={}},fr={title="Plaguelands",body="Les Plaguelands comprennent les régions Lordaeron dévastées par la maladie et les morts-vivants. Leurs anciennes colonies et champs sont devenus des lieux où la lutte concerne également la récupération de la nature et de la mémoire de leurs habitants."},de={title="Plaguelands",body="Die Plaguelands umfassen die von Krankheiten verwüsteten und untoten Lordaeron-Regionen. Ihre ehemaligen Siedlungen und Felder sind zu Orten geworden, an denen es im Kampf auch darum geht, die Natur und das Gedächtnis ihrer Bewohner zurückzugewinnen."},pt={title="Plaguelands",body="O Plaguelands compreende regiões Lordaeron devastadas por doenças e mortos-vivos. Seus antigos assentamentos e campos tornaram-se lugares onde a luta também diz respeito à recuperação da natureza e da memória de seus habitantes."},pl={title="Plaguelands",body="The Plaguelands obejmują regiony Lordaeron zniszczone przez chorobę i nieumarłych. Dawne osady i pola stały się miejscami walki także o odzyskanie natury i pamięci mieszkańców."},ru={title="Plaguelands",body="Plaguelands включает в себя Lordaeron регионы, опустошенные болезнями и неживыми. Их бывшие поселения и поля стали местами, где борьба также касается восстановления природы и памяти их жителей."},references={["place:lordaeron"]=true}},
    ["place:plaguewood"] = {title="Bosque de la Peste",kind="Lugar",aliases={"Bosque de la Peste","el Bosque de la Peste"},body="El Bosque de la Peste se encuentra en las Tierras de la Peste del Este. Sus montículos de termitas albergan criaturas capaces de dañar la madera, un peligro natural que los enemigos de la Cruzada Escarlata consideran útil contra sus aserraderos.",aliasQuestIDs={},en={title="Plaguewood",aliases={"Plaguewood"},body="Plaguewood lies in the Eastern Plaguelands. Its termite mounds house creatures capable of damaging timber, a natural danger the Scarlet Crusade's enemies consider useful against its lumber mills.",aliasQuestIDs={}},fr={title="Plaguewood",body="Plaguewood se trouve dans le Eastern Plaguelands. Ses termitières abritent des créatures capables d'endommager le bois, un danger naturel que les ennemis de la Scarlet Crusade considèrent comme utile contre ses scieries."},de={title="Plaguewood",body="Plaguewood liegt im Eastern Plaguelands. Seine Termitenhügel beherbergen Lebeherbergen Geschöpfe, die das Holz schädigen können, eine natürliche Gefahr, die die die die Scarlet Crusade \"Feinde für seine Holzmühlen als nützlich erachten."},pt={title="Plaguewood",body="Plaguewood encontra-se no Eastern Plaguelands. Seus montes de cupins abrigam criaturas capazes de danificar a madeira, um perigo natural que os inimigos do Scarlet Crusade consideram útil contra seus moinhos de madeira."},pl={title="Plaguewood",body="Plaguewood leży w Eastern Plaguelands. Kopce termitów mieszczą stworzenia zdolne niszczyć drewno, naturalne zagrożenie uważane przez wrogów Scarlet Crusade za użyteczne przeciw jej tartakom."},ru={title="Plaguewood",body="Plaguewood лежит в Eastern Plaguelands. В его термитных курганах обитают существа, способные повреждать древесину, что является естественной опасностью для врагов Scarlet Crusade."},references={["organization:scarlet-crusade"]=true,["place:eastern-plaguelands"]=true,["place:plaguelands"]=true}},
    ["place:purgation-isle"] = {title="Isla del Purgatorio",kind="Lugar",aliases={"Isla del Purgatorio"},body="La Isla del Purgatorio se encuentra frente a la costa sur de las Laderas de Trabalomas. Las almas de sus muertos desterrados y las cenizas de sus restos atraen a nigrománticos interesados en invocar y manipular espíritus.",aliasQuestIDs={},en={title="Purgation Isle",aliases={"Purgation Isle"},body="Purgation Isle lies off the southern coast of the Hillsbrad Foothills. The souls of its banished dead and ashes from their remains draw necromancers interested in summoning and manipulating spirits.",aliasQuestIDs={}},fr={title="Purgation Isle",body="Purgation Isle se trouve au large de la côte sud de la Hillsbrad Foothills. Les âmes de ses morts bannis et des cendres de leurs restes attirent les nécromanciens intéressés à invoquer et à manipuler les esprits."},de={title="Purgation Isle",body="Purgation Isle liegt vor der Südküste des Hillsbrad Foothills. Die Seelen ihrer verbannten Toten und die Asche aus ihren Überresten ziehen Totenbeschwörende Geister an, die Geister, die daran interessiert sind, Geister zu beschwören und zu manipulieren."},pt={title="Purgation Isle",body="Purgation Isle fica ao largo da costa sul do Hillsbrad Foothills. As almas de seus mortos banidos e cinzas de seus restos mortais atraem necromantes interessados em convocar e manipular espíritos."},pl={title="Purgation Isle",body="Purgation Isle leży u południowego wybrzeża Hillsbrad Foothills. Dusze wygnanych zmarłych i popioły ich szczątków przyciągają nekromantów zainteresowanych przyzywaniem i manipulowaniem duchami."},ru={title="Purgation Isle",body="Purgation Isle находится у южного побережья Hillsbrad Foothills. Души изгнанных мертвецов и пепел их останков привлекают некромантов, заинтересованных в вызове и манипулировании духами."},references={}},
    ["place:pyrewood-village"] = {title="Aldea Piroleña",kind="Lugar",aliases={"Aldea Piroleña","Piroleña"},body="Aldea Piroleña es una población de Argénteos sometida a la influencia de Arugal. Sus habitantes sufren una transformación que cambia su aspecto cuando cae la noche.",aliasQuestIDs={["Piroleña"]={[99]=true}},en={title="Pyrewood Village",aliases={"Pyrewood","Pyrewood Village"},body="Pyrewood Village is a Silverpine settlement under Arugal's influence. Its inhabitants suffer a transformation that changes their appearance after nightfall.",aliasQuestIDs={["Pyrewood"]={[99]=true}}},fr={title="Pyrewood Village",body="Pyrewood Village est un règlement Silverpine sous l'influence de Arugal. Ses habitants subissent une transformation qui change leur apparence après la tombée de la nuit."},de={title="Pyrewood Village",body="Pyrewood Village ist eine Silverpine-Siedlung unter Arugal \"Einfluss. Seine Bewohner erleiden einen Wandel, der ihr Aussehen nach Einbruch der Dunkelheit verändert."},pt={title="Pyrewood Village",body="Pyrewood Village é um acordo Silverpine sob a influência de Arugal. Seus habitantes sofrem uma transformação que muda sua aparência após o anoitecer."},pl={title="Pyrewood Village",body="Pyrewood Village jest osadą w Silverpine pod wpływem Arugal. Jej mieszkańcy cierpią na przemianę zmieniającą ich wygląd po zmroku."},ru={title="Pyrewood Village",body="Pyrewood Village - это поселение Silverpine под влиянием Arugal. Его жители переживают преображение, которое меняет их внешний вид после наступления темноты."},references={["npc:arugal"]=true,["place:silverpine-forest"]=true}},
    ["place:quel-danil"] = {title="Avanzada Quel'Danil",kind="Lugar",aliases={"Avanzada Quel'Danil","Avanzada Quel’Danil","Quel'Danil","Quel’Danil"},body="La Avanzada Quel'Danil es un puesto de las Tierras del Interior cuyos ocupantes controlan el acceso a su entorno. La presencia de cautivos refleja las tensiones entre las comunidades que habitan esta región.",aliasQuestIDs={},en={title="Quel'Danil Lodge",aliases={"Quel'Danil","Quel'Danil Lodge","Quel’Danil","Quel’Danil Lodge"},body="Quel’Danil Lodge is a Hinterlands outpost whose occupants control access to the surrounding district. Captives held there reflect the tensions between the region’s communities.",aliasQuestIDs={}},fr={title="Quel'Danil Lodge",body="Quel’Danil Lodge est un avant-poste Hinterlands dont les occupants contrôlent l'accès au quartier environnant. Les prisonniers qui y sont détenus reflètent les tensions entre les communautés de la région."},de={title="Quel'Danil Lodge",body="Quel’Danil Lodge ist ein Hinterlands-Außenposten, dessen Bewohner den Zugang zum umliegenden Bezirk kontrollieren. Die dort inhaftierten Gefangenen spiegeln die Spannungen zwischen den Gemeinschaften der Region wider."},pt={title="Quel'Danil Lodge",body="Quel’Danil Lodge é um posto avançado Hinterlands cujos ocupantes controlam o acesso ao distrito circundante. Os cativos ali mantidos refletem as tensões entre as comunidades da região."},pl={title="Quel'Danil Lodge",body="Quel’Danil Lodge to placówka w Hinterlands, której mieszkańcy kontrolują dostęp do okolicy. Przetrzymywani tam jeńcy odzwierciedlają napięcia między społecznościami regionu."},ru={title="Quel'Danil Lodge",body="Quel’Danil Lodge - это форпост Hinterlands, жители которого контролируют доступ к окружающему району. Заключенные там отражают напряженность между общинами региона."},references={["place:hinterlands"]=true}},
    ["place:rage-scar"] = {title="Cicatriz de Rabia",kind="Lugar",aliases={"Cicatriz de Rabia"},body="Cicatriz de Rabia es una zona de Feralas habitada por yetis. Sus pellejos forman parte de los materiales que buscan los peleteros de los asentamientos cercanos, conectando la fauna del bosque con los oficios de sus habitantes.",aliasQuestIDs={},en={title="Rage Scar",aliases={"Rage Scar"},body="Rage Scar is a part of Feralas inhabited by yetis. Their hides are sought by leatherworkers in nearby settlements, connecting the forest’s wildlife with its inhabitants’ crafts.",aliasQuestIDs={}},fr={title="Rage Scar",body="Rage Scar fait partie de Feralas habité par des yétis. Leurs peaux sont recherchées par les maroquiniers dans les colonies voisines, reliant la faune de la forêt à l’artisanat de ses habitants."},de={title="Rage Scar",body="Rage Scar ist ein Teil von Feralas, der von Yetis bewohnt wird. Ihre Verstecke werden von Lederarbeitern in nahegelegenen Siedlungen gesucht und verbinden die Tierwelt des Waldes Waldes Landes mit dem Kunsthandwerk seiner Bewohner."},pt={title="Rage Scar",body="Rage Scar é uma parte do Feralas habitada por yetis. Suas peles são procuradas por trabalhadores de couro em assentamentos próximos, conectando a vida selvagem da floresta com os artesanatos de seus habitantes."},pl={title="Rage Scar",body="Rage Scar jest częścią Feralas zamieszkaną przez yeti. Ich skóry są poszukiwane przez rzemieślników z pobliskich osad, łącząc leśną przyrodę z rękodziełem mieszkańców."},ru={title="Rage Scar",body="Rage Scar - это часть Feralas, населенная ети. Их шкуры ищут кожевенники в близлежащих поселениях, связывая дикую природу леса с ремеслом его жителей."},references={["place:feralas"]=true}},
    ["place:ratchet"] = {title="Trinquete",kind="Lugar",aliases={"Trinquete"},body="Trinquete es un puerto de Los Baldíos donde los negocios y la navegación marcan el ritmo de la vida diaria. Los goblins que trabajan allí mantienen talleres y redes comerciales, siempre atentos a piratas y otros peligros de la costa.",aliasQuestIDs={},en={title="Ratchet",aliases={"Ratchet"},body="Ratchet is a port in the Barrens where business and shipping shape daily life. The goblins working there maintain workshops and trade networks while watching for pirates and other coastal dangers.",aliasQuestIDs={}},fr={title="Ratchet",body="Ratchet est un port dans le Barrens où les affaires et l'expédition façonnent la vie quotidienne. Les gobelins qui y travaillent entretiennent des ateliers et des réseaux commerciaux tout en surveillant les pirates et autres dangers côtiers."},de={title="Ratchet",body="Ratchet ist ein Hafen im Barrens, wo Geschäft und Schifffahrt den Alltag prägen. Die dort arbeitenden Goblins unterhalten Werkstätten und Handelsnetzwerke und halten Ausschau nach Piraten und anderen Gefahren an der Küste."},pt={title="Ratchet",body="Ratchet é um porto no Barrens onde negócios e transporte moldam a vida diária. Os goblins que trabalham lá mantêm oficinas e redes de comércio enquanto observam piratas e outros perigos costeiros."},pl={title="Ratchet",body="Ratchet to port w regionie Barrens, gdzie handel i żegluga kształtują codzienne życie. Pracujące tam gobliny prowadzą warsztaty i sieci handlowe, wypatrując zarazem piratów oraz innych niebezpieczeństw na wybrzeżu."},ru={title="Ratchet",body="Ratchet - это порт в Barrens, где бизнес и судоходство формируют повседневную жизнь. Гоблины, работающие там, поддерживают мастерские и торговые сети, наблюдая за пиратами и другими опасностями на побережье."},references={["place:the-barrens"]=true}},
    ["place:raven-hill"] = {title="Cerro del Cuervo",kind="Lugar",aliases={"Cerro del Cuervo"},body="El Cerro del Cuervo es una zona del Bosque del Ocaso dominada por su cementerio y por viviendas apartadas. La presencia de no muertos ha convertido sus tumbas y caminos en un lugar especialmente peligroso para los habitantes del bosque.",aliasQuestIDs={},en={title="Raven Hill",aliases={"Raven Hill"},body="Raven Hill is a Duskwood district marked by its cemetery and isolated dwellings. The presence of undead has made its graves and roads particularly dangerous for the forest’s inhabitants.",aliasQuestIDs={}},fr={title="Raven Hill",body="Raven Hill est un quartier Duskwood marqué par son cimetière et ses habitations isolées. La présence de morts-vivants a rendu ses tombes et ses routes particulièrement dangereuses pour les habitants de la forêt."},de={title="Raven Hill",body="Raven Hill ist ein Duskwood-Viertel, das durch seine Friedhöfe und isolierten Wohnungen geprägt ist. Die Anwesenheit von Untoten hat ihre Gräber und Straßen für die Waldbewohner besonders gefährlich gemacht."},pt={title="Raven Hill",body="Raven Hill é um distrito Duskwood marcado por seu cemitério e habitações isoladas. A presença de mortos-vivos tornou suas sepulturas e estradas particularmente perigosas para os habitantes da floresta."},pl={title="Raven Hill",body="Raven Hill to część Duskwood wyróżniająca się cmentarzem i odosobnionymi domostwami. Obecność nieumarłych sprawia, że groby i drogi są szczególnie niebezpieczne dla mieszkańców lasu."},ru={title="Raven Hill",body="Raven Hill - это район Duskwood, отмеченный своим кладбищем и изолированными жилыми домами. Присутствие неживых мертвецов делает его могилы и дороги особенно опасными для жителей леса."},references={["place:duskwood"]=true}},
    ["place:ravenholdt-manor"] = {title="Mansión Ravenholdt",kind="Lugar",aliases={"Mansión Ravenholdt"},body="La Mansión Ravenholdt es un punto de reunión para agentes que investigan a la Hermandad. Sus actividades conceden un valor especial a la discreción, el robo de informes y la vigilancia de los movimientos enemigos.",aliasQuestIDs={},en={title="Ravenholdt Manor",aliases={"Ravenholdt Manor"},body="Ravenholdt Manor is a gathering place for agents investigating the Syndicate. Their work places special value on discretion, stolen reports and watching enemy movements.",aliasQuestIDs={}},fr={title="Ravenholdt Manor",body="Ravenholdt Manor est un lieu de rassemblement pour les agents enquêtant sur le Syndicate. Leur travail accorde une importance particulière à la discrétion, aux rapports volés et à la surveillance des mouvements ennemis."},de={title="Ravenholdt Manor",body="Ravenholdt Manor ist ein Sammelplatz für Agenten, die den Syndicate untersuchen. Bei ihrer Arbeit legen sie besonderen Wert auf Diskretion, gestohlene Berichte und das Beobachten feindlicher Bewegungen."},pt={title="Ravenholdt Manor",body="Ravenholdt Manor é um local de encontro para agentes que investigam o Syndicate. Seu trabalho valoriza especialmente a discrição, os relatórios roubados e os movimentos inimigos."},pl={title="Ravenholdt Manor",body="Ravenholdt Manor to miejsce spotkań agentów badających Syndicate. Szczególne znaczenie mają dla nich dyskrecja, skradzione meldunki i obserwacja ruchów wroga."},ru={title="Ravenholdt Manor",body="Ravenholdt Manor - это место для агентов, расследующих Syndicate. В их работе особое значение придается осторожности, краже отчетов и наблюдению за движением врага."},references={["organization:ravenholdt"]=true,["organization:syndicate"]=true}},
    ["place:raynewood"] = {title="Algaba",kind="Lugar",aliases={"Algaba"},body="Algaba es un paraje boscoso de Vallefresno donde se encuentra Ordanus. Su refugio en lo alto de un gran árbol vincula el lugar con uno de los hijos mayores del dios del bosque.",aliasQuestIDs={},en={title="Raynewood",aliases={"Raynewood"},body="Raynewood is a wooded part of Ashenvale where Ordanus is found. His refuge atop a great tree connects the place with one of the forest god’s eldest sons.",aliasQuestIDs={}},fr={title="Raynewood",body="Raynewood est une partie boisée de Ashenvale où Ordanus se trouve. Son refuge au sommet d'un grand arbre relie l'endroit à l'un des fils aînés du dieu de la forêt."},de={title="Raynewood",body="Raynewood ist ein Waldstück von Ashenvale, wo Ordanus gefunden wird. Seine Zuflucht auf einem großen Baum verbindet den Ort mit einem der ältesten Söhne des Waldgottes."},pt={title="Raynewood",body="Raynewood é uma parte arborizada do Ashenvale onde o Ordanus se encontra. Seu refúgio no topo de uma grande árvore conecta o lugar com um dos filhos mais velhos do deus da floresta."},pl={title="Raynewood",body="Raynewood jest leśnym obszarem Ashenvale, w którym przebywa Ordanus. Jego schronienie na szczycie wielkiego drzewa łączy to miejsce z jednym z najstarszych synów leśnego boga."},ru={title="Raynewood",body="Raynewood - это лесистая часть Ashenvale, где находится Ordanus. Его убежище на вершине большого дерева связывает место с одним из старших сыновей лесного бога."},references={["person:keeper-ordanus"]=true,["place:ashenvale"]=true}},
    ["place:razor-hill"] = {title="Cerrotajo",kind="Lugar",aliases={"Cerrotajo"},body="Cerrotajo es un asentamiento de la Horda en Durotar. Sus guardias y habitantes mantienen las rutas locales y vigilan las amenazas que se acercan desde las colinas y la costa.",aliasQuestIDs={},en={title="Razor Hill",aliases={"Razor Hill"},body="Razor Hill is a Horde settlement in Durotar. Its guards and residents maintain local routes and watch for threats approaching from the hills and coast.",aliasQuestIDs={}},fr={title="Razor Hill",body="Razor Hill est un règlement Horde dans Durotar. Ses gardes et ses habitants maintiennent des routes locales et surveillent les menaces venant des collines et de la côte."},de={title="Razor Hill",body="Razor Hill ist eine Horde-Siedlung in Durotar. Seine Wachen und Bewohner halten lokale Routen aufrecht und achten auf Bedrohungen, die sich von den Hügeln und der Küste nähern."},pt={title="Razor Hill",body="Razor Hill é um assentamento Horde em Durotar. Seus guardas e moradores mantêm rotas locais e vigiam as ameaças que se aproximam das colinas e da costa."},pl={title="Razor Hill",body="Razor Hill to osada frakcji Horde w Durotar. Jej strażnicy i mieszkańcy dbają o miejscowe szlaki oraz wypatrują zagrożeń nadciągających ze wzgórz i wybrzeża."},ru={title="Razor Hill",body="Razor Hill — поселение Horde на территории Durotar. Его охранники и жители охраняют местные маршруты и наблюдают за угрозами, приближающимися с холмов и побережья."},references={["organization:horde"]=true,["place:durotar"]=true}},
    ["place:razorfen-downs"] = {title="Zahúrda Rajacieno",kind="Lugar",aliases={"Zahúrda Rajacieno"},body="Zahúrda Rajacieno es una fortaleza jabaespín cercada por zarzas. La presencia de no muertos convierte sus túneles en un lugar especialmente peligroso y amenaza también a quienes viven fuera de sus límites.",aliasQuestIDs={},en={title="Razorfen Downs",aliases={"Razorfen Downs"},body="Razorfen Downs is a quilboar stronghold surrounded by thorns. The presence of undead makes its passages especially dangerous and threatens those living beyond its borders.",aliasQuestIDs={}},fr={title="Razorfen Downs",body="Razorfen Downs est un fief de quilboar entouré d'épines. La présence de morts-vivants rend ses passages particulièrement dangereux et menace ceux qui vivent au-delà de ses frontières."},de={title="Razorfen Downs",body="Razorfen Downs ist eine Quiltschwein-Hochburg, umgeben von Dornen. Die Anwesenheit von Untoten macht seine Übergänge besonders gefährlich und bedroht diejenigen, die außerhalb seiner Grenzen leben."},pt={title="Razorfen Downs",body="Razorfen Downs é um reduto quilboar cercado por espinhos. A presença de mortos-vivos torna suas passagens especialmente perigosas e ameaça aqueles que vivem além de suas fronteiras."},pl={title="Razorfen Downs",body="Razorfen Downs to twierdza kolcozwierzy otoczona cierniami. Obecność nieumarłych czyni jej korytarze szczególnie niebezpiecznymi i zagraża mieszkańcom ziem poza jej granicami."},ru={title="Razorfen Downs",body="Razorfen Downs - крепость кабана, окруженная шипами. Присутствие неживых мертвецов делает его проходы особенно опасными и угрожает тем, кто живет за его пределами."},references={}},
    ["place:razorfen-kraul"] = {title="Horado Rajacieno",kind="Lugar",aliases={"Horado Rajacieno"},body="Horado Rajacieno es un dominio jabaespín entre enormes zarzas. Sus habitantes combinan la defensa de sus territorios con prácticas espirituales que vinculan a sus líderes con poderes más allá de la fuerza de las armas.",aliasQuestIDs={},en={title="Razorfen Kraul",aliases={"Razorfen Kraul"},body="Razorfen Kraul is a quilboar domain within a great tangle of thorns. Its inhabitants combine territorial defense with spiritual practices that connect their leaders to powers beyond the strength of weapons.",aliasQuestIDs={}},fr={title="Razorfen Kraul",body="Razorfen Kraul est un domaine de quilboar dans un grand enchevêtrement d'épines. Ses habitants combinent la défense territoriale avec des pratiques spirituelles qui relient leurs dirigeants à des pouvoirs au-delà de la force des armes."},de={title="Razorfen Kraul",body="Razorfen Kraul ist eine Quilschwein-Domäne in einem großen Wirrwarr aus Dornen. Seine Bewohner verbinden territoriale Verteidigung mit spirituellen Praktiken, die ihre Führer mit Mächten jenseits der Waffenkraft verbinden."},pt={title="Razorfen Kraul",body="Razorfen Kraul é um domínio quilboar dentro de um grande emaranhado de espinhos. Seus habitantes combinam defesa territorial com práticas espirituais que conectam seus líderes a poderes além da força das armas."},pl={title="Razorfen Kraul",body="Razorfen Kraul to domena kolcozwierzy pośród ogromnej plątaniny cierni. Jej mieszkańcy łączą obronę terytorium z praktykami duchowymi, które wiążą ich przywódców z mocami wykraczającymi poza siłę oręża."},ru={title="Razorfen Kraul",body="Razorfen Kraul - это домен квилбора в большой запутанной шипе. Жители города сочетают защиту территории с духовными практиками, которые связывают их лидеров с силами, превосходящими силу оружия."},references={}},
    ["place:rebel-camp"] = {title="Asentamiento Rebelde",kind="Lugar",aliases={"Asentamiento Rebelde"},body="El Asentamiento Rebelde reúne a quienes se oponen a Kurzen en Tuercespina. Su posición en la selva exige vigilar las rutas, buscar información y aprovechar la ayuda de exploradores independientes.",aliasQuestIDs={},en={title="Rebel Camp",aliases={"Rebel Camp"},body="The Rebel Camp gathers those opposing Kurzen in Stranglethorn. Its jungle position requires watching routes, gathering intelligence and using the help of independent scouts.",aliasQuestIDs={}},fr={title="Rebel Camp",body="Le Rebel Camp rassemble ceux qui s'opposent à Kurzen dans Stranglethorn. Sa position dans la jungle nécessite d'observer les routes, de recueillir des renseignements et d'utiliser l'aide d'éclaireurs indépendants."},de={title="Rebel Camp",body="Der Rebel Camp versammelt die Gegner Kurzen in Stranglethorn. Seine Position im Dschungel erfordert das Beobachten von Routen, das Sammeln von Informationen und die Hilfe unabhängiger Kundschafter."},pt={title="Rebel Camp",body="O Rebel Camp reúne aqueles que se opõem ao Kurzen no Stranglethorn. Sua posição na selva requer observar rotas, coletar inteligência e usar a ajuda de olheiros independentes."},pl={title="Rebel Camp",body="Rebel Camp skupia przeciwników Kurzen w Stranglethorn. Położenie w dżungli wymaga obserwowania szlaków, gromadzenia informacji i korzystania z pomocy niezależnych zwiadowców."},ru={title="Rebel Camp",body="Rebel Camp собирает противников Kurzen в Stranglethorn. Его положение в джунглях требует следить за маршрутами, собирать информацию и использовать помощь независимых разведчиков."},references={["npc:colonel-kurzen"]=true,["place:stranglethorn-vale"]=true}},
    ["place:redridge-mountains"] = {title="Montañas Crestagrana",kind="Lugar",aliases={"Crestagrana","Montañas Crestagrana"},body="Las Montañas Crestagrana son una región de caminos, bosques y fortificaciones amenazada por orcos Roca Negra y clanes gnoll. Sus habitantes intentan sostener los vínculos con Ventormenta mientras protegen Villa del Lago y sus alrededores.",aliasQuestIDs={},en={title="Redridge Mountains",aliases={"Redridge","Redridge Mountains"},body="The Redridge Mountains are a district of roads, woods and fortifications threatened by Blackrock orcs and gnoll clans. Its people try to maintain their ties with Stormwind while defending Lakeshire and the surrounding countryside.",aliasQuestIDs={}},fr={title="Redridge Mountains",body="Les Redridge Mountains sont un district de routes, de bois et de fortifications menacés par les clans Blackrock orcs et gnoll. Ses habitants tentent de maintenir leurs liens avec Stormwind tout en défendant Lakeshire et la campagne environnante."},de={title="Redridge Mountains",body="Die Redridge Mountains sind ein Bezirk von Straßen, Wäldern und Befestigungen, die von Blackrock orcs und Gnoll-Clans bedroht sind. Seine Leute versuchen, ihre Verbindungen zu Stormwind aufrechtzuerhalten und gleichzeitig Lakeshire und die umliegende Landschaft zu verteidigen."},pt={title="Redridge Mountains",body="O Redridge Mountains é um distrito de estradas, bosques e fortificações ameaçados por Blackrock orcs e clãs gnoll. Seu povo tenta manter seus laços com Stormwind enquanto defende Lakeshire e a paisagem circundante."},pl={title="Redridge Mountains",body="Redridge Mountains to obszar dróg, lasów i fortyfikacji zagrożony przez orków Blackrock oraz klany gnolli. Mieszkańcy próbują zachować więzi ze Stormwind, broniąc Lakeshire i okolicznych ziem."},ru={title="Redridge Mountains",body="Redridge Mountains - это район дорог, лесов и укреплений, которым угрожают Blackrock orcs и кланы гнолов. Его жители пытаются сохранить свои связи с Stormwind, защищая Lakeshire и окружающую сельскую местность."},references={["organization:blackrock-clan"]=true,["place:lakeshire"]=true,["place:stormwind"]=true}},
    ["place:refuge-pointe"] = {title="Refugio de la Zaga",kind="Lugar",aliases={"Refugio de la Zaga"},body="El Refugio de la Zaga es una base de la Alianza en Arathi. Desde allí se atienden las necesidades militares y de abastecimiento relacionadas con la lucha por los recursos de la cuenca cercana.",aliasQuestIDs={},en={title="Refuge Pointe",aliases={"Refuge Pointe"},body="Refuge Pointe is an Alliance base in Arathi. It supports military and supply needs tied to the struggle for resources in the nearby basin.",aliasQuestIDs={}},fr={title="Refuge Pointe",body="Refuge Pointe est une base Alliance dans Arathi. Il soutient les besoins militaires et d’approvisionnement liés à la lutte pour les ressources dans le bassin voisin."},de={title="Refuge Pointe",body="Refuge Pointe ist ein Alliance-Stützpunkt in Arathi. Sie unterstützt militärische und Versorgungsbedürfnisse, die mit dem Kampf um Ressourcen im nahegelegenen Becken verbunden sind."},pt={title="Refuge Pointe",body="Refuge Pointe é uma base Alliance em Arathi. Ele suporta necessidades militares e de fornecimento ligadas à luta por recursos na bacia próxima."},pl={title="Refuge Pointe",body="Refuge Pointe to baza Alliance w Arathi. Zaspokaja potrzeby wojskowe i zaopatrzeniowe związane z walką o zasoby pobliskiej kotliny."},ru={title="Refuge Pointe",body="Refuge Pointe - это база Alliance в Arathi. Он поддерживает военные и снабженческие потребности, связанные с борьбой за ресурсы в соседнем бассейне."},references={["organization:alliance"]=true,["place:arathi-highlands"]=true}},
    ["place:renders-valley"] = {title="Valle de Render",kind="Lugar",aliases={"Valle de Render"},body="El Valle de Render es un enclave de Crestagrana relacionado con grupos de orcos y taumaturgos. Sus vínculos con otras fuerzas de la zona lo convierten en una preocupación para las autoridades de Villa del Lago.",aliasQuestIDs={},en={title="Render's Valley",aliases={"Render's Valley","Render’s Valley"},body="Render’s Valley is a Redridge enclave associated with groups of orcs and spellcasters. Their ties with other forces in the district make it a concern for Lakeshire’s authorities.",aliasQuestIDs={}},fr={title="Render's Valley",body="Render’s Valley est une enclave Redridge associée à des groupes d'orcs et de lanceurs de sorts. Leurs liens avec les autres forces du district en font une préoccupation pour les autorités de Lakeshire."},de={title="Render's Valley",body="Render’s Valley ist ein Gebiet in Redridge, das mit Gruppen von Orks und Zauberwirkern in Verbindung steht. Ihre Verbindungen zu anderen Kräften der Gegend geben den Behörden von Lakeshire Anlass zur Sorge."},pt={title="Render's Valley",body="Render’s Valley é um enclave Redridge associado a grupos de orcs e conjuradores. Seus laços com outras forças no distrito fazem com que seja uma preocupação para as autoridades do Lakeshire."},pl={title="Render's Valley",body="Render’s Valley to enklawa w Redridge związana z grupami orków i czarowników. Ich powiązania z innymi siłami okolicy niepokoją władze Lakeshire."},ru={title="Render's Valley",body="Render’s Valley - это анклав Redridge, связанный с группами орков и колдунов. Их связи с другими силами в районе делают это проблемой для властей Lakeshire."},references={["place:lakeshire"]=true,["place:redridge-mountains"]=true}},
    ["place:rethban-caverns"] = {title="Cavernas de Rethban",kind="Lugar",aliases={"Cavernas de Rethban"},body="Las Cavernas de Rethban son una explotación de Crestagrana conocida por un mineral de color oscuro. Ese recurso interesa tanto a quienes trabajan el metal como a los escribas que aprovechan su color para elaborar tintes.",aliasQuestIDs={},en={title="Rethban Caverns",aliases={"Rethban Caverns"},body="Rethban Caverns are a Redridge mining site known for a dark-colored ore. The resource interests metalworkers as well as scribes using its color to make inks.",aliasQuestIDs={}},fr={title="Rethban Caverns",body="Rethban Caverns est un site minier Redridge connu pour son minerai de couleur foncée. La ressource intéresse les métallurgistes ainsi que les scribes utilisant sa couleur pour faire des encres."},de={title="Rethban Caverns",body="Rethban Caverns sind ein Redridge-Bergbaugebiet, das für ein dunkelfarbenes Erz bekannt ist. Die Ressource interessiert Metallarbeiter ebenso wie Schreiber, die ihre Farben zur Herstellung von Tinten verwenden."},pt={title="Rethban Caverns",body="Rethban Caverns é um local de mineração Redridge conhecido por um minério de cor escura. Os interesses dos metalúrgicos, bem como escribas usando sua cor para fazer tintas."},pl={title="Rethban Caverns",body="Rethban Caverns to wyrobisko w Redridge znane z ciemnej rudy. Surowiec interesuje zarówno metalurgów, jak i skrybów wykorzystujących jego barwę do produkcji atramentów."},ru={title="Rethban Caverns",body="Rethban Caverns - это зоны добычи Redridge, известные темной рудой. Этот материал интересует металлургов и писарей, которые используют его цвет для изготовления чернил."},references={["place:redridge-mountains"]=true}},
    ["place:revantusk-village"] = {title="Poblado Sañadiente",kind="Lugar",aliases={"Poblado Sañadiente"},body="El Poblado Sañadiente reúne a una comunidad trol de las Tierras del Interior. La pesca, la vigilancia de las criaturas de la costa y los conflictos con sus vecinos influyen en la vida del asentamiento.",aliasQuestIDs={},en={title="Revantusk Village",aliases={"Revantusk Village"},body="Revantusk Village is home to a troll community in the Hinterlands. Fishing, watching coastal creatures and conflicts with neighboring peoples shape the settlement’s life.",aliasQuestIDs={}},fr={title="Revantusk Village",body="Revantusk Village abrite une communauté de trolls dans le Hinterlands. La pêche, l’observation des créatures côtières et les conflits avec les peuples voisins façonnent la vie de la colonie."},de={title="Revantusk Village",body="Revantusk Village beheimatet eine Trollgemeinschaft im Hinterlands. Fischfang, die Beobachtung von Küstenbewohnern und Konflikte mit Nachbarvölkern prägen das Leben in der Siedlung."},pt={title="Revantusk Village",body="Revantusk Village é o lar de uma comunidade de trolls no Hinterlands. Pescar, observar criaturas costeiras e conflitos com os povos vizinhos moldam a vida do assentamento."},pl={title="Revantusk Village",body="Revantusk Village jest domem społeczności trolli w Hinterlands. Rybołówstwo, obserwacja stworzeń wybrzeża i konflikty z sąsiednimi ludami kształtują życie osady."},ru={title="Revantusk Village",body="Revantusk Village является домом для сообщества троллей в Hinterlands. Рыбалка, наблюдение за прибрежными существами и конфликты с соседними народами формируют жизнь поселения."},references={["place:hinterlands"]=true}},
    ["place:ridgepoint-tower"] = {title="Torre de la Peña",kind="Lugar",aliases={"Torre de la Peña"},body="La Torre de la Peña sirve de punto de vigilancia para los caminos de Elwynn. Sus guardias reciben noticias sobre criaturas peligrosas que hostigan a quienes recorren la región.",aliasQuestIDs={},en={title="Ridgepoint Tower",aliases={"Ridgepoint Tower"},body="Ridgepoint Tower is a lookout point for Elwynn’s roads. Its guards receive reports about dangerous creatures harassing travelers through the region.",aliasQuestIDs={}},fr={title="Ridgepoint Tower",body="Ridgepoint Tower est un point d'observation pour les routes de Elwynn. Ses gardes reçoivent des rapports sur des créatures dangereuses qui harcèlent les voyageurs à travers la région."},de={title="Ridgepoint Tower",body="Ridgepoint Tower ist ein Aussichtspunkt für Elwynn \"Straßen. Ihre Wachen erhalten Berichte über gefährliche Kreaturen, die Reisende in der Region belästigen."},pt={title="Ridgepoint Tower",body="Ridgepoint Tower é um ponto de observação para as estradas de Elwynn. Seus guardas recebem relatórios sobre criaturas perigosas assediando viajantes pela região."},pl={title="Ridgepoint Tower",body="Ridgepoint Tower to punkt obserwacyjny dróg Elwynn. Strażnicy otrzymują meldunki o niebezpiecznych stworzeniach nękających podróżnych w regionie."},ru={title="Ridgepoint Tower",body="Ridgepoint Tower — сторожевой пункт, с которого следят за дорогами Elwynn. Его стражники получают сообщения об опасных существах, угрожающих путешественникам в этих землях."},references={["place:elwynn-forest"]=true}},
    ["place:ruins-of-lordaeron"] = {title="Ruinas de Lordaeron",kind="Lugar",aliases={"Ruinas de Lordaeron"},body="Las Ruinas de Lordaeron se extienden sobre Entrañas y conservan sectores amenazados por criaturas y nigromantes. Sus calles y cementerios siguen siendo una preocupación para los defensores de Tirisfal.",aliasQuestIDs={},en={title="Ruins of Lordaeron",aliases={"Ruins of Lordaeron"},body="The Ruins of Lordaeron spread above Undercity and include areas threatened by creatures and necromancers. Their streets and graveyards remain a concern for Tirisfal's defenders.",aliasQuestIDs={}},fr={title="Ruins of Lordaeron",body="Les Ruins of Lordaeron se propagent au-dessus de Undercity et comprennent des zones menacées par des créatures et des nécromanciens. Leurs rues et leurs cimetières restent une préoccupation pour les défenseurs de Tirisfal."},de={title="Ruins of Lordaeron",body="Der Ruins of Lordaeron breitete sich über Undercity aus und umfasste Gebiete, die von Kreaturen und Totenbeschwörern bedroht waren. Ihre Straßen und Friedhöfe bereiten den Verteidigern von Tirisfal nach wie vor Sorgen."},pt={title="Ruins of Lordaeron",body="O Ruins of Lordaeron se espalhou acima do Undercity e inclui áreas ameaçadas por criaturas e necromantes. Suas ruas e cemitérios continuam sendo uma preocupação para os defensores do Tirisfal."},pl={title="Ruins of Lordaeron",body="The Ruins of Lordaeron rozciągają się nad Undercity i obejmują miejsca zagrożone przez stworzenia i nekromantów. Ich ulice oraz cmentarze wciąż niepokoją obrońców Tirisfal."},ru={title="Ruins of Lordaeron",body="Ruins of Lordaeron распространяется над Undercity и включает в себя зоны, подверженные угрозе со стороны существ и некромантов. Их улицы и кладбища остаются проблемой для защитников Tirisfal."},references={["place:lordaeron"]=true,["place:tirisfal-glades"]=true,["place:undercity"]=true}},
    ["place:ruins-of-thaurissan"] = {title="Ruinas de Thaurissan",kind="Lugar",aliases={"Ruinas de Thaurissan","Thaurissan"},body="Las Ruinas de Thaurissan conservan los restos de una antigua ciudad de los Hierro Negro en las Estepas Ardientes. Sus tesoros y vestigios interesan a historiadores y exploradores, aunque los guardianes de la zona vuelven peligrosa cualquier investigación.",aliasQuestIDs={},en={title="Ruins of Thaurissan",aliases={"Ruins of Thaurissan","Thaurissan"},body="The Ruins of Thaurissan preserve the remains of a former Dark Iron city in the Burning Steppes. Its treasures and remnants interest historians and explorers, although local guardians make any investigation dangerous.",aliasQuestIDs={}},fr={title="Ruins of Thaurissan",body="La Ruins of Thaurissan conserve les vestiges d'une ancienne ville Dark Iron dans la Burning Steppes. Ses trésors et vestiges intéressent les historiens et les explorateurs, bien que les gardiens locaux rendent toute enquête dangereuse."},de={title="Ruins of Thaurissan",body="Die Ruins of Thaurissan bewahren die Überreste einer ehemaligen Dark Iron-Stadt im Burning Steppes auf. Seine Schätze und Überreste interessieren Historiker und Forscher, obwohl lokale Wächter jede Untersuchung gefährlich machen."},pt={title="Ruins of Thaurissan",body="O Ruins of Thaurissan preserva os restos de uma antiga cidade Dark Iron no Burning Steppes. Seus tesouros e remanescentes interessam historiadores e exploradores, embora os guardiões locais tornem qualquer investigação perigosa."},pl={title="Ruins of Thaurissan",body="Ruins of Thaurissan zachowują pozostałości dawnego miasta Dark Iron w Burning Steppes. Skarby i szczątki interesują historyków oraz odkrywców, choć miejscowi strażnicy czynią badania niebezpiecznymi."},ru={title="Ruins of Thaurissan",body="Ruins of Thaurissan сохраняют останки бывшего города Dark Iron в Burning Steppes. Его сокровища и остатки интересуют историков и исследователей, хотя местные хранители делают любое расследование опасным."},references={["place:burning-steppes"]=true},questIDs={[3701]=true,[4296]=true}},
    ["place:ruttheran-village"] = {title="Aldea Rut'theran",kind="Lugar",aliases={"Aldea Rut'theran","Aldea Rut’theran","Rut'theran","Rut’theran"},body="La Aldea Rut'theran es un punto de viaje de Teldrassil conectado con Auberdine. Sus transbordadores e hipogrifos permiten transportar visitantes y mercancías entre el gran árbol y la costa de Kalimdor.",aliasQuestIDs={},en={title="Rut'theran Village",aliases={"Rut'theran","Rut'theran Village","Rut’theran","Rut’theran Village"},body="Rut'theran Village is a travel point in Teldrassil connected with Auberdine. Its ferries and hippogryphs carry visitors and goods between the great tree and Kalimdor’s coast.",aliasQuestIDs={}},fr={title="Rut'theran Village",body="Rut'theran Village est un point de déplacement dans Teldrassil connecté à Auberdine. Ses ferries et ses hippogryphes transportent les visiteurs et les marchandises entre le grand arbre et la côte de Kalimdor."},de={title="Rut'theran Village",body="Rut'theran Village ist ein mit Auberdine verbundener Verkehrsknotenpunkt in Teldrassil. Seine Fähren und Hippogryphen befördern Besucher und Waren zwischen dem großen Baum und der Küste von Kalimdor."},pt={title="Rut'theran Village",body="Rut'theran Village é um ponto de viagem em Teldrassil conectado com Auberdine. Seus ferries e hipogrifos transportam visitantes e mercadorias entre a grande árvore e a costa do Kalimdor."},pl={title="Rut'theran Village",body="Rut'theran Village to punkt podróży w Teldrassil połączony z Auberdine. Promy i hipogryfy przewożą przybyszów oraz towary między wielkim drzewem a wybrzeżem kontynentu Kalimdor."},ru={title="Rut'theran Village",body="Rut'theran Village - это точка путешествия в Teldrassil, соединенная с Auberdine. Его паромные лодки и гиппогрифы перевозили посетителей и грузы между большим деревом и побережьем Kalimdor."},references={["place:auberdine"]=true,["place:kalimdor"]=true,["place:teldrassil"]=true}},
    ["place:scarlet-bastion"] = {title="El Bastión Escarlata",kind="Lugar",aliases={"Bastión Escarlata","El Bastión Escarlata"},body="El Bastión Escarlata es el centro de mando de la Cruzada en Stratholme. Las comunicaciones y escoltas que parten de él enlazan sus defensas con posiciones exteriores como Mano de Tyr.",aliasQuestIDs={},en={title="The Scarlet Bastion",aliases={"Scarlet Bastion","The Scarlet Bastion"},body="The Scarlet Bastion is the Crusade's command center in Stratholme. Communications and escorts leaving it connect its defenses with outlying positions such as Tyr's Hand.",aliasQuestIDs={}},fr={title="The Scarlet Bastion",body="The Scarlet Bastion est le centre de commande de Crusade dans Stratholme. Les communications et les escortes qui le quittent connectent ses défenses avec des positions périphériques telles que Tyr's Hand."},de={title="The Scarlet Bastion",body="The Scarlet Bastion ist die Kommandozentrale des Crusade in Stratholme. Kommunikation und Geleitschutz verbinden seine Verteidigung mit Außenpositionen wie Tyr's Hand."},pt={title="The Scarlet Bastion",body="The Scarlet Bastion é o centro de comando do Crusade em Stratholme. Comunicações e acompanhantes deixando-o conectar suas defesas com posições periféricas, como Tyr's Hand."},pl={title="The Scarlet Bastion",body="The Scarlet Bastion jest ośrodkiem dowodzenia Crusade w Stratholme. Wyruszające stamtąd wiadomości i eskorty łączą jego obronę z odległymi pozycjami takimi jak Tyr's Hand."},ru={title="The Scarlet Bastion",body="The Scarlet Bastion - это командный центр Crusade в Stratholme. Коммуникации и сопровождение, покидающие его, связывают его обороны с отдаленными позициями, такими как Tyr's Hand."},references={["organization:scarlet-crusade"]=true,["place:stratholme"]=true,["place:tyrs-hand"]=true}},
    ["place:scarlet-monastery"] = {title="Monasterio Escarlata",kind="Lugar",aliases={"Monasterio Escarlata"},body="El Monasterio Escarlata es un centro de la organización que combate a los no-muertos de Tirisfal. Desde allí parten mensajeros que enlazan con destacamentos de la Cruzada Escarlata.",aliasQuestIDs={},en={title="Scarlet Monastery",aliases={"Scarlet Monastery"},body="The Scarlet Monastery is a center of the organization fighting Tirisfal's undead. Couriers travel from it to link up with Scarlet Crusade detachments.",aliasQuestIDs={}},fr={title="Scarlet Monastery",body="Le Scarlet Monastery est un centre de l'organisation combattant les morts-vivants de Tirisfal. Les coursiers voyagent à partir de celui-ci pour se lier avec les détachements Scarlet Crusade."},de={title="Scarlet Monastery",body="Der Scarlet Monastery ist ein Zentrum der Organisation, die gegen die Untoten von Tirisfal kämpft. Von dort reisen Kuriere an, um sich mit Scarlet Crusade-Abteilungen zu verbinden."},pt={title="Scarlet Monastery",body="O Scarlet Monastery é um centro da organização que luta contra os mortos-vivos do Tirisfal. Couriers viajar a partir dele para ligar-se com destacamentos Scarlet Crusade."},pl={title="Scarlet Monastery",body="The Scarlet Monastery jest ośrodkiem organizacji walczącej z nieumarłymi Tirisfal. Wyruszają stąd kurierzy utrzymujący łączność z oddziałami Scarlet Crusade."},ru={title="Scarlet Monastery",body="Scarlet Monastery - это центр организации, которая борется с неживыми живыми Tirisfal. Курьеры отправляются оттуда, чтобы связаться с отрядами Scarlet Crusade."},references={["organization:scarlet-crusade"]=true,["place:tirisfal-glades"]=true}},
    ["place:scarlet-raven-tavern"] = {title="Mesón del Cuervo Escarlata",kind="Lugar",aliases={"Mesón del Cuervo Escarlata"},body="El Mesón del Cuervo Escarlata es una taberna de Villa Oscura que recibe a vecinos y viajeros. Las conversaciones y las historias que allí se recuerdan conservan parte de la memoria del Bosque del Ocaso.",aliasQuestIDs={},en={title="Scarlet Raven Tavern",aliases={"Scarlet Raven Tavern"},body="The Scarlet Raven Tavern is a Darkshire inn welcoming residents and travelers. Conversations and remembered stories there preserve part of Duskwood’s memory.",aliasQuestIDs={}},fr={title="Scarlet Raven Tavern",body="La Scarlet Raven Tavern est une auberge Darkshire accueillant les résidents et les voyageurs. Des conversations et des histoires mémorables y conservent une partie de la mémoire de Duskwood."},de={title="Scarlet Raven Tavern",body="Das Scarlet Raven Tavern ist ein Darkshire-Wirtshaus, das Bewohner und Reisende willkommen heißt. Gespräche und erinnerliche Geschichten bewahren dort einen Teil des Gedächtnisses von Duskwood."},pt={title="Scarlet Raven Tavern",body="O Scarlet Raven Tavern é uma pousada Darkshire que recebe residentes e viajantes. Conversas e histórias lembradas preservam parte da memória do Duskwood."},pl={title="Scarlet Raven Tavern",body="Scarlet Raven Tavern to gospoda w Darkshire przyjmująca mieszkańców i podróżnych. Rozmowy i wspominane historie zachowują tam część pamięci Duskwood."},ru={title="Scarlet Raven Tavern",body="Scarlet Raven Tavern - это гостиница Darkshire, которая принимает жителей и путешественников. Разговоры и запоминающиеся истории там сохраняют часть памяти Duskwood."},references={["place:darkshire"]=true,["place:duskwood"]=true}},
    ["place:scholomance"] = {title="Scholomance",kind="Lugar",aliases={"Scholomance"},body="Scholomance es una escuela en la isla de Castel Darrow que sirve de bastión a la Plaga. Sus ocupantes realizan investigaciones para aumentar su poder tras una entrada protegida.",aliasQuestIDs={},en={title="Scholomance",aliases={"Scholomance"},body="Scholomance is a school on the island of Caer Darrow serving as a Scourge stronghold. Its occupants conduct research to increase their power behind a protected entrance.",aliasQuestIDs={}},fr={title="Scholomance",body="Scholomance est une école sur l'île de Caer Darrow servant de bastion Scourge. Ses occupants effectuent des recherches pour augmenter leur puissance derrière une entrée protégée."},de={title="Scholomance",body="Scholomance ist eine Schule auf der Insel Caer Darrow, die als Scourge-Hochburg dient. Seine Bewohner forschen, um ihre Macht hinter einem geschützten Eingang zu vergrößern."},pt={title="Scholomance",body="Scholomance é uma escola na ilha de Caer Darrow servindo como um reduto Scourge. Seus ocupantes realizam pesquisas para aumentar seu poder por trás de uma entrada protegida."},pl={title="Scholomance",body="Scholomance jest szkołą na wyspie Caer Darrow służącą jako twierdza Scourge. Za chronionym wejściem jej mieszkańcy prowadzą badania mające zwiększyć ich potęgę."},ru={title="Scholomance",body="Scholomance - это школа на острове Caer Darrow, которая служит крепостью Scourge. Его обитатели проводят исследования, чтобы увеличить свою мощь за защищенным входом."},references={["organization:scourge"]=true,["place:caer-darrow"]=true}},
    ["place:searing-gorge"] = {title="Garganta de Fuego",kind="Lugar",aliases={"Garganta de Fuego","La Garganta de Fuego"},body="La Garganta de Fuego es una región de terreno quemado, minas y actividad industrial. El Puesto del Torio ofrece un punto de encuentro para quienes buscan trabajo y suministros entre los peligros de la zona.",aliasQuestIDs={},en={title="Searing Gorge",aliases={"Searing Gorge"},body="Searing Gorge is a region of scorched ground, mines and industrial activity. Thorium Point provides a gathering place for those seeking work and supplies among the district’s dangers.",aliasQuestIDs={}},fr={title="Searing Gorge",body="Searing Gorge est une région de terre brûlée, de mines et d'activités industrielles. Thorium Point fournit un lieu de rassemblement pour ceux qui cherchent du travail et des fournitures parmi les dangers du district."},de={title="Searing Gorge",body="Searing Gorge ist eine Region mit verbranntem Boden, Minen und industriellen Aktivitäten. Thorium Point ist ein Sammelplatz für Arbeits- und Versorgungssuchende in den Gefahren des Bezirks."},pt={title="Searing Gorge",body="Searing Gorge é uma região de terra queimada, minas e atividade industrial. Thorium Point fornece um local de encontro para aqueles que procuram trabalho e suprimentos entre os perigos do distrito."},pl={title="Searing Gorge",body="Searing Gorge to region spalonej ziemi, kopalń i przemysłu. Thorium Point jest miejscem spotkań osób szukających pracy oraz zaopatrzenia pośród miejscowych niebezpieczeństw."},ru={title="Searing Gorge",body="Searing Gorge - это регион сгоревшей земли, шахт и промышленной деятельности. Thorium Point предоставляет место для тех, кто ищет работу и припасы среди опасностей района."},references={["npc:thorius"]=true,["place:thorium-point"]=true}},
    ["place:senjin-village"] = {title="Poblado Sen'jin",kind="Lugar",aliases={"Poblado Sen'jin","Poblado Sen’jin"},body="El Poblado Sen'jin es una comunidad trol de Durotar, vinculada a los Lanza Negra. La cercanía de la costa y de las Islas del Eco hace que la pesca, la navegación y la defensa del litoral formen parte de su vida cotidiana.",aliasQuestIDs={},en={title="Sen'jin Village",aliases={"Sen'jin Village","Sen’jin Village"},body="Sen'jin Village is a troll community in Durotar associated with the Darkspear. Its proximity to the coast and Echo Isles makes fishing, seafaring and coastal defense part of everyday life.",aliasQuestIDs={}},fr={title="Sen'jin Village",body="Sen'jin Village est une communauté de trolls dans Durotar associée à Darkspear. Sa proximité avec la côte et Echo Isles fait de la pêche, de la navigation et de la défense côtière une partie de la vie quotidienne."},de={title="Sen'jin Village",body="Sen'jin Village ist eine Troll-Gemeinschaft in Durotar, die mit den Darkspear in Verbindung gebracht wird. Seine Nähe zur Küste und zu Echo Isles macht Fischerei, Seefahrt und Küstenverteidigung zum Alltag."},pt={title="Sen'jin Village",body="Sen'jin Village é uma comunidade de trolls no Durotar associada ao Darkspear. Sua proximidade com a costa e Echo Isles faz da pesca, navegação e defesa costeira parte da vida cotidiana."},pl={title="Sen'jin Village",body="Sen'jin Village to społeczność trolli w Durotar związana z plemieniem Darkspear. Bliskość wybrzeża i Echo Isles sprawia, że rybołówstwo, żegluga oraz obrona wybrzeża stanowią część codziennego życia."},ru={title="Sen'jin Village",body="Sen'jin Village - это сообщество троллей в Durotar, связанное с Darkspear. Его близость к побережью и Echo Isles делает рыболовство, мореплавание и береговую оборону частью повседневной жизни."},references={["organization:darkspear-tribe"]=true,["place:durotar"]=true,["place:echo-isles"]=true}},
    ["place:sentinel-hill"] = {title="Colina del Centinela",kind="Lugar",aliases={"Colina del Centinela"},body="La Colina del Centinela sirve como centro de organización de la Milicia Popular en los Páramos de Poniente. Desde este refugio se reúnen noticias sobre los campos, los gnolls y las actividades de los Defias.",aliasQuestIDs={},en={title="Sentinel Hill",aliases={"Sentinel Hill"},body="Sentinel Hill serves as the organizing center of the People’s Militia in Westfall. Reports about the fields, gnolls and Defias activity are gathered at this refuge.",aliasQuestIDs={}},fr={title="Sentinel Hill",body="Sentinel Hill sert de centre d'organisation de la People’s Militia dans Westfall. Des rapports sur les champs, les gnolls et l'activité Defias sont rassemblés dans ce refuge."},de={title="Sentinel Hill",body="Sentinel Hill fungiert als Organisationszentrum des People’s Militia in Westfall. Berichte über die Felder Arbeit der Gnolls und Defias werden in diesem Schutzhaus gesammelt."},pt={title="Sentinel Hill",body="Sentinel Hill serve como o centro organizador do People’s Militia em Westfall. Relatórios sobre os campos, gnolls e Defias atividade estão reunidos neste refúgio."},pl={title="Sentinel Hill",body="Sentinel Hill jest ośrodkiem organizacyjnym People’s Militia w Westfall. W tym schronieniu zbierane są doniesienia o polach, gnollach i działalności Defias."},ru={title="Sentinel Hill",body="Sentinel Hill служит организационным центром People’s Militia в Westfall. Отчеты о полях, гнолах и деятельности Defias собираются в этом убежище."},references={["organization:defias-brotherhood"]=true,["organization:peoples-militia"]=true,["place:westfall"]=true}},
    ["place:shadowfang-keep"] = {title="Castillo de Colmillo Oscuro",kind="Lugar",aliases={"Castillo de Colmillo Oscuro","Colmillo Oscuro"},body="El Castillo de Colmillo Oscuro es una fortaleza que conserva libros y objetos mágicos de gran interés para distintos investigadores. Entre sus tesoros se encuentran estudios de Ur sobre otros mundos.",aliasQuestIDs={},en={title="Shadowfang Keep",aliases={"Shadowfang Keep"},body="Shadowfang Keep is a fortress holding books and magical objects of interest to various researchers. Its treasures include Ur's studies of other worlds.",aliasQuestIDs={}},fr={title="Shadowfang Keep",body="Shadowfang Keep est une forteresse contenant des livres et des objets magiques d'intérêt pour divers chercheurs. Ses trésors comprennent les études d'Ur sur d'autres mondes."},de={title="Shadowfang Keep",body="Shadowfang Keep ist eine Festung mit Büchern und magischen Objekten, die für verschiedene Forscher interessant sind. Zu seinen Schätzen zählen Urs Studien anderer Welten."},pt={title="Shadowfang Keep",body="Shadowfang Keep é uma fortaleza que guarda livros e objetos mágicos de interesse para vários pesquisadores. Seus tesouros incluem estudos de Ur de outros mundos."},pl={title="Shadowfang Keep",body="Shadowfang Keep jest twierdzą kryjącą księgi i magiczne przedmioty interesujące różnych badaczy. Wśród jej skarbów znajdują się badania Ur dotyczące innych światów."},ru={title="Shadowfang Keep",body="Shadowfang Keep - это крепость, в которой хранятся книги и магические предметы, представляющие интерес для различных исследователей. Среди ее сокровищ - исследования Ура других миров."},references={}},
    ["place:shadowglen"] = {title="Cañada Umbría",kind="Lugar",aliases={"Cañada Umbría"},body="Cañada Umbría es una zona de Teldrassil donde se forman nuevos aventureros elfos de la noche. Allí reciben instrucción de sus maestros y aprenden a reconocer los peligros que alteran el bosque.",aliasQuestIDs={},en={title="Shadowglen",aliases={"Shadowglen"},body="Shadowglen is an area of Teldrassil where new night elf adventurers receive their training. Their teachers guide them as they learn to recognize the dangers disturbing the forest.",aliasQuestIDs={}},fr={title="Shadowglen",body="Shadowglen est une zone de Teldrassil où les nouveaux aventuriers elfes de nuit reçoivent leur formation. Leurs enseignants les guident alors qu’ils apprennent à reconnaître les dangers qui perturbent la forêt."},de={title="Shadowglen",body="Shadowglen ist ein Bereich von Teldrassil, in dem neue Nachtelfen-Abenteurer ihre Ausbildung erhalten. Ihre Lehrer führen sie an, während sie lernen, die Gefahren zu erkennen, die den Wald stören."},pt={title="Shadowglen",body="Shadowglen é uma área de Teldrassil onde novos aventureiros de elfo noturno recebem seu treinamento. Seus professores os guiam à medida que aprendem a reconhecer os perigos que perturbam a floresta."},pl={title="Shadowglen",body="Shadowglen to obszar Teldrassil, gdzie początkujący poszukiwacze przygód wśród nocnych elfów przechodzą szkolenie. Nauczyciele prowadzą ich, gdy uczą się rozpoznawać niebezpieczeństwa zakłócające spokój lasu."},ru={title="Shadowglen",body="Shadowglen - это область Teldrassil, где новые приключенцы ночных эльфов получают обучение. Их учителя направляют их, когда они узнают опасности, которые угрожают лесу."},references={["place:teldrassil"]=true}},
    ["place:shadowprey-village"] = {title="Aldea Cazasombras",kind="Lugar",aliases={"Aldea Cazasombras"},body="La Aldea Cazasombras es una comunidad trol de Desolace. Sus habitantes mantienen sus actividades en la costa mientras buscan espacio entre los conflictos y los peligros del interior.",aliasQuestIDs={},en={title="Shadowprey Village",aliases={"Shadowprey Village"},body="Shadowprey Village is a troll community in Desolace. Its residents maintain their coastal livelihoods while finding a place amid the conflicts and dangers of the interior.",aliasQuestIDs={}},fr={title="Shadowprey Village",body="Shadowprey Village est une communauté de trolls dans Desolace. Ses habitants maintiennent leurs moyens de subsistance côtiers tout en trouvant une place au milieu des conflits et des dangers de l'intérieur."},de={title="Shadowprey Village",body="Shadowprey Village ist eine Trollgemeinschaft in Desolace. Seine Bewohner erhalten ihren Lebensunterhalt an der Küste und finden einen Platz inmitten in den Konflikten und Gefahren des Landesinneren."},pt={title="Shadowprey Village",body="Shadowprey Village é uma comunidade de trolls em Desolace. Seus moradores mantêm seus meios de subsistência costeiros enquanto encontram um lugar em meio aos conflitos e perigos do interior."},pl={title="Shadowprey Village",body="Shadowprey Village to społeczność trolli w Desolace. Jej mieszkańcy utrzymują nadmorski sposób życia, szukając dla siebie miejsca pośród konfliktów i zagrożeń w głębi lądu."},ru={title="Shadowprey Village",body="Shadowprey Village - это сообщество троллей в Desolace. Жители города живут на побережье, но находятся в условиях конфликтов и опасностей."},references={["place:desolace"]=true}},
    ["place:shadowvale"] = {title="Vallesombra",kind="Lugar",aliases={"Vallesombra"},body="Vallesombra es una aldea en ruinas del Bosque Susurrante, en Claros de Tirisfal. Antes de la invasión de la Plaga era conocida por el elixir susurrante, una preparación de hierbas apreciada por boticarios, místicos y fabricantes de veneno.",aliasQuestIDs={},en={title="Shadowvale",aliases={"Shadowvale"},body="Shadowvale is a ruined village in the Whispering Forest in Tirisfal Glades. Before the Scourge invasion it was known for Whispering Elixir, an herbal preparation sought by apothecaries, mystics and poisoners.",aliasQuestIDs={}},fr={title="Shadowvale",body="Shadowvale est un village en ruine dans la forêt de Whispering dans Tirisfal Glades. Avant l'invasion the Scourge, il était connu pour Whispering Elixir, une préparation à base de plantes recherchée par les apothicaires, les mystiques et les empoisonneurs."},de={title="Shadowvale",body="Shadowvale ist ein zerstörtes Dorf im Flüsterwald von Tirisfal Glades. Vor der Invasion durch the Scourge war es für sein Flüsterelixier bekannt, ein Kräuterpräparat, das Apotheker, Mystiker und Vergiftende Apotheker und Giftstoffe suchten."},pt={title="Shadowvale",body="Shadowvale é uma aldeia arruinada na Floresta Sussurrante em Tirisfal Glades. Antes da invasão do the Scourge, era conhecido por Whispering Elixir, uma preparação à base de plantas procurada por apotecários, místicos e envenenadores."},pl={title="Shadowvale",body="Shadowvale to zrujnowana wieś w Whispering Forest w Tirisfal Glades. Przed inwazją „the Scourge” słynęła z Whispering Elixir, ziołowej mikstury poszukiwanej przez aptekarzy, mistyków i trucicieli."},ru={title="Shadowvale",body="Shadowvale - это разрушенная деревня в Шепчущем лесу в Tirisfal Glades. До вторжения the Scourge он был известен своим Эликсиром шепота, травяным препаратом, который искали аптеки, мистики и отравляющие."},references={["organization:scourge"]=true,["place:tirisfal-glades"]=true}},
    ["place:shady-rest-inn"] = {title="Posada Reposo Umbrío",kind="Lugar",aliases={"Posada Reposo Umbrío","Reposo Umbrío"},body="La Posada Reposo Umbrío es una posada del Marjal Revolcafango devastada por un incendio. Entre sus restos permanecen una chimenea ennegrecida, objetos dañados y huellas en el barro, testimonios de una tragedia que inquieta a los habitantes de la región.",aliasQuestIDs={},en={title="Shady Rest Inn",aliases={"Shady Rest","Shady Rest Inn"},body="Shady Rest Inn is a Dustwallow Marsh inn devastated by fire. A blackened chimney, damaged objects, and muddy tracks remain among its ruins, evidence of a tragedy troubling the region’s inhabitants.",aliasQuestIDs={}},fr={title="Shady Rest Inn",body="Shady Rest Inn est une auberge Dustwallow Marsh dévastée par le feu. Une cheminée noircie, des objets endommagés et des pistes boueuses restent parmi ses ruines, preuve d’une tragédie troublant les habitants de la région."},de={title="Shady Rest Inn",body="Shady Rest Inn ist ein vom Feuer verwüstetes Dustwallow Marsh Gasthaus. Ein geschwärzter Schornstein, beschädigte Gegenstände und schlammige Spuren bleiben in den Ruinen zurück - ein Beweis für eine Tragödie, die die die die Bewohner der Region beunruhig macht."},pt={title="Shady Rest Inn",body="Shady Rest Inn é uma pousada Dustwallow Marsh devastada pelo fogo. Uma chaminé enegrecidas, objetos danificados e trilhas lamacentas permanecem entre suas ruínas, evidência de uma tragédia que preocupa os habitantes da região."},pl={title="Shady Rest Inn",body="Shady Rest Inn jest gospodą w Dustwallow Marsh spustoszoną przez pożar. Pośród ruin pozostały sczerniały komin, zniszczone przedmioty i błotniste ślady, świadectwa tragedii niepokojącej mieszkańców regionu."},ru={title="Shady Rest Inn",body="Shady Rest Inn - это гостиница Dustwallow Marsh, разрушенная пожаром. Среди руин остались почерневший дымоход, поврежденные предметы и грязные следы, свидетельствующие о трагедии, беспокоящей жителей региона."},references={["place:dustwallow-marsh"]=true}},
    ["place:shendar"] = {title="Aldea Shen'dar",kind="Lugar",aliases={"Aldea Shen'dar","Aldea Shen’dar","Shen'dar","Shen’dar"},body="Shen'dar es una aldea de Isla Zephras amenazada por el Culto de Al'Aketh. Su seguridad está vinculada a la labor de la agente Aonda y a la protección de un pilar cercano. Los informes de la aldea permiten a los pacificadores de Valanaar conocer los peligros que afronta esta comunidad.",aliasQuestIDs={},en={title="Shen'dar Village",aliases={"Shen'dar","Shen'dar Village","Shen’dar","Shen’dar Village"},body="Shen'dar is a village on Zephras Isle threatened by the Al'Aketh Cult. Its security is linked to Constable Aonda's work and the protection of a nearby pylon. Reports from the village keep Valanaar's peacekeepers informed about the dangers facing this community.",aliasQuestIDs={}},fr={title="Shen'dar Village",body="Shen'dar est un village sur Zephras Isle menacé par le Al'Aketh Cult. Sa sécurité est liée au travail de Constable Aonda et à la protection d'un pylône à proximité. Les rapports du village tiennent les soldats de la paix de Valanaar informés des dangers auxquels cette communauté est confrontée."},de={title="Shen'dar Village",body="Shen'dar ist ein Dorf auf Zephras Isle, das vom Al'Aketh Cult bedroht ist. Seine Sicherheit ist mit der Arbeit von Constable Aonda und dem Schutz eines nahe gelegenen Pylons verknüpft. Berichte aus dem Dorf informieren die Friedenstruppen von Valanaar über die Gefahren, denen diese Gemeinschaft ausgesetzt ist."},pt={title="Shen'dar Village",body="Shen'dar é uma vila no Zephras Isle ameaçada pelo Al'Aketh Cult. Sua segurança está ligada ao trabalho de Constable Aonda e à proteção de um poste próximo. Os relatórios da aldeia mantêm as forças de paz da Valanaar informadas sobre os perigos que esta comunidade enfrenta."},pl={title="Shen'dar Village",body="Shen'dar jest wioską na Zephras Isle zagrożoną przez kult znany jako the Al'Aketh Cult. Jej bezpieczeństwo wiąże się z pracą Constable Aonda i ochroną pobliskiego pylonu. Raporty z wioski informują strażników pokoju Valanaar o zagrożeniach społeczności."},ru={title="Shen'dar Village",body="Shen'dar - это деревня на Zephras Isle, которой угрожают Al'Aketh Cult. Его безопасность связана с работой Constable Aonda и защитой соседних пилонов. Отчеты из деревни информируют миротворцев Valanaar об опасностях, с которыми сталкивается это сообщество."},references={["organization:al-aketh"]=true,["person:constable-aonda"]=true,["place:valanaar"]=true,["place:zephras"]=true}},
    ["place:shendar-highlands"] = {title="Tierras Altas de Shen'dar",kind="Lugar",aliases={"Tierras Altas de Shen'dar","Tierras Altas de Shen’dar"},body="Las Tierras Altas de Shen'dar son una región de Zephras conectada por caminos con Valanaar. Albergan formaciones donde se concentra la magia del viento y el Poblado Falaath. La presencia de los Formavientos, los estudios de la Suma Orden y la actividad del Culto de Al'Aketh hacen de esta zona un punto de encuentro conflictivo entre distintas fuerzas de la isla.",aliasQuestIDs={},en={title="Shen'dar Highlands",aliases={"Shen'dar Highlands","Shen’dar Highlands"},body="The Shen'dar Highlands are a region of Zephras connected to Valanaar by road. They contain formations where windborne magic gathers, as well as Falaath Village. The presence of the Windshapers, the High Order's research and the Al'Aketh Cult's activities make this area a contested meeting place for different forces on the island.",aliasQuestIDs={}},fr={title="Shen'dar Highlands",body="Les Shen'dar Highlands sont une région de Zephras reliée à Valanaar par la route. Ils contiennent des formations où la magie du vent se rassemble, ainsi que Falaath Village. La présence de la Windshapers, de la recherche de the High Order et des activités de la Al'Aketh Cult font de cette zone un lieu de rencontre contesté pour les différentes forces de l'île."},de={title="Shen'dar Highlands",body="Die Shen'dar Highlands sind eine Region von Zephras, die durch die Straße mit Valanaar verbunden ist. Sie enthalten Formationen, in denen sich windgetragene Magie sammelt, sowie Falaath Village. Die Anwesenheit der Windshapers, die Forschungen von the High Order und die Aktivitäten der Al'Aketh Cult machen dieses Gebiet zu einem umkämpften Treffpunkt für verschiedene Kräfte auf der Insel."},pt={title="Shen'dar Highlands",body="O Shen'dar Highlands é uma região do Zephras conectada ao Valanaar por estrada. Eles contêm formações onde a magia eólica se reúne, bem como Falaath Village. A presença do Windshapers, a pesquisa do the High Order e as atividades do Al'Aketh Cult fazem desta área um ponto de encontro contestado para diferentes forças na ilha."},pl={title="Shen'dar Highlands",body="The Shen'dar Highlands są regionem Zephras połączonym drogą z Valanaar. Mieszczą formacje gromadzące magię niesioną wiatrem oraz Falaath Village. Obecność społeczności znanej jako the Windshapers, badania organizacji znanej jako the High Order i działania Al'Aketh Cult czynią obszar spornym miejscem spotkania różnych sił wyspy."},ru={title="Shen'dar Highlands",body="Shen'dar Highlands - это область Zephras, соединенная с Valanaar автомобильным транспортом. Они содержат образования, где собирается ветровая магия, а также Falaath Village. Присутствие Windshapers, исследования the High Order и деятельность Al'Aketh Cult делают эту область местом встречи различных сил на острове."},references={["organization:al-aketh"]=true,["organization:high-order"]=true,["organization:windshapers"]=true,["place:falaath-village"]=true,["place:shendar"]=true,["place:valanaar"]=true,["place:zephras"]=true}},
    ["place:shimmering-flats"] = {title="El Desierto de Sal",kind="Lugar",aliases={"Desierto de Sal","El Desierto de Sal"},body="El Desierto de Sal es una amplia extensión de Las Mil Agujas aprovechada para las carreras de vehículos. Inventores, mecánicos y equipos rivales convierten su superficie abierta en un laboratorio de velocidad y competencia.",aliasQuestIDs={},en={title="Shimmering Flats",aliases={"Shimmering Flats","The Shimmering Flats"},body="The Shimmering Flats are a broad salt flat in Thousand Needles used for vehicle racing. Inventors, mechanics and rival teams turn the open ground into a testing place for speed and competition.",aliasQuestIDs={}},fr={title="Shimmering Flats",body="The Shimmering Flats sont un large plat de sel dans Thousand Needles utilisé pour la course automobile. Inventeurs, mécaniciens et équipes rivales transforment le terrain ouvert en un lieu de test pour la vitesse et la compétition."},de={title="Shimmering Flats",body="The Shimmering Flats ist eine breite Streusalzebene in Thousand Needles, die für Autorennen verwendet wird. Erfinder, Mechaniker und rivalisierende Teams verwandeln das offene Gelände in einen Testplatz für Geschwindigkeit und Wettbewerb."},pt={title="Shimmering Flats",body="The Shimmering Flats é um amplo plano de sal em Thousand Needles usado para corridas de veículos. Inventores, mecânicos e equipes rivais transformam o campo aberto em um local de teste para velocidade e competição."},pl={title="Shimmering Flats",body="The Shimmering Flats to rozległe solnisko w regionie Thousand Needles wykorzystywane do wyścigów pojazdów. Wynalazcy, mechanicy i rywalizujące zespoły zamieniają otwarty teren w miejsce prób szybkości oraz współzawodnictwa."},ru={title="Shimmering Flats",body="The Shimmering Flats - это широкая солевая плоскость в Thousand Needles, используемая для гоночных автомобилей. Изобретатели, механики и соперничающие команды превращают открытую землю в место для испытаний скорости и соревнований."},references={["place:thousand-needles"]=true}},
    ["place:shrine-dormant-flame"] = {title="Santuario de la Llama Latente",kind="Lugar",aliases={"Santuario de la Llama Latente"},body="El Santuario de la Llama Latente se encuentra en una cumbre de Loch Modan accesible por un sendero apartado. Es un lugar de aprendizaje chamánico donde el fuego y la preparación de sus ritos tienen un carácter sagrado.",aliasQuestIDs={},en={title="Shrine of the Dormant Flame",aliases={"Shrine of the Dormant Flame"},body="The Shrine of the Dormant Flame stands on a Loch Modan peak reached by an isolated path. It is a place of shamanic learning where fire and the preparation of its rites are sacred.",aliasQuestIDs={}},fr={title="Shrine of the Dormant Flame",body="Le Shrine of the Dormant Flame se trouve sur un pic Loch Modan atteint par un chemin isolé. C’est un lieu d’apprentissage chamanique où le feu et la préparation de ses rites sont sacrés."},de={title="Shrine of the Dormant Flame",body="Der Shrine of the Dormant Flame liegt auf einem Gipfel in Loch Modan, der über einen abgelegenen Pfad erreichbar ist. An diesem Ort schamanischer Lehre sind das Feuer und die Vorbereitung seiner Riten heilig."},pt={title="Shrine of the Dormant Flame",body="O Shrine of the Dormant Flame está em um pico Loch Modan atingido por um caminho isolado. É um lugar de aprendizado xamânico onde o fogo e a preparação de seus ritos são sagrados."},pl={title="Shrine of the Dormant Flame",body="Shrine of the Dormant Flame stoi na szczycie w Loch Modan, dostępnym przez odosobnioną ścieżkę. To miejsce szamańskiej nauki, w którym ogień i przygotowania do jego obrzędów są święte."},ru={title="Shrine of the Dormant Flame",body="Shrine of the Dormant Flame стоит на вершине Loch Modan, достигаемой изолированным путем. Это место шаманского обучения, где огонь и подготовка его обрядов священны."},references={["place:loch-modan"]=true}},
    ["place:shrine-of-flames"] = {title="Santuario de las Llamas",kind="Lugar",aliases={"Santuario de las Llamas"},body="El Santuario de las Llamas se encuentra junto al borde de Isla Zephras, en los Bajíos Ventobaya. Es el lugar donde Olariaan Fuegoveloz recibe a quienes se acercan a la enseñanza del fuego. Su presencia recuerda que, incluso en Muro Celeste, pueden escucharse espíritus de los cuatro elementos.",aliasQuestIDs={},en={title="Shrine of Flames",aliases={"Shrine of Flames"},body="The Shrine of Flames stands near the edge of Zephras Isle in the Gustberry Lowlands. It is where Olariaan Swiftburn receives those approaching the teachings of fire. Its presence reflects that spirits of all four elements can be heard even within Skywall.",aliasQuestIDs={}},fr={title="Shrine of Flames",body="Le Shrine of Flames se trouve près du bord de Zephras Isle dans le Gustberry Lowlands. C’est là que Olariaan Swiftburn reçoit ceux qui s’approchent des enseignements du feu. Sa présence reflète que les esprits des quatre éléments peuvent être entendus même au sein de Skywall."},de={title="Shrine of Flames",body="Der Shrine of Flames steht am Rand von Zephras Isle im Gustberry Lowlands. Hier empfängt Olariaan Swiftburn jene, die sich den Lehren des Feuers nähern. Seine Anwesenheit spiegelt wider, dass die Geister aller vier Elemente sogar in Skywall zu hören sind."},pt={title="Shrine of Flames",body="O Shrine of Flames fica perto da borda do Zephras Isle no Gustberry Lowlands. É onde Olariaan Swiftburn recebe aqueles que se aproximam dos ensinamentos do fogo. Sua presença reflete que os espíritos de todos os quatro elementos podem ser ouvidos mesmo dentro do Skywall."},pl={title="Shrine of Flames",body="The Shrine of Flames stoi przy krańcu Zephras Isle w Gustberry Lowlands. Olariaan Swiftburn przyjmuje tam zbliżających się do nauk ognia. Obecność świątyni odzwierciedla możliwość słyszenia duchów wszystkich czterech żywiołów nawet w Skywall."},ru={title="Shrine of Flames",body="Shrine of Flames находится рядом с краем Zephras Isle в Gustberry Lowlands. Здесь Olariaan Swiftburn принимает тех, кто приближается к учениям огне. Его присутствие отражает, что духи всех четырех элементов можно услышать даже внутри Skywall."},references={["person:olariaan-swiftburn"]=true,["place:gustberry-lowlands"]=true,["place:skywall"]=true,["place:zephras"]=true}},
    ["place:shrine-of-remulos"] = {title="Santuario de Remulos",kind="Lugar",aliases={"Santuario de Remulos"},body="El Santuario de Remulos es un lugar sagrado de Claro de la Luna. Sus altares y guardianes participan en las pruebas con las que los druidas afianzan su relación con la naturaleza.",aliasQuestIDs={},en={title="Shrine of Remulos",aliases={"Shrine of Remulos"},body="The Shrine of Remulos is a sacred place in Moonglade. Its altars and guardians are part of the trials through which druids strengthen their relationship with nature.",aliasQuestIDs={}},fr={title="Shrine of Remulos",body="Le Shrine of Remulos est un lieu sacré dans Moonglade. Ses autels et ses gardiens font partie des épreuves par lesquelles les druides renforcent leur relation avec la nature."},de={title="Shrine of Remulos",body="Der Shrine of Remulos ist ein heiliger Ort in Moonglade. Seine Altäre und Beschützer sind Teil der Prüfungen, durch die Druiden ihre Beziehung zur Natur stärken."},pt={title="Shrine of Remulos",body="O Shrine of Remulos é um lugar sagrado no Moonglade. Seus altares e guardiões fazem parte dos ensaios através dos quais os druidas fortalecem sua relação com a natureza."},pl={title="Shrine of Remulos",body="Shrine of Remulos to święte miejsce w Moonglade. Jego ołtarze i strażnicy uczestniczą w próbach, poprzez które druidzi pogłębiają więź z przyrodą."},ru={title="Shrine of Remulos",body="Shrine of Remulos - это священное место в Moonglade. Его алтари и хранители являются частью испытаний, через которые друиды укрепляют свои отношения с природой."},references={["person:keeper-remulos"]=true,["place:moonglade"]=true}},
    ["place:silithus"] = {title="Silithus",kind="Lugar",aliases={"Silithus"},body="Silithus es una región desértica de Kalimdor donde grandes colmenas y fuerzas hostiles amenazan a los viajeros. El Fuerte Cenarion sirve de apoyo a quienes investigan y contienen los peligros del desierto.",aliasQuestIDs={},en={title="Silithus",aliases={"Silithus"},body="Silithus is a desert region of Kalimdor where great hives and hostile forces threaten travelers. Cenarion Hold supports those investigating and containing the desert’s dangers.",aliasQuestIDs={}},fr={title="Silithus",body="Silithus est une région désertique de Kalimdor où de grandes ruches et des forces hostiles menacent les voyageurs. Cenarion Hold soutient ceux qui enquêtent et contiennent les dangers du désert."},de={title="Silithus",body="Silithus ist eine Wüstenregion von Kalimdor, wo große Bienenstöcke und feindliche Kräfte Reisende bedrohen. Cenarion Hold unterstützt diejenigen, die die die Gefahren der Wüste untersuchen und eindämmen."},pt={title="Silithus",body="Silithus é uma região do deserto de Kalimdor onde grandes colmeias e forças hostis ameaçam os viajantes. Cenarion Hold apoia aqueles que investigam e contêm os perigos do deserto."},pl={title="Silithus",body="Silithus to pustynny region kontynentu Kalimdor, gdzie wielkie roje i wrogie siły zagrażają podróżnym. Cenarion Hold wspiera tych, którzy badają oraz powstrzymują niebezpieczeństwa pustyni."},ru={title="Silithus",body="Silithus - это пустынный регион Kalimdor, где большие ульи и враждебные силы угрожают путешественникам. Cenarion Hold поддерживает тех, кто изучает и сдерживает опасность пустыни."},references={["place:cenarion-hold"]=true,["place:kalimdor"]=true}},
    ["place:silverpine-forest"] = {title="Bosque de Argénteos",kind="Lugar",aliases={"Argénteos","Bosque de Argénteos"},body="El Bosque de Argénteos es una región de caminos, lagos y poblaciones amenazadas por la magia de Arugal. Los Renegados mantienen una base en El Sepulcro y vigilan la presencia de Dalaran en el bosque.",aliasQuestIDs={},en={title="Silverpine Forest",aliases={"Silverpine","Silverpine Forest"},body="Silverpine Forest is a region of roads, lakes and settlements threatened by Arugal's magic. The Forsaken maintain a base at the Sepulcher and monitor Dalaran's presence in the forest.",aliasQuestIDs={}},fr={title="Silverpine Forest",body="Silverpine Forest est une région de routes, de lacs et de colonies menacées par la magie de Arugal. Le Forsaken maintient une base au Sepulcher et surveille la présence du Dalaran dans la forêt."},de={title="Silverpine Forest",body="Silverpine Forest ist eine Region von Straßen, Seen und Siedlungen, die durch den Zauber Arugal 's bedroht sind. Die Forsaken unterhalten einen Stützpunkt am Sepulcher und überwachen Dalaran 'Anwesenheit im Wald."},pt={title="Silverpine Forest",body="Silverpine Forest é uma região de estradas, lagos e assentamentos ameaçados pela magia de Arugal. O Forsaken mantém uma base no Sepulcher e monitora a presença do Dalaran na floresta."},pl={title="Silverpine Forest",body="Silverpine Forest jest krainą dróg, jezior i osad zagrożonych magią Arugal. Społeczność znana jako the Forsaken utrzymuje bazę w Sepulcher i obserwuje obecność Dalaran w lesie."},ru={title="Silverpine Forest",body="Silverpine Forest - это регион дорог, озер и поселений, которым угрожает магия Arugal. Forsaken поддерживают базу в Sepulcher и контролируют присутствие Dalaran в лесу."},references={["npc:arugal"]=true,["organization:forsaken"]=true,["place:dalaran"]=true,["place:the-sepulcher"]=true}},
    ["place:sishir-canyon"] = {title="Cañón Sishir",kind="Lugar",aliases={"Cañón Sishir"},body="El Cañón Sishir forma parte de Sierra Espolón y alberga numerosas arañas. Besseleth y sus crías han tejido allí una guarida que convierte el paso por el cañón en un riesgo para los viajeros.",aliasQuestIDs={},en={title="Sishir Canyon",aliases={"Sishir Canyon"},body="Sishir Canyon is part of Stonetalon Mountains and home to many spiders. Besseleth and her offspring have woven a lair there that makes passage through the canyon dangerous for travelers.",aliasQuestIDs={}},fr={title="Sishir Canyon",body="Sishir Canyon fait partie de Stonetalon Mountains et abrite de nombreuses araignées. Besseleth et sa progéniture y ont tissé une tanière qui rend le passage à travers le canyon dangereux pour les voyageurs."},de={title="Sishir Canyon",body="Sishir Canyon ist Teil von Stonetalon Mountains und Heimat vieler Spinnen. Besseleth und ihr Nachwuchs haben dort ein Versteck gewebt, das die Passage durch den Canyon für Reisende gefährlich macht."},pt={title="Sishir Canyon",body="Sishir Canyon faz parte do Stonetalon Mountains e é o lar de muitas aranhas. Besseleth e sua prole teceram um covil lá que faz a passagem através do cânion perigoso para os viajantes."},pl={title="Sishir Canyon",body="Sishir Canyon jest częścią Stonetalon Mountains i domem wielu pająków. Besseleth i jej potomstwo utkały tam legowisko, przez które przejście kanionem jest niebezpieczne dla podróżnych."},ru={title="Sishir Canyon",body="Sishir Canyon является частью Stonetalon Mountains и является домом для многих пауков. Besseleth и ее потомство создали там норы, которые делают проход через каньон опасным для путешественников."},references={["person:besseleth"]=true,["place:stonetalon-mountains"]=true}},
    ["place:skulk-rock"] = {title="Roca Oculta",kind="Lugar",aliases={"Roca Oculta"},body="Roca Oculta es un conjunto de ruinas de las Tierras del Interior próximo a una antigua base de la Horda. Las babosas y los mocos que ocupan el lugar dificultan recuperar los suministros abandonados allí.",aliasQuestIDs={},en={title="Skulk Rock",aliases={"Skulk Rock"},body="Skulk Rock is a set of Hinterlands ruins near an old Horde base. Slimes and oozes occupying the area make it difficult to recover supplies abandoned there.",aliasQuestIDs={}},fr={title="Skulk Rock",body="Skulk Rock est un ensemble de ruines Hinterlands près d'une ancienne base Horde. Slimes et suintements occupant la zone rendent difficile la récupération des approvisionnements abandonnés là-bas."},de={title="Skulk Rock",body="Skulk Rock ist eine Gruppe von Hinterlands Ruinen in der Nähe eines alten Horde-Stützpunktes. Slimes und seine Kumpel erschweren die Bergung der dort verlassenen Vorräte."},pt={title="Skulk Rock",body="Skulk Rock é um conjunto de ruínas Hinterlands perto de uma antiga base Horde. Slimes e onças que ocupam a área dificultam a recuperação de suprimentos abandonados lá."},pl={title="Skulk Rock",body="Skulk Rock to ruiny w Hinterlands niedaleko dawnej bazy Horde. Zajmujące teren śluzowce i szlamy utrudniają odzyskanie porzuconych zapasów."},ru={title="Skulk Rock",body="Skulk Rock - это набор руин Hinterlands возле старой базы Horde. Slimes и слизи заняли этот район, что затрудняет извлечение запасов, оставленных там."},references={["organization:horde"]=true,["place:hinterlands"]=true}},
    ["place:skull-rock"] = {title="Roca del Cráneo",kind="Lugar",aliases={"Roca del Cráneo"},body="Roca del Cráneo es una cueva de Durotar utilizada por seguidores de la magia demoníaca. Su aislamiento ofrece refugio a cultistas y criaturas que amenazan las tierras próximas a Orgrimmar.",aliasQuestIDs={},en={title="Skull Rock",aliases={"Skull Rock"},body="Skull Rock is a cave in Durotar used by followers of demonic magic. Its isolation shelters cultists and creatures that threaten the lands near Orgrimmar.",aliasQuestIDs={}},fr={title="Skull Rock",body="Skull Rock est une grotte dans Durotar utilisée par les adeptes de la magie démoniaque. Son isolement abrite des cultes et des créatures qui menacent les terres proches de Orgrimmar."},de={title="Skull Rock",body="Skull Rock ist eine Höhle in Durotar, die von Anhängern der dämonischen Magie benutzt wird. Seine Isolation beherbergt Kultisten und Kreaturen, die das Land in der Nähe von Orgrimmar bedrohen."},pt={title="Skull Rock",body="Skull Rock é uma caverna em Durotar usada por seguidores da magia demoníaca. Seu isolamento abriga cultistas e criaturas que ameaçam as terras perto de Orgrimmar."},pl={title="Skull Rock",body="Skull Rock to jaskinia w Durotar wykorzystywana przez wyznawców demonicznej magii. Jej odosobnienie zapewnia schronienie kultystom i stworzeniom zagrażającym ziemiom w pobliżu Orgrimmar."},ru={title="Skull Rock",body="Skull Rock - пещера в Durotar, используемая последователями демонической магии. Его изоляция дает убежище культовым и существам, которые угрожают землям рядом с Orgrimmar."},references={["place:durotar"]=true,["place:orgrimmar"]=true}},
    ["place:skywall"] = {title="Muro Celeste",kind="Lugar",aliases={"Muro Celeste"},body="Muro Celeste es un reino del plano elemental vinculado al viento. Isla Zephras se encuentra dentro de este dominio, aunque sus habitantes también pueden escuchar a los espíritus de los otros elementos. Los fieles de Al'Akir veneran al señor del viento como su gobernante elemental.",aliasQuestIDs={},en={title="Skywall",aliases={"Skywall"},body="Skywall is a realm of the elemental plane associated with wind. Zephras Isle lies within this domain, although its inhabitants can also hear the spirits of the other elements. Al'Akir’s faithful venerate the Windlord as its elemental ruler.",aliasQuestIDs={}},fr={title="Skywall",body="Skywall est un domaine du plan élémentaire associé au vent. Zephras Isle se trouve dans ce domaine, bien que ses habitants puissent également entendre les esprits des autres éléments. Les fidèles de Al'Akir vénèrent le Windlord comme sa règle élémentaire."},de={title="Skywall",body="Skywall ist ein mit dem Wind verbundenes Reich der Elementarebene. Zephras Isle liegt innerhalb dieses Gebiets, doch seine Bewohner können auch die Geister der anderen Elemente hören. Die Gläubigen von Al'Akir verehren den Windlord als dessen elementaren Herrscher."},pt={title="Skywall",body="Skywall é um reino do plano elementar associado ao vento. Zephras Isle encontra-se dentro deste domínio, embora seus habitantes também possam ouvir os espíritos dos outros elementos. Os fiéis do Al'Akir veneram o Windlord como seu governante elementar."},pl={title="Skywall",body="Skywall jest krainą planu żywiołów związaną z wiatrem. Zephras Isle leży w tej domenie, choć mieszkańcy słyszą także duchy innych żywiołów. Wierni Al'Akir czczą Windlord jako jej władcę żywiołów."},ru={title="Skywall",body="Skywall - это область элементарной плоскости, связанная с ветром. Zephras Isle находится в этой области, хотя его жители также могут слышать духи других элементов. Верные Al'Akir  почитают Windlord как своего элементарного правителя."},references={["npc:alakir"]=true,["place:zephras"]=true}},
    ["place:slaughtered-lamb"] = {title="El Cordero Degollado",kind="Lugar",aliases={"Cordero Degollado","El Cordero Degollado"},body="El Cordero Degollado es un local de Ventormenta que sirve de punto de encuentro a brujos. Sus espacios interiores y sus criptas se utilizan para la instrucción y la preparación de invocaciones.",aliasQuestIDs={},en={title="The Slaughtered Lamb",aliases={"Slaughtered Lamb","The Slaughtered Lamb"},body="The Slaughtered Lamb is a Stormwind establishment serving as a meeting place for warlocks. Its interior rooms and crypts are used for instruction and preparing summons.",aliasQuestIDs={}},fr={title="The Slaughtered Lamb",body="The Slaughtered Lamb est un établissement Stormwind servant de lieu de rencontre pour les démonistes. Ses salles intérieures et cryptes sont utilisées pour l'instruction et la préparation des convocations."},de={title="The Slaughtered Lamb",body="The Slaughtered Lamb ist ein Stormwind-Etablissement, das als Treffpunkt für Hexenmeister dient. Seine Innenräume und Krypten werden für Belehrungen und Vorladungen genutzt."},pt={title="The Slaughtered Lamb",body="The Slaughtered Lamb é um estabelecimento Stormwind que serve como um ponto de encontro para bruxos. Seus quartos interiores e criptas são usados para instrução e preparação de intimações."},pl={title="The Slaughtered Lamb",body="The Slaughtered Lamb to lokal w Stormwind będący miejscem spotkań czarnoksiężników. Wewnętrzne pomieszczenia i krypty służą nauce oraz przygotowywaniu przywołań."},ru={title="The Slaughtered Lamb",body="The Slaughtered Lamb - это учреждение Stormwind, которое служит местом встречи для чернокнижников. Внутренние комнаты и склепы используются для обучения и подготовки призывов."},references={["place:stormwind"]=true}},
    ["place:south-seas"] = {title="Mares del Sur",kind="Lugar",aliases={"Mares del Sur"},body="Los Mares del Sur son una región marítima con numerosas islas, rutas comerciales y comunidades trol. Las expediciones y los comerciantes de Tuercespina mantienen vínculos con estas tierras, que también albergan hogares y refugios de los Zandalar.",aliasQuestIDs={},en={title="South Seas",aliases={"South Seas"},body="The South Seas are a maritime region of many islands, trade routes and troll communities. Stranglethorn’s expeditions and merchants maintain ties with these lands, which also include Zandalar homes and havens.",aliasQuestIDs={}},fr={title="South Seas",body="Les South Seas sont une région maritime de nombreuses îles, routes commerciales et communautés de trolls. Les expéditions et les marchands de Stranglethorn entretiennent des liens avec ces terres, qui comprennent également des maisons et des refuges Zandalar."},de={title="South Seas",body="Die South Seas sind eine Meeresregion mit zahlreichen Inseln, Handelsrouten und Trollgemeinschaften. Expeditionen und Händler aus Stranglethorn pflegen Verbindungen zu diesen Ländern, in denen sich auch Wohnorte und Zufluchtsstätten der Zandalar befinden."},pt={title="South Seas",body="O South Seas é uma região marítima de muitas ilhas, rotas comerciais e comunidades de trolls. As expedições e os comerciantes da Stranglethorn mantêm laços com essas terras, que também incluem casas e paraísos Zandalar."},pl={title="South Seas",body="South Seas to morski region licznych wysp, szlaków handlowych i społeczności trolli. Wyprawy i kupcy Stranglethorn utrzymują więzi z tymi ziemiami, obejmującymi także domy i schronienia Zandalar."},ru={title="South Seas",body="South Seas - это морской регион, многочисленные острова, торговые пути и сообщества троллей. Экспедиции и торговцы Stranglethorn  поддерживают связи с этими землями, которые также включают дома и гавани Zandalar."},references={["organization:zandalar-tribe"]=true,["place:stranglethorn-vale"]=true}},
    ["place:southshore"] = {title="Costasur",kind="Lugar",aliases={"Costasur"},body="Costasur es una comunidad humana de las Laderas de Trabalomas. Sus autoridades, comerciantes y cuidadores de caballos intentan mantener la seguridad frente a las amenazas de las montañas y los caminos.",aliasQuestIDs={},en={title="Southshore",aliases={"Southshore"},body="Southshore is a human community in the Hillsbrad Foothills. Its officials, traders and horse keepers try to maintain safety against threats from the mountains and roads.",aliasQuestIDs={}},fr={title="Southshore",body="Southshore est une communauté humaine dans le Hillsbrad Foothills. Ses fonctionnaires, les commerçants et les gardiens de chevaux tentent de maintenir la sécurité contre les menaces des montagnes et des routes."},de={title="Southshore",body="Southshore ist eine menschliche Gemeinschaft im Hillsbrad Foothills. Seine Beamten, Händler und Pferdehalter versuchen, die Sicherheit vor Bedrohungen durch Berge und Straßen aufrechtzuerhalten."},pt={title="Southshore",body="Southshore é uma comunidade humana no Hillsbrad Foothills. Seus funcionários, comerciantes e detentores de cavalos tentam manter a segurança contra ameaças das montanhas e estradas."},pl={title="Southshore",body="Southshore to ludzka społeczność w Hillsbrad Foothills. Urzędnicy, kupcy i hodowcy koni próbują zapewnić bezpieczeństwo wobec zagrożeń z gór i dróg."},ru={title="Southshore",body="Southshore - это человеческое сообщество в Hillsbrad Foothills. Ее чиновники, торговцы и владельцы лошадей стараются защищать от угроз с гор и дорог."},references={["place:hillsbrad-foothills"]=true}},
    ["place:splintertree-post"] = {title="Puesto del Hachazo",kind="Lugar",aliases={"Puesto Hachazo","Puesto del Hachazo"},body="El Puesto del Hachazo es un asentamiento de la Horda en Vallefresno. Sus habitantes organizan patrullas y expediciones en un bosque donde la caza, la explotación de recursos y la defensa del territorio se entrecruzan.",aliasQuestIDs={},en={title="Splintertree Post",aliases={"Splintertree Post"},body="Splintertree Post is a Horde settlement in Ashenvale. Its residents organize patrols and expeditions in a forest where hunting, resource gathering and territorial defense overlap.",aliasQuestIDs={}},fr={title="Splintertree Post",body="Splintertree Post est un règlement Horde dans Ashenvale. Ses habitants organisent des patrouilles et des expéditions dans une forêt où la chasse, la collecte de ressources et la défense territoriale se chevauchent."},de={title="Splintertree Post",body="Splintertree Post ist eine Horde-Siedlung in Ashenvale. Seine Bewohner organisieren Patrouillen und Expeditionen in einem Wald, in dem sich Jagd, Ressourcensammlung und territoriale Verteidigung überschneiden."},pt={title="Splintertree Post",body="Splintertree Post é um assentamento Horde em Ashenvale. Seus moradores organizam patrulhas e expedições em uma floresta onde a caça, coleta de recursos e defesa territorial se sobrepõem."},pl={title="Splintertree Post",body="Splintertree Post to osada frakcji Horde w Ashenvale. Jej mieszkańcy organizują patrole i wyprawy w lesie, gdzie polowania, zbieranie surowców i obrona terytorium wzajemnie się przenikają."},ru={title="Splintertree Post",body="Splintertree Post — поселение Horde на территории Ashenvale. Его жители организуют патрулирование и экспедиции в лесу, где охота, сбор ресурсов и территориальная оборона перекрываются."},references={["organization:horde"]=true,["place:ashenvale"]=true}},
    ["place:starbreeze-village-teldrassil"] = {title="Aldea Brisa Estelar",kind="Lugar",aliases={"Aldea Brisa Estelar","Brisa Estelar"},body="La Aldea Brisa Estelar es un asentamiento de Teldrassil donde vive el celador Gaerolas Talvethren. Su tranquilidad se ha perdido por la corrupción de los fúrbolgs que ahora ocupan el lugar, junto a hogares y pertenencias que quedaron atrás.",aliasQuestIDs={},en={title="Starbreeze Village",aliases={"Starbreeze","Starbreeze Village"},body="Starbreeze Village is a Teldrassil settlement where Warden Gaerolas Talvethren lives. Its peace has been lost to the corruption of the furbolgs now occupying it, amid homes and belongings left behind.",aliasQuestIDs={}},fr={title="Starbreeze Village",body="Starbreeze Village est un établissement Teldrassil où habite le directeur Gaerolas Talvethren. Sa paix a été perdue à cause de la corruption des furbolgs qui l’occupent maintenant, au milieu des maisons et des biens laissés derrière."},de={title="Starbreeze Village",body="Starbreeze Village ist eine Teldrassil-Siedlung, in der Aufseher Gaerolas Talvethren wohnt. Sein Frieden ist durch die Korruption der Furbolgs verloren gegangen, die es jetzt besetzen, inmitten von Häusern und hinterlassenem Hab."},pt={title="Starbreeze Village",body="Starbreeze Village é um assentamento Teldrassil onde Warden Gaerolas Talvethren vive. Sua paz foi perdida para a corrupção dos furbolgs que agora a ocupam, em meio a casas e pertences deixados para trás."},pl={title="Starbreeze Village",body="Starbreeze Village jest osadą w Teldrassil, w której mieszka strażnik Gaerolas Talvethren. Utraciła spokój wskutek skażenia furbolgów, które teraz ją zajmują, pośród pozostawionych domów i dobytku."},ru={title="Starbreeze Village",body="Starbreeze Village — поселение Teldrassil, где живёт смотритель Gaerolas Talvethren. Его мирная жизнь была разрушена порчей фурболгов, теперь занявших эти земли среди оставленных домов и вещей."},references={["person:gaerolas-talvethren"]=true,["place:teldrassil"]=true},questIDs={[475]=true,[2438]=true}},
    ["place:starfall-village"] = {title="Aldea Estrella Fugaz",kind="Lugar",aliases={"Aldea Estrella Fugaz"},body="La Aldea Estrella Fugaz es un asentamiento de Cuna del Invierno. Sus habitantes y visitantes mantienen una presencia en las montañas mientras intentan comprender los ataques y alteraciones que afectan a las criaturas cercanas.",aliasQuestIDs={},en={title="Starfall Village",aliases={"Starfall Village"},body="Starfall Village is a settlement in Winterspring. Its inhabitants and visitors maintain a presence in the mountains while trying to understand the attacks and disturbances affecting nearby creatures.",aliasQuestIDs={}},fr={title="Starfall Village",body="Starfall Village est un règlement dans Winterspring. Ses habitants et visiteurs maintiennent une présence dans les montagnes tout en essayant de comprendre les attaques et les perturbations affectant les créatures voisines."},de={title="Starfall Village",body="Starfall Village ist eine Siedlung in Winterspring. Seine Bewohner und Besucher sind in den Bergen präsent, während sie versuchen, die Angriffe und Störungen zu verstehen, die nahe gelegene Kreaturen betreffen."},pt={title="Starfall Village",body="Starfall Village é um assentamento em Winterspring. Seus habitantes e visitantes mantêm uma presença nas montanhas enquanto tentam entender os ataques e distúrbios que afetam as criaturas próximas."},pl={title="Starfall Village",body="Starfall Village to osada w Winterspring. Mieszkańcy i przybysze utrzymują obecność w górach, próbując zrozumieć ataki oraz zaburzenia dotykające pobliskie stworzenia."},ru={title="Starfall Village",body="Starfall Village - это поселение в Winterspring. Жители и посетители сохраняют присутствие в горах, пытаясь понять нападения и беспорядки, влияющие на близлежащие существа."},references={["place:winterspring"]=true}},
    ["place:steamwheedle-port"] = {title="Puerto Bonvapor",kind="Lugar",aliases={"Puerto Bonvapor"},body="El Puerto Bonvapor es un asentamiento costero de Tanaris. Sus habitantes y comerciantes dependen del mar, pero la proximidad de los piratas obliga a cuidar tanto los negocios como la seguridad de la costa.",aliasQuestIDs={},en={title="Steamwheedle Port",aliases={"Steamwheedle Port"},body="Steamwheedle Port is a coastal settlement in Tanaris. Its residents and traders depend on the sea, but nearby pirates make coastal security as important as business.",aliasQuestIDs={}},fr={title="Steamwheedle Port",body="Steamwheedle Port est une colonie côtière dans Tanaris. Ses habitants et ses commerçants dépendent de la mer, mais les pirates à proximité rendent la sécurité côtière aussi importante que les affaires."},de={title="Steamwheedle Port",body="Steamwheedle Port ist eine Küstensiedlung in Tanaris. Seine Bewohner und Händler sind vom Meer abhängig, aber in der Nähe liegende Piraten machen die Sicherheit der Küsten ebenso wichtig wie das Geschäft."},pt={title="Steamwheedle Port",body="Steamwheedle Port é um assentamento costeiro em Tanaris. Seus moradores e comerciantes dependem do mar, mas os piratas próximos tornam a segurança costeira tão importante quanto os negócios."},pl={title="Steamwheedle Port",body="Steamwheedle Port to nadmorska osada w Tanaris. Mieszkańcy i kupcy zależą od morza, lecz pobliscy piraci sprawiają, że bezpieczeństwo wybrzeża jest równie ważne jak interesy."},ru={title="Steamwheedle Port",body="Steamwheedle Port - это прибрежное поселение в Tanaris. Жители и торговцы города зависят от моря, но пираты делают береговую безопасность не менее важной, чем бизнес."},references={["place:tanaris"]=true}},
    ["place:stillwater-pond"] = {title="Charca Aguaserena",kind="Lugar",aliases={"Charca Aguaserena"},body="La Charca Aguaserena se encuentra al oeste de Rémol. Sus alrededores forman parte de las rutas vigiladas por los subordinados del ejecutor Zygand.",aliasQuestIDs={},en={title="Stillwater Pond",aliases={"Stillwater Pond"},body="Stillwater Pond lies west of Brill. Its surroundings form part of the routes watched by Executor Zygand's subordinates.",aliasQuestIDs={}},fr={title="Stillwater Pond",body="Stillwater Pond se trouve à l'ouest de Brill. Ses environs font partie des itinéraires surveillés par les subordonnés de Executor Zygand."},de={title="Stillwater Pond",body="Stillwater Pond liegt westlich von Brill. Seine Umgebung ist Teil der Routen, die Executor Zygand \"Untergebenen beobachten."},pt={title="Stillwater Pond",body="Stillwater Pond fica a oeste de Brill. Seus arredores fazem parte das rotas observadas pelos subordinados da Executor Zygand."},pl={title="Stillwater Pond",body="Stillwater Pond leży na zachód od Brill. Jego okolice należą do tras obserwowanych przez podwładnych Executor Zygand."},ru={title="Stillwater Pond",body="Stillwater Pond находится к западу от Brill. Его окрестности являются частью маршрутов, наблюдаемых подчиненными Executor Zygand."},references={["npc:executor-zygand"]=true,["place:brill"]=true}},
    ["place:stonard"] = {title="Rocal",kind="Lugar",aliases={"Rocal"},body="Rocal es un asentamiento de la Horda en el Pantano de las Penas. Sus defensores vigilan las amenazas de la costa y recurren a los recursos de las criaturas locales para sostener su equipo.",aliasQuestIDs={},en={title="Stonard",aliases={"Stonard"},body="Stonard is a Horde settlement in the Swamp of Sorrows. Its defenders watch for coastal threats and use materials from local creatures to maintain their equipment.",aliasQuestIDs={}},fr={title="Stonard",body="Stonard est un règlement Horde dans le Swamp of Sorrows. Ses défenseurs surveillent les menaces côtières et utilisent du matériel provenant de créatures locales pour entretenir leur équipement."},de={title="Stonard",body="Stonard ist eine Horde-Siedlung im Swamp of Sorrows. Seine Verteidiger halten Ausschau nach Bedrohungen der Küsten und verwenden Materialien lokaler Kreaturen, um ihre Ausrüstung zu warten."},pt={title="Stonard",body="Stonard é um assentamento Horde no Swamp of Sorrows. Seus defensores vigiam as ameaças costeiras e usam materiais de criaturas locais para manter seus equipamentos."},pl={title="Stonard",body="Stonard to osada Horde w Swamp of Sorrows. Jej obrońcy obserwują zagrożenia nadciągające od wybrzeża i używają materiałów z miejscowych stworzeń do utrzymania wyposażenia."},ru={title="Stonard",body="Stonard - это расчетное заведение Horde в Swamp of Sorrows. Защитники берегов следят за угрозами и используют материалы местных животных для обслуживания своего снаряжения."},references={["organization:horde"]=true,["place:swamp-of-sorrows"]=true}},
    ["place:stone-cairn-lake"] = {title="Lago del Hito",kind="Lugar",aliases={"Lago del Hito"},body="El Lago del Hito es una masa de agua de Elwynn cuyas orillas e islas atraen a exploradores y criaturas hostiles. Los múrlocs instalados allí representan una preocupación para los guardias del bosque.",aliasQuestIDs={},en={title="Stone Cairn Lake",aliases={"Stone Cairn Lake"},body="Stone Cairn Lake is an Elwynn body of water whose shores and islands draw explorers and hostile creatures. Murlocs established there are a concern for the forest’s guards.",aliasQuestIDs={}},fr={title="Stone Cairn Lake",body="Stone Cairn Lake est un plan d'eau Elwynn dont les rivages et les îles attirent les explorateurs et les créatures hostiles. Murlocs a établi qu’il y a une préoccupation pour les gardes de la forêt."},de={title="Stone Cairn Lake",body="Stone Cairn Lake ist ein Elwynn-Gewässer, dessen Ufer und Inseln Entdecker und feindliche Kreaturen anziehen. Murlocs stellte fest, dass sich die Waldschützer Sorgen machen."},pt={title="Stone Cairn Lake",body="Stone Cairn Lake é um corpo de água Elwynn cujas costas e ilhas atraem exploradores e criaturas hostis. Murlocs estabeleceu que há uma preocupação para os guardas da floresta."},pl={title="Stone Cairn Lake",body="Stone Cairn Lake to zbiornik w Elwynn, którego brzegi i wyspy przyciągają odkrywców oraz wrogie stworzenia. Osiedleni tam Murloki niepokoją strażników lasu."},ru={title="Stone Cairn Lake",body="Stone Cairn Lake - это водоем Elwynn, берега и острова которого привлекают исследователей и враждебных существ. Murlocs установили, что есть опасения для лесного охранника."},references={["place:elwynn-forest"]=true}},
    ["place:stonefield-farm"] = {title="Granja Pedregosa",kind="Lugar",aliases={"Granja Pedregosa","La Granja Pedregosa"},body="La Granja Pedregosa es una de las propiedades agrícolas de Elwynn. La protección de los cultivos y las relaciones con las familias vecinas forman parte de las preocupaciones de sus habitantes.",aliasQuestIDs={},en={title="Stonefield Farm",aliases={"Stonefield Farm","Stonefield's Farm","Stonefield’s Farm"},body="Stonefield Farm is one of Elwynn’s farming properties. Protecting crops and dealing with neighboring families are part of its inhabitants’ everyday concerns.",aliasQuestIDs={}},fr={title="Stonefield Farm",body="Stonefield Farm est l'une des propriétés agricoles de Elwynn. Protéger les cultures et traiter avec les familles voisines font partie des préoccupations quotidiennes de ses habitants."},de={title="Stonefield Farm",body="Stonefield Farm ist einer von Elwynn 'Bauernhöfen. Der Schutz von Feldfrüchten und der Umgang mit Nachbarfamilien gehören zu den täglichen Anliegen seiner Bewohner."},pt={title="Stonefield Farm",body="Stonefield Farm é uma das propriedades agrícolas da Elwynn. Proteger as culturas e lidar com as famílias vizinhas fazem parte das preocupações cotidianas de seus habitantes."},pl={title="Stonefield Farm",body="Stonefield Farm jest jednym z gospodarstw Elwynn. Ochrona plonów i kontakty z sąsiednimi rodzinami należą do codziennych trosk mieszkańców."},ru={title="Stonefield Farm",body="Stonefield Farm - это одно из сельскохозяйственных свойств Elwynn. Защита урожая и отношения с соседними семьями - это часть повседневной заботы жителей."},references={["place:elwynn-forest"]=true}},
    ["place:stonetalon-mountains"] = {title="Sierra Espolón",kind="Lugar",aliases={"Espolón","Sierra Espolón"},body="Sierra Espolón es una región montañosa de Kalimdor, con bosques y valles afectados por la explotación y el fuego. En sus caminos coinciden asentamientos de la Horda, defensores de la naturaleza y empresas interesadas en sus recursos.",aliasQuestIDs={},en={title="Stonetalon Mountains",aliases={"Stonetalon","Stonetalon Mountains"},body="The Stonetalon Mountains are a mountainous region of Kalimdor whose woods and valleys suffer from exploitation and fire. Horde settlements, defenders of nature and businesses seeking resources meet along its roads.",aliasQuestIDs={}},fr={title="Stonetalon Mountains",body="Les Stonetalon Mountains sont une région montagneuse de Kalimdor dont les bois et les vallées souffrent de l'exploitation et du feu. Horde colonies, défenseurs de la nature et les entreprises à la recherche de ressources se rencontrent le long de ses routes."},de={title="Stonetalon Mountains",body="Die Stonetalon Mountains sind eine Bergregion von Kalimdor, deren Wälder und Täler unter Ausbeutung und Feuer leiden. Horde-Siedlungen, Naturschützer und ressourcensuchende Unternehmen treffen sich entlang seiner Straßen."},pt={title="Stonetalon Mountains",body="O Stonetalon Mountains é uma região montanhosa do Kalimdor cujas florestas e vales sofrem de exploração e fogo. Os assentamentos Horde, os defensores da natureza e as empresas que buscam recursos se encontram ao longo de suas estradas."},pl={title="Stonetalon Mountains",body="Stonetalon Mountains to górzysty region kontynentu Kalimdor, którego lasy i doliny cierpią wskutek eksploatacji oraz pożarów. Wzdłuż jego dróg spotykają się osady frakcji Horde, obrońcy przyrody i przedsiębiorstwa poszukujące surowców."},ru={title="Stonetalon Mountains",body="Stonetalon Mountains - это горный регион Kalimdor, чьи леса и долины страдают от эксплуатации и пожаров. Вдоль его дорог сходятся поселения Horde, защитники природы и предприятия, ищущие ресурсы."},references={["organization:horde"]=true,["place:kalimdor"]=true}},
    ["place:stonewatch-keep"] = {title="Fuerte de Petravista",kind="Lugar",aliases={"Fuerte de Petravista","Petravista"},body="El Fuerte de Petravista es una fortificación al norte de Villa del Lago. La ocupación de los orcos Roca Negra lo convierte en una base desde la que sus guerreros amenazan a la población de Crestagrana.",aliasQuestIDs={},en={title="Stonewatch Keep",aliases={"Stonewatch","Stonewatch Keep"},body="Stonewatch Keep is a fortification north of Lakeshire. Occupation by Blackrock orcs has made it a base from which their warriors threaten the people of Redridge.",aliasQuestIDs={}},fr={title="Stonewatch Keep",body="Stonewatch Keep est une fortification au nord de Lakeshire. Occupation par Blackrock orcs a fait une base à partir de laquelle leurs guerriers menacent les gens de Redridge."},de={title="Stonewatch Keep",body="Stonewatch Keep ist eine Festung nördlich von Lakeshire. Die Besetzung durch Blackrock orcs hat sie zu einem Stützpunkt gemacht, von dem aus ihre Krieger das Volk von Redridge bedrohen."},pt={title="Stonewatch Keep",body="Stonewatch Keep é uma fortificação ao norte de Lakeshire. Ocupação por Blackrock orcs tornou uma base a partir da qual seus guerreiros ameaçam o povo de Redridge."},pl={title="Stonewatch Keep",body="Stonewatch Keep to fortyfikacja na północ od Lakeshire. Okupacja przez orków Blackrock zmieniła ją w bazę, z której ich wojownicy zagrażają mieszkańcom Redridge."},ru={title="Stonewatch Keep",body="Stonewatch Keep - это укрепление к северу от Lakeshire. Занимание Blackrock orcs сделало его базой, с которой их воины угрожают людям Redridge."},references={["organization:blackrock-clan"]=true,["place:lakeshire"]=true,["place:redridge-mountains"]=true}},
    ["place:stonewrought-dam"] = {title="Presa de las Tres Cabezas",kind="Lugar",aliases={"Presa de las Tres Cabezas"},body="La Presa de las Tres Cabezas es una gran obra de ingeniería que marca el extremo norte del lago de Loch Modan. Su presencia sirve como referencia para los viajeros y para quienes habitan las orillas cercanas.",aliasQuestIDs={},en={title="Stonewrought Dam",aliases={"Stonewrought","Stonewrought Dam"},body="Stonewrought Dam is a major engineering work at the northern end of Loch Modan’s lake. It serves as a landmark for travelers and for the people living along the nearby shores.",aliasQuestIDs={}},fr={title="Stonewrought Dam",body="Stonewrought Dam est un travail d’ingénierie majeur à l’extrémité nord du lac Loch Modan. Il sert de point de repère pour les voyageurs et pour les personnes vivant le long des rives voisines."},de={title="Stonewrought Dam",body="Stonewrought Dam ist ein bedeutender Ingenieur am nördlichen Ende des Loch Modan 's Sees. Es dient als Wahrzeichen für Reisende und für die Menschen, die an den nahe gelegenen Ufern wohnen."},pt={title="Stonewrought Dam",body="Stonewrought Dam é um grande trabalho de engenharia no extremo norte do lago Loch Modan. Ele serve como um marco para os viajantes e para as pessoas que vivem ao longo das costas próximas."},pl={title="Stonewrought Dam",body="Stonewrought Dam to wielka budowla inżynieryjna na północnym krańcu jeziora w Loch Modan. Jest punktem orientacyjnym dla podróżnych i mieszkańców pobliskich brzegów."},ru={title="Stonewrought Dam",body="Stonewrought Dam - это крупное инженерное сооружение на северном конце озера Loch Modan s. Он служит ориентиром для путешественников и людей, живущих вдоль близлежащих берегов."},references={["place:loch-modan"]=true}},
    ["place:stormwind"] = {title="Ventormenta",kind="Lugar",aliases={"Ciudad de Ventormenta","Ventormenta"},body="Ventormenta es una ciudad humana que reúne barrios de comerciantes, magos, artesanos y autoridades militares. Sus habitantes dependen de las rutas y las comunidades de los territorios vecinos, aunque sus recursos no siempre bastan para protegerlos a todos.",aliasQuestIDs={},en={title="Stormwind",aliases={"Stormwind","Stormwind City"},body="Stormwind is a human city bringing together districts of traders, mages, craftspeople and military authorities. Its inhabitants rely on routes and communities in neighboring lands, although its resources do not always stretch to protecting them all.",aliasQuestIDs={}},fr={title="Stormwind",body="Stormwind est une ville humaine réunissant des quartiers de commerçants, mages, artisans et autorités militaires. Ses habitants dépendent des routes et des communautés des pays voisins, bien que ses ressources ne s’étendent pas toujours à la protection de tous."},de={title="Stormwind",body="Stormwind ist eine menschliche Stadt, die Bezirke von Händlern, Magiern, Handwerkern und Militärbehörden zusammenbringt. Seine Bewohner sind auf Routen und Gemeinschaften in Nachbarländern angewiesen, obwohl seine Ressourcen nicht immer ausreichen, um sie alle zu schützen."},pt={title="Stormwind",body="Stormwind é uma cidade humana que reúne distritos de comerciantes, magos, artesãos e autoridades militares. Seus habitantes dependem de rotas e comunidades em terras vizinhas, embora seus recursos nem sempre estiquem para protegê-los a todos."},pl={title="Stormwind",body="Stormwind to ludzkie miasto skupiające dzielnice kupców, magów, rzemieślników i władz wojskowych. Mieszkańcy polegają na szlakach i społecznościach sąsiednich ziem, choć zasobów miasta nie zawsze starcza na ochronę wszystkich."},ru={title="Stormwind",body="Stormwind - это город, объединяющий районы торговцев, магов, ремесленников и военных властей. Жители города полагаются на дороги и населенные пункты в соседних странах, хотя ресурсы не всегда достаточны для защиты всех."},references={}},
    ["place:stormwind-dwarven-district"] = {title="Distrito de los Enanos",kind="Lugar",aliases={"Distrito de los Enanos"},body="El Distrito de los Enanos es una zona de Ventormenta relacionada con artesanos e inventores. Sus talleres conectan la fabricación de equipo con el intercambio de técnicas y materiales entre ciudades.",aliasQuestIDs={},en={title="Dwarven District",aliases={"Dwarven District"},body="The Dwarven District is a Stormwind area associated with craftspeople and inventors. Its workshops connect equipment making with the exchange of techniques and materials between cities.",aliasQuestIDs={}},fr={title="Dwarven District",body="Le Dwarven District est une zone Stormwind associée aux artisans et inventeurs. Ses ateliers relient la fabrication d’équipements à l’échange de techniques et de matériaux entre les villes."},de={title="Dwarven District",body="Der Dwarven District ist ein Stormwind-Gebiet, das mit Handwerkern und Erfindern in Verbindung gebracht wird. Seine Werkstätten verbinden die Geräteherstellung mit dem Austausch von Techniken und Materialien zwischen Städten."},pt={title="Dwarven District",body="O Dwarven District é uma área Stormwind associada a artesãos e inventores. Suas oficinas conectam equipamentos com a troca de técnicas e materiais entre as cidades."},pl={title="Dwarven District",body="Dwarven District to część Stormwind związana z rzemieślnikami i wynalazcami. Warsztaty łączą wytwarzanie wyposażenia z wymianą technik oraz materiałów między miastami."},ru={title="Dwarven District",body="Dwarven District - это зона Stormwind, связанная с ремесленниками и изобретателями. В его мастерских создается связь между производством оборудования и обменом технологиями и материалами между городами."},references={["place:stormwind"]=true}},
    ["place:stormwind-mage-quarter"] = {title="Barrio de los Magos",kind="Lugar",aliases={"Barrio de los Magos"},body="El Barrio de los Magos es una zona de Ventormenta ligada al estudio y la práctica de la magia. Allí se reúnen instructores y discípulos que necesitan conocimientos, materiales y lugares adecuados para sus trabajos.",aliasQuestIDs={},en={title="Mage Quarter",aliases={"Mage Quarter"},body="The Mage Quarter is a Stormwind district associated with the study and practice of magic. Instructors and students there need knowledge, materials and suitable places for their work.",aliasQuestIDs={}},fr={title="Mage Quarter",body="Le Mage Quarter est un quartier Stormwind associé à l'étude et à la pratique de la magie. Les instructeurs et les étudiants ont besoin de connaissances, de matériel et de lieux appropriés pour leur travail."},de={title="Mage Quarter",body="Der Mage Quarter ist ein Stormwind-Distrikt, der mit dem Studium und der Praxis der Magie verbunden ist. Dozenten und Studenten brauchen dort Wissen, Materialien und geeignete Orte für ihre Arbeit."},pt={title="Mage Quarter",body="O Mage Quarter é um distrito Stormwind associado ao estudo e prática da magia. Instrutores e alunos precisam de conhecimento, materiais e lugares adequados para o seu trabalho."},pl={title="Mage Quarter",body="Mage Quarter to dzielnica Stormwind związana z badaniem i praktykowaniem magii. Nauczyciele i uczniowie potrzebują wiedzy, materiałów oraz odpowiednich miejsc do pracy."},ru={title="Mage Quarter",body="Mage Quarter - это район Stormwind, связанный с изучением и практикой магии. Учителям и студентам там нужны знания, материалы и подходящие места для их работы."},references={["place:stormwind"]=true}},
    ["place:stormwind-old-town"] = {title="Casco Antiguo",kind="Lugar",aliases={"Casco Antiguo"},body="El Casco Antiguo es un barrio de Ventormenta donde coinciden comercios, guardias y contactos de inteligencia. Las tiendas y los cuarteles lo conectan tanto con la vida cotidiana de la ciudad como con sus investigaciones discretas.",aliasQuestIDs={},en={title="Old Town",aliases={"Old Town"},body="Old Town is a Stormwind district where shops, guards and intelligence contacts meet. Its businesses and barracks connect it with both everyday city life and discreet investigations.",aliasQuestIDs={}},fr={title="Old Town",body="Old Town est un quartier Stormwind où les magasins, les gardes et les contacts du renseignement se rencontrent. Ses commerces et ses casernes le relient à la vie quotidienne de la ville et aux enquêtes discrètes."},de={title="Old Town",body="Old Town ist ein Stormwind-Viertel, in dem Geschäfte, Wachen und Geheimdienstkontakte zusammentreffen. Seine Geschäfte und Kasernen verbinden es sowohl mit dem Alltag in der Stadt als auch mit diskreten Untersuchungen."},pt={title="Old Town",body="Old Town é um distrito de Stormwind onde lojas, guardas e contatos de inteligência se encontram. Seus negócios e quartéis o conectam com a vida cotidiana da cidade e investigações discretas."},pl={title="Old Town",body="Old Town to dzielnica Stormwind, w której spotykają się sklepy, strażnicy i kontakty wywiadowcze. Przedsiębiorstwa i koszary łączą ją zarówno z codziennością miasta, jak i dyskretnymi dochodzeniami."},ru={title="Old Town",body="Old Town - это район Stormwind, где встречаются магазины, охранники и контакты разведки. Его предприятия и казармы связывают его с повседневной городской жизнью и с дискретными расследованиями."},references={["place:stormwind"]=true}},
    ["place:stormwind-stockade"] = {title="Mazmorras de Ventormenta",kind="Lugar",aliases={"Las Mazmorras","Mazmorras de Ventormenta"},body="Las Mazmorras de Ventormenta son la prisión de la ciudad. Sus celadores deben mantener el orden entre detenidos peligrosos, una responsabilidad que se vuelve crítica cuando estallan los motines.",aliasQuestIDs={},en={title="Stormwind Stockade",aliases={"Stockades","Stormwind Stockade","The Stockade","The Stockades"},body="The Stormwind Stockade is the city’s prison. Its wardens must maintain order among dangerous inmates, a responsibility that becomes critical when riots erupt.",aliasQuestIDs={}},fr={title="Stormwind Stockade",body="Le Stormwind Stockade est la prison de la ville. Ses gardiens doivent maintenir l’ordre parmi les détenus dangereux, une responsabilité qui devient critique lorsque des émeutes éclatent."},de={title="Stormwind Stockade",body="Das Stormwind Stockade ist das Gefängnis der Stadt. Ihre Aufseher müssen die Ordnung unter gefährlichen Häftlingen aufrechterhalten, eine Verantwortung, die bei Ausbruch von Unruhen kritisch wird."},pt={title="Stormwind Stockade",body="O Stormwind Stockade é a prisão da cidade. Seus guardas devem manter a ordem entre os presos perigosos, uma responsabilidade que se torna crítica quando os tumultos entram em erupção."},pl={title="Stormwind Stockade",body="Stormwind Stockade to miejskie więzienie. Strażnicy muszą utrzymywać porządek wśród niebezpiecznych osadzonych, co staje się szczególnie ważne podczas buntów."},ru={title="Stormwind Stockade",body="Stormwind Stockade - это тюрьма города. Его охранники должны поддерживать порядок среди опасных заключенных, и это становится критически важно, когда вспыхивают беспорядки."},references={["place:stormwind"]=true}},
    ["place:stormwind-trade-district"] = {title="Distrito de Mercaderes",kind="Lugar",aliases={"Distrito de Mercaderes"},body="El Distrito de Mercaderes concentra tiendas y negocios de Ventormenta. Sus boticarios y comerciantes reciben materiales y noticias de los poblados vecinos, manteniendo el vínculo de la ciudad con el campo.",aliasQuestIDs={},en={title="Trade District",aliases={"Trade District"},body="The Trade District concentrates Stormwind’s shops and businesses. Its apothecaries and merchants receive materials and news from neighboring settlements, sustaining the city’s ties with the countryside.",aliasQuestIDs={}},fr={title="Trade District",body="Le Trade District concentre les magasins et les entreprises de Stormwind. Ses apothicaires et ses marchands reçoivent des matériaux et des nouvelles des colonies voisines, entretenant les liens de la ville avec la campagne."},de={title="Trade District",body="Im Trade District konzentrieren sich die Geschäfte und Handelsbetriebe von Stormwind. Seine Apotheker und Händler erhalten Materialien und Nachrichten aus benachbarten Siedlungen und halten so die Verbindungen der Stadt zum Umland aufrecht."},pt={title="Trade District",body="O Trade District concentra as lojas e empresas da Stormwind. Seus boticários e comerciantes recebem materiais e notícias de assentamentos vizinhos, sustentando os laços da cidade com o campo."},pl={title="Trade District",body="Trade District skupia sklepy i przedsiębiorstwa Stormwind. Aptekarze oraz kupcy otrzymują materiały i wieści z sąsiednich osad, podtrzymując więzi miasta z okolicznymi ziemiami."},ru={title="Trade District",body="Trade District сосредоточен на магазинах и предприятиях Stormwind. Ее аптеки и торговцы получают материалы и новости из соседних поселений, поддерживая связи города с сельской местностью."},references={["place:stormwind"]=true}},
    ["place:strahnbrad"] = {title="Strahnbrad",kind="Lugar",aliases={"Strahnbrad"},body="Strahnbrad es un asentamiento de Alterac utilizado por grupos de la Hermandad. Los informes y las operaciones de sus exploradores atraen a agentes que intentan averiguar qué busca la organización en las ruinas de la región.",aliasQuestIDs={},en={title="Strahnbrad",aliases={"Strahnbrad"},body="Strahnbrad is an Alterac settlement used by Syndicate groups. Its scouts’ reports and operations draw agents trying to learn what the organization seeks in the region’s ruins.",aliasQuestIDs={}},fr={title="Strahnbrad",body="Strahnbrad est un règlement Alterac utilisé par les groupes Syndicate. Les rapports et les opérations de ses éclaireurs attirent des agents qui tentent d’apprendre ce que l’organisation cherche dans les ruines de la région."},de={title="Strahnbrad",body="Strahnbrad ist eine Alterac-Siedlung, die von Syndicate-Gruppen genutzt wird. Die Berichte und Operationen seiner Kundschafter ziehen Agenten an, die versuchen herauszufinden, was die Organisation in den Ruinen der Region sucht."},pt={title="Strahnbrad",body="Strahnbrad é um acordo Alterac usado por grupos Syndicate. Os relatórios e operações de seus olheiros atraem agentes que tentam aprender o que a organização busca nas ruínas da região."},pl={title="Strahnbrad",body="Strahnbrad jest osadą w Alterac wykorzystywaną przez grupy Syndicate. Meldunki i działania zwiadowców przyciągają agentów próbujących ustalić, czego organizacja szuka w miejscowych ruinach."},ru={title="Strahnbrad",body="Strahnbrad - это распределение Alterac, используемое группами Syndicate. Отчеты и операции разведчиков привлекают агентов, пытающихся узнать, что организация ищет в руинах региона."},references={["organization:syndicate"]=true,["place:alterac-mountains"]=true}},
    ["place:stranglethorn-vale"] = {title="Vega de Tuercespina",kind="Lugar",aliases={"Tuercespina","Vega de Tuercespina"},body="La Vega de Tuercespina es una extensa selva donde coinciden cazadores, expediciones, poblaciones trol y comerciantes. Sus costas y ruinas ofrecen riquezas y conocimientos, pero también disputas por territorio y recursos.",aliasQuestIDs={},en={title="Stranglethorn Vale",aliases={"Stranglethorn","Stranglethorn Vale"},body="Stranglethorn Vale is a vast jungle shared by hunters, expeditions, troll communities and traders. Its coasts and ruins offer wealth and knowledge, alongside disputes over territory and resources.",aliasQuestIDs={}},fr={title="Stranglethorn Vale",body="Stranglethorn Vale est une vaste jungle partagée par les chasseurs, les expéditions, les communautés de trolls et les commerçants. Ses côtes et ses ruines offrent richesse et savoir, ainsi que des différends sur le territoire et les ressources."},de={title="Stranglethorn Vale",body="Stranglethorn Vale ist ein riesiger Dschungel, der von Jägern, Expeditionen, Trollgemeinschaften und Händlern geteilt wird. Seine Küsten und Ruinen bieten Reichtum und Wissen, aber auch Streitigkeiten um Territorien und Ressourcen."},pt={title="Stranglethorn Vale",body="Stranglethorn Vale é uma vasta selva compartilhada por caçadores, expedições, comunidades de trolls e comerciantes. Suas costas e ruínas oferecem riqueza e conhecimento, ao lado de disputas sobre território e recursos."},pl={title="Stranglethorn Vale",body="Stranglethorn Vale to rozległa dżungla, którą dzielą myśliwi, ekspedycje, społeczności trolli i kupcy. Wybrzeża oraz ruiny oferują bogactwo i wiedzę, ale towarzyszą im spory o terytorium oraz zasoby."},ru={title="Stranglethorn Vale",body="Stranglethorn Vale - это огромная джунгли, разделяемая охотниками, экспедициями, сообществами троллей и торговцами. Ее берега и руины предлагают богатство и знания, а также споры о территории и ресурсах."},references={}},
    ["place:stratholme"] = {title="Stratholme",kind="Lugar",aliases={"Stratholme"},body="Stratholme es una ciudad de Lordaeron dominada por fuerzas de la Plaga. El poder del Barón Osahendido y la presencia de criaturas como Ramstein la convierten en un foco de resistencia para los enemigos del Rey Exánime.",aliasQuestIDs={},en={title="Stratholme",aliases={"Stratholme"},body="Stratholme is a Lordaeron city held by Scourge forces. Baron Rivendare's power and creatures such as Ramstein make it a strongpoint confronting the Lich King's enemies.",aliasQuestIDs={}},fr={title="Stratholme",body="Stratholme est une ville Lordaeron détenue par les forces Scourge. Le pouvoir de Baron Rivendare et les créatures telles que Ramstein en font un point fort face aux ennemis de Lich King."},de={title="Stratholme",body="Stratholme ist eine von Scourge gehaltene Lordaeron-Stadt. Baron Rivendare \"Macht und Kreaturen wie Ramstein machen ihn zu einer Stärke gegen die Feinde des Lich King."},pt={title="Stratholme",body="Stratholme é uma cidade Lordaeron mantida pelas forças Scourge. O poder do Baron Rivendare e criaturas como o Ramstein fazem dele um ponto forte confrontando os inimigos do Lich King."},pl={title="Stratholme",body="Stratholme jest miastem Lordaeron zajętym przez siły Scourge. Potęga Baron Rivendare i stworzenia takie jak Ramstein czynią je twierdzą stojącą na drodze wrogów Lich King."},ru={title="Stratholme",body="Stratholme - это город Lordaeron, удерживаемый силами Scourge. Сила Baron Rivendare и такие существа, как Ramstein делают его сильной точкой для противостояния врагам Lich King."},references={["npc:baron-rivendare"]=true,["npc:lich-king"]=true,["npc:ramstein-the-gorger"]=true,["organization:scourge"]=true,["place:lordaeron"]=true}},
    ["place:stromgarde"] = {title="Stromgarde",kind="Lugar",aliases={"Stromgarde"},body="Stromgarde es una fortaleza de las Tierras Altas de Arathi cuyos muros albergan fuerzas enfrentadas. Su castillo posee importancia estratégica para las organizaciones que buscan refugio, influencia y control sobre las rutas de la región.",aliasQuestIDs={},en={title="Stromgarde",aliases={"Stromgarde"},body="Stromgarde is a fortress in the Arathi Highlands whose walls house competing forces. Its castle is strategically important to organizations seeking shelter, influence and control of the region’s routes.",aliasQuestIDs={}},fr={title="Stromgarde",body="Stromgarde est une forteresse dans le Arathi Highlands dont les murs abritent des forces concurrentes. Son château est stratégiquement important pour les organisations qui cherchent un abri, une influence et un contrôle sur les routes de la région."},de={title="Stromgarde",body="Stromgarde ist eine Festung im Arathi Highlands, dessen Mauern konkurrierende Kräfte beherbergen. Seine Burg ist strategisch wichtig für Organisationen, die Schutz, Einfluss und Kontrolle über die Routen der Region suchen."},pt={title="Stromgarde",body="Stromgarde é uma fortaleza no Arathi Highlands cujas paredes abrigam forças concorrentes. Seu castelo é estrategicamente importante para organizações que buscam abrigo, influência e controle das rotas da região."},pl={title="Stromgarde",body="Stromgarde to twierdza w Arathi Highlands, której mury mieszczą rywalizujące siły. Zamek ma strategiczne znaczenie dla organizacji poszukujących schronienia, wpływów i kontroli nad drogami regionu."},ru={title="Stromgarde",body="Stromgarde - крепость в Arathi Highlands, стены которой вмещают конкурирующие силы. Его замок имеет стратегическое значение для организаций, ищущих убежища, влияния и контроля над маршрутами региона."},references={["person:zamek"]=true,["place:arathi-highlands"]=true}},
    ["place:sun-rock-retreat"] = {title="Refugio Roca del Sol",kind="Lugar",aliases={"Refugio Roca del Sol"},body="El Refugio Roca del Sol es un asentamiento de la Horda en Sierra Espolón. Sirve como punto de apoyo en una región donde los espíritus elementales, las talas y los incendios alteran la vida de los habitantes.",aliasQuestIDs={},en={title="Sun Rock Retreat",aliases={"Sun Rock Retreat"},body="Sun Rock Retreat is a Horde settlement in the Stonetalon Mountains. It serves as a foothold in a region where elemental spirits, logging and fires disrupt the lives of its inhabitants.",aliasQuestIDs={}},fr={title="Sun Rock Retreat",body="Sun Rock Retreat est un règlement Horde dans le Stonetalon Mountains. Il sert de point d’ancrage dans une région où les esprits élémentaires, l’exploitation forestière et les incendies perturbent la vie de ses habitants."},de={title="Sun Rock Retreat",body="Sun Rock Retreat ist eine Horde-Siedlung im Stonetalon Mountains. Es dient als Stützpunkt in einer Region, in der Elementare Geister, Holzeinschlag und Feuer das Leben seiner Bewohner stören."},pt={title="Sun Rock Retreat",body="Sun Rock Retreat é um assentamento Horde no Stonetalon Mountains. Ele serve como um ponto de apoio em uma região onde espíritos elementares, extração de madeira e incêndios perturbam a vida de seus habitantes."},pl={title="Sun Rock Retreat",body="Sun Rock Retreat to osada frakcji Horde w regionie Stonetalon Mountains. Stanowi punkt oparcia na ziemiach, gdzie duchy żywiołów, wyrąb lasów i pożary zakłócają życie mieszkańców."},ru={title="Sun Rock Retreat",body="Sun Rock Retreat - это расчетное заведение Horde в Stonetalon Mountains. Он служит опорой в регионе, где стихийные духи, вырубка леса и пожары разрушают жизнь его жителей."},references={["organization:horde"]=true,["place:stonetalon-mountains"]=true}},
    ["place:swamp-of-sorrows"] = {title="Pantano de las Penas",kind="Lugar",aliases={"El Pantano de las Penas","Pantano de las Penas"},body="El Pantano de las Penas reúne aguas turbias, ruinas y comunidades que viven entre amenazas naturales y mágicas. Sus habitantes estudian materiales extraños y vigilan los peligros que se ocultan en el pantano y en la costa.",aliasQuestIDs={},en={title="Swamp of Sorrows",aliases={"Swamp of Sorrows"},body="The Swamp of Sorrows contains murky waters, ruins and communities living among natural and magical threats. Its inhabitants study strange materials and watch for dangers hidden in the swamp and along the coast.",aliasQuestIDs={}},fr={title="Swamp of Sorrows",body="Le Swamp of Sorrows contient des eaux troubles, des ruines et des communautés vivant parmi des menaces naturelles et magiques. Ses habitants étudient des matériaux étranges et surveillent les dangers cachés dans le marais et le long de la côte."},de={title="Swamp of Sorrows",body="Der Swamp of Sorrows enthält trübe Gewässer, Ruinen und Gemeinschaften, die inmitten natürlicher und magischer Bedrohungen leben. Seine Bewohner studieren seltsame Materialien und halten Ausschau nach Gefahren, die sich im Sumpf und entlang der Küste verstecken."},pt={title="Swamp of Sorrows",body="O Swamp of Sorrows contém águas turvas, ruínas e comunidades que vivem entre ameaças naturais e mágicas. Seus habitantes estudam materiais estranhos e observam os perigos escondidos no pântano e ao longo da costa."},pl={title="Swamp of Sorrows",body="Swamp of Sorrows obejmuje mętne wody, ruiny i społeczności żyjące pośród naturalnych oraz magicznych zagrożeń. Mieszkańcy badają niezwykłe materiały i wypatrują niebezpieczeństw ukrytych na bagnach oraz wzdłuż wybrzeża."},ru={title="Swamp of Sorrows",body="В Swamp of Sorrows есть мрачные воды, руины и общины, живущие среди природных и магических угроз. Жители изучают необычные материалы и наблюдают за опасностями, скрытыми в болоте и вдоль побережья."},references={}},
    ["place:tanaris"] = {title="Tanaris",kind="Lugar",aliases={"Tanaris"},body="Tanaris es una región desértica del sur de Kalimdor. Sus poblados comerciales dependen de rutas expuestas a piratas, bandidos y criaturas que se disputan los escasos recursos del desierto.",aliasQuestIDs={},en={title="Tanaris",aliases={"Tanaris"},body="Tanaris is a desert region in southern Kalimdor. Its trading settlements depend on routes exposed to pirates, bandits and creatures competing for the desert’s scarce resources.",aliasQuestIDs={}},fr={title="Tanaris",body="Tanaris est une région désertique dans le sud de Kalimdor. Ses colonies commerciales dépendent des routes exposées aux pirates, aux bandits et aux créatures en compétition pour les ressources rares du désert."},de={title="Tanaris",body="Tanaris ist eine Wüstenregion im Süden von Kalimdor. Seine Handelssiedlungen sind von Routen abhängig, die Piraten, Banditen und Kreaturen ausgesetzt sind, die um die um die knappen Ressourcen der Wüste konkurrieren."},pt={title="Tanaris",body="Tanaris é uma região do deserto no sul de Kalimdor. Seus assentamentos comerciais dependem de rotas expostas a piratas, bandidos e criaturas que competem pelos escassos recursos do deserto."},pl={title="Tanaris",body="Tanaris to pustynny region na południu kontynentu Kalimdor. Osady handlowe zależą od szlaków narażonych na ataki piratów, bandytów i stworzeń walczących o skąpe zasoby pustyni."},ru={title="Tanaris",body="Tanaris - это пустынный регион на юге Kalimdor. Торговые поселения зависят от маршрутов, где находятся пираты, бандиты и другие существа, конкурирующие за редкие ресурсы пустыни."},references={["place:kalimdor"]=true}},
    ["place:tarren-mill"] = {title="Molino Tarren",kind="Lugar",aliases={"Molino Tarren"},body="Molino Tarren es una base de los Renegados en las Laderas de Trabalomas. Desde allí se dirigen operaciones militares y de inteligencia en un territorio disputado.",aliasQuestIDs={},en={title="Tarren Mill",aliases={"Tarren Mill"},body="Tarren Mill is a Forsaken base in Hillsbrad Foothills. Military and intelligence operations are directed from there across disputed territory.",aliasQuestIDs={}},fr={title="Tarren Mill",body="Tarren Mill est une base Forsaken dans Hillsbrad Foothills. Les opérations militaires et de renseignement sont dirigées à partir de là à travers le territoire contesté."},de={title="Tarren Mill",body="Tarren Mill ist ein Forsaken-Stützpunkt in Hillsbrad Foothills. Von dort aus werden militärische und geheimdienstliche Operationen über umstrittenes Gebiet gelenkt."},pt={title="Tarren Mill",body="Tarren Mill é uma base Forsaken em Hillsbrad Foothills. Operações militares e de inteligência são dirigidas de lá através do território disputado."},pl={title="Tarren Mill",body="Tarren Mill jest bazą Forsaken w Hillsbrad Foothills. Kieruje się stąd działaniami wojskowymi i wywiadowczymi na spornym terytorium."},ru={title="Tarren Mill",body="Tarren Mill - это база Forsaken в Hillsbrad Foothills. Оттуда ведутся военные и разведывательные операции по всей спорной территории."},references={["organization:forsaken"]=true}},
    ["place:teldrassil"] = {title="Teldrassil",kind="Lugar",aliases={"Teldrassil"},body="Teldrassil es el gran árbol que alberga comunidades de los elfos de la noche y la ciudad de Darnassus. Sus habitantes intentan proteger el equilibrio natural mientras investigan señales de enfermedad y corrupción en su nuevo hogar.",aliasQuestIDs={},en={title="Teldrassil",aliases={"Teldrassil"},body="Teldrassil is the great tree that shelters night elf communities and the city of Darnassus. Its inhabitants try to protect the natural balance while investigating signs of sickness and corruption in their new home.",aliasQuestIDs={}},fr={title="Teldrassil",body="Teldrassil est le grand arbre qui abrite les communautés d'elfes de nuit et la ville de Darnassus. Ses habitants tentent de protéger l'équilibre naturel tout en enquêtant sur les signes de maladie et de corruption dans leur nouvelle maison."},de={title="Teldrassil",body="Teldrassil ist der große Baum, der die Nachtelfengemeinden und die Stadt Darnassus beherbergt. Seine Bewohner versuchen, das natürliche Gleichgewicht zu schützen, während sie Anzeichen von Krankheit und Korruption in ihrer neuen Heimat untersuchen."},pt={title="Teldrassil",body="Teldrassil é a grande árvore que abriga as comunidades de elfos noturnos e a cidade de Darnassus. Seus habitantes tentam proteger o equilíbrio natural enquanto investigam sinais de doença e corrupção em sua nova casa."},pl={title="Teldrassil",body="Teldrassil to wielkie drzewo dające schronienie społecznościom nocnych elfów oraz miastu Darnassus. Mieszkańcy starają się chronić równowagę przyrody, badając oznaki choroby i skażenia w swoim nowym domu."},ru={title="Teldrassil",body="Teldrassil - это великое дерево, которое укрывает сообщества ночных эльфов и город Darnassus. Жители пытаются защитить природное равновесие, изучая признаки болезней и коррупции в своем новом доме."},references={["place:darnassus"]=true}},
    ["place:temple-of-atal-hakkar"] = {title="Templo de Atal'Hakkar",kind="Lugar",aliases={"Templo Sumergido","Templo de Atal'Hakkar","Templo de Atal’Hakkar"},body="El Templo de Atal'Hakkar es un santuario dedicado a Hakkar que permanece hundido en la Charca de Lágrimas. Los Atal'ai lo protegen, lo que vuelve peligroso recuperar los artefactos que interesan a los estudiosos de su historia.",aliasQuestIDs={},en={title="Temple of Atal'Hakkar",aliases={"Sunken Temple","Temple of Atal'Hakkar","Temple of Atal’Hakkar"},body="The Temple of Atal’Hakkar is a sanctuary dedicated to Hakkar, submerged in the Pool of Tears. The Atal’ai protect it, making the recovery of artifacts sought by students of its history dangerous.",aliasQuestIDs={}},fr={title="Temple of Atal'Hakkar",body="Le Temple of Atal’Hakkar est un sanctuaire dédié au Hakkar, immergé dans le Pool of Tears. Le Atal’ai le protège, rendant dangereuse la récupération des artefacts recherchés par les étudiants de son histoire."},de={title="Temple of Atal'Hakkar",body="Der Temple of Atal’Hakkar ist ein Hakkar geweihtes Heiligtum, das im Becken der Tränen versunken ist. Die Atal’ai schützen es und machen die Wiederherstellung von Artefakten, die von Studenten seiner Geschichte gesucht werden, gefährlich."},pt={title="Temple of Atal'Hakkar",body="O Temple of Atal’Hakkar é um santuário dedicado ao Hakkar, submerso na Piscina das Lágrimas. O Atal’ai o protege, tornando a recuperação de artefatos procurados por estudantes de sua história perigosa."},pl={title="Temple of Atal'Hakkar",body="Temple of Atal’Hakkar to sanktuarium poświęcone Hakkar, zatopione w jeziorze łez. Chronią je Atal’ai, czyniąc odzyskiwanie artefaktów poszukiwanych przez badaczy jego historii niebezpiecznym przedsięwzięciem."},ru={title="Temple of Atal'Hakkar",body="Temple of Atal’Hakkar - это святилище, посвященное Hakkar, погруженному в Бассейн Слёз. Atal’ai защищают его, что делает восстановление артефактов, ищущихся студентами его истории опасным."},references={["npc:hakkar"]=true,["organization:atalai"]=true}},
    ["place:temple-of-the-moon"] = {title="Templo de la Luna",kind="Lugar",aliases={"Templo de la Luna"},body="El Templo de la Luna es un centro de culto de Elune en Darnassus. Sus sacerdotisas atienden la vida espiritual de los elfos de la noche y conservan conocimientos sobre las aguas, criaturas y objetos vinculados a la diosa.",aliasQuestIDs={},en={title="Temple of the Moon",aliases={"Temple of the Moon"},body="The Temple of the Moon is a center of Elune worship in Darnassus. Its priestesses serve the night elves’ spiritual life and preserve knowledge of waters, creatures and objects associated with the goddess.",aliasQuestIDs={}},fr={title="Temple of the Moon",body="Le Temple of the Moon est un centre du culte Elune dans Darnassus. Ses prêtresses servent la vie spirituelle des elfes de la nuit et préservent la connaissance des eaux, des créatures et des objets associés à la déesse."},de={title="Temple of the Moon",body="Der Temple of the Moon ist ein Zentrum der Elune-Verehrung in Darnassus. Seine Priesterinnen dienen dem spirituellen Leben der Nachtelfen und bewahren das Wissen über Wasser, Lebewesen und Objekte, die mit der Göttin Verbindung mit der Gottheit."},pt={title="Temple of the Moon",body="O Temple of the Moon é um centro de adoração Elune em Darnassus. Suas sacerdotisas servem a vida espiritual dos elfos noturnos e preservam o conhecimento das águas, criaturas e objetos associados à deusa."},pl={title="Temple of the Moon",body="Temple of the Moon to ośrodek kultu bogini Elune w Darnassus. Kapłanki służą duchowemu życiu nocnych elfów i przechowują wiedzę o wodach, stworzeniach oraz przedmiotach związanych z boginią."},ru={title="Temple of the Moon",body="Temple of the Moon - это центр поклонения Elune в Darnassus. Его жрицы служат духовной жизни ночных эльфов и сохраняют знания о водах, существах и предметах, связанных с богиней."},references={["npc:elune"]=true,["place:darnassus"]=true}},
    ["place:terrordale"] = {title="Valle del Terror",kind="Lugar",aliases={"Valle del Terror"},body="Valle del Terror es una población vinculada a la devastación de las Tierras de la Peste. Entre sus recuerdos cotidianos persisten una posada y la actividad comercial que Augustus intenta mantener.",aliasQuestIDs={},en={title="Terrordale",aliases={"Terrordale"},body="Terrordale is a settlement associated with the Plaguelands' devastation. Everyday traces include an inn and the trading business Augustus tries to maintain.",aliasQuestIDs={}},fr={title="Terrordale",body="Terrordale est une colonie associée à la dévastation Plaguelands '. Les traces quotidiennes comprennent une auberge et le commerce Augustus essaie de maintenir."},de={title="Terrordale",body="Terrordale ist eine Siedlung, die mit den Verwüstungen des Plaguelands in Verbindung gebracht wird. Zu den täglichen Spuren gehören ein Wirtshaus und das Handelsgeschäft, das Augustus zu unterhalten versucht."},pt={title="Terrordale",body="Terrordale é um assentamento associado à devastação do Plaguelands. Os traços diários incluem uma pousada e o negócio de comércio Augustus tenta manter."},pl={title="Terrordale",body="Terrordale jest osadą związaną ze zniszczeniem Plaguelands. Ślady codzienności obejmują gospodę i handel, który Augustus próbuje utrzymać."},ru={title="Terrordale",body="Terrordale - это поселение, связанное с разрушением Plaguelands. Ежедневные следы включают гостиницу и торговый бизнес, который пытается поддерживать Augustus."},references={["npc:augustus-the-touched"]=true,["place:plaguelands"]=true}},
    ["place:thandol-span"] = {title="Puente Thandol",kind="Lugar",aliases={"Puente Thandol","Thandol"},body="El Puente Thandol es un paso de importancia militar para las fuerzas que recorren las tierras enanas y Arathi. Los ataques y los daños sufridos allí convierten su defensa en una preocupación para los soldados de la zona.",aliasQuestIDs={},en={title="Thandol Span",aliases={"Thandol","Thandol Span"},body="Thandol Span is a militarily important crossing for forces traveling between dwarven lands and Arathi. Attacks and damage there make its defense a concern for soldiers in the district.",aliasQuestIDs={}},fr={title="Thandol Span",body="Thandol Span est une traversée militairement importante pour les forces voyageant entre les terres naines et Arathi. Les attaques et les dégâts là-bas font de sa défense une préoccupation pour les soldats du district."},de={title="Thandol Span",body="Thandol Span ist ein militärisch wichtiger Übergang für Streitkräfte, die zwischen Zwergenländern und Arathi unterwegs sind. Angriffe und Schäden dort machen seine Verteidigung zu einem Anliegen für die Soldaten im Bezirk."},pt={title="Thandol Span",body="Thandol Span é um cruzamento militarmente importante para as forças que viajam entre terras anãs e Arathi. Ataques e danos fazem da sua defesa uma preocupação para os soldados do distrito."},pl={title="Thandol Span",body="Thandol Span jest przeprawą o znaczeniu wojskowym dla sił przemieszczających się między krasnoludzkimi ziemiami a Arathi. Ataki i zniszczenia sprawiają, że obrona mostu zajmuje miejscowych żołnierzy."},ru={title="Thandol Span",body="Thandol Span - это военно важное пересечение для сил, путешествующих между землями карликов и Arathi. Нападения и повреждения делают его защиту проблемой для солдат в районе."},references={["place:arathi-highlands"]=true}},
    ["place:the-barrens"] = {title="Los Baldíos",kind="Lugar",aliases={"Baldíos","Los Baldíos"},body="Los Baldíos son una extensa región de Kalimdor recorrida por caravanas, cazadores y patrullas de la Horda. La distancia entre los poblados y la presencia de jabaespines, centauros y depredadores convierten sus rutas en una preocupación constante.",aliasQuestIDs={},en={title="The Barrens",aliases={"Barrens","The Barrens"},body="The Barrens are a vast region of Kalimdor crossed by caravans, hunters and Horde patrols. Long distances between settlements, along with quilboar, centaurs and predators, make its roads a constant concern.",aliasQuestIDs={}},fr={title="The Barrens",body="The Barrens est une vaste région de Kalimdor traversée par des caravanes, des chasseurs et des patrouilles Horde. Les longues distances entre les colonies, ainsi que les quilboars, les centaures et les prédateurs, font de ses routes une préoccupation constante."},de={title="The Barrens",body="The Barrens sind eine riesige Gegend von Kalimdor, die von Wohnwagen, Jägern und Horde Patrouilliert wird. Große Entfernungen zwischen den Siedlungen, zusammen mit Quiltschweinen, Zentauren und Raubtieren, machen seine Straßen zu einem ständigen Besorgnis erregend."},pt={title="The Barrens",body="The Barrens são uma vasta região de Kalimdor atravessada por caravanas, caçadores e patrulhas Horde. Longas distâncias entre assentamentos, juntamente com quilboar, centauros e predadores, fazem de suas estradas uma preocupação constante."},pl={title="The Barrens",body="The Barrens to rozległy region kontynentu Kalimdor przemierzany przez karawany, myśliwych i patrole frakcji Horde. Duże odległości między osadami oraz obecność kolcozwierzy, centaurów i drapieżników sprawiają, że bezpieczeństwo dróg wymaga stałej uwagi."},ru={title="The Barrens",body="The Barrens - это обширный регион Kalimdor, через который проходят караваны, охотники и патрули Horde. Длинные расстояния между населенными пунктами, вместе с кильбором, кентаврами и хищниками делают его дороги постоянной проблемой."},references={["organization:horde"]=true,["place:kalimdor"]=true}},
    ["place:the-bulwark"] = {title="El Baluarte",kind="Lugar",aliases={"Baluarte","El Baluarte"},body="El Baluarte es un puesto de los Renegados en las Tierras de la Peste del Oeste. Desde allí se organizan operaciones contra los no-muertos que dominan Andorhal.",aliasQuestIDs={},en={title="The Bulwark",aliases={"Bulwark","The Bulwark"},body="The Bulwark is a Forsaken post in Western Plaguelands. Operations against the undead holding Andorhal are organized from there.",aliasQuestIDs={}},fr={title="The Bulwark",body="The Bulwark est un poste Forsaken dans Western Plaguelands. Des opérations contre les morts-vivants détenant Andorhal sont organisées à partir de là."},de={title="The Bulwark",body="The Bulwark ist ein Forsaken in Western Plaguelands. Von dort aus werden Operationen gegen die Untoten organisiert, die Andorhal festhalten."},pt={title="The Bulwark",body="The Bulwark é um post de Forsaken em Western Plaguelands. Operações contra os mortos-vivos segurando Andorhal são organizadas a partir daí."},pl={title="The Bulwark",body="The Bulwark jest posterunkiem Forsaken w Western Plaguelands. Organizuje się stąd działania przeciw nieumarłym okupującym Andorhal."},ru={title="The Bulwark",body="The Bulwark - это пост Forsaken в Western Plaguelands. Операции против неживых мертвецов Andorhal организуются оттуда."},references={["organization:forsaken"]=true,["place:andorhal"]=true,["place:plaguelands"]=true,["place:western-plaguelands"]=true}},
    ["place:the-crossroads"] = {title="El Cruce",kind="Lugar",aliases={"El Cruce","el Cruce"},body="El Cruce es un asentamiento de la Horda situado en Los Baldíos. Su posición en las rutas de la región lo convierte en un punto de encuentro para viajeros, cazadores y defensores de los poblados cercanos.",aliasQuestIDs={},en={title="The Crossroads",aliases={"Crossroads","The Crossroads"},body="The Crossroads is a Horde settlement in the Barrens. Its position on the region’s roads makes it a meeting point for travelers, hunters and defenders of nearby communities.",aliasQuestIDs={}},fr={title="The Crossroads",body="The Crossroads est un règlement Horde dans le Barrens. Sa position sur les routes de la région en fait un point de rencontre pour les voyageurs, les chasseurs et les défenseurs des communautés voisines."},de={title="The Crossroads",body="The Crossroads ist eine Horde-Siedlung im Barrens. Seine Lage an den Straßen der Region macht es zu einem Treffpunkt für Reisende, Jäger und Verteidiger der umliegenden Gemeinden."},pt={title="The Crossroads",body="The Crossroads é um assentamento Horde no Barrens. Sua posição nas estradas da região o torna um ponto de encontro para viajantes, caçadores e defensores de comunidades próximas."},pl={title="The Crossroads",body="The Crossroads to osada frakcji Horde w regionie Barrens. Położenie przy miejscowych drogach czyni ją punktem spotkań podróżnych, myśliwych i obrońców pobliskich społeczności."},ru={title="The Crossroads",body="The Crossroads - это расчетное заведение Horde в Barrens. Его расположение на дорогах региона делает его местом встречи путешественников, охотников и защитников близлежащих общин."},references={["organization:horde"]=true,["place:the-barrens"]=true}},
    ["place:the-sepulcher"] = {title="El Sepulcro",kind="Lugar",aliases={"El Sepulcro","Sepulcro"},body="El Sepulcro es una base de los Renegados en el Bosque de Argénteos. Sus oficiales, agentes y boticarios coordinan la defensa y la investigación de los peligros del bosque.",aliasQuestIDs={},en={title="The Sepulcher",aliases={"Sepulcher","The Sepulcher"},body="The Sepulcher is a Forsaken base in Silverpine Forest. Its officers, operatives and apothecaries coordinate defense and research into the forest's dangers.",aliasQuestIDs={}},fr={title="The Sepulcher",body="The Sepulcher est une base Forsaken dans Silverpine Forest. Ses officiers, agents et apothicaires coordonnent la défense et la recherche sur les dangers de la forêt."},de={title="The Sepulcher",body="The Sepulcher ist ein Forsaken-Stützpunkt in Silverpine Forest. Seine Offiziere, Aktivisten und Apotheker koordinieren Verteidigung und Erforschung der Gefahren des Waldes Waldes."},pt={title="The Sepulcher",body="The Sepulcher é uma base Forsaken em Silverpine Forest. Seus oficiais, agentes e boticários coordenam a defesa e a pesquisa sobre os perigos da floresta."},pl={title="The Sepulcher",body="The Sepulcher jest bazą Forsaken w Silverpine Forest. Jej oficerowie, agenci i aptekarze koordynują obronę oraz badania nad zagrożeniami lasu."},ru={title="The Sepulcher",body="The Sepulcher - это база Forsaken в Silverpine Forest. Его офицеры, оперативники и аптечные сотрудники координируют защиту и исследования опасностей леса."},references={["organization:forsaken"]=true,["place:silverpine-forest"]=true}},
    ["place:thelsamar"] = {title="Thelsamar",kind="Lugar",aliases={"Thelsamar"},body="Thelsamar es un poblado enano de Loch Modan que sirve de base a viajeros, exploradores y estudiosos. Desde sus alrededores parten investigaciones sobre los recursos de la región y sobre los hallazgos de las excavaciones.",aliasQuestIDs={},en={title="Thelsamar",aliases={"Thelsamar"},body="Thelsamar is a dwarven settlement in Loch Modan used by travelers, explorers and scholars. Investigations of the region’s resources and archaeological discoveries are organized from the surrounding district.",aliasQuestIDs={}},fr={title="Thelsamar",body="Thelsamar est un établissement nain dans Loch Modan utilisé par les voyageurs, les explorateurs et les chercheurs. Des recherches sur les ressources de la région et des découvertes archéologiques sont organisées dans le quartier environnant."},de={title="Thelsamar",body="Thelsamar ist eine Zwergensiedlung in Loch Modan, die von Reisenden, Entdeckern und Gelehrten genutzt wird. Aus der Umgebung werden Untersuchungen der Bodenschätze und archäologische Funde organisiert."},pt={title="Thelsamar",body="Thelsamar é um assentamento anão no Loch Modan usado por viajantes, exploradores e estudiosos. Investigações dos recursos da região e descobertas arqueológicas são organizadas a partir do distrito circundante."},pl={title="Thelsamar",body="Thelsamar to krasnoludzka osada w Loch Modan, z której korzystają podróżni, odkrywcy i uczeni. W jej okolicy organizowane są badania zasobów regionu oraz odkryć archeologicznych."},ru={title="Thelsamar",body="Thelsamar - это населенный пункт карликов в Loch Modan, используемый путешественниками, исследователями и учеными. Исследования ресурсов региона и археологических находок организуются из окружающего района."},references={["place:loch-modan"]=true}},
    ["place:thendal-grove"] = {title="Arboleda Thendal",kind="Lugar",aliases={"Arboleda Thendal","Thendal"},body="Arboleda Thendal es una comunidad de Isla Zephras con una torre de vigilancia y un árbol ancestral en el centro del poblado. Sus forestales protegen a los habitantes de los animales peligrosos que se acercan desde las tierras vecinas. Aetheen de los Vendavales es una de las dirigentes vinculadas a este lugar.",aliasQuestIDs={},en={title="Thendal Grove",aliases={"Thendal","Thendal Grove"},body="Thendal Grove is a community on Zephras Isle with a watchtower and an elder tree at the center of the village. Its rangers protect residents from dangerous animals approaching from the surrounding countryside. Aetheen of the Gales is one of the leaders associated with the settlement.",aliasQuestIDs={}},fr={title="Thendal Grove",body="Thendal Grove est une communauté sur Zephras Isle avec une tour de guet et un arbre sureau au centre du village. Ses gardes protègent les résidents des animaux dangereux qui s'approchent de la campagne environnante. Aetheen of the Gales est l’un des leaders associés au règlement."},de={title="Thendal Grove",body="Thendal Grove ist eine Gemeinschaft auf Zephras Isle mit einem Wachturm und einem Holunderbaum in der Mitte des Dorfes. Ihre Ranger schützen die Bewohner vor gefährlichen Tieren, die sich aus dem Umland nähern. Aetheen of the Gales ist einer der Anführer, die mit der Siedlungen verbunden sind."},pt={title="Thendal Grove",body="Thendal Grove é uma comunidade em Zephras Isle com uma torre de vigia e uma árvore mais velha no centro da aldeia. Seus guardas protegem os moradores de animais perigosos que se aproximam do campo circundante. Aetheen of the Gales é um dos líderes associados ao assentamento."},pl={title="Thendal Grove",body="Thendal Grove jest społecznością na Zephras Isle z wieżą strażniczą i pradawnym drzewem w centrum wioski. Jej strażnicy chronią mieszkańców przed niebezpiecznymi zwierzętami z okolicy. Aetheen of the Gales należy do przywódców związanych z osadą."},ru={title="Thendal Grove",body="Thendal Grove - это сообщество на Zephras Isle с сторожевой башней и деревом в центре деревни. Его рейнджеры защищают жителей от опасных животных, приближающихся из окрестных сельских районов. Aetheen of the Gales - один из лидеров, связанных с поселением."},references={["person:aetheen-of-the-gales"]=true,["place:zephras"]=true}},
    ["place:theramore"] = {title="Theramore",kind="Lugar",aliases={"Theramore"},body="Theramore es un asentamiento humano de la costa de Marjal Revolcafango. Su puerto y sus fuerzas militares sostienen una presencia de la Alianza en Kalimdor, cerca de territorios ocupados por la Horda.",aliasQuestIDs={},en={title="Theramore",aliases={"Theramore"},body="Theramore is a human settlement on the coast of Dustwallow Marsh. Its harbor and military forces support an Alliance presence in Kalimdor near territories occupied by the Horde.",aliasQuestIDs={}},fr={title="Theramore",body="Theramore est un établissement humain sur la côte de Dustwallow Marsh. Son port et ses forces militaires soutiennent une présence Alliance à Kalimdor près des territoires occupés par le Horde."},de={title="Theramore",body="Theramore ist eine menschliche Siedlung an der Küste von Dustwallow Marsh. Seine Hafen- und Militärstreitkräfte unterstützen eine Alliance-Präsenz in Kalimdor in der Nähe von Gebieten, die von den Horde besetzt sind."},pt={title="Theramore",body="Theramore é um assentamento humano na costa do Dustwallow Marsh. Seu porto e forças militares apoiam uma presença Alliance em Kalimdor perto de territórios ocupados pelo Horde."},pl={title="Theramore",body="Theramore to ludzka osada na wybrzeżu Dustwallow Marsh. Jej port i wojsko wspierają obecność frakcji Alliance na kontynencie Kalimdor w pobliżu terytoriów zajmowanych przez Horde."},ru={title="Theramore",body="Theramore - это населенный пункт на побережье Dustwallow Marsh. Его портовые и военные силы поддерживают присутствие Alliance в Kalimdor рядом с территориями, оккупированными Horde."},references={["organization:alliance"]=true,["organization:horde"]=true,["place:dustwallow-marsh"]=true,["place:kalimdor"]=true}},
    ["place:thistlefur-hold"] = {title="Bastión Piel de Cardo",kind="Lugar",aliases={"Bastión Piel de Cardo"},body="El Bastión Piel de Cardo es una cueva situada al final del poblado de la tribu, al norte de Astranaar. Los fúrbolgs guardan allí objetos tomados a los viajeros, entre ellos talismanes sagrados de los trols.",aliasQuestIDs={},en={title="Thistlefur Hold",aliases={"Thistlefur Hold"},body="Thistlefur Hold is a cave at the far end of the tribe’s village north of Astranaar. The furbolgs keep objects taken from travelers there, including sacred troll charms.",aliasQuestIDs={}},fr={title="Thistlefur Hold",body="Thistlefur Hold est une grotte à l'extrémité du village de la tribu au nord de Astranaar. Les furbolgs y gardent les objets pris aux voyageurs, y compris les charmes sacrés des trolls."},de={title="Thistlefur Hold",body="Thistlefur Hold ist eine Höhle am äußersten Ende des Stammesdorfes nördlich von Astranaar. In den Furbolgs werden Gegenstände aufbewahrt, die Reisenden dort entwendet wurden, darunter auch heilige Trollzauber."},pt={title="Thistlefur Hold",body="Thistlefur Hold é uma caverna no extremo da aldeia da tribo ao norte de Astranaar. Os furbolgs mantêm objetos retirados de viajantes lá, incluindo encantos sagrados de trolls."},pl={title="Thistlefur Hold",body="Thistlefur Hold jest jaskinią na krańcu wioski plemienia, na północ od Astranaar. Furbolgi przechowują tam przedmioty zabrane podróżnym, w tym święte amulety trolli."},ru={title="Thistlefur Hold",body="Thistlefur Hold — пещера в дальней части деревни племени, к северу от Astranaar. Фурболги хранят там вещи, отнятые у путешественников, в том числе священные обереги троллей."},references={["organization:thistlefur"]=true,["place:astranaar"]=true}},
    ["place:thorium-point"] = {title="Puesto del Torio",kind="Lugar",aliases={"Puesto del Torio"},body="El Puesto del Torio es un asentamiento de la Garganta de Fuego relacionado con el trabajo de los enanos de la región. Allí se reúnen encargos, materiales e investigaciones que conectan la minería con expediciones a lugares lejanos.",aliasQuestIDs={},en={title="Thorium Point",aliases={"Thorium Point"},body="Thorium Point is a Searing Gorge settlement associated with the region’s dwarven workers. Jobs, materials and research gathered there connect mining with expeditions to distant places.",aliasQuestIDs={}},fr={title="Thorium Point",body="Thorium Point est un règlement Searing Gorge associé aux travailleurs nains de la région. Les emplois, les matériaux et la recherche qui s’y sont rassemblés relient l’exploitation minière aux expéditions dans des endroits lointains."},de={title="Thorium Point",body="Thorium Point ist eine Searing Gorge-Siedlung, die mit den Zwergenarbeitern der Region verbunden ist. Die dort gesammelten Arbeitsplätze, Materialien und Forschungsergebnisse verbinden den Bergbau mit Expeditionen zu weit entfernten Orten."},pt={title="Thorium Point",body="Thorium Point é um acordo Searing Gorge associado aos trabalhadores anões da região. Empregos, materiais e pesquisas reunidos ali conectam a mineração com expedições a lugares distantes."},pl={title="Thorium Point",body="Thorium Point to osada w Searing Gorge związana z krasnoludzkimi robotnikami regionu. Gromadzone tam zlecenia, materiały i wyniki badań łączą górnictwo z wyprawami do odległych miejsc."},ru={title="Thorium Point",body="Thorium Point - это поселение Searing Gorge, связанное с рабочими карликами региона. Работы, материалы и исследования, собранные там, связывают добычу с экспедициями в далекие места."},references={["npc:thorius"]=true,["place:searing-gorge"]=true}},
    ["place:thousand-needles"] = {title="Las Mil Agujas",kind="Lugar",aliases={"Las Mil Agujas","Mil Agujas"},body="Las Mil Agujas son una región de Kalimdor dominada por grandes columnas de roca y rutas entre cañones. Los poblados elevados, los territorios de los centauros y las salinas del este dan al lugar formas de vida muy distintas.",aliasQuestIDs={},en={title="Thousand Needles",aliases={"Thousand Needles"},body="Thousand Needles is a region of Kalimdor dominated by tall rock pillars and canyon routes. Elevated settlements, centaur territories and the eastern salt flats support very different ways of life.",aliasQuestIDs={}},fr={title="Thousand Needles",body="Thousand Needles est une région de Kalimdor dominée par de hauts piliers rocheux et des itinéraires de canyon. Les établissements surélevés, les territoires centaures et les marais salants de l'est soutiennent des modes de vie très différents."},de={title="Thousand Needles",body="Thousand Needles ist eine Region von Kalimdor, die von hohen Felssäulen und Canyonrouten dominiert wird. Hochsiedlungen, Zentaurengebiete und die östlichen Salzebenen unterstützen sehr unterschiedliche Lebensweisen."},pt={title="Thousand Needles",body="Thousand Needles é uma região do Kalimdor dominada por altos pilares de rocha e rotas de canyon. Os assentamentos elevados, os territórios centauros e as planícies de sal do leste suportam modos de vida muito diferentes."},pl={title="Thousand Needles",body="Thousand Needles to region kontynentu Kalimdor zdominowany przez wysokie skalne filary i szlaki w kanionach. Osady na wzniesieniach, terytoria centaurów oraz wschodnie solniska umożliwiają bardzo odmienne sposoby życia."},ru={title="Thousand Needles",body="Thousand Needles - это область Kalimdor, в которой доминируют высокие скальные столбы и канаонные маршруты. Высокие поселения, территории кентавров и восточные соляные равнины поддерживают очень разные способы жизни."},references={["place:kalimdor"]=true}},
    ["place:thunder-axe-fortress"] = {title="Fortaleza del Hacha de Trueno",kind="Lugar",aliases={"Fortaleza del Hacha de Trueno"},body="La Fortaleza del Hacha de Trueno es un bastión del Filo Ardiente en Desolace. Sus torres y recintos albergan cultistas y objetos de poder que preocupan a los habitantes de las tierras cercanas.",aliasQuestIDs={},en={title="Thunder Axe Fortress",aliases={"Thunder Axe Fortress"},body="Thunder Axe Fortress is a Burning Blade stronghold in Desolace. Its towers and chambers hold cultists and objects of power that concern the inhabitants of nearby lands.",aliasQuestIDs={}},fr={title="Thunder Axe Fortress",body="Thunder Axe Fortress est un bastion Burning Blade dans Desolace. Ses tours et ses chambres abritent des cultes et des objets de pouvoir qui concernent les habitants des terres voisines."},de={title="Thunder Axe Fortress",body="Thunder Axe Fortress ist eine Burning Blade-Hochburg in Desolace. Seine Türme und Kammern beherbergen Kultisten und Machtgegenstände, die die die die Bewohner der nahegelegenen Länder betreffen."},pt={title="Thunder Axe Fortress",body="Thunder Axe Fortress é uma fortaleza Burning Blade em Desolace. Suas torres e câmaras possuem cultistas e objetos de poder que dizem respeito aos habitantes de terras próximas."},pl={title="Thunder Axe Fortress",body="Thunder Axe Fortress to twierdza Burning Blade w Desolace. Wieże i komnaty kryją kultystów oraz przedmioty mocy niepokojące mieszkańców pobliskich ziem."},ru={title="Thunder Axe Fortress",body="Thunder Axe Fortress - это крепость Burning Blade в Desolace. В его башнях и камерах хранятся культовые деятели и предметы власти, которые касаются жителей соседних земель."},references={["organization:burning-blade"]=true,["place:desolace"]=true}},
    ["place:thunder-bluff"] = {title="Cima del Trueno",kind="Lugar",aliases={"Cima del Trueno"},body="Cima del Trueno es la gran ciudad tauren de Mulgore, construida sobre elevaciones unidas por puentes. Allí se reúnen sus dirigentes, ancestros e instructores para orientar a las comunidades de las llanuras.",aliasQuestIDs={},en={title="Thunder Bluff",aliases={"Thunder Bluff"},body="Thunder Bluff is the great tauren city of Mulgore, built on rises connected by bridges. Its leaders, elders and trainers gather there to guide the communities of the plains.",aliasQuestIDs={}},fr={title="Thunder Bluff",body="Thunder Bluff est la grande ville tauren de Mulgore, construite sur des hauteurs reliées par des ponts. Ses dirigeants, anciens et formateurs s’y réunissent pour guider les communautés des plaines."},de={title="Thunder Bluff",body="Thunder Bluff ist die große Taurenstadt von Mulgore, die auf Erhebungen erbaut wurde, die durch Brücken miteinander verbunden sind. Ihre Führer, Ältesten und Ausbilder versammeln sich dort, um die Gemeinschaften der Ebene zu leiten."},pt={title="Thunder Bluff",body="Thunder Bluff é a grande cidade tauren de Mulgore, construída sobre elevações conectadas por pontes. Seus líderes, anciãos e treinadores se reúnem lá para orientar as comunidades das planícies."},pl={title="Thunder Bluff",body="Thunder Bluff to wielkie miasto taurenów w Mulgore, zbudowane na wzniesieniach połączonych mostami. Przywódcy, starszyzna i nauczyciele zbierają się tam, aby przewodzić społecznościom równin."},ru={title="Thunder Bluff",body="Thunder Bluff - это великий городок Таурен Mulgore, построенный на возвышениях, соединенных мостами. Его лидеры, старейшины и наставники собираются там, чтобы вести общины равнин."},references={["place:mulgore"]=true}},
    ["place:thunder-ridge"] = {title="Monte del Trueno",kind="Lugar",aliases={"Monte del Trueno"},body="El Monte del Trueno es una zona de colinas de Durotar. Sus pasos y rincones apartados permiten que criaturas y grupos hostiles se acerquen a los asentamientos sin ser vistos desde los caminos principales.",aliasQuestIDs={},en={title="Thunder Ridge",aliases={"Thunder Ridge"},body="Thunder Ridge is an area of hills in Durotar. Its secluded paths and hollows allow dangerous creatures and hostile groups to approach settlements out of sight of the main roads.",aliasQuestIDs={}},fr={title="Thunder Ridge",body="Thunder Ridge est une région de collines dans Durotar. Ses sentiers isolés et ses creux permettent à des créatures dangereuses et à des groupes hostiles de s'approcher des colonies hors de la vue des routes principales."},de={title="Thunder Ridge",body="Thunder Ridge ist ein Hügelgebiet in Durotar. Seine abgeschiedenen Pfade und Senken ermöglichen es gefährlichen Kreaturen und feindlichen Gruppen, sich Siedlungen außerhalb der Hauptstraßen zu nähern."},pt={title="Thunder Ridge",body="Thunder Ridge é uma área de colinas em Durotar. Seus caminhos isolados e cavidades permitem que criaturas perigosas e grupos hostis se aproximem de assentamentos fora da vista das estradas principais."},pl={title="Thunder Ridge",body="Thunder Ridge to obszar wzgórz w Durotar. Zaciszne ścieżki i zagłębienia pozwalają niebezpiecznym stworzeniom oraz wrogim grupom zbliżać się do osad poza zasięgiem wzroku podróżnych na głównych drogach."},ru={title="Thunder Ridge",body="Thunder Ridge - это район холмов в Durotar. Отдельные тропы и ущелья позволяют опасным существам и враждебным группам приближаться к поселениям, не видя главных дорог."},references={["place:durotar"]=true}},
    ["place:timbermaw-hold"] = {title="Bastión Fauces de Madera",kind="Lugar",aliases={"Bastión Fauces de Madera"},body="El Bastión Fauces de Madera es un refugio fúrbolg que comunica regiones del norte de Kalimdor. Sus guardianes distinguen cuidadosamente entre aliados y enemigos, por lo que atravesarlo depende de la confianza que concedan a un visitante.",aliasQuestIDs={},en={title="Timbermaw Hold",aliases={"Timbermaw Hold"},body="Timbermaw Hold is a furbolg refuge connecting regions of northern Kalimdor. Its guardians carefully distinguish friends from enemies, so passage depends on the trust they place in a visitor.",aliasQuestIDs={}},fr={title="Timbermaw Hold",body="Timbermaw Hold est un refuge furbolg reliant les régions du nord de Kalimdor. Ses gardiens distinguent soigneusement les amis des ennemis, de sorte que le passage dépend de la confiance qu'ils accordent à un visiteur."},de={title="Timbermaw Hold",body="Timbermaw Hold ist ein Zufluchtsort in Furbolg, der die Regionen des nördlichen Kalimdor miteinander verbindet. Ihre Wächter unterscheiden sorgfältig zwischen Freunden und Feinden, daher hängt der Durchlauf vom Vertrauen ab, das sie in einen Besucher setzen."},pt={title="Timbermaw Hold",body="Timbermaw Hold é um refúgio furbolg que conecta regiões do norte de Kalimdor. Seus guardiões distinguem cuidadosamente os amigos dos inimigos, então a passagem depende da confiança que eles depositam em um visitante."},pl={title="Timbermaw Hold",body="Timbermaw Hold to schronienie furbolgów łączące regiony północnego Kalimdor. Strażnicy starannie odróżniają przyjaciół od wrogów, dlatego możliwość przejścia zależy od zaufania, jakim obdarzą przybysza."},ru={title="Timbermaw Hold",body="Timbermaw Hold - это убежище для фуробольгов, соединяющее регионы северного Kalimdor. Его хранители тщательно отличают друзей от врагов, поэтому проход зависит от доверия, которое они проявляют к посетителю."},references={["organization:timbermaw"]=true,["place:kalimdor"]=true}},
    ["place:tinker-town"] = {title="Ciudad Manitas",kind="Lugar",aliases={"Ciudad Manitas"},body="Ciudad Manitas es una zona de Forjaz vinculada a inventores y especialistas en dispositivos. Los materiales y encargos que llegan a sus talleres la conectan con proyectos de ingeniería de otras regiones.",aliasQuestIDs={},en={title="Tinker Town",aliases={"Tinker Town"},body="Tinker Town is an Ironforge district associated with inventors and device specialists. Materials and commissions reaching its workshops connect it with engineering projects in other regions.",aliasQuestIDs={}},fr={title="Tinker Town",body="Tinker Town est un district Ironforge associé à des inventeurs et des spécialistes des dispositifs. Les matériaux et les commandes qui parviennent à ses ateliers le relient à des projets d'ingénierie dans d'autres régions."},de={title="Tinker Town",body="Tinker Town ist ein Ironforge-Distrikt, der mit Erfindern und Gerätespezialisten in Verbindung gebracht wird. Materialien und Aufträge, die seine Werkstätten erreichen, verbinden es mit Ingenieurprojekten in anderen Regionen."},pt={title="Tinker Town",body="Tinker Town é um distrito Ironforge associado a inventores e especialistas em dispositivos. Materiais e comissões que chegam às suas oficinas conectam-no com projetos de engenharia em outras regiões."},pl={title="Tinker Town",body="Tinker Town to dzielnica Ironforge związana z wynalazcami i specjalistami od urządzeń. Materiały i zlecenia docierające do warsztatów łączą ją z projektami inżynieryjnymi w innych regionach."},ru={title="Tinker Town",body="Tinker Town - это район Ironforge, связанный с изобретателями и специалистами по устройствам. Материалы и заказы, поступающие в мастерские, связывают его с инженерными проектами в других регионах."},references={["place:ironforge"]=true}},
    ["place:tirisfal-glades"] = {title="Claros de Tirisfal",kind="Lugar",aliases={"Claros de Tirisfal","Tirisfal"},body="Claros de Tirisfal rodea los accesos a la antigua capital de Lordaeron. Los Renegados mantienen asentamientos en una tierra disputada por la Plaga y la Cruzada Escarlata.",aliasQuestIDs={},en={title="Tirisfal Glades",aliases={"Tirisfal","Tirisfal Glades"},body="Tirisfal Glades surrounds the approaches to Lordaeron's former capital. The Forsaken maintain settlements in land contested by the Scourge and Scarlet Crusade.",aliasQuestIDs={}},fr={title="Tirisfal Glades",body="Tirisfal Glades entoure les approches de l'ancienne capitale de Lordaeron. Les Forsaken maintiennent des règlements dans les terres contestées par the Scourge et Scarlet Crusade."},de={title="Tirisfal Glades",body="Tirisfal Glades umgibt die Zugänge zu Lordaeron 's ehemaliger Hauptstadt. Die Forsaken unterhalten Siedlungen auf von the Scourge und Scarlet Crusade umkämpftem Land."},pt={title="Tirisfal Glades",body="Tirisfal Glades envolve as abordagens da antiga capital da Lordaeron. O Forsaken mantém assentamentos em terras contestadas pela the Scourge e Scarlet Crusade."},pl={title="Tirisfal Glades",body="Tirisfal Glades otacza drogi prowadzące do dawnej stolicy Lordaeron. Forsaken utrzymują osady na ziemiach, o które walczą siły znane jako the Scourge oraz Scarlet Crusade."},ru={title="Tirisfal Glades",body="Tirisfal Glades окружает подходы к бывшей столице Lordaeron. Forsaken поддерживают поселения на землях, оспариваемых the Scourge и Scarlet Crusade."},references={["organization:forsaken"]=true,["organization:scarlet-crusade"]=true,["organization:scourge"]=true,["place:lordaeron"]=true}},
    ["place:tower-of-azora"] = {title="Torre de Azora",kind="Lugar",aliases={"Azora","Torre de Azora"},body="La Torre de Azora es un punto de referencia en el camino oriental del Bosque de Elwynn. Su nombre aparece en las indicaciones de quienes viajan hacia las minas y otras comunidades apartadas de Villadorada.",aliasQuestIDs={},en={title="Tower of Azora",aliases={"Azora","Tower of Azora"},body="The Tower of Azora is a landmark along the eastern road through Elwynn Forest. Travelers use it to find the mines and other communities farther from Goldshire.",aliasQuestIDs={}},fr={title="Tower of Azora",body="La Tower of Azora est un point de repère le long de la route de l'Est à travers Elwynn Forest. Les voyageurs l'utilisent pour trouver les mines et d'autres communautés plus loin de Goldshire."},de={title="Tower of Azora",body="Der Tower of Azora ist ein Wahrzeichen entlang der östlichen Straße durch Elwynn Forest. Reisende nutzen es, um die Minen und andere Gemeinden weiter entfernt von Goldshire zu finden."},pt={title="Tower of Azora",body="O Tower of Azora é um marco ao longo da estrada oriental através do Elwynn Forest. Os viajantes usá-lo para encontrar as minas e outras comunidades mais distantes de Goldshire."},pl={title="Tower of Azora",body="Tower of Azora to charakterystyczny punkt przy wschodniej drodze przez Elwynn Forest. Pomaga podróżnym odnajdywać kopalnie i inne osady położone dalej od Goldshire."},ru={title="Tower of Azora",body="Tower of Azora - это ориентир вдоль восточной дороги через Elwynn Forest. Путешественники используют его, чтобы найти шахты и другие населенные пункты дальше от Goldshire."},references={["place:elwynn-forest"]=true,["place:goldshire"]=true}},
    ["place:tower-of-ilgalar"] = {title="Torre de Ilgalar",kind="Lugar",aliases={"Torre de Ilgalar"},body="La Torre de Ilgalar es la residencia de Morganth en Crestagrana. Su actividad mágica despierta la vigilancia de otros magos y la preocupación de quienes defienden los asentamientos cercanos.",aliasQuestIDs={},en={title="Tower of Ilgalar",aliases={"Tower of Ilgalar"},body="The Tower of Ilgalar is Morganth’s home in Redridge. His magical activities draw the scrutiny of other mages and concern from those defending nearby settlements.",aliasQuestIDs={}},fr={title="Tower of Ilgalar",body="Le Tower of Ilgalar est la maison de Morganth dans Redridge. Ses activités magiques attirent l'attention d'autres mages et l'inquiétude de ceux qui défendent les colonies voisines."},de={title="Tower of Ilgalar",body="Der Tower of Ilgalar ist Morganth 's Zuhause in Redridge. Seine magischen Aktivitäten ziehen die Aufmerksamkeit anderer Magier und Besorgnis der Verteidiger nahe gelegener Siedlungen auf sich."},pt={title="Tower of Ilgalar",body="O Tower of Ilgalar é a casa do Morganth em Redridge. Suas atividades mágicas atraem o escrutínio de outros magos e a preocupação daqueles que defendem assentamentos próximos."},pl={title="Tower of Ilgalar",body="Tower of Ilgalar jest siedzibą Morganth w Redridge. Jego magiczna działalność przyciąga uwagę innych magów i niepokoi obrońców pobliskich osad."},ru={title="Tower of Ilgalar",body="Tower of Ilgalar это Morganth  дом в Redridge. Его магические действия привлекают внимание других волхвов и беспокойство тех, кто защищает близлежащие поселения."},references={["npc:morganth"]=true,["place:redridge-mountains"]=true}},
    ["place:tranquil-gardens-cemetery"] = {title="Cementerio del Jardín Sereno",kind="Lugar",aliases={"Cementerio del Jardín Sereno","Jardín Sereno"},body="El Cementerio del Jardín Sereno está al sur de Villa Oscura. Los esqueletos que ocupan el camposanto hacen que este lugar de descanso forme parte de los peligros que vigila la defensa local.",aliasQuestIDs={},en={title="Tranquil Gardens Cemetery",aliases={"Tranquil Gardens","Tranquil Gardens Cemetery"},body="Tranquil Gardens Cemetery lies south of Darkshire. The skeletons occupying its grounds make this resting place one of the dangers watched by the local defenders.",aliasQuestIDs={}},fr={title="Tranquil Gardens Cemetery",body="Tranquil Gardens Cemetery se trouve au sud de Darkshire. Les squelettes qui l’occupent font de ce lieu de repos l’un des dangers surveillés par les défenseurs locaux."},de={title="Tranquil Gardens Cemetery",body="Tranquil Gardens Cemetery liegt südlich von Darkshire. Die Skelette, die sein Gelände besetzen, machen diese Ruhestätte zu einer der Gefahren, die von den lokalen Verteidigern beobachtet werden."},pt={title="Tranquil Gardens Cemetery",body="Tranquil Gardens Cemetery fica ao sul de Darkshire. Os esqueletos que ocupam seus terrenos fazem deste lugar de descanso um dos perigos observados pelos defensores locais."},pl={title="Tranquil Gardens Cemetery",body="Tranquil Gardens Cemetery leży na południe od Darkshire. Szkielety zajmujące jego teren czynią to miejsce spoczynku jednym z zagrożeń obserwowanych przez miejscowych obrońców."},ru={title="Tranquil Gardens Cemetery",body="Tranquil Gardens Cemetery находится к югу от Darkshire. Скелеты, занимающие его территории, делают это место отдыха одной из опасностей, наблюдаемой местными защитниками."},references={["place:darkshire"]=true}},
    ["place:tyrs-hand"] = {title="Mano de Tyr",kind="Lugar",aliases={"Mano de Tyr"},body="Mano de Tyr es una posición de la Cruzada Escarlata en las Tierras de la Peste del Este. Mantiene comunicaciones regulares con Stratholme y recibe órdenes de los altos mandos de la organización.",aliasQuestIDs={},en={title="Tyr's Hand",aliases={"Tyr's Hand","Tyr’s Hand"},body="Tyr's Hand is a Scarlet Crusade position in Eastern Plaguelands. It maintains regular communications with Stratholme and receives orders from the organization's senior command.",aliasQuestIDs={}},fr={title="Tyr's Hand",body="Tyr's Hand est une position Scarlet Crusade dans Eastern Plaguelands. Il maintient des communications régulières avec Stratholme et reçoit des ordres du commandement supérieur de l'organisation."},de={title="Tyr's Hand",body="Tyr's Hand ist eine Scarlet Crusade-Position in Eastern Plaguelands. Sie unterhält regelmäßige Kommunikation mit Stratholme und erhält Befehle vom Oberkommando der Organisation."},pt={title="Tyr's Hand",body="Tyr's Hand é uma posição Scarlet Crusade em Eastern Plaguelands. Ele mantém comunicações regulares com Stratholme e recebe ordens do comando sênior da organização."},pl={title="Tyr's Hand",body="Tyr's Hand jest pozycją Scarlet Crusade w Eastern Plaguelands. Utrzymuje regularną łączność ze Stratholme i otrzymuje rozkazy wyższego dowództwa organizacji."},ru={title="Tyr's Hand",body="Tyr's Hand - это позиция Scarlet Crusade в Eastern Plaguelands. Он поддерживает регулярные связи с Stratholme и получает приказы от высшего командования организации."},references={["organization:scarlet-crusade"]=true,["place:eastern-plaguelands"]=true,["place:plaguelands"]=true,["place:stratholme"]=true}},
    ["place:uldaman"] = {title="Uldaman",kind="Lugar",aliases={"Uldaman"},body="Uldaman es un extenso lugar de excavación cuyas profundidades atraen a exploradores y estudiosos. Sus galerías contienen hallazgos antiguos y formas de vida que convierten la investigación en una actividad peligrosa.",aliasQuestIDs={},en={title="Uldaman",aliases={"Uldaman"},body="Uldaman is a vast excavation whose depths draw explorers and scholars. Its tunnels contain ancient finds and forms of life that make research a dangerous undertaking.",aliasQuestIDs={}},fr={title="Uldaman",body="Uldaman est une vaste excavation dont les profondeurs attirent les explorateurs et les chercheurs. Ses tunnels contiennent des trouvailles anciennes et des formes de vie qui font de la recherche une entreprise dangereuse."},de={title="Uldaman",body="Uldaman ist eine riesige Ausgrabung, deren Tiefen Forscher und Gelehrte anziehen. Seine Tunnel enthalten uralte Funde und Lebensformen, die die die die Forschung zu einem gefährlichen Unterfangen machen."},pt={title="Uldaman",body="Uldaman é uma vasta escavação cujas profundidades atraem exploradores e estudiosos. Seus túneis contêm achados antigos e formas de vida que tornam a pesquisa um empreendimento perigoso."},pl={title="Uldaman",body="Uldaman to rozległe wykopaliska, których głębiny przyciągają odkrywców i uczonych. Tunele kryją starożytne znaleziska oraz formy życia, które czynią badania niebezpiecznym przedsięwzięciem."},ru={title="Uldaman",body="Uldaman - это огромное раскопки, глубины которых привлекают исследователей и ученых. В туннелях находятся древние находки и формы жизни, которые делают исследования опасным делом."},references={}},
    ["place:uldum"] = {title="Uldum",kind="Lugar",aliases={"Uldum"},body="Uldum es un recinto de Tanaris protegido por puertas selladas. La Liga de Expedicionarios y los sabios de Cima del Trueno investigan sus posibles vínculos con los discos de platino y los descubrimientos de Uldaman.",aliasQuestIDs={},en={title="Uldum",aliases={"Uldum"},body="Uldum is a compound in Tanaris behind sealed gates. The Explorers’ League and Thunder Bluff’s sages investigate its possible connections with platinum discs and the discoveries at Uldaman.",aliasQuestIDs={}},fr={title="Uldum",body="Uldum est un composé de Tanaris derrière des portes scellées. Les sages de The Explorers’ League et Thunder Bluff étudient ses connexions possibles avec les disques de platine et les découvertes à Uldaman."},de={title="Uldum",body="Uldum ist eine Mischung aus Tanaris hinter verschlossenen Toren. Die Weisen von The Explorers’ League und Thunder Bluff untersuchen ihre möglichen Verbindungen mit Platinscheiben und den Entdeckungen bei Uldaman."},pt={title="Uldum",body="Uldum é um composto em Tanaris atrás de portões selados. Os sábios de The Explorers’ League e Thunder Bluff investigam suas possíveis conexões com discos de platina e as descobertas na Uldaman."},pl={title="Uldum",body="Uldum jest kompleksem w Tanaris za zapieczętowanymi wrotami. Grupa The Explorers’ League oraz mędrcy z Thunder Bluff badają jego możliwe powiązania z platynowymi dyskami i odkryciami w Uldaman."},ru={title="Uldum",body="Uldum - это соединение в Tanaris за запечатанными воротами. Мудрецы The Explorers’ League и Thunder Bluff  изучают возможные связи с платиновыми дисками и открытиями в Uldaman."},references={["organization:explorers-league"]=true,["place:tanaris"]=true,["place:thunder-bluff"]=true,["place:uldaman"]=true}},
    ["place:undercity"] = {title="Entrañas",kind="Lugar",aliases={"Entrañas"},body="Entrañas es una ciudad de los Renegados dividida en barrios dedicados al comercio, la magia y otras actividades. Allí trabajan los agentes de Sylvanas y los investigadores de la Sociedad Real de Boticarios.",aliasQuestIDs={},en={title="Undercity",aliases={"Undercity"},body="Undercity is a Forsaken city divided into quarters devoted to trade, magic and other activities. Sylvanas's agents and the Royal Apothecary Society's researchers work there.",aliasQuestIDs={}},fr={title="Undercity",body="Undercity est une ville Forsaken divisée en quartiers consacrés au commerce, à la magie et à d'autres activités. Les agents de Sylvanas et les chercheurs du Royal Apothecary Society y travaillent."},de={title="Undercity",body="Undercity ist eine Stadt der Forsaken, die in Viertel für Handel, Magie und andere Tätigkeiten unterteilt ist. Dort arbeiten die Agenten von Sylvanas und die Forscher der Royal Apothecary Society."},pt={title="Undercity",body="Undercity é uma cidade Forsaken dividida em bairros dedicados ao comércio, magia e outras atividades. Os agentes do Sylvanas e os pesquisadores do Royal Apothecary Society trabalham lá."},pl={title="Undercity",body="Undercity jest miastem Forsaken podzielonym na dzielnice poświęcone handlowi, magii i innym zajęciom. Działają tu agenci Sylvanas oraz badacze Royal Apothecary Society."},ru={title="Undercity",body="Undercity - это город Forsaken, разделенный на кварталы, посвященные торговле, магии и другим видам деятельности. Там работают агенты Sylvanas и исследователи Royal Apothecary Society."},references={["npc:sylvanas-windrunner"]=true,["organization:forsaken"]=true,["organization:royal-apothecary-society"]=true}},
    ["place:undercroft"] = {title="La Subgranja",kind="Lugar",aliases={"La Subgranja","Subgranja"},body="La Subgranja es el refugio de un grupo de trols no muertos al oeste de la Capilla de la Esperanza de la Luz. Bajo el mando de Zaeldarr, sus habitantes llevan hasta allí los cuerpos que sustraen durante incursiones nocturnas.",aliasQuestIDs={},en={title="The Undercroft",aliases={"The Undercroft","Undercroft"},body="The Undercroft is an undead troll refuge west of Light's Hope Chapel. Under Zaeldarr's command, its inhabitants bring back bodies stolen during nighttime raids.",aliasQuestIDs={}},fr={title="The Undercroft",body="The Undercroft est un refuge de trolls morts-vivants à l'ouest de Light's Hope Chapel. Sous le commandement de Zaeldarr, ses habitants ramènent les corps volés lors des raids nocturnes."},de={title="The Undercroft",body="The Undercroft ist ein Zufluchtsort für untote Trolle westlich von Light's Hope Chapel. Unter dem Kommando von Zaeldarr bringen die Bewohner Leichen zurück, die bei nächtlichen Razzien gestohlen wurden."},pt={title="The Undercroft",body="The Undercroft é um refúgio de trolls mortos-vivos a oeste de Light's Hope Chapel. Sob o comando de Zaeldarr, seus habitantes trazem de volta corpos roubados durante incursões noturnas."},pl={title="The Undercroft",body="The Undercroft jest schronieniem nieumarłych trolli na zachód od Light's Hope Chapel. Pod dowództwem Zaeldarr mieszkańcy przynoszą ciała skradzione podczas nocnych najazdów."},ru={title="The Undercroft",body="The Undercroft - это убежище троллей-немертвых к западу от Light's Hope Chapel. Под командованием Zaeldarr, его жители возвращают тела, украденные во время ночных рейдов."},references={["concept:holy-light"]=true,["npc:zaeldarr-the-outcast"]=true,["place:lights-hope-chapel"]=true}},
    ["place:ungoro-crater"] = {title="Cráter de Un'Goro",kind="Lugar",aliases={"Cráter de Un'Goro","Cráter de Un’Goro","Un'Goro","Un’Goro"},body="El Cráter de Un'Goro es una región exuberante de Kalimdor con actividad volcánica y una fauna extraordinaria. Sus plantas, criaturas y cristales atraen a investigadores, aunque el terreno hace que las expediciones sean difíciles de sostener.",aliasQuestIDs={},en={title="Un'Goro Crater",aliases={"Un'Goro","Un'Goro Crater","Un’Goro","Un’Goro Crater"},body="Un'Goro Crater is a lush region of Kalimdor with volcanic activity and remarkable wildlife. Its plants, creatures and crystals attract researchers, although the terrain makes expeditions difficult to sustain.",aliasQuestIDs={}},fr={title="Un'Goro Crater",body="Un'Goro Crater est une région luxuriante de Kalimdor avec une activité volcanique et une faune remarquable. Ses plantes, ses créatures et ses cristaux attirent les chercheurs, bien que le terrain rende les expéditions difficiles à supporter."},de={title="Un'Goro Crater",body="Un'Goro Crater ist eine üppige Region von Kalimdor mit vulkanischer Aktivität und bemerkenswerter Tierwelt. Seine Pflanzen, Lebewesen und Kristalle ziehen Forscher an, obwohl das Gelände Expeditionen schwierig zu erhalten ist."},pt={title="Un'Goro Crater",body="Un'Goro Crater é uma região exuberante de Kalimdor com atividade vulcânica e vida selvagem notável. Suas plantas, criaturas e cristais atraem pesquisadores, embora o terreno torne as expedições difíceis de sustentar."},pl={title="Un'Goro Crater",body="Un'Goro Crater to bujny region kontynentu Kalimdor z aktywnością wulkaniczną i niezwykłą fauną. Rośliny, stworzenia oraz kryształy przyciągają badaczy, choć ukształtowanie terenu utrudnia utrzymanie wypraw."},ru={title="Un'Goro Crater",body="Un'Goro Crater - это пышный регион Kalimdor с вулканической активностью и замечательной дикой природой. Ее растения, животные и кристаллы привлекают исследователей, хотя местность делает экспедиции трудно поддерживать."},references={["place:kalimdor"]=true}},
    ["place:valanaar"] = {title="Valanaar",kind="Lugar",aliases={"Valanaar"},body="Valanaar es una ciudad situada en el extremo sureste de Isla Zephras. Alberga a los pacificadores dirigidos por Valennia Puñotormenta y a miembros de la Suma Orden y los Formavientos. La rivalidad entre estas dos tradiciones exige mantener una convivencia cuidadosa dentro de sus calles.",aliasQuestIDs={},en={title="Valanaar",aliases={"Valanaar"},body="Valanaar is a city at the southeastern edge of Zephras Isle. It is home to the peacekeepers led by Valennia Stormfist and to members of the High Order and the Windshapers. Rivalry between these two traditions makes preserving peace within its streets a delicate responsibility.",aliasQuestIDs={}},fr={title="Valanaar",body="Valanaar est une ville à l'extrémité sud-est de Zephras Isle. Elle accueille les gardiens de la paix menés par Valennia Stormfist ainsi que des membres de «the High Order» et des Windshapers. La rivalité entre ces deux traditions fait du maintien de la paix dans ses rues une responsabilité délicate."},de={title="Valanaar",body="Valanaar ist eine Stadt am südöstlichen Rand von Zephras Isle. Es ist die Heimat der Friedenstruppen unter Valennia Stormfist und der Mitglieder von the High Order and the Windshapers. Die Rivalität zwischen diesen beiden Traditionen macht die Erhaltung des Friedens auf den Straßen zu einer heiklen Aufgabe."},pt={title="Valanaar",body="Valanaar é uma cidade no extremo sudeste de Zephras Isle. Ela abriga os pacificadores liderados por Valennia Stormfist e membros de «the High Order» e dos Windshapers. A rivalidade entre essas duas tradições torna a preservação da paz em suas ruas uma responsabilidade delicada."},pl={title="Valanaar",body="Valanaar jest miastem na południowo-wschodnim krańcu Zephras Isle. Mieszkają tu strażnicy pokoju dowodzeni przez Valennia Stormfist oraz członkowie organizacji znanych jako the High Order i the Windshapers. Rywalizacja tych tradycji czyni zachowanie pokoju na ulicach delikatną odpowiedzialnością."},ru={title="Valanaar",body="Valanaar - это город на юго-восточном краю Zephras Isle. Здесь находятся миротворцы под командованием Valennia Stormfist и члены the High Order и Windshapers. Соперничество между этими двумя традициями делает сохранение мира на улицах страны неотложной ответственностью."},references={["organization:high-order"]=true,["organization:windshapers"]=true,["person:valennia-stormfist"]=true,["place:zephras"]=true}},
    ["place:valley-of-bones"] = {title="Valle de los Huesos",kind="Lugar",aliases={"Valle de los Huesos"},body="El Valle de los Huesos es una zona de Desolace temida por sus maldiciones y su energía nigromántica. La rivalidad entre clanes de centauros se ha extendido al valle, donde sus recursos atraen a quienes buscan nuevas fuentes de poder.",aliasQuestIDs={},en={title="Valley of Bones",aliases={"Valley of Bones"},body="The Valley of Bones is an area of Desolace feared for curses and necromantic energy. Rivalry between centaur clans has extended into the valley, whose resources attract those seeking new sources of power.",aliasQuestIDs={}},fr={title="Valley of Bones",body="Le Valley of Bones est une zone de Desolace craint pour les malédictions et l'énergie nécromantique. La rivalité entre les clans centaures s'est étendue dans la vallée, dont les ressources attirent ceux qui cherchent de nouvelles sources de pouvoir."},de={title="Valley of Bones",body="Der Valley of Bones ist ein Bereich von Desolace, der wegen Flüchen und nekromantischer Energie gefürchtet ist. Die Rivalität zwischen den Zentauren-Clans hat sich bis ins Tal ausgedehnt, deren Ressourcen diejenigen anziehen, die nach neuen Machtquellen suchen."},pt={title="Valley of Bones",body="O Valley of Bones é uma área do Desolace temida por maldições e energia necromante. A rivalidade entre os clãs centauros se estendeu para o vale, cujos recursos atraem aqueles que buscam novas fontes de poder."},pl={title="Valley of Bones",body="Valley of Bones to obszar Desolace budzący lęk z powodu klątw i nekromantycznej energii. Rywalizacja klanów centaurów rozszerzyła się na dolinę, której zasoby przyciągają poszukiwaczy nowych źródeł mocy."},ru={title="Valley of Bones",body="Valley of Bones - это область Desolace, которой боятся проклятия и некромантической энергии. Соперничество между кланами кентавров распространилось и в долину, ресурсы которой привлекают тех, кто ищет новые источники силы."},references={["place:desolace"]=true}},
    ["place:valley-of-kings"] = {title="Valle de los Reyes",kind="Lugar",aliases={"Valle de los Reyes"},body="El Valle de los Reyes es un lugar de Loch Modan que sirve de referencia para quienes buscan los pasos de las montañas. Más allá se encuentran senderos hacia cumbres apartadas y lugares de tradición espiritual.",aliasQuestIDs={},en={title="Valley of Kings",aliases={"Valley o' Kings","Valley of Kings","Valley o’ Kings"},body="The Valley of Kings is a Loch Modan landmark for those seeking mountain passages. Beyond it lie trails toward isolated peaks and places of spiritual tradition.",aliasQuestIDs={}},fr={title="Valley of Kings",body="Le Valley of Kings est un point de repère Loch Modan pour ceux qui recherchent des passages en montagne. Au-delà se trouvent des sentiers vers des sommets isolés et des lieux de tradition spirituelle."},de={title="Valley of Kings",body="Der Valley of Kings ist ein Loch Modan-Wahrzeichen für Bergsteiger. Dahinter liegen Pfade zu isolierten Gipfeln und Orten spiritueller Tradition."},pt={title="Valley of Kings",body="O Valley of Kings é um marco do Loch Modan para aqueles que procuram passagens de montanha. Além disso, encontram-se trilhas em direção a picos isolados e lugares de tradição espiritual."},pl={title="Valley of Kings",body="Valley of Kings jest punktem orientacyjnym w Loch Modan dla osób szukających górskich przejść. Dalej prowadzą szlaki ku odosobnionym szczytom i miejscom duchowej tradycji."},ru={title="Valley of Kings",body="Valley of Kings - это ориентир Loch Modan для тех, кто ищет горные проходы. За ним лежат тропы к изолированным вершинам и местам духовной традиции."},references={["place:loch-modan"]=true}},
    ["place:valley-of-spirits"] = {title="Valle de los Espíritus",kind="Lugar",aliases={"Valle de los Espíritus","el Valle de los Espíritus"},body="El Valle de los Espíritus es un distrito de Orgrimmar asociado con las tradiciones espirituales de los trols. Allí enseña Ur'kyo, y sus contactos atraen a sacerdotes que buscan aprender las antiguas costumbres de su pueblo.",aliasQuestIDs={},en={title="Valley of Spirits",aliases={"The Valley of Spirits","Valley of Spirits"},body="The Valley of Spirits is an Orgrimmar district associated with troll spiritual traditions. Ur'kyo teaches there, and his contacts draw priests seeking to learn their people's old ways.",aliasQuestIDs={}},fr={title="Valley of Spirits",body="The Valley of Spirits est un quartier Orgrimmar associé aux traditions spirituelles des trolls. Ur'kyo y enseigne, et ses contacts attirent les prêtres qui cherchent à apprendre les anciennes manières de leur peuple."},de={title="Valley of Spirits",body="The Valley of Spirits ist ein Orgrimmar-Distrikt, der mit spirituellen Traditionen der Trolle verbunden ist. Ur'kyo unterrichtet dort, und seine Kontakte ziehen Priester an, die versuchen, die alten Gewohnheiten ihres Volkes kennenzulernen."},pt={title="Valley of Spirits",body="The Valley of Spirits é um distrito Orgrimmar associado a tradições espirituais troll. Ur'kyo ensina lá, e seus contatos atraem padres que procuram aprender os velhos caminhos de seu povo."},pl={title="Valley of Spirits",body="The Valley of Spirits jest dzielnicą Orgrimmar związaną z duchowymi tradycjami trolli. Ur'kyo naucza tutaj, a jego kontakty przyciągają kapłanów pragnących poznać dawne zwyczaje swojego ludu."},ru={title="Valley of Spirits",body="The Valley of Spirits - это район Orgrimmar, связанный с духовными традициями троллей. Ur'kyo преподаёт там, а его связи привлекают жрецов, желающих изучить древние традиции своего народа."},references={["person:urkyo"]=true,["place:orgrimmar"]=true}},
    ["place:valley-of-trials"] = {title="Valle de los Retos",kind="Lugar",aliases={"Valle de los Retos"},body="El Valle de los Retos es una zona de formación de Durotar. Allí, los nuevos miembros de la Horda aprenden a sobrevivir en una tierra difícil y a convertir su fuerza en servicio para la comunidad.",aliasQuestIDs={},en={title="Valley of Trials",aliases={"Valley of Trials"},body="The Valley of Trials is a training ground in Durotar. New members of the Horde learn to survive in a harsh land and put their strength to work for the community.",aliasQuestIDs={}},fr={title="Valley of Trials",body="Le Valley of Trials est un terrain d'entraînement dans Durotar. Les nouveaux membres du Horde apprennent à survivre dans un pays rude et mettent leur force au service de la communauté."},de={title="Valley of Trials",body="Der Valley of Trials ist ein Trainingsplatz in Durotar. Neue Mitglieder der Horde lernen, in einem rauen Land zu überleben und setzen und setzen ihre Kraft für die Gemeinschaft einzusetzen."},pt={title="Valley of Trials",body="O Valley of Trials é um campo de treinamento em Durotar. Novos membros do Horde aprendem a sobreviver em uma terra dura e colocar suas forças para trabalhar para a comunidade."},pl={title="Valley of Trials",body="Valley of Trials to teren szkoleniowy w Durotar. Nowi członkowie frakcji Horde uczą się przetrwania w surowej krainie i wykorzystywania własnej siły dla dobra społeczności."},ru={title="Valley of Trials",body="Valley of Trials — место для тренировок в Durotar. Новые члены Horde учатся выживать в суровой местности и отдают свои силы на работу для общества."},references={["organization:horde"]=true,["place:durotar"]=true}},
    ["place:venomweb-vale"] = {title="Vega Venerácnidas",kind="Lugar",aliases={"Vega Venerácnidas"},body="Vega Venerácnidas es una zona de los Claros de Tirisfal donde los Renegados vigilan actividad de la Cruzada Escarlata. La presencia de enemigos y criaturas peligrosas dificulta las labores de sus exploradores.",aliasQuestIDs={},en={title="Venomweb Vale",aliases={"Venomweb Vale"},body="Venomweb Vale is an area of Tirisfal Glades where the Forsaken monitor Scarlet Crusade activity. Hostile forces and dangerous creatures complicate their scouts' work.",aliasQuestIDs={}},fr={title="Venomweb Vale",body="Venomweb Vale est une zone de Tirisfal Glades où the Forsaken surveille l'activité Scarlet Crusade. Les forces hostiles et les créatures dangereuses compliquent le travail de leurs éclaireurs."},de={title="Venomweb Vale",body="Venomweb Vale ist ein Bereich von Tirisfal Glades, wo the Forsaken Scarlet Crusade die Aktivität überwacht. Feindliche Kräfte und gefährliche Kreaturen erschweren die Arbeit ihrer Kundschafter."},pt={title="Venomweb Vale",body="Venomweb Vale é uma área de Tirisfal Glades onde the Forsaken monitorar Scarlet Crusade atividade. Forças hostis e criaturas perigosas complicam o trabalho de seus batedores."},pl={title="Venomweb Vale",body="Venomweb Vale jest obszarem Tirisfal Glades, gdzie lud znany jako the Forsaken obserwuje działania Scarlet Crusade. Wrogie siły i niebezpieczne stworzenia utrudniają pracę jego zwiadowcom."},ru={title="Venomweb Vale",body="Venomweb Vale - это область Tirisfal Glades, где the Forsaken контролирует активность Scarlet Crusade. Вражеские силы и опасные существа усложняют работу разведчиков."},references={["organization:forsaken"]=true,["organization:scarlet-crusade"]=true,["place:tirisfal-glades"]=true}},
    ["place:violet-citadel"] = {title="Ciudadela Violeta",kind="Lugar",aliases={"Ciudadela Violeta"},body="La Ciudadela Violeta es un centro de actividad mágica de Dalaran. Sus salas y resguardos están ligados al trabajo del Kirin Tor y al control de los poderes arcanos que atraviesan la ciudad.",aliasQuestIDs={},en={title="Violet Citadel",aliases={"Violet Citadel"},body="The Violet Citadel is a center of magical activity in Dalaran. Its halls and wards are associated with the Kirin Tor’s work and the control of arcane powers running through the city.",aliasQuestIDs={}},fr={title="Violet Citadel",body="Le Violet Citadel est un centre d'activité magique dans Dalaran. Ses salles et quartiers sont associés au travail de la Kirin Tor et au contrôle des pouvoirs arcaniques qui traversent la ville."},de={title="Violet Citadel",body="Der Violet Citadel ist ein Zentrum magischer Aktivität in Dalaran. Seine Hallen und Stationen sind mit der Arbeit der Kirin Tor und der Kontrolle obskurer Mächtiger Mächte verbunden, die durch die sich durch die Stadt ziehen."},pt={title="Violet Citadel",body="O Violet Citadel é um centro de atividade mágica no Dalaran. Seus corredores e alas estão associados ao trabalho do Kirin Tor e ao controle de poderes arcanos que atravessam a cidade."},pl={title="Violet Citadel",body="Violet Citadel jest ośrodkiem magicznej działalności w Dalaran. Sale i zabezpieczenia wiążą się z pracą Kirin Tor oraz kontrolą magicznych sił przepływających przez miasto."},ru={title="Violet Citadel",body="Violet Citadel - это центр магической деятельности в Dalaran. Его залы и палаты связаны с работой Kirin Tor  и контролем таинственных сил, проходящих по городу."},references={["organization:kirin-tor"]=true,["place:dalaran"]=true}},
    ["place:voodress"] = {title="Voodress",kind="Lugar",aliases={"Voodress"},body="Voodress es un pueblo de los mares del sur cuya imagen aparece en un orbe de Maywiki. Ese vínculo mágico permite que sus aliados contemplen un lugar lejano como recordatorio de los espíritus y de las tradiciones que comparten.",aliasQuestIDs={},en={title="Voodress",aliases={"Voodress"},body="Voodress is a South Seas village whose image appears in one of Maywiki's orbs. That magical connection lets his allies glimpse a distant place as a reminder of the spirits and traditions they share.",aliasQuestIDs={}},fr={title="Voodress",body="Voodress est un village South Seas dont l'image apparaît dans l'une des orbes de Maywiki. Cette connexion magique permet à ses alliés d’entrevoir un endroit lointain comme un rappel des esprits et des traditions qu’ils partagent."},de={title="Voodress",body="Voodress ist ein South Seas-Dorf, dessen Abbild in einer von Maywiki 'Kugeln erscheint. Diese magische Verbindung lässt seine Verbündeten einen fernen Ort erahnen, als Erinnerung an die Geister und Traditionen, die sie teilen."},pt={title="Voodress",body="Voodress é uma aldeia South Seas cuja imagem aparece em um dos orbes de Maywiki. Essa conexão mágica permite que seus aliados vislumbrem um lugar distante como um lembrete dos espíritos e tradições que compartilham."},pl={title="Voodress",body="Voodress jest wioską na South Seas, której obraz pojawia się w jednej z kul Maywiki. To magiczne połączenie pozwala jego sojusznikom ujrzeć odległe miejsce, przypominające o wspólnych duchach i tradycjach."},ru={title="Voodress",body="Voodress - это деревня South Seas, изображение которой появляется в одном из шаров Maywiki. Эта магическая связь позволяет его союзникам увидеть далекое место, напоминающее об их духовных и традиционных отношениях."},references={["npc:maywiki-of-zuldazar"]=true,["place:south-seas"]=true}},
    ["place:wailing-caverns"] = {title="Cuevas de los Lamentos",kind="Lugar",aliases={"Cuevas de los Lamentos"},body="Las Cuevas de los Lamentos forman un sistema subterráneo de Los Baldíos, relacionado con los esfuerzos druídicos por devolver la vida a la región. Dentro de sus túneles, el sueño y la naturaleza han adquirido formas peligrosas.",aliasQuestIDs={},en={title="Wailing Caverns",aliases={"Wailing Caverns"},body="The Wailing Caverns are an underground system in the Barrens associated with druidic attempts to restore life to the region. Within its tunnels, dreams and nature have taken dangerous forms.",aliasQuestIDs={}},fr={title="Wailing Caverns",body="Le Wailing Caverns est un système souterrain dans le Barrens associé à des tentatives druidiques pour restaurer la vie dans la région. Dans ses tunnels, les rêves et la nature ont pris des formes dangereuses."},de={title="Wailing Caverns",body="Die Wailing Caverns sind ein unterirdisches System im Barrens, das mit druidischen Versuchen in Verbindung gebracht wird, der Region das Leben wiederherzustellen. In ihren Tunneln haben Träume und Natur gefährliche Formen angenommen."},pt={title="Wailing Caverns",body="O Wailing Caverns é um sistema subterrâneo no Barrens associado a tentativas druídicas de restaurar a vida na região. Dentro de seus túneis, sonhos e natureza assumiram formas perigosas."},pl={title="Wailing Caverns",body="Wailing Caverns to podziemny system jaskiń w regionie Barrens, związany z próbami druidów przywrócenia życia tej krainie. W jego tunelach sny i przyroda przybrały niebezpieczne formy."},ru={title="Wailing Caverns",body="Wailing Caverns - подземная система в Barrens, связанная с попытками друидов восстановить жизнь в регионе. В его туннелях мечты и природа приняли опасные формы."},references={["place:the-barrens"]=true}},
    ["place:warsong-gulch"] = {title="Garganta Grito de Guerra",kind="Lugar",aliases={"Garganta Grito de Guerra"},body="La Garganta Grito de Guerra es una zona de conflicto entre la Horda y la Alianza. La disputa por los bosques y la madera enfrenta allí a los escoltas Grito de Guerra con las centinelas Ala de Plata.",aliasQuestIDs={},en={title="Warsong Gulch",aliases={"Warsong Gulch"},body="Warsong Gulch is a conflict zone between the Horde and Alliance. Disputes over forest and timber pit the Warsong Outriders against the Silverwing Sentinels there.",aliasQuestIDs={}},fr={title="Warsong Gulch",body="Warsong Gulch est une zone de conflit entre Horde et Alliance. Les disputes sur la forêt et le bois opposent la Warsong Outriders à la Silverwing Sentinels."},de={title="Warsong Gulch",body="Warsong Gulch ist eine Konfliktzone zwischen dem Horde und Alliance. Streitigkeiten um Wald und Holz bringen den Warsong Outriders gegen den Silverwing Sentinels dort in die Bredouille."},pt={title="Warsong Gulch",body="Warsong Gulch é uma zona de conflito entre o Horde e Alliance. Disputas sobre floresta e madeira colocam o Warsong Outriders contra o Silverwing Sentinels lá."},pl={title="Warsong Gulch",body="Warsong Gulch to obszar konfliktu między frakcjami Horde i Alliance. Spory o las oraz drewno stawiają tam Warsong Outriders przeciw Silverwing Sentinels."},ru={title="Warsong Gulch",body="Warsong Gulch - это зона конфликта между Horde и Alliance. Споры по поводу леса и древесины вынуждают Warsong Outriders противостоять Silverwing Sentinels там."},references={["organization:alliance"]=true,["organization:horde"]=true,["organization:night-elf-sentinels"]=true,["organization:silverwing-sentinels"]=true,["organization:warsong-outriders"]=true}},
    ["place:westbrook-garrison"] = {title="Cuartel de Arroyoeste",kind="Lugar",aliases={"Arroyoeste","Cuartel de Arroyoeste"},body="El Cuartel de Arroyoeste protege la frontera occidental de Elwynn. Sus soldados vigilan las incursiones de gnolls y ladrones en una zona donde los refuerzos de Ventormenta no siempre alcanzan para cubrir todas las necesidades.",aliasQuestIDs={},en={title="Westbrook Garrison",aliases={"Westbrook","Westbrook Garrison"},body="Westbrook Garrison protects Elwynn’s western frontier. Its soldiers watch for gnoll and bandit incursions in a district where Stormwind cannot always provide enough reinforcements.",aliasQuestIDs={}},fr={title="Westbrook Garrison",body="Westbrook Garrison protège la frontière ouest de Elwynn. Ses soldats surveillent les incursions de gnolls et de bandits dans un quartier où Stormwind ne peut pas toujours fournir suffisamment de renforts."},de={title="Westbrook Garrison",body="Westbrook Garrison schützt die westliche Grenze von Elwynn. Seine Soldaten halten nach einfallenden Gnollen und Banditen Ausschau, während Stormwind der Gegend nicht immer genügend Verstärkung zur Verfügung stellen kann."},pt={title="Westbrook Garrison",body="Westbrook Garrison protege a fronteira ocidental do Elwynn. Seus soldados vigiam incursões de gnoll e bandidos em um distrito onde Stormwind nem sempre pode fornecer reforços suficientes."},pl={title="Westbrook Garrison",body="Westbrook Garrison chroni zachodnią granicę Elwynn. Jego żołnierze wypatrują najazdów gnolli i bandytów w okolicy, której Stormwind nie zawsze może zapewnić wystarczające posiłki."},ru={title="Westbrook Garrison",body="Westbrook Garrison защищает западную границу Elwynn. Его солдаты следят за вторжениями бандитов в район, где Stormwind не всегда может обеспечить достаточно подкреплений."},references={["place:elwynn-forest"]=true,["place:stormwind"]=true}},
    ["place:western-plaguelands"] = {title="Tierras de la Peste del Oeste",kind="Lugar",aliases={"Tierras de la Peste del Oeste"},body="Las Tierras de la Peste del Oeste contienen antiguas poblaciones de Lordaeron devastadas por los no-muertos. La lucha por Andorhal enfrenta a los defensores de la región con los comandantes de la Plaga.",aliasQuestIDs={},en={title="Western Plaguelands",aliases={"Western Plaguelands"},body="Western Plaguelands contains former Lordaeron settlements devastated by the undead. The struggle for Andorhal pits regional defenders against Scourge commanders.",aliasQuestIDs={}},fr={title="Western Plaguelands",body="Western Plaguelands contient d'anciens établissements Lordaeron dévastés par les morts-vivants. La lutte pour Andorhal oppose les défenseurs régionaux contre les commandants Scourge."},de={title="Western Plaguelands",body="Western Plaguelands enthält ehemalige Lordaeron-Siedlungen, die von Untoten verwüstet wurden. Im Kampf um Andorhal stehen sich regionale Verteidiger gegen Scourge Kommandeure."},pt={title="Western Plaguelands",body="Western Plaguelands contém antigos assentamentos Lordaeron devastados pelos mortos-vivos. A luta pelo Andorhal coloca os defensores regionais contra os comandantes do Scourge."},pl={title="Western Plaguelands",body="Western Plaguelands obejmuje dawne osady Lordaeron zniszczone przez nieumarłych. Walka o Andorhal stawia obrońców regionu przeciw dowódcom Scourge."},ru={title="Western Plaguelands",body="Western Plaguelands содержит бывшие поселения Lordaeron, опустошенные неживыми. Борьба за Andorhal ставит региональных защитников против командующих Scourge."},references={["organization:scourge"]=true,["place:andorhal"]=true,["place:lordaeron"]=true,["place:plaguelands"]=true}},
    ["place:westfall"] = {title="Páramos de Poniente",kind="Lugar",aliases={"Poniente","Páramos de Poniente"},body="Los Páramos de Poniente son una región de granjas y minas cuya población vive bajo la presión de bandidos y criaturas hostiles. Los vecinos que permanecen allí dependen de su propia milicia para defender sus hogares y mantener abiertas las rutas.",aliasQuestIDs={},en={title="Westfall",aliases={"Westfall"},body="Westfall is a region of farms and mines whose people live under pressure from bandits and hostile creatures. Those who remain depend on their own militia to defend their homes and keep the roads open.",aliasQuestIDs={}},fr={title="Westfall",body="Westfall est une région de fermes et de mines dont les habitants vivent sous la pression de bandits et de créatures hostiles. Ceux qui restent dépendent de leur propre milice pour défendre leurs maisons et garder les routes ouvertes."},de={title="Westfall",body="Westfall ist eine Region mit Höfen und Minen, deren Menschen unter dem Druck von Banditen und feindlichen Kreaturen leben. Diejenigen, die bleiben, sind auf ihre eigene Milizen angewiesen, um ihre Häuser zu verteidigen und die Straßen offen zu halten."},pt={title="Westfall",body="Westfall é uma região de fazendas e minas cujas pessoas vivem sob pressão de bandidos e criaturas hostis. Aqueles que permanecem dependem de sua própria milícia para defender suas casas e manter as estradas abertas."},pl={title="Westfall",body="Westfall to region gospodarstw i kopalń, którego mieszkańcy żyją pod presją bandytów i wrogich stworzeń. Ci, którzy pozostali, polegają na własnej milicji, by bronić domów i utrzymywać przejezdność dróg."},ru={title="Westfall",body="Westfall - это регион ферм и шахт, жители которого живут под давлением бандитов и враждебных существ. Те, кто остался, полагаются на свои собственные ополченцы, чтобы защитить свои дома и держать дороги открытыми."},references={}},
    ["place:westfall-lighthouse"] = {title="Faro de Poniente",kind="Lugar",aliases={"Faro de Poniente"},body="El Faro de Poniente ayuda a los navegantes a evitar los peligros de la costa. Mantener su luz requiere suministros y protección frente a las criaturas que amenazan a quienes viven junto al mar.",aliasQuestIDs={},en={title="Westfall Lighthouse",aliases={"Westfall Lighthouse","lighthouse"},body="Westfall Lighthouse helps sailors avoid the dangers along the coast. Keeping its light burning requires supplies and protection from the creatures that threaten the shoreline’s inhabitants.",aliasQuestIDs={}},fr={title="Westfall Lighthouse",body="Westfall Lighthouse aide les marins à éviter les dangers le long de la côte. Garder sa lumière allumée nécessite des fournitures et une protection contre les créatures qui menacent les habitants du littoral."},de={title="Westfall Lighthouse",body="Westfall Lighthouse hilft Seeleuten, die Gefahren entlang der Küste zu vermeiden. Um sein Licht brennen zu lassen, bedarf es Vorräte und Schutz vor den Kreaturen, die die die die Bewohner der Küste bedrohen."},pt={title="Westfall Lighthouse",body="Westfall Lighthouse ajuda os marinheiros a evitar os perigos ao longo da costa. Manter sua queima de luz requer suprimentos e proteção contra as criaturas que ameaçam os habitantes da costa."},pl={title="Westfall Lighthouse",body="Westfall Lighthouse pomaga żeglarzom unikać niebezpieczeństw wybrzeża. Utrzymanie jej światła wymaga dostaw oraz ochrony przed stworzeniami zagrażającymi mieszkańcom nadbrzeżnych terenów."},ru={title="Westfall Lighthouse",body="Westfall Lighthouse помогает морякам избегать опасностей вдоль побережья. Чтобы его свет не терялся, необходимо снабжение и защита от существ, угрожающих жителям береговой линии."},references={["place:westfall"]=true}},
    ["place:wetlands"] = {title="Los Humedales",kind="Lugar",aliases={"Humedales","Los Humedales"},body="Los Humedales son una región de marismas, vías de agua y excavaciones. Sus asentamientos y expediciones deben convivir con criaturas de los pantanos y con los peligros que surgen en los barrancos y las antiguas ruinas.",aliasQuestIDs={},en={title="Wetlands",aliases={"Wetlands"},body="The Wetlands are a region of marshes, waterways and excavation sites. Its settlements and expeditions contend with swamp creatures and dangers emerging from ravines and ancient ruins.",aliasQuestIDs={}},fr={title="Wetlands",body="Les Wetlands sont une région de marais, de cours d'eau et de sites d'excavation. Ses colonies et ses expéditions font face à des créatures marécageuses et à des dangers émergeant des ravins et des ruines antiques."},de={title="Wetlands",body="Die Wetlands sind eine Region mit Sümpfen, Gewässern und Ausgrabungsstätten. Seine Siedlungen und Expeditionen kämpfen mit Sumpfwesen und Gefahren, die aus Schluchten und uralten Ruinen entstehen."},pt={title="Wetlands",body="O Wetlands é uma região de pântanos, cursos de água e locais de escavação. Seus assentamentos e expedições lidam com criaturas pantanosas e perigos emergentes de ravinas e ruínas antigas."},pl={title="Wetlands",body="Wetlands to region mokradeł, cieków wodnych i wykopalisk. Jego osady oraz wyprawy zmagają się z bagiennymi stworzeniami i zagrożeniami wyłaniającymi się z wąwozów oraz dawnych ruin."},ru={title="Wetlands",body="Wetlands - это регион болотов, водных путей и раскопок. В его поселениях и экспедициях встречаются мутные существа и опасности, возникающие из ущелий и древних руин."},references={}},
    ["place:whelgars-excavation"] = {title="Excavación de Whelgar",kind="Lugar",aliases={"Excavación de Whelgar","Whelgar"},body="La Excavación de Whelgar es un lugar de investigación arqueológica en los Humedales. Las reliquias descubiertas allí forman parte del trabajo de los exploradores que intentan comprender el pasado conservado bajo la tierra.",aliasQuestIDs={},en={title="Whelgar's Excavation Site",aliases={"Whelgar","Whelgar's Excavation Site","Whelgar’s Excavation Site"},body="Whelgar’s Excavation Site is an archaeological dig in the Wetlands. Relics found there are part of the explorers’ efforts to understand the past preserved beneath the earth.",aliasQuestIDs={}},fr={title="Whelgar's Excavation Site",body="Whelgar’s Excavation Site est une fouille archéologique dans le Wetlands. Les reliques trouvées là-bas font partie des efforts des explorateurs pour comprendre le passé préservé sous la terre."},de={title="Whelgar's Excavation Site",body="Whelgar’s Excavation Site ist eine archäologische Ausgrabung im Wetlands. Die dort gefundenen Relikte sind Teil der Bemühungen der Forscher, die unter der Erde erhaltene Vergangenheit zu verstehen."},pt={title="Whelgar's Excavation Site",body="Whelgar’s Excavation Site é uma escavação arqueológica no Wetlands. Relíquias encontradas lá são parte dos esforços dos exploradores para entender o passado preservado sob a terra."},pl={title="Whelgar's Excavation Site",body="Whelgar’s Excavation Site to stanowisko archeologiczne w Wetlands. Znajdowane tam relikty pomagają odkrywcom zrozumieć przeszłość zachowaną pod ziemią."},ru={title="Whelgar's Excavation Site",body="Whelgar’s Excavation Site - это археологические раскопки в Wetlands. Останки, найденные там, являются частью исследовательских усилий по изучению прошлого, сохранившегося под землей."},references={["place:wetlands"]=true}},
    ["place:whitereach-post"] = {title="Campamento del Tramo Blanco",kind="Lugar",aliases={"Campamento del Tramo Blanco"},body="El Campamento del Tramo Blanco se encuentra al este de Nido Alto, en Las Mil Agujas. Sirve de punto de referencia para quienes estudian o buscan dracoleones en los riscos cercanos.",aliasQuestIDs={},en={title="Whitereach Post",aliases={"Whitereach Post"},body="Whitereach Post lies east of Highperch in Thousand Needles. It is a point of reference for those studying or seeking wyverns among the nearby cliffs.",aliasQuestIDs={}},fr={title="Whitereach Post",body="Whitereach Post se trouve à l'est de Highperch dans Thousand Needles. C'est un point de référence pour ceux qui étudient ou cherchent des wyverns parmi les falaises voisines."},de={title="Whitereach Post",body="Whitereach Post liegt östlich von Highperch in Thousand Needles. Es ist ein Bezugspunkt für diejenigen, die Flügeldrachen zwischen den nahe gelegenen Klippen studieren oder suchen."},pt={title="Whitereach Post",body="Whitereach Post fica a leste de Highperch em Thousand Needles. É um ponto de referência para aqueles que estudam ou procuram wyverns entre as falésias próximas."},pl={title="Whitereach Post",body="Whitereach Post leży na wschód od Highperch w Thousand Needles. Jest punktem odniesienia dla osób badających wywerny lub szukających ich wśród pobliskich klifów."},ru={title="Whitereach Post",body="Whitereach Post находится к востоку от Highperch в Thousand Needles. Это ориентир для тех, кто изучает или ищет виверны среди близлежащих скал."},references={["place:highperch"]=true,["place:thousand-needles"]=true}},
    ["place:wildpaw-cavern"] = {title="Caverna Zarpa Salvaje",kind="Lugar",aliases={"Caverna Zarpa Salvaje"},body="La Caverna Zarpa Salvaje es un refugio de gnolls en el Valle de Alterac. Su interior también conserva un estandarte Lobo Gélido relacionado con los ritos de los combatientes del clan.",aliasQuestIDs={},en={title="Wildpaw Cavern",aliases={"Wildpaw Cavern"},body="Wildpaw Cavern is a gnoll refuge in Alterac Valley. Its interior also holds a Frostwolf banner associated with the clan's battle rites.",aliasQuestIDs={}},fr={title="Wildpaw Cavern",body="Wildpaw Cavern est un refuge gnoll dans Alterac Valley. Son intérieur contient également une bannière Frostwolf associée aux rites de combat du clan."},de={title="Wildpaw Cavern",body="Wildpaw Cavern ist ein Zufluchtsort der Gnolle in Alterac Valley. In ihrem Inneren befindet sich außerdem ein Banner der Frostwolf, das mit den Kampfriten des Klans verbunden ist."},pt={title="Wildpaw Cavern",body="Wildpaw Cavern é um refúgio gnoll em Alterac Valley. Seu interior também possui uma bandeira Frostwolf associada aos ritos de batalha do clã."},pl={title="Wildpaw Cavern",body="Wildpaw Cavern jest schronieniem gnolli w Alterac Valley. Wewnątrz znajduje się także sztandar Frostwolf związany z bitewnymi obrzędami klanu."},ru={title="Wildpaw Cavern",body="Wildpaw Cavern - это убежище гнолов в Alterac Valley. Внутри его также находится знамя Frostwolf, связанное с боевыми ритуалами клана."},references={["object:frostwolf-banner"]=true,["organization:frostwolf-clan"]=true,["place:alterac-mountains"]=true,["place:alterac-valley"]=true}},
    ["place:windfield-orchard"] = {title="Huerto de Campo de Viento",kind="Lugar",aliases={"Huerto de Campo de Viento","huerto de Campo de Viento"},body="El Huerto de Campo de Viento es una explotación agrícola en los bajíos al oeste de Valanaar. Pertenece a la familia de Alvarion y Aamelia Campo de Viento y produce tormanzanas. Los bandidos que acechan entre sus árboles amenazan tanto la cosecha como la seguridad de quienes viven allí.",aliasQuestIDs={},en={title="Windfield Orchard",aliases={"Windfield Orchard"},body="Windfield Orchard is a farm in the lowlands west of Valanaar. It belongs to the family of Alvarion and Aamelia Windfield and produces stormapples. Bandits lurking among its trees threaten both the harvest and the safety of the people who live there.",aliasQuestIDs={}},fr={title="Windfield Orchard",body="Windfield Orchard est une ferme dans les basses terres à l'ouest de Valanaar. Il appartient à la famille des Alvarion et Aamelia Windfield. Les bandits qui se cachent parmi ses arbres menacent à la fois la récolte et la sécurité des personnes qui y vivent."},de={title="Windfield Orchard",body="Windfield Orchard ist ein Bauernhof im Tiefland westlich von Valanaar. Sie gehört der Familie von Alvarion und Aamelia Windfield und produziert Sturmäpfel. Banditen, die zwischen den Bäumen lauern, bedrohen sowohl die Ernte als auch die Sicherheit der Menschen, die dort leben."},pt={title="Windfield Orchard",body="Windfield Orchard é uma fazenda nas terras baixas a oeste de Valanaar. Pertence à família de Alvarion e Aamelia Windfield, e produz stormapples. Os bandidos que se escondem entre suas árvores ameaçam tanto a colheita quanto a segurança das pessoas que vivem lá."},pl={title="Windfield Orchard",body="Windfield Orchard jest gospodarstwem na nizinach na zachód od Valanaar. Należy do rodziny Alvarion i Aamelia Windfield oraz produkuje burzowe jabłka. Bandyci ukryci między drzewami zagrażają zbiorom i bezpieczeństwu mieszkańców."},ru={title="Windfield Orchard",body="Windfield Orchard - это ферма в низине к западу от Valanaar. Он принадлежит к семейству Alvarion и Aamelia Windfield и производит буревые яблоки. Бандиты, скрывающиеся среди деревьев, угрожают урожаю и безопасности людей, живущих там."},references={["person:aamelia-windfield"]=true,["person:alvarion-windfield"]=true,["place:valanaar"]=true}},
    ["place:windshear-crag"] = {title="Risco Cortaviento",kind="Lugar",aliases={"Risco Cortaviento"},body="Risco Cortaviento es una zona de Sierra Espolón explotada por la compañía Ventura y Cía. Sus operaciones enfrentan el interés industrial por la madera con quienes intentan conservar los bosques.",aliasQuestIDs={},en={title="Windshear Crag",aliases={"Windshear Crag"},body="Windshear Crag is an area of the Stonetalon Mountains exploited by the Venture Company. Its operations pit industrial demand for timber against those trying to preserve the forests.",aliasQuestIDs={}},fr={title="Windshear Crag",body="Windshear Crag est une zone du Stonetalon Mountains exploitée par le Venture Company. Ses opérations opposent la demande industrielle de bois à ceux qui tentent de préserver les forêts."},de={title="Windshear Crag",body="Windshear Crag ist ein Bereich des Stonetalon Mountains, der vom Venture Company ausgebeutet wird. Ihre Betriebe stellen die industrielle Nachfrage nach Holz denjenigen gegenüber, die versuchen, die Wälder zu erhalten."},pt={title="Windshear Crag",body="Windshear Crag é uma área do Stonetalon Mountains explorada pelo Venture Company. Suas operações colocam a demanda industrial por madeira contra aqueles que tentam preservar as florestas."},pl={title="Windshear Crag",body="Windshear Crag to obszar regionu Stonetalon Mountains eksploatowany przez Venture Company. Działalność przedsiębiorstwa stawia przemysłowe zapotrzebowanie na drewno w konflikcie z wysiłkami obrońców lasów."},ru={title="Windshear Crag",body="Windshear Crag - это область Stonetalon Mountains, эксплуатируемая Venture Company. Его деятельность вытесняет промышленное спрос на древесину от тех, кто пытается сохранить леса."},references={["organization:venture-company"]=true,["place:stonetalon-mountains"]=true}},
    ["place:winterspring"] = {title="Cuna del Invierno",kind="Lugar",aliases={"Cuna del Invierno"},body="Cuna del Invierno es una región nevada del norte de Kalimdor. Sus criaturas, comunidades y ruinas conviven con un clima duro que atrae tanto a exploradores como a quienes buscan recursos poco comunes.",aliasQuestIDs={},en={title="Winterspring",aliases={"Winterspring"},body="Winterspring is a snowy region in northern Kalimdor. Its creatures, communities and ruins share a harsh climate that attracts explorers and those seeking unusual resources.",aliasQuestIDs={}},fr={title="Winterspring",body="Winterspring est une région enneigée dans le nord de Kalimdor. Ses créatures, ses communautés et ses ruines partagent un climat rigoureux qui attire les explorateurs et ceux qui recherchent des ressources inhabituelles."},de={title="Winterspring",body="Winterspring ist eine verschneite Region im Norden von Kalimdor. Seine Geschöpfe, Gemeinschaften und Ruinen teilen ein raues Klima, das Entdeforscher und diejenigen anzieht, die ungewöhnliche Ressourcen suchen."},pt={title="Winterspring",body="Winterspring é uma região nevada no norte de Kalimdor. Suas criaturas, comunidades e ruínas compartilham um clima severo que atrai exploradores e aqueles que procuram recursos incomuns."},pl={title="Winterspring",body="Winterspring to śnieżny region północnego Kalimdor. Jego stworzenia, społeczności i ruiny dzielą surowy klimat przyciągający odkrywców oraz poszukiwaczy niezwykłych zasobów."},ru={title="Winterspring",body="Winterspring - снежный регион на севере Kalimdor. Его существа, общины и руины разделяют суровый климат, который привлекает исследователей и тех, кто ищет необычные ресурсы."},references={["place:kalimdor"]=true}},
    ["place:writhing-deep"] = {title="Galerías Retorcidas",kind="Lugar",aliases={"Galerías Retorcidas"},body="Las Galerías Retorcidas son el territorio de los insectos Zukk'ash en Feralas. Entre sus criaturas destaca Latigador con aguijón, cuyo tamaño y extrañas secreciones han atraído la atención de los exploradores.",aliasQuestIDs={},en={title="Writhing Deep",aliases={"Writhing Deep"},body="The Writhing Deep is the territory of the Zukk'ash insects in Feralas. Among its creatures is Stinglasher, whose size and unusual secretions have drawn scouts’ attention.",aliasQuestIDs={}},fr={title="Writhing Deep",body="Le Writhing Deep est le territoire des insectes Zukk'ash dans Feralas. Parmi ses créatures se trouve Stinglasher, dont la taille et les sécrétions inhabituelles ont attiré l’attention des éclaireurs."},de={title="Writhing Deep",body="Der Writhing Deep ist das Revier der Zukk'ash-Insekten in Feralas. Zu den Lebewesen gehört Stinglasher, dessen Größe und ungewöhnliche Sekrete die Aufmerksamkeit der Pfadfinder Kundschafter auf sich gezogen haben."},pt={title="Writhing Deep",body="O Writhing Deep é o território dos insetos Zukk'ash no Feralas. Entre suas criaturas está o Stinglasher, cujo tamanho e secreções incomuns atraíram a atenção dos escoteiros."},pl={title="Writhing Deep",body="Writhing Deep jest terytorium owadów Zukk'ash w Feralas. Wśród jego stworzeń znajduje się Stinglasher, którego rozmiary i niezwykłe wydzieliny zwróciły uwagę zwiadowców."},ru={title="Writhing Deep",body="Writhing Deep - это территория насекомых Zukk'ash в Feralas. Среди его существ есть Stinglasher, чей размер и необычные секреты привлекли внимание разведчиков."},references={["organization:zukkash"]=true,["person:stinglasher"]=true,["place:feralas"]=true}},
    ["place:xavian"] = {title="Xavian",kind="Lugar",aliases={"Xavian"},body="Xavian es una antigua ciudad escondida en el este de Vallefresno. Sus aguas tienen fama de albergar gran poder mágico, pero las ruinas están ocupadas por sátiros que rechazan a quienes intentan investigar sus secretos.",aliasQuestIDs={},en={title="Xavian",aliases={"Xavian"},body="Xavian is an ancient city hidden in eastern Ashenvale. Its waters are reputed to hold great magical power, but satyrs occupy the ruins and resist outsiders investigating their secrets.",aliasQuestIDs={}},fr={title="Xavian",body="Xavian est une ancienne ville cachée dans l'est de Ashenvale. Ses eaux sont réputées pour détenir un grand pouvoir magique, mais les satyres occupent les ruines et résistent aux étrangers qui enquêtent sur leurs secrets."},de={title="Xavian",body="Xavian ist eine antike Stadt im östlichen Ashenvale versteckt. Seine Gewässer haben angeblich eine große magische Kraft, aber Satyren bewohnen die Ruinen und widerstehen Außenstehenden Forschern, die ihre Geheimnisse erforschen."},pt={title="Xavian",body="Xavian é uma cidade antiga escondida no leste de Ashenvale. Suas águas têm a fama de possuir grande poder mágico, mas os sátiros ocupam as ruínas e resistem aos estranhos que investigam seus segredos."},pl={title="Xavian",body="Xavian jest starożytnym miastem ukrytym we wschodniej części Ashenvale. Jego wodom przypisuje się wielką moc magiczną, lecz ruiny zajmują satyrowie, którzy stawiają opór obcym próbującym poznać ich tajemnice."},ru={title="Xavian",body="Xavian - это древний город, спрятанный в восточном Ashenvale. Считается, что в его водах велика магическая сила, но сатири занимают руины и сопротивляются посторонним, которые расследуют их тайны."},references={["place:ashenvale"]=true}},
    ["place:yojamba-isle"] = {title="Isla Yojamba",kind="Lugar",aliases={"Isla Yojamba"},body="La Isla Yojamba es un punto de reunión de los Zandalar frente a Tuercespina. Sus representantes reúnen conocimientos, materiales rituales y ayuda para afrontar los peligros relacionados con Zul'Gurub.",aliasQuestIDs={},en={title="Yojamba Isle",aliases={"Yojamba Isle"},body="Yojamba Isle is a Zandalar gathering place off Stranglethorn. Its representatives collect knowledge, ritual materials and assistance against the dangers associated with Zul’Gurub.",aliasQuestIDs={}},fr={title="Yojamba Isle",body="Yojamba Isle est un lieu de rassemblement Zandalar au large de Stranglethorn. Ses représentants recueillent des connaissances, du matériel rituel et de l'aide contre les dangers associés à Zul’Gurub."},de={title="Yojamba Isle",body="Yojamba Isle ist ein Zandalar-Sammelplatz vor Stranglethorn. Ihre Vertreter sammeln Wissen, rituelles Material und Hilfestellung gegen die mit Zul’Gurub verbundenen Gefahren."},pt={title="Yojamba Isle",body="Yojamba Isle é um local de encontro Zandalar fora Stranglethorn. Seus representantes coletam conhecimento, materiais rituais e assistência contra os perigos associados ao Zul’Gurub."},pl={title="Yojamba Isle",body="Yojamba Isle to miejsce spotkań Zandalar u wybrzeży Stranglethorn. Ich przedstawiciele gromadzą wiedzę, materiały rytualne i pomoc przeciw niebezpieczeństwom związanym z Zul’Gurub."},ru={title="Yojamba Isle",body="Yojamba Isle - это место собрания Zandalar у Stranglethorn. Его представители собирают знания, ритуальные материалы и помощь против опасностей, связанных с Zul’Gurub."},references={["organization:zandalar-tribe"]=true,["place:stranglethorn-vale"]=true,["place:zulgurub"]=true}},
    ["place:zephras"] = {title="Isla Zephras",kind="Lugar",aliases={"Isla Zephras","Zephras"},body="Zephras es una isla donde comunidades de cielonatos conviven con tradiciones arcanas y espirituales distintas. La Suma Orden y los Formavientos tienen presencia en Valanaar, mientras poblados como Arboleda Thendal y Shen'dar afrontan sus propios peligros. El Culto de Al'Aketh constituye una amenaza para la seguridad de sus habitantes.",aliasQuestIDs={},en={title="Zephras Isle",aliases={"Zephras","Zephras Isle"},body="Zephras is an island whose Skyborne communities maintain distinct arcane and spiritual traditions. The High Order and the Windshapers have a presence in Valanaar, while settlements such as Thendal Grove and Shen'dar face dangers of their own. The Al'Aketh Cult threatens the safety of the island's inhabitants.",aliasQuestIDs={}},fr={title="Zephras Isle",body="Zephras est une île dont les communautés Skyborne maintiennent des arcanes et des traditions spirituelles distinctes. Le High Order et le Windshapers sont présents dans Valanaar, tandis que les règlements tels que Thendal Grove ou Shen'dar font face à leurs propres dangers. Le Al'Aketh Cult menace la sécurité des habitants de l'île."},de={title="Zephras Isle",body="Zephras ist eine Insel, deren Skyborne-Gemeinschaften unterschiedliche geheimnisvolle und spirituelle Traditionen pflegen. High Order und Windshapers sind in Valanaar präsent, während Siedlungen wie Thendal Grove und Shen'dar eigenen Gefahren ausgesetzt sind. Der Al'Aketh Cult bedroht die Sicherheit der Inselbewohner."},pt={title="Zephras Isle",body="Zephras é uma ilha cujas comunidades Skyborne mantêm distintas tradições arcanas e espirituais. O High Order e o Windshapers têm presença no Valanaar, enquanto assentamentos como Thendal Grove ou Shen'dar enfrentam perigos próprios. O Al'Aketh Cult ameaça a segurança dos habitantes da ilha."},pl={title="Zephras Isle",body="Zephras jest wyspą, której społeczności Skyborne utrzymują odrębne tradycje magii tajemnej i duchowości. The High Order i grupa znana jako the Windshapers są obecne w Valanaar, a osady takie jak Thendal Grove i Shen'dar mierzą się z własnymi zagrożeniami. The Al'Aketh Cult zagraża bezpieczeństwu mieszkańców wyspy."},ru={title="Zephras Isle",body="Zephras - это остров, чьи сообщества Skyborne поддерживают различные таинственные и духовные традиции. High Order и Windshapers присутствуют в Valanaar, в то время как такие поселения, как Thendal Grove и Shen'dar, сталкиваются со своими собственными опасностями. Al'Aketh Cult угрожает безопасности жителей острова."},references={["organization:al-aketh"]=true,["organization:high-order"]=true,["organization:windshapers"]=true,["place:shendar"]=true,["place:thendal-grove"]=true,["place:valanaar"]=true}},
    ["place:zoram-strand"] = {title="La Ensenada de Zoram",kind="Lugar",aliases={"Ensenada de Zoram","La Ensenada de Zoram"},body="La Ensenada de Zoram es una zona costera de Vallefresno. Su cercanía a las Cavernas de Brazanegra y a la Avanzada de Zoram'gar la convierte en un lugar donde la vigilancia de la costa es esencial.",aliasQuestIDs={},en={title="Zoram Strand",aliases={"The Zoram Strand","Zoram Strand"},body="The Zoram Strand is a coastal area of Ashenvale. Its proximity to Blackfathom Deeps and Zoram'gar Outpost makes watching the shore essential.",aliasQuestIDs={}},fr={title="Zoram Strand",body="The Zoram Strand est une zone côtière de Ashenvale. Sa proximité de Blackfathom Deeps et Zoram'gar Outpost rend la surveillance du rivage essentielle."},de={title="Zoram Strand",body="The Zoram Strand ist ein Küstengebiet von Ashenvale. Die Nähe zu Blackfathom Deeps und Zoram'gar Outpost macht die Beobachtung des Ufers unverzichtbar."},pt={title="Zoram Strand",body="The Zoram Strand é uma área costeira de Ashenvale. Sua proximidade com Blackfathom Deeps e Zoram'gar Outpost torna a observação da costa essencial."},pl={title="Zoram Strand",body="The Zoram Strand to nadmorski obszar Ashenvale. Bliskość Blackfathom Deeps oraz Zoram'gar Outpost czyni obserwowanie brzegu niezbędnym."},ru={title="Zoram Strand",body="The Zoram Strand - это прибрежный район Ashenvale. Его близость к Blackfathom Deeps и Zoram'gar Outpost делает наблюдение за берегом необходимым."},references={["place:ashenvale"]=true,["place:blackfathom-deeps"]=true,["place:zoramgar-outpost"]=true}},
    ["place:zoramgar-outpost"] = {title="Avanzada de Zoram'gar",kind="Lugar",aliases={"Avanzada de Zoram'gar","Avanzada de Zoram’gar","Zoram'gar","Zoram’gar"},body="La Avanzada de Zoram'gar es una posición de la Horda en la costa de Vallefresno. Sus habitantes vigilan La Ensenada de Zoram y los peligros de las cercanas Cavernas de Brazanegra.",aliasQuestIDs={},en={title="Zoram'gar Outpost",aliases={"Zoram'gar","Zoram'gar Outpost","Zoram’gar","Zoram’gar Outpost"},body="Zoram'gar Outpost is a Horde position on the coast of Ashenvale. Its inhabitants watch the Zoram Strand and the dangers of nearby Blackfathom Deeps.",aliasQuestIDs={}},fr={title="Zoram'gar Outpost",body="Zoram'gar Outpost est une position Horde sur la côte de Ashenvale. Ses habitants regardent le Zoram Strand et les dangers du Blackfathom Deeps à proximité."},de={title="Zoram'gar Outpost",body="Zoram'gar Outpost ist ein Horde Position an der Küste von Ashenvale. Seine Bewohner beobachten den Zoram Strand und die Gefahren des nahegelegenen Blackfathom Deeps."},pt={title="Zoram'gar Outpost",body="Zoram'gar Outpost é uma posição Horde na costa de Ashenvale. Seus habitantes assistem ao Zoram Strand e os perigos do Blackfathom Deeps nas proximidades."},pl={title="Zoram'gar Outpost",body="Zoram'gar Outpost to placówka frakcji Horde na wybrzeżu Ashenvale. Mieszkańcy obserwują Zoram Strand i niebezpieczeństwa pobliskiego Blackfathom Deeps."},ru={title="Zoram'gar Outpost",body="Zoram'gar Outpost - это позиция Horde на побережье Ashenvale. Ее жители наблюдают за Zoram Strand и опасностью близлежащих Blackfathom Deeps."},references={["organization:horde"]=true,["place:ashenvale"]=true,["place:blackfathom-deeps"]=true,["place:zoram-strand"]=true}},
    ["place:zulfarrak"] = {title="Zul'Farrak",kind="Lugar",aliases={"Zul'Farrak","Zul’Farrak"},body="Zul'Farrak es una ciudad trol del desierto de Tanaris. Sus recintos conservan tradiciones, figuras religiosas y tesoros de gran importancia para sus habitantes, que defienden el lugar frente a los intrusos.",aliasQuestIDs={},en={title="Zul'Farrak",aliases={"Zul'Farrak","Zul’Farrak"},body="Zul'Farrak is a troll city in the desert of Tanaris. Its chambers preserve traditions, religious figures and treasures of great importance to its inhabitants, who defend the site against intruders.",aliasQuestIDs={}},fr={title="Zul'Farrak",body="Zul'Farrak est une ville troll dans le désert de Tanaris. Ses chambres conservent des traditions, des figures religieuses et des trésors de grande importance pour ses habitants, qui défendent le site contre les intrus."},de={title="Zul'Farrak",body="Zul'Farrak ist eine Trollstadt in der Wüste von Tanaris. Seine Kammern bewahren Traditionen, religiöse Figuren und Schätze von großer Bedeutung für die Bewohner, die den Ort gegen Eindringlinge verteidigen."},pt={title="Zul'Farrak",body="Zul'Farrak é uma cidade troll no deserto de Tanaris. Suas câmaras preservam tradições, figuras religiosas e tesouros de grande importância para seus habitantes, que defendem o local contra intrusos."},pl={title="Zul'Farrak",body="Zul'Farrak to miasto trolli na pustyni Tanaris. Jego komnaty przechowują tradycje, postacie religijne i skarby o wielkim znaczeniu dla mieszkańców, którzy bronią tego miejsca przed intruzami."},ru={title="Zul'Farrak",body="Zul'Farrak - это город троллей в пустыне Tanaris. В его помещениях хранятся традиции, религиозные деятели и сокровища, имеющие большое значение для жителей, которые защищают место от злоумышленников."},references={["place:tanaris"]=true}},
    ["place:zulgurub"] = {title="Zul'Gurub",kind="Lugar",aliases={"Zul'Gurub","Zul’Gurub"},body="Zul'Gurub es una ciudad trol de Tuercespina asociada con los Gurubashi y sus tradiciones religiosas. Su importancia atrae a los Zandalar, que se preocupan por las influencias capaces de poner en peligro a su pueblo.",aliasQuestIDs={},en={title="Zul'Gurub",aliases={"Zul'Gurub","Zul’Gurub"},body="Zul’Gurub is a troll city in Stranglethorn associated with the Gurubashi and their religious traditions. Its importance draws the Zandalar, who are concerned about influences that could endanger their people.",aliasQuestIDs={}},fr={title="Zul'Gurub",body="Zul’Gurub est une ville troll dans Stranglethorn associée à la Gurubashi et leurs traditions religieuses. Son importance attire les Zandalar, qui sont préoccupés par les influences qui pourraient mettre en danger leur peuple."},de={title="Zul'Gurub",body="Zul’Gurub ist eine Trollstadt in Stranglethorn, die mit den Gurubashi und ihren religiösen Traditionen verbunden ist. Seine Bedeutung zieht die Zandalar an, die sich Sorgen über Einflüsse machen, die ihr Volk gefährden könnten."},pt={title="Zul'Gurub",body="Zul’Gurub é uma cidade troll em Stranglethorn associada ao Gurubashi e suas tradições religiosas. Sua importância atrai o Zandalar, que está preocupado com influências que poderiam pôr em perigo seu povo."},pl={title="Zul'Gurub",body="Zul’Gurub to miasto trolli w Stranglethorn związane z Gurubashi i ich tradycjami religijnymi. Jego znaczenie przyciąga Zandalar, zaniepokojonych wpływami mogącymi zagrozić ich ludowi."},ru={title="Zul'Gurub",body="Zul’Gurub - город троллей в Stranglethorn, связанный с Gurubashi и их религиозными традициями. Ее важность привлекает Zandalar, которые обеспокоены влияниями, которые могут поставить под угрозу их людей."},references={["organization:gurubashi"]=true,["organization:zandalar-tribe"]=true,["place:stranglethorn-vale"]=true}},
}
